const ALTARA_OFFLINE_NAVIGATION_STORAGE_PREFIX = "altara.offline.navigation.v1:";
const ALTARA_OFFLINE_DRAFT_STORAGE_PREFIX = "altara.offline.draft.v1:";
let altaraOfflineNavigationCacheLoaded = false;
let altaraOfflineNavigationCacheSavedAt = 0;
let altaraOfflineNavigationCacheWriteTimer = 0;
let altaraOfflineCachedActiveConversation = null;
let altaraDesktopRuntimeMeta = { appVersion: "web", packaged: false };

async function hydrateAltaraDesktopRuntimeMeta() {
  const bridge = getDesktopBridge?.();
  if (!bridge?.getMeta) return altaraDesktopRuntimeMeta;
  try {
    const meta = await bridge.getMeta();
    altaraDesktopRuntimeMeta = {
      appVersion: String(meta?.version || meta?.appVersion || "").trim() || "unknown",
      packaged: meta?.isPackaged === true,
    };
  } catch (_) {}
  return altaraDesktopRuntimeMeta;
}

function getAltaraOfflineNavigationStorageKey(userId = state.user?.id || "") {
  const uid = normId(userId || "");
  return uid ? `${ALTARA_OFFLINE_NAVIGATION_STORAGE_PREFIX}${uid}` : "";
}

function readAltaraOfflineNavigationSnapshot(userId = state.user?.id || "") {
  const uid = normId(userId || "");
  const key = getAltaraOfflineNavigationStorageKey(uid);
  if (!uid || !key) return null;
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return null;
    return sanitizeOfflineNavigationSnapshot(JSON.parse(raw), uid);
  } catch (_) {
    return null;
  }
}

function buildAltaraOfflineNavigationSnapshot() {
  const uid = normId(state.user?.id || "");
  if (!uid) return null;
  const serverChannels = [];
  try {
    for (const [serverId, channels] of serverChannelListByServerId.entries()) {
      serverChannels.push({ serverId, channels: Array.isArray(channels) ? channels : [] });
    }
  } catch (_) {}
  const conversationMeta = [];
  try {
    for (const [conversationId, meta] of dmConversationMetaById.entries()) {
      conversationMeta.push({ conversationId, meta });
    }
  } catch (_) {}
  return sanitizeOfflineNavigationSnapshot({
    schema: 1,
    userId: uid,
    savedAt: Date.now(),
    profile: state.me,
    friends: state.friends,
    dmContacts: state.dmContacts,
    groupDms: state.groupDms,
    servers: state.servers,
    activeConversation: state.activeDm,
    selectedServerId: state.selectedServerId || "",
    selectedChannelId: state.selectedChannelId || "",
    serverChannels,
    conversationMeta,
  }, uid);
}

function persistAltaraOfflineNavigationSnapshot({ immediate = false } = {}) {
  const write = () => {
    altaraOfflineNavigationCacheWriteTimer = 0;
    const snapshot = buildAltaraOfflineNavigationSnapshot();
    const key = getAltaraOfflineNavigationStorageKey(snapshot?.userId || "");
    if (!snapshot || !key) return false;
    try {
      localStorage.setItem(key, JSON.stringify(snapshot));
      altaraOfflineNavigationCacheSavedAt = snapshot.savedAt;
      exposeAltaraBootDebugHelper?.();
      return true;
    } catch (_) {
      return false;
    }
  };
  if (immediate) {
    if (altaraOfflineNavigationCacheWriteTimer) clearTimeout(altaraOfflineNavigationCacheWriteTimer);
    return write();
  }
  if (altaraOfflineNavigationCacheWriteTimer) clearTimeout(altaraOfflineNavigationCacheWriteTimer);
  altaraOfflineNavigationCacheWriteTimer = setTimeout(write, 180);
  return true;
}

function restoreAltaraOfflineNavigationSnapshot(userId = state.user?.id || "") {
  const uid = normId(userId || "");
  const snapshot = readAltaraOfflineNavigationSnapshot(uid);
  altaraOfflineNavigationCacheLoaded = !!snapshot;
  if (!snapshot) return null;
  if (snapshot.profile) {
    state.me = { ...(state.me || {}), ...snapshot.profile, id: uid };
    try { cacheProfileRow(state.me); } catch (_) {}
  }
  if (snapshot.friends.length) state.friends = snapshot.friends.slice();
  if (snapshot.dmContacts.length) state.dmContacts = snapshot.dmContacts.slice();
  if (snapshot.groupDms.length) state.groupDms = snapshot.groupDms.slice();
  if (snapshot.servers.length) state.servers = snapshot.servers.slice();
  if (snapshot.selectedServerId) state.selectedServerId = snapshot.selectedServerId;
  if (snapshot.selectedChannelId) state.selectedChannelId = snapshot.selectedChannelId;
  altaraOfflineCachedActiveConversation = snapshot.activeConversation
    ? { ...snapshot.activeConversation }
    : null;
  for (const entry of snapshot.serverChannels) {
    serverChannelListByServerId.set(entry.serverId, entry.channels.slice());
  }
  for (const entry of snapshot.conversationMeta) {
    dmConversationMetaById.set(entry.conversationId, { ...entry.meta });
  }
  try {
    populateDmConversationIdMapFromRows(state.dmContacts, "offline-navigation-cache");
    populateDmConversationIdMapFromRows(state.friends, "offline-navigation-cache");
    syncConversationMetaCaches();
  } catch (_) {}
  altaraOfflineNavigationCacheSavedAt = snapshot.savedAt;
  return snapshot;
}

function getAltaraOfflineDraftStorageKey(conversationId = activeDmId || state.activeDm?.conversationId || "") {
  const uid = normId(state.user?.id || "");
  const convId = normId(conversationId || "");
  return uid && convId ? `${ALTARA_OFFLINE_DRAFT_STORAGE_PREFIX}${uid}:${convId}` : "";
}

function readAltaraOfflineComposerDraft(conversationId = "") {
  const key = getAltaraOfflineDraftStorageKey(conversationId);
  if (!key) return "";
  try {
    return sanitizeComposerDraft(localStorage.getItem(key) || "");
  } catch (_) {
    return "";
  }
}

function persistAltaraOfflineComposerDraft(conversationId = "", value = "") {
  const key = getAltaraOfflineDraftStorageKey(conversationId);
  if (!key) return false;
  const text = sanitizeComposerDraft(value);
  try {
    if (text) localStorage.setItem(key, text);
    else localStorage.removeItem(key);
    return true;
  } catch (_) {
    return false;
  }
}

function restoreAltaraOfflineComposerDraft(
  conversationId = "",
  input = document.getElementById("dmInput"),
  { replace = false } = {}
) {
  if (!input || (!replace && String(input.value || ""))) return false;
  const draft = readAltaraOfflineComposerDraft(conversationId);
  if (replace) input.value = draft;
  else if (draft) input.value = draft;
  return !!draft;
}
