function getAltaraBootLoadingDomSnapshot() {
  if (typeof document === "undefined") {
    return { dmListText: "", userDockText: "", widgetsText: "", loadingTexts: [], homeHasWidgets: false, loadingCount: 0, loadingNodeCount: 0 };
  }
  const dmList = document.getElementById("dmList");
  const meName = document.getElementById("meName");
  const meTag = document.getElementById("meTag");
  const groupsRail = document.getElementById("leftGroupsRail") || document.getElementById("leftGroups") || document.getElementById("groupsRail") || document.getElementById("serverRail");
  const widgetRoots = Array.from(document.querySelectorAll("#widgetsGrid, .widgetsGrid, [data-widget-grid], [data-tab-panel='widgets']"));
  const activeNow = document.getElementById("activeNow");
  const loadingNodes = Array.from(document.querySelectorAll(".hint, [aria-busy='true'], .loading, .spinner"));
  const loadingTexts = loadingNodes.map((node) => String(node?.textContent || "").replace(/\s+/g, " ").trim()).filter((text) => /\bloading\b/i.test(text) || /a carregar/i.test(text)).slice(0, 24);
  const loadingCount = loadingTexts.length + loadingNodes.reduce((count, node) => count + (node?.classList?.contains?.("loading") && !loadingTexts.includes(String(node?.textContent || "").replace(/\s+/g, " ").trim()) ? 1 : 0), 0);
  const widgetsText = widgetRoots.map((el) => String(el?.textContent || "").replace(/\s+/g, " ").trim()).filter(Boolean).join(" | ").slice(0, 500);
  return {
    dmListText: String(dmList?.textContent || "").trim().slice(0, 240),
    userDockText: `${String(meName?.textContent || "").trim()} ${String(meTag?.textContent || "").trim()}`.trim().slice(0, 240),
    widgetsText,
    activeNowText: String(activeNow?.textContent || "").replace(/\s+/g, " ").trim().slice(0, 240),
    htmlRuntimeDataset: typeof document !== "undefined" ? String(document.documentElement?.dataset?.altaraRuntime || "") : "",
    shellRendered: typeof window !== "undefined" ? window.__ALTARA_SHELL_RENDERED__ === true : false,
    shellRenderReason: typeof window !== "undefined" ? String(window.__ALTARA_PREBOOT_STATE__?.shellReason || "") : "",
    homeHasWidgets: widgetRoots.some((el) => !!el && (el.children.length > 0 || String(el.textContent || "").trim().length > 0)),
    serverRailRendered: !!groupsRail && (groupsRail.children.length > 0 || String(groupsRail.textContent || "").trim().length > 0),
    loadingTexts,
    loadingCount,
    loadingNodeCount: loadingCount,
  };
}

function renderBootUserDockFallback(reason = "boot-safe-shell") {
  if (typeof document === "undefined") return false;
  const user = state?.me || state?.user || {};
  const userId = normId(user?.id || state?.user?.id || "");
  const rawEmail = String(user?.email || state?.user?.email || "").trim();
  const fallbackName = rawEmail ? rawEmail.split("@")[0] : (userId ? `User ${userId.slice(0, 8)}` : "ALTARA");
  const displayName = String(user?.display_name || user?.displayName || user?.username || user?.user_metadata?.display_name || user?.user_metadata?.username || fallbackName || "ALTARA").trim();
  const username = String(user?.username || user?.user_metadata?.username || rawEmail.split("@")[0] || (userId ? userId.slice(0, 8) : "user")).trim();
  const cachedAvatarUrl = String(state?.me?.avatar_url || state?.me?.avatarUrl || "").trim();
  const hasCachedIdentity = !!String(
    state?.me?.display_name
    || state?.me?.displayName
    || state?.me?.username
    || state?.user?.user_metadata?.display_name
    || state?.user?.user_metadata?.username
    || ""
  ).trim();
  try {
    const meName = document.getElementById("meName");
    const meTag = document.getElementById("meTag");
    const meAvatar = document.getElementById("meAvatar");
    const currentName = String(meName?.textContent || "").trim();
    const currentTag = String(meTag?.textContent || "").trim();
    const replaceStaticName = hasCachedIdentity && (
      currentName === "You"
      || meName?.getAttribute("data-static-fallback-shell") === "1"
      || meName?.getAttribute("data-immediate-shell") === "1"
    );
    const replaceStaticTag = hasCachedIdentity && (
      currentTag === "@you"
      || meTag?.getAttribute("data-static-fallback-shell") === "1"
      || meTag?.getAttribute("data-immediate-shell") === "1"
    );
    if (meName && (!currentName || currentName === "..." || /loading/i.test(currentName) || replaceStaticName)) {
      meName.textContent = displayName || "ALTARA";
      meName.removeAttribute("data-static-fallback-shell");
      meName.removeAttribute("data-immediate-shell");
    }
    if (meTag && (!currentTag || currentTag === "..." || replaceStaticTag)) {
      meTag.textContent = username ? `@${username}` : (userId ? userId.slice(0, 8) : "@user");
      meTag.removeAttribute("data-static-fallback-shell");
      meTag.removeAttribute("data-immediate-shell");
    }
    if (meAvatar && cachedAvatarUrl) {
      setAvatar(meAvatar, cachedAvatarUrl, userId);
      meAvatar.removeAttribute("data-static-fallback-shell");
      meAvatar.removeAttribute("data-immediate-shell");
    }
    applyMeHeaderNameStyle?.();
    applyMeHeaderBannerStyle?.();
    applyMeStatusDot?.(resolveMyPresenceStatus?.(state.me) || "offline");
    recordAltaraBootEvent("required_task_done", { task: "user_dock_fallback", reason });
    return true;
  } catch (error) {
    recordAltaraBootEvent("required_task_error", { task: "user_dock_fallback", reason, message: error?.message || error || "unknown" });
    return false;
  }
}

function renderBootSafeDmSidebarFallback(reason = "boot-safe-shell") {
  if (typeof document === "undefined") return false;
  let rendered = false;
  try {
    renderFriends?.({ skipPresenceRefresh: true, skipGroupsRail: true });
  } catch (_) {}
  try {
    renderGroupsRail?.();
  } catch (_) {}
  try {
    const dmList = document.getElementById("dmList");
    if (dmList) {
      const text = String(dmList.textContent || "").trim();
      const isLoading = !text || /\bloading\b/i.test(text) || /a carregar/i.test(text);
      if (isLoading) {
        const hasAnyRows = (Array.isArray(state?.friends) && state.friends.length)
          || (Array.isArray(state?.dmContacts) && state.dmContacts.length)
          || (Array.isArray(state?.groupDms) && state.groupDms.length)
          || (Array.isArray(state?.servers) && state.servers.length);
        dmList.innerHTML = hasAnyRows
          ? '<div class="hint">Messages will appear when sync finishes.</div>'
          : '<div class="hint">Waiting for connection\u2026</div>';
      }
      rendered = true;
    }
  } catch (error) {
    recordAltaraBootEvent("required_task_error", { task: "dm_sidebar_fallback", reason, message: error?.message || error || "unknown" });
  }
  try { renderWidgets?.(); } catch (_) {}
  try { renderPartyPicker?.(); } catch (_) {}
  if (rendered) recordAltaraBootEvent("safe_shell_rendered", { reason });
  return rendered;
}

function clearAltaraBootLoadingPlaceholders(reason = "boot-safe-shell") {
  if (typeof document === "undefined") return false;
  let cleared = false;
  try {
    const dmList = document.getElementById("dmList");
    if (dmList) {
      const text = String(dmList.textContent || "").trim();
      if (!text || /\bloading\b/i.test(text) || /a carregar/i.test(text)) {
        dmList.innerHTML = '<div class="hint">Waiting for connection\u2026</div>';
        cleared = true;
      }
    }
    const friendsList = document.getElementById("friendsList");
    if (friendsList) {
      const text = String(friendsList.textContent || "").trim();
      if (/\bloading\b/i.test(text) || /a carregar/i.test(text)) {
        friendsList.innerHTML = '<div class="hint">Waiting for connection\u2026</div>';
        cleared = true;
      }
    }
  } catch (_) {}
  if (cleared) recordAltaraBootEvent("loading_placeholders_cleared", { reason });
  return cleared;
}

function forceRenderBootSafeShell(reason = "boot-safe-shell") {
  if (typeof document === "undefined") return false;
  try { setDesktopBootOverlayVisible?.(false); } catch (_) {}
  const userRendered = renderBootUserDockFallback(reason);
  const sidebarRendered = renderBootSafeDmSidebarFallback(reason);
  clearAltaraBootLoadingPlaceholders(reason);
  exposeAltaraBootDebugHelper?.();
  return !!(userRendered || sidebarRendered);
}

let altaraHardBootDeadlineScheduled = false;
function scheduleAltaraHardBootDeadlines(reason = "boot") {
  if (altaraHardBootDeadlineScheduled || typeof window === "undefined") return;
  altaraHardBootDeadlineScheduled = true;
  recordAltaraBootEvent("required_task_start", { task: "hard_boot_deadline", reason });
  window.setTimeout(() => {
    if (!altaraBootDebugState.bootCompleted) forceRenderBootSafeShell(`${reason}:1500ms`);
  }, 1500);
  window.setTimeout(() => {
    if (!altaraBootDebugState.bootCompleted) clearAltaraBootLoadingPlaceholders(`${reason}:2500ms`);
  }, 2500);
  window.setTimeout(() => {
    if (!altaraBootDebugState.bootCompleted) {
      recordAltaraBootEvent("shell_ready_forced", { reason, non_blocking: true });
      forceRenderBootSafeShell(`${reason}:3000ms`);
      if (typeof window !== "undefined" && window.__ALTARA_SAFE_BOOT_ENABLED__ !== true) {
        window.setTimeout(() => {
          try {
            if (window.__ALTARA_IS_REAL_HYDRATED_CONTENT_PRESENT__?.("any") === true) return;
            void startNormalBootHydration({ reason: `${reason}:hard_deadline_retry`, lightweight: true });
          } catch (_) {}
        }, 0);
      }
    }
  }, 3000);
}
