function scheduleUiRender(key, fn) {
  const safeKey = String(key || "ui").trim() || "ui";
  if (altaraScheduledUiRenders.has(safeKey)) return altaraScheduledUiRenders.get(safeKey);
  const scheduleFrame = (typeof requestAnimationFrame === "function")
    ? requestAnimationFrame
    : ((cb) => setTimeout(cb, 16));
  const handle = scheduleFrame(() => {
    altaraScheduledUiRenders.delete(safeKey);
    markPerfStart(`ui_render_${safeKey}`);
    try { if (typeof fn === "function") fn(); }
    catch (error) { console.warn(`scheduled UI render failed (${safeKey})`, error?.message || error); }
    finally { markPerfEnd(`ui_render_${safeKey}`); }
  });
  altaraScheduledUiRenders.set(safeKey, handle);
  return handle;
}

