function getAltaraPlusTierKey(statusOrPlan = null) {
  if (typeof statusOrPlan === "string") {
    const raw = statusOrPlan.trim().toLowerCase();
    if (raw === "nova" || raw === ALTARA_PLUS_PLAN_NOVA) return "nova";
    if (raw === "core" || raw === ALTARA_PLUS_PLAN_CORE) return "core";
    return "free";
  }
  const status = statusOrPlan && typeof statusOrPlan === "object"
    ? statusOrPlan
    : (typeof getCurrentUserAltaraPlusStatus === "function" ? getCurrentUserAltaraPlusStatus() : null);
  const planKey = String(status?.planKey || status?.plan_key || "").trim().toLowerCase();
  if (planKey === ALTARA_PLUS_PLAN_NOVA || status?.tier === "nova") return "nova";
  if (planKey === ALTARA_PLUS_PLAN_CORE || status?.tier === "core") return "core";
  try {
    if (typeof hasAltaraPlusNovaAccess === "function" && hasAltaraPlusNovaAccess(status)) return "nova";
    if (typeof hasAltaraPlusCoreAccess === "function" && hasAltaraPlusCoreAccess(status)) return "core";
  } catch (_) {}
  return "free";
}

function getAltaraPlusUploadHardCapBytes() {
  try {
    if (typeof CHAT_UPLOAD_MAX_BYTES === "number" && Number.isFinite(CHAT_UPLOAD_MAX_BYTES) && CHAT_UPLOAD_MAX_BYTES > 0) {
      return CHAT_UPLOAD_MAX_BYTES;
    }
  } catch (_) {}
  return ALTARA_PLUS_UPLOAD_NOVA_BYTES;
}

function getAltaraPlusUploadLimitBytes(statusOrPlan = null) {
  const tier = getAltaraPlusTierKey(statusOrPlan);
  const base = ALTARA_PLUS_LIMITS_BY_TIER[tier] || ALTARA_PLUS_LIMITS_BY_TIER.free;
  const requested = Number(base.upload_file_size_bytes || ALTARA_PLUS_UPLOAD_FREE_BYTES) || ALTARA_PLUS_UPLOAD_FREE_BYTES;
  return Math.max(1, Math.min(requested, getAltaraPlusUploadHardCapBytes()));
}

function getAltaraPlusRawLimits(statusOrPlan = null) {
  const tier = getAltaraPlusTierKey(statusOrPlan);
  const base = ALTARA_PLUS_LIMITS_BY_TIER[tier] || ALTARA_PLUS_LIMITS_BY_TIER.free;
  const uploadBytes = getAltaraPlusUploadLimitBytes(statusOrPlan);
  return {
    servers_joined: base.servers_joined,
    best_friends: base.best_friends,
    saved_focus_profiles: base.saved_focus_profiles,
    saved_spatial_layouts: base.saved_spatial_layouts,
    upload_file_size_mb: Math.max(1, Math.round(uploadBytes / ALTARA_PLUS_LIMIT_UPLOAD_MB)),
    upload_file_size_bytes: uploadBytes,
  };
}

function readAltaraPlusLimitsDebugOverrides() {
  const result = {
    enabled: false,
    overrides: {},
  };
  try {
    if (typeof localStorage === "undefined") return result;
    result.enabled = localStorage.getItem("altara.debug.limits") === "1";
    if (!result.enabled) return result;
    const rawServersJoined = String(localStorage.getItem("altara.debug.limit.servers_joined") || "").trim();
    if (rawServersJoined) {
      const parsed = Number(rawServersJoined);
      if (Number.isFinite(parsed) && parsed > 0) {
        result.overrides.servers_joined = Math.floor(parsed);
      }
    }
    const rawBestFriends = String(localStorage.getItem("altara.debug.limit.best_friends") || "").trim();
    if (rawBestFriends) {
      const parsed = Number(rawBestFriends);
      if (Number.isFinite(parsed) && parsed > 0) {
        result.overrides.best_friends = Math.floor(parsed);
      }
    }
    const rawSavedFocusProfiles = String(localStorage.getItem("altara.debug.limit.saved_focus_profiles") || "").trim();
    if (rawSavedFocusProfiles) {
      const parsed = Number(rawSavedFocusProfiles);
      if (Number.isFinite(parsed) && parsed > 0) {
        result.overrides.saved_focus_profiles = Math.floor(parsed);
      }
    }
    const rawSavedSpatialLayouts = String(localStorage.getItem("altara.debug.limit.saved_spatial_layouts") || "").trim();
    if (rawSavedSpatialLayouts) {
      const parsed = Number(rawSavedSpatialLayouts);
      if (Number.isFinite(parsed) && parsed >= 0) {
        result.overrides.saved_spatial_layouts = Math.floor(parsed);
      }
    }
    const rawUploadFileSizeMb = String(localStorage.getItem("altara.debug.limit.upload_file_size_mb") || "").trim();
    if (rawUploadFileSizeMb) {
      const parsed = Number(rawUploadFileSizeMb);
      if (Number.isFinite(parsed) && parsed > 0) {
        const overrideMb = Math.max(0.01, parsed);
        result.overrides.upload_file_size_mb = Math.round(overrideMb * 100) / 100;
        result.overrides.upload_file_size_bytes = Math.max(1, Math.floor(overrideMb * ALTARA_PLUS_LIMIT_UPLOAD_MB));
      }
    }
  } catch (_) {}
  return result;
}

function getAltaraPlusLimits(statusOrPlan = null) {
  const rawLimits = getAltaraPlusRawLimits(statusOrPlan);
  const debug = readAltaraPlusLimitsDebugOverrides();
  const limits = { ...rawLimits };
  if (debug.enabled && Number.isFinite(Number(debug.overrides.servers_joined)) && Number(debug.overrides.servers_joined) > 0) {
    limits.servers_joined = Math.min(rawLimits.servers_joined, Math.floor(Number(debug.overrides.servers_joined)));
  }
  if (debug.enabled && Number.isFinite(Number(debug.overrides.best_friends)) && Number(debug.overrides.best_friends) > 0) {
    limits.best_friends = Math.min(rawLimits.best_friends, Math.floor(Number(debug.overrides.best_friends)));
  }
  if (debug.enabled && Number.isFinite(Number(debug.overrides.saved_focus_profiles)) && Number(debug.overrides.saved_focus_profiles) > 0) {
    limits.saved_focus_profiles = Math.min(rawLimits.saved_focus_profiles, Math.floor(Number(debug.overrides.saved_focus_profiles)));
  }
  if (debug.enabled && Number.isFinite(Number(debug.overrides.saved_spatial_layouts)) && Number(debug.overrides.saved_spatial_layouts) >= 0) {
    limits.saved_spatial_layouts = Math.min(rawLimits.saved_spatial_layouts, Math.floor(Number(debug.overrides.saved_spatial_layouts)));
  }
  if (debug.enabled && Number.isFinite(Number(debug.overrides.upload_file_size_bytes)) && Number(debug.overrides.upload_file_size_bytes) > 0) {
    const uploadBytes = Math.max(1, Math.min(
      Math.floor(Number(debug.overrides.upload_file_size_bytes)),
      Number(rawLimits.upload_file_size_bytes || 0) || getAltaraPlusUploadLimitBytes(statusOrPlan),
      getAltaraPlusUploadHardCapBytes()
    ));
    limits.upload_file_size_bytes = uploadBytes;
    limits.upload_file_size_mb = Math.max(0.01, Math.round((uploadBytes / ALTARA_PLUS_LIMIT_UPLOAD_MB) * 100) / 100);
  }
  return limits;
}
function getCurrentAltaraPlusUploadLimitBytes() {
  const limits = getAltaraPlusLimits(getCurrentUserAltaraPlusStatus());
  const bytes = Number(limits?.upload_file_size_bytes || 0);
  return Number.isFinite(bytes) && bytes > 0
    ? Math.floor(bytes)
    : getAltaraPlusUploadLimitBytes(getCurrentUserAltaraPlusStatus());
}

function formatAltaraPlusUploadLimit(bytes) {
  const size = Number(bytes || 0) || getCurrentAltaraPlusUploadLimitBytes();
  try {
    if (typeof formatBytesLabel === "function") return formatBytesLabel(size);
  } catch (_) {}
  return Math.max(1, Math.round(size / ALTARA_PLUS_LIMIT_UPLOAD_MB)) + " MB";
}

function getAltaraPlusLimitCounts() {
  const counts = {
    servers_joined: 0,
    best_friends: 0,
    saved_focus_profiles: 0,
    saved_spatial_layouts: 0,
  };
  try {
    const servers = Array.isArray(state.servers) ? state.servers : [];
    const seenServers = new Set();
    servers.forEach((row) => {
      const sid = normId(row?.serverId || row?.server_id || row?.id || "");
      if (!sid) return;

      try { if (typeof isServerDeletedLocally === "function" && isServerDeletedLocally(sid)) return; } catch (_) {}
      seenServers.add(sid);
    });
    counts.servers_joined = seenServers.size;
  } catch (_) {}
  try {
    if (typeof ensureDmClientStateLoaded === "function") ensureDmClientStateLoaded();
    if (typeof dmBestFriendUserIds !== "undefined" && dmBestFriendUserIds instanceof Set) {
      counts.best_friends = dmBestFriendUserIds.size;
    } else {
      counts.best_friends = (Array.isArray(state.friends) ? state.friends : []).filter((row) => !!(row?.is_best_friend || row?.best_friend || row?.isBestFriend || row?.bestFriend)).length;
    }
  } catch (_) {}
  try {
    const focus = typeof getFocusNotificationSettings === "function" ? getFocusNotificationSettings() : null;
    counts.saved_focus_profiles = Array.isArray(focus?.profiles) ? focus.profiles.length : 0;
  } catch (_) {}
  try {
    const cloudCount = typeof getSpatialAudioSavedLayoutsCloudCount === "function" ? getSpatialAudioSavedLayoutsCloudCount() : null;
    counts.saved_spatial_layouts = Number.isFinite(Number(cloudCount)) && Number(cloudCount) >= 0
      ? Math.floor(Number(cloudCount))
      : 0;
  } catch (_) {}
  return counts;
}

function getAltaraPlusCurrentTierForCopy() {
  try {
    return getAltaraPlusTierKey(getCurrentUserAltaraPlusStatus());
  } catch (_) {
    return "free";
  }
}

function getAltaraPlusLimitNoticeCta(tier = getAltaraPlusCurrentTierForCopy()) {
  const normalized = getAltaraPlusTierKey(tier);
  if (normalized === "nova") return "OK";
  if (normalized === "core") return "Upgrade to Nova";
  return "Upgrade to ALTARA+";
}

function getAltaraPlusLimitNoticeCopy(limitKey = "", tierInput = getAltaraPlusCurrentTierForCopy(), options = {}) {
  const tier = getAltaraPlusTierKey(tierInput);
  const key = String(limitKey || "").trim().toLowerCase();
  const uploadFreeLabel = formatAltaraPlusUploadLimit(getAltaraPlusUploadLimitBytes("free"));
  const uploadCoreLabel = formatAltaraPlusUploadLimit(getAltaraPlusUploadLimitBytes("core"));
  const uploadNovaLabel = formatAltaraPlusUploadLimit(getAltaraPlusUploadLimitBytes("nova"));

  const copy = {
    servers_joined: {
      free: "Free users can join up to 100 servers. ALTARA+ Core raises this to 150, and Nova raises it to 200.",
      core: "ALTARA+ Core lets you join up to 150 servers. Nova raises this to 200.",
      nova: "You've reached the highest server limit available on ALTARA+ Nova.",
    },
    best_friends: {
      free: "Free users can keep up to 10 Best Friends. ALTARA+ Core unlocks 15, and Nova unlocks 25.",
      core: "ALTARA+ Core lets you keep up to 15 Best Friends. Nova unlocks 25.",
      nova: "You've reached the highest Best Friends limit available on ALTARA+ Nova.",
    },
    saved_focus_profiles: {
      free: "Free users can save up to 3 Focus Profiles. ALTARA+ Core unlocks 10, and Nova unlocks 25.",
      core: "ALTARA+ Core lets you save up to 10 Focus Profiles. Nova unlocks 25.",
      nova: "You've reached the highest Focus Profile limit available on ALTARA+ Nova.",
    },
    saved_spatial_layouts_required: {
      free: "Saving Spatial Audio layouts is available with ALTARA+ Core and Nova.",
      core: "ALTARA+ Core lets you save personal Spatial Audio layouts.",
      nova: "ALTARA+ Nova already includes saved personal Spatial Audio layouts.",
    },
    saved_spatial_layouts: {
      free: "Saving Spatial Audio layouts is available with ALTARA+ Core and Nova.",
      core: "ALTARA+ Core lets you save up to 5 Spatial layouts. Nova unlocks up to 15.",
      nova: "You've reached the highest Spatial layout limit available on ALTARA+ Nova.",
    },
    upload_file_size_mb: {
      free: "Free users can upload files up to " + uploadFreeLabel + ". ALTARA+ Core unlocks " + uploadCoreLabel + ", and Nova unlocks " + uploadNovaLabel + ".",
      core: "ALTARA+ Core supports files up to " + uploadCoreLabel + ". Nova unlocks " + uploadNovaLabel + ".",
      nova: "You've reached the highest upload size available on ALTARA+ Nova.",
    },
  };

  return copy[key]?.[tier]
    || copy[key]?.free
    || "You've reached your current ALTARA+ limit.";
}

function openAltaraPlusSettingsFromLimitNotice() {
  try {
    if (typeof openProfileOverlay !== "function" || typeof setSettingsTab !== "function") return false;
    try { settingsActiveTab = "altara-plus"; } catch (_) {}
    openProfileOverlay();
    setSettingsTab("altara-plus");
    const refocus = () => {
      try { setSettingsTab("altara-plus"); } catch (_) {}
    };
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(refocus);
    else if (typeof setTimeout === "function") setTimeout(refocus, 0);
    return true;
  } catch (_) {
    return false;
  }
}

function showAltaraPlusLimitNotice(title = "ALTARA+ limit reached", body = "You've reached your current ALTARA+ limit.", options = {}) {
  const tier = getAltaraPlusCurrentTierForCopy();
  const okText = String(options?.okText || "").trim() || getAltaraPlusLimitNoticeCta(tier);
  const shouldOpenUpgrade = tier !== "nova" && okText !== "OK";
  try {
    if (typeof requestAppAlert === "function") {
      void requestAppAlert(body, { title, okText }).then((confirmed) => {
        if (confirmed && shouldOpenUpgrade) openAltaraPlusSettingsFromLimitNotice();
      }).catch(() => {});
      return;
    }
  } catch (_) {}
  try { alert(title + "\n\n" + body); } catch (_) {}
  if (shouldOpenUpgrade) openAltaraPlusSettingsFromLimitNotice();
}

