function getAltaraPlusFileTooLargeMessage(limitBytes = getCurrentAltaraPlusUploadLimitBytes()) {
  return getAltaraPlusLimitNoticeCopy("upload_file_size_mb", getAltaraPlusCurrentTierForCopy(), { limitBytes });
}

function showAltaraPlusFileTooLargeNotice(limitBytes = getCurrentAltaraPlusUploadLimitBytes()) {
  showAltaraPlusLimitNotice("File too large", getAltaraPlusFileTooLargeMessage(limitBytes));
}

function isAltaraPlusLimitError(errorInput = null, limitKey = "") {
  const msg = String(errorInput?.message || errorInput?.details || errorInput?.hint || errorInput || "").toLowerCase();
  const key = String(limitKey || "").trim().toLowerCase();
  if (!msg) return false;
  if (key === "servers_joined") return msg.includes("server_limit_reached") || msg.includes("server limit reached");
  if (key === "best_friends") return msg.includes("best_friends_limit_reached") || msg.includes("best friends limit reached");
  if (key === "saved_focus_profiles") return msg.includes("focus_profile_limit_reached") || msg.includes("focus profile limit reached");
  if (key === "saved_spatial_layouts") return msg.includes("spatial_layout_limit_reached") || msg.includes("spatial layout limit reached");
  if (key === "upload_file_size_mb") return msg.includes("upload_file_size_limit_reached") || msg.includes("upload_file_size_missing") || msg.includes("invalid_upload_path") || msg.includes("file too large");
  return /(?:server|best_friends|focus_profile|spatial_layout|upload_file_size)_limit_reached/.test(msg);
}

function getAltaraPlusUploadValidation(fileOrBlob, { technicalHardCapBytes = null } = {}) {
  const size = Number(fileOrBlob?.size || 0) || 0;
  const planLimitBytes = getCurrentAltaraPlusUploadLimitBytes();
  const technicalInput = Number(technicalHardCapBytes);
  const technicalLimitBytes = Number.isFinite(technicalInput) && technicalInput > 0
    ? Math.floor(technicalInput)
    : getAltaraPlusUploadHardCapBytes();
  const effectiveLimitBytes = Math.max(1, Math.min(planLimitBytes, technicalLimitBytes));
  const allowed = size <= effectiveLimitBytes;
  return {
    allowed,
    size,
    planLimitBytes,
    technicalLimitBytes,
    effectiveLimitBytes,
    blockedBy: allowed ? "" : (planLimitBytes <= technicalLimitBytes ? "plan" : "technical"),
  };
}

function getAltaraPlusUploadLimitFailureMessage(validation, technicalMessage = "") {
  if (!validation || validation.allowed) return "";
  if (validation.blockedBy === "plan") {
    return getAltaraPlusFileTooLargeMessage(validation.effectiveLimitBytes);
  }
  return technicalMessage || ("File too large. Max " + formatAltaraPlusUploadLimit(validation.technicalLimitBytes) + ".");
}

function throwIfAltaraUploadLimitExceeded(fileOrBlob, options = {}) {
  const validation = getAltaraPlusUploadValidation(fileOrBlob, options);
  if (!validation.allowed) {
    try { showAltaraUploadLimitFailure(validation, { technicalMessage: options?.technicalMessage || "" }); } catch (_) {}
    const error = new Error(getAltaraPlusUploadLimitFailureMessage(validation, options?.technicalMessage || ""));
    error.code = validation.blockedBy === "plan" ? "ALTARA_UPLOAD_FILE_TOO_LARGE" : "ALTARA_UPLOAD_TECHNICAL_LIMIT";
    error.validation = validation;
    throw error;
  }
  return validation;
}

function showAltaraUploadLimitFailure(validation, { technicalMessage = "" } = {}) {
  if (!validation || validation.allowed) return false;
  if (validation.blockedBy === "plan") {
    showAltaraPlusFileTooLargeNotice(validation.effectiveLimitBytes);
  } else {
    try { alert(getAltaraPlusUploadLimitFailureMessage(validation, technicalMessage)); } catch (_) {}
  }
  return true;
}


function readAltaraUploadDebugEnabled() {
  try { return typeof localStorage !== "undefined" && localStorage.getItem("altara.debug.uploads") === "1"; } catch (_) { return false; }
}

function logAltaraUploadDebug(event = "", details = null) {
  if (!readAltaraUploadDebugEnabled()) return;
  try { console.info("[upload-auth] " + String(event || "event"), details || {}); } catch (_) {}
}

function normalizeAltaraUploadContext(value = "") {
  const context = String(value || "").trim().toLowerCase();
  return ALTARA_UPLOAD_CONTEXTS.includes(context) ? context : "";
}

function getAltaraStorageUploadErrorText(error = null) {
  const parts = [];
  try {
    [error?.message, error?.details, error?.hint, error?.code, error?.name, error?.error, error?.statusText].forEach((part) => {
      const text = String(part || "").trim();
      if (text) parts.push(text);
    });
    if (error && typeof error === "object") {
      const serialized = JSON.stringify(error);
      if (serialized && serialized !== "{}") parts.push(serialized);
    }
  } catch (_) {}
  if (!parts.length) parts.push(String(error || ""));
  return parts.join(" ").toLowerCase();
}

function isAltaraStorageUploadLimitError(error = null) {
  const msg = getAltaraStorageUploadErrorText(error);
  return msg.includes("upload_file_size_limit_reached")
    || msg.includes("upload_file_size_missing")
    || msg.includes("invalid_upload_path")
    || msg.includes("file too large")
    || msg.includes("payload too large");
}

function isSupabaseStorageMissingBucketError(error = null) {
  const msg = getAltaraStorageUploadErrorText(error);
  return msg.includes("bucket") && (msg.includes("not found") || msg.includes("does not exist"));
}

function handleAltaraStorageUploadError(error = null, { uploadContext = "", bucket = "", path = "" } = {}) {
  const context = normalizeAltaraUploadContext(uploadContext);
  if (isAltaraStorageUploadLimitError(error)) {
    logAltaraUploadDebug("storage rejected upload", { uploadContext: context, bucket, path, reason: getAltaraStorageUploadErrorText(error).slice(0, 220) });
    showAltaraPlusFileTooLargeNotice(getCurrentAltaraPlusUploadLimitBytes());
    return true;
  }
  logAltaraUploadDebug("upload failed", { uploadContext: context, bucket, path, reason: getAltaraStorageUploadErrorText(error).slice(0, 220) });
  return false;
}

async function uploadFileViaAltaraStorage(fileOrBlob, {
  bucket = ALTARA_UPLOAD_STORAGE_BUCKET_DEFAULT,
  fileName = "",
  path = "",
  contentType = "",
  cacheControl = "31536000",
  uploadContext = "",
  upsert = false,
} = {}) {
  if (!fileOrBlob || !state.user?.id) throw new Error("upload_invalid");
  const bucketName = String(bucket || ALTARA_UPLOAD_STORAGE_BUCKET_DEFAULT).trim() || ALTARA_UPLOAD_STORAGE_BUCKET_DEFAULT;
  const targetPath = String(path || "").trim().replace(/^\/+/, "");
  if (!targetPath) throw new Error("upload_path_invalid");
  const name = String(fileName || fileOrBlob.name || "file.bin").trim() || "file.bin";
  const mimeType = String(contentType || fileOrBlob.type || "application/octet-stream").trim() || "application/octet-stream";
  throwIfAltaraUploadLimitExceeded(fileOrBlob);
  const context = normalizeAltaraUploadContext(uploadContext);
  logAltaraUploadDebug("direct upload starting", { uploadContext: context, bucket: bucketName, path: targetPath, fileName: name, fileSize: Number(fileOrBlob.size || 0) || 0, contentType: mimeType });
  const upload = await supabase.storage.from(bucketName).upload(targetPath, fileOrBlob, {
    upsert: !!upsert,
    contentType: mimeType,
    cacheControl,
  });
  if (upload.error) {
    handleAltaraStorageUploadError(upload.error, { uploadContext: context, bucket: bucketName, path: targetPath });
    throw upload.error;
  }
  const publicUrl = String(supabase.storage.from(bucketName).getPublicUrl(targetPath)?.data?.publicUrl || "").trim();
  logAltaraUploadDebug("direct upload completed", { uploadContext: context, bucket: bucketName, path: targetPath });
  return { bucket: bucketName, path: targetPath, publicUrl, upload };
}

