function createFreeAltaraPlusStatus() {
  return {
    hasAltaraPlus: false,
    planKey: null,
    intervalKey: null,
    tierLabel: null,
    environment: null,
    expiresAt: null,
    subscriptionStatus: null,
    cancelAtPeriodEnd: null,
  };
}

function normalizeAltaraPlusPlanKey(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === ALTARA_PLUS_PLAN_CORE) return ALTARA_PLUS_PLAN_CORE;
  if (normalized === ALTARA_PLUS_PLAN_NOVA) return ALTARA_PLUS_PLAN_NOVA;
  return null;
}

function normalizeAltaraPlusEnvironment(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "test") return "test";
  if (normalized === "live") return "live";
  return null;
}

function normalizeAltaraPlusIntervalKey(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "monthly") return "monthly";
  if (normalized === "yearly") return "yearly";
  return null;
}

function normalizeAltaraPlusSubscriptionStatus(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (!normalized) return null;
  return normalized;
}

function normalizeAltaraPlusCancelAtPeriodEnd(value) {
  if (value === true) return true;
  if (value === false) return false;
  const normalized = String(value || "").trim().toLowerCase();
  if (!normalized) return null;
  if (normalized === "true") return true;
  if (normalized === "false") return false;
  return null;
}

function normalizeAltaraPlusExpiresAt(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  const dt = new Date(raw);
  if (!Number.isFinite(dt.getTime())) return null;
  return dt.toISOString();
}

function pickAltaraPlusRawValue(source = {}, keys = []) {
  if (!source || typeof source !== "object") return undefined;
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(source, key)) return source[key];
  }
  return undefined;
}

function normalizeAltaraPlusClientState(rawStatus = null) {
  const free = createFreeAltaraPlusStatus();
  const status = rawStatus && typeof rawStatus === "object" ? rawStatus : {};
  const planKey = normalizeAltaraPlusPlanKey(pickAltaraPlusRawValue(status, [
    "planKey",
    "plan_key",
    "altaraPlusPlanKey",
    "altara_plus_plan_key",
    "altaraPlusPlan",
    "altara_plus_plan",
  ]));
  const rawHasAltaraPlus = pickAltaraPlusRawValue(status, [
    "hasAltaraPlus",
    "has_altara_plus",
    "altaraPlus",
    "altara_plus",
    "altaraPlusActive",
    "altara_plus_active",
    "isActive",
    "is_active",
    "active",
  ]);
  const rawNovaFlag = pickAltaraPlusRawValue(status, ["altaraPlusNova", "altara_plus_nova"]);
  const rawCoreFlag = pickAltaraPlusRawValue(status, ["altaraPlusCore", "altara_plus_core"]);
  const hasExplicitAccessValue = typeof rawHasAltaraPlus !== "undefined"
    || typeof rawNovaFlag !== "undefined"
    || typeof rawCoreFlag !== "undefined";
  const hasAltaraPlus = hasExplicitAccessValue
    ? (isTruthyAltaraPlusFlag(rawHasAltaraPlus) || isTruthyAltaraPlusFlag(rawNovaFlag) || isTruthyAltaraPlusFlag(rawCoreFlag))
    : !!planKey;
  if (!hasAltaraPlus) return free;

  const tierLabel = planKey === ALTARA_PLUS_PLAN_NOVA
    ? "Nova"
    : planKey === ALTARA_PLUS_PLAN_CORE
      ? "Core"
      : null;

  return {
    hasAltaraPlus: true,
    planKey,
    intervalKey: normalizeAltaraPlusIntervalKey(pickAltaraPlusRawValue(status, ["intervalKey", "interval_key"])),
    tierLabel,
    environment: normalizeAltaraPlusEnvironment(pickAltaraPlusRawValue(status, ["environment", "stripe_environment", "stripeEnvironment"])),
    expiresAt: normalizeAltaraPlusExpiresAt(pickAltaraPlusRawValue(status, ["expiresAt", "expires_at"])),
    subscriptionStatus: normalizeAltaraPlusSubscriptionStatus(pickAltaraPlusRawValue(status, ["subscriptionStatus", "subscription_status"])),
    cancelAtPeriodEnd: normalizeAltaraPlusCancelAtPeriodEnd(pickAltaraPlusRawValue(status, ["cancelAtPeriodEnd", "cancel_at_period_end"])),
  };
}

function getCurrentUserAltaraPlusStatus() {
  state.altaraPlus = normalizeAltaraPlusClientState(state.altaraPlus);
  return state.altaraPlus;
}

function currentUserHasAltaraPlus() {
  return getCurrentUserAltaraPlusStatus().hasAltaraPlus === true;
}

function isTruthyAltaraPlusFlag(value) {
  if (value === true) return true;
  const normalized = String(value || "").trim().toLowerCase();
  return normalized === "true" || normalized === "1" || normalized === "yes";
}

function hasAltaraPlusCoreAccess(statusInput = null) {
  const status = statusInput && typeof statusInput === "object" ? statusInput : {};
  const planKey = normalizeAltaraPlusPlanKey(
    status.planKey
    ?? status.plan_key
    ?? status.altara_plus_plan_key
    ?? status.altaraPlusPlanKey
    ?? status.altara_plus_plan
    ?? status.altaraPlusPlan
    ?? ""
  );
  return Boolean(
    isTruthyAltaraPlusFlag(status.hasAltaraPlus)
    || isTruthyAltaraPlusFlag(status.has_altara_plus)
    || isTruthyAltaraPlusFlag(status.altara_plus)
    || isTruthyAltaraPlusFlag(status.altaraPlus)
    || isTruthyAltaraPlusFlag(status.altara_plus_core)
    || isTruthyAltaraPlusFlag(status.altaraPlusCore)
    || isTruthyAltaraPlusFlag(status.altara_plus_nova)
    || isTruthyAltaraPlusFlag(status.altaraPlusNova)
    || planKey === ALTARA_PLUS_PLAN_CORE
    || planKey === ALTARA_PLUS_PLAN_NOVA
  );
}

function hasAltaraPlusNovaAccess(statusInput = null) {
  const status = statusInput && typeof statusInput === "object" ? statusInput : {};
  const planKey = normalizeAltaraPlusPlanKey(
    status.planKey
    ?? status.plan_key
    ?? status.altara_plus_plan_key
    ?? status.altaraPlusPlanKey
    ?? status.altara_plus_plan
    ?? status.altaraPlusPlan
    ?? ""
  );
  return Boolean(
    isTruthyAltaraPlusFlag(status.altara_plus_nova)
    || isTruthyAltaraPlusFlag(status.altaraPlusNova)
    || planKey === ALTARA_PLUS_PLAN_NOVA
  );
}

function currentUserHasAltaraPlusCore() {
  return hasAltaraPlusCoreAccess(getCurrentUserAltaraPlusStatus());
}

function currentUserHasAltaraPlusNova() {
  return hasAltaraPlusNovaAccess(getCurrentUserAltaraPlusStatus());
}

function normalizeAltaraPlusFeatureTier(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "free") return "free";
  if (normalized === "core") return "core";
  if (normalized === "nova") return "nova";
  return "";
}

function getAltaraPlusFeatureRequiredTier(featureKey = "") {
  const key = String(featureKey || "").trim().toLowerCase();
  return normalizeAltaraPlusFeatureTier(ALTARA_PLUS_FEATURE_TIERS[key] || "");
}

function getAltaraPlusFeatureRequiredLabel(featureKey = "") {
  const tier = getAltaraPlusFeatureRequiredTier(featureKey);
  if (tier === "nova") return "ALTARA+ Nova";
  if (tier === "core") return "ALTARA+ Core";
  if (tier === "free") return "Free";
  return "ALTARA+";
}

function canUseAltaraPlusFeature(featureKey = "", statusInput = null) {
  const tier = getAltaraPlusFeatureRequiredTier(featureKey);
  if (!tier) return false;
  if (tier === "free") return true;
  const status = statusInput && typeof statusInput === "object"
    ? normalizeAltaraPlusClientState(statusInput)
    : getCurrentUserAltaraPlusStatus();
  if (tier === "nova") return hasAltaraPlusNovaAccess(status);
  if (tier === "core") return hasAltaraPlusCoreAccess(status);
  return false;
}

function getAltaraPlusFeatureDebugSnapshot() {
  const status = getCurrentUserAltaraPlusStatus();
  const featureKeys = [
    "focus_profiles",
    "focus_schedules",
    "focus_auto_apps",
    "focus_auto_calls",
    "focus_auto_screenshare",
    "spatial_audio_basic",
    "spatial_audio_more_participants",
    "spatial_audio_saved_layouts",
    "spatial_audio_personal_presets",
    "spatial_audio_personal_tuning",
    "spatial_audio_layout_sync",
    "spatial_audio_hd",
    "spatial_audio_auto_arrange",
    "spatial_audio_advanced_presets",
    "spatial_audio_context_profiles",
    "spatial_audio_layout_import_export",
  ];
  return {
    rawStatus: lastAltaraPlusStatusRpcSnapshot ? { ...lastAltaraPlusStatusRpcSnapshot } : null,
    normalizedStatus: { ...status },
    planKey: status.planKey || null,
    tier: status.planKey === ALTARA_PLUS_PLAN_NOVA ? "nova" : (status.planKey === ALTARA_PLUS_PLAN_CORE ? "core" : null),
    isActive: status.hasAltaraPlus === true,
    featureAccess: Object.fromEntries(featureKeys.map((key) => [key, canUseAltaraPlusFeature(key, status)])),
  };
}

function exposeAltaraPlusDebugHelper() {
  try {
    window.__ALTARA_PLUS_DEBUG__ = async function __ALTARA_PLUS_DEBUG__(options = {}) {
      const refresh = options === true || options?.refresh === true;
      if (refresh) {
        await refreshCurrentUserAltaraPlusStatus({ reason: "debug_helper", force: true }).catch(() => null);
      }
      const snapshot = getAltaraPlusFeatureDebugSnapshot();
      try { console.info("[altara-plus] debug", snapshot); } catch (_) {}
      return snapshot;
    };
  } catch (_) {}
}

exposeAltaraPlusDebugHelper();

function getAltaraPlusPlanDisplayLabel(status = getCurrentUserAltaraPlusStatus()) {
  if (!status?.hasAltaraPlus) return "Free";
  if (status.planKey === ALTARA_PLUS_PLAN_NOVA) return "ALTARA+ Nova";
  if (status.planKey === ALTARA_PLUS_PLAN_CORE) return "ALTARA+ Core";
  return "ALTARA+";
}

function buildProfileMetaSegmentsHtml(segmentsInput = []) {
  const segments = (Array.isArray(segmentsInput) ? segmentsInput : [segmentsInput])
    .map((segment) => String(segment || "").trim())
    .filter(Boolean);
  if (!segments.length) return "";
  return segments.map((segment, idx) => (
    idx === 0
      ? esc(segment)
      : '<span class="profile-meta-dot" aria-hidden="true"></span>' + esc(segment)
  )).join("");
}

function getAltaraPlusProfileBadgeAssetPath(planKeyInput) {
  const planKey = normalizeAltaraPlusPlanKey(planKeyInput);
  if (planKey === ALTARA_PLUS_PLAN_CORE) return "assets/badges/altara-plus-core.svg";
  if (planKey === ALTARA_PLUS_PLAN_NOVA) return "assets/badges/altara-plus-nova.svg";
  return "";
}

function buildAltaraPlusProfileBadgeHtmlForPlanKey(planKeyInput, {
  className = "altaraPlusProfileBadge",
} = {}) {
  const planKey = normalizeAltaraPlusPlanKey(planKeyInput);
  if (!planKey) return "";
  const assetPath = getAltaraPlusProfileBadgeAssetPath(planKey);
  if (!assetPath) return "";
  const isNova = planKey === ALTARA_PLUS_PLAN_NOVA;
  const toneClass = isNova ? (className + "--nova") : (className + "--core");
  const tooltipText = isNova ? "ALTARA+ Nova Supporter" : "ALTARA+ Core Supporter";
  return '<span class="' + escAttr(className) + ' ' + escAttr(toneClass) + '" role="img" aria-label="' + escAttr(tooltipText) + '" title="' + escAttr(tooltipText) + '"><img class="altaraPlusProfileBadge__img" src="' + escAttr(assetPath) + '" alt="" loading="lazy" decoding="async" draggable="false" /></span>';
}

function resolveAltaraPlusPlanKeyForProfileBadge(profileInput = null, profileIdInput = "") {
  const profile = profileInput && typeof profileInput === "object" ? profileInput : {};
  const profileId = normId(profileIdInput || profile?.id || "");
  const selfId = normId(state.user?.id || "");

  if (selfId && profileId && selfId === profileId) {
    const status = getCurrentUserAltaraPlusStatus();
    if (!status?.hasAltaraPlus) return null;
    return normalizeAltaraPlusPlanKey(status.planKey) || null;
  }

  const hasAltaraPlusRaw = (
    profile?.has_altara_plus
    ?? profile?.hasAltaraPlus
    ?? profile?.altara_plus_active
    ?? profile?.altaraPlusActive
    ?? null
  );
  const hasAltaraPlus = hasAltaraPlusRaw === true || String(hasAltaraPlusRaw || "").trim().toLowerCase() === "true";
  if (!hasAltaraPlus) return null;

  const planKeyCandidate = (
    profile?.plan_key
    ?? profile?.planKey
    ?? profile?.altara_plus_plan_key
    ?? profile?.altaraPlusPlanKey
    ?? profile?.altara_plus_plan
    ?? profile?.altaraPlusPlan
    ?? ""
  );

  return normalizeAltaraPlusPlanKey(planKeyCandidate) || null;
}

function buildCurrentUserAltaraPlusProfileBadgeHtml({
  className = "altaraPlusProfileBadge",
} = {}) {
  const status = getCurrentUserAltaraPlusStatus();
  if (!status.hasAltaraPlus) return "";
  return buildAltaraPlusProfileBadgeHtmlForPlanKey(status.planKey, { className });
}

function formatAltaraPlusExpiryLabel(isoValue) {
  const raw = String(isoValue || "").trim();
  if (!raw) return "-";
  const dt = new Date(raw);
  if (!Number.isFinite(dt.getTime())) return "-";
  try {
    return dt.toLocaleString();
  } catch (_) {
    return dt.toISOString();
  }
}

function parseAltaraPlusStatusRpcRow(data) {
  const row = Array.isArray(data) ? (data[0] || null) : (data && typeof data === "object" ? data : null);
  lastAltaraPlusStatusRpcSnapshot = row ? { ...row } : null;
  if (!row || typeof row !== "object") return createFreeAltaraPlusStatus();
  return normalizeAltaraPlusClientState(row);
}

async function loadCurrentUserAltaraPlusStatus() {
  if (!state.user?.id) return createFreeAltaraPlusStatus();
  const { data, error } = await rpcWithTimeout("get_my_altara_plus_status", {});
  if (error) {
    console.warn("altara+ status load failed", error?.message || error);
    return createFreeAltaraPlusStatus();
  }
  return parseAltaraPlusStatusRpcRow(data);
}

function normalizeAltaraPlusCheckoutPlan(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "core" || raw === "nova") return raw;
  return "";
}

function normalizeAltaraPlusCheckoutInterval(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "monthly" || raw === "yearly") return raw;
  return "";
}

function getAltaraPlusCheckoutOption(planInput, intervalInput) {
  const plan = normalizeAltaraPlusCheckoutPlan(planInput);
  const interval = normalizeAltaraPlusCheckoutInterval(intervalInput);
  if (!plan || !interval) return null;
  return ALTARA_PLUS_CHECKOUT_OPTION_LIST.find((item) => item.plan === plan && item.interval === interval) || null;
}

function resolveAltaraPlusCheckoutReturnStateFromValue(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "success") return "success";
  if (raw === "cancelled" || raw === "canceled") return "cancelled";
  return "";
}

function resolveAltaraPlusPortalReturnStateFromValue(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "return") return "return";
  return "";
}

function parseAltaraPlusCheckoutReturnSignalFromLocation() {
  try {
    const url = new URL(window.location.href);
    const state = resolveAltaraPlusCheckoutReturnStateFromValue(url.searchParams.get("altaraPlusCheckout"));
    if (!state) return null;
    const sessionId = String(url.searchParams.get("session_id") || "").trim();
    return {
      state,
      sessionId,
    };
  } catch (_) {
    return null;
  }
}

function parseAltaraPlusPortalReturnSignalFromLocation() {
  try {
    const url = new URL(window.location.href);
    const state = resolveAltaraPlusPortalReturnStateFromValue(url.searchParams.get("altaraPlusPortal"));
    if (!state) return null;
    return { state };
  } catch (_) {
    return null;
  }
}

function consumeAltaraPlusCheckoutReturnSignalFromLocation() {
  if (altaraPlusCheckoutReturnSignalConsumed) return null;
  const signal = parseAltaraPlusCheckoutReturnSignalFromLocation();
  if (!signal) return null;
  altaraPlusCheckoutReturnSignalConsumed = true;
  try {
    const url = new URL(window.location.href);
    let changed = false;
    ["altaraPlusCheckout", "session_id"].forEach((key) => {
      if (!url.searchParams.has(key)) return;
      url.searchParams.delete(key);
      changed = true;
    });
    if (changed) {
      const nextHref = url.pathname + url.search + url.hash;
      history.replaceState(history.state, "", nextHref);
    }
  } catch (_) {}
  return signal;
}

function consumeAltaraPlusPortalReturnSignalFromLocation() {
  if (altaraPlusPortalReturnSignalConsumed) return null;
  const signal = parseAltaraPlusPortalReturnSignalFromLocation();
  if (!signal) return null;
  altaraPlusPortalReturnSignalConsumed = true;
  try {
    const url = new URL(window.location.href);
    if (url.searchParams.has("altaraPlusPortal")) {
      url.searchParams.delete("altaraPlusPortal");
      const nextHref = url.pathname + url.search + url.hash;
      history.replaceState(history.state, "", nextHref);
    }
  } catch (_) {}
  return signal;
}

function shouldRefreshAltaraPlusFromWindowLocation() {
  return !!parseAltaraPlusCheckoutReturnSignalFromLocation()
    || !!parseAltaraPlusPortalReturnSignalFromLocation();
}

function normalizeAltaraBillingReturnType(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "checkout") return "checkout";
  if (raw === "portal") return "portal";
  return "";
}

async function openAltaraBillingUrl(url, returnType = "checkout") {
  const targetUrl = String(url || "").trim();
  if (!/^https?:\/\//i.test(targetUrl)) throw new Error("altara_plus_billing_url_invalid");

  const normalizedReturnType = normalizeAltaraBillingReturnType(returnType) || "checkout";
  const bridge = getDesktopBridge();
  if (bridge && typeof bridge.openAltaraBillingWindow === "function") {
    const result = await bridge.openAltaraBillingWindow(targetUrl, normalizedReturnType);
    if (result && result.ok === false) {
      throw new Error(String(result.reason || "altara_plus_billing_window_open_failed"));
    }
    return;
  }

  try {
    window.location.assign(targetUrl);
  } catch (_) {
    window.location.href = targetUrl;
  }
}

async function handleAltaraPlusCheckoutReturnSignal(signal) {
  const state = resolveAltaraPlusCheckoutReturnStateFromValue(signal?.state);
  if (!state) return false;

  if (state === "success") {
    showAltaraPlusCheckoutToast("Payment completed. Confirming your ALTARA+ access...", "info");
  } else {
    showAltaraPlusCheckoutToast("Checkout cancelled.", "warn");
  }

  const refreshDelayMs = state === "success" ? 1800 : 0;
  if (refreshDelayMs > 0) {
    await new Promise((resolve) => setTimeout(resolve, refreshDelayMs));
  }

  await refreshCurrentUserAltaraPlusStatus({ reason: "checkout_return", force: true }).catch(() => null);
  return true;
}

async function handleAltaraPlusPortalReturnSignal(signal) {
  const state = resolveAltaraPlusPortalReturnStateFromValue(signal?.state);
  if (!state) return false;

  showAltaraPlusCheckoutToast("Subscription settings updated. Refreshing ALTARA+ status...", "info");
  await new Promise((resolve) => setTimeout(resolve, 1200));
  await refreshCurrentUserAltaraPlusStatus({ reason: "portal_return", force: true }).catch(() => null);
  return true;
}

function bindAltaraPlusDesktopBillingEventsOnce() {
  if (altaraPlusDesktopBillingEventsBound) return;
  altaraPlusDesktopBillingEventsBound = true;

  const bridge = getDesktopBridge();
  if (!bridge || typeof bridge.onAltaraBillingEvent !== "function") return;

  try {
    bridge.onAltaraBillingEvent((payload) => {
      const eventType = String(payload?.type || "").trim().toLowerCase();
      if (eventType === "closed") {
        showAltaraPlusCheckoutToast("Billing window closed.", "warn");
        return;
      }
      if (eventType !== "return") return;

      const returnType = normalizeAltaraBillingReturnType(payload?.returnType);
      if (returnType === "portal") {
        void handleAltaraPlusPortalReturnSignal({ state: "return" });
        return;
      }
      if (returnType === "checkout") {
        const checkoutState = resolveAltaraPlusCheckoutReturnStateFromValue(payload?.checkoutState);
        if (!checkoutState) return;
        void handleAltaraPlusCheckoutReturnSignal({ state: checkoutState, sessionId: "" });
      }
    });
  } catch (_) {}
}

function showAltaraPlusCheckoutToast(message, tone = "info") {
  const text = String(message || "").trim();
  if (!text) return;
  let toast = document.getElementById("altaraPlusCheckoutToast");
  if (!toast) {
    toast = document.createElement("div");
    toast.id = "altaraPlusCheckoutToast";
    toast.className = "altaraPlusCheckoutToast";
    document.body.appendChild(toast);
  }
  toast.textContent = text;
  toast.setAttribute("data-tone", tone === "warn" ? "warn" : "info");
  toast.classList.add("is-visible");
  if (altaraPlusCheckoutToastTimer) clearTimeout(altaraPlusCheckoutToastTimer);
  altaraPlusCheckoutToastTimer = setTimeout(() => {
    altaraPlusCheckoutToastTimer = null;
    toast.classList.remove("is-visible");
  }, 4200);
}

function getAltaraPlusIntervalCtaLabel(option) {
  if (!option) return "Upgrade";
  if (option.plan === "core") {
    return option.interval === "yearly" ? "Support with Core yearly" : "Support with Core monthly";
  }
  if (option.plan === "nova") {
    return option.interval === "yearly" ? "Support with Nova yearly" : "Support with Nova monthly";
  }
  return "Upgrade";
}

function getAltaraPlusIntervalDisplayLabel(intervalKey) {
  const normalized = normalizeAltaraPlusIntervalKey(intervalKey);
  if (normalized === "monthly") return "Monthly";
  if (normalized === "yearly") return "Yearly";
  return "-";
}

function getAltaraPlusCheckoutActionState(option, status) {
  const currentStatus = normalizeAltaraPlusClientState(status);
  const isBusy = altaraPlusCheckoutInFlight || altaraPlusBillingPortalInFlight;

  if (!option) {
    return {
      enabled: false,
      label: "Unavailable",
      isCurrent: false,
      isUpgradePath: false,
      target: "none",
    };
  }

  if (isBusy) {
    return {
      enabled: false,
      label: altaraPlusBillingPortalInFlight ? "Opening Billing Portal..." : "Opening Checkout...",
      isCurrent: false,
      isUpgradePath: false,
      target: "none",
    };
  }

  if (!currentStatus.hasAltaraPlus) {
    return {
      enabled: true,
      label: getAltaraPlusIntervalCtaLabel(option),
      isCurrent: false,
      isUpgradePath: false,
      target: "checkout",
    };
  }

  const currentIntervalKey = normalizeAltaraPlusIntervalKey(currentStatus.intervalKey);
  const isExactCurrentPlan = option.planKey === currentStatus.planKey
    && !!currentIntervalKey
    && option.interval === currentIntervalKey;

  if (isExactCurrentPlan) {
    return {
      enabled: false,
      label: "Current plan",
      isCurrent: true,
      isUpgradePath: false,
      target: "none",
    };
  }

  if (currentStatus.planKey === ALTARA_PLUS_PLAN_CORE) {
    if (option.planKey === ALTARA_PLUS_PLAN_NOVA) {
      return {
        enabled: true,
        label: "Upgrade to Nova",
        isCurrent: false,
        isUpgradePath: true,
        target: "portal",
      };
    }
    return {
      enabled: true,
      label: "Switch billing interval",
      isCurrent: false,
      isUpgradePath: false,
      target: "portal",
    };
  }

  if (currentStatus.planKey === ALTARA_PLUS_PLAN_NOVA) {
    if (option.planKey === ALTARA_PLUS_PLAN_NOVA) {
      return {
        enabled: true,
        label: "Switch billing interval",
        isCurrent: false,
        isUpgradePath: false,
        target: "portal",
      };
    }

    return {
      enabled: true,
      label: "Manage in portal",
      isCurrent: false,
      isUpgradePath: false,
      target: "portal",
    };
  }

  return {
    enabled: true,
    label: "Manage in portal",
    isCurrent: false,
    isUpgradePath: false,
    target: "portal",
  };
}

function renderSettingsAltaraPlusPlanOptions() {
  const status = getCurrentUserAltaraPlusStatus();
  const root = document.getElementById("settingsAltaraPlusPlanOptions");
  if (!root) return;

  root.querySelectorAll(".settingsAltaraPlusPlanCard").forEach((card) => {
    if (!(card instanceof HTMLElement)) return;
    const planRoot = normalizeAltaraPlusCheckoutPlan(card.dataset.planRoot);
    const planKey = planRoot === "nova" ? ALTARA_PLUS_PLAN_NOVA : (planRoot === "core" ? ALTARA_PLUS_PLAN_CORE : null);
    card.classList.toggle("is-current-family", !!(status.hasAltaraPlus && planKey && status.planKey === planKey));
  });

  root.querySelectorAll('button[data-altara-plus-checkout="1"]').forEach((button) => {
    if (!(button instanceof HTMLButtonElement)) return;
    const option = getAltaraPlusCheckoutOption(button.dataset.plan, button.dataset.interval);
    const actionState = getAltaraPlusCheckoutActionState(option, status);
    button.disabled = !actionState.enabled;
    button.setAttribute("aria-disabled", actionState.enabled ? "false" : "true");
    button.textContent = actionState.label;
    button.classList.toggle("is-current", !!actionState.isCurrent);
    button.classList.toggle("is-upgrade", !!actionState.isUpgradePath);
  });
}


function renderSettingsIdentityProfilePreviewAltaraPlusBadge() {
  const badgeEl = document.getElementById("settingsIdentityAltaraPlusBadge");
  if (!(badgeEl instanceof HTMLElement)) return;
  const badgeHtml = buildCurrentUserAltaraPlusProfileBadgeHtml({ className: "altaraPlusProfileBadge settingsIdentityAltaraPlusProfileBadge" });
  badgeEl.hidden = !badgeHtml;
  badgeEl.style.display = badgeHtml ? "" : "none";
  badgeEl.innerHTML = badgeHtml || "";
}
function renderSettingsAltaraPlusPanel() {
  const status = getCurrentUserAltaraPlusStatus();
  const hasAltaraPlus = status.hasAltaraPlus === true;
  const busy = altaraPlusCheckoutInFlight || altaraPlusBillingPortalInFlight;
  const currentPlanLabel = hasAltaraPlus
    ? (status.planKey === ALTARA_PLUS_PLAN_NOVA ? "ALTARA+ Nova" : "ALTARA+ Core")
    : "Free";
  const currentIntervalLabel = hasAltaraPlus ? getAltaraPlusIntervalDisplayLabel(status.intervalKey) : "-";
  const expiryLabel = hasAltaraPlus
    ? (status.expiresAt ? formatAltaraPlusExpiryLabel(status.expiresAt) : "No date")
    : "-";
  const topHintEl = document.getElementById("settingsAltaraPlusHint");

  const planEl = document.getElementById("settingsAltaraPlusCurrentPlan");
  if (planEl) planEl.textContent = currentPlanLabel;

  const statusEl = document.getElementById("settingsAltaraPlusStatus");
  if (statusEl) statusEl.textContent = hasAltaraPlus ? "Active" : "Inactive";

  const intervalEl = document.getElementById("settingsAltaraPlusInterval");
  if (intervalEl) intervalEl.textContent = currentIntervalLabel;

  const dateLabelEl = document.getElementById("settingsAltaraPlusDateLabel");
  if (dateLabelEl) dateLabelEl.textContent = "Renewal";

  const expiresEl = document.getElementById("settingsAltaraPlusExpiresAt");
  if (expiresEl) expiresEl.textContent = expiryLabel;

  const envPillEl = document.getElementById("settingsAltaraPlusEnvironmentPill");
  if (envPillEl) {
    const isTest = String(status.environment || "").trim().toLowerCase() === "test";
    envPillEl.hidden = !isTest;
    if (isTest) envPillEl.textContent = "Test environment";
  }

  if (topHintEl) {
    if (!hasAltaraPlus) {
      topHintEl.textContent = "ALTARA+ unlocks higher usage limits, personal Focus tools, personal Spatial Audio upgrades, better screen sharing, and supporter recognition.";
    } else {
      topHintEl.textContent = "Thank you for supporting ALTARA. Your ALTARA+ personal features and profile badge are active.";
    }
  }

  const descriptionEl = document.getElementById("settingsAltaraPlusStatusDescription");
  if (descriptionEl) {
    if (!hasAltaraPlus) {
      descriptionEl.textContent = "Free includes basic ALTARA, basic Focus, basic personal Spatial Audio, and standard calls, messages, and widgets.";
    } else {
      descriptionEl.textContent = "Your ALTARA+ features are active. Thank you for supporting ALTARA.";
    }
  }

  const cancelWrapEl = document.getElementById("settingsAltaraPlusCancelNotice");
  const cancelTextEl = document.getElementById("settingsAltaraPlusCancelNoticeText");
  const cancelBtnEl = document.getElementById("btnSettingsAltaraPlusManageCancellation");
  const hasCancellation = hasAltaraPlus && status.cancelAtPeriodEnd === true;
  if (cancelWrapEl) cancelWrapEl.hidden = !hasCancellation;
  if (cancelTextEl && hasCancellation) {
    const endDate = status.expiresAt ? formatAltaraPlusExpiryLabel(status.expiresAt) : "the end of your current period";
    cancelTextEl.textContent = `Your subscription is scheduled to end on ${endDate}. You will keep ALTARA+ until then.`;
  }
  if (cancelBtnEl instanceof HTMLButtonElement) {
    cancelBtnEl.disabled = !hasCancellation || busy;
    cancelBtnEl.setAttribute("aria-disabled", cancelBtnEl.disabled ? "true" : "false");
    cancelBtnEl.textContent = busy ? "Opening Billing Portal..." : "Manage cancellation";
  }

  const manageBtn = document.getElementById("btnSettingsAltaraPlusManage");
  if (manageBtn instanceof HTMLButtonElement) {
    manageBtn.hidden = !hasAltaraPlus;
    manageBtn.disabled = !hasAltaraPlus || busy;
    manageBtn.setAttribute("aria-disabled", manageBtn.disabled ? "true" : "false");
    manageBtn.textContent = altaraPlusBillingPortalInFlight
      ? "Opening Billing Portal..."
      : "Manage subscription";
  }

  renderSettingsAltaraPlusPlanOptions();

  const hintEl = document.getElementById("settingsAltaraPlusCtaHint");
  if (hintEl) {
    if (altaraPlusCheckoutInFlight) {
      hintEl.textContent = "Opening Stripe Checkout...";
    } else if (altaraPlusBillingPortalInFlight) {
      hintEl.textContent = "Opening Stripe Billing Portal...";
    } else {
      hintEl.textContent = "Payments are handled securely by Stripe. You can manage or cancel your subscription through the billing portal. Core raises key limits and unlocks advanced personal tools; Nova includes Core plus the highest limits, automation, and HD Spatial Audio.";
    }
  }
}

function rerenderOpenSelfMeProfilePopoutForAltaraPlus() {
  const popout = document.getElementById("meProfilePopout");
  if (!popout || !popout.classList.contains("is-open")) return;
  const meId = normId(state.user?.id || "");
  const targetId = normId(getMeProfilePopoutTargetId());
  if (!meId || targetId !== meId) return;
  const seedProfile = getMeUserCardSeed();
  popout.innerHTML = buildMeProfilePopoutHtml(seedProfile, { loading: false });
  queueManagedGifPlaybackSync(popout);
  applyMeProfilePopoutBannerStyle(seedProfile);
  renderMeProfilePopoutWidgetsPreview({ loading: false });
  positionMeProfilePopout();
}

function syncCurrentUserAltaraPlusUi() {
  renderSettingsIdentityProfilePreviewAltaraPlusBadge();
  renderSettingsAltaraPlusPanel();
  try { renderFocusAdvancedSettingsUi(getFocusNotificationSettings()); } catch (_) {}
  try { scheduleFocusAutomationEvaluation("entitlement_changed"); } catch (_) {}
  rerenderOpenSelfMeProfilePopoutForAltaraPlus();
  refreshOpenUserCard();
  // TODO: if public ALTARA+ badges are needed, expose a minimal safe RPC with only public entitlement bits.
}

function applyCurrentUserAltaraPlusStatus(statusInput = null) {
  state.altaraPlus = normalizeAltaraPlusClientState(statusInput);
  syncCurrentUserAltaraPlusUi();
  return state.altaraPlus;
}

async function refreshCurrentUserAltaraPlusStatus({ reason = "manual", force = false } = {}) {
  if (!state.user?.id) return applyCurrentUserAltaraPlusStatus(createFreeAltaraPlusStatus());
  if (altaraPlusStatusRefreshInFlight && !force) return altaraPlusStatusRefreshInFlight;
  altaraPlusStatusRefreshInFlight = (async () => {
    try {
      const loaded = await loadCurrentUserAltaraPlusStatus();
      return applyCurrentUserAltaraPlusStatus(loaded);
    } catch (error) {
      console.warn("altara+ status refresh failed (" + String(reason || "manual") + "):", error?.message || error);
      return applyCurrentUserAltaraPlusStatus(createFreeAltaraPlusStatus());
    } finally {
      altaraPlusStatusRefreshInFlight = null;
    }
  })();
  return altaraPlusStatusRefreshInFlight;
}

async function createAltaraPlusCheckoutSessionUrl({ plan = "", interval = "" } = {}) {
  const option = getAltaraPlusCheckoutOption(plan, interval);
  if (!option) throw new Error("altara_plus_checkout_option_invalid");

  const edgeFunctionName = ALTARA_PLUS_CHECKOUT_FUNCTION_NAME;
  const functionPath = "/functions/v1/" + edgeFunctionName;
  const authReady = await ensureSupabaseFunctionInvokeAuthReady({
    edgeFunctionName,
    functionPath,
    requireUser: true,
    logPrefix: "[altara-plus auth]",
    logEvent: "altara_plus_checkout.auth_state",
    logChannel: "altara-plus",
    failEvent: "altara_plus_checkout.auth_missing",
  });
  if (!authReady.ok) throw authReady.error || new Error("altara_plus_checkout_auth_missing");

  const { data, error } = await supabase.functions.invoke(edgeFunctionName, {
    body: {
      plan: option.plan,
      interval: option.interval,
    },
  });
  if (error) throw error;
  if (!data || typeof data !== "object") throw new Error("altara_plus_checkout_response_invalid");

  const url = String(data?.url || "").trim();
  if (!/^https?:\/\//i.test(url)) throw new Error("altara_plus_checkout_url_invalid");
  return url;
}

async function createAltaraPlusBillingPortalSessionUrl() {
  const edgeFunctionName = ALTARA_PLUS_BILLING_PORTAL_FUNCTION_NAME;
  const functionPath = "/functions/v1/" + edgeFunctionName;
  const authReady = await ensureSupabaseFunctionInvokeAuthReady({
    edgeFunctionName,
    functionPath,
    requireUser: true,
    logPrefix: "[altara-plus auth]",
    logEvent: "altara_plus_portal.auth_state",
    logChannel: "altara-plus",
    failEvent: "altara_plus_portal.auth_missing",
  });
  if (!authReady.ok) throw authReady.error || new Error("altara_plus_portal_auth_missing");

  const { data, error } = await supabase.functions.invoke(edgeFunctionName, { body: {} });
  if (error) throw error;
  if (!data || typeof data !== "object") throw new Error("altara_plus_portal_response_invalid");

  const url = String(data?.url || "").trim();
  if (!/^https?:\/\//i.test(url)) throw new Error("altara_plus_portal_url_invalid");
  return url;
}

async function openAltaraPlusBillingPortalFromSettings({ source = "manage" } = {}) {
  if (!state.user?.id) return;
  const status = getCurrentUserAltaraPlusStatus();
  if (!status.hasAltaraPlus) return;
  if (altaraPlusCheckoutInFlight || altaraPlusBillingPortalInFlight) return;

  altaraPlusBillingPortalInFlight = true;
  renderSettingsAltaraPlusPanel();
  try {
    const portalUrl = await createAltaraPlusBillingPortalSessionUrl();
    await openAltaraBillingUrl(portalUrl, "portal");
  } catch (error) {
    console.warn("altara+ billing portal open failed (" + String(source || "manage") + ")", error?.message || error);
    showAltaraPlusCheckoutToast("Could not open subscription management right now. Please try again.", "warn");
  } finally {
    altaraPlusBillingPortalInFlight = false;
    renderSettingsAltaraPlusPanel();
  }
}

async function startAltaraPlusCheckoutFromSettings({ plan = "", interval = "" } = {}) {
  if (!state.user?.id) return;
  if (altaraPlusCheckoutInFlight || altaraPlusBillingPortalInFlight) return;

  const option = getAltaraPlusCheckoutOption(plan, interval);
  if (!option) return;

  const actionState = getAltaraPlusCheckoutActionState(option, getCurrentUserAltaraPlusStatus());
  if (!actionState.enabled) return;
  if (actionState.target === "portal") {
    await openAltaraPlusBillingPortalFromSettings({ source: "plan_option" });
    return;
  }
  if (actionState.target !== "checkout") return;

  altaraPlusCheckoutInFlight = true;
  renderSettingsAltaraPlusPanel();
  try {
    const checkoutUrl = await createAltaraPlusCheckoutSessionUrl({
      plan: option.plan,
      interval: option.interval,
    });
    await openAltaraBillingUrl(checkoutUrl, "checkout");
  } catch (error) {
    console.warn("altara+ checkout session create failed", error?.message || error);
    showAltaraPlusCheckoutToast("Could not open checkout right now. Please try again.", "warn");
  } finally {
    altaraPlusCheckoutInFlight = false;
    renderSettingsAltaraPlusPanel();
  }
}

async function handleAltaraPlusCheckoutReturnFromLocation() {
  const signal = consumeAltaraPlusCheckoutReturnSignalFromLocation();
  return handleAltaraPlusCheckoutReturnSignal(signal);
}

async function handleAltaraPlusPortalReturnFromLocation() {
  const signal = consumeAltaraPlusPortalReturnSignalFromLocation();
  return handleAltaraPlusPortalReturnSignal(signal);
}

const RELATIONSHIP_TRACE_ENABLED = false;
let relationshipTraceSeq = 0;
let relationshipActiveTrace = null;
let relationshipReconcileTrace = null;

function relationshipNow() {
  try {
    if (typeof performance !== "undefined" && typeof performance.now === "function") {
      return performance.now();
    }
  } catch (_) {}
  return Date.now();
}

function beginRelationshipTrace(action = "relationship", meta = {}) {
  if (!RELATIONSHIP_TRACE_ENABLED) return null;
  const id = ++relationshipTraceSeq;
  const safeAction = String(action || "relationship").trim() || "relationship";
  const baseLabel = `[relationship:${id}] ${safeAction}`;
  const trace = {
    id,
    action: safeAction,
    baseLabel,
    startedAt: relationshipNow(),
    ended: false,
    deferEnd: false,
  };
  try { console.groupCollapsed(baseLabel); } catch (_) {}
  try { console.time(`${baseLabel} total`); } catch (_) {}
  try { console.log(`${baseLabel} meta`, meta || {}); } catch (_) {}
  return trace;
}

function setRelationshipActiveTrace(trace = null) {
  relationshipActiveTrace = trace || null;
}

function beginRelationshipActionTrace(action = "relationship", meta = {}) {
  const trace = beginRelationshipTrace(action, meta);
  if (trace) setRelationshipActiveTrace(trace);
  relationshipTraceLog(trace, "handler:start", meta || {});
  return trace;
}

function getRelationshipCurrentTrace() {
  return relationshipActiveTrace || relationshipReconcileTrace || null;
}

function relationshipTracePhaseLabel(trace, phase = "") {
  if (!trace) return "";
  return `${trace.baseLabel} :: ${String(phase || "phase").trim() || "phase"}`;
}

function relationshipTraceLog(trace, phase, meta = null) {
  if (!trace || trace.ended) return;
  try {
    if (meta === null || typeof meta === "undefined") console.log(`${trace.baseLabel} ${phase}`);
    else console.log(`${trace.baseLabel} ${phase}`, meta);
  } catch (_) {}
}

function relationshipTracePhaseStart(trace, phase, meta = null) {
  if (!trace || trace.ended) return "";
  const label = relationshipTracePhaseLabel(trace, phase);
  try { console.time(label); } catch (_) {}
  if (meta !== null && typeof meta !== "undefined") relationshipTraceLog(trace, `${phase}:start`, meta);
  return label;
}

function relationshipTracePhaseEnd(trace, label, meta = null) {
  if (!trace || !label || trace.ended) return;
  try { console.timeEnd(label); } catch (_) {}
  if (meta !== null && typeof meta !== "undefined") relationshipTraceLog(trace, `${label.split(" :: ").pop()}:end`, meta);
}

function relationshipTraceMeasureSync(trace, phase, fn, meta = null) {
  if (!trace || trace.ended) return fn();
  const label = relationshipTracePhaseStart(trace, phase, meta);
  try {
    return fn();
  } finally {
    relationshipTracePhaseEnd(trace, label);
  }
}

async function relationshipTraceMeasureAsync(trace, phase, fn, meta = null) {
  if (!trace || trace.ended) return await fn();
  const label = relationshipTracePhaseStart(trace, phase, meta);
  try {
    return await fn();
  } finally {
    relationshipTracePhaseEnd(trace, label);
  }
}

function relationshipTraceSchedulePaint(trace, label = "paint") {
  if (!trace || trace.ended) return;
  const startedAt = relationshipNow();
  requestAnimationFrame(() => {
    relationshipTraceLog(trace, `${label}:raf1`, {
      ms: Number((relationshipNow() - startedAt).toFixed(2)),
    });
    requestAnimationFrame(() => {
      relationshipTraceLog(trace, `${label}:raf2`, {
        ms: Number((relationshipNow() - startedAt).toFixed(2)),
      });
    });
  });
}

function endRelationshipTrace(trace, outcome = "done", meta = null) {
  if (!trace || trace.ended) return;
  trace.ended = true;
  const payload = {
    outcome,
    totalMs: Number((relationshipNow() - Number(trace.startedAt || 0)).toFixed(2)),
    ...(meta && typeof meta === "object" ? meta : {}),
  };
  try { console.log(`${trace.baseLabel} result`, payload); } catch (_) {}
  try { console.timeEnd(`${trace.baseLabel} total`); } catch (_) {}
  try { console.groupEnd(); } catch (_) {}
  if (relationshipActiveTrace === trace) relationshipActiveTrace = null;
  if (relationshipReconcileTrace === trace) relationshipReconcileTrace = null;
}

function deferRelationshipTraceToReconcile(trace, meta = null) {
  if (!trace || trace.ended) return;
  trace.deferEnd = true;
  if (relationshipActiveTrace === trace) relationshipActiveTrace = null;
  relationshipTraceLog(trace, "reconcile:scheduled", meta || {});
}

