function normalizeDeveloperPortalText(value = "", maxLen = 400) {
  return String(value || "").trim().replace(/\s+/g, " ").slice(0, maxLen);
}

function getSelectedDeveloperApp() {
  const selectedId = normId(settingsDeveloperSelectedAppId || "");
  return (settingsDeveloperApps || []).find((app) => normId(app?.app_id || app?.appId || "") === selectedId)
    || (settingsDeveloperApps || [])[0]
    || null;
}

function getSelectedDeveloperBot() {
  const app = getSelectedDeveloperApp();
  if (!app?.bot_id) return null;
  return {
    id: normId(app.bot_id || ""),
    appId: normId(app.app_id || ""),
    publicId: String(app.bot_public_id || "").trim(),
    name: String(app.bot_name || "").trim(),
    avatarUrl: String(app.bot_avatar_url || "").trim(),
    description: String(app.bot_description || "").trim(),
    status: String(app.bot_status || "").trim(),
    tokenPrefix: String(app.bot_token_prefix || "").trim(),
    lastUsedAt: String(app.bot_last_used_at || "").trim(),
    revokedAt: String(app.bot_revoked_at || "").trim(),
    defaultInstallPermissions: normalizeBotPermissionList(app.default_install_permissions || app.defaultInstallPermissions || ALTARA_BOT_DEFAULT_PERMISSIONS),
  };
}

function setSettingsDeveloperStatus(message = "", tone = "info") {
  settingsDeveloperStatusText = String(message || "").trim();
  settingsDeveloperStatusTone = String(tone || "info").trim().toLowerCase() || "info";
  renderSettingsDeveloperPortal();
}

function formatDeveloperDate(value = "") {
  const ts = Date.parse(String(value || ""));
  if (!Number.isFinite(ts)) return "Never";
  try {
    return new Date(ts).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
  } catch (_) {
    return new Date(ts).toLocaleString();
  }
}

function isDeveloperPortalMissingSqlError(error = null) {
  return isMissingRpcError(error) || /does not exist|schema cache|function .* does not exist|rpc/i.test(String(error?.message || error || ""));
}

async function settingsDeveloperRpc(name, payload = {}, timeoutMs = 6000) {
  const { data, error } = await rpcWithTimeout(name, payload || {}, timeoutMs);
  if (error) throw error;
  return data;
}

function firstDeveloperRpcRow(data) {
  return Array.isArray(data) ? (data[0] || null) : (data || null);
}

async function loadSettingsDeveloperCommands(botId = "") {
  const bid = normId(botId || "");
  settingsDeveloperCommands = [];
  if (!bid) return [];
  try {
    const data = await settingsDeveloperRpc("bots_list_app_commands", { p_bot_id: bid });
    settingsDeveloperCommands = Array.isArray(data) ? data : [];
  } catch (error) {
    if (!isDeveloperPortalMissingSqlError(error)) console.warn("developer bot commands load failed", error?.message || error);
    settingsDeveloperCommands = [];
  }
  return settingsDeveloperCommands;
}

async function loadSettingsDeveloperAuditLogs(botId = "") {
  const bid = normId(botId || "");
  settingsDeveloperAuditLogs = [];
  if (!bid) return [];
  try {
    const { data, error } = await supabase
      .from("bot_audit_logs")
      .select("id, action, server_id, channel_id, actor_user_id, metadata, created_at")
      .eq("bot_id", bid)
      .order("created_at", { ascending: false })
      .limit(25);
    if (error) throw error;
    settingsDeveloperAuditLogs = Array.isArray(data) ? data : [];
  } catch (error) {
    if (!isDeveloperPortalMissingSqlError(error)) console.warn("developer bot audit logs load failed", error?.message || error);
    settingsDeveloperAuditLogs = [];
  }
  return settingsDeveloperAuditLogs;
}
async function loadSettingsDeveloperPortal({ silent = false } = {}) {
  if (!state.user?.id) return;
  settingsDeveloperLoading = true;
  if (!silent) settingsDeveloperStatusText = "";
  renderSettingsDeveloperPortal();
  try {
    const rows = await settingsDeveloperRpc("bots_list_my_apps", {});
    settingsDeveloperApps = Array.isArray(rows) ? rows : [];
    if (!settingsDeveloperApps.some((app) => normId(app?.app_id || "") === normId(settingsDeveloperSelectedAppId || ""))) {
      settingsDeveloperSelectedAppId = normId(settingsDeveloperApps[0]?.app_id || "");
    }
    const bot = getSelectedDeveloperBot();
    await loadSettingsDeveloperCommands(bot?.id || "");
    if (!silent && !settingsDeveloperStatusText) settingsDeveloperStatusText = settingsDeveloperApps.length ? "Developer apps loaded." : "Create your first app to start.";
    settingsDeveloperStatusTone = "info";
  } catch (error) {
    settingsDeveloperApps = [];
    settingsDeveloperCommands = [];
    settingsDeveloperAuditLogs = [];
    settingsDeveloperStatusText = isDeveloperPortalMissingSqlError(error)
      ? "Bots SQL is not deployed yet. Apply SQL/SUPABASE_PATCH_BOTS_PHASE1.sql, deploy the bot Edge Functions, then reload."
      : `Could not load Developer Portal: ${String(error?.message || error || "unknown error")}`;
    settingsDeveloperStatusTone = "error";
  } finally {
    settingsDeveloperLoading = false;
    renderSettingsDeveloperPortal();
    exposeDeveloperPortalDebugHelper();
  }
}

function getDeveloperPortalAdminServers() {
  return (Array.isArray(state.servers) ? state.servers : [])
    .filter((server) => {
      const sid = normId(server?.serverId || server?.server_id || server?.id || "");
      return sid && currentUserCanManageApps(sid);
    })
    .map((server) => ({
      id: normId(server?.serverId || server?.server_id || server?.id || ""),
      name: normalizeConversationLabel(server?.name || server?.serverName || "Server", "Server"),
    }));
}

function buildDeveloperPortalTokenNoticeHtml() {
  const app = getSelectedDeveloperApp();
  const bot = getSelectedDeveloperBot();
  const appId = normId(app?.app_id || "");
  const botId = normId(bot?.id || "");
  const pieces = [];
  if (settingsDeveloperOneTimeSigningSecret?.appId === appId && settingsDeveloperOneTimeSigningSecret?.secret) {
    pieces.push(`
      <div class="settingsDeveloperSecretBox" data-secret-kind="signing">
        <div>
          <b>Signing secret</b>
          <small>Shown once. Only needed for Advanced Webhook Mode.</small>
        </div>
        <code>${esc(settingsDeveloperOneTimeSigningSecret.secret)}</code>
        <button class="btn ghost" type="button" data-dev-copy="signing-secret">Copy</button>
      </div>
    `);
  }
  if (settingsDeveloperOneTimeBotToken?.botId === botId && settingsDeveloperOneTimeBotToken?.token) {
    pieces.push(`
      <div class="settingsDeveloperSecretBox settingsDeveloperSecretBox--token" data-secret-kind="bot-token">
        <div>
          <b>Bot token</b>
          <small>Copy this token now. You won't be able to see it again.</small>
        </div>
        <code>${esc(settingsDeveloperOneTimeBotToken.token)}</code>
        <button class="btn ghost" type="button" data-dev-copy="bot-token">Copy</button>
      </div>
    `);
  }
  return pieces.join("");
}

function buildDeveloperPortalAppListHtml() {
  if (settingsDeveloperLoading && !settingsDeveloperApps.length) {
    return '<div class="settingsDeveloperEmpty">Loading apps...</div>';
  }
  if (!settingsDeveloperApps.length) {
    return '<div class="settingsDeveloperEmpty">No developer apps yet.</div>';
  }
  const selectedId = normId(settingsDeveloperSelectedAppId || "");
  return settingsDeveloperApps.map((app) => {
    const appId = normId(app?.app_id || "");
    const isSelected = appId === selectedId || (!selectedId && app === settingsDeveloperApps[0]);
    const botName = String(app?.bot_name || "").trim();
    return `
      <button class="settingsDeveloperAppRow${isSelected ? " is-active" : ""}" type="button" data-dev-select-app="${escAttr(appId)}">
        <span class="settingsDeveloperAppIcon">${esc(getGroupOrbFallbackChar(app?.app_name || "A", "A"))}</span>
        <span class="settingsDeveloperAppRow__text">
          <b>${esc(app?.app_name || "ALTARA App")}</b>
          <small>${botName ? `Bot: ${esc(botName)}` : "No bot yet"}</small>
        </span>
      </button>
    `;
  }).join("");
}

