function buildDeveloperPortalInviteSectionHtml() {
  const app = getSelectedDeveloperApp();
  const bot = getSelectedDeveloperBot();
  if (!app || !bot) return "";
  const adminServers = getDeveloperPortalAdminServers();
  const savedPermissions = getDeveloperSavedDefaultInstallPermissions(bot || app);
  const optionsHtml = adminServers.length
    ? adminServers.map((server) => `<option value="${escAttr(server.id)}">${esc(server.name)}</option>`).join("")
    : '<option value="">No manageable servers</option>';
  const permissionsHtml = ALTARA_BOT_PHASE1_PERMISSIONS.map((perm) => {
    const checked = savedPermissions.includes(perm.key) ? " checked" : "";
    return `
      <label class="settingsDeveloperPermRow">
        <input type="checkbox" data-dev-permission="${escAttr(perm.key)}"${checked} />
        <span>${esc(perm.label)}</span>
      </label>
    `;
  }).join("");
  const inviteUrl = buildBotAuthorizeUrl(normId(app.app_id || ""), savedPermissions);
  return `
    <div class="settingsDeveloperPanelBlock">
      <div class="settingsDeveloperBlockHead">
        <div>
          <b>Invite bot</b>
          <small>Server owner or Manage Apps permission is required.</small>
        </div>
      </div>
      <div class="settingsDeveloperInviteUrl"><code data-dev-authorize-url>${esc(inviteUrl)}</code></div>
      <select id="developerInstallServer" class="input"${adminServers.length ? "" : " disabled"}>${optionsHtml}</select>
      <div class="settingsDeveloperPermGrid">${permissionsHtml}</div>
      <div class="settingsDeveloperActions"><button class="btn ghost" type="button" data-dev-copy="authorize-url">Copy public invite link</button><button class="btn ghost" type="button" data-dev-action="open-authorize-url">Open invite in browser</button><button class="btn primary" type="button" data-dev-action="install-bot"${adminServers.length ? "" : " disabled"}>Install to server</button></div>
    </div>
  `;
}

