function openBotContextMenuAt(seed = {}, { point = null, anchorEl = null } = {}) {
  const profile = normalizeBotProfileSeed(seed);
  if (!profile.botId && !profile.publicId) return;
  const activeServerId = normId(seed?.serverId || seed?.server_id || getActiveServerContext?.()?.serverId || state.activeDm?.serverId || "");
  const manageAppsResolved = isCurrentServerPermissionSnapshotResolved(activeServerId);
  const canManageApps = manageAppsResolved && currentUserCanManageApps(activeServerId);
  const canExposeInvite = !!(profile?.appId && (profile?.isPublic || profile?.canManage));
  const inviteUrl = canExposeInvite ? buildBotAuthorizeUrl(profile.appId, getBotDefaultInstallPermissions(profile, ALTARA_BOT_DEFAULT_PERMISSIONS)) : "";
  const attrs = getBotContextProfileAttrs(profile, activeServerId, inviteUrl);
  const menu = ensureBotContextMenu();
  closeActivePopover();
  closeMessageMenu("open_other_menu");
  closeGroupMemberMenu("open_other_menu");
  closeGroupDmListMenu("open_other_menu");
  closeDmUserListMenu("open_other_menu");
  closeDmMuteDurationMenu("open_other_menu");
  closeDmUserRoleMenu("open_other_menu");
  closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });

  const item = (action, label, { danger = false, disabled = false, hint = "", extraAttrs = "" } = {}) => {
    const hintHtml = hint ? `<span class="msgMenu__itemHint">${esc(hint)}</span>` : "";
    return `<button class="msgMenu__item${danger ? " msgMenu__item--danger" : ""}${disabled ? " is-disabled" : ""}" data-bot-menu-act="${escAttr(action)}" ${attrs} ${extraAttrs} ${disabled ? "disabled" : ""}><span class="msgMenu__itemMain"><span>${esc(label)}</span>${hintHtml}</span></button>`;
  };
  const divider = '<div class="msgMenu__divider"></div>';
  const isBanned = profile?.isBanned === true;
  const canManageServerBot = !!(activeServerId && canManageApps);
  const canRemove = !!(profile.installed && canManageServerBot);
  const canBan = !!(profile.installed && canManageServerBot && !isBanned);
  const canUnban = !!(isBanned && canManageServerBot);
  const canInstall = !!(inviteUrl && !profile.installed && !isBanned && canManageServerBot);
  const messageNode = anchorEl?.closest?.('.msg[data-message-source="bot_channel_messages"][data-msg-id]') || null;
  const timelineMessageId = String(messageNode?.getAttribute("data-msg-id") || "").trim();
  const timelineMessage = timelineMessageId ? getMessageById(timelineMessageId) : null;
  const messageModeration = getServerMessageModerationContext(timelineMessage);
  const canDeleteMessage = !!(
    timelineMessage
    && messageModeration.sourceTable === "bot_channel_messages"
    && messageModeration.canDelete
  );
  menu.innerHTML = [
    item("profile", "Profile"),
    item("mention", "Mention"),
    item("view_commands", "View Commands"),
    divider,
    item("copy_bot_id", "Copy Bot ID", { disabled: !(profile.publicId || profile.botId) }),
    item("copy_app_id", "Copy Application ID", { disabled: !profile.appId }),
    divider,
    item("install", profile.installed ? "Installed here" : "Add to Server / Install App", { disabled: !canInstall, hint: profile.installed ? "Already installed in this server" : (!manageAppsResolved ? "Checking app permissions" : (!canManageServerBot ? "Requires Manage Apps" : (inviteUrl ? "" : "This bot is private"))) }),
    item("copy_invite", "Copy Invite Link", { disabled: !inviteUrl, hint: inviteUrl ? "" : "This bot is private" }),
    profile.canManage ? item("manage", "Manage Bot") : "",
    canDeleteMessage ? divider : "",
    canDeleteMessage ? item("delete_message", "Delete Message", {
      danger: true,
      extraAttrs: `data-bot-menu-message-id="${escAttr(timelineMessageId)}"`,
    }) : "",
    canManageServerBot ? divider : "",
    item("remove", "Remove Bot / Kick Bot", { danger: true, disabled: !canRemove, hint: canRemove ? "" : "Requires Manage Apps" }),
    isBanned ? item("unban", "Unban Bot", { disabled: !canUnban, hint: canUnban ? "" : "Requires Manage Apps" }) : item("ban", "Ban Bot", { danger: true, disabled: !canBan, hint: canBan ? "" : "Requires Manage Apps" }),
    item("roles", "Roles", { disabled: true, hint: "Coming Soon" }),
  ].filter(Boolean).join("");
  menu.classList.add("is-open");
  setAltaraContextMenuOpen({
    type: "bot",
    targetId: profile.publicId || profile.botId || "",
    targetKind: "bot",
    menuId: "botContextMenu",
    anchorEl,
    point,
    reason: point ? "contextmenu" : "trigger",
  });
  const cursorPoint = point
    ? {
      clientX: Number.isFinite(Number(point.clientX)) ? Number(point.clientX) : Number(point.x),
      clientY: Number.isFinite(Number(point.clientY)) ? Number(point.clientY) : Number(point.y),
    }
    : null;
  const positionedByCursor = cursorPoint && openContextMenuAtCursor(cursorPoint, menu, { width: 286, minHeight: 180, margin: 8, offset: 6 });
  if (!positionedByCursor) {
    const positionedByAnchor = positionContextMenuByAnchor(menu, anchorEl, { width: 286, minHeight: 180, margin: 8, gap: 8 });
    if (!positionedByAnchor && cursorPoint) positionMenuAtPoint(menu, cursorPoint, { width: 286, minHeight: 180, margin: 8 });
  }
}
async function openBotProfileCard(seed = {}) {
  await ensureActiveServerBotListLoaded({ force: true });
  const initial = normalizeBotProfileSeed(seed);
  if (!initial.botId && !initial.publicId) return;
  renderBotProfileCard(initial, { loading: true });
  const full = normalizeBotProfileSeed(await fetchSafeBotProfile(initial));
  renderBotProfileCard(full, { loading: false });
}
function getDeveloperAppById(appId = "") {
  const aid = normId(appId || "");
  return (settingsDeveloperApps || []).find((app) => normId(app?.app_id || "") === aid) || null;
}

function safeBotRouteSearchParams(search = "") {
  try {
    const raw = String(search || "").trim();
    return new URLSearchParams(raw.startsWith("?") ? raw.slice(1) : raw);
  } catch (_) {
    return new URLSearchParams();
  }
}

function normalizeBotRoutePath(path = "/") {
  let out = String(path || "/").trim() || "/";
  out = out.replace(/\\/g, "/");
  out = out.replace(/\/index\.html$/i, "") || "/";
  out = out.replace(/\/+$/, "") || "/";
  return out;
}

function getBotHashRouteParts(hash = "") {
  const rawHash = String(hash || "");
  if (!rawHash.startsWith("#/")) return { path: "", search: "", params: new URLSearchParams() };
  const body = rawHash.slice(1);
  const idx = body.indexOf("?");
  const path = normalizeBotRoutePath(idx >= 0 ? body.slice(0, idx) : body);
  const search = idx >= 0 ? body.slice(idx) : "";
  return { path, search, params: safeBotRouteSearchParams(search) };
}

function getFirstBotAuthorizeParam(paramSets = [], key = "") {
  for (const entry of paramSets) {
    const params = entry?.params;
    if (!params || typeof params.has !== "function" || !params.has(key)) continue;
    const value = String(params.get(key) || "").trim();
    if (value) return value;
  }
  return "";
}

function readBotAuthorizeInviteFromLocation() {
  const paramSets = [];
  const pushParams = (params, source) => {
    if (!params || typeof params.get !== "function") return;
    paramSets.push({ params, source });
  };
  pushParams(safeBotRouteSearchParams(window.location?.search || ""), "search");
  const hashParts = getBotHashRouteParts(window.location?.hash || "");
  pushParams(hashParts.params, "hash");
  try {
    const url = new URL(String(window.location?.href || ""), String(window.location?.origin || "http://localhost"));
    pushParams(url.searchParams, "href-search");
    const hrefHashParts = getBotHashRouteParts(url.hash || "");
    pushParams(hrefHashParts.params, "href-hash");
  } catch (_) {}
  const selected = paramSets.find((entry) => String(entry?.params?.get("client_id") || "").trim()) || paramSets[0] || { params: new URLSearchParams(), source: "none" };
  const rawClientId = String(selected.params.get("client_id") || "").trim();
  const parsedClientId = isValidAltaraUuid(rawClientId) ? rawClientId.toLowerCase() : "";
  const rawScope = getFirstBotAuthorizeParam(paramSets, "scope") || ALTARA_BOT_PHASE1_SCOPES.join(" ");
  const rawPermissions = getFirstBotAuthorizeParam(paramSets, "permissions");
  const permissionInput = rawPermissions || ALTARA_BOT_DEFAULT_PERMISSIONS;
  const parsedPermissions = parseBotPermissionList(permissionInput);
  return {
    params: selected.params,
    source: selected.source || "none",
    rawClientId,
    parsedClientId,
    clientIdValid: !!parsedClientId,
    scopes: normalizeBotScopeList(rawScope),
    permissions: parsedPermissions.permissions,
    unknownPermissions: parsedPermissions.unknown,
    permissionSource: parsedPermissions.source || (rawPermissions ? "named" : "default"),
    rawScope,
    rawPermissions,
    buildId: ALTARA_BOTS_BUILD_ID,
  };}

function readBotAuthorizeInviteFromUrl(inviteUrl = "") {
  const paramSets = [];
  const pushParams = (params, source) => {
    if (!params || typeof params.get !== "function") return;
    paramSets.push({ params, source });
  };
  try {
    const parsed = new URL(String(inviteUrl || ""), getBotAuthorizeOrigin());
    pushParams(parsed.searchParams, "invite-search");
    const hashParts = getBotHashRouteParts(parsed.hash || "");
    pushParams(hashParts.params, "invite-hash");
  } catch (_) {}
  const selected = paramSets.find((entry) => String(entry?.params?.get("client_id") || "").trim()) || paramSets[0] || { params: new URLSearchParams(), source: "none" };
  const rawClientId = String(selected.params.get("client_id") || "").trim();
  const parsedClientId = isValidAltaraUuid(rawClientId) ? rawClientId.toLowerCase() : "";
  const rawScope = getFirstBotAuthorizeParam(paramSets, "scope") || ALTARA_BOT_PHASE1_SCOPES.join(" ");
  const rawPermissions = getFirstBotAuthorizeParam(paramSets, "permissions");
  const permissionInput = rawPermissions || ALTARA_BOT_DEFAULT_PERMISSIONS;
  const parsedPermissions = parseBotPermissionList(permissionInput);
  return {
    params: selected.params,
    source: selected.source || "none",
    rawClientId,
    parsedClientId,
    clientIdValid: !!parsedClientId,
    scopes: normalizeBotScopeList(rawScope),
    permissions: parsedPermissions.permissions,
    unknownPermissions: parsedPermissions.unknown,
    permissionSource: parsedPermissions.source || (rawPermissions ? "named" : "default"),
    rawScope,
    rawPermissions,
    buildId: ALTARA_BOTS_BUILD_ID,
  };
}

async function openBotAuthorizeUrlInApp(inviteUrl = "") {
  const safeUrl = String(inviteUrl || "").trim();
  if (!safeUrl || !state.user?.id || !isAltaraDeveloperPlatformRoutesEnabled()) return false;
  const invite = readBotAuthorizeInviteFromUrl(safeUrl);
  if (!invite.clientIdValid) return false;
  const route = {
    kind: "authorize",
    section: "authorize",
    appId: invite.parsedClientId,
    path: "/oauth2/authorize",
    params: invite.params,
    invite,
    inAppOverlay: true,
  };
  botRouteActive = route;
  closeProfileOverlay();
  closeBotProfileCard();
  closeBotContextMenu();
  setBotRouteLoading("Loading authorization...");
  await loadBotAuthorizeState(route);
  const activeSid = normId(getActiveServerContext?.()?.serverId || state.activeDm?.serverId || "");
  if (activeSid && botAuthorizeState && !botAuthorizeState.success) {
    const adminServers = getDeveloperPortalAdminServers();
    const activeServer = adminServers.find((server) => server.id === activeSid) || null;
    if (activeServer) {
      botAuthorizeState = { ...botAuthorizeState, serverId: activeSid, serverName: activeServer.name || "" };
      await refreshBotAuthorizeInstallStateForServer(activeSid, { render: false, force: false }).catch(() => null);
    }
  }  renderBotRouteOverlay(route);
  return true;
}

async function openBotAuthorizeUrlInAppOrBrowser(inviteUrl = "") {
  const openedInApp = await openBotAuthorizeUrlInApp(inviteUrl).catch(() => false);
  if (openedInApp) return true;
  await openBotAuthorizeUrlInBrowser(inviteUrl);
  return true;
}
function isBotAuthorizeDebugAllowed() {
  const protocol = String(window.location?.protocol || "").toLowerCase();
  const host = String(window.location?.hostname || "").trim().toLowerCase();
  return protocol === "file:" || host === "localhost" || host === "127.0.0.1" || host === "::1";
}

function exposeBotAuthorizeDebugHelper() {
  try {
    if (!isBotAuthorizeDebugAllowed()) {
      try { delete window.ALTARA_AUTHORIZE_DEBUG; delete window.__ALTARA_AUTHORIZE_DEBUG__; delete window.__ALTARA_DEBUG_BOT_PERMISSION_UPDATE__; } catch (_) { window.ALTARA_AUTHORIZE_DEBUG = undefined; window.__ALTARA_AUTHORIZE_DEBUG__ = undefined; window.__ALTARA_DEBUG_BOT_PERMISSION_UPDATE__ = undefined; }
      return;
    }
    const debugFn = function altaraAuthorizeDebug() {
      const parsed = readBotAuthorizeInviteFromLocation();
      return {
        buildId: ALTARA_BOTS_BUILD_ID,
        href: String(window.location?.href || ""),
        pathname: String(window.location?.pathname || ""),
        search: String(window.location?.search || ""),
        hash: String(window.location?.hash || ""),
        parsedClientId: parsed.parsedClientId || null,
        parsedScopes: parsed.scopes || [],
        parsedPermissions: parsed.permissions || [],
        permissionSource: parsed.permissionSource || null,
        unknownPermissions: parsed.unknownPermissions || [],
        selectedServerId: normId(document.getElementById("botAuthorizeServer")?.value || botAuthorizeState?.serverId || "") || null,
      };
    };
    const permissionUpdateDebugFn = function altaraBotPermissionUpdateDebug() {
      try {
        const st = botAuthorizeState || {};
        const sid = normId(document.getElementById("botAuthorizeServer")?.value || st.serverId || "");
        const seed = getBotAuthorizeInstallSeed(st);
        const installed = sid ? findServerInstalledBot(sid, seed) : null;
        const currentPermissions = normalizeBotPermissionList(st.existingInstallPermissions || installed?.permissions || installed?.botPermissions || []);
        const requestedPermissions = normalizeBotPermissionList(st.permissions || []);
        const diff = getBotPermissionDiff(currentPermissions, requestedPermissions);
        return {
          activeAppId: normId(st.appId || st.app?.app_id || "") || null,
          activeBotId: normId(st.app?.bot_id || seed.botId || "") || null,
          activeServerId: sid || null,
          currentPermissions,
          requestedPermissions,
          addedPermissions: diff.added,
          removedPermissions: diff.removed,
          lastAuthorizeUrl: botPermissionUpdateDebugState.lastAuthorizeUrl || "",
          inFlight: botPermissionUpdateInFlight === true || botPermissionUpdateDebugState.inFlight === true,
          lastError: botPermissionUpdateDebugState.lastError,
          lastRpcResponse: botPermissionUpdateDebugState.lastRpcResponse,
          lastEvent: botPermissionUpdateDebugState.lastEvent,
        };
      } catch (error) {
        return {
          activeAppId: null,
          activeBotId: null,
          activeServerId: null,
          currentPermissions: [],
          requestedPermissions: [],
          addedPermissions: [],
          removedPermissions: [],
          lastAuthorizeUrl: botPermissionUpdateDebugState.lastAuthorizeUrl || "",
          inFlight: botPermissionUpdateInFlight === true || botPermissionUpdateDebugState.inFlight === true,
          lastError: botPermissionUpdateDebugState.lastError || { message: String(error?.message || error || "debug unavailable") },
          lastRpcResponse: botPermissionUpdateDebugState.lastRpcResponse,
          lastEvent: botPermissionUpdateDebugState.lastEvent,
        };
      }
    };
    window.ALTARA_AUTHORIZE_DEBUG = debugFn;
    window.__ALTARA_AUTHORIZE_DEBUG__ = debugFn;
    window.__ALTARA_DEBUG_BOT_PERMISSION_UPDATE__ = permissionUpdateDebugFn;
    if (!window.__ALTARA_AUTHORIZE_DEBUG_BUILD_LOGGED__) {
      window.__ALTARA_AUTHORIZE_DEBUG_BUILD_LOGGED__ = true;
      try { console.info(`[ALTARA Bots] authorize build ${ALTARA_BOTS_BUILD_ID}`); } catch (_) {}
    }
  } catch (_) {}
}
function isWebsiteDeveloperPortalRoutePath(path = "") {
  const normalized = normalizeBotRoutePath(path || "/");
  return normalized === "/developers" || normalized.startsWith("/developers/");
}

function buildDeveloperPortalWebsiteHandoffHtml(path = "/developers") {
  const routePath = isWebsiteDeveloperPortalRoutePath(path) ? path : "/developers";
  const externalUrl = buildWebsiteDeveloperPortalUrl(routePath);
  return `
    <section class="botAuthorizeCard botAuthorizeCard--loading">
      <div>
        <h2 id="botRouteTitle">Open Developer Portal</h2>
        <p>Developer configuration now lives on the ALTARA website, not inside the chat app.</p>
        <div class="settingsDeveloperActions">
          <button class="btn primary" type="button" data-dev-action="open-website-developer-portal">Open Developer Portal</button>
          <a class="btn ghost" href="${escAttr(externalUrl)}" target="_blank" rel="noopener noreferrer">Open in browser</a>
        </div>
      </div>
    </section>
  `;
}

function parseBotRouteFromLocation() {
  let path = normalizeBotRoutePath(window.location?.pathname || "/");
  let search = String(window.location?.search || "");
  const hashParts = getBotHashRouteParts(window.location?.hash || "");
  if (hashParts.path) {
    path = hashParts.path;
    search = hashParts.search || search;
  }
  const params = safeBotRouteSearchParams(search);
  if (isWebsiteDeveloperPortalRoutePath(path)) return { kind: "developers-external", section: "external", appId: "", path, params };
  if (path === "/oauth2/authorize") {
    const invite = readBotAuthorizeInviteFromLocation();
    return { kind: "authorize", section: "authorize", appId: invite.parsedClientId, path, params: invite.params, invite };
  }
  return null;
}
function navigateBotRoute(path = "") {
  const nextPath = String(path || "/developers/applications").trim() || "/developers/applications";
  const protocol = String(window.location?.protocol || "").toLowerCase();
  if (protocol === "http:" || protocol === "https:") window.history?.pushState?.({}, "", nextPath);
  else window.location.hash = `#${nextPath}`;
  void handleBotRouteFromLocation({ source: "navigate" });
}

function closeBotRouteOverlay({ updateUrl = true } = {}) {
  const activeRoute = botRouteActive || null;
  const overlay = document.getElementById("botRouteOverlay");
  if (overlay) {
    overlay.classList.add("hidden");
    overlay.setAttribute("aria-hidden", "true");
  }
  botRouteActive = null;
  if (updateUrl && !activeRoute?.inAppOverlay) {
    const protocol = String(window.location?.protocol || "").toLowerCase();
    if (protocol === "http:" || protocol === "https:") window.history?.pushState?.({}, "", "/");
    else if (String(window.location.hash || "").startsWith("#/")) window.location.hash = "";
  }
}
function setBotRouteLoading(message = "Loading...") {
  const overlay = document.getElementById("botRouteOverlay");
  const root = document.getElementById("botRouteRoot");
  const sidebar = document.getElementById("botRouteSidebar");
  const shell = overlay?.querySelector?.(".botRouteShell");
  const isAuthorize = botRouteActive?.kind === "authorize";
  if (!overlay || !root) return;
  overlay.classList.remove("hidden");
  overlay.setAttribute("aria-hidden", "false");
  shell?.classList.toggle("botRouteShell--authorize", !!isAuthorize);
  if (sidebar) sidebar.innerHTML = isAuthorize ? "" : `<div class="botRouteBrand"><b>ALTARA</b><span>Developer Portal</span></div>`;
  root.innerHTML = isAuthorize
    ? `<section class="botAuthorizeCard botAuthorizeCard--loading"><div class="botAuthorizeSpinner" aria-hidden="true"></div><div><h2 id="botRouteTitle">${esc(message)}</h2><p>Preparing this ALTARA bot invite.</p></div></section>`
    : `<div class="botRouteLoading">${esc(message)}</div>`;
}
async function handleBotRouteFromLocation({ source = "location" } = {}) {
  const route = parseBotRouteFromLocation();
  if (!route) return false;
  if (route.kind === "developers-external") {
    await openWebsiteDeveloperPortal(route.path || "/developers");
    return true;
  }
  botRouteActive = route;
  closeProfileOverlay();
  setBotRouteLoading(route.kind === "authorize" ? "Loading authorization..." : "Loading Developer Portal...");
  try {
    if (route.kind === "authorize") {
      await loadBotAuthorizeState(route);
    }
  } catch (error) {
    console.warn("bot route load failed", source, error?.message || error);
  }
  renderBotRouteOverlay(route);
  return true;
}

function bindBotRouteOverlayOnce() {
  if (!isAltaraDeveloperPlatformRoutesEnabled()) return;
  if (botRouteOverlayBound) return;
  botRouteOverlayBound = true;
  window.addEventListener("popstate", () => { void handleBotRouteFromLocation({ source: "popstate" }); });
  window.addEventListener("hashchange", () => { void handleBotRouteFromLocation({ source: "hashchange" }); });
  document.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    const routeBtn = target.closest?.("[data-bot-route]");
    if (routeBtn) {
      event.preventDefault();
      const routePath = routeBtn.getAttribute("data-bot-route") || "/developers/applications";
      if (isWebsiteDeveloperPortalRoutePath(routePath)) {
        void openWebsiteDeveloperPortal(routePath);
      } else {
        navigateBotRoute(routePath);
      }
      return;
    }
    const closeBtn = target.closest?.("[data-bot-route-close]");
    if (closeBtn) {
      event.preventDefault();
      closeBotRouteOverlay();
    }
  });
  const root = document.getElementById("botRouteRoot");
  root?.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    const actionBtn = target.closest?.("[data-dev-action]");
    if (actionBtn) {
      event.preventDefault();
      void handleDeveloperPortalAction(actionBtn.getAttribute("data-dev-action") || "open-website-developer-portal");
      return;
    }
    const openAltaraBtn = target.closest?.("[data-bot-open-altara]");
    if (openAltaraBtn) {
      event.preventDefault();
      void openAltaraAfterBotAuthorization(openAltaraBtn.getAttribute("data-bot-open-altara") || "");
      return;
    }
    const authorizeBtn = target.closest?.("[data-bot-authorize]");
    if (authorizeBtn) {
      event.preventDefault();
      event.stopPropagation?.();
      if (authorizeBtn.disabled || botPermissionUpdateInFlight) {
        logBotPermissionUpdateEvent("duplicate_authorize_suppressed", { phase: "duplicate_authorize_suppressed", inFlight: botPermissionUpdateInFlight });
        return;
      }
      void submitBotAuthorization();
      return;
    }
  });
  root?.addEventListener("change", (event) => {
    const target = eventTargetElement(event);
    if (!target || !target.matches?.("#botAuthorizeServer")) return;
    const serverId = normId(target.value || "");
    void refreshBotAuthorizeInstallStateForServer(serverId, { render: true, force: false });
  });
}

function renderBotRouteOverlay(route = botRouteActive) {
  if (!route) return;
  const overlay = document.getElementById("botRouteOverlay");
  const sidebar = document.getElementById("botRouteSidebar");
  const root = document.getElementById("botRouteRoot");
  const shell = overlay?.querySelector?.(".botRouteShell");
  if (!overlay || !root || !sidebar) return;
  overlay.classList.remove("hidden");
  overlay.setAttribute("aria-hidden", "false");
  shell?.classList.toggle("botRouteShell--authorize", route.kind === "authorize");
  if (route.kind === "authorize") {
    sidebar.innerHTML = "";
    root.innerHTML = buildBotAuthorizeHtml();
    exposeBotAuthorizeDebugHelper();
    return;
  }
  sidebar.innerHTML = "";
  root.innerHTML = buildDeveloperPortalWebsiteHandoffHtml(route?.path || "/developers");
}
function buildDeveloperRouteSidebarHtml(route) {
  const appId = normId(route?.appId || settingsDeveloperSelectedAppId || getSelectedDeveloperApp()?.app_id || "");
  const appBase = appId ? `/developers/applications/${appId}` : "/developers/applications";
  const item = (label, path, active) => `<button class="botRouteNavItem${active ? " is-active" : ""}" type="button" data-bot-route="${escAttr(path)}">${esc(label)}</button>`;
  return `
    <div class="botRouteBrand"><b>ALTARA</b><span>Developer Portal</span></div>
    <nav class="botRouteNav" aria-label="Developer navigation">
      ${item("Applications", "/developers/applications", route?.section === "applications")}
      ${appId ? item("General Information", `${appBase}/general`, route?.section === "general") : ""}
      ${appId ? item("Bot", `${appBase}/bot`, route?.section === "bot") : ""}
      ${appId ? item("Installation / OAuth2", `${appBase}/installation`, route?.section === "installation") : ""}
      ${appId ? item("Bot Permissions", `${appBase}/permissions`, route?.section === "permissions") : ""}
      ${appId ? item("Commands", `${appBase}/commands`, route?.section === "commands") : ""}
      ${appId ? item("Code / Quickstart", `${appBase}/code`, route?.section === "code") : ""}
      ${appId ? item("Hosting", `${appBase}/hosting`, route?.section === "hosting") : ""}
      ${appId ? item("Advanced Webhook Mode", `${appBase}/interactions`, route?.section === "interactions") : ""}
      ${appId ? item("Logs", `${appBase}/logs`, route?.section === "logs") : ""}
      ${item("Docs", "/developers/docs", route?.section === "docs")}
    </nav>
    <button class="botRouteClose" type="button" data-bot-route-close>Back to ALTARA</button>
  `;
}
function buildDeveloperRouteHeaderHtml(title, subtitle = "") {
  return `<div class="botRouteHeader"><div><div id="botRouteTitle" class="botRouteTitle">${esc(title)}</div><div class="botRouteSubtitle">${esc(subtitle)}</div></div></div>`;
}

function buildDeveloperRouteStatusHtml() {
  return settingsDeveloperStatusText
    ? `<div class="settingsDeveloperStatus" data-tone="${escAttr(settingsDeveloperStatusTone)}">${esc(settingsDeveloperStatusText)}</div>`
    : "";
}

function buildDeveloperRouteHtml(route) {
  if (route.section === "applications") return buildDeveloperApplicationsHtml();
  if (route.section === "docs") return buildDeveloperDocsHtml(route.doc || "overview");
  const app = getDeveloperAppById(route.appId || settingsDeveloperSelectedAppId || "");
  if (!app) return `${buildDeveloperRouteHeaderHtml("Application not found", "Create an application or choose one from the list.")}${buildDeveloperRouteStatusHtml()}<button class="btn primary" type="button" data-bot-route="/developers/applications">View Applications</button>`;
  if (route.section === "bot") return buildDeveloperBotHtml(app);
  if (route.section === "code") return buildDeveloperCodeHtml(app);
  if (route.section === "installation") return buildDeveloperInstallationHtml(app);
  if (route.section === "permissions") return buildDeveloperPermissionsHtml(app);
  if (route.section === "commands") return buildDeveloperCommandsHtml(app);
  if (route.section === "hosting") return buildDeveloperHostingHtml(app);
  if (route.section === "interactions") return buildDeveloperInteractionsHtml(app);
  if (route.section === "logs") return buildDeveloperLogsHtml(app);
  return buildDeveloperGeneralHtml(app);
}
