function getDeveloperBotConnectionStatusMeta(bot = {}) {
  const lastSeenTs = Date.parse(String(bot?.lastUsedAt || ""));
  const revoked = !!String(bot?.revokedAt || "").trim() || String(bot?.status || "").trim().toLowerCase() === "revoked";
  const online = !revoked && Number.isFinite(lastSeenTs) && (Date.now() - lastSeenTs) <= 120000;
  return {
    label: online ? "Online" : "Offline",
    tone: online ? "success" : (revoked ? "error" : "muted"),
    lastSeen: Number.isFinite(lastSeenTs) ? formatDeveloperDate(bot.lastUsedAt) : "Never",
  };
}

