    '  token: process.env.ALTARA_BOT_TOKEN,',
    '});',
    '',
    'bot.command("ola-mundo", {',
    '  description: "Primeiro comando do bot",',
    '}, async (ctx) => {',
    '  await ctx.reply("Ol� mundo!");',
    '});',
    '',
