function getDeveloperCommandOptionsExample() {
  return JSON.stringify([
    { name: "text", description: "Text to send to your bot", type: "STRING", required: false },
  ], null, 2);
}

function normalizeDeveloperCommandOptionType(value = "") {
  const raw = String(value || "").trim().toUpperCase();
  const allowed = new Set(["STRING", "INTEGER", "BOOLEAN", "NUMBER", "USER", "CHANNEL", "ROLE"]);
  return allowed.has(raw) ? raw : "STRING";
}

function parseDeveloperCommandOptionsInput(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return [];
  let parsed;
  try { parsed = JSON.parse(raw); } catch (_) { throw new Error("Command options must be valid JSON."); }
  if (!Array.isArray(parsed)) throw new Error("Command options must be a JSON array.");
  return parsed.slice(0, 25).map((item, idx) => normalizeDeveloperCommandOptionRecord(item, idx));
}

function normalizeDeveloperCommandOptionRecord(item = {}, idx = 0) {
  if (!item || typeof item !== "object" || Array.isArray(item)) throw new Error(`Command option ${idx + 1} must be an object.`);
  const name = normalizeDeveloperPortalText(item.name || "", 32).toLowerCase().replace(/^\//, "");
  const description = normalizeDeveloperPortalText(item.description || "", 120);
  if (!/^[a-z0-9_-]{1,32}$/.test(name)) throw new Error(`Command option ${idx + 1} has an invalid name.`);
  if (!description) throw new Error(`Command option ${idx + 1} needs a description.`);
  const option = {
    name,
    description,
    type: normalizeDeveloperCommandOptionType(item.type || item.option_type || "STRING"),
    required: item.required === true,
  };
  if (Array.isArray(item.choices)) {
    option.choices = item.choices.slice(0, 25).map((choice) => ({
      name: normalizeDeveloperPortalText(choice?.name || choice?.label || choice?.value || "", 80),
      value: String(choice?.value ?? choice?.name ?? "").slice(0, 100),
    })).filter((choice) => choice.name && choice.value);
  }
  return option;
}

function readDeveloperCommandOptionsFromForm() {
  const jsonValue = String(document.getElementById("developerCommandOptions")?.value || "").trim();
  if (jsonValue) return parseDeveloperCommandOptionsInput(jsonValue);
  const optionName = normalizeDeveloperPortalText(document.getElementById("developerCommandOptionName")?.value || "", 32).toLowerCase().replace(/^\//, "");
  if (!optionName) return [];
  const choicesRaw = String(document.getElementById("developerCommandOptionChoices")?.value || "").trim();
  const choices = choicesRaw
    ? choicesRaw.split(",").map((item) => {
        const value = normalizeDeveloperPortalText(item || "", 100);
        return value ? { name: value, value } : null;
      }).filter(Boolean)
    : [];
  return [normalizeDeveloperCommandOptionRecord({
    name: optionName,
    description: document.getElementById("developerCommandOptionDescription")?.value || `${optionName} option`,
    type: document.getElementById("developerCommandOptionType")?.value || "STRING",
    required: document.getElementById("developerCommandOptionRequired")?.checked === true,
    choices,
  }, 0)];
}

function getDeveloperCommandOptionsArray(cmd = {}) {
  return Array.isArray(cmd?.options) ? cmd.options : [];
}

function buildDeveloperCommandRowsHtml() {
  const rows = (settingsDeveloperCommands || []).map((cmd) => {
    const options = getDeveloperCommandOptionsArray(cmd);
    const callback = String(cmd?.callback_url || "").trim();
    return `
      <div class="settingsDeveloperCommandRow">
        <div>
          <b>/${esc(cmd?.name || "command")}</b>
          <small>${esc(cmd?.description || "No description")}</small>
          <small>${esc(options.length ? `${options.length} option${options.length === 1 ? "" : "s"}` : "No options")} � ${esc(cmd?.server_id ? "Server command" : "Available where installed")}</small>
        </div>
        <span>${callback ? "Advanced webhook callback" : "Synced from code"}</span>
        <button class="btn ghost danger" type="button" data-dev-delete-command="${escAttr(normId(cmd?.command_id || ""))}">Disable</button>
      </div>
    `;
  }).join("");
  return rows || '<div class="settingsDeveloperEmpty">No commands registered.</div>';
}

