function getDeveloperInteractionStatusMeta(app = {}, endpointValue = "") {
  const endpoint = String(endpointValue || "").trim();
  const status = String(app?.interaction_endpoint_verification_status || "").trim().toLowerCase();
  const error = String(app?.last_interaction_error || "").trim();
  const verifiedAt = String(app?.interaction_endpoint_verified_at || "").trim();
  if (!endpoint) return { label: "Not configured", tone: "muted", detail: "No webhook endpoint configured. This is fine for Bot Token Connection mode." };
  if (status === "verified" || verifiedAt) return { label: "Verified", tone: "success", detail: "ALTARA received a valid PONG challenge response." };
  if (status === "failed" || error) return { label: "Last test failed", tone: "error", detail: getFriendlyInteractionEndpointErrorMessage(null, error || "invalid_response") };
  return { label: "Not verified", tone: "warning", detail: "Save the endpoint, then test it with a signed PING challenge." };
}

function buildDeveloperInteractionsHtml(app) {
  const bot = getSelectedDeveloperBot();
  if (!bot) return `${buildDeveloperRouteHeaderHtml("Advanced Webhook Mode", "Create a bot before configuring optional webhook delivery.")}${buildDeveloperRouteStatusHtml()}<button class="btn primary" type="button" data-bot-route="/developers/applications/${escAttr(normId(app?.app_id || ""))}/bot">Create Bot</button>`;
  const appEndpoint = String(app?.interaction_endpoint_url || "").trim();
  const commandWithCallback = (settingsDeveloperCommands || []).find((cmd) => String(cmd?.callback_url || "").trim());
  const callbackUrl = String(commandWithCallback?.callback_url || "").trim();
  const endpointValue = appEndpoint || callbackUrl;
  const statusMeta = getDeveloperInteractionStatusMeta(app, endpointValue);
  const lastChecked = formatDeveloperDate(app?.interaction_endpoint_last_checked_at || "");
  const lastError = String(app?.last_interaction_error || "none").trim();
  const payload = {
    type: "PING",
    application_id: normId(app?.app_id || ""),
    bot_id: normId(bot?.id || ""),
    challenge: "<random_string>",
    timestamp: "<iso_timestamp>",
  };
  const pong = {
    type: "PONG",
    challenge: "<same_random_string>",
  };
  return `
    ${buildDeveloperRouteHeaderHtml("Advanced Webhook Mode", "Optional inbound HTTPS delivery for serverless webhook bots.")}
    ${buildDeveloperRouteStatusHtml()}
    <section class="botRoutePanel botInteractionPanel">
      <div class="botInstallWarning">Most bots do not need this. Use Bot Token Connection mode unless you are building a serverless webhook bot.</div>
      <div class="settingsDeveloperBotMeta"><span>Default mode: <code>Bot Token Connection</code></span><span>Advanced mode: public HTTPS endpoint with <code>/altara/interactions</code></span></div>
      <div class="settingsDeveloperBlockHead"><div><b>Interaction Endpoint URL</b><small>Only for Advanced Webhook Mode.</small></div></div>
      <label>Endpoint URL<input id="developerInteractionEndpoint" class="input" maxlength="500" placeholder="https://example.com/altara/interactions" value="${escAttr(endpointValue)}" /></label>
      <div class="botInteractionStatusRow">
        <span class="botInteractionStatusBadge" data-tone="${escAttr(statusMeta.tone)}">${esc(statusMeta.label)}</span>
        <span>Signing secret prefix: <code>${esc(app?.signing_secret_prefix || "not generated")}</code></span>
        <span>Last tested: <code>${esc(lastChecked)}</code></span>
      </div>
      <div class="botInteractionStatusDetail">${esc(statusMeta.detail)}</div>
      <div class="settingsDeveloperBotMeta"><span>Last error: <code>${esc(lastError)}</code></span><span>Secrets are never exposed here.</span></div>
      <div class="settingsDeveloperActions"><button class="btn ghost" type="button" data-dev-action="save-interaction-endpoint">Save endpoint</button><button class="btn primary" type="button" data-dev-action="test-interaction">Test endpoint</button><button class="btn ghost" type="button" data-dev-action="rotate-signing-secret">Rotate signing secret</button></div>
    </section>
    <section class="botRoutePanel botInteractionPanel">
      <div class="settingsDeveloperBlockHead"><div><b>Advanced webhook verification payload</b><small>ALTARA sends this signed JSON body only when testing a webhook endpoint.</small></div></div>
      ${buildDeveloperDocsCodeBlockHtml("PING challenge", JSON.stringify(payload, null, 2))}
    </section>
    <section class="botRoutePanel botInteractionPanel">
      <div class="settingsDeveloperBlockHead"><div><b>Expected response</b><small>Your bot must return PONG with the exact same challenge.</small></div></div>
      ${buildDeveloperDocsCodeBlockHtml("PONG response", JSON.stringify(pong, null, 2))}
      <div class="botInstallWarning">Verify <code>X-Altara-Timestamp</code>, <code>X-Altara-Signature</code>, and <code>X-Altara-Event-Id</code> with your signing secret. Never put tokens in frontend code.</div>
    </section>
  `;
}
