function getOwnerReportTargetStateLabel(stateInput = null) {
  const info = stateInput && typeof stateInput === "object" ? stateInput : null;
  if (info?.isBanned) return t("settings.reports.target_state.banned", "Banned");
  return t("settings.reports.target_state.active", "Active");
}

function buildOwnerReportModerationHistoryHtml(actionsInput = []) {
  const actions = Array.isArray(actionsInput) ? actionsInput.filter(Boolean) : [];
  if (!actions.length) {
    return `<div class="settingsPlaceholder">${esc(t("settings.reports.moderation.history.empty", "No moderation actions recorded for this report yet."))}</div>`;
  }

  return `
    <div class="settingsReportsModerationHistory">
      ${actions.map((action) => {
        const createdLabel = formatOwnerReportTimestamp(action?.createdAt);
        const label = getOwnerModerationActionTypeLabel(action?.actionType);
        const reasonText = String(action?.reason || action?.reportReason || "").trim();
        const respondedLabel = formatOwnerReportTimestamp(action?.respondedAt || "");
        const isRequestExplanation = action?.actionType === "request_explanation";
        return `
          <div class="settingsReportsModerationHistoryItem">
            <div class="settingsReportsModerationHistoryTop">
              <b>${esc(label)}</b>
              <span>${esc(createdLabel || "—")}</span>
            </div>
            ${reasonText ? `
              <div class="settingsReportsModerationHistoryMeta">${esc(
                isRequestExplanation
                  ? t("settings.reports.moderation.request_message", "Moderation request")
                  : t("settings.reports.reason", "Reason")
              )}</div>
              <div class="settingsReportsModerationHistoryText">${esc(reasonText)}</div>
            ` : ""}
            ${action?.responseText ? `
              <div class="settingsReportsModerationResponseCard">
                <div class="settingsReportsModerationResponseTop">
                  <b>${esc(t("settings.reports.moderation.reply", "Resposta do utilizador"))}</b>
                  ${respondedLabel ? `<span>${esc(respondedLabel)}</span>` : ""}
                </div>
                <div class="settingsReportsModerationResponseBody">${esc(action.responseText)}</div>
              </div>
            ` : (isRequestExplanation
              ? `<div class="settingsReportsModerationHistoryMeta">${esc(t("settings.reports.moderation.reply_pending", "Waiting for explanation"))}</div>`
              : "")}
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function getSelectedOwnerReport() {
  return settingsOwnerReportsRows.find((row) => row.id === settingsOwnerReportsSelectedId) || null;
}

function renderOwnerReportsSettingsUiFromState() {
  const listEl = document.getElementById("settingsReportsList");
  const detailEl = document.getElementById("settingsReportsDetail");
  if (!listEl || !detailEl) return;
  if (!isCurrentUserOwner()) {
    const ownerOnlyText = esc(t("settings.reports.owner_only", "This panel is only available to the app owner account."));
    listEl.innerHTML = `<div class="settingsPlaceholder">${ownerOnlyText}</div>`;
    detailEl.innerHTML = `<div class="settingsPlaceholder">${ownerOnlyText}</div>`;
    return;
  }

  const rows = Array.isArray(settingsOwnerReportsRows) ? settingsOwnerReportsRows : [];
  if (!rows.length) {
    const emptyText = esc(t("settings.reports.empty", "No reports yet."));
    listEl.innerHTML = `<div class="settingsPlaceholder">${emptyText}</div>`;
    detailEl.innerHTML = `<div class="settingsPlaceholder">${esc(t("settings.reports.select", "Select a report to review."))}</div>`;
    return;
  }

  if (!rows.some((row) => row.id === settingsOwnerReportsSelectedId)) {
    settingsOwnerReportsSelectedId = rows[0]?.id || "";
  }
  const activeId = settingsOwnerReportsSelectedId;

  listEl.innerHTML = rows.map((row) => {
    const targetLabel = row.targetUserId
      ? getOwnerReportUserLabel(row.targetProfile, row.targetUserId)
      : t("settings.reports.target.missing", "No linked target user");
    const reporterLabel = getOwnerReportUserLabel(row.reporterProfile, row.reporterUserId);
    const createdLabel = formatOwnerReportTimestamp(row.createdAt);
    const reasonPreview = row.reason || "—";
    return `
      <button class="settingsReportsItem${row.id === activeId ? " is-active" : ""}" type="button" data-settings-report-open="${escAttr(row.id)}">
        <div class="settingsReportsItemTop">
          <div class="settingsReportsItemTitle">${esc(targetLabel)}</div>
          <span class="settingsReportsStatus settingsReportsStatus--${escAttr(row.status)}">${esc(getReportStatusLabel(row.status))}</span>
        </div>
        <div class="settingsReportsMeta">${esc(`${t("settings.reports.meta.reporter", "Reporter")}: ${reporterLabel}`)}</div>
        <div class="settingsReportsMeta">${esc(createdLabel || "")}</div>
        <div class="settingsReportsReason">${esc(reasonPreview)}</div>
      </button>
    `;
  }).join("");

  const activeRow = getSelectedOwnerReport();
  if (!activeRow) {
    detailEl.innerHTML = `<div class="settingsPlaceholder">${esc(t("settings.reports.select", "Select a report to review."))}</div>`;
    return;
  }

  const targetSummary = activeRow.targetProfile;
  const reporterSummary = activeRow.reporterProfile;
  const targetLabel = activeRow.targetUserId
    ? getOwnerReportUserLabel(targetSummary, activeRow.targetUserId)
    : t("settings.reports.target.missing", "No linked target user");
  const reporterLabel = getOwnerReportUserLabel(reporterSummary, activeRow.reporterUserId);
  const createdLabel = formatOwnerReportTimestamp(activeRow.createdAt);
  const detailLines = [];
  if (activeRow.metadata?.details) detailLines.push(String(activeRow.metadata.details).trim());
  const evidenceHtml = buildOwnerReportEvidenceSectionHtml(activeRow.evidence);
  const targetModerationState = normalizeUserModerationStateRow(activeRow.targetModerationState || {});
  const moderationHistoryHtml = buildOwnerReportModerationHistoryHtml(activeRow.moderationActions || []);
  const targetIsBanned = targetModerationState.isBanned === true;
  const moderationButtonsDisabled = settingsOwnerReportsStatusSaving
    || settingsOwnerReportsModerationSaving
    || !activeRow.targetUserId
    || !settingsOwnerReportsModerationSqlReady;
  const moderationSqlMessage = !settingsOwnerReportsModerationSqlReady
    ? (() => {
        const errText = String(settingsOwnerReportsModerationSqlError?.message || settingsOwnerReportsModerationSqlError || "").trim();
        if (!errText || isModerationSqlMissingError(settingsOwnerReportsModerationSqlError)) {
          return t("settings.reports.moderation.sql_missing", "Moderation actions SQL is missing. Apply the Phase 5.2 patch and reload.");
        }
        return `${t("settings.reports.moderation.sql_missing", "Moderation actions SQL is missing. Apply the Phase 5.2 patch and reload.")} ${errText}`.trim();
      })()
    : "";
  const prettyMetadata = (() => {
    const clone = { ...(activeRow.metadata || {}) };
    if (typeof clone.details !== "undefined" && !clone.details) delete clone.details;
    if (typeof clone.evidence !== "undefined") delete clone.evidence;
    const keys = Object.keys(clone);
    if (!keys.length) return "";
    try {
      return JSON.stringify(clone, null, 2);
    } catch (_) {
      return String(clone);
    }
  })();
  detailEl.innerHTML = `
    <div class="settingsReportsDetailCard">
      <div class="settingsReportsItemTop">
        <div class="settingsReportsItemTitle">${esc(targetLabel)}</div>
        <span class="settingsReportsStatus settingsReportsStatus--${escAttr(activeRow.status)}">${esc(getReportStatusLabel(activeRow.status))}</span>
      </div>
      <div class="settingsHint">${esc(t("settings.reports.hint", "Only context explicitly attached by the reporting user may appear here."))}</div>
      <div class="settingsReportsIdentity">
        <div class="settingsReportsAvatar" aria-hidden="true">${buildOwnerReportAvatarHtml(targetSummary, targetLabel)}</div>
        <div class="settingsReportsIdentityMeta">
          <b>${esc(targetLabel)}</b>
          <small>${esc(activeRow.targetUserId || t("settings.reports.target.missing", "No linked target user"))}</small>
        </div>
      </div>
      <div class="settingsReportsIdentity">
        <div class="settingsReportsAvatar" aria-hidden="true">${buildOwnerReportAvatarHtml(reporterSummary, reporterLabel)}</div>
        <div class="settingsReportsIdentityMeta">
          <b>${esc(reporterLabel)}</b>
          <small>${esc(activeRow.reporterUserId || "")}</small>
        </div>
      </div>
      <div class="settingsReportsKv">
        <div class="settingsReportsKvItem">
          <span>${esc(t("settings.reports.meta.created", "Created"))}</span>
          <b>${esc(createdLabel || "—")}</b>
        </div>
        <div class="settingsReportsKvItem">
          <span>${esc(t("settings.reports.meta.status", "Status"))}</span>
          <b>${esc(getReportStatusLabel(activeRow.status))}</b>
        </div>
        <div class="settingsReportsKvItem">
          <span>${esc(t("settings.reports.meta.reporter_user_id", "Reporter user ID"))}</span>
          <code>${esc(activeRow.reporterUserId || "—")}</code>
        </div>
        <div class="settingsReportsKvItem">
          <span>${esc(t("settings.reports.meta.target_user_id", "Target user ID"))}</span>
          <code>${esc(activeRow.targetUserId || "—")}</code>
        </div>
        <div class="settingsReportsKvItem">
          <span>${esc(t("settings.reports.meta.target_state", "Target standing"))}</span>
          <b>${esc(getOwnerReportTargetStateLabel(targetModerationState))}</b>
        </div>
        <div class="settingsReportsKvItem">
          <span>${esc(t("settings.reports.meta.message_id", "Message ID"))}</span>
          <code>${esc(activeRow.messageId || "—")}</code>
        </div>
        <div class="settingsReportsKvItem">
          <span>${esc(t("settings.reports.meta.conversation_id", "Conversation ID"))}</span>
          <code>${esc(activeRow.conversationId || "—")}</code>
        </div>
      </div>
      <div class="settingsSectionTitle">${esc(t("settings.reports.reason", "Reason"))}</div>
      <div class="settingsReportsReason">${esc(activeRow.reason || "—")}</div>
      ${evidenceHtml}
      ${detailLines.length ? `
        <div class="settingsSectionTitle">${esc(t("settings.reports.additional", "Additional metadata"))}</div>
        <div class="settingsReportsReason">${esc(detailLines.join("\n"))}</div>
      ` : ""}
      <div class="settingsSectionTitle">${esc(t("settings.reports.moderation.title", "Moderation actions"))}</div>
      ${!settingsOwnerReportsModerationSqlReady ? `
        <div class="settingsPlaceholder">${esc(moderationSqlMessage)}</div>
      ` : ""}
      <div class="settingsReportsActionRow">
        <button class="btn ghost" type="button" data-settings-report-moderation="warning" ${moderationButtonsDisabled ? "disabled" : ""}>${esc(t("settings.reports.action.warning", "Send warning"))}</button>
        <button class="btn ghost" type="button" data-settings-report-moderation="request_explanation" ${moderationButtonsDisabled ? "disabled" : ""}>${esc(t("settings.reports.action.request_explanation", "Request explanation"))}</button>
        ${targetIsBanned
          ? `<button class="btn ghost" type="button" data-settings-report-moderation="unban" ${moderationButtonsDisabled ? "disabled" : ""}>${esc(t("settings.reports.action.unban", "Unban user"))}</button>`
          : `<button class="btn danger" type="button" data-settings-report-moderation="ban" ${moderationButtonsDisabled ? "disabled" : ""}>${esc(t("settings.reports.action.ban", "Ban user"))}</button>`}
      </div>
      <div class="settingsSectionTitle">${esc(t("settings.reports.moderation.history", "Action history"))}</div>
      ${moderationHistoryHtml}
      ${prettyMetadata ? `
        <pre class="settingsReportsCode">${esc(prettyMetadata)}</pre>
      ` : ""}
      <div class="settingsReportsActionRow">
        <button class="btn ghost" type="button" data-settings-report-status="reviewed" ${activeRow.status === "reviewed" || settingsOwnerReportsStatusSaving ? "disabled" : ""}>${esc(t("settings.reports.action.reviewed", "Mark as reviewed"))}</button>
        <button class="btn ghost" type="button" data-settings-report-status="actioned" ${activeRow.status === "actioned" || settingsOwnerReportsStatusSaving ? "disabled" : ""}>${esc(t("settings.reports.action.actioned", "Mark as actioned"))}</button>
      </div>
    </div>
  `;
}

function isModerationSqlMissingError(error) {
  return isMissingRpcError(error)
    || isMissingTableError(error, "moderation_actions")
    || isMissingTableError(error, "user_moderation_state");
}

async function fetchOwnerModerationActionsForReports(reportIds = []) {
  const ids = Array.isArray(reportIds) ? reportIds.map((value) => normId(value || "")).filter(Boolean) : [];
  if (!ids.length) return { rows: [], error: null };
  const { data, error } = await supabase
    .from("moderation_actions")
    .select("id, report_id, target_user_id, actor_user_id, action_type, reason, metadata, created_at")
    .in("report_id", ids)
    .order("created_at", { ascending: false })
    .limit(500);
  if (error) return { rows: [], error };
  return {
    rows: (Array.isArray(data) ? data : [])
      .map((row) => normalizeOwnerModerationActionRow(row))
      .filter(Boolean),
    error: null,
  };
}

async function fetchOwnerModerationStatesForUsers(userIds = []) {
  const ids = Array.isArray(userIds) ? userIds.map((value) => normId(value || "")).filter(Boolean) : [];
  if (!ids.length) return { rows: [], error: null };
  const { data, error } = await supabase
    .from("user_moderation_state")
    .select("user_id, is_banned, ban_reason, banned_at, banned_by_user_id, metadata")
    .in("user_id", ids)
    .limit(Math.max(ids.length, 1));
  if (error) return { rows: [], error };
  return {
    rows: (Array.isArray(data) ? data : [])
      .map((row) => normalizeUserModerationStateRow(row))
      .filter((row) => row.userId),
    error: null,
  };
}

async function fetchOwnerReportsForSettings() {
  if (!isCurrentUserOwner()) {
    return { rows: [], error: { message: "owner_only" } };
  }

  const { data, error } = await supabase
    .from("reports")
    .select("id, reporter_user_id, target_user_id, message_id, conversation_id, reason, status, metadata, created_at")
    .order("created_at", { ascending: false })
    .limit(250);

  if (error) return { rows: [], error };

  const rows = (Array.isArray(data) ? data : [])
    .map((row) => normalizeOwnerReportRow(row))
    .filter((row) => row.id);

  settingsOwnerReportsModerationSqlReady = true;
  settingsOwnerReportsModerationSqlError = null;

  if (rows.length) {
    const [moderationActionsRes, moderationStateRes] = await Promise.all([
      fetchOwnerModerationActionsForReports(rows.map((row) => row.id)),
      fetchOwnerModerationStatesForUsers(rows.map((row) => row.targetUserId)),
    ]);

    if (moderationActionsRes?.error || moderationStateRes?.error) {
      settingsOwnerReportsModerationSqlReady = false;
      settingsOwnerReportsModerationSqlError = moderationActionsRes?.error || moderationStateRes?.error || null;
    } else {
      const actionsByReportId = new Map();
      (moderationActionsRes?.rows || []).forEach((row) => {
        const reportId = normId(row?.reportId || "");
        if (!reportId) return;
        if (!actionsByReportId.has(reportId)) actionsByReportId.set(reportId, []);
        actionsByReportId.get(reportId).push(row);
      });
      const stateByUserId = new Map(
        (moderationStateRes?.rows || []).map((row) => [row.userId, row])
      );
      rows.forEach((row) => {
        row.moderationActions = actionsByReportId.get(row.id) || [];
        row.targetModerationState = stateByUserId.get(row.targetUserId) || null;
      });
    }
  }

  const profileIds = Array.from(new Set(rows.flatMap((row) => [row.reporterUserId, row.targetUserId]).filter(Boolean)));
  if (profileIds.length) {
    try {
      await fetchProfilesByIds(profileIds, { includeBio: false, force: false });
    } catch (_) {}
  }

  rows.forEach((row) => {
    row.reporterProfile = buildOwnerReportProfileSummary(row.reporterUserId);
    row.targetProfile = buildOwnerReportProfileSummary(row.targetUserId);
  });

  return { rows, error: null };
}

async function checkOwnerReportsSqlAccess() {
  try {
    const { data, error } = await supabase.rpc("is_reports_owner");
    if (error) return { ok: false, error };
    return { ok: true, isOwner: data === true };
  } catch (error) {
    return { ok: false, error };
  }
}

async function renderOwnerReportsSettingsUi({ force = false } = {}) {
  const listEl = document.getElementById("settingsReportsList");
  const detailEl = document.getElementById("settingsReportsDetail");
  if (!listEl || !detailEl) return;
  if (!force && settingsActiveTab !== "reports") return;
  if (!isCurrentUserOwner()) {
    renderOwnerReportsSettingsUiFromState();
    return;
  }
  if (settingsOwnerReportsLoading) return;

  settingsOwnerReportsLoading = true;
  listEl.innerHTML = `<div class="settingsPlaceholder">${esc(t("settings.reports.loading", "Loading reports..."))}</div>`;
  detailEl.innerHTML = `<div class="settingsPlaceholder">${esc(t("settings.reports.select", "Select a report to review."))}</div>`;
  try {
    const ownerAccess = await checkOwnerReportsSqlAccess();
    if (!ownerAccess.ok) {
      const errorText = isMissingRpcError(ownerAccess.error)
        ? t("settings.reports.error.sql_missing", "Reports owner moderation SQL is missing. Apply the Phase 5 patch and reload.")
        : `${t("settings.reports.error.load", "Could not load reports.")} ${ownerAccess.error?.message || ownerAccess.error || ""}`.trim();
      listEl.innerHTML = `<div class="settingsPlaceholder">${esc(errorText)}</div>`;
      detailEl.innerHTML = `<div class="settingsPlaceholder">${esc(errorText)}</div>`;
      settingsOwnerReportsRows = [];
      settingsOwnerReportsSelectedId = "";
      return;
    }
    if (!ownerAccess.isOwner) {
      const ownerOnlyText = t("settings.reports.owner_only", "This panel is only available to the app owner account.");
      listEl.innerHTML = `<div class="settingsPlaceholder">${esc(ownerOnlyText)}</div>`;
      detailEl.innerHTML = `<div class="settingsPlaceholder">${esc(ownerOnlyText)}</div>`;
      settingsOwnerReportsRows = [];
      settingsOwnerReportsSelectedId = "";
      return;
    }
    const { rows, error } = await fetchOwnerReportsForSettings();
    if (error) {
      const errorText = isMissingTableError(error, "reports")
        ? t("settings.reports.error.sql_missing", "Reports owner moderation SQL is missing. Apply the Phase 5 patch and reload.")
        : `${t("settings.reports.error.load", "Could not load reports.")} ${error.message || error}`;
      listEl.innerHTML = `<div class="settingsPlaceholder">${esc(errorText)}</div>`;
      detailEl.innerHTML = `<div class="settingsPlaceholder">${esc(errorText)}</div>`;
      settingsOwnerReportsRows = [];
      settingsOwnerReportsSelectedId = "";
      return;
    }
    settingsOwnerReportsRows = rows;
    if (!rows.some((row) => row.id === settingsOwnerReportsSelectedId)) {
      settingsOwnerReportsSelectedId = rows[0]?.id || "";
    }
    renderOwnerReportsSettingsUiFromState();
  } finally {
    settingsOwnerReportsLoading = false;
  }
}

async function updateOwnerReportStatusRpc(reportId, statusInput) {
  const reportIdSafe = normId(reportId || "");
  const nextStatus = normalizeReportStatus(statusInput);
  if (!reportIdSafe) return { ok: false, error: "invalid_report_id" };
  if (nextStatus !== "reviewed" && nextStatus !== "actioned") return { ok: false, error: "invalid_status" };
  try {
    const { data, error } = await supabase.rpc("owner_update_report_status", {
      p_report_id: reportIdSafe,
      p_status: nextStatus,
    });
    if (error) return { ok: false, error };
    if (data?.ok === false) return { ok: false, error: data.error || "update_failed" };
    return { ok: true, status: normalizeReportStatus(data?.status || nextStatus) };
  } catch (error) {
    return { ok: false, error };
  }
}

async function updateSelectedOwnerReportStatus(nextStatus) {
  const row = getSelectedOwnerReport();
  if (!row || settingsOwnerReportsStatusSaving) return;
  settingsOwnerReportsStatusSaving = true;
  renderOwnerReportsSettingsUiFromState();
  try {
    const result = await updateOwnerReportStatusRpc(row.id, nextStatus);
    if (!result?.ok) {
      const err = result?.error;
      const message = isMissingRpcError(err)
        ? t("settings.reports.error.sql_missing", "Reports owner moderation SQL is missing. Apply the Phase 5 patch and reload.")
        : `${t("settings.reports.error.update", "Could not update report status.")} ${err?.message || err || ""}`.trim();
      await requestAppAlert(message, {
        title: t("settings.section.reports", "Reports"),
        okText: t("dialog.notice.ok", "OK"),
      });
      return;
    }
    settingsOwnerReportsRows = settingsOwnerReportsRows.map((entry) => (
      entry.id === row.id
        ? { ...entry, status: result.status || normalizeReportStatus(nextStatus) }
        : entry
    ));
    renderOwnerReportsSettingsUiFromState();
  } finally {
    settingsOwnerReportsStatusSaving = false;
    renderOwnerReportsSettingsUiFromState();
  }
}

async function ownerModerateReportRpc(row, actionTypeInput, reasonInput, metadataInput = {}) {
  const reportId = normId(row?.id || "");
  const targetUserId = normId(row?.targetUserId || "");
  const actionType = normalizeOwnerModerationActionType(actionTypeInput);
  const reason = String(reasonInput || "").trim();
  if (!reportId || !targetUserId || !actionType) {
    return { ok: false, error: "invalid_moderation_payload" };
  }
  const metadata = {
    ...(metadataInput && typeof metadataInput === "object" && !Array.isArray(metadataInput) ? metadataInput : {}),
    reporter_user_id: row?.reporterUserId || null,
    message_id: row?.messageId || null,
    conversation_id: row?.conversationId || null,
    report_reason: row?.reason || "",
  };
  try {
    const { data, error } = await supabase.rpc("owner_moderate_report", {
      p_report_id: reportId,
      p_target_user_id: targetUserId,
      p_action_type: actionType,
      p_reason: reason || null,
      p_metadata: metadata,
    });
    if (error) return { ok: false, error };
    if (data?.ok === false) return { ok: false, error: data.error || "moderation_failed" };
    return {
      ok: true,
      actionId: normId(data?.action_id || ""),
      actionType,
      reportStatus: normalizeReportStatus(data?.report_status || "actioned"),
      isBanned: data?.is_banned === true,
      metadata,
    };
  } catch (error) {
    return { ok: false, error };
  }
}

async function respondToModerationActionRpc(actionIdInput, responseInput) {
  const actionId = normId(actionIdInput || "");
  const responseText = String(responseInput || "").trim();
  if (!actionId) return { ok: false, error: "invalid_action_id" };
  if (responseText.length < 2) return { ok: false, error: "response_too_short" };
  try {
    const { data, error } = await supabase.rpc("respond_to_moderation_action", {
      p_action_id: actionId,
      p_response: responseText,
    });
    if (error) return { ok: false, error };
    if (data?.ok === false) return { ok: false, error: data.error || "response_failed" };
    return {
      ok: true,
      respondedAt: String(data?.responded_at || new Date().toISOString()).trim(),
    };
  } catch (error) {
    return { ok: false, error };
  }
}

async function requestOwnerModerationReason(actionTypeInput, row) {
  const actionType = normalizeOwnerModerationActionType(actionTypeInput);
  const defaultValue = String(row?.reason || "").trim();
  if (actionType === "warning") {
    return requestAppPrompt(
      t("moderation.prompt.warning.message", "Write the warning that will be sent to this user."),
      {
        title: t("moderation.prompt.warning.title", "Send warning"),
        defaultValue,
        placeholder: t("moderation.prompt.warning.placeholder", "Explain what behavior must stop..."),
        label: t("moderation.prompt.label", "Message"),
        hint: t("moderation.prompt.hint", "Press Ctrl+Enter to send."),
        requireValue: true,
      }
    );
  }
  if (actionType === "request_explanation") {
    return requestAppPrompt(
      t("moderation.prompt.request.message", "Write what ALTARA moderation wants this user to explain."),
      {
        title: t("moderation.prompt.request.title", "Request explanation"),
        defaultValue,
        placeholder: t("moderation.prompt.request.placeholder", "Ask for an explanation about the reported behavior..."),
        label: t("moderation.prompt.label", "Message"),
        hint: t("moderation.prompt.hint", "Press Ctrl+Enter to send."),
        requireValue: true,
      }
    );
  }
  if (actionType === "ban") {
    return requestAppPrompt(
      t("moderation.prompt.ban.message", "Write the reason that will be attached to this ban."),
      {
        title: t("moderation.prompt.ban.title", "Ban user"),
        defaultValue,
        placeholder: t("moderation.prompt.ban.placeholder", "Explain why this account is being banned..."),
        label: t("moderation.prompt.label", "Message"),
        hint: t("moderation.prompt.hint", "Press Ctrl+Enter to send."),
        requireValue: true,
      }
    );
  }
  if (actionType === "unban") {
    return "";
  }
  return null;
}

async function runSelectedOwnerModerationAction(actionTypeInput) {
  const row = getSelectedOwnerReport();
  const actionType = normalizeOwnerModerationActionType(actionTypeInput);
  if (!row || !actionType || settingsOwnerReportsModerationSaving || !settingsOwnerReportsModerationSqlReady) return;
  if (!row.targetUserId) return;

  const targetLabel = row.targetUserId
    ? getOwnerReportUserLabel(row.targetProfile, row.targetUserId)
    : t("settings.reports.target.missing", "No linked target user");
  const reason = await requestOwnerModerationReason(actionType, row);
  if (reason === null) return;

  if (actionType === "ban") {
    const confirmed = await requestAppConfirm(
      tf("moderation.ban.confirm", { name: targetLabel }, `Ban ${targetLabel} from ALTARA?`),
      {
        title: t("moderation.ban.confirm_title", "Ban user"),
        okText: t("settings.reports.action.ban", "Ban user"),
        cancelText: t("dialog.confirm.cancel", "Cancel"),
        danger: true,
      }
    );
    if (!confirmed) return;
  }
  if (actionType === "unban") {
    const confirmed = await requestAppConfirm(
      tf("moderation.unban.confirm", { name: targetLabel }, `Lift the ALTARA ban for ${targetLabel}?`),
      {
        title: t("moderation.unban.confirm_title", "Unban user"),
        okText: t("settings.reports.action.unban", "Unban user"),
        cancelText: t("dialog.confirm.cancel", "Cancel"),
      }
    );
    if (!confirmed) return;
  }

  settingsOwnerReportsModerationSaving = true;
  renderOwnerReportsSettingsUiFromState();
  try {
    const result = await ownerModerateReportRpc(row, actionType, reason);
    if (!result?.ok) {
      const err = result?.error;
      const message = isModerationSqlMissingError(err)
        ? t("settings.reports.moderation.sql_missing", "Moderation actions SQL is missing. Apply the Phase 5.2 patch and reload.")
        : `${t("moderation.error.action", "Could not save this moderation action.")} ${err?.message || err || ""}`.trim();
      await requestAppAlert(message, {
        title: t("settings.section.reports", "Reports"),
        okText: t("dialog.notice.ok", "OK"),
        danger: true,
      });
      return;
    }

    const createdAt = new Date().toISOString();
    const nextAction = normalizeOwnerModerationActionRow({
      id: result.actionId,
      report_id: row.id,
      target_user_id: row.targetUserId,
      actor_user_id: getCurrentUserOwnerId(),
      action_type: result.actionType,
      reason,
      metadata: result.metadata,
      created_at: createdAt,
    });
    const nextTargetState = actionType === "ban"
      ? normalizeUserModerationStateRow({
          ...(row.targetModerationState || {}),
          user_id: row.targetUserId,
          is_banned: true,
          ban_reason: reason,
          banned_at: createdAt,
          banned_by_user_id: getCurrentUserOwnerId(),
          metadata: {
            ...((row.targetModerationState && typeof row.targetModerationState === "object") ? row.targetModerationState.metadata : {}),
            last_action_id: result.actionId,
            last_action_type: actionType,
          },
        })
      : (actionType === "unban"
        ? normalizeUserModerationStateRow({
            ...(row.targetModerationState || {}),
            user_id: row.targetUserId,
            is_banned: false,
            ban_reason: "",
            banned_at: "",
            banned_by_user_id: "",
            metadata: {
              ...((row.targetModerationState && typeof row.targetModerationState === "object") ? row.targetModerationState.metadata : {}),
              last_action_id: result.actionId,
              last_action_type: actionType,
              unbanned_at: createdAt,
              unbanned_by_user_id: getCurrentUserOwnerId(),
            },
          })
        : null);

    settingsOwnerReportsRows = settingsOwnerReportsRows.map((entry) => (
      (entry.id === row.id || entry.targetUserId === row.targetUserId)
        ? {
            ...entry,
            ...(entry.id === row.id
              ? {
                  status: result.reportStatus || "actioned",
                  moderationActions: nextAction ? [nextAction, ...(Array.isArray(entry.moderationActions) ? entry.moderationActions : [])] : (entry.moderationActions || []),
                }
              : {}),
            ...(nextTargetState && entry.targetUserId === row.targetUserId
              ? { targetModerationState: nextTargetState }
              : {}),
          }
        : entry
    ));
    renderOwnerReportsSettingsUiFromState();
  } finally {
    settingsOwnerReportsModerationSaving = false;
    renderOwnerReportsSettingsUiFromState();
  }
}

async function listMyModerationActionsRpc(limit = 25) {
  try {
    const { data, error } = await rpcWithTimeout(
      "list_my_moderation_actions",
      { p_limit: Math.max(1, Number(limit) || 25) },
      RPC_SOFT_TIMEOUT_MS
    );
    if (error) return { rows: [], error };
    return {
      rows: (Array.isArray(data) ? data : [])
        .map((row) => normalizeOwnerModerationActionRow(row))
        .filter(Boolean),
      error: null,
    };
  } catch (error) {
    return { rows: [], error };
  }
}

async function getMyModerationStateRpc(timeoutMs = RPC_SOFT_TIMEOUT_MS) {
  try {
    const { data, error } = await rpcWithTimeout(
      "get_my_moderation_state",
      {},
      timeoutMs
    );
    if (error) return { state: normalizeUserModerationStateRow({}), error };
    return {
      state: normalizeMyModerationStatePayload(data),
      error: null,
    };
  } catch (error) {
    return { state: normalizeUserModerationStateRow({}), error };
  }
}

function syncMyModerationState(nextStateInput = null) {
  const nextState = normalizeMyModerationStatePayload(nextStateInput || {});
  state.moderationState = {
    ...normalizeUserModerationStateRow({ user_id: state.user?.id || "" }),
    ...nextState,
    userId: nextState.userId || normId(state.user?.id || ""),
  };
  return state.moderationState;
}

async function refreshMyModerationInboxEntries({ render = true } = {}) {
  if (!state.user?.id) return [];
  const result = await listMyModerationActionsRpc(25);
  if (result?.error) {
    if (isModerationSqlMissingError(result.error)) {
      moderationInboxReplyPendingActionIds.clear();
      setModerationInboxActions([], { render });
      return [];
    }
    return state.moderationInboxActions || [];
  }
  const nextActions = setModerationInboxActions(result.rows || [], { render: false });
  Array.from(moderationInboxReplyPendingActionIds).forEach((actionId) => {
    if (!shouldModerationActionRequireResponse(getModerationInboxActionById(actionId))) {
      moderationInboxReplyPendingActionIds.delete(actionId);
    }
  });
  if (render) renderDesktopInboxPanel();
  return nextActions;
}

function scheduleModerationInboxRefresh(delayMs = 120, { render = true } = {}) {
  if (!state.user?.id) return;
  const safeDelay = Math.max(0, Number(delayMs) || 0);
  if (moderationInboxRefreshTimer) clearTimeout(moderationInboxRefreshTimer);
  moderationInboxRefreshTimer = setTimeout(() => {
    moderationInboxRefreshTimer = null;
    void refreshMyModerationInboxEntries({ render });
  }, safeDelay);
}

async function refreshMyModerationState({ enforceBan = false, timeoutMs = RPC_SOFT_TIMEOUT_MS } = {}) {
  if (!state.user?.id) return normalizeUserModerationStateRow({});
  const result = await getMyModerationStateRpc(timeoutMs);
  if (result?.error) {
    if (isModerationSqlMissingError(result.error)) {
      return syncMyModerationState({ user_id: state.user.id, is_banned: false, metadata: {} });
    }
    return state.moderationState || normalizeUserModerationStateRow({ user_id: state.user.id });
  }
  const nextState = syncMyModerationState(result.state);
  if (enforceBan) await enforceModerationAccessGate(nextState);
  return nextState;
}

async function enforceModerationAccessGate(stateInput = null) {
  const nextState = normalizeUserModerationStateRow(stateInput || state.moderationState || {});
  if (!nextState?.isBanned || moderationBanEnforcementInFlight) return false;

  moderationBanEnforcementInFlight = true;
  try {
    const reasonText = String(nextState.banReason || nextState.metadata?.report_reason || "").trim();
    const message = reasonText
      ? `${t("moderation.account.banned.body", "This ALTARA account is banned and can no longer use the app.")}\n\n${t("inbox.item.moderation.reason_prefix", "Reason")}: ${reasonText}`
      : t("moderation.account.banned.body", "This ALTARA account is banned and can no longer use the app.");
    await requestAppAlert(message, {
      title: t("moderation.account.banned.title", "Account unavailable"),
      okText: t("dialog.notice.ok", "OK"),
      danger: true,
    });
  } finally {
    try {
      clearConversationMessageMemoryCache({ userSwitch: true });
      await logout();
    } catch (_) {
      try { window.location.replace("./login.html"); } catch (_) {}
    }
  }
  return true;
}

function startModerationPolling() {
  if (!state.user?.id) return;
  if (moderationPollTimer) clearInterval(moderationPollTimer);
  moderationPollTimer = setInterval(() => {
    if (!state.user?.id) return;
    void refreshMyModerationState({ enforceBan: true });
    void refreshMyModerationInboxEntries({ render: true });
  }, 60000);

  if (moderationPollingVisibilityBound) return;
  moderationPollingVisibilityBound = true;
  document.addEventListener("visibilitychange", () => {
    if (!state.user?.id || document.visibilityState !== "visible") return;
    void refreshMyModerationState({ enforceBan: true });
    void refreshMyModerationInboxEntries({ render: true });
  });
}

function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("file_read_failed"));
    try {
      reader.readAsDataURL(file);
    } catch (err) {
      reject(err);
    }
  });
}

