function setAppLanguage(lang, { persist = true, rerender = true, syncForm = true } = {}) {
  const next = normalizeAppLanguage(lang, APP_LANG_DEFAULT);
  appLanguage = next;
  if (persist) writeStoredAppLanguage(next);
  if (syncForm) {
    const langSelect = document.getElementById("themeLanguage");
    if (langSelect) langSelect.value = next;
  }
  document.documentElement.lang = next === "pt" ? "pt-PT" : "en";
  applyLanguageToStaticUi();
  setSettingsTab(settingsActiveTab || "account");
  if (rerender) {
    renderWidgets();
    renderFriends();
    renderPending();
    renderPartyPicker();
    void loadDmList().catch(() => {});
  }
}

function syncSettingsOverlayDockMode(tabId = settingsActiveTab) {
  const overlay = document.getElementById("profileOverlay");
  if (!overlay) return;
  overlay.classList.remove("settingsOverlay--appearance-live");
}

function isProfileOverlayOpen() {
  const overlay = document.getElementById("profileOverlay");
  return !!overlay && !overlay.classList.contains("hidden");
}

function isSettingsAccountPanelActive() {
  const panel = document.querySelector('#profileOverlay [data-settings-panel="account"]');
  return !!panel && panel.classList.contains("is-active");
}

function isSettingsDebugEnabled() {
  try {
    return String(localStorage.getItem("altara.debug.settings") || "").trim() === "1";
  } catch (_) {
    return false;
  }
}

function debugSettingsLog(...args) {
  if (!isSettingsDebugEnabled()) return;
  try { console.debug(...args); } catch (_) {}
}

function safeSettingsBind(label = "settings", binder = null) {
  try {
    if (typeof binder === "function") binder();
    return true;
  } catch (error) {
    console.warn("[Settings] " + label + " binding failed", error);
    return false;
  }
}

function bindSettingsClickDebugOnce() {
  if (window.__altaraSettingsClickDebugBound === true) return;
  window.__altaraSettingsClickDebugBound = true;
  document.addEventListener("click", (event) => {
    if (window.__altaraDebugClick !== true && window.__altaraDebugSettingsClick !== true && !isSettingsDebugEnabled()) return;
    const overlay = document.getElementById("profileOverlay");
    if (!overlay || overlay.classList.contains("hidden")) return;
    const target = eventTargetElement(event);
    if (!(target instanceof Element) || !overlay.contains(target)) return;
    const button = target.closest("button, [role='button'], [data-action]");
    const pointEl = (Number.isFinite(event.clientX) && Number.isFinite(event.clientY))
      ? document.elementFromPoint(event.clientX, event.clientY)
      : null;
    const targetStyle = target instanceof HTMLElement ? getComputedStyle(target) : null;
    const buttonStyle = button instanceof HTMLElement ? getComputedStyle(button) : null;
    console.debug("[Settings click debug]", {
      target,
      button,
      action: button instanceof HTMLElement ? button.dataset?.action : undefined,
      id: button instanceof HTMLElement ? button.id : undefined,
      disabled: button instanceof HTMLButtonElement ? button.disabled : undefined,
      targetPointerEvents: targetStyle?.pointerEvents,
      buttonPointerEvents: buttonStyle?.pointerEvents,
      targetZIndex: targetStyle?.zIndex,
      buttonZIndex: buttonStyle?.zIndex,
      targetAppRegion: targetStyle?.webkitAppRegion,
      buttonAppRegion: buttonStyle?.webkitAppRegion,
      elementFromPoint: pointEl,
      pointIsTarget: pointEl === target || (pointEl instanceof Node && target.contains(pointEl)),
      pointIsButton: button instanceof Node && (pointEl === button || (pointEl instanceof Node && button.contains(pointEl))),
    });
  }, true);
}

function isPlaceholderMyAccountValue(value = "") {
  const normalized = String(value ?? "").trim().toLowerCase();
  return !normalized || normalized === "..." || normalized === "@...";
}

function hasOwnProfileValue(profile = null, key = "") {
  return !!(profile && typeof profile === "object" && Object.prototype.hasOwnProperty.call(profile, key));
}

function isRealProfile(profileInput = null) {
  if (!profileInput || typeof profileInput !== "object") return false;
  const profile = profileInput;
  const profileId = normId(profile.id || profile.user_id || "");
  const currentUserId = normId(state.user?.id || "");
  if (profileId && currentUserId && profileId !== currentUserId) return false;

  const hasProfileRowShape = !!(profileId && [
    "username",
    "display_name",
    "bio",
    "pronouns",
  ].some((key) => hasOwnProfileValue(profile, key)));
  if (hasProfileRowShape) return true;

  const profileTextSignals = [
    profile.username,
    profile.display_name,
    profile.bio,
    profile.pronouns,
  ].some((value) => !isPlaceholderMyAccountValue(value));
  if (profileTextSignals) return true;

  const hasLifecycleSignal = !!(profileId && ["updated_at", "updatedAt", "created_at", "createdAt"].some((key) => (
    hasOwnProfileValue(profile, key) && !isPlaceholderMyAccountValue(profile[key])
  )));
  return hasLifecycleSignal;
}

function isRealMyAccountProfile(profileInput = null) {
  return isRealProfile(profileInput);
}

function getRealMyAccountProfileSnapshot(profileInput = null) {
  const candidates = [];
  if (profileInput && typeof profileInput === "object") candidates.push(profileInput);
  if (myAccountPendingProfile && typeof myAccountPendingProfile === "object") candidates.push(myAccountPendingProfile);
  if (state.me && typeof state.me === "object") candidates.push(state.me);
  const meId = normId(state.user?.id || "");
  if (meId) candidates.push(profileCache.get(meId) || null);

  for (const candidate of candidates) {
    if (!candidate || typeof candidate !== "object") continue;
    if (!isRealProfile(candidate)) continue;
    return getCurrentMeProfileSnapshot(candidate);
  }
  return null;
}

function getMyAccountProfileKey(profile = null) {
  if (!profile || typeof profile !== "object") return "";
  let themeKey = "";
  try { themeKey = JSON.stringify(profile.theme_settings || null); } catch (_) { themeKey = ""; }
  return [
    normId(profile.id || profile.user_id || state.user?.id || ""),
    profile.updated_at || profile.updatedAt || "",
    profile.created_at || profile.createdAt || "",
    profile.username || "",
    profile.display_name || "",
    profile.pronouns || "",
    profile.bio || "",
    profile.name_color || "",
    profile.call_tile_color || "",
    profile.avatar_url || "",
    profile.banner_url || "",
    profile.email || state.user?.email || "",
    themeKey,
  ].map((item) => String(item ?? "")).join("|");
}

function getMyAccountProfileVersion(profile = null) {
  return getMyAccountProfileKey(profile);
}

function getSettingsAccountFieldElements() {
  return [
    document.getElementById("username"),
    document.getElementById("displayName"),
    document.getElementById("bio"),
    document.getElementById("pronouns"),
    document.getElementById("nameColor"),
    document.getElementById("callTileColor"),
  ].filter((el) => el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement);
}

function setSettingsAccountProfileLoadingUi(isLoading = false) {
  const loading = !!isLoading;
  const panel = document.querySelector('#profileOverlay [data-settings-panel="account"]');
  if (panel instanceof HTMLElement) {
    panel.classList.toggle("is-profile-loading", loading);
    panel.setAttribute("aria-busy", loading ? "true" : "false");
  }
  getSettingsAccountFieldElements().forEach((field) => {
    field.disabled = loading;
  });
  ["btnSaveUsername", "btnSaveProfile", "btnOpenProfileWidgets"].forEach((id) => {
    const button = document.getElementById(id);
    if (button instanceof HTMLButtonElement) button.disabled = loading;
  });
}

function renderSettingsAccountLoadStatus() {
  const statusEl = document.getElementById("settingsAccountLoadStatus");
  const realProfile = getRealMyAccountProfileSnapshot(state.me || null) || getRealMyAccountProfileSnapshot();
  const hasProfile = !!(myAccountHasHydratedRealProfile || realProfile);
  const loadingWithoutProfile = !hasProfile && (settingsProfileLoading || isSettingsAccountPanelActive());
  setSettingsAccountProfileLoadingUi(loadingWithoutProfile);
  if (!statusEl) return;
  if (loadingWithoutProfile && !settingsProfileLoadError) {
    statusEl.hidden = false;
    statusEl.removeAttribute("data-tone");
    statusEl.removeAttribute("title");
    statusEl.textContent = "Loading profile...";
    return;
  }
  if (settingsProfileLoadError && !hasProfile) {
    statusEl.hidden = false;
    statusEl.setAttribute("data-tone", "error");
    statusEl.setAttribute("title", settingsProfileLoadError);
    statusEl.innerHTML = '<span>Couldn\'t load your profile.</span><button class="btn ghost settingsAccountRetryBtn" type="button" data-action="settings-account-retry">Retry</button>';
    return;
  }
  statusEl.hidden = true;
  statusEl.removeAttribute("data-tone");
  statusEl.removeAttribute("title");
  statusEl.textContent = "";
}

function markSettingsAccountDirty() {
  if (myAccountHydrating) return;
  myAccountDirty = true;
  debugSettingsLog("[Settings] My Account dirty", { dirty: myAccountDirty, hydrated: myAccountHasHydratedRealProfile });
}

function hydrateMyAccountFromProfile(profileInput = null, { reason = "settings", hydrateFields = true } = {}) {
  if (!isProfileOverlayOpen()) return false;
  const profile = getCurrentMeProfileSnapshot(profileInput || state.me || {});
  const uid = normId(profile.id || profile.user_id || state.user?.id || "");
  const displayName = String(profile.display_name || profile.username || "User").trim() || "User";
  const username = String(profile.username || "").trim();
  const pronouns = normalizePronouns(profile.pronouns || "");
  const avatarUrl = resolveProfileAvatarUrl(profile.avatar_url, getCurrentMeAvatarUrl());

  myAccountHydrating = true;
  try {
    const meLine = document.getElementById("meLine");
    if (meLine) meLine.textContent = displayName;
    const uidLine = document.getElementById("uidLine");
    if (uidLine) uidLine.textContent = username ? "@" + username : "@...";
    const pronounsLine = document.getElementById("pronounsLine");
    if (pronounsLine) {
      pronounsLine.textContent = pronouns;
      pronounsLine.hidden = !pronouns;
    }
    const settingsUserName = document.getElementById("settingsUserName");
    if (settingsUserName) settingsUserName.textContent = displayName;
    const settingsUserTag = document.getElementById("settingsUserTag");
    if (settingsUserTag) settingsUserTag.textContent = username ? "@" + username : "@...";

    setAvatar(document.getElementById("settingsUserAvatar"), avatarUrl || null, state.user?.id || uid || "");
    const avatarPreview = document.getElementById("avatarPreview");
    if (avatarPreview) {
      avatarPreview.innerHTML = avatarUrl
        ? buildAvatarMediaHtml(avatarUrl, { userId: state.user?.id || uid || "", alt: "avatar", controlledGif: true })
        : "";
      queueManagedGifPlaybackSync(avatarPreview);
    }

    const settingsBanner = document.getElementById("settingsIdentityBanner");
    if (settingsBanner) {
      const base = normalizeCallTileColor(profile.call_tile_color) || "#1b2230";
      const left = mixHex(base, "#77c5ff", 0.1);
      const right = mixHex(base, "#05080d", 0.55);
      const glow = rgbaFromHex(base, 0.22);
      const bannerUrl = resolveProfileBannerUrl(
        profile.banner_url,
        profile.theme_settings,
        resolveUserBannerUrl(state.user?.id || uid || "", profile.banner_url || profile.theme_settings?.banner_url || "")
      );
      applyBannerStyle(settingsBanner, bannerUrl, left, right, glow, { userId: state.user?.id || uid || "" });
      if (!bannerUrl) settingsBanner.style.background = "linear-gradient(135deg, " + left + ", " + right + " 78%)";
    }

    if (hydrateFields) {
      const usernameInput = document.getElementById("username");
      if (usernameInput) usernameInput.value = username;
      const displayNameInput = document.getElementById("displayName");
      if (displayNameInput) displayNameInput.value = String(profile.display_name || "");
      const pronounsInput = document.getElementById("pronouns");
      if (pronounsInput) pronounsInput.value = pronouns;
      const bioInput = document.getElementById("bio");
      if (bioInput) bioInput.value = String(profile.bio || "");
      const nameColorInput = document.getElementById("nameColor");
      if (nameColorInput) nameColorInput.value = normalizeNameColor(profile.name_color) || "#f1f2f5";
      const callTileColorInput = document.getElementById("callTileColor");
      if (callTileColorInput) callTileColorInput.value = normalizeCallTileColor(profile.call_tile_color) || "#1b2230";
      const currentEmailInput = document.getElementById("currentEmail");
      if (currentEmailInput) currentEmailInput.value = String(state.user?.email || profile.email || "");
    }
  } finally {
    myAccountHydrating = false;
  }

  syncProfileBioFieldUi();
  renderSettingsIdentityProfilePreviewAltaraPlusBadge();
  renderSettingsAccountLoadStatus();
  debugSettingsLog("[Settings] hydrateMyAccountFromProfile", {
    reason,
    hydrateFields,
    username,
    displayName,
  });
  return true;
}

function maybeHydrateMyAccount(profileInput = null, { force = false, reason = "settings" } = {}) {
  const profile = getRealMyAccountProfileSnapshot(profileInput || null);
  debugSettingsLog("[Settings] maybeHydrateMyAccount", {
    reason,
    force,
    overlayOpen: isProfileOverlayOpen(),
    accountActive: isSettingsAccountPanelActive(),
    currentUser: !!state.user?.id,
    profileExists: !!profile,
    dirty: myAccountDirty,
    hasHydratedRealProfile: myAccountHasHydratedRealProfile,
  });

  if (profile) myAccountPendingProfile = profile;
  if (!isProfileOverlayOpen()) return false;
  if (!profile) {
    if (isSettingsAccountPanelActive()) {
      settingsProfileLoading = true;
      renderSettingsAccountLoadStatus();
    }
    return false;
  }

  const profileKey = getMyAccountProfileKey(profile);
  const isSameProfile = !!(myAccountLastProfileKey && myAccountLastProfileKey === profileKey);
  const shouldHydrateFields = force || !myAccountHasHydratedRealProfile || (!myAccountDirty && !isSameProfile);

  if (shouldHydrateFields) {
    hydrateMyAccountFromProfile(profile, { reason, hydrateFields: true });
    myAccountHasHydratedRealProfile = true;
    myAccountDirty = false;
    myAccountLastProfileKey = profileKey;
    settingsProfileLoading = false;
    settingsProfileLoadError = "";
    renderSettingsAccountLoadStatus();
    return true;
  }

  if (myAccountDirty) {
    hydrateMyAccountFromProfile(profile, { reason: reason + ":preview_only_dirty", hydrateFields: false });
    debugSettingsLog("[Settings] My Account hydration skipped fields because dirty", { reason, profileKey });
  } else {
    renderSettingsAccountLoadStatus();
  }
  return false;
}

function hydrateMyAccountSettings(profileInput = null, { force = false, reason = "settings" } = {}) {
  return maybeHydrateMyAccount(profileInput, { force, reason });
}

function syncSettingsAccountFormFromProfile(profileInput = null, { force = false, reason = "legacy" } = {}) {
  return maybeHydrateMyAccount(profileInput, { force, reason });
}

function syncOpenSettingsAccountFromProfile(profileInput = null, { force = false, reason = "open_sync" } = {}) {
  if (!isProfileOverlayOpen()) {
    const profile = getRealMyAccountProfileSnapshot(profileInput || state.me || null);
    if (profile) myAccountPendingProfile = profile;
    return false;
  }
  return maybeHydrateMyAccount(profileInput || state.me || null, { force, reason });
}

function ensureSettingsAccountProfileLoad({ force = false, reason = "settings" } = {}) {
  if (!isProfileOverlayOpen()) return null;
  debugSettingsLog("[Settings] ensureSettingsAccountProfileLoad", {
    reason,
    force,
    user: !!state.user?.id,
    accountActive: isSettingsAccountPanelActive(),
  });
  if (!state.user?.id) {
    settingsProfileLoading = true;
    settingsProfileLoadError = "";
    renderSettingsAccountLoadStatus();
    return null;
  }
  const realProfile = getRealMyAccountProfileSnapshot(state.me || null);
  if (!force && realProfile) {
    settingsProfileLoading = false;
    settingsProfileLoadError = "";
    maybeHydrateMyAccount(realProfile, { force: false, reason: reason + ":cached-profile" });
    return null;
  }
  settingsProfileLoading = true;
  settingsProfileLoadError = "";
  renderSettingsAccountLoadStatus();
  if (!force && settingsProfileLoadPromise) {
    return settingsProfileLoadPromise.then((profile) => {
      if (profile) maybeHydrateMyAccount(profile, { force: false, reason: reason + ":profile-load-promise" });
      return profile;
    }).catch((error) => {
      settingsProfileLoading = false;
      settingsProfileLoadError = String(error?.message || error || "Profile unavailable.").slice(0, 180);
      renderSettingsAccountLoadStatus();
      return null;
    });
  }
  return loadProfileOverlay({ force, reason }).then((profile) => {
    if (profile) maybeHydrateMyAccount(profile, { force: false, reason: reason + ":profile-loaded" });
    return profile;
  }).catch((error) => {
    console.warn("settings profile load failed", error?.message || error);
    settingsProfileLoading = false;
    settingsProfileLoadError = String(error?.message || error || "Profile unavailable.").slice(0, 180);
    renderSettingsAccountLoadStatus();
    return null;
  });
}

function setSettingsTab(tabId = "account") {
  markPerfStart("settings_tab_switch", { tabId: String(tabId || "account") });
  const overlay = document.getElementById("profileOverlay");
  if (!overlay) return;

  const navItems = Array.from(overlay.querySelectorAll("[data-settings-tab]"));
  const panels = Array.from(overlay.querySelectorAll("[data-settings-panel]"));
  if (!navItems.length || !panels.length) return;

  const wanted = String(tabId || "account").trim() || "account";
  let resolved = panels.some((panel) => panel.dataset.settingsPanel === wanted) ? wanted : "account";
  if (resolved === "reports" && !isCurrentUserOwner()) resolved = "account";
  if (settingsActiveTab === "voice-video" && resolved !== "voice-video") {
    stopVoiceMicTest({ clearError: true });
  }

  navItems.forEach((item) => {
    const isActive = item.dataset.settingsTab === resolved;
    item.classList.toggle("is-active", isActive);
    item.setAttribute("aria-current", isActive ? "page" : "false");
  });

  panels.forEach((panel) => {
    panel.classList.toggle("is-active", panel.dataset.settingsPanel === resolved);
  });

  const titleEl = document.getElementById("settingsTitle");
  if (titleEl) {
    const active = navItems.find((item) => item.dataset.settingsTab === resolved);
    const label = active?.querySelector("span")?.textContent?.trim() || "Settings";
    titleEl.textContent = label;
  }
  const subtitleEl = document.querySelector("#profileOverlay .settingsSubtitle");
  if (subtitleEl) {
    const meta = SETTINGS_TAB_META[resolved] || SETTINGS_TAB_META.account;
    subtitleEl.textContent = t(meta.subtitleKey, meta.fallback);
  }

  settingsActiveTab = resolved;
  syncSettingsOverlayDockMode(resolved);
  if (resolved === "security") {
    renderSecurityAccessUi();
    void renderDmPrivacySettingsUi({ force: false });
    void refreshDmE2eeBackupSettingsState({ force: true });
    requestAnimationFrame(() => {
      if (isAppConfirmVisible()) return;
      ensureSecurityInputsInteractive();
      const preferred = getPreferredSecurityTypingInput();
      if (preferred && document.activeElement !== preferred) focusSecurityInput(preferred);
    });
  }
  if (resolved === "altara-plus") {
    renderSettingsAltaraPlusPanel();
    void refreshCurrentUserAltaraPlusStatus({ reason: "settings_open" });
  }
  if (resolved === "blocked-users") {
    void renderBlockedUsersSettingsUi({ force: true });
  }
  if (resolved === "reports") {
    void renderOwnerReportsSettingsUi({ force: true });
  }
  if (resolved === "notifications") {
    syncNotificationBehaviorSettingsUi();
    void refreshCurrentUserAltaraPlusStatus({ reason: "focus_settings_open" });
  }
  if (resolved === "activity") {
    renderActivitySettingsUi();
      scheduleRegisteredGamesMetadataEnrichment({ force: false, reason: "settings_open" });
    void syncDesktopActivityDetectionEnabled();
  }
  if (resolved === "developer") {
    bindSettingsDeveloperPortalOnce();
    renderSettingsDeveloperPortal();
  }
  if (resolved === "connections") {
    renderConnectionsSettingsUi();
    void refreshConnectedAccounts({ force: true });
    if (getSpotifyConnectedAccount()) syncSpotifyPollingFromAccounts({ immediate: true });
  }
  if (resolved === "account") {
    renderSettingsAccountLoadStatus();
    maybeHydrateMyAccount(getRealMyAccountProfileSnapshot(state.me || null), { force: false, reason: "account_tab_render" });
    void ensureSettingsAccountProfileLoad({ force: false, reason: "account_tab" });
  }
  markPerfEnd("settings_tab_switch", { tab: resolved });
}

function openProfileOverlay() {
  markPerfStart("settings_open");
  closeActivePopover();
  const p = document.getElementById("profileOverlay");
  if (!p) return;
  settingsSecurityUnlocked = false;
  settingsSecurityRemoveVerificationPending = false;
  settingsDmE2eeBackupLoading = false;
  settingsDmE2eeBackupSaving = false;
  settingsDmE2eeBackupRestoring = false;
  settingsDmE2eeBackupSetupInFlight = false;
  settingsDmE2eeBackupState = {
    loaded: false,
    identityStatus: "unknown",
    exportable: false,
    hasBackup: false,
    backupUpdatedAt: "",
    backupPasswordSource: "",
    hasRecoveryKeyMethod: false,
    hasVaultConversation: false,
    hasVaultMessages: false,
    hasLocalVaultKey: false,
    error: null,
  };
  syncSecurityCodeStateFromUser(state.user, { preserveUnlock: false });
  syncOwnerReportsSettingsAccessUi();
  p.classList.remove("hidden");
  p.setAttribute("aria-hidden", "false");
  markPerfEnd("settings_open", { shell: true });
  myAccountDirty = false;
  myAccountHydrating = false;
  myAccountHasHydratedRealProfile = false;
  myAccountLastProfileKey = null;
  myAccountPendingProfile = null;
  settingsProfileLoadError = "";
  settingsProfileLoading = !getRealMyAccountProfileSnapshot(state.me || null);
  renderSettingsAccountLoadStatus();
  bindProfileOverlayOnce();
  safeSettingsBind("custom theme picker", () => bindCustomThemeColorPickerOnce());
  renderThemePresetSelectOptions();
  renderThemeCustomPresetSelect();
  setSettingsTab(settingsActiveTab || "account");
  syncSettingsOverlayDockMode(settingsActiveTab || "account");
  loadProfileOverlay({ reason: "settings_open" }).catch(console.error);
}

function closeProfileOverlay() {
  const p = document.getElementById("profileOverlay");
  if (!p) return;
  if (typeof resetSteamConnectFlowState === "function" && (pendingSteamWebConnect || steamConnectInFlight)) {
    resetSteamConnectFlowState({
      closePopup: true,
      preserveMessage: true,
      terminalReason: "settings_closed",
    });
  }
  if (typeof clearSteamConnectionNotice === "function" && steamConnectionNotice) {
    clearSteamConnectionNotice({ source: "settings_closed", render: false });
  }
  stopVoiceMicTest({ clearError: true });
  if (themeEditorCommittedSettings) {
    state.me = state.me || {};
    state.me.theme_settings = normalizeThemeSettings(themeEditorCommittedSettings);
    applyAppearanceSettings(normalizeAppearanceSettings(themeEditorCommittedSettings));
  }
  clearThemeEditorDraftFromStorage();
  settingsSecurityUnlocked = false;
  settingsSecurityRemoveVerificationPending = false;
  clearSecurityCodeInputs();
  clearDmE2eeBackupInputs({ clearRestore: true });
  p.classList.add("hidden");
  p.setAttribute("aria-hidden", "true");
  p.classList.remove("settingsOverlay--appearance-live");
  if (callKeybindCaptureAction) {
    callKeybindCaptureAction = "";
    callKeybindCapturePressedTokens.clear();
    callKeybindCaptureLastCombo = "";
    callKeybindCaptureError = "";
    renderCallKeybindSettingsUi();
  }
  if (appKeybindCaptureAction) {
    appKeybindCaptureAction = "";
    appKeybindCapturePressedTokens.clear();
    appKeybindCaptureLastCombo = "";
    appKeybindCaptureError = "";
    renderAppKeybindSettingsUi();
  }
}

const VAULT_RISK_DEBUG_STORAGE_KEY = "altara.debug.vault";

function isVaultRiskDebugEnabled() {
  try {
    const raw = String(localStorage.getItem(VAULT_RISK_DEBUG_STORAGE_KEY) || "").trim().toLowerCase();
    return raw === "1" || raw === "true" || raw === "yes";
  } catch (_) {
    return false;
  }
}

function logVaultRiskState(riskState = {}) {
  if (!isVaultRiskDebugEnabled() || typeof console === "undefined" || typeof console.info !== "function") return;
  console.info("[vault-risk] state", {
    hasLocalVaultKey: riskState.hasLocalVaultKey === true,
    hasVaultRecoveryBackup: riskState.hasVaultRecoveryBackup === true,
    hasVaultConversation: riskState.hasVaultConversation === true,
    hasVaultMessages: riskState.hasVaultMessages === true,
    warningLevel: String(riskState.warningLevel || "none"),
  });
}

function hasCachedVaultConversationRisk() {
  const isVaultState = (value = "") => {
    const privacyState = normalizeDmPrivacyState(value || "standard");
    return privacyState === "private_requested" || privacyState === "private_active";
  };
  const checkRow = (row = null) => {
    if (!row || typeof row !== "object") return false;
    return isVaultState(row.dm_privacy_state || row.dmPrivacyState || row.state || row.privacy?.state || "standard");
  };
  if (checkRow(state.activeDm)) return true;
  try {
    for (const meta of dmConversationMetaById.values()) {
      if (checkRow(meta)) return true;
    }
  } catch (_) {}
  const lists = [state.dmContacts, state.friends, state.groupDms];
  return lists.some((list) => Array.isArray(list) && list.some(checkRow));
}

function hasCachedVaultMessageRisk() {
  try {
    return Array.isArray(dmMessagesCache) && dmMessagesCache.some((row) => isEncryptedDmMessageRow(row));
  } catch (_) {
    return false;
  }
}

async function queryCurrentUserHasVaultConversationRisk() {
  try {
    const { data, error } = await supabase
      .from("conversations")
      .select("id")
      .in("dm_privacy_state", ["private_requested", "private_active"])
      .limit(1);
    if (error) return false;
    return Array.isArray(data) && data.length > 0;
  } catch (_) {
    return false;
  }
}

async function queryCurrentUserHasVaultMessageRisk() {
  try {
    const { data, error } = await supabase
      .from("messages")
      .select("id")
      .eq("message_mode", DM_E2EE_MESSAGE_MODE)
      .limit(1);
    if (error) return false;
    return Array.isArray(data) && data.length > 0;
  } catch (_) {
    return false;
  }
}

async function getCurrentUserVaultRiskState() {
  const base = {
    hasLocalVaultKey: false,
    hasVaultRecoveryBackup: false,
    hasVaultConversation: false,
    hasVaultMessages: false,
    hasVaultRisk: false,
    warningLevel: "none",
  };
  if (!isDirectDmE2eeEnabled() || !state.user?.id) {
    logVaultRiskState(base);
    return base;
  }

  const userId = state.user.id;
  let identityState = null;
  let backupMeta = null;
  try {
    [identityState, backupMeta] = await Promise.all([
      getDmE2eeIdentityState({ userId, force: true }).catch(() => null),
      getDmE2eeKeyBackupMetadata({ userId, force: true }).catch(() => null),
    ]);
  } catch (_) {}

  const hasLocalVaultKey = identityState?.hasLocalPrivateKey === true;
  const hasVaultRecoveryBackup = !!backupMeta;
  let hasVaultConversation = hasCachedVaultConversationRisk();
  let hasVaultMessages = hasCachedVaultMessageRisk();

  if (!hasVaultConversation || !hasVaultMessages) {
    const [conversationRisk, messageRisk] = await Promise.all([
      hasVaultConversation ? Promise.resolve(true) : queryCurrentUserHasVaultConversationRisk(),
      hasVaultMessages ? Promise.resolve(true) : queryCurrentUserHasVaultMessageRisk(),
    ]);
    hasVaultConversation = !!conversationRisk;
    hasVaultMessages = !!messageRisk;
  }

  // A local E2EE identity can be created by bootstrap before the user ever switches a DM to Vault.
  // Treat backup/conversation/message evidence as real Vault recovery risk.
  const hasVaultUsageOrRecoveryRisk = hasVaultRecoveryBackup || hasVaultConversation || hasVaultMessages;
  const warningLevel = !hasVaultUsageOrRecoveryRisk
    ? "none"
    : (hasVaultRecoveryBackup ? "mild" : "strong");
  const result = {
    hasLocalVaultKey,
    hasVaultRecoveryBackup,
    hasVaultConversation,
    hasVaultMessages,
    hasVaultRisk: warningLevel !== "none",
    warningLevel,
  };
  logVaultRiskState(result);
  return result;
}

async function logoutFromSettings() {
  if (settingsLogoutInFlight) return;
  settingsLogoutInFlight = true;
  const button = document.getElementById("btnSettingsLogout");
  const label = document.getElementById("settingsNavLogout");
  let forceRedirectTimer = null;

  try {
    forceRedirectTimer = setTimeout(() => {
      try { window.location.replace("./login.html"); } catch (_) {}
    }, 4500);
    if (button) button.disabled = true;
    if (label) label.textContent = t("settings.logout.pending", "Signing out...");
    syncDesktopTaskbarUnreadCount(0, { force: true });
    clearConversationMessageMemoryCache({ userSwitch: true });
    await logout();
  } catch (err) {
    console.warn("settings logout failed", err);
    await requestAppAlert(t("settings.logout.error", "Could not sign out. Please try again."), {
      title: t("settings.section.security", "Security"),
      okText: t("dialog.confirm.ok", "OK"),
      danger: true,
    });
    if (button) button.disabled = false;
    if (label) label.textContent = t("settings.nav.logout", "Log out");
  } finally {
    if (forceRedirectTimer) clearTimeout(forceRedirectTimer);
    settingsLogoutInFlight = false;
  }
}

