function getWidgetChecklistSubtitle(model = {}) {
  const overdue = Math.max(0, Number(model?.summary?.overdue) || 0);
  const dueToday = Math.max(0, Number(model?.summary?.dueToday) || 0);
  const left = Math.max(0, Number(model?.leftCount) || 0);
  if (overdue > 0) return overdue === 1 ? t("widget.todo.subtitle.overdue_one", "1 overdue") : tf("widget.todo.subtitle.overdue", { count: overdue }, `${overdue} overdue`);
  if (dueToday > 0) return dueToday === 1 ? t("widget.todo.subtitle.today_one", "1 due today") : tf("widget.todo.subtitle.today", { count: dueToday }, `${dueToday} due today`);
  if (left > 0) return left === 1 ? t("widget.todo.subtitle.left_one", "1 left") : tf("widget.todo.subtitle.left", { count: left }, `${left} left`);
  return model.totalCount ? t("widget.todo.subtitle.done", "All done") : t("widget.todo.empty", "No tasks yet.");
}

function getWidgetTodoDisplayRank(item, nowInput = new Date()) {
  if (item?.done) return 4;
  const meta = getWidgetTodoScheduleMeta(item, nowInput);
  if (meta.isOverdue) return 0;
  if (meta.isToday) return 1;
  if (item?.dueDate) return 2;
  return 3;
}

function sortWidgetTodoItemsForDisplay(items = getWidgetTodoItems()) {
  const now = new Date();
  return normalizeWidgetTodoItems(items)
    .map((item, index) => {
      const due = getWidgetTodoDueDateTime(item, { fallbackHour: 23, fallbackMinute: 59 });
      return {
        item,
        index,
        rank: getWidgetTodoDisplayRank(item, now),
        dueMs: due ? due.getTime() : Number.POSITIVE_INFINITY,
      };
    })
    .sort((a, b) => (
      a.rank - b.rank
      || a.dueMs - b.dueMs
      || a.index - b.index
    ))
    .map((entry) => entry.item);
}

function pickWidgetChecklistVisibleItems(items = [], limitInput = 3) {
  const limit = clampInt(limitInput, 0, WIDGET_TODO_MAX_ITEMS, 3);
  if (limit <= 0) return [];
  const active = items.filter((item) => !item.done);
  const completed = items.filter((item) => !!item.done);
  return active.slice(0, limit).concat(completed.slice(0, Math.max(0, limit - active.length)));
}

function getWidgetChecklistModel() {
  const todos = getWidgetTodoItems();
  const doneCount = todos.filter((item) => !!item.done).length;
  const totalCount = todos.length;
  const leftCount = Math.max(0, totalCount - doneCount);
  const pct = totalCount ? Math.round((doneCount / totalCount) * 100) : 0;
  const summary = getWidgetTodoSummary(todos);
  const sortedItems = sortWidgetTodoItemsForDisplay(todos);
  return {
    todos,
    sortedItems,
    doneCount,
    totalCount,
    leftCount,
    pct,
    summary,
    isFull: totalCount >= WIDGET_TODO_MAX_ITEMS,
  };
}

function buildChecklistDueChipHtml(item = null) {
  const schedule = getWidgetTodoScheduleMeta(item);
  if (!schedule?.chipLabel) return "";
  const chipClass = [
    "profileChecklistDueChip",
    schedule.isOverdue ? "is-overdue" : "",
    schedule.isToday ? "is-today" : "",
    schedule.isDueSoon && !schedule.isOverdue && !schedule.isToday ? "is-soon" : "",
  ].filter(Boolean).join(" ");
  return `<span class="${chipClass}">${esc(schedule.chipLabel)}</span>`;
}

function buildChecklistPriorityChipHtml(item = null) {
  const priority = normalizeWidgetTodoPriority(item?.priority || item?.metadata?.priority);
  if (!priority) return "";
  return `<span class="profileChecklistDueChip profileChecklistDueChip--priority" data-priority="${escAttr(priority)}">${esc(getWidgetTodoPriorityLabel(priority))}</span>`;
}

function buildChecklistTaskRowHtml(item = null, index = 0, totalCount = 0, options = {}) {
  if (!item?.id) return "";
  const showActions = options.showActions !== false;
  const schedule = getWidgetTodoScheduleMeta(item);
  const chipHtml = buildChecklistDueChipHtml(item) || buildChecklistPriorityChipHtml(item);
  const isRenaming = widgetChecklistRenamingId === item.id;
  const isConfirmingDelete = widgetChecklistDeleteConfirmId === item.id;
  const rowClass = [
    "profileChecklistTaskRow",
    item.done ? "is-done" : "",
    schedule.isOverdue ? "is-overdue" : "",
    schedule.isDueSoon ? "is-soon" : "",
    isRenaming ? "is-renaming" : "",
    isConfirmingDelete ? "is-confirming-delete" : "",
  ].filter(Boolean).join(" ");

  if (isConfirmingDelete) {
    return `
      <li class="${rowClass}">
        <button class="profileChecklistCheckbox" type="button" data-widget-todo-toggle="${escAttr(item.id)}" aria-label="${escAttr(item.done ? t("widget.todo.mark_incomplete", "Mark incomplete") : t("widget.todo.mark_complete", "Mark complete"))}" aria-pressed="${item.done ? "true" : "false"}">
          <span aria-hidden="true"></span>
        </button>
        <span class="profileChecklistDeletePrompt">${esc(t("widget.todo.delete_confirm_inline", "Delete this task?"))}</span>
        <div class="profileChecklistTaskActions is-confirming">
          <button class="profileChecklistTextAction" type="button" data-checklist-delete-cancel="${escAttr(item.id)}">${esc(t("dialog.confirm.cancel", "Cancel"))}</button>
          <button class="profileChecklistTextAction is-danger" type="button" data-checklist-delete-confirm="${escAttr(item.id)}">${esc(t("widget.todo.delete", "Delete"))}</button>
        </div>
      </li>
    `;
  }

  if (isRenaming) {
    return `
      <li class="${rowClass}">
        <button class="profileChecklistCheckbox" type="button" data-widget-todo-toggle="${escAttr(item.id)}" aria-label="${escAttr(item.done ? t("widget.todo.mark_incomplete", "Mark incomplete") : t("widget.todo.mark_complete", "Mark complete"))}" aria-pressed="${item.done ? "true" : "false"}">
          <span aria-hidden="true"></span>
        </button>
        <input class="profileChecklistRenameInput" type="text" data-checklist-rename-input="${escAttr(item.id)}" maxlength="${WIDGET_TODO_MAX_CHARS}" value="${escAttr(item.text)}" autocomplete="off" />
        <div class="profileChecklistTaskActions is-renaming">
          <button class="profileChecklistMiniAction profileChecklistMiniAction--renameSave" type="button" data-checklist-rename-save="${escAttr(item.id)}" aria-label="${escAttr(t("widget.todo.save", "Save"))}" title="${escAttr(t("widget.todo.save", "Save"))}">${getWidgetTodoIcon("toggle", { done: true })}</button>
          <button class="profileChecklistMiniAction profileChecklistMiniAction--renameCancel" type="button" data-checklist-rename-cancel="${escAttr(item.id)}" aria-label="${escAttr(t("widget.todo.cancel", "Cancel"))}" title="${escAttr(t("widget.todo.cancel", "Cancel"))}">${getWidgetTodoIcon("remove")}</button>
        </div>
      </li>
    `;
  }

  return `
    <li class="${rowClass}">
      <button class="profileChecklistCheckbox" type="button" data-widget-todo-toggle="${escAttr(item.id)}" aria-label="${escAttr(item.done ? t("widget.todo.mark_incomplete", "Mark incomplete") : t("widget.todo.mark_complete", "Mark complete"))}" aria-pressed="${item.done ? "true" : "false"}">
        <span aria-hidden="true"></span>
      </button>
      <span class="profileChecklistTaskTitle" title="${escAttr(item.text)}">${esc(item.text)}</span>
      ${chipHtml ? `<span class="profileChecklistTaskMeta">${chipHtml}</span>` : `<span class="profileChecklistTaskMeta" aria-hidden="true"></span>`}
      ${showActions ? `<div class="profileChecklistTaskActions">
        <button class="profileChecklistMiniAction" type="button" data-widget-todo-edit="${escAttr(item.id)}" aria-label="${escAttr(t("widget.todo.rename", "Rename task"))}" title="${escAttr(t("widget.todo.rename", "Rename task"))}">${getWidgetTodoIcon("edit")}</button>
        <button class="profileChecklistMiniAction profileChecklistMiniAction--delete" type="button" data-widget-todo-remove="${escAttr(item.id)}" aria-label="${escAttr(t("widget.todo.delete", "Delete task"))}" title="${escAttr(t("widget.todo.delete", "Delete task"))}">${getWidgetTodoIcon("remove")}</button>
      </div>` : ""}
    </li>
  `;
}

function getWidgetChecklistRenameInputById(itemId) {
  const id = String(itemId || "").trim();
  if (!id) return null;
  return Array.from(document.querySelectorAll("[data-checklist-rename-input]"))
    .find((input) => input instanceof HTMLInputElement && input.getAttribute("data-checklist-rename-input") === id) || null;
}

function focusWidgetChecklistRenameInput({ selectAll = true } = {}) {
  requestAnimationFrame(() => {
    const id = String(widgetChecklistRenamingId || "").trim();
    if (!id) return;
    const input = getWidgetChecklistRenameInputById(id);
    if (!(input instanceof HTMLInputElement)) return;
    try {
      input.focus({ preventScroll: true });
      if (selectAll && typeof input.select === "function") input.select();
    } catch (_) {}
  });
}

function startWidgetChecklistRename(itemId) {
  const id = String(itemId || "").trim();
  if (!id || !getWidgetTodoItemById(id)) return false;
  widgetChecklistRenamingId = id;
  widgetChecklistDeleteConfirmId = "";
  widgetChecklistQuickAddOpen = false;
  renderWidgets();
  focusWidgetChecklistRenameInput();
  return true;
}

function cancelWidgetChecklistRename() {
  if (!widgetChecklistRenamingId) return false;
  widgetChecklistRenamingId = "";
  renderWidgets();
  return true;
}

function submitWidgetChecklistRename(itemId = widgetChecklistRenamingId) {
  const id = String(itemId || widgetChecklistRenamingId || "").trim();
  if (!id) return false;
  const input = getWidgetChecklistRenameInputById(id);
  const nextText = getWidgetTodoDraftText(input instanceof HTMLInputElement ? input.value : "");
  if (!nextText) {
    showWidgetChecklistToast(t("widgets.todo.name_required", "Type a task name."), "warn");
    focusWidgetChecklistRenameInput({ selectAll: false });
    return false;
  }
  if (!renameWidgetTodoItem(id, nextText)) return false;
  widgetChecklistRenamingId = "";
  renderWidgets();
  return true;
}

function confirmWidgetChecklistDelete(itemId) {
  const id = String(itemId || "").trim();
  if (!id || !getWidgetTodoItemById(id)) return false;
  widgetChecklistDeleteConfirmId = id;
  widgetChecklistRenamingId = "";
  renderWidgets();
  return true;
}

function cancelWidgetChecklistDelete() {
  if (!widgetChecklistDeleteConfirmId) return false;
  widgetChecklistDeleteConfirmId = "";
  renderWidgets();
  return true;
}

function commitWidgetChecklistDelete(itemId = widgetChecklistDeleteConfirmId) {
  const id = String(itemId || widgetChecklistDeleteConfirmId || "").trim();
  if (!id) return false;
  removeWidgetTodoItem(id);
  widgetChecklistDeleteConfirmId = "";
  widgetChecklistRenamingId = "";
  renderWidgets();
  return true;
}
function buildChecklistQuickAddHtml(model = {}) {
  const disabled = model.isFull ? " disabled" : "";
  const label = model.isFull ? t("widget.todo.placeholder.limit", "Checklist is full.") : t("widget.todo.add_task", "Add task");
  if (widgetChecklistQuickAddOpen && !model.isFull) {
    return `
      <div class="profileChecklistQuickAddRow" data-checklist-quick-add-row="1">
        <input
          class="profileChecklistQuickAddInput"
          data-checklist-quick-add-input="1"
          maxlength="${WIDGET_TODO_MAX_CHARS}"
          autocomplete="off"
          placeholder="${escAttr(t("widget.todo.placeholder.add", "Add task..."))}"
        />
        <button class="profileChecklistQuickAddSubmit" type="button" data-checklist-quick-add-submit="1">${esc(t("widget.todo.add", "Add"))}</button>
        <button class="profileChecklistQuickAddCancel" type="button" data-checklist-quick-add-cancel="1" aria-label="${escAttr(t("widget.todo.cancel", "Cancel"))}">&times;</button>
      </div>
    `;
  }
  return `<button class="profileChecklistQuickAdd" type="button" data-widget-todo-quick-add="1"${disabled}>+ ${esc(label)}</button>`;
}

function focusWidgetChecklistQuickAddInput({ selectAll = false } = {}) {
  requestAnimationFrame(() => {
    const input = document.querySelector("[data-widget-id='checklist'] [data-checklist-quick-add-input]");
    if (!(input instanceof HTMLInputElement)) return;
    try {
      input.focus({ preventScroll: true });
      if (selectAll && typeof input.select === "function") input.select();
    } catch (_) {}
  });
}

function cancelWidgetChecklistQuickAdd() {
  widgetChecklistQuickAddOpen = false;
  renderWidgets();
}

function submitWidgetChecklistQuickAdd() {
  const input = document.querySelector("[data-widget-id='checklist'] [data-checklist-quick-add-input]");
  const text = getWidgetTodoDraftText(input instanceof HTMLInputElement ? input.value : "");
  if (!text) {
    showWidgetChecklistToast(t("widgets.todo.name_required", "Type a task name."), "warn");
    focusWidgetChecklistQuickAddInput();
    return false;
  }
  if (!addWidgetTodoItem(text)) {
    showWidgetChecklistToast(tf("widgets.todo.limit_toast", { max: WIDGET_TODO_MAX_ITEMS }, `Checklist limit reached (${WIDGET_TODO_MAX_ITEMS}).`), "warn");
    return false;
  }
  widgetChecklistQuickAddOpen = false;
  renderWidgets();
  return true;
}

function buildChecklistHiddenSummaryHtml(model = {}, visibleItems = []) {
  const hidden = Math.max(0, model.totalCount - visibleItems.length);
  if (!hidden) return "";
  const completedVisible = visibleItems.filter((item) => !!item.done).length;
  const completedHidden = Math.max(0, model.doneCount - completedVisible);
  const label = completedHidden > 0 && completedHidden === hidden
    ? (completedHidden === 1 ? t("widget.todo.completed_hidden_one", "1 completed") : tf("widget.todo.completed_hidden", { count: completedHidden }, `${completedHidden} completed`))
    : (hidden === 1 ? t("widget.todo.more_tasks_one", "+1 more") : tf("widget.todo.more_tasks", { count: hidden }, `+${hidden} more`));
  return `<div class="profileChecklistHiddenCount">${esc(label)}</div>`;
}

