    label: isTimer ? t("widget.timer.add_label", "Focus Timer") : getWidgetLabel(id),
    description: isTimer
      ? t("widget.timer.add_subtitle", "Study 20 min - Break 5 min")
      : t("widgets.add.default_subtitle", "Personalize your home grid."),
    iconHtml: isTimer ? "&#9201;" : "+",
