const SERVER_VOICE_V2_STALE_MEMBER_MS = 35000;
const SERVER_VOICE_V2_STALE_CLEANUP_INTERVAL_MS = 60000;

function traceVoiceV2ChannelWrite(reason = "unknown", details = {}) {
  const entry = {
    at: Date.now(),
    reason: String(reason || "unknown"),
    ...(details && typeof details === "object" ? details : {}),
    stack: (() => {
      try { return new Error().stack || ""; } catch (_) { return ""; }
    })(),
  };
  voiceV2ChannelWriteTrace.push(entry);
  while (voiceV2ChannelWriteTrace.length > 50) voiceV2ChannelWriteTrace.shift();
  console.info("[voice-v2] channel write", entry);
  return entry;
}

function traceVoiceV2RenderSource(renderTarget = "unknown", details = {}) {
  const entry = {
    at: Date.now(),
    renderTarget: String(renderTarget || "unknown"),
    ...(details && typeof details === "object" ? details : {}),
  };
  voiceV2RenderSourceTrace.push(entry);
  while (voiceV2RenderSourceTrace.length > 50) voiceV2RenderSourceTrace.shift();
  voiceV2DebugInfo("[voice-v2] render source chosen", entry);
  return entry;
}

function isVoiceV2DebugLoggingEnabled() {
  try {
    return localStorage.getItem("altara_debug_voice_v2") === "1";
  } catch (_) {
    return false;
  }
}

function voiceV2DebugLog(...args) {
  if (isVoiceV2DebugLoggingEnabled()) console.log(...args);
}

function voiceV2DebugInfo(...args) {
  if (isVoiceV2DebugLoggingEnabled()) console.info(...args);
}

function recordVoiceV2MoveTiming(event = "", details = {}) {
  const entry = {
    at: Date.now(),
    event: String(event || "unknown"),
    ...(details && typeof details === "object" ? details : {}),
  };
  voiceV2MoveTimingTrace.push(entry);
  while (voiceV2MoveTimingTrace.length > 100) voiceV2MoveTimingTrace.shift();
  voiceV2DebugInfo("[voice-v2-timing] " + entry.event, entry);
  return entry;
}

function normalizeVoiceV2AssignmentTimestamp(value, fallback = 0) {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  const raw = String(value || "").trim();
  if (!raw) return fallback;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function getVoiceV2AssignmentNonce(payload = {}) {
  return String(
    payload?.assignmentNonce
    || payload?.assignment_nonce
    || payload?.voiceChannelNonce
    || payload?.voice_channel_nonce
    || payload?.nonce
    || ""
  ).trim();
}

function getVoiceV2AssignmentTimestamp(payload = {}, fallback = 0) {
  return normalizeVoiceV2AssignmentTimestamp(
    payload?.assignmentUpdatedAt
    || payload?.assignment_updated_at
    || payload?.voiceChannelUpdatedAt
    || payload?.voice_channel_updated_at
    || payload?.updatedAt
    || payload?.updated_at
    || payload?.createdAt
    || payload?.created_at
    || "",
    fallback
  );
}

function isVoiceV2AssignmentNewer(next = null, previous = null) {
  if (!previous) return true;
  if (!next) return false;
  const nextNonce = String(next.nonce || "").trim();
  const previousNonce = String(previous.nonce || "").trim();
  if (nextNonce && previousNonce && nextNonce === previousNonce) return true;
  const nextUpdatedAt = Number(next.updatedAt || 0);
  const previousUpdatedAt = Number(previous.updatedAt || 0);
  return nextUpdatedAt >= previousUpdatedAt;
}

function isServerVoiceV2Enabled() {
  try {
    // Server Voice V2 is the deployed server-voice transport. Keep an explicit
    // local opt-out for diagnostics without making fresh clients use legacy join.
    return localStorage.getItem("altara_voice_v2_enabled") !== "0";
  } catch (_) {
    return true;
  }
}

function isVoiceV2RpcFastPathEnabled() {
  try {
    return localStorage.getItem("altara_voice_v2_rpc_fast_enabled") === "1";
  } catch (_) {
    return false;
  }
}

function isVoiceV2DedicatedMoveEnabled() {
  try {
    return localStorage.getItem("altara_voice_v2_dedicated_move_disabled") !== "1";
  } catch (_) {
    return true;
  }
}

function isVoiceV2SfxEnabled() {
  try {
    return localStorage.getItem("altara_voice_v2_sfx_enabled") !== "0";
  } catch (_) {
    return true;
  }
}

function setVoiceV2SfxEnabled(value) {
  try {
    if (value) localStorage.removeItem("altara_voice_v2_sfx_enabled");
    else localStorage.setItem("altara_voice_v2_sfx_enabled", "0");
  } catch (_) {}
  return isVoiceV2SfxEnabled();
}

function markVoiceV2SfxPlayed(nonce = "", type = "move") {
  const key = `${String(type || "move").trim()}:${String(nonce || "").trim()}`;
  if (!String(nonce || "").trim()) return false;
  if (voiceV2SfxPlayedMoveNonces.has(key)) return false;
  voiceV2SfxPlayedMoveNonces.add(key);
  voiceV2SfxPlayedMoveNonceOrder.push(key);
  while (voiceV2SfxPlayedMoveNonceOrder.length > 120) {
    const oldKey = voiceV2SfxPlayedMoveNonceOrder.shift();
    if (oldKey) voiceV2SfxPlayedMoveNonces.delete(oldKey);
  }
  return true;
}

function playVoiceV2Sfx(type = "move", options = {}) {
  if (!isVoiceV2SfxEnabled()) return false;
  if (typeof window === "undefined") return false;
  const now = Date.now();
  if (now - voiceV2LastSfxAt < 45) return false;
  voiceV2LastSfxAt = now;
  const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextCtor) return false;
  try {
    if (!voiceV2SfxAudioContext || voiceV2SfxAudioContext.state === "closed") {
      voiceV2SfxAudioContext = new AudioContextCtor();
    }
    const ctx = voiceV2SfxAudioContext;
    if (ctx.state === "suspended" && typeof ctx.resume === "function") {
      void ctx.resume().catch(() => {});
    }
    const kind = String(type || "move").trim();
    const startedAt = ctx.currentTime;
    const notes = kind === "self_moved"
      ? [{ at: 0, freq: 520, duration: 0.075, gain: 0.035 }, { at: 0.075, freq: 780, duration: 0.085, gain: 0.03 }]
      : kind === "move_sent"
        ? [{ at: 0, freq: 360, duration: 0.08, gain: 0.026 }]
        : [{ at: 0, freq: 460, duration: 0.065, gain: 0.02 }];
    notes.forEach((note) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = kind === "move_sent" ? "triangle" : "sine";
      osc.frequency.setValueAtTime(note.freq, startedAt + note.at);
      gain.gain.setValueAtTime(0.0001, startedAt + note.at);
      gain.gain.exponentialRampToValueAtTime(note.gain, startedAt + note.at + 0.012);
      gain.gain.exponentialRampToValueAtTime(0.0001, startedAt + note.at + note.duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(startedAt + note.at);
      osc.stop(startedAt + note.at + note.duration + 0.015);
    });
    recordVoiceV2MoveTiming("sound_played", {
      type: kind,
      moveId: options.moveId || options.assignmentNonce || "",
      assignmentNonce: options.assignmentNonce || options.moveId || "",
      reason: options.reason || "",
    });
    return true;
  } catch (error) {
    console.warn("[voice-v2-sfx] failed", { type, message: error?.message || String(error || "unknown") });
    return false;
  }
}

function buildServerVoiceV2RoomName(serverId = "") {
  const sid = normId(serverId || "");
  return sid ? `server-voice-v2:${sid}` : "";
}

function parseServerVoiceV2RoomName(roomName = "") {
  const raw = String(roomName || "").trim();
  const prefix = "server-voice-v2:";
  if (!raw.startsWith(prefix)) return null;
  const serverId = normId(raw.slice(prefix.length));
  return serverId ? { serverId } : null;
}

function getServerVoiceV2LocalSessionId() {
  if (serverVoiceV2LocalSessionId) return serverVoiceV2LocalSessionId;
  const randomPart = (() => {
    try { return crypto.randomUUID(); } catch (_) { return `${Date.now()}-${Math.random().toString(16).slice(2)}`; }
  })();
  serverVoiceV2LocalSessionId = `web:${normId(state.user?.id || "anon")}:${randomPart}`;
  return serverVoiceV2LocalSessionId;
}

function createStableServerVoicePresenceSessionId(userId = "") {
  const randomPart = (() => {
    try { return crypto.randomUUID(); } catch (_) { return `${Date.now()}-${Math.random().toString(16).slice(2)}`; }
  })();
  return `web:${normId(userId || state.user?.id || "anon")}:${randomPart}`;
}

function isStableServerVoicePresenceDebugEnabled() {
  try {
    return localStorage.getItem("altara_debug_server_voice") === "1"
      || localStorage.getItem("altara_debug_voice_stability") === "1";
  } catch (_) {
    return false;
  }
}

function captureStableServerVoicePresenceContext(input = {}, { newSession = false } = {}) {
  const serverId = normId(input?.serverId || input?.server_id || "");
  const channelId = normId(input?.canonicalChannelId || input?.channelId || input?.channel_id || "");
  const conversationId = normId(input?.conversationId || input?.conversation_id || "");
  const userId = normId(input?.userId || input?.user_id || state.user?.id || "");
  if (!serverId || !channelId || !conversationId || !userId) return null;
  const previous = stableServerVoicePresenceContextByConversationId.get(conversationId) || null;
  const context = Object.freeze({
    serverId,
    canonicalChannelId: channelId,
    channelId,
    conversationId,
    roomName: String(input?.roomName || previous?.roomName || `server-voice:${conversationId}`).trim(),
    userId,
    sessionId: String(
      input?.sessionId
      || (!newSession ? previous?.sessionId : "")
      || createStableServerVoicePresenceSessionId(userId),
    ).trim(),
    joinedFromServerVoiceChannel: true,
    capturedAt: Number(input?.capturedAt || Date.now()),
  });
  stableServerVoicePresenceContextByConversationId.set(conversationId, context);
  return context;
}

function getStableServerVoicePresenceContext(conversationId = "") {
  const convId = normId(conversationId || serverVoiceTransportConversationId || callConversationId || "");
  if (convId && stableServerVoicePresenceContextByConversationId.has(convId)) {
    return stableServerVoicePresenceContextByConversationId.get(convId);
  }
  if (!convId || normId(currentStableServerVoicePresenceContext?.conversationId || "") === convId) {
    return currentStableServerVoicePresenceContext;
  }
  return null;
}

async function publishStableServerVoicePresence(context = null, reason = "stable_join") {
  const captured = context || getStableServerVoicePresenceContext();
  if (!captured?.serverId || !captured?.canonicalChannelId || !captured?.conversationId || !captured?.sessionId) {
    return { ok: false, error: "missing_stable_server_voice_context" };
  }
  const key = captured.conversationId;
  if (stableServerVoicePresenceWriteInFlightByConversationId.has(key)) {
    return stableServerVoicePresenceWriteInFlightByConversationId.get(key);
  }

  const request = (async () => {
    const assignmentNonce = `stable-join:${captured.sessionId}`;
    const payload = buildServerVoiceV2ControlPlaneRow({
      serverId: captured.serverId,
      userId: captured.userId,
      channelId: captured.canonicalChannelId,
      conversationId: captured.conversationId,
      sessionId: captured.sessionId,
      roomName: captured.roomName,
      assignmentNonce,
      assignmentUpdatedAt: Date.now(),
    });
    lastStableServerVoicePresenceWrite = {
      at: Date.now(),
      reason,
      attempted: true,
      succeeded: false,
      payload: { ...payload },
      error: null,
      readback: null,
    };
    recordServerVoiceV2PresenceLifecycle("presence_upsert_attempted", {
      reason,
      payload: { ...payload },
      stableServerVoice: true,
    });

    const write = await supabase
      .from("server_voice_members_v2")
      .upsert(payload, { onConflict: "server_id,user_id" })
      .select("*")
      .maybeSingle();
    if (write.error) {
      const errorDetails = {
        code: String(write.error?.code || ""),
        message: String(write.error?.message || write.error || "presence_upsert_failed"),
        details: String(write.error?.details || ""),
        hint: String(write.error?.hint || ""),
      };
      lastStableServerVoicePresenceWrite = {
        ...lastStableServerVoicePresenceWrite,
        error: errorDetails,
      };
      recordServerVoiceV2PresenceLifecycle("presence_upsert_failed", {
        reason,
        payload: { ...payload },
        error: errorDetails,
        stableServerVoice: true,
      });
      if (isStableServerVoicePresenceDebugEnabled()) {
        console.warn("[server-voice presence] upsert failed", {
          reason,
          payload,
          ...errorDetails,
        });
      }
      return { ok: false, error: "presence_upsert_failed", details: errorDetails, payload };
    }

    let persisted = write.data ? normalizeServerVoiceV2MemberRow(write.data) : null;
    if (!persisted?.userId) {
      const readback = await supabase
        .from("server_voice_members_v2")
        .select("*")
        .eq("server_id", captured.serverId)
        .eq("user_id", captured.userId)
        .maybeSingle();
      if (readback.error) {
        const errorDetails = {
          code: String(readback.error?.code || ""),
          message: String(readback.error?.message || readback.error || "presence_readback_failed"),
          details: String(readback.error?.details || ""),
          hint: String(readback.error?.hint || ""),
        };
        lastStableServerVoicePresenceWrite = {
          ...lastStableServerVoicePresenceWrite,
          error: errorDetails,
        };
        return { ok: false, error: "presence_readback_failed", details: errorDetails, payload };
      }
      persisted = readback.data ? normalizeServerVoiceV2MemberRow(readback.data) : null;
    }

    const readbackMatches = !!(
      persisted
      && persisted.serverId === captured.serverId
      && persisted.userId === captured.userId
      && persisted.channelId === captured.canonicalChannelId
      && persisted.conversationId === captured.conversationId
      && persisted.sessionId === captured.sessionId
      && persisted.roomName === captured.roomName
    );
    lastStableServerVoicePresenceReadback = {
      at: Date.now(),
      reason,
      readbackMatches,
      row: persisted ? { ...persisted } : null,
    };
    lastStableServerVoicePresenceWrite = {
      ...lastStableServerVoicePresenceWrite,
      succeeded: readbackMatches,
      readback: lastStableServerVoicePresenceReadback,
    };
    recordServerVoiceV2PresenceLifecycle("presence_readback", {
      reason,
      readbackMatches,
      row: persisted ? { ...persisted } : null,
      stableServerVoice: true,
    });
    if (!readbackMatches) {
      return { ok: false, error: "presence_readback_mismatch", payload, row: persisted };
    }

    currentStableServerVoicePresenceContext = captured;
    upsertServerVoiceV2MemberRow(persisted, `stable_${reason}`, { render: false });
    await broadcastServerVoiceV2ControlPlaneRow(write.data || payload).catch(() => false);
    if (isStableServerVoicePresenceDebugEnabled()) {
      console.info("[server-voice presence] upserted", {
        reason,
        payload,
        row: persisted,
      });
    }
    return { ok: true, payload, row: persisted };
  })().finally(() => {
    stableServerVoicePresenceWriteInFlightByConversationId.delete(key);
  });
  stableServerVoicePresenceWriteInFlightByConversationId.set(key, request);
  return request;
}

async function repairCurrentServerVoicePresence(reason = "manual_repair") {
  const context = currentStableServerVoicePresenceContext;
  const snapshot = serverVoiceTransportController?.getSnapshot?.() || null;
  if (!context || snapshot?.connected !== true) {
    return { ok: false, skipped: true, error: "stable_server_voice_not_connected" };
  }
  const cached = getCurrentUserServerVoiceV2Member();
  if (
    cached
    && cached.serverId === context.serverId
    && cached.channelId === context.canonicalChannelId
    && cached.sessionId === context.sessionId
    && cached.roomName === context.roomName
  ) {
    if (!serverVoiceV2HeartbeatTimer) startServerVoiceV2Heartbeat();
    return { ok: true, repaired: false, row: cached };
  }

  stableServerVoicePresenceRepairCount += 1;
  const result = await publishStableServerVoicePresence(context, reason);
  if (result?.ok && !serverVoiceV2HeartbeatTimer) startServerVoiceV2Heartbeat();
  return { ...result, repaired: result?.ok === true };
}

function scheduleStableServerVoicePresenceRepair(reason = "join_write_failed") {
  const context = currentStableServerVoicePresenceContext;
  if (!context) return false;
  [350, 1100, 2600].forEach((delayMs, index) => {
    setTimeout(() => {
      const active = currentStableServerVoicePresenceContext;
      const cached = getCurrentUserServerVoiceV2Member();
      if (!active || active.sessionId !== context.sessionId) return;
      if (cached?.sessionId === context.sessionId) return;
      void repairCurrentServerVoicePresence(`${reason}:${index + 1}`).catch(() => false);
    }, delayMs);
  });
  return true;
}

async function deleteStableServerVoicePresence(context = null, reason = "leave") {
  const captured = context || currentStableServerVoicePresenceContext || getStableServerVoicePresenceContext();
  if (!captured?.serverId || !captured?.userId || !captured?.sessionId) return false;
  lastStableServerVoicePresenceDeleteReason = String(reason || "leave");
  if (normId(currentStableServerVoicePresenceContext?.conversationId || "") === captured.conversationId) {
    currentStableServerVoicePresenceContext = null;
  }
  stableServerVoicePresenceContextByConversationId.delete(captured.conversationId);
  const cached = serverVoiceV2MembersByUser.get(captured.userId) || null;
  if (!cached || cached.sessionId === captured.sessionId) {
    deleteServerVoiceV2MemberRow({ user_id: captured.userId }, `stable_${reason}`);
  }
  const deletion = await supabase
    .from("server_voice_members_v2")
    .delete()
    .eq("server_id", captured.serverId)
    .eq("user_id", captured.userId)
    .eq("session_id", captured.sessionId);
  recordServerVoiceV2PresenceLifecycle(deletion.error ? "presence_delete_failed" : "presence_deleted", {
    reason,
    serverId: captured.serverId,
    userId: captured.userId,
    sessionId: captured.sessionId,
    stableServerVoice: true,
    error: deletion.error ? String(deletion.error?.message || deletion.error) : null,
  });
  return !deletion.error;
}

function normalizeServerVoiceV2MemberRow(row = {}) {
  const serverId = normId(row?.server_id || row?.serverId || "");
  const userId = normId(row?.user_id || row?.userId || "");
  const channelId = normId(row?.channel_id || row?.channelId || row?.voiceChannelId || "");
  const conversationId = normId(row?.conversation_id || row?.conversationId || "");
  const assignmentUpdatedAtRaw = row?.assignment_updated_at || row?.assignmentUpdatedAt || row?.updated_at || row?.updatedAt || "";
  return {
    serverId,
    userId,
    channelId,
    voiceChannelId: channelId,
    conversationId,
    sessionId: String(row?.session_id || row?.sessionId || "").trim(),
    roomName: String(row?.room_name || row?.roomName || "").trim(),
    voiceMode: String(row?.voice_mode || row?.voiceMode || "server_room_v2").trim() || "server_room_v2",
    joinedAt: row?.joined_at || row?.joinedAt || "",
    updatedAt: normalizeVoiceV2AssignmentTimestamp(row?.updated_at || row?.updatedAt || assignmentUpdatedAtRaw, Date.now()),
    heartbeatAt: row?.heartbeat_at || row?.heartbeatAt || "",
    assignmentNonce: String(row?.assignment_nonce || row?.assignmentNonce || row?.voiceChannelNonce || "").trim(),
    assignmentUpdatedAt: normalizeVoiceV2AssignmentTimestamp(assignmentUpdatedAtRaw, Date.now()),
    selfMuted: !!(row?.self_muted ?? row?.selfMuted),
    selfDeafened: !!(row?.self_deafened ?? row?.selfDeafened),
    serverMuted: !!(row?.server_muted ?? row?.serverMuted),
    serverDeafened: !!(row?.server_deafened ?? row?.serverDeafened),
    serverMuteBy: normId(row?.server_mute_by || row?.serverMuteBy || ""),
    serverDeafenBy: normId(row?.server_deafen_by || row?.serverDeafenBy || ""),
  };
}

function getServerVoiceV2RowHeartbeatTime(row = {}) {
  const values = [
    row?.heartbeatAt,
    row?.heartbeat_at,
    row?.updatedAt,
    row?.updated_at,
  ];
  for (const value of values) {
    if (typeof value === "number" && Number.isFinite(value)) return value;
    const raw = String(value || "").trim();
    if (!raw) continue;
    const parsed = Date.parse(raw);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function isServerVoiceV2MemberRowFresh(row = {}, now = Date.now()) {
  const heartbeatMs = getServerVoiceV2RowHeartbeatTime(row);
  return Boolean(heartbeatMs && now - heartbeatMs <= SERVER_VOICE_V2_STALE_MEMBER_MS);
}

function getServerVoiceV2FreshRows(rows = Array.from(serverVoiceV2MembersByUser.values()), now = Date.now()) {
  return (Array.isArray(rows) ? rows : []).filter((row) => isServerVoiceV2MemberRowFresh(row, now));
}

function getServerVoiceV2StaleRows(rows = Array.from(serverVoiceV2MembersByUser.values()), now = Date.now()) {
  return (Array.isArray(rows) ? rows : []).filter((row) => !isServerVoiceV2MemberRowFresh(row, now));
}

function isServerVoiceV2MemberRowNewer(next = null, previous = null) {
  if (!previous) return true;
  if (!next) return false;
  const nextNonce = String(next.assignmentNonce || "").trim();
  const previousNonce = String(previous.assignmentNonce || "").trim();
  if (nextNonce && previousNonce && nextNonce === previousNonce) return true;
  const nextAssignmentAt = Number(next.assignmentUpdatedAt || 0);
  const previousAssignmentAt = Number(previous.assignmentUpdatedAt || 0);
  if (nextAssignmentAt || previousAssignmentAt) return nextAssignmentAt >= previousAssignmentAt;
  return Number(next.updatedAt || 0) >= Number(previous.updatedAt || 0);
}

function syncCurrentServerVoiceV2SessionFromControlRow(row = {}, reason = "control_plane") {
  const normalized = normalizeServerVoiceV2MemberRow(row);
  if (!normalized.serverId || !normalized.userId || !normalized.channelId) return false;
  currentServerVoiceV2Session = {
    ...(currentServerVoiceV2Session || {}),
    serverId: normalized.serverId,
    roomName: normalized.roomName || buildServerVoiceV2RoomName(normalized.serverId),
    voiceChannelId: normalized.channelId,
    channelId: normalized.channelId,
    conversationId: normalized.conversationId,
    sessionId: normalized.sessionId,
    participantIdentity: normalized.userId,
    controller: currentServerVoiceV2Session?.controller || serverVoiceTransportController || null,
    room: currentServerVoiceV2Session?.room || serverVoiceTransportController?.room || null,
    assignmentNonce: normalized.assignmentNonce,
    assignmentUpdatedAt: normalized.assignmentUpdatedAt,
    updatedAt: Date.now(),
  };
  if (normalized.conversationId) {
    callConversationId = normalized.conversationId;
    if (isServerVoiceConversationById(activeDmId || "")) activeDmId = normalized.conversationId;
    if (state.activeDm && isServerVoiceConversationById(state.activeDm.conversationId || "")) {
      state.activeDm = {
        ...state.activeDm,
        conversationId: normalized.conversationId,
        serverId: normalized.serverId,
        channelId: normalized.channelId,
        displayName: getServerVoiceV2ChannelNameById(normalized.channelId) || state.activeDm.displayName,
      };
    }
  }
  console.info("[voice-v2-control] current session synced from row", {
    reason,
    row: normalized,
    currentServerVoiceV2Session,
  });
  return true;
}

function renderServerVoiceV2FromControlPlane(reason = "control_plane") {
  console.info("[voice-v2-control] render from control plane", {
    reason,
    currentChannelId: getCurrentVoiceV2ChannelId(),
    rowCount: getServerVoiceV2FreshRows().length,
    staleRowCount: getServerVoiceV2StaleRows().length,
  });
  refreshServerVoiceChannelBadges();
  refreshCallUI();
}

function purgeStaleServerVoiceV2Members(reason = "stale_purge") {
  if (!isServerVoiceV2Enabled()) return [];
  const now = Date.now();
  const removed = [];
  for (const [userId, row] of serverVoiceV2MembersByUser.entries()) {
    if (isServerVoiceV2MemberRowFresh(row, now)) continue;
    serverVoiceV2MembersByUser.delete(userId);
    voiceV2ChannelAssignmentsByUser.delete(userId);
    const rowServerId = normId(row?.serverId || "");
    const serverSnapshot = rowServerId ? serverVoiceOccupancySnapshotByServerId.get(rowServerId) : null;
    if (serverSnapshot instanceof Map) serverSnapshot.delete(userId);
    removed.push({
      userId,
      row,
      ageMs: now - getServerVoiceV2RowHeartbeatTime(row),
    });
  }
  if (!removed.length) return [];
  recordServerVoiceV2PresenceLifecycle("presence_pruned", {
    reason,
    removed: removed.map((entry) => ({
      userId: entry.userId,
      channelId: entry.row?.channelId || "",
      sessionId: entry.row?.sessionId || "",
      roomName: entry.row?.roomName || "",
      ageMs: entry.ageMs,
    })),
  });
  console.info("[voice-v2-control] stale rows purged", {
    reason,
    staleMemberMs: SERVER_VOICE_V2_STALE_MEMBER_MS,
    removed,
  });
  refreshServerVoiceChannelBadges();
  refreshCallUI();
  reconcileVoiceV2Subscriptions(`stale_purge:${reason}`);
  return removed;
}

function applyServerVoiceV2MemberRow(row = {}, reason = "unknown", options = {}) {
  const normalized = normalizeServerVoiceV2MemberRow(row);
  if (!normalized.serverId || !normalized.userId || !normalized.channelId) {
    console.warn("[voice-v2-control] invalid row ignored", { reason, rawRow: row, row: normalized });
    return false;
  }
  if (!isServerVoiceV2MemberRowFresh(normalized)) {
    const previous = serverVoiceV2MembersByUser.get(normalized.userId) || null;
    let removedCachedRow = false;
    if (previous && !isServerVoiceV2MemberRowFresh(previous)) {
      serverVoiceV2MembersByUser.delete(normalized.userId);
      voiceV2ChannelAssignmentsByUser.delete(normalized.userId);
      removedCachedRow = true;
    }
    console.warn("[voice-v2-control] stale member row ignored", {
      reason,
      incoming: normalized,
      heartbeatAgeMs: Date.now() - getServerVoiceV2RowHeartbeatTime(normalized),
      staleMemberMs: SERVER_VOICE_V2_STALE_MEMBER_MS,
    });
    if (removedCachedRow && options?.render !== false) {
      refreshServerVoiceChannelBadges();
      refreshCallUI();
      reconcileVoiceV2Subscriptions(`stale_row:${reason}`);
    }
    return false;
  }
  const previous = serverVoiceV2MembersByUser.get(normalized.userId) || null;
  if (!isServerVoiceV2MemberRowNewer(normalized, previous)) {
    console.warn("[voice-v2-control] stale row ignored", { reason, incoming: normalized, current: previous });
    return false;
  }
  const meId = normId(state.user?.id || "");
  const previousChannelId = normId(previous?.channelId || "");
  const nextChannelId = normId(normalized.channelId || "");
  const channelChanged = !!previousChannelId && !!nextChannelId && previousChannelId !== nextChannelId;
  serverVoiceV2MembersByUser.set(normalized.userId, normalized);
  const serverSnapshot = serverVoiceOccupancySnapshotByServerId.get(normalized.serverId) || new Map();
  serverSnapshot.set(normalized.userId, normalized);
  serverVoiceOccupancySnapshotByServerId.set(normalized.serverId, serverSnapshot);
  console.info("[voice-v2-control] row applied", { reason, row: normalized });
  recordVoiceV2MoveTiming("row_applied", {
    moveId: normalized.assignmentNonce,
    assignmentNonce: normalized.assignmentNonce,
    userId: normalized.userId,
    channelId: normalized.channelId,
    reason,
  });
  const allowSfx = options?.sound !== false && options?.render !== false;
  if (allowSfx && String(reason || "") === "drag_optimistic" && markVoiceV2SfxPlayed(normalized.assignmentNonce, "move_sent")) {
    playVoiceV2Sfx("move_sent", {
      moveId: normalized.assignmentNonce,
      assignmentNonce: normalized.assignmentNonce,
      reason,
    });
  } else if (allowSfx && normalized.userId === meId && channelChanged && markVoiceV2SfxPlayed(normalized.assignmentNonce, "self_moved")) {
    playVoiceV2Sfx("self_moved", {
      moveId: normalized.assignmentNonce,
      assignmentNonce: normalized.assignmentNonce,
      reason,
    });
  }
  if (normalized.userId === meId) {
    syncCurrentServerVoiceV2SessionFromControlRow(normalized, reason);
  }
  if (options?.render === false) return true;
  voiceV2DebugInfo("[voice-v2-snappy] immediate render", {
    reason,
    userId: normalized.userId,
    channelId: normalized.channelId,
  });
  recordVoiceV2MoveTiming("immediate_render_start", {
    moveId: normalized.assignmentNonce,
    assignmentNonce: normalized.assignmentNonce,
    userId: normalized.userId,
    channelId: normalized.channelId,
    reason,
  });
  renderServerVoiceV2FromControlPlane(reason);
  recordVoiceV2MoveTiming("immediate_render_done", {
    moveId: normalized.assignmentNonce,
    assignmentNonce: normalized.assignmentNonce,
    userId: normalized.userId,
    channelId: normalized.channelId,
    reason,
  });
  recordVoiceV2MoveTiming("render_done", {
    moveId: normalized.assignmentNonce,
    assignmentNonce: normalized.assignmentNonce,
    userId: normalized.userId,
    channelId: normalized.channelId,
    reason,
  });
  recordVoiceV2MoveTiming("subscriptions_start", {
    moveId: normalized.assignmentNonce,
    assignmentNonce: normalized.assignmentNonce,
    userId: normalized.userId,
    channelId: normalized.channelId,
    reason,
  });
  reconcileVoiceV2Subscriptions(`control_plane:${reason}`);
  recordVoiceV2MoveTiming("subscriptions_done", {
    moveId: normalized.assignmentNonce,
    assignmentNonce: normalized.assignmentNonce,
    userId: normalized.userId,
    channelId: normalized.channelId,
    reason,
  });
  return true;
}

function upsertServerVoiceV2MemberRow(row = {}, reason = "unknown", options = {}) {
  return applyServerVoiceV2MemberRow(row, reason, options);
}

function deleteServerVoiceV2MemberRow(row = {}, reason = "delete") {
  const userId = normId(row?.user_id || row?.userId || "");
  if (!userId) return false;
  const serverId = normId(row?.server_id || row?.serverId || serverVoiceV2MembersByUser.get(userId)?.serverId || "");
  const cached = serverVoiceV2MembersByUser.get(userId) || null;
  if (!serverId || normId(cached?.serverId || "") === serverId) serverVoiceV2MembersByUser.delete(userId);
  const serverSnapshot = serverId ? serverVoiceOccupancySnapshotByServerId.get(serverId) : null;
  if (serverSnapshot instanceof Map) serverSnapshot.delete(userId);
  voiceV2ChannelAssignmentsByUser.delete(userId);
  recordServerVoiceV2PresenceLifecycle("presence_cache_deleted", { reason, serverId, userId });
  console.info("[voice-v2-control] row delete", { reason, serverId, userId });
  refreshServerVoiceChannelBadges();
  refreshCallUI();
  reconcileVoiceV2Subscriptions(`control_plane:${reason}`);
  return true;
}

function getServerVoiceV2Member(userId = "") {
  const row = serverVoiceV2MembersByUser.get(normId(userId || "")) || null;
  return row && isServerVoiceV2MemberRowFresh(row) ? row : null;
}

function getCurrentUserServerVoiceV2Member() {
  return getServerVoiceV2Member(state.user?.id || "");
}

function getServerVoiceV2ChannelMembers(channelId = "", serverId = "") {
  const cid = normId(channelId || "");
  const sid = normId(serverId || "");
  if (!cid) return [];
  return Array.from(serverVoiceV2MembersByUser.values())
    .filter((row) => isServerVoiceV2MemberRowFresh(row))
    .filter((row) => !sid || normId(row?.serverId || "") === sid)
    .filter((row) => normId(row?.channelId || "") === cid)
    .sort((a, b) => String(a.userId).localeCompare(String(b.userId)));
}

function isCurrentUserInServerVoiceV2() {
  return !!getCurrentUserServerVoiceV2Member();
}

function getServerVoiceV2ChannelNameById(channelId = "") {
  const cid = normId(channelId || "");
  if (!cid) return "";
  const ctx = findServerChannelContextByChannelId(cid, currentServerVoiceV2Session?.serverId || state.activeServerId || state.currentServerId || "") || null;
  return String(ctx?.channel?.name || "").trim();
}

function buildServerVoiceV2ControlPlaneRow({
  serverId = "",
  userId = "",
  channelId = "",
  conversationId = "",
  sessionId = "",
  roomName = "",
  assignmentNonce = "",
  assignmentUpdatedAt = "",
} = {}) {
  const updatedAtIso = assignmentUpdatedAt
    ? new Date(normalizeVoiceV2AssignmentTimestamp(assignmentUpdatedAt, Date.now())).toISOString()
    : new Date().toISOString();
  return {
    server_id: normId(serverId || ""),
    user_id: normId(userId || state.user?.id || ""),
    channel_id: normId(channelId || ""),
    conversation_id: normId(conversationId || "") || null,
    session_id: String(sessionId || getServerVoiceV2LocalSessionId()).trim(),
    room_name: String(roomName || buildServerVoiceV2RoomName(serverId)).trim(),
    voice_mode: "server_room_v2",
    heartbeat_at: new Date().toISOString(),
    assignment_nonce: String(assignmentNonce || "").trim() || `local:${Date.now()}:${channelId}`,
    assignment_updated_at: updatedAtIso,
  };
}

function getServerVoiceOccupancyHydrationState(serverId = "") {
  const sid = normId(serverId || "");
  const current = sid ? serverVoiceOccupancyHydrationStateByServerId.get(sid) : null;
  return {
    serverId: sid,
    status: String(current?.status || "idle"),
    loaded: current?.loaded === true,
    inFlight: !!(sid && serverVoiceOccupancyRefreshInFlightByServerId.has(sid)),
    lastAuthoritativeFetchAt: Number(current?.lastAuthoritativeFetchAt || 0),
    lastTriggerReason: String(current?.lastTriggerReason || ""),
    realtimeStatus: String(current?.realtimeStatus || ""),
    snapshotFingerprint: String(current?.snapshotFingerprint || ""),
    lastError: current?.lastError || null,
  };
}

function getServerVoiceOccupancySnapshotRows(serverId = "") {
  const sid = normId(serverId || "");
  const rows = sid ? serverVoiceOccupancySnapshotByServerId.get(sid) : null;
  return rows instanceof Map ? Array.from(rows.values()) : [];
}

function buildServerVoiceOccupancySnapshotFingerprint(rows = []) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => normalizeServerVoiceV2MemberRow(row))
    .filter((row) => row.userId && row.channelId)
    .sort((a, b) => a.userId.localeCompare(b.userId))
    .map((row) => [
      row.userId,
      row.channelId,
      row.conversationId,
      row.sessionId,
      row.selfMuted ? 1 : 0,
      row.selfDeafened ? 1 : 0,
      row.serverMuted ? 1 : 0,
      row.serverDeafened ? 1 : 0,
    ].join(":"))
    .join("|");
}

function getVisibleServerVoiceChannelIds(serverId = "") {
  const sid = normId(serverId || "");
  return new Set(
    (serverChannelListByServerId.get(sid) || [])
      .filter((channel) => normalizeConversationChannelType(channel?.channelType || "") === "voice")
      .map((channel) => normId(channel?.id || channel?.channelId || channel?.channel_id || ""))
      .filter(Boolean)
  );
}

function reprojectServerVoiceOccupancy(serverId = "", reason = "visibility_changed") {
  const sid = normId(serverId || "");
  if (!sid) return false;
  const activeSid = normId(getActiveServerContext?.()?.serverId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
  lastServerVoiceOccupancyVisibilityTransition = {
    serverId: sid,
    reason: String(reason || "visibility_changed"),
    visibleVoiceChannelIds: Array.from(getVisibleServerVoiceChannelIds(sid)),
    snapshotRowCount: getServerVoiceOccupancySnapshotRows(sid).length,
    at: Date.now(),
  };
  if (activeSid !== sid) return false;
  refreshServerVoiceChannelBadges();
  return true;
}

function applyAuthoritativeServerVoiceOccupancySnapshot(serverId = "", rows = [], reason = "snapshot") {
  const sid = normId(serverId || "");
  if (!sid) return { changed: false, rows: [] };
  const nextRows = new Map();
  (Array.isArray(rows) ? rows : []).forEach((rawRow) => {
    const row = normalizeServerVoiceV2MemberRow(rawRow);
    if (row.serverId !== sid || !row.userId || !row.channelId || !isServerVoiceV2MemberRowFresh(row)) return;
    const current = nextRows.get(row.userId) || null;
    if (!current || isServerVoiceV2MemberRowNewer(row, current)) nextRows.set(row.userId, row);
  });
  const previousRows = serverVoiceOccupancySnapshotByServerId.get(sid) || new Map();
  const previousFingerprint = buildServerVoiceOccupancySnapshotFingerprint(Array.from(previousRows.values()));
  const nextFingerprint = buildServerVoiceOccupancySnapshotFingerprint(Array.from(nextRows.values()));
  const changed = previousFingerprint !== nextFingerprint;

  serverVoiceOccupancySnapshotByServerId.set(sid, nextRows);
  for (const [userId, row] of Array.from(serverVoiceV2MembersByUser.entries())) {
    if (normId(row?.serverId || "") === sid && !nextRows.has(userId)) {
      serverVoiceV2MembersByUser.delete(userId);
      voiceV2ChannelAssignmentsByUser.delete(userId);
    }
  }
  nextRows.forEach((row, userId) => {
    serverVoiceV2MembersByUser.set(userId, row);
  });
  return { changed, rows: Array.from(nextRows.values()), fingerprint: nextFingerprint };
}

function scheduleServerVoiceOccupancyHydration(serverId = "", reason = "scheduled", {
  delayMs = 0,
  ensureSubscription = true,
} = {}) {
  const sid = normId(serverId || "");
  if (!sid || !isServerVoiceV2Enabled()) return false;
  reprojectServerVoiceOccupancy(sid, `${reason}:cached`);
  if (serverVoiceOccupancyRefreshTimerByServerId.has(sid)) {
    clearTimeout(serverVoiceOccupancyRefreshTimerByServerId.get(sid));
  }
  const timer = setTimeout(() => {
    serverVoiceOccupancyRefreshTimerByServerId.delete(sid);
    if (ensureSubscription) {
      void ensureServerVoiceV2ControlPlaneSubscription(sid, {
        hydrate: true,
        reason,
      }).catch(() => false);
    } else {
      void loadServerVoiceV2ControlPlaneSnapshot(sid, reason).catch(() => false);
    }
  }, Math.max(0, Number(delayMs || 0)));
  serverVoiceOccupancyRefreshTimerByServerId.set(sid, timer);
  return true;
}

async function loadServerVoiceV2ControlPlaneSnapshot(serverId = "", reason = "manual") {
  const sid = normId(serverId || currentServerVoiceV2Session?.serverId || state.activeServerId || state.currentServerId || "");
  if (!sid || !isServerVoiceV2Enabled()) return false;
  if (serverVoiceOccupancyRefreshInFlightByServerId.has(sid)) {
    return serverVoiceOccupancyRefreshInFlightByServerId.get(sid);
  }
  const requestRealtimeVersion = Number(serverVoiceOccupancyRealtimeVersionByServerId.get(sid) || 0);
  const previousState = getServerVoiceOccupancyHydrationState(sid);
  serverVoiceOccupancyHydrationStateByServerId.set(sid, {
    ...previousState,
    status: previousState.loaded ? "refreshing" : "loading",
    lastTriggerReason: String(reason || "manual"),
    lastError: null,
  });

  const request = (async () => {
    void callServerVoiceV2CleanupRpc(sid, `snapshot:${reason}`).catch(() => false);
    const freshSinceIso = new Date(Date.now() - SERVER_VOICE_V2_STALE_MEMBER_MS).toISOString();
    let { data, error } = await supabase
      .from("server_voice_members_v2")
      .select("*")
      .eq("server_id", sid)
      .gte("heartbeat_at", freshSinceIso);
    if (error) {
      console.warn("[voice-v2-control] fresh snapshot load failed; falling back to local stale filter", {
        serverId: sid,
        reason,
        message: error?.message || String(error || "unknown"),
      });
      const fallback = await supabase
        .from("server_voice_members_v2")
        .select("*")
        .eq("server_id", sid);
      data = fallback.data;
      error = fallback.error;
      if (error) {
        const lastError = {
          code: String(error?.code || ""),
          message: String(error?.message || error || "unknown"),
        };
        serverVoiceOccupancyHydrationStateByServerId.set(sid, {
          ...getServerVoiceOccupancyHydrationState(sid),
          status: previousState.loaded ? "ready" : "error",
          loaded: previousState.loaded,
          lastTriggerReason: String(reason || "manual"),
          lastError,
        });
        console.warn("[voice-v2-control] snapshot load failed", { serverId: sid, reason, ...lastError });
        return false;
      }
    }

    if (Number(serverVoiceOccupancyRealtimeVersionByServerId.get(sid) || 0) !== requestRealtimeVersion) {
      serverVoiceOccupancyStaleResponsesIgnored += 1;
      setTimeout(() => {
        void loadServerVoiceV2ControlPlaneSnapshot(sid, `${reason}:realtime_race_retry`).catch(() => false);
      }, 80);
      return false;
    }

    const applied = applyAuthoritativeServerVoiceOccupancySnapshot(sid, data || [], reason);
    serverVoiceOccupancyHydrationStateByServerId.set(sid, {
      ...getServerVoiceOccupancyHydrationState(sid),
      status: "ready",
      loaded: true,
      lastAuthoritativeFetchAt: Date.now(),
      lastTriggerReason: String(reason || "manual"),
      snapshotFingerprint: applied.fingerprint || "",
      lastError: null,
    });
    if (isStableServerVoicePresenceDebugEnabled()) {
      console.info("[voice-v2-control] authoritative server snapshot loaded", {
        serverId: sid,
        reason,
        count: applied.rows.length,
        changed: applied.changed,
        freshSinceIso,
      });
    }
    if (applied.changed || !previousState.loaded) {
      reprojectServerVoiceOccupancy(sid, `${reason}:authoritative`);
    }
    if (applied.changed) {
      refreshCallUI();
      reconcileVoiceV2Subscriptions(`snapshot:${reason}`);
    }
    const stableContext = currentStableServerVoicePresenceContext;
    const currentRow = getCurrentUserServerVoiceV2Member();
    const connected = serverVoiceTransportController?.getSnapshot?.()?.connected === true;
    if (
      connected
      && stableContext?.serverId === sid
      && currentRow?.sessionId !== stableContext.sessionId
    ) {
      void repairCurrentServerVoicePresence(`snapshot_missing:${reason}`).catch(() => false);
    }
    return true;
  })().finally(() => {
    serverVoiceOccupancyRefreshInFlightByServerId.delete(sid);
  });
  serverVoiceOccupancyRefreshInFlightByServerId.set(sid, request);
  return request;
}

function handleServerVoiceV2ControlBroadcast(payload = {}) {
  const row = payload?.row || payload?.member || payload;
  recordVoiceV2MoveTiming("broadcast_received", {
    moveId: payload?.moveId || payload?.move_id || row?.assignmentNonce || row?.assignment_nonce || "",
    assignmentNonce: payload?.assignmentNonce || payload?.assignment_nonce || row?.assignmentNonce || row?.assignment_nonce || "",
    targetUserId: row?.userId || row?.user_id || payload?.targetUserId || payload?.target_user_id || "",
    targetChannelId: row?.channelId || row?.channel_id || payload?.targetChannelId || payload?.target_channel_id || "",
    source: "broadcast",
  });
  if (payload?.event === "DELETE" || payload?.type === "DELETE" || payload?.deleted === true) {
    deleteServerVoiceV2MemberRow(row, "broadcast");
    return;
  }
  upsertServerVoiceV2MemberRow(row, "broadcast");
}

async function callServerVoiceV2CleanupRpc(serverId = "", reason = "manual") {
  if (!isServerVoiceV2Enabled()) return false;
  const sid = normId(
    serverId
    || currentServerVoiceV2Session?.serverId
    || serverVoiceV2ControlPlaneServerId
    || state.activeServerId
    || state.currentServerId
    || ""
  );
  if (!sid) return false;
  try {
    const { error } = await supabase.rpc("cleanup_stale_server_voice_presence_v2", {
      p_server_id: sid,
    });
    if (error) {
      if (!serverVoiceV2CleanupRpcWarned) {
        serverVoiceV2CleanupRpcWarned = true;
        console.warn("[voice-v2] stale cleanup rpc unavailable", {
          reason,
          message: error?.message || String(error || "unknown"),
        });
      }
      return false;
    }
    return true;
  } catch (error) {
    if (!serverVoiceV2CleanupRpcWarned) {
      serverVoiceV2CleanupRpcWarned = true;
      console.warn("[voice-v2] stale cleanup rpc unavailable", {
        reason,
        message: error?.message || String(error || "unknown"),
      });
    }
    return false;
  }
}

async function ensureServerVoiceV2ControlPlaneSubscription(serverId = "", options = {}) {
  const sid = normId(serverId || currentServerVoiceV2Session?.serverId || state.activeServerId || state.currentServerId || "");
  if (!sid || !isServerVoiceV2Enabled()) return false;
  const reason = String(options?.reason || "ensure_subscription");
  const connectedServerId = normId(currentServerVoiceV2Session?.serverId || currentStableServerVoicePresenceContext?.serverId || "");
  for (const [otherServerId, otherChannel] of Array.from(serverVoiceOccupancyChannelByServerId.entries())) {
    if (otherServerId === sid || (connectedServerId && otherServerId === connectedServerId)) continue;
    try { supabase.removeChannel(otherChannel); } catch (_) {}
    serverVoiceOccupancyChannelByServerId.delete(otherServerId);
  }
  const existingChannel = serverVoiceOccupancyChannelByServerId.get(sid) || null;
  if (existingChannel && options?.force !== true) {
    if (normId(currentServerVoiceV2Session?.serverId || "") === sid) {
      serverVoiceV2ControlPlaneChannel = existingChannel;
      serverVoiceV2ControlPlaneServerId = sid;
    }
    if (options?.hydrate !== false) {
      await loadServerVoiceV2ControlPlaneSnapshot(sid, reason).catch(() => false);
    }
    return true;
  }
  if (existingChannel) {
    try { supabase.removeChannel(existingChannel); } catch (_) {}
    serverVoiceOccupancyChannelByServerId.delete(sid);
    if (serverVoiceV2ControlPlaneChannel === existingChannel) {
      serverVoiceV2ControlPlaneChannel = null;
      serverVoiceV2ControlPlaneServerId = "";
    }
  }
  if (serverVoiceOccupancyResubscribeTimerByServerId.has(sid)) {
    clearTimeout(serverVoiceOccupancyResubscribeTimerByServerId.get(sid));
    serverVoiceOccupancyResubscribeTimerByServerId.delete(sid);
  }
  const channelName = `server_voice_v2:${sid}`;
  const controlChannel = supabase.channel(channelName, { config: { broadcast: { self: true } } })
    .on("broadcast", { event: "server_voice_v2_channel_changed" }, (event) => {
      serverVoiceOccupancyRealtimeVersionByServerId.set(
        sid,
        Number(serverVoiceOccupancyRealtimeVersionByServerId.get(sid) || 0) + 1
      );
      handleServerVoiceV2ControlBroadcast(event?.payload || {});
    })
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "server_voice_members_v2",
      filter: `server_id=eq.${sid}`,
    }, (payload) => {
      serverVoiceOccupancyRealtimeVersionByServerId.set(
        sid,
        Number(serverVoiceOccupancyRealtimeVersionByServerId.get(sid) || 0) + 1
      );
      if (payload?.eventType === "DELETE") deleteServerVoiceV2MemberRow(payload.old || {}, "realtime_delete");
      else {
        const eventType = String(payload?.eventType || "change").toLowerCase();
        const row = payload.new || {};
        if (eventType === "update" || eventType === "insert") {
          recordVoiceV2MoveTiming(eventType === "update" ? "postgres_update_received" : "postgres_insert_received", {
            moveId: row.assignment_nonce || row.assignmentNonce || "",
            assignmentNonce: row.assignment_nonce || row.assignmentNonce || "",
            movePath: "rpc",
            serverId: row.server_id || row.serverId || sid,
            targetUserId: row.user_id || row.userId || "",
            targetChannelId: row.channel_id || row.channelId || "",
            receivedAt: Date.now(),
          });
        }
        upsertServerVoiceV2MemberRow(row, eventType === "update" ? "postgres_update" : eventType === "insert" ? "postgres_insert" : `realtime_${eventType}`);
      }
    })
    .subscribe((status, error) => {
      console.info("[voice-v2-control] subscription", { serverId: sid, status, message: error?.message || "" });
      const currentState = getServerVoiceOccupancyHydrationState(sid);
      serverVoiceOccupancyHydrationStateByServerId.set(sid, {
        ...currentState,
        realtimeStatus: String(status || ""),
        lastError: error ? {
          code: String(error?.code || ""),
          message: String(error?.message || error || ""),
        } : currentState.lastError,
      });
      if (status === "SUBSCRIBED") {
        void loadServerVoiceV2ControlPlaneSnapshot(sid, `realtime_subscribed:${reason}`).catch(() => false);
        return;
      }
      if (!["CHANNEL_ERROR", "TIMED_OUT", "CLOSED"].includes(String(status || ""))) return;
      if (serverVoiceOccupancyChannelByServerId.get(sid) === controlChannel) {
        serverVoiceOccupancyChannelByServerId.delete(sid);
      }
      if (serverVoiceV2ControlPlaneChannel === controlChannel) {
        serverVoiceV2ControlPlaneChannel = null;
        serverVoiceV2ControlPlaneServerId = "";
      }
      try { supabase.removeChannel(controlChannel); } catch (_) {}
      if (serverVoiceOccupancyResubscribeTimerByServerId.has(sid)) return;
      const timer = setTimeout(() => {
        serverVoiceOccupancyResubscribeTimerByServerId.delete(sid);
        if (normId(getActiveServerContext?.()?.serverId || getActiveServerIdForSidebar?.() || "") !== sid) return;
        void ensureServerVoiceV2ControlPlaneSubscription(sid, {
          hydrate: true,
          reason: `reconnect:${status}`,
          force: true,
        }).catch(() => false);
      }, 1200);
      serverVoiceOccupancyResubscribeTimerByServerId.set(sid, timer);
    });
  serverVoiceOccupancyChannelByServerId.set(sid, controlChannel);
  if (!serverVoiceV2ControlPlaneChannel || normId(currentServerVoiceV2Session?.serverId || "") === sid) {
    serverVoiceV2ControlPlaneChannel = controlChannel;
    serverVoiceV2ControlPlaneServerId = sid;
  }
  if (options?.hydrate !== false) {
    await loadServerVoiceV2ControlPlaneSnapshot(sid, `subscription_start:${reason}`).catch(() => false);
  }
  return true;
}

function bindServerVoiceOccupancyLifecycleRefresh() {
  if (serverVoiceOccupancyLifecycleListenersBound) return;
  serverVoiceOccupancyLifecycleListenersBound = true;
  const refreshIfStale = (reason) => {
    const sid = normId(getActiveServerContext?.()?.serverId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
    if (!sid) return;
    const hydration = getServerVoiceOccupancyHydrationState(sid);
    if (hydration.inFlight || (hydration.lastAuthoritativeFetchAt && Date.now() - hydration.lastAuthoritativeFetchAt < 15000)) {
      reprojectServerVoiceOccupancy(sid, `${reason}:cached`);
      return;
    }
    scheduleServerVoiceOccupancyHydration(sid, reason, {
      delayMs: 0,
      ensureSubscription: true,
    });
  };
  window.addEventListener("focus", () => refreshIfStale("window_focus"));
  window.addEventListener("online", () => refreshIfStale("network_online"));
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") refreshIfStale("visibility_return");
  });
}
bindServerVoiceOccupancyLifecycleRefresh();

function installAltaraVoiceOccupancyDebugHelpers() {
  const resolveServerId = (serverId = "") => normId(
    serverId
    || getActiveServerContext?.()?.serverId
    || getActiveServerIdForSidebar?.()
    || state.activeDm?.serverId
    || ""
  );
  const inspectServerSnapshot = (serverId = "") => {
    const sid = resolveServerId(serverId);
    const rows = getServerVoiceOccupancySnapshotRows(sid);
    const byChannel = {};
    rows.forEach((row) => {
      const channelId = normId(row?.channelId || "");
      if (!channelId) return;
      if (!byChannel[channelId]) byChannel[channelId] = [];
      byChannel[channelId].push(row.userId);
    });
    return {
      serverId: sid,
      hydration: getServerVoiceOccupancyHydrationState(sid),
      snapshotRowCount: rows.length,
      channelIdsWithOccupants: Object.keys(byChannel),
      occupantUserIdsByChannel: byChannel,
      lastAuthoritativeFetchAt: getServerVoiceOccupancyHydrationState(sid).lastAuthoritativeFetchAt,
    };
  };
  const inspectRenderedVoiceRows = (serverId = "") => {
    const sid = resolveServerId(serverId);
    const panel = document.getElementById("serverChannelsPanel");
    const panelServerId = normId(panel?.getAttribute?.("data-server-panel-server-id") || "");
    const rows = panelServerId === sid
      ? Array.from(panel?.querySelectorAll?.("[data-server-voice-member-id]") || [])
        .filter((row) => !row.hasAttribute("data-server-voice-bot-id"))
      : [];
    return {
      serverId: sid,
      panelServerId,
      renderedOccupantCount: rows.length,
      renderedOccupantIds: normalizeUuidArray(rows.map((row) => row.getAttribute("data-server-voice-member-id") || "")),
      renderedChannelIds: normalizeUuidArray(rows.map((row) => row.getAttribute("data-server-voice-channel-id") || "")),
    };
  };
  const compareSnapshotWithRendered = (serverId = "") => {
    const sid = resolveServerId(serverId);
    const visibleChannelIds = getVisibleServerVoiceChannelIds(sid);
    const expectedRows = getServerVoiceOccupancySnapshotRows(sid)
      .filter((row) => visibleChannelIds.has(normId(row?.channelId || "")));
    const rendered = inspectRenderedVoiceRows(sid);
    const expectedIds = normalizeUuidArray(expectedRows.map((row) => row.userId));
    const renderedIds = normalizeUuidArray(rendered.renderedOccupantIds);
    return {
      serverId: sid,
      expectedOccupantIds: expectedIds,
      renderedOccupantIds: renderedIds,
      missingRenderedOccupantIds: expectedIds.filter((id) => !renderedIds.includes(id)),
      unexpectedRenderedOccupantIds: renderedIds.filter((id) => !expectedIds.includes(id)),
      matches: expectedIds.length === renderedIds.length
        && expectedIds.every((id) => renderedIds.includes(id)),
    };
  };
  window.altaraDebugVoiceOccupancy = {
    ...(window.altaraDebugVoiceOccupancy || {}),
    inspectServerSnapshot,
    inspectVisibleVoiceChannels(serverId = "") {
      const sid = resolveServerId(serverId);
      const channels = (serverChannelListByServerId.get(sid) || [])
        .filter((channel) => normalizeConversationChannelType(channel?.channelType || "") === "voice")
        .map((channel) => ({
          channelId: normId(channel?.id || ""),
          conversationId: normId(channel?.conversationId || ""),
          name: String(channel?.name || ""),
          isPrivate: channel?.isPrivate === true,
        }));
      return { serverId: sid, count: channels.length, channels };
    },
    inspectRenderedVoiceRows,
    inspectHydrationState(serverId = "") {
      return getServerVoiceOccupancyHydrationState(resolveServerId(serverId));
    },
    refreshNow(serverId = "") {
      const sid = resolveServerId(serverId);
      return ensureServerVoiceV2ControlPlaneSubscription(sid, {
        hydrate: true,
        reason: "debug_refresh",
      });
    },
    compareSnapshotWithRendered,
    inspectLastVisibilityTransition() {
      return lastServerVoiceOccupancyVisibilityTransition
        ? { ...lastServerVoiceOccupancyVisibilityTransition }
        : null;
    },
    inspectRealtimeState(serverId = "") {
      const sid = resolveServerId(serverId);
      const hydration = getServerVoiceOccupancyHydrationState(sid);
      return {
        serverId: sid,
        subscriptionStatus: hydration.realtimeStatus,
        subscriptionPresent: serverVoiceOccupancyChannelByServerId.has(sid),
        refreshInFlight: serverVoiceOccupancyRefreshInFlightByServerId.has(sid),
        realtimeEventVersion: Number(serverVoiceOccupancyRealtimeVersionByServerId.get(sid) || 0),
        staleResponseIgnoredCount: serverVoiceOccupancyStaleResponsesIgnored,
        lastError: hydration.lastError,
      };
    },
  };
}
installAltaraVoiceOccupancyDebugHelpers();

async function broadcastServerVoiceV2ControlPlaneRow(row = {}, event = "server_voice_v2_channel_changed") {
  const sid = normId(row?.server_id || row?.serverId || row?.server_id || currentServerVoiceV2Session?.serverId || "");
  const channel = serverVoiceOccupancyChannelByServerId.get(sid)
    || (serverVoiceV2ControlPlaneServerId === sid ? serverVoiceV2ControlPlaneChannel : null);
  if (!sid || !channel) return false;
  try {
    await channel.send({
      type: "broadcast",
      event,
      payload: { row },
    });
    return true;
  } catch (error) {
    console.warn("[voice-v2-control] broadcast failed", { serverId: sid, message: error?.message || String(error || "unknown") });
    return false;
  }
}

function isServerVoiceJoinContractDebugEnabled() {
  try {
    return localStorage.getItem("altara_debug_private_voice") === "1"
      || localStorage.getItem("altara_debug_server_voice") === "1";
  } catch (_) {
    return false;
  }
}

function recordServerVoiceV2PresenceLifecycle(event = "", details = {}) {
  const entry = {
    at: Date.now(),
    event: String(event || "unknown"),
    ...(details && typeof details === "object" ? details : {}),
  };
  lastServerVoiceV2PresenceLifecycle = entry;
  serverVoiceV2PresenceLifecycleEvents.push(entry);
  if (serverVoiceV2PresenceLifecycleEvents.length > SERVER_VOICE_V2_PRESENCE_DEBUG_EVENT_LIMIT) {
    serverVoiceV2PresenceLifecycleEvents.splice(
      0,
      serverVoiceV2PresenceLifecycleEvents.length - SERVER_VOICE_V2_PRESENCE_DEBUG_EVENT_LIMIT,
    );
  }
  if (isServerVoiceJoinContractDebugEnabled()) {
    try { console.info("[voice-v2-contract]", entry); } catch (_) {}
  }
  return entry;
}

function getCapturedServerVoiceV2JoinContext() {
  const session = currentServerVoiceV2Session || null;
  const pending = pendingServerVoiceV2JoinContract || null;
  const token = lastServerVoiceV2TokenContract || null;
  const source = session || pending || token || null;
  if (!source) return null;
  const serverId = normId(source.serverId || "");
  const channelId = normId(source.channelId || source.voiceChannelId || source.canonicalChannelId || "");
  const conversationId = normId(source.conversationId || "");
  if (!serverId || !channelId) return null;
  return {
    ...source,
    serverId,
    channelId,
    voiceChannelId: channelId,
    conversationId,
    roomName: String(source.roomName || "").trim(),
    participantIdentity: normId(source.participantIdentity || state.user?.id || ""),
    source: session ? "session" : (pending ? "pending_join" : "last_token"),
  };
}

async function upsertCurrentUserServerVoiceV2ControlPlane({
  serverId = "",
  channelId = "",
  conversationId = "",
  roomName = "",
  assignmentNonce = "",
  assignmentUpdatedAt = "",
  reason = "upsert",
} = {}) {
  const sid = normId(serverId || currentServerVoiceV2Session?.serverId || "");
  const cid = normId(channelId || "");
  const uid = normId(state.user?.id || "");
  if (!sid || !cid || !uid || !isServerVoiceV2Enabled()) return false;
  if (getCurrentUserServerTimeout(sid)) {
    if (isServerTimeoutDebugEnabled()) {
      console.info("[server-timeouts] voice control-plane upsert blocked locally", { serverId: sid, channelId: cid, reason });
    }
    notifyServerTimeoutVoiceBlocked();
    throw createServerTimeoutVoiceBlockError(getCurrentUserServerTimeout(sid));
  }
  const row = buildServerVoiceV2ControlPlaneRow({
    serverId: sid,
    userId: uid,
    channelId: cid,
    conversationId,
    sessionId: getServerVoiceV2LocalSessionId(),
    roomName: roomName || buildServerVoiceV2RoomName(sid),
    assignmentNonce,
    assignmentUpdatedAt,
  });
  upsertServerVoiceV2MemberRow(row, `optimistic_${reason}`);
  await broadcastServerVoiceV2ControlPlaneRow(row).catch(() => false);
  const { error } = await supabase
    .from("server_voice_members_v2")
    .upsert(row, { onConflict: "server_id,user_id" });
  if (error) {
    console.warn("[voice-v2-control] own row upsert failed", { reason, serverId: sid, channelId: cid, message: error?.message || String(error || "unknown") });
    return false;
  }
  console.info("[voice-v2-control] own row upserted", { reason, row });
  return true;
}

async function deleteCurrentUserServerVoiceV2ControlPlane(reason = "leave") {
  const uid = normId(state.user?.id || "");
  const row = serverVoiceV2MembersByUser.get(uid) || getCurrentUserServerVoiceV2Member();
  const sid = normId(row?.serverId || currentServerVoiceV2Session?.serverId || "");
  if (!sid || !uid) return false;
  recordServerVoiceV2PresenceLifecycle("presence_delete_attempted", { reason, serverId: sid, userId: uid });
  deleteServerVoiceV2MemberRow({ user_id: uid }, reason);
  const { error } = await supabase
    .from("server_voice_members_v2")
    .delete()
    .eq("server_id", sid)
    .eq("user_id", uid);
  recordServerVoiceV2PresenceLifecycle(error ? "presence_delete_failed" : "presence_deleted", {
    reason,
    serverId: sid,
    userId: uid,
    error: error ? String(error?.message || error) : null,
  });
  if (error) console.warn("[voice-v2-control] own row delete failed", { reason, message: error?.message || String(error || "unknown") });
  return !error;
}

function startServerVoiceV2Heartbeat() {
  if (serverVoiceV2HeartbeatTimer) clearInterval(serverVoiceV2HeartbeatTimer);
  void updateCurrentServerVoiceV2Heartbeat("heartbeat_start");
  serverVoiceV2HeartbeatTimer = setInterval(() => {
    void updateCurrentServerVoiceV2Heartbeat("heartbeat_interval");
  }, SERVER_VOICE_V2_HEARTBEAT_INTERVAL_MS);
  recordServerVoiceV2PresenceLifecycle("heartbeat_started", {
    serverId: currentServerVoiceV2Session?.serverId || "",
    channelId: currentServerVoiceV2Session?.voiceChannelId || "",
    sessionId: currentServerVoiceV2Session?.sessionId || "",
  });
  startServerVoiceV2StalePurgeTimer();
}

function stopServerVoiceV2Heartbeat() {
  if (serverVoiceV2HeartbeatTimer) clearInterval(serverVoiceV2HeartbeatTimer);
  serverVoiceV2HeartbeatTimer = null;
  stopServerVoiceV2StalePurgeTimer();
}

async function updateCurrentServerVoiceV2Heartbeat(reason = "heartbeat") {
  const row = getCurrentUserServerVoiceV2Member();
  if (!row?.serverId || !row?.userId || !isServerVoiceV2Enabled()) return false;
  const nowIso = new Date().toISOString();
  const cached = serverVoiceV2MembersByUser.get(row.userId);
  if (cached) {
    cached.heartbeatAt = nowIso;
    cached.updatedAt = Date.now();
  }
  const { error } = await supabase
    .from("server_voice_members_v2")
    .update({ heartbeat_at: nowIso })
    .eq("server_id", row.serverId)
    .eq("user_id", row.userId);
  if (error) {
    serverVoiceV2HeartbeatFailureCount += 1;
    if (serverVoiceV2HeartbeatFailureCount >= 2) {
      console.warn("[voice-v2-control] heartbeat failed", {
        reason,
        failures: serverVoiceV2HeartbeatFailureCount,
        message: error?.message || String(error || "unknown"),
      });
    }
    return false;
  }
  serverVoiceV2HeartbeatFailureCount = 0;
  return true;
}

function startServerVoiceV2StalePurgeTimer() {
  if (serverVoiceV2StalePurgeTimer) return;
  serverVoiceV2StalePurgeTimer = setInterval(() => {
    purgeStaleServerVoiceV2Members("timer");
    void callServerVoiceV2CleanupRpc("", "timer").catch(() => false);
  }, SERVER_VOICE_V2_STALE_CLEANUP_INTERVAL_MS);
}

function stopServerVoiceV2StalePurgeTimer() {
  if (serverVoiceV2StalePurgeTimer) clearInterval(serverVoiceV2StalePurgeTimer);
  serverVoiceV2StalePurgeTimer = null;
}

function sendServerVoiceV2UnloadBeacon() {
  const uid = normId(state.user?.id || "");
  const row = serverVoiceV2MembersByUser.get(uid) || getCurrentUserServerVoiceV2Member();
  const sid = normId(row?.serverId || currentServerVoiceV2Session?.serverId || "");
  if (!sid || !uid) return;
  try {
    void supabase
      .from("server_voice_members_v2")
      .delete()
      .eq("server_id", sid)
      .eq("user_id", uid);
  } catch (_) {}
}

if (typeof window !== "undefined") {
  window.addEventListener("pagehide", sendServerVoiceV2UnloadBeacon);
  window.addEventListener("beforeunload", sendServerVoiceV2UnloadBeacon);
}

function resolveVoiceV2ChannelIdentity(input = {}) {
  const raw = input && typeof input === "object" ? input : { channelId: input };
  const requestedServerId = normId(raw.serverId || raw.server_id || currentServerVoiceV2Session?.serverId || "");
  const requestedChannelId = normId(raw.channelId || raw.channel_id || raw.voiceChannelId || raw.voice_channel_id || raw.targetChannelId || raw.target_channel_id || raw.id || "");
  const requestedConversationId = normId(raw.conversationId || raw.conversation_id || raw.targetConversationId || raw.target_conversation_id || raw.conversation_id || "");
  let ctx = null;
  if (requestedChannelId) ctx = findServerChannelContextByChannelId(requestedChannelId, requestedServerId) || null;
  if (!ctx && requestedConversationId) ctx = findServerChannelContextByConversationId(requestedConversationId) || null;
  const channel = ctx?.channel || raw.channel || raw;
  const channelId = normId(channel?.id || channel?.channelId || channel?.channel_id || requestedChannelId || "");
  const conversationId = normId(channel?.conversationId || channel?.conversation_id || requestedConversationId || "");
  const serverId = normId(ctx?.serverId || channel?.serverId || channel?.server_id || requestedServerId || "");
  const name = String(channel?.name || channel?.label || raw.name || raw.targetChannelName || raw.target_channel_name || "").trim();
  return {
    serverId,
    channelId,
    conversationId,
    name,
  };
}

function getVoiceV2ParticipantMetadata(participant = null) {
  if (!participant) return {};
  const direct = participant.metadataJson && typeof participant.metadataJson === "object" ? participant.metadataJson : null;
  if (direct) return direct;
  try {
    const parsed = JSON.parse(String(participant.metadata || "{}"));
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch (_) {
    return {};
  }
}

function getVoiceV2ParticipantAttributes(participant = null) {
  return participant?.attributes && typeof participant.attributes === "object" ? participant.attributes : {};
}

function getVoiceV2ParticipantUserId(participant = null) {
  const attrs = getVoiceV2ParticipantAttributes(participant);
  const meta = getVoiceV2ParticipantMetadata(participant);
  return normId(attrs.user_id || attrs.altara_user_id || meta.userId || meta.altaraUserId || participant?.identity || participant?.userId || "");
}

function getVoiceV2ParticipantChannelId(participant = null) {
  const uid = getVoiceV2ParticipantUserId(participant);
  const member = uid ? getServerVoiceV2Member(uid) : null;
  if (member?.channelId) return member.channelId;
  if (isServerVoiceV2Enabled()) return "";
  const assignment = uid ? getVoiceV2ChannelAssignment(uid) : null;
  if (assignment?.voiceChannelId) return assignment.voiceChannelId;
  const attrs = getVoiceV2ParticipantAttributes(participant);
  const meta = getVoiceV2ParticipantMetadata(participant);
  return normId(attrs.voice_channel_id || attrs.channel_id || meta.voiceChannelId || meta.channelId || "");
}

function pruneVoiceV2ChannelAssignments() {
  const now = Date.now();
  Array.from(voiceV2ChannelAssignmentsByUser.entries()).forEach(([userId, assignment]) => {
    const expiresAt = Number(assignment?.expiresAt || 0);
    if (!assignment || (expiresAt && expiresAt < now)) {
      voiceV2ChannelAssignmentsByUser.delete(userId);
    }
  });
}

function getVoiceV2ChannelAssignment(userId = "") {
  pruneVoiceV2ChannelAssignments();
  return voiceV2ChannelAssignmentsByUser.get(normId(userId || "")) || null;
}

function isVoiceV2ParticipantInChannel(participant = null, channelId = "") {
  const cid = normId(channelId || "");
  return !!cid && getVoiceV2ParticipantChannelId(participant) === cid;
}

function getCurrentVoiceV2CanonicalAssignmentForMe() {
  const meId = normId(state.user?.id || "");
  const member = getCurrentUserServerVoiceV2Member();
  if (member?.channelId) {
    return {
      userId: meId,
      serverId: member.serverId,
      voiceChannelId: member.channelId,
      conversationId: member.conversationId,
      channelName: getServerVoiceV2ChannelNameById(member.channelId),
      nonce: member.assignmentNonce,
      updatedAt: member.assignmentUpdatedAt,
      source: "server_voice_members_v2",
    };
  }
  if (isServerVoiceV2Enabled()) return null;
  const fromMap = meId ? getVoiceV2ChannelAssignment(meId) : null;
  const fromSession = currentServerVoiceV2Session ? {
    userId: meId,
    voiceChannelId: normId(currentServerVoiceV2Session.voiceChannelId || ""),
    conversationId: normId(currentServerVoiceV2Session.conversationId || ""),
    channelName: String(currentServerVoiceV2Session.channelName || "").trim(),
    nonce: String(currentServerVoiceV2Session.assignmentNonce || "").trim(),
    updatedAt: Number(currentServerVoiceV2Session.assignmentUpdatedAt || currentServerVoiceV2Session.updatedAt || 0),
    source: "session",
  } : null;
  if (fromMap && (!fromSession || isVoiceV2AssignmentNewer(fromMap, fromSession))) return fromMap;
  return fromSession || fromMap || null;
}

function buildVoiceV2ParticipantMetadata({
  serverId = "",
  voiceChannelId = "",
  conversationId = "",
  assignmentNonce = "",
  assignmentUpdatedAt = 0,
} = {}) {
  const uid = normId(state.user?.id || "");
  const updatedAtMs = normalizeVoiceV2AssignmentTimestamp(assignmentUpdatedAt, Date.now());
  const updatedAtIso = new Date(updatedAtMs).toISOString();
  return {
    altaraVoiceMode: "server_room_v2",
    serverId: normId(serverId || ""),
    voiceChannelId: normId(voiceChannelId || ""),
    channelId: normId(voiceChannelId || ""),
    conversationId: normId(conversationId || ""),
    voiceChannelUpdatedAt: updatedAtIso,
    voiceChannelNonce: String(assignmentNonce || "").trim(),
    userId: uid,
    altaraUserId: uid,
  };
}

function buildVoiceV2ParticipantAttributes({
  serverId = "",
  voiceChannelId = "",
  conversationId = "",
  assignmentNonce = "",
  assignmentUpdatedAt = 0,
} = {}) {
  const uid = normId(state.user?.id || "");
  const updatedAtMs = normalizeVoiceV2AssignmentTimestamp(assignmentUpdatedAt, Date.now());
  const updatedAtIso = new Date(updatedAtMs).toISOString();
  return {
    altara_voice_mode: "server_room_v2",
    server_id: normId(serverId || ""),
    voice_channel_id: normId(voiceChannelId || ""),
    channel_id: normId(voiceChannelId || ""),
    conversation_id: normId(conversationId || ""),
    voice_channel_updated_at: updatedAtIso,
    voice_channel_nonce: String(assignmentNonce || "").trim(),
    user_id: uid,
    altara_user_id: uid,
  };
}

function shouldSubscribeToVoiceV2Participant(participant = null) {
  const myChannelId = normId(getCurrentVoiceV2ChannelId() || "");
  const remoteUserId = getVoiceV2ParticipantUserId(participant);
  const remoteRow = getServerVoiceV2Member(remoteUserId);
  const theirChannelId = normId(remoteRow?.channelId || "");
  const shouldSubscribe = Boolean(myChannelId && remoteRow && theirChannelId === myChannelId);
  voiceV2DebugInfo("[voice-v2-control] subscription decision", {
    reason: "predicate",
    myChannelId,
    remoteUserId,
    remoteChannelId: theirChannelId,
    shouldSubscribe,
  });
  return shouldSubscribe;
}

function reconcileVoiceV2Subscriptions(reason = "manual") {
  if (!isServerVoiceV2Enabled() || !currentServerVoiceV2Session || !serverVoiceTransportController) return null;
  const result = serverVoiceTransportController.reconcileRemoteSubscriptions?.(({ participant }) => (
    shouldSubscribeToVoiceV2Participant(participant)
  ), { reason: String(reason || "manual") }) || null;
  voiceV2DebugInfo("[voice-v2] reconcile subscriptions", {
    reason,
    myChannelId: currentServerVoiceV2Session.voiceChannelId || "",
    subscribedUserIds: result?.subscribedUserIds || [],
    unsubscribedUserIds: result?.unsubscribedUserIds || [],
  });
  return result;
}

function getServerVoiceV2Snapshot() {
  const convId = normId(currentServerVoiceV2Session?.conversationId || callConversationId || "");
  try {
    return serverVoiceTransportController?.getSnapshot?.() || getServerVoiceTransportSnapshot(convId) || null;
  } catch (_) {
    return null;
  }
}

function getServerVoiceV2Participants() {
  const snapshot = getServerVoiceV2Snapshot();
  return Object.values(snapshot?.participantsByUser || {});
}

function getServerVoiceV2ChannelOccupants(channelId = "", serverId = "") {
  const cid = normId(channelId || "");
  if (!cid) return [];
  const controlPlaneRows = getServerVoiceV2ChannelMembers(cid, serverId);
  if (isServerVoiceV2Enabled()) {
    return controlPlaneRows
      .filter((row) => {
        const legal = normId(row?.channelId || "") === cid;
        if (!legal) console.error("[voice-v2-control] illegal stage member filtered", { member: row, currentChannelId: cid });
        return legal;
      })
      .map((row) => ({
      userId: row.userId,
      participantIdentity: row.userId,
      identity: row.userId,
      voiceChannelId: row.channelId,
      conversationId: row.conversationId,
      presentInRoom: true,
      isLocal: row.userId === normId(state.user?.id || ""),
      controlPlaneRow: row,
    }));
  }
  const seen = new Set();
  return getServerVoiceV2Participants()
    .filter((participant) => isVoiceV2ParticipantInChannel(participant, cid))
    .filter((participant) => {
      const uid = getVoiceV2ParticipantUserId(participant);
      if (!uid || seen.has(uid)) return false;
      seen.add(uid);
      return true;
    });
}

function getCurrentVoiceV2ChannelId() {
  if (isServerVoiceV2Enabled()) return normId(getCurrentUserServerVoiceV2Member()?.channelId || "");
  const canonical = getCurrentVoiceV2CanonicalAssignmentForMe();
  return normId(canonical?.voiceChannelId || currentServerVoiceV2Session?.voiceChannelId || "");
}

function getCurrentVoiceV2ConversationId() {
  if (isServerVoiceV2Enabled()) return normId(getCurrentUserServerVoiceV2Member()?.conversationId || "");
  const canonical = getCurrentVoiceV2CanonicalAssignmentForMe();
  return normId(canonical?.conversationId || currentServerVoiceV2Session?.conversationId || callConversationId || "");
}

function getCurrentVoiceV2ChannelName() {
  const canonical = getCurrentVoiceV2CanonicalAssignmentForMe();
  if (canonical?.channelName) return canonical.channelName;
  const channelId = getCurrentVoiceV2ChannelId();
  const ctx = channelId ? findServerChannelContextByChannelId(channelId, currentServerVoiceV2Session?.serverId || "") : null;
  return String(ctx?.channel?.name || currentServerVoiceV2Session?.channelName || "").trim();
}

function commitVoiceV2ChannelAssignment(userId = "", assignment = {}, reason = "unknown") {
  const targetUserId = normId(userId || assignment?.userId || "");
  const meId = normId(state.user?.id || "");
  const resolved = resolveVoiceV2ChannelIdentity({
    serverId: assignment?.serverId || assignment?.server_id || currentServerVoiceV2Session?.serverId || "",
    channelId: assignment?.voiceChannelId || assignment?.voice_channel_id || assignment?.targetChannelId || assignment?.target_channel_id || assignment?.channelId || assignment?.channel_id || "",
    conversationId: assignment?.conversationId || assignment?.conversation_id || assignment?.targetConversationId || assignment?.target_conversation_id || "",
    targetChannelName: assignment?.channelName || assignment?.targetChannelName || assignment?.target_channel_name || "",
  });
  const serverId = normId(resolved.serverId || assignment?.serverId || assignment?.server_id || currentServerVoiceV2Session?.serverId || "");
  const voiceChannelId = normId(resolved.channelId || "");
  const conversationId = normId(resolved.conversationId || "");
  if (!targetUserId || !serverId || !voiceChannelId) {
    traceVoiceV2ChannelWrite(reason, {
      userId: targetUserId,
      toChannelId: voiceChannelId,
      source: assignment?.source || reason,
      accepted: false,
      rejectedReason: "missing_required_assignment_data",
      assignment,
    });
    return false;
  }
  const previous = getVoiceV2ChannelAssignment(targetUserId);
  const next = {
    userId: targetUserId,
    serverId,
    voiceChannelId,
    conversationId,
    channelName: resolved.name || String(assignment?.channelName || assignment?.targetChannelName || assignment?.target_channel_name || "").trim(),
    source: String(assignment?.source || reason || "unknown"),
    nonce: String(assignment?.nonce || getVoiceV2AssignmentNonce(assignment) || "").trim(),
    updatedAt: Number(assignment?.updatedAt || getVoiceV2AssignmentTimestamp(assignment, Date.now())),
    expiresAt: Number(assignment?.expiresAt || 0),
  };
  if (!isVoiceV2AssignmentNewer(next, previous)) {
    const staleReason = /metadata|attributes|snapshot/i.test(String(reason || ""))
      ? "metadata_mirror_stale"
      : "stale_assignment";
    console.warn(staleReason === "metadata_mirror_stale"
      ? "[voice-v2] metadata mirror stale ignored"
      : "[voice-v2] stale channel assignment ignored", {
      incoming: next,
      current: previous,
      reason,
    });
    traceVoiceV2ChannelWrite(reason, {
      userId: targetUserId,
      fromChannelId: previous?.voiceChannelId || "",
      toChannelId: next.voiceChannelId,
      source: next.source,
      accepted: false,
      rejectedReason: staleReason,
      incoming: next,
      current: previous,
    });
    if (targetUserId === meId && previous?.voiceChannelId && serverVoiceTransportController) {
      void updateVoiceV2LocalParticipantChannel({
        serverId: previous.serverId || serverId,
        channelId: previous.voiceChannelId,
        conversationId: previous.conversationId || "",
        reason: "restore_canonical_assignment",
      });
    }
    return false;
  }

  voiceV2ChannelAssignmentsByUser.set(targetUserId, next);
  traceVoiceV2ChannelWrite(reason, {
    userId: targetUserId,
    fromChannelId: previous?.voiceChannelId || "",
    toChannelId: next.voiceChannelId,
    source: next.source,
    accepted: true,
    assignment: next,
  });

  if (targetUserId === meId) {
    currentServerVoiceV2Session = {
      ...(currentServerVoiceV2Session || {}),
      serverId,
      roomName: buildServerVoiceV2RoomName(serverId),
      voiceChannelId,
      conversationId: conversationId || currentServerVoiceV2Session?.conversationId || "",
      channelName: next.channelName || currentServerVoiceV2Session?.channelName || "",
      assignmentNonce: next.nonce,
      assignmentUpdatedAt: next.updatedAt,
      joinedAt: currentServerVoiceV2Session?.joinedAt || Date.now(),
      updatedAt: Date.now(),
    };
    if (conversationId) {
      callConversationId = conversationId;
      if (isServerVoiceConversationById(activeDmId || "")) activeDmId = conversationId;
      if (state.activeDm && isServerVoiceConversationById(state.activeDm.conversationId || "")) {
        state.activeDm = {
          ...state.activeDm,
          conversationId,
          serverId,
          channelId: voiceChannelId,
          displayName: next.channelName || state.activeDm.displayName,
        };
      }
    }
    if (serverVoiceTransportController) {
      void updateVoiceV2LocalParticipantChannel({
        serverId,
        channelId: voiceChannelId,
        conversationId: conversationId || currentServerVoiceV2Session.conversationId || "",
        reason: `assignment:${reason}`,
      }).catch((error) => {
        console.warn("[voice-v2] local metadata refresh after assignment failed", {
          reason,
          voiceChannelId,
          message: error?.message || String(error || "unknown"),
        });
      });
    }
    reconcileVoiceV2Subscriptions("self_assignment_committed");
    console.info("[voice-v2] self assignment committed", {
      voiceChannelId,
      conversationId,
      channelName: next.channelName,
      nonce: next.nonce,
      currentServerVoiceV2Session,
      callConversationId,
    });
  } else {
    reconcileVoiceV2Subscriptions("remote_assignment_committed");
  }
  return true;
}

async function applyVoiceV2ChannelAssignment(payload = {}, reason = "unknown") {
  if (!isServerVoiceV2Enabled()) {
    console.warn("[voice-v2] disabled on this client", { reason });
    return false;
  }
  const targetUserId = normId(payload?.targetUserId || payload?.target_user_id || payload?.userId || payload?.user_id || "");
  const resolved = resolveVoiceV2ChannelIdentity({
    serverId: payload?.serverId || payload?.server_id,
    channelId: payload?.targetChannelId || payload?.target_channel_id || payload?.voiceChannelId || payload?.voice_channel_id || payload?.channelId || payload?.channel_id,
    conversationId: payload?.targetConversationId || payload?.target_conversation_id || payload?.conversationId || payload?.conversation_id,
    targetChannelName: payload?.targetChannelName || payload?.target_channel_name,
  });
  const serverId = normId(resolved.serverId || payload?.serverId || payload?.server_id || currentServerVoiceV2Session?.serverId || "");
  const voiceChannelId = normId(resolved.channelId || "");
  const conversationId = normId(resolved.conversationId || "");
  if (!targetUserId || !serverId || !voiceChannelId) {
    console.warn("[voice-v2] channel assignment ignored missing data", {
      reason,
      targetUserId,
      serverId,
      voiceChannelId,
      conversationId,
      payload,
    });
    return false;
  }
  const fallbackUpdatedAt = /metadata|attributes|snapshot/i.test(String(reason || "")) ? 0 : Date.now();
  const assignment = {
    userId: targetUserId,
    serverId,
    voiceChannelId,
    conversationId,
    channelName: resolved.name || String(payload?.targetChannelName || payload?.target_channel_name || "").trim(),
    source: String(reason || "unknown"),
    nonce: getVoiceV2AssignmentNonce(payload),
    updatedAt: getVoiceV2AssignmentTimestamp(payload, fallbackUpdatedAt),
    expiresAt: 0,
  };
  console.info("[voice-v2] assignment incoming", {
    reason,
    incoming: assignment,
    current: getVoiceV2ChannelAssignment(targetUserId),
  });
  const committed = commitVoiceV2ChannelAssignment(targetUserId, assignment, reason);
  if (!committed) return false;
  lastVoiceV2MovePayload = {
    ...(payload && typeof payload === "object" ? payload : {}),
    targetUserId,
    serverId,
    targetChannelId: voiceChannelId,
    targetConversationId: conversationId,
    assignmentNonce: assignment.nonce,
    assignmentUpdatedAt: assignment.updatedAt ? new Date(assignment.updatedAt).toISOString() : "",
    reason,
    appliedAt: Date.now(),
  };
  console.info("[voice-v2] assignment applied", {
    reason,
    assignment,
  });
  console.info("[voice-v2] channel assignment received", lastVoiceV2MovePayload);

  refreshServerVoiceChannelBadges();
  refreshCallUI();
  return true;
}

function applyVoiceV2AssignmentsFromTransportSnapshot(reason = "metadata") {
  if (!isServerVoiceV2Enabled() || !currentServerVoiceV2Session) return;
  console.info("[voice-v2-control] metadata ignored as authority", { reason });
  return;
  getServerVoiceV2Participants().forEach((participant) => {
    const userId = getVoiceV2ParticipantUserId(participant);
    const attrs = getVoiceV2ParticipantAttributes(participant);
    const meta = getVoiceV2ParticipantMetadata(participant);
    const mode = String(attrs.altara_voice_mode || meta.altaraVoiceMode || "").trim();
    const voiceChannelId = normId(attrs.voice_channel_id || attrs.channel_id || meta.voiceChannelId || meta.channelId || "");
    if (!userId || mode !== "server_room_v2" || !voiceChannelId) return;
    const resolved = resolveVoiceV2ChannelIdentity({
      serverId: attrs.server_id || meta.serverId || currentServerVoiceV2Session.serverId,
      channelId: voiceChannelId,
      conversationId: attrs.conversation_id || meta.conversationId,
    });
    const assignment = getVoiceV2ChannelAssignment(userId);
    if (assignment?.voiceChannelId === resolved.channelId && assignment?.conversationId === resolved.conversationId) return;
    void applyVoiceV2ChannelAssignment({
      targetUserId: userId,
      serverId: resolved.serverId,
      targetChannelId: resolved.channelId,
      targetConversationId: resolved.conversationId,
      targetChannelName: resolved.name,
      assignmentNonce: attrs.voice_channel_nonce || meta.voiceChannelNonce || "",
      assignmentUpdatedAt: attrs.voice_channel_updated_at || meta.voiceChannelUpdatedAt || "",
    }, reason);
  });
}

function handleVoiceV2ParticipantChannelChanged(reason = "participant_channel_changed") {
  if (!isServerVoiceV2Enabled() || !currentServerVoiceV2Session) return;
  console.info("[voice-v2] participant channel changed", { reason });
  applyVoiceV2AssignmentsFromTransportSnapshot(reason);
  reconcileVoiceV2Subscriptions(reason);
  const convId = normId(currentServerVoiceV2Session.conversationId || callConversationId || "");
  const channelId = normId(currentServerVoiceV2Session.voiceChannelId || "");
  if (convId && channelId) {
    setGroupCallActiveMembers(
      getServerVoiceV2ChannelOccupants(channelId).map((participant) => getVoiceV2ParticipantUserId(participant)),
      convId
    );
  }
  refreshServerVoiceChannelBadges();
  refreshCallUI();
}

function getVoiceV2DebugParticipantRows() {
  return getServerVoiceV2Participants().map((participant) => {
    const publications = Array.isArray(participant?.audioTrackIds)
      ? participant.audioTrackIds
      : [];
    return {
      identity: participant?.participantIdentity || participant?.userId || "",
      userId: getVoiceV2ParticipantUserId(participant),
      voiceChannelId: getVoiceV2ParticipantChannelId(participant),
      subscribedPublications: publications,
      audioSubscribed: participant?.audioSubscribed === true,
      presentInRoom: participant?.presentInRoom === true,
      isLocal: participant?.isLocal === true,
      metadataJson: getVoiceV2ParticipantMetadata(participant),
      attributes: getVoiceV2ParticipantAttributes(participant),
    };
  });
}

