function getServerUnreadCount(serverId = "", fallbackConversationId = "") {
  ensureServerUnreadStateLoaded();
  const sid = normId(serverId || "");
  const fallbackConvId = normId(fallbackConversationId || "");
  const seenChannels = new Set();
  let total = 0;

  const pushUnreadForChannel = (channelInput = {}) => {
    const convId = normId(channelInput?.conversationId || channelInput?.conversation_id || "");
    const channelId = normId(channelInput?.id || channelInput?.channelId || channelInput?.channel_id || "") || getActiveChannelIdForConversation(convId, sid);
    if (!channelId || seenChannels.has(channelId)) return;
    seenChannels.add(channelId);
    const unread = getServerChannelUnreadCount({ serverId: sid, channelId, conversationId: convId });
    if (Number.isFinite(unread) && unread > 0) total += unread;
  };

  if (sid) {
    const channels = serverChannelListByServerId.get(sid) || [];
    (channels || []).forEach((ch) => pushUnreadForChannel(ch));
  }
  if (fallbackConvId) {
    pushUnreadForChannel({ conversationId: fallbackConvId, channelId: getActiveChannelIdForConversation(fallbackConvId, sid) });
  }

  const directUnread = sid ? Math.max(0, Number(serverUnreadByServerId.get(sid) || 0) || 0) : 0;
  return Math.max(0, total, directUnread);
}
function formatGroupOrbUnreadBadgeCount(unreadCount = 0) {
  const count = Math.max(0, Number(unreadCount) || 0);
  if (!count) return "";
  return count > 99 ? "99+" : String(count);
}

function buildGroupOrbUnreadBadgeHtml(unreadCount = 0, extraClass = "") {
  const label = formatGroupOrbUnreadBadgeCount(unreadCount);
  if (!label) return "";
  const className = ["groupOrbUnreadBadge", String(extraClass || "").trim()].filter(Boolean).join(" ");
  return `<span class="${escAttr(className)}" aria-hidden="true">${esc(label)}</span>`;
}

function buildDmRailUnreadBadgeHtml(unreadCount = 0) {
  const label = formatGroupOrbUnreadBadgeCount(unreadCount);
  if (!label) return "";
  return `<span class="groupOrbDmUnreadBadge" aria-hidden="true">${esc(label)}</span>`;
}
function ensureServerUnreadStateLoaded() {
  if (serverUnreadStateLoaded) return;
  serverUnreadStateLoaded = true;
  serverUnreadByServerId.clear();
  channelUnreadByChannelId.clear();
  serverUnreadChannelMetaByChannelId.clear();
  try {
    const raw = localStorage.getItem(getServerUnreadStorageKey());
    const parsed = raw ? JSON.parse(raw) : {};
    const rows = Array.isArray(parsed?.channels)
      ? parsed.channels
      : Object.entries(parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {}).map(([channelId, value]) => ({ channelId, ...(value && typeof value === "object" ? value : { count: value }) }));
    rows.forEach((row) => {
      const channelId = normId(row?.channelId || row?.channel_id || row?.id || "");
      const serverId = normId(row?.serverId || row?.server_id || "");
      const conversationId = normId(row?.conversationId || row?.conversation_id || "");
      const count = Math.max(0, Math.min(999, Number(row?.count || row?.unread || 0) || 0));
      if (!channelId || !serverId || count <= 0) return;
      channelUnreadByChannelId.set(channelId, count);
      serverUnreadChannelMetaByChannelId.set(channelId, { serverId, conversationId });
    });
    recomputeAllServerUnreadCounts();
  } catch (_) {}
}

function persistServerUnreadStateToStorage() {
  ensureServerUnreadStateLoaded();
  try {
    const channels = Array.from(channelUnreadByChannelId.entries())
      .map(([channelId, count]) => {
        const meta = serverUnreadChannelMetaByChannelId.get(channelId) || {};
        return {
          channelId,
          serverId: normId(meta.serverId || ""),
          conversationId: normId(meta.conversationId || ""),
          count: Math.max(1, Math.min(999, Number(count) || 0)),
        };
      })
      .filter((row) => row.channelId && row.serverId && row.count > 0)
      .slice(0, 1600);
    localStorage.setItem(getServerUnreadStorageKey(), JSON.stringify({ version: 1, channels }));
  } catch (_) {}
}

function rememberServerUnreadChannelMeta({ serverId = "", channelId = "", conversationId = "" } = {}) {
  ensureServerUnreadStateLoaded();
  const sid = normId(serverId || "");
  let cid = normId(channelId || "");
  const convId = normId(conversationId || "");
  if (!cid && convId) cid = getActiveChannelIdForConversation(convId, sid);
  if (!sid || !cid) return { serverId: sid, channelId: cid, conversationId: convId };
  const prev = serverUnreadChannelMetaByChannelId.get(cid) || {};
  serverUnreadChannelMetaByChannelId.set(cid, {
    serverId: sid,
    conversationId: convId || normId(prev.conversationId || ""),
  });
  return { serverId: sid, channelId: cid, conversationId: convId || normId(prev.conversationId || "") };
}

function recomputeServerUnreadCount(serverId = "") {
  ensureServerUnreadStateLoaded();
  const sid = normId(serverId || "");
  if (!sid) return 0;
  let total = 0;
  channelUnreadByChannelId.forEach((count, channelId) => {
    const meta = serverUnreadChannelMetaByChannelId.get(channelId) || {};
    if (normId(meta.serverId || "") !== sid) return;
    total += Math.max(0, Number(count) || 0);
  });
  if (total > 0) serverUnreadByServerId.set(sid, Math.min(999, total));
  else serverUnreadByServerId.delete(sid);
  return Math.max(0, total);
}

function recomputeAllServerUnreadCounts() {
  ensureServerUnreadStateLoaded();
  serverUnreadByServerId.clear();
  channelUnreadByChannelId.forEach((_, channelId) => {
    const sid = normId((serverUnreadChannelMetaByChannelId.get(channelId) || {}).serverId || "");
    if (sid) recomputeServerUnreadCount(sid);
  });
}

function getServerChannelUnreadCount(input = {}) {
  ensureServerUnreadStateLoaded();
  const ctx = input && typeof input === "object" ? input : { conversationId: input };
  const sid = normId(ctx.serverId || ctx.server_id || "");
  const convId = normId(ctx.conversationId || ctx.conversation_id || "");
  let channelId = normId(ctx.channelId || ctx.channel_id || "");
  if (!channelId && convId) channelId = getActiveChannelIdForConversation(convId, sid);
  if (sid && channelId) rememberServerUnreadChannelMeta({ serverId: sid, channelId, conversationId: convId });
  const legacyUnread = convId ? Math.max(0, Number(dmUnreadByConversationId.get(convId) || 0) || 0) : 0;
  if (legacyUnread > 0 && sid && channelId) {
    const prev = Math.max(0, Number(channelUnreadByChannelId.get(channelId) || 0) || 0);
    channelUnreadByChannelId.set(channelId, Math.min(999, Math.max(prev, legacyUnread)));
    dmUnreadByConversationId.delete(convId);
    persistDmUnreadConversationsToStorage();
    persistServerUnreadStateToStorage();
    recomputeServerUnreadCount(sid);
  }
  return channelId ? Math.max(0, Number(channelUnreadByChannelId.get(channelId) || 0) || 0) : 0;
}

function clearServerChannelUnread(input = {}) {
  ensureServerUnreadStateLoaded();
  const ctx = input && typeof input === "object" ? input : { conversationId: input };
  const sid = normId(ctx.serverId || ctx.server_id || "");
  const convId = normId(ctx.conversationId || ctx.conversation_id || "");
  let channelId = normId(ctx.channelId || ctx.channel_id || "");
  if (!channelId && convId) channelId = getActiveChannelIdForConversation(convId, sid);
  let changed = false;
  if (channelId && channelUnreadByChannelId.delete(channelId)) changed = true;
  if (convId && dmUnreadByConversationId.delete(convId)) {
    persistDmUnreadConversationsToStorage();
    changed = true;
  }
  if (!changed) return false;
  if (sid) recomputeServerUnreadCount(sid);
  else recomputeAllServerUnreadCounts();
  persistServerUnreadStateToStorage();
  applyServerOrbNotificationDecorations();
  applyServerChannelUnreadDecorations();
  scheduleDmChromeRender({ decorations: true, groupsRail: true, widgets: true });
  return true;
}

function clearServerUnreadForConversation(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId) return false;
  const ctx = resolveServerChannelTimelineContext({ conversationId: convId });
  return clearServerChannelUnread(ctx?.conversationId ? ctx : { conversationId: convId });
}

function clearServerUnreadForServer(serverId = "") {
  ensureServerUnreadStateLoaded();
  const sid = normId(serverId || "");
  if (!sid) return false;
  let changed = false;
  channelUnreadByChannelId.forEach((_, channelId) => {
    const meta = serverUnreadChannelMetaByChannelId.get(channelId) || {};
    if (normId(meta.serverId || "") !== sid) return;
    channelUnreadByChannelId.delete(channelId);
    changed = true;
  });
  const channels = serverChannelListByServerId.get(sid) || [];
  (channels || []).forEach((ch) => {
    const convId = normId(ch?.conversationId || "");
    if (convId && dmUnreadByConversationId.delete(convId)) changed = true;
  });
  if (serverUnreadByServerId.delete(sid)) changed = true;
  clearServerUnreadSender(sid);
  if (!changed) return false;
  persistDmUnreadConversationsToStorage();
  persistServerUnreadStateToStorage();
  applyServerOrbNotificationDecorations();
  applyServerChannelUnreadDecorations();
  scheduleDmChromeRender({ decorations: true, groupsRail: true, widgets: true });
  return true;
}

function isServerChannelActivelyViewed(context = {}) {
  const convId = normId(context.conversationId || context.conversation_id || "");
  const sid = normId(context.serverId || context.server_id || "");
  const channelId = normId(context.channelId || context.channel_id || "");
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  const activeServerId = normId(state.activeDm?.serverId || state.activeDm?.server_id || getActiveServerContext()?.serverId || "");
  const activeChannelId = normId(state.activeDm?.channelId || state.activeDm?.channel_id || getActiveChannelIdForConversation(activeConvId, activeServerId));
  const sameConversation = !!(convId && activeConvId && convId === activeConvId);
  const sameServerChannel = !!(sid && channelId && activeServerId === sid && activeChannelId === channelId);
  const dmMain = document.getElementById("dmMain");
  return !!(isElementActuallyVisible(dmMain) && (sameConversation || sameServerChannel));
}

function getServerNotificationSoundSkipReason(context = {}) {
  const sid = normId(context.serverId || context.server_id || "");
  const convId = normId(context.conversationId || context.conversation_id || "");
  if (sid && isServerMuted(sid)) return "server_muted";
  if (convId && isDmConversationMuted(convId)) return "channel_muted";
  if (sid && getServerNotificationMode(sid) === "nothing") return "server_notifications_disabled";
  return "";
}

function playServerMessageNotificationCue(context = {}, senderUserId = "", sourceTable = "messages") {
  const sid = normId(context.serverId || context.server_id || "");
  const channelId = normId(context.channelId || context.channel_id || context.conversationId || "");
  const skipReason = getServerNotificationSoundSkipReason(context);
  if (skipReason) return { played: false, skippedReason: skipReason };
  const key = `${sid || "server"}:${channelId || "channel"}`;
  const now = Date.now();
  const last = Number(serverUnreadSoundLastPlayedByKey.get(key) || 0) || 0;
  if (now - last < SERVER_MESSAGE_NOTIFICATION_SOUND_COOLDOWN_MS) return { played: false, skippedReason: "throttled" };
  const notificationMeta = { type: sourceTable === "bot_channel_messages" ? "server_bot_message" : "server_message", sender_user_id: normId(senderUserId || "") || null };
  if (!shouldNotifyInFocus(notificationMeta)) return { played: false, skippedReason: "focus_suppressed" };
  serverUnreadSoundLastPlayedByKey.set(key, now);
  playUiCue("msg", notificationMeta);
  return { played: true, skippedReason: "" };
}

function buildServerChannelNotificationMappingSnapshot() {
  const serverChannelByConversationId = {};
  const conversationIdByServerChannelId = {};
  const serverChannelMetaByChannelId = {};
  const remember = ({ serverId = "", channelId = "", conversationId = "", channelName = "" } = {}) => {
    const sid = normId(serverId || "");
    const cid = normId(channelId || "");
    const convId = normId(conversationId || "");
    if (!sid || !cid) return;
    const meta = {
      serverId: sid,
      channelId: cid,
      conversationId: convId,
      channelName: normalizeConversationLabel(channelName || "general", "general"),
    };
    serverChannelMetaByChannelId[cid] = meta;
    if (convId) {
      serverChannelByConversationId[convId] = meta;
      conversationIdByServerChannelId[cid] = convId;
    }
  };
  for (const [sid, channels] of serverChannelListByServerId.entries()) {
    (Array.isArray(channels) ? channels : []).forEach((ch) => remember({
      serverId: sid,
      channelId: ch?.id || ch?.channelId || ch?.channel_id || "",
      conversationId: ch?.conversationId || ch?.conversation_id || "",
      channelName: ch?.name || ch?.displayName || "",
    }));
  }
  for (const [convIdRaw, metaRaw] of dmConversationMetaById.entries()) {
    const convId = normId(convIdRaw || "");
    const meta = metaRaw || {};
    if (!convId || !isServerConversationKind(meta?.kind)) continue;
    remember({
      serverId: meta?.serverId || meta?.server_id || "",
      channelId: meta?.channelId || meta?.channel_id || "",
      conversationId: convId,
      channelName: meta?.displayName || meta?.name || "",
    });
  }
  return { serverChannelByConversationId, conversationIdByServerChannelId, serverChannelMetaByChannelId };
}

function isServerChannelConversationForNotifications(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId) return false;
  const meta = getConversationMeta(convId) || {};
  return !!(
    isServerConversationKind(meta?.kind)
    || normId(meta?.serverId || meta?.server_id || "")
    || findServerChannelContextByConversationId(convId)
  );
}

function isGroupDmConversationForUnread(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId || isServerChannelConversationForNotifications(convId)) return false;
  const meta = getConversationMeta(convId) || {};
  if (isGroupConversationKind(meta?.kind)) return true;
  return (state.groupDms || []).some((row) => normId(row?.conversationId || row?.conversation_id || "") === convId);
}

function getPrivateConversationUnreadCount(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId || isServerChannelConversationForNotifications(convId)) return 0;
  return Math.max(0, Number(dmUnreadByConversationId.get(convId) || 0) || 0);
}
function getUnreadDmWidgetCount() {
  const direct = Array.from(dmUnreadByUserId.values()).reduce((acc, n) => acc + Math.max(0, Number(n) || 0), 0);
  const group = Array.from(dmUnreadByConversationId.entries()).reduce((acc, [convId, count]) => {
    if (!isGroupDmConversationForUnread(convId)) return acc;
    return acc + Math.max(0, Number(count) || 0);
  }, 0);
  return direct + group;
}

function cleanupServerConversationDmState({ conversationId = "", senderUserId = "", reason = "server-channel-classified" } = {}) {
  const convId = normId(conversationId || "");
  const senderId = normId(senderUserId || "");
  if (!convId) return { changed: false, clearedConversationUnread: false, clearedPeerMapping: false, clearedUserUnread: false };
  let changed = false;
  let clearedConversationUnread = false;
  let clearedPeerMapping = false;
  let clearedUserUnread = false;
  if (dmUnreadByConversationId.delete(convId)) {
    changed = true;
    clearedConversationUnread = true;
    persistDmUnreadConversationsToStorage();
  }
  const cachedPeer = normId(dmConversationPeerCache.get(convId) || "");
  if (cachedPeer) {
    if (normId(dmConversationIdByUserId.get(cachedPeer) || "") === convId) dmConversationIdByUserId.delete(cachedPeer);
    dmConversationPeerCache.delete(convId);
    changed = true;
    clearedPeerMapping = true;
  }
  if (senderId && normId(dmConversationIdByUserId.get(senderId) || "") === convId) {
    dmConversationIdByUserId.delete(senderId);
    if (dmUnreadByUserId.delete(senderId)) {
      persistDmUnreadUsersToStorage();
      clearedUserUnread = true;
    }
    changed = true;
    clearedPeerMapping = true;
  }
  if (changed) {
    scheduleDmChromeRender({ decorations: true, groupsRail: true, widgets: true, reorderDmList: true });
    logNotificationDebug("server_conversation_dm_state_cleanup", {
      conversationId: convId,
      senderUserId: senderId,
      context: "server_channel",
      skippedReason: reason,
      appliedDmUnread: false,
      clearedConversationUnread,
      clearedPeerMapping,
      clearedUserUnread,
    });
  }
  return { changed, clearedConversationUnread, clearedPeerMapping, clearedUserUnread };
}

async function resolveServerChannelContextForNotification(conversationId = "", { allowLookup = true, senderUserId = "", reason = "notification-classifier" } = {}) {
  const convId = normId(conversationId || "");
  if (!convId) return null;
  const cached = resolveServerChannelTimelineContext({ conversationId: convId }) || null;
  if (normId(cached?.serverId || "")) {
    cleanupServerConversationDmState({ conversationId: convId, senderUserId, reason: `${reason}:cache` });
    return { ...cached, classificationReason: "server_channel_cache" };
  }
  const meta = getConversationMeta(convId) || {};
  if (isServerConversationKind(meta?.kind) && normId(meta?.serverId || meta?.server_id || "")) {
    const mapped = resolveServerChannelTimelineContext({
      conversationId: convId,
      serverId: meta?.serverId || meta?.server_id || "",
      channelId: meta?.channelId || meta?.channel_id || "",
    }) || {};
    cleanupServerConversationDmState({ conversationId: convId, senderUserId, reason: `${reason}:meta` });
    return { ...mapped, conversationId: convId, classificationReason: "server_channel_meta" };
  }
  if (!allowLookup) return null;
  const lookedUp = await resolveServerConversationMembershipContext(convId, { allowLookup: true }).catch(() => null);
  if (normId(lookedUp?.serverId || "")) {
    cleanupServerConversationDmState({ conversationId: convId, senderUserId, reason: `${reason}:server_channels_lookup` });
    return { ...lookedUp, classificationReason: "server_channels_lookup" };
  }
  return null;
}
function logNotificationDebug(eventName = "event", details = {}, { level = "log" } = {}) {
  const safe = {
    at: Date.now(),
    event: String(eventName || "event").slice(0, 80),
    sourceTable: details.sourceTable || details.source || null,
    messageId: normId(details.messageId || details.id || "") || null,
    context: details.context || details.contextType || null,
    classificationReason: details.classificationReason || details.reason || "",
    serverId: normId(details.serverId || "") || null,
    channelId: normId(details.channelId || "") || null,
    conversationId: normId(details.conversationId || "") || null,
    senderUserId: normId(details.senderUserId || details.sender_user_id || "") || null,
    isOwnMessage: details.isOwnMessage === true,
    skippedOwn: details.skippedOwn === true || details.isOwnMessage === true,
    activeMatch: details.activeMatch === true,
    unreadApplied: details.unreadApplied === true,
    appliedServerUnread: details.appliedServerUnread === true || details.unreadApplied === true,
    appliedDmUnread: details.appliedDmUnread === true,
    soundPlayed: details.soundPlayed === true,
    skippedReason: details.skippedReason || "",
    clearedConversationUnread: details.clearedConversationUnread === true,
    clearedPeerMapping: details.clearedPeerMapping === true,
    clearedUserUnread: details.clearedUserUnread === true,
  };
  try {
    lastNotificationEvents.push(safe);
    if (lastNotificationEvents.length > 40) lastNotificationEvents.splice(0, lastNotificationEvents.length - 40);
  } catch (_) {}
  if (!isAltaraLocalhostDebugContext()) return;
  const fn = level === "warn" ? console.warn : (level === "error" ? console.error : console.log);
  fn("[notifications]", eventName, safe);
}

async function getIncomingMessageContext(row = {}, { sourceTable = "messages" } = {}) {
  const table = String(sourceTable || "messages").trim();
  if (table === "bot_channel_messages") {
    let serverId = normId(row?.server_id || row?.serverId || "");
    const channelId = normId(row?.channel_id || row?.channelId || "");
    let conversationId = normId(row?.conversation_id || row?.conversationId || getActiveConversationIdForChannel(channelId, serverId));
    if (!conversationId && channelId) {
      try {
        const { data, error } = await supabase
          .from("server_channels")
          .select("id, server_id, conversation_id, name, channel_type")
          .eq("id", channelId)
          .maybeSingle();
        if (!error && data) {
          conversationId = normId(data?.conversation_id || "");
          const resolvedServerId = normId(data?.server_id || serverId);
          if (resolvedServerId) serverId = resolvedServerId;
          if (conversationId && resolvedServerId) {
            setConversationMeta(conversationId, {
              kind: "server",
              isGroup: true,
              serverId: resolvedServerId,
              channelId,
              channel_id: channelId,
              displayName: normalizeConversationLabel(data?.name || "general", "general"),
              channelType: normalizeConversationChannelType(data?.channel_type || "text"),
            });
          }
        }
      } catch (_) {}
    }
    return {
      type: "bot_server_channel",
      sourceTable: table,
      serverId,
      channelId,
      conversationId,
      senderUserId: normId(row?.bot_id || row?.botId || ""),
      isOwnMessage: false,
    };
  }

  const conversationId = normId(row?.conversation_id || row?.conversationId || "");
  const senderUserId = normId(row?.user_id || row?.author_user_id || row?.authorUserId || "");
  const meId = normId(state.user?.id || "");
  const serverCtx = await resolveServerChannelContextForNotification(conversationId, {
    allowLookup: true,
    senderUserId,
    reason: "incoming-message-context",
  });
  if (serverCtx?.serverId) {
    return {
      type: "server_channel",
      sourceTable: table,
      serverId: normId(serverCtx?.serverId || ""),
      channelId: normId(serverCtx?.channelId || ""),
      conversationId,
      senderUserId,
      isOwnMessage: !!(senderUserId && senderUserId === meId),
      classificationReason: serverCtx?.classificationReason || "server_channel_mapping",
    };
  }
  const kind = await getConversationKindForNotificationRouting(conversationId);
  if (kind === "group") {
    return { type: "group_dm", sourceTable: table, conversationId, senderUserId, isOwnMessage: !!(senderUserId && senderUserId === meId) };
  }
  return { type: "dm", sourceTable: table, conversationId, senderUserId, isOwnMessage: !!(senderUserId && senderUserId === meId) };
}

function applyIncomingServerChannelUnread(context = {}, { row = null, sourceTable = "messages", isSystemEvent = false } = {}) {
  ensureServerUnreadStateLoaded();
  const serverId = normId(context.serverId || context.server_id || "");
  const conversationId = normId(context.conversationId || context.conversation_id || "");
  let channelId = normId(context.channelId || context.channel_id || "");
  if (!channelId && conversationId) channelId = getActiveChannelIdForConversation(conversationId, serverId);
  if (!serverId || !channelId || isSystemEvent) return { unreadApplied: false, soundPlayed: false, skippedReason: !serverId || !channelId ? "missing_server_channel" : "system_event" };
  const cleanup = cleanupServerConversationDmState({ conversationId, senderUserId: context.senderUserId || context.sender_user_id || "", reason: "incoming-server-unread" });
  rememberServerUnreadChannelMeta({ serverId, channelId, conversationId });
  const activeMatch = isServerChannelActivelyViewed({ serverId, channelId, conversationId });
  const senderUserId = normId(context.senderUserId || context.sender_user_id || "");
  const isOwnMessage = context.isOwnMessage === true || !!(senderUserId && senderUserId === normId(state.user?.id || ""));
  if (activeMatch || isOwnMessage) {
    if (activeMatch) clearServerChannelUnread({ serverId, channelId, conversationId });
    logNotificationDebug("incoming_server_message", { sourceTable, messageId: row?.id, context: context.type || "server_channel", classificationReason: context.classificationReason || "server_channel_mapping", serverId, channelId, conversationId, senderUserId, isOwnMessage, skippedOwn: isOwnMessage, activeMatch, unreadApplied: false, appliedServerUnread: false, appliedDmUnread: false, soundPlayed: false, skippedReason: activeMatch ? "active_channel" : "own_message", ...cleanup });
    return { unreadApplied: false, soundPlayed: false, skippedReason: activeMatch ? "active_channel" : "own_message" };
  }
  const prev = Math.max(0, Number(channelUnreadByChannelId.get(channelId) || 0) || 0);
  channelUnreadByChannelId.set(channelId, Math.min(999, prev + 1));
  recomputeServerUnreadCount(serverId);
  persistServerUnreadStateToStorage();
  if (conversationId && dmUnreadByConversationId.delete(conversationId)) persistDmUnreadConversationsToStorage();
  if (senderUserId && sourceTable !== "bot_channel_messages") {
    void rememberServerUnreadSenderForConversation(conversationId, senderUserId, {
      senderAvatarUrl: String(row?.profiles?.avatar_url || "").trim(),
    });
  }
  const sound = playServerMessageNotificationCue({ serverId, channelId, conversationId }, senderUserId, sourceTable);
  applyServerOrbNotificationDecorations();
  applyServerChannelUnreadDecorations();
  scheduleDmChromeRender({ decorations: true, groupsRail: true, widgets: true });
  logNotificationDebug("incoming_server_message", { sourceTable, messageId: row?.id, context: context.type || "server_channel", classificationReason: context.classificationReason || "server_channel_mapping", serverId, channelId, conversationId, senderUserId, isOwnMessage, skippedOwn: isOwnMessage, activeMatch, unreadApplied: true, appliedServerUnread: true, appliedDmUnread: false, soundPlayed: sound.played, skippedReason: sound.skippedReason, ...cleanup });
  return { unreadApplied: true, soundPlayed: sound.played, skippedReason: sound.skippedReason };
}

function exposeAltaraNotificationsDebugHelper() {
  try {
    if (typeof window === "undefined" || !isAltaraLocalhostDebugContext()) return;
    window.__ALTARA_DEBUG_NOTIFICATIONS__ = () => ({
      activeServerId: normId(state.activeDm?.serverId || getActiveServerContext()?.serverId || ""),
      activeChannelId: normId(state.activeDm?.channelId || getActiveChannelIdForConversation(activeDmId || state.activeDm?.conversationId || "", state.activeDm?.serverId || "")),
      activeConversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
      ...buildServerChannelNotificationMappingSnapshot(),
      serverUnreadByServerId: Object.fromEntries(Array.from(serverUnreadByServerId.entries())),
      channelUnreadByChannelId: Object.fromEntries(Array.from(channelUnreadByChannelId.entries())),
      dmUnreadByConversationId: Object.fromEntries(Array.from(dmUnreadByConversationId.entries())),
      groupDmUnreadByConversationId: Object.fromEntries(Array.from(dmUnreadByConversationId.entries()).filter(([convId]) => isGroupDmConversationForUnread(convId))),
      dmUnreadByUserId: Object.fromEntries(Array.from(dmUnreadByUserId.entries())),
      unreadDmWidgetCount: getUnreadDmWidgetCount(),
      lastNotificationEvents: lastNotificationEvents.slice(-20),
    });
  } catch (_) {}
}

function getServerUnreadSender(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return null;
  const cached = serverUnreadSenderByServerId.get(sid) || null;
  if (!cached) return null;

  const userId = normId(cached?.userId || "");
  const profileAvatar = String(getCachedProfile(userId)?.avatar_url || "").trim();
  const avatarUrl = String(profileAvatar || cached?.avatarUrl || "").trim();
  return {
    ...cached,
    serverId: sid,
    userId,
    avatarUrl,
  };
}

function setServerUnreadSender(serverId = "", userId = "", avatarUrl = "") {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return false;

  const prev = serverUnreadSenderByServerId.get(sid) || {};
  const fallbackAvatar = String(getCachedProfile(uid)?.avatar_url || "").trim();
  const nextAvatar = String(avatarUrl || fallbackAvatar || prev?.avatarUrl || "").trim();
  const next = {
    userId: uid,
    avatarUrl: nextAvatar,
    at: Date.now(),
  };
  const changed = normId(prev?.userId || "") !== next.userId || String(prev?.avatarUrl || "") !== next.avatarUrl;
  serverUnreadSenderByServerId.set(sid, next);
  return changed;
}

function clearServerUnreadSender(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return false;
  return serverUnreadSenderByServerId.delete(sid);
}

function resolveCachedServerIdForConversation(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId) return "";

  const cachedMeta = getConversationMeta(convId) || {};
  let sid = normId(cachedMeta?.serverId || "");
  if (sid) return sid;

  sid = normId(findServerChannelContextByConversationId(convId)?.serverId || "");
  if (sid) return sid;

  const activeConvId = normId(state.activeDm?.conversationId || activeDmId || "");
  if (activeConvId === convId && isServerConversationKind(state.activeDm?.kind)) {
    sid = normId(state.activeDm?.serverId || "");
    if (sid) return sid;
  }

  const serverRow = (state.servers || []).find((s) => normId(s?.defaultConversationId || "") === convId) || null;
  return normId(serverRow?.serverId || "");
}

async function rememberServerUnreadSenderForConversation(conversationId = "", senderUserId = "", {
  senderAvatarUrl = "",
} = {}) {
  const convId = normId(conversationId || "");
  const uid = normId(senderUserId || "");
  if (!convId || !uid) return;
  if (uid === normId(state.user?.id || "")) return;

  let sid = resolveCachedServerIdForConversation(convId);
  if (!sid) {
    const ctx = await resolveServerConversationMembershipContext(convId, { allowLookup: true }).catch(() => null);
    sid = normId(ctx?.serverId || "");
  }
  if (!sid) return;


  const changed = setServerUnreadSender(sid, uid, senderAvatarUrl);
  if (changed) applyServerOrbNotificationDecorations();

  const current = getServerUnreadSender(sid);
  if (String(current?.avatarUrl || "").trim()) return;

  try {
    const rows = await fetchProfilesByIds([uid], { includeBio: false, force: false });
    const fetchedAvatar = String(rows?.[0]?.avatar_url || getCachedProfile(uid)?.avatar_url || "").trim();
    const avatarChanged = setServerUnreadSender(sid, uid, fetchedAvatar);
    if (avatarChanged) applyServerOrbNotificationDecorations();
  } catch (_) {}
}

function syncDmRailUnreadBadge(buttonEl, unreadCount = 0) {
  if (!buttonEl) return;
  const existing = buttonEl.querySelector(".groupOrbDmUnreadBadge");
  const label = formatGroupOrbUnreadBadgeCount(unreadCount);
  if (!label) {
    if (existing) existing.remove();
    return;
  }

  if (existing) {
    if (existing.textContent === label) return;
    existing.textContent = label;
    return;
  }

  buttonEl.insertAdjacentHTML("beforeend", buildDmRailUnreadBadgeHtml(unreadCount));
}

function syncGroupOrbUnreadBadge(buttonEl, unreadCount = 0) {
  if (!buttonEl) return;
  buttonEl.querySelector(".groupOrbNotifyAvatar")?.remove();
  const existing = buttonEl.querySelector(".groupOrbUnreadBadge");
  const isServerBadge = !!buttonEl.classList?.contains("groupOrb--server");
  const label = formatGroupOrbUnreadBadgeCount(unreadCount);
  if (!label) {
    if (existing) existing.remove();
    return;
  }

  if (existing) {
    existing.classList.toggle("serverIconUnreadBadge", isServerBadge);
    if (existing.textContent === label) return;
    existing.textContent = label;
    return;
  }

  buttonEl.insertAdjacentHTML(
    "beforeend",
    `<span class="groupOrbUnreadBadge${isServerBadge ? " serverIconUnreadBadge" : ""}" aria-hidden="true">${esc(label)}</span>`
  );
}

function applyServerOrbNotificationDecorations() {
  const rail = document.getElementById("leftGroupsRail");
  if (!rail) return;

  rail.querySelectorAll(".groupOrb.groupOrb--dm[data-open-rail-dm-user-id]").forEach((btn) => {
    const uid = normId(btn.getAttribute("data-open-rail-dm-user-id") || "");
    const unread = Math.max(0, Number(dmUnreadByUserId.get(uid) || 0));
    const hasUnread = unread > 0;
    btn.classList.toggle("has-notification", hasUnread);
    if (hasUnread) {
      const safeUnread = Math.min(999, unread);
      const displayName = String(btn.getAttribute("data-open-rail-dm-display") || btn.getAttribute("data-open-rail-dm-username") || "DM").trim() || "DM";
      const unreadText = safeUnread === 1 ? "1 unread message" : `${safeUnread} unread messages`;
      const tooltip = `${displayName} \u2014 ${unreadText}`;
      btn.setAttribute("data-dm-unread", String(safeUnread));
      btn.setAttribute("data-notify-text", unreadText);
      btn.setAttribute("title", tooltip);
      btn.setAttribute("aria-label", tooltip);
    } else {
      btn.removeAttribute("data-dm-unread");
      btn.removeAttribute("data-notify-text");
    }
    syncDmRailUnreadBadge(btn, unread);
  });

  rail.querySelectorAll(".groupOrb.groupOrb--group[data-open-group-dm-conversation]").forEach((btn) => {
    const convId = normId(btn.getAttribute("data-open-group-dm-conversation") || "");
    const unread = getPrivateConversationUnreadCount(convId);
    const hasUnread = unread > 0;
    btn.classList.toggle("has-notification", hasUnread);
    if (hasUnread) {
      const safeUnread = Math.min(999, unread);
      btn.setAttribute("data-group-unread", String(safeUnread));
      btn.setAttribute("data-notify-text", safeUnread > 1 ? `${safeUnread} novas mensagens` : "Nova mensagem");
    } else {
      btn.removeAttribute("data-group-unread");
      btn.removeAttribute("data-notify-text");
    }
    syncGroupOrbUnreadBadge(btn, unread);
  });

  rail.querySelectorAll(".groupOrb.groupOrb--server").forEach((btn) => {
    const sid = normId(btn.getAttribute("data-open-group-server-id") || "");
    const fallbackConvId = normId(btn.getAttribute("data-open-group-conversation") || "");
    const unread = getServerUnreadCount(sid, fallbackConvId);
    const hasUnread = unread > 0;
    btn.classList.toggle("has-notification", hasUnread);
    if (hasUnread) {
      const safeUnread = Math.min(999, unread);
      btn.setAttribute("data-server-unread", String(safeUnread));
      btn.setAttribute("data-notify-text", safeUnread > 1 ? `${safeUnread} novas mensagens` : "Nova mensagem");
    } else {
      btn.removeAttribute("data-server-unread");
      btn.removeAttribute("data-notify-text");
      clearServerUnreadSender(sid);
    }
    syncGroupOrbUnreadBadge(btn, unread);
  });

  rail.querySelectorAll(".groupOrb.groupOrb--folder[data-server-folder-id]").forEach((btn) => {
    const folderId = normId(btn.getAttribute("data-server-folder-id") || "");
    const unread = getServerFolderUnreadCount(folderId);
    const hasUnread = unread > 0;
    btn.classList.toggle("has-notification", hasUnread);
    if (hasUnread) {
      const safeUnread = Math.min(999, unread);
      btn.setAttribute("data-server-unread", String(safeUnread));
      btn.setAttribute("data-notify-text", safeUnread > 1 ? `${safeUnread} novas mensagens` : "Nova mensagem");
    } else {
      btn.removeAttribute("data-server-unread");
      btn.removeAttribute("data-notify-text");
    }
    syncGroupOrbUnreadBadge(btn, unread);
  });
}

async function markServerAsRead(serverId, { forceLoadChannels = false } = {}) {
  const sid = normId(serverId);
  if (!sid) return false;

  let channels = serverChannelListByServerId.get(sid) || [];
  if (!channels.length || forceLoadChannels) {
    channels = await fetchServerChannelsForSidebar(sid, { force: forceLoadChannels }).catch(() => channels);
  }

  const fallbackServerRow = getServerRowById(sid);
  const conversationIds = normalizeUuidArray([
    ...(Array.isArray(channels) ? channels.map((ch) => normId(ch?.conversationId || "")) : []),
    normId(fallbackServerRow?.defaultConversationId || ""),
  ]);

  if (!conversationIds.length) ensureServerUnreadStateLoaded();
  clearServerUnreadForServer(sid);

  if (normId(getActiveServerContext()?.serverId || "") === sid) {
    await refreshServerConversationUi({ reason: "mark-server-read", refreshChannels: true, refreshMembers: false }).catch(() => {});
  } else {
    renderGroupsRail();
  }
  return true;
}

function closeServerCreateModal() {
  const modal = document.getElementById("serverCreateModal");
  if (!modal || modal.classList.contains("hidden")) return;
  clearServerCreateIconDraft();
  serverCreateName = "";
  modal.classList.add("hidden");
  modal.setAttribute("aria-hidden", "true");
}

const altaraOptionalUiHookWarnings = new Set();

function warnMissingOptionalUiHookOnce(key = "", message = "") {
  const safeKey = String(key || "").trim();
  if (!safeKey || altaraOptionalUiHookWarnings.has(safeKey)) return;
  altaraOptionalUiHookWarnings.add(safeKey);
  try { console.warn(message || `[ui] optional hook skipped: ${safeKey}`); } catch (_) {}
}

function hideAltaraContextMenuElement(menu) {
  if (!menu) return;
  try { menu.classList.remove("is-open", "open", "active"); } catch (_) {}
  try { menu.classList.add("hidden"); } catch (_) {}
  try { menu.setAttribute("aria-hidden", "true"); } catch (_) {}
  try { menu.hidden = true; } catch (_) {}
}

function getOrCreateServerPanelMenuElement() {
  let menu = document.getElementById("serverPanelMenu");
  if (menu) return menu;
  menu = document.createElement("div");
  menu.id = "serverPanelMenu";
  menu.className = "msgMenu serverPanelMenu hidden";
  menu.setAttribute("role", "menu");
  menu.setAttribute("aria-hidden", "true");
  document.body?.appendChild(menu);
  return menu;
}

function closeServerPanelMenu(reason = "manual_close") {
  serverPanelMenuTargetServerId = "";
  hideAltaraContextMenuElement(document.getElementById("serverPanelMenu"));
  try { document.body?.classList?.remove("server-panel-menu-open"); } catch (_) {}
}

function positionServerPanelMenu(menu, point = null, anchorEl = null) {
  if (!menu) return;
  const anchorRect = anchorEl?.getBoundingClientRect?.() || null;
  const x = Number(point?.x || 0) || Math.round(anchorRect?.left || 0) || 16;
  const y = Number(point?.y || 0) || Math.round((anchorRect?.bottom || 0) + 6) || 72;
  const width = 220;
  const margin = 8;
  const viewportWidth = Math.max(0, window.innerWidth || document.documentElement?.clientWidth || 0);
  const viewportHeight = Math.max(0, window.innerHeight || document.documentElement?.clientHeight || 0);
  const left = Math.max(margin, Math.min(x, Math.max(margin, viewportWidth - width - margin)));
  menu.style.position = "fixed";
  menu.style.left = `${left}px`;
  menu.style.top = `${Math.max(margin, Math.min(y, Math.max(margin, viewportHeight - 220)))}px`;
  menu.style.minWidth = `${width}px`;
  menu.style.zIndex = "10020";
}

function bindServerPanelMenuOnce() {
  if (serverPanelMenuBound) return;
  serverPanelMenuBound = true;

  document.addEventListener("pointerdown", (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    if (target.closest?.("#serverPanelMenu") || target.closest?.("[data-server-panel-menu-open]")) return;
    closeServerPanelMenu("outside_click");
  }, true);

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    const menu = document.getElementById("serverPanelMenu");
    if (!menu || !menu.classList.contains("is-open")) return;
    event.preventDefault();
    closeServerPanelMenu("escape");
  });
}

function buildServerPanelMenuItem(action, label, {
  serverId = "",
  serverName = "",
  iconUrl = "",
  disabled = false,
  danger = false,
  check = false,
  checked = false,
  hint = "",
  right = "",
} = {}) {
  const disabledAttr = disabled ? " disabled" : "";
  const classes = [
    "msgMenu__item",
    danger ? "msgMenu__item--danger" : "",
    check ? "msgMenu__item--check" : "",
    disabled ? "is-disabled" : "",
  ].filter(Boolean).join(" ");
  const main = hint
    ? `<span class="msgMenu__itemMain"><span>${esc(label)}</span><span class="msgMenu__itemHint">${esc(hint)}</span></span>`
    : `<span>${esc(label)}</span>`;
  const rightHtml = check
    ? `<span class="msgMenu__check${checked ? " is-on" : ""}" aria-hidden="true"></span>`
    : right;
  return `<button class="${classes}" type="button" role="menuitem" data-server-panel-act="${escAttr(action)}" data-server-panel-id="${escAttr(serverId)}" data-server-panel-name="${escAttr(serverName)}" data-server-panel-icon="${escAttr(iconUrl)}"${disabledAttr}>${main}${rightHtml || ""}</button>`;
}

function buildServerPanelMenuHtml({ sid = "", serverName = "Server", iconUrl = "", variant = "server" } = {}) {
  const caps = getServerCapabilityMeta(sid);
  const capabilityState = getCurrentServerCapabilityUiState(sid);
  const canOpenSettings = !!(capabilityState.isOwner || capabilityState.canManageServer || capabilityState.canManageRoles);
  const canManageChannelStructure = currentUserCanManageChannels(sid);
  const hideMuted = isServerHideMutedChannelsEnabled(sid);
  const serverMuted = isServerMuted(sid);
  const notificationModeLabel = getServerNotificationModeLabel(getServerNotificationMode(sid));
  const submenuChevron = "&#x203A;";
  const divider = '<div class="msgMenu__divider"></div>';
  const v = String(variant || "server").trim().toLowerCase();
  const item = (action, label, options = {}) => buildServerPanelMenuItem(action, label, {
    serverId: sid,
    serverName,
    iconUrl,
    ...options,
  });

  if (v === "channels") {
    return [
      item("toggle_hide_muted", "Hide Muted Channels", { check: true, checked: hideMuted }),
      divider,
      item("create_channel", "Create Channel", { disabled: !canManageChannelStructure }),
      item("create_category", "Create Category", { disabled: !canManageChannelStructure }),
      item("invite", "Invite to Server", { disabled: !caps.canInvite }),
    ].join("");
  }

  if (v === "orb") {
    return [
      item("mark_read", "Mark As Read"),
      divider,
      item("invite", "Invite to Server", { disabled: !caps.canInvite }),
      item("toggle_mute", "Mute Server", { check: true, checked: serverMuted, hint: serverMuted ? "Mute active" : "" }),
      item("cycle_notifications", "Notification Settings", { hint: notificationModeLabel, right: `<span>${submenuChevron}</span>` }),
      item("toggle_hide_muted", "Hide Muted Channels", { check: true, checked: hideMuted }),
      divider,
      item("settings", "Server Settings", { disabled: !canOpenSettings, right: `<span>${submenuChevron}</span>` }),
      item("privacy_settings", "Privacy Settings", { hint: "Soon" }),
      item("edit_per_server_profile", "Edit Per-server Profile"),
      divider,
      item("create_channel", "Create Channel", { disabled: !canManageChannelStructure }),
      item("create_category", "Create Category", { disabled: !canManageChannelStructure }),
      item("create_event", "Create Event", { disabled: !caps.canSettings }),
      divider,
      item("copy_server_id", "Copy Server ID", { right: '<span class="msgMenu__kbd">ID</span>' }),
    ].join("");
  }

  return [
    item("invite", "Invite People", { disabled: !caps.canInvite }),
    item("settings", "Server Settings", { disabled: !canOpenSettings }),
    divider,
    item("leave", "Leave Server", { danger: true, disabled: !caps.canLeave }),
    divider,
    item("copy_server_id", "Copy Server ID", { right: '<span class="msgMenu__kbd">ID</span>' }),
  ].join("");
}

async function runServerPanelMenuAction(action = "", { sid = "", serverName = "Server", iconUrl = "" } = {}) {
  const act = String(action || "").trim().toLowerCase();
  if (!sid || !act) return;

  if (act === "mark_read") {
    await markServerAsRead(sid, { forceLoadChannels: false });
    return;
  }

  if (act === "invite") {
    if (!currentUserCanCreateInvites(sid)) {
      await requestAppAlert("You do not have permission to create invites.", { title: "Invite People" }).catch(() => {});
      return;
    }
    await openServerInviteModal({ serverId: sid, name: serverName, iconUrl });
    return;
  }

  if (act === "settings") {
    if (!currentUserCanOpenServerSettings(sid)) {
      await requestAppAlert("Sem permissao para configurar este server.", { title: "Server Settings" }).catch(() => alert("Sem permissao para configurar este server."));
      return;
    }
    const capabilityState = getCurrentServerCapabilityUiState(sid);
    const panel = capabilityState.canManageRoles && !capabilityState.canManageServer ? "roles" : "profile";
    await openServerSettingsModal({ serverId: sid, name: serverName, iconUrl, panel });
    return;
  }

  if (act === "create_channel" || act === "create_category") {
    await openServerChannelCreateModal({ serverId: sid, name: serverName, iconUrl }, {
      defaultType: act === "create_category" ? "category" : "text",
    });
    return;
  }

  if (act === "toggle_mute") {
    toggleServerMuted(sid);
    return;
  }

  if (act === "cycle_notifications") {
    cycleServerNotificationMode(sid);
    return;
  }

  if (act === "toggle_hide_muted") {
    toggleServerHideMutedChannels(sid);
    return;
  }

  if (act === "leave") {
    await leaveServerById(sid, { serverName });
    return;
  }

  if (act === "copy_server_id") {
    await copyTextWithPromptFallback(sid, "Server ID").catch(() => {});
    return;
  }

  if (act === "privacy_settings" || act === "edit_per_server_profile" || act === "create_event") {
    warnMissingOptionalUiHookOnce(`server-panel:${act}`, `[server-menu] ${act} is not available yet.`);
  }
}

function openServerPanelMenuAt(server = null, point = null, options = {}) {
  const sid = normId(server?.serverId || getActiveServerContext?.()?.serverId || state.activeDm?.serverId || "");
  if (!sid) return;

  bindServerPanelMenuOnce();
  const menu = getOrCreateServerPanelMenuElement();
  if (!menu) return;

  const serverName = normalizeConversationLabel(server?.name || getServerRowById(sid)?.name || "Server", "Server");
  const iconUrl = String(server?.iconUrl || getServerRowById(sid)?.iconUrl || "").trim();
  const variant = String(options?.variant || "server").trim().toLowerCase() || "server";
  const isOpenForSameServer = menu.classList.contains("is-open") && serverPanelMenuTargetServerId === sid;
  if (isOpenForSameServer) {
    closeServerPanelMenu("toggle");
    return;
  }

  closeServerFolderMenu("open_other_menu");
  closeServerChannelItemMenu("open_other_menu");
  closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });

  serverPanelMenuTargetServerId = sid;
  menu.innerHTML = buildServerPanelMenuHtml({ sid, serverName, iconUrl, variant });

  menu.querySelectorAll("[data-server-panel-act]").forEach((button) => {
    button.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (button.disabled || button.classList.contains("is-disabled")) return;
      const action = String(button.getAttribute("data-server-panel-act") || "").trim().toLowerCase();
      closeServerPanelMenu("action");
      await runServerPanelMenuAction(action, { sid, serverName, iconUrl });
    });
  });

  const width = variant === "orb" ? 262 : (variant === "channels" ? 236 : 240);
  const minHeight = variant === "orb" ? 420 : (variant === "channels" ? 168 : 172);
  if (typeof positionMenuAtPoint === "function" && point) {
    positionMenuAtPoint(menu, point, { width, minHeight });
  } else {
    positionServerPanelMenu(menu, point, options?.anchorEl || null);
  }
  menu.hidden = false;
  menu.classList.remove("hidden");
  menu.classList.add("is-open");
  menu.setAttribute("aria-hidden", "false");
  try { document.body?.classList?.add("server-panel-menu-open"); } catch (_) {}
}
function closeServerFolderMenu(reason = "manual_close") {
  serverFolderMenuTargetId = "";
  hideAltaraContextMenuElement(document.getElementById("serverFolderMenu"));
  try { document.body?.classList?.remove("server-folder-menu-open"); } catch (_) {}
}

function openServerFolderMenuAt(folder = null, point = null, options = {}) {
  serverFolderMenuTargetId = normId(folder?.folderId || "");
  warnMissingOptionalUiHookOnce("openServerFolderMenuAt", "[server-folder] context menu UI is unavailable; open request skipped safely.");
}

function closeServerChannelItemMenu(reason = "manual_close") {
  serverChannelItemMenuTarget = null;
  hideAltaraContextMenuElement(document.getElementById("serverChannelItemMenu"));
  try { document.body?.classList?.remove("server-channel-menu-open"); } catch (_) {}
}

function getOrCreateServerChannelItemMenuElement() {
  let menu = document.getElementById("serverChannelItemMenu");
  if (menu) return menu;
  menu = document.createElement("div");
  menu.id = "serverChannelItemMenu";
  menu.className = "msgMenu serverChannelItemMenu hidden";
  menu.setAttribute("role", "menu");
  menu.setAttribute("aria-hidden", "true");
  document.body?.appendChild(menu);
  return menu;
}

function buildServerChannelItemMenuHtml(target = null) {
  const itemType = String(target?.itemType || "channel").trim().toLowerCase();
  const isChannel = itemType !== "category";
  const sid = normId(target?.serverId || "");
  const canManage = currentUserCanManageChannels(sid) || currentUserCanManageServer(sid) || currentUserCanManageRoles(sid);
  const label = isChannel ? "Channel Settings" : "Category Settings";
  const editLabel = isChannel ? "Edit Channel" : "Edit Category";
  const idLabel = isChannel ? "Copy Channel ID" : "Copy Category ID";
  const deleteLabel = isChannel ? "Delete Channel" : "Delete Category";
  return [
    `<button class="msgMenu__item" type="button" role="menuitem" data-server-channel-menu-act="settings"${canManage ? "" : " disabled"}>${esc(label)}</button>`,
    `<button class="msgMenu__item" type="button" role="menuitem" data-server-channel-menu-act="edit"${canManage ? "" : " disabled"}>${esc(editLabel)}</button>`,
    `${!isChannel ? `<button class="msgMenu__item" type="button" role="menuitem" data-server-channel-menu-act="create_channel"${canManage ? "" : " disabled"}>Create Channel</button>` : ""}`,
    `<button class="msgMenu__item" type="button" role="menuitem" data-server-channel-menu-act="copy_id">${esc(idLabel)}</button>`,
    `<div class="msgMenu__divider"></div>`,
    `<button class="msgMenu__item msgMenu__item--danger" type="button" role="menuitem" data-server-channel-menu-act="delete"${canManage ? "" : " disabled"}>${esc(deleteLabel)}</button>`,
  ].join("");
}

async function runServerChannelItemMenuAction(action = "", target = null) {
  const act = String(action || "").trim().toLowerCase();
  const itemType = String(target?.itemType || "channel").trim().toLowerCase();
  const sid = normId(target?.serverId || "");
  if (!act || !sid) return;

  if (act === "settings") {
    if (itemType === "category") {
      await openServerChannelCreateModal({
        serverId: sid,
        name: getServerRowById(sid)?.name || "Server",
        iconUrl: getServerRowById(sid)?.iconUrl || "",
      }, {
        mode: "edit",
        defaultType: "category",
        categoryId: target?.categoryId || "",
        name: target?.label || "Category",
      });
      return;
    }
    await openChannelSettingsModal(target);
    return;
  }

  if (act === "edit") {
    await openServerChannelCreateModal({
      serverId: sid,
      name: getServerRowById(sid)?.name || "Server",
      iconUrl: getServerRowById(sid)?.iconUrl || "",
    }, {
      mode: "edit",
      defaultType: itemType === "category" ? "category" : (target?.channelType || "text"),
      channelId: target?.channelId || "",
      conversationId: target?.conversationId || "",
      categoryId: target?.categoryId || "",
      name: target?.label || (itemType === "category" ? "Category" : "channel"),
    });
    return;
  }

  if (act === "create_channel" && itemType === "category") {
    await openServerChannelCreateModal({
      serverId: sid,
      name: getServerRowById(sid)?.name || "Server",
      iconUrl: getServerRowById(sid)?.iconUrl || "",
    }, {
      defaultType: "text",
      defaultCategoryId: target?.categoryId || "",
    });
    return;
  }

  if (act === "copy_id") {
    const id = itemType === "category" ? normId(target?.categoryId || "") : normId(target?.channelId || "");
    await copyTextWithPromptFallback(id, itemType === "category" ? "Category ID" : "Channel ID").catch(() => {});
    return;
  }

  if (act === "delete") {
    if (itemType === "category") {
      await deleteServerChannelCategoryById(sid, {
        categoryId: target?.categoryId || "",
        categoryName: target?.label || "Category",
      });
      return;
    }
    await deleteServerChannelById(sid, {
      channelId: target?.channelId || "",
      conversationId: target?.conversationId || "",
      channelName: target?.label || "channel",
      channelType: target?.channelType || "text",
    });
  }
}

function bindServerChannelItemMenuOnce() {
  if (serverChannelItemMenuBound) return;
  serverChannelItemMenuBound = true;
  document.addEventListener("pointerdown", (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    if (target.closest?.("#serverChannelItemMenu")) return;
    closeServerChannelItemMenu("outside_click");
  }, true);
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    const menu = document.getElementById("serverChannelItemMenu");
    if (!menu || !menu.classList.contains("is-open")) return;
    event.preventDefault();
    closeServerChannelItemMenu("escape");
  });
  const menu = getOrCreateServerChannelItemMenuElement();
  menu.addEventListener("click", async (event) => {
    const button = eventTargetElement(event)?.closest?.("[data-server-channel-menu-act]");
    if (!button || button.disabled) return;
    event.preventDefault();
    event.stopPropagation();
    const action = button.getAttribute("data-server-channel-menu-act") || "";
    const target = serverChannelItemMenuTarget || null;
    closeServerChannelItemMenu("action");
    await runServerChannelItemMenuAction(action, target);
  });
}

function openServerChannelItemMenuAt(target = null, point = null, options = {}) {
  const sid = normId(target?.serverId || "");
  if (!sid) return;
  bindServerChannelItemMenuOnce();
  const menu = getOrCreateServerChannelItemMenuElement();
  if (!menu) return;
  serverChannelItemMenuTarget = target || null;
  closeServerPanelMenu("open_other_menu");
  closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });
  menu.innerHTML = buildServerChannelItemMenuHtml(target);
  if (typeof positionMenuAtPoint === "function" && point) {
    positionMenuAtPoint(menu, point, { width: 236, minHeight: 150 });
  } else {
    positionServerPanelMenu(menu, point, options?.anchorEl || target?.anchorEl || null);
  }
  menu.hidden = false;
  menu.classList.remove("hidden");
  menu.classList.add("is-open");
  menu.setAttribute("aria-hidden", "false");
  try { document.body?.classList?.add("server-channel-menu-open"); } catch (_) {}
}

function getOrCreateChannelSettingsModalElement() {
  let modal = document.getElementById("channelSettingsModal");
  if (modal) return modal;
  modal = document.createElement("div");
  modal.id = "channelSettingsModal";
  modal.className = "modal hidden channelSettingsModal";
  modal.setAttribute("aria-hidden", "true");
  modal.innerHTML = `
    <div class="modal__backdrop" data-channel-settings-close="1"></div>
    <div class="modalCard channelSettingsCard" role="dialog" aria-modal="true" aria-labelledby="channelSettingsTitle">
      <div class="modalTop channelSettingsTop">
        <div>
          <div class="modalTitle" id="channelSettingsTitle">Channel Settings</div>
          <div class="channelSettingsSubtitle" id="channelSettingsSubtitle"></div>
        </div>
        <button class="serverSettingsCloseBtn" type="button" data-channel-settings-close="1" aria-label="Close channel settings">×</button>
      </div>
      <div class="channelSettingsShell">
        <aside class="channelSettingsNav" role="tablist" aria-label="Channel settings sections">
          <button class="channelSettingsNavItem is-active" type="button" data-channel-settings-tab="overview">Overview</button>
          <button class="channelSettingsNavItem" type="button" data-channel-settings-tab="permissions">Permissions</button>
        </aside>
        <main class="channelSettingsBody" id="channelSettingsBody"></main>
      </div>
      <div class="channelSettingsFooter">
        <span class="channelSettingsFeedback" id="channelSettingsFeedback"></span>
        <button class="btn ghost" type="button" data-channel-settings-close="1">Close</button>
      </div>
    </div>
  `;
  document.body?.appendChild(modal);
  modal.addEventListener("click", async (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    if (target.closest("[data-channel-settings-close]")) {
      closeChannelSettingsModal();
      return;
    }
    const tabBtn = target.closest("[data-channel-settings-tab]");
    if (tabBtn) {
      activeChannelSettingsTab = String(tabBtn.getAttribute("data-channel-settings-tab") || "overview").trim().toLowerCase() === "permissions" ? "permissions" : "overview";
      renderChannelSettingsModal();
      return;
    }
    const tri = target.closest("[data-channel-permission-state]");
    if (tri) {
      const group = tri.closest("[data-channel-permission-key]");
      if (!group) return;
      group.setAttribute("data-channel-permission-value", tri.getAttribute("data-channel-permission-state") || "neutral");
      renderChannelPermissionTriStateGroup(group);
      return;
    }
    const addRole = target.closest("[data-channel-permissions-add-role]");
    if (addRole) {
      const select = modal.querySelector("[data-channel-permissions-role-select]");
      const roleId = normId(select?.value || "");
      if (!roleId || !activeChannelSettingsModalState) return;
      activeChannelSettingsModalState.extraTargets = activeChannelSettingsModalState.extraTargets || [];
      if (!activeChannelSettingsModalState.extraTargets.some((entry) => entry.targetType === "role" && entry.targetId === roleId)) {
        activeChannelSettingsModalState.extraTargets.push({ targetType: "role", targetId: roleId });
      }
      renderChannelSettingsModal();
      return;
    }
    const saveTarget = target.closest("[data-channel-permissions-save-target]");
    if (saveTarget) {
      await saveChannelPermissionTargetFromModal(saveTarget);
      return;
    }
    const saveOverview = target.closest("[data-channel-settings-save-overview]");
    if (saveOverview) {
      await saveChannelSettingsOverviewFromModal();
    }
  });
  modal.addEventListener("input", (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    if (target.matches("[data-channel-settings-name]")) {
      activeChannelSettingsFeedback = "";
      renderChannelSettingsFeedback();
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    const el = document.getElementById("channelSettingsModal");
    if (!el || el.classList.contains("hidden")) return;
    event.preventDefault();
    closeChannelSettingsModal();
  });
  return modal;
}

function closeChannelSettingsModal() {
  const modal = document.getElementById("channelSettingsModal");
  if (!modal) return;
  activeChannelSettingsModalState = null;
  activeChannelSettingsSaving = false;
  activeChannelSettingsFeedback = "";
  activeChannelSettingsFeedbackIsError = false;
  modal.classList.add("hidden");
  modal.setAttribute("aria-hidden", "true");
}

function getChannelSettingsChannelRow() {
  const stateRow = activeChannelSettingsModalState || {};
  const sid = normId(stateRow.serverId || "");
  const cid = normId(stateRow.channelId || "");
  const convId = normId(stateRow.conversationId || "");
  return (serverChannelListByServerId.get(sid) || []).find((row) => (
    (cid && normId(row?.id || "") === cid)
    || (convId && normId(row?.conversationId || "") === convId)
  )) || stateRow.channel || null;
}

function setChannelSettingsFeedback(message = "", { error = false } = {}) {
  activeChannelSettingsFeedback = String(message || "").trim();
  activeChannelSettingsFeedbackIsError = !!error;
  renderChannelSettingsFeedback();
}

function renderChannelSettingsFeedback() {
  const el = document.getElementById("channelSettingsFeedback");
  if (!el) return;
  el.textContent = activeChannelSettingsFeedback;
  el.classList.toggle("is-error", !!activeChannelSettingsFeedbackIsError);
  el.classList.toggle("is-visible", !!activeChannelSettingsFeedback);
}

function getChannelPermissionOverwriteForTarget(channelId = "", targetType = "", targetId = "") {
  const type = String(targetType || "").trim().toLowerCase();
  const tid = normId(targetId || "");
  return getChannelPermissionOverwrites(channelId).find((row) => row.targetType === type && row.targetId === tid) || null;
}

function getChannelPermissionTargetLabel(serverId = "", targetType = "", targetId = "") {
  const sid = normId(serverId || "");
  const tid = normId(targetId || "");
  const type = String(targetType || "").trim().toLowerCase();
  if (type === "everyone") return "@everyone";
  if (type === "role") {
    const role = getServerRolesForSettingsDisplay(sid).find((row) => normId(row?.id || "") === tid) || null;
    return role?.name || "Role";
  }
  if (type === "member") {
    const member = getCachedServerMemberForUser(sid, tid);
    return member?.displayName || member?.username || "Member";
  }
  return "Target";
}

function getChannelPermissionEditorTargets(serverId = "", channelId = "") {
  const sid = normId(serverId || "");
  const cid = normId(channelId || "");
  const targets = [{ targetType: "everyone", targetId: sid }];
  getChannelPermissionOverwrites(cid).forEach((row) => {
    if (!targets.some((target) => target.targetType === row.targetType && target.targetId === row.targetId)) {
      targets.push({ targetType: row.targetType, targetId: row.targetId });
    }
  });
  (activeChannelSettingsModalState?.extraTargets || []).forEach((target) => {
    const type = String(target?.targetType || "").trim().toLowerCase();
    const tid = normId(target?.targetId || "");
    if (tid && !targets.some((entry) => entry.targetType === type && entry.targetId === tid)) targets.push({ targetType: type, targetId: tid });
  });
  return targets;
}

function buildChannelPermissionTriStateHtml({ key = "", value = "neutral", disabled = false } = {}) {
  const safeKey = normalizeChannelPermissionKey(key || "");
  const current = ["allow", "deny"].includes(value) ? value : "neutral";
  const button = (stateName, label, title) => `
    <button
      class="channelPermissionTriBtn${current === stateName ? " is-active" : ""}"
      type="button"
      data-channel-permission-state="${escAttr(stateName)}"
      title="${escAttr(title)}"
      ${disabled ? "disabled" : ""}
    >${label}</button>
  `;
  return `
    <div class="channelPermissionTri" data-channel-permission-key="${escAttr(safeKey)}" data-channel-permission-value="${escAttr(current)}">
      ${button("neutral", "/", "Use default")}
      ${button("allow", "✓", "Allow")}
      ${button("deny", "×", "Deny")}
    </div>
  `;
}

function renderChannelPermissionTriStateGroup(group) {
  const value = String(group.getAttribute("data-channel-permission-value") || "neutral");
  group.querySelectorAll("[data-channel-permission-state]").forEach((btn) => {
    btn.classList.toggle("is-active", String(btn.getAttribute("data-channel-permission-state") || "") === value);
  });
}

function buildChannelPermissionTargetEditorHtml(target = {}) {
  const row = getChannelPermissionOverwriteForTarget(activeChannelSettingsModalState?.channelId || "", target.targetType, target.targetId);
  const label = getChannelPermissionTargetLabel(activeChannelSettingsModalState?.serverId || "", target.targetType, target.targetId);
  const disabled = activeChannelSettingsSaving || !currentUserCanManageChannels(activeChannelSettingsModalState?.serverId || "");
  return `
    <section class="channelPermissionTarget" data-channel-permission-target-type="${escAttr(target.targetType)}" data-channel-permission-target-id="${escAttr(target.targetId)}">
      <div class="channelPermissionTarget__head">
        <div>
          <strong>${esc(label)}</strong>
          <small>${esc(target.targetType === "everyone" ? "Default channel overwrite" : target.targetType)}</small>
        </div>
        <button class="btn ghost" type="button" data-channel-permissions-save-target="1" ${disabled ? "disabled" : ""}>Save</button>
      </div>
      <div class="channelPermissionRows">
        ${CHANNEL_PERMISSION_META.map((perm) => {
          const value = row?.allow?.[perm.key] === true ? "allow" : (row?.deny?.[perm.key] === true ? "deny" : "neutral");
          return `
            <div class="channelPermissionRow">
              <div class="channelPermissionRow__text">
                <span>${esc(perm.label)}</span>
                <small>${esc(perm.hint || "")}</small>
              </div>
              ${buildChannelPermissionTriStateHtml({ key: perm.key, value, disabled })}
            </div>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function buildChannelSettingsPermissionsHtml() {
  const stateRow = activeChannelSettingsModalState || {};
  const sid = normId(stateRow.serverId || "");
  const cid = normId(stateRow.channelId || "");
  if (channelPermissionOverwritesSqlAvailable === false) {
    return `
      <div class="channelSettingsNotice is-warning">
        <strong>Channel permissions are not enabled yet.</strong>
        <span>Apply the manual SQL patch to edit channel permission overwrites.</span>
      </div>
    `;
  }
  const roleOptions = getServerRolesForSettingsDisplay(sid)
    .filter((role) => normId(role?.id || "") && !isDefaultServerRole(role))
    .map((role) => `<option value="${escAttr(role.id)}">${esc(role.name || "Role")}</option>`)
    .join("");
  const targets = getChannelPermissionEditorTargets(sid, cid);
  return `
    <div class="channelSettingsSectionIntro">
      <h3>Permission Overwrites</h3>
      <p>Deny wins over allow for the same target. Voice permissions are stored now and enforced in a later phase.</p>
    </div>
    <div class="channelPermissionToolbar">
      <select class="input" data-channel-permissions-role-select ${roleOptions ? "" : "disabled"}>
        ${roleOptions || `<option value="">No roles available</option>`}
      </select>
      <button class="btn ghost" type="button" data-channel-permissions-add-role ${roleOptions ? "" : "disabled"}>Add Role</button>
      <button class="btn ghost" type="button" disabled title="Member-specific overwrites are structured in SQL and coming next.">Add Member</button>
    </div>
    <div class="channelPermissionTargetList">
      ${targets.map(buildChannelPermissionTargetEditorHtml).join("")}
    </div>
  `;
}

function buildChannelSettingsOverviewHtml() {
  const row = getChannelSettingsChannelRow();
  const sid = normId(activeChannelSettingsModalState?.serverId || "");
  const categoryId = normId(row?.categoryId || activeChannelSettingsModalState?.categoryId || "");
  const categories = serverChannelCategoryListByServerId.get(sid) || [];
  const options = [`<option value="">No Category</option>`].concat(categories.map((cat) => {
    const id = normId(cat?.id || "");
    return `<option value="${escAttr(id)}"${id === categoryId ? " selected" : ""}>${esc(normalizeServerCategoryName(cat?.name || "Category"))}</option>`;
  })).join("");
  return `
    <div class="channelSettingsOverview">
      <label class="field">
        <span class="label">Channel name</span>
        <input class="input" type="text" data-channel-settings-name value="${escAttr(row?.name || activeChannelSettingsModalState?.label || "general")}" maxlength="72" />
      </label>
      <label class="field">
        <span class="label">Category</span>
        <select class="input" data-channel-settings-category>${options}</select>
      </label>
      <div class="channelSettingsButtonRow">
        <button class="btn primary" type="button" data-channel-settings-save-overview ${activeChannelSettingsSaving ? "disabled" : ""}>Save Changes</button>
      </div>
    </div>
  `;
}

function renderChannelSettingsModal() {
  const modal = getOrCreateChannelSettingsModalElement();
  const stateRow = activeChannelSettingsModalState;
  if (!modal || !stateRow) return;
  const row = getChannelSettingsChannelRow();
  const title = document.getElementById("channelSettingsTitle");
  const sub = document.getElementById("channelSettingsSubtitle");
  const body = document.getElementById("channelSettingsBody");
  const channelType = normalizeConversationChannelType(row?.channelType || stateRow.channelType || "text");
  const prefix = channelType === "voice" ? "" : "#";
  if (title) title.textContent = `${prefix}${row?.name || stateRow.label || "channel"} Settings`;
  if (sub) sub.textContent = channelType === "voice" ? "Voice channel" : "Text channel";
  modal.querySelectorAll("[data-channel-settings-tab]").forEach((btn) => {
    const tab = String(btn.getAttribute("data-channel-settings-tab") || "");
    btn.classList.toggle("is-active", tab === activeChannelSettingsTab);
  });
  if (body) body.innerHTML = activeChannelSettingsTab === "permissions"
    ? buildChannelSettingsPermissionsHtml()
    : buildChannelSettingsOverviewHtml();
  renderChannelSettingsFeedback();
}

async function saveChannelSettingsOverviewFromModal() {
  const stateRow = activeChannelSettingsModalState || {};
  const sid = normId(stateRow.serverId || "");
  const cid = normId(stateRow.channelId || "");
  if (!sid || !cid || activeChannelSettingsSaving) return;
  if (!currentUserCanManageChannels(sid)) {
    setChannelSettingsFeedback("Requires Manage Channels.", { error: true });
    return;
  }
  const modal = getOrCreateChannelSettingsModalElement();
  const name = normalizeConversationLabel(modal.querySelector("[data-channel-settings-name]")?.value || "", "general");
  const categoryId = normId(modal.querySelector("[data-channel-settings-category]")?.value || "");
  activeChannelSettingsSaving = true;
  setChannelSettingsFeedback("Saving...", { error: false });
  renderChannelSettingsModal();
  const res = await updateServerChannelRpc({
    serverId: sid,
    channelId: cid,
    name,
    categoryId,
  });
  activeChannelSettingsSaving = false;
  if (res?.error) {
    if (isMissingRpcError(res.error)) serverChannelManagementSqlAvailable = false;
    setChannelSettingsFeedback(`Could not save: ${getServerChannelManagementErrorMessage(res.error)}`, { error: true });
    renderChannelSettingsModal();
    return;
  }
  serverChannelManagementSqlAvailable = true;
  const list = (serverChannelListByServerId.get(sid) || []).slice();
  const idx = list.findIndex((ch) => normId(ch?.id || "") === cid);
  if (idx >= 0) {
    const rpcRow = res?.data?.row || res?.data || null;
    const next = normalizeServerChannelSidebarRow(rpcRow || {
      ...list[idx],
      name,
      category_id: categoryId || null,
    }, sid, {
      hasPositionColumn: true,
      hasCreatedAtColumn: true,
      hasChannelTypeColumn: true,
      hasCategoryIdColumn: true,
      hasIsPrivateColumn: true,
      hasUserLimitColumn: true,
      hasMediaModeColumn: true,
    }) || { ...list[idx], name, categoryId };
    list[idx] = next;
    serverChannelListByServerId.set(sid, list);
    activeChannelSettingsModalState = { ...activeChannelSettingsModalState, ...next, channel: next, label: next.name };
  }
  await emitServerChannelsChangedBroadcast(sid, {
    reason: "channel_updated",
    channelId: cid,
    patch: { name, category_id: categoryId || null },
  }).catch(() => {});
  await refreshServerConversationUi({ force: true, reason: "channel-settings-overview-save", refreshChannels: true, refreshMembers: false }).catch(() => {});
  setChannelSettingsFeedback("Saved.", { error: false });
  renderChannelSettingsModal();
}

async function saveChannelPermissionTargetFromModal(button) {
  const targetSection = button?.closest?.("[data-channel-permission-target-type]");
  const stateRow = activeChannelSettingsModalState || {};
  const sid = normId(stateRow.serverId || "");
  const cid = normId(stateRow.channelId || "");
  const targetType = String(targetSection?.getAttribute("data-channel-permission-target-type") || "").trim().toLowerCase();
  const targetId = normId(targetSection?.getAttribute("data-channel-permission-target-id") || "");
  if (!sid || !cid || !targetType || !targetId || activeChannelSettingsSaving) return;
  const allow = {};
  const deny = {};
  targetSection.querySelectorAll("[data-channel-permission-key]").forEach((group) => {
    const key = normalizeChannelPermissionKey(group.getAttribute("data-channel-permission-key") || "");
    const value = String(group.getAttribute("data-channel-permission-value") || "neutral");
    if (!key) return;
    if (value === "allow") allow[key] = true;
    if (value === "deny") deny[key] = true;
  });
  activeChannelSettingsSaving = true;
  setChannelSettingsFeedback("Saving overwrite...", { error: false });
  renderChannelSettingsModal();
  const empty = !Object.keys(allow).length && !Object.keys(deny).length;
  const result = empty
    ? await deleteChannelPermissionOverwrite({ serverId: sid, channelId: cid, targetType, targetId })
    : await setChannelPermissionOverwrite({ serverId: sid, channelId: cid, targetType, targetId, allow, deny });
  activeChannelSettingsSaving = false;
  if (!result?.ok) {
    const missing = result?.missingSql || isMissingChannelPermissionsSqlError(result?.error);
    setChannelSettingsFeedback(missing ? "Apply the SQL patch to enable channel permissions." : `Could not save overwrite: ${result?.error?.message || result?.error || "Unknown error"}`, { error: true });
    renderChannelSettingsModal();
    return;
  }
  await emitServerPermissionsChangedBroadcast(sid, {
    reason: "channel_permission_overwrite_saved",
    channelId: cid,
    targetType,
    targetId,
  }).catch(() => {});
  scheduleActivePermissionsRefresh("channel_permission_overwrite_saved", { serverId: sid, new: { server_id: sid, channel_id: cid } });
  void invokeServerVoicePermissionReconciliation({
    serverId: sid,
    channelId: cid,
    scope: "channel",
    reason: "channel_permission_overwrite_saved",
  }).catch((error) => {
    console.warn("[server-voice-permissions] channel reconciliation failed after overwrite save", {
      serverId: sid,
      channelId: cid,
      message: error?.message || error,
    });
  });
  void reconcileActiveServerChannelAfterPermissionChange("channel_permission_overwrite_saved").catch((error) => {
    console.warn("[channel-permissions] active channel reconcile failed after save", { message: error?.message || error, error });
  });
  setChannelSettingsFeedback("Saved.", { error: false });
  renderChannelSettingsModal();
}

async function openChannelSettingsModal(target = null) {
  const sid = normId(target?.serverId || "");
  const channelId = normId(target?.channelId || "");
  if (!sid || !channelId) return false;
  await ensureServerRolePermissionCache(sid, { force: false }).catch(() => null);
  if (!currentUserCanManageChannels(sid)) {
    await requestAppAlert("Requires Manage Channels.", { title: "Channel Settings" }).catch(() => {});
    return false;
  }
  const channel = await resolveServerChannelForServer(sid, {
    channelId,
    conversationId: target?.conversationId || "",
  }).catch(() => null);
  activeChannelSettingsModalState = {
    ...(target || {}),
    ...(channel || {}),
    serverId: sid,
    channelId,
    channel,
    extraTargets: [],
  };
  activeChannelSettingsTab = "overview";
  activeChannelSettingsSaving = false;
  activeChannelSettingsFeedback = "";
  activeChannelSettingsFeedbackIsError = false;
  await loadChannelPermissionOverwrites(sid, channelId, { force: false }).catch(() => null);
  void loadServerSettingsMembersBestEffort(sid, { force: false }).catch(() => {});
  const modal = getOrCreateChannelSettingsModalElement();
  renderChannelSettingsModal();
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  requestAnimationFrame(() => modal.querySelector("[data-channel-settings-name]")?.focus?.());
  return true;
}

function closeServerVoiceMemberMenu(options = {}) {
  serverVoiceMemberMenuTarget = null;
  serverVoiceMemberMenuHovering = false;
  if (serverMemberContextMenuActiveSubmenu === "voice") serverMemberContextMenuActiveSubmenu = "";
  hideAltaraContextMenuElement(document.getElementById("serverVoiceMemberMenu"));
  try { document.body?.classList?.remove("server-voice-member-menu-open"); } catch (_) {}
}

function bindServerCreateModalOnce() {
  if (serverCreateModalBound) return;
  serverCreateModalBound = true;

  const modal = document.getElementById("serverCreateModal");
  if (!modal) {
    warnMissingOptionalUiHookOnce("bindServerCreateModalOnce", "[server-create] modal DOM not found; binding skipped safely.");
    return;
  }

  const nameInput = document.getElementById("serverCreateName");
  const fileInput = document.getElementById("serverCreateIconFile");
  const pickBtn = document.getElementById("btnServerCreateIconPick");
  const clearBtn = document.getElementById("btnServerCreateIconClear");
  const previewBtn = document.getElementById("serverCreateIconPreview");
  const closeBtn = document.getElementById("btnServerCreateClose");
  const cancelBtn = document.getElementById("btnServerCreateCancel");
  const confirmBtn = document.getElementById("btnServerCreateConfirm");

  modal.addEventListener("click", (event) => {
    if (serverChannelCreateSaving) return;
    const target = eventTargetElement(event);
    if (target?.dataset?.close) closeServerCreateModal();
  });
  closeBtn?.addEventListener("click", closeServerCreateModal);
  cancelBtn?.addEventListener("click", closeServerCreateModal);
  pickBtn?.addEventListener("click", () => fileInput?.click?.());
  previewBtn?.addEventListener("click", () => fileInput?.click?.());
  clearBtn?.addEventListener("click", () => {
    clearServerCreateIconDraft();
    renderServerCreateIconPreview();
  });
  nameInput?.addEventListener("input", () => {
    serverCreateName = String(nameInput.value || "").trim();
    renderServerCreateIconPreview();
  });
  fileInput?.addEventListener("change", () => {
    const file = fileInput.files?.[0] || null;
    if (serverCreateIconPreviewUrl) safeRevokeObjectUrl(serverCreateIconPreviewUrl);
    serverCreateIconFile = file;
    serverCreateIconPreviewUrl = file ? URL.createObjectURL(file) : "";
    renderServerCreateIconPreview();
  });
  confirmBtn?.addEventListener("click", () => {
    warnMissingOptionalUiHookOnce("serverCreateConfirm", "[server-create] create submit handler is unavailable in this build.");
  });
}

async function openServerCreateModal() {
  bindServerCreateModalOnce();
  const modal = document.getElementById("serverCreateModal");
  if (!modal) return false;
  const nameInput = document.getElementById("serverCreateName");
  clearServerCreateIconDraft();
  serverCreateName = "";
  if (nameInput) nameInput.value = "";
  renderServerCreateIconPreview();
  modal.classList.remove("hidden");
  modal.hidden = false;
  modal.setAttribute("aria-hidden", "false");
  requestAnimationFrame(() => {
    try { nameInput?.focus?.(); } catch (_) {}
  });
  return true;
}

function closeServerChannelCreateModal({ force = false } = {}) {
  if (serverChannelCreateSaving && !force) return;
  const modal = document.getElementById("serverChannelCreateModal");
  if (!modal) return;
  modal.classList.add("hidden");
  modal.setAttribute("aria-hidden", "true");
  serverChannelCreateSaving = false;
  serverChannelCreateMode = "create";
  serverChannelCreateEditChannelId = "";
  serverChannelCreateEditConversationId = "";
  serverChannelCreateEditCategoryId = "";
  serverChannelCreateOrigin = "";
  serverChannelEditModalContext = null;
  serverChannelCreateMutationState = null;
  serverChannelCreatePrivateLoading = false;
  serverChannelCreateAllowedRoleIds.clear();
  serverChannelCreateAllowedUserIds.clear();
  if (serverChannelCreateSavedStatusTimer) {
    clearTimeout(serverChannelCreateSavedStatusTimer);
    serverChannelCreateSavedStatusTimer = 0;
  }
}

function normalizeServerChannelManagementName(value = "", fallback = "general") {
  const raw = String(value || "").trim().replace(/^#+/, "").replace(/\s+/g, "-").replace(/[^\p{L}\p{N}_\- ]/gu, "").trim();
  return normalizeConversationLabel(raw || fallback, fallback).slice(0, 72);
}

function getServerChannelManagementErrorMessage(error = null) {
  if (isMissingRpcError(error)) return "Channel management SQL patch is required.";
  const raw = String(error?.message || error || "Unknown error").trim();
  if (!raw) return "Unknown error";
  if (/missing_manage_channels|permission|42501|not authorized|not_authenticated/i.test(raw)) return "You don't have permission to manage channels.";
  if (/target_channel_not_voice|invalid_channel_type|channel_type/i.test(raw)) return "Invalid channel type.";
  if (/category_not_found|invalid_category/i.test(raw)) return "Category not found.";
  if (/channel_not_found/i.test(raw)) return "Channel not found.";
  return raw;
}

function setServerChannelCreateStatus(message = "", { error = false, success = false } = {}) {
  const sub = document.getElementById("serverChannelCreateSub");
  if (!sub) return;
  sub.textContent = String(message || "").trim() || "Choose a channel type and name.";
  sub.classList.toggle("is-error", !!error);
  sub.classList.toggle("is-success", !!success);
}

function recordServerChannelEditSaveClick(source = "programmatic") {
  const button = document.getElementById("btnServerChannelCreateConfirm");
  serverChannelEditSaveClickCount += 1;
  serverChannelEditLastSaveClickDebug = {
    clickedAt: Date.now(),
    clickCount: serverChannelEditSaveClickCount,
    source: String(source || "programmatic"),
    handlerInstalledCount: serverChannelCreateConfirmHandlerInstallCount,
    buttonDisabled: !!button?.disabled,
    modalServerId: normId(serverChannelEditModalContext?.serverId || serverChannelCreateServerId || ""),
    canonicalChannelId: normId(serverChannelEditModalContext?.canonicalChannelId || serverChannelCreateEditChannelId || ""),
    conversationId: normId(serverChannelEditModalContext?.conversationId || serverChannelCreateEditConversationId || ""),
    mutationStarted: false,
    earlyReturnReason: "",
  };
  return serverChannelEditLastSaveClickDebug;
}

function getServerChannelCreateSelectedType() {
  const checked = document.querySelector("input[name='serverChannelCreateTypeRadio']:checked");
  const hidden = document.getElementById("serverChannelCreateType");
  const raw = String(checked?.value || hidden?.value || "text").trim().toLowerCase();
  return raw === "voice" || raw === "category" ? raw : "text";
}

