  window.altaraDebugChannelAccess.testExpectedPrivateAccess = function testExpectedPrivateAccess(serverId = "", channelId = "", allowedUserId = "", blockedUserId = "") {
    const sid = resolveChannelAccessDebugServerId(serverId);
    const cid = resolveChannelAccessDebugChannelId(channelId);
    const allowedUid = normId(allowedUserId || "");
    const blockedUid = normId(blockedUserId || "");
    const resolveFor = (uid) => {
      if (!uid) return null;
      const r = resolveEffectiveChannelPermissionsForUser({
        serverId: sid,
        channelId: cid,
        userId: uid,
        reason: "debug-test-expected-private-access",
      });
      return {
        userId: uid,
        canView: !!(r?.isOwner || r?.permissions?.view_channels === true),
        isOwner: !!r?.isOwner,
        trace: r?.trace || null,
      };
    };
    const allowed = resolveFor(allowedUid);
    const blocked = resolveFor(blockedUid);
    const result = {
      serverId: sid,
      channelId: cid,
      allowed,
      blocked,
      pass: !!(
        (!allowedUid || allowed?.canView === true)
        && (!blockedUid || blocked?.canView === false)
      ),
    };
    console.info("[channel-access] test-expected-private-access", result);
    return result;
  };

  window.altaraDebugChannelAccess.testPrivateAccessMatrix = function testPrivateAccessMatrix(
    serverId = "",
    channelId = "",
    {
      ownerUserId = "",
      allowedMemberUserId = "",
      blockedMemberUserId = "",
    } = {}
  ) {
    const identity = getChannelAccessDebugIdentity(serverId, channelId);
    const sid = identity.serverId;
    const cid = identity.channelRowId;
    const resolveFor = (userId, label) => {
      const uid = normId(userId || "");
      if (!uid) return { label, userId: "", canView: null, ownerBypass: false, matchingOverwriteRows: [] };
      const resolved = resolveEffectiveChannelPermissionsForUser({
        serverId: sid,
        channelId: cid,
        userId: uid,
        reason: `debug-private-access-matrix-${label}`,
      });
      return {
        label,
        userId: uid,
        canView: !!(resolved?.isOwner || resolved?.permissions?.view_channels === true),
        ownerBypass: !!(resolved?.isOwner || resolved?.trace?.owner_bypass),
        matchingOverwriteRows: getChannelPermissionOverwrites(cid).filter((row) => (
          (row.targetType === "everyone" && row.targetId === sid)
          || (row.targetType === "member" && row.targetId === uid)
          || (row.targetType === "role" && getCachedServerMemberRoleIdsForUser(sid, uid).includes(row.targetId))
        )),
        trace: resolved?.trace || null,
      };
    };
    const owner = resolveFor(ownerUserId, "owner");
    const allowedMember = resolveFor(allowedMemberUserId, "allowed_member");
    const blockedMember = resolveFor(blockedMemberUserId, "blocked_member");
    const result = {
      serverId: sid,
      channelRowId: identity.channelRowId,
      conversationId: identity.conversationId,
      rpcChannelId: cid,
      modalSelectedUserIds: Array.from(serverChannelCreateAllowedUserIds),
      owner,
      allowedMember,
      blockedMember,
      pass: owner.canView === true && allowedMember.canView === true && blockedMember.canView === false,
    };
    console.info("[channel-access] private-access-matrix", result);
    return result;
  };

