  window.altaraDebugChannelAccess.explainVisibilityPipeline = async function explainVisibilityPipeline(serverId = "", channelId = "", userId = "") {
    let identity = getChannelAccessDebugIdentity(serverId, channelId);
    const resolvedChannel = await resolveServerChannelForServer(identity.serverId, {
      channelId: identity.requestedChannelId,
      conversationId: identity.conversationId,
    }).catch(() => null);
    if (resolvedChannel?.id) {
      identity = {
        ...identity,
        channel: resolvedChannel,
        channelRowId: normId(resolvedChannel.id),
        conversationId: normId(resolvedChannel.conversationId || identity.conversationId),
      };
    }
    const sid = identity.serverId;
    const cid = identity.channelRowId;
    const uid = normId(userId || state.user?.id || "");
    await Promise.allSettled([
      resolveCanonicalServerOwnerUserId(sid, { force: true }),
      ensureServerRolePermissionCache(sid, { force: true }),
      fetchServerMembersForSidebar(sid, { force: true }),
      loadChannelPermissionOverwrites(sid, cid, { force: true }),
    ]);
    const canonicalOwnerUserId = getCanonicalServerOwnerUserIdSync(sid);
    const member = getCachedServerMemberForUser(sid, uid) || null;
    const effective = resolveEffectiveChannelPermissionsForUser({
      serverId: sid,
      channelId: cid,
      userId: uid,
      reason: "debug-visibility-pipeline",
    });
    const matchingOverwriteRows = getChannelPermissionOverwrites(cid).filter((row) => (
      (row.targetType === "everyone" && row.targetId === sid)
      || (row.targetType === "member" && row.targetId === uid)
      || (row.targetType === "role" && getCachedServerMemberRoleIdsForUser(sid, uid).includes(row.targetId))
    ));
    const result = {
      serverId: sid,
      canonicalOwnerUserId,
      currentUserId: normId(state.user?.id || ""),
      userId: uid,
      modalSelectedRoleIds: Array.from(serverChannelCreateAllowedRoleIds),
      modalSelectedUserIds: Array.from(serverChannelCreateAllowedUserIds),
      profileId: normId(getCachedProfile(uid)?.id || uid),
      serverMemberUserId: getServerChannelPrivateAccessMemberUserId(member),
      channelRowId: cid,
      conversationId: identity.conversationId,
      rpcChannelId: cid,
      persistedOverwriteChannelIds: Array.from(new Set(getChannelPermissionOverwrites(cid).map((row) => row.channelId))),
      matchingOverwriteRows,
      targetType: matchingOverwriteRows.find((row) => row.targetType === "member")?.targetType || null,
      targetId: matchingOverwriteRows.find((row) => row.targetType === "member")?.targetId || null,
      allow: matchingOverwriteRows.find((row) => row.targetType === "member")?.allow || {},
      deny: matchingOverwriteRows.find((row) => row.targetType === "member")?.deny || {},
      effectiveViewChannels: effective?.permissions?.view_channels === true,
      ownerBypass: !!(effective?.isOwner || effective?.trace?.owner_bypass),
      sidebarVisible: uid === normId(state.user?.id || "")
        ? canCurrentUserViewServerChannelSync(sid, cid)
        : effective?.permissions?.view_channels === true,
      directOpenAllowed: !!(effective?.isOwner || effective?.permissions?.view_channels === true),
      trace: effective?.trace || null,
    };
    console.info("[channel-access] visibility-pipeline", result);
    return result;
  };

