  window.altaraDebugChannelAccess.simulateSingleSaveGuard = async function simulateSingleSaveGuard() {
    const key = "debug-single-flight";
    let mutationRuns = 0;
    let ignored = 0;
    const start = () => {
      const existing = serverChannelCreateSaveInFlightByChannel.get(key);
      if (existing) {
        ignored += 1;
        return existing;
      }
      mutationRuns += 1;
      const promise = altaraDelay(40).finally(() => {
        if (serverChannelCreateSaveInFlightByChannel.get(key) === promise) {
          serverChannelCreateSaveInFlightByChannel.delete(key);
        }
      });
      serverChannelCreateSaveInFlightByChannel.set(key, promise);
      return promise;
    };
    await Promise.all([start(), start(), start(), start(), start()]);
    const result = { requestedClicks: 5, mutationRuns, ignored, pass: mutationRuns === 1 && ignored === 4 };
    console.info("[channel-access] single-save-guard", result);
    return result;
  };

