async function uploadServerIconFile(file, { serverId = "" } = {}) {
  if (!file || !state.user?.id) throw new Error("Upload de icon do server invalido.");
  const contentType = String(file.type || "").trim().toLowerCase();
  if (!contentType.startsWith("image/")) {
    throw new Error("O icon do server tem de ser uma imagem.");
  }
  throwIfAltaraUploadLimitExceeded(file, {
    technicalHardCapBytes: SERVER_ICON_MAX_BYTES,
    technicalMessage: "Icon do server demasiado grande (max 8MB).",
  });

  const uploadFile = await maybeResizeStaticImageFileForUpload(file, {
    maxDimension: STATIC_AVATAR_UPLOAD_MAX_DIMENSION,
    quality: STATIC_AVATAR_UPLOAD_QUALITY,
  });
  const ext = (String(uploadFile.name || file.name || "").split(".").pop() || "png").toLowerCase();
  const { ext: safeExt, mime } = resolveAvatarMimeAndExt(ext, uploadFile.type || file.type || "");
  const serverTag = normId(serverId) || "draft";
  const path = `${state.user.id}/server_${serverTag}_${Date.now()}.${safeExt}`;
  const upload = await uploadFileViaAltaraStorage(uploadFile, {
    fileName: uploadFile.name || file.name || ("server_icon." + safeExt),
    path,
    contentType: mime,
    cacheControl: "31536000",
    uploadContext: "server_icon",
  });
  const publicUrl = String(upload?.publicUrl || "").trim();
  if (!publicUrl) throw new Error("Nao consegui gerar URL publica para o icon do server.");
  return publicUrl;
}

async function uploadServerBannerFile(file, { serverId = "" } = {}) {
  if (!file || !state.user?.id) throw new Error("Upload de banner do server invalido.");
  const contentType = String(file.type || "").trim().toLowerCase();
  const rawExt = (String(file.name || "").split(".").pop() || "").toLowerCase();
  const looksImage = contentType.startsWith("image/") || /^(png|jpe?g|webp|gif)$/i.test(rawExt);
  if (!looksImage) {
    throw new Error("O banner do server tem de ser uma imagem.");
  }
  const isGif = contentType === "image/gif" || rawExt === "gif";
  throwIfAltaraUploadLimitExceeded(file, {
    technicalHardCapBytes: isGif ? (15 * ALTARA_PLUS_LIMIT_UPLOAD_MB) : (10 * ALTARA_PLUS_LIMIT_UPLOAD_MB),
    technicalMessage: isGif ? "GIF do server demasiado grande (max 15MB)." : "Banner otimizado demasiado grande.",
  });

  const uploadFile = file;
  const ext = (String(uploadFile.name || file.name || "").split(".").pop() || "png").toLowerCase();
  const { ext: safeExt, mime } = resolveAvatarMimeAndExt(ext, uploadFile.type || file.type || "");
  const serverTag = normId(serverId) || "draft";
  const path = `${state.user.id}/server-banners/${serverTag}_${Date.now()}.${safeExt}`;
  const upload = await uploadFileViaAltaraStorage(uploadFile, {
    fileName: uploadFile.name || file.name || ("server_banner." + safeExt),
    path,
    contentType: mime,
    cacheControl: "31536000",
    uploadContext: "server_banner",
  });
  const publicUrl = String(upload?.publicUrl || "").trim();
  if (!publicUrl) throw new Error("Nao consegui gerar URL publica para o banner do server.");
  return publicUrl;
}

function getServerRowById(serverId = "") {
  const sid = normId(serverId);
  if (!sid || isServerDeletedLocally(sid)) return null;
  return (state.servers || []).find((row) => normId(row?.serverId || "") === sid && !isServerDeletedLocally(row?.serverId || "")) || null;
}

async function readServerWelcomeChannelFromTable(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return { welcomeConversationId: "", defaultConversationId: "" };
  const fromRpc = async () => {
    const rpc = await readServerWelcomeChannelFromRpc(sid);
    if (!rpc) return null;
    return {
      welcomeConversationId: normId(rpc?.welcomeConversationId || ""),
      defaultConversationId: normId(rpc?.defaultConversationId || ""),
    };
  };
  try {
    const primary = await supabase
      .from("servers")
      .select("id, welcome_channel_id, default_conversation_id")
      .eq("id", sid)
      .maybeSingle();
    if (!primary?.error && primary?.data) {
      return {
        welcomeConversationId: normId(primary.data?.welcome_channel_id || ""),
        defaultConversationId: normId(primary.data?.default_conversation_id || ""),
      };
    }

    if (isMissingColumnError(primary?.error, "default_conversation_id")) {
      const withoutDefault = await supabase
        .from("servers")
        .select("id, welcome_channel_id")
        .eq("id", sid)
        .maybeSingle();
      if (!withoutDefault?.error && withoutDefault?.data) {
        return {
          welcomeConversationId: normId(withoutDefault.data?.welcome_channel_id || ""),
          defaultConversationId: "",
        };
      }
    }

    if (isMissingColumnError(primary?.error, "welcome_channel_id")) {
      const legacy = await supabase
        .from("servers")
        .select("id, welcome_conversation_id, default_conversation_id")
        .eq("id", sid)
        .maybeSingle();
      if (!legacy?.error && legacy?.data) {
        return {
          welcomeConversationId: normId(legacy.data?.welcome_conversation_id || ""),
          defaultConversationId: normId(legacy.data?.default_conversation_id || ""),
        };
      }

      if (isMissingColumnError(legacy?.error, "default_conversation_id")) {
        const legacyWithoutDefault = await supabase
          .from("servers")
          .select("id, welcome_conversation_id")
          .eq("id", sid)
          .maybeSingle();
        if (!legacyWithoutDefault?.error && legacyWithoutDefault?.data) {
          return {
            welcomeConversationId: normId(legacyWithoutDefault.data?.welcome_conversation_id || ""),
            defaultConversationId: "",
          };
        }
      }
    }
    const rpcFallback = await fromRpc();
    if (rpcFallback) return rpcFallback;
    return { welcomeConversationId: "", defaultConversationId: "" };
  } catch (_) {
    const rpcFallback = await fromRpc();
    if (rpcFallback) return rpcFallback;
    return { welcomeConversationId: "", defaultConversationId: "" };
  }
}

async function readServerWelcomeChannelFromRpc(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return null;
  const payloads = [
    { p_server_id: sid },
    { server_id: sid },
  ];
  let lastErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("get_server_welcome_channel", payload);
    if (!res?.error) {
      const row = Array.isArray(res?.data) ? (res.data[0] || null) : (res?.data || null);
      if (!row) return { welcomeConversationId: "", defaultConversationId: "" };
      return {
        welcomeConversationId: normId(row?.welcome_channel_id || row?.welcome_conversation_id || ""),
        defaultConversationId: normId(row?.default_conversation_id || ""),
      };
    }
    if (!isMissingRpcError(res?.error)) {
      lastErr = res?.error || null;
      break;
    }
    lastErr = res?.error || null;
  }
  if (lastErr && !isMissingRpcError(lastErr)) {
    console.warn("get_server_welcome_channel rpc failed", lastErr);
  }
  return null;
}

async function saveServerWelcomeChannelViaRpc(serverId = "", conversationId = "") {
  const sid = normId(serverId || "");
  if (!sid) return { ok: false, error: { message: "server_id invalido" }, needsPatch: false };
  const nextId = normId(conversationId || "");
  const payloadValue = nextId || null;
  const payloads = [
    { p_server_id: sid, p_welcome_channel_id: payloadValue },
    { server_id: sid, welcome_channel_id: payloadValue },
    { p_server_id: sid, p_conversation_id: payloadValue },
    { server_id: sid, conversation_id: payloadValue },
  ];
  let lastErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("set_server_welcome_channel", payload);
    if (!res?.error) {
      const row = Array.isArray(res?.data) ? (res.data[0] || null) : (res?.data || null);
      const savedId = normId(row?.welcome_channel_id || row?.welcome_conversation_id || nextId);
      return { ok: true, error: null, column: "rpc:set_server_welcome_channel", value: savedId };
    }
    if (!isMissingRpcError(res?.error)) {
      lastErr = res?.error || null;
      break;
    }
    lastErr = res?.error || null;
  }
  if (lastErr && isMissingRpcError(lastErr)) {
    return { ok: false, error: lastErr, needsPatch: true };
  }
  return { ok: false, error: lastErr || { message: "rpc falhou" }, needsPatch: false };
}

async function saveServerWelcomeChannelToTable(serverId = "", conversationId = "") {
  const sid = normId(serverId || "");
  if (!sid) return { ok: false, error: { message: "server_id invalido" }, needsPatch: false };
  const nextId = normId(conversationId || "");
  const payloadValue = nextId || null;

  const primary = await supabase
    .from("servers")
    .update({ welcome_channel_id: payloadValue })
    .eq("id", sid)
    .select("id")
    .maybeSingle();
  if (!primary?.error) {
    const verify = await readServerWelcomeChannelFromTable(sid);
    const savedId = normId(verify?.welcomeConversationId || "");
    if (savedId === nextId) {
      return { ok: true, error: null, column: "welcome_channel_id", value: nextId };
    }
    const rpcFallback = await saveServerWelcomeChannelViaRpc(sid, nextId);
    if (rpcFallback?.ok) return rpcFallback;
    return {
      ok: false,
      error: {
        message: rpcFallback?.needsPatch
          ? "Falhou ao confirmar o canal de bem-vindo. Verifica permissoes do server (RLS/update)."
          : "Falhou ao confirmar o canal de bem-vindo. Verifica permissoes/RLS do server."
      },
      needsPatch: false,
    };
  }

  if (isMissingColumnError(primary.error, "welcome_channel_id")) {
    const legacy = await supabase
      .from("servers")
      .update({ welcome_conversation_id: payloadValue })
      .eq("id", sid)
      .select("id")
      .maybeSingle();
    if (!legacy?.error) {
      const verify = await readServerWelcomeChannelFromTable(sid);
      const savedId = normId(verify?.welcomeConversationId || "");
      if (savedId === nextId) {
        return { ok: true, error: null, column: "welcome_conversation_id", value: nextId };
      }
      const rpcFallback = await saveServerWelcomeChannelViaRpc(sid, nextId);
      if (rpcFallback?.ok) return rpcFallback;
      return {
        ok: false,
        error: {
          message: rpcFallback?.needsPatch
            ? "Falhou ao confirmar o canal de bem-vindo. Verifica permissoes do server (RLS/update)."
            : "Falhou ao confirmar o canal de bem-vindo. Verifica permissoes/RLS do server."
        },
        needsPatch: false,
      };
    }
    if (isMissingColumnError(legacy.error, "welcome_conversation_id")) {
      const rpcFallback = await saveServerWelcomeChannelViaRpc(sid, nextId);
      if (rpcFallback?.ok) return rpcFallback;
      return { ok: false, error: legacy.error, needsPatch: true };
    }
    const rpcFallback = await saveServerWelcomeChannelViaRpc(sid, nextId);
    if (rpcFallback?.ok) return rpcFallback;
    return {
      ok: false,
      error: legacy.error,
      needsPatch: !!rpcFallback?.needsPatch,
    };
  }

  const rpcFallback = await saveServerWelcomeChannelViaRpc(sid, nextId);
  if (rpcFallback?.ok) return rpcFallback;
  return {
    ok: false,
    error: primary.error,
    needsPatch: !!rpcFallback?.needsPatch,
  };
}

async function resolveServerWelcomeChannelConversationId(serverId = "", {
  fallbackConversationId = "",
  forceLookup = false,
} = {}) {
  const sid = normId(serverId || "");
  if (!sid) return "";

  const row = getServerRowById(sid);
  let welcomeConversationId = normId(row?.welcomeConversationId || "");
  let defaultConversationId = normId(row?.defaultConversationId || fallbackConversationId || "");

  if (forceLookup || !welcomeConversationId || !defaultConversationId) {
    const lookup = await readServerWelcomeChannelFromTable(sid);
    if (lookup?.welcomeConversationId) welcomeConversationId = normId(lookup.welcomeConversationId);
    if (lookup?.defaultConversationId) defaultConversationId = normId(lookup.defaultConversationId);
    if (row && lookup?.welcomeConversationId) row.welcomeConversationId = normId(lookup.welcomeConversationId);
  }

  const channels = await fetchServerChannelsForSidebar(sid, { force: false }).catch(() => []);
  const textChannels = (channels || []).filter((ch) => normalizeConversationChannelType(ch?.channelType || "") !== "voice");
  const textByConversationId = new Set(textChannels.map((ch) => normId(ch?.conversationId || "")).filter(Boolean));

  const candidates = [
    welcomeConversationId,
    defaultConversationId,
    normId(fallbackConversationId || ""),
  ].filter(Boolean);

  for (const candidate of candidates) {
    if (textByConversationId.has(candidate)) return candidate;
  }
  // IMPORTANT:
  // Fallback should prefer the server default channel, not an arbitrary first channel.
  return candidates[0] || "";
}

async function renderServerSettingsWelcomeChannelOptions(serverId = "") {
  const sid = normId(serverId || serverSettingsServerId || "");
  const selectEl = document.getElementById("serverSettingsWelcomeChannel");
  const hintEl = document.getElementById("serverSettingsWelcomeHint");
  if (!sid || !selectEl) return;

  selectEl.disabled = true;
  selectEl.innerHTML = `<option value="">Loading channels...</option>`;
  if (hintEl) hintEl.textContent = "Member join/leave messages are posted in this channel.";

  const channels = await fetchServerChannelsForSidebar(sid, { force: true }).catch(() => []);
  const textChannels = (channels || []).filter((ch) => normalizeConversationChannelType(ch?.channelType || "") !== "voice");
  const tableRow = await readServerWelcomeChannelFromTable(sid);
  const explicitWelcomeId = normId(
    tableRow?.welcomeConversationId
    || getServerRowById(sid)?.welcomeConversationId
    || serverSettingsWelcomeChannelId
    || ""
  );
  const defaultConversationId = normId(
    tableRow?.defaultConversationId
    || getServerRowById(sid)?.defaultConversationId
    || ""
  );
  serverSettingsWelcomeChannelId = explicitWelcomeId;

  if (!textChannels.length) {
    selectEl.innerHTML = `<option value="">No text channels available</option>`;
    selectEl.disabled = true;
    if (hintEl) hintEl.textContent = "Create a text channel first to enable welcome logs.";
    renderServerSettingsProfilePreview();
    return;
  }

  const defaultChannelLabel = (() => {
    const found = textChannels.find((ch) => normId(ch?.conversationId || "") === defaultConversationId);
    const rawName = found?.name || "general";
    return `Default server chat (# ${normalizeConversationLabel(rawName, "general")})`;
  })();

  const defaultOption = `<option value="">${esc(defaultChannelLabel)}</option>`;
  const optionsHtml = textChannels.map((ch) => {
    const convId = normId(ch?.conversationId || "");
    const channelName = normalizeConversationLabel(ch?.name || "general", "general");
    const selected = convId && convId === explicitWelcomeId ? " selected" : "";
    return `<option value="${escAttr(convId)}"${selected}># ${esc(channelName)}</option>`;
  }).join("");
  selectEl.innerHTML = `${defaultOption}${optionsHtml}`;

  const optionValues = new Set(textChannels.map((ch) => normId(ch?.conversationId || "")).filter(Boolean));
  if (explicitWelcomeId && optionValues.has(explicitWelcomeId)) {
    selectEl.value = explicitWelcomeId;
  } else {
    selectEl.value = "";
    serverSettingsWelcomeChannelId = "";
  }

  selectEl.disabled = false;
  if (hintEl) hintEl.textContent = "If empty, welcome logs use the default chat created by the server.";
  renderServerSettingsProfilePreview();
}

function getServerMyRole(serverId = "") {
  const sid = normId(serverId);
  if (!sid) return "";
  const meId = normId(state.user?.id || "");
  if (!meId) return "";
  const members = serverMemberListByServerId.get(sid) || [];
  const meRow = (members || []).find((m) => normId(m?.userId || "") === meId) || null;
  return String(meRow?.role || "").trim().toLowerCase();
}

function isServerActualOwner(serverId = "") {
  const sid = normId(serverId);
  const meId = normId(state.user?.id || "");
  if (!sid || !meId) return false;
  const ownerUserId = getCanonicalServerOwnerUserIdSync(sid);
  return !!(ownerUserId && ownerUserId === meId);
}

function getServerCapabilityMeta(serverId = "") {
  const sid = normId(serverId);
  const meId = normId(state.user?.id || "");
  const row = getServerRowById(sid);
  const ownerUserId = getCanonicalServerOwnerUserIdSync(sid);
  const role = getServerMyRole(sid);
  const isMember = !!(sid && row);
  const isActualOwner = !!(meId && ownerUserId && ownerUserId === meId);
  const isOwner = !!(meId && (isActualOwner || role === "owner"));
  const isAdmin = role === "admin" || isOwner;
  return {
    isMember,
    isOwner,
    isActualOwner,
    isAdmin,
    canInvite: currentUserCanCreateInvites(sid),
    canSettings: isAdmin || isOwner,
    canLeave: isMember && !isOwner,
    canDelete: isActualOwner,
  };
}

function clearServerSettingsIconDraft() {
  if (serverSettingsIconPreviewUrl) safeRevokeObjectUrl(serverSettingsIconPreviewUrl);
  serverSettingsIconPreviewUrl = "";
  serverSettingsIconFile = null;
  const input = document.getElementById("serverSettingsIconFile");
  if (input) input.value = "";
}

async function inviteServerMembersRpc(serverId, memberIds = []) {
  const sid = normId(serverId);
  const ids = normalizeUuidArray(memberIds);
  if (!sid || !ids.length) return { data: null, error: { message: "server_id ou member_ids invalido" } };

  const payloads = [
    { p_server_id: sid, p_member_ids: ids },
    { server_id: sid, member_ids: ids },
  ];
  let lastMissingErr = null;
  let lastRpcErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("invite_server_members", payload);
    if (!res?.error) return res;
    if (!isMissingRpcError(res.error)) return res;
    lastMissingErr = res.error;
  }
  return { data: null, error: lastMissingErr || { message: "rpc nao encontrada" } };
}

async function inviteServerMemberDirectFallback(serverId, userId) {
  const sid = normId(serverId);
  const uid = normId(userId);
  if (!sid || !uid) return { ok: false, error: { message: "server_id/user_id invalido" } };

  const rpcRes = await inviteServerMembersRpc(sid, [uid]);
  if (!rpcRes?.error) return { ok: true, via: "rpc", data: rpcRes.data };
  if (!isMissingRpcError(rpcRes.error)) return { ok: false, error: rpcRes.error };

  // Fallback without RPC: insert member directly.
  const insertPayload = { server_id: sid, user_id: uid, role: "member" };
  let directRes = await supabase
    .from("server_members")
    .upsert(insertPayload, { onConflict: "server_id,user_id", ignoreDuplicates: true });

  if (directRes?.error) {
    const roleErr = String(directRes.error?.message || "").toLowerCase();
    const roleMissing = roleErr.includes("role") && roleErr.includes("column");
    if (roleMissing) {
      directRes = await supabase
        .from("server_members")
        .upsert({ server_id: sid, user_id: uid }, { onConflict: "server_id,user_id", ignoreDuplicates: true });
    }
  }
  if (directRes?.error) return { ok: false, error: directRes.error };

  return { ok: true, via: "direct" };
}

async function ensureSelfServerConversationMembership(serverId, { force = false } = {}) {
  void serverId;
  void force;
  // Server-channel access is enforced by RLS:
  // - public channels use server_members
  // - private channels use server-managed conversation_members allowlists
  // The client must not self-grant channel membership rows anymore.
}

function getInvitableServerFriends(serverId) {
  const sid = normId(serverId);
  if (!sid) return [];
  const memberSet = new Set(
    normalizeUuidArray((serverMemberListByServerId.get(sid) || []).map((row) => normId(row?.userId || "")))
  );

  return (state.friends || [])
    .map((row) => {
      const uid = normId(row?.other_user_id || row?.id || "");
      if (!uid) return null;
      if (memberSet.has(uid)) return null;
      const username = String(row?.username || "").trim();
      const displayName = normalizeConversationLabel(row?.display_name || username || "friend", "friend");
      return {
        userId: uid,
        username,
        displayName,
        avatarUrl: String(row?.avatar_url || "").trim(),
      };
    })
    .filter(Boolean)
    .sort((a, b) => String(a.displayName || "").localeCompare(String(b.displayName || "")));
}

async function reloadServerInviteCandidates({ force = false } = {}) {
  const sid = normId(serverInviteServerId || "");
  if (!sid) return { ok: false, error: { message: "server_id invalido" }, candidates: [] };
  await Promise.allSettled([
    fetchServerMembersForSidebar(sid, { force: !!force }),
    (!Array.isArray(state.friends) || !state.friends.length || force)
      ? supabase.rpc("list_my_friends").then(async ({ data, error }) => {
          if (!error) state.friends = await hydrateFriendRowsWithProfiles(data || []);
        })
      : Promise.resolve(),
  ]);
  const candidates = getInvitableServerFriends(sid);
  renderServerInviteFriendsList();
  return { ok: true, candidates };
}

async function ensureDmConversationWithFriendUser(userId) {
  const friend = getFriendRowByUserId(userId) || null;
  const username = String(friend?.username || "").trim();
  if (!friend || !username) {
    return {
      conversationId: "",
      friend,
      error: { message: "friend nao encontrado" },
    };
  }

  const displayName = normalizeConversationLabel(friend?.display_name || username || "DM", "DM");
  const avatarUrl = String(friend?.avatar_url || "").trim();
  const otherUserId = normId(friend?.other_user_id || friend?.id || "");
  const { data: conversationId, error } = await supabase.rpc("create_dm", { target_username: username });
  if (error || !conversationId) {
    return {
      conversationId: "",
      friend,
      error: error || { message: "nao foi possivel abrir a DM" },
    };
  }

  rememberDmConversationPeer(conversationId, otherUserId, "ensure-dm-conversation");
  setConversationMeta(conversationId, {
    kind: "dm",
    isGroup: false,
    displayName,
    username,
    otherUserId,
    avatarUrl,
    dmPrivacyState: "standard",
    dmPrivacyEpoch: 0,
  });

  return {
    conversationId,
    friend,
    error: null,
  };
}

function buildServerInviteDirectMessageText(serverId = "", inviteUrl = "") {
  const sid = normId(serverId || "");
  const serverName = normalizeConversationLabel(getServerRowById(sid)?.name || "this server", "this server");
  const url = String(inviteUrl || "").trim();
  return `You're invited to join ${serverName} on ALTARA:\n${url}`;
}

async function sendServerInviteLinkToFriend(userId = "") {
  const sid = normId(serverInviteServerId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return { ok: false, error: { message: "server_id/user_id invalido" } };
  if (serverInviteBusyUserId) return { ok: false, error: { message: "invite already in progress" } };

  serverInviteBusyUserId = uid;
  serverInviteLastInvitedUserId = "";
  renderServerInviteModalState({ busy: true, statusText: "Preparing invite..." });
  try {
    const linkResult = await ensureServerInviteLinkReady({ silent: false, forceRefresh: false });
    if (!linkResult?.ok || !linkResult.inviteUrl) {
      throw new Error(linkResult?.error?.message || "Could not create invite link.");
    }
    const dmResult = await ensureDmConversationWithFriendUser(uid);
    if (dmResult?.error || !dmResult?.conversationId) {
      throw new Error(dmResult?.error?.message || "Could not open DM.");
    }
    const sendResult = await sendPlainTextMessageToConversation(
      dmResult.conversationId,
      buildServerInviteDirectMessageText(sid, linkResult.inviteUrl)
    );
    if (!sendResult?.ok) {
      throw new Error(sendResult?.error?.message || "Could not send invite.");
    }
    serverInviteLastInvitedUserId = uid;
    renderServerInviteModalState({ busy: false, statusText: "Invite sent." });
    if (typeof showDmComposerNotice === "function") {
      showDmComposerNotice("Invite sent.", { title: "Server Invite" });
    }
    return { ok: true, userId: uid, inviteUrl: linkResult.inviteUrl, conversationId: dmResult.conversationId };
  } catch (error) {
    renderServerInviteModalState({ busy: false, statusText: `Invite failed: ${String(error?.message || error || "unknown error")}` });
    if (typeof showDmComposerNotice === "function") {
      showDmComposerNotice(`Invite failed: ${String(error?.message || error || "unknown error")}`, { title: "Server Invite" });
    }
    return { ok: false, error };
  } finally {
    serverInviteBusyUserId = "";
    renderServerInviteFriendsList();
  }
}

function normalizeDmPrivacyRpcPayload(input = null) {
  if (!input || typeof input !== "object") return null;
  return normalizeDmPrivacyPayload(input);
}

function isDmPrivacyRpcMissingError(error) {
  const text = String(error?.message || error || "").toLowerCase();
  return text.includes("function")
    && (
      text.includes("private_dm")
      || text.includes("direct_dm_encryption")
      || text.includes("switch_direct_dm_to_sync")
    );
}

function formatDmPrivacyRpcError(error, fallback = "Could not update Vault.") {
  if (isDmPrivacyRpcMissingError(error)) {
    return "Missing DM privacy SQL. Apply the hybrid DM privacy patch and reload.";
  }
  const code = String(error?.code || error?.error || "").trim().toLowerCase();
  const map = {
    conversation_not_found: "This DM is no longer available.",
    not_direct_dm: "Vault is only available in 1-to-1 direct messages.",
    not_one_to_one_dm: "Vault is only available in real 1-to-1 direct messages.",
    not_conversation_member: "You no longer have access to this DM.",
    request_already_pending: "A Vault request is already pending here.",
    request_not_pending: "There is no pending Vault request anymore.",
    requester_cannot_accept: "The requester cannot accept their own Vault request.",
    requester_cannot_reject: "The requester cannot reject their own Vault request.",
    only_requester_can_cancel: "Only the requester can cancel this Vault request.",
    unauthenticated: "Sign in before changing Vault for this DM.",
    peer_not_found: "Could not find the other person in this DM.",
    not_friends: "Vault is available between friends.",
    blocked_pair: "Vault cannot be requested while one of you has blocked the other.",
    missing_own_key: "Set up Vault on this device before requesting Vault.",
    crypto_unavailable: getDmE2eeSetupFailureMessage("crypto_unavailable"),
    indexeddb_unavailable: getDmE2eeSetupFailureMessage("indexeddb_unavailable"),
    local_private_key_store_failed: getDmE2eeSetupFailureMessage("local_private_key_store_failed"),
    public_key_upload_failed: getDmE2eeSetupFailureMessage("public_key_upload_failed"),
    rpc_error: getDmE2eeSetupFailureMessage("rpc_error"),
    auth_missing: getDmE2eeSetupFailureMessage("auth_missing"),
    invalid_public_key: getDmE2eeSetupFailureMessage("invalid_public_key"),
    missing_requester_key: "Your friend needs to set up Vault before new Vault messages can be sent.",
    requester_cannot_decline: "The requester cannot decline their own Vault request.",
    stale_request: "This Vault request changed before your action finished. Try again.",
    already_active: "Vault is already active here.",
    private_already_active: "Vault is already active here.",
    not_private_active: "Vault is not active in this conversation.",
    disable_request_already_pending: "A request to turn off Vault is already pending here.",
    disable_request_not_pending: "There is no pending request to turn off Vault anymore.",
    disable_requester_cannot_accept: "The person who requested turning off Vault cannot accept their own request.",
    disable_requester_cannot_reject: "The person who requested turning off Vault cannot reject their own request.",
    only_disable_requester_can_cancel: "Only the person who requested turning off Vault can cancel that request.",
  };
  if (code && map[code]) return map[code];
  return String(error?.message || error || fallback);
}

function isDmPrivacyRpcStateSyncError(error) {
  const code = String(error?.code || error?.error || "").trim().toLowerCase();
  return code === "stale_request"
    || code === "request_already_pending"
    || code === "request_not_pending"
    || code === "already_active"
    || code === "private_already_active"
    || code === "disable_request_not_pending";
}

function normalizeConversationPrivacyPatch(input = null) {
  const source = input?.privacy && typeof input.privacy === "object" ? input.privacy : input;
  if (!source || typeof source !== "object") return null;
  const privacyKeys = [
    "dm_privacy_state", "state", "dmPrivacyState",
    "dm_privacy_request_nonce", "request_nonce", "dmPrivacyRequestNonce",
    "dm_privacy_requested_by", "requested_by", "dmPrivacyRequestedBy",
    "dm_privacy_requested_at", "requested_at", "dmPrivacyRequestedAt",
    "dm_privacy_activated_at", "activated_at", "dmPrivacyActivatedAt",
    "dm_privacy_disabled_at", "disabled_at", "dmPrivacyDisabledAt",
    "dm_privacy_disabled_by", "disabled_by", "dmPrivacyDisabledBy",
    "dm_privacy_disable_request_nonce", "disable_request_nonce", "dmPrivacyDisableRequestNonce",
    "dm_privacy_disable_requested_by", "disable_requested_by", "dmPrivacyDisableRequestedBy",
    "dm_privacy_disable_requested_at", "disable_requested_at", "dmPrivacyDisableRequestedAt",
    "dm_privacy_epoch", "epoch", "dmPrivacyEpoch",
    "dm_privacy_source", "source", "dmPrivacySource",
  ];
  const hasAnyPrivacyField = privacyKeys.some((key) => Object.prototype.hasOwnProperty.call(source, key));
  if (!hasAnyPrivacyField) return null;
  return normalizeDmPrivacyPayload(source);
}

function patchConversationPrivacyState(conversationId, privacyPayloadOrConversationRow = {}, {
  rerender = true,
  refreshKeys = true,
  renderList = true,
  source = "unknown",
} = {}) {
  const convId = normId(conversationId || privacyPayloadOrConversationRow?.id || privacyPayloadOrConversationRow?.conversation_id || "");
  if (!convId) return null;
  const activeConversationIdForPatch = normId(state.activeDm?.conversationId || activeDmId || "");
  logDmPrivacyDebug("patch target", {
    source: String(source || "unknown"),
    conversationId: convId,
    activeConversationId: activeConversationIdForPatch,
    activeMatches: activeConversationIdForPatch === convId,
  });
  const patch = normalizeConversationPrivacyPatch(privacyPayloadOrConversationRow);
  if (!patch) return getConversationDmPrivacyMeta(convId);

  const oldPrivacyMeta = getConversationDmPrivacyMeta(convId);
  const oldMeta = summarizeDmPrivacyMetaForDebug(oldPrivacyMeta);
  const oldPrivacySignature = getDmPrivacySignature(oldPrivacyMeta);
  const projectedPrivacyMeta = buildDmPrivacyMeta({
    ...(oldPrivacyMeta || {}),
    ...(patch || {}),
  }, {
    fallbackKind: String(patch?.kind || oldPrivacyMeta?.kind || state.activeDm?.kind || "dm").trim().toLowerCase() || "dm",
  });
  const newPrivacySignature = getDmPrivacySignature(projectedPrivacyMeta);
  if (oldPrivacySignature === newPrivacySignature) {
    logDmPrivacyDebug("patch skipped unchanged", {
      source: String(source || "unknown"),
      conversationId: convId,
      state: oldMeta.state,
    });
    logDmPrivacyEventsDebug("patch skipped unchanged", {
      source: String(source || "unknown"),
      conversationId: convId,
      state: oldMeta.state,
    });
    return false;
  }
  const meta = applyConversationDmPrivacyMeta(convId, patch);
  const privacyChanged = true;
  let cacheUpdated = true;
  const patchRow = (row) => {
    if (!row || typeof row !== "object") return;
    const rowConvId = normId(row.conversationId || row.conversation_id || row.id || "");
    if (rowConvId !== convId) return;
    Object.assign(row, patch, meta);
  };
  [state.dmContacts, state.friends, state.groupDms].forEach((list) => {
    if (Array.isArray(list)) list.forEach(patchRow);
  });

  const isActive = getVisibleDmPrivacyConversationId() === convId;
  let activeHeaderUpdated = false;
  let bannerUpdated = false;
  if (isActive) {
    state.activeDm = {
      ...(state.activeDm || {}),
      ...patch,
      ...meta,
      conversationId: convId,
      kind: "dm",
    };
    if (normalizeDmPrivacyState(meta.dmPrivacyState) === "private_active") {
      if (refreshKeys) {
        void ensureDmE2eeBootstrapStarted({ force: true });
        const peerId = getActiveDirectDmPeerUserId();
        if (peerId) void refreshDirectDmPeerE2eeKeyStatus(convId, peerId, { force: true });
      }
    }
    if (rerender) {
      renderDmPrivacyUi();
      if (privacyChanged) {
        applyDmComposerEditUi();
        syncActiveConversationHeaderFromMeta();
      } else {
        logRenderDebug("privacy skipped unchanged", {
          conversationId: convId,
          source: String(source || "unknown"),
        });
      }
      try {
        activeHeaderUpdated = !!document.getElementById("dmPrivacyBadge");
        bannerUpdated = !!document.getElementById("dmPrivacyBanner");
      } catch (_) {}
    }
    if (shouldPollActiveDmPrivacy(convId)) startActiveDmPrivacyPolling(convId);
    else stopActiveDmPrivacyPolling();
  }

  if (renderList && privacyChanged) {
    try { queueLightweightDmListRenderFromState(); } catch (_) {}
    try { renderGroupsRail(); } catch (_) {}
  }
  logDmPrivacyDebug("patch applied", {
    ...getDmPrivacyDebugContext(convId),
    source: String(source || "unknown"),
    oldState: oldMeta.state,
    newState: normalizeDmPrivacyState(meta.dmPrivacyState),
    requestedBy: normId(meta.dmPrivacyRequestedBy || ""),
    epoch: normalizeDmPrivacyEpoch(meta.dmPrivacyEpoch, 0),
    activeConversationMatches: isActive,
    activeHeaderUpdated,
    bannerUpdated,
    cacheUpdated,
  });
  logDmPrivacyEventsDebug("patch applied", {
    source: String(source || "unknown"),
    conversationId: convId,
    oldState: oldMeta.state,
    newState: normalizeDmPrivacyState(meta.dmPrivacyState),
    activeConversationMatches: isActive,
  });
  return meta;
}

async function handleDmPrivacySoftStateError(error, conversationId = "") {
  const code = String(error?.code || error?.error || "").trim().toLowerCase();
  const message = String(error?.message || error || "").trim().toLowerCase();
  const isRequestAlreadyPending = code === "request_already_pending" || message.includes("already pending");
  const isAlreadyActive = code === "already_active"
    || code === "private_already_active"
    || message.includes("already active")
    || message.includes("already encrypted");
  const isSoftStateMessage = message.includes("no pending private dm request")
    || message.includes("request is no longer pending")
    || message.includes("request was already")
    || isRequestAlreadyPending
    || isAlreadyActive;
  if (!isDmPrivacyRpcStateSyncError(error) && !isSoftStateMessage) return false;
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (convId) {
    logDmPrivacyActivePollDebug(isRequestAlreadyPending ? "request_already_pending direct fetch" : "stale rpc direct fetch", {
      conversationId: convId,
      code: code || (isAlreadyActive ? "already_active" : "soft_state"),
    });
    if (normId(activeDmId || state.activeDm?.conversationId || "") === convId && isDirectDmConversationKind(state.activeDm?.kind || "")) {
      startActiveDmPrivacyPolling(convId, { immediate: true });
      await reconcileActiveDmPrivacyStateFromServer(convId, { source: "stale-error-refetch" }).catch(() => {});
    } else {
      await refreshDmPrivacyMetaFromServer(convId, { rerender: true, source: "stale-error-refetch" }).catch(() => {});
    }
    scheduleDmPrivacyFollowupRefetch(convId);
  }
  showDmPrivacyToast(t("dm.privacy.toast_state_updated", "Vault request was already updated."));
  return true;
}

async function ensureDmPrivacyFeatureCapsForSync(conversationId = "", reason = "sync") {
  if (!isDirectDmE2eeEnabled()) return false;
  if (dmFeatureCaps.dmPrivacyState) return true;
  if (!activeDmPrivacyFeatureCapsPromise) {
    logDmPrivacyDebug("feature caps refresh", {
      ...getDmPrivacyDebugContext(conversationId),
      reason: String(reason || "sync"),
      previousDmPrivacyStateCap: !!dmFeatureCaps.dmPrivacyState,
    });
    activeDmPrivacyFeatureCapsPromise = ensureDmFeatureCaps(true)
      .catch((error) => {
        logDmPrivacyDebug("feature caps refresh failed", {
          ...getDmPrivacyDebugContext(conversationId),
          reason: String(reason || "sync"),
          error: String(error?.message || error || "unknown"),
        });
        return dmFeatureCaps;
      })
      .finally(() => {
        activeDmPrivacyFeatureCapsPromise = null;
      });
  }
  const caps = await activeDmPrivacyFeatureCapsPromise;
  return !!caps?.dmPrivacyState;
}

async function fetchConversationPrivacyRowDirect(conversationId = "", { reason = "refetch" } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return { row: null, error: new Error("conversation_id_missing") };
  const capsReady = await ensureDmPrivacyFeatureCapsForSync(convId, reason);
  if (!capsReady) return { row: null, error: new Error("dm_privacy_columns_unavailable") };
  try {
    const { data, error } = await supabase
      .from("conversations")
      .select(buildDmPrivacyConversationSelectColumns())
      .eq("id", convId)
      .maybeSingle();
    if (error) return { row: null, error };
    return { row: data || null, error: null };
  } catch (error) {
    return { row: null, error };
  }
}

async function refreshDmPrivacyMetaFromServer(conversationId = "", { rerender = true, source = "refetch" } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!isDirectDmE2eeEnabled()) {
    if (convId) {
      return patchConversationPrivacyState(convId, {
        kind: "dm",
        dm_privacy_state: "standard",
        dm_privacy_request_nonce: null,
        dm_privacy_requested_by: null,
        dm_privacy_requested_at: null,
        dm_privacy_activated_at: null,
        dm_privacy_disabled_at: null,
        dm_privacy_disabled_by: null,
        dm_privacy_disable_request_nonce: null,
        dm_privacy_disable_requested_by: null,
        dm_privacy_disable_requested_at: null,
        dm_privacy_epoch: 0,
      }, { rerender, refreshKeys: false, source });
    }
    if (rerender) {
      renderDmPrivacyUi();
      applyDmComposerEditUi();
    }
    return getConversationDmPrivacyMeta(convId);
  }
  if (!convId) {
    if (rerender) {
      renderDmPrivacyUi();
      applyDmComposerEditUi();
    }
    return getConversationDmPrivacyMeta(convId);
  }

  const { row, error } = await fetchConversationPrivacyRowDirect(convId, { reason: source });
  if (row) {
    const nextMeta = patchConversationPrivacyState(convId, {
      ...row,
      kind: String(row?.kind || "dm").trim().toLowerCase() || "dm",
    }, { rerender, refreshKeys: true, source });
    if (nextMeta?.dmPrivacyState === "private_active") {
      void ensureDmE2eeBootstrapStarted();
    }
    return nextMeta;
  }

  logDmPrivacyDebug("refetch failed", {
    ...getDmPrivacyDebugContext(convId),
    source: String(source || "refetch"),
    error: String(error?.message || error || "no_row"),
  });
  if (rerender) {
    renderDmPrivacyUi();
    applyDmComposerEditUi();
    syncActiveConversationHeaderFromMeta();
  }
  return getConversationDmPrivacyMeta(convId);
}

async function fetchConversationPrivacyState(conversationId = "", { rerender = true, source = "fetch" } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId) throw new Error("conversation_id_missing");
  const { row, error } = await fetchConversationPrivacyRowDirect(convId, { reason: source });
  if (!row) {
    throw error || new Error("conversation_privacy_state_unavailable");
  }
  logDmPrivacyEventsDebug("fetch privacy result", {
    conversationId: convId,
    dm_privacy_state: normalizeDmPrivacyState(row?.dm_privacy_state || row?.dmPrivacyState || "standard"),
    dm_privacy_requested_by: normId(row?.dm_privacy_requested_by || row?.dmPrivacyRequestedBy || ""),
    dm_privacy_epoch: normalizeDmPrivacyEpoch(row?.dm_privacy_epoch ?? row?.dmPrivacyEpoch, 0),
  });
  const meta = patchConversationPrivacyState(convId, {
    ...row,
    kind: String(row?.kind || "dm").trim().toLowerCase() || "dm",
  }, { rerender, refreshKeys: true, source });
  if (meta?.dmPrivacyState === "private_active") {
    void ensureDmE2eeBootstrapStarted();
  }
  return meta;
}

async function applyDmPrivacyRpcResult(result = {}, conversationId = "", { action = "" } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  const privacyPayload = normalizeDmPrivacyRpcPayload(result?.privacy || null);
  if (convId && privacyPayload) {
    if (normId(activeDmId || state.activeDm?.conversationId || "") === convId && isDirectDmConversationKind(state.activeDm?.kind || "")) {
      startActiveDmPrivacyListener(convId);
    }
    setConversationPrivacyState(convId, privacyPayload, { rerender: true, refreshKeys: true, source: "rpc" });
    scheduleDmPrivacyFollowupRefetch(convId);
    void refreshDmPrivacyMetaFromServer(convId, { rerender: true, source: "rpc-followup" }).catch(() => {});
    return;
  }
  await refreshDmPrivacyMetaFromServer(convId, { rerender: true, source: action ? "rpc-" + action : "rpc" });
}

async function runDmPrivacyRpc(rpcName, payload = {}, {
  conversationId = activeDmId || state.activeDm?.conversationId || "",
  fallbackError = "Could not update Vault.",
  action = "",
} = {}) {
  if (!isDirectDmE2eeEnabled()) {
    throw new Error(DM_PRIVATE_RUNTIME_DISABLED_STATUS_TEXT);
  }
  const convId = normId(conversationId || "");
  const localStateBeforePatch = summarizeDmPrivacyMetaForDebug(getConversationDmPrivacyMeta(convId));
  const { data, error } = await rpcWithTimeout(rpcName, payload);
  if (error) {
    logDmPrivacyDebug("rpc result", {
      ...getDmPrivacyDebugContext(convId),
      action: String(action || rpcName || ""),
      ok: false,
      error: String(error?.code || error?.error || error?.message || error || "unknown"),
      returnedPrivacy: null,
      localStateBeforePatch,
    });
    const wrappedError = new Error(formatDmPrivacyRpcError(error, fallbackError));
    wrappedError.code = String(error?.code || error?.error || "");
    wrappedError.details = error?.details || null;
    throw wrappedError;
  }

  const result = (data && typeof data === "object" && !Array.isArray(data)) ? data : {};
  logDmPrivacyDebug("rpc result", {
    ...getDmPrivacyDebugContext(convId),
    action: String(action || rpcName || ""),
    ok: result?.ok === true,
    error: result?.ok === true ? "" : String(result?.error || "not_ok"),
    returnedPrivacy: normalizeDmPrivacyRpcPayload(result?.privacy || null),
    localStateBeforePatch,
  });
  if (result?.ok !== true) {
    const wrappedError = new Error(formatDmPrivacyRpcError(result, fallbackError));
    wrappedError.code = String(result?.error || "");
    throw wrappedError;
  }

  await applyDmPrivacyRpcResult(result, convId, { action });
  return result;
}

function logDmPrivacyActionClicked(action = "", conversationId = "") {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  const meta = getConversationDmPrivacyMeta(convId);
  logDmPrivacyDebug("action clicked", {
    ...getDmPrivacyDebugContext(convId),
    action: String(action || ""),
    localStateBefore: normalizeDmPrivacyState(meta.dmPrivacyState),
    requestedByBefore: normId(meta.dmPrivacyRequestedBy || ""),
  });
}

function summarizeDmRequestPrivacyPayload(input = null) {
  const privacy = normalizeDmPrivacyRpcPayload(input || null) || normalizeConversationPrivacyPatch(input || null);
  if (!privacy) return null;
  return {
    dm_privacy_state: normalizeDmPrivacyState(privacy.dm_privacy_state || privacy.dmPrivacyState || "standard"),
    dm_privacy_requested_by: normId(privacy.dm_privacy_requested_by || privacy.dmPrivacyRequestedBy || ""),
    dm_privacy_epoch: normalizeDmPrivacyEpoch(privacy.dm_privacy_epoch ?? privacy.dmPrivacyEpoch, 0),
  };
}

function getDmRequestSafeReason(errorOrResult = null, fallback = "unknown_error") {
  const raw = errorOrResult?.code || errorOrResult?.error || errorOrResult?.reason || errorOrResult?.status || "";
  const code = String(raw || "").trim().toLowerCase();
  if (code) return code;
  const message = String(errorOrResult?.message || errorOrResult || "").trim().toLowerCase();
  if (message.includes("timeout")) return "timeout";
  if (message.includes("missing") && message.includes("key")) return "missing_own_key";
  if (message.includes("already pending")) return "request_already_pending";
  if (message.includes("already active") || message.includes("already encrypted")) return "already_active";
  if (message.includes("not friends")) return "not_friends";
  if (message.includes("blocked")) return "blocked_pair";
  return String(fallback || "unknown_error").trim().toLowerCase() || "unknown_error";
}

function createDmRequestFlowError(message = "Could not request Vault.", code = "unknown_error", step = "unknown") {
  const error = new Error(String(message || "Could not request Vault."));
  error.code = String(code || "unknown_error");
  error.reason = String(code || "unknown_error");
  error.step = String(step || "unknown");
  return error;
}

async function confirmDmRequestConversationState(conversationId = "", { source = "request-confirm" } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  const { row, error } = await fetchConversationPrivacyRowDirect(convId, { reason: source });
  if (!row) {
    logDmRequestDebug("db confirm fetch", {
      conversationId: convId,
      dm_privacy_state: "unavailable",
      dm_privacy_requested_by: "",
      dm_privacy_epoch: 0,
      error: String(error?.message || error || "no_row"),
    });
    throw error || createDmRequestFlowError("Vault request state could not be confirmed.", "db_confirm_failed", source);
  }
  logDmRequestDebug("db confirm fetch", {
    conversationId: convId,
    dm_privacy_state: normalizeDmPrivacyState(row?.dm_privacy_state || row?.dmPrivacyState || "standard"),
    dm_privacy_requested_by: normId(row?.dm_privacy_requested_by || row?.dmPrivacyRequestedBy || ""),
    dm_privacy_epoch: normalizeDmPrivacyEpoch(row?.dm_privacy_epoch ?? row?.dmPrivacyEpoch, 0),
  });
  return patchConversationPrivacyState(convId, {
    ...row,
    kind: String(row?.kind || "dm").trim().toLowerCase() || "dm",
  }, { rerender: true, refreshKeys: true, source });
}

function getDmRequestRpcPrivacyState(result = {}) {
  const status = String(result?.status || result?.state || "").trim().toLowerCase();
  if (status === "requested" || status === "private_requested" || status === "pending") return "private_requested";
  if (status === "already_active" || status === "private_active" || status === "active") return "private_active";
  const privacySource = result?.privacy && typeof result.privacy === "object" ? result.privacy : null;
  const rawPrivacyState = privacySource
    ? (privacySource.state ?? privacySource.dm_privacy_state ?? privacySource.dmPrivacyState)
    : undefined;
  if (typeof rawPrivacyState !== "undefined" && rawPrivacyState !== null && String(rawPrivacyState).trim() !== "") {
    return normalizeDmPrivacyState(rawPrivacyState);
  }
  if (status === "standard") return "standard";
  return "";
}

function buildDmRequestOptimisticPatchFromRpc(result = {}, conversationId = "", rpcStateInput = "") {
  const rpcState = normalizeDmPrivacyState(rpcStateInput || getDmRequestRpcPrivacyState(result));
  const privacyPayload = normalizeDmPrivacyRpcPayload(result?.privacy || null);
  if (privacyPayload && rpcState !== "standard") return privacyPayload;
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  const currentMeta = getConversationDmPrivacyMeta(convId);
  if (rpcState === "private_requested") {
    return {
      kind: "dm",
      dm_privacy_state: "private_requested",
      dm_privacy_request_nonce: normId(currentMeta.dmPrivacyRequestNonce || "") || null,
      dm_privacy_requested_by: normId(state.user?.id || "") || null,
      dm_privacy_requested_at: new Date().toISOString(),
      dm_privacy_activated_at: null,
      dm_privacy_epoch: normalizeDmPrivacyEpoch(currentMeta.dmPrivacyEpoch, 0),
      dm_privacy_source: "user",
    };
  }
  if (rpcState === "private_active") {
    return {
      kind: "dm",
      dm_privacy_state: "private_active",
      dm_privacy_request_nonce: null,
      dm_privacy_requested_by: null,
      dm_privacy_requested_at: null,
      dm_privacy_activated_at: new Date().toISOString(),
      dm_privacy_epoch: Math.max(1, normalizeDmPrivacyEpoch(currentMeta.dmPrivacyEpoch, 1)),
      dm_privacy_source: "user",
    };
  }
  return null;
}

function rememberDmRequestGrace(conversationId = "", rpcState = "") {
  const convId = normId(conversationId || "");
  const stateValue = normalizeDmPrivacyState(rpcState || "");
  if (!convId || stateValue !== "private_requested") return;
  dmPrivacyRequestGraceByConversation.set(convId, {
    rpcState: stateValue,
    until: Date.now() + DM_PRIVACY_REQUEST_GRACE_MS,
  });
}

function getDmRequestGrace(conversationId = "") {
  const convId = normId(conversationId || "");
  const grace = convId ? dmPrivacyRequestGraceByConversation.get(convId) : null;
  if (!grace) return null;
  if (Date.now() > Number(grace.until || 0)) {
    dmPrivacyRequestGraceByConversation.delete(convId);
    return null;
  }
  return grace;
}

function shouldIgnoreDmRequestGraceDowngrade(conversationId = "", dbState = "", localState = "") {
  const convId = normId(conversationId || "");
  const grace = getDmRequestGrace(convId);
  return !!(
    grace
    && normalizeDmPrivacyState(grace.rpcState) === "private_requested"
    && normalizeDmPrivacyState(localState) === "private_requested"
    && normalizeDmPrivacyState(dbState) === "standard"
  );
}

function clearDmRequestConfirmTimers(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId) return;
  const timers = dmPrivacyRequestConfirmTimersByConversation.get(convId) || [];
  timers.forEach((timer) => clearTimeout(timer));
  dmPrivacyRequestConfirmTimersByConversation.delete(convId);
}

function scheduleDmRequestConfirmFetches(conversationId = "", { rpcState = "", showFailureOnAllStandard = false } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return;
  clearDmRequestConfirmTimers(convId);
  const normalizedRpcState = normalizeDmPrivacyState(rpcState || "standard");
  const observedStates = [];
  const timers = DM_PRIVACY_REQUEST_CONFIRM_DELAYS_MS.map((delayMs, index) => setTimeout(async () => {
    const attempt = index + 1;
    let dbState = "unavailable";
    try {
      const { row, error } = await fetchConversationPrivacyRowDirect(convId, { reason: "request-confirm-retry" });
      if (!row) throw error || new Error("conversation_privacy_state_unavailable");
      dbState = normalizeDmPrivacyState(row?.dm_privacy_state || row?.dmPrivacyState || "standard");
      observedStates.push(dbState);
      logDmRequestDebug("confirm fetch attempt", {
        attempt,
        delayMs,
        dbState,
        rpcState: normalizedRpcState,
      });
      if (dbState === "standard" && normalizedRpcState === "private_requested") {
        logDmRequestDebug("confirm mismatch ignored", {
          dbState: "standard",
          rpcState: "private_requested",
        });
        logDmRequestDebug("false-failure prevented", {
          reason: "rpc_requested_confirm_stale",
        });
        return;
      }
      patchConversationPrivacyState(convId, {
        ...row,
        kind: String(row?.kind || "dm").trim().toLowerCase() || "dm",
      }, { rerender: true, refreshKeys: true, source: "request-confirm-retry" });
    } catch (error) {
      observedStates.push("unavailable");
      logDmRequestDebug("confirm fetch attempt", {
        attempt,
        delayMs,
        dbState,
        rpcState: normalizedRpcState,
        error: String(error?.message || error || "unknown"),
      });
    } finally {
      if (attempt === DM_PRIVACY_REQUEST_CONFIRM_DELAYS_MS.length) {
        dmPrivacyRequestConfirmTimersByConversation.delete(convId);
        const allStandard = observedStates.length > 0 && observedStates.every((stateValue) => stateValue === "standard");
        if (showFailureOnAllStandard && normalizedRpcState !== "private_requested" && allStandard) {
          const message = "Vault request was not created.";
          showDmPrivacyToast(message);
          void requestAppAlert(message, {
            title: t("dm.privacy.alert_title", "ALTARA Vault"),
            okText: "OK",
          });
        }
      }
    }
  }, delayMs));
  dmPrivacyRequestConfirmTimersByConversation.set(convId, timers);
}

async function getDmRequestIdentityStateDebug(userId = "") {
  const uid = normId(userId || state.user?.id || "");
  if (!uid) return { hasLocalPrivateKey: false, hasActivePublicKey: false, reason: "auth_missing" };
  const identityState = await getDmE2eeIdentityState({ userId: uid, force: true }).catch((error) => ({
    status: "error",
    error,
  }));
  return {
    hasLocalPrivateKey: identityState?.hasLocalPrivateKey === true,
    hasActivePublicKey: identityState?.hasRemotePublicKey === true,
    reason: getDmRequestSafeReason(identityState?.error || identityState?.status || "ready", "ready"),
  };
}

async function runRequestDirectDmEncryptionRpc(conversationId = "", { attempt = 1 } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  logDmRequestDebug("rpc start", {
    conversationId: convId,
    rpc: "request_direct_dm_encryption",
    attempt,
  });
  const { data, error } = await rpcWithTimeout("request_direct_dm_encryption", {
    p_conversation_id: convId,
  });
  const result = (data && typeof data === "object" && !Array.isArray(data))
    ? data
    : (Array.isArray(data) && data[0] && typeof data[0] === "object" ? data[0] : {});
  const rpcError = error || null;
  const rpcState = getDmRequestRpcPrivacyState(result);
  logDmRequestDebug("rpc result", {
    ok: !rpcError && result?.ok === true,
    status: String(result?.status || result?.state || ""),
    error: String(rpcError?.code || rpcError?.error || rpcError?.message || result?.error || ""),
    privacyState: rpcState || normalizeDmPrivacyState(summarizeDmRequestPrivacyPayload(result?.privacy || null)?.dm_privacy_state || "standard"),
  });
  if (rpcError) {
    const wrapped = createDmRequestFlowError(formatDmPrivacyRpcError(rpcError, "Could not request Vault."), getDmRequestSafeReason(rpcError), "rpc");
    wrapped.details = rpcError?.details || null;
    throw wrapped;
  }
  if (result?.ok !== true) {
    throw createDmRequestFlowError(formatDmPrivacyRpcError(result, "Could not request Vault."), getDmRequestSafeReason(result, "not_ok"), "rpc");
  }

  const optimisticPatch = buildDmRequestOptimisticPatchFromRpc(result, convId, rpcState);
  if (optimisticPatch) {
    setConversationPrivacyState(convId, optimisticPatch, { rerender: true, refreshKeys: true, source: "request-rpc-optimistic" });
    rememberDmRequestGrace(convId, rpcState);
    logDmRequestDebug("optimistic patch from rpc", {
      conversationId: convId,
      state: normalizeDmPrivacyState(optimisticPatch.dm_privacy_state || optimisticPatch.dmPrivacyState || rpcState),
    });
  }
  scheduleDmRequestConfirmFetches(convId, {
    rpcState: rpcState || normalizeDmPrivacyState(optimisticPatch?.dm_privacy_state || "standard"),
    showFailureOnAllStandard: !optimisticPatch,
  });
  return { ...result, _dmRequestRpcState: rpcState, _dmRequestOptimisticPatched: !!optimisticPatch };
}

async function setupDmRequestEncryptionKey(conversationId = "", { retry = false } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  const userId = normId(state.user?.id || "");
  logDmRequestDebug("setup start", {
    conversationId: convId,
    currentUserId: userId,
    retry: retry === true,
  });
  const setup = await awaitWithTimeout(
    setupDirectDmEncryptionForCurrentDevice({ conversationId: convId, showError: false, checkPeerKey: false }),
    15000,
    "dm request encryption setup"
  );
  const identityDebug = await getDmRequestIdentityStateDebug(userId);
  const hasLocalPrivateKey = setup?.hasLocalPrivateKey === true || identityDebug.hasLocalPrivateKey === true;
  const hasActivePublicKey = setup?.hasActivePublicKey === true || identityDebug.hasActivePublicKey === true;
  const reason = normalizeDmE2eeSetupFailureReason(setup?.reason || setup?.status || identityDebug.reason || "unknown_error");
  logDmRequestDebug("setup result", {
    ok: setup?.ok === true && hasLocalPrivateKey && hasActivePublicKey,
    reason: setup?.ok === true ? "ready" : reason,
    hasLocalPrivateKey,
    hasActivePublicKey,
  });
  if (setup?.ok !== true || !hasLocalPrivateKey || !hasActivePublicKey) {
    const safeReason = !hasLocalPrivateKey
      ? "local_private_key_store_failed"
      : (!hasActivePublicKey ? "public_key_upload_failed" : reason);
    throw setup?.error || createDmRequestFlowError(getDmE2eeSetupFailureMessage(safeReason), safeReason, "setup");
  }
  return setup;
}

function createVaultRecoveryCancelledError(step = "recovery") {
  return createDmRequestFlowError(
    t("dm.privacy.vault_recovery.cancelled", "Vault request cancelled before recovery setup finished."),
    "vault_recovery_cancelled",
    step
  );
}

function isVaultRecoveryCancelledError(error = null) {
  return String(error?.code || error?.reason || "").trim().toLowerCase() === "vault_recovery_cancelled";
}

async function requestVaultRecoveryPasswordFromUser({ confirm = false, title = "", message = "" } = {}) {
  const firstPassword = await requestAppPrompt(
    message || t(
      "dm.privacy.vault_recovery.password_prompt",
      "Create a Vault Recovery Password. ALTARA cannot recover Vault messages if you forget it and lose your trusted devices."
    ),
    {
      title: title || t("dm.privacy.vault_recovery.title", "Set up Vault Recovery"),
      label: t("settings.security.dm_backup.password", "Vault Recovery Password"),
      placeholder: t("settings.security.dm_backup.password", "Vault Recovery Password"),
      okText: t("settings.security.dm_backup.create_btn", "Set up Vault Recovery"),
      cancelText: t("dialog.confirm.cancel", "Cancel"),
      inputType: "password",
      requireValue: true,
      maxLength: 4000,
    }
  );
  if (firstPassword === null) return null;
  if (String(firstPassword || "").length < DM_E2EE_BACKUP_PASSWORD_MIN_LENGTH) {
    await requestAppAlert(
      tf(
        "settings.security.dm_backup.error_password_short",
        { min: DM_E2EE_BACKUP_PASSWORD_MIN_LENGTH },
        "Use a Vault Recovery Password with at least {min} characters."
      ),
      { title: t("dm.privacy.vault_recovery.title", "Set up Vault Recovery"), okText: "OK" }
    );
    return null;
  }
  if (!confirm) return String(firstPassword || "");

  const confirmPassword = await requestAppPrompt(
    t("dm.privacy.vault_recovery.confirm_prompt", "Confirm your Vault Recovery Password."),
    {
      title: t("dm.privacy.vault_recovery.title", "Set up Vault Recovery"),
      label: t("settings.security.dm_backup.password_confirm", "Confirm Vault Recovery Password"),
      placeholder: t("settings.security.dm_backup.password_confirm", "Confirm Vault Recovery Password"),
      okText: t("dialog.confirm.ok", "Confirm"),
      cancelText: t("dialog.confirm.cancel", "Cancel"),
      inputType: "password",
      requireValue: true,
      maxLength: 4000,
    }
  );
  if (confirmPassword === null) return null;
  if (String(confirmPassword || "") !== String(firstPassword || "")) {
    await requestAppAlert(t("settings.security.dm_backup.error_password_match", "Vault Recovery Passwords do not match."), {
      title: t("dm.privacy.vault_recovery.title", "Set up Vault Recovery"),
      okText: "OK",
    });
    return null;
  }
  return String(firstPassword || "");
}

async function confirmVaultRequestForActiveConversation(conversationId = "") {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  const peerLabel = getActiveDirectDmPeerDisplayName(t("dm.privacy.peer_fallback", "your friend"));
  const body = [
    tf("dm.privacy.vault_request.body", { name: peerLabel }, "Vault uses end-to-end encryption for this DM with {name}. New messages will only be readable on authorized devices. ALTARA cannot recover Vault messages if you lose your recovery password, recovery key, and trusted devices."),
    "",
    t("dm.privacy.vault_request.bullet_consent", "- Both people must agree."),
    t("dm.privacy.vault_request.bullet_old", "- Old Sync messages remain as they are."),
    t("dm.privacy.vault_request.bullet_new", "- New Vault messages are end-to-end encrypted."),
    t("dm.privacy.vault_request.bullet_restore", "- You can restore Vault messages on new devices using your recovery methods."),
  ].join("\n");
  return requestAppConfirm(body, {
    title: t("dm.privacy.vault_request.title", "Switch this DM to Vault?"),
    confirmText: t("dm.privacy.vault_request.confirm", "Request Vault"),
    cancelText: t("dialog.confirm.cancel", "Cancel"),
  });
}

async function ensureVaultLocalIdentityRestoredBeforeSetup(conversationId = "") {
  const userId = normId(state.user?.id || "");
  if (!userId) return true;
  const [identityState, backupMeta] = await Promise.all([
    getDmE2eeIdentityState({ userId, force: true }).catch((error) => ({ status: "error", error })),
    getDmE2eeKeyBackupMetadata({ userId, force: true }).catch(() => null),
  ]);
  const identityStatus = String(identityState?.status || "").trim().toLowerCase();
  if (identityStatus !== "missing_local_private" || !backupMeta) return true;

  const ok = await requestAppConfirm(
    t(
      "dm.privacy.vault_recovery.restore_before_request",
      "This account already has a Vault key, but this device is missing it. Restore Vault messages before requesting Vault so older Vault messages stay readable."
    ),
    {
      title: t("dm.e2ee.restore.title", "Restore Vault messages"),
      confirmText: t("settings.security.dm_backup.restore_btn", "Restore Vault messages"),
      cancelText: t("dialog.confirm.cancel", "Cancel"),
    }
  );
  if (!ok) throw createVaultRecoveryCancelledError("restore-before-request");
  const restored = await promptRestoreDmE2eeBackupFromDm();
  if (!restored) throw createVaultRecoveryCancelledError("restore-before-request");
  return true;
}

async function ensureVaultRecoveryBackupReadyForRequest(conversationId = "") {
  const userId = normId(state.user?.id || "");
  if (!userId) throw createDmRequestFlowError("Sign in before requesting Vault.", "auth_missing", "recovery");
  const [identityState, backupMeta] = await Promise.all([
    getDmE2eeIdentityState({ userId, force: true }),
    getDmE2eeKeyBackupMetadata({ userId, force: true }).catch(() => null),
  ]);
  const identityStatus = String(identityState?.status || "").trim().toLowerCase();
  if (identityStatus !== "ready") {
    throw createDmRequestFlowError(getDmE2eeSetupFailureMessage(identityStatus || identityState?.error || "setup_failed"), identityStatus || "setup_failed", "recovery");
  }
  if (backupMeta?.hasRecoveryKeyMethod) return true;

  const ok = await requestAppConfirm(
    t(
      "dm.privacy.vault_recovery.required_body",
      "Before switching a DM to Vault, set up Vault Recovery. Vault messages cannot be restored by ALTARA. Recovery lets you restore them on new devices with your recovery password or Recovery Key."
    ),
    {
      title: t("dm.privacy.vault_recovery.title", "Set up Vault Recovery"),
      confirmText: t("settings.security.dm_backup.create_btn", "Set up Vault Recovery"),
      cancelText: t("dialog.confirm.cancel", "Cancel"),
    }
  );
  if (!ok) throw createVaultRecoveryCancelledError("recovery");

  const understoodRecovery = await showVaultRecoveryResponsibilityNotice();
  if (!understoodRecovery) throw createVaultRecoveryCancelledError("recovery-warning");

  const password = await requestVaultRecoveryPasswordFromUser({ confirm: true });
  if (password === null) throw createVaultRecoveryCancelledError("recovery");
  const backupResult = await createDmE2eeKeyBackup({
    userId,
    password,
    passwordSource: DM_E2EE_BACKUP_PASSWORD_SOURCE_MANUAL,
    includeRecoveryKey: true,
  });
  if (backupResult?.recoveryKey) {
    const savedKey = await showVaultRecoveryKeyOnce(backupResult.recoveryKey);
    if (!savedKey) throw createVaultRecoveryCancelledError("recovery-key");
  }
  clearDmE2eeBackupInputs({ clearRestore: true });
  await refreshDmE2eeBackupSettingsState({ force: true }).catch(() => {});
  showDmPrivacyToast(t("settings.security.dm_backup.saved", "Vault Recovery is ready. Use your password or saved Recovery Key to restore Vault messages on new devices."));
  return true;
}

async function requestPrivateDmForActiveConversation() {
  const convId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (!convId || directDmPrivacyActionInFlight) return;
  const currentUserId = normId(state.user?.id || "");
  const peerUserId = getActiveDirectDmPeerUserId();
  const localPrivacyState = normalizeDmPrivacyState(getConversationDmPrivacyMeta(convId).dmPrivacyState);
  let step = "clicked";
  logDmPrivacyActionClicked("request", convId);
  logDmRequestDebug("clicked", {
    conversationId: convId,
    activeConversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
    buttonConversationId: convId,
    currentUserId,
    peerUserId,
    localPrivacyState,
  });
  const confirmed = await confirmVaultRequestForActiveConversation(convId);
  if (!confirmed) return;
  setDirectDmPrivacyActionInFlight("request");
  try {
    startActiveDmPrivacyListener(convId);
    step = "restore-before-request";
    await ensureVaultLocalIdentityRestoredBeforeSetup(convId);

    step = "setup";
    await setupDmRequestEncryptionKey(convId, { retry: false });

    step = "recovery";
    await ensureVaultRecoveryBackupReadyForRequest(convId);

    step = "rpc";
    try {
      await runRequestDirectDmEncryptionRpc(convId, { attempt: 1 });
    } catch (rpcError) {
      const rpcReason = getDmRequestSafeReason(rpcError);
      if (rpcReason !== "missing_own_key") throw rpcError;
      step = "setup-retry";
      dmE2eeBootstrapPromise = null;
      directDmE2eeDeviceSetupPromise = null;
      await setupDmRequestEncryptionKey(convId, { retry: true });
      step = "rpc-retry";
      await runRequestDirectDmEncryptionRpc(convId, { attempt: 2 });
    }

    const finalState = normalizeDmPrivacyState(getConversationDmPrivacyMeta(convId).dmPrivacyState);
    logDmRequestDebug("finished", { ok: true, finalState });
  } catch (error) {
    const safeReason = getDmRequestSafeReason(error);
    if (isVaultRecoveryCancelledError(error)) {
      logDmRequestDebug("failed", {
        step: String(error?.step || step || "recovery"),
        safeReason,
        errorMessage: String(error?.message || error || "cancelled"),
      });
      return;
    }
    if (await handleDmPrivacySoftStateError(error, convId)) {
      scheduleDmRequestConfirmFetches(convId, { rpcState: normalizeDmPrivacyState(getConversationDmPrivacyMeta(convId).dmPrivacyState) });
      const finalState = normalizeDmPrivacyState(getConversationDmPrivacyMeta(convId).dmPrivacyState);
      logDmRequestDebug("finished", { ok: true, finalState });
      return;
    }
    const setupFailure = step === "setup"
      || step === "setup-retry"
      || safeReason === "public_key_upload_failed"
      || safeReason === "local_private_key_store_failed"
      || (safeReason === "timeout" && (step === "setup" || step === "setup-retry"));
    if (setupFailure) {
      directDmE2eeDeviceSetupInFlight = false;
      directDmE2eeDeviceSetupPromise = null;
      dmE2eeBootstrapPromise = null;
      setDmE2eeReadiness({
        status: "failed",
        userId: currentUserId,
        identityStatus: safeReason,
        error: error instanceof Error ? error : new Error(String(error || "Could not set up Vault on this device.")),
      });
    }
    logDmRequestDebug("failed", {
      step: String(error?.step || step || "unknown"),
      safeReason,
      errorMessage: String(error?.message || error || "unknown"),
    });
    const message = safeReason === "request_not_created"
      ? "Vault request was not created."
      : (safeReason === "not_friends"
        ? "Vault is available between friends."
        : (safeReason === "blocked_pair"
          ? "Vault request is unavailable."
          : (setupFailure
            ? getDmE2eeSetupFailureMessage(safeReason === "timeout" ? "setup_failed" : safeReason)
            : formatDmPrivacyRpcError(error, "Could not request Vault."))));
    showDmPrivacyToast(message);
    await requestAppAlert(message, {
      title: t("dm.privacy.alert_title", "ALTARA Vault"),
      okText: "OK",
    });
  } finally {
    if (directDmPrivacyActionInFlight === "request") setDirectDmPrivacyActionInFlight("");
  }
}

async function acceptPrivateDmRequestForActiveConversation() {
  const convId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (!convId || directDmPrivacyActionInFlight) return;
  logDmPrivacyActionClicked("accept", convId);
  setDirectDmPrivacyActionInFlight("accept");
  try {
    startActiveDmPrivacyListener(convId);
    await ensureVaultLocalIdentityRestoredBeforeSetup(convId);
    const setup = await setupDirectDmEncryptionForCurrentDevice({ conversationId: convId, showError: false });
    if (setup?.ok !== true) {
      throw setup?.error || new Error(getDmE2eeSetupFailureMessage(setup?.reason || setup?.status || "unknown_error"));
    }
    await ensureVaultRecoveryBackupReadyForRequest(convId);
    await runDmPrivacyRpc("accept_direct_dm_encryption", {
      p_conversation_id: convId,
    }, {
      conversationId: convId,
      fallbackError: "Could not switch to Vault.",
      action: "accept",
    });
    void ensureDmE2eeBootstrapStarted({ force: true });
    const peerId = getActiveDirectDmPeerUserId();
    if (peerId) void refreshDirectDmPeerE2eeKeyStatus(convId, peerId, { force: true });
  } catch (error) {
    if (isVaultRecoveryCancelledError(error)) return;
    if (await handleDmPrivacySoftStateError(error, convId)) return;
    await requestAppAlert(formatDmPrivacyRpcError(error, "Could not switch to Vault."), {
      title: t("dm.privacy.alert_title", "ALTARA Vault"),
      okText: "OK",
    });
  } finally {
    if (directDmPrivacyActionInFlight === "accept") setDirectDmPrivacyActionInFlight("");
  }
}

