function buildSendMessagesPermissionError(permissionResult = null) {
  const isVerifyFailure = permissionResult?.ok === false && permissionResult?.error;
  const permissionError = new Error(isVerifyFailure
    ? MESSAGE_COMPOSER_PERMISSION_VERIFY_TEXT
    : MESSAGE_COMPOSER_NO_SEND_PERMISSION_TEXT);
  permissionError.code = isVerifyFailure ? "send_messages_permission_not_verified" : "missing_send_messages_permission";
  permissionError.expectedPermissionBlock = true;
  permissionError.permissionResult = permissionResult || null;
  return permissionError;
}

function buildServerTimeoutSendError(serverId = "") {
  const timeout = getCurrentUserServerTimeout(serverId);
  const until = formatServerTimeoutUntil(timeout);
  const text = until
    ? `You are timed out until ${until} and cannot send messages.`
    : "You are timed out and cannot send messages.";
  const error = new Error(text);
  error.code = "server_member_timed_out";
  error.expectedPermissionBlock = true;
  error.timeout = timeout || null;
  return error;
}

function markActiveComposerTimeoutBlocked(serverId = "", timeout = null) {
  const context = getActiveMessageComposerPermissionContext();
  lastServerTimeoutComposerBlockedReason = "server_member_timed_out";
  setActiveMessageComposerPermissionState({
    key: context.key,
    loading: false,
    canSend: false,
    canReact: false,
    canAttach: false,
    reason: "server_member_timed_out",
    trace: { serverId: normId(serverId || ""), timeout: timeout || getCurrentUserServerTimeout(serverId) },
  });
  renderActiveServerMessageCapabilitySurfaces("server-timeout-blocked");
}

async function verifyCanSendPlainTextMessageToConversation(conversationId, reason = "send-message-preflight") {
  const convId = normId(conversationId || "");
  const permissionContext = getServerPermissionContextForConversation(convId);
  if (!permissionContext?.serverId || permissionContext.channelType === "voice") {
    return { ok: true, permissionResult: null, error: null };
  }
  const timeout = getCurrentUserServerTimeout(permissionContext.serverId);
  if (timeout) {
    const timeoutError = buildServerTimeoutSendError(permissionContext.serverId);
    markActiveComposerTimeoutBlocked(permissionContext.serverId, timeout);
    recordMessageSendState("blocked", {
      conversationId: convId,
      serverId: permissionContext.serverId,
      blockedReason: "server_member_timed_out",
      error: timeoutError.message,
      timeout,
    });
    return { ok: false, permissionResult: { ok: true, timeout }, error: timeoutError };
  }
  const permissionResult = await resolveCurrentUserMessagePermission({
    serverId: permissionContext.serverId,
    channelId: permissionContext.channelId || permissionContext.conversationId || convId,
    reason,
  });
  try { console.info("[permissions] send-message preflight", permissionResult); } catch (_) {}
  if (permissionResult?.ok && permissionResult?.permissions?.send_messages === true) {
    return { ok: true, permissionResult, error: null };
  }
  const permissionError = buildSendMessagesPermissionError(permissionResult);
  markActiveComposerSendPermissionBlocked(permissionResult, permissionError.code === "send_messages_permission_not_verified" ? "could_not_verify" : "missing_send_messages");
  try { console.warn("[permissions] blocked send-message", permissionResult); } catch (_) {}
  recordMessageSendState("blocked", {
    conversationId: convId,
    serverId: permissionContext.serverId,
    blockedReason: permissionError.code,
    error: permissionError.message,
    permissionTrace: permissionResult?.trace || null,
  });
  return { ok: false, permissionResult, error: permissionError };
}

function getOptimisticEmbedServerContext(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId) return null;
  const resolved = getServerPermissionContextForConversation(convId);
  if (resolved?.serverId) return { ...resolved, resolved: true };

  // If the UI already knows this is a server timeline but its channel mapping
  // snapshot is unresolved, fail closed for the optimistic card. The database
  // remains authoritative and the returned row replaces this snapshot.
  const meta = getConversationMeta(convId) || {};
  const active = normId(activeDmId || state.activeDm?.conversationId || "") === convId
    ? (state.activeDm || {})
    : {};
  const serverId = normId(meta?.serverId || meta?.server_id || active?.serverId || active?.server_id || "");
  if (!serverId) return null;
  return {
    serverId,
    conversationId: convId,
    channelId: normId(meta?.channelId || meta?.channel_id || active?.channelId || active?.channel_id || ""),
    channelType: normalizeConversationChannelType(meta?.channelType || meta?.channel_type || active?.channelType || active?.channel_type || "text"),
    resolved: false,
  };
}

async function resolveOptimisticHumanMessageSuppressEmbeds(
  conversationId,
  { permissionResult = null } = {}
) {
  const context = getOptimisticEmbedServerContext(conversationId);
  if (!context?.serverId) return false;

  let resolvedPermissions = permissionResult?.ok === true ? permissionResult : null;
  if (!resolvedPermissions) {
    try {
      resolvedPermissions = await resolveCurrentUserMessagePermission({
        serverId: context.serverId,
        channelId: context.channelId || context.conversationId,
        reason: "embed-links-optimistic-snapshot",
      });
    } catch (_) {
      resolvedPermissions = null;
    }
  }

  return !(
    resolvedPermissions?.ok === true
    && resolvedPermissions?.permissions?.embed_links === true
  );
}

async function verifyCanAttachFilesToConversation(conversationId, reason = "attach-files-preflight") {
  const convId = normId(conversationId || "");
  const context = getServerPermissionContextForConversation(convId);
  if (!context?.serverId || context.channelType === "voice") {
    return { ok: true, permissionResult: null, error: null };
  }
  const timeout = getCurrentUserServerTimeout(context.serverId);
  if (timeout) {
    const error = buildServerTimeoutSendError(context.serverId);
    markActiveComposerTimeoutBlocked(context.serverId, timeout);
    return { ok: false, permissionResult: { ok: true, timeout }, error };
  }
  const permissionResult = await resolveCurrentUserMessagePermission({
    serverId: context.serverId,
    channelId: context.channelId || context.conversationId || convId,
    reason,
  });
  const allowed = Boolean(
    permissionResult?.ok
    && permissionResult?.permissions?.send_messages === true
    && permissionResult?.permissions?.attach_files === true
  );
  if (allowed) return { ok: true, permissionResult, error: null };

  const verifyFailed = permissionResult?.ok === false && permissionResult?.error;
  const error = new Error(verifyFailed ? MESSAGE_COMPOSER_PERMISSION_VERIFY_TEXT : MESSAGE_ATTACHMENT_PERMISSION_TEXT);
  error.code = verifyFailed ? "attach_files_permission_not_verified" : "missing_attach_files_permission";
  error.expectedPermissionBlock = true;
  error.permissionResult = permissionResult || null;
  serverMessagePermissionDebugState.lastAttachmentSend = {
    phase: "blocked",
    at: Date.now(),
    serverId: context.serverId,
    conversationId: convId,
    attachmentCount: dmPendingAttachments.length,
    error: { code: error.code, message: error.message },
  };
  return { ok: false, permissionResult, error };
}

async function sendPlainTextMessageToConversation(conversationId, text, { replyToId = null, sendId: providedSendId = "" } = {}) {
  const convId = normId(conversationId);
  const content = String(text || "").trim();
  if (!convId || !content || !state.user?.id) {
    return { ok: false, error: { message: "conversation_id ou content invalido" } };
  }
  if (isActiveMessageRequestPreview()) {
    return { ok: false, error: { message: "Accept this request before replying." } };
  }

  const permissionPreflight = await verifyCanSendPlainTextMessageToConversation(convId, "send-message-preflight");
  if (!permissionPreflight?.ok) {
    return { ok: false, error: permissionPreflight?.error || new Error(MESSAGE_COMPOSER_NO_SEND_PERMISSION_TEXT), permissionBlocked: true };
  }

  const optimisticSuppressEmbeds = await resolveOptimisticHumanMessageSuppressEmbeds(convId, {
    permissionResult: permissionPreflight.permissionResult,
  });

  markPerfStart("message_send_total", { conversationId: convId });
  const optimisticMessage = createOptimisticOutgoingMessage({
    conversationId: convId,
    content,
    replyToId,
    suppressEmbeds: optimisticSuppressEmbeds,
    retryPayload: {
      kind: "text",
      conversationId: convId,
      text: content,
      replyToId: replyToId || null,
    },
  });
  const sendId = String(providedSendId || optimisticMessage?.id || ("send_" + Date.now().toString(36))).trim();
  recordMessageSendState("started", {
    sendId,
    conversationId: convId,
    contentLength: content.length,
    phase: "optimistic_created",
    pendingCount: getOptimisticSendingMessagesSnapshot().length,
    insertStarted: false,
  });
  if (optimisticMessage) finalizeLocalOutgoingEcho();

  let insertPayload = null;
  try {
    await ensureConversationMessageRateLimit(convId, { sendId });
    insertPayload = await altaraWithTimeout(buildConversationMessageInsertPayload({
      conversationId: convId,
      content,
      replyToId,
    }), 5000, "message payload build");
  } catch (error) {
    if (optimisticMessage) markOptimisticOutgoingMessageFailed(optimisticMessage.id, error);
    recordMessageSendState("prepare_failed", {
      sendId,
      conversationId: convId,
      contentLength: content.length,
      phase: "prepare",
      pendingCount: getOptimisticSendingMessagesSnapshot().length,
      clearedPending: true,
      error: error?.message || error,
    });
    markPerfEnd("message_send_total", { conversationId: convId, ok: false, stage: "prepare" });
    return { ok: false, error };
  }

  const { row, error } = await insertMessageRowAndHydrate(insertPayload, convId, { sendId, contentLength: content.length });
  if (error) {
    if (optimisticMessage) markOptimisticOutgoingMessageFailed(optimisticMessage.id, error);
    recordMessageSendState("insert_failed", {
      sendId,
      conversationId: convId,
      contentLength: content.length,
      phase: "insert",
      pendingCount: getOptimisticSendingMessagesSnapshot().length,
      clearedPending: true,
      error: error?.message || error,
    });
    markPerfEnd("message_send_total", { conversationId: convId, ok: false, stage: "insert" });
    return { ok: false, error };
  }
  if (optimisticMessage && row) reconcileOptimisticOutgoingMessage(optimisticMessage.id, row, { keepBottom: true });
  else if (optimisticMessage) markOptimisticOutgoingMessageSentLocally(optimisticMessage.id, { keepBottom: true });
  recordMessageSendState("send_success", {
    sendId,
    conversationId: convId,
    contentLength: content.length,
    phase: "complete",
    pendingCount: getOptimisticSendingMessagesSnapshot().length,
    insertSucceeded: true,
    clearedPending: true,
  });
  markPerfEnd("message_send_total", { conversationId: convId, ok: true });
  return { ok: true, row: row || null };
}

function getCurrentUserSystemDisplayName() {
  return normalizeConversationLabel(
    String(state.me?.display_name || state.me?.username || state.user?.email || "Alguem").trim(),
    "Alguem"
  );
}

function buildServerMembershipSystemText(event = "", actorName = "") {
  const who = normalizeConversationLabel(actorName || getCurrentUserSystemDisplayName(), "Alguem");
  const ev = String(event || "").trim().toLowerCase();
  if (ev === "member_left") return `${who} saiu do servidor.`;
  if (ev === "member_joined") return `${who} entrou no servidor.`;
  return `${who} atualizou o estado do servidor.`;
}

async function sendSystemEventMessageToConversation(conversationId, {
  event = "notice",
  text = "",
  actorName = "",
} = {}) {
  const convId = normId(conversationId);
  if (!convId || !state.user?.id) {
    return { ok: false, error: { message: "conversation_id invalido" }, messageId: "" };
  }

  const payload = {
    type: "system_event",
    event: String(event || "notice").trim().toLowerCase() || "notice",
    actor: String(actorName || getCurrentUserSystemDisplayName()).trim() || "Alguem",
    text: String(text || "").trim() || buildServerMembershipSystemText(event, actorName),
  };

  let insertPayload = null;
  try {
    insertPayload = await buildConversationMessageInsertPayload({
      conversationId: convId,
      content: JSON.stringify(payload),
    });
  } catch (error) {
    return { ok: false, error, messageId: "" };
  }

  const { data, error } = await supabase
    .from("messages")
    .insert(insertPayload)
    .select("id")
    .maybeSingle();

  if (error) return { ok: false, error, messageId: "" };
  return { ok: true, messageId: normId(data?.id || "") };
}

async function announceServerMembershipEvent(serverId, {
  event = "member_joined",
  actorName = "",
  fallbackConversationId = "",
} = {}) {
  const sid = normId(serverId || "");
  if (!sid) return { ok: false, reason: "invalid_server", messageId: "", conversationId: "" };

  const conversationId = await resolveServerWelcomeChannelConversationId(sid, {
    fallbackConversationId: normId(fallbackConversationId || getServerRowById(sid)?.defaultConversationId || ""),
    forceLookup: true,
  }).catch(() => "");

  const convId = normId(conversationId || "");
  if (!convId) return { ok: false, reason: "missing_channel", messageId: "", conversationId: "" };

  const sendRes = await sendSystemEventMessageToConversation(convId, {
    event,
    actorName,
    text: buildServerMembershipSystemText(event, actorName),
  });
  if (!sendRes?.ok) {
    return { ok: false, reason: "insert_failed", error: sendRes?.error || null, messageId: "", conversationId: convId };
  }
  return { ok: true, messageId: normId(sendRes.messageId || ""), conversationId: convId };
}

async function ensureServerInviteLinkReady({ silent = false, forceRefresh = false } = {}) {
  const sid = normId(serverInviteServerId || "");
  if (!sid) {
    return { ok: false, error: { message: "server_id invalido" } };
  }
  if (!currentUserCanCreateInvites(sid)) {
    const error = { code: "42501", message: "missing_create_invite" };
    renderServerInviteModalState({ busy: false, statusText: "You do not have permission to create invites." });
    return { ok: false, error };
  }
  if (serverInviteCreatePromise) return serverInviteCreatePromise;

  if (!forceRefresh && !serverInviteSettingsDirty && serverInviteLinkCode && serverInviteLinkUrl) {
    return {
      ok: true,
      code: serverInviteLinkCode,
      inviteUrl: serverInviteLinkUrl,
      expiresAt: serverInviteLinkExpiresAt,
      maxUses: serverInviteLinkMaxUses,
      usesCount: serverInviteLinkUsesCount,
    };
  }

  const requestExpiresHours = normalizeServerInviteExpiresHours(serverInviteExpiresHours);
  const requestMaxUses = normalizeServerInviteMaxUses(serverInviteMaxUses);
  const requestId = ++serverInviteLinkRequestId;
  renderServerInviteModalState({
    busy: true,
    statusText: "Creating invite...",
  });
  serverInviteCreatePromise = createServerInviteLinkRpc(sid, {
    expiresHours: requestExpiresHours,
    maxUses: requestMaxUses,
  });
  const { data, error } = await serverInviteCreatePromise.finally(() => {
    serverInviteCreatePromise = null;
  });
  if (requestId !== serverInviteLinkRequestId) {
    return { ok: false, stale: true, error: { message: "invite request superseded" } };
  }
  if (error) {
    if (isMissingRpcError(error)) {
      renderServerInviteModalState({
        busy: false,
        statusText: "Invite creation is not available yet.",
      });
      return { ok: false, error };
    }
    renderServerInviteModalState({ busy: false, statusText: "Could not generate invite link." });
    if (!silent) alert(`Erro ao criar link de convite: ${error.message}`);
    return { ok: false, error };
  }

  const row = Array.isArray(data) ? data[0] : data;
  const code = normalizeServerInviteCode(row?.invite_code || row?.code || "");
  const inviteUrl = resolveServerInviteUrl(row?.invite_url, code);
  const expiresAt = String(row?.expires_at || "").trim();
  const maxUses = normalizeServerInviteMaxUses(
    typeof row?.max_uses !== "undefined" ? row.max_uses : requestMaxUses
  );
  const usesCount = normalizeServerInviteMaxUses(
    typeof row?.uses_count !== "undefined" ? row.uses_count : 0
  );
  if (!code || !inviteUrl) {
    renderServerInviteModalState({ busy: false, statusText: "Invite link generated with missing data." });
    if (!silent) alert("Link criado mas veio sem dados validos.");
    return { ok: false, error: { message: "invite data incompleta" } };
  }

  serverInviteLinkCode = code;
  serverInviteLinkUrl = inviteUrl;
  serverInviteLinkExpiresAt = expiresAt;
  serverInviteLinkMaxUses = maxUses;
  serverInviteLinkUsesCount = usesCount;
  serverInviteSettingsDirty = false;
  renderServerInviteModalState({ busy: false, statusText: "Invite created." });
  void emitServerInvitesChangedBroadcast(sid, { reason: "invite_created", inviteId: normId(row?.id || "") });
  if (currentUserCanManageInvites(sid)) {
    void loadServerSettingsInvites(sid, { force: true, reason: "invite-created" });
  }
  return { ok: true, code, inviteUrl, expiresAt, maxUses, usesCount };
}

function renderServerInviteFriendsList() {
  const listEl = document.getElementById("serverInviteFriendsList");
  if (!listEl) return;
  const sid = normId(serverInviteServerId || "");
  if (!sid) {
    listEl.innerHTML = `<div class="hint">Open a server first.</div>`;
    return;
  }

  const query = String(serverInviteFriendSearch || "").trim().toLowerCase();
  let rows = getInvitableServerFriends(sid);
  if (query) {
    rows = rows.filter((row) => {
      const display = String(row?.displayName || "").toLowerCase();
      const username = String(row?.username || "").toLowerCase();
      return display.includes(query) || username.includes(query);
    });
  }

  if (!rows.length) {
    listEl.innerHTML = `<div class="hint">No friends available to invite.</div>`;
    return;
  }

  listEl.innerHTML = rows.map((row) => {
    const uid = normId(row?.userId || "");
    const displayName = normalizeConversationLabel(row?.displayName || row?.username || "friend", "friend");
    const username = String(row?.username || "").trim();
    const avatarUrl = String(row?.avatarUrl || "").trim();
    const isBusy = !!(serverInviteBusyUserId && serverInviteBusyUserId === uid);
    const wasInvited = !!(serverInviteLastInvitedUserId && serverInviteLastInvitedUserId === uid);
    const actionLabel = isBusy ? "Sending..." : (wasInvited ? "Invited" : "Invite");
    const actionClass = wasInvited && !isBusy ? " is-ok" : "";

    return `
      <div class="serverInviteFriendRow">
        <div class="serverInviteFriendIdentity">
          <span class="serverInviteFriendAvatar">
            ${avatarUrl ? buildAvatarMediaHtml(avatarUrl, { userId: uid, alt: "avatar", deferAnimatedStorage: true }) : `<span class="groupDmAvatarFallback">${esc(getGroupOrbFallbackChar(displayName, "U"))}</span>`}
          </span>
          <span class="serverInviteFriendText">
            <span class="serverInviteFriendName">${esc(displayName)}</span>
            <span class="serverInviteFriendUsername">@${esc(username || "user")}</span>
          </span>
        </div>
        <button
          class="btn ghost serverInviteFriendAction${actionClass}"
          type="button"
          data-server-direct-invite="${escAttr(uid)}"
          ${isBusy ? "disabled" : ""}
        >${esc(actionLabel)}</button>
      </div>
    `;
  }).join("");
}

const SERVER_INVITE_QUERY_KEYS = ["server_invite", "invite", "serverInvite"];
const SERVER_INVITE_CODE_RE = /^[A-Za-z0-9_-]{6,96}$/;
const SERVER_INVITE_DEFAULT_EXPIRE_HOURS = 168;
const SERVER_INVITE_DEFAULT_MAX_USES = 0;

function normalizeServerInviteCode(value) {
  const code = String(value || "").trim().replace(/\s+/g, "");
  if (!code || !SERVER_INVITE_CODE_RE.test(code)) return "";
  return code;
}

function normalizeServerInviteExpiresHours(value) {
  const hours = Number(value);
  if (!Number.isFinite(hours)) return SERVER_INVITE_DEFAULT_EXPIRE_HOURS;
  return Math.max(0, Math.round(hours));
}

function normalizeServerInviteMaxUses(value) {
  const uses = Number(value);
  if (!Number.isFinite(uses)) return SERVER_INVITE_DEFAULT_MAX_USES;
  return Math.max(0, Math.round(uses));
}

function formatServerInviteExpirySettingLabel(hours) {
  const normalized = normalizeServerInviteExpiresHours(hours);
  if (normalized <= 0) return "Never";
  if (normalized === 1) return "1 hour";
  if (normalized % 24 === 0) {
    const days = normalized / 24;
    return days === 1 ? "1 day" : `${days} days`;
  }
  return `${normalized} hours`;
}

function formatServerInviteUsesSettingLabel(maxUses) {
  const normalized = normalizeServerInviteMaxUses(maxUses);
  if (normalized <= 0) return "No limit";
  if (normalized === 1) return "1 use";
  return `${normalized} uses`;
}

function formatServerInviteSettingsSummary(hours, maxUses) {
  return `${formatServerInviteExpirySettingLabel(hours)} • ${formatServerInviteUsesSettingLabel(maxUses)}`;
}

function resetServerInviteGeneratedLink({ markDirty = false } = {}) {
  serverInviteLinkCode = "";
  serverInviteLinkUrl = "";
  serverInviteLinkExpiresAt = "";
  serverInviteLinkMaxUses = normalizeServerInviteMaxUses(serverInviteMaxUses);
  serverInviteLinkUsesCount = 0;
  serverInviteSettingsDirty = !!markDirty;
  serverInviteLinkRequestId += 1;
}

function buildServerInviteUrlFromCode(code) {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode) return "";
  if (getDesktopBridge()) {
    return `altara://invite/${encodeURIComponent(inviteCode)}`;
  }
  const origin = String(window.location?.origin || "").trim();
  const path = String(window.location?.pathname || "").trim() || "/";
  const base = origin ? `${origin}${path}` : path;
  return `${base}?server_invite=${encodeURIComponent(inviteCode)}`;
}

function resolveServerInviteUrl(rawInviteUrl, code) {
  const inviteCode = normalizeServerInviteCode(code);
  const fallback = buildServerInviteUrlFromCode(inviteCode);
  if (getDesktopBridge() && fallback) return fallback;
  const raw = String(rawInviteUrl || "").trim();
  if (!raw) return fallback;
  try {
    const url = new URL(raw, window.location?.origin || undefined);
    const extracted = extractServerInviteCodeFromUrl(url.toString());
    if (!extracted && inviteCode) {
      url.searchParams.set("server_invite", inviteCode);
    }
    return url.toString();
  } catch (_) {
    return fallback;
  }
}

function extractServerInviteCodeFromUrl(urlLike = "") {
  const raw = String(urlLike || "").trim();
  if (!raw) return "";
  try {
    const url = new URL(raw, window.location?.origin || undefined);
    for (const key of SERVER_INVITE_QUERY_KEYS) {
      const code = normalizeServerInviteCode(url.searchParams.get(key) || "");
      if (code) return code;
    }
    const segments = String(url.pathname || "")
      .split("/")
      .map((segment) => {
        try {
          return decodeURIComponent(String(segment || "").trim());
        } catch (_) {
          return String(segment || "").trim();
        }
      })
      .filter(Boolean);
    if (segments.length >= 2 && String(segments[0] || "").trim().toLowerCase() === "invite") {
      const code = normalizeServerInviteCode(segments[1]);
      if (code) return code;
    }
    const host = String(url.hostname || url.host || "").trim().toLowerCase();
    if (host === "invite" && segments.length >= 1) {
      const code = normalizeServerInviteCode(segments[0]);
      if (code) return code;
    }
  } catch (_) {
    // not an URL, ignore
  }
  return "";
}

function extractServerInviteCodeFromText(text) {
  const raw = String(text || "").trim();
  if (!raw) return "";
  const direct = normalizeServerInviteCode(raw);
  if (direct) return direct;
  const fromUrl = extractServerInviteCodeFromUrl(raw);
  if (fromUrl) return fromUrl;
  const urlMatch = raw.match(/(?:https?:\/\/|altara:\/\/)[^\s<>"']+/i);
  if (urlMatch?.[0]) {
    return extractServerInviteCodeFromUrl(urlMatch[0]);
  }
  return "";
}

function readServerInviteCodeFromWindowLocation() {
  try {
    const url = new URL(window.location.href);
    for (const key of SERVER_INVITE_QUERY_KEYS) {
      const code = normalizeServerInviteCode(url.searchParams.get(key) || "");
      if (code) return code;
    }
    const hash = String(url.hash || "");
    if (hash.includes("=")) {
      const hashBody = hash.startsWith("#") ? hash.slice(1) : hash;
      const hashParams = new URLSearchParams(hashBody.startsWith("?") ? hashBody.slice(1) : hashBody);
      for (const key of SERVER_INVITE_QUERY_KEYS) {
        const code = normalizeServerInviteCode(hashParams.get(key) || "");
        if (code) return code;
      }
    }
    const pathMatch = String(url.pathname || "").match(/\/invite\/([A-Za-z0-9_-]{6,96})/i);
    if (pathMatch?.[1]) {
      const code = normalizeServerInviteCode(pathMatch[1]);
      if (code) return code;
    }
  } catch (_) {}
  return "";
}

function clearServerInviteCodeFromWindowLocation() {
  try {
    const url = new URL(window.location.href);
    let changed = false;
    for (const key of SERVER_INVITE_QUERY_KEYS) {
      if (url.searchParams.has(key)) {
        url.searchParams.delete(key);
        changed = true;
      }
    }
    if (!changed) return;
    const nextSearch = url.searchParams.toString();
    const nextHref = `${url.pathname}${nextSearch ? `?${nextSearch}` : ""}${url.hash || ""}`;
    window.history?.replaceState?.(window.history.state || null, "", nextHref);
  } catch (_) {}
}

async function createServerInviteLinkRpc(serverId, { expiresHours = SERVER_INVITE_DEFAULT_EXPIRE_HOURS, maxUses = SERVER_INVITE_DEFAULT_MAX_USES } = {}) {
  const sid = normId(serverId);
  if (!sid) return { data: null, error: { message: "server_id invalido" } };
  const normalizedExpiresHours = normalizeServerInviteExpiresHours(expiresHours);
  const normalizedMaxUses = normalizeServerInviteMaxUses(maxUses);
  const payload = {
    p_server_id: sid,
    p_expires_in_hours: normalizedExpiresHours,
    p_max_uses: normalizedMaxUses,
  };
  lastServerInviteCreateRpcDebug = {
    rpcFunction: "create_server_invite_link",
    payloadKeys: Object.keys(payload),
    phase: "requesting",
    startedAt: Date.now(),
    error: null,
  };
  const result = await supabase.rpc("create_server_invite_link", payload);
  lastServerInviteCreateRpcDebug = {
    ...lastServerInviteCreateRpcDebug,
    phase: result?.error ? "failed" : "completed",
    finishedAt: Date.now(),
    error: result?.error ? {
      code: String(result.error?.code || ""),
      message: String(result.error?.message || result.error || ""),
      details: String(result.error?.details || ""),
      hint: String(result.error?.hint || ""),
    } : null,
    responseShape: Array.isArray(result?.data) ? "table_rows" : typeof result?.data,
  };
  return result;
}

function getInviteErrorDatabaseFunctionName(error = null) {
  const text = [error?.message, error?.details, error?.hint]
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean)
    .join(" ");
  const match = text.match(/(?:function|find the function)\s+(?:public\.)?([a-z0-9_]+)\s*\(/i);
  return String(match?.[1] || "").trim().toLowerCase();
}

function isInviteRpcUnavailableError(error = null, functionName = "") {
  const code = String(error?.code || "").trim().toUpperCase();
  const text = [error?.message, error?.details, error?.hint]
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean)
    .join(" ");
  const fn = String(functionName || "").trim().toLowerCase();
  if (!fn) return false;
  const namesOuterFunction = text.includes(`public.${fn}`) || text.includes(`${fn}(`);
  if (code === "PGRST202") return namesOuterFunction;
  if (code === "42883") {
    return getInviteErrorDatabaseFunctionName(error) === fn && text.includes("does not exist");
  }
  return text.includes(`could not find the function public.${fn}`)
    || (namesOuterFunction && text.includes("does not exist"));
}

async function joinServerByInviteCodeRpc(code) {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode) return { data: null, error: { message: "codigo de convite invalido" } };
  const existing = serverInviteJoinPromiseByCode.get(inviteCode);
  if (existing) return existing;
  const payload = { p_code: inviteCode };
  lastServerInviteJoinRpcDebug = {
    rpcFunction: "join_server_by_invite_code_safe",
    payloadKeys: Object.keys(payload),
    inviteCodeRedacted: `${inviteCode.slice(0, 3)}...`,
    phase: "requesting",
    inviteStatus: "",
    outerRpcAvailable: null,
    underlyingFunction: "",
    membershipInsertionStarted: false,
    membershipCreated: false,
    inviteUseIncremented: false,
    startedAt: Date.now(),
    error: null,
  };
  const promise = supabase.rpc("join_server_by_invite_code_safe", payload)
    .then((result) => {
      const error = result?.error || null;
      const row = Array.isArray(result?.data) ? (result.data[0] || null) : result?.data;
      const underlyingFunction = error ? getInviteErrorDatabaseFunctionName(error) : "";
      const outerRpcAvailable = !error || !isInviteRpcUnavailableError(error, "join_server_by_invite_code_safe");
      const membershipHelperStarted = underlyingFunction === "altara_insert_server_member_safe";
      const alreadyMember = row?.already_member === true || row?.alreadyMember === true;
      const joinedNow = row?.joined_now === true || row?.joinedNow === true || (!error && !alreadyMember);
      lastServerInviteJoinRpcDebug = {
        ...lastServerInviteJoinRpcDebug,
        phase: error ? "failed" : "completed",
        inviteStatus: error ? classifyServerInviteJoinError(error) : "joined",
        outerRpcAvailable,
        underlyingFunction,
        membershipInsertionStarted: membershipHelperStarted || joinedNow,
        membershipCreated: !!(!error && joinedNow),
        inviteUseIncremented: !!(!error && joinedNow),
        finishedAt: Date.now(),
        error: error ? {
          code: String(error?.code || ""),
          message: String(error?.message || error || ""),
          details: String(error?.details || ""),
          hint: String(error?.hint || ""),
        } : null,
      };
      return result;
    })
    .finally(() => {
      if (serverInviteJoinPromiseByCode.get(inviteCode) === promise) {
        serverInviteJoinPromiseByCode.delete(inviteCode);
      }
    });
  serverInviteJoinPromiseByCode.set(inviteCode, promise);
  return promise;
}

function getServerIdFromInviteJoinResult(data = null) {
  const row = Array.isArray(data) ? (data[0] || null) : data;
  return normId(
    row?.server_id
    || row?.serverId
    || row?.id
    || row?.server?.id
    || row?.server?.server_id
    || ""
  );
}

function isServerInviteBannedError(error = null) {
  const raw = String(error?.message || error?.details || error?.hint || error || "").trim().toLowerCase();
  return raw === "server_banned" || raw.includes("server_banned") || raw.includes("banned from this server");
}

function classifyServerInviteJoinError(error = null) {
  const raw = String(error?.message || error?.details || error?.hint || error || "").trim().toLowerCase();
  if (getInviteErrorDatabaseFunctionName(error) === "altara_insert_server_member_safe") return "membership_setup_incomplete";
  if (isInviteRpcUnavailableError(error, "join_server_by_invite_code_safe")) return "rpc_missing";
  if (raw.includes("invite_revoked")) return "revoked";
  if (raw.includes("invite_expired")) return "expired";
  if (raw.includes("invite_exhausted")) return "exhausted";
  if (raw.includes("server_banned") || raw.includes("banned from this server")) return "banned";
  if (raw.includes("already_member")) return "already_member";
  if (raw.includes("invite_not_found") || raw.includes("invalid_invite")) return "invalid";
  if (String(error?.code || "").trim() === "42702") return "database_ambiguity";
  return "error";
}

function getServerInviteJoinErrorMessage(error = null) {
  const status = classifyServerInviteJoinError(error);
  if (status === "rpc_missing") return "Invite join SQL is missing. Apply the server invite patch and reload.";
  if (status === "membership_setup_incomplete") return "Invite join is temporarily unavailable because server membership setup is incomplete.";
  if (status === "revoked") return "This invite has been revoked.";
  if (status === "expired") return "This invite has expired.";
  if (status === "exhausted") return "This invite has reached its maximum number of uses.";
  if (status === "banned") return "You are banned from this server.";
  if (status === "invalid") return "This invite is invalid.";
  if (status === "database_ambiguity") return "This invite could not be processed because the server invite function needs the runtime hotfix.";
  return "Could not join this server. Try again.";
}

function getServerInviteBannedState(code = "") {
  const inviteCode = normalizeServerInviteCode(code);
  return inviteCode ? (serverInviteBannedStateByCode.get(inviteCode) || null) : null;
}

function normalizeServerInvitePreviewData(code = "", data = null, { source = "unknown", error = null } = {}) {
  const inviteCode = normalizeServerInviteCode(code);
  const row = Array.isArray(data) ? (data[0] || null) : data;
  if (!inviteCode) return null;
  if (!row || typeof row !== "object") {
    return {
      code: inviteCode,
      status: error ? "error" : "loading",
      ok: false,
      source,
      lastPreviewAt: new Date().toISOString(),
      lastPreviewError: error ? String(error?.message || error || "unknown_error") : "",
    };
  }
  const statusRaw = String(row?.status || "").trim().toLowerCase();
  const isBanned = row?.isBanned === true || row?.is_banned === true || statusRaw === "banned";
  const alreadyMember = row?.alreadyMember === true || row?.already_member === true || statusRaw === "already_member" || statusRaw === "member";
  const invalid = row?.ok === false || statusRaw === "invalid_or_expired" || statusRaw === "expired" || statusRaw === "invalid";
  const serverId = normId(row?.serverId || row?.server_id || "");
  const serverName = normalizeConversationLabel(row?.serverName || row?.server_name || row?.name || "Server", "Server");
  const serverIconUrl = sanitizeServerIconUrl(row?.serverIconUrl || row?.server_icon_url || row?.icon_url || row?.avatar_url || "");
  const serverBannerUrl = normalizeBannerUrl(row?.serverBannerUrl || row?.server_banner_url || row?.banner_url || row?.cover_url || row?.image_url || "");
  const memberCount = Number(row?.memberCount ?? row?.member_count ?? row?.approximateMemberCount ?? row?.approximate_member_count ?? 0) || 0;
  const status = invalid ? "invalid_or_expired" : (isBanned ? "banned" : (alreadyMember ? "already_member" : "joinable"));
  return {
    code: inviteCode,
    ok: !invalid,
    status,
    serverId,
    serverName,
    serverIconUrl,
    serverBannerUrl,
    isBanned,
    alreadyMember,
    memberCount,
    approximateMemberCount: memberCount,
    expiresAt: row?.expiresAt || row?.expires_at || "",
    maxUses: Number(row?.maxUses ?? row?.max_uses ?? 0) || 0,
    usesCount: Number(row?.usesCount ?? row?.uses_count ?? 0) || 0,
    source,
    lastPreviewAt: new Date().toISOString(),
    lastPreviewError: error ? String(error?.message || error || "unknown_error") : "",
  };
}

function rememberServerInvitePreviewState(code = "", preview = null) {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode || !preview) return null;
  const sid = normId(preview?.serverId || "");
  const clearAt = sid ? Number(lastServerBannerClearAtByServerId.get(sid) || 0) : 0;
  const setInfo = sid ? (lastServerBannerSetByServerId.get(sid) || null) : null;
  if (sid && clearAt && preview.serverBannerUrl) {
    preview = {
      ...preview,
      serverBannerUrl: "",
      hasBanner: false,
      bannerRemoved: true,
      lastBannerClearAt: new Date(clearAt).toISOString(),
    };
  } else if (sid && setInfo?.url && !preview.serverBannerUrl) {
    preview = {
      ...preview,
      serverBannerUrl: setInfo.url,
      hasBanner: true,
      bannerRemoved: false,
      lastBannerSetAt: new Date(setInfo.at).toISOString(),
    };
  }
  serverInvitePreviewStateByCode.set(inviteCode, preview);
  serverInvitePreviewStaleByCode.delete(inviteCode);
  if (preview.status === "banned" || preview.isBanned) {
    markServerInviteCodeBanned(inviteCode, {
      serverId: preview.serverId || "",
      message: "You are banned from this server.",
    });
  } else if (preview.status === "joinable" || preview.status === "already_member") {
    serverInviteBannedStateByCode.delete(inviteCode);
  }
  return preview;
}

function getEscapedInviteCodeSelectorValue(inviteCode = "") {
  const code = normalizeServerInviteCode(inviteCode);
  if (!code) return "";
  return typeof CSS !== "undefined" && typeof CSS.escape === "function"
    ? CSS.escape(code)
    : code.replace(/["\\]/g, "\\$&");
}

function getVisibleInviteCardsForCode(code = "") {
  const inviteCode = normalizeServerInviteCode(code);
  const escapedCode = getEscapedInviteCodeSelectorValue(inviteCode);
  if (!escapedCode) return [];
  return Array.from(document.querySelectorAll(`.dmServerInviteCard[data-invite-code="${escapedCode}"]`));
}

function getVisibleInviteCardsForServer(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return [];
  return Array.from(document.querySelectorAll(".dmServerInviteCard[data-invite-server-id]"))
    .filter((card) => normId(card.getAttribute("data-invite-server-id") || "") === sid);
}

function markInvitePreviewStaleForServer(serverId = "", reason = "server_profile_updated") {
  const sid = normId(serverId || "");
  if (!sid) return 0;
  let count = 0;
  for (const [code, preview] of serverInvitePreviewStateByCode.entries()) {
    if (normId(preview?.serverId || "") !== sid) continue;
    serverInvitePreviewStaleByCode.set(code, { reason, at: new Date().toISOString() });
    count += 1;
  }
  getVisibleInviteCardsForServer(sid).forEach((card) => {
    const code = normalizeServerInviteCode(card.getAttribute("data-invite-code") || "");
    if (!code) return;
    serverInvitePreviewStaleByCode.set(code, { reason, at: new Date().toISOString() });
    count += 1;
  });
  return count;
}

function applyServerProfilePatchToInvitePreview(preview = null, patch = {}) {
  if (!preview) return preview;
  const next = { ...preview };
  const explicitBannerClear = hasExplicitBannerClear(patch);
  const explicitBannerSetUrl = getExplicitBannerSetUrl(patch);
  if (typeof patch.name !== "undefined") next.serverName = normalizeConversationLabel(patch.name || next.serverName || "Server", "Server");
  if (typeof patch.iconUrl !== "undefined") next.serverIconUrl = sanitizeServerIconUrl(patch.iconUrl || "");
  if (explicitBannerClear) {
    next.serverBannerUrl = "";
    next.hasBanner = false;
    next.bannerRemoved = true;
    next.lastBannerClearAt = new Date().toISOString();
  } else if (explicitBannerSetUrl) {
    next.serverBannerUrl = explicitBannerSetUrl;
    next.hasBanner = true;
    next.bannerRemoved = false;
    next.lastBannerSetAt = new Date().toISOString();
  } else if (typeof patch.bannerUrl !== "undefined" || typeof patch.serverBannerUrl !== "undefined") {
    next.serverBannerUrl = "";
    next.hasBanner = false;
  }
  next.lastProfileUpdateAt = new Date().toISOString();
  return next;
}

function applyServerProfilePatchToInviteCards(serverId = "", patch = {}, { repreview = true, reason = "server_profile_updated" } = {}) {
  const sid = normId(serverId || patch?.serverId || "");
  if (!sid) return 0;
  lastServerProfileUpdateAtByServerId.set(sid, Date.now());
  const explicitBannerClear = hasExplicitBannerClear(patch);
  const explicitBannerSetUrl = getExplicitBannerSetUrl(patch);
  if (explicitBannerClear) {
    lastServerBannerClearAtByServerId.set(sid, Date.now());
    lastServerBannerSetByServerId.delete(sid);
  }
  else if (explicitBannerSetUrl) {
    const at = Date.now();
    lastServerBannerSetByServerId.set(sid, { url: explicitBannerSetUrl, at });
    lastServerBannerClearAtByServerId.delete(sid);
    logServerProfileBannerDebug("explicit set received", { serverId: sid, bannerUrl: explicitBannerSetUrl, source: reason });
  }
  markInvitePreviewStaleForServer(sid, reason);
  let count = 0;
  for (const [code, preview] of Array.from(serverInvitePreviewStateByCode.entries())) {
    if (normId(preview?.serverId || "") !== sid) continue;
    const patched = applyServerProfilePatchToInvitePreview(preview, patch);
    serverInvitePreviewStateByCode.set(code, patched);
    serverInvitePreviewProfileTouchedByCode.set(code, new Date().toISOString());
    getVisibleInviteCardsForCode(code).forEach((card) => {
      applyServerInvitePreviewToCard(card, patched);
      count += 1;
    });
    if (repreview) {
      void refreshInvitePreviewForCode(code, { reason, render: true }).catch(() => {});
    }
  }
  getVisibleInviteCardsForServer(sid).forEach((card) => {
    const code = normalizeServerInviteCode(card.getAttribute("data-invite-code") || "");
    if (!code) return;
    const preview = serverInvitePreviewStateByCode.get(code) || {
      code,
      ok: true,
      status: card.getAttribute("data-invite-state") || "joinable",
      serverId: sid,
      serverName: card.querySelector(".dmServerInviteName")?.textContent?.trim?.() || "Server",
      serverIconUrl: "",
      serverBannerUrl: "",
    };
    const patched = applyServerProfilePatchToInvitePreview(preview, patch);
    serverInvitePreviewStateByCode.set(code, patched);
    serverInvitePreviewProfileTouchedByCode.set(code, new Date().toISOString());
    applyServerInvitePreviewToCard(card, patched);
    count += 1;
    if (repreview) {
      void refreshInvitePreviewForCode(code, { reason, render: true }).catch(() => {});
    }
  });
  return count;
}

async function previewServerInviteCode(code = "") {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode) return normalizeServerInvitePreviewData(code, null, { source: "invalid", error: "invalid_invite_code" });
  const v2 = await supabase.rpc("preview_server_invite_v2", { p_code: inviteCode });
  if (!v2?.error && v2?.data) {
    return rememberServerInvitePreviewState(inviteCode, normalizeServerInvitePreviewData(inviteCode, v2.data, { source: "preview_server_invite_v2" }));
  }
  if (v2?.error && !isMissingRpcError(v2.error)) {
    return rememberServerInvitePreviewState(inviteCode, normalizeServerInvitePreviewData(inviteCode, null, { source: "preview_server_invite_v2", error: v2.error }));
  }

  const { data: rpcData, error: rpcErr } = await supabase.rpc("preview_server_invite", { p_code: inviteCode });
  if (!rpcErr && rpcData?.length) {
    return rememberServerInvitePreviewState(inviteCode, normalizeServerInvitePreviewData(inviteCode, rpcData, { source: "preview_server_invite" }));
  }
  if (rpcErr && !isMissingRpcError(rpcErr)) {
    return rememberServerInvitePreviewState(inviteCode, normalizeServerInvitePreviewData(inviteCode, null, { source: "preview_server_invite", error: rpcErr }));
  }

  return rememberServerInvitePreviewState(inviteCode, normalizeServerInvitePreviewData(inviteCode, null, {
    source: "invite_preview_fallback",
    error: rpcErr || v2?.error || "preview_unavailable",
  }));
}

async function refreshInvitePreviewForCode(code = "", { reason = "manual", render = true } = {}) {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode) return null;
  const preview = await previewServerInviteCode(inviteCode);
  const sid = normId(preview?.serverId || "");
  const clearAt = sid ? Number(lastServerBannerClearAtByServerId.get(sid) || 0) : 0;
  const setInfo = sid ? (lastServerBannerSetByServerId.get(sid) || null) : null;
  const previewAt = Date.parse(preview?.lastPreviewAt || "") || Date.now();
  if (preview && sid && clearAt && previewAt >= clearAt && preview.serverBannerUrl) {
    preview.serverBannerUrl = "";
    preview.hasBanner = false;
    preview.bannerRemoved = true;
    preview.lastBannerClearAt = new Date(clearAt).toISOString();
    serverInvitePreviewStateByCode.set(inviteCode, preview);
  } else if (preview && sid && setInfo?.url && previewAt >= Number(setInfo.at || 0) && !preview.serverBannerUrl) {
    preview.serverBannerUrl = setInfo.url;
    preview.hasBanner = true;
    preview.bannerRemoved = false;
    preview.lastBannerSetAt = new Date(setInfo.at).toISOString();
    serverInvitePreviewStateByCode.set(inviteCode, preview);
  }
  if (preview) {
    serverInvitePreviewStaleByCode.delete(inviteCode);
    preview.lastRepreviewReason = reason;
  }
  if (render) {
    getVisibleInviteCardsForCode(inviteCode).forEach((card) => {
      applyServerInvitePreviewToCard(card, preview);
    });
  }
  if (sid) syncServerProfileBroadcastSubscriptions();
  return preview;
}

function applyServerInviteBannedStateToCard(card, stateInfo = null) {
  if (!card) return false;
  const code = normalizeServerInviteCode(card.getAttribute("data-invite-code") || "");
  const info = stateInfo || getServerInviteBannedState(code);
  if (!info) return false;
  card.setAttribute("data-invite-state", "banned");
  card.classList.add("dmServerInviteCard--blocked");
  const joinBtn = card.querySelector(".msgInviteCard__joinBtn");
  if (joinBtn) {
    joinBtn.textContent = "Banned";
    joinBtn.disabled = true;
    joinBtn.setAttribute("aria-disabled", "true");
    joinBtn.title = info.message || "You are banned from this server.";
  }
  const membersEl = card.querySelector(".msgInviteCard__members");
  if (membersEl) {
    membersEl.innerHTML = `<span class="msgInviteCard__membersDot dmServerInviteMetaDot"></span><span class="dmServerInviteMetaText">${esc(info.message || "You are banned from this server.")}</span>`;
  }
  return true;
}

function applyServerInvitePreviewToCard(card, preview = null) {
  if (!card || !preview) return false;
  const code = normalizeServerInviteCode(card.getAttribute("data-invite-code") || preview.code || "");
  const nameEl = card.querySelector(".msgInviteCard__name");
  const iconWrap = card.querySelector(".msgInviteCard__iconWrap");
  const heroEl = card.querySelector(".dmServerInviteHero");
  const membersEl = card.querySelector(".msgInviteCard__members");
  const joinBtn = card.querySelector(".msgInviteCard__joinBtn");
  const serverName = normalizeConversationLabel(preview.serverName || "Server", "Server");
  const status = String(preview.status || "joinable").trim().toLowerCase();
  card.classList.add("dmServerInviteCard--ready");
  card.classList.toggle("dmServerInviteCard--blocked", status === "banned");
  card.classList.toggle("dmServerInviteCard--expired", status === "invalid_or_expired" || status === "expired" || status === "invalid");
  card.setAttribute("data-invite-state", status);
  if (preview.serverId) card.setAttribute("data-invite-server-id", preview.serverId);
  if (nameEl) nameEl.textContent = serverName;
  if (iconWrap) {
    iconWrap.classList.remove("msgInviteCard__iconWrap--loading");
    iconWrap.innerHTML = preview.serverIconUrl
      ? `<img class="msgInviteCard__icon" src="${escAttr(preview.serverIconUrl)}" alt="" loading="lazy" />`
      : `<span class="msgInviteCard__iconFallback">${esc((serverName[0] || "S").toUpperCase())}</span>`;
  }
  if (heroEl) {
    if (preview.serverBannerUrl) {
      heroEl.classList.add("dmServerInviteHero--media");
      heroEl.innerHTML = `<img class="dmServerInviteHeroImg" src="${escAttr(preview.serverBannerUrl)}" alt="" loading="lazy" />`;
    } else {
      heroEl.classList.remove("dmServerInviteHero--media");
      heroEl.innerHTML = "";
    }
  }
  if (membersEl) {
    const count = Number(preview.memberCount || preview.approximateMemberCount || 0) || 0;
    let meta = "Server Invite";
    if (status === "banned") meta = "You are banned from this server.";
    else if (status === "invalid_or_expired" || status === "expired" || status === "invalid") meta = "Invite expired";
    else if (status === "already_member") meta = "Already a member";
    else if (count > 0) meta = count === 1 ? t("dm.group_member_count_one", "1 member") : t("dm.group_member_count", "{n} members").replace("{n}", count.toLocaleString());
    membersEl.innerHTML = `<span class="msgInviteCard__membersDot dmServerInviteMetaDot"></span><span class="dmServerInviteMetaText">${esc(meta)}</span>`;
  }
  if (joinBtn) {
    if (status === "banned") {
      joinBtn.textContent = "Banned";
      joinBtn.disabled = true;
      joinBtn.setAttribute("aria-disabled", "true");
      joinBtn.title = "You are banned from this server.";
    } else if (status === "invalid_or_expired" || status === "expired" || status === "invalid") {
      joinBtn.textContent = "Expired";
      joinBtn.disabled = true;
      joinBtn.setAttribute("aria-disabled", "true");
      joinBtn.title = "Invite expired";
    } else if (status === "already_member") {
      joinBtn.textContent = t("dm.server_invite.open", "Open Server");
      joinBtn.disabled = false;
      joinBtn.removeAttribute("aria-disabled");
      joinBtn.title = "";
    } else {
      joinBtn.textContent = t("dm.server_invite.join", "Join Server");
      joinBtn.disabled = false;
      joinBtn.removeAttribute("aria-disabled");
      joinBtn.title = "";
    }
  }
  if (code) rememberServerInvitePreviewState(code, { ...preview, code });
  if (preview.serverId) syncServerProfileBroadcastSubscriptions();
  return true;
}

