function markServerInviteCodeBanned(code = "", { serverId = "", message = "You are banned from this server." } = {}) {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode) return null;
  const info = {
    status: "banned",
    message: String(message || "You are banned from this server.").trim() || "You are banned from this server.",
    serverId: normId(serverId || ""),
    updatedAt: new Date().toISOString(),
  };
  serverInviteBannedStateByCode.set(inviteCode, info);
  const escapedCode = typeof CSS !== "undefined" && typeof CSS.escape === "function"
    ? CSS.escape(inviteCode)
    : inviteCode.replace(/["\\]/g, "\\$&");
  document.querySelectorAll(`.dmServerInviteCard[data-invite-code="${escapedCode}"]`).forEach((card) => {
    applyServerInviteBannedStateToCard(card, info);
  });
  return info;
}

function refreshInviteCardsForCode(code = "") {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode) return 0;
  const escapedCode = typeof CSS !== "undefined" && typeof CSS.escape === "function"
    ? CSS.escape(inviteCode)
    : inviteCode.replace(/["\\]/g, "\\$&");
  let count = 0;
  document.querySelectorAll(`.dmServerInviteCard[data-invite-code="${escapedCode}"]`).forEach((card) => {
    count += 1;
    card.removeAttribute("data-invite-hydrated");
    void hydrateOneInviteCard(card).catch(() => {});
  });
  return count;
}

function refreshServerInviteCardsForServer(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return 0;
  let count = 0;
  for (const [code, preview] of serverInvitePreviewStateByCode.entries()) {
    if (normId(preview?.serverId || "") === sid) {
      serverInvitePreviewStateByCode.delete(code);
      count += refreshInviteCardsForCode(code);
    }
  }
  document.querySelectorAll(".dmServerInviteCard[data-invite-server-id]").forEach((card) => {
    if (normId(card.getAttribute("data-invite-server-id") || "") !== sid) return;
    count += 1;
    card.removeAttribute("data-invite-hydrated");
    void hydrateOneInviteCard(card).catch(() => {});
  });
  return count;
}

async function refreshVisibleInviteCardsForServer(serverId = "", reason = "manual") {
  const sid = normId(serverId || "");
  if (!sid) return { serverId: sid, refreshed: 0, codes: [] };
  const codes = new Set();
  for (const [code, preview] of serverInvitePreviewStateByCode.entries()) {
    if (normId(preview?.serverId || "") === sid) codes.add(code);
  }
  getVisibleInviteCardsForServer(sid).forEach((card) => {
    const code = normalizeServerInviteCode(card.getAttribute("data-invite-code") || "");
    if (code) codes.add(code);
  });
  let refreshed = 0;
  for (const code of codes) {
    await refreshInvitePreviewForCode(code, { reason, render: true }).catch((error) => {
      if (isServerProfileDebugEnabled()) console.warn("[server-profile] invite repreview failed", { serverId: sid, code, reason, message: error?.message || error });
    });
    refreshed += 1;
  }
  syncServerProfileBroadcastSubscriptions();
  return { serverId: sid, refreshed, codes: Array.from(codes) };
}

function scheduleVisibleInviteProfileRevalidation(reason = "focus") {
  if (serverProfileFocusRepreviewTimer) clearTimeout(serverProfileFocusRepreviewTimer);
  serverProfileFocusRepreviewTimer = setTimeout(() => {
    serverProfileFocusRepreviewTimer = 0;
    const serverIds = new Set();
    document.querySelectorAll(".dmServerInviteCard[data-invite-server-id]").forEach((card) => {
      const sid = normId(card.getAttribute("data-invite-server-id") || "");
      if (sid) serverIds.add(sid);
    });
    for (const sid of serverIds) {
      void refreshVisibleInviteCardsForServer(sid, reason).catch(() => {});
    }
    syncServerProfileBroadcastSubscriptions();
  }, 250);
}

function bindServerProfileInviteRevalidationFallbackOnce() {
  if (serverProfileFocusRepreviewBound || typeof window === "undefined" || typeof document === "undefined") return;
  serverProfileFocusRepreviewBound = true;
  window.addEventListener("focus", () => scheduleVisibleInviteProfileRevalidation("window_focus"));
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") scheduleVisibleInviteProfileRevalidation("visibilitychange");
  });
}

async function joinServerFromInviteCode(code, { openConversation = true, showFeedback = true, source = "invite_card" } = {}) {
  const inviteCode = normalizeServerInviteCode(code);
  if (!inviteCode) return { ok: false, error: { message: "Invalid invite code." } };

  const { data, error } = await joinServerByInviteCodeRpc(inviteCode);
  if (error) {
    const banned = isServerInviteBannedError(error);
    const message = getServerInviteJoinErrorMessage(error);
    if (banned) markServerInviteCodeBanned(inviteCode, { message });
    if (showFeedback) {
      if (typeof showDmComposerNotice === "function") showDmComposerNotice(message, { title: "Server Invite" });
      else await requestAppAlert(message, { title: "Server Invite" }).catch(() => {});
    }
    console.warn("[server-invite] join failed", { source, code: inviteCode, error });
    return { ok: false, error };
  }

  const joinedServerId = getServerIdFromInviteJoinResult(data);
  serverInviteBannedStateByCode.delete(inviteCode);
  serverInvitePreviewStateByCode.delete(inviteCode);
  await loadGroupAndServerCollections({ force: true, hydrateGroupMetadata: true }).catch((refreshError) => {
    console.warn("[server-invite] server list refresh failed", refreshError?.message || refreshError);
  });
  renderGroupsRail();

  const sid = joinedServerId || getServerIdFromInviteJoinResult(data) || "";
  const serverRow = sid ? getServerRowById(sid) : null;
  if (sid) {
    syncUserMembershipBroadcastSubscription();
    syncServerMemberRemovalBroadcastSubscriptions();
    syncServerProfileBroadcastSubscriptions();
    void handleServerMemberJoined({
      serverId: sid,
      userId: state.user?.id || "",
      reason: "invite_join_local",
      source: source || "invite_join",
    });
    void broadcastServerMemberJoined(sid, {
      userId: normId(state.user?.id || ""),
      reason: "invite_join",
      source: "invite_join",
      at: new Date().toISOString(),
    });
    void emitServerInvitesChangedBroadcast(sid, { reason: "invite_used" });
  }
  if (openConversation && sid) {
    await Promise.allSettled([
      fetchServerChannelsForSidebar(sid, { force: true }),
      fetchServerMembersForSidebar(sid, { force: true }),
      typeof loadChannelPermissionOverwritesForServer === "function"
        ? loadChannelPermissionOverwritesForServer(sid, { force: false })
        : Promise.resolve(),
    ]);
    const opened = await openVisibleServerChannelAfterPermissionChange(sid, null, "server-invite-joined").catch(() => false);
    if (!opened && serverRow?.defaultConversationId) {
      await openConversationById(serverRow.defaultConversationId, {
        kind: "server",
        isGroup: true,
        displayName: serverRow.name || "Server",
        serverId: sid,
        serverName: serverRow.name || "Server",
        avatarUrl: serverRow.iconUrl || "",
      }).catch(() => {});
    }
  }

  if (showFeedback && typeof showDmComposerNotice === "function") {
    showDmComposerNotice(serverRow?.name ? `Joined ${serverRow.name}.` : "Joined server.", { title: "Server Invite" });
  }
  return { ok: true, data, serverId: sid || normId(serverRow?.serverId || "") };
}

async function updateServerProfileRpc(serverId, { name = "", iconUrl = "", bannerUrl = "", bannerTouched = false } = {}) {
  const sid = normId(serverId);
  if (!sid) return { data: null, error: { message: "server_id invalido" } };
  const normalizedName = normalizeConversationLabel(String(name || "").trim(), "Server");
  const normalizedIcon = sanitizeServerIconUrl(iconUrl || "");
  const normalizedBanner = normalizeBannerUrl(bannerUrl || "");

  const payloads = bannerTouched
    ? [{ p_server_id: sid, p_name: normalizedName, p_icon_url: normalizedIcon || null, p_banner_url: normalizedBanner || null }]
    : [
        { p_server_id: sid, p_name: normalizedName, p_icon_url: normalizedIcon || null },
        { server_id: sid, name: normalizedName, icon_url: normalizedIcon || null },
      ];
  let lastMissingErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("update_server_profile", payload);
    if (!res?.error) return { ...res, method: "rpc:update_server_profile", savedWelcomeChannel: false };
    if (!isMissingRpcError(res.error)) return { ...res, method: "rpc:update_server_profile", savedWelcomeChannel: false };
    lastMissingErr = res.error;
  }
  return { data: null, error: lastMissingErr || { message: "rpc nao encontrada" }, method: "rpc:update_server_profile", savedWelcomeChannel: false };
}

function getServerSettingsActiveChannelSummaries(serverId = "") {
  const sid = normId(serverId || getServerSettingsActiveServerId());
  return (serverChannelListByServerId.get(sid) || []).map((channel) => ({
    id: normId(channel?.id || ""),
    conversationId: normId(channel?.conversationId || channel?.conversation_id || ""),
    name: String(channel?.name || "").trim(),
    channelType: String(channel?.channelType || channel?.channel_type || "").trim(),
    serverId: sid,
  }));
}

async function updateServerProfileWithWelcomeRpc(serverId, { name = "", iconUrl = "", welcomeChannelId = "", bannerUrl = "", bannerTouched = false } = {}) {
  const sid = normId(serverId);
  if (!sid) return { data: null, error: { message: "server_id invalido" }, method: "rpc:update_server_profile_v2", savedWelcomeChannel: false };
  const normalizedName = normalizeConversationLabel(String(name || "").trim(), "Server");
  const normalizedIcon = sanitizeServerIconUrl(iconUrl || "");
  const normalizedBanner = normalizeBannerUrl(bannerUrl || "");
  const normalizedWelcomeChannelId = normId(welcomeChannelId || "") || null;
  const selectedWelcomeChannelOption = (() => {
    const selectEl = typeof document !== "undefined" ? document.getElementById("serverSettingsWelcomeChannel") : null;
    const option = selectEl?.selectedOptions?.[0] || null;
    return option ? { value: String(option.value || ""), text: String(option.textContent || "").trim() } : null;
  })();
  console.info("[server-settings] update_server_profile_v2 payload", {
    serverId: sid,
    name: normalizedName,
    iconUrl: normalizedIcon,
    bannerUrl: normalizedBanner,
    welcomeChannelId: normalizedWelcomeChannelId,
    welcomeChannelIdType: typeof normalizedWelcomeChannelId,
    selectedWelcomeChannelOption,
    activeServerChannels: getServerSettingsActiveChannelSummaries(sid),
  });
  const payloads = bannerTouched
    ? [{ p_server_id: sid, p_name: normalizedName, p_icon_url: normalizedIcon || null, p_welcome_channel_id: normalizedWelcomeChannelId, p_banner_url: normalizedBanner || null }]
    : [
        { p_server_id: sid, p_name: normalizedName, p_icon_url: normalizedIcon || null, p_welcome_channel_id: normalizedWelcomeChannelId },
        { server_id: sid, name: normalizedName, icon_url: normalizedIcon || null, welcome_channel_id: normalizedWelcomeChannelId },
      ];
  let lastMissingErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("update_server_profile_v2", payload);
    if (!res?.error) return { ...res, method: "rpc:update_server_profile_v2", savedWelcomeChannel: true };
    if (!isMissingRpcError(res.error)) return { ...res, method: "rpc:update_server_profile_v2", savedWelcomeChannel: false };
    lastMissingErr = res.error;
  }

  const fallback = await updateServerProfileRpc(sid, { name: normalizedName, iconUrl: normalizedIcon, bannerUrl: normalizedBanner, bannerTouched });
  return {
    ...fallback,
    missingV2Error: lastMissingErr || null,
    savedWelcomeChannel: false,
  };
}

function isServerProfilePermissionError(error) {
  const code = String(error?.code || error?.status || "").trim().toUpperCase();
  const message = String(error?.message || error || "").toLowerCase();
  return code === "403"
    || code === "42501"
    || message.includes("sem permiss")
    || message.includes("permission denied")
    || message.includes("not authorized")
    || message.includes("unauthorized")
    || message.includes("forbidden");
}

function getServerSettingsActiveServerId() {
  const candidates = [
    typeof serverSettingsServerId !== "undefined" ? serverSettingsServerId : null,
    typeof getActiveServerContext === "function" ? getActiveServerContext()?.serverId : null,
    state?.activeDm?.serverId,
    state?.activeDm?.server_id,
    typeof getActiveServerIdForSidebar === "function" ? getActiveServerIdForSidebar() : null,
    typeof getActiveServerId === "function" ? getActiveServerId() : null,
    typeof activeServer !== "undefined" ? activeServer?.id : null,
    typeof currentServer !== "undefined" ? currentServer?.id : null,
    typeof selectedServer !== "undefined" ? selectedServer?.id : null,
    state?.activeServerId,
    state?.currentServerId,
    state?.selectedServerId,
  ];
  const found = candidates.find((value) => value !== null && value !== undefined && String(value).trim() !== "");
  return found ? normId(found) : "";
}

async function debugReadServerProfileRow(serverId) {
  const sid = normId(serverId || "");
  if (!sid) return { data: null, error: { message: "server_id invalido" } };
  const { data, error } = await supabase
    .from("servers")
    .select("*")
    .eq("id", sid)
    .maybeSingle();
  return { data, error };
}

async function updateServerProfileDirectForManageServer(serverId, { name = "", iconUrl = "", bannerUrl = "", bannerTouched = false } = {}, { capabilityState = null, rpcError = null } = {}) {
  const sid = normId(serverId);
  if (!sid) return { data: null, error: { message: "server_id invalido" }, method: "direct" };
  const payload = {
    name: normalizeConversationLabel(String(name || "").trim(), "Server"),
    icon_url: sanitizeServerIconUrl(iconUrl || "") || null,
  };
  if (bannerTouched) payload.banner_url = normalizeBannerUrl(bannerUrl || "") || null;

  console.info("[server-settings] direct server profile update payload", {
    serverId: sid,
    userId: normId(state.user?.id || ""),
    updatePayload: payload,
    capabilityState,
  });

  // SECURITY TODO: enforce manage_server role permission checks server-side via validated RPC/RLS before production.
  const { data, error } = await supabase
    .from("servers")
    .update(payload)
    .eq("id", sid)
    .select(bannerTouched ? "id, name, icon_url, banner_url" : "id, name, icon_url")
    .maybeSingle();

  if (error) {
    console.error("[server-settings] direct server profile update failed", {
      serverId: sid,
      userId: normId(state.user?.id || ""),
      canManageServer: capabilityState?.canManageServer,
      capabilityState,
      rpcError,
      payload,
      message: error?.message,
      details: error?.details,
      hint: error?.hint,
      code: error?.code,
      error,
    });
    return { data: null, error, method: "direct" };
  }

  if (!data) {
    const readback = await debugReadServerProfileRow(sid).catch((readError) => ({ data: null, error: readError }));
    const noRowsError = {
      message: readback?.data ? "server_profile_update_blocked_by_rls" : "server_profile_row_not_visible_or_missing",
    };
    console.error("[server-settings] direct server profile update affected no rows", {
      serverId: sid,
      userId: normId(state.user?.id || ""),
      canManageServer: capabilityState?.canManageServer,
      capabilityState,
      rpcError,
      payload,
      readback,
    });
    return { data: null, error: noRowsError, method: "direct", readback };
  }

  return { data, error: null, method: "direct" };
}

