function unwrapServerChannelRpcData(data = null) {
  if (Array.isArray(data)) return data[0] || null;
  if (data && typeof data === "object" && data.row && typeof data.row === "object") return data.row;
  return data && typeof data === "object" ? data : null;
}

function getSafeServerChannelMutationResponse(result = null) {
  const data = unwrapServerChannelRpcData(result?.data);
  return {
    ok: !result?.error,
    data: data ? {
      ok: data?.ok === true,
      channelId: normId(data?.channelId || data?.channel_id || data?.id || ""),
      conversationId: normId(data?.conversationId || data?.conversation_id || ""),
    } : null,
    error: getSafeServerChannelRpcErrorDebug(result?.error),
  };
}

function getSafeServerChannelRpcErrorDebug(error = null) {
  if (!error) return null;
  return {
    code: String(error?.code || ""),
    message: String(error?.message || ""),
    details: String(error?.details || ""),
    hint: String(error?.hint || ""),
  };
}


