function isMissingTableError(error, tableName = "") {
  const code = String(error?.code || "").trim().toUpperCase();
  const msg = String(error?.message || "").toLowerCase();
  const details = String(error?.details || "").toLowerCase();
  const hint = String(error?.hint || "").toLowerCase();
  if (code === "42P01") {
    if (!tableName) return true;
    return msg.includes(String(tableName || "").toLowerCase());
  }
  if (code === "PGRST205") {
    if (!tableName) return true;
    const name = String(tableName || "").toLowerCase();
    return msg.includes(name) || details.includes(name) || hint.includes(name) || msg.includes("schema cache");
  }
  if (!tableName) {
    return (msg.includes("relation") && msg.includes("does not exist"))
      || msg.includes("schema cache");
  }
  const name = String(tableName || "").toLowerCase();
  return (
    (msg.includes(name) && msg.includes("does not exist"))
    || (msg.includes(name) && msg.includes("schema cache"))
    || (details.includes(name) && details.includes("schema cache"))
    || (hint.includes(name) && hint.includes("schema cache"))
    || (msg.includes("could not find the table") && msg.includes(name))
  );
}

function isAmbiguousColumnError(error, columnName = "") {
  const code = String(error?.code || "").trim().toUpperCase();
  const msg = String(error?.message || "").toLowerCase();
  if (code !== "42702" && code !== "42P09" && !msg.includes("ambiguous")) return false;
  if (!columnName) return true;
  const col = String(columnName || "").trim().toLowerCase();
  return !col || msg.includes(`"${col}"`) || msg.includes(` ${col} `) || msg.includes(col);
}

function isMissingColumnError(error, columnName = "") {
  const code = String(error?.code || "").trim().toUpperCase();
  const msg = String(error?.message || "").toLowerCase();
  if (code !== "42703" && !msg.includes("column")) return false;
  if (!columnName) return true;
  const col = String(columnName || "").trim().toLowerCase();
  return !col || msg.includes(col);
}

function normalizeServerMemberRoleValue(role = "") {
  const raw = String(role || "").trim().toLowerCase();
  if (raw === "owner" || raw === "admin") return raw;
  return "member";
}

function getServerMemberModerationRank(role = "") {
  const normalized = normalizeServerMemberRoleValue(role);
  if (normalized === "owner") return 3;
  if (normalized === "admin") return 2;
  return 1;
}

function getServerMemberRoleFromCache(serverId, userId, { members = null } = {}) {
  const sid = normId(serverId);
  const uid = normId(userId);
  if (!sid || !uid) return "member";
  const rows = Array.isArray(members) ? members : (serverMemberListByServerId.get(sid) || []);
  const memberRow = (rows || []).find((row) => normId(row?.userId || "") === uid) || null;
  if (memberRow) return normalizeServerMemberRoleValue(memberRow?.role || "member");
  const serverRow = getServerRowById(sid);
  const ownerId = normId(serverRow?.ownerUserId || "");
  if (ownerId && ownerId === uid) return "owner";
  return "member";
}

function canServerMemberModerateTarget(serverId, actorUserId, targetUserId, { members = null } = {}) {
  const sid = normId(serverId);
  const actorId = normId(actorUserId);
  const targetId = normId(targetUserId);
  if (!sid || !actorId || !targetId) return false;
  if (actorId === targetId) return false;

  const actorRole = getServerMemberRoleFromCache(sid, actorId, { members });
  const targetRole = getServerMemberRoleFromCache(sid, targetId, { members });
  const actorRank = getServerMemberModerationRank(actorRole);
  const targetRank = getServerMemberModerationRank(targetRole);
  if (actorRank < 2) return false;
  if (actorRole === "admin" && targetRank >= actorRank) return false;
  if (actorRole === "owner" && targetRole === "owner") return false;
  return true;
}

function resolveServerVoiceServerIdByConversation(conversationId = null) {
  const convId = normId(conversationId || callConversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return "";
  const meta = getActiveConversationMeta(convId) || getConversationMeta(convId) || {};
  const directServerId = normId(meta?.serverId || state.activeDm?.serverId || "");
  if (directServerId) return directServerId;
  const channelCtx = findServerChannelContextByConversationId(convId) || {};
  return normId(channelCtx?.serverId || "");
}

function resolveServerVoiceMemberDisplayName(conversationId, userId, fallback = "member") {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  if (!uid) return normalizeConversationLabel(fallback || "member", "member");
  const sid = resolveServerVoiceServerIdByConversation(convId);
  const members = sid ? (serverMemberListByServerId.get(sid) || []) : [];
  const memberRow = (members || []).find((row) => normId(row?.userId || "") === uid) || null;
  const presenceMeta = getServerVoicePresenceMemberMeta(convId, uid) || {};
  const identity = getGroupMemberIdentity(convId, uid) || {};
  return normalizeConversationLabel(
    resolveServerDisplayName(sid, uid, memberRow, "")
      || presenceMeta?.label
      || identity?.label
      || fallback
      || memberRow?.username
      || "member",
    "member"
  );
}

function resolveServerVoiceMenuConversationForMember(serverId = "", userId = "") {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  const members = sid ? (serverMemberListByServerId.get(sid) || []) : [];
  const isSameServerVoiceConv = (convId) => {
    const normalizedConvId = normId(convId || "");
    if (!normalizedConvId) return false;
    if (!isServerVoiceConversationById(normalizedConvId)) return false;
    const convServerId = normId(resolveServerVoiceServerIdByConversation(normalizedConvId));
    return !sid || (convServerId && convServerId === sid);
  };
  const memberIsActiveInConv = (convId) => {
    const normalizedConvId = normId(convId || "");
    if (!normalizedConvId || !uid) return false;
    return getServerVoiceChannelActiveMembers(normalizedConvId, members, {
      triggerReason: "resolve_server_voice_menu_conversation",
      callerFunction: "resolveServerVoiceMenuConversationForMember",
    })
      .some((member) => normId(member?.userId || "") === uid);
  };

  const primaryCandidates = normalizeUuidArray([
    callConversationId,
    activeDmId,
    state.activeDm?.conversationId,
  ]).filter(isSameServerVoiceConv);

  const activeCandidate = primaryCandidates.find(memberIsActiveInConv);
  if (activeCandidate) return activeCandidate;
  if (primaryCandidates.length) return primaryCandidates[0];

  const voiceChannels = (sid ? (serverChannelListByServerId.get(sid) || []) : [])
    .filter((ch) => normalizeConversationChannelType(ch?.channelType || "") === "voice")
    .map((ch) => normId(ch?.conversationId || ""))
    .filter(Boolean);
  const voiceCandidateWithTarget = voiceChannels.find(memberIsActiveInConv);
  if (voiceCandidateWithTarget) return voiceCandidateWithTarget;
  if (voiceChannels.length) return voiceChannels[0];

  return "";
}

function getServerVoiceMemberModerationContext({
  userId = "",
  conversationId = null,
  serverId = "",
  displayName = "",
} = {}) {
  const uid = normId(userId || "");
  const convId = normId(conversationId || callConversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!uid || !convId || !isServerVoiceConversationById(convId)) return null;
  const sid = normId(serverId || resolveServerVoiceServerIdByConversation(convId));
  if (!sid) return null;

  const meId = normId(state.user?.id || "");
  const members = serverMemberListByServerId.get(sid) || [];
  const roles = serverRoleListByServerId.get(sid) || [];
  const roleMemberMap = serverRoleMemberMapByServerId.get(sid) || new Map();
  const isSelf = !!(meId && uid === meId);
  const targetLabel = resolveServerVoiceMemberDisplayName(convId, uid, displayName || "member");
  const audioState = getParticipantAudioStateForUi(uid, convId) || {};
  const ability = canServerActorModerateTargetWithPermission({
    serverId: sid,
    actorUserId: meId,
    targetUserId: uid,
    members,
    roles,
    roleMemberMap,
  });
  const caps = getServerCapabilityMeta(sid);
  const actorIsOwner = !!(caps.isActualOwner || caps.isOwner);
  const actorFlags = actorIsOwner
    ? normalizeServerRolePermissions(SERVER_ROLE_PERMISSION_PRESETS.safe || {})
    : getEffectiveServerPermissionsForCurrentUser(sid);
  const canDisconnect = !!meId && !!(actorIsOwner || actorFlags.move_members || actorFlags.voice_disconnect_members);
  const canMuteMic = !!meId && !!(actorIsOwner || actorFlags.mute_members || actorFlags.voice_mute_microphone);
  const canDeafen = !!meId && !!(actorIsOwner || actorFlags.deafen_members || actorFlags.voice_deafen_members);
  const canKick = !!meId && !!(actorIsOwner || actorFlags.kick_members || actorFlags.server_kick_members);
  const canBan = !!meId && !!(actorIsOwner || actorFlags.ban_members || actorFlags.server_ban_members);
  const canTouchTarget = !!meId && (isSelf || canDisconnect || canMuteMic || canDeafen || canKick || canBan);
  const canModerate = canDisconnect || canMuteMic || canDeafen || canKick || canBan;

  return {
    serverId: sid,
    conversationId: convId,
    targetUserId: uid,
    targetDisplayName: targetLabel,
    targetRole: ability?.targetRole || "member",
    myRole: ability?.actorRole || "member",
    isSelf,
    canTouchTarget,
    canModerate: !!canModerate,
    canDisconnect,
    canMuteMic,
    canDeafen,
    canKick,
    canBan,
    micMuted: !!audioState.micMuted,
    serverMuted: !!audioState.serverMuted,
    deafened: !!audioState.deafened,
    selfDeafened: !!audioState.selfDeafened,
    serverDeafened: !!audioState.serverDeafened,
  };
}


let voiceModerationToastTimer = 0;

function showVoiceModerationToast(message = "", type = "success") {
  const text = String(message || "").trim();
  if (!text) return;
  let toast = document.getElementById("voiceModerationToast");
  if (!toast) {
    toast = document.createElement("div");
    toast.id = "voiceModerationToast";
    toast.className = "voice-moderation-toast";
    toast.setAttribute("role", "status");
    toast.setAttribute("aria-live", "polite");
    document.body.appendChild(toast);
  }
  toast.textContent = text;
  toast.className = "voice-moderation-toast is-visible " + (type === "error" ? "is-error" : "is-success");
  if (voiceModerationToastTimer) clearTimeout(voiceModerationToastTimer);
  voiceModerationToastTimer = setTimeout(() => {
    toast.classList.remove("is-visible");
    voiceModerationToastTimer = 0;
  }, type === "error" ? 2600 : 1800);
}

function notifyServerVoiceModerationUi(message = "", { error = false } = {}) {
  const text = String(message || "").trim();
  if (!text) return;
  try { showVoiceModerationToast(text, error ? "error" : "success"); } catch (_) {}
  try {
    if (typeof setCallStatus === "function") {
      setCallStatus(text, true);
      setTimeout(() => setCallStatus("", false), error ? 2600 : 1600);
      return;
    }
  } catch (_) {}
  try {
    if (typeof showDmComposerNotice === "function") {
      showDmComposerNotice(text, { title: "Voice" });
      return;
    }
  } catch (_) {}
  try { console[error ? "warn" : "info"]("[voice-moderation-ui]", text); } catch (_) {}
}

const VOICE_MODERATION_OPTIMISTIC_TTL_MS = 10000;
const voiceModerationOptimisticState = {
  actionsByTarget: new Map(),
  memberOverrides: new Map(),
  moveOverrides: new Map(),
};

function getVoiceModerationActionTargetKey(targetUserId = "", action = "") {
  return `${normId(targetUserId || "")}:${String(action || "").trim()}`;
}

function pruneVoiceModerationOptimisticState() {
  const now = Date.now();
  const expiredActions = [];
  voiceModerationOptimisticState.actionsByTarget.forEach((entry, key) => {
    if (!entry || now - Number(entry.startedAt || 0) > VOICE_MODERATION_OPTIMISTIC_TTL_MS) expiredActions.push(key);
  });
  expiredActions.forEach((key) => voiceModerationOptimisticState.actionsByTarget.delete(key));

  const expiredMembers = [];
  voiceModerationOptimisticState.memberOverrides.forEach((entry, key) => {
    if (!entry || now - Number(entry.updatedAt || 0) > VOICE_MODERATION_OPTIMISTIC_TTL_MS) expiredMembers.push(key);
  });
  expiredMembers.forEach((key) => voiceModerationOptimisticState.memberOverrides.delete(key));

  const expiredMoves = [];
  voiceModerationOptimisticState.moveOverrides.forEach((entry, key) => {
    if (!entry || now - Number(entry.updatedAt || 0) > VOICE_MODERATION_OPTIMISTIC_TTL_MS) expiredMoves.push(key);
  });
  expiredMoves.forEach((key) => voiceModerationOptimisticState.moveOverrides.delete(key));
  if (expiredActions.length || expiredMembers.length || expiredMoves.length) {
    try { console.warn("[voice-moderation] optimistic rollback", { reason: "timeout", expiredActions, expiredMembers, expiredMoves }); } catch (_) {}
  }
}

function getVoiceModerationMemberOverride(userId = "") {
  pruneVoiceModerationOptimisticState();
  return voiceModerationOptimisticState.memberOverrides.get(normId(userId || "")) || null;
}

function getVoiceModerationMoveOverride(userId = "") {
  pruneVoiceModerationOptimisticState();
  return voiceModerationOptimisticState.moveOverrides.get(normId(userId || "")) || null;
}

function handleCurrentUserOptimisticVoiceMove({ targetChannelId = "" } = {}) {
  const channelId = normId(targetChannelId || "");
  const meId = normId(state.user?.id || "");
  if (!channelId || !meId) return;
  const targetCtx = findServerChannelContextByChannelId(channelId) || null;
  const targetConvId = normId(targetCtx?.channel?.conversationId || targetCtx?.channel?.conversation_id || "");
  if (!targetConvId || !isServerVoiceConversationById(targetConvId)) return;
  try {
    callConversationId = targetConvId;
    if (isServerVoiceConversationById(activeDmId || "")) activeDmId = targetConvId;
    if (state.activeDm && isServerVoiceConversationById(state.activeDm.conversationId || "")) {
      state.activeDm = {
        ...state.activeDm,
        conversationId: targetConvId,
        serverId: targetCtx.serverId || state.activeDm.serverId,
        channelId,
        displayName: targetCtx.channel?.name || state.activeDm.displayName,
      };
    }
    console.info("[voice-drag] current user optimistic voice channel", {
      targetChannelId: channelId,
      targetConversationId: targetConvId,
      targetChannelName: targetCtx.channel?.name || "",
    });
  } catch (error) {
    console.warn("[voice-drag] failed to update current user optimistic voice channel", {
      targetChannelId: channelId,
      message: error?.message,
      error,
    });
  }
}

function applyImmediateVoiceModerationDomPatch(targetUserId = "", statePatch = {}) {
  const uid = normId(targetUserId || "");
  if (!uid || typeof document === "undefined") return;
  const hasServerMuted = Object.prototype.hasOwnProperty.call(statePatch || {}, "serverMuted");
  const hasServerDeafened = Object.prototype.hasOwnProperty.call(statePatch || {}, "serverDeafened");
  const pending = !!(statePatch?.pendingMute || statePatch?.pendingDeafen || statePatch?.pendingMove);
  document.querySelectorAll("[data-voice-member-user-id]").forEach((el) => {
    if (normId(el?.getAttribute?.("data-voice-member-user-id") || "") !== uid) return;
    if (hasServerMuted) el.classList.toggle("is-server-muted", statePatch.serverMuted === true);
    if (hasServerDeafened) el.classList.toggle("is-server-deafened", statePatch.serverDeafened === true);
    el.classList.toggle("is-moderation-pending", pending);
    el.classList.toggle("is-voice-action-pending", pending);
  });
}
function refreshVoiceModerationOptimisticUi() {
  try { refreshServerVoiceChannelBadges(); } catch (_) {}
  try { refreshCallUI(); } catch (_) {}
  try {
    if (serverVoiceMemberMenuTarget) {
      const menu = document.getElementById("serverVoiceMemberMenu");
      if (menu && menu.classList.contains("is-open")) {
        const nextContext = getServerVoiceMemberModerationContext({
          userId: serverVoiceMemberMenuTarget.targetUserId,
          conversationId: serverVoiceMemberMenuTarget.conversationId,
          serverId: serverVoiceMemberMenuTarget.serverId,
          displayName: serverVoiceMemberMenuTarget.targetDisplayName,
        });
        if (nextContext) {
          nextContext.anchorEl = serverVoiceMemberMenuTarget.anchorEl || null;
          serverVoiceMemberMenuTarget = nextContext;
          menu.innerHTML = buildVoiceMemberContextMenuHtml(nextContext);
        }
      }
    }
  } catch (_) {}
}

function buildVoiceModerationOptimisticSnapshot({ action = "", targetUserId = "", targetChannelId = "", channelId = "", conversationId = "", source = "" } = {}) {
  const targetId = normId(targetUserId || "");
  const destinationId = normId(targetChannelId || "");
  if (!targetId) return null;
  const actionKey = getVoiceModerationActionTargetKey(targetId, action);
  return {
    member: voiceModerationOptimisticState.memberOverrides.has(targetId)
      ? { ...voiceModerationOptimisticState.memberOverrides.get(targetId) }
      : null,
    move: voiceModerationOptimisticState.moveOverrides.has(targetId)
      ? { ...voiceModerationOptimisticState.moveOverrides.get(targetId) }
      : null,
    actionKey,
    action: voiceModerationOptimisticState.actionsByTarget.has(actionKey)
      ? { ...voiceModerationOptimisticState.actionsByTarget.get(actionKey) }
      : null,
    targetUserId: targetId,
    targetChannelId: destinationId,
    channelId: normId(channelId || findServerChannelContextByConversationId(conversationId)?.channel?.id || ""),
    source,
  };
}

function applyVoiceModerationOptimisticAction(details = {}) {
  const action = String(details?.action || "").trim();
  const targetId = normId(details?.targetUserId || "");
  if (!action || !targetId) return null;
  pruneVoiceModerationOptimisticState();
  const now = Date.now();
  const previousState = buildVoiceModerationOptimisticSnapshot(details);
  voiceModerationOptimisticState.actionsByTarget.set(getVoiceModerationActionTargetKey(targetId, action), {
    action,
    targetUserId: targetId,
    targetChannelId: normId(details?.targetChannelId || "") || null,
    startedAt: now,
    source: String(details?.source || "").trim(),
  });

  if (["mute_member", "unmute_member", "deafen_member", "undeafen_member"].includes(action)) {
    const current = voiceModerationOptimisticState.memberOverrides.get(targetId) || {};
    const next = { ...current, updatedAt: now };
    if (action === "mute_member" || action === "unmute_member") {
      next.serverMuted = action === "mute_member";
      next.pendingMute = true;
    }
    if (action === "deafen_member" || action === "undeafen_member") {
      next.serverDeafened = action === "deafen_member";
      next.pendingDeafen = true;
    }
    voiceModerationOptimisticState.memberOverrides.set(targetId, next);
    applyImmediateVoiceModerationDomPatch(targetId, next);
  }

  if (action === "move_member") {
    const toChannelId = normId(details?.targetChannelId || "");
    if (toChannelId) {
      const fromChannelId = normId(details?.channelId || findServerChannelContextByConversationId(details?.conversationId || "")?.channel?.id || "");
      voiceModerationOptimisticState.moveOverrides.set(targetId, {
        fromChannelId,
        toChannelId,
        pendingMove: false,
        updatedAt: now,
      });
      console.info("[voice-drag] optimistic move apply", {
        targetUserId: targetId,
        fromChannelId,
        toChannelId,
      });
      if (targetId === normId(state.user?.id || "")) {
        handleCurrentUserOptimisticVoiceMove({ targetChannelId: toChannelId });
      }
      applyImmediateVoiceModerationDomPatch(targetId, { pendingMove: false });
    }
  }

  const nextState = buildVoiceModerationOptimisticSnapshot(details);
  console.info("[voice-moderation] optimistic apply", {
    action,
    targetUserId: targetId,
    targetChannelId: normId(details?.targetChannelId || "") || null,
    previousState,
    nextState,
  });
  refreshVoiceModerationOptimisticUi();
  return previousState;
}

function confirmVoiceModerationOptimisticAction(details = {}) {
  const action = String(details?.action || "").trim();
  const targetId = normId(details?.targetUserId || "");
  if (!targetId) return;
  if (action) voiceModerationOptimisticState.actionsByTarget.delete(getVoiceModerationActionTargetKey(targetId, action));
  const member = voiceModerationOptimisticState.memberOverrides.get(targetId);
  if (member) {
    const next = { ...member, updatedAt: Date.now() };
    if (action === "mute_member" || action === "unmute_member") next.pendingMute = false;
    if (action === "deafen_member" || action === "undeafen_member") next.pendingDeafen = false;
    voiceModerationOptimisticState.memberOverrides.set(targetId, next);
  }
  const move = voiceModerationOptimisticState.moveOverrides.get(targetId);
  if (action === "move_member" && move) {
    voiceModerationOptimisticState.moveOverrides.set(targetId, { ...move, pendingMove: false, updatedAt: Date.now() });
    console.info("[voice-drag] optimistic move confirmed", {
      targetUserId: targetId,
      fromChannelId: move.fromChannelId || "",
      toChannelId: move.toChannelId || normId(details?.targetChannelId || ""),
    });
  }
  console.info("[voice-moderation] optimistic confirmed", {
    action,
    targetUserId: targetId,
    targetChannelId: normId(details?.targetChannelId || "") || null,
  });
  refreshVoiceModerationOptimisticUi();
}

function rollbackVoiceModerationOptimisticAction(details = {}, snapshot = null, reason = "failed") {
  const action = String(details?.action || "").trim();
  const targetId = normId(details?.targetUserId || "");
  if (!targetId) return;
  if (action) voiceModerationOptimisticState.actionsByTarget.delete(getVoiceModerationActionTargetKey(targetId, action));
  if (snapshot?.member) voiceModerationOptimisticState.memberOverrides.set(targetId, snapshot.member);
  else voiceModerationOptimisticState.memberOverrides.delete(targetId);
  if (snapshot?.move) voiceModerationOptimisticState.moveOverrides.set(targetId, snapshot.move);
  else voiceModerationOptimisticState.moveOverrides.delete(targetId);
  console.warn("[voice-moderation] optimistic rollback", {
    action,
    targetUserId: targetId,
    targetChannelId: normId(details?.targetChannelId || "") || null,
    reason,
  });
  if (action === "move_member") {
    console.warn("[voice-drag] optimistic move rollback", {
      targetUserId: targetId,
      targetChannelId: normId(details?.targetChannelId || "") || null,
      reason,
    });
  }
  refreshVoiceModerationOptimisticUi();
}

function getCurrentUserVisibleVoiceChannelId() {
  const meId = normId(state.user?.id || "");
  if (!meId || typeof document === "undefined") return "";
  const row = Array.from(document.querySelectorAll(".server-voice-member-row[data-voice-member-user-id]"))
    .find((el) => normId(el.getAttribute("data-voice-member-user-id") || "") === meId) || null;
  return resolveVoiceMemberSourceChannelId(row);
}

function ensureServerVoiceStageEmptyState({
  stageViewport = null,
  show = false,
  channelName = "",
  participantCount = 0,
  currentUserChannelName = "",
} = {}) {
  if (!stageViewport || typeof document === "undefined") return;
  let empty = stageViewport.querySelector(".server-voice-stage-empty");
  if (!show) {
    if (empty) empty.remove();
    stageViewport.classList.remove("has-server-voice-empty-state");
    return;
  }
  if (!empty) {
    empty = document.createElement("div");
    empty.className = "server-voice-stage-empty serverVoiceStageEmpty";
    empty.innerHTML = [
      '<div class="serverVoiceStageEmpty__inner">',
      '<div class="serverVoiceStageEmptyIcon" aria-hidden="true">🎧</div>',
      '<div class="serverVoiceStageEmptyTitle"></div>',
      '<div class="serverVoiceStageEmptyText"></div>',
      '<div class="serverVoiceStageEmptyMeta"></div>',
      '<div class="serverVoiceStageEmptyHint"></div>',
      '</div>',
    ].join("");
    stageViewport.appendChild(empty);
  }
  const title = empty.querySelector(".serverVoiceStageEmptyTitle");
  const text = empty.querySelector(".serverVoiceStageEmptyText");
  const meta = empty.querySelector(".serverVoiceStageEmptyMeta");
  const hint = empty.querySelector(".serverVoiceStageEmptyHint");
  const safeChannelName = String(channelName || "Voice channel").trim() || "Voice channel";
  if (title) title.textContent = "Ninguém nesta chamada";
  if (text) text.textContent = `${safeChannelName} está vazio.`;
  if (meta) meta.textContent = `${Number(participantCount || 0)} participantes`;
  if (hint) hint.textContent = currentUserChannelName
    ? `Estás em ${currentUserChannelName}.`
    : "Quando alguém entrar, o palco aparece aqui.";
  stageViewport.classList.add("has-server-voice-empty-state");
}

function getVoiceModerationSuccessMessage({ action = "", targetName = "", targetChannelName = "" } = {}) {
  const name = String(targetName || "Member").trim() || "Member";
  const channel = String(targetChannelName || "voice channel").trim() || "voice channel";
  if (action === "mute_member") return `Muted ${name}.`;
  if (action === "unmute_member") return `Unmuted ${name}.`;
  if (action === "deafen_member") return `Deafened ${name}.`;
  if (action === "undeafen_member") return `Undeafened ${name}.`;
  if (action === "move_member") return `Moved ${name} to ${channel}.`;
  return "Voice moderation updated.";
}

function getServerVoiceActionErrorMessage(payload = null, fallback = "Could not complete that voice action.") {
  const source = payload && typeof payload === "object" ? payload : {};
  const code = String(source.error || source.code || source.message || "").trim();
  const detailMessage = String(source.message || source.details?.message || "").trim();
  if (
    /livekitParticipantLookupError/i.test(code)
    || /livekitParticipantLookupError/i.test(detailMessage)
  ) {
    return "Could not confirm voice move.";
  }
  if (code === "missing_move_members") return "You need Move Members to move other members.";
  if (code === "missing_mute_members") return "You need Mute Members to mute other members.";
  if (code === "missing_deafen_members") return "You need Deafen Members to deafen other members.";
  if (code === "target_role_too_high_for_actor") return "You can't moderate members with an equal or higher role.";
  if (code === "target_role_too_high") return "The bot role must be above the target member's highest role.";
  if (code === "bot_role_missing_permission") return "The bot role must be above the target member's highest role and include the needed voice permission.";
  if (code === "bot_permission_required" || code === "missing_permission") return detailMessage || "This bot needs a permission update to use this feature.";
  if (code === "bot_not_installed") return "A voice bot must be installed before voice moderation can run.";
  if (code === "cannot_moderate_owner" || code === "target_protected") return "You can't moderate the server owner.";
  if (code === "actor_permission_lookup_failed" || code === "actor_role_hierarchy_lookup_failed") return "Could not verify your voice moderation permissions.";
  if (code === "livekit_move_participant_unavailable") return "Instant voice move requires LiveKit MoveParticipant.";
  if (code === "livekit_move_participant_failed") return "LiveKit could not move that participant.";
  return detailMessage || (code ? code.replace(/_/g, " ") : fallback);
}

async function performServerVoiceModerationAction({
  action = "",
  serverId = "",
  conversationId = "",
  channelId = "",
  targetUserId = "",
  targetChannelId = "",
  targetChannelName = "",
  source = "frontend_voice_member_ui",
  moveId = "",
} = {}) {
  const canonicalAction = String(action || "").trim();
  const sid = normId(serverId || resolveServerVoiceServerIdByConversation(conversationId));
  const convId = normId(conversationId || "");
  const sourceChannelId = normId(channelId || findServerChannelContextByConversationId(convId)?.channel?.id || "");
  const targetId = normId(targetUserId || "");
  const destinationId = normId(targetChannelId || "");
  const requesterUserId = normId(state.user?.id || "");
  if (!canonicalAction || !sid || !targetId || !requesterUserId) throw new Error("voice_moderation_invalid_context");

  const edgeFunctionName = "altara-bot-voice-actions";
  const functionPath = `/functions/v1/${edgeFunctionName}`;

  console.info("[voice-moderation] action start", {
    action: canonicalAction,
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId || null,
    source: String(source || "frontend_voice_member_ui"),
  });

  const optimisticDetails = {
    action: canonicalAction,
    serverId: sid,
    conversationId: convId,
    channelId: sourceChannelId,
    targetUserId: targetId,
    targetChannelId: destinationId,
    source: String(source || "frontend_voice_member_ui"),
  };
  const optimisticSnapshot = applyVoiceModerationOptimisticAction(optimisticDetails);

  const authReady = await ensureSupabaseFunctionInvokeAuthReady({
    edgeFunctionName,
    functionPath,
    requireUser: true,
    logPrefix: "[voice moderation auth]",
    logEvent: "voice_moderation.auth_state",
    logChannel: "voice-moderation",
    failEvent: "voice_moderation.auth_missing",
  });
  if (!authReady.ok) {
    rollbackVoiceModerationOptimisticAction(optimisticDetails, optimisticSnapshot, "voice_moderation_auth_missing");
    throw authReady.error || new Error("voice_moderation_auth_missing");
  }

  const body = {
    action: canonicalAction,
    serverId: sid,
    channelId: sourceChannelId || undefined,
    conversationId: convId || undefined,
    mode: isServerVoiceV2Enabled() ? "server_room_v2" : undefined,
    voiceMode: isServerVoiceV2Enabled() ? "server_room_v2" : undefined,
    requesterUserId,
    targetUserId: targetId,
    targetChannelId: destinationId || undefined,
    targetChannelName: String(targetChannelName || "").trim() || undefined,
    source: String(source || "frontend_voice_member_ui"),
    moveId: String(moveId || "").trim() || undefined,
  };
  const { data, error } = await supabase.functions.invoke(edgeFunctionName, { body });
  const errorPayload = error ? await readSupabaseFunctionErrorPayload(error) : null;
  const payload = data && typeof data === "object" ? data : (errorPayload || {});
  if (error || payload?.ok === false) {
    const err = new Error(getServerVoiceActionErrorMessage(errorPayload || payload, "Could not complete that voice action."));
    err.details = errorPayload || payload || null;
    err.status = Number(error?.status || payload?.status || payload?.http_status || 0) || null;
    console.error("[voice-moderation] action failed", {
      action: canonicalAction,
      serverId: sid,
      targetUserId: targetId,
      targetChannelId: destinationId || null,
      message: err.message,
      details: err.details,
      code: payload?.error || errorPayload?.error || null,
      error,
    });
    rollbackVoiceModerationOptimisticAction(optimisticDetails, optimisticSnapshot, err.message || "failed");
    throw err;
  }
  console.info("[voice-moderation] action success", {
    action: canonicalAction,
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId || null,
    payload,
  });
  confirmVoiceModerationOptimisticAction(optimisticDetails);
  try {
    window.altaraDebugVoiceModeration = window.altaraDebugVoiceModeration || {};
    window.altaraDebugVoiceModeration.lastAction = { action: canonicalAction, serverId: sid, targetUserId: targetId, targetChannelId: destinationId || null, payload, at: Date.now() };
  } catch (_) {}
  return payload;
}

function getServerVoiceChannelsForMenu(serverId = "") {
  const sid = normId(serverId || "");
  return (sid ? (serverChannelListByServerId.get(sid) || []) : [])
    .filter((channel) => normalizeConversationChannelType(channel?.channelType || "") === "voice")
    .map((channel) => ({
      id: normId(channel?.id || channel?.channelId || ""),
      conversationId: normId(channel?.conversationId || ""),
      name: String(channel?.name || channel?.label || "Voice").trim() || "Voice",
    }))
    .filter((channel) => channel.id);
}

function ensureServerVoiceMemberMenuElement() {
  let menu = document.getElementById("serverVoiceMemberMenu");
  if (menu) return menu;
  menu = document.createElement("div");
  menu.id = "serverVoiceMemberMenu";
  menu.className = "msgMenu serverVoiceMemberMenu msgMenu--server-voice hidden";
  menu.hidden = true;
  menu.setAttribute("aria-hidden", "true");
  document.body.appendChild(menu);
  return menu;
}

function insertVoiceMemberMentionIntoComposer(label = "") {
  const input = document.getElementById("dmInput");
  if (!input) return false;
  const name = String(label || "member").trim().replace(/\s+/g, " ") || "member";
  const mention = `@${name}`;
  const value = String(input.value || "");
  const start = Number.isFinite(input.selectionStart) ? input.selectionStart : value.length;
  const end = Number.isFinite(input.selectionEnd) ? input.selectionEnd : start;
  const needsLeadingSpace = start > 0 && !/\s/.test(value.charAt(start - 1));
  const needsTrailingSpace = end < value.length && !/\s/.test(value.charAt(end));
  const insert = `${needsLeadingSpace ? " " : ""}${mention}${needsTrailingSpace ? " " : ""}`;
  if (typeof input.setRangeText === "function") input.setRangeText(insert, start, end, "end");
  else input.value = `${value.slice(0, start)}${insert}${value.slice(end)}`;
  input.dispatchEvent(new Event("input", { bubbles: true }));
  try { input.focus({ preventScroll: true }); } catch (_) { try { input.focus(); } catch (_) {} }
  if (typeof updateDmComposerPreview === "function") updateDmComposerPreview();
  return true;
}

function buildVoiceMemberContextMenuHtml(context = {}) {
  const label = String(context?.targetDisplayName || "Member").trim() || "Member";
  const isSelf = context?.isSelf === true;
  const channels = getServerVoiceChannelsForMenu(context?.serverId || "");
  const currentChannelId = normId(findServerChannelContextByConversationId(context?.conversationId || "")?.channel?.id || "");
  const pendingMute = context?.pendingMute === true;
  const pendingDeafen = context?.pendingDeafen === true;
  const actionToEdgeAction = (action) => action === "mute" ? "mute_member"
    : action === "unmute" ? "unmute_member"
      : action === "deafen" ? "deafen_member"
        : action === "undeafen" ? "undeafen_member"
          : action === "move_to" ? "move_member"
            : "";
  const item = (action, text, { disabled = false, hint = "", danger = false, right = "", pending = false } = {}) => {
    const edgeAction = actionToEdgeAction(action);
    const isDisabled = disabled || pending;
    return `
    <button class="msgMenu__item${danger ? " msgMenu__item--danger" : ""}${isDisabled ? " is-disabled" : ""}${pending ? " is-pending" : ""}" type="button" data-voice-member-menu-act="${escAttr(action)}"${edgeAction ? ` data-voice-action="${escAttr(edgeAction)}"` : ""} ${isDisabled ? "disabled" : ""} title="${escAttr(hint || text)}">
      <span class="msgMenu__itemMain"><span>${esc(text)}</span>${hint ? `<span class="msgMenu__itemHint">${esc(hint)}</span>` : ""}</span>${right || ""}
    </button>`;
  };
  const moveRows = channels.length
    ? channels.map((channel) => item("move_to", channel.name, {
        disabled: channel.id === currentChannelId,
        hint: channel.id === currentChannelId ? "Already there" : (!context?.canDisconnect ? "Requires Move Members" : ""),
        right: channel.id === currentChannelId ? '<span class="serverVoiceMemberMenu__state is-on">HERE</span>' : "",
      }).replace('data-voice-member-menu-act="move_to"', `data-voice-member-menu-act="move_to" data-voice-member-target-channel-id="${escAttr(channel.id)}" data-voice-member-target-channel-name="${escAttr(channel.name)}"`))
    : ['<div class="msgMenu__meta">No voice channels.</div>'];
  return `
    <div class="msgMenu__meta">${esc(label)}</div>
    <div class="msgMenu__divider"></div>
    ${item("profile", "Profile")}
    ${item("mention", "Mention")}
    <div class="msgMenu__divider"></div>
    ${item(context?.serverMuted ? "unmute" : "mute", context?.serverMuted ? "Server Unmute" : "Server Mute", {
      disabled: false,
      pending: pendingMute,
      hint: pendingMute ? "Working" : (!context?.canMuteMic ? "Requires Mute Members" : ""),
      danger: !context?.serverMuted,
      right: `<span class="serverVoiceMemberMenu__state ${pendingMute ? "is-pending" : (context?.serverMuted ? "is-on" : "is-off")}">${pendingMute ? "..." : (context?.serverMuted ? "ON" : "OFF")}</span>`,
    })}
    ${item(context?.serverDeafened ? "undeafen" : "deafen", context?.serverDeafened ? "Server Undeafen" : "Server Deafen", {
      disabled: false,
      pending: pendingDeafen,
      hint: pendingDeafen ? "Working" : (!context?.canDeafen ? "Requires Deafen Members" : ""),
      danger: !context?.serverDeafened,
      right: `<span class="serverVoiceMemberMenu__state ${pendingDeafen ? "is-pending" : (context?.serverDeafened ? "is-on" : "is-off")}">${pendingDeafen ? "..." : (context?.serverDeafened ? "ON" : "OFF")}</span>`,
    })}
    <div class="msgMenu__divider"></div>
    ${item("roles", "Roles", { disabled: true, hint: activeServerCapabilityState?.canManageRoles ? "Role assignment UI is coming next." : "Requires Manage Roles" })}
    <div class="msgMenu__meta">Move to</div>
    ${moveRows.join("")}
    <div class="msgMenu__divider"></div>
    ${item("copy_user_id", "Copy User ID", { right: '<span class="msgMenu__kbd">ID</span>' })}
  `;
}

function bindServerVoiceMemberMenuOnce(menu) {
  if (!menu || serverVoiceMemberMenuBound) return;
  serverVoiceMemberMenuBound = true;
  menu.addEventListener("mouseenter", () => { serverVoiceMemberMenuHovering = true; });
  menu.addEventListener("mouseleave", () => { serverVoiceMemberMenuHovering = false; });
  menu.addEventListener("pointerdown", (event) => {
    event.stopPropagation();
  });
  menu.addEventListener("click", async (event) => {
    const target = eventTargetElement(event);
    const button = target?.closest?.("[data-voice-member-menu-act], [data-voice-action]");
    if (!button || button.disabled) return;
    event.preventDefault();
    event.stopPropagation();
    const action = String(button.getAttribute("data-voice-member-menu-act") || "").trim();
    const context = serverVoiceMemberMenuTarget || null;
    if (!context) return;
    try {
      if (action === "profile") {
        closeDmListMenus("voice_profile");
        await openCallParticipantProfilePreview(context.targetUserId, context.anchorEl || menu, {
          display_name: context.targetDisplayName,
        }, { conversationId: context.conversationId, serverId: context.serverId, kind: "server" });
        return;
      }
      if (action === "mention") {
        insertVoiceMemberMentionIntoComposer(context.targetDisplayName);
        closeDmListMenus("voice_mention");
        return;
      }
      if (action === "copy_user_id") {
        await copyTextWithPromptFallback(context.targetUserId, "User ID");
        notifyServerVoiceModerationUi("User ID copied.");
        closeDmListMenus("voice_copy");
        return;
      }
      if (action === "roles") return;
      serverVoiceMemberMenuBusy = true;
      const targetChannelId = normId(button.getAttribute("data-voice-member-target-channel-id") || button.getAttribute("data-target-channel-id") || "");
      const targetChannelName = String(button.getAttribute("data-voice-member-target-channel-name") || "").trim();
      const edgeAction = String(button.getAttribute("data-voice-action") || "").trim() || (action === "mute" ? "mute_member"
        : action === "unmute" ? "unmute_member"
          : action === "deafen" ? "deafen_member"
            : action === "undeafen" ? "undeafen_member"
              : action === "move_to" ? "move_member"
                : "");
      if (!edgeAction) return;
      console.info("[voice-moderation] context menu action clicked", {
        action: edgeAction,
        targetUserId: context.targetUserId,
        targetChannelId: targetChannelId || null,
      });
      await performServerVoiceModerationAction({
        action: edgeAction,
        serverId: context.serverId,
        conversationId: context.conversationId,
        targetUserId: context.targetUserId,
        targetChannelId,
        targetChannelName,
        source: "menu",
      });
      notifyServerVoiceModerationUi(getVoiceModerationSuccessMessage({ action: edgeAction, targetName: context.targetDisplayName, targetChannelName }));
      closeDmListMenus("voice_action");
      refreshServerVoiceChannelBadges();
      refreshCallUI();
    } catch (error) {
      notifyServerVoiceModerationUi(error?.message || "Could not complete that voice action.", { error: true });
    } finally {
      serverVoiceMemberMenuBusy = false;
    }
  });
  document.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    if (!target || !menu.classList.contains("is-open")) return;
    if (target.closest?.("#serverVoiceMemberMenu")) return;
    closeServerVoiceMemberMenu({ force: true, reason: "outside_click" });
  }, true);
  document.addEventListener("keydown", (event) => {
    if (String(event.key || "") === "Escape") closeServerVoiceMemberMenu({ force: true, reason: "escape" });
  });
}

function tryOpenServerVoiceMemberMenuAt(userId, conversationId, point = null, options = {}) {
  const uid = normId(userId || "");
  const convId = normId(conversationId || "");
  const sid = normId(options?.serverId || resolveServerVoiceServerIdByConversation(convId));
  if (!uid || !convId || !sid) return false;
  const context = getServerVoiceMemberModerationContext({
    userId: uid,
    conversationId: convId,
    serverId: sid,
    displayName: options?.displayName || "",
  });
  if (!context) return false;
  context.anchorEl = options?.anchorEl || null;
  const menu = ensureServerVoiceMemberMenuElement();
  bindServerVoiceMemberMenuOnce(menu);
  serverVoiceMemberMenuTarget = context;
  menu.className = `msgMenu serverVoiceMemberMenu msgMenu--server-voice${options?.asSubmenu ? " msgMenu--submenu" : ""}`;
  menu.dataset.targetUserId = context.targetUserId || "";
  menu.dataset.serverId = context.serverId || "";
  menu.dataset.conversationId = context.conversationId || "";
  menu.innerHTML = buildVoiceMemberContextMenuHtml(context);
  if (typeof bindStableAltaraContextMenu === "function") {
    bindStableAltaraContextMenu(menu, {
      type: "server_voice_member",
      close: (reason) => closeServerVoiceMemberMenu({ force: true, reason }),
      getAnchor: () => serverVoiceMemberMenuTarget?.anchorEl || null,
    });
  }
  menu.hidden = false;
  menu.classList.remove("hidden");
  menu.classList.add("is-open");
  menu.setAttribute("aria-hidden", "false");
  positionMenuAtPoint(menu, point || { x: 0, y: 0 }, { width: 286, minHeight: 240 });
  try { document.body?.classList?.add("server-voice-member-menu-open"); } catch (_) {}
  return true;
}

function isServerVoiceMemberInteractiveTarget(target = null) {
  return Boolean(target?.closest?.([
    "button",
    "input",
    "select",
    "textarea",
    "a",
    "label",
    "[contenteditable='true']",
    ".msgMenu",
    ".serverVoiceMemberMenu",
    ".voice-member-context-menu",
    "[role='menuitem']",
  ].join(",")));
}

function getServerVoiceMemberDragSourceFromTarget(target = null) {
  return target?.closest?.(
    ".server-voice-member-row[data-voice-member-user-id], .voice-participant-tile[data-voice-member-user-id]"
  ) || null;
}

function clearServerVoiceMemberDropTarget() {
  if (serverVoiceMemberDropTargetEl) {
    serverVoiceMemberDropTargetEl.classList.remove("is-voice-member-drop-target");
    serverVoiceMemberDropTargetEl = null;
  }
}

function setServerVoiceMemberDropTarget(targetEl = null) {
  if (targetEl === serverVoiceMemberDropTargetEl) return;
  clearServerVoiceMemberDropTarget();
  if (!targetEl) return;
  serverVoiceMemberDropTargetEl = targetEl;
  targetEl.classList.add("is-voice-member-drop-target");
}

function createVoiceMemberNativeDragImage(memberEl, payload = {}) {
  const ghost = document.createElement("div");
  ghost.className = "voice-member-drag-ghost";
  const avatar = memberEl?.querySelector?.("img, .serverVoiceMember__avatar, .serverVoiceMemberAvatar, .avatar, .userAvatar");
  if (avatar) {
    const clone = avatar.cloneNode(true);
    clone.classList?.add?.("voice-member-drag-ghost__avatar");
    ghost.appendChild(clone);
  }
  const label = document.createElement("span");
  label.className = "voice-member-drag-ghost__name";
  label.textContent = payload.memberName || "Member";
  ghost.appendChild(label);
  if ((payload.memberName || "").toLowerCase().includes("general")) {
    console.error("[voice-drag] WRONG SOURCE: member drag got channel name", payload);
  }
  ghost.style.position = "fixed";
  ghost.style.left = "-9999px";
  ghost.style.top = "-9999px";
  return ghost;
}

function eventHasVoiceMemberNativeDrag(event) {
  const types = Array.from(event?.dataTransfer?.types || []);
  return types.includes(ALTARA_VOICE_MEMBER_DRAG_MIME) || Boolean(activeVoiceMemberNativeDrag);
}

function getVoiceChannelNativeDropTarget(event) {
  const target = eventTargetElement(event);
  const row = target?.closest?.(".server-voice-channel-row[data-voice-channel-id]") || null;
  if (row) return row;
  const membersList = target?.closest?.(".server-voice-members-list[data-voice-members-for-channel]") || null;
  const channelId = normId(membersList?.getAttribute?.("data-voice-members-for-channel") || "");
  if (!channelId) return null;
  try {
    return document.querySelector(`.server-voice-channel-row[data-voice-channel-id="${cssEscapeAltaraIdentifier(channelId)}"]`);
  } catch (_) {
    return null;
  }
}

function resolveVoiceMemberSourceChannelId(memberEl = null) {
  if (!memberEl) return "";
  const direct = normId(memberEl.dataset?.currentVoiceChannelId || memberEl.getAttribute?.("data-current-voice-channel-id") || "");
  if (direct) return direct;

  const list = memberEl.closest?.("[data-voice-members-for-channel]") || null;
  const listId = normId(list?.dataset?.voiceMembersForChannel || list?.getAttribute?.("data-voice-members-for-channel") || "");
  if (listId) return listId;

  const block = memberEl.closest?.("[data-voice-channel-block]") || null;
  const blockId = normId(block?.dataset?.voiceChannelBlock || block?.getAttribute?.("data-voice-channel-block") || "");
  if (blockId) return blockId;

  const wrap = memberEl.closest?.(".serverVoiceRoomWrap,.server-voice-channel-block") || null;
  const wrapId = normId(wrap?.getAttribute?.("data-server-voice-channel-id") || wrap?.getAttribute?.("data-server-channel-id") || "");
  if (wrapId) return wrapId;

  const header = wrap?.querySelector?.(".server-voice-channel-row[data-voice-channel-id]") || null;
  const headerId = normId(header?.dataset?.voiceChannelId || header?.getAttribute?.("data-voice-channel-id") || "");
  if (headerId) return headerId;

  return "";
}

function cleanupVoiceMemberNativeDrag() {
  document
    .querySelectorAll(".server-voice-channel-row.is-voice-member-drop-target, .serverVoiceRoomWrap.is-voice-member-drop-target")
    .forEach((el) => el.classList.remove("is-voice-member-drop-target"));
  document
    .querySelectorAll(".server-voice-member-row.is-voice-member-dragging, .voice-participant-tile.is-voice-member-dragging")
    .forEach((el) => el.classList.remove("is-voice-member-dragging"));
  activeVoiceMemberNativeDrag = null;
  clearServerVoiceMemberDropTarget();
}

function handleVoiceMemberNativeDragStart(event) {
  const memberEl = getServerVoiceMemberDragSourceFromTarget(eventTargetElement(event));
  if (!memberEl || isServerVoiceBotMemberRow(memberEl)) return;
  if (isServerVoiceMemberInteractiveTarget(eventTargetElement(event))) return;

  const targetUserId = normId(memberEl.dataset.voiceMemberUserId || memberEl.getAttribute("data-server-voice-member-id") || "");
  const sourceChannelId = resolveVoiceMemberSourceChannelId(memberEl);
  if (sourceChannelId) {
    memberEl.dataset.currentVoiceChannelId = sourceChannelId;
    memberEl.setAttribute("data-current-voice-channel-id", sourceChannelId);
  }
  const conversationId = normId(memberEl.getAttribute("data-server-voice-conversation-id") || memberEl.getAttribute("data-voice-channel-conversation-id") || "");
  const serverId = normId(resolveServerVoiceServerIdByConversation(conversationId));
  const memberName = String(memberEl.dataset.voiceMemberName || memberEl.getAttribute("data-server-voice-member-label") || memberEl.getAttribute("aria-label") || memberEl.textContent || "Member").trim();

  console.info("[voice-drag] native start resolved source", {
    targetUserId,
    sourceChannelId,
    memberName,
    direct: memberEl.dataset.currentVoiceChannelId || "",
    fromList: memberEl.closest?.("[data-voice-members-for-channel]")?.dataset?.voiceMembersForChannel || "",
    fromHeader: memberEl.closest?.(".serverVoiceRoomWrap,.server-voice-channel-block")?.querySelector?.(".server-voice-channel-row[data-voice-channel-id]")?.dataset?.voiceChannelId || "",
  });

  if (!targetUserId || !sourceChannelId) {
    console.warn("[voice-drag] member dragstart missing source channel after resolver", {
      targetUserId,
      sourceChannelId,
      memberName,
      memberEl,
    });
    event.preventDefault?.();
    return;
  }

  const payload = {
    kind: "voice-member",
    targetUserId,
    sourceChannelId,
    conversationId,
    serverId,
    memberName,
    moveId: `move:${Date.now()}:${targetUserId}:${sourceChannelId}`,
  };
  activeVoiceMemberNativeDrag = payload;
  serverVoiceMemberDragSuppressClickUntil = Date.now() + 800;

  try {
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData(ALTARA_VOICE_MEMBER_DRAG_MIME, JSON.stringify(payload));
    event.dataTransfer.setData("text/plain", memberName);
    const dragImage = createVoiceMemberNativeDragImage(memberEl, payload);
    if (dragImage) {
      document.body.appendChild(dragImage);
      event.dataTransfer.setDragImage(dragImage, 14, 14);
      setTimeout(() => dragImage.remove(), 0);
    }
  } catch (error) {
    console.warn("[voice-drag] failed to prepare native drag payload", error);
  }

  memberEl.classList.add("is-voice-member-dragging");
  console.info("[voice-drag] native start", payload);
  event.stopPropagation?.();
}

function handleVoiceMemberNativeDragOver(event) {
  if (!eventHasVoiceMemberNativeDrag(event)) return;
  const channelEl = getVoiceChannelNativeDropTarget(event);
  if (!channelEl) return;
  const targetChannelId = normId(channelEl.dataset.voiceChannelId || channelEl.getAttribute("data-server-voice-channel-id") || "");
  if (!targetChannelId) return;

  event.preventDefault?.();
  event.stopPropagation?.();
  try { event.dataTransfer.dropEffect = "move"; } catch (_) {}
  setServerVoiceMemberDropTarget(channelEl);

  if (activeVoiceMemberNativeDrag?.lastTargetChannelId !== targetChannelId) {
    activeVoiceMemberNativeDrag.lastTargetChannelId = targetChannelId;
    console.info("[voice-drag] native target", {
      targetChannelId,
      name: channelEl.dataset.voiceChannelName || channelEl.getAttribute("data-server-voice-name") || channelEl.textContent.trim(),
    });
  }
}

function handleVoiceMemberNativeDragLeave(event) {
  if (!activeVoiceMemberNativeDrag) return;
  const related = event?.relatedTarget || null;
  if (related?.closest?.(".server-voice-channel-row.is-voice-member-drop-target")) return;
  const channelEl = getVoiceChannelNativeDropTarget(event);
  if (channelEl && serverVoiceMemberDropTargetEl === channelEl) clearServerVoiceMemberDropTarget();
}

async function moveServerVoiceMemberV2FastPath({
  serverId = "",
  targetUserId = "",
  sourceChannelId = "",
  targetChannelId = "",
  targetChannelName = "",
  conversationId = "",
  memberName = "",
  moveId = "",
  requestedAt = Date.now(),
} = {}) {
  const sid = normId(serverId || currentServerVoiceV2Session?.serverId || "");
  const targetId = normId(targetUserId || "");
  const destinationId = normId(targetChannelId || "");
  const effectiveMoveId = String(moveId || `move:${requestedAt}:${targetId}:${sourceChannelId}`).trim();
  if (!sid || !targetId || !destinationId) throw new Error("voice_v2_rpc_invalid_context");
  if (isServerMemberTimedOut(sid, targetId)) {
    throw createServerTimeoutVoiceBlockError(getServerMemberTimeout(sid, targetId), "That member is timed out and cannot join voice channels.");
  }

  const existingRow = getServerVoiceV2Member(targetId);
  const targetConversationId = getActiveConversationIdForChannel(destinationId, sid);
  applyServerVoiceV2MemberRow({
    ...(existingRow || {}),
    serverId: sid,
    userId: targetId,
    channelId: destinationId,
    conversationId: targetConversationId || "",
    sessionId: existingRow?.sessionId || "optimistic-drag",
    roomName: existingRow?.roomName || currentServerVoiceV2Session?.roomName || buildServerVoiceV2RoomName(sid),
    assignmentNonce: effectiveMoveId,
    assignmentUpdatedAt: requestedAt,
    updatedAt: requestedAt,
    heartbeatAt: requestedAt,
  }, "drag_optimistic");
  recordVoiceV2MoveTiming("optimistic_row_applied", {
    moveId: effectiveMoveId,
    assignmentNonce: effectiveMoveId,
    movePath: "rpc",
    targetUserId: targetId,
    sourceChannelId,
    targetChannelId: destinationId,
    elapsedMs: Date.now() - requestedAt,
  });

  recordVoiceV2MoveTiming("rpc_request_start", {
    moveId: effectiveMoveId,
    assignmentNonce: effectiveMoveId,
    movePath: "rpc",
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId,
    requestedAt,
  });
  console.info("[voice-v2-fast] rpc_request_start", {
    moveId: effectiveMoveId,
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId,
  });

  const rpcStartedAt = Date.now();
  const { data, error } = await supabase.rpc("move_server_voice_member_v2", {
    p_server_id: sid,
    p_target_user_id: targetId,
    p_target_channel_id: destinationId,
    p_move_id: effectiveMoveId,
  });
  recordVoiceV2MoveTiming("rpc_response", {
    moveId: effectiveMoveId,
    assignmentNonce: effectiveMoveId,
    movePath: "rpc",
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId,
    elapsedMs: Date.now() - rpcStartedAt,
    ok: !error && data?.ok !== false,
    error: error ? String(error?.message || error) : (data?.ok === false ? String(data?.error || "rpc_not_ok") : ""),
  });

  if (error || data?.ok === false) {
    console.warn("[voice-v2-fast] rpc_failed", {
      moveId: effectiveMoveId,
      serverId: sid,
      targetUserId: targetId,
      targetChannelId: destinationId,
      missingRpc: isMissingRpcError(error || data),
      message: error?.message || data?.message || data?.error || String(error || "rpc_not_ok"),
    });
    if (isMissingRpcError(error || data)) {
      console.info("[voice-v2-fast] edge_fallback_start", {
        moveId: effectiveMoveId,
        serverId: sid,
        targetUserId: targetId,
        targetChannelId: destinationId,
        reason: "rpc_missing",
      });
      recordVoiceV2MoveTiming("edge_fallback_start", {
        moveId: effectiveMoveId,
        assignmentNonce: effectiveMoveId,
        movePath: "edge_fallback",
        serverId: sid,
        targetUserId: targetId,
        targetChannelId: destinationId,
      });
      const fallbackResult = await performServerVoiceModerationAction({
        action: "move_member",
        serverId: sid,
        conversationId,
        channelId: sourceChannelId,
        targetUserId: targetId,
        targetChannelId: destinationId,
        targetChannelName,
        source: "drag",
        moveId: effectiveMoveId,
      });
      console.info("[voice-v2-fast] edge_fallback_response", {
        moveId: effectiveMoveId,
        serverId: sid,
        targetUserId: targetId,
        targetChannelId: destinationId,
        ok: fallbackResult?.ok !== false,
      });
      recordVoiceV2MoveTiming("edge_fallback_response", {
        moveId: effectiveMoveId,
        assignmentNonce: fallbackResult?.assignmentNonce || fallbackResult?.assignment_nonce || effectiveMoveId,
        movePath: "edge_fallback",
        serverId: sid,
        targetUserId: targetId,
        targetChannelId: destinationId,
        ok: fallbackResult?.ok !== false,
      });
      return fallbackResult;
    }
    const err = new Error(getServerVoiceActionErrorMessage(error || data, "Could not move that member."));
    err.details = error || data || null;
    throw err;
  }

  const confirmRow = data?.row || data?.member || null;
  if (confirmRow) {
    applyServerVoiceV2MemberRow(confirmRow, "rpc_confirm");
    recordVoiceV2MoveTiming("rpc_confirm_row_applied", {
      moveId: data?.moveId || data?.move_id || effectiveMoveId,
      assignmentNonce: data?.assignmentNonce || data?.assignment_nonce || effectiveMoveId,
      movePath: "rpc",
      serverId: sid,
      targetUserId: targetId,
      targetChannelId: destinationId,
      elapsedMs: Date.now() - requestedAt,
    });
  }

  console.info("[voice-v2-fast] rpc_response", {
    moveId: effectiveMoveId,
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId,
    targetChannelName,
    memberName,
    ok: true,
  });
  return data;
}

function isMissingDedicatedVoiceMoveFunctionError(error = null, payload = null) {
  const status = Number(error?.status || payload?.status || payload?.http_status || 0) || 0;
  const text = [
    error?.name,
    error?.message,
    error?.error,
    payload?.error,
    payload?.message,
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean).join(" ");
  if (status === 404) return true;
  return text.includes("function not found")
    || text.includes("functionshttperror")
    || text.includes("not found")
    || text.includes("failed to send a request to the edge function")
    || text.includes("server-voice-v2-move");
}

async function moveServerVoiceMemberV2DedicatedEdge({
  serverId = "",
  targetUserId = "",
  sourceChannelId = "",
  targetChannelId = "",
  targetChannelName = "",
  conversationId = "",
  moveId = "",
  requestedAt = Date.now(),
} = {}) {
  const sid = normId(serverId || currentServerVoiceV2Session?.serverId || "");
  const targetId = normId(targetUserId || "");
  const destinationId = normId(targetChannelId || "");
  const effectiveMoveId = String(moveId || `move:${requestedAt}:${targetId}:${sourceChannelId}`).trim();
  if (!sid || !targetId || !destinationId) throw new Error("voice_v2_dedicated_edge_invalid_context");
  if (isServerMemberTimedOut(sid, targetId)) {
    throw createServerTimeoutVoiceBlockError(getServerMemberTimeout(sid, targetId), "That member is timed out and cannot join voice channels.");
  }

  const edgeFunctionName = "server-voice-v2-move";
  const functionPath = `/functions/v1/${edgeFunctionName}`;
  const authReady = await ensureSupabaseFunctionInvokeAuthReady({
    edgeFunctionName,
    functionPath,
    requireUser: true,
    logPrefix: "[voice-v2 dedicated move auth]",
    logEvent: "voice_v2_dedicated_move.auth_state",
    logChannel: "voice-v2",
    failEvent: "voice_v2_dedicated_move.auth_missing",
  });
  if (!authReady.ok) throw authReady.error || new Error("voice_v2_dedicated_move_auth_missing");

  recordVoiceV2MoveTiming("dedicated_edge_request_start", {
    moveId: effectiveMoveId,
    assignmentNonce: effectiveMoveId,
    movePath: "dedicated_edge",
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId,
    requestedAt,
  });
  const startedAt = Date.now();
  const { data, error } = await supabase.functions.invoke(edgeFunctionName, {
    body: {
      serverId: sid,
      targetUserId: targetId,
      targetChannelId: destinationId,
      targetChannelName: String(targetChannelName || "").trim() || undefined,
      sourceChannelId: sourceChannelId || undefined,
      conversationId: conversationId || undefined,
      moveId: effectiveMoveId,
    },
  });
  const errorPayload = error ? await readSupabaseFunctionErrorPayload(error) : null;
  const payload = data && typeof data === "object" ? data : (errorPayload || {});
  recordVoiceV2MoveTiming("dedicated_edge_response", {
    moveId: effectiveMoveId,
    assignmentNonce: payload?.assignmentNonce || payload?.assignment_nonce || effectiveMoveId,
    movePath: "dedicated_edge",
    serverId: sid,
    targetUserId: targetId,
    targetChannelId: destinationId,
    elapsedMs: Date.now() - startedAt,
    ok: !error && payload?.ok !== false,
    controlSent: payload?.controlSent === true || payload?.control_sent === true,
    error: error ? String(error?.message || error) : (payload?.ok === false ? String(payload?.error || "dedicated_edge_not_ok") : ""),
  });

  if (error || payload?.ok === false) {
    const err = new Error(getServerVoiceActionErrorMessage(errorPayload || payload, "Could not move that member."));
    err.details = errorPayload || payload || null;
    err.status = Number(error?.status || payload?.status || payload?.http_status || 0) || null;
    err.isMissingDedicatedVoiceMoveFunction = isMissingDedicatedVoiceMoveFunctionError(error, errorPayload || payload);
    throw err;
  }

  if (payload?.row) applyServerVoiceV2MemberRow(payload.row, "dedicated_edge_confirm");
  return payload;
}

async function moveVoiceMemberToChannelFromNativeDrag({
  targetUserId = "",
  sourceChannelId = "",
  targetChannelId = "",
  targetChannelName = "",
  conversationId = "",
  serverId = "",
  memberName = "",
  moveId = "",
} = {}) {
  try {
    const requestedAt = Date.now();
    const effectiveMoveId = String(moveId || `move:${requestedAt}:${targetUserId}:${sourceChannelId}`).trim();
    if (isServerVoiceV2Enabled() && isVoiceV2RpcFastPathEnabled()) {
      await moveServerVoiceMemberV2FastPath({
        serverId,
        targetUserId,
        sourceChannelId,
        targetChannelId,
        targetChannelName,
        conversationId,
        memberName,
        moveId: effectiveMoveId,
        requestedAt,
      });
      notifyServerVoiceModerationUi("Move sent.");
      return;
    }
    if (isServerVoiceV2Enabled()) {
      const existingRow = getServerVoiceV2Member(targetUserId);
      const sid = serverId || existingRow?.serverId || currentServerVoiceV2Session?.serverId || "";
      const targetConversationId = getActiveConversationIdForChannel(targetChannelId, sid);
      applyServerVoiceV2MemberRow({
        ...(existingRow || {}),
        serverId: sid,
        userId: targetUserId,
        channelId: targetChannelId,
        conversationId: targetConversationId || "",
        sessionId: existingRow?.sessionId || "optimistic-drag",
        roomName: existingRow?.roomName || currentServerVoiceV2Session?.roomName || buildServerVoiceV2RoomName(sid),
        assignmentNonce: effectiveMoveId,
        assignmentUpdatedAt: requestedAt,
        updatedAt: requestedAt,
        heartbeatAt: requestedAt,
      }, "drag_optimistic");
      recordVoiceV2MoveTiming("optimistic_row_applied", {
        moveId: effectiveMoveId,
        assignmentNonce: effectiveMoveId,
        movePath: isVoiceV2DedicatedMoveEnabled() ? "dedicated_edge" : "edge_control_signal",
        targetUserId,
        sourceChannelId,
        targetChannelId,
        elapsedMs: Date.now() - requestedAt,
      });
      if (isVoiceV2DedicatedMoveEnabled()) {
        try {
          await moveServerVoiceMemberV2DedicatedEdge({
            serverId: sid,
            targetUserId,
            sourceChannelId,
            targetChannelId,
            targetChannelName,
            conversationId,
            moveId: effectiveMoveId,
            requestedAt,
          });
          notifyServerVoiceModerationUi("Move sent.");
          return;
        } catch (dedicatedError) {
          if (!dedicatedError?.isMissingDedicatedVoiceMoveFunction) throw dedicatedError;
          console.warn("[voice-v2-move] dedicated edge missing; falling back to legacy edge", {
            moveId: effectiveMoveId,
            serverId: sid,
            targetUserId,
            targetChannelId,
            message: dedicatedError?.message || String(dedicatedError || "unknown"),
          });
          recordVoiceV2MoveTiming("legacy_edge_fallback_start", {
            moveId: effectiveMoveId,
            assignmentNonce: effectiveMoveId,
            movePath: "legacy_edge_fallback",
            serverId: sid,
            targetUserId,
            targetChannelId,
            reason: "dedicated_edge_missing",
          });
        }
      } else {
        recordVoiceV2MoveTiming("legacy_edge_fallback_start", {
          moveId: effectiveMoveId,
          assignmentNonce: effectiveMoveId,
          movePath: "legacy_edge_fallback",
          serverId: sid,
          targetUserId,
          targetChannelId,
          reason: "dedicated_edge_disabled",
        });
      }
    }
    recordVoiceV2MoveTiming("edge_request_start", {
      moveId: effectiveMoveId,
      assignmentNonce: effectiveMoveId,
      movePath: isServerVoiceV2Enabled() ? "legacy_edge_fallback" : "edge",
      targetUserId,
      sourceChannelId,
      targetChannelId,
      source: "drag",
      requestedAt,
    });
    const result = await performServerVoiceModerationAction({
      action: "move_member",
      serverId,
      conversationId,
      channelId: sourceChannelId,
      targetUserId,
      targetChannelId,
      targetChannelName,
      source: "drag",
      moveId: effectiveMoveId,
    });
    recordVoiceV2MoveTiming("edge_response", {
      moveId: effectiveMoveId,
      assignmentNonce: result?.assignmentNonce || result?.assignment_nonce || effectiveMoveId,
      movePath: isServerVoiceV2Enabled() ? "legacy_edge_fallback" : "edge",
      targetUserId,
      targetChannelId,
      elapsedMs: Date.now() - requestedAt,
      mode: result?.mode || result?.moveMode || "",
      controlSent: result?.controlSent === true || result?.control_sent === true,
      metadataMirrorOk: result?.metadataMirrorOk ?? result?.metadata_mirror_ok ?? null,
    });
    if (isServerVoiceV2Enabled()) {
      recordVoiceV2MoveTiming("legacy_edge_fallback_response", {
        moveId: effectiveMoveId,
        assignmentNonce: result?.assignmentNonce || result?.assignment_nonce || effectiveMoveId,
        movePath: "legacy_edge_fallback",
        targetUserId,
        targetChannelId,
        elapsedMs: Date.now() - requestedAt,
        ok: result?.ok !== false,
      });
    }
    notifyServerVoiceModerationUi(isServerVoiceV2Enabled()
      ? "Move sent."
      : getVoiceModerationSuccessMessage({ action: "move_member", targetName: memberName, targetChannelName }));
  } catch (error) {
    if (isServerVoiceV2Enabled()) {
      void loadServerVoiceV2ControlPlaneSnapshot(serverId || currentServerVoiceV2Session?.serverId || "", "drag_failed");
    }
    const safeMessage = /livekitParticipantLookupError/i.test(String(error?.message || ""))
      ? "Could not confirm voice move."
      : (error?.message || "Could not move that member.");
    console.error("[voice-drag] native move failed", {
      targetUserId,
      sourceChannelId,
      targetChannelId,
      memberName,
      message: error?.message,
      error,
    });
    notifyServerVoiceModerationUi(safeMessage, { error: true });
  }
}

async function handleVoiceMemberNativeDrop(event) {
  if (!eventHasVoiceMemberNativeDrag(event)) return;
  const channelEl = getVoiceChannelNativeDropTarget(event);
  if (!channelEl) return;
  const targetChannelId = normId(channelEl.dataset.voiceChannelId || channelEl.getAttribute("data-server-voice-channel-id") || "");
  if (!targetChannelId) return;

  let payload = activeVoiceMemberNativeDrag;
  try {
    const raw = event.dataTransfer?.getData?.(ALTARA_VOICE_MEMBER_DRAG_MIME) || "";
    if (raw) payload = JSON.parse(raw);
  } catch (error) {
    console.warn("[voice-drag] failed to parse voice member drag payload", error);
  }

  event.preventDefault?.();
  event.stopPropagation?.();

  if (!payload?.targetUserId || !payload?.sourceChannelId) {
    console.warn("[voice-drag] drop missing payload", { payload });
    cleanupVoiceMemberNativeDrag();
    return;
  }
  if (targetChannelId === normId(payload.sourceChannelId)) {
    console.info("[voice-drag] native drop ignored same channel", {
      targetUserId: payload.targetUserId,
      targetChannelId,
    });
    cleanupVoiceMemberNativeDrag();
    return;
  }

  const targetChannelName = String(channelEl.dataset.voiceChannelName || channelEl.getAttribute("data-server-voice-name") || channelEl.textContent || "").trim();
  console.info("[voice-drag] native drop", {
    targetUserId: payload.targetUserId,
    from: payload.sourceChannelId,
    to: targetChannelId,
  });
  recordVoiceV2MoveTiming("drag_drop", {
    moveId: payload.moveId || "",
    assignmentNonce: payload.moveId || "",
    targetUserId: payload.targetUserId,
    from: payload.sourceChannelId,
    to: targetChannelId,
    at: Date.now(),
  });
  cleanupVoiceMemberNativeDrag();
  await moveVoiceMemberToChannelFromNativeDrag({
    targetUserId: payload.targetUserId,
    sourceChannelId: payload.sourceChannelId,
    targetChannelId,
    targetChannelName,
    conversationId: payload.conversationId,
    serverId: payload.serverId,
    memberName: payload.memberName,
    moveId: payload.moveId,
  });
}

function handleVoiceMemberNativeDragEnd() {
  cleanupVoiceMemberNativeDrag();
}


function cleanupServerVoiceMemberPointerDrag({ restoreRow = true } = {}) {
  const drag = serverVoiceMemberPointerDrag;
  if (drag?.sourceRow && restoreRow) drag.sourceRow.classList.remove("is-voice-member-dragging");
  try { drag?.sourceRow?.setAttribute?.("draggable", "false"); } catch (_) {}
  try { drag?.sourceRow?.releasePointerCapture?.(drag.pointerId); } catch (_) {}
  if (serverVoiceMemberDragGhostEl) {
    serverVoiceMemberDragGhostEl.remove();
    serverVoiceMemberDragGhostEl = null;
  }
  clearServerVoiceMemberDropTarget();
  try { document.body?.classList?.remove("is-server-voice-member-dragging"); } catch (_) {}
  serverVoiceMemberPointerDrag = null;
}

function updateServerVoiceMemberDragGhost(event) {
  const drag = serverVoiceMemberPointerDrag;
  if (!drag?.ghostEl) return;
  drag.ghostEl.style.left = `${Number(event.clientX || 0) - Number(drag.offsetX || 18)}px`;
  drag.ghostEl.style.top = `${Number(event.clientY || 0) - Number(drag.offsetY || 16)}px`;
}

function getServerVoiceMemberDropTargetFromPoint(clientX, clientY) {
  const x = Number(clientX || 0);
  const y = Number(clientY || 0);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  const previousPointerEvents = serverVoiceMemberDragGhostEl?.style?.pointerEvents || "";
  if (serverVoiceMemberDragGhostEl) serverVoiceMemberDragGhostEl.style.pointerEvents = "none";
  const el = document.elementFromPoint(x, y);
  if (serverVoiceMemberDragGhostEl) serverVoiceMemberDragGhostEl.style.pointerEvents = previousPointerEvents || "none";
  const target = el?.closest?.("[data-voice-channel-id].server-voice-channel-row, [data-server-voice-drop-target='1'][data-server-voice-channel-id]") || null;
  if (!target) return null;
  const targetChannelId = normId(target.getAttribute("data-server-voice-channel-id") || target.getAttribute("data-voice-channel-id") || "");
  const dragChannelId = normId(serverVoiceMemberPointerDrag?.sourceChannelId || "");
  if (!targetChannelId || targetChannelId === dragChannelId) return null;
  if (serverVoiceMemberPointerDrag?.lastDropTargetId !== targetChannelId) {
    serverVoiceMemberPointerDrag.lastDropTargetId = targetChannelId;
    const targetName = String(target.getAttribute("data-voice-channel-name") || target.getAttribute("data-server-voice-name") || target.querySelector?.(".serverVoiceRoom__label")?.textContent || "").trim();
    console.info("[voice-drag] target", { targetChannelId, name: targetName });
  }
  return target;
}

function beginServerVoiceMemberPointerDrag(event) {
  if (serverVoiceMemberPointerDrag) return;
  if (!event || event.button !== 0) return;
  const target = eventTargetElement(event);
  if (!target || isServerVoiceMemberInteractiveTarget(target)) return;
  const row = getServerVoiceMemberDragSourceFromTarget(target);
  if (!row || isServerVoiceBotMemberRow(row)) return;
  event.stopPropagation?.();
  const targetUserId = normId(row.dataset.voiceMemberUserId || row.getAttribute("data-server-voice-member-id") || "");
  const conversationId = normId(row.getAttribute("data-server-voice-conversation-id") || row.getAttribute("data-voice-channel-conversation-id") || "");
  const sourceChannelId = normId(row.dataset.currentVoiceChannelId || row.getAttribute("data-server-voice-channel-id") || row.getAttribute("data-voice-channel-id") || "");
  const serverId = normId(resolveServerVoiceServerIdByConversation(conversationId));
  const actorId = normId(state.user?.id || "");
  if (!targetUserId || !conversationId || !sourceChannelId || !serverId || !actorId) return;
  try { row.setAttribute("draggable", "false"); } catch (_) {}
  const context = getServerVoiceMemberModerationContext({
    userId: targetUserId,
    conversationId,
    serverId,
    displayName: row.getAttribute("data-server-voice-member-label") || "",
  });
  console.info("[voice-drag] candidate", {
    targetUserId,
    sourceChannelId,
    memberName: row.dataset.voiceMemberName || row.getAttribute("data-server-voice-member-label") || String(row.textContent || "").trim(),
    className: row.className || "",
  });
  const rect = row.getBoundingClientRect();
  serverVoiceMemberPointerDrag = {
    pointerId: event.pointerId,
    sourceRow: row,
    serverId,
    conversationId,
    sourceChannelId,
    targetUserId,
    targetDisplayName: row.dataset.voiceMemberName || row.getAttribute("data-server-voice-member-label") || row.getAttribute("aria-label") || context?.targetDisplayName || String(row.textContent || "").trim() || "Member",
    targetAvatarHtml: row.querySelector(".serverVoiceMember__avatar, .participantAvatar, .stageAvatar, .avatar")?.innerHTML || "",
    startX: event.clientX,
    startY: event.clientY,
    offsetX: Number(event.clientX || 0) - rect.left,
    offsetY: Number(event.clientY || 0) - rect.top,
    started: false,
    ghostEl: null
  };
  try { row.setPointerCapture?.(event.pointerId); } catch (_) {}
}

function moveServerVoiceMemberPointerDrag(event) {
  const drag = serverVoiceMemberPointerDrag;
  if (!drag || event.pointerId !== drag.pointerId) return;
  const dx = Number(event.clientX || 0) - Number(drag.startX || 0);
  const dy = Number(event.clientY || 0) - Number(drag.startY || 0);
  if (!drag.started) {
    if (Math.hypot(dx, dy) < 7) return;
    drag.started = true;
    serverVoiceMemberDragSuppressClickUntil = Date.now() + 500;
    console.info("[voice-drag] start", {
      targetUserId: drag.targetUserId,
      sourceChannelId: drag.sourceChannelId,
      memberName: drag.targetDisplayName,
    });
    event.preventDefault?.();
    event.stopPropagation?.();
    closeServerVoiceMemberMenu({ force: true, reason: "voice_member_drag" });
    if (/^general$/i.test(String(drag.targetDisplayName || "").trim())) {
      console.error("[voice-drag] wrong source: ghost got channel name", {
        targetUserId: drag.targetUserId,
        sourceChannelId: drag.sourceChannelId,
        sourceRow: drag.sourceRow,
      });
    }
    const ghost = document.createElement("div");
    ghost.className = "voice-member-drag-ghost";
    ghost.innerHTML = `${drag.targetAvatarHtml ? `<span class="voice-member-drag-ghost__avatar">${drag.targetAvatarHtml}</span>` : ""}<span class="voice-member-drag-ghost__name">${esc(drag.targetDisplayName || "Member")}</span>`;
    document.body.appendChild(ghost);
    serverVoiceMemberDragGhostEl = ghost;
    drag.ghostEl = ghost;
    drag.sourceRow?.classList?.add("is-voice-member-dragging");
    document.body?.classList?.add("is-server-voice-member-dragging");
  }
  event.preventDefault?.();
  event.stopPropagation?.();
  updateServerVoiceMemberDragGhost(event);
  setServerVoiceMemberDropTarget(getServerVoiceMemberDropTargetFromPoint(event.clientX, event.clientY));
}

async function endServerVoiceMemberPointerDrag(event) {
  const drag = serverVoiceMemberPointerDrag;
  if (!drag || event.pointerId !== drag.pointerId) return;
  const hadStarted = drag.started === true;
  const dropTarget = hadStarted ? getServerVoiceMemberDropTargetFromPoint(event.clientX, event.clientY) : null;
  const targetChannelId = normId(dropTarget?.getAttribute?.("data-server-voice-channel-id") || dropTarget?.getAttribute?.("data-voice-channel-id") || "");
  const targetChannelName = String(dropTarget?.getAttribute?.("data-voice-channel-name") || dropTarget?.getAttribute?.("data-server-voice-name") || dropTarget?.querySelector?.("[data-server-voice-name], .serverVoiceRoom__label")?.getAttribute?.("data-server-voice-name") || dropTarget?.querySelector?.(".serverVoiceRoom__label")?.textContent || "").trim();
  cleanupServerVoiceMemberPointerDrag();
  if (!hadStarted || !targetChannelId) {
    console.info("[voice-drag] cancel no target", {
      hadStarted,
      targetUserId: drag.targetUserId,
      sourceChannelId: drag.sourceChannelId,
    });
    return;
  }
  event.preventDefault?.();
  event.stopPropagation?.();
  console.info("[voice-drag] drop", {
    targetUserId: drag.targetUserId,
    sourceChannelId: drag.sourceChannelId,
    targetChannelId,
  });
  try {
    await performServerVoiceModerationAction({
      action: "move_member",
      serverId: drag.serverId,
      conversationId: drag.conversationId,
      channelId: drag.sourceChannelId,
      targetUserId: drag.targetUserId,
      targetChannelId,
      targetChannelName,
      source: "drag",
    });
    notifyServerVoiceModerationUi(isServerVoiceV2Enabled()
      ? "Move sent."
      : getVoiceModerationSuccessMessage({ action: "move_member", targetName: drag.targetDisplayName, targetChannelName }));
  } catch (error) {
    notifyServerVoiceModerationUi(error?.message || "Could not move that member.", { error: true });
  }
}

function cancelServerVoiceMemberPointerDrag(event = null) {
  const drag = serverVoiceMemberPointerDrag;
  if (event?.pointerId != null && drag && event.pointerId !== drag.pointerId) return;
  cleanupServerVoiceMemberPointerDrag();
}

function bindServerVoiceMemberDocumentDragOnce() {
  if (bindServerVoiceMemberDocumentDragOnce.bound) return;
  bindServerVoiceMemberDocumentDragOnce.bound = true;
  document.addEventListener("click", (event) => {
    if (Date.now() >= serverVoiceMemberDragSuppressClickUntil) return;
    const target = eventTargetElement(event);
    if (!getServerVoiceMemberDragSourceFromTarget(target)) return;
    console.info("[voice-drag] suppressed profile click after native drag");
    event.preventDefault?.();
    event.stopPropagation?.();
  }, true);
  document.addEventListener("dragstart", handleVoiceMemberNativeDragStart, true);
  document.addEventListener("dragover", handleVoiceMemberNativeDragOver, true);
  document.addEventListener("dragleave", handleVoiceMemberNativeDragLeave, true);
  document.addEventListener("drop", handleVoiceMemberNativeDrop, true);
  document.addEventListener("dragend", handleVoiceMemberNativeDragEnd, true);
  document.addEventListener("keydown", (event) => {
    if (String(event.key || "") === "Escape") cleanupVoiceMemberNativeDrag();
  }, true);
}
bindServerVoiceMemberDocumentDragOnce();

try {
  window.altaraDebugVoiceModeration = window.altaraDebugVoiceModeration || {};
  window.altaraDebugVoiceModeration.dragState = () => serverVoiceMemberPointerDrag ? {
    serverId: serverVoiceMemberPointerDrag.serverId,
    conversationId: serverVoiceMemberPointerDrag.conversationId,
    sourceChannelId: serverVoiceMemberPointerDrag.sourceChannelId,
    targetUserId: serverVoiceMemberPointerDrag.targetUserId,
    started: serverVoiceMemberPointerDrag.started === true,
  } : activeVoiceMemberNativeDrag;
  window.altaraDebugVoiceModeration.nativeMemberDragState = () => activeVoiceMemberNativeDrag;
  window.altaraDebugVoiceModeration.testMove = (targetUserId, targetChannelId) => performServerVoiceModerationAction({
    action: "move_member",
    serverId: getServerSettingsActiveServerId?.() || state.activeDm?.serverId || "",
    targetUserId,
    targetChannelId,
    source: "manual-debug",
  });
  window.altaraDebugVoiceModeration.testMute = (targetUserId) => performServerVoiceModerationAction({
    action: "mute_member",
    serverId: getServerSettingsActiveServerId?.() || state.activeDm?.serverId || "",
    targetUserId,
    source: "manual-debug",
  });
  window.altaraDebugVoiceModeration.testDeafen = (targetUserId) => performServerVoiceModerationAction({
    action: "deafen_member",
    serverId: getServerSettingsActiveServerId?.() || state.activeDm?.serverId || "",
    targetUserId,
    source: "manual-debug",
  });
  window.altaraDebugVoiceModeration.inspectVoiceRows = () => Array.from(document.querySelectorAll("[data-voice-member-user-id]")).map((el) => ({
    text: String(el.textContent || "").trim(),
    userId: el.dataset.voiceMemberUserId || "",
    channelId: el.dataset.currentVoiceChannelId || el.getAttribute("data-voice-channel-id") || "",
  }));
  window.altaraDebugVoiceModeration.inspectVoiceChannels = () => Array.from(document.querySelectorAll("[data-voice-channel-id].server-voice-channel-row, [data-server-voice-drop-target='1'][data-server-voice-channel-id]")).map((el) => ({
    text: String(el.textContent || "").trim(),
    channelId: el.dataset.voiceChannelId || el.getAttribute("data-server-voice-channel-id") || "",
  }));
  window.altaraDebugVoiceModeration.inspectVoiceDragSources = () => Array.from(document.querySelectorAll(".server-voice-member-row[data-voice-member-user-id], .voice-participant-tile[data-voice-member-user-id]")).map((el) => {
    const rect = el.getBoundingClientRect?.();
    return {
      text: String(el.textContent || el.getAttribute("aria-label") || "").trim(),
      className: el.className || "",
      userId: el.dataset.voiceMemberUserId || "",
      name: el.dataset.voiceMemberName || el.getAttribute("data-server-voice-member-label") || "",
      directChannelId: el.dataset.currentVoiceChannelId || "",
      resolvedChannelId: resolveVoiceMemberSourceChannelId(el),
      draggable: el.getAttribute("draggable"),
      hasDraggableAncestor: Boolean(el.parentElement?.closest?.("[draggable='true']")),
      draggableAncestorText: String(el.parentElement?.closest?.("[draggable='true']")?.textContent || "").trim().slice(0, 80),
      rect: rect ? { x: rect.x, y: rect.y, width: rect.width, height: rect.height, top: rect.top, left: rect.left, bottom: rect.bottom, right: rect.right } : null,
    };
  });
  window.altaraDebugVoiceModeration.inspectVoiceDropTargets = () => Array.from(document.querySelectorAll(".server-voice-channel-row[data-voice-channel-id], [data-voice-channel-id].server-voice-channel-row")).map((el) => ({
    text: String(el.textContent || "").trim(),
    className: el.className || "",
    channelId: el.dataset.voiceChannelId || "",
    name: el.dataset.voiceChannelName || el.getAttribute("data-server-voice-name") || "",
    draggable: el.getAttribute("draggable"),
  }));
  window.altaraDebugVoiceModeration.inspectEffectiveState = (userId = "") => {
    const uid = normId(userId || state.user?.id || "");
    const convId = getCurrentCallConversationId();
    const audio = getParticipantAudioStateForUi(uid, convId) || {};
    const isSelf = uid && uid === normId(state.user?.id || "");
    const stateForDisplay = {
      selfMuted: isSelf ? !!micMuted : !!audio.selfMuted,
      selfDeafened: isSelf ? !!deafened : !!audio.selfDeafened,
      serverMuted: isSelf ? isServerVoiceSelfMuted(convId) : !!audio.serverMuted,
      serverDeafened: isSelf ? isServerVoiceSelfDeafened(convId) : !!audio.serverDeafened,
    };
    const effective = computeEffectiveVoiceState(stateForDisplay);
    return {
      userId: uid,
      conversationId: convId,
      ...stateForDisplay,
      effectiveMicMuted: isSelf ? getEffectiveLocalMicMuted(convId) : effective.effectiveMicMuted,
      effectiveOutputDeafened: isSelf ? getEffectiveLocalDeafened(convId) : effective.effectiveOutputDeafened,
      displayBadges: getVoiceDisplayBadges(stateForDisplay),
      preServerLock: getServerVoicePreServerLockState(convId, uid),
      raw: audio,
    };
  };
  window.altaraDebugVoiceModeration.inspectDisplayState = (userId = "") => {
    const uid = normId(userId || state.user?.id || "");
    const convId = getCurrentCallConversationId();
    const audio = getParticipantAudioStateForUi(uid, convId) || {};
    const displayState = {
      selfMuted: !!audio.selfMuted,
      selfDeafened: !!audio.selfDeafened,
      serverMuted: !!audio.serverMuted,
      serverDeafened: !!audio.serverDeafened,
    };
    const effective = computeEffectiveVoiceState(displayState);
    return {
      userId: uid,
      conversationId: convId,
      ...displayState,
      effectiveMicMuted: effective.effectiveMicMuted,
      effectiveOutputDeafened: effective.effectiveOutputDeafened,
      displayBadges: getVoiceDisplayBadges(displayState),
      raw: audio,
    };
  };
  window.altaraDebugVoiceModeration.inspectLocalAudioLocks = () => {
    const convId = getCurrentCallConversationId();
    const meId = normId(state.user?.id || "");
    return {
      userId: meId,
      conversationId: convId,
      localMicTrackMuted: getLocalMicTrackMutedState(),
      selfMuted: !!micMuted,
      serverMuted: isServerVoiceSelfMuted(convId),
      selfDeafened: !!deafened,
      serverDeafened: isServerVoiceSelfDeafened(convId),
      effectiveMicMuted: getEffectiveLocalMicMuted(convId),
      effectiveOutputDeafened: getEffectiveLocalDeafened(convId),
      preServerLock: getServerVoicePreServerLockState(convId, meId),
    };
  };
  window.altaraDebugVoiceModeration.traceMicState = () => {
    const convId = getCurrentCallConversationId();
    const meId = normId(state.user?.id || "");
    return {
      userId: meId,
      conversationId: convId,
      localMicTransportMuted: getLocalMicTrackMutedState(),
      selfMuted: !!micMuted,
      selfDeafened: !!deafened,
      serverMuted: isServerVoiceSelfMuted(convId),
      serverDeafened: isServerVoiceSelfDeafened(convId),
      effectiveMicMuted: getEffectiveLocalMicMuted(convId),
      effectiveOutputDeafened: getEffectiveLocalDeafened(convId),
      lastMicStateChange: lastVoiceMicStateChange,
      lastOutputStateChange: lastVoiceOutputStateChange,
    };
  };
  window.altaraDebugVoiceModeration.optimisticState = () => ({
    actionsByTarget: Array.from(voiceModerationOptimisticState.actionsByTarget.entries()),
    memberOverrides: Array.from(voiceModerationOptimisticState.memberOverrides.entries()),
    moveOverrides: Array.from(voiceModerationOptimisticState.moveOverrides.entries()),
  });
  window.altaraDebugVoiceModeration.inspectMoveTransitions = () => Array.from(voiceModerationOptimisticState.moveOverrides.entries()).map(([userId, entry]) => ({
    userId,
    fromChannelId: entry?.fromChannelId || "",
    targetChannelId: entry?.toChannelId || entry?.targetChannelId || "",
    status: entry?.pendingMove ? "switching" : "confirmed",
    updatedAt: entry?.updatedAt || null,
  }));
  window.altaraDebugVoiceModeration.inspectCurrentVoiceMove = () => {
    const currentUserId = normId(state.user?.id || "");
    const currentUserVoiceChannelId = getCurrentUserVisibleVoiceChannelId();
    const convId = normId(callConversationId || activeDmId || state.activeDm?.conversationId || "");
    const ctx = findServerChannelContextByConversationId(convId) || null;
    return {
      currentUserId,
      currentUserVoiceChannelId,
      activeVoiceChannelId: normId(ctx?.channel?.id || ""),
      callConversationId: normId(callConversationId || ""),
      moveTransition: voiceModerationOptimisticState.moveOverrides.get(currentUserId) || null,
    };
  };
  window.altaraDebugVoiceModeration.inspectMoveMode = () => {
    const convId = normId(callConversationId || activeDmId || state.activeDm?.conversationId || "");
    let snapshot = null;
    try {
      snapshot = serverVoiceTransportController?.getSnapshot?.() || getServerVoiceTransportSnapshot(convId) || null;
    } catch (_) {
      snapshot = null;
    }
    const ctx = findServerChannelContextByConversationId(convId) || null;
    return {
      moveMode: "livekit_move_participant",
      activeMoveTransitions: window.altaraDebugVoiceModeration.inspectMoveTransitions(),
      currentRoomName: String(snapshot?.roomName || "").trim() || null,
      currentVoiceChannelId: normId(ctx?.channel?.id || ""),
      currentVoiceChannelName: ctx?.channel?.name || "",
      currentConversationId: convId,
    };
  };
  window.altaraDebugVoiceModeration.serverState = () => Array.from(serverVoiceModerationStateByConversation.entries()).map(([conversationId, entries]) => ({
    conversationId,
    users: Array.from(entries.entries()).map(([userId, row]) => ({
      userId,
      channelId: row?.channelId || "",
      micServerMuted: row?.micServerMuted === true,
      deafServerMuted: row?.deafServerMuted === true,
      updatedAt: row?.updatedAt || "",
      source: row?.source || "",
    })),
  }));
  window.altaraDebugVoiceModeration.clearOptimisticState = () => {
    voiceModerationOptimisticState.actionsByTarget.clear();
    voiceModerationOptimisticState.memberOverrides.clear();
    voiceModerationOptimisticState.moveOverrides.clear();
    refreshVoiceModerationOptimisticUi();
    return window.altaraDebugVoiceModeration.optimisticState();
  };
  window.altaraDebugVoiceModeration.inspectVoiceStageState = () => {
    const convId = normId(callConversationId || activeDmId || state.activeDm?.conversationId || "");
    const ctx = findServerChannelContextByConversationId(convId) || null;
    const stage = document.getElementById("callStage");
    const visibleTileIds = collectVisibleStageTileIds(stage);
    const currentUserVoiceChannelId = getCurrentUserVisibleVoiceChannelId();
    const currentUserCtx = currentUserVoiceChannelId ? findServerChannelContextByChannelId(currentUserVoiceChannelId) : null;
    return {
      activeVoiceChannelId: normId(ctx?.channel?.id || ""),
      activeVoiceChannelName: ctx?.channel?.name || "",
      visibleParticipantIds: visibleTileIds.map((tileId) => parseStageParticipantTileId(tileId).participantId).filter(Boolean),
      participantCount: visibleTileIds.length,
      currentUserVoiceChannelId,
      currentUserVoiceChannelName: currentUserCtx?.channel?.name || "",
      moveOverrides: Array.from(voiceModerationOptimisticState.moveOverrides.entries()),
      emptyStateVisible: !!document.querySelector(".server-voice-stage-empty"),
    };
  };
  window.altaraDebugPermissions = window.altaraDebugPermissions || {};
  window.altaraDebugPermissions.explainVoiceModeration = async () => {
    const serverId = getServerSettingsActiveServerId?.() || state.activeDm?.serverId || "";
    await ensureServerRolePermissionCache(serverId, { force: false }).catch(() => {});
    return {
      serverId,
      permissions: getEffectiveServerPermissionsForCurrentUser(serverId),
      capabilityState: getCurrentServerCapabilityUiState(serverId),
      menuTarget: serverVoiceMemberMenuTarget,
      dragState: window.altaraDebugVoiceModeration.dragState(),
    };
  };
} catch (_) {}

async function canServerVoiceModeratorAffectTarget(conversationId, actorUserId, targetUserId, action = "") {
  const convId = normId(conversationId || "");
  const actorId = normId(actorUserId || "");
  const targetId = normId(targetUserId || "");
  if (!convId || !actorId || !targetId || !isServerVoiceConversationById(convId)) return false;
  const sid = resolveServerVoiceServerIdByConversation(convId);
  if (!sid) return false;

  let members = serverMemberListByServerId.get(sid) || [];
  if (!Array.isArray(members) || !members.length) {
    try {
      members = await fetchServerMembersForSidebar(sid, { force: true });
    } catch (_) {
      members = members || [];
    }
  }
  await ensureServerRolePermissionCache(sid, { force: false }).catch(() => {});
  const roles = serverRoleListByServerId.get(sid) || [];
  const roleMemberMap = serverRoleMemberMapByServerId.get(sid) || new Map();
  const ability = canServerActorModerateTargetWithPermission({
    serverId: sid,
    actorUserId: actorId,
    targetUserId: targetId,
    members,
    roles,
    roleMemberMap,
  });
  if (!ability?.canTouchTarget) return false;

  const actionName = String(action || "").trim().toLowerCase();
  if (!actionName) return true;
  const flags = ability.permissions || normalizeServerRolePermissions({});
  if (actionName === "disconnect") {
    return !!(flags.move_members || flags.voice_disconnect_members || flags.kick_members || flags.server_kick_members || flags.ban_members || flags.server_ban_members);
  }
  if (actionName === "set_mic_muted") return !!(flags.mute_members || flags.voice_mute_microphone);
  if (actionName === "set_deafened") return !!(flags.deafen_members || flags.voice_deafen_members);
  if (actionName === "kick") return !!(flags.kick_members || flags.server_kick_members);
  if (actionName === "ban") return !!(flags.ban_members || flags.server_ban_members);
  return false;
}

async function kickServerMemberFromServer(serverId, userId) {
  const sid = normId(serverId);
  const uid = normId(userId);
  if (!sid || !uid) return { ok: false, error: { message: "server_id/user_id invalido" } };

  const rpcPayloads = [
    { p_server_id: sid, p_user_id: uid },
    { server_id: sid, user_id: uid },
  ];
  const rpcNames = ["kick_server_member", "remove_server_member"];
  let lastMissingErr = null;
  for (const rpcName of rpcNames) {
    for (const payload of rpcPayloads) {
      const res = await supabase.rpc(rpcName, payload);
      if (!res?.error) return { ok: true, via: rpcName, error: null };
      if (!isMissingRpcError(res.error)) return { ok: false, error: res.error };
      lastMissingErr = res.error;
    }
  }

  const { error: deleteErr } = await supabase
    .from("server_members")
    .delete()
    .eq("server_id", sid)
    .eq("user_id", uid);
  if (deleteErr) {
    if (!lastMissingErr || !isMissingTableError(deleteErr, "server_members")) {
      return { ok: false, error: deleteErr };
    }
    return { ok: false, error: lastMissingErr };
  }

  try {
    const channels = await fetchServerChannelsForSidebar(sid, { force: false });
    const conversationIds = normalizeUuidArray((channels || []).map((ch) => normId(ch?.conversationId || "")));
    if (conversationIds.length) {
      await supabase
        .from("conversation_members")
        .delete()
        .eq("user_id", uid)
        .in("conversation_id", conversationIds);
    }
  } catch (e) {
    console.warn("server member kick conversation cleanup failed", e);
  }

  return { ok: true, via: "direct", error: null };
}

function getServerMemberManagementContext(serverId = "", targetUserId = "") {
  const sid = normId(serverId || "");
  const targetId = normId(targetUserId || "");
  const actorId = normId(state.user?.id || "");
  const server = getServerRowById(sid) || { id: sid };
  const members = serverMemberListByServerId.get(sid) || [];
  const roles = getServerRolesForSettingsDisplay(sid);
  const actorMember = getCachedServerMemberForUser(sid, actorId, { serverMembers: members });
  const targetMember = getCachedServerMemberForUser(sid, targetId, { serverMembers: members });
  const actorIsOwner = isServerOwnerUser(server, actorId, actorMember) || !!getServerCapabilityMeta(sid).isOwner || !!getServerCapabilityMeta(sid).isActualOwner;
  const targetIsOwner = isServerOwnerUser(server, targetId, targetMember);
  const actorTopRole = getServerRoleHighestPositionForMember(sid, actorId);
  const targetTopRole = getServerRoleHighestPositionForMember(sid, targetId);
  const actorRank = actorIsOwner ? 0 : getRoleHierarchyRank(actorTopRole);
  const targetRank = targetIsOwner ? 0 : getRoleHierarchyRank(targetTopRole);
  const perms = sid ? getEffectiveServerPermissionsForCurrentUser(sid) : {};
  const isSelf = !!(actorId && targetId && actorId === targetId);
  const targetBelowActor = actorIsOwner
    ? !targetIsOwner || isSelf
    : (!!targetId && !isSelf && !targetIsOwner && Number.isFinite(actorRank) && targetRank > actorRank);
  return {
    serverId: sid,
    actorUserId: actorId,
    targetUserId: targetId,
    actorIsOwner,
    targetIsOwner,
    isSelf,
    actorTopRole,
    targetTopRole,
    actorRank,
    targetRank,
    targetBelowActor,
    permissions: perms,
    canOpenMembers: currentUserCanManageMembers(sid),
    canManageRoles: !!(actorIsOwner || perms.manage_roles === true || perms.manage_server === true),
    canKick: !!(actorIsOwner || perms.kick_members === true || perms.server_kick_members === true),
    canBan: !!(actorIsOwner || perms.ban_members === true || perms.server_ban_members === true),
    canTimeout: !!(actorIsOwner || perms.timeout_members === true || perms.moderate_members === true || perms.manage_server === true),
    canChangeOwnNickname: !!(actorIsOwner || perms.change_nickname === true || perms.manage_nicknames === true),
    canManageNicknames: !!(actorIsOwner || perms.manage_nicknames === true),
    roles,
    members,
  };
}

function canCurrentUserManageMemberRoles(serverId = "", targetUserId = "") {
  const ctx = getServerMemberManagementContext(serverId, targetUserId);
  if (!ctx.serverId || !ctx.targetUserId || ctx.isSelf || ctx.targetIsOwner) return false;
  return !!(ctx.canManageRoles && (ctx.actorIsOwner || ctx.targetBelowActor));
}

function canCurrentUserKickServerMember(serverId = "", targetUserId = "") {
  const ctx = getServerMemberManagementContext(serverId, targetUserId);
  if (!ctx.serverId || !ctx.targetUserId || ctx.isSelf || ctx.targetIsOwner) return false;
  return !!(ctx.canKick && (ctx.actorIsOwner || ctx.targetBelowActor));
}

function canCurrentUserBanServerMember(serverId = "", targetUserId = "") {
  const ctx = getServerMemberManagementContext(serverId, targetUserId);
  if (!ctx.serverId || !ctx.targetUserId || ctx.isSelf || ctx.targetIsOwner) return false;
  return !!(ctx.canBan && (ctx.actorIsOwner || ctx.targetBelowActor));
}

function canCurrentUserTimeoutServerMember(serverId = "", targetUserId = "") {
  const ctx = getServerMemberManagementContext(serverId, targetUserId);
  if (!ctx.serverId || !ctx.targetUserId || ctx.isSelf || ctx.targetIsOwner) return false;
  return !!(ctx.canTimeout && (ctx.actorIsOwner || ctx.targetBelowActor));
}

function getServerNicknameActionState(serverId = "", targetUserId = "") {
  const sid = normId(serverId || "");
  const uid = normId(targetUserId || "");
  const actorId = normId(state.user?.id || "");
  const context = getServerMemberManagementContext(sid, uid);
  const member = getCachedServerMemberForUser(sid, uid)
    || (serverBotInstallListByServerId.get(sid) || []).find((row) => normId(row?.userId || row?.botId || "") === uid)
    || null;
  const permissionResolved = !!(
    serverRolePermissionCacheFetchedAtByServerId.has(sid)
    || getServerCapabilityMeta(sid).isOwner
    || getServerCapabilityMeta(sid).isActualOwner
  );
  const isSelf = !!(actorId && uid && actorId === uid);
  const isBot = member?.isBot === true || member?.bot === true;
  const canChangeOwn = currentUserCanChangeOwnServerNickname(sid);
  const canManage = currentUserCanManageServerNicknames(sid);
  let allowed = false;
  let reason = "";
  if (!sid || !uid) reason = "invalid_target";
  else if (!permissionResolved) reason = "permission_loading";
  else if (isBot) reason = "managed_bot_nickname_locked";
  else if (isSelf) {
    allowed = canChangeOwn;
    if (!allowed) reason = "missing_change_nickname";
  } else if (context.targetIsOwner) {
    reason = "target_is_owner";
  } else if (!canManage) {
    reason = "missing_manage_nicknames";
  } else if (!(context.actorIsOwner || context.targetBelowActor)) {
    reason = "role_hierarchy_blocked";
  } else {
    allowed = true;
  }
  return {
    serverId: sid,
    targetUserId: uid,
    actorUserId: actorId,
    permissionResolved,
    isSelf,
    isBot,
    canChangeOwn,
    canManage,
    allowed,
    reason,
    hierarchy: {
      actorIsOwner: context.actorIsOwner,
      targetIsOwner: context.targetIsOwner,
      actorRank: context.actorRank,
      targetRank: context.targetRank,
      targetBelowActor: context.targetBelowActor,
    },
  };
}

function canCurrentUserAssignServerRoleToMember(serverId = "", targetUserId = "", roleId = "") {
  const sid = normId(serverId || "");
  const rid = normId(roleId || "");
  if (!sid || !rid || !canCurrentUserManageMemberRoles(sid, targetUserId)) return false;
  const role = (serverRoleListByServerId.get(sid) || []).find((entry) => normId(entry?.id || "") === rid) || null;
  if (!role || isDefaultServerRole(role) || isManagedServerRole(role) || isVirtualServerRole(role)) return false;
  const ctx = getServerMemberManagementContext(sid, targetUserId);
  if (ctx.actorIsOwner) return true;
  const roleRank = getRoleHierarchyRank(role);
  return Number.isFinite(ctx.actorRank) && Number.isFinite(roleRank) && roleRank > ctx.actorRank;
}

async function setServerRoleMembershipForServer(serverId, {
  roleId = "",
  userId = "",
  enabled = false,
} = {}) {
  const sid = normId(serverId);
  const rid = normId(roleId);
  const uid = normId(userId);
  if (!sid || !rid || !uid) return { data: null, error: { message: "server_id, role_id ou user_id invalido" } };
  const current = getServerMemberRoleIds(sid, uid);
  const next = new Set(current);
  if (enabled) next.add(rid);
  else next.delete(rid);
  return setServerMemberRolesForServer(sid, {
    targetUserId: uid,
    roleIds: Array.from(next),
  });
}

async function setServerMemberRolesForServer(serverId, {
  targetUserId = "",
  roleIds = [],
} = {}) {
  const sid = normId(serverId);
  const uid = normId(targetUserId);
  const ids = normalizeUuidArray(roleIds);
  if (!sid || !uid) return { data: null, error: { message: "server_id/user_id invalido" } };
  if (!canCurrentUserManageMemberRoles(sid, uid)) {
    return { data: null, error: { message: "You don't have permission to manage this member's roles." } };
  }
  const blockedRole = ids.find((rid) => !canCurrentUserAssignServerRoleToMember(sid, uid, rid));
  if (blockedRole) {
    return { data: null, error: { message: "You can only assign roles below your highest role." } };
  }
  return supabase.rpc("set_server_member_roles_v2", {
    p_server_id: sid,
    p_target_user_id: uid,
    p_role_ids: ids,
  });
}

async function kickServerMemberFromServerV2(serverId, {
  targetUserId = "",
  reason = "",
} = {}) {
  const sid = normId(serverId);
  const uid = normId(targetUserId);
  if (!sid || !uid) return { data: null, error: { message: "server_id/user_id invalido" } };
  if (!canCurrentUserKickServerMember(sid, uid)) {
    return { data: null, error: { message: "You don't have permission to kick this member." } };
  }
  const reasonText = String(reason || "").trim().slice(0, 280);
  return supabase.rpc("kick_server_member_v2", {
    p_server_id: sid,
    p_target_user_id: uid,
    p_reason: reasonText || null,
  });
}

