function normalizeServerProfileUpdatePayload(serverId = "", payload = {}) {
  const sid = normId(payload?.serverId || payload?.server_id || serverId || "");
  if (!sid) return null;
  const explicitBannerClear = hasExplicitBannerClear(payload);
  const explicitBannerSetUrl = getExplicitBannerSetUrl(payload);
  const hasBannerValue = typeof payload?.bannerUrl !== "undefined"
    || typeof payload?.banner_url !== "undefined"
    || typeof payload?.serverBannerUrl !== "undefined"
    || typeof payload?.server_banner_url !== "undefined"
    || explicitBannerClear;
  return {
    type: "server_profile_updated",
    serverId: sid,
    name: typeof payload?.name !== "undefined" ? normalizeConversationLabel(payload.name || "Server", "Server") : undefined,
    iconUrl: typeof payload?.iconUrl !== "undefined" || typeof payload?.icon_url !== "undefined"
      ? sanitizeServerIconUrl(payload?.iconUrl || payload?.icon_url || "")
      : undefined,
    bannerUrl: hasBannerValue
      ? (explicitBannerClear ? "" : explicitBannerSetUrl)
      : undefined,
    bannerRemoved: explicitBannerClear,
    hasBanner: hasBannerValue ? !explicitBannerClear && !!explicitBannerSetUrl : undefined,
    welcomeChannelId: normId(payload?.welcomeChannelId || payload?.welcome_channel_id || ""),
    sourceUserId: normId(payload?.sourceUserId || payload?.source_user_id || ""),
    updatedAt: payload?.updatedAt || payload?.updated_at || new Date().toISOString(),
  };
}

function applyServerProfileUpdate(serverId = "", payload = {}, { source = "broadcast", repreview = true } = {}) {
  const update = normalizeServerProfileUpdatePayload(serverId, payload);
  if (!update?.serverId) return false;
  const sid = update.serverId;
  lastServerProfileUpdateAtByServerId.set(sid, Date.now());
  lastServerProfileBroadcastPayload = { ...update, source, receivedAt: new Date().toISOString() };
  if (update.bannerRemoved) {
    lastServerBannerClearAtByServerId.set(sid, Date.now());
    lastServerBannerSetByServerId.delete(sid);
  }
  else if (typeof update.bannerUrl !== "undefined" && update.bannerUrl) {
    lastServerBannerSetByServerId.set(sid, { url: update.bannerUrl, at: Date.now() });
    lastServerBannerClearAtByServerId.delete(sid);
    logServerProfileBannerDebug("explicit set received", { serverId: sid, bannerUrl: update.bannerUrl, source });
  }
  const row = getServerRowById(sid);
  if (row) {
    if (typeof update.name !== "undefined") row.name = update.name;
    if (typeof update.iconUrl !== "undefined") row.iconUrl = update.iconUrl;
    if (typeof update.bannerUrl !== "undefined") row.bannerUrl = update.bannerUrl;
    if (update.welcomeChannelId) row.welcomeConversationId = update.welcomeChannelId;
  }
  const activeCtx = typeof getActiveServerContext === "function" ? getActiveServerContext() : null;
  const activeSid = normId(activeCtx?.serverId || state.activeDm?.serverId || "");
  if (activeSid === sid && state.activeDm) {
    if (typeof update.name !== "undefined") {
      state.activeDm.serverName = update.name;
      state.activeDm.displayName = update.name;
    }
    if (typeof update.iconUrl !== "undefined") state.activeDm.avatarUrl = update.iconUrl;
    if (update.welcomeChannelId) state.activeDm.welcomeConversationId = update.welcomeChannelId;
  }
  if (normId(serverSettingsServerId || "") === sid) {
    if (typeof update.name !== "undefined") serverSettingsName = update.name;
    if (typeof update.iconUrl !== "undefined" && !serverSettingsIconFile && !serverSettingsIconRemoved) {
      serverSettingsIconUrl = update.iconUrl;
      renderServerSettingsIconPreview();
    }
    if (typeof update.bannerUrl !== "undefined" && !serverSettingsBannerFile && !serverSettingsBannerRemoved) {
      serverSettingsBannerUrl = update.bannerUrl;
      renderServerSettingsBannerPreview();
    }
  }
  renderGroupsRail();
  if (activeSid === sid) {
    void refreshServerConversationUi({
      force: false,
      reason: `server-profile-update:${source}`,
      refreshChannels: false,
      refreshMembers: false,
    }).catch(() => {});
  }
  applyServerProfilePatchToInviteCards(sid, update, { repreview, reason: `server-profile-update:${source}` });
  return true;
}

