async function confirmCurrentUserRemovalFromServer(serverId = "", { reason = "member_removed", source = "target_broadcast", payload = null } = {}) {
  const sid = normId(serverId || "");
  const uid = normId(state.user?.id || "");
  if (!sid || !uid) return false;
  const { data, error } = await supabase
    .from("server_members")
    .select("user_id")
    .eq("server_id", sid)
    .eq("user_id", uid)
    .maybeSingle();
  if (!error && normId(data?.user_id || "") === uid) {
    console.warn("[server-members] target removal broadcast ignored; membership still exists", { serverId: sid, reason, source });
    return false;
  }
  if (error) {
    console.warn("[server-members] target removal membership confirmation failed; evicting locally", { serverId: sid, message: error?.message || error });
  }
  lastTargetEvictionEvent = {
    serverId: sid,
    userId: uid,
    reason,
    source,
    at: new Date().toISOString(),
    confirmationError: error?.message || null,
  };
  await handleServerMemberRemoved({
    serverId: sid,
    userId: uid,
    actorUserId: payload?.actorUserId || payload?.actor_user_id || "",
    serverName: payload?.serverName || payload?.server_name || "",
    reason,
    source,
  });
  return true;
}

function syncServerMemberRemovalBroadcastSubscriptions() {
  if (!state.user?.id) return;
  const wanted = new Set((state.servers || []).map((row) => normId(row?.serverId || "")).filter(Boolean));
  for (const [sid, channel] of Array.from(serverMemberRemovalBroadcastChannels.entries())) {
    if (wanted.has(sid)) continue;
    try { supabase.removeChannel(channel); } catch (_) {}
    serverMemberRemovalBroadcastChannels.delete(sid);
  }
  wanted.forEach((sid) => {
    if (serverMemberRemovalBroadcastChannels.has(sid)) return;
    const channelName = getServerMemberBroadcastChannelName(sid);
    const channel = supabase.channel(channelName, { config: { broadcast: { self: false } } })
      .on("broadcast", { event: "server_member_joined" }, (event) => {
        const payload = event?.payload || {};
        lastMemberJoinedBroadcastReceivedAt = Date.now();
        serverMembersDebugLog("[server-members] join broadcast received", { serverId: sid, payload });
        void handleServerMemberJoined({
          serverId: payload.serverId || payload.server_id || sid,
          userId: payload.userId || payload.user_id || "",
          row: payload.row || null,
          reason: payload.reason || "member_joined",
          source: "broadcast",
        });
      })
      .on("broadcast", { event: "server_member_removed" }, (event) => {
        const payload = event?.payload || {};
        const reason = payload.reason || "member_removed";
        void handleServerMemberRemoved({
          serverId: payload.serverId || payload.server_id || sid,
          userId: payload.userId || payload.user_id || "",
          actorUserId: payload.actorUserId || payload.actor_user_id || "",
          serverName: payload.serverName || payload.server_name || "",
          reason,
          source: "broadcast",
        });
        if (reason === "ban" && normId(serverSettingsServerId || "") === sid) {
          serverSettingsModerationLastRealtimeEvent = { type: "server_ban_added", serverId: sid, userId: payload.userId || payload.user_id || "", source: "server_members_broadcast", at: Date.now() };
          void loadServerSettingsBansBestEffort(sid, { force: true });
        }
      })
      .on("broadcast", { event: "server_timeout_updated" }, (event) => {
        const payload = event?.payload || {};
        lastServerTimeoutBroadcastEvent = { received: true, serverId: sid, payload, at: Date.now() };
        applyServerTimeoutRealtimePayload(payload, { source: "server_members_broadcast" });
      })
      .on("broadcast", { event: "server_moderation_updated" }, (event) => {
        const payload = event?.payload || {};
        serverSettingsModerationLastRealtimeEvent = { received: true, serverId: sid, payload, at: Date.now() };
        if (normId(serverSettingsServerId || "") === sid) {
          void loadServerSettingsModerationBestEffort(sid, { force: true });
        }
      })
      .subscribe();
    serverMemberRemovalBroadcastChannels.set(sid, channel);
  });
}

function getWantedServerProfileSubscriptionIds() {
  const wanted = new Set((state.servers || []).map((row) => normId(row?.serverId || "")).filter(Boolean));
  document.querySelectorAll(".dmServerInviteCard[data-invite-server-id]").forEach((card) => {
    const sid = normId(card.getAttribute("data-invite-server-id") || "");
    if (sid) wanted.add(sid);
  });
  for (const preview of serverInvitePreviewStateByCode.values()) {
    const sid = normId(preview?.serverId || "");
    if (sid) wanted.add(sid);
  }
  return wanted;
}

function syncServerProfileBroadcastSubscriptions() {
  if (!state.user?.id) return;
  const wanted = getWantedServerProfileSubscriptionIds();
  for (const [sid, channel] of Array.from(serverProfileBroadcastChannels.entries())) {
    if (wanted.has(sid)) continue;
    try { supabase.removeChannel(channel); } catch (_) {}
    serverProfileBroadcastChannels.delete(sid);
  }
  wanted.forEach((sid) => {
    if (serverProfileBroadcastChannels.has(sid)) return;
    const channelName = getServerProfileBroadcastChannelName(sid);
    if (!channelName) return;
    const channel = supabase.channel(channelName, { config: { broadcast: { self: false } } })
      .on("broadcast", { event: "server_profile_updated" }, (event) => {
        const payload = event?.payload || {};
        lastServerProfileBroadcastReceivedAt = Date.now();
        if (isServerProfileDebugEnabled()) console.info("[server-profile] profile broadcast received", { serverId: sid, payload });
        applyServerProfileUpdate(payload.serverId || payload.server_id || sid, payload, {
          source: "broadcast",
          repreview: true,
        });
      })
      .subscribe((status) => {
        if (isServerProfileDebugEnabled() && !["SUBSCRIBED"].includes(String(status || ""))) {
          console.info("[server-profile] profile channel status", { serverId: sid, status });
        }
      });
    serverProfileBroadcastChannels.set(sid, channel);
  });
}

function syncUserMembershipBroadcastSubscription() {
  const uid = normId(state.user?.id || "");
  const channelName = getUserMembershipBroadcastChannelName(uid);
  if (!uid || !channelName) {
    if (userMembershipBroadcastChannel) {
      try { supabase.removeChannel(userMembershipBroadcastChannel); } catch (_) {}
    }
    userMembershipBroadcastChannel = null;
    userMembershipBroadcastChannelName = "";
    return null;
  }
  if (userMembershipBroadcastChannel && userMembershipBroadcastChannelName === channelName) {
    return userMembershipBroadcastChannel;
  }
  if (userMembershipBroadcastChannel) {
    try { supabase.removeChannel(userMembershipBroadcastChannel); } catch (_) {}
  }
  userMembershipBroadcastChannelName = channelName;
  userMembershipBroadcastChannel = supabase.channel(channelName, { config: { broadcast: { self: false } } })
    .on("broadcast", { event: "server_member_removed" }, (event) => {
      const payload = event?.payload || {};
      const sid = normId(payload.serverId || payload.server_id || "");
      const uidFromPayload = normId(payload.userId || payload.user_id || "");
      if (!sid || (uidFromPayload && uidFromPayload !== uid)) return;
      void confirmCurrentUserRemovalFromServer(sid, {
        reason: payload.reason || "member_removed",
        source: "user_membership_broadcast",
        payload,
      });
    })
    .subscribe();
  return userMembershipBroadcastChannel;
}

function stopServerMembershipEventsRealtime() {
  if (serverMembershipEventsChannel) {
    try { supabase.removeChannel(serverMembershipEventsChannel); } catch (_) {}
  }
  serverMembershipEventsChannel = null;
  serverMembershipEventsChannelState = "stopped";
}

function startServerMembershipEventsRealtime() {
  if (!state.user?.id) {
    stopServerMembershipEventsRealtime();
    return null;
  }
  if (serverMembershipEventsChannel) return serverMembershipEventsChannel;
  serverMembershipEventsChannelState = "starting";
  serverMembershipEventsChannel = supabase
    .channel("server-membership-events:" + state.user.id)
    .on("postgres_changes", {
      event: "INSERT",
      schema: "public",
      table: "server_membership_events",
    }, (payload) => {
      const row = payload?.new || {};
      const sid = normId(row?.server_id || "");
      const uid = normId(row?.user_id || "");
      const eventType = String(row?.event_type || "").trim().toLowerCase();
      if (!sid || !uid) return;
      lastMembershipEventReceivedAt = Date.now();
      lastMembershipEvent = {
        serverId: sid,
        userId: uid,
        actorUserId: normId(row?.actor_user_id || ""),
        eventType,
        reason: String(row?.reason || "").trim(),
        createdAt: row?.created_at || "",
        receivedAt: lastMembershipEventReceivedAt,
      };
      serverMembersDebugLog("[server-members] membership event received", lastMembershipEvent);
      if (eventType === "member_joined") {
        void handleServerMemberJoined({
          serverId: sid,
          userId: uid,
          row: {
            ...(row || {}),
            server_id: sid,
            user_id: uid,
            role: row?.role || "member",
            joined_at: row?.created_at || new Date().toISOString(),
          },
          reason: row?.reason || "member_joined",
          source: "membership_events_insert",
        });
      } else if (eventType === "member_removed") {
        void handleServerMemberRemoved({
          serverId: sid,
          userId: uid,
          actorUserId: row?.actor_user_id || "",
          reason: row?.reason || "remove",
          source: "membership_events_insert",
        });
      }
    })
    .subscribe((status) => {
      serverMembershipEventsChannelState = String(status || "");
      if (status === "SUBSCRIBED") return;
      if (!["CHANNEL_ERROR", "TIMED_OUT", "CLOSED"].includes(String(status || ""))) return;
      console.warn("[server-members] membership events realtime issue", { status });
    });
  return serverMembershipEventsChannel;
}

async function verifyCurrentUserServerMembership(serverId = "", { source = "membership_check" } = {}) {
  const sid = normId(serverId || "");
  const uid = normId(state.user?.id || "");
  if (!sid || !uid) return { ok: false, checked: false };
  const isTrackedServer = (state.servers || []).some((row) => normId(row?.serverId || "") === sid);
  if (!isTrackedServer) return { ok: false, checked: false, reason: "not_tracked" };
  const { data, error } = await supabase
    .from("server_members")
    .select("user_id")
    .eq("server_id", sid)
    .eq("user_id", uid)
    .maybeSingle();
  if (error) {
    console.warn("[server-members] membership check failed", { serverId: sid, message: error?.message || error });
    return { ok: false, checked: true, error };
  }
  if (!data?.user_id) {
    await handleServerMemberRemoved({
      serverId: sid,
      userId: uid,
      reason: "membership_check",
      source,
    });
    return { ok: true, checked: true, currentUserIsMember: false };
  }
  return { ok: true, checked: true, currentUserIsMember: true };
}

function getActiveOrVisibleServerIdForMembershipCheck() {
  return normId(getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
}

function bindServerMembershipRemovalFallbacks() {
  if (bindServerMembershipRemovalFallbacks.bound) return;
  bindServerMembershipRemovalFallbacks.bound = true;
  window.addEventListener("focus", () => {
    const sid = getActiveOrVisibleServerIdForMembershipCheck();
    if (sid) void verifyCurrentUserServerMembership(sid, { source: "window_focus" });
  });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState !== "visible") return;
    const sid = getActiveOrVisibleServerIdForMembershipCheck();
    if (sid) void verifyCurrentUserServerMembership(sid, { source: "visibilitychange" });
  });
}
bindServerMembershipRemovalFallbacks.bound = false;
bindServerMembershipRemovalFallbacks();

async function banServerMemberFromServer(serverId, userId, { reason = "" } = {}) {
  const sid = normId(serverId);
  const uid = normId(userId);
  if (!sid || !uid) return { ok: false, error: { message: "server_id/user_id invalido" }, banStored: false };
  if (!canCurrentUserBanServerMember(sid, uid)) {
    return { ok: false, error: { message: "You don't have permission to ban this member." }, banStored: false };
  }

  const reasonText = String(reason || "").trim().slice(0, 280);
  const res = await supabase.rpc("ban_server_member_v2", {
    p_server_id: sid,
    p_target_user_id: uid,
    p_reason: reasonText || null,
  });
  if (res?.error) {
    return { ok: false, error: res.error, banStored: false };
  }
  return { ok: true, via: "ban_server_member_v2", data: res.data || null, error: null, banStored: true };
}

async function listServerRolesForServer(serverId) {
  const sid = normId(serverId);
  if (!sid) return { rows: [], error: { message: "server_id invalido" } };

  const payloads = [
    { p_server_id: sid },
    { server_id: sid },
  ];
  let lastMissingErr = null;
  let lastRpcErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("list_server_roles", payload);
    if (!res?.error) {
      return { rows: Array.isArray(res.data) ? res.data : [], error: null };
    }
    if (!isMissingRpcError(res.error)) {
      lastRpcErr = res.error;
      break;
    }
    lastMissingErr = res.error;
  }

  const directVariants = [
    { select: "id, server_id, name, color, position, created_at, permissions, is_managed, managed_by_bot_id, managed_kind, managed_metadata, is_default", order: "position" },
    { select: "id, server_id, name, color, role_position, created_at, permissions, is_managed, managed_by_bot_id, managed_kind, managed_metadata, is_default", order: "role_position" },
    { select: "id, server_id, name, color, position, created_at, permissions", order: "position" },
    { select: "id, server_id, name, color, role_position, created_at, permissions", order: "role_position" },
    { select: "id, server_id, name, color, position, created_at", order: "position" },
    { select: "id, server_id, name, color, role_position, created_at", order: "role_position" },
  ];
  let lastDirectError = null;
  for (const variant of directVariants) {
    let query = supabase
      .from("server_roles")
      .select(variant.select)
      .eq("server_id", sid);
    query = query.order(variant.order, { ascending: true }).order("created_at", { ascending: true });
    const { data, error } = await query;
    if (!error) {
      const rows = (Array.isArray(data) ? data : []).map((row) => {
        const normalized = { ...(row || {}) };
        if (typeof normalized.position === "undefined" && typeof normalized.role_position !== "undefined") {
          normalized.position = normalized.role_position;
        }
        return normalized;
      });
      return { rows, error: null };
    }
    lastDirectError = error;
    if (!isMissingColumnError(error, "permissions")
        && !isMissingColumnError(error, "position")
        && !isMissingColumnError(error, "role_position")
        && !isMissingColumnError(error, "is_managed")
        && !isMissingColumnError(error, "managed_by_bot_id")
        && !isMissingColumnError(error, "managed_kind")
        && !isMissingColumnError(error, "managed_metadata")
        && !isMissingColumnError(error, "is_default")) {
      break;
    }
  }

  const error = lastDirectError || lastRpcErr || lastMissingErr;
  if (error) {
    if (!lastMissingErr || !isMissingTableError(error, "server_roles")) {
      return { rows: [], error };
    }
    return { rows: [], error: lastMissingErr };
  }
  return { rows: [], error: null };
}

async function listServerRoleMembersForServer(serverId) {
  const sid = normId(serverId);
  if (!sid) return { rows: [], error: { message: "server_id invalido" } };

  const payloads = [
    { p_server_id: sid },
    { server_id: sid },
  ];
  let lastMissingErr = null;
  let lastRpcErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("list_server_role_members", payload);
    if (!res?.error) {
      return { rows: Array.isArray(res.data) ? res.data : [], error: null };
    }
    if (!isMissingRpcError(res.error)) {
      lastRpcErr = res.error;
      break;
    }
    lastMissingErr = res.error;
  }

  const { data, error } = await supabase
    .from("server_role_members")
    .select("role_id, user_id, assigned_at")
    .eq("server_id", sid);
  if (error) {
    if (!lastMissingErr || !isMissingTableError(error, "server_role_members")) {
      return { rows: [], error };
    }
    return { rows: [], error: lastMissingErr };
  }
  return { rows: Array.isArray(data) ? data : [], error: null };
}

// Batch 0A correction pass: role creation is now RPC-only. The previous
// browser-side direct INSERT into public.server_roles (used whenever every
// payload shape below reported the RPC as missing) has been removed -- it
// bypassed create_server_role's owner/manage_roles authorization, name/color
// validation, and permission sanitization entirely, writing an unvalidated
// row straight to the table. If the RPC is genuinely unavailable (the SQL
// patch has not been applied), this now returns that error directly; the
// caller (submitServerSettingsRoleCreate) already shows a concrete
// "Missing SQL patch" message for isMissingRpcError(error), releases its own
// mutation lock (serverSettingsRolesMutating) unconditionally right after
// this call resolves, and never touches the cached role-list snapshot on the
// error path -- so no duplicate role can be created and the last-known-good
// snapshot is retained automatically.
async function createServerRoleForServer(serverId, {
  name = "",
  color = SERVER_ROLE_DEFAULT_COLOR,
  permissions = {},
} = {}) {
  const sid = normId(serverId);
  const roleName = normalizeServerRoleName(name);
  const roleColor = normalizeServerRoleColor(color);
  const rolePermissions = normalizeServerRolePermissions(permissions || {}, { name: roleName });
  if (!sid || !roleName) return { row: null, error: { message: "server_id ou role name invalido" }, warning: null };

  const payloads = [
    { p_server_id: sid, p_name: roleName, p_color: roleColor, p_permissions: rolePermissions },
    { p_server_id: sid, p_name: roleName, p_color: roleColor },
    { server_id: sid, name: roleName, color: roleColor },
  ];
  let lastMissingErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("create_server_role", payload);
    if (!res?.error) {
      const rows = Array.isArray(res.data) ? res.data : (res.data ? [res.data] : []);
      return { row: rows[0] || null, error: null, warning: null };
    }
    if (!isMissingRpcError(res.error)) {
      return { row: null, error: res.error, warning: null };
    }
    lastMissingErr = res.error;
  }

  return { row: null, error: lastMissingErr || { message: "create_server_role_rpc_unavailable" }, warning: null };
}

// Batch 0A: restored -- the Delete Role button (submitServerSettingsRoleDelete,
// which awaits this at its call site) called this function, but its
// definition had been removed from app.js while the call site was kept,
// so deleting a role threw a ReferenceError. Deliberately RPC-only, no
// raw-table-delete fallback: the RPC now enforces the canonical permission +
// hierarchy + managed/default-role checks (see
// supabase/manual_patches/2026-07-27_server_permissions_batch0a_hardening_v1.sql),
// and a client-side fallback would bypass all of that.
async function deleteServerRoleForServer(serverId, roleId) {
  const sid = normId(serverId);
  const rid = normId(roleId);
  if (!sid || !rid) return { error: { message: "server_id ou role_id invalido" } };

  const payloads = [
    { p_server_id: sid, p_role_id: rid },
    { server_id: sid, role_id: rid },
  ];
  let lastMissingErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("delete_server_role", payload);
    if (!res?.error) return { error: null };
    if (!isMissingRpcError(res.error)) return { error: res.error };
    lastMissingErr = res.error;
  }
  return { error: lastMissingErr || { message: "delete_server_role_rpc_unavailable" } };
}

async function reorderServerRolesForServer(serverId, orderedRoleIds = []) {
  const sid = normId(serverId);
  const ids = (orderedRoleIds || []).map(normId).filter(Boolean);
  if (!sid || !ids.length) return { rows: [], error: { message: "server_id/role order invalido" }, needsPatch: false };

  const payloads = [
    { p_server_id: sid, p_ordered_role_ids: ids },
    { server_id: sid, ordered_role_ids: ids },
  ];
  let lastMissingErr = null;
  let lastRpcErr = null;
  for (const payload of payloads) {
    const res = await supabase.rpc("server_roles_reorder", payload);
    if (!res?.error) {
      const rows = Array.isArray(res.data) ? res.data : (res.data ? [res.data] : []);
      return { rows, error: null, needsPatch: false };
    }
    if (!isMissingRpcError(res.error)) return { rows: [], error: res.error, needsPatch: false };
    lastMissingErr = res.error;
  }

  return {
    rows: [],
    error: lastMissingErr || { message: "server_roles_reorder RPC missing" },
    needsPatch: true,
  };
}

function getServerRoleReorderSafeError(error = null) {
  if (!error) return null;
  return {
    code: String(error?.code || ""),
    message: String(error?.message || error || "role_reorder_failed"),
    details: String(error?.details || ""),
    hint: String(error?.hint || ""),
  };
}

function getServerRoleReorderErrorMessage(error = null) {
  const text = [
    error?.message,
    error?.details,
    error?.hint,
    error?.code,
  ].map((value) => String(value || "").trim()).filter(Boolean).join(" ").toLowerCase();
  if (/role_hierarchy_reorder_denied|admin_highest_role_required/.test(text)) {
    return "You cannot move a role at or above your highest role.";
  }
  if (/everyone_role_cannot_move|default role/.test(text)) {
    return "@everyone must remain at the bottom.";
  }
  if (/missing_manage_roles|not_server_member|auth_required/.test(text)) {
    return "You do not have permission to reorder these roles.";
  }
  if (/role_order_must_include_all_roles|duplicate_role_ids|role_not_in_server/.test(text)) {
    return "The role list changed while you were reordering it. Try again.";
  }
  return "Could not save role order. Try again.";
}

function rollbackServerSettingsRoleOrder(serverId = "", {
  roles = null,
  reason = "reorder_failed",
} = {}) {
  const sid = normId(serverId || "");
  if (!sid) return false;
  const rollbackRoles = Array.isArray(roles) && roles.length
    ? roles
    : serverSettingsRoleOriginalOrder;
  if (Array.isArray(rollbackRoles) && rollbackRoles.length) {
    serverRoleListByServerId.set(sid, cloneServerRoleListForOrder(rollbackRoles));
  }
  serverSettingsRoleOrderDirty = false;
  serverSettingsPendingRoleOrderUpdates = [];
  serverSettingsRoleLastRollbackReason = String(reason || "reorder_failed");
  logServerRolesEvent("reorder_rollback", {
    serverId: sid,
    order: getPersistableRoleOrderIdsForServer(sid),
    error: reason,
  });
  return true;
}

async function readServerRoleOrderAuthoritatively(serverId = "") {
  const sid = normId(serverId || "");
  const response = await listServerRolesForServer(sid);
  if (response?.error) {
    return {
      roles: [],
      orderedRoleIds: [],
      error: response.error,
      duplicateEveryoneCount: 0,
    };
  }
  const currentById = new Map(
    (serverRoleListByServerId.get(sid) || [])
      .map((role) => [normId(role?.id || ""), role])
      .filter(([id]) => id),
  );
  const roles = sortServerRolesForHierarchy(
    (response?.rows || []).map(normalizeServerRoleRow).filter(Boolean).map((role) => {
      const current = currentById.get(normId(role?.id || "")) || null;
      return current
        ? {
          ...current,
          ...role,
          permissions: role?.permissions && Object.keys(role.permissions).length
            ? role.permissions
            : current.permissions,
        }
        : role;
    }),
    { serverId: sid },
  );
  const orderedRoleIds = roles
    .filter((role) => normId(role?.id || "") && !isDefaultServerRole(role))
    .map((role) => normId(role.id));
  const duplicateEveryoneCount = Math.max(
    0,
    roles.filter(isDefaultServerRole).length - 1,
  );
  const positionCounts = new Map();
  roles.forEach((role) => {
    const position = getServerRolePosition(role, 0);
    if (!Number.isFinite(position) || position <= 0) return;
    positionCounts.set(position, Number(positionCounts.get(position) || 0) + 1);
  });
  const positionCollisions = Array.from(positionCounts.entries())
    .filter(([, count]) => count > 1)
    .map(([position, count]) => ({ position, count }));
  return {
    roles,
    orderedRoleIds,
    error: null,
    duplicateEveryoneCount,
    positionCollisions,
  };
}

async function submitServerSettingsRoleOrderSave({ silent = false } = {}) {
  const sid = normId(serverSettingsServerId || "");
  if (!sid || !serverSettingsRoleOrderDirty) return true;
  if (serverSettingsRolesError) {
    if (!silent) setServerSettingsRolesMeta(serverSettingsRolesError, { error: true });
    renderServerSettingsRolesUi();
    return false;
  }
  if (!canReorderServerRolesInSettings(sid)) {
    const err = { message: "You do not have permission to reorder these roles." };
    serverSettingsRoleLastReorderError = err;
    rollbackServerSettingsRoleOrder(sid, {
      reason: "role_reorder_permission_unresolved_or_denied",
    });
    if (!silent) setServerSettingsRolesMeta(err.message, { error: true });
    renderServerSettingsRolesUi();
    return false;
  }

  const orderedRoleIds = getPersistableRoleOrderIdsForServer(sid);
  const pendingUpdates = getPendingServerRoleOrderUpdatesForServer(sid);
  if (!pendingUpdates.length) {
    const { updates } = reindexServerRolePositions(serverRoleListByServerId.get(sid) || []);
    serverSettingsPendingRoleOrderUpdates = updates;
  }
  const updatesToSave = getPendingServerRoleOrderUpdatesForServer(sid);
  const actorHighestPosition = getServerRoleHierarchyLimitForCurrentUser(sid);
  serverSettingsRoleLastReorderPayload = {
    serverId: sid,
    actorId: normId(state.user?.id || ""),
    actorIsCanonicalOwner: isServerActualOwner(sid),
    actorHighestPosition: Number.isFinite(actorHighestPosition) ? actorHighestPosition : null,
    visualOrder: getServerRoleOrderSnapshot(sid, { includeEveryone: true }),
    orderedRoleIds,
    updates: updatesToSave,
    startedAt: new Date().toISOString(),
  };
  serverSettingsRoleLastReorderResponse = null;
  serverSettingsRoleLastReadback = null;
  serverSettingsRoleLastRollbackReason = "";
  logServerRolesEvent("reorder_save_start", { serverId: sid, order: orderedRoleIds });
  serverSettingsRolesMutating = true;
  if (!silent) setServerSettingsRolesMeta("Saving role order...", { error: false });
  renderServerSettingsRolesUi();

  // Batch 0A correction pass: role reordering is now RPC-only.
  // updateServerRolePositionsForServer (removed) used to be tried FIRST as a
  // raw, per-role `server_roles.update({position})` write with no RPC call at
  // all, protected only by whatever legacy RLS policy governs UPDATE on this
  // table -- it bypassed server_roles_reorder's manage_roles + hierarchy
  // checks entirely, and since it almost always succeeded, the RPC fallback
  // below it was effectively dead/untested code. That fallback also called
  // reorderServerRolesForServer with orderedRoleIds reversed, which does not
  // match the RPC's actual semantics: server_roles_reorder assigns position
  // via row_number() over the array in the order given, so the FIRST id must
  // be the most senior role. getPersistableRoleOrderIdsForServer already
  // returns ids in that exact order (ascending by position, i.e. most senior
  // first), so the array must be passed through unreversed.
  let result = null;
  try {
    result = await reorderServerRolesForServer(sid, orderedRoleIds);
  } catch (error) {
    result = {
      rows: [],
      error,
      needsPatch: false,
    };
  }

  if (normId(serverSettingsServerId || "") !== sid) {
    serverSettingsRolesMutating = false;
    return false;
  }
  if (result?.error) {
    serverSettingsRoleLastReorderError = result.error;
    const message = result.needsPatch
      ? "Missing SQL patch: run SQL/SUPABASE_PATCH_REORDER_SERVER_ROLES.sql"
      : getServerRoleReorderErrorMessage(result.error);
    rollbackServerSettingsRoleOrder(sid, {
      reason: String(result.error?.message || result.error || "role_reorder_failed"),
    });
    if (!silent) setServerSettingsRolesMeta(message, { error: true });
    serverSettingsRoleLastReorderResponse = {
      ok: false,
      needsPatch: result.needsPatch === true,
      error: getServerRoleReorderSafeError(result.error),
    };
    serverSettingsRolesMutating = false;
    logServerRolesEvent("reorder_save_error", { serverId: sid, order: orderedRoleIds, error: result.error });
    renderServerSettingsRolesUi();
    return false;
  }

  const rpcRows = (result?.rows || []).map(normalizeServerRoleRow).filter(Boolean);
  let readback = null;
  try {
    readback = await readServerRoleOrderAuthoritatively(sid);
  } catch (error) {
    readback = {
      roles: [],
      orderedRoleIds: [],
      error,
      duplicateEveryoneCount: 0,
      positionCollisions: [],
    };
  }
  serverSettingsRoleLastReadback = {
    at: Date.now(),
    orderedRoleIds: [...readback.orderedRoleIds],
    duplicateEveryoneCount: Number(readback.duplicateEveryoneCount || 0),
    positionCollisions: Array.isArray(readback.positionCollisions)
      ? readback.positionCollisions.map((entry) => ({ ...entry }))
      : [],
    error: getServerRoleReorderSafeError(readback.error),
  };
  const readbackMatches = !readback.error
    && readback.orderedRoleIds.length === orderedRoleIds.length
    && readback.orderedRoleIds.every((roleId, index) => roleId === orderedRoleIds[index]);
  if (!readbackMatches) {
    const verifyError = readback.error || {
      code: "role_order_readback_mismatch",
      message: "role_order_readback_mismatch",
      details: `submitted=${orderedRoleIds.join(",")} readback=${readback.orderedRoleIds.join(",")}`,
    };
    serverSettingsRoleLastReorderError = verifyError;
    rollbackServerSettingsRoleOrder(sid, {
      roles: readback.roles,
      reason: String(verifyError?.message || "role_order_readback_mismatch"),
    });
    serverSettingsRoleLastReorderResponse = {
      ok: false,
      needsPatch: false,
      error: getServerRoleReorderSafeError(verifyError),
    };
    serverSettingsRolesMutating = false;
    if (!silent) setServerSettingsRolesMeta("Could not verify the saved role order. Try again.", { error: true });
    renderServerSettingsRolesUi();
    return false;
  }
  serverRoleListByServerId.set(sid, readback.roles);
  serverSettingsRoleOrderDirty = false;
  serverSettingsRolesError = "";
  serverSettingsPendingRoleOrderUpdates = [];
  serverSettingsRoleLastReorderPayload = {
    ...serverSettingsRoleLastReorderPayload,
    savedAt: new Date().toISOString(),
  };
  serverSettingsRoleLastReorderResponse = {
    ok: true,
    rpcRowsCount: rpcRows.length,
    submittedOrder: [...orderedRoleIds],
    readbackOrder: [...readback.orderedRoleIds],
    rows: readback.roles.map((role) => ({
      id: normId(role?.id || ""),
      name: role?.name || "",
      position: getServerRolePosition(role, 0),
      isDefault: isDefaultServerRole(role),
    })),
  };
  serverSettingsRoleLastReorderError = null;
  serverSettingsRoleLastReorderAt = Date.now();
  rememberServerSettingsRoleOrderBaseline(sid, readback.roles);
  serverSettingsRolesMutating = false;
  if (!silent) setServerSettingsRolesMeta("Role order saved.", { error: false });
  logServerRolesEvent("reorder_save_done", { serverId: sid, order: orderedRoleIds, saved: true });
  void emitServerPermissionsChangedBroadcast(sid, {
    reason: "role_order_saved",
    changedRoleIds: updatesToSave.map((entry) => normId(entry?.id || entry?.roleId || "")).filter(Boolean),
  });
  scheduleActivePermissionsRefresh("role_order_saved_local", { serverId: sid });
  renderServerSettingsRolesUi();
  return true;
}
async function readServerRolePermissionsRow(serverId, roleId) {
  const sid = normId(serverId);
  const rid = normId(roleId);
  if (!sid || !rid) return null;
  const { data, error } = await supabase
    .from("server_roles")
    .select("id, server_id, name, permissions")
    .eq("server_id", sid)
    .eq("id", rid)
    .maybeSingle();

  if (error) {
    console.error("[server-settings] failed to read role permissions row", {
      serverId: sid,
      roleId: rid,
      message: error?.message,
      details: error?.details,
      hint: error?.hint,
      code: error?.code,
      error,
    });
    throw error;
  }

  return data || null;
}
async function enrichServerRoleRowsWithDirectPermissions(serverId, roleRows = []) {
  const sid = normId(serverId);
  const rows = Array.isArray(roleRows) ? roleRows : [];
  const ids = Array.from(new Set(rows.map((role) => normId(role?.id || role?.role_id || "")).filter(Boolean)));
  if (!sid || !ids.length) return rows;

  const { data, error } = await supabase
    .from("server_roles")
    .select("id, permissions")
    .eq("server_id", sid)
    .in("id", ids);

  if (error) {
    console.warn("[server-settings] failed to enrich role permissions from server_roles", {
      serverId: sid,
      ids,
      message: error?.message,
      details: error?.details,
      hint: error?.hint,
      code: error?.code,
      error,
    });
    return rows;
  }

  const permissionsById = new Map((Array.isArray(data) ? data : []).map((row) => [normId(row?.id || ""), getRawServerRolePermissionsFromRow(row)]).filter(([id]) => id));
  return rows.map((row) => {
    const rid = normId(row?.id || row?.role_id || "");
    const directPermissions = permissionsById.get(rid);
    if (!directPermissions) return row;
    return {
      ...row,
      permissions: directPermissions,
      role_permissions: directPermissions,
    };
  });
}

function rememberConfirmedRolePermissions(roleId, permissions = {}, role = null) {
  const rid = normId(roleId);
  if (!rid) return;
  serverSettingsConfirmedRolePermissions.set(rid, {
    permissions: normalizeServerRolePermissions(permissions || {}, role || getServerSettingsRoleById(rid)),
    confirmedAt: Date.now(),
  });
}

function applyConfirmedRolePermissionsOverlay(roleRows = []) {
  const now = Date.now();
  const rows = Array.isArray(roleRows) ? roleRows : [];
  return rows.map((role) => {
    const rid = normId(role?.id || role?.role_id || "");
    const confirmed = rid ? serverSettingsConfirmedRolePermissions.get(rid) : null;
    if (!confirmed) return role;
    if (now - Number(confirmed.confirmedAt || 0) > 10000) {
      serverSettingsConfirmedRolePermissions.delete(rid);
      return role;
    }
    const normalized = normalizeServerRolePermissions(confirmed.permissions || {}, role);
    return {
      ...role,
      permissions: normalized,
      role_permissions: normalized,
    };
  });
}

function doImplementedRolePermissionsMatch(expected = {}, persisted = {}, role = null) {
  const expectedNormalized = normalizeServerRolePermissions(expected || {}, role);
  const persistedNormalized = normalizeServerRolePermissions(persisted || {}, role);
  return getImplementedServerPermissionKeys().every((key) => Boolean(expectedNormalized[key]) === Boolean(persistedNormalized[key]));
}

// Batch 0A: canonical, RPC-only role-permission persistence. Authenticated
// browser code must never write public.server_roles.permissions directly --
// the raw-table-write fallback this used to fall through to (guarded only by
// the legacy owner/admin RLS check, with no hierarchy or self-escalation
// guard) has been removed now that set_server_role_permissions enforces
// canonical permission + hierarchy + self-escalation checks server-side and
// its sanitizer whitelists every currently-implemented permission key,
// including for the @everyone/default role. If the RPC fails or a save
// can't be verified by readback, this returns an error -- it no longer falls
// back to an insecure direct write.
async function persistServerRolePermissionsViaRpc(sid, rid, normalizedPermissions, role, method = "rpc") {
  const rpcPayloads = [
    { p_server_id: sid, p_role_id: rid, p_permissions: normalizedPermissions },
    { server_id: sid, role_id: rid, permissions: normalizedPermissions },
  ];
  let rpcError = null;
  for (const payload of rpcPayloads) {
    const res = await supabase.rpc("set_server_role_permissions", payload);
    if (!res?.error) {
      try {
        const afterRpc = await readServerRolePermissionsRow(sid, rid);
        if (afterRpc && doImplementedRolePermissionsMatch(normalizedPermissions, afterRpc.permissions || {}, { ...role, permissions: afterRpc.permissions || {} })) {
          rememberConfirmedRolePermissions(rid, afterRpc.permissions || normalizedPermissions, { ...role, permissions: afterRpc.permissions || normalizedPermissions });
          console.info("[server-settings] saved role permissions", { serverId: sid, roleId: rid, roleName: role?.name || "", method });
          return { ok: true, method, row: afterRpc, error: null };
        }
        return { row: null, error: { message: "role_permissions_rpc_verify_failed" } };
      } catch (error) {
        return { row: null, error };
      }
    }
    if (!isMissingRpcError(res.error)) {
      return { row: null, error: res.error };
    }
    rpcError = res.error;
  }
  return { row: null, error: rpcError || { message: "role_permissions_rpc_unavailable" } };
}

async function setDefaultServerRolePermissionsForServer(serverId, roleId, permissions = {}) {
  const sid = normId(serverId);
  const rid = normId(roleId);
  const role = getServerSettingsRoleById(rid, sid);
  if (!sid || !rid) return { row: null, error: { message: "server_id/role_id invalido" } };
  if (!role || !isDefaultServerRole(role)) return { row: null, error: { message: "not_default_role" } };
  if (isVirtualServerRole(role)) return { row: null, error: { message: "virtual_role_not_persistable" } };
  if (isManagedServerRole(role)) return { row: null, error: { message: "managed_role_locked" } };

  const normalizedPermissions = normalizeServerRolePermissions(permissions || {}, role);
  console.info("[server-settings] saving role permissions", { serverId: sid, roleId: rid, roleName: role?.name || "", permissions: normalizedPermissions, method: "default-rpc" });
  const result = await persistServerRolePermissionsViaRpc(sid, rid, normalizedPermissions, role, "default-rpc");
  if (result.error) {
    console.error("[server-settings] failed to save default role permissions", {
      serverId: sid,
      roleId: rid,
      roleName: role?.name || "",
      permissions: normalizedPermissions,
      message: result.error?.message,
      details: result.error?.details,
      hint: result.error?.hint,
      code: result.error?.code,
      error: result.error,
    });
  }
  return result;
}

async function setNormalServerRolePermissionsForServer(serverId, {
  roleId = "",
  permissions = {},
} = {}) {
  const sid = normId(serverId);
  const rid = normId(roleId);
  const role = getServerSettingsRoleById(rid, sid);
  if (!sid || !rid) return { row: null, error: { message: "server_id/role_id invalido" } };
  if (!role) return { row: null, error: { message: "role_missing" } };
  if (isDefaultServerRole(role)) return { row: null, error: { message: "use_default_role_permission_save" } };
  if (isManagedServerRole(role)) return { row: null, error: { message: "managed_role_locked" } };
  if (isVirtualServerRole(role)) return { row: null, error: { message: "virtual_role_not_persistable" } };

  const normalizedPermissions = normalizeServerRolePermissions(permissions || {}, role);
  console.info("[server-settings] saving role permissions", { serverId: sid, roleId: rid, roleName: role?.name || "", permissions: normalizedPermissions });
  const result = await persistServerRolePermissionsViaRpc(sid, rid, normalizedPermissions, role, "rpc");
  if (result.error) {
    console.error("[server-settings] failed to save role permissions", {
      serverId: sid,
      roleId: rid,
      roleName: role?.name || "",
      permissions: normalizedPermissions,
      message: result.error?.message,
      details: result.error?.details,
      hint: result.error?.hint,
      code: result.error?.code,
      error: result.error,
    });
  }
  return result;
}

async function setServerRolePermissionsForServer(serverId, {
  roleId = "",
  permissions = {},
} = {}) {
  const sid = normId(serverId);
  const rid = normId(roleId);
  const role = getServerSettingsRoleById(rid, sid);
  if (!sid || !rid) return { row: null, error: { message: "server_id/role_id invalido" } };
  if (role) {
    if (isManagedServerRole(role)) return { row: null, error: { message: "managed_role_locked" } };
    if (isVirtualServerRole(role)) return { row: null, error: { message: "virtual_role_not_persistable" } };
    if (isDefaultServerRole(role)) return setDefaultServerRolePermissionsForServer(sid, rid, permissions);
  }
  return setNormalServerRolePermissionsForServer(sid, { roleId: rid, permissions });
}
function normalizeServerRoleRow(row = {}) {
  const roleId = normId(row?.id || row?.role_id || "");
  if (!roleId) return null;
  const roleName = normalizeServerRoleName(row?.name || "New role") || "New role";
  const roleColor = normalizeServerRoleColor(row?.color || row?.role_color || SERVER_ROLE_DEFAULT_COLOR);
  const rolePermissionsRaw = getRawServerRolePermissionsFromRow(row);
  const positionRaw = Number(
    typeof row?.position !== "undefined" ? row.position : row?.role_position
  );
  const position = Number.isFinite(positionRaw) ? Math.round(positionRaw) : 0;
  const createdAt = Date.parse(String(row?.created_at || "")) || 0;
  const isManaged = row?.is_managed === true || String(row?.is_managed || row?.isManaged || "").trim().toLowerCase() === "true";
  const managedKind = String(row?.managed_kind || row?.managedKind || "").trim();
  const isDefault = row?.is_default === true
    || row?.is_everyone === true
    || row?.default === true
    || String(row?.is_default || row?.isDefault || row?.is_everyone || row?.isEveryone || row?.default || "").trim().toLowerCase() === "true"
    || String(managedKind || row?.kind || "").trim().toLowerCase() === "default"
    || String(managedKind || "").trim().toLowerCase() === "everyone"
    || roleName.trim().toLowerCase() === "@everyone"
    || roleName.trim().toLowerCase() === "everyone"
    || roleName.trim().toLowerCase() === "default";
  const normalizedRolePermissions = normalizeServerRolePermissions(rolePermissionsRaw, {
    id: roleId,
    name: roleName,
    isDefault,
    is_default: isDefault,
    managedKind,
    managed_kind: managedKind,
  });
  return {
    id: roleId,
    name: roleName,
    color: roleColor,
    permissions: normalizedRolePermissions,
    role_permissions: normalizedRolePermissions,
    position,
    role_position: position,
    isManaged,
    isDefault,
    managedByBotId: normId(row?.managed_by_bot_id || row?.managedByBotId || ""),
    managedKind,
    managedMetadata: row?.managed_metadata && typeof row.managed_metadata === "object" ? row.managed_metadata : {},
    createdAt,
  };
}

function isDefaultServerRole(role) {
  const name = String(role?.name || "").trim().toLowerCase();
  const kind = String(role?.managed_kind || role?.managedKind || role?.kind || "").trim().toLowerCase();

  return Boolean(
    role?.is_default
    || role?.isDefault
    || role?.is_everyone
    || role?.isEveryone
    || role?.default
    || kind === "default"
    || kind === "everyone"
    || name === "@everyone"
    || name === "everyone"
    || name === "default"
  );
}

function isManagedServerRole(role = null) {
  if (!role) return false;
  if (isDefaultServerRole(role)) return false;
  const kind = String(role?.managed_kind || role?.managedKind || role?.kind || "").trim().toLowerCase();
  return Boolean(
    role?.is_managed === true
    || role?.isManaged === true
    || role?.managed === true
    || String(role?.is_managed || role?.isManaged || role?.managed || "").trim().toLowerCase() === "true"
    || !!normId(role?.managed_by_bot_id || role?.managedByBotId || role?.bot_id || role?.botId || "")
    || kind === "bot"
    || kind === "managed"
    || kind === "integration"
  );
}

function getManagedServerRolePermissionsLockedMessage() {
  return "Managed role permissions are controlled by the bot/integration.";
}

function isVirtualServerRole(role = null) {
  const id = String(role?.id || "").trim();
  return Boolean(
    !id
    || id.startsWith("virtual")
    || id.startsWith("synthetic")
    || id.startsWith("local-default")
    || id === "default"
    || role?.is_virtual === true
    || role?.virtual === true
    || role?.synthetic === true
  );
}

function canPersistServerRolePermissions(role = null) {
  if (!role) return false;
  if (isManagedServerRole(role)) return false;
  if (isVirtualServerRole(role)) return false;
  return Boolean(normId(role?.id || ""));
}

function getVirtualServerRolePermissionsLockedMessage(role = null) {
  return isDefaultServerRole(role)
    ? "Default role is not persisted yet, so its permissions cannot be saved."
    : "This role is not persisted yet, so its permissions cannot be saved.";
}
function isEveryoneServerRole(role = null) {
  return isDefaultServerRole(role);
}

function getServerRolePosition(role, fallback = 0) {
  const raw = role?.role_position ?? role?.rolePosition ?? role?.position ?? role?.sort_order ?? fallback;
  const value = Number(raw);
  return Number.isFinite(value) ? value : fallback;
}

function getRoleCreatedAtSortValue(role = null) {
  const parsed = Date.parse(String(role?.created_at || role?.createdAt || ""));
  return Number.isFinite(parsed) ? parsed : 0;
}

function sortServerRolesForHierarchy(roles = [], { serverId = "", includeSyntheticEveryone = false } = {}) {
  const normalized = (Array.isArray(roles) ? roles : []).filter(Boolean);
  const hasEveryone = normalized.some((role) => isDefaultServerRole(role));
  const withEveryone = includeSyntheticEveryone && !hasEveryone
    ? [...normalized, createSyntheticEveryoneRole(serverId)]
    : normalized.slice();

  const normal = [];
  const defaults = [];
  withEveryone.forEach((role, index) => {
    const item = { ...role, __fallbackIndex: index };
    if (isDefaultServerRole(role)) defaults.push(item);
    else normal.push(item);
  });

  const byPositionAsc = (a, b, fallbackBase) => {
    const byPos = getServerRolePosition(a, fallbackBase + a.__fallbackIndex) - getServerRolePosition(b, fallbackBase + b.__fallbackIndex);
    if (byPos !== 0) return byPos;
    const byCreated = getRoleCreatedAtSortValue(a) - getRoleCreatedAtSortValue(b);
    if (byCreated !== 0) return byCreated;
    return String(a?.name || "").localeCompare(String(b?.name || ""));
  };

  normal.sort((a, b) => byPositionAsc(a, b, 1));
  defaults.sort((a, b) => byPositionAsc(a, b, 999999));

  return [...normal, ...defaults].map(({ __fallbackIndex, ...role }) => role);
}

function getRoleHierarchyRank(role) {
  if (isDefaultServerRole(role)) return Number.POSITIVE_INFINITY;
  return getServerRolePosition(role, Number.POSITIVE_INFINITY);
}

function createSyntheticEveryoneRole(serverId = "") {
  const sid = normId(serverId || "");
  return {
    id: "",
    syntheticId: sid ? `everyone:${sid}` : "everyone",
    name: "@everyone",
    color: "#99aab5",
    permissions: normalizeServerRolePermissions({}, { name: "@everyone", isDefault: true, is_default: true, managedKind: "everyone" }),
    position: Number.POSITIVE_INFINITY,
    role_position: Number.POSITIVE_INFINITY,
    isManaged: true,
    isDefault: true,
    managedByBotId: "",
    managedKind: "everyone",
    managedMetadata: { synthetic: true },
    createdAt: 0,
    synthetic: true,
  };
}

function getServerRolesForSettingsDisplay(serverId = "") {
  const sid = normId(serverId || "");
  return sortServerRolesForHierarchy(serverRoleListByServerId.get(sid) || [], {
    serverId: sid,
    includeSyntheticEveryone: true,
  });
}

function reindexServerRolePositions(displayRoles) {
  const roles = sortServerRolesForHierarchy(displayRoles);
  const normal = roles.filter((role) => !isDefaultServerRole(role));
  const defaults = roles.filter(isDefaultServerRole);

  const nextRoles = [];
  const updates = [];

  normal.forEach((role, index) => {
    const position = index + 1;
    nextRoles.push({ ...role, position, role_position: position });
    if (role.id) updates.push({ id: role.id, position });
  });

  defaults.forEach((role, index) => {
    const position = normal.length + index + 1;
    nextRoles.push({ ...role, position, role_position: position });
    if (role.id && !String(role.id).startsWith("virtual")) {
      updates.push({ id: role.id, position });
    }
  });

  return { roles: nextRoles, updates };
}

function reorderServerRoleByDrag(roles, draggedRoleId, targetRoleId, placement = "before") {
  const ordered = sortServerRolesForHierarchy(roles);
  const movable = ordered.filter((role) => !isDefaultServerRole(role));
  const defaults = ordered.filter(isDefaultServerRole);
  const draggedId = normId(draggedRoleId || "");
  const targetToken = String(targetRoleId || "").trim();
  const targetId = normId(targetToken);

  const draggedIndex = movable.findIndex((role) => normId(role?.id || "") === draggedId);
  if (!draggedId || draggedIndex < 0) return { changed: false, roles: ordered, updates: [] };

  const dragged = movable[draggedIndex];
  const withoutDragged = movable.filter((role) => normId(role?.id || "") !== draggedId);
  let insertIndex = withoutDragged.length;

  const targetIsDefault = defaults.some((role) => {
    const rid = normId(role?.id || "");
    return (!!targetId && rid === targetId) || getServerRoleUiId(role) === targetToken;
  });

  if (!targetIsDefault && targetToken) {
    const targetIndex = withoutDragged.findIndex((role) => {
      const rid = normId(role?.id || "");
      return (!!targetId && rid === targetId) || getServerRoleUiId(role) === targetToken;
    });
    if (targetIndex >= 0) {
      insertIndex = String(placement || "before").toLowerCase() === "after" ? targetIndex + 1 : targetIndex;
    }
  }

  insertIndex = Math.max(0, Math.min(insertIndex, withoutDragged.length));
  const nextMovable = [...withoutDragged];
  nextMovable.splice(insertIndex, 0, dragged);
  const nextOrdered = [...nextMovable, ...defaults];

  const beforeIds = ordered.map((role) => String(role?.id || role?.syntheticId || "")).join("|");
  const afterIds = nextOrdered.map((role) => String(role?.id || role?.syntheticId || "")).join("|");
  if (beforeIds === afterIds) return { changed: false, roles: ordered, updates: [] };

  const nextRoles = [];
  const updates = [];
  nextOrdered.forEach((role, index) => {
    const position = index + 1;
    const nextRole = { ...role, position, role_position: position };
    nextRoles.push(nextRole);
    const isVirtualDefault = isDefaultServerRole(role)
      && (!role.id || String(role.id).startsWith("virtual") || String(role.id).startsWith("default"));
    if (!isVirtualDefault && role.id) updates.push({ id: role.id, position });
  });

  return { changed: true, roles: nextRoles, updates };
}
function getPersistableRoleOrderIdsForServer(serverId = "") {
  const sid = normId(serverId || "");
  return sortServerRolesForHierarchy(serverRoleListByServerId.get(sid) || [])
    .filter((role) => normId(role?.id || "") && !isDefaultServerRole(role))
    .map((role) => normId(role.id));
}

function getPendingServerRoleOrderUpdatesForServer(serverId = "") {
  void serverId;
  return (Array.isArray(serverSettingsPendingRoleOrderUpdates) ? serverSettingsPendingRoleOrderUpdates : [])
    .map((entry) => ({ id: normId(entry?.id || ""), position: Math.max(1, Math.round(Number(entry?.position || 0))) }))
    .filter((entry) => entry.id && Number.isFinite(entry.position));
}

function getServerRoleOrderSnapshot(serverId = "", { includeEveryone = true } = {}) {
  const sid = normId(serverId || "");
  return getServerRolesForSettingsDisplay(sid)
    .filter((role) => includeEveryone || !isDefaultServerRole(role))
    .map((role) => ({
      id: normId(role?.id || "") || null,
      syntheticId: role?.syntheticId || null,
      name: role?.name || "",
      position: getServerRolePosition(role, 0),
      isDefault: isDefaultServerRole(role),
      isManaged: role?.isManaged === true,
    }));
}

function getServerRoleUiId(role = null) {
  return normId(role?.id || "") || String(role?.syntheticId || "").trim();
}

function cloneServerRoleListForOrder(roles = []) {
  return (roles || [])
    .filter((role) => normId(role?.id || ""))
    .map((role) => ({ ...role, permissions: { ...(role?.permissions || {}) }, managedMetadata: { ...(role?.managedMetadata || {}) } }));
}

function rememberServerSettingsRoleOrderBaseline(serverId = "", roles = []) {
  const sid = normId(serverId || "");
  if (!sid) return;

  serverSettingsRoleOriginalOrder = cloneServerRoleListForOrder(sortServerRolesForHierarchy(roles || []));
  serverSettingsRoleOrderDirty = false;
  serverSettingsRolesError = "";
  serverSettingsPendingRoleOrderUpdates = [];
  serverSettingsPendingRolePermissionUpdates = new Map();
  serverSettingsRolePermissionsDirty = false;
  serverSettingsRolePointerDrag = null;
  serverSettingsRoleDropTargetId = "";
  serverSettingsRoleDropPosition = "";
  serverSettingsRoleLastReorderError = null;
}

function restoreServerSettingsRoleOrderIfDirty() {
  const sid = normId(serverSettingsServerId || "");
  if (!sid || (!serverSettingsRoleOrderDirty && !serverSettingsRolePermissionsDirty) || !serverSettingsRoleOriginalOrder.length) return false;
  serverRoleListByServerId.set(sid, cloneServerRoleListForOrder(serverSettingsRoleOriginalOrder));
  serverSettingsRoleOrderDirty = false;
  serverSettingsRolePermissionsDirty = false;
  serverSettingsPendingRoleOrderUpdates = [];
  serverSettingsPendingRolePermissionUpdates = new Map();
  serverSettingsRolePointerDrag = null;
  serverSettingsRoleDropTargetId = "";
  serverSettingsRoleDropPosition = "";
  logServerRolesEvent("order_reset", { serverId: sid });
  return true;
}

function getServerRoleHighestPositionForMember(serverId = "", userId = "") {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return null;
  const roleList = serverRoleListByServerId.get(sid) || [];
  const roleMap = serverRoleMemberMapByServerId.get(sid) || new Map();
  let top = null;
  roleList.forEach((role) => {
    const rid = normId(role?.id || "");
    if (!rid || isDefaultServerRole(role)) return;
    if (!roleMap.get(rid)?.has(uid)) return;
    if (!top || getRoleHierarchyRank(role) < getRoleHierarchyRank(top)) top = role;
  });
  return top;
}

function getImplementedServerPermissionKeys() {
  return ALTARA_SERVER_PERMISSION_CATALOG
    .filter((permission) => permission?.implemented === true)
    .map((permission) => String(permission.key || "").trim())
    .filter(Boolean);
}

function getCurrentServerMember(serverId = "") {
  const sid = normId(serverId || "");
  const meId = normId(state.user?.id || "");
  if (!sid || !meId) return null;
  const members = serverMemberListByServerId.get(sid) || [];
  return (members || []).find((member) => normId(member?.userId || member?.user_id || "") === meId) || null;
}

function getServerMemberRoleIds(serverId = "", userId = "") {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return [];
  const roleMap = serverRoleMemberMapByServerId.get(sid) || new Map();
  const ids = [];
  roleMap.forEach((set, roleId) => {
    if (set instanceof Set && set.has(uid)) ids.push(normId(roleId || ""));
  });
  return ids.filter(Boolean);
}

function isServerOwnerForPermissionCheck(server = null, member = null) {
  const meId = normId(state.user?.id || "");
  const ownerId = normId(server?.ownerUserId || server?.owner_user_id || "");
  const memberRole = String(member?.role || "").trim().toLowerCase();
  return !!((meId && ownerId && meId === ownerId) || memberRole === "owner");
}

function getCanonicalServerOwnerUserIdSync(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return "";
  const cachedOwnerId = normId(serverOwnerUserIdByServerId.get(sid) || "");
  if (cachedOwnerId) return cachedOwnerId;
  const server = getServerRowById(sid) || null;
  const rowOwnerId = normId(
    server?.ownerUserId
    || server?.owner_user_id
    || server?.ownerId
    || server?.owner_id
    || server?.createdBy
    || server?.created_by
    || ""
  );
  if (rowOwnerId) {
    serverOwnerUserIdByServerId.set(sid, rowOwnerId);
    return rowOwnerId;
  }
  const ownerMember = (serverMemberListByServerId.get(sid) || []).find((member) => (
    member?.is_owner === true
    || member?.isOwner === true
    || String(member?.role || "").trim().toLowerCase() === "owner"
  ));
  const memberOwnerId = getServerChannelPrivateAccessMemberUserId(ownerMember);
  if (memberOwnerId) serverOwnerUserIdByServerId.set(sid, memberOwnerId);
  return memberOwnerId;
}

function isServerOwnerUser(server = null, userId = "", member = null) {
  const uid = normId(userId || "");
  const sid = normId(server?.serverId || server?.server_id || server?.id || "");
  const ownerId = normId(
    getCanonicalServerOwnerUserIdSync(sid)
    || server?.ownerUserId
    || server?.owner_user_id
    || server?.ownerId
    || server?.owner_id
    || server?.createdBy
    || server?.created_by
    || server?.user_id
    || ""
  );
  const memberRole = String(member?.role || "").trim().toLowerCase();
  const memberIsOwner = member?.is_owner === true || member?.isOwner === true || memberRole === "owner";
  return !!((uid && ownerId && uid === ownerId) || memberIsOwner);
}

function getCachedServerMemberRoleIdsForUser(serverId = "", userId = "") {
  return getServerMemberRoleIds(serverId, userId);
}

function getCachedServerMemberForUser(serverId = "", userId = "", { serverMembers = null } = {}) {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return null;
  const members = Array.isArray(serverMembers) ? serverMembers : (serverMemberListByServerId.get(sid) || []);
  return (members || []).find((member) => normId(member?.userId || member?.user_id || "") === uid) || null;
}

function buildEmptyImplementedServerPermissions() {
  const permissions = {};
  getImplementedServerPermissionKeys().forEach((key) => { permissions[key] = false; });
  return permissions;
}

function resolveEffectiveServerPermissionsForUser({
  serverId = "",
  userId = "",
  server = null,
  roles = null,
  memberRoles = null,
  serverMembers = null,
  reason = "server-permissions",
} = {}) {
  const sid = normId(serverId || server?.id || server?.serverId || "");
  const uid = normId(userId || state.user?.id || "");
  const roleList = Array.isArray(roles)
    ? roles
    : sortServerRolesForHierarchy(getServerRolesForSettingsDisplay(sid), { serverId: sid, includeSyntheticEveryone: true });
  const member = getCachedServerMemberForUser(sid, uid, { serverMembers }) || null;
  const memberRoleIds = Array.isArray(memberRoles)
    ? memberRoles.map(normId).filter(Boolean)
    : getCachedServerMemberRoleIdsForUser(sid, uid);
  const memberRoleIdSet = new Set(memberRoleIds);
  const resolvedServer = server || getServerRowById(sid) || { id: sid };
  const permissions = buildEmptyImplementedServerPermissions();
  const grants = {};
  getImplementedServerPermissionKeys().forEach((key) => { grants[key] = []; });
  const trace = {
    reason,
    serverId: sid,
    userId: uid,
    isOwner: false,
    owner_bypass: false,
    memberId: uid,
    memberRoleIds,
    rolesApplied: [],
    grants,
    permissions,
    missingData: [],
  };

  if (!sid || !uid) {
    trace.missingData.push(!sid ? "server_id" : "user_id");
    return { ok: false, isOwner: false, userId: uid, serverId: sid, memberId: uid, memberRoleIds, rolesApplied: [], permissions, trace, error: "missing_context" };
  }

  const isOwner = isServerOwnerUser(resolvedServer, uid, member);
  trace.canonicalOwnerUserId = getCanonicalServerOwnerUserIdSync(sid);
  trace.isOwner = isOwner;
  if (isOwner) {
    Object.keys(permissions).forEach((key) => {
      permissions[key] = true;
      grants[key] = [{ source: "owner_bypass", roleId: null, roleName: "Owner" }];
    });
    trace.owner_bypass = true;
    return { ok: true, isOwner: true, userId: uid, serverId: sid, memberId: uid, memberRoleIds, rolesApplied: [], permissions, trace };
  }

  if (!Array.isArray(roleList) || !roleList.length) trace.missingData.push("roles");
  if (!serverRoleMemberMapByServerId.has(sid) && !Array.isArray(memberRoles)) trace.missingData.push("member_roles");
  if (!Array.isArray(serverMembers) && !serverMemberListByServerId.has(sid)) trace.missingData.push("server_members");

  const orderedRoles = sortServerRolesForHierarchy(roleList || [], { serverId: sid, includeSyntheticEveryone: true });
  orderedRoles.forEach((role) => {
    const rid = normId(role?.id || "");
    const roleName = String(role?.name || role?.role_name || "Role").trim() || "Role";
    const isDefault = isDefaultServerRole(role);
    const applies = isDefault || (rid && memberRoleIdSet.has(rid));
    if (!applies) return;
    const rolePermissions = getServerRolePermissions(role);
    const applied = {
      id: rid || getServerRoleUiId(role) || null,
      name: roleName,
      isDefault,
      permissions: {},
    };
    getImplementedServerPermissionKeys().forEach((key) => {
      const enabled = rolePermissions[key] === true;
      applied.permissions[key] = enabled;
      if (enabled) {
        permissions[key] = true;
        grants[key].push({ roleId: rid || null, roleName, isDefault });
      }
    });
    trace.rolesApplied.push(applied);
  });

  trace.permissions = { ...permissions };
  if (trace.missingData.length) {
    return { ok: false, isOwner: false, userId: uid, serverId: sid, memberId: uid, memberRoleIds, rolesApplied: trace.rolesApplied, permissions, trace, error: "permissions_not_fully_loaded" };
  }

  return { ok: true, isOwner: false, userId: uid, serverId: sid, memberId: uid, memberRoleIds, rolesApplied: trace.rolesApplied, permissions, trace };
}

async function ensureServerPermissionDataForUser(serverId = "", userId = "") {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return { ok: false, error: { message: "Missing server/user id." } };
  const roleRes = await ensureServerRolePermissionCache(sid, { force: false });
  if (!roleRes?.ok) return roleRes;
  if (!serverMemberListByServerId.has(sid)) {
    await fetchServerMembersForSidebar(sid, { force: false }).catch((error) => {
      console.warn("[permissions] failed to load server members", { serverId: sid, message: error?.message || error, error });
      return [];
    });
  }
  const server = getServerRowById(sid) || { id: sid };
  const member = getCachedServerMemberForUser(sid, uid);
  if (!isServerOwnerUser(server, uid, member) && (!serverMemberListByServerId.has(sid) || !member)) {
    return { ok: false, error: { message: "Could not verify server membership." } };
  }
  return { ok: true, error: null };
}

async function resolveCurrentUserServerPermissions({ serverId = "", reason = "server-permissions" } = {}) {
  const sid = normId(serverId || "");
  const uid = normId(state.user?.id || "");
  const ensure = await ensureServerPermissionDataForUser(sid, uid);
  const result = resolveEffectiveServerPermissionsForUser({
    serverId: sid,
    userId: uid,
    server: getServerRowById(sid) || { id: sid },
    roles: getServerRolesForSettingsDisplay(sid),
    memberRoles: getCachedServerMemberRoleIdsForUser(sid, uid),
    serverMembers: serverMemberListByServerId.get(sid) || [],
    reason,
  });
  if (!ensure?.ok && !result.isOwner) {
    result.ok = false;
    result.error = ensure?.error?.message || result.error || "permissions_not_verified";
    result.trace.missingData = Array.from(new Set([...(result.trace.missingData || []), "permission_cache"]));
  }
  return result;
}

// Voice participation stays server-role scoped until a channel assignment and
// its LiveKit source grants can be changed atomically.
const CHANNEL_PERMISSION_KEYS = Object.freeze([
  "view_channels",
  "send_messages",
  "use_voice_activity",
  "manage_channels",
]);
const CHANNEL_PERMISSION_META = Object.freeze([
  { key: "view_channels", label: "View Channel", hint: "See this channel in the sidebar and open it." },
  { key: "send_messages", label: "Send Messages", hint: "Send messages in text channels." },
  { key: "use_voice_activity", label: "Use Voice Activity", hint: "Use voice activity instead of push-to-talk. Enforced in a later phase." },
  { key: "manage_channels", label: "Manage Channel", hint: "Edit channel settings and permission overwrites." },
]);

function normalizeChannelPermissionKey(key = "") {
  const raw = normalizeServerPermissionKey(key || "");
  return CHANNEL_PERMISSION_KEYS.includes(raw) ? raw : "";
}

function normalizeChannelPermissionMap(raw = {}) {
  const source = raw && typeof raw === "object" ? raw : {};
  const out = {};
  CHANNEL_PERMISSION_KEYS.forEach((key) => {
    const direct = source[key];
    if (direct === true) out[key] = true;
  });
  return out;
}

function normalizeChannelPermissionOverwrite(row = null) {
  if (!row || typeof row !== "object") return null;
  const serverId = normId(row.serverId || row.server_id || "");
  const channelId = normId(row.channelId || row.channel_id || "");
  const targetType = String(row.targetType || row.target_type || "").trim().toLowerCase();
  const targetId = normId(row.targetId || row.target_id || "");
  if (!serverId || !channelId || !targetId || !["everyone", "role", "member"].includes(targetType)) return null;
  return {
    id: normId(row.id || "") || `${channelId}:${targetType}:${targetId}`,
    serverId,
    channelId,
    targetType,
    targetId,
    allow: normalizeChannelPermissionMap(row.allow || row.allowed || {}),
    deny: normalizeChannelPermissionMap(row.deny || row.denied || {}),
    updatedAt: String(row.updatedAt || row.updated_at || row.createdAt || row.created_at || ""),
  };
}

function isMissingChannelPermissionsSqlError(error = null) {
  return isMissingRpcError(error) || isMissingTableError(error, "server_channel_permission_overwrites");
}

function setChannelPermissionOverwritesForChannel(channelId = "", rows = []) {
  const cid = normId(channelId || "");
  if (!cid) return [];
  const normalized = (Array.isArray(rows) ? rows : [])
    .map(normalizeChannelPermissionOverwrite)
    .filter((row) => row && row.channelId === cid);
  normalized.sort((a, b) => (
    String(a.targetType).localeCompare(String(b.targetType))
    || String(a.targetId).localeCompare(String(b.targetId))
  ));
  channelPermissionOverwritesByChannel.set(cid, normalized);
  channelPermissionOverwritesLoadedAtByChannel.set(cid, Date.now());
  return normalized;
}

function getChannelPermissionOverwrites(channelId = "") {
  const cid = normId(channelId || "");
  return cid ? (channelPermissionOverwritesByChannel.get(cid) || []) : [];
}

function hasChannelPermissionOverwritesLoaded(channelId = "") {
  return channelPermissionOverwritesLoadedAtByChannel.has(normId(channelId || ""));
}

function isChannelPermissionsSqlAvailable() {
  return channelPermissionOverwritesSqlAvailable !== false;
}

async function loadChannelPermissionOverwrites(serverId = "", channelId = "", { force = false } = {}) {
  const sid = normId(serverId || "");
  const cid = normId(channelId || "");
  if (!sid || !cid) return { ok: false, rows: [], error: { message: "missing_channel_context" } };
  if (!force && hasChannelPermissionOverwritesLoaded(cid)) {
    return { ok: true, rows: getChannelPermissionOverwrites(cid), cached: true };
  }
  if (channelPermissionOverwritesSqlAvailable === false && !force) {
    return { ok: false, rows: getChannelPermissionOverwrites(cid), missingSql: true };
  }
  const res = await supabase.rpc("list_channel_permission_overwrites", {
    p_server_id: sid,
    p_channel_id: cid,
  });
  if (res?.error) {
    if (isMissingChannelPermissionsSqlError(res.error)) {
      channelPermissionOverwritesSqlAvailable = false;
      setChannelPermissionOverwritesForChannel(cid, []);
      console.warn("[channel-permissions] SQL patch missing; channel overwrites disabled until applied.", res.error);
      return { ok: false, rows: [], error: res.error, missingSql: true };
    }
    return { ok: false, rows: getChannelPermissionOverwrites(cid), error: res.error };
  }
  channelPermissionOverwritesSqlAvailable = true;
  const rows = setChannelPermissionOverwritesForChannel(cid, Array.isArray(res.data) ? res.data : []);
  return { ok: true, rows, error: null };
}

async function loadAllVisibleChannelPermissionOverwritesForServer(serverId = "", { force = false } = {}) {
  const sid = normId(serverId || "");
  if (!sid || channelPermissionOverwritesSqlAvailable === false && !force) return { ok: false, missingSql: channelPermissionOverwritesSqlAvailable === false };
  const channels = serverChannelListByServerId.get(sid) || [];
  const ids = channels.map((ch) => normId(ch?.id || "")).filter(Boolean);
  if (!ids.length) return { ok: true, rows: [] };
  const results = await Promise.allSettled(ids.map((channelId) => loadChannelPermissionOverwrites(sid, channelId, { force })));
  const missingSql = results.some((entry) => entry.status === "fulfilled" && entry.value?.missingSql);
  return {
    ok: !missingSql,
    missingSql,
    rows: ids.flatMap((channelId) => getChannelPermissionOverwrites(channelId)),
  };
}

async function setChannelPermissionOverwrite({
  serverId = "",
  channelId = "",
  targetType = "",
  targetId = "",
  allow = {},
  deny = {},
} = {}) {
  const sid = normId(serverId || "");
  const cid = normId(channelId || "");
  const tid = normId(targetId || "");
  const type = String(targetType || "").trim().toLowerCase();
  if (!sid || !cid || !tid || !["everyone", "role", "member"].includes(type)) {
    return { ok: false, error: { message: "invalid_channel_permission_target" } };
  }
  const res = await supabase.rpc("set_channel_permission_overwrite", {
    p_server_id: sid,
    p_channel_id: cid,
    p_target_type: type,
    p_target_id: tid,
    p_allow: normalizeChannelPermissionMap(allow),
    p_deny: normalizeChannelPermissionMap(deny),
  });
  if (res?.error) {
    if (isMissingChannelPermissionsSqlError(res.error)) channelPermissionOverwritesSqlAvailable = false;
    return { ok: false, error: res.error, missingSql: isMissingChannelPermissionsSqlError(res.error) };
  }
  channelPermissionOverwritesSqlAvailable = true;
  const row = normalizeChannelPermissionOverwrite(res.data);
  if (row) {
    const nextRows = getChannelPermissionOverwrites(cid)
      .filter((item) => !(item.targetType === row.targetType && item.targetId === row.targetId));
    nextRows.push(row);
    setChannelPermissionOverwritesForChannel(cid, nextRows);
  }
  return { ok: true, row, error: null };
}

async function deleteChannelPermissionOverwrite({
  serverId = "",
  channelId = "",
  targetType = "",
  targetId = "",
} = {}) {
  const sid = normId(serverId || "");
  const cid = normId(channelId || "");
  const tid = normId(targetId || "");
  const type = String(targetType || "").trim().toLowerCase();
  if (!sid || !cid || !tid || !["everyone", "role", "member"].includes(type)) {
    return { ok: false, error: { message: "invalid_channel_permission_target" } };
  }
  const res = await supabase.rpc("delete_channel_permission_overwrite", {
    p_server_id: sid,
    p_channel_id: cid,
    p_target_type: type,
    p_target_id: tid,
  });
  if (res?.error) {
    if (isMissingChannelPermissionsSqlError(res.error)) channelPermissionOverwritesSqlAvailable = false;
    return { ok: false, error: res.error, missingSql: isMissingChannelPermissionsSqlError(res.error) };
  }
  const nextRows = getChannelPermissionOverwrites(cid)
    .filter((item) => !(item.targetType === type && item.targetId === tid));
  setChannelPermissionOverwritesForChannel(cid, nextRows);
  return { ok: true, error: null };
}

function applyChannelPermissionMap(permissions = {}, overwrite = null, traceList = []) {
  if (!overwrite) return permissions;
  const deny = normalizeChannelPermissionMap(overwrite.deny || {});
  const allow = normalizeChannelPermissionMap(overwrite.allow || {});
  Object.keys(deny).forEach((key) => { permissions[key] = false; });
  Object.keys(allow).forEach((key) => { permissions[key] = true; });
  if (traceList) traceList.push({ targetType: overwrite.targetType, targetId: overwrite.targetId, deny, allow });
  return permissions;
}

function resolveEffectiveChannelPermissionsForUser({
  serverId = "",
  channelId = "",
  userId = "",
  reason = "channel-permissions",
} = {}) {
  const sid = normId(serverId || "");
  const cid = normId(channelId || "");
  const uid = normId(userId || state.user?.id || "");
  const base = resolveEffectiveServerPermissionsForUser({
    serverId: sid,
    userId: uid,
    server: getServerRowById(sid) || { id: sid },
    roles: getServerRolesForSettingsDisplay(sid),
    memberRoles: getCachedServerMemberRoleIdsForUser(sid, uid),
    serverMembers: serverMemberListByServerId.get(sid) || [],
    reason,
  });
  const permissions = { ...(base.permissions || {}) };
  CHANNEL_PERMISSION_KEYS.forEach((key) => {
    if (!Object.prototype.hasOwnProperty.call(permissions, key)) permissions[key] = false;
  });
  const trace = {
    reason,
    serverId: sid,
    channelId: cid,
    userId: uid,
    basePermissions: { ...(base.permissions || {}) },
    overwritesApplied: [],
    finalPermissions: permissions,
    channelPermissionsAvailable: channelPermissionOverwritesSqlAvailable !== false,
    loaded: hasChannelPermissionOverwritesLoaded(cid),
    baseTrace: base.trace || null,
  };
  if (!sid || !cid || !uid) {
    trace.error = "missing_context";
    return { ok: false, permissions, trace, error: "missing_context" };
  }
  if (base.isOwner) {
    CHANNEL_PERMISSION_KEYS.forEach((key) => { permissions[key] = true; });
    trace.owner_bypass = true;
    trace.finalPermissions = { ...permissions };
    return { ok: base.ok, permissions, trace, isOwner: true };
  }
  const rows = getChannelPermissionOverwrites(cid);
  const everyone = rows.find((row) => row.targetType === "everyone" && row.targetId === sid) || null;
  applyChannelPermissionMap(permissions, everyone, trace.overwritesApplied);
  const roleIds = new Set(getCachedServerMemberRoleIdsForUser(sid, uid));
  const roleRows = rows.filter((row) => row.targetType === "role" && roleIds.has(row.targetId));
  if (roleRows.length) {
    const aggregate = { targetType: "role", targetId: Array.from(roleIds).join(","), allow: {}, deny: {} };
    roleRows.forEach((row) => {
      Object.assign(aggregate.deny, normalizeChannelPermissionMap(row.deny || {}));
      Object.assign(aggregate.allow, normalizeChannelPermissionMap(row.allow || {}));
    });
    Object.keys(aggregate.deny).forEach((key) => { delete aggregate.allow[key]; });
    applyChannelPermissionMap(permissions, aggregate, trace.overwritesApplied);
  }
  const member = rows.find((row) => row.targetType === "member" && row.targetId === uid) || null;
  applyChannelPermissionMap(permissions, member, trace.overwritesApplied);
  trace.finalPermissions = { ...permissions };
  return { ok: base.ok !== false, permissions, trace, isOwner: false, channelPermissionsAvailable: trace.channelPermissionsAvailable };
}

function canCurrentUserViewServerChannelSync(serverId = "", channelId = "") {
  const sid = normId(serverId || "");
  const cid = normId(channelId || "");
  if (!sid || !cid) return true;
  const currentUserId = normId(state.user?.id || "");
  const canonicalOwnerUserId = getCanonicalServerOwnerUserIdSync(sid);
  if (currentUserId && canonicalOwnerUserId && currentUserId === canonicalOwnerUserId) return true;
  if (serverChannelBackendVisibleIdsByServerId.get(sid)?.has(cid)) return true;
  if (channelPermissionOverwritesSqlAvailable === false) return currentUserCanViewChannels(sid);
  if (!hasChannelPermissionOverwritesLoaded(cid)) return currentUserCanViewChannels(sid);
  const result = resolveEffectiveChannelPermissionsForUser({
    serverId: sid,
    channelId: cid,
    userId: state.user?.id || "",
    reason: "sidebar-visible-channel",
  });
  return result?.isOwner || result?.permissions?.view_channels === true;
}

function canCurrentUserViewServerChannel(channelId = "") {
  const cid = normId(channelId || "");
  if (!cid) return true;
  const activeCtx = getServerPermissionContextForConversation(activeDmId) || {};
  const sid = normId(activeCtx.serverId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
  return canCurrentUserViewServerChannelSync(sid, cid);
}

function getVisibleServerChannelsForCurrentUser(serverId = "", channels = []) {
  const sid = normId(serverId || "");
  if (!sid || !Array.isArray(channels)) return [];
  return channels.filter((channel) => {
    const cid = normId(channel?.id || channel?.channelId || channel?.channel_id || "");
    if (!cid) return true;
    return canCurrentUserViewServerChannelSync(sid, cid);
  });
}

function getFirstVisibleServerTextChannel(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return null;
  const visible = getVisibleServerChannelsForCurrentUser(sid, serverChannelListByServerId.get(sid) || []);
  return visible.find((channel) => normalizeConversationChannelType(channel?.channelType || "text") === "text") || null;
}

function getFirstVisibleServerChannel(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return null;
  return getFirstVisibleServerTextChannel(sid)
    || getVisibleServerChannelsForCurrentUser(sid, serverChannelListByServerId.get(sid) || [])[0]
    || null;
}

function renderNoAccessibleServerChannelsState(serverId = "", reason = "channel_permissions_changed") {
  const sid = normId(serverId || "");
  activeDmId = null;
  state.activeDm = {
    kind: "server",
    isGroup: true,
    serverId: sid,
    serverName: normalizeConversationLabel(getServerRowById(sid)?.name || "Server", "Server"),
    displayName: "No channels available",
    channelId: "",
    channelType: "text",
    conversationId: "",
    noAccessibleServerChannels: true,
  };
  dmMessagesCache = [];
  dmMessageIds = new Set();
  setMidMode("dm");
  syncDmActiveListHighlight();
  setRightSidebarToServerMembers({ active: false });
  const msgsBox = document.getElementById("dmMessages");
  if (msgsBox) {
    setElementHtmlIfChanged(msgsBox, `
      <div class="serverNoAccessibleChannelsState">
        <div class="serverNoAccessibleChannelsState__inner">
          <div class="serverNoAccessibleChannelsState__icon" aria-hidden="true">#</div>
          <div class="serverNoAccessibleChannelsState__title">No channels available</div>
          <div class="serverNoAccessibleChannelsState__text">You don't have access to any channel in this server.</div>
        </div>
      </div>
    `);
  }
  setActiveMessageComposerPermissionState({
    key: `server-no-access:${sid}:${normId(state.user?.id || "")}`,
    loading: false,
    canSend: false,
    reason: "missing_send_messages",
    trace: { reason, serverId: sid, noVisibleChannels: true },
  });
  renderMessageComposer(reason);
  try { updateDmHeaderAvatar(); } catch (_) {}
}

async function openVisibleServerChannelAfterPermissionChange(serverId = "", channel = null, reason = "channel_permissions_changed") {
  const sid = normId(serverId || "");
  const row = channel || getFirstVisibleServerTextChannel(sid) || getFirstVisibleServerChannel(sid);
  if (!sid || !row?.conversationId) return false;
  const serverRow = getServerRowById(sid) || null;
  const channelType = normalizeConversationChannelType(row?.channelType || "text");
  const meta = {
    kind: "server",
    isGroup: true,
    displayName: normalizeConversationLabel(row.name || (channelType === "voice" ? "voice-lounge" : "general"), channelType === "voice" ? "voice-lounge" : "general"),
    serverId: sid,
    serverName: normalizeConversationLabel(serverRow?.name || state.activeDm?.serverName || "Server", "Server"),
    avatarUrl: String(serverRow?.iconUrl || state.activeDm?.avatarUrl || "").trim(),
    channelId: normId(row.id || ""),
    channel_id: normId(row.id || ""),
    channelType,
    userLimit: channelType === "voice" ? clampServerVoiceUserLimit(row?.userLimit ?? 0, 0) : 0,
    mediaMode: channelType === "voice" ? normalizeServerVoiceMediaMode(row?.mediaMode || "audio_only", "audio_only") : "audio_only",
  };
  console.info("[channel-permissions] switched to first visible channel", {
    reason,
    serverId: sid,
    channelId: meta.channelId,
    conversationId: row.conversationId,
    channelName: meta.displayName,
  });
  commitServerChannelSelectionForUi(row.conversationId, meta, { reason, userInitiated: false });
  await openConversationById(row.conversationId, meta);
  return true;
}

async function reconcileActiveServerChannelAfterPermissionChange(reason = "channel_permissions_changed") {
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  const activeCtx = getServerPermissionContextForConversation(activeConvId) || null;
  const sid = normId(activeCtx?.serverId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
  if (!sid) return { ok: true, action: "no_server" };
  const { serverCtx } = getActiveServerChannelsRuntimeContext();
  if (serverCtx && normId(serverCtx.serverId || "") === sid) {
    renderServerChannelsPanel(
      serverCtx,
      serverChannelListByServerId.get(sid) || [],
      serverMemberListByServerId.get(sid) || [],
      serverChannelCategoryListByServerId.get(sid) || []
    );
  }
  if (!activeCtx?.channelId) {
    await refreshActiveMessageComposerPermission({ reason });
    return { ok: true, action: "no_active_channel" };
  }
  const stillVisible = canCurrentUserViewServerChannelSync(sid, activeCtx.channelId);
  if (stillVisible) {
    await refreshActiveMessageComposerPermission({ reason });
    renderMessagesFromCache({ keepBottom: true, reason, force: true });
    return { ok: true, action: "still_visible", channelId: activeCtx.channelId };
  }
  console.info("[channel-permissions] active channel no longer visible", {
    reason,
    serverId: sid,
    channelId: activeCtx.channelId,
    conversationId: activeConvId,
  });
  const next = getFirstVisibleServerTextChannel(sid) || getFirstVisibleServerChannel(sid);
  if (next?.conversationId) {
    await openVisibleServerChannelAfterPermissionChange(sid, next, reason);
    await refreshActiveMessageComposerPermission({ reason });
    return { ok: true, action: "switched", channelId: normId(next.id || ""), conversationId: normId(next.conversationId || "") };
  }
  console.info("[channel-permissions] no visible channels available", { reason, serverId: sid });
  renderNoAccessibleServerChannelsState(sid, reason);
  return { ok: true, action: "no_visible_channels" };
}

async function resolveCurrentUserMessagePermission({ serverId = "", channelId = "", reason = "send-message" } = {}) {
  const sid = normId(serverId || "");
  const cid = normId(channelId || "");
  await resolveCurrentUserServerPermissions({ serverId: sid, reason });
  if (cid && channelPermissionOverwritesSqlAvailable !== false && !hasChannelPermissionOverwritesLoaded(cid)) {
    const load = await loadChannelPermissionOverwrites(sid, cid, { force: false });
    if (load?.error && !load?.missingSql) {
      const fallback = await resolveCurrentUserServerPermissions({ serverId: sid, reason });
      fallback.channelId = cid;
      fallback.trace.channelId = cid;
      fallback.ok = false;
      fallback.error = load.error?.message || "channel_permissions_not_verified";
      return fallback;
    }
  }
  const result = resolveEffectiveChannelPermissionsForUser({
    serverId: sid,
    channelId: cid,
    userId: state.user?.id || "",
    reason,
  });
  result.channelId = cid;
  return result;
}

