function computeServerAccessPanelData(serverId = "") {
  const sid = normId(serverId || "");
  const server = getServerRowById(sid) || { id: sid };
  const capMeta = getServerCapabilityMeta(sid);
  const roles = getServerRolesForSettingsDisplay(sid);
  const memberList = serverMemberListByServerId.get(sid) || [];
  const roleMemberMap = serverRoleMemberMapByServerId.get(sid) || new Map();
  const meId = normId(state.user?.id || "");
  const implementedKeySet = new Set(getImplementedServerPermissionKeys());
  const visiblePermissionDefs = SERVER_ROLE_VISIBLE_PERMISSION_META.slice();
  const implementedVisiblePermissionDefs = visiblePermissionDefs.filter((perm) => implementedKeySet.has(perm.key));

  // --- 1) Your Access ---------------------------------------------------
  const myResolved = resolveEffectiveServerPermissionsForUser({
    serverId: sid,
    userId: meId,
    server,
    roles,
    memberRoles: getServerMemberRoleIds(sid, meId),
    serverMembers: memberList,
    reason: "access-panel-your-access",
  });
  const myIsOwner = !!(myResolved.isOwner || capMeta.isOwner || capMeta.isActualOwner);
  const yourAccessRows = implementedVisiblePermissionDefs.map((perm) => {
    const granted = myIsOwner ? true : (myResolved.permissions?.[perm.key] === true);
    const grantedBy = myIsOwner
      ? [{ roleId: null, roleName: "Owner", isDefault: false, source: "owner_bypass" }]
      : (myResolved.trace?.grants?.[perm.key] || []);
    return {
      key: perm.key,
      label: perm.label,
      hint: perm.hint,
      category: perm.category,
      risk: perm.risk,
      granted,
      grantedBy,
    };
  });
  const yourAccessGrantedCount = yourAccessRows.filter((row) => row.granted).length;

  // --- 2) Risk Overview ---------------------------------------------------
  const dangerousPermDefs = implementedVisiblePermissionDefs.filter((perm) => perm.risk === "dangerous");
  const elevatedPermDefs = implementedVisiblePermissionDefs.filter((perm) => perm.risk === "elevated");

  let membersWithDangerous = 0;
  let membersWithElevated = 0;
  const seenMemberIds = new Set();
  memberList.forEach((member) => {
    const uid = normId(member?.userId || "");
    if (!uid || seenMemberIds.has(uid)) return;
    seenMemberIds.add(uid);
    const isOwnerMember = isServerOwnerUser(server, uid, member);
    let hasDangerous = isOwnerMember;
    let hasElevated = isOwnerMember;
    if (!isOwnerMember) {
      const perms = getServerRolePermissionsForUser(sid, uid, { members: memberList, roles, roleMemberMap });
      hasDangerous = dangerousPermDefs.some((perm) => perms[perm.key] === true);
      hasElevated = elevatedPermDefs.some((perm) => perms[perm.key] === true);
    }
    if (hasDangerous) membersWithDangerous += 1;
    if (hasElevated) membersWithElevated += 1;
  });

  const rolesGrantingDangerous = roles.filter((role) => {
    const perms = getServerRolePermissions(role);
    return dangerousPermDefs.some((perm) => perms[perm.key] === true);
  });
  const rolesGrantingElevated = roles.filter((role) => {
    const perms = getServerRolePermissions(role);
    return elevatedPermDefs.some((perm) => perms[perm.key] === true);
  });
  const notEnforcedDangerousCount = ALTARA_SERVER_PERMISSION_CATALOG.filter((perm) => perm.risk === "dangerous" && perm.implemented !== true).length;

  let riskLevel = "low";
  if (membersWithDangerous > 0 || rolesGrantingDangerous.length > 0) riskLevel = "high";
  else if (membersWithElevated > 0 || rolesGrantingElevated.length > 0) riskLevel = "moderate";

  const riskOverview = {
    riskLevel,
    memberCount: memberList.length,
    roleCount: roles.length,
    membersWithDangerous,
    membersWithElevated,
    rolesGrantingDangerousCount: rolesGrantingDangerous.length,
    rolesGrantingElevatedCount: rolesGrantingElevated.length,
    notEnforcedDangerousCount,
  };

  // --- 3) Role Permissions Matrix -----------------------------------------
  const matrixRoles = roles.map((role) => {
    const rid = normId(role?.id || "");
    const isDefault = isDefaultServerRole(role);
    const perms = getServerRolePermissions(role);
    return {
      id: rid,
      uiId: getServerRoleUiId(role),
      name: String(role?.name || "Role"),
      color: String(role?.color || "#99aab5"),
      isDefault,
      managed: isManagedServerRole(role) && !isDefault,
      memberCount: isDefault ? memberList.length : (roleMemberMap.get(role.id)?.size || 0),
      permissions: perms,
      enabledCount: countEnabledServerRolePermissions(perms),
    };
  });
  const roleMatrix = {
    permissions: visiblePermissionDefs,
    roles: matrixRoles,
  };

  // --- 4) Dangerous Permissions --------------------------------------------
  const dangerousPermissions = ALTARA_SERVER_PERMISSION_CATALOG
    .filter((perm) => perm.risk === "dangerous")
    .map((perm) => {
      const holdingRoles = roles
        .filter((role) => getServerRolePermissions(role)[perm.key] === true)
        .map((role) => ({
          id: normId(role?.id || ""),
          name: String(role?.name || "Role"),
          color: String(role?.color || "#99aab5"),
          isDefault: isDefaultServerRole(role),
        }));
      return {
        key: perm.key,
        label: perm.label,
        hint: perm.hint,
        implemented: perm.implemented === true,
        holdingRoles,
      };
    });

  return {
    serverId: sid,
    generatedAt: Date.now(),
    isOwner: myIsOwner,
    yourAccess: {
      isOwner: myIsOwner,
      ok: myResolved.ok !== false,
      grantedCount: yourAccessGrantedCount,
      totalCount: yourAccessRows.length,
      rows: yourAccessRows,
      trace: myResolved.trace || null,
    },
    riskOverview,
    roleMatrix,
    dangerousPermissions,
  };
}

function serverAccessRiskBadgeHtml(risk = "normal") {
  const level = String(risk || "normal").trim().toLowerCase();
  if (level === "dangerous") return '<span class="botPermissionStatus botPermissionStatus--dangerous">Dangerous</span>';
  if (level === "elevated") return '<span class="botPermissionStatus botPermissionStatus--elevated">Elevated</span>';
  return '<span class="botPermissionStatus">Normal</span>';
}

function buildServerAccessYourAccessHtml(data) {
  if (data.yourAccess.isOwner) {
    return '<div class="serverAccessOwnerNote hint">You are the server owner. Owner access bypasses role permissions and grants every implemented permission.</div>';
  }
  const rows = data.yourAccess.rows;
  const categoriesHtml = SERVER_ROLE_PERMISSION_CATEGORY_ORDER.map((category) => {
    const categoryRows = rows.filter((row) => row.category === category);
    if (!categoryRows.length) return "";
    const allowedCount = categoryRows.filter((row) => row.granted).length;
    return `
      <div class="serverAccessCategoryBlock">
        <div class="serverAccessCategoryHead"><span>${esc(category)}</span><small>${allowedCount}/${categoryRows.length} allowed</small></div>
        <div class="serverAccessRowList">
          ${categoryRows.map((row) => {
            const grantedByHtml = row.granted && row.grantedBy.length
              ? row.grantedBy.map((grant) => `<span class="serverSettingsRolePermsBadge" title="Granted by ${escAttr(grant.roleName || "Role")}">${esc(grant.roleName || "Role")}</span>`).join("")
              : "";
            return `
              <div class="serverAccessRow${row.granted ? " is-granted" : ""}">
                <div class="serverAccessRowMain">
                  <span class="serverAccessRowLabel">${esc(row.label)}</span>
                  ${serverAccessRiskBadgeHtml(row.risk)}
                </div>
                <div class="serverAccessRowHint">${esc(row.hint || "")}</div>
                <div class="serverAccessRowFoot">
                  <span class="serverAccessGrantBadge ${row.granted ? "is-granted" : "is-denied"}">${row.granted ? "Allowed" : "Not granted"}</span>
                  ${grantedByHtml}
                </div>
              </div>
            `;
          }).join("")}
        </div>
      </div>
    `;
  }).join("");
  return categoriesHtml || '<div class="hint">No implemented permissions to display yet.</div>';
}

function buildServerAccessOverviewHtml(data) {
  const overview = data.riskOverview;
  const riskBadge = overview.riskLevel === "high"
    ? '<span class="botPermissionStatus botPermissionStatus--dangerous">High Risk</span>'
    : (overview.riskLevel === "moderate"
      ? '<span class="botPermissionStatus botPermissionStatus--elevated">Moderate Risk</span>'
      : '<span class="botPermissionStatus">Low Risk</span>');
  return `
    <div class="serverAccessOverviewHead">${riskBadge}</div>
    <div class="serverAccessOverviewGrid">
      <div class="serverAccessOverviewCard"><span>Roles</span><strong>${overview.roleCount}</strong></div>
      <div class="serverAccessOverviewCard"><span>Members</span><strong>${overview.memberCount}</strong></div>
      <div class="serverAccessOverviewCard"><span>Members holding a dangerous permission</span><strong>${overview.membersWithDangerous}</strong></div>
      <div class="serverAccessOverviewCard"><span>Members holding an elevated permission</span><strong>${overview.membersWithElevated}</strong></div>
      <div class="serverAccessOverviewCard"><span>Roles granting a dangerous permission</span><strong>${overview.rolesGrantingDangerousCount}</strong></div>
      <div class="serverAccessOverviewCard"><span>Roles granting an elevated permission</span><strong>${overview.rolesGrantingElevatedCount}</strong></div>
    </div>
    ${overview.notEnforcedDangerousCount ? `<div class="hint">${overview.notEnforcedDangerousCount} cataloged dangerous permission${overview.notEnforcedDangerousCount === 1 ? "" : "s"} are not yet enforced anywhere in the app.</div>` : ""}
  `;
}

function buildServerAccessMatrixHtml(data) {
  const matrix = data.roleMatrix;
  if (!matrix.roles.length) return '<div class="hint">No roles found for this server.</div>';
  const headHtml = matrix.roles.map((role) => `
    <th title="${escAttr(role.name)}">
      <span class="serverSettingsRoleSwatch" style="--role-color:${escAttr(role.color)}"></span>
      <span class="serverAccessMatrixRoleName">${esc(role.name)}</span>
      <small>${role.memberCount} member${role.memberCount === 1 ? "" : "s"}</small>
    </th>
  `).join("");
  const bodyHtml = SERVER_ROLE_PERMISSION_CATEGORY_ORDER.map((category) => {
    const permRows = matrix.permissions.filter((perm) => perm.category === category);
    if (!permRows.length) return "";
    const categoryRowHtml = `<tr class="serverAccessMatrixCategoryRow"><td colspan="${matrix.roles.length + 1}">${esc(category)}</td></tr>`;
    const permRowsHtml = permRows.map((perm) => {
      const risk = String(perm.risk || "normal").trim().toLowerCase();
      const implemented = perm.implemented === true;
      const rowClass = [risk === "dangerous" ? "risk-dangerous" : (risk === "elevated" ? "risk-elevated" : ""), implemented ? "" : "is-coming-soon"].filter(Boolean).join(" ");
      const cellsHtml = matrix.roles.map((role) => {
        const has = role.permissions?.[perm.key] === true;
        return `<td>${has ? '<span class="serverAccessCheck" title="Granted">&#10003;</span>' : '<span class="serverAccessDash" aria-hidden="true">&#8212;</span>'}</td>`;
      }).join("");
      return `
        <tr class="${escAttr(rowClass)}">
          <td class="serverAccessMatrixPermCol">${esc(perm.label)}${implemented ? "" : ' <em class="serverSettingsRolePermsBadge">Soon</em>'}</td>
          ${cellsHtml}
        </tr>
      `;
    }).join("");
    return categoryRowHtml + permRowsHtml;
  }).join("");
  return `
    <div class="serverAccessMatrixWrap">
      <table class="serverAccessMatrixTable">
        <thead><tr><th class="serverAccessMatrixPermCol">Permission</th>${headHtml}</tr></thead>
        <tbody>${bodyHtml}</tbody>
      </table>
    </div>
  `;
}

function buildServerAccessDangerousHtml(data) {
  const list = data.dangerousPermissions;
  if (!list.length) return '<div class="hint">No dangerous permissions are cataloged.</div>';
  return `
    <div class="serverAccessDangerList">
      ${list.map((perm) => `
        <div class="serverAccessDangerCard${perm.implemented ? "" : " is-not-enforced"}">
          <div class="serverAccessDangerHead">
            <strong>${esc(perm.label)}</strong>
            ${perm.implemented ? '<span class="botPermissionStatus botPermissionStatus--dangerous">Dangerous</span>' : '<span class="serverSettingsRolePermsBadge">Not yet enforced</span>'}
          </div>
          <div class="serverAccessRowHint">${esc(perm.hint || "")}</div>
          <div class="serverAccessDangerRoles">
            ${perm.holdingRoles.length
              ? perm.holdingRoles.map((role) => `<span class="serverSettingsRolePermsBadge"><span class="serverSettingsRoleSwatch" style="--role-color:${escAttr(role.color)}"></span>${esc(role.name)}${role.isDefault ? " (default)" : ""}</span>`).join("")
              : '<span class="hint">No roles currently grant this.</span>'}
          </div>
        </div>
      `).join("")}
    </div>
  `;
}

function renderServerSettingsAccessPanel({ force = false } = {}) {
  ensureServerAccessPanelStyles();
  ensureServerAccessChannelSectionStyles();
  const root = document.getElementById("serverSettingsAccessRoot");
  if (!root) return;
  const sid = normId(serverSettingsServerId || "");
  if (!sid) {
    root.innerHTML = `<div class="serverSettingsPlaceholder"><h2>Permissions / Access</h2><p>Open a server to view its access diagnostics.</p></div>`;
    return;
  }
  if (force) {
    // Best-effort background refresh using the same already-existing, read-only loader the
    // Members panel uses; re-renders this panel afterward. No new RPCs/SQL are introduced here.
    void loadServerSettingsMembersBestEffort(sid, { force: true })
      .then(() => { if (normId(serverSettingsServerId || "") === sid) renderServerSettingsAccessPanel(); })
      .catch(() => { if (normId(serverSettingsServerId || "") === sid) renderServerSettingsAccessPanel(); });
    // Phase 3B addition: also best-effort refresh channel + channel-permission-overwrite data,
    // additively alongside the members loader above (does not replace it, no new RPC shape).
    void loadServerAccessChannelsBestEffort(sid, { force: true })
      .then(() => { if (normId(serverSettingsServerId || "") === sid) renderServerSettingsAccessPanel(); })
      .catch(() => { if (normId(serverSettingsServerId || "") === sid) renderServerSettingsAccessPanel(); });
  }
  const data = computeServerAccessPanelData(sid);
  const channelData = computeServerAccessChannelSectionData(sid);
  root.innerHTML = `
    <div class="serverSettingsRolesHead">
      <div>
        <div class="label">Permissions / Access</div>
        <div class="hint">Read-only diagnostics. Nothing here edits permissions or channel overrides.</div>
      </div>
      <button class="btn ghost" type="button" data-server-settings-access-reload="1">Refresh</button>
    </div>
    <section class="serverAccessSection">
      <div class="serverAccessSectionHead">
        <h3>Your Access</h3>
        <p class="hint">${data.yourAccess.isOwner ? "You are the server owner." : `${data.yourAccess.grantedCount} of ${data.yourAccess.totalCount} permissions are granted to you, based on your resolved roles.`}</p>
      </div>
      ${buildServerAccessYourAccessHtml(data)}
    </section>
    <section class="serverAccessSection">
      <div class="serverAccessSectionHead">
        <h3>Risk Overview</h3>
        <p class="hint">Server-wide moderation and access risk summary.</p>
      </div>
      ${buildServerAccessOverviewHtml(data)}
    </section>
    <section class="serverAccessSection">
      <div class="serverAccessSectionHead">
        <h3>Role Permissions Matrix</h3>
        <p class="hint">Which roles hold which permissions.</p>
      </div>
      ${buildServerAccessMatrixHtml(data)}
    </section>
    <section class="serverAccessSection">
      <div class="serverAccessSectionHead">
        <h3>Dangerous Permissions</h3>
        <p class="hint">The highest-risk permissions cataloged in this app, and which roles currently hold them.</p>
      </div>
      ${buildServerAccessDangerousHtml(data)}
    </section>
    <section class="serverAccessSection" id="serverAccessChannelSection">
      <div class="serverAccessSectionHead">
        <h3>Channel Access Overview</h3>
        <p class="hint">${channelData.loading ? "Loading channel data…" : `${channelData.channelsCount} channel${channelData.channelsCount === 1 ? "" : "s"} (${channelData.textChannelsCount} text, ${channelData.voiceChannelsCount} voice, ${channelData.privateChannelsCount} private) — read-only per-channel visibility and access summary.`}</p>
      </div>
      ${buildServerAccessChannelsHtml(channelData, sid)}
    </section>
  `;
}

function installAltaraServerAccessDebugHelpers() {
  if (typeof window === "undefined") return;
  window.altaraDebugServerAccess = window.altaraDebugServerAccess || {};
  const resolveAccessDebugServerId = (serverId = "") => normId(serverId || serverSettingsServerId || getServerSettingsActiveServerId?.() || getActiveServerIdForSidebar?.() || "");
  window.altaraDebugServerAccess.inspect = function inspect(serverId = "") {
    const sid = resolveAccessDebugServerId(serverId);
    const result = computeServerAccessPanelData(sid);
    console.info("[server-access] inspect", result);
    return result;
  };
  window.altaraDebugServerAccess.computePanelData = function computePanelData(serverId = "") {
    return computeServerAccessPanelData(resolveAccessDebugServerId(serverId));
  };
  window.altaraDebugServerAccess.explainCurrentUser = function explainCurrentUser(serverId = "") {
    const sid = resolveAccessDebugServerId(serverId);
    const result = computeServerAccessPanelData(sid).yourAccess;
    console.info("[server-access] your-access", result);
    return result;
  };
  window.altaraDebugServerAccess.dangerousPermissions = function dangerousPermissions(serverId = "") {
    const sid = resolveAccessDebugServerId(serverId);
    const result = computeServerAccessPanelData(sid).dangerousPermissions;
    console.info("[server-access] dangerous-permissions", result);
    return result;
  };
  window.altaraDebugServerAccess.reload = function reload(serverId = "") {
    const sid = resolveAccessDebugServerId(serverId);
    if (normId(serverSettingsServerId || "") === sid) renderServerSettingsAccessPanel({ force: true });
    return computeServerAccessPanelData(sid);
  };
}
installAltaraServerAccessDebugHelpers();

// ---------------------------------------------------------------------------
// Server Settings > Permissions / Access (Phase 3B) — Channel Access Overview.
// Additive 5th section for the Access panel above. Read-only: it reuses the
// SAME real per-channel permission-overwrite machinery the (separate, not
// touched here) channel-settings permissions editor uses — getChannelPermissionOverwrites /
// applyChannelPermissionMap — layered over getServerRolePermissions(role), exactly like the
// Role Permissions Matrix section already does. A per-channel permission-overwrite model DOES
// already exist end-to-end in this codebase (client cache/resolver + a manual SQL patch under
// supabase/manual_patches/), so this section resolves real per-channel role access rather than a
// fabricated one; it only falls back to server-wide role permissions (with a visible note) when
// channelPermissionOverwritesSqlAvailable is runtime-detected as false, or shows a soft loading
// note when overwrites simply haven't finished loading yet for some channels. Nothing here writes
// to server_channels / server_channel_permission_overwrites. No RPC/network call is ever made from
// inside a render/compute function — loading only happens via loadServerAccessChannelsBestEffort(),
// invoked from renderServerSettingsAccessPanel's existing force-refresh branch and from the debug
// helper below, mirroring Phase 3A's loader pattern exactly.
// ---------------------------------------------------------------------------

const serverAccessChannelSearchByServerId = new Map();
const serverAccessChannelFilterByServerId = new Map();

