installAltaraDebugServerVoicePermissions();

function logServerTimeoutRpcError(rpcName = "", params = {}, error = null) {
  serverTimeoutLastRpcError = {
    rpcName: String(rpcName || ""),
    params,
    code: String(error?.code || ""),
    message: String(error?.message || error || ""),
    details: String(error?.details || ""),
    at: Date.now(),
  };
  if (isServerTimeoutDebugEnabled()) {
    console.warn("[server-timeouts] rpc_error", serverTimeoutLastRpcError);
  }
}

async function checkServerTimeoutSqlAvailable({ force = false, serverId = "" } = {}) {
  const sid = normId(serverId || serverSettingsServerId || getActiveServerContext()?.serverId || "");
  const freshEnough = serverTimeoutSqlAvailability.checked
    && !force
    && (Date.now() - Number(serverTimeoutSqlAvailability.checkedAt || 0) < 60000);
  if (freshEnough) return { ...serverTimeoutSqlAvailability };
  if (!sid) return markServerTimeoutSqlAvailability(serverTimeoutSqlAvailability.available !== false, serverTimeoutSqlAvailability.error);
  const res = await supabase.rpc("list_server_member_timeouts_v2", { p_server_id: sid });
  if (res?.error) {
    lastServerTimeoutError = res.error;
    logServerTimeoutRpcError("list_server_member_timeouts_v2", { p_server_id: sid }, res.error);
    if (isServerTimeoutSqlMissingError(res.error)) {
      return markServerTimeoutSqlAvailability(false, "Timeout SQL patch is required.");
    }
    return markServerTimeoutSqlAvailability(true, null);
  }
  return markServerTimeoutSqlAvailability(true, null);
}

async function listServerMemberTimeoutsForServer(serverId = "", { force = false } = {}) {
  const sid = normId(serverId || "");
  if (!sid) return { rows: [], error: { message: "server_id invalido" } };
  const now = Date.now();
  const inFlight = serverTimeoutLoadInFlightByServerId.get(sid);
  if (inFlight && !force) return inFlight;
  const lastLoadedAt = Number(serverTimeoutLastLoadedAtByServerId.get(sid) || 0);
  if (!force && serverMemberTimeoutsByServerId.has(sid) && now - lastLoadedAt < 3000) {
    return { rows: Array.from((serverMemberTimeoutsByServerId.get(sid) || new Map()).values()), error: serverMemberTimeoutErrorByServerId.get(sid) || null, unchanged: true };
  }
  if (!force && serverMemberTimeoutsByServerId.has(sid)) {
    return { rows: Array.from((serverMemberTimeoutsByServerId.get(sid) || new Map()).values()), error: serverMemberTimeoutErrorByServerId.get(sid) || null };
  }
  const promise = (async () => {
    serverMemberTimeoutLoadingByServerId.set(sid, true);
    serverMemberTimeoutErrorByServerId.delete(sid);
    const res = await supabase.rpc("list_server_member_timeouts_v2", { p_server_id: sid });
    serverMemberTimeoutLoadingByServerId.set(sid, false);
    serverTimeoutLastLoadedAtByServerId.set(sid, Date.now());
    if (res?.error) {
      lastServerTimeoutError = res.error;
      logServerTimeoutRpcError("list_server_member_timeouts_v2", { p_server_id: sid }, res.error);
      serverMemberTimeoutErrorByServerId.set(sid, res.error);
      if (isServerTimeoutSqlMissingError(res.error)) markServerTimeoutSqlAvailability(false, "Timeout SQL patch is required.");
      return { rows: [], error: res.error };
    }
    markServerTimeoutSqlAvailability(true, null);
    const rows = (Array.isArray(res.data) ? res.data : []).map(mergeServerTimeoutRowWithCachedProfiles).filter(Boolean).filter((row) => isServerMemberTimeoutActive(row));
    const changed = hasServerTimeoutSnapshotChanged(sid, rows);
    if (changed || !serverMemberTimeoutsByServerId.has(sid)) {
      const map = new Map();
      rows.forEach((row) => {
        map.set(row.userId, row);
        scheduleServerMemberTimeoutExpiry(row);
      });
      serverMemberTimeoutsByServerId.set(sid, map);
      rememberServerTimeoutSnapshot(sid);
    }
    serverMemberTimeoutErrorByServerId.delete(sid);
    void hydrateServerTimeoutProfiles(sid, { reason: "timeouts_loaded" }).catch(() => {});
    return { rows: Array.from((serverMemberTimeoutsByServerId.get(sid) || new Map()).values()), error: null, changed };
  })().finally(() => {
    serverTimeoutLoadInFlightByServerId.delete(sid);
  });
  serverTimeoutLoadInFlightByServerId.set(sid, promise);
  return promise;
}

async function loadCurrentUserServerTimeout(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid || !state.user?.id) return null;
  const before = stringifyServerTimeoutSnapshotRows(getServerTimeoutSnapshotRows(sid));
  const res = await supabase.rpc("get_my_server_timeout_v2", { p_server_id: sid });
  if (res?.error) {
    lastServerTimeoutError = res.error;
    logServerTimeoutRpcError("get_my_server_timeout_v2", { p_server_id: sid }, res.error);
    if (isServerTimeoutSqlMissingError(res.error)) markServerTimeoutSqlAvailability(false, "Timeout SQL patch is required.");
    return null;
  }
  markServerTimeoutSqlAvailability(true, null);
  const data = res?.data || {};
  if (data?.active === true) {
    return upsertServerMemberTimeoutInCache({
      serverId: sid,
      userId: state.user.id,
      expiresAt: data.expiresAt || data.expires_at,
      reason: data.reason || "",
    }, { source: "get_my_server_timeout" });
  }
  const map = getServerTimeoutMap(sid, { create: true });
  const uid = normId(state.user.id || "");
  const existed = !!map?.delete(uid);
  clearServerMemberTimeoutTimer(sid, uid);
  rememberServerTimeoutSnapshot(sid);
  if (existed || before !== stringifyServerTimeoutSnapshotRows(getServerTimeoutSnapshotRows(sid))) {
    renderServerTimeoutAffectedUi(sid, uid, "current_user_timeout_absent");
  }
  return null;
}

async function timeoutServerMemberOnServer(serverId = "", userId = "", { seconds = 600, reason = "" } = {}) {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return { data: null, error: { message: "server_id/user_id invalido" } };
  if (!canCurrentUserTimeoutServerMember(sid, uid)) {
    return { data: null, error: { message: "You don't have permission to timeout this member." } };
  }
  if (serverTimeoutSqlAvailability.checked && serverTimeoutSqlAvailability.available === false) {
    return { data: null, error: { message: getServerTimeoutSqlMissingError(), code: "timeout_sql_missing", _timeoutSqlMissing: true } };
  }
  const duration = Math.max(60, Math.min(2419200, Math.round(Number(seconds || 0) || 600)));
  const res = await supabase.rpc("timeout_server_member_v2", {
    p_server_id: sid,
    p_target_user_id: uid,
    p_duration_seconds: duration,
    p_reason: String(reason || "").trim().slice(0, 500) || null,
  });
  if (res?.error) {
    lastServerTimeoutError = res.error;
    logServerTimeoutRpcError("timeout_server_member_v2", {
      p_server_id: sid,
      p_target_user_id: uid,
      p_duration_seconds: duration,
      p_reason: String(reason || "").trim().slice(0, 500) || null,
    }, res.error);
    if (isServerTimeoutSqlMissingError(res.error)) markServerTimeoutSqlAvailability(false, "Timeout SQL patch is required.");
    return res;
  }
  const data = res?.data || {};
  const row = upsertServerMemberTimeoutInCache({
    serverId: sid,
    userId: uid,
    reason: data.reason || reason || "",
    expiresAt: data.expiresAt || data.expires_at,
    timedOutBy: data.timedOutBy || data.timed_out_by || state.user?.id || "",
  }, { source: "timeout_rpc_success" });
  const voiceRow = getServerVoiceV2Member?.(uid) || null;
  if (voiceRow && normId(voiceRow.serverId || voiceRow.server_id || "") === sid) {
    deleteServerVoiceV2MemberRow({ server_id: sid, user_id: uid }, "timeout_rpc_success");
    if (isServerTimeoutDebugEnabled()) {
      console.info("[server-timeouts] target evicted from voice after timeout", { serverId: sid, userId: uid });
    }
  }
  void broadcastServerTimeoutUpdated(sid, {
    targetUserId: uid,
    active: true,
    expiresAt: row?.expiresAt || data.expiresAt || data.expires_at || "",
    reason: row?.reason || reason || "",
  });
  return res;
}

async function clearServerMemberTimeoutOnServer(serverId = "", userId = "") {
  const sid = normId(serverId || "");
  const uid = normId(userId || "");
  if (!sid || !uid) return { data: null, error: { message: "server_id/user_id invalido" } };
  if (!canCurrentUserTimeoutServerMember(sid, uid)) {
    return { data: null, error: { message: "You don't have permission to remove this timeout." } };
  }
  if (serverTimeoutSqlAvailability.checked && serverTimeoutSqlAvailability.available === false) {
    return { data: null, error: { message: getServerTimeoutSqlMissingError(), code: "timeout_sql_missing", _timeoutSqlMissing: true } };
  }
  const res = await supabase.rpc("clear_server_member_timeout_v2", {
    p_server_id: sid,
    p_target_user_id: uid,
  });
  if (res?.error) {
    lastServerTimeoutError = res.error;
    logServerTimeoutRpcError("clear_server_member_timeout_v2", {
      p_server_id: sid,
      p_target_user_id: uid,
    }, res.error);
    if (isServerTimeoutSqlMissingError(res.error)) markServerTimeoutSqlAvailability(false, "Timeout SQL patch is required.");
    return res;
  }
  removeServerMemberTimeoutFromCache(sid, uid, { reason: "timeout_clear_rpc_success", source: "clear_rpc_success" });
  void broadcastServerTimeoutUpdated(sid, { targetUserId: uid, active: false });
  return res;
}

function getServerTimeoutBroadcastChannelName(serverId = "") {
  const sid = normId(serverId || "");
  return sid ? `server-timeouts:${sid}` : "";
}

async function broadcastServerTimeoutUpdated(serverId = "", payload = {}) {
  const sid = normId(serverId || "");
  const channelName = getServerMemberBroadcastChannelName(sid);
  if (!sid || !channelName) return false;
  try {
    const channel = serverMemberRemovalBroadcastChannels.get(sid) || supabase.channel(channelName, { config: { broadcast: { self: false } } });
    if (!serverMemberRemovalBroadcastChannels.has(sid)) {
      serverMemberRemovalBroadcastChannels.set(sid, channel);
      await new Promise((resolve) => {
        channel.subscribe(() => resolve());
        setTimeout(resolve, 900);
      });
    }
    const body = {
      type: "server_timeout_updated",
      serverId: sid,
      actorUserId: normId(state.user?.id || ""),
      updatedAt: new Date().toISOString(),
      ...payload,
    };
    lastServerTimeoutBroadcastEvent = { sent: true, payload: body, at: Date.now() };
    await channel.send({ type: "broadcast", event: "server_timeout_updated", payload: body });
    return true;
  } catch (error) {
    lastServerTimeoutBroadcastEvent = { sent: false, error: String(error?.message || error || ""), at: Date.now() };
    return false;
  }
}

async function broadcastServerModerationUpdated(serverId = "", payload = {}) {
  const sid = normId(serverId || "");
  const channelName = getServerMemberBroadcastChannelName(sid);
  if (!sid || !channelName) return false;
  try {
    const channel = serverMemberRemovalBroadcastChannels.get(sid) || supabase.channel(channelName, { config: { broadcast: { self: false } } });
    if (!serverMemberRemovalBroadcastChannels.has(sid)) {
      serverMemberRemovalBroadcastChannels.set(sid, channel);
      await new Promise((resolve) => {
        channel.subscribe(() => resolve());
        setTimeout(resolve, 900);
      });
    }
    const body = {
      type: "server_moderation_updated",
      serverId: sid,
      actorUserId: normId(state.user?.id || ""),
      updatedAt: new Date().toISOString(),
      ...payload,
    };
    serverSettingsModerationLastRealtimeEvent = { sent: true, payload: body, at: Date.now() };
    await channel.send({ type: "broadcast", event: "server_moderation_updated", payload: body });
    return true;
  } catch (error) {
    serverSettingsModerationLastRealtimeEvent = { sent: false, serverId: sid, error: String(error?.message || error || ""), at: Date.now() };
    return false;
  }
}

