      loadInFlightByServerId: Array.from(serverTimeoutLoadInFlightByServerId.keys()),
      lastLoadedAtByServerId: Array.from(serverTimeoutLastLoadedAtByServerId.entries()).map(([serverId, at]) => ({ serverId, at })),
      lastTimeoutSnapshotByServerId: Array.from(serverTimeoutLastSnapshotByServerId.entries()).map(([serverId, snapshot]) => ({ serverId, snapshot })),
      renderCountByReason: Array.from(serverTimeoutRenderCountByReason.entries()).map(([reason, count]) => ({ reason, count })),
      lastRenderReason: serverTimeoutLastRenderReason,
      lastRenderAt: serverTimeoutLastRenderAt,
      lastRpcError: serverTimeoutLastRpcError,
      timeoutLastRpcError: serverTimeoutLastRpcError,
      timeoutProfilesMissing: timeoutProfileState.missing,
      timeoutProfilesHydrating: timeoutProfileState.hydrating,
      timeoutRowsHydrated: visibleTimeoutRows.filter((row) => !isServerTimeoutProfilePlaceholder(row)).length,
      visibleTimeoutRows,
      hoverRenderGuardActive: true,
      lastRealtimeEvent: lastServerTimeoutRealtimeEvent,
      lastBroadcastEvent: lastServerTimeoutBroadcastEvent,
      composerBlockedReason: lastServerTimeoutComposerBlockedReason,
      voiceBlockedReason: lastServerTimeoutVoiceBlockedReason,
      lastVoiceEvictionEvent: lastServerTimeoutVoiceEvictionEvent,
      sqlPatchAvailable: serverTimeoutSqlPatchAvailable,
