function formatServerAuditDate(value = "") {
  const stamp = Date.parse(String(value || ""));
  if (!Number.isFinite(stamp)) return "";
  const diff = Date.now() - stamp;
  if (diff >= 0 && diff < 60000) return "just now";
  if (diff >= 0 && diff < 3600000) return `${Math.max(1, Math.floor(diff / 60000))}m ago`;
  if (diff >= 0 && diff < 86400000) return `${Math.max(1, Math.floor(diff / 3600000))}h ago`;
  try {
    return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(stamp));
  } catch (_) {
    return new Date(stamp).toLocaleString();
  }
}

function getServerAuditLogRowsForDisplay(serverId = "") {
  const sid = normId(serverId || "");
  const filter = String(serverAuditLogFilterByServerId.get(sid) || "all").trim() || "all";
  const query = String(serverAuditLogSearchByServerId.get(sid) || "").trim().toLowerCase();
  return (serverAuditLogsByServerId.get(sid) || [])
    .filter((row) => filter === "all" || getServerAuditLogActionGroup(row.action) === filter)
    .filter((row) => {
      if (!query) return true;
      return [
        row.id,
        row.action,
        row.reason,
        row.actorUserId,
        row.actorUsername,
        row.actorDisplayName,
        row.targetUserId,
        row.targetUsername,
        row.targetDisplayName,
        JSON.stringify(row.metadata || {}),
      ].join(" ").toLowerCase().includes(query);
    });
}

function isServerAuditLogMissingSqlError(error = null) {
  return isMissingRpcError(error) || isMissingTableError(error, "server_audit_logs");
}

async function loadServerAuditLogs(serverId = "", { force = false } = {}) {
  const sid = normId(serverId || "");
  if (!sid) return { rows: [], error: { message: "server_id invalido" } };
  const inFlight = serverAuditLogLoadInFlightByServerId.get(sid);
  if (inFlight && !force) return inFlight;
  const lastLoadedAt = Number(serverAuditLogLastLoadedAtByServerId.get(sid) || 0);
  if (!force && serverAuditLogsByServerId.has(sid) && Date.now() - lastLoadedAt < 3000) {
    return { rows: serverAuditLogsByServerId.get(sid) || [], error: serverAuditLogErrorByServerId.get(sid) || null, unchanged: true };
  }
  if (!force && serverAuditLogsByServerId.has(sid)) {
    return { rows: serverAuditLogsByServerId.get(sid) || [], error: serverAuditLogErrorByServerId.get(sid) || null };
  }
  const promise = (async () => {
    serverAuditLogLoadingByServerId.set(sid, true);
    serverAuditLogErrorByServerId.delete(sid);
    const res = await supabase.rpc("list_server_audit_logs_v2", {
      p_server_id: sid,
      p_limit: 50,
      p_action: null,
      p_target_user_id: null,
    });
    serverAuditLogLoadingByServerId.set(sid, false);
    serverAuditLogLastLoadedAtByServerId.set(sid, Date.now());
    if (res?.error) {
      serverAuditLogErrorByServerId.set(sid, res.error);
      lastServerAuditLogRpcError = { rpcName: "list_server_audit_logs_v2", serverId: sid, message: res.error?.message || String(res.error || ""), code: res.error?.code || "", at: Date.now() };
      return { rows: [], error: res.error };
    }
    const rows = (Array.isArray(res.data) ? res.data : []).map(mergeServerAuditLogWithCachedProfiles).filter(Boolean);
    const previous = serverAuditLogLastSnapshotByServerId.get(sid) || stringifyServerAuditLogSnapshot(serverAuditLogsByServerId.get(sid) || []);
    const next = stringifyServerAuditLogSnapshot(rows);
    if (previous !== next || !serverAuditLogsByServerId.has(sid)) {
      serverAuditLogsByServerId.set(sid, rows);
      serverAuditLogLastSnapshotByServerId.set(sid, next);
    }
    void hydrateServerAuditLogProfiles(sid, { force: false }).catch(() => {});
    return { rows: serverAuditLogsByServerId.get(sid) || rows, error: null, changed: previous !== next };
  })().finally(() => {
    serverAuditLogLoadInFlightByServerId.delete(sid);
  });
  serverAuditLogLoadInFlightByServerId.set(sid, promise);
  return promise;
}

function applyServerAuditLogRealtimeRow(rowInput = {}, { source = "realtime" } = {}) {
  const row = mergeServerAuditLogWithCachedProfiles(rowInput);
  if (!row) return false;
  const sid = row.serverId;
  const rows = serverAuditLogsByServerId.get(sid) || [];
  const next = [row, ...rows.filter((entry) => normId(entry?.id || "") !== row.id)]
    .sort((a, b) => Date.parse(b.createdAt || "") - Date.parse(a.createdAt || ""))
    .slice(0, 100);
  serverAuditLogsByServerId.set(sid, next);
  serverAuditLogLastSnapshotByServerId.set(sid, stringifyServerAuditLogSnapshot(next));
  serverAuditLogLastLoadedAtByServerId.set(sid, Date.now());
  lastServerAuditLogRealtimeEvent = { source, row, at: Date.now() };
  void hydrateServerAuditLogProfiles(sid, { force: false }).catch(() => {});
  if (normId(serverSettingsServerId || "") === sid) renderServerSettingsModerationPanel();
  return true;
}

async function loadServerSettingsModerationBestEffort(serverId, { force = false } = {}) {
  const sid = normId(serverId || "");
  if (!sid || normId(serverSettingsServerId || "") !== sid) return null;
  serverBanListLoadingByServerId.set(sid, true);
  serverMemberTimeoutLoadingByServerId.set(sid, true);
  serverAuditLogLoadingByServerId.set(sid, true);
  renderServerSettingsModerationPanel();
  const [bansResult, timeoutsResult, auditResult] = await Promise.allSettled([
    listServerBansForServer(sid, { force }),
    listServerMemberTimeoutsForServer(sid, { force }),
    loadServerAuditLogs(sid, { force }),
  ]);
  if (normId(serverSettingsServerId || "") !== sid) return null;
  serverBanListLoadingByServerId.set(sid, false);
  serverMemberTimeoutLoadingByServerId.set(sid, false);
  serverAuditLogLoadingByServerId.set(sid, false);
  if (bansResult.status === "fulfilled") {
    if (bansResult.value?.error) serverBanListErrorByServerId.set(sid, bansResult.value.error);
    else serverBanListErrorByServerId.delete(sid);
  } else {
    serverBanListErrorByServerId.set(sid, bansResult.reason || { message: "Could not load bans." });
    serverSettingsModerationLastRpcError = { rpcName: "list_server_bans_v2", serverId: sid, message: bansResult.reason?.message || String(bansResult.reason || ""), at: Date.now() };
  }
  if (timeoutsResult.status === "fulfilled") {
    if (timeoutsResult.value?.error) serverMemberTimeoutErrorByServerId.set(sid, timeoutsResult.value.error);
    else serverMemberTimeoutErrorByServerId.delete(sid);
  } else {
    serverMemberTimeoutErrorByServerId.set(sid, timeoutsResult.reason || { message: "Could not load timeouts." });
    serverSettingsModerationLastRpcError = { rpcName: "list_server_member_timeouts_v2", serverId: sid, message: timeoutsResult.reason?.message || String(timeoutsResult.reason || ""), at: Date.now() };
  }
  if (auditResult.status === "fulfilled") {
    if (auditResult.value?.error) serverAuditLogErrorByServerId.set(sid, auditResult.value.error);
    else serverAuditLogErrorByServerId.delete(sid);
  } else {
    serverAuditLogErrorByServerId.set(sid, auditResult.reason || { message: "Could not load audit log." });
    lastServerAuditLogRpcError = { rpcName: "list_server_audit_logs_v2", serverId: sid, message: auditResult.reason?.message || String(auditResult.reason || ""), at: Date.now() };
  }
  renderServerSettingsModerationPanel();
  return {
    bans: bansResult.status === "fulfilled" ? bansResult.value : null,
    timeouts: timeoutsResult.status === "fulfilled" ? timeoutsResult.value : null,
    audit: auditResult.status === "fulfilled" ? auditResult.value : null,
  };
}

function getServerSettingsMembersForDisplay(serverId = "") {
  const sid = normId(serverId || "");
  const query = String(serverSettingsMembersSearchQuery || "").trim().toLowerCase();
  const server = getServerRowById(sid) || { id: sid };
  const humans = (serverMemberListByServerId.get(sid) || []).map((member) => ({ ...member, isBot: member?.isBot === true }));
  const humanIds = new Set(humans.map((member) => normId(member?.userId || "")).filter(Boolean));
  const bots = (serverBotInstallListByServerId.get(sid) || [])
    .filter((bot) => {
      const uid = normId(bot?.userId || bot?.botId || "");
      return uid && !humanIds.has(uid);
    })
    .map((bot) => ({
      ...bot,
      userId: normId(bot?.userId || bot?.botId || ""),
      username: String(bot?.username || bot?.publicId || "bot").trim(),
      displayName: String(bot?.displayName || bot?.botName || "Bot").trim() || "Bot",
      avatarUrl: String(bot?.avatarUrl || bot?.botAvatarUrl || "").trim(),
      joinedAt: Number(bot?.joinedAt || 0),
      role: "bot",
      isBot: true,
    }));
  return [...humans, ...bots]
    .filter((member) => {
      if (!query) return true;
      const uid = normId(member?.userId || "");
      const haystack = [
        uid,
        member?.username,
        resolveServerDisplayName(sid, uid, member, "Member"),
        getServerMemberGlobalDisplayName(member),
        getServerMemberServerNickname(member),
        member?.role,
        ...getServerSettingsMemberRoles(sid, uid).map((role) => role.name),
      ].join(" ").toLowerCase();
      return haystack.includes(query);
    })
    .slice()
    .sort((a, b) => {
      const ownerA = isServerOwnerUser(server, normId(a?.userId || ""), a);
      const ownerB = isServerOwnerUser(server, normId(b?.userId || ""), b);
      if (ownerA !== ownerB) return ownerA ? -1 : 1;
      const onlineA = getPresenceStatusForServerMember(a?.userId || "") !== "offline";
      const onlineB = getPresenceStatusForServerMember(b?.userId || "") !== "offline";
      const rankA = getRoleHierarchyRank(getServerRoleHighestPositionForMember(sid, a?.userId || ""));
      const rankB = getRoleHierarchyRank(getServerRoleHighestPositionForMember(sid, b?.userId || ""));
      if (rankA !== rankB) return rankA - rankB;
      if (a?.isBot !== b?.isBot) return a?.isBot ? 1 : -1;
      if (onlineA !== onlineB) return onlineA ? -1 : 1;
      return getServerSettingsMemberDisplayName(a, sid).localeCompare(getServerSettingsMemberDisplayName(b, sid));
    });
}

