const serverSettingsChannelsRefreshInFlightByServerId = new Map();
const serverSettingsChannelsSelectionByServerId = new Map();
const serverSettingsChannelsExpandedByServerId = new Map();
const serverSettingsChannelsRenderSignatureByServerId = new Map();
