function isLocalServerVoiceCallContextActive(conversationId) {
  const convId = normId(conversationId || "");
  if (!convId || !isServerVoiceConversationById(convId)) return false;
  if (normId(callConversationId || "") !== convId) return false;
  return !!(
    isServerVoiceTransportSessionActive(convId) ||
    inCall ||
    pendingOffer ||
    pendingGroupRingInfo ||
    ringTimeout ||
    (callPc && callPc.connectionState !== "closed" && callPc.connectionState !== "failed")
  );
}

async function requestServerVoicePresenceSnapshot(conversationId, { targetUserIds = [], force = false } = {}) {
  const convId = normId(conversationId || "");
  const meId = normId(state.user?.id || "");
  if (!convId || !meId || !isServerVoiceConversationById(convId)) return false;
  if (shouldUseServerVoiceLiveKitTransport(convId)) return false;
  if (getAuthoritativeServerVoicePresenceMembers(convId) !== null) return false;

  const now = Date.now();
  const lastProbeAt = Number(serverVoicePresenceProbeAtByConversation.get(convId) || 0);
  if (!force && lastProbeAt > 0 && (now - lastProbeAt) < SERVER_VOICE_PRESENCE_PROBE_THROTTLE_MS) {
    return false;
  }
  serverVoicePresenceProbeAtByConversation.set(convId, now);

  const conversationMeta = getActiveConversationMeta(convId) || getConversationMeta(convId) || {};
  const serverCtx = findServerChannelContextByConversationId(convId) || {};
  const sid = normId(serverCtx?.serverId || "");
  const serverMembers = sid ? (serverMemberListByServerId.get(sid) || []) : [];
  const probeTargets = normalizeUuidArray([
    ...normalizeUuidArray(targetUserIds),
    ...normalizeUuidArray(groupCallMemberIds),
    ...getServerVoicePresenceMemberIds(convId),
    ...normalizeUuidArray(conversationMeta?.memberIds || []),
    ...normalizeUuidArray((serverMembers || []).map((m) => m?.userId || "")),
  ]).filter((uid) => uid && uid !== meId);
  if (!probeTargets.length) return false;

  const payload = {
    signal: "group_presence_probe",
    group_call: true,
    from_label: state.me?.display_name || state.me?.username || t("call.someone", "someone"),
    from_avatar: state.me?.avatar_url || null,
    presence_ts: now,
  };

  await Promise.allSettled(
    probeTargets.map((uid) => sendCallSignal("ice", payload, uid, convId))
  );
  return true;
}

function requestServerVoicePresenceSnapshotsForServer(serverId, channels = [], members = []) {
  const sid = normId(serverId || "");
  if (!sid) return;

  const memberIds = normalizeUuidArray(
    (Array.isArray(members) ? members : []).map((m) => m?.userId || "")
  );
  const voiceChannels = (Array.isArray(channels) ? channels : []).filter((ch) => {
    return normalizeConversationChannelType(ch?.channelType || "") === "voice";
  });
  if (!voiceChannels.length) return;
  voiceChannels.forEach((channel, idx) => {
    const convId = normId(channel?.conversationId || "");
    if (!convId) return;
    const delayMs = Math.min(420, idx * 80);
    setTimeout(() => {
      void requestServerVoicePresenceSnapshot(convId, {
        targetUserIds: memberIds,
        force: idx === 0,
      });
    }, delayMs);
  });
}

function getServerVoiceUiVisibilityEntry(conversationId, { create = false } = {}) {
  const convId = normId(conversationId || "");
  if (!convId) return null;
  let entry = serverVoiceUiVisibilityByConversation.get(convId) || null;
  if (!entry && create) {
    entry = {
      visibleIds: [],
      seenAtByUser: new Map(),
      leaveGraceUntilByUser: new Map(),
    };
    serverVoiceUiVisibilityByConversation.set(convId, entry);
  }
  return entry;
}

function logServerVoiceUiParticipantsEvent(event, conversationId, visibleParticipantIds = [], triggerReason = "", extra = {}) {
  const convId = normId(conversationId || "");
  if (!convId) return;
  const visibleIds = normalizeUuidArray(visibleParticipantIds || []);
  const details = {
    conversationId: convId,
    visibleParticipantIds: visibleIds,
    count: visibleIds.length,
    triggerReason: String(triggerReason || "").trim() || null,
    ...(extra && typeof extra === "object" && !Array.isArray(extra) ? extra : {}),
  };
  writeStructuredServerVoiceConsoleLog("[server-voice ui]", event, details, {
    level: "info",
    channel: "server-voice-ui",
  });
}

function logServerVoiceOccupancyEvent(event, conversationId, occupantIds = [], {
  triggerReason = "",
  callerFunction = "",
  sourceType = "",
  ...extra
} = {}) {
  const convId = normId(conversationId || "");
  if (!convId) return;
  const ids = normalizeUuidArray(occupantIds || []);
  const details = {
    conversationId: convId,
    occupantIds: ids,
    count: ids.length,
    triggerReason: String(triggerReason || "").trim() || null,
    callerFunction: String(callerFunction || "").trim() || null,
    sourceType: String(sourceType || "").trim() || null,
    ...(extra && typeof extra === "object" && !Array.isArray(extra) ? extra : {}),
  };
  try {
    if (Array.isArray(serverVoiceLastPresenceEvents)) {
      serverVoiceLastPresenceEvents.push({ at: Date.now(), event: String(event || "").slice(0, 80), ...details });
      while (serverVoiceLastPresenceEvents.length > SERVER_VOICE_MUTE_EVENT_HISTORY_LIMIT) serverVoiceLastPresenceEvents.shift();
    }
  } catch (_) {}
  writeStructuredServerVoiceConsoleLog("[server-voice occupancy]", event, details, {
    level: "info",
    channel: "server-voice-occupancy",
  });
}

function getServerVoiceControlPlaneOccupancySnapshot(conversationId, {
  context = null,
  allowFallback = true,
} = {}) {
  const convId = normId(conversationId || "");
  if (!convId) {
    return {
      source: "none",
      occupantIds: [],
      authoritative: false,
      contextJoined: false,
      presenceSynced: false,
    };
  }
  const activeContext = context || getCallRealtimeChannelContext(convId) || null;
  const contextPresenceMembers = Array.isArray(activeContext?.presenceMembers)
    ? activeContext.presenceMembers
    : [];
  const contextPresenceIds = normalizeUuidArray(
    contextPresenceMembers.map((member) => member?.userId || "")
  );
  const authoritativeMembers = getAuthoritativeServerVoicePresenceMembers(convId);
  if (Array.isArray(authoritativeMembers)) {
    return {
      source: "supabase_realtime_presence",
      occupantIds: normalizeUuidArray(authoritativeMembers.map((member) => member?.userId || "")),
      authoritative: true,
      contextJoined: !!activeContext?.joined,
      presenceSynced: !!activeContext?.presenceSynced,
    };
  }
  if (contextPresenceIds.length) {
    return {
      source: "realtime_presence_context_cache",
      occupantIds: contextPresenceIds,
      authoritative: false,
      contextJoined: !!activeContext?.joined,
      presenceSynced: !!activeContext?.presenceSynced,
    };
  }
  if (!allowFallback) {
    return {
      source: "none",
      occupantIds: [],
      authoritative: false,
      contextJoined: !!activeContext?.joined,
      presenceSynced: !!activeContext?.presenceSynced,
    };
  }
  return {
    source: "local_control_plane_cache",
    occupantIds: normalizeUuidArray(getServerVoicePresenceMemberIds(convId)),
    authoritative: false,
    contextJoined: !!activeContext?.joined,
    presenceSynced: !!activeContext?.presenceSynced,
  };
}


function isServerVoiceTransportSnapshotAuthoritativeForPresence(conversationId, snapshot = null) {
  const convId = normId(conversationId || "");
  if (!convId || !shouldUseServerVoiceLiveKitTransport(convId)) return false;
  const resolvedSnapshot = snapshot || getServerVoiceTransportSnapshot(convId);
  if (!resolvedSnapshot || typeof resolvedSnapshot !== "object" || Array.isArray(resolvedSnapshot)) return false;
  const connectionState = String(resolvedSnapshot?.connectionState || "").trim().toLowerCase();
  const joinPhase = String(resolvedSnapshot?.joinPhase || "").trim().toLowerCase();
  return !!(
    resolvedSnapshot?.local?.roomConnected === true
    || resolvedSnapshot?.connected === true
    || connectionState === "connected"
    || connectionState === "reconnecting"
    || connectionState === "signalreconnecting"
    || joinPhase === "room_connected"
    || joinPhase === "media_ready"
    || joinPhase === "publishing_audio"
    || joinPhase === "reconnecting"
  );
}

function getServerVoicePresenceHeartbeatAgeMsByUser(conversationId, userIds = []) {
  const convId = normId(conversationId || "");
  const ids = normalizeUuidArray(userIds || []);
  const ages = {};
  if (!convId || !ids.length) return ages;
  const now = Date.now();
  const entry = getServerVoicePresenceEntry(convId, { create: false });
  ids.forEach((uid) => {
    const seenAt = Number(
      entry?.seenAtByUser?.get?.(uid)
      || groupCallPresenceSeenAtByUser.get(uid)
      || 0
    );
    ages[uid] = Number.isFinite(seenAt) && seenAt > 0 ? Math.max(0, now - seenAt) : null;
  });
  return ages;
}

function pruneServerVoiceStaleVisibleParticipantCaches(conversationId, staleIds = [], {
  finalVisibleIds = [],
  triggerReason = "",
  callerFunction = "",
} = {}) {
  const convId = normId(conversationId || "");
  const ids = normalizeUuidArray(staleIds || []);
  if (!convId || !ids.length) return [];
  const finalSet = new Set(normalizeUuidArray(finalVisibleIds || []));
  const forcedEntry = getServerVoiceUiForcedRemovedEntry(convId, { create: true });
  const prunedIds = [];
  ids.forEach((uid) => {
    if (!uid || finalSet.has(uid)) return;
    if (isBotVoiceParticipantIdentity(uid) || getServerVoiceBotSessionMeta(convId, uid)) {
      recordBotVoiceUiEvent("bot_voice_prune_skipped", {
        botId: getBotIdFromVoiceParticipantIdentity(uid) || getServerVoiceBotSessionMeta(convId, uid)?.botId || "",
        conversationId: convId,
        rowSource: "bot_voice_session_or_identity",
        visible: true,
        removed: false,
        removeReason: "user_occupancy_snapshot_not_authoritative_for_bots",
        botVoiceSessionPresent: !!getServerVoiceBotSessionMeta(convId, uid),
      });
      return;
    }
    const transportState = getServerVoiceTransportParticipantState(convId, uid);
    if (isServerVoiceTransportParticipantInChannel(convId, uid, transportState)) return;
    forcedEntry?.add?.(uid);
    removeServerVoiceUiCachedParticipantState(convId, uid);
    prunedIds.push(uid);
  });
  if (prunedIds.length) {
    logServerVoiceUiParticipantsEvent("ui.stale_participant_cache_pruned", convId, normalizeUuidArray(finalVisibleIds || []), triggerReason || "presence_resolution", {
      callerFunction: callerFunction || "pruneServerVoiceStaleVisibleParticipantCaches",
      prunedIds,
      source: "livekit_authoritative_presence_resolution",
    });
  }
  return prunedIds;
}

function logServerVoicePresenceResolution(conversationId, {
  triggerReason = "",
  callerFunction = "",
  liveKitParticipantIds = [],
  supabasePresenceIds = [],
  localCacheIds = [],
  stalePrunedIds = [],
  finalVisibleIds = [],
  sourceReasonsByUserId = {},
  usedLiveKitAuthoritative = false,
  transportConnectionState = "",
  transportJoinPhase = "",
} = {}) {
  if (!isServerVoiceDebugLoggingEnabled()) return;
  const convId = normId(conversationId || "");
  if (!convId) return;
  const meId = normId(state.user?.id || "");
  const allIds = normalizeUuidArray([
    ...normalizeUuidArray(liveKitParticipantIds || []),
    ...normalizeUuidArray(supabasePresenceIds || []),
    ...normalizeUuidArray(localCacheIds || []),
    ...normalizeUuidArray(stalePrunedIds || []),
    ...normalizeUuidArray(finalVisibleIds || []),
  ]);
  logServerVoiceDebug("server_voice_presence_resolution", {
    currentUserId: meId || null,
    channelId: convId,
    conversationId: convId,
    liveKitParticipantIds: normalizeUuidArray(liveKitParticipantIds || []),
    supabasePresenceIds: normalizeUuidArray(supabasePresenceIds || []),
    localCacheIds: normalizeUuidArray(localCacheIds || []),
    stalePrunedIds: normalizeUuidArray(stalePrunedIds || []),
    finalVisibleIds: normalizeUuidArray(finalVisibleIds || []),
    reasonsByUserId: sourceReasonsByUserId || {},
    heartbeatAgeMsByUserId: getServerVoicePresenceHeartbeatAgeMsByUser(convId, allIds),
    usedLiveKitAuthoritative: !!usedLiveKitAuthoritative,
    transportConnectionState: String(transportConnectionState || "").trim() || null,
    transportJoinPhase: String(transportJoinPhase || "").trim() || null,
    triggerReason: String(triggerReason || "").trim() || "unknown",
    callerFunction: String(callerFunction || "").trim() || "unknown",
    resolvedAt: new Date().toISOString(),
  });
}

function areServerVoiceUiIdSetsEqual(left = [], right = []) {
  const a = normalizeUuidArray(left || []);
  const b = normalizeUuidArray(right || []);
  if (a.length !== b.length) return false;
  const bSet = new Set(b);
  return a.every((value) => bSet.has(value));
}

function getServerVoiceLegacyUiParticipantIds(conversationId) {
  const convId = normId(conversationId || "");
  const meId = normId(state.user?.id || "");
  if (!convId) return [];
  return normalizeUuidArray([
    ...(normId(groupCallActiveMembersConversationId || "") === convId
      ? normalizeUuidArray(groupCallActiveMemberIds)
      : []),
    ...getServerVoicePresenceMemberIds(convId),
    ...getServerVoiceTransportParticipantIds(convId),
    ...(isLocalServerVoiceCallContextActive(convId) && meId ? [meId] : []),
  ]);
}

function auditServerVoiceUiSource(conversationId, {
  visibleParticipantIds = [],
  triggerReason = "",
  callerFunction = "",
  sourceKind = "unified",
  usesUnifiedSource = true,
  legacyVisibleParticipantIds = null,
} = {}) {
  const convId = normId(conversationId || "");
  const hasTransportContext = !!(
    getServerVoiceTransportSnapshot(convId)
    || getActiveServerVoiceTransportController(convId)
    || serverVoiceUiVisibilityByConversation.has(convId)
  );
  if (!convId || (!isServerVoiceConversationById(convId) && !hasTransportContext)) return;
  const visibleIds = normalizeUuidArray(visibleParticipantIds || []);
  const reason = String(triggerReason || "").trim() || "unknown";
  const caller = String(callerFunction || "").trim() || "unknown";
  const source = String(sourceKind || "").trim() || "unknown";
  const legacyIds = Array.isArray(legacyVisibleParticipantIds)
    ? normalizeUuidArray(legacyVisibleParticipantIds)
    : getServerVoiceLegacyUiParticipantIds(convId);
  logServerVoiceUiParticipantsEvent("ui.source_audit", convId, visibleIds, reason, {
    callerFunction: caller,
    sourceKind: source,
    usesUnifiedSource: !!usesUnifiedSource,
    legacyVisibleParticipantIds: legacyIds,
  });
  if (!areServerVoiceUiIdSetsEqual(visibleIds, legacyIds)) {
    logServerVoiceUiParticipantsEvent("ui.render_source_mismatch", convId, visibleIds, reason, {
      callerFunction: caller,
      sourceKind: source,
      unifiedVisibleParticipantIds: visibleIds,
      legacyVisibleParticipantIds: legacyIds,
    });
  }
}

function getServerVoiceUiForcedRemovedEntry(conversationId, { create = false } = {}) {
  const convId = normId(conversationId || "");
  if (!convId) return null;
  let entry = serverVoiceUiForcedRemovedByConversation.get(convId) || null;
  if (!entry && create) {
    entry = new Set();
    serverVoiceUiForcedRemovedByConversation.set(convId, entry);
  }
  return entry;
}

function getServerVoiceUiForcedRemovedIds(conversationId) {
  const entry = getServerVoiceUiForcedRemovedEntry(conversationId, { create: false });
  if (!(entry instanceof Set)) return [];
  return normalizeUuidArray(Array.from(entry.values()));
}

function clearServerVoiceUiForcedRemovedIds(conversationId, ids = []) {
  const convId = normId(conversationId || "");
  if (!convId) return;
  const entry = getServerVoiceUiForcedRemovedEntry(convId, { create: false });
  if (!(entry instanceof Set)) return;
  normalizeUuidArray(ids || []).forEach((uid) => entry.delete(uid));
  if (!entry.size) serverVoiceUiForcedRemovedByConversation.delete(convId);
}

function preserveServerVoiceRemoteParticipantsAfterLocalLeave(conversationId, {
  triggerReason = "",
  previousVisibleParticipantIds = [],
} = {}) {
  const convId = normId(conversationId || "");
  const localUserId = normId(state.user?.id || "");
  if (!convId || !localUserId) return [];
  const reason = String(triggerReason || "").trim() || "local_leave_cleanup";
  const previousVisibleIds = normalizeUuidArray(previousVisibleParticipantIds || []);
  const visibilityEntry = getServerVoiceUiVisibilityEntry(convId, { create: true });
  if (!visibilityEntry) return [];
  const baseVisibleIds = normalizeUuidArray([
    ...previousVisibleIds,
    ...normalizeUuidArray(visibilityEntry.visibleIds || []),
  ]);
  const remoteParticipantIds = baseVisibleIds.filter((uid) => uid && uid !== localUserId);
  visibilityEntry.visibleIds = remoteParticipantIds.slice();
  visibilityEntry.seenAtByUser.delete(localUserId);
  visibilityEntry.leaveGraceUntilByUser.delete(localUserId);
  remoteParticipantIds.forEach((uid) => {
    visibilityEntry.seenAtByUser.set(uid, Number(visibilityEntry.seenAtByUser.get(uid) || Date.now()));
    visibilityEntry.leaveGraceUntilByUser.delete(uid);
  });
  const forcedEntry = getServerVoiceUiForcedRemovedEntry(convId, { create: true });
  forcedEntry?.add?.(localUserId);
  clearServerVoiceUiForcedRemovedIds(convId, remoteParticipantIds);
  if (remoteParticipantIds.length) {
    serverVoiceUiPreserveRemoteAfterLocalLeaveByConversation.set(convId, Date.now());
    serverVoiceLastVisibleMembersByConversation.set(convId, new Set(remoteParticipantIds));
  } else {
    serverVoiceUiPreserveRemoteAfterLocalLeaveByConversation.delete(convId);
    serverVoiceLastVisibleMembersByConversation.delete(convId);
  }
  removeServerVoicePresenceMember(convId, localUserId);
  removeCallParticipantAudioState(convId, localUserId);
  removeCallParticipantShareState(convId, localUserId);
  if (normId(groupCallActiveMembersConversationId || "") === convId) {
    setGroupCallActiveMembers(
      normalizeUuidArray(groupCallActiveMemberIds).filter((id) => id !== localUserId),
      convId
    );
  }
  logServerVoiceUiParticipantsEvent("ui.local_leave_only_removed_self", convId, remoteParticipantIds, reason, {
    localUserId,
    remoteParticipantIds,
  });
  if (remoteParticipantIds.length) {
    logServerVoiceUiParticipantsEvent("ui.remote_participants_preserved_after_local_leave", convId, remoteParticipantIds, reason, {
      localUserId,
      remoteParticipantIds,
    });
  } else if (previousVisibleIds.length > 0) {
    logServerVoiceUiParticipantsEvent("ui.full_visible_set_cleared", convId, remoteParticipantIds, reason, {
      localUserId,
      previousVisibleParticipantIds: previousVisibleIds,
      remoteParticipantIds,
    });
  }
  logServerVoiceUiParticipantsEvent("ui.visible_participants_after_local_leave", convId, remoteParticipantIds, reason, {
    localUserId,
    remoteParticipantIds,
  });
  return remoteParticipantIds;
}

function deriveServerVoiceVisibleParticipantIdsFromTransport(conversationId) {
  const convId = normId(conversationId || "");
  const meId = normId(state.user?.id || "");
  const snapshot = getServerVoiceTransportSnapshot(convId) || {};
  const connectionState = String(snapshot?.connectionState || "").trim().toLowerCase();
  const participantsByUser = snapshot?.participantsByUser && typeof snapshot.participantsByUser === "object"
    ? snapshot.participantsByUser
    : {};
  const participantIds = normalizeUuidArray(Object.keys(participantsByUser || {}));
  const visibleIds = [];
  const explicitAbsentIds = [];
  const localConnected = !!(
    snapshot?.local?.roomConnected === true
    || snapshot?.connected === true
    || connectionState === "connected"
    || connectionState === "reconnecting"
    || connectionState === "signalreconnecting"
  );
  const sessionActive = !!(
    localConnected
    || isServerVoiceTransportSessionActive(convId)
    || !!String(serverVoiceJoinInFlightByConversation.get(convId) || "").trim()
    || connectionState === "connecting"
  );
  if (meId) {
    if (localConnected || sessionActive) visibleIds.push(meId);
    else if (Object.prototype.hasOwnProperty.call(participantsByUser, meId)) explicitAbsentIds.push(meId);
  }
  participantIds.forEach((uid) => {
    if (!uid || uid === meId) return;
    const participantState = participantsByUser?.[uid] || null;
    if (isServerVoiceTransportParticipantInChannel(convId, uid, participantState)) {
      visibleIds.push(uid);
      return;
    }
    explicitAbsentIds.push(uid);
  });
  const hasEvidence = !!sessionActive;
  return {
    source: "transport",
    hasEvidence,
    visibleIds: normalizeUuidArray(visibleIds),
    explicitAbsentIds: normalizeUuidArray(explicitAbsentIds),
  };
}

function deriveServerVoiceVisibleParticipantIdsFromFallback(conversationId) {
  const convId = normId(conversationId || "");
  const meId = normId(state.user?.id || "");
  const activeIds = normalizeUuidArray([
    ...getServerVoicePresenceMemberIds(convId),
    ...(
      normId(groupCallActiveMembersConversationId || "") === convId
        ? normalizeUuidArray(groupCallActiveMemberIds)
        : []
    ),
    ...(normId(callConversationId || "") === convId && inCall && meId ? [meId] : []),
  ]);
  return {
    source: "fallback",
    hasEvidence: activeIds.length > 0,
    visibleIds: activeIds,
    explicitAbsentIds: [],
  };
}

function getServerVoiceVisibleParticipantIds(conversationId, {
  triggerReason = "",
  callerFunction = "",
  allowPresenceFallback = true,
} = {}) {
  const convId = normId(conversationId || "");
  const hasTransportContext = !!(
    getServerVoiceTransportSnapshot(convId)
    || getActiveServerVoiceTransportController(convId)
    || serverVoiceUiVisibilityByConversation.has(convId)
  );
  if (!convId || (!isServerVoiceConversationById(convId) && !hasTransportContext)) return [];
  const reason = String(triggerReason || "").trim() || "unknown";
  const caller = String(callerFunction || "").trim() || "unknown";
  const useLiveKitTransport = shouldUseServerVoiceLiveKitTransport(convId);
  const derived = useLiveKitTransport
    ? (() => {
        const transportDerived = deriveServerVoiceVisibleParticipantIdsFromTransport(convId);
        if (!allowPresenceFallback) {
          return {
            ...transportDerived,
            source: "transport_only",
          };
        }
        if (transportDerived.hasEvidence || transportDerived.visibleIds.length || transportDerived.explicitAbsentIds.length) {
          return transportDerived;
        }
        const fallbackDerived = deriveServerVoiceVisibleParticipantIdsFromFallback(convId);
        return {
          ...fallbackDerived,
          source: "authoritative_presence",
        };
      })()
    : deriveServerVoiceVisibleParticipantIdsFromFallback(convId);

  const visibilityEntry = getServerVoiceUiVisibilityEntry(convId, { create: true });
  if (!visibilityEntry) return normalizeUuidArray(derived.visibleIds || []);
  const previousVisibleIds = normalizeUuidArray(visibilityEntry.visibleIds || []);
  const previousSet = new Set(previousVisibleIds);
  const nextVisibleIds = normalizeUuidArray(derived.visibleIds || []);
  const nextSet = new Set(nextVisibleIds);
  const forcedRemovedIds = getServerVoiceUiForcedRemovedIds(convId);
  const forcedRemovedSet = new Set(forcedRemovedIds);
  const transportSnapshot = useLiveKitTransport ? getServerVoiceTransportSnapshot(convId) : null;
  const transportAuthoritativeForPresence = !!(
    useLiveKitTransport
    && String(derived?.source || "").startsWith("transport")
    && derived?.hasEvidence
    && isServerVoiceTransportSnapshotAuthoritativeForPresence(convId, transportSnapshot)
  );
  const transportOmittedAbsentIds = transportAuthoritativeForPresence
    ? previousVisibleIds.filter((uid) => uid && !nextSet.has(uid))
    : [];
  const explicitAbsentSet = new Set([
    ...normalizeUuidArray(derived.explicitAbsentIds || []),
    ...forcedRemovedIds,
    ...transportOmittedAbsentIds,
  ]);
  const now = Date.now();
  const localUserId = normId(state.user?.id || "");
  const preserveOmittedTransportParticipants = !!(
    useLiveKitTransport
    && derived?.source === "transport"
    && derived?.hasEvidence
    && !transportAuthoritativeForPresence
  );
  const preserveRemoteAfterLocalLeave = !!serverVoiceUiPreserveRemoteAfterLocalLeaveByConversation.get(convId);
  if (nextVisibleIds.includes(localUserId)) {
    serverVoiceUiPreserveRemoteAfterLocalLeaveByConversation.delete(convId);
  }
  if (nextVisibleIds.length) clearServerVoiceUiForcedRemovedIds(convId, nextVisibleIds);

  nextVisibleIds.forEach((uid) => {
    visibilityEntry.seenAtByUser.set(uid, now);
    visibilityEntry.leaveGraceUntilByUser.delete(uid);
  });

  previousVisibleIds.forEach((uid) => {
    if (!uid || nextSet.has(uid)) return;
    if (explicitAbsentSet.has(uid)) {
      logServerVoiceUiParticipantsEvent("ui.participant_leave_detected", convId, nextVisibleIds, reason, {
        callerFunction: caller,
        peerUserId: uid,
        source: forcedRemovedSet.has(uid) ? "forced_removed_cache" : "transport_explicit_absent",
      });
      visibilityEntry.leaveGraceUntilByUser.delete(uid);
      visibilityEntry.seenAtByUser.delete(uid);
      return;
    }
    if (preserveOmittedTransportParticipants) {
      const seenAt = Number(visibilityEntry.seenAtByUser.get(uid) || 0);
      if (!seenAt || !Number.isFinite(seenAt)) {
        visibilityEntry.seenAtByUser.set(uid, now);
      }
      visibilityEntry.leaveGraceUntilByUser.delete(uid);
      return;
    }
    if (preserveRemoteAfterLocalLeave && uid !== localUserId) {
      visibilityEntry.leaveGraceUntilByUser.delete(uid);
      return;
    }
    const existingGraceUntil = Number(visibilityEntry.leaveGraceUntilByUser.get(uid) || 0);
    visibilityEntry.leaveGraceUntilByUser.set(
      uid,
      existingGraceUntil > now ? existingGraceUntil : (now + SERVER_VOICE_PRESENCE_LEAVE_GRACE_MS)
    );
  });

  const stabilizedIds = normalizeUuidArray([
    ...nextVisibleIds,
    ...previousVisibleIds.filter((uid) => {
      if (!uid || nextSet.has(uid) || explicitAbsentSet.has(uid)) return false;
      if (preserveOmittedTransportParticipants) return true;
      if (preserveRemoteAfterLocalLeave && uid !== localUserId) return true;
      const graceUntil = Number(visibilityEntry.leaveGraceUntilByUser.get(uid) || 0);
      return Number.isFinite(graceUntil) && graceUntil > now;
    }),
  ]);
  const stabilizedSet = new Set(stabilizedIds);
  visibilityEntry.visibleIds = stabilizedIds.slice();
  Array.from(visibilityEntry.seenAtByUser.keys()).forEach((uid) => {
    if (!stabilizedSet.has(uid)) visibilityEntry.seenAtByUser.delete(uid);
  });
  Array.from(visibilityEntry.leaveGraceUntilByUser.keys()).forEach((uid) => {
    if (!stabilizedSet.has(uid)) visibilityEntry.leaveGraceUntilByUser.delete(uid);
  });

  const addedIds = stabilizedIds.filter((uid) => uid && !previousSet.has(uid));
  const removedIds = previousVisibleIds.filter((uid) => uid && !stabilizedSet.has(uid));
  const changed = addedIds.length > 0 || removedIds.length > 0;
  if (preserveOmittedTransportParticipants && removedIds.length > 1) {
    logServerVoiceUiParticipantsEvent("ui.render_source_mismatch", convId, stabilizedIds, reason, {
      callerFunction: caller,
      reason: "invariant.multi_remove_while_transport_active",
      removedIds,
      explicitAbsentIds: Array.from(explicitAbsentSet),
      previousVisibleIds,
    });
  }
  if (changed) {
    logServerVoiceUiParticipantsEvent("ui.visible_participants_snapshot", convId, stabilizedIds, reason, {
      callerFunction: caller,
      source: derived.source || null,
      addedIds,
      removedIds,
    });
    logServerVoiceUiParticipantsEvent("ui.participants_snapshot", convId, stabilizedIds, reason, {
      source: derived.source || null,
      addedIds,
      removedIds,
    });
    addedIds.forEach((uid) => {
      logServerVoiceUiParticipantsEvent("ui.participant_added", convId, stabilizedIds, reason, {
        peerUserId: uid,
        source: derived.source || null,
      });
    });
    removedIds.forEach((uid) => {
      logServerVoiceUiParticipantsEvent("ui.participant_removed_from_visible_list", convId, stabilizedIds, reason, {
        callerFunction: caller,
        peerUserId: uid,
        source: derived.source || null,
      });
      logServerVoiceUiParticipantsEvent("ui.participant_removed", convId, stabilizedIds, reason, {
        peerUserId: uid,
        source: derived.source || null,
      });
    });
    const meId = normId(state.user?.id || "");
    const localParticipantId = meId && stabilizedSet.has(meId) ? meId : null;
    const remoteParticipantIds = stabilizedIds.filter((uid) => uid && uid !== meId);
    logServerVoiceUiParticipantsEvent("ui.runtime_membership_snapshot", convId, stabilizedIds, reason, {
      callerFunction: caller,
      source: derived.source || null,
      localParticipantId,
      remoteParticipantIds,
    });
  }
  if (previousVisibleIds.length !== stabilizedIds.length) {
    logServerVoiceUiParticipantsEvent("ui.count_updated", convId, stabilizedIds, reason, {
      previousCount: previousVisibleIds.length,
      source: derived.source || null,
    });
  }
  if (previousVisibleIds.length > 0 && stabilizedIds.length === 0) {
    logServerVoiceUiParticipantsEvent("ui.full_visible_set_cleared", convId, stabilizedIds, reason, {
      localUserId,
      remoteParticipantIds: previousVisibleIds.filter((uid) => uid && uid !== localUserId),
      previousVisibleParticipantIds: previousVisibleIds,
      source: derived.source || null,
    });
  }

  if (!stabilizedIds.length && !isServerVoiceTransportSessionActive(convId)) {
    serverVoiceUiVisibilityByConversation.delete(convId);
    serverVoiceUiPreserveRemoteAfterLocalLeaveByConversation.delete(convId);
  }

  return stabilizedIds;
}

function logServerVoiceSourceSplitRenderSnapshot(conversationId, participantIds = [], {
  sourceType = "",
  sourceDetail = "",
  triggerReason = "",
  callerFunction = "",
  snapshotEvent = "",
} = {}) {
  const convId = normId(conversationId || "");
  if (!convId) return;
  const ids = normalizeUuidArray(participantIds || []);
  const reason = String(triggerReason || "").trim() || "unknown";
  const caller = String(callerFunction || "").trim() || "unknown";
  const source = String(sourceType || "").trim() || "unknown";
  const detail = String(sourceDetail || "").trim() || null;
  const extra = {
    callerFunction: caller,
    sourceType: source,
    sourceDetail: detail,
  };
  if (snapshotEvent) {
    logServerVoiceUiParticipantsEvent(snapshotEvent, convId, ids, reason, extra);
  }
  logServerVoiceUiParticipantsEvent("ui.source_split_render", convId, ids, reason, extra);
}

function buildServerVoiceParticipantsFromIds(conversationId, participantIds = [], {
  serverMembers = [],
  includeTransportState = true,
} = {}) {
  const convId = normId(conversationId || "");
  const ids = normalizeUuidArray(participantIds || []);
  if (!convId || !ids.length) return [];
  const sid = resolveServerVoiceServerIdByConversation(convId);
  const memberRows = Array.isArray(serverMembers) && serverMembers.length
    ? serverMembers
    : (sid ? (serverMemberListByServerId.get(sid) || []) : []);
  const memberById = new Map();
  memberRows.forEach((member) => {
    const uid = normId(member?.userId || "");
    if (!uid) return;
    memberById.set(uid, member);
  });
  const participantUiStateByUserId = new Map();
  if (includeTransportState) {
    getServerVoiceTransportUiStates(convId).forEach((participantUiState) => {
      const uid = normId(participantUiState?.userId || "");
      if (!uid) return;
      participantUiStateByUserId.set(uid, participantUiState);
    });
  }
  const meId = normId(state.user?.id || "");
  return ids.map((uid) => {
    const botSession = getServerVoiceBotSessionMeta(convId, uid);
    if (botSession || isBotVoiceParticipantIdentity(uid)) {
      return normalizeServerVoiceBotParticipant(convId, uid, botSession, {
        includeTransportState,
        participantUiStateByUserId,
      });
    }

    const member = memberById.get(uid) || {};
    const cachedProfile = getCachedProfile(uid) || {};
    const voicePresenceMeta = getServerVoicePresenceMemberMeta(convId, uid) || {};
    const fallbackIdentity = getGroupMemberIdentity(convId, uid) || {};
    const participantUiState = includeTransportState
      ? (participantUiStateByUserId.get(uid) || null)
      : null;
    const isMe = !!(meId && uid === meId);
    const displayName = normalizeConversationLabel(
      resolveServerDisplayName(sid, uid, member, "")
        || cachedProfile?.display_name
        || cachedProfile?.username
        || voicePresenceMeta?.label
        || (isMe ? (state.me?.display_name || state.me?.username || "") : "")
        || fallbackIdentity?.label
        || member?.username
        || "member",
      "member"
    );
    const avatarUrl = String(
      member?.avatarUrl
      || member?.avatar_url
      || cachedProfile?.avatar_url
      || cachedProfile?.avatarUrl
      || voicePresenceMeta?.avatar
      || (isMe ? (state.me?.avatar_url || "") : "")
      || fallbackIdentity?.avatar
      || ""
    ).trim();
    if (displayName && displayName !== "member") {
      cacheProfileRow({
        id: uid,
        username: member?.username || cachedProfile?.username || fallbackIdentity?.username || "",
        display_name: getServerMemberGlobalDisplayName(member) || cachedProfile?.display_name || cachedProfile?.username || "",
        avatar_url: avatarUrl || cachedProfile?.avatar_url || "",
        name_color: cachedProfile?.name_color || member?.nameColor || member?.name_color || "",
      });
    } else {
      try {
        if (window?.ALTARA_DEBUG_VOICE) {
          console.debug("[server-voice] participant profile fallback", {
            conversation_id: convId,
            user_id: uid,
            reason: "missing_member_profile_for_audio_state",
          });
        }
      } catch (_) {}
    }
    let presenceStatus = getPresenceStatusForServerMember(uid);
    if (presenceStatus === "offline") presenceStatus = "online";
    return {
      userId: uid,
      displayName,
      avatarUrl,
      isMe,
      presenceStatus,
      voiceState: participantUiState?.state || (includeTransportState
        ? SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.NOT_IN_CHANNEL
        : SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED),
      voiceStateLabel: includeTransportState ? (participantUiState?.stateLabel || "") : "",
    };
  }).filter(Boolean);
}
// LiveKit transport-owned participants for in-call media UI.
function getServerVoiceInCallParticipantIds(conversationId, {
  triggerReason = "",
  callerFunction = "",
} = {}) {
  const convId = normId(conversationId || "");
  const hasTransportContext = !!(
    getServerVoiceTransportSnapshot(convId)
    || getActiveServerVoiceTransportController(convId)
    || serverVoiceUiVisibilityByConversation.has(convId)
  );
  if (!convId || (!isServerVoiceConversationById(convId) && !hasTransportContext)) return [];
  const reason = String(triggerReason || "").trim() || "in_call_participants";
  const caller = String(callerFunction || "").trim() || "getServerVoiceInCallParticipantIds";
  const participantIds = getServerVoiceVisibleParticipantIds(convId, {
    triggerReason: reason,
    callerFunction: caller,
    allowPresenceFallback: false,
  });
  logServerVoiceSourceSplitRenderSnapshot(convId, participantIds, {
    sourceType: "in_call_transport",
    sourceDetail: "livekit_transport_owned",
    triggerReason: reason,
    callerFunction: caller,
    snapshotEvent: "ui.incall_participants_snapshot",
  });
  auditServerVoiceUiSource(convId, {
    visibleParticipantIds: participantIds,
    triggerReason: reason,
    callerFunction: caller,
    sourceKind: "in_call_transport",
    usesUnifiedSource: true,
  });
  return participantIds;
}

