function getServerVoiceStageParticipantIds(conversationId, {
  triggerReason = "",
  callerFunction = "",
} = {}) {
  const convId = normId(conversationId || "");
  if (!convId || !isServerVoiceConversationUiContext(convId)) return [];
  if (!isActiveServerVoiceCallJoined(convId)) return [];

  return getServerVoiceChannelParticipantIds(convId, {
    triggerReason: triggerReason || "server_voice_stage_participants",
    callerFunction: callerFunction || "getServerVoiceStageParticipantIds",
  });
}

function getServerVoiceChannelParticipantIds(conversationId, {
  triggerReason = "",
  callerFunction = "",
} = {}) {
  const convId = normId(conversationId || "");
  const hasTransportContext = !!(
    getServerVoiceTransportSnapshot(convId)
    || getActiveServerVoiceTransportController(convId)
    || serverVoiceUiVisibilityByConversation.has(convId)
  );
  const resolvedServerId = normId(resolveServerVoiceServerIdByConversation(convId) || getActiveServerContext?.()?.serverId || state.activeDm?.serverId || "");
  if (!convId || (!isServerVoiceConversationUiContext(convId) && !hasTransportContext)) {
    logServerVoiceLocalDiagnostic("voice_participant_ids_skipped", {
      functionName: "getServerVoiceChannelParticipantIds",
      channelId: convId,
      resolvedServerId,
      reason: !convId ? "missing_channel_id" : "not_server_voice_context",
    });
    return [];
  }
  if (isServerVoiceV2Enabled()) {
    const channelCtx = findServerChannelContextByConversationId(convId) || null;
    const channelId = normId(channelCtx?.channel?.id || channelCtx?.channel?.channelId || channelCtx?.channel?.channel_id || "");
    const channelServerId = normId(channelCtx?.serverId || resolvedServerId || "");
    const occupancyState = getServerVoiceOccupancyHydrationState(channelServerId);
    if (channelId && channelServerId && occupancyState.loaded) {
      const participantIds = normalizeUuidArray(
        getServerVoiceV2ChannelOccupants(channelId, channelServerId).map((participant) => getVoiceV2ParticipantUserId(participant))
      );
      traceVoiceV2RenderSource("sidebar/stage_participants", {
        channelId,
        conversationId: convId,
        source: "server_voice_members_v2",
        hydrationStatus: occupancyState.status,
        participantIds,
        ignoredLegacyVisibleParticipantIds: normalizeUuidArray(groupCallActiveMemberIds || []),
      });
      logServerVoiceSourceSplitRenderSnapshot(convId, participantIds, {
        sourceType: "server_voice_members_v2",
        sourceDetail: buildServerVoiceV2RoomName(channelServerId),
        triggerReason: triggerReason || "server_voice_v2_channel_participants",
        callerFunction: callerFunction || "getServerVoiceChannelParticipantIds",
        snapshotEvent: "ui.channel_occupants_snapshot",
      });
      return participantIds;
    }
  }

  const reason = String(triggerReason || "").trim() || "server_voice_channel_participants";
  const caller = String(callerFunction || "").trim() || "getServerVoiceChannelParticipantIds";
  const ids = [];
  const sourceByUserId = new Map();
  const sourceReasonsByUserId = {};
  const seen = new Set();
  const seenBotIds = new Set();
  const forcedRemoved = new Set(getServerVoiceUiForcedRemovedIds(convId));
  const addSourceReason = (value, reasonValue) => {
    const uid = normId(value || "");
    if (!uid) return;
    if (!sourceReasonsByUserId[uid]) sourceReasonsByUserId[uid] = [];
    const text = String(reasonValue || "").trim();
    if (text && !sourceReasonsByUserId[uid].includes(text)) sourceReasonsByUserId[uid].push(text);
  };
  const push = (value, source) => {
    const uid = normId(value || "");
    if (!uid) return;
    const botIdentity = isBotVoiceParticipantIdentity(uid);
    const botSessionForUid = botIdentity ? null : getServerVoiceBotSessionMeta(convId, uid);
    const botId = botIdentity ? getBotIdFromVoiceParticipantIdentity(uid) : normId(botSessionForUid?.botId || "");
    const botSessionPresent = !!(botSessionForUid || (botId && getServerVoiceBotSessions(convId).some((session) => normId(session?.botId || "") === botId)));
    if (!botSessionPresent && botId && shouldHideServerVoiceBotParticipantForPresence(resolvedServerId, botId)) {
      addSourceReason(uid, `excluded:${source || "unknown"}:bot_presence_offline`);
      return;
    }
    if (forcedRemoved.has(uid) || (botId && forcedRemoved.has(botId))) {
      addSourceReason(uid, `excluded:${source || "unknown"}:forced_removed`);
      return;
    }
    if (botId && seenBotIds.has(botId)) {
      addSourceReason(uid, `duplicate:${source || "unknown"}:bot_identity_alias`);
      return;
    }
    if (seen.has(uid)) {
      addSourceReason(uid, `duplicate:${source || "unknown"}`);
      return;
    }
    seen.add(uid);
    if (botId) seenBotIds.add(botId);
    ids.push(uid);
    sourceByUserId.set(uid, String(source || "").trim() || "unknown");
    addSourceReason(uid, `included:${source || "unknown"}`);
  };

  const transportSnapshot = getServerVoiceTransportSnapshot(convId);
  const transportAuthoritativeForPresence = isServerVoiceTransportSnapshotAuthoritativeForPresence(convId, transportSnapshot);
  const liveKitParticipantIds = getServerVoiceInCallParticipantIds(convId, {
    triggerReason: reason,
    callerFunction: caller,
  });
  liveKitParticipantIds.forEach((uid) => push(uid, "livekit_transport"));

  const realtimeParticipantIds = getServerVoiceChannelOccupantIds(convId, {
    triggerReason: `${reason}:realtime_presence`,
    callerFunction: caller,
  });
  const legacyParticipantIds = getServerVoiceLegacyUiParticipantIds(convId);
  if (!transportAuthoritativeForPresence) {
    realtimeParticipantIds.forEach((uid) => push(uid, "realtime_presence"));
    legacyParticipantIds.forEach((uid) => push(uid, "legacy_visible_cache"));
  } else {
    const liveKitSet = new Set(liveKitParticipantIds);
    realtimeParticipantIds.forEach((uid) => {
      if (!liveKitSet.has(uid)) addSourceReason(uid, "excluded:realtime_presence:not_in_livekit_transport");
    });
    legacyParticipantIds.forEach((uid) => {
      if (!liveKitSet.has(uid)) addSourceReason(uid, "excluded:legacy_visible_cache:not_in_livekit_transport");
    });
  }

  const botParticipantIds = getServerVoiceBotParticipantIds(convId);
  botParticipantIds.forEach((uid) => {
    push(uid, "bot_voice_session");
    const session = getServerVoiceBotSessionMeta(convId, uid);
    recordBotVoiceUiEvent("bot_voice_row_resolved", {
      botId: session?.botId || getBotIdFromVoiceParticipantIdentity(uid),
      serverId: resolvedServerId,
      channelId: session?.channelId || "",
      conversationId: convId,
      rowSource: "bot_voice_session",
      visible: true,
      liveKitParticipantPresent: liveKitParticipantIds.includes(uid),
      botVoiceSessionPresent: !!session,
      occupancySnapshotPresent: realtimeParticipantIds.includes(uid),
    });
  });

  const meId = normId(state.user?.id || "");
  if (meId && isActiveServerVoiceCallJoined(convId)) push(meId, "local_joined_fallback");

  const sortedIds = sortGroupCallMemberIdsForLayout(convId, ids);
  const finalSet = new Set(sortedIds);
  const staleCandidateIds = transportAuthoritativeForPresence
    ? normalizeUuidArray([
        ...realtimeParticipantIds,
        ...legacyParticipantIds,
      ]).filter((uid) => uid && !finalSet.has(uid))
    : [];
  const prunedStaleIds = transportAuthoritativeForPresence
    ? pruneServerVoiceStaleVisibleParticipantCaches(convId, staleCandidateIds, {
        finalVisibleIds: sortedIds,
        triggerReason: reason,
        callerFunction: caller,
      })
    : [];
  prunedStaleIds.forEach((uid) => addSourceReason(uid, "pruned:stale_cache_absent_from_livekit_transport"));

  logServerVoicePresenceResolution(convId, {
    triggerReason: reason,
    callerFunction: caller,
    liveKitParticipantIds,
    supabasePresenceIds: realtimeParticipantIds,
    localCacheIds: legacyParticipantIds,
    stalePrunedIds: prunedStaleIds,
    finalVisibleIds: sortedIds,
    sourceReasonsByUserId,
    usedLiveKitAuthoritative: transportAuthoritativeForPresence,
    transportConnectionState: transportSnapshot?.connectionState || "",
    transportJoinPhase: transportSnapshot?.joinPhase || "",
  });

  if (isServerVoiceDebugLoggingEnabled()) {
    const finalParticipants = buildServerVoiceParticipantsFromIds(convId, sortedIds, {
      includeTransportState: true,
    });
    logServerVoiceDebug("server_voice_channel_participants_resolved", {
      channelId: convId,
      conversationId: convId,
      liveKitParticipantCount: liveKitParticipantIds.length,
      realtimePresenceCount: realtimeParticipantIds.length,
      legacyOccupantIdsCount: legacyParticipantIds.length,
      finalNormalizedCount: sortedIds.length,
      finalUserIds: sortedIds,
      finalUsers: finalParticipants.map((participant) => ({
        userId: participant.userId,
        name: participant.displayName,
        source: sourceByUserId.get(participant.userId) || "unknown",
      })),
      currentUserIncluded: !!(meId && sortedIds.includes(meId)),
      duplicatesRemoved: Math.max(
        0,
        liveKitParticipantIds.length + realtimeParticipantIds.length + legacyParticipantIds.length + (meId ? 1 : 0) - sortedIds.length
      ),
      forcedRemovedIds: Array.from(forcedRemoved),
      staleCandidateIds,
      prunedStaleIds,
      liveKitAuthoritativeForPresence: transportAuthoritativeForPresence,
      triggerReason: reason,
      callerFunction: caller,
    });
  }
  return sortedIds;
}
function getServerVoiceStageParticipants(conversationId, {
  serverMembers = [],
  triggerReason = "",
  callerFunction = "",
} = {}) {
  const convId = normId(conversationId || "");
  const participantIds = getServerVoiceStageParticipantIds(convId, {
    triggerReason: triggerReason || "server_voice_stage_participants",
    callerFunction: callerFunction || "getServerVoiceStageParticipants",
  });
  return buildServerVoiceParticipantsFromIds(convId, participantIds, {
    serverMembers,
    includeTransportState: true,
  });
}

function resolveServerVoiceGridConversationId(conversationId = "") {
  const preferredConvId = normId(conversationId || "");
  const activeViewedConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  const activeCallConvId = normId(callConversationId || "");
  const candidates = normalizeUuidArray([
    preferredConvId,
    activeViewedConvId,
    activeCallConvId,
  ]);
  for (const candidateId of candidates) {
    if (candidateId && isServerVoiceConversationUiContext(candidateId)) return candidateId;
  }
  return preferredConvId || activeViewedConvId || activeCallConvId || "";
}

// Control-plane occupants with UI metadata for sidebar/channel surfaces.
function getServerVoiceChannelOccupants(conversationId, {
  serverMembers = [],
  triggerReason = "",
  callerFunction = "",
} = {}) {
  const convId = normId(conversationId || "");
  const resolvedServerId = normId(resolveServerVoiceServerIdByConversation(convId) || getActiveServerContext?.()?.serverId || state.activeDm?.serverId || "");
  if (!convId) {
    logServerVoiceLocalDiagnostic("voice_occupants_skipped", {
      functionName: "getServerVoiceChannelOccupants",
      channelId: convId,
      resolvedServerId,
      reason: "missing_channel_id",
    });
    return [];
  }
  try {
    const participantIds = getServerVoiceChannelParticipantIds(convId, {
      triggerReason: triggerReason || "channel_occupants",
      callerFunction: callerFunction || "getServerVoiceChannelOccupants",
    });
    let participants = buildServerVoiceParticipantsFromIds(convId, participantIds, {
      serverMembers,
      includeTransportState: true,
    });
    const channelCtx = findServerChannelContextByConversationId(convId) || null;
    const channelId = normId(channelCtx?.channel?.id || channelCtx?.channel?.channelId || "");
    if (channelId) {
      pruneVoiceModerationOptimisticState();
      const removedIds = new Set();
      voiceModerationOptimisticState.moveOverrides.forEach((override, userId) => {
        const uid = normId(userId || "");
        const toChannelId = normId(override?.toChannelId || "");
        const fromChannelId = normId(override?.fromChannelId || "");
        if (!uid || !toChannelId) return;
        if (channelId !== toChannelId && (channelId === fromChannelId || participants.some((member) => normId(member?.userId || "") === uid))) {
          removedIds.add(uid);
        }
      });
      if (removedIds.size) participants = participants.filter((member) => !removedIds.has(normId(member?.userId || "")));
      voiceModerationOptimisticState.moveOverrides.forEach((override, userId) => {
        const uid = normId(userId || "");
        const toChannelId = normId(override?.toChannelId || "");
        if (!uid || channelId !== toChannelId) return;
        if (participants.some((member) => normId(member?.userId || "") === uid)) {
          if (override?.pendingMove !== true) voiceModerationOptimisticState.moveOverrides.delete(uid);
          return;
        }
        const memberRecord = (serverMembers || []).find((member) => normId(member?.id || member?.user_id || member?.userId || "") === uid) || {};
        participants.push({
          userId: uid,
          displayName: memberRecord.display_name || memberRecord.username || memberRecord.name || "Member",
          avatarUrl: memberRecord.avatar_url || memberRecord.avatarUrl || "",
          presenceStatus: memberRecord.presence_status || memberRecord.status || "online",
          isMe: !!(state.user?.id && uid === normId(state.user.id)),
          isBot: false,
          optimisticMovePending: override?.pendingMove === true,
        });
      });
    }
    return participants
  } catch (error) {
    logServerVoiceLocalDiagnostic("voice_occupants_failed", {
      functionName: "getServerVoiceChannelOccupants",
      channelId: convId,
      resolvedServerId,
      message: String(error?.message || error || "unknown_error").slice(0, 220),
    }, { level: "warn" });
    return [];
  }
}

function resetCallSidebarElapsedCache() {
  callSidebarElapsedConnectedAtMs = 0;
  callSidebarElapsedLabelUpdatedAtMs = 0;
  callSidebarElapsedLabel = "";
}

function getCallSidebarElapsedLabel({ force = false } = {}) {
  const connectedAtMs = Number(callEventConnectedAtMs || 0);
  if (!Number.isFinite(connectedAtMs) || connectedAtMs <= 0) {
    resetCallSidebarElapsedCache();
    return "";
  }
  const now = Date.now();
  if (callSidebarElapsedConnectedAtMs !== connectedAtMs) {
    callSidebarElapsedConnectedAtMs = connectedAtMs;
    callSidebarElapsedLabelUpdatedAtMs = 0;
    callSidebarElapsedLabel = "";
  }
  if (
    force
    || !callSidebarElapsedLabel
    || !callSidebarElapsedLabelUpdatedAtMs
    || (now - callSidebarElapsedLabelUpdatedAtMs) >= CALL_SIDEBAR_ELAPSED_REFRESH_MS
  ) {
    callSidebarElapsedLabel = formatCallElapsedCompactLabel(now - connectedAtMs);
    callSidebarElapsedLabelUpdatedAtMs = now;
  }
  return callSidebarElapsedLabel;
}

function shouldShowServerVoiceRoomElapsed(conversationId) {
  const convId = normId(conversationId || "");
  if (!convId || !callEventConnectedAtMs) return false;
  if (!shouldUseServerVoiceLiveKitTransport(convId)) return false;
  const connectedConvId = normId(getMiniCallDockConversationId());
  if (connectedConvId && connectedConvId !== convId) return false;
  return !!isActiveServerVoiceCallJoined(convId);
}

function getServerVoiceRoomElapsedLabel(conversationId, { force = false } = {}) {
  if (!shouldShowServerVoiceRoomElapsed(conversationId)) return "";
  return getCallSidebarElapsedLabel({ force });
}

function buildServerVoiceRoomElapsedHtml(conversationId) {
  const convId = normId(conversationId || "");
  const elapsedText = getServerVoiceRoomElapsedLabel(convId);
  if (!elapsedText) return "";
  return `<span class="serverVoiceRoom__elapsed" data-server-voice-call-elapsed="${escAttr(convId)}">${esc(elapsedText)}</span>`;
}

function syncServerVoiceRoomElapsedElement(btn, conversationId, { force = false } = {}) {
  if (!btn) return;
  const convId = normId(conversationId || btn.getAttribute?.("data-server-voice-channel") || "");
  const elapsedText = getServerVoiceRoomElapsedLabel(convId, { force });
  let elapsedEl = btn.querySelector?.(".serverVoiceRoom__elapsed") || null;
  if (!elapsedText) {
    elapsedEl?.remove?.();
    return;
  }
  if (!elapsedEl) {
    elapsedEl = document.createElement("span");
    elapsedEl.className = "serverVoiceRoom__elapsed";
    const metaEl = btn.querySelector?.(".serverVoiceRoom__meta") || btn;
    const countEl = btn.querySelector?.(".serverVoiceRoom__count") || null;
    if (countEl && countEl.parentElement === metaEl) metaEl.insertBefore(elapsedEl, countEl);
    else metaEl.appendChild(elapsedEl);
  }
  elapsedEl.dataset.serverVoiceCallElapsed = convId;
  if (elapsedEl.textContent !== elapsedText) elapsedEl.textContent = elapsedText;
}

function refreshServerVoiceRoomElapsedElements({ force = false } = {}) {
  document.querySelectorAll(".serverVoiceRoom[data-server-voice-channel]").forEach((btn) => {
    syncServerVoiceRoomElapsedElement(btn, btn.getAttribute("data-server-voice-channel"), { force });
  });
}

function stopCallSidebarElapsedTimer() {
  if (callSidebarElapsedTimer) {
    clearInterval(callSidebarElapsedTimer);
    callSidebarElapsedTimer = null;
  }
  resetCallSidebarElapsedCache();
  document.querySelectorAll(".serverVoiceRoom__elapsed").forEach((el) => el.remove());
}

function ensureCallSidebarElapsedTimer(enabled = false) {
  if (!enabled) {
    stopCallSidebarElapsedTimer();
    return;
  }
  if (callSidebarElapsedConnectedAtMs !== Number(callEventConnectedAtMs || 0)) {
    resetCallSidebarElapsedCache();
  }
  getCallSidebarElapsedLabel({ force: !callSidebarElapsedLabel });
  refreshServerVoiceRoomElapsedElements();
  if (callSidebarElapsedTimer) return;
  callSidebarElapsedTimer = setInterval(() => {
    getCallSidebarElapsedLabel({ force: true });
    refreshServerVoiceChannelBadges();
    refreshServerVoiceRoomElapsedElements({ force: true });
  }, CALL_SIDEBAR_ELAPSED_REFRESH_MS);
}
function getServerVoiceChannelConnectedCount(conversationId, {
  triggerReason = "",
  callerFunction = "",
} = {}) {
  const convId = normId(conversationId || "");
  const resolvedServerId = normId(resolveServerVoiceServerIdByConversation(convId) || getActiveServerContext?.()?.serverId || state.activeDm?.serverId || "");
  if (isAltaraVoiceBadgeRefreshDisabled()) {
    logServerVoiceLocalDiagnostic("voice_connected_count_disabled", {
      functionName: "getServerVoiceChannelConnectedCount",
      channelId: convId,
      resolvedServerId,
      triggerReason,
    });
    return 0;
  }
  let participants = [];
  try {
    participants = getServerVoiceChannelOccupants(conversationId, {
      triggerReason: triggerReason || "channel_connected_count",
      callerFunction: callerFunction || "getServerVoiceChannelConnectedCount",
    });
  } catch (error) {
    logServerVoiceLocalDiagnostic("voice_connected_count_failed", {
      functionName: "getServerVoiceChannelConnectedCount",
      channelId: convId,
      resolvedServerId,
      message: String(error?.message || error || "unknown_error").slice(0, 220),
    }, { level: "warn" });
    return 0;
  }
  const count = participants.length;
  const meId = normId(state.user?.id || "");
  const localVisible = !!participants.find((participant) => normId(participant?.userId || "") === meId);
  if (localVisible && count <= 0) {
    logServerVoiceUiParticipantsEvent("ui.render_source_mismatch", convId, [], triggerReason || "channel_connected_count", {
      callerFunction: callerFunction || "getServerVoiceChannelConnectedCount",
      reason: "invariant.local_visible_but_count_zero",
      localParticipantId: meId || null,
    });
    return 1;
  }
  return count;
}

function getServerVoiceChannelActiveMembers(conversationId, serverMembers = [], {
  triggerReason = "",
  callerFunction = "",
} = {}) {
  return getServerVoiceChannelOccupants(conversationId, {
    serverMembers,
    triggerReason: triggerReason || "channel_active_members",
    callerFunction: callerFunction || "getServerVoiceChannelActiveMembers",
  });
}

function buildServerVoiceMemberRowsHtml(conversationId, serverMembers = [], options = {}) {
  const activeMembers = getServerVoiceChannelActiveMembers(conversationId, serverMembers, {
    triggerReason: "build_server_voice_member_rows",
    callerFunction: "buildServerVoiceMemberRowsHtml",
  });
  if (!activeMembers.length) return "";
  const voiceChannelContext = findServerChannelContextByConversationId(conversationId) || null;
  const voiceChannelId = normId(options?.channelId || voiceChannelContext?.channel?.id || voiceChannelContext?.channel?.channelId || "");
  return activeMembers.map((member) => {
    const isBot = member?.isBot === true;
    const serverId = resolveServerVoiceServerIdByConversation(conversationId);
    const botProfile = isBot ? normalizeBotProfileSeed({
      botId: member.botId || member.userId || "",
      name: member.displayName || "Bot",
      avatarUrl: member.avatarUrl || "",
      voiceStatus: member.voiceStatus || "",
      presenceStatus: member.presenceStatus || "online",
      serverId,
    }) : null;
    const botProfileAttrs = isBot ? getBotContextProfileAttrs(botProfile, serverId, "") : "";
    const avatarHtml = member.avatarUrl
      ? buildAvatarMediaHtml(member.avatarUrl, { userId: member.userId, alt: isBot ? "bot avatar" : "avatar", deferAnimatedStorage: true })
      : `<span class="groupDmAvatarFallback">${esc(getGroupOrbFallbackChar(member.displayName, isBot ? "B" : "U"))}</span>`;
    const audioState = isBot ? null : getParticipantAudioStateForUi(member.userId, conversationId);
    const optimisticMove = isBot ? null : getVoiceModerationMoveOverride(member.userId);
    const moderationClasses = [
      audioState?.serverMuted ? "is-server-muted" : "",
      audioState?.serverDeafened ? "is-server-deafened" : "",
      audioState?.pendingMute || audioState?.pendingDeafen || optimisticMove?.pendingMove || member?.optimisticMovePending ? "is-moderation-pending" : "",
      optimisticMove?.pendingMove || member?.optimisticMovePending ? "is-move-pending" : "",
    ].filter(Boolean).join(" ");
    const audioBadgesHtml = isBot ? "" : buildCallAudioStateBadgesHtml(member.userId, conversationId);
    const transportStatusLabel = "";
    const shareMetaText = "";
    const stateBits = [];
    if (isBot) stateBits.push(member.voiceStatus || "Bot connected");
    if (member.isMe) stateBits.push("You");
    if (transportStatusLabel) stateBits.push(transportStatusLabel);
    const stateTextHtml = stateBits.length
      ? `<span class="serverVoiceMember__stateText"${shareMetaText ? ` title="${escAttr(shareMetaText)}"` : ""}>${esc(stateBits.join(" - "))}</span>`
      : "";
    const botBadgeHtml = isBot ? `<span class="serverVoiceMember__botBadge">BOT</span>` : "";
    return `
      <div
        class="serverVoiceMember server-voice-member-row${isBot ? " is-bot" : ""}${moderationClasses ? ` ${moderationClasses}` : ""}"
        data-server-voice-member-id="${escAttr(member.userId)}"
        data-voice-member-user-id="${escAttr(member.userId)}"
        data-voice-member-name="${escAttr(member.displayName || (isBot ? "Bot" : "member"))}"
        data-current-voice-channel-id="${escAttr(voiceChannelId)}"
        data-server-voice-conversation-id="${escAttr(conversationId)}"
        data-voice-channel-conversation-id="${escAttr(conversationId)}"
        data-server-voice-channel-id="${escAttr(voiceChannelId)}"
        data-voice-channel-id="${escAttr(voiceChannelId)}"
        data-server-voice-member-label="${escAttr(member.displayName || (isBot ? "Bot" : "member"))}"
        data-server-voice-member-avatar="${escAttr(member.avatarUrl || "")}"
        draggable="${isBot ? "false" : "true"}"
        ${isBot ? `data-server-voice-bot-id="${escAttr(member.botId || "")}" data-server-right-is-bot="1" data-server-right-user="${escAttr(member.botId || member.userId || "")}" data-server-right-display="${escAttr(member.displayName || "Bot")}" data-server-right-avatar="${escAttr(member.avatarUrl || "")}" ${botProfileAttrs} role="button" tabindex="0" aria-label="Open bot profile for ${escAttr(member.displayName || "Bot")}"` : ""}
      >
        <span class="serverVoiceMember__avatar">
          ${avatarHtml}
          <span class="statusDot" data-status-dot="${escAttr(member.userId)}" data-status="${escAttr(member.presenceStatus || "online")}"></span>
        </span>
        <span class="serverVoiceMember__name">${esc(member.displayName)}${botBadgeHtml}${member.isMe ? " (You)" : ""}</span>
        <span class="serverVoiceMember__state">
          ${audioBadgesHtml}
          ${stateTextHtml}
        </span>
      </div>
    `;
  }).join("");
}
function refreshServerVoiceChannelBadges() {
  if (isAltaraVoiceBadgeRefreshDisabled()) {
    logServerVoiceLocalDiagnostic("voice_badge_refresh_disabled", {
      functionName: "refreshServerVoiceChannelBadges",
      reason: "ALTARA_DISABLE_VOICE_BADGE_REFRESH",
    });
    return false;
  }
  try {
    return refreshServerVoiceChannelBadgesUnsafe();
  } catch (error) {
    logServerVoiceLocalDiagnostic("voice_badge_refresh_failed", {
      functionName: "refreshServerVoiceChannelBadges",
      activeConversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
      message: String(error?.message || error || "unknown_error").slice(0, 220),
    }, { level: "warn" });
    return false;
  }
}

function refreshServerVoiceChannelBadgesUnsafe() {
  const panel = document.getElementById("serverChannelsPanel");
  if (!panel || panel.classList.contains("hidden")) return;
  const activeConversationId = normId(activeDmId || state.activeDm?.conversationId || "");
  const serverCtx = getActiveServerContext();
  const sid = normId(serverCtx?.serverId || "");
  const serverMembers = sid ? (serverMemberListByServerId.get(sid) || []) : [];
  if (sid) scheduleServerVoiceBotSessionsRefresh(sid, { force: false });
  panel.querySelectorAll("[data-server-voice-channel]").forEach((btn) => {
    const convId = normId(btn.getAttribute("data-server-voice-channel"));
    if (!convId) return;
    if (!serverVoiceModerationStateApplying) {
      void fetchServerVoiceModerationStatesForConversation(convId, { reason: "refresh-server-voice-badges" }).catch(() => {});
    }
    const count = getServerVoiceChannelConnectedCount(convId, {
      triggerReason: "refresh_server_voice_channel_badges",
      callerFunction: "refreshServerVoiceChannelBadges",
    });
    const countEl = btn.querySelector(".serverVoiceRoom__count");
    if (countEl) countEl.textContent = String(Math.max(0, count));
    syncServerVoiceRoomElapsedElement(btn, convId);
    const channelId = normId(btn.getAttribute("data-server-channel-id") || "");
    const unread = getServerChannelUnreadCount({ serverId: sid, channelId, conversationId: convId });
    const hasUnread = unread > 0;
    btn.classList.toggle("has-live", count > 0);
    btn.classList.toggle("has-unread", hasUnread);
    btn.classList.toggle("is-active", !!activeConversationId && convId === activeConversationId);

    const wrap = btn.closest(".serverVoiceRoomWrap");
    if (!wrap) return;
    wrap.classList.toggle("has-live", count > 0);
    wrap.classList.toggle("has-unread", hasUnread);
    wrap.classList.toggle("is-active", !!activeConversationId && convId === activeConversationId);
    let membersEl = wrap.querySelector(".serverVoiceRoomMembers");
    const membersHtml = buildServerVoiceMemberRowsHtml(convId, serverMembers, { channelId });

    if (shouldUseServerVoiceLiveKitTransport(convId) && isServerVoiceDebugLoggingEnabled()) {
      const activeMembers = getServerVoiceChannelActiveMembers(convId, serverMembers, {
        triggerReason: "refresh_server_voice_channel_badges",
        callerFunction: "refreshServerVoiceChannelBadges",
      });
      const stageParticipantIds = isActiveServerVoiceCallJoined(convId)
        ? getServerVoiceStageParticipantIds(convId, {
          triggerReason: "refresh_server_voice_channel_badges:stage_count",
          callerFunction: "refreshServerVoiceChannelBadges",
        })
        : [];
      logServerVoiceDebug("server_voice_channel_badge_render", {
        channelId: convId,
        conversationId: convId,
        displayedCount: count,
        nestedRowCount: activeMembers.length,
        stageParticipantCount: stageParticipantIds.length,
        nestedUserIds: activeMembers.map((member) => member.userId),
        stageParticipantIds,
      });
      const currentIds = new Set(activeMembers.map((m) => m.userId));
      const previousIds = serverVoiceLastChannelOccupantsByConversation.get(convId) || new Set();
      const meId = normId(state.user?.id || "");
      currentIds.forEach((uid) => {
        if (!previousIds.has(uid)) {
          const isLocal = !!(meId && uid === meId);
          logServerVoiceDebug("participant_visible", {
            conversationId: convId,
            peerUserId: uid,
            reason: isLocal ? "local_presence_joined" : "remote_presence_joined",
            sourceType: "normalized_voice_participants",
            isLocal,
          });
        }
      });
      previousIds.forEach((uid) => {
        if (!currentIds.has(uid)) {
          const isLocal = !!(meId && uid === meId);
          logServerVoiceDebug("participant_removed", {
            conversationId: convId,
            peerUserId: uid,
            reason: isLocal
              ? "local_presence_left"
              : "remote_presence_left",
            sourceType: "normalized_voice_participants",
            isLocal,
          });
        }
      });
      serverVoiceLastChannelOccupantsByConversation.set(convId, currentIds);
    }

    if (membersHtml) {
      if (!membersEl) {
        membersEl = document.createElement("div");
        membersEl.className = "serverVoiceRoomMembers";
        wrap.appendChild(membersEl);
      }
      membersEl.innerHTML = membersHtml;
    } else if (membersEl) {
      membersEl.remove();
    }
  });
}

function applyServerChannelUnreadDecorations() {
  const panel = document.getElementById("serverChannelsPanel");
  if (!panel || panel.classList.contains("hidden")) return;
  const activeConversationId = normId(activeDmId || state.activeDm?.conversationId || "");

  const sid = normId(getActiveServerContext()?.serverId || state.activeDm?.serverId || "");

  panel.querySelectorAll("[data-server-channel-open]").forEach((btn) => {
    const convId = normId(btn.getAttribute("data-server-channel-open"));
    if (!convId) return;
    const channelId = normId(btn.getAttribute("data-server-channel-id") || "");
    const unread = getServerChannelUnreadCount({ serverId: sid, channelId, conversationId: convId });
    const hasUnread = unread > 0;
    btn.classList.toggle("has-unread", hasUnread);
    btn.classList.toggle("is-active", !!activeConversationId && convId === activeConversationId);
    if (hasUnread) btn.setAttribute("data-unread-count", String(Math.min(99, unread)));
    else btn.removeAttribute("data-unread-count");
  });

  panel.querySelectorAll("[data-server-voice-channel]").forEach((btn) => {
    const convId = normId(btn.getAttribute("data-server-voice-channel"));
    if (!convId) return;
    const channelId = normId(btn.getAttribute("data-server-channel-id") || "");
    const unread = getServerChannelUnreadCount({ serverId: sid, channelId, conversationId: convId });
    const hasUnread = unread > 0;
    btn.classList.toggle("has-unread", hasUnread);
    if (hasUnread) btn.setAttribute("data-unread-count", String(Math.min(99, unread)));
    else btn.removeAttribute("data-unread-count");
  });

  panel.querySelectorAll(".serverChannelsCategory").forEach((section) => {
    const hasUnread = !!section.querySelector(".serverChannelItem.has-unread, .serverVoiceRoom.has-unread");
    const hasActive = !!section.querySelector(".serverChannelItem.is-active, .serverVoiceRoom.is-active");
    section.classList.toggle("has-unread", hasUnread);
    section.classList.toggle("is-active", hasActive);
  });
}

async function reorderServerChannelCategoriesForServer(serverId, orderedCategoryIds = []) {
  const sid = normId(serverId || "");
  const nextOrder = normalizeUuidArray(orderedCategoryIds || []);
  if (!sid || !nextOrder.length) return { error: null };

  const currentOrder = (serverChannelCategoryListByServerId.get(sid) || [])
    .map((cat) => normId(cat?.id || ""))
    .filter(Boolean);
  const movedId = nextOrder.find((id, index) => currentOrder[index] !== id) || nextOrder[0] || "";
  if (!movedId) return { error: null };
  const movedIndex = nextOrder.indexOf(movedId);
  const beforeCategoryId = normId(nextOrder[movedIndex + 1] || "");
  const afterCategoryId = normId(nextOrder[movedIndex - 1] || "");
  const res = await reorderServerChannelCategoryRpc({
    serverId: sid,
    categoryId: movedId,
    beforeCategoryId,
    afterCategoryId: beforeCategoryId ? "" : afterCategoryId,
  });
  if (res?.error) return { error: res.error };
  if (Array.isArray(res?.data)) {
    const normalized = res.data.map((row) => {
      const id = normId(row?.id || "");
      if (!id) return null;
      return {
        id,
        serverId: sid,
        name: normalizeServerCategoryName(row?.name || "Category"),
        position: Number(row?.position || 0),
        createdAt: Date.parse(String(row?.created_at || row?.createdAt || "")) || Number(row?.createdAt || 0) || 0,
      };
    }).filter(Boolean);
    if (normalized.length) {
      const channels = serverChannelListByServerId.get(sid) || [];
      applyServerChannelsSnapshot(sid, channels, normalized, { reason: "category_reordered_rpc" });
    }
  }
  return { error: null };
}

async function saveServerChannelOrderingForServer(serverId, updates = []) {
  const sid = normId(serverId || "");
  const rows = Array.isArray(updates) ? updates : [];
  if (!sid || !rows.length) return { error: null };

  const moving = rows.find((row) => normId(row?.channelId || "") && !!row?.isMovedChannel) || rows[0] || null;
  const channelId = normId(moving?.channelId || "");
  if (!channelId) return { error: null };
  const res = await reorderServerChannelRpc({
    serverId: sid,
    channelId,
    targetCategoryId: normId(moving?.categoryId || ""),
    beforeChannelId: normId(moving?.beforeChannelId || ""),
    afterChannelId: normId(moving?.afterChannelId || ""),
  });
  if (res?.error) return { error: res.error };
  if (Array.isArray(res?.data)) {
    const normalized = res.data.map((row) => normalizeServerChannelSidebarRow(row, sid, {
      hasPositionColumn: true,
      hasCreatedAtColumn: true,
      hasChannelTypeColumn: true,
      hasCategoryIdColumn: true,
      hasIsPrivateColumn: true,
      hasUserLimitColumn: true,
      hasMediaModeColumn: true,
    })).filter(Boolean);
    if (normalized.length) {
      const categories = serverChannelCategoryListByServerId.get(sid) || [];
      applyServerChannelsSnapshot(sid, normalized, categories, { reason: "channel_reordered_rpc" });
    }
  }
  return { error: null };
}

function compareOrderedServerRows(a = {}, b = {}) {
  return Number(a.position || 0) - Number(b.position || 0)
    || Number(a.createdAt || 0) - Number(b.createdAt || 0)
    || String(a.name || "").localeCompare(String(b.name || ""))
    || String(a.id || "").localeCompare(String(b.id || ""));
}

function getOrderedServerCategories(serverId = "") {
  const sid = normId(serverId || "");
  return (serverChannelCategoryListByServerId.get(sid) || [])
    .filter((cat) => normId(cat?.id || ""))
    .slice()
    .sort(compareOrderedServerRows);
}

function getOrderedServerChannelsForCategory(serverId = "", categoryId = "", channelType = "") {
  const sid = normId(serverId || "");
  const catId = normId(categoryId || "");
  const type = String(channelType || "").trim().toLowerCase();
  return (serverChannelListByServerId.get(sid) || [])
    .filter((ch) => {
      if (normId(ch?.categoryId || "") !== catId) return false;
      if (!type) return true;
      const rowType = normalizeConversationChannelType(ch?.channelType || "text");
      return type === "voice" ? rowType === "voice" : rowType !== "voice";
    })
    .slice()
    .sort(compareOrderedServerRows);
}

function getUncategorizedServerChannels(serverId = "", channelType = "") {
  return getOrderedServerChannelsForCategory(serverId, "", channelType);
}

function renderServerChannelsPanel(serverCtx, channels = [], members = [], categories = []) {
  const panel = document.getElementById("serverChannelsPanel");
  const body = document.querySelector("#dmMain .dmMainBody");
  if (!panel || !body) return;

  const sid = normId(serverCtx?.serverId || "");
  const previousPanelServerId = normId(panel.getAttribute("data-server-panel-server-id") || "");
  if (previousPanelServerId && previousPanelServerId !== sid) {
    captureServerChannelSidebarVisualState(previousPanelServerId, { reason: "switch_server_capture" });
  }
  const sidebarVisualState = previousPanelServerId === sid
    ? captureServerChannelSidebarVisualState(sid, { reason: "render_server_channels_panel" })
    : {
      serverId: sid,
      scrollTop: Number(serverChannelSidebarScrollTopByServerId.get(sid) || 0),
      ...(serverChannelSidebarAnchorByServerId.has(sid)
        ? {
          anchorRowId: serverChannelSidebarAnchorByServerId.get(sid)?.rowId || "",
          anchorOffset: Number(serverChannelSidebarAnchorByServerId.get(sid)?.offset || 0),
        }
        : {}),
    };
  if (shouldSkipRemovedServerRender(sid, "renderServerChannelsPanel")) return;
  if (!sid) {
    panel.classList.add("hidden");
    panel.setAttribute("aria-hidden", "true");
    body.classList.remove("is-server-layout");
    return;
  }

  const activeConversationId = normId(activeDmId || state.activeDm?.conversationId || "");
  const serverName = normalizeConversationLabel(serverCtx?.name || "Server", "Server");
  const dmList = document.getElementById("dmList");
  if (dmList) dmList.replaceChildren();
  setDmListPanelTitle(serverName, { serverMode: true });
  const channelLoadErrorRaw = serverChannelLoadErrorByServerId.get(sid) || null;
  logSidebarRenderState("render_server_channels_panel_start", {
    mode: "server",
    serverId: sid,
    selectedChannelId: activeConversationId,
    channelCount: Array.isArray(channels) ? channels.length : 0,
    categoryCount: Array.isArray(categories) ? categories.length : 0,
    hasChannelError: !!channelLoadErrorRaw,
    cacheCount: getKnownServerChannelsForSidebar(sid).length,
    loadState: getServerChannelLoadState(sid)?.state || "idle",
    token: Number(getServerChannelLoadState(sid)?.token || 0) || 0,
    domStillLoading: isServerChannelSidebarStillLoading(sid),
  });
  const serverIconUrl = String(serverCtx?.iconUrl || "").trim();
  const caps = getServerCapabilityMeta(sid);
  const canManageChannelStructure = currentUserCanManageChannels(sid);
  const serverInitial = getGroupOrbFallbackChar(serverName, "S");
  const hideMutedChannels = isServerHideMutedChannelsEnabled(sid);
  const allChannels = (Array.isArray(channels) ? channels : [])
    .map((ch) => ({
      ...ch,
      conversationId: normId(ch?.conversationId || ""),
      categoryId: normId(ch?.categoryId || ""),
      isPrivate: !!ch?.isPrivate,
      channelType: normalizeConversationChannelType(ch?.channelType || "text"),
      userLimit: clampServerVoiceUserLimit(ch?.userLimit ?? 0, 0),
      mediaMode: normalizeServerVoiceMediaMode(ch?.mediaMode || "audio_only", "audio_only"),
      position: Number(ch?.position || 0),
      createdAt: Number(ch?.createdAt || 0),
      name: normalizeConversationLabel(ch?.name || (normalizeConversationChannelType(ch?.channelType || "") === "voice" ? "voice-lounge" : "general"), "general"),
    }))
    .filter((ch) => !!ch.conversationId)
    .sort(compareOrderedServerRows);
  const permissionVisibleChannels = getVisibleServerChannelsForCurrentUser(sid, allChannels);
  const visibleChannels = hideMutedChannels
    ? permissionVisibleChannels.filter((ch) => !isDmConversationMuted(ch?.conversationId || ""))
    : permissionVisibleChannels.slice();
  const channelLoadError = visibleChannels.length ? null : channelLoadErrorRaw;
  setServerChannelLoadState(sid, channelLoadError ? "error" : "ready", {
    reason: channelLoadError ? "render-server-channel-error" : "render-server-channels",
  });
  clearServerChannelLoadWatchdog(sid);
  if (!channelLoadError) serverChannelLoadRetryCountByServerId.delete(sid);

  const categoryRows = (Array.isArray(categories) ? categories : [])
    .map((cat) => ({
      id: normId(cat?.id || ""),
      name: normalizeServerCategoryName(cat?.name || "Category"),
      position: Number(cat?.position || 0),
      createdAt: Number(cat?.createdAt || 0),
    }))
    .filter((cat) => !!cat.id)
    .sort(compareOrderedServerRows);

  const renderTextChannelItem = (ch) => {
    const convId = normId(ch?.conversationId || "");
    const channelId = normId(ch?.id || "");
    const categoryId = normId(ch?.categoryId || "");
    const label = normalizeConversationLabel(ch?.name || "general", "general");
    const unread = getServerChannelUnreadCount({ serverId: sid, channelId, conversationId: convId });
    const hasUnread = unread > 0;
    const isActive = !!activeConversationId && convId === activeConversationId;
    const canDragChannel = !!canManageChannelStructure && !!channelId;
    return `
      <button
        class="serverChannelItem channelRow${isActive ? " is-active" : ""}${hasUnread ? " has-unread" : ""}"
        type="button"
        data-server-channel-open="${escAttr(convId)}"
        data-server-channel-id="${escAttr(channelId)}"
        data-server-category-id="${escAttr(categoryId)}"
        data-server-channel-type="text"
        data-server-channel-name="${escAttr(label)}"
        data-server-drop-channel-target="1"
        data-server-drag-type="channel"
        data-server-drag-channel-id="${escAttr(channelId)}"
        data-server-drag-source-category-id="${escAttr(categoryId)}"
        draggable="${canDragChannel ? "true" : "false"}"
      >
        <span class="serverChannelItem__icon" aria-hidden="true">#</span>
        <span class="serverChannelItem__label">${esc(label)}</span>
      </button>
    `;
  };

  const renderVoiceChannelItem = (ch) => {
    const label = normalizeConversationLabel(ch?.name || "voice-lounge", "voice-lounge");
    const convId = normId(ch?.conversationId || "");
    const channelId = normId(ch?.id || "");
    const categoryId = normId(ch?.categoryId || "");
    const settingsSummary = buildServerVoiceChannelSettingsSummary();
    const unread = getServerChannelUnreadCount({ serverId: sid, channelId, conversationId: convId });
    const hasUnread = unread > 0;
    const count = getServerVoiceChannelConnectedCount(convId, {
      triggerReason: "render_server_channels_panel",
      callerFunction: "renderServerChannelsPanel",
    });
    const isActive = !!activeConversationId && convId === activeConversationId;
    const canDragChannel = !!canManageChannelStructure && !!channelId;
    const membersHtml = buildServerVoiceMemberRowsHtml(convId, members, { channelId });
    const elapsedHtml = buildServerVoiceRoomElapsedHtml(convId);
    const voicePermissionDecision = getCachedServerVoicePermissionDecision(sid, channelId)
      || resolveLocalServerVoicePermissionDecision(sid, channelId, "channel_row");
    const connectPermissionResolved = voicePermissionDecision?.ok === true;
    const connectPermissionDenied = !connectPermissionResolved || voicePermissionDecision?.connect !== true;
    const connectPermissionLabel = connectPermissionResolved
      ? getServerVoicePermissionDeniedMessage("connect")
      : "Checking voice permissions...";
    const channelTitle = connectPermissionDenied
      ? `${settingsSummary} ${connectPermissionLabel}`.trim()
      : settingsSummary;
    return `
      <div
        class="serverVoiceRoomWrap server-voice-channel-block${isActive ? " is-active" : ""}${count > 0 ? " has-live" : ""}${hasUnread ? " has-unread" : ""}${connectPermissionDenied ? " is-connect-denied" : ""}"
        data-voice-channel-block="${escAttr(channelId)}"
        data-server-voice-channel-id="${escAttr(channelId)}"
        data-server-voice-conversation-id="${escAttr(convId)}"
        data-server-channel-id="${escAttr(channelId)}"
        data-server-category-id="${escAttr(categoryId)}"
        title="${escAttr(channelTitle)}"
      >
        <button
          class="serverChannelItem channelRow serverVoiceRoom server-voice-channel-row${isActive ? " is-active" : ""}${count > 0 ? " has-live" : ""}${hasUnread ? " has-unread" : ""}${connectPermissionDenied ? " is-voice-permission-denied" : ""}"
          type="button"
          data-server-voice-channel="${escAttr(convId)}"
          data-server-drop-channel-target="1"
          data-server-voice-drop-target="1"
          data-server-voice-channel-id="${escAttr(channelId)}"
          data-voice-channel-id="${escAttr(channelId)}"
          data-voice-channel-name="${escAttr(label)}"
          data-server-channel-id="${escAttr(channelId)}"
          data-server-category-id="${escAttr(categoryId)}"
          data-server-channel-type="voice"
          data-server-channel-name="${escAttr(label)}"
          data-server-voice-name="${escAttr(label)}"
          data-server-drag-type="channel"
          data-server-drag-channel-id="${escAttr(channelId)}"
          data-server-drag-source-category-id="${escAttr(categoryId)}"
          draggable="${canDragChannel ? "true" : "false"}"
          aria-disabled="${connectPermissionDenied ? "true" : "false"}"
          data-voice-connect-permission="${connectPermissionResolved ? (voicePermissionDecision.connect ? "allowed" : "denied") : "loading"}"
          style="${connectPermissionDenied ? "cursor:not-allowed;opacity:.62;" : ""}"
          title="${escAttr(channelTitle)}"
        >
          <span class="serverChannelItem__icon serverVoiceRoom__icon" aria-hidden="true">&#127911;</span>
          <span class="serverChannelItem__label serverVoiceRoom__label">${esc(label)}</span>
          <span class="serverVoiceRoom__meta">
            ${connectPermissionDenied ? `<span class="serverVoiceRoom__permissionLock" aria-hidden="true">&#128274;</span>` : ``}
            ${elapsedHtml}
            <span class="serverChannelItem__badge serverVoiceRoom__count">${count}</span>
          </span>
        </button>
        ${membersHtml ? `<div class="serverVoiceRoomMembers server-voice-members-list" data-voice-members-for-channel="${escAttr(channelId)}">${membersHtml}</div>` : ``}
      </div>
    `;
  };

  const renderChannelItem = (ch) => {
    if (normalizeConversationChannelType(ch?.channelType || "") === "voice") {
      return renderVoiceChannelItem(ch);
    }
    return renderTextChannelItem(ch);
  };

  const channelsByCategoryId = new Map();
  visibleChannels.forEach((ch) => {
    const cid = normId(ch?.categoryId || "");
    if (!channelsByCategoryId.has(cid)) channelsByCategoryId.set(cid, []);
    channelsByCategoryId.get(cid).push(ch);
  });
  const channelsByConversationId = new Map(
    visibleChannels.map((ch) => [normId(ch?.conversationId || ""), ch]).filter(([id]) => !!id)
  );
  const categoriesById = new Map(
    categoryRows.map((cat) => [normId(cat?.id || ""), cat]).filter(([id]) => !!id)
  );

  reconcileServerChannelContextMenuAfterRender(sid, visibleChannels, categoryRows);

  let collapsedSet = serverChannelCategoryCollapsedByServerId.get(sid);
  if (!(collapsedSet instanceof Set)) {
    collapsedSet = new Set();
    serverChannelCategoryCollapsedByServerId.set(sid, collapsedSet);
  }

  const channelSectionsHtml = (() => {
    if (channelLoadError) {
      return `
        <section class="serverChannelsCategory serverChannelsCategory--root serverChannelsCategory--uncategorized" data-server-category-section="" data-server-category-drop="1">
          <button class="serverChannelsRetryBtn" type="button" data-server-channels-retry="1" title="Retry loading channels">Retry</button>
          <div class="serverChannelsHint">Could not load channels.</div>
        </section>
      `;
    }
    const rootChannels = (channelsByCategoryId.get("") || []).slice().sort(compareOrderedServerRows);
    const rootHtml = rootChannels.map(renderChannelItem).join("");
    const rootSectionHtml = (rootChannels.length || !categoryRows.length)
      ? `
        <section class="serverChannelsCategory serverChannelsCategory--root serverChannelsCategory--uncategorized" data-server-category-section="" data-server-category-drop="1">
          <div class="serverChannelsCategory__body serverChannelsCategory__body--root">
            ${rootHtml || `<div class="serverChannelsHint">No channels yet.</div>`}
          </div>
        </section>
      `
      : "";
    if (!categoryRows.length) {
      return rootSectionHtml;
    }

    const categoryHtml = categoryRows
      .filter((cat) => {
        const catId = normId(cat?.id || "");
        const catChannels = (channelsByCategoryId.get(catId) || []).slice();
        return catChannels.length > 0 || canManageChannelStructure;
      })
      .map((cat) => {
      const catId = normId(cat?.id || "");
      const catChannels = (channelsByCategoryId.get(catId) || []).slice();
      const isCollapsed = collapsedSet.has(catId);
      const hasUnread = catChannels.some((ch) => getServerChannelUnreadCount({ serverId: sid, channelId: ch?.id || ch?.channelId || ch?.channel_id || "", conversationId: ch?.conversationId || "" }) > 0);
      const hasActive = catChannels.some((ch) => normId(ch?.conversationId || "") === activeConversationId);
      return `
        <section
          class="serverChannelsCategory${isCollapsed ? " is-collapsed" : ""}${hasUnread ? " has-unread" : ""}${hasActive ? " is-active" : ""}"
          data-server-category-section="${escAttr(catId)}"
          data-server-category-drop="1"
        >
          <div class="serverChannelsCategory__head">
            <button class="serverChannelsCategory__toggle" type="button" data-server-category-toggle="${escAttr(catId)}" data-server-category-id="${escAttr(catId)}" data-server-category-name="${escAttr(cat.name)}" data-server-drag-type="category" data-server-drag-category-id="${escAttr(catId)}" draggable="${canManageChannelStructure ? "true" : "false"}" aria-expanded="${isCollapsed ? "false" : "true"}">
              <span class="serverChannelsCategory__caret" aria-hidden="true">${isCollapsed ? "&#9656;" : "&#9662;"}</span>
              <span class="serverChannelsCategory__name">${esc(cat.name)}</span>
              <span class="serverChannelsCategory__count">${catChannels.length}</span>
            </button>
            <button class="serverChannelsCategory__add" type="button" data-server-create-channel="1" data-server-create-type="text" data-server-create-category-id="${escAttr(catId)}" title="Create channel in ${escAttr(cat.name)}"${canManageChannelStructure ? "" : " disabled"}>+</button>
          </div>
          <div class="serverChannelsCategory__body">
            ${catChannels.length ? catChannels.map(renderChannelItem).join("") : ``}
          </div>
        </section>
      `;
    }).join("");

    return `${rootSectionHtml}${categoryHtml}` || `<div class="serverChannelsHint">No channels yet.</div>`;
  })();

  const nextPanelHtml = `
    <div class="serverChannelsPanel__top">
      <button class="serverChannelsPanel__identity serverChannelsPanel__identityBtn" type="button" data-server-panel-menu-open="1" title="Server menu" aria-label="Open server menu for ${escAttr(serverName)}">
        <span class="serverChannelsPanel__icon">
          ${serverIconUrl ? `<img src="${esc(serverIconUrl)}" alt="server icon" />` : `<span>${esc(serverInitial)}</span>`}
        </span>
        <span class="serverChannelsPanel__identityMeta">
          <span class="serverChannelsPanel__name">${esc(serverName)}</span>
          <span class="serverChannelsPanel__meta">Server Channels</span>
        </span>
        <span class="serverChannelsPanel__menuChevron" aria-hidden="true">&#9662;</span>
      </button>
    </div>
    <div class="serverChannelsPanel__body">
      <section class="serverChannelsQuick">
        <button class="serverQuickItem" type="button" disabled>
          <span class="serverQuickItem__icon" aria-hidden="true">&#128197;</span>
          <span class="serverQuickItem__label">Events</span>
        </button>
        <button class="serverQuickItem" type="button" disabled>
          <span class="serverQuickItem__icon" aria-hidden="true">&#11015;</span>
          <span class="serverQuickItem__label">Server Boosts</span>
        </button>
      </section>
      ${channelSectionsHtml}
    </div>
  `;
  const nextRenderSignature = nextPanelHtml.replace(
    /(<span class="serverVoiceRoom__elapsed"[^>]*>)[\s\S]*?(<\/span>)/g,
    "$1$2"
  );
  const previousRenderSignature = serverChannelSidebarRenderSignatureByServerId.get(sid) || "";
  const panelHasRenderedShell = !!(
    panel.querySelector(".serverChannelsPanel__top")
    && panel.querySelector(".serverChannelsPanel__body")
  );
  const domReplaced = previousPanelServerId !== sid
    || !panelHasRenderedShell
    || previousRenderSignature !== nextRenderSignature;
  if (!domReplaced) {
    lastServerChannelSidebarScrollDebug = {
      ...(lastServerChannelSidebarScrollDebug || {}),
      activeServerId: sid,
      renderReason: "render_server_channels_panel",
      DOMReplaced: false,
      snapshotChanged: false,
      skippedUnchangedRender: true,
      restoreApplied: false,
    };
    updateServerChannelActiveState(activeConversationId, { reason: "render-server-channels-panel-unchanged", serverId: sid });
    bindServerChannelSidebarScrollPersistence(sid);
    applyServerChannelUnreadDecorations();
    refreshServerVoiceChannelBadges();
    return;
  }
  panel.innerHTML = nextPanelHtml;
  serverChannelSidebarRenderSignatureByServerId.set(sid, nextRenderSignature);

  panel.classList.remove("hidden");
  panel.setAttribute("aria-hidden", "false");
  panel.setAttribute("data-server-panel-server-id", sid);
  const loadStateEntry = getServerChannelLoadState(sid);
  panel.setAttribute("data-server-channel-load-state", normalizeServerChannelLoadState(loadStateEntry?.state || "ready"));
  if (loadStateEntry?.reason) panel.setAttribute("data-server-channel-load-reason", loadStateEntry.reason);
  else panel.removeAttribute("data-server-channel-load-reason");
  if (loadStateEntry?.token) panel.setAttribute("data-server-channel-load-token", String(loadStateEntry.token));
  else panel.removeAttribute("data-server-channel-load-token");
  body.classList.add("is-server-layout");
  bindServerChannelSidebarScrollPersistence(sid);
  restoreServerChannelSidebarVisualState(sidebarVisualState, {
    reason: previousPanelServerId === sid ? "render_refresh" : "switch_server_restore",
    afterLayout: true,
  });
  lastServerChannelSidebarScrollDebug = {
    ...(lastServerChannelSidebarScrollDebug || {}),
    activeServerId: sid,
    renderReason: "render_server_channels_panel",
    DOMReplaced: true,
    snapshotChanged: true,
  };
  updateServerChannelActiveState(activeConversationId, { reason: "render-server-channels-panel", serverId: sid });
  void ensureServerRolePermissionCache(sid, { force: false }).catch(() => {});
  const retryChannelsBtn = panel.querySelector("[data-server-channels-retry]");
  if (retryChannelsBtn) {
    retryChannelsBtn.addEventListener("click", () => {
      serverChannelLoadErrorByServerId.delete(sid);
      void refreshServerConversationUi({ force: true, reason: "server-channel-retry", refreshChannels: true, refreshMembers: true }).catch(() => {});
    });
  }

  logSidebarRenderState("render_server_channels_panel_end", {
    mode: "server",
    serverId: sid,
    selectedChannelId: activeConversationId,
    visibleChannelCount: visibleChannels.length,
    hasChannelError: !!channelLoadError,
    loadState: getServerChannelLoadState(sid)?.state || "idle",
    token: Number(getServerChannelLoadState(sid)?.token || 0) || 0,
    domStillLoading: isServerChannelSidebarStillLoading(sid),
  });

  if (!panel.dataset.voiceMemberCtxBound) {
    panel.dataset.voiceMemberCtxBound = "1";
    panel.addEventListener("click", async (e) => {
      const target = eventTargetElement(e);
      if (!target) return;
      if (Date.now() < serverVoiceMemberDragSuppressClickUntil && getServerVoiceMemberDragSourceFromTarget(target)) {
        e.preventDefault?.();
        e.stopPropagation?.();
        console.info("[voice-drag] suppressed profile click after drag");
        return;
      }
      const memberRow = target.closest(".serverVoiceMember[data-server-voice-member-id]");
      if (!memberRow) return;
      if (isServerVoiceBotMemberRow(memberRow)) {
        await openServerVoiceBotProfileFromRow(memberRow);
        return;
      }
      const memberUserId = normId(memberRow.getAttribute("data-server-voice-member-id") || "");
      if (!memberUserId) return;
      const displayName = memberRow.getAttribute("data-server-voice-member-label") || "";
      const avatarUrl = memberRow.getAttribute("data-server-voice-member-avatar") || "";
      await openCallParticipantProfilePreview(memberUserId, memberRow, {
        display_name: displayName,
        avatar_url: avatarUrl,
      }, {
        conversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
        conversationLabel: String(state.activeDm?.displayName || "").trim(),
        serverId: sid,
        kind: "server",
      });
    });
    panel.addEventListener("keydown", async (e) => {
      const target = eventTargetElement(e);
      if (!target) return;
      if (Date.now() < serverVoiceMemberDragSuppressClickUntil && getServerVoiceMemberDragSourceFromTarget(target)) {
        e.preventDefault?.();
        e.stopPropagation?.();
        console.info("[voice-drag] suppressed profile click after drag");
        return;
      }
      const memberRow = target.closest(".serverVoiceMember[data-server-voice-member-id]");
      if (!memberRow || !isServerVoiceBotMemberRow(memberRow)) return;
      const key = String(e.key || "");
      if (key === "Enter" || key === " ") {
        e.preventDefault();
        e.stopPropagation();
        await openServerVoiceBotProfileFromRow(memberRow);
        return;
      }
      if (key === "ContextMenu" || (key === "F10" && e.shiftKey)) {
        e.preventDefault();
        e.stopPropagation();
        const rect = memberRow.getBoundingClientRect();
        openServerVoiceBotContextMenuFromRow(memberRow, {
          x: Math.round(rect.left + rect.width / 2),
          y: Math.round(rect.top + rect.height / 2),
        });
      }
    });
    panel.addEventListener("contextmenu", async (e) => {
      const target = eventTargetElement(e);
      if (!target) return;
      const panelServerId = normId(panel.getAttribute("data-server-panel-server-id") || "");

      const memberRow = target.closest(".serverVoiceMember[data-server-voice-member-id]");
      if (memberRow) {
        e.preventDefault();
        e.stopPropagation();
        if (isServerVoiceBotMemberRow(memberRow)) {
          openServerVoiceBotContextMenuFromRow(memberRow, { x: e.clientX, y: e.clientY });
          return;
        }
        closeCallAudioMenu();
        closeServerChannelItemMenu("open_other_menu");
        closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });

        const memberUserId = normId(memberRow.getAttribute("data-server-voice-member-id") || "");
        const convId = normId(memberRow.getAttribute("data-server-voice-conversation-id") || "");
        const displayName = memberRow.getAttribute("data-server-voice-member-label") || "";
        if (!memberUserId || !convId) return;
        if (panelServerId) {
          await ensureServerRolePermissionCache(panelServerId, { force: false }).catch(() => {});
        }

        const opened = tryOpenServerVoiceMemberMenuAt(memberUserId, convId, {
          x: e.clientX,
          y: e.clientY,
        }, {
          displayName,
          serverId: panelServerId,
          anchorEl: memberRow,
        });
        if (!opened) return;
        return;
      }

      const channelBtn = target.closest("[data-server-channel-open], [data-server-voice-channel]");
      if (channelBtn) {
        e.preventDefault();
        e.stopPropagation();
        closeCallAudioMenu();
        closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });

        const convId = normId(
          channelBtn.getAttribute("data-server-channel-open")
          || channelBtn.getAttribute("data-server-voice-channel")
          || ""
        );
        const row = channelsByConversationId.get(convId) || null;
        const channelType = normalizeConversationChannelType(
          channelBtn.getAttribute("data-server-channel-type")
          || row?.channelType
          || "text"
        );
        const label = normalizeConversationLabel(
          channelBtn.getAttribute("data-server-channel-name")
          || channelBtn.getAttribute("data-server-voice-name")
          || row?.name
          || (channelType === "voice" ? "voice-lounge" : "general"),
          channelType === "voice" ? "voice-lounge" : "general"
        );
        openServerChannelItemMenuAt({
          itemType: "channel",
          serverId: panelServerId || sid,
          channelId: normId(channelBtn.getAttribute("data-server-channel-id") || row?.id || ""),
          conversationId: convId,
          channelType,
          categoryId: normId(row?.categoryId || ""),
          isPrivate: !!row?.isPrivate,
          label,
          anchorEl: channelBtn,
        }, {
          x: e.clientX,
          y: e.clientY,
        });
        return;
      }

      const categoryBtn = target.closest("[data-server-category-toggle]");
      if (categoryBtn) {
        e.preventDefault();
        e.stopPropagation();
        closeCallAudioMenu();
        closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });

        const catId = normId(
          categoryBtn.getAttribute("data-server-category-id")
          || categoryBtn.getAttribute("data-server-category-toggle")
          || ""
        );
        const catRow = categoriesById.get(catId) || null;
        const label = normalizeServerCategoryName(
          categoryBtn.getAttribute("data-server-category-name")
          || catRow?.name
          || "Category",
          "Category"
        );
        openServerChannelItemMenuAt({
          itemType: "category",
          serverId: panelServerId || sid,
          categoryId: catId,
          label,
          anchorEl: categoryBtn,
        }, {
          x: e.clientX,
          y: e.clientY,
        });
        return;
      }

      const bodyEl = target.closest(".serverChannelsPanel__body");
      const isBareChannelsArea = !!(
        bodyEl
        && !target.closest(".serverQuickItem")
        && !target.closest(".serverChannelsGroup__head, .serverChannelsCategory__head")
        && !target.closest("[data-server-channel-open], [data-server-voice-channel], [data-server-category-toggle], [data-server-create-channel]")
        && !target.closest(".serverVoiceMember[data-server-voice-member-id]")
      );
      if (isBareChannelsArea) {
        e.preventDefault();
        e.stopPropagation();
        closeCallAudioMenu();
        closeServerChannelItemMenu("open_other_menu");
        closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });

        const currentCtx = getActiveServerContext();
        openServerPanelMenuAt({
          serverId: panelServerId || normId(currentCtx?.serverId || ""),
          name: currentCtx?.name || serverName,
          iconUrl: String(currentCtx?.iconUrl || serverCtx?.iconUrl || "").trim(),
        }, {
          x: e.clientX,
          y: e.clientY,
        }, {
          variant: "channels",
          anchorEl: bodyEl,
        });
      }
    });
  }

  panel.querySelectorAll("[data-server-category-toggle]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (panel.dataset.serverCategoryDragging === "1") return;
      const catId = normId(btn.getAttribute("data-server-category-toggle") || "");
      if (!catId) return;
      const set = serverChannelCategoryCollapsedByServerId.get(sid) || new Set();
      if (set.has(catId)) set.delete(catId);
      else set.add(catId);
      serverChannelCategoryCollapsedByServerId.set(sid, set);
      renderServerChannelsPanel(serverCtx, allChannels, members, categoryRows);
      applyServerChannelUnreadDecorations();
      refreshServerVoiceChannelBadges();
    });
  });

  panel.querySelectorAll("[data-server-channel-open]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const convId = normId(btn.getAttribute("data-server-channel-open"));
      if (!convId) return;
      const channelId = normId(btn.getAttribute("data-server-channel-id") || "");
      if (channelId && !canCurrentUserViewServerChannelSync(sid, channelId)) {
        await requestAppAlert("You do not have access to this channel.", { title: "Channel Access" }).catch(() => alert("You do not have access to this channel."));
        return;
      }
      const label = btn.getAttribute("data-server-channel-name") || "general";
      const meta = {
        kind: "server",
        isGroup: true,
        displayName: normalizeConversationLabel(label, "general"),
        serverId: sid,
        serverName,
        avatarUrl: String(serverCtx?.iconUrl || "").trim(),
        channelId,
        channel_id: channelId,
        channelType: "text",
      };
      commitServerChannelSelectionForUi(convId, meta, { reason: "channel-click", userInitiated: true });
      await openConversationById(convId, meta);
    });
  });

  panel.querySelectorAll("[data-server-voice-channel]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const convId = normId(btn.getAttribute("data-server-voice-channel"));
      const voiceChannelId = normId(btn.getAttribute("data-server-channel-id") || btn.getAttribute("data-voice-channel-id") || "");
      if (!convId) {
        await requestServerVoiceJoinFromUi({
          serverId: sid,
          channelId: voiceChannelId,
          conversationId: "",
          name: btn.getAttribute("data-server-voice-name") || "",
          type: "voice",
        }, { source: "sidebar" });
        return;
      }
      const activeCallConvId = normId(callConversationId || "");
      const hasLiveCallContext = !!(
        inCall ||
        ringTimeout ||
        pendingOffer ||
        pendingCallInfo ||
        (callPc && callPc.connectionState !== "closed" && callPc.connectionState !== "failed")
      );
      captureStableServerVoicePresenceContext({
        serverId: sid,
        canonicalChannelId: voiceChannelId,
        conversationId: convId,
        roomName: `server-voice:${convId}`,
        userId: state.user?.id || "",
      }, { newSession: true });
      const canSwitchInVoiceV2 = !!(
        isServerVoiceV2Enabled()
        && currentServerVoiceV2Session
        && currentServerVoiceV2Session.serverId === sid
        && voiceChannelId
      );
      if (!canSwitchInVoiceV2 && hasLiveCallContext && activeCallConvId && activeCallConvId !== convId) {
        await hangupCurrentCallByUser("?? Mudaste para outra call.");
      }
      const label = btn.getAttribute("data-server-voice-name") || "voice-lounge";
      const meta = {
        kind: "server",
        isGroup: true,
        displayName: normalizeConversationLabel(label, "voice-lounge"),
        serverId: sid,
        serverName,
        avatarUrl: String(serverCtx?.iconUrl || "").trim(),
        channelType: "voice",
      };
      commitServerChannelSelectionForUi(convId, meta, { reason: "voice-channel-click", userInitiated: true });
      await openConversationById(convId, meta);
      await requestServerVoiceJoinFromUi({
        serverId: sid,
        channelId: voiceChannelId,
        conversationId: convId,
        name: label,
        type: "voice",
      }, { source: "sidebar" });
    });
  });

  panel.querySelectorAll("[data-server-create-channel]").forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.preventDefault();
      e.stopPropagation();
      const defaultTypeRaw = String(btn.getAttribute("data-server-create-type") || "text").trim().toLowerCase();
      const defaultType = defaultTypeRaw === "voice" || defaultTypeRaw === "category" ? defaultTypeRaw : "text";
      const defaultCategoryId = normId(btn.getAttribute("data-server-create-category-id") || "");
      await openServerChannelCreateModal({
        serverId: sid,
        name: serverName,
        iconUrl: String(serverCtx?.iconUrl || "").trim(),
      }, {
        defaultType,
        defaultCategoryId,
      });
    });
  });

  panel.querySelectorAll("[data-server-panel-menu-open]").forEach((btn) => {
    const openMenu = (point = null) => {
      const rect = btn.getBoundingClientRect();
      openServerPanelMenuAt({
        serverId: sid,
        name: serverName,
        iconUrl: String(serverCtx?.iconUrl || "").trim(),
      }, point || { x: Math.round(rect.left), y: Math.round(rect.bottom + 6) }, { anchorEl: btn });
    };
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const hasPointerPoint = Number(e.clientX) > 0 || Number(e.clientY) > 0;
      openMenu(hasPointerPoint ? { x: e.clientX, y: e.clientY } : null);
    });
    btn.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openMenu({ x: e.clientX || 0, y: e.clientY || 0 });
    });
  });

  if (canManageChannelStructure) {
    const dragState = {
      type: "",
      channelId: "",
      categoryId: "",
      sourceCategoryId: "",
    };
    let dragGhostEl = null;
    const dropClasses = ["is-drop-before", "is-drop-after", "is-drop-over"];
    const cleanupDragGhost = () => {
      if (!dragGhostEl) return;
      try { dragGhostEl.remove(); } catch (_) {}
      dragGhostEl = null;
    };
    const buildDragGhost = (sourceEl, dragType) => {
      const type = String(dragType || "").trim().toLowerCase();
      let label = "";
      let icon = "#";
      if (type === "category") {
        label = String(
          sourceEl.getAttribute("data-server-category-name")
          || sourceEl.querySelector(".serverChannelsCategory__name")?.textContent
          || "Category"
        ).trim();
        icon = "?";
      } else {
        const nestedChannelBtn = sourceEl.matches?.(".serverVoiceRoomWrap")
          ? sourceEl.querySelector("[data-server-channel-type]")
          : sourceEl;
        const channelType = String(
          nestedChannelBtn?.getAttribute?.("data-server-channel-type")
          || sourceEl.getAttribute("data-server-channel-type")
          || "text"
        ).trim().toLowerCase();
        label = String(
          nestedChannelBtn?.getAttribute?.("data-server-channel-name")
          || nestedChannelBtn?.getAttribute?.("data-server-voice-name")
          || sourceEl.getAttribute("data-server-channel-name")
          || sourceEl.getAttribute("data-server-voice-name")
          || sourceEl.querySelector(".serverChannelItem__label, .serverVoiceRoom__label")?.textContent
          || "channel"
        ).trim();
        icon = channelType === "voice" ? UI_GLYPHS.voiceChannel : "#";
      }
      const ghost = document.createElement("div");
      ghost.className = "serverChannelDragGhost";
      const sourceRect = sourceEl.getBoundingClientRect?.() || null;
      const nextWidth = sourceRect
        ? Math.max(170, Math.min(320, Math.round(sourceRect.width)))
        : 220;
      ghost.style.width = `${nextWidth}px`;
      ghost.innerHTML = `
        <span class="serverChannelDragGhost__icon" aria-hidden="true">${esc(icon)}</span>
        <span class="serverChannelDragGhost__label">${esc(label || "Channel")}</span>
      `;
      document.body.appendChild(ghost);
      dragGhostEl = ghost;
      return ghost;
    };
    const clearDropState = () => {
      panel.querySelectorAll(
        '[data-server-drop-channel-target="1"], [data-server-category-drop="1"], [data-server-drag-type]'
      ).forEach((el) => {
        dropClasses.forEach((cls) => el.classList.remove(cls));
      });
    };
    const refreshAfterLayoutChange = async () => {
      clearDropState();
      serverChannelListByServerId.delete(sid);
      serverChannelCategoryListByServerId.delete(sid);
      await refreshServerConversationUi({ force: true, reason: "server-channel-change", refreshChannels: true, refreshMembers: true }).catch(() => {});
    };
    const getChannelRowForDrag = (channelId = "") => {
      const cid = normId(channelId || "");
      return (allChannels || []).find((row) => normId(row?.id || "") === cid) || null;
    };
    const isValidChannelDropZone = (dragChannelId = "", targetCategoryId = "", targetUncategorizedType = "") => {
      const source = getChannelRowForDrag(dragChannelId);
      if (!source) return false;
      const targetCatId = normId(targetCategoryId || "");
      if (targetCatId) return true;
      const zoneType = String(targetUncategorizedType || "").trim().toLowerCase();
      if (!zoneType) return true;
      const sourceType = normalizeConversationChannelType(source?.channelType || "text");
      return zoneType === "voice" ? sourceType === "voice" : sourceType !== "voice";
    };
    const renderOptimisticServerChannelLayout = (nextChannels = allChannels, nextCategories = categoryRows, reason = "server-channel-reorder-optimistic") => {
      const visualState = captureServerChannelSidebarVisualState();
      renderServerChannelsPanel(serverCtx, nextChannels, members, nextCategories);
      restoreServerChannelSidebarVisualState(visualState);
      applyServerChannelUnreadDecorations();
      refreshServerVoiceChannelBadges();
      activeServerChannelsRealtimeState.lastAppliedPayloadReason = reason;
    };
    const moveCategoryByDrop = async (dragCategoryId, targetCategoryId, position = "before") => {
      const dragId = normId(dragCategoryId || "");
      const targetId = normId(targetCategoryId || "");
      if (!dragId || !targetId || dragId === targetId) return;

      const orderedIds = categoryRows.map((cat) => normId(cat?.id || "")).filter(Boolean);
      const fromIdx = orderedIds.indexOf(dragId);
      const targetIdx = orderedIds.indexOf(targetId);
      if (fromIdx < 0 || targetIdx < 0) return;

      orderedIds.splice(fromIdx, 1);
      let insertIdx = targetIdx;
      if (fromIdx < targetIdx) insertIdx -= 1;
      if (String(position || "before").toLowerCase() === "after") insertIdx += 1;
      insertIdx = Math.max(0, Math.min(orderedIds.length, insertIdx));
      orderedIds.splice(insertIdx, 0, dragId);

      const optimisticCategories = categoryRows.map((cat) => {
        const id = normId(cat?.id || "");
        const idx = orderedIds.indexOf(id);
        return idx >= 0 ? { ...cat, position: idx } : cat;
      });
      serverChannelCategoryListByServerId.set(sid, optimisticCategories);
      renderOptimisticServerChannelLayout(allChannels, optimisticCategories, "category_reorder_optimistic");

      const movedIndex = orderedIds.indexOf(dragId);
      const saveRes = await reorderServerChannelCategoryRpc({
        serverId: sid,
        categoryId: dragId,
        beforeCategoryId: normId(orderedIds[movedIndex + 1] || ""),
        afterCategoryId: normId(orderedIds[movedIndex + 1] || "") ? "" : normId(orderedIds[movedIndex - 1] || ""),
      });
      if (saveRes?.error) {
        if (isMissingRpcError(saveRes.error)) serverChannelManagementSqlAvailable = false;
        await refreshAfterLayoutChange();
        alert(isMissingRpcError(saveRes.error)
          ? "Channel reorder SQL patch is required."
          : `Erro ao mover categoria: ${saveRes.error?.message || saveRes.error}`);
        return;
      }
      serverChannelManagementSqlAvailable = true;
      if (Array.isArray(saveRes?.data)) {
        const normalizedCategories = saveRes.data.map((row) => {
          const id = normId(row?.id || "");
          if (!id) return null;
          return {
            id,
            serverId: sid,
            name: normalizeServerCategoryName(row?.name || "Category"),
            position: Number(row?.position || 0),
            createdAt: Date.parse(String(row?.created_at || row?.createdAt || "")) || Number(row?.createdAt || 0) || 0,
          };
        }).filter(Boolean);
        if (normalizedCategories.length) applyServerChannelsSnapshot(sid, allChannels, normalizedCategories, { reason: "category_reordered" });
      }
      void emitServerChannelsChangedBroadcast(sid, {
        reason: "category_reordered",
        changedCategoryIds: [dragId],
        orderedCategoryIds: orderedIds,
        categories: optimisticCategories,
      });
    };
    const moveChannelByDrop = async ({
      dragChannelId = "",
      targetChannelId = "",
      targetCategoryId = "",
      targetUncategorizedType = "",
      position = "before",
      dropOnCategory = false,
    } = {}) => {
      const dragId = normId(dragChannelId || "");
      const targetId = normId(targetChannelId || "");
      if (!dragId) return;
      if (!dropOnCategory && (!targetId || targetId === dragId)) return;
      const sourceChannel = getChannelRowForDrag(dragId);
      if (!sourceChannel) return;
      if (!dropOnCategory && targetId) {
        const targetChannel = getChannelRowForDrag(targetId);
        const targetCatId = normId(targetChannel?.categoryId || "");
        const sourceType = normalizeConversationChannelType(sourceChannel?.channelType || "text");
        const targetType = normalizeConversationChannelType(targetChannel?.channelType || "text");
        if (!targetCatId && sourceType !== targetType) return;
      }

      const grouped = new Map();
      (allChannels || []).forEach((channelRow) => {
        const channelId = normId(channelRow?.id || "");
        if (!channelId) return;
        const catId = normId(channelRow?.categoryId || "");
        if (!grouped.has(catId)) grouped.set(catId, []);
        grouped.get(catId).push({
          channelId,
          categoryId: catId,
          originalCategoryId: catId,
          originalPosition: Number(channelRow?.position || 0),
        });
      });

      let moving = null;
      for (const [, rows] of grouped.entries()) {
        const fromIdx = rows.findIndex((row) => row.channelId === dragId);
        if (fromIdx < 0) continue;
        moving = rows.splice(fromIdx, 1)[0];
        break;
      }
      if (!moving) return;

      const destinationCategoryId = normId(targetCategoryId || "");
      if (!isValidChannelDropZone(dragId, destinationCategoryId, dropOnCategory ? targetUncategorizedType : "")) return;
      if (!grouped.has(destinationCategoryId)) grouped.set(destinationCategoryId, []);
      const destinationRows = grouped.get(destinationCategoryId) || [];
      let insertIdx = destinationRows.length;
      if (!dropOnCategory && targetId) {
        const targetIdx = destinationRows.findIndex((row) => row.channelId === targetId);
        if (targetIdx >= 0) {
          insertIdx = String(position || "before").toLowerCase() === "after"
            ? targetIdx + 1
            : targetIdx;
        }
      }
      insertIdx = Math.max(0, Math.min(destinationRows.length, insertIdx));
      moving.categoryId = destinationCategoryId;
      destinationRows.splice(insertIdx, 0, moving);

      const updates = [];
      let beforeChannelId = "";
      let afterChannelId = "";
      const finalDestinationRows = grouped.get(destinationCategoryId) || [];
      const finalMovingIdx = finalDestinationRows.findIndex((row) => row.channelId === dragId);
      if (finalMovingIdx >= 0) {
        beforeChannelId = normId(finalDestinationRows[finalMovingIdx + 1]?.channelId || "");
        afterChannelId = normId(finalDestinationRows[finalMovingIdx - 1]?.channelId || "");
      }
      for (const [catId, rows] of grouped.entries()) {
        rows.forEach((row, idx) => {
          const nextCategoryId = normId(catId || "");
          const changedPosition = Number(row.originalPosition || 0) !== idx;
          const changedCategory = normId(row.originalCategoryId || "") !== nextCategoryId;
          if (!changedPosition && !changedCategory) return;
          updates.push({
            channelId: row.channelId,
            categoryId: nextCategoryId,
            position: idx,
            beforeChannelId: row.channelId === dragId ? beforeChannelId : "",
            afterChannelId: row.channelId === dragId ? (beforeChannelId ? "" : afterChannelId) : "",
            isMovedChannel: row.channelId === dragId,
          });
        });
      }
      if (!updates.length) return;

      const optimisticChannels = allChannels.map((channelRow) => {
        const update = updates.find((entry) => normId(entry?.channelId || "") === normId(channelRow?.id || ""));
        return update ? { ...channelRow, categoryId: normId(update.categoryId || ""), position: Number(update.position || 0) } : channelRow;
      });
      serverChannelListByServerId.set(sid, optimisticChannels);
      renderOptimisticServerChannelLayout(optimisticChannels, categoryRows, "channel_reorder_optimistic");

      const saveRes = await saveServerChannelOrderingForServer(sid, updates);
      if (saveRes?.error) {
        if (isMissingRpcError(saveRes.error)) serverChannelManagementSqlAvailable = false;
        await refreshAfterLayoutChange();
        alert(isMissingRpcError(saveRes.error)
          ? "Channel reorder SQL patch is required."
          : `Erro ao mover canal: ${saveRes.error?.message || saveRes.error}`);
        return;
      }
      serverChannelManagementSqlAvailable = true;
      void emitServerChannelsChangedBroadcast(sid, {
        reason: "channel_reordered",
        changedChannelIds: updates.map((entry) => normId(entry?.channelId || "")).filter(Boolean),
        orderedChannelIds: Array.from(grouped.values()).flat().map((entry) => normId(entry?.channelId || "")).filter(Boolean),
        channels: optimisticChannels,
      });
    };

    panel.querySelectorAll("[data-server-drag-type][draggable='true']").forEach((sourceEl) => {
      sourceEl.addEventListener("dragstart", (e) => {
        const target = eventTargetElement(e);
        if (getServerVoiceMemberDragSourceFromTarget(target)) {
          e.preventDefault();
          e.stopPropagation();
          return;
        }
        const dragType = String(sourceEl.getAttribute("data-server-drag-type") || "").trim().toLowerCase();
        cleanupDragGhost();
        if (dragType === "channel") {
          const channelId = normId(sourceEl.getAttribute("data-server-drag-channel-id") || "");
          if (!channelId) {
            e.preventDefault();
            return;
          }
          dragState.type = "channel";
          dragState.channelId = channelId;
          dragState.sourceCategoryId = normId(sourceEl.getAttribute("data-server-drag-source-category-id") || "");
          sourceEl.classList.add("is-dragging");
        } else if (dragType === "category") {
          const categoryId = normId(sourceEl.getAttribute("data-server-drag-category-id") || "");
          if (!categoryId) {
            e.preventDefault();
            return;
          }
          dragState.type = "category";
          dragState.categoryId = categoryId;
          panel.dataset.serverCategoryDragging = "1";
          sourceEl.classList.add("is-dragging");
        } else {
          e.preventDefault();
          return;
        }
        try {
          e.dataTransfer.effectAllowed = "move";
          e.dataTransfer.setData("text/plain", dragType === "channel" ? dragState.channelId : dragState.categoryId);
          const ghost = buildDragGhost(sourceEl, dragType);
          if (ghost && typeof e.dataTransfer.setDragImage === "function") {
            e.dataTransfer.setDragImage(ghost, 18, 16);
          }
        } catch (_) {}
      });
      sourceEl.addEventListener("dragend", () => {
        dragState.type = "";
        dragState.channelId = "";
        dragState.categoryId = "";
        dragState.sourceCategoryId = "";
        setTimeout(() => {
          if (panel.dataset.serverCategoryDragging === "1") {
            delete panel.dataset.serverCategoryDragging;
          }
        }, 0);
        panel.querySelectorAll("[data-server-drag-type].is-dragging").forEach((el) => {
          el.classList.remove("is-dragging");
        });
        cleanupDragGhost();
        clearDropState();
      });
    });

    panel.querySelectorAll('[data-server-drop-channel-target="1"]').forEach((targetEl) => {
      const resolveDropPosition = (event) => {
        const rect = targetEl.getBoundingClientRect();
        const midpoint = rect.top + (rect.height / 2);
        return Number(event?.clientY || 0) >= midpoint ? "after" : "before";
      };
      targetEl.addEventListener("dragover", (e) => {
        if (dragState.type !== "channel" || !dragState.channelId) return;
        const targetChannelId = normId(targetEl.getAttribute("data-server-channel-id") || "");
        if (!targetChannelId || targetChannelId === dragState.channelId) return;
        e.preventDefault();
        e.stopPropagation();
        const position = resolveDropPosition(e);
        clearDropState();
        targetEl.classList.add(position === "after" ? "is-drop-after" : "is-drop-before");
        try { e.dataTransfer.dropEffect = "move"; } catch (_) {}
      });
      targetEl.addEventListener("drop", async (e) => {
        if (dragState.type !== "channel" || !dragState.channelId) return;
        const targetChannelId = normId(targetEl.getAttribute("data-server-channel-id") || "");
        if (!targetChannelId || targetChannelId === dragState.channelId) return;
        e.preventDefault();
        e.stopPropagation();
        const targetCategoryId = normId(targetEl.getAttribute("data-server-category-id") || "");
        const position = resolveDropPosition(e);
        await moveChannelByDrop({
          dragChannelId: dragState.channelId,
          targetChannelId,
          targetCategoryId,
          position,
          dropOnCategory: false,
        });
      });
    });

    panel.querySelectorAll('[data-server-category-drop="1"]').forEach((sectionEl) => {
      const resolveDropPosition = (event) => {
        const rect = sectionEl.getBoundingClientRect();
        const midpoint = rect.top + (rect.height / 2);
        return Number(event?.clientY || 0) >= midpoint ? "after" : "before";
      };
      sectionEl.addEventListener("dragover", (e) => {
        if (!dragState.type) return;
        const targetCategoryId = normId(sectionEl.getAttribute("data-server-category-section") || "");
        const targetUncategorizedType = String(sectionEl.getAttribute("data-server-uncategorized-type") || "").trim().toLowerCase();
        if (dragState.type === "channel" && dragState.channelId) {
          if (!isValidChannelDropZone(dragState.channelId, targetCategoryId, targetUncategorizedType)) {
            try { e.dataTransfer.dropEffect = "none"; } catch (_) {}
            return;
          }
          e.preventDefault();
          e.stopPropagation();
          clearDropState();
          sectionEl.classList.add("is-drop-over");
          try { e.dataTransfer.dropEffect = "move"; } catch (_) {}
          return;
        }
        if (dragState.type === "category" && dragState.categoryId) {
          if (!targetCategoryId || targetCategoryId === dragState.categoryId) return;
          e.preventDefault();
          e.stopPropagation();
          const position = resolveDropPosition(e);
          clearDropState();
          sectionEl.classList.add(position === "after" ? "is-drop-after" : "is-drop-before");
          try { e.dataTransfer.dropEffect = "move"; } catch (_) {}
        }
      });
      sectionEl.addEventListener("drop", async (e) => {
        if (!dragState.type) return;
        const targetCategoryId = normId(sectionEl.getAttribute("data-server-category-section") || "");
        const targetUncategorizedType = String(sectionEl.getAttribute("data-server-uncategorized-type") || "").trim().toLowerCase();
        if (dragState.type === "channel" && dragState.channelId) {
          if (!isValidChannelDropZone(dragState.channelId, targetCategoryId, targetUncategorizedType)) return;
          e.preventDefault();
          e.stopPropagation();
          await moveChannelByDrop({
            dragChannelId: dragState.channelId,
            targetCategoryId,
            targetUncategorizedType,
            dropOnCategory: true,
          });
          return;
        }
        if (dragState.type === "category" && dragState.categoryId) {
          if (!targetCategoryId || targetCategoryId === dragState.categoryId) return;
          e.preventDefault();
          e.stopPropagation();
          const position = resolveDropPosition(e);
          await moveCategoryByDrop(dragState.categoryId, targetCategoryId, position);
        }
      });
    });

    panel.addEventListener("dragover", (e) => {
      if (!dragState.type) return;
      e.preventDefault();
      try { e.dataTransfer.dropEffect = "move"; } catch (_) {}
    });
    panel.addEventListener("drop", () => {
      clearDropState();
    });
    panel.addEventListener("dragleave", (e) => {
      const related = e?.relatedTarget instanceof Element ? e.relatedTarget : null;
      if (related && panel.contains(related)) return;
      clearDropState();
    });
  }

  applyServerChannelUnreadDecorations();
  refreshServerVoiceChannelBadges();
}

function getServerMembersPanelContextKey(serverId = "", conversationId = "", isPrivate = false, search = "") {
  return [
    normId(serverId || ""),
    normId(conversationId || "") || "server",
    isPrivate ? "private" : "public",
    String(search || "").trim().toLowerCase(),
  ].join(":");
}

function getServerMembersPanelLoadSnapshot(serverId = "") {
  const sid = normId(serverId || "");
  const stateEntry = serverMemberLoadStateByServerId.get(sid) || null;
  const membersLoaded = stateEntry?.loaded === true || serverMemberListByServerId.has(sid);
  const presenceLoaded = !!presence || (Array.isArray(presenceList) && presenceList.length > 0);
  return {
    membersLoaded,
    presenceLoaded,
    loadInFlight: serverMemberLoadInFlightByServerId.has(sid),
    error: stateEntry?.error || null,
  };
}

function buildServerMembersPanelSnapshot(serverId = "", groups = []) {
  const sid = normId(serverId || "");
  return JSON.stringify((groups || []).map((group) => ({
    key: String(group?.key || ""),
    label: String(group?.label || ""),
    color: String(group?.nameColor || ""),
    members: (group?.members || []).map((member) => ({
      id: normId(member?.userId || ""),
      username: String(member?.username || ""),
      displayName: String(member?.displayName || ""),
      avatarUrl: String(member?.avatarUrl || ""),
      nameColor: String(member?.nameColor || member?.roleNameColor || ""),
      presence: String(member?.presenceStatus || "offline"),
      timeout: !!getServerMemberTimeout(sid, normId(member?.userId || "")),
      isMe: !!member?.isMe,
      isBot: !!member?.isBot,
    })),
  })));
}

async function renderServerMembersRightPanel(serverCtx, members = [], {
  forceChannelMembers = false,
  immediate = false,
  reason = "server_members_render",
} = {}) {
  const sid = normId(serverCtx?.serverId || "");
  if (shouldSkipRemovedServerRender(sid, "renderServerMembersRightPanel")) return;
  const membersPanel = document.getElementById("serverMembersPanel");
  const listEl = document.getElementById("serverMembersList");
  const searchInput = document.getElementById("serverMembersSearch");
  if (!sid || !membersPanel || !listEl) return;
  ensureServerInviteCardPolishStyles();
  sanitizeRightSidebarForContext("server_members");
  const renderConversationId = normId(activeDmId || state.activeDm?.conversationId || "");
  const activeChannelCtx = findServerChannelContextByConversationId(renderConversationId) || null;
  const activeChannelBelongsToServer = normId(activeChannelCtx?.serverId || "") === sid;
  const activeChannelType = normalizeConversationChannelType(
    activeChannelCtx?.channel?.channelType || state.activeDm?.channelType || ""
  );
  const isServerVoiceChannelContext = !!(activeChannelBelongsToServer && activeChannelType === "voice");
  if (membersPanel) membersPanel.dataset.serverMembersMode = "members";
  if (membersPanel) membersPanel.dataset.serverMembersRenderVersion = String(serverMemberRenderVersionByServerId.get(sid) || 0);
  const renderToken = ++serverMembersRightPanelRenderToken;
  const suppliedMemberRows = Array.isArray(members) ? members : [];
  const cachedMemberRows = serverMemberListByServerId.get(sid) || [];
  const allMemberRows = suppliedMemberRows.length || !cachedMemberRows.length
    ? suppliedMemberRows
    : cachedMemberRows;
  let memberRows = allMemberRows.slice();
  const roleList = serverRoleListByServerId.get(sid) || [];
  const roleMemberMap = serverRoleMemberMapByServerId.get(sid) || new Map();
  const channelLabel = normalizeConversationLabel(
    activeChannelCtx?.channel?.name
    || state.activeDm?.displayName
    || serverCtx?.name
    || "Channel",
    "Channel"
  );
  const normalizedSearch = String(serverMembersSearchByServerId.get(sid) || "").trim().toLowerCase();
  const panelContextKey = getServerMembersPanelContextKey(
    sid,
    renderConversationId,
    activeChannelCtx?.channel?.isPrivate === true,
    normalizedSearch
  );
  const panelLoadSnapshot = getServerMembersPanelLoadSnapshot(sid);

  if (activeChannelBelongsToServer && renderConversationId && !!activeChannelCtx?.channel?.isPrivate) {
    const channelId = normId(activeChannelCtx?.channel?.id || "");
    const accessState = getPrivateChannelAccessibleMemberState(channelId);
    const canPreserveExistingRows = listEl.dataset.serverMembersContextKey === panelContextKey
      && !!listEl.querySelector("[data-server-right-user], .serverMembersGroup");
    const renderPrivateMemberState = (message) => {
      listEl.innerHTML = `<div class="hint">${esc(message)}</div>`;
      listEl.dataset.serverMembersContextKey = panelContextKey;
      setRightSidebarToServerMembers({
        active: true,
        title: `${channelLabel} Members`,
        count: 0,
      });
      sanitizeRightSidebarForContext("server_members");
    };
    if (!accessState || accessState.loading) {
      if (canPreserveExistingRows) {
        setRightSidebarToServerMembers({
          active: true,
          title: `${channelLabel} Members`,
          count: listEl.querySelectorAll("[data-server-right-user]").length,
        });
        return;
      }
      renderPrivateMemberState("Loading members\u2026");
      return;
    }
    if (accessState.error) {
      if (canPreserveExistingRows) return;
      renderPrivateMemberState("Could not load channel members.");
      return;
    }
    const allowedIds = new Set(normalizeUuidArray(accessState.userIds || []));
    memberRows = allMemberRows.filter((member) => allowedIds.has(normId(member?.userId || "")));
    (accessState.rows || []).forEach((accessibleRow) => {
      const uid = normId(accessibleRow?.userId || "");
      if (!uid || memberRows.some((member) => normId(member?.userId || "") === uid)) return;
      memberRows.push({
        ...accessibleRow,
        isMe: uid === normId(state.user?.id || ""),
        nameColor: normalizeNameColor(getCachedProfile(uid)?.name_color || ""),
      });
    });
  }

  if (!activeChannelCtx?.channel?.isPrivate) {
    const cachedBotRows = serverBotInstallListByServerId.get(sid) || [];
    if (Array.isArray(cachedBotRows) && cachedBotRows.length) memberRows = [...memberRows, ...cachedBotRows];
  }

  const currentServerId = normId(getActiveServerContext()?.serverId || "");
  const currentConversationId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (currentServerId !== sid || currentConversationId !== renderConversationId) return;
  if (renderToken !== serverMembersRightPanelRenderToken) return;

  if (searchInput) {
    const hasInputFocus = document.activeElement === searchInput;
    if (!hasInputFocus) {
      const nextSavedSearch = String(serverMembersSearchByServerId.get(sid) || "");
      if (searchInput.value !== nextSavedSearch) searchInput.value = nextSavedSearch;
    }
    searchInput.oninput = () => {
      serverMembersSearchByServerId.set(sid, String(searchInput.value || ""));
      if (serverMembersSearchRenderRaf) cancelAnimationFrame(serverMembersSearchRenderRaf);
      serverMembersSearchRenderRaf = requestAnimationFrame(() => {
        serverMembersSearchRenderRaf = 0;
        void renderServerMembersRightPanel(serverCtx, allMemberRows, {
          forceChannelMembers: false,
        });
      });
    };
  }

  const presenceOrder = { online: 0, idle: 1, focus: 2, dnd: 3, invisible: 4, offline: 5 };
  const groupsByKey = new Map();

  const resolveGroupMeta = (member) => {
    if (member?.isBot) {
      return { key: "__bots", label: "BOTS", order: 500, nameColor: "" };
    }
    const uid = normId(member?.userId || "");
    let pickedRole = null;
    (roleList || []).forEach((role) => {
      const rid = normId(role?.id || "");
      if (!rid || !uid) return;
      const assigned = roleMemberMap.get(rid);
      if (!(assigned instanceof Set) || !assigned.has(uid)) return;
      if (!pickedRole) {
        pickedRole = role;
        return;
      }
      const posA = Number(role?.position || 0);
      const posB = Number(pickedRole?.position || 0);
      if (posA < posB) {
        pickedRole = role;
      } else if (posA === posB) {
        const nameA = String(role?.name || "");
        const nameB = String(pickedRole?.name || "");
        if (nameA.localeCompare(nameB) < 0) pickedRole = role;
      }
    });
    if (pickedRole) {
      const label = normalizeServerRoleName(pickedRole?.name || "Role") || "Role";
      return {
        key: `role:${normId(pickedRole?.id || "")}`,
        label,
        order: Number(pickedRole?.position || 0) + 10,
        nameColor: normalizeNameColor(pickedRole?.color || ""),
      };
    }
    const baseRole = normalizeServerMemberRoleValue(member?.role || "member");
    if (baseRole === "owner") {
      return { key: "__owner", label: "Owner", order: -200, nameColor: "" };
    }
    if (baseRole === "admin") {
      return { key: "__admin", label: "Admin", order: -100, nameColor: "" };
    }
    return { key: "__members", label: "Members", order: 9999, nameColor: "" };
  };

  memberRows.forEach((m) => {
    const uid = normId(m?.userId || "");
    if (!uid) return;
    const username = String(m?.username || "").trim();
    const globalDisplayName = getServerMemberGlobalDisplayName(m);
    const displayName = resolveServerDisplayName(sid, uid, m, "Member");
    const haystack = `${displayName} ${globalDisplayName} ${username}`.toLowerCase();
    if (normalizedSearch && !haystack.includes(normalizedSearch)) return;

    const presenceStatus = m?.isBot ? normalizeBotPresenceStatus(m?.presenceStatus || m?.effectiveStatus || "offline") : getPresenceStatusForServerMember(uid);
    const groupMeta = resolveGroupMeta(m);
    if (!groupsByKey.has(groupMeta.key)) {
      groupsByKey.set(groupMeta.key, {
        key: groupMeta.key,
        label: groupMeta.label,
        order: Number(groupMeta.order || 0),
        nameColor: normalizeNameColor(groupMeta?.nameColor || ""),
        members: [],
      });
    }
    const existingGroup = groupsByKey.get(groupMeta.key);
    if (existingGroup && !existingGroup.nameColor) {
      existingGroup.nameColor = normalizeNameColor(groupMeta?.nameColor || "");
    }
    existingGroup.members.push({
      ...m,
      presenceStatus,
      username,
      displayName,
      roleNameColor: normalizeNameColor(groupMeta?.nameColor || ""),
    });
  });

  const groups = Array.from(groupsByKey.values())
    .map((group) => ({
      ...group,
      members: (group.members || []).sort((a, b) => {
        const statusDiff = (presenceOrder[a.presenceStatus] ?? 9) - (presenceOrder[b.presenceStatus] ?? 9);
        if (statusDiff) return statusDiff;
        const nameA = String(a.displayName || a.username || "").toLowerCase();
        const nameB = String(b.displayName || b.username || "").toLowerCase();
        const nameDiff = nameA.localeCompare(nameB);
        if (nameDiff) return nameDiff;
        return String(a.userId || "").localeCompare(String(b.userId || ""));
      }),
    }))
    .sort((a, b) => {
      const orderDiff = Number(a.order || 0) - Number(b.order || 0);
      if (orderDiff) return orderDiff;
      return String(a.label || "").localeCompare(String(b.label || ""));
    });

  const rowHtml = (m) => {
    const uid = normId(m?.userId || "");
    const isBot = !!m?.isBot;
    const username = String(m?.username || (isBot ? "bot" : "user")).trim() || (isBot ? "bot" : "user");
    const displayName = isBot
      ? (String(m?.displayName || username || "Bot").trim() || "Bot")
      : resolveServerDisplayName(sid, uid, m, "Member");
    const avatarUrl = String(m?.avatarUrl || "").trim();
    const statusLabelMap = {
      online: "Online",
      idle: "Away",
      focus: "Focus",
      dnd: "Do Not Disturb",
      invisible: "Invisible",
      offline: "Offline",
    };
    const statusLabel = statusLabelMap[m?.presenceStatus] || "Offline";
    const memberActivityMeta = isBot ? getBotPresenceMetaLabel(m) : getServerMemberActivityMeta(uid, statusLabel);
    const profileNameColor = normalizeNameColor(m?.nameColor || "");
    const nameColor = profileNameColor;
    const nameColorStyle = nameColor ? ` style="color:${escAttr(nameColor)}"` : "";
    const isPendingJoin = getFreshPendingMembershipJoins(sid).some((entry) => normId(entry?.userId || "") === uid);
    const timeout = !isBot ? getServerMemberTimeout(sid, uid) : null;
    return `
      <button
        class="serverMemberRow${m?.isMe ? " is-self" : ""}${isBot ? " serverMemberRow--bot" : ""}${isPendingJoin && !isBot ? " serverMemberRow--pendingJoin" : ""}"
        type="button"
        data-user-id="${escAttr(uid)}"
        data-server-right-user="${escAttr(uid)}"
        data-server-right-username="${escAttr(username)}"
        data-server-right-display="${escAttr(displayName)}"
        data-server-right-avatar="${escAttr(avatarUrl)}"
        data-server-right-is-me="${m?.isMe ? "1" : "0"}"
        data-server-right-is-bot="${isBot ? "1" : "0"}"
        data-server-right-bot-id="${isBot ? escAttr(m?.botId || uid) : ""}"
        data-server-right-app-id="${isBot ? escAttr(m?.appId || "") : ""}"
        data-server-right-public-id="${isBot ? escAttr(m?.publicId || "") : ""}"
        data-server-right-banner="${isBot ? escAttr(m?.bannerUrl || "") : ""}"
        data-server-right-description="${isBot ? escAttr(m?.botDescription || "") : ""}"
        data-server-right-public="${isBot && m?.isPublic === true ? "1" : "0"}"
        data-server-right-install-count="${isBot ? escAttr(String(m?.installCount || "")) : ""}"
        data-server-right-presence="${isBot ? escAttr(m?.presenceStatus || "offline") : ""}"
        data-server-right-last-seen="${isBot ? escAttr(m?.presenceLastSeenAt || "") : ""}"
        data-server-right-connection-mode="${isBot ? escAttr(m?.connectionMode || "") : ""}"
        data-server-right-voice-status="${isBot ? escAttr(m?.voiceStatus || "") : ""}"
        data-server-member-row-key="${escAttr(uid)}"
      >
        <div class="serverMemberRow__avatar">
          ${avatarUrl ? buildAvatarMediaHtml(avatarUrl, { userId: uid, alt: "avatar", deferAnimatedStorage: true }) : `<span class="groupDmAvatarFallback">${esc(getGroupOrbFallbackChar(displayName, "U"))}</span>`}
          <span class="statusDot" data-status-dot="${escAttr(uid)}" data-status="${escAttr(m.presenceStatus || "offline")}"></span>
        </div>
        <div class="serverMemberRow__text">
          <div class="serverMemberRow__name"${nameColorStyle}>${esc(displayName)}${m?.isMe ? " (You)" : ""}${isBot ? ' <span class="serverMemberRow__botBadge">BOT</span>' : ""}${timeout ? ' <span class="serverMemberRow__botBadge">TIMED OUT</span>' : ""}</div>
          <div class="serverMemberRow__meta">${isBot ? "Bot" : `@${esc(username)}`} &middot; ${esc(timeout ? (formatServerTimeoutRemaining(timeout) || "Timed out") : memberActivityMeta)}</div>
        </div>
      </button>
    `;
  };

  const visibleCount = groups.reduce((sum, group) => sum + (group.members?.length || 0), 0);
  const onlineMemberCount = groups.reduce((sum, group) => (
    sum + (group.members || []).filter((member) => !["offline", "invisible"].includes(String(member?.presenceStatus || "offline"))).length
  ), 0);
  const nextSnapshot = [
    buildServerMembersPanelSnapshot(sid, groups),
    panelLoadSnapshot.membersLoaded ? "members-loaded" : "members-loading",
    panelLoadSnapshot.presenceLoaded ? "presence-loaded" : "presence-loading",
  ].join("|");
  const previousSnapshot = String(serverMembersPanelSnapshotByContext.get(panelContextKey) || "");
  const sameContext = listEl.dataset.serverMembersContextKey === panelContextKey;
  const hasExistingMemberRows = !!listEl.querySelector("[data-server-right-user], .serverMembersGroup");
  const snapshotUnchanged = sameContext && previousSnapshot === nextSnapshot;
  const previousScrollTop = Number(listEl.scrollTop || 0);
  let nextHtml = "";
  let emptyStateRendered = false;
  let emptyStateReason = "";

  if (!groups.length) {
    if (!panelLoadSnapshot.membersLoaded || !panelLoadSnapshot.presenceLoaded) {
      if (sameContext && hasExistingMemberRows) {
        nextHtml = "";
        emptyStateReason = "background_refresh_preserved_existing_rows";
      } else {
        nextHtml = '<div class="hint">Loading members\u2026</div>';
        emptyStateReason = !panelLoadSnapshot.membersLoaded
          ? "members_not_loaded"
          : "presence_not_loaded";
      }
    } else {
      emptyStateRendered = true;
      emptyStateReason = activeChannelCtx?.channel?.isPrivate
        ? "confirmed_no_accessible_members"
        : (normalizedSearch ? "confirmed_no_search_results" : "confirmed_no_members");
      nextHtml = `<div class="hint">${activeChannelCtx?.channel?.isPrivate ? "No members can access this channel." : "No members found."}</div>`;
    }
  } else {
    nextHtml = groups.map((group) => `
      <section class="serverMembersGroup" data-server-members-group="${escAttr(group.key)}">
        <div class="serverMembersGroup__title">
          <span class="serverMembersGroup__roleName"${group?.nameColor ? ` style="color:${escAttr(group.nameColor)}"` : ""}>${esc(group.label)}</span>
          <span class="serverMembersGroup__count"> - ${group.members.length}</span>
        </div>
        ${group.members.map(rowHtml).join("")}
      </section>
    `).join("");
  }

  const shouldReplaceDom = !!nextHtml && (
    !snapshotUnchanged
    || !sameContext
    || (groups.length > 0 && !hasExistingMemberRows)
  );
  if (shouldReplaceDom) {
    listEl.innerHTML = nextHtml;
    listEl.dataset.serverMembersContextKey = panelContextKey;
    listEl.scrollTop = previousScrollTop;
    serverMembersPanelSnapshotByContext.set(panelContextKey, nextSnapshot);
  } else if (snapshotUnchanged || (sameContext && hasExistingMemberRows && !nextHtml)) {
    serverMembersPanelDebugState.skippedUnchangedRender += 1;
  }

  serverMembersPanelDebugState.renderCount += 1;
  serverMembersPanelDebugState.previousSnapshot = previousSnapshot;
  serverMembersPanelDebugState.nextSnapshot = nextSnapshot;
  serverMembersPanelDebugState.lastContextKey = panelContextKey;
  serverMembersPanelDebugState.emptyStateRendered = emptyStateRendered;
  serverMembersPanelDebugState.emptyStateReason = emptyStateReason;
  serverMembersPanelDebugState.membersLoaded = panelLoadSnapshot.membersLoaded;
  serverMembersPanelDebugState.presenceLoaded = panelLoadSnapshot.presenceLoaded;
  serverMembersPanelDebugState.loadInFlight = panelLoadSnapshot.loadInFlight;
  serverMembersPanelDebugState.rawMemberCount = allMemberRows.length;
  serverMembersPanelDebugState.visibleMemberCount = visibleCount;
  serverMembersPanelDebugState.onlineMemberCount = onlineMemberCount;
  serverMembersRightPanelLastRenderAt = Date.now();
  serverMembersRightPanelLastRenderReason = String(reason || (immediate ? "immediate" : "server_members_render"));
  serverMembersRightPanelLastGroupedOrder = groups.map((group) => ({
    key: group.key,
    members: (group.members || []).map((member) => normId(member?.userId || "")),
  }));

  setRightSidebarToServerMembers({
    active: true,
    title: `${channelLabel} Members`,
    count: visibleCount,
  });
  sanitizeRightSidebarForContext("server_members");

  renderTypingStatusOnUserCards({ reason: "server-members-render" });
  listEl.querySelectorAll(".serverMemberRow[data-server-right-user]").forEach((btn) => {
    if (btn.getAttribute("data-server-member-actions-bound") === "1") return;
    btn.setAttribute("data-server-member-actions-bound", "1");
    btn.addEventListener("click", async () => {
      const userId = normId(btn.getAttribute("data-server-right-user") || "");
      if (!userId) return;
      if (btn.getAttribute("data-server-right-is-bot") === "1") {
        await openBotProfileCard(getBotProfileSeedFromElement(btn));
        return;
      }
      const displayName = btn.getAttribute("data-server-right-display") || "member";
      const avatarUrl = btn.getAttribute("data-server-right-avatar") || "";
      await openCallParticipantProfilePreview(userId, btn, {
        display_name: displayName,
        avatar_url: avatarUrl,
      }, {
        conversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
        conversationLabel: String(state.activeDm?.displayName || "").trim(),
        serverId: sid,
        kind: "server",
      });
    });

    btn.addEventListener("contextmenu", async (e) => {
      const userId = normId(btn.getAttribute("data-server-right-user") || "");
      if (!userId) return;
      e.preventDefault();
      e.stopPropagation();
      closeCallAudioMenu();
      closeServerVoiceMemberMenu({ force: true, reason: "open_other_menu" });
      if (btn.getAttribute("data-server-right-is-bot") === "1") {
        openBotContextMenuAt(getBotProfileSeedFromElement(btn), {
          point: { x: e.clientX, y: e.clientY },
          anchorEl: btn,
        });
        return;
      }

      await ensureServerRolePermissionCache(sid, { force: false }).catch(() => {});
      const username = String(btn.getAttribute("data-server-right-username") || "").trim();
      const displayName = btn.getAttribute("data-server-right-display") || "member";
      const avatarUrl = String(btn.getAttribute("data-server-right-avatar") || "").trim();
      const convId = resolveServerVoiceMenuConversationForMember(sid, userId);
      openDmUserListMenuAt({
        userId,
        username,
        displayName,
        avatarUrl,
        point: { x: e.clientX, y: e.clientY },
        anchorEl: btn,
        serverVoiceMenu: {
          serverId: sid,
          conversationId: convId,
        },
      });
    });
  });
}

async function refreshServerConversationUi({
  force = false,
  reason = "server-refresh",
  refreshChannels = false,
  refreshMembers = true,
} = {}) {
  const refreshReason = String(reason || "server-refresh").trim() || "server-refresh";
  const shouldRefreshChannels = refreshChannels === true;
  const shouldRefreshMembers = refreshMembers !== false;
  const dmMain = document.getElementById("dmMain");
  const body = document.querySelector("#dmMain .dmMainBody");
  const panel = document.getElementById("serverChannelsPanel");
  if (!dmMain || !body || !panel) return;

  const dmVisible = dmMain.style.display !== "none";
  const activeSidebarServerId = dmVisible ? getActiveServerIdForSidebar() : "";
  let serverCtxBase = dmVisible ? getActiveServerContext() : null;
  if (!serverCtxBase && activeSidebarServerId) {
    const row = getServerRowById?.(activeSidebarServerId) || null;
    serverCtxBase = {
      serverId: activeSidebarServerId,
      name: normalizeConversationLabel(row?.name || state.activeDm?.serverName || state.activeDm?.displayName || "Server", "Server"),
      iconUrl: String(row?.iconUrl || state.activeDm?.avatarUrl || "").trim(),
      ownerUserId: normId(row?.ownerUserId || state.activeDm?.ownerUserId || ""),
      defaultConversationId: normId(row?.defaultConversationId || state.activeDm?.conversationId || activeDmId || ""),
      memberCount: Number(row?.memberCount || state.activeDm?.memberCount || 0),
    };
  }
  if (!serverCtxBase || !activeSidebarServerId) {
    teardownActiveServerChannelsRealtime();
    stopActiveServerBotInstallRealtime();
    stopActiveServerBotPresencePolling();
    clearServerSidebarChrome("refresh_server_sidebar_no_context");
    setRightSidebarToServerMembers({ active: false });
    return;
  }

  const serverCtx = {
    ...serverCtxBase,
    serverId: activeSidebarServerId,
    conversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
  };
  const sid = normId(activeSidebarServerId || serverCtx.serverId || "");
  if (shouldSkipRemovedServerRender(sid, `refreshServerConversationUi:${refreshReason}`)) return;
  const conversationIdAtStart = normId(serverCtx.conversationId || "");
  const channelToken = shouldRefreshChannels ? ++serverChannelsRenderToken : serverChannelsRenderToken;
  const memberToken = shouldRefreshMembers ? ++serverMembersRefreshToken : serverMembersRefreshToken;
  const realCachedChannelsAtStart = Array.isArray(serverChannelListByServerId.get(sid))
    ? (serverChannelListByServerId.get(sid) || [])
    : [];
  const cachedChannelsAtStart = getKnownServerChannelsForSidebar(sid);
  const cachedCategoriesAtStart = serverChannelCategoryListByServerId.get(sid) || [];
  const cachedMembersAtStart = serverMemberListByServerId.get(sid) || [];

  claimServerSidebarContext(serverCtx, { reason: `refresh_server_sidebar_start:${refreshReason}` });
  setupActiveServerChannelsRealtime(sid);
  reprojectServerVoiceOccupancy(sid, `server_ui:${refreshReason}:cached`);
  const occupancyHydrationPromise = ensureServerVoiceV2ControlPlaneSubscription(sid, {
    hydrate: true,
    reason: `server_ui:${refreshReason}`,
  }).catch(() => false);
  startActiveServerBotInstallRealtime(sid);
  startActiveServerBotPresencePolling(sid);
  logSidebarRenderState("refresh_server_sidebar_start", {
    mode: "server",
    reason: refreshReason,
    refreshChannels: shouldRefreshChannels,
    refreshMembers: shouldRefreshMembers,
    force: !!force,
    serverId: sid,
    selectedChannelId: conversationIdAtStart,
    channelCacheCount: cachedChannelsAtStart.length,
    realChannelCacheCount: realCachedChannelsAtStart.length,
    memberCacheCount: cachedMembersAtStart.length,
  });

  let channelsForSnapshots = cachedChannelsAtStart;
  let membersForSnapshots = cachedMembersAtStart;

  if (shouldRefreshChannels) {
    setServerChannelLoadState(sid, "loading", { reason: refreshReason, token: channelToken });
    scheduleServerChannelLoadWatchdog(sid, serverCtx, { token: channelToken, reason: refreshReason });
    if (cachedChannelsAtStart.length) {
      renderServerChannelsPanel(serverCtx, cachedChannelsAtStart, membersForSnapshots, cachedCategoriesAtStart || []);
      if (!realCachedChannelsAtStart.length) {
        setServerChannelLoadState(sid, "loading", { reason: refreshReason, token: channelToken });
        scheduleServerChannelLoadWatchdog(sid, serverCtx, { token: channelToken, reason: refreshReason });
      }
    } else {
      renderServerChannelsLoadingState(serverCtx, { reason: refreshReason, token: channelToken });
    }

    let channelResult = { ok: true, error: null, channels: cachedChannelsAtStart };
    let categories = cachedCategoriesAtStart;
    try {
      const [nextChannelResult, nextCategories] = await Promise.all([
        fetchServerChannelsForSidebarResult(sid, { force }),
        fetchServerChannelCategoriesForSidebar(sid, { force }),
      ]);
      channelResult = nextChannelResult || channelResult;
      categories = Array.isArray(nextCategories) ? nextCategories : categories;
    } catch (error) {
      channelResult = {
        ok: false,
        error,
        channels: getKnownServerChannelsForSidebar(sid),
      };
      categories = serverChannelCategoryListByServerId.get(sid) || categories;
      if (!channelResult.channels.length) serverChannelLoadErrorByServerId.set(sid, error);
      if (isSidebarStateDebugEnabled()) {
        console.warn("server channels sidebar refresh failed", {
          reason: refreshReason,
          server_id: sid,
          channel_id: conversationIdAtStart,
          token: channelToken,
          load_state: getServerChannelLoadState(sid)?.state || "idle",
          cache_count: getKnownServerChannelsForSidebar(sid).length,
          message: String(error?.message || error || "unknown_error").slice(0, 240),
          code: String(error?.code || "").slice(0, 80),
          details: String(error?.details || "").slice(0, 240),
          hint: String(error?.hint || "").slice(0, 240),
        });
      }
    }

    if (channelToken !== serverChannelsRenderToken || !isServerSidebarContextStillActive(sid, conversationIdAtStart)) {
      logSidebarRenderState("refresh_server_channels_stale", {
        mode: "server",
        reason: refreshReason,
        serverId: sid,
        conversationId: conversationIdAtStart,
        channelToken,
        activeChannelToken: serverChannelsRenderToken,
        loadState: getServerChannelLoadState(sid)?.state || "idle",
      });
      if (isServerChannelSidebarStillLoading(sid)) {
        queueServerChannelHydrationRetry(sid, "stale-channel-render", { force: true });
      }
    } else {
      const channels = Array.isArray(channelResult?.channels) ? channelResult.channels : [];
      channelsForSnapshots = channels.length ? channels : getKnownServerChannelsForSidebar(sid);
      if (channelResult?.ok === false && channelResult?.error && !channelsForSnapshots.length) {
        serverChannelLoadErrorByServerId.set(sid, channelResult.error);
        setServerChannelLoadState(sid, "error", { reason: refreshReason, token: channelToken });
      } else {
        if (channelsForSnapshots.length) serverChannelLoadErrorByServerId.delete(sid);
        setServerChannelLoadState(sid, "ready", { reason: refreshReason, token: channelToken });
      }
      clearServerChannelLoadWatchdog(sid);
      await occupancyHydrationPromise;
      renderServerChannelsPanel(serverCtx, channelsForSnapshots, membersForSnapshots, categories || []);
      setDmListPanelTitle(serverCtx.name || "Server", { serverMode: true });
      logSidebarRenderState("refresh_server_channels_rendered", {
        mode: "server",
        reason: refreshReason,
        serverId: sid,
        conversationId: conversationIdAtStart,
        channelCount: Array.isArray(channelsForSnapshots) ? channelsForSnapshots.length : 0,
        categoryCount: Array.isArray(categories) ? categories.length : 0,
        channelLoadOk: channelResult?.ok !== false,
        loadState: getServerChannelLoadState(sid)?.state || "idle",
      });
    }
  }

  if (shouldRefreshMembers) {
    try {
      membersForSnapshots = await fetchServerMembersForSidebar(sid, { force });
      await ensureServerRolePermissionCache(sid, { force: !!force }).catch(() => {});
      const activeChannelContext = findServerChannelContextByConversationId(conversationIdAtStart) || null;
      if (
        normId(activeChannelContext?.serverId || "") === sid
        && activeChannelContext?.channel?.isPrivate === true
      ) {
        await loadPrivateChannelAccessibleMembers(
          sid,
          activeChannelContext.channel.id,
          {
            conversationId: conversationIdAtStart,
            force: !!force,
          }
        ).catch(() => null);
      }
      if (memberToken !== serverMembersRefreshToken || !isServerSidebarContextStillActive(sid, conversationIdAtStart)) {
        logSidebarRenderState("refresh_server_members_stale", {
          mode: "server",
          reason: refreshReason,
          serverId: sid,
          conversationId: conversationIdAtStart,
          memberToken,
          activeMemberToken: serverMembersRefreshToken,
        });
        return;
      }
      await renderServerMembersRightPanel(serverCtx, membersForSnapshots || [], {
        forceChannelMembers: !!force,
      });
      logSidebarRenderState("refresh_server_members_rendered", {
        mode: "server",
        reason: refreshReason,
        serverId: sid,
        conversationId: conversationIdAtStart,
        memberCount: Array.isArray(membersForSnapshots) ? membersForSnapshots.length : 0,
      });
    } catch (error) {
      if (memberToken !== serverMembersRefreshToken || !isServerSidebarContextStillActive(sid, conversationIdAtStart)) return;
      console.warn("server members refresh failed", {
        reason: refreshReason,
        server_id: sid,
        channel_id: conversationIdAtStart,
        message: String(error?.message || error || "unknown_error").slice(0, 200),
      });
    }
  }

  if (isServerSidebarContextStillActive(sid, conversationIdAtStart)) {
    const activeConversationId = normId(activeDmId || state.activeDm?.conversationId || "");
    const activeChannelCtx = findServerChannelContextByConversationId(activeConversationId) || null;
    const activeChannelBelongsToServer = normId(activeChannelCtx?.serverId || "") === sid;
    const activeChannelType = normalizeConversationChannelType(
      activeChannelCtx?.channel?.channelType || state.activeDm?.channelType || ""
    );
    if (activeChannelBelongsToServer && activeChannelType === "voice") {
      const snapshotChannels = (Array.isArray(channelsForSnapshots) && channelsForSnapshots.length)
        ? channelsForSnapshots
        : getKnownServerChannelsForSidebar(sid);
      void requestServerVoicePresenceSnapshotsForServer(sid, snapshotChannels || [], membersForSnapshots || []);
    }
  }
}
function getFriendsMessagesTitle() {
  return t("sidebar.friends_messages", "Friends / Messages");
}

function setDmListPanelTitle(title, { serverMode = false } = {}) {
  const titleEl = document.querySelector(".leftDockDms .leftDockTitle");
  if (titleEl) titleEl.textContent = String(title || getFriendsMessagesTitle());
  const sectionEl = document.querySelector(".leftDockDms");
  if (sectionEl) sectionEl.classList.toggle("is-server-context", !!serverMode);
}

function isSidebarStateDebugEnabled() {
  try {
    const host = String(window.location?.hostname || "").trim().toLowerCase();
    const flag = String(localStorage.getItem("altara.debug.sidebar") || "").trim().toLowerCase();
    return host === "localhost" || host === "127.0.0.1" || flag === "1" || flag === "true";
  } catch (_) {
    return false;
  }
}

function logSidebarRenderState(event = "", details = {}) {
  if (!isSidebarStateDebugEnabled()) return;
  try {
    console.debug("[sidebar-state]", String(event || "render"), {
      selectedServerId: normId(getActiveServerContext?.()?.serverId || state.activeDm?.serverId || ""),
      selectedChannelId: normId(activeDmId || state.activeDm?.conversationId || ""),
      currentChannelId: normId(state.activeDm?.conversationId || activeDmId || ""),
      currentView: String(state.activeDm?.kind || "home").trim() || "home",
      homeMode: String(document.querySelector("[data-tab].active")?.getAttribute("data-tab") || "").trim(),
      ...(details || {}),
    });
  } catch (_) {}
}

function isChannelSelectDebugEnabled() {
  try {
    if (typeof window === "undefined") return false;
    if (window.__ALTARA_CHANNEL_SELECT_DEBUG__ === true) return true;
    const host = String(window.location?.hostname || "").trim().toLowerCase();
    if (host === "localhost" || host === "127.0.0.1" || host === "::1") return true;
    const raw = String(window.localStorage?.getItem?.("altara.debug.channelSelect") || "").trim().toLowerCase();
    return raw === "1" || raw === "true" || raw === "yes";
  } catch (_) {
    return false;
  }
}

function logChannelSelectState(event = "state", details = {}) {
  if (!isChannelSelectDebugEnabled() || typeof console === "undefined" || typeof console.info !== "function") return;
  try {
    console.info("[channel-select]", String(event || "state"), {
      activeConversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
      activeServerId: normId(getActiveServerContext?.()?.serverId || state.activeDm?.serverId || ""),
      userNavigationVersion: Number(serverChannelUserNavigationVersion || 0),
      ...(details || {}),
    });
  } catch (_) {}
}

function getActiveServerChannelConversationId() {
  const convId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return "";
  const kind = String(state.activeDm?.kind || getConversationMeta(convId)?.kind || "").trim().toLowerCase();
  if (kind === "server") return convId;
  const ctx = findServerChannelContextByConversationId(convId) || null;
  return ctx?.serverId ? convId : "";
}

function updateServerChannelActiveState(conversationId = "", { reason = "active-channel-sync", serverId = "" } = {}) {
  const activeConversationId = normId(conversationId || getActiveServerChannelConversationId());
  const panel = document.getElementById("serverChannelsPanel");
  if (!panel || panel.classList.contains("hidden")) return false;
  const sid = normId(serverId || panel.getAttribute("data-server-panel-server-id") || getActiveServerContext?.()?.serverId || state.activeDm?.serverId || "");
  let activeMatches = 0;
  let rowCount = 0;

  panel.querySelectorAll("[data-server-channel-open]").forEach((btn) => {
    rowCount += 1;
    const convId = normId(btn.getAttribute("data-server-channel-open") || "");
    const isActive = !!activeConversationId && convId === activeConversationId;
    if (isActive) activeMatches += 1;
    btn.classList.toggle("is-active", isActive);
    if (isActive) btn.setAttribute("aria-current", "page");
    else btn.removeAttribute("aria-current");
  });

  panel.querySelectorAll("[data-server-voice-channel]").forEach((btn) => {
    rowCount += 1;
    const convId = normId(btn.getAttribute("data-server-voice-channel") || "");
    const isActive = !!activeConversationId && convId === activeConversationId;
    if (isActive) activeMatches += 1;
    btn.classList.toggle("is-active", isActive);
    if (isActive) btn.setAttribute("aria-current", "page");
    else btn.removeAttribute("aria-current");
    const wrap = btn.closest(".serverVoiceRoomWrap");
    if (wrap) wrap.classList.toggle("is-active", isActive);
  });

  panel.querySelectorAll(".serverChannelsCategory").forEach((section) => {
    const hasActive = !!section.querySelector(".serverChannelItem.is-active, .serverVoiceRoom.is-active");
    section.classList.toggle("is-active", hasActive);
  });

  logChannelSelectState("active_state_updated", {
    reason,
    serverId: sid,
    channelId: activeConversationId,
    rowCount,
    activeMatches,
  });
  return activeMatches > 0;
}

function markServerChannelUserNavigation({ reason = "channel-click", serverId = "", conversationId = "" } = {}) {
  serverChannelUserNavigationVersion += 1;
  logChannelSelectState("user_navigation", {
    reason,
    serverId: normId(serverId || ""),
    channelId: normId(conversationId || ""),
    userNavigationVersion: serverChannelUserNavigationVersion,
  });
  return serverChannelUserNavigationVersion;
}

function commitServerChannelSelectionForUi(conversationId = "", meta = {}, { reason = "channel-click", userInitiated = false } = {}) {
  const convId = normId(conversationId || meta?.conversationId || meta?.conversation_id || "");
  if (!convId) return null;
  const previousActiveChannelId = getActiveServerChannelConversationId() || normId(activeDmId || state.activeDm?.conversationId || "");
  const serverCtx = findServerChannelContextByConversationId(convId) || null;
  const sid = normId(meta?.serverId || meta?.server_id || serverCtx?.serverId || state.activeDm?.serverId || "");
  const label = normalizeConversationLabel(
    meta?.displayName || meta?.display_name || meta?.name || serverCtx?.channel?.name || "general",
    normalizeConversationChannelType(meta?.channelType || serverCtx?.channel?.channelType || "text") === "voice" ? "voice-lounge" : "general"
  );
  const channelType = normalizeConversationChannelType(meta?.channelType || meta?.channel_type || serverCtx?.channel?.channelType || "text");
  const serverChannelId = normId(meta?.channelId || meta?.channel_id || serverCtx?.channel?.id || "");
  const navigationVersion = userInitiated
    ? markServerChannelUserNavigation({ reason, serverId: sid, conversationId: convId })
    : Number(serverChannelUserNavigationVersion || 0);

  clearActiveConversationMessageRestoreWatchdog?.();
  dmMessageLoadToken += 1;
  activeDmId = convId;
  state.activeDm = {
    ...(normId(state.activeDm?.conversationId || "") === convId ? state.activeDm : {}),
    ...(meta || {}),
    conversationId: convId,
    displayName: label,
    kind: "server",
    isGroup: true,
    serverId: sid,
    serverName: String(meta?.serverName || state.activeDm?.serverName || ""),
    avatarUrl: String(meta?.avatarUrl || state.activeDm?.avatarUrl || "").trim(),
    channelId: serverChannelId,
    channelType,
  };
  setConversationMeta(convId, {
    ...(getConversationMeta(convId) || {}),
    ...(meta || {}),
    conversationId: convId,
    displayName: label,
    kind: "server",
    isGroup: true,
    serverId: sid,
    channelId: serverChannelId,
    channel_id: serverChannelId,
    channelType,
  });
  if (sid) rememberServerLastChannel(sid, convId, { persist: true });

  try { setMidMode("dm"); } catch (_) {}
  try { setRightSidebarInteractionModeForConversation({ serverMode: true, forceHidden: false, applyCollapsed: true }); } catch (_) {}
  const titleEl = document.getElementById("dmTitle");
  if (titleEl) setElementTextIfChanged(titleEl, label);
  try { updateDmHeaderAvatar(); } catch (_) {}
  try { applyDmTitleNameStyle(); } catch (_) {}
  const msgsBox = document.getElementById("dmMessages");
  if (msgsBox) {
    bindDmJumpLatestButtonOnce(msgsBox);
    const renderedCache = tryRenderMemoryCachedConversationMessages(convId, { source: `${reason}-memory-cache` });
    if (!renderedCache) {
      setElementHtmlIfChanged(msgsBox, `<div class="hint">${esc(t("app.loading", "Loading..."))}</div>`);
      setDmJumpLatestVisible(false);
    }
  }
  updateServerChannelActiveState(convId, { reason, serverId: sid });
  try { syncDmActiveListHighlight(); } catch (_) {}
  try { captureCurrentMainNavigationRoute(); } catch (_) {}

  logChannelSelectState("commit", {
    reason,
    serverId: sid,
    previousActiveChannelId,
    newActiveChannelId: convId,
    channelType,
    userNavigationVersion: navigationVersion,
    userInitiated: !!userInitiated,
  });
  return { conversationId: convId, serverId: sid, navigationVersion };
}
function getActiveServerSidebarContext() {
  const dmMain = document.getElementById("dmMain");
  if (!dmMain || dmMain.style.display === "none") return null;
  const sid = getActiveServerIdForSidebar();
  if (!sid) return null;
  const conversationId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (!conversationId) return null;
  const serverCtx = getActiveServerContext?.() || null;
  const row = serverCtx?.serverId ? null : (getServerRowById?.(sid) || null);
  return {
    ...(serverCtx || {}),
    serverId: sid,
    name: normalizeConversationLabel(serverCtx?.name || row?.name || state.activeDm?.serverName || state.activeDm?.displayName || "Server", "Server"),
    iconUrl: String(serverCtx?.iconUrl || row?.iconUrl || state.activeDm?.avatarUrl || "").trim(),
    ownerUserId: normId(serverCtx?.ownerUserId || row?.ownerUserId || state.activeDm?.ownerUserId || ""),
    defaultConversationId: normId(serverCtx?.defaultConversationId || row?.defaultConversationId || conversationId),
    memberCount: Number(serverCtx?.memberCount || row?.memberCount || state.activeDm?.memberCount || 0),
    conversationId,
  };
}

function isServerSidebarContextStillActive(serverId = "", conversationId = "") {
  const active = getActiveServerSidebarContext();
  if (!active) return false;
  if (serverId && normId(active.serverId || "") !== normId(serverId || "")) return false;
  if (conversationId && normId(active.conversationId || "") !== normId(conversationId || "")) return false;
  return true;
}

function clearServerSidebarChrome(reason = "clear_server_sidebar") {
  serverSidebarRenderToken += 1;
  serverChannelsRenderToken += 1;
  serverMembersRefreshToken += 1;
  const panel = document.getElementById("serverChannelsPanel");
  const body = document.querySelector("#dmMain .dmMainBody");
  if (panel) {
    panel.classList.add("hidden");
    panel.setAttribute("aria-hidden", "true");
    panel.removeAttribute("data-server-panel-server-id");
    panel.removeAttribute("data-server-channel-load-state");
    panel.removeAttribute("data-server-channel-load-reason");
    panel.removeAttribute("data-server-channel-load-token");
  }
  for (const timer of serverChannelLoadWatchdogByServerId.values()) clearTimeout(timer);
  serverChannelLoadWatchdogByServerId.clear();
  for (const timer of serverChannelHydrationRetryTimersByServerId.values()) clearTimeout(timer);
  serverChannelHydrationRetryTimersByServerId.clear();
  for (const timer of serverChannelBackgroundHydrationTimersByServerId.values()) clearTimeout(timer);
  serverChannelBackgroundHydrationTimersByServerId.clear();
  if (body) body.classList.remove("is-server-layout");
  setDmListPanelTitle(getFriendsMessagesTitle(), { serverMode: false });
  logSidebarRenderState(reason, { mode: "home" });
}

function hasServerSidebarShell(serverId = "") {
  const sid = normId(serverId || "");
  const panel = document.getElementById("serverChannelsPanel");
  if (!sid || !panel) return false;
  const panelSid = normId(panel.getAttribute("data-server-panel-server-id") || "");
  if (panelSid !== sid) return false;
  return !!(panel.querySelector(".serverChannelsPanel__top") && panel.querySelector(".serverChannelsPanel__body"));
}

function renderServerSidebarShell(serverCtx = null, { reason = "server-sidebar-shell", forceHydration = true } = {}) {
  const sid = normId(serverCtx?.serverId || "");
  const panel = document.getElementById("serverChannelsPanel");
  const body = document.querySelector("#dmMain .dmMainBody");
  if (!sid || !panel || !body) return false;
  if (shouldSkipRemovedServerRender(sid, `renderServerSidebarShell:${reason}`)) return false;

  const ctx = buildServerChannelFallbackContext(sid, serverCtx) || serverCtx || { serverId: sid, name: "Server" };
  const serverName = normalizeConversationLabel(ctx?.name || "Server", "Server");
  const serverIconUrl = String(ctx?.iconUrl || "").trim();
  const serverInitial = getGroupOrbFallbackChar(serverName, "S");
  const knownChannels = getKnownServerChannelsForSidebar(sid, { activeConversationId: normId(ctx?.conversationId || activeDmId || state.activeDm?.conversationId || "") });
  const realCachedChannels = Array.isArray(serverChannelListByServerId.get(sid)) ? (serverChannelListByServerId.get(sid) || []) : [];
  const dmList = document.getElementById("dmList");
  if (dmList) dmList.replaceChildren();
  setDmListPanelTitle(serverName, { serverMode: true });
  body.classList.add("is-server-layout");
  panel.classList.remove("hidden");
  panel.setAttribute("aria-hidden", "false");
  panel.setAttribute("data-server-panel-server-id", sid);

  logSidebarRenderState("render_server_sidebar_shell_start", {
    mode: "server",
    reason,
    serverId: sid,
    selectedChannelId: normId(activeDmId || state.activeDm?.conversationId || ""),
    cacheCount: knownChannels.length,
    realCacheCount: realCachedChannels.length,
    hasShell: hasServerSidebarShell(sid),
    loadState: getServerChannelLoadState(sid)?.state || "idle",
    domStillLoading: isServerChannelSidebarStillLoading(sid),
  });

  if (knownChannels.length) {
    renderServerChannelsPanel(ctx, knownChannels, serverMemberListByServerId.get(sid) || [], serverChannelCategoryListByServerId.get(sid) || []);
    if (!realCachedChannels.length && forceHydration) {
      const token = ++serverChannelsRenderToken;
      setServerChannelLoadState(sid, "loading", { reason: `${reason}:hydrate`, token });
      scheduleServerChannelLoadWatchdog(sid, ctx, { token, reason: `${reason}:hydrate` });
      queueServerChannelBackgroundHydration(sid, ctx, `${reason}:background-hydration`);
    }
    logSidebarRenderState("render_server_sidebar_shell_panel", {
      mode: "server",
      reason,
      serverId: sid,
      channelCount: knownChannels.length,
      realCacheCount: realCachedChannels.length,
      domStillLoading: isServerChannelSidebarStillLoading(sid),
    });
    return true;
  }

  setServerChannelLoadState(sid, "loading", { reason, token: serverChannelsRenderToken });
  panel.innerHTML = `
    <div class="serverChannelsPanel__top">
      <button class="serverChannelsPanel__identity serverChannelsPanel__identityBtn" type="button" data-server-panel-menu-open="1" title="Server menu" aria-label="Open server menu for ${escAttr(serverName)}">
        <span class="serverChannelsPanel__icon">
          ${serverIconUrl ? `<img src="${esc(serverIconUrl)}" alt="server icon" />` : `<span>${esc(serverInitial)}</span>`}
        </span>
        <span class="serverChannelsPanel__identityMeta">
          <span class="serverChannelsPanel__name">${esc(serverName)}</span>
          <span class="serverChannelsPanel__meta">Server Channels</span>
        </span>
        <span class="serverChannelsPanel__menuChevron" aria-hidden="true">&#9662;</span>
      </button>
    </div>
    <div class="serverChannelsPanel__body">
      <section class="serverChannelsQuick">
        <button class="serverQuickItem" type="button" disabled>
          <span class="serverQuickItem__icon" aria-hidden="true">&#128197;</span>
          <span class="serverQuickItem__label">Events</span>
        </button>
        <button class="serverQuickItem" type="button" disabled>
          <span class="serverQuickItem__icon" aria-hidden="true">&#11015;</span>
          <span class="serverQuickItem__label">Server Boosts</span>
        </button>
      </section>
      <section class="serverChannelsCategory serverChannelsCategory--root serverChannelsCategory--uncategorized">
        <div class="serverChannelsHint">Loading channels...</div>
      </section>
    </div>
  `;
  panel.setAttribute("data-server-channel-load-state", "loading");
  panel.setAttribute("data-server-channel-load-reason", reason);
  if (forceHydration) {
    scheduleServerChannelLoadWatchdog(sid, ctx, { token: serverChannelsRenderToken, reason });
    queueServerChannelBackgroundHydration(sid, ctx, `${reason}:background-hydration`);
  }
  logSidebarRenderState("render_server_sidebar_shell_end", {
    mode: "server",
    reason,
    serverId: sid,
    hasShell: hasServerSidebarShell(sid),
    loadState: getServerChannelLoadState(sid)?.state || "idle",
    domStillLoading: isServerChannelSidebarStillLoading(sid),
  });
  return true;
}

function ensureServerSidebarForCurrentContext(reason = "server-sidebar-invariant") {
  const ctx = getActiveServerSidebarContext?.() || null;
  const sid = normId(ctx?.serverId || "");
  if (!sid) return false;
  if (shouldSkipRemovedServerRender(sid, `ensureServerSidebarForCurrentContext:${reason}`)) return false;
  if (hasServerSidebarShell(sid)) return true;
  if (isSidebarStateDebugEnabled()) {
    console.warn("[sidebar-state] missing server shell, repairing", {
      reason: String(reason || "server-sidebar-invariant"),
      server_id: sid,
      channel_id: normId(activeDmId || state.activeDm?.conversationId || ""),
    });
  }
  logSidebarRenderState("server_sidebar_shell_missing_repair", {
    mode: "server",
    reason,
    serverId: sid,
    selectedChannelId: normId(activeDmId || state.activeDm?.conversationId || ""),
    cacheCount: getKnownServerChannelsForSidebar(sid).length,
    loadState: getServerChannelLoadState(sid)?.state || "idle",
  });
  renderServerSidebarShell(ctx, { reason: `${reason}:repair`, forceHydration: true });
  return true;
}

function claimServerSidebarContext(serverCtx = null, { reason = "server_sidebar_claim" } = {}) {
  const sid = normId(serverCtx?.serverId || "");
  if (!sid) return false;
  if (shouldSkipRemovedServerRender(sid, `claimServerSidebarContext:${reason}`)) return false;
  dmSidebarRenderToken += 1;
  const panel = document.getElementById("serverChannelsPanel");
  const body = document.querySelector("#dmMain .dmMainBody");
  const dmList = document.getElementById("dmList");
  if (dmList) dmList.replaceChildren();
  setDmListPanelTitle(serverCtx?.name || "Server", { serverMode: true });
  if (body) body.classList.add("is-server-layout");
  if (panel) {
    const previousSid = normId(panel.getAttribute("data-server-panel-server-id") || "");
    if (previousSid && previousSid !== sid) panel.replaceChildren();
    panel.classList.remove("hidden");
    panel.setAttribute("aria-hidden", "false");
    panel.setAttribute("data-server-panel-server-id", sid);
    if (!String(panel.innerHTML || "").trim()) {
      panel.innerHTML = "";
      panel.removeAttribute("data-server-channel-load-state");
      panel.removeAttribute("data-server-channel-load-reason");
      panel.removeAttribute("data-server-channel-load-token");
    }
  }
  if (!hasServerSidebarShell(sid)) {
    renderServerSidebarShell(serverCtx, { reason: `${reason}:shell`, forceHydration: true });
  }
  logSidebarRenderState(reason, {
    mode: "server",
    serverId: sid,
    conversationId: normId(serverCtx?.conversationId || activeDmId || state.activeDm?.conversationId || ""),
    cacheCount: getKnownServerChannelsForSidebar(sid).length,
    realCacheCount: Array.isArray(serverChannelListByServerId.get(sid)) ? (serverChannelListByServerId.get(sid) || []).length : 0,
    loadState: getServerChannelLoadState(sid)?.state || "idle",
    domStillLoading: isServerChannelSidebarStillLoading(sid),
  });
  return true;
}

function renderServerSidebar(serverCtx = null) {
  // Legacy path intentionally disabled:
  // server navigation must stay in #serverChannelsPanel, never inside DM list.
  if (serverCtx?.serverId && !shouldSkipRemovedServerRender(serverCtx.serverId, "renderServerSidebar")) {
    claimServerSidebarContext(serverCtx, { reason: "legacy_render_server_sidebar" });
  }
}

function renderFriends({ skipPresenceRefresh = false, skipGroupsRail = false } = {}) {
  markPerfStart("friends_sidebar_render");
  const trace = getRelationshipCurrentTrace();
  const traceLabel = relationshipTracePhaseStart(trace, "renderFriends", {
    friendCount: Array.isArray(state.friends) ? state.friends.length : 0,
    skipPresenceRefresh: !!skipPresenceRefresh,
    skipGroupsRail: !!skipGroupsRail,
  });
  const q = getFriendSearchQuery();
  try {
    const list = sortFriendsByBestFriend((state.friends || []).filter((f) => {
      const uid = getFriendUserId(f);
      const a = (f.username || "").toLowerCase();
      const b = String(getFriendDisplayName(f) || "").toLowerCase();
      const c = String(getDmFriendNickname(uid) || "").toLowerCase();
      return !!uid && (!q || a.includes(q) || b.includes(q) || c.includes(q));
    }));

    const renderFriendRowHtml = (f) => {
      const uid = getFriendUserId(f);
      return rowUser(
      { ...f, other_user_id: uid || f.other_user_id, display_name: getFriendDisplayName(f) },
      "",
      uid || null,
      {
        clickable: true,
        attrs: [
          `data-open-dm="${escAttr(f.username || "")}"`,
          `data-user-list-id="${escAttr(uid || "")}"`,
          `data-user-list-username="${escAttr(f.username || "")}"`,
          `data-user-list-display="${escAttr(getFriendDisplayName(f) || f.username || "")}"`,
          `data-user-list-avatar="${escAttr(f.avatar_url || "")}"`,
        ].join(" "),
      }
    );
    };

    const bestFriends = list.filter((f) => isDmBestFriend(getFriendUserId(f)));
    const normalFriends = list.filter((f) => !isDmBestFriend(getFriendUserId(f)));

    const html = [
      bestFriends.length
        ? `
          <div class="friendsSectionTitle">BEST FRIENDS - ${bestFriends.length}</div>
          <div class="friendsSection">
            ${bestFriends.map(renderFriendRowHtml).join("")}
          </div>
        `
        : "",
      normalFriends.length
        ? `
          <div class="friendsSectionTitle">FRIENDS - ${normalFriends.length}</div>
          <div class="friendsSection">
            ${normalFriends.map(renderFriendRowHtml).join("")}
          </div>
        `
        : "",
    ].filter(Boolean).join("");

    const friendsList = $("friendsList");
    if (friendsList) {
      friendsList.innerHTML = html || (
        isAltaraDefinitivelyOffline()
          ? '<div class="hint" role="status">Waiting for connection\u2026</div>'
          : '<div class="hint">' + t("dm.no_friends", "No friends yet. Go to Add Friend.") + '</div>'
      );
    }

    const leftFriends = $("leftFriends");
    if (leftFriends) {
      leftFriends.innerHTML = "";
    }

    if (!skipGroupsRail) renderGroupsRail();

    document.querySelectorAll("[data-open-dm]").forEach(row => {
      const openFromRow = async () => {
        const uname = row.getAttribute("data-open-dm");
        if (!uname) return;
        await openDm(uname);
      };

      row.addEventListener("click", async (e) => {
        const target = eventTargetElement(e);
        if (target?.closest("button,a,input,textarea,select,label")) return;
        await openFromRow();
      });

      row.addEventListener("keydown", async (e) => {
        if (e.key !== "Enter" && e.key !== " ") return;
        e.preventDefault();
        await openFromRow();
      });

      row.addEventListener("contextmenu", (e) => {
        const uid = normId(row.getAttribute("data-user-list-id") || "");
        const username = String(row.getAttribute("data-user-list-username") || "").trim();
        const display = String(row.getAttribute("data-user-list-display") || username).trim();
        const avatar = String(row.getAttribute("data-user-list-avatar") || "").trim();
        if (!uid && !username) return;
        e.preventDefault();
        e.stopPropagation();
        openDmUserListMenuAt({
          userId: uid,
          username,
          displayName: display,
          avatarUrl: avatar,
          point: { x: e.clientX, y: e.clientY },
          anchorEl: row,
        });
      });
    });

    if (!skipPresenceRefresh) updatePresenceRender();
  } finally {
    relationshipTracePhaseEnd(trace, traceLabel, {
      friendCount: Array.isArray(state.friends) ? state.friends.length : 0,
      query: q,
    });
    markPerfEnd("friends_sidebar_render", {
      friendCount: Array.isArray(state.friends) ? state.friends.length : 0,
      query: q,
    });
  }
}

function getFriendRequestPeerUserId(row = {}) {
  return normId(
    row?.other_user_id
    || row?.from_user_id
    || row?.to_user_id
    || row?.user_id
    || row?.id
    || ""
  );
}

function getAddFriendPreviewPrimaryAction(profile = {}) {
  const uid = normId(profile?.id || "");
  const username = String(profile?.username || "").trim().toLowerCase();
  const selfId = normId(state.user?.id || "");
  if (!uid) {
    const outgoingByUsername = username
      ? ((state.outgoing || []).find((row) => String(row?.username || "").trim().toLowerCase() === username) || null)
      : null;
    if (outgoingByUsername) {
      return { kind: "sent", label: "Pedido enviado", disabled: true, className: "ghost", requestId: "" };
    }
    return { kind: "none", label: "Sem perfil", disabled: true, className: "ghost", requestId: "" };
  }
  if (uid === selfId) {
    return { kind: "self", label: "Este es tu", disabled: true, className: "ghost", requestId: "" };
  }
  if (isUserBlockedLocally(uid)) {
    return { kind: "blocked", label: t("relationship.blocked", "Blocked"), disabled: true, className: "ghost", requestId: "" };
  }

  const incoming = (state.incoming || []).find((row) => (
    normId(row?.from_user_id || row?.user_id || row?.id || "") === uid
    || (!!username && String(row?.username || "").trim().toLowerCase() === username)
  )) || null;
  if (incoming) {
    return {
      kind: "accept",
      label: "Aceitar pedido",
      disabled: false,
      className: "primary",
      requestId: String(incoming?.request_id || "").trim(),
    };
  }

  const outgoing = (state.outgoing || []).find((row) => (
    normId(row?.to_user_id || row?.user_id || row?.id || "") === uid
    || (!!username && String(row?.username || "").trim().toLowerCase() === username)
  )) || null;
  if (outgoing) {
    return { kind: "sent", label: "Pedido enviado", disabled: true, className: "ghost", requestId: "" };
  }

  if (getFriendRowByUserId(uid)) {
    return { kind: "friend", label: "Ja sao amigos", disabled: true, className: "ghost", requestId: "" };
  }

  if (!String(profile?.username || "").trim()) {
    return { kind: "none", label: "Sem username", disabled: true, className: "ghost", requestId: "" };
  }

  return { kind: "send", label: "Enviar pedido", disabled: false, className: "primary", requestId: "" };
}

function renderAddFriendPreview(profile = null, { query = "", loading = false } = {}) {
  const host = document.getElementById("addFriendPreview");
  if (!host) return;

  const wanted = String(query || "").trim();
  addFriendLookupLastQuery = wanted;
  addFriendPreviewProfileId = String(profile?.id || "").trim();
  addFriendPreviewProfileUsername = String(profile?.username || wanted || "").trim().toLowerCase();

  if (!wanted) {
    addFriendPreviewProfileId = "";
    addFriendPreviewProfileUsername = "";
    host.innerHTML = `<div class="addFriendPreviewEmpty">Escreve um username para ver logo a preview com avatar, banner e bio.</div>`;
    return;
  }

  if (loading) {
    host.innerHTML = `<div class="addFriendPreviewEmpty">A procurar esse perfil...</div>`;
    return;
  }

  if (!profile?.id) {
    addFriendPreviewProfileId = "";
    host.innerHTML = `<div class="addFriendPreviewEmpty">Nao encontrei nenhum perfil para <b>${esc(wanted)}</b>.</div>`;
    return;
  }

  const id = String(profile.id || "").trim();
  const name = String(profile?.display_name || profile?.username || "User").trim();
  const username = String(profile?.username || "").trim();
  const bio = String(profile?.bio || "").trim();
  const avatarUrl = String(profile?.avatar_url || "").trim();
  const initial = String(name || "?").charAt(0).toUpperCase() || "?";
  const status = getPresenceStatusForUser(id);
  const relation = getUserCardRelationMeta(id);
  const primaryAction = getAddFriendPreviewPrimaryAction(profile);
  const messageAction = getUserCardMessageActionMeta(id, username);
  scheduleCanMessageUserRefresh(id);
  const relationHtml = relation?.label
    ? `<div class="userCardRelation" data-tone="${escAttr(relation.tone || "friend")}">${esc(relation.label)}</div>`
    : "";
  const nameColor = resolveUserNameColor(id, profile?.name_color);
  const bannerUrl = resolveUserBannerUrl(id, profile?.banner_url || profile?.theme_settings?.banner_url || "");
  const tileColor = resolveCallTileColor(id, profile?.call_tile_color);
  const avatarHtml = avatarUrl
    ? buildAvatarMediaHtml(avatarUrl, { userId: id, profile, alt: "avatar", controlledGif: true })
    : `<span class="msg__avatarFallback">${esc(initial)}</span>`;
  const messageHint = messageAction?.action === "send_message_request" && !messageAction?.disabled
    ? "This will send a message request."
    : (messageAction?.action === "privacy_blocked" ? (messageAction?.reason || "This user isn't accepting messages.") : "");

  host.innerHTML = `
    <article class="addFriendPreviewCard">
      <div class="addFriendPreviewBanner"></div>
      <div class="addFriendPreviewBody">
        <div class="addFriendPreviewIdentity">
          <div class="addFriendPreviewAvatar">
            <div class="addFriendPreviewAvatarMedia">${avatarHtml}</div>
            <span class="statusDot addFriendPreviewAvatarStatusDot" data-status-dot="${escAttr(id)}" data-status="${escAttr(status || "offline")}"></span>
          </div>
          <div class="addFriendPreviewMeta">
            <div class="addFriendPreviewBadgeRow">${relationHtml}</div>
            <div class="addFriendPreviewName${nameColor ? " userNameCustom" : ""}"${nameColor ? ` style="--user-name-color:${escAttr(nameColor)}"` : ""}>${esc(name)}</div>
            <div class="addFriendPreviewHandle">@${esc(username || "user")}</div>
          </div>
        </div>
        <div class="addFriendPreviewBio">${esc(bio || t("dm.no_bio", "No bio."))}</div>
        <div class="addFriendPreviewActions">
          <button
            class="btn ${escAttr(primaryAction.className || "ghost")}"
            type="button"
            data-add-preview-action="${escAttr(primaryAction.kind || "none")}"
            ${primaryAction.disabled ? "disabled" : ""}
            ${primaryAction.requestId ? `data-add-preview-request-id="${escAttr(primaryAction.requestId)}"` : ""}
          >${esc(primaryAction.label || t("usercard.unavailable", "Unavailable"))}</button>
          <button
            class="btn ghost"
            type="button"
            data-add-preview-message="1"
            ${messageAction?.disabled ? "disabled" : ""}
            title="${escAttr(messageAction?.reason || messageHint || messageAction?.label || "") }"
          >${esc(messageAction?.label || t("usercard.message", "Message"))}</button>
          <button class="btn ghost" type="button" data-add-preview-open-profile="1">${t("usercard.profile", "Profile")}</button>
        </div>
        ${messageHint ? `<div class="addFriendPreviewMessageHint">${esc(messageHint)}</div>` : ""}
      </div>
    </article>
  `;

  const bannerEl = host.querySelector(".addFriendPreviewBanner");
  if (bannerEl) {
    const base = tileColor || "#3a4668";
    const start = mixHex(base, "#1a2133", 0.62);
    const end = mixHex(base, "#0b121d", 0.86);
    const glow = rgbaFromHex(base, 0.24);
    applyBannerStyle(bannerEl, bannerUrl, start, end, glow, {
      userId: id,
      profile,
    });
    if (!bannerUrl) {
      bannerEl.style.backgroundImage = `linear-gradient(140deg, ${start}, ${end} 80%)`;
    }
  }
  queueManagedGifPlaybackSync(host);

  host.querySelector('[data-add-preview-action="send"]')?.addEventListener("click", async () => {
    await sendFriendRequest(username, { preserveInput: true });
  });
  host.querySelector('[data-add-preview-action="accept"]')?.addEventListener("click", async (e) => {
    const requestId = String(e.currentTarget?.getAttribute("data-add-preview-request-id") || "").trim();
    if (!requestId) return;
    await acceptReq(requestId);
    void scheduleAddFriendProfileLookup({ immediate: true, force: true });
  });
  host.querySelector('[data-add-preview-message]')?.addEventListener("click", async () => {
    const currentAction = getUserCardMessageActionMeta(id, username);
    if (currentAction?.action === "open_dm") {
      await startDmWith(username, name || username, avatarUrl || null, id);
      return;
    }
    if (currentAction?.action === "accept_message_request" && currentAction?.requestId) {
      const result = await acceptMessageReq(currentAction.requestId);
      if (result?.ok && result?.conversationId) await showDm(result.conversationId, { autoAnswerIfPending: true });
      return;
    }
    if (currentAction?.action === "send_message_request") {
      await promptAndStartMessageRequest(profile, { source: "search" });
      void scheduleAddFriendProfileLookup({ immediate: true, force: true });
      return;
    }
    if (currentAction?.action === "privacy_blocked" || currentAction?.action === "blocked") {
      await requestAppAlert(currentAction?.reason || "This user isn't accepting messages.", {
        title: "Direct Messages",
        okText: "OK",
      });
    }
  });
  host.querySelector('[data-add-preview-open-profile]')?.addEventListener("click", async () => {
    await openUserCardModal(id, profile, {
      anchorEl: host.querySelector(".addFriendPreviewCard") || host,
      presentation: "overlay",
      layout: "preview",
      kind: "directory",
    });
  });
}

async function runAddFriendProfileLookup(queryInput, { force = false } = {}) {
  const trace = getRelationshipCurrentTrace();
  const query = String(queryInput || "").trim();
  if (!query) {
    renderAddFriendPreview(null, { query: "", loading: false });
    return;
  }

  const token = ++addFriendLookupToken;
  renderAddFriendPreview(null, { query, loading: true });
  const profile = await relationshipTraceMeasureAsync(trace, "runAddFriendProfileLookup", async () => (
    fetchProfileByUsername(query, { includeBio: true, force }).catch(() => null)
  ), {
    query,
    force: !!force,
  });
  if (token !== addFriendLookupToken) return;
  renderAddFriendPreview(profile, { query, loading: false });
}

function scheduleAddFriendProfileLookup({ immediate = false, force = false } = {}) {
  const trace = getRelationshipCurrentTrace();
  const input = document.getElementById("addUsername");
  const query = String(input?.value || "").trim();
  if (addFriendLookupTimer) {
    clearTimeout(addFriendLookupTimer);
    addFriendLookupTimer = 0;
  }
  if (!query) {
    addFriendLookupToken += 1;
    renderAddFriendPreview(null, { query: "", loading: false });
    return;
  }
  if (immediate) {
    relationshipTraceLog(trace, "scheduleAddFriendProfileLookup:immediate", { query, force: !!force });
    void runAddFriendProfileLookup(query, { force });
    return;
  }
  relationshipTraceLog(trace, "scheduleAddFriendProfileLookup:debounced", { query, delayMs: 170, force: !!force });
  addFriendLookupTimer = setTimeout(() => {
    addFriendLookupTimer = 0;
    void runAddFriendProfileLookup(query, { force });
  }, 170);
}

function renderPending({ skipWidgets = false, skipAddFriendLookup = false } = {}) {
  const trace = getRelationshipCurrentTrace();
  const traceLabel = relationshipTracePhaseStart(trace, "renderPending", {
    incoming: Array.isArray(state.incoming) ? state.incoming.length : 0,
    outgoing: Array.isArray(state.outgoing) ? state.outgoing.length : 0,
    messageIncoming: Array.isArray(state.messageIncoming) ? state.messageIncoming.length : 0,
    messageOutgoing: Array.isArray(state.messageOutgoing) ? state.messageOutgoing.length : 0,
    skipWidgets: !!skipWidgets,
    skipAddFriendLookup: !!skipAddFriendLookup,
  });
  try {
    const incomingRows = [
      ...(state.incoming || []).map((r) => ({
        row: r,
        type: "friend",
        createdAt: String(r?.created_at || "").trim(),
      })),
      ...(state.messageIncoming || []).map((r) => ({
        row: r,
        type: "message",
        createdAt: String(r?.created_at || "").trim(),
      })),
    ].sort((a, b) => (Date.parse(b.createdAt) || 0) - (Date.parse(a.createdAt) || 0));

    const outgoingRows = [
      ...(state.outgoing || []).map((r) => ({
        row: r,
        type: "friend",
        createdAt: String(r?.created_at || "").trim(),
      })),
      ...(state.messageOutgoing || []).map((r) => ({
        row: r,
        type: "message",
        createdAt: String(r?.created_at || "").trim(),
      })),
    ].sort((a, b) => (Date.parse(b.createdAt) || 0) - (Date.parse(a.createdAt) || 0));

    $("incomingList").innerHTML = incomingRows.map(({ row: r, type }) => rowUser(
      r,
      `
        <span class="pendingReqKind">${type === "message" ? t("pending.type.message", "Message") : t("pending.type.friendship", "Friend Request")}</span>
        ${type === "message" && getMessageRequestPreviewText(r) ? `<span class="pendingReqPreview">${esc(getMessageRequestPreviewText(r))}</span>` : ""}
        ${type === "message" && getMessageRequestMutualInfoText(r) ? `<span class="pendingReqPreview pendingReqPreview--meta">${esc(getMessageRequestMutualInfoText(r))}</span>` : ""}
        <button class="smallBtn primary" ${type === "message" ? `data-msg-acc="${escAttr(r.request_id)}"` : `data-acc="${escAttr(r.request_id)}"`}>${type === "message" ? "Accept" : "Aceitar"}</button>
        <button class="smallBtn" ${type === "message" ? `data-msg-rej="${escAttr(r.request_id)}"` : `data-rej="${escAttr(r.request_id)}"`}>${type === "message" ? "Ignore" : "Rejeitar"}</button>
        ${type === "message" ? `<button class="smallBtn danger" data-msg-block="${escAttr(r.request_id)}">Block</button>` : ""}
      `,
      getFriendRequestPeerUserId(r),
      {
        clickable: !!getFriendRequestPeerUserId(r),
        attrs: [
          `data-pending-profile-id="${escAttr(getFriendRequestPeerUserId(r))}"`,
          `data-pending-profile-username="${escAttr(r?.username || "")}"`,
          `data-pending-profile-display="${escAttr(r?.display_name || r?.username || "")}"`,
          `data-pending-profile-avatar="${escAttr(r?.avatar_url || "")}"`,
        ].join(" "),
      }
    )).join("") || `<div class="hint">Nenhum pedido.</div>`;

    $("outgoingList").innerHTML = outgoingRows.map(({ row: r, type }) => rowUser(
      r,
      `
        <span class="pendingReqKind">${type === "message" ? t("pending.type.message", "Message") : t("pending.type.friendship", "Friend Request")}</span>
        ${type === "message" && getMessageRequestPreviewText(r) ? `<span class="pendingReqPreview">${esc(getMessageRequestPreviewText(r))}</span>` : ""}
        <button class="smallBtn" ${type === "message" ? `data-msg-cancel="${escAttr(r.request_id)}"` : `data-cancel="${escAttr(r.request_id)}"`}>Cancelar</button>
      `,
      getFriendRequestPeerUserId(r),
      {
        clickable: !!getFriendRequestPeerUserId(r),
        attrs: [
          `data-pending-profile-id="${escAttr(getFriendRequestPeerUserId(r))}"`,
          `data-pending-profile-username="${escAttr(r?.username || "")}"`,
          `data-pending-profile-display="${escAttr(r?.display_name || r?.username || "")}"`,
          `data-pending-profile-avatar="${escAttr(r?.avatar_url || "")}"`,
        ].join(" "),
      }
    )).join("") || `<div class="hint">Nada pendente.</div>`;

    const pendingCount = state.incoming.length + state.outgoing.length + state.messageIncoming.length + state.messageOutgoing.length;
    const badge = $("pendingBadge");
    badge.style.display = pendingCount ? "inline-flex" : "none";
    badge.textContent = String(pendingCount);

    document.querySelectorAll("[data-acc]").forEach(b => b.addEventListener("click", () => acceptReq(b.dataset.acc)));
    document.querySelectorAll("[data-rej]").forEach(b => b.addEventListener("click", () => rejectReq(b.dataset.rej)));
    document.querySelectorAll("[data-cancel]").forEach(b => b.addEventListener("click", () => cancelReq(b.dataset.cancel)));
    document.querySelectorAll("[data-msg-acc]").forEach((b) => b.addEventListener("click", async () => {
      const result = await acceptMessageReq(b.dataset.msgAcc);
      if (result?.ok && result?.conversationId) {
        await showDm(result.conversationId, { autoAnswerIfPending: true });
      }
    }));
    document.querySelectorAll("[data-msg-rej]").forEach((b) => b.addEventListener("click", () => rejectMessageReq(b.dataset.msgRej)));
    document.querySelectorAll("[data-msg-block]").forEach((b) => b.addEventListener("click", () => blockMessageReq(b.dataset.msgBlock)));
    document.querySelectorAll("[data-msg-cancel]").forEach((b) => b.addEventListener("click", () => cancelMessageReq(b.dataset.msgCancel)));
    document.querySelectorAll("[data-pending-profile-id]").forEach((row) => {
      const openPendingProfile = async () => {
        const uid = normId(row.getAttribute("data-pending-profile-id") || "");
        if (!uid) return;
        await openUserCardModal(uid, {
          username: String(row.getAttribute("data-pending-profile-username") || "").trim(),
          display_name: String(row.getAttribute("data-pending-profile-display") || "").trim(),
          avatar_url: String(row.getAttribute("data-pending-profile-avatar") || "").trim(),
        }, {
          anchorEl: row,
          presentation: "overlay",
          layout: "preview",
          kind: "directory",
        });
      };

      row.addEventListener("click", async (e) => {
        const target = eventTargetElement(e);
        if (target?.closest("button,a,input,textarea,select,label")) return;
        await openPendingProfile();
      });

      row.addEventListener("keydown", async (e) => {
        if (e.key !== "Enter" && e.key !== " ") return;
        e.preventDefault();
        await openPendingProfile();
      });
    });
    if (!skipAddFriendLookup) {
      relationshipTraceMeasureSync(trace, "renderPending:scheduleAddFriendProfileLookup", () => {
        scheduleAddFriendProfileLookup({ immediate: false, force: false });
      });
    }
    if (!skipWidgets) {
      relationshipTraceMeasureSync(trace, "renderPending:renderWidgets", () => {
        renderWidgets();
      });
    }
  } finally {
    relationshipTracePhaseEnd(trace, traceLabel);
  }
}

function prunePartyPickerSelection() {
  const friendIdSet = new Set((state.friends || []).map((f) => normId(f?.other_user_id || f?.id)).filter(Boolean));
  for (const id of Array.from(partyPickerSelectedIds)) {
    if (!friendIdSet.has(id)) partyPickerSelectedIds.delete(id);
  }
}

function renderPartyPicker() {
  const listEl = document.getElementById("partyFriendPicker");
  const metaEl = document.getElementById("partySelectionMeta");
  const createGroupBtn = document.getElementById("btnCreateGroupDm");
  const createServerBtn = document.getElementById("btnCreateServer");
  if (!listEl || !metaEl) return;

  prunePartyPickerSelection();

  const query = String(partyPickerFilter || "").trim().toLowerCase();
  const friends = (state.friends || [])
    .filter((f) => {
      const uid = normId(f?.other_user_id || f?.id);
      if (!uid) return false;
      const username = String(f?.username || "").toLowerCase();
      const displayName = String(f?.display_name || "").toLowerCase();
      if (!query) return true;
      return username.includes(query) || displayName.includes(query);
    })
    .sort((a, b) => {
      const an = String(a?.display_name || a?.username || "").toLowerCase();
      const bn = String(b?.display_name || b?.username || "").toLowerCase();
      return an.localeCompare(bn);
    });

  if (!friends.length) {
    listEl.innerHTML = `<div class="hint">Sem amigos para adicionar.</div>`;
  } else {
    listEl.innerHTML = friends.map((f) => {
      const uid = normId(f?.other_user_id || f?.id);
      const selected = partyPickerSelectedIds.has(uid);
      const avatar = f?.avatar_url
        ? buildAvatarMediaHtml(f.avatar_url, { userId: uid, alt: f?.display_name || f?.username || "avatar", deferAnimatedStorage: true })
        : `<span class="partyPickAvatarFallback">${esc(String(f?.display_name || f?.username || "?").trim().charAt(0).toUpperCase() || "?")}</span>`;
      return `
        <button
          class="partyPickItem${selected ? " is-on" : ""}"
          type="button"
          data-party-friend-id="${escAttr(uid)}"
          aria-pressed="${selected ? "true" : "false"}"
        >
          <span class="partyPickAvatar">${avatar}</span>
          <span class="partyPickMain">
            <span class="partyPickName">${esc(f?.display_name || f?.username || "user")}</span>
            <span class="partyPickHandle">@${esc(f?.username || "")}</span>
          </span>
          <span class="partyPickCheck" aria-hidden="true">${selected ? "?" : "+"}</span>
        </button>
      `;
    }).join("");
  }

  const selectedCount = partyPickerSelectedIds.size;
  const totalForServer = selectedCount + 1; // inclui o proprio user
  const totalForGroup = selectedCount + 1; // inclui o proprio user
  const hasGroupButton = !!createGroupBtn;
  if (hasGroupButton) {
    const groupStatus = totalForGroup > GROUP_DM_MAX_MEMBERS
      ? `Selecionados: ${totalForGroup}/${GROUP_DM_MAX_MEMBERS} (limite excedido)`
      : `Selecionados: ${totalForGroup}/${GROUP_DM_MAX_MEMBERS} (inclui-te)`;
    metaEl.textContent = groupStatus;
    metaEl.dataset.tone = totalForGroup > GROUP_DM_MAX_MEMBERS ? "warn" : "ok";
  } else {
    const serverStatus = totalForServer > SERVER_MAX_MEMBERS
      ? `Selecionados para server: ${totalForServer}/${SERVER_MAX_MEMBERS} (limite excedido)`
      : `Selecionados para server: ${totalForServer}/${SERVER_MAX_MEMBERS} (inclui-te)`;
    metaEl.textContent = serverStatus;
    metaEl.dataset.tone = totalForServer > SERVER_MAX_MEMBERS ? "warn" : "ok";
  }

  if (createGroupBtn) {
    createGroupBtn.disabled = selectedCount < 2 || totalForGroup > GROUP_DM_MAX_MEMBERS;
    createGroupBtn.title = groupDmRpcAvailable
      ? "Criar Group DM"
      : "Aplica o patch SQL de groups/servers para ativar";
  }
  if (createServerBtn) {
    createServerBtn.disabled = !serverRpcAvailable || (selectedCount + 1) > SERVER_MAX_MEMBERS;
    createServerBtn.title = serverRpcAvailable
      ? "Criar Server"
      : "Aplica o patch SQL de groups/servers para ativar";
  }
}

function bindPartyPickerOnce() {
  if (partyPickerBound) return;
  partyPickerBound = true;

  const search = document.getElementById("partyFriendSearch");
  const listEl = document.getElementById("partyFriendPicker");
  const createGroupBtn = document.getElementById("btnCreateGroupDm");
  const createServerBtn = document.getElementById("btnCreateServer");

  search?.addEventListener("input", () => {
    partyPickerFilter = String(search.value || "").trim();
    renderPartyPicker();
  });

  listEl?.addEventListener("click", (e) => {
    const target = eventTargetElement(e);
    const btn = target?.closest("[data-party-friend-id]");
    if (!btn) return;
    const uid = normId(btn.getAttribute("data-party-friend-id"));
    if (!uid) return;
    if (partyPickerSelectedIds.has(uid)) partyPickerSelectedIds.delete(uid);
    else partyPickerSelectedIds.add(uid);
    renderPartyPicker();
  });

  createGroupBtn?.addEventListener("click", async () => {
    const friendIds = Array.from(partyPickerSelectedIds).filter(Boolean);
    if (friendIds.length < 2) {
      alert("Escolhe pelo menos 2 amigos para criar um Group DM.");
      return;
    }
    if (friendIds.length + 1 > GROUP_DM_MAX_MEMBERS) {
      alert(`Group DM suporta no maximo ${GROUP_DM_MAX_MEMBERS} pessoas (inclui-te).`);
      return;
    }

    const nameInput = document.getElementById("partyName");
    const rawName = String(nameInput?.value || "").trim();
    const groupName = rawName ? normalizeConversationLabel(rawName, "Group DM") : getDefaultGroupDmName();

    const { data, error } = await supabase.rpc("create_group_dm", {
      p_member_ids: friendIds,
      p_name: groupName,
    });
    if (error) {
      if (isMissingRpcError(error)) {
        groupDmRpcAvailable = false;
        alert("A funcao create_group_dm ainda nao existe no SQL.");
      } else {
        alert(`Erro ao criar Group DM: ${error.message}`);
      }
      renderPartyPicker();
      return;
    }

    const conversationId = normId(data);
    if (!conversationId) {
      alert("Group DM criado, mas nao consegui abrir automaticamente.");
      invalidateGroupAndServerCollectionsCache();
      await refresh();
      return;
    }

    partyPickerSelectedIds.clear();
    if (nameInput) nameInput.value = "";
    try {
      invalidateGroupAndServerCollectionsCache();
      await refresh();
    } catch (e) {
      console.warn("refresh failed after create_group_dm", e);
      await loadDmList().catch(() => {});
      renderFriends({ skipPresenceRefresh: true, skipGroupsRail: true });
      renderPending({ skipWidgets: true, skipAddFriendLookup: true });
      renderGroupsRail();
      renderWidgets();
      updatePresenceRender();
    }
    const meta = getConversationMeta(conversationId) || {
      kind: "group",
      isGroup: true,
      displayName: groupName || "Group DM",
    };
    await openConversationById(conversationId, meta);
  });

  createServerBtn?.addEventListener("click", async () => {
    if (!serverRpcAvailable) {
      alert("A funcao create_server ainda nao existe. Aplica o patch SQL de servers.");
      return;
    }

    const nameInput = document.getElementById("partyName");
    const rawName = String(nameInput?.value || "").trim();
    if (!rawName) {
      alert("Escreve um nome para o server.");
      return;
    }

    const friendIds = Array.from(partyPickerSelectedIds).filter(Boolean);
    if (friendIds.length + 1 > SERVER_MAX_MEMBERS) {
      alert(`Server suporta no maximo ${SERVER_MAX_MEMBERS} membros no setup inicial.`);
      return;
    }

    if (!(await ensureCanAddServerOrShowLimit("create_server_legacy_party"))) return;

    const { data, error } = await supabase.rpc("create_server", {
      p_name: normalizeConversationLabel(rawName, "Server"),
      p_member_ids: friendIds,
    });
    if (error) {
      if (isMissingRpcError(error)) serverRpcAvailable = false;
      alert(`Erro ao criar server: ${error.message}`);
      renderPartyPicker();
      return;
    }

    const row = Array.isArray(data) ? data[0] : data;
    let conversationId = normId(row?.default_conversation_id || row?.conversation_id);
    const serverId = normId(row?.server_id);

    if (serverId) {
      const bootstrapRes = await ensureDefaultServerStructureForServer(serverId, {
        defaultConversationId: conversationId,
      });
      if (bootstrapRes?.error) {
        console.warn("default server structure bootstrap failed", bootstrapRes.error);
      } else {
        conversationId = normId(bootstrapRes?.textConversationId || conversationId);
      }
    }

    partyPickerSelectedIds.clear();
    if (nameInput) nameInput.value = "";
    invalidateGroupAndServerCollectionsCache();
    await refresh();

    if (!conversationId) {
      alert("Server criado. Falta abrir o canal default.");
      return;
    }

    const meta = getConversationMeta(conversationId) || {
      kind: "server",
      isGroup: true,
      displayName: normalizeConversationLabel(rawName, "Server"),
      serverId,
      serverName: normalizeConversationLabel(rawName, "Server"),
    };
    await openConversationById(conversationId, meta);
  });
}

