function normalizeDmPrivacySettings(input = {}) {
  const src = input && typeof input === "object" ? input : {};
  const who = DM_PRIVACY_WHO_VALUES.includes(String(src.who_can_message_me || "").trim().toLowerCase())
    ? String(src.who_can_message_me || "").trim().toLowerCase()
    : DM_PRIVACY_DEFAULT_SETTINGS.who_can_message_me;
  const nonFriend = DM_PRIVACY_NON_FRIEND_VALUES.includes(String(src.non_friend_messages || "").trim().toLowerCase())
    ? String(src.non_friend_messages || "").trim().toLowerCase()
    : DM_PRIVACY_DEFAULT_SETTINGS.non_friend_messages;
  return {
    who_can_message_me: who,
    non_friend_messages: nonFriend,
    allow_server_member_requests: typeof src.allow_server_member_requests === "boolean"
      ? src.allow_server_member_requests
      : DM_PRIVACY_DEFAULT_SETTINGS.allow_server_member_requests,
    allow_unknown_requests: typeof src.allow_unknown_requests === "boolean"
      ? src.allow_unknown_requests
      : DM_PRIVACY_DEFAULT_SETTINGS.allow_unknown_requests,
    spam_filter_enabled: typeof src.spam_filter_enabled === "boolean"
      ? src.spam_filter_enabled
      : DM_PRIVACY_DEFAULT_SETTINGS.spam_filter_enabled,
  };
}

function getDmPrivacySettingsSnapshot() {
  return normalizeDmPrivacySettings(state.dmPrivacySettings || DM_PRIVACY_DEFAULT_SETTINGS);
}

function setDmPrivacySettingsStatus(label = "", status = "ready") {
  const el = document.getElementById("settingsDmPrivacyStatus");
  if (!el) return;
  el.textContent = String(label || "").trim() || "Ready";
  el.dataset.status = String(status || "ready").trim().toLowerCase() || "ready";
}

function applyDmPrivacySettingsToControls(settingsInput = null) {
  const settings = normalizeDmPrivacySettings(settingsInput || state.dmPrivacySettings || DM_PRIVACY_DEFAULT_SETTINGS);
  const who = document.getElementById("settingsDmWhoCanMessageMe");
  const nonFriend = document.getElementById("settingsDmNonFriendMessages");
  const allowServer = document.getElementById("settingsDmAllowServerMemberRequests");
  const spam = document.getElementById("settingsDmSpamFilterEnabled");
  if (who) who.value = settings.who_can_message_me;
  if (nonFriend) nonFriend.value = settings.non_friend_messages;
  if (allowServer) allowServer.checked = !!settings.allow_server_member_requests;
  if (spam) spam.checked = !!settings.spam_filter_enabled;
}

function readDmPrivacySettingsFromControls() {
  const current = getDmPrivacySettingsSnapshot();
  const who = document.getElementById("settingsDmWhoCanMessageMe");
  const nonFriend = document.getElementById("settingsDmNonFriendMessages");
  const allowServer = document.getElementById("settingsDmAllowServerMemberRequests");
  const spam = document.getElementById("settingsDmSpamFilterEnabled");
  return normalizeDmPrivacySettings({
    ...current,
    who_can_message_me: who?.value || current.who_can_message_me,
    non_friend_messages: nonFriend?.value || current.non_friend_messages,
    allow_server_member_requests: !!allowServer?.checked,
    spam_filter_enabled: !!spam?.checked,
  });
}

async function fetchDmPrivacySettings({ force = false } = {}) {
  if (!force && dmPrivacySettingsLoaded && state.dmPrivacySettings) return getDmPrivacySettingsSnapshot();
  if (!state.user?.id) {
    state.dmPrivacySettings = normalizeDmPrivacySettings(DM_PRIVACY_DEFAULT_SETTINGS);
    dmPrivacySettingsLoaded = true;
    return state.dmPrivacySettings;
  }
  const res = await rpcWithTimeout("get_dm_privacy_settings");
  if (res?.error) {
    if (isMissingRpcError(res.error)) {
      state.dmPrivacySettings = normalizeDmPrivacySettings(DM_PRIVACY_DEFAULT_SETTINGS);
      dmPrivacySettingsLoaded = true;
      return state.dmPrivacySettings;
    }
    throw res.error;
  }
  const row = Array.isArray(res?.data) ? (res.data[0] || null) : (res?.data || null);
  state.dmPrivacySettings = normalizeDmPrivacySettings(row || DM_PRIVACY_DEFAULT_SETTINGS);
  dmPrivacySettingsLoaded = true;
  return state.dmPrivacySettings;
}

async function saveDmPrivacySettingsFromControls() {
  if (dmPrivacySettingsSaveInFlight) return;
  if (!guardAltaraNetworkAction("Direct Messages")) return;
  const payload = readDmPrivacySettingsFromControls();
  const btn = document.getElementById("btnSettingsDmPrivacySave");
  dmPrivacySettingsSaveInFlight = true;
  if (btn) btn.disabled = true;
  setDmPrivacySettingsStatus("Saving", "loading");
  try {
    let res = await rpcWithTimeout("update_dm_privacy_settings", { payload });
    if (res?.error && isMissingRpcError(res.error)) {
      res = await rpcWithTimeout("update_dm_privacy_settings", { p_payload: payload });
    }
    if (res?.error) throw res.error;
    const row = Array.isArray(res?.data) ? (res.data[0] || null) : (res?.data || payload);
    state.dmPrivacySettings = normalizeDmPrivacySettings(row || payload);
    dmPrivacySettingsLoaded = true;
    dmCanMessageCacheByUserId.clear();
    applyDmPrivacySettingsToControls(state.dmPrivacySettings);
    setDmPrivacySettingsStatus("Saved", "ready");
  } catch (error) {
    setDmPrivacySettingsStatus("Not saved", "error");
    await requestAppAlert(error?.message || String(error || "Could not save Direct Message settings."), {
      title: "Direct Messages",
      okText: "OK",
    });
  } finally {
    dmPrivacySettingsSaveInFlight = false;
    if (btn) btn.disabled = false;
  }
}

function bindDmPrivacySettingsUiOnce() {
  const card = document.getElementById("settingsDirectMessagesCard");
  if (!card || card.dataset.dmPrivacyBound === "1") return;
  card.dataset.dmPrivacyBound = "1";
  card.querySelector("#btnSettingsDmPrivacySave")?.addEventListener("click", () => {
    void saveDmPrivacySettingsFromControls();
  });
  card.querySelectorAll("select,input").forEach((control) => {
    control.addEventListener("change", () => setDmPrivacySettingsStatus("Unsaved", "pending"));
  });
}

async function renderDmPrivacySettingsUi({ force = false } = {}) {
  bindDmPrivacySettingsUiOnce();
  const card = document.getElementById("settingsDirectMessagesCard");
  if (!card) return;
  if (!dmPrivacySettingsLoaded || force) setDmPrivacySettingsStatus("Loading", "loading");
  try {
    const settings = await fetchDmPrivacySettings({ force });
    applyDmPrivacySettingsToControls(settings);
    setDmPrivacySettingsStatus("Ready", "ready");
  } catch (error) {
    applyDmPrivacySettingsToControls(DM_PRIVACY_DEFAULT_SETTINGS);
    setDmPrivacySettingsStatus("Needs SQL", "error");
  }
}

function buildLocalCanMessageUserResult(targetUserId = "") {
  const uid = normId(targetUserId || "");
  const selfId = normId(state.user?.id || "");
  const isFriend = !!getFriendRowByUserId(uid);
  const isContact = !!getMessageContactRowByUserId(uid);
  const isBlocked = !!isUserBlockedLocally(uid);
  if (!uid || uid === selfId) {
    return { allowed: false, route: "blocked", reason: "You can't message this user.", mutualServerCount: 0, isFriend, isBlocked: true, localOnly: true };
  }
  if (isBlocked) {
    return { allowed: false, route: "blocked", reason: "You can't message this user.", mutualServerCount: 0, isFriend, isBlocked: true, localOnly: true };
  }
  if (isFriend || isContact) {
    return { allowed: true, route: "direct", reason: "", mutualServerCount: 0, isFriend, isContact, isBlocked: false, localOnly: true };
  }
  return {
    allowed: true,
    route: "request",
    reason: "They'll need to accept before you can chat.",
    mutualServerCount: 0,
    isFriend: false,
    isBlocked: false,
    localOnly: true,
  };
}

function normalizeCanMessageUserResult(data = null, targetUserId = "") {
  const local = buildLocalCanMessageUserResult(targetUserId);
  const row = Array.isArray(data) ? (data[0] || null) : (data || null);
  if (!row || typeof row !== "object") return local;
  const rawRoute = String(row.route || row.status || "").trim().toLowerCase();
  const route = rawRoute === "direct" || rawRoute === "request" || rawRoute === "blocked" ? rawRoute : local.route;
  const allowed = typeof row.allowed === "boolean" ? row.allowed : route !== "blocked";
  const mutualServerCount = Number(row.mutualServerCount ?? row.mutual_server_count ?? row.mutual_server_count_safe ?? 0) || 0;
  return {
    allowed: !!allowed && route !== "blocked",
    route,
    reason: String(row.reason || (route === "request" ? "They'll need to accept before you can chat." : "")).trim(),
    mutualServerCount,
    isFriend: row.isFriend === true || row.is_friend === true || local.isFriend === true,
    isContact: row.isContact === true || row.is_contact === true || local.isContact === true,
    isBlocked: row.isBlocked === true || row.is_blocked === true || route === "blocked",
    localOnly: false,
  };
}

async function canMessageUserRpc(targetUserId, { force = false } = {}) {
  const uid = normId(targetUserId || "");
  const cached = dmCanMessageCacheByUserId.get(uid);
  if (!force && cached && Date.now() - Number(cached.fetchedAt || 0) < 5 * 60 * 1000) return cached.result;
  const local = buildLocalCanMessageUserResult(uid);
  if (!uid || !state.user?.id) return local;
  const payloads = [{ target_user_id: uid }, { p_target_user_id: uid }];
  let lastMissingErr = null;
  let lastRpcErr = null;
  for (const payload of payloads) {
    const res = await rpcWithTimeout("can_message_user", payload);
    if (!res?.error) {
      const result = normalizeCanMessageUserResult(res?.data, uid);
      dmCanMessageCacheByUserId.set(uid, { result, fetchedAt: Date.now() });
      return result;
    }
    if (!isMissingRpcError(res.error)) {
      const result = { ...local, error: res.error };
      dmCanMessageCacheByUserId.set(uid, { result, fetchedAt: Date.now() });
      return result;
    }
    lastMissingErr = res.error;
  }
  const result = { ...local, missingSql: true, error: lastMissingErr || null };
  dmCanMessageCacheByUserId.set(uid, { result, fetchedAt: Date.now() });
  return result;
}

function getCanMessageUserCachedOrLocal(targetUserId = "") {
  const uid = normId(targetUserId || "");
  const cached = dmCanMessageCacheByUserId.get(uid);
  if (cached?.result) return cached.result;
  return buildLocalCanMessageUserResult(uid);
}

function scheduleCanMessageUserRefresh(targetUserId = "") {
  const uid = normId(targetUserId || "");
  if (!uid || dmCanMessageInFlightByUserId.has(uid)) return;
  const cached = dmCanMessageCacheByUserId.get(uid);
  if (cached && Date.now() - Number(cached.fetchedAt || 0) < 5 * 60 * 1000) return;
  dmCanMessageInFlightByUserId.add(uid);
  const previous = cached?.result ? JSON.stringify(cached.result) : "";
  void canMessageUserRpc(uid, { force: true }).then((result) => {
    const next = JSON.stringify(result || {});
    if (previous !== next) {
      if (normId(userCardCurrentUserId || "") === uid) refreshOpenUserCard();
      refreshAddFriendPreviewFromLocalState({ userId: uid });
    }
  }).catch(() => {}).finally(() => {
    dmCanMessageInFlightByUserId.delete(uid);
  });
}

function getMessageRequestPreviewText(row = {}) {
  const metadata = row?.metadata && typeof row.metadata === "object" ? row.metadata : {};
  const text = String(
    row?.first_message_preview
    || row?.message_preview
    || row?.preview
    || metadata.first_message_preview
    || metadata.preview
    || ""
  ).replace(/\s+/g, " ").trim();
  return text.length > 160 ? text.slice(0, 157) + "..." : text;
}

function getMessageRequestMutualInfoText(row = {}) {
  const metadata = row?.metadata && typeof row.metadata === "object" ? row.metadata : {};
  const serverCount = Number(row?.mutual_server_count ?? row?.mutualServerCount ?? metadata.mutual_server_count ?? 0) || 0;
  const friendCount = Number(row?.mutual_friend_count ?? row?.mutualFriendCount ?? metadata.mutual_friend_count ?? 0) || 0;
  const serverNames = Array.isArray(row?.mutual_server_names)
    ? row.mutual_server_names
    : (Array.isArray(metadata.mutual_server_names) ? metadata.mutual_server_names : []);
  const parts = [];
  if (serverCount > 0) {
    const label = serverCount === 1 ? "1 mutual server" : String(serverCount) + " mutual servers";
    const names = serverNames.slice(0, 2).map((name) => String(name || "").trim()).filter(Boolean).join(", ");
    parts.push(names ? (label + ": " + names) : label);
  }
  if (friendCount > 0) parts.push(friendCount === 1 ? "1 mutual friend" : String(friendCount) + " mutual friends");
  return parts.join(" / ");
}

function isMessageRequestsDebugEnabled() {
  try {
    return typeof localStorage !== "undefined"
      && String(localStorage.getItem(MESSAGE_REQUESTS_DEBUG_STORAGE_KEY) || "").trim() === "1";
  } catch (_) {
    return false;
  }
}

function logMessageRequestsDebug(event = "", details = null) {
  if (!isMessageRequestsDebugEnabled()) return;
  const label = String(event || "").trim() || "event";
  if (typeof console === "undefined" || typeof console.info !== "function") return;
  if (details && typeof details === "object") {
    console.info("[MessageRequests] " + label, details);
    return;
  }
  console.info("[MessageRequests] " + label);
}

function getMessageRequestNestedPeer(row = {}, { direction = "incoming" } = {}) {
  const safeDirection = String(direction || "incoming").trim().toLowerCase() === "outgoing" ? "outgoing" : "incoming";
  const candidates = safeDirection === "outgoing"
    ? [
      row?.recipient_profile,
      row?.recipient,
      row?.to_profile,
      row?.to_user,
      row?.target_profile,
      row?.target_user,
      row?.other_profile,
      row?.other_user,
      row?.profile,
      row?.user,
    ]
    : [
      row?.sender_profile,
      row?.sender,
      row?.from_profile,
      row?.from_user,
      row?.requester_profile,
      row?.requester,
      row?.other_profile,
      row?.other_user,
      row?.profile,
      row?.user,
    ];
  return candidates.find((candidate) => candidate && typeof candidate === "object") || null;
}

function getIncomingMessageRequestPeerId(row = {}) {
  const peer = getMessageRequestNestedPeer(row, { direction: "incoming" });
  return normId(
    row?.from_user_id
    || row?.sender_id
    || row?.sender_user_id
    || row?.requester_id
    || row?.from_profile_id
    || row?.sender_profile_id
    || row?.other_user_id
    || row?.user_id
    || row?.profile_id
    || peer?.id
    || peer?.user_id
    || peer?.profile_id
    || ""
  );
}

function getOutgoingMessageRequestPeerId(row = {}) {
  const peer = getMessageRequestNestedPeer(row, { direction: "outgoing" });
  return normId(
    row?.to_user_id
    || row?.recipient_id
    || row?.recipient_user_id
    || row?.target_user_id
    || row?.to_profile_id
    || row?.recipient_profile_id
    || row?.other_user_id
    || row?.user_id
    || row?.profile_id
    || peer?.id
    || peer?.user_id
    || peer?.profile_id
    || ""
  );
}

function normalizeMessageRequestRow(row = {}, { direction = "incoming" } = {}) {
  const safeDirection = String(direction || "incoming").trim().toLowerCase() === "outgoing" ? "outgoing" : "incoming";
  const peer = getMessageRequestNestedPeer(row, { direction: safeDirection }) || {};
  const requestId = String(row?.request_id || row?.id || "").trim();
  const peerId = safeDirection === "outgoing"
    ? getOutgoingMessageRequestPeerId(row)
    : getIncomingMessageRequestPeerId(row);
  const next = {
    ...(row || {}),
    ...(requestId ? { request_id: requestId } : {}),
    ...(safeDirection === "outgoing" && peerId ? { to_user_id: peerId } : {}),
    ...(safeDirection === "incoming" && peerId ? { from_user_id: peerId } : {}),
    username: String(row?.username || peer?.username || peer?.handle || "").trim(),
    display_name: String(row?.display_name || row?.displayName || peer?.display_name || peer?.displayName || peer?.name || row?.username || peer?.username || "Message request").trim(),
    avatar_url: row?.avatar_url ?? row?.avatarUrl ?? peer?.avatar_url ?? peer?.avatarUrl ?? null,
  };
  if (!String(next.status || "").trim()) next.status = "pending";
  return hydrateRelationshipRowsFromCache([next])[0] || next;
}

function normalizeMessageRequestRows(rows = [], { direction = "incoming" } = {}) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => normalizeMessageRequestRow(row, { direction }))
    .filter((row) => String(row?.request_id || row?.id || "").trim());
}

function syncMessageRequestStateAliases() {
  state.incomingMessageRequests = Array.isArray(state.messageIncoming) ? state.messageIncoming : [];
  state.outgoingMessageRequests = Array.isArray(state.messageOutgoing) ? state.messageOutgoing : [];
}

function setMessageRequestRows({ incoming = null, outgoing = null } = {}) {
  if (incoming !== null) {
    state.messageIncoming = normalizeMessageRequestRows(incoming, { direction: "incoming" });
  }
  if (outgoing !== null) {
    state.messageOutgoing = normalizeMessageRequestRows(outgoing, { direction: "outgoing" });
  }
  syncMessageRequestStateAliases();
  return {
    incoming: state.messageIncoming || [],
    outgoing: state.messageOutgoing || [],
  };
}

function getIncomingMessageRequestRows() {
  const alias = Array.isArray(state.incomingMessageRequests) ? state.incomingMessageRequests : null;
  const legacy = Array.isArray(state.messageIncoming) ? state.messageIncoming : [];
  return alias || legacy;
}

function getOutgoingMessageRequestRows() {
  const alias = Array.isArray(state.outgoingMessageRequests) ? state.outgoingMessageRequests : null;
  const legacy = Array.isArray(state.messageOutgoing) ? state.messageOutgoing : [];
  return alias || legacy;
}


async function startDmOrMessageRequestRpc(targetUserId, firstMessage, source = "profile") {
  const uid = normId(targetUserId || "");
  const content = String(firstMessage || "").trim();
  if (!uid || !content) return { ok: false, error: { message: "Missing message target or first message." } };
  const safeSource = String(source || "profile").trim().toLowerCase() || "profile";
  const payloads = [
    { target_user_id: uid, first_message: content, source: safeSource },
    { p_target_user_id: uid, p_first_message: content, p_source: safeSource },
  ];
  let lastMissingErr = null;
  let lastRpcErr = null;
  for (const payload of payloads) {
    const res = await rpcWithTimeout("start_dm_or_request", payload);
    if (!res?.error) {
      const row = Array.isArray(res?.data) ? (res.data[0] || null) : (res?.data || null);
      const rawStatus = String(row?.status || row?.route || "").trim().toLowerCase();
      const status = rawStatus === "direct" || rawStatus === "accepted"
        ? "direct"
        : (rawStatus === "pending_request" || rawStatus === "request" || rawStatus === "pending" ? "pending_request" : rawStatus);
      return {
        ok: true,
        status: status || (row?.conversation_id ? "direct" : "pending_request"),
        requestId: String(row?.request_id || row?.id || "").trim(),
        conversationId: normId(row?.conversation_id || ""),
        row,
      };
    }
    if (!isMissingRpcError(res.error)) return { ok: false, error: res.error };
    lastMissingErr = res.error;
  }
  return { ok: false, missingSql: true, error: lastMissingErr || { message: "start_dm_or_request RPC is missing." } };
}

async function promptAndStartMessageRequest(profile = {}, { source = "profile" } = {}) {
  const uid = normId(profile?.id || profile?.other_user_id || profile?.userId || "");
  const username = String(profile?.username || "").trim();
  if (!uid && !username) return { ok: false, error: { message: "Missing user." } };
  const gate = uid ? await canMessageUserRpc(uid, { force: true }).catch(() => getCanMessageUserCachedOrLocal(uid)) : buildLocalCanMessageUserResult(uid);
  if (!gate?.allowed || gate.route === "blocked") {
    await requestAppAlert(gate?.reason || "This user isn't accepting messages.", {
      title: "Direct Messages",
      okText: "OK",
    });
    return { ok: false, blocked: true };
  }

  const displayName = String(profile?.display_name || profile?.displayName || username || "User").trim() || "User";
  const avatarUrl = profile?.avatar_url || profile?.avatarUrl || null;
  const isKnownDirect = gate.route === "direct" && (getFriendRowByUserId(uid) || getMessageContactRowByUserId(uid));
  if (isKnownDirect && username) {
    const conversationId = await startDmWith(username, displayName, avatarUrl, uid);
    return { ok: !!conversationId, status: "direct", conversationId };
  }

  if (!uid) {
    await requestAppAlert("Could not start this DM from this profile. Try opening the full profile first.", {
      title: "Direct Messages",
      okText: "OK",
    });
    return { ok: false, error: { message: "Missing user id." } };
  }

  unhideDmUser(uid, { rerender: false });

  const existingOutgoing = getOutgoingMessageRequestByUserId(uid);
  const existingOutgoingId = String(existingOutgoing?.request_id || existingOutgoing?.id || "").trim();
  const existingOutgoingStatus = String(existingOutgoing?.status || "pending").trim().toLowerCase();
  if (existingOutgoingId && (!existingOutgoingStatus || existingOutgoingStatus === "pending")) {
    renderRelationshipUiNow({ rerenderDmList: true, affectedUserId: uid, affectedUsername: username });
    openMessageRequestPreview(existingOutgoingId, { direction: "outgoing" });
    return { ok: true, status: "pending_request", requestId: existingOutgoingId };
  }

  const existingIncoming = getIncomingMessageRequestByUserId(uid);
  const existingIncomingId = String(existingIncoming?.request_id || existingIncoming?.id || "").trim();
  const existingIncomingStatus = String(existingIncoming?.status || "pending").trim().toLowerCase();
  if (existingIncomingId && (!existingIncomingStatus || existingIncomingStatus === "pending")) {
    renderRelationshipUiNow({ rerenderDmList: true, affectedUserId: uid, affectedUsername: username });
    openMessageRequestPreview(existingIncomingId, { direction: "incoming" });
    return { ok: true, status: "incoming_request", requestId: existingIncomingId };
  }

  const draftRow = upsertDraftMessageRequestRow({
    to_user_id: uid,
    username,
    display_name: displayName,
    avatar_url: avatarUrl,
    source: String(source || "profile").trim().toLowerCase() || "profile",
    created_at: new Date().toISOString(),
  });
  renderRelationshipUiNow({ rerenderDmList: true, affectedUserId: uid, affectedUsername: username });
  const draftId = String(draftRow?.draft_id || draftRow?.request_id || uid).trim();
  if (draftId) openDraftMessageRequest(draftId);
  return { ok: true, status: "draft", draftId, route: gate.route || "request" };
}

async function sendMessageRequest(username, { silent = false } = {}) {
  if (!guardAltaraNetworkAction("Message requests")) return { ok: false, error: { message: "Waiting for connection" }, conversationId: "" };
  const uname = String(username || "").trim();
  if (!uname) return { ok: false, error: { message: "username em falta" }, conversationId: "" };
  const trace = beginRelationshipActionTrace("send_message_request", { username: uname });

  const currentCardUserId = normId(userCardCurrentUserId || "");
  const currentCardMatches = currentCardUserId
    && String(userCardCurrentUsername || "").trim().toLowerCase() === uname.toLowerCase();
  const knownUserId = findKnownUserIdByUsername(uname) || (currentCardMatches ? currentCardUserId : "");
  const optimisticProfile = getOptimisticRelationshipProfile({ userId: knownUserId, username: uname });
  const snapshot = relationshipTraceMeasureSync(trace, "snapshotRelationshipState", () => snapshotRelationshipState());
  const tempReqId = `_opt_msg_${Date.now()}`;
  relationshipTraceMeasureSync(trace, "optimisticPatch", () => {
    state.messageOutgoing = [
      {
        request_id: tempReqId,
        to_user_id: normId(optimisticProfile?.id || ""),
        username: uname,
        display_name: optimisticProfile?.display_name || uname,
        avatar_url: optimisticProfile?.avatar_url || null,
        created_at: new Date().toISOString(),
        _optimistic: true,
      },
      ...(state.messageOutgoing || []),
    ];
    syncMessageRequestStateAliases();
  });
  renderRelationshipUiNow({
    rerenderPending: true,
    rerenderDmList: true,
    affectedUserId: normId(optimisticProfile?.id || ""),
    affectedUsername: uname,
  });
  relationshipTraceSchedulePaint(trace, "optimisticPaint");

  const res = await relationshipTraceMeasureAsync(trace, "rpc:send_message_request", () => (
    rpcWithTimeout("send_message_request", { target_username: uname })
  ));
  if (res?.error) {
    restoreRelationshipState(snapshot, {
      rerenderPending: true,
      rerenderDmList: true,
      affectedUserId: normId(optimisticProfile?.id || ""),
      affectedUsername: uname,
    });
    relationshipTraceSchedulePaint(trace, "rollbackPaint");
    endRelationshipTrace(trace, "rpc_error", { message: String(res?.error?.message || res?.error || "") });
    if (!silent) {
      if (isMissingRpcError(res.error)) {
        await requestAppAlert("Falta SQL no Supabase: aplica o patch de message requests.", {
          title: "Message Requests",
          okText: "OK",
        });
      } else {
        await requestAppAlert(`Falhou o pedido de mensagem: ${res.error.message}`, {
          title: "Message Requests",
          okText: "OK",
        });
      }
    }
    return { ok: false, error: res.error, conversationId: "" };
  }

  const row = Array.isArray(res?.data) ? (res.data[0] || null) : (res?.data || null);
  const status = String(row?.status || "").trim().toLowerCase();
  const conversationId = normId(row?.conversation_id || "");
  relationshipTraceMeasureSync(trace, "successPatch", () => {
    if (status === "accepted" && conversationId) {
      optimisticRemoveMessageOutgoing(tempReqId);
      upsertDmContactRow({
        other_user_id: normId(optimisticProfile?.id || ""),
        username: uname,
        display_name: optimisticProfile?.display_name || uname,
        avatar_url: optimisticProfile?.avatar_url || null,
        conversation_id: conversationId,
        _optimistic: false,
      });
    } else {
      state.messageOutgoing = (state.messageOutgoing || []).map((entry) =>
        String(entry?.request_id || "").trim() === tempReqId
          ? {
            ...entry,
            request_id: String(row?.request_id || "").trim() || tempReqId,
            conversation_id: conversationId || normId(entry?.conversation_id || ""),
            _optimistic: false,
          }
          : entry
      );
    }
    syncMessageRequestStateAliases();
  });
  renderRelationshipUiNow({
    rerenderPending: true,
    rerenderDmList: true,
    affectedUserId: normId(optimisticProfile?.id || ""),
    affectedUsername: uname,
  });
  if (status !== "accepted") {
    const pendingRequestId = String(row?.request_id || "").trim() || tempReqId;
    if (pendingRequestId) openMessageRequestPreview(pendingRequestId, { direction: "outgoing" });
    void refreshMessageRequestsForSidebar({ rerender: true }).then(() => {
      if (pendingRequestId && isActiveMessageRequestPreview()) {
        openMessageRequestPreview(pendingRequestId, { direction: "outgoing" });
      }
    }).catch(() => {});
  }
  relationshipTraceSchedulePaint(trace, "successPaint");
  deferRelationshipTraceToReconcile(trace, { delayMs: 180, status, conversationId });
  scheduleRelationshipReconcile(180, trace);
  return {
    ok: true,
    error: null,
    requestId: String(row?.request_id || "").trim(),
    status,
    conversationId,
  };
}

