async function blockMessageReq(requestId, { silent = false } = {}) {
  const rid = String(requestId || "").trim();
  if (!rid) return { ok: false, error: { message: "request_id invalido" } };
  const trace = beginRelationshipActionTrace("block_message_request", { requestId: rid });

  const incomingRow = (state.messageIncoming || []).find(
    (r) => String(r?.request_id || r?.id || "").trim() === rid
  ) || null;
  const targetUid = normId(incomingRow?.from_user_id || incomingRow?.user_id || "");
  const targetUsername = String(incomingRow?.username || "").trim();
  const snapshot = relationshipTraceMeasureSync(trace, "snapshotRelationshipState", () => snapshotRelationshipState({
    targetUserId: targetUid,
    includeBlockedUsers: true,
  }));
  relationshipTraceMeasureSync(trace, "optimisticPatch", () => {
    optimisticRemoveMessageIncoming(rid);
    if (targetUid) {
      upsertBlockedUserRow({
        userId: targetUid,
        username: targetUsername,
        displayName: String(incomingRow?.display_name || targetUsername || "User").trim() || "User",
        avatarUrl: incomingRow?.avatar_url || "",
      });
    }
  });
  if (activeMessageRequestPreviewId === rid) {
    activeMessageRequestPreviewId = "";
    hideDmRequestBanner();
    leaveActiveDmView({ captureHistory: true });
  }
  renderRelationshipUiNow({
    rerenderPending: true,
    rerenderBlockedSettings: true,
    rerenderDmList: true,
    affectedUserId: targetUid,
    affectedUsername: targetUsername,
  });
  relationshipTraceSchedulePaint(trace, "optimisticPaint");

  let res = await relationshipTraceMeasureAsync(trace, "rpc:block_message_request", () => (
    rpcWithTimeout("block_message_request", { request_id: rid })
  ));
  if (res?.error && isMissingRpcError(res.error) && targetUid) {
    const blockRes = await blockUserRpc(targetUid);
    if (!blockRes?.error) {
      await rejectMessageReq(rid, { silent: true }).catch(() => {});
      res = { data: { ok: true }, error: null };
    } else {
      res = blockRes;
    }
  }
  if (res?.error) {
    restoreRelationshipState(snapshot, {
      rerenderPending: true,
      rerenderBlockedSettings: true,
      rerenderDmList: true,
      affectedUserId: targetUid,
      affectedUsername: targetUsername,
    });
    relationshipTraceSchedulePaint(trace, "rollbackPaint");
    endRelationshipTrace(trace, "rpc_error", { message: String(res?.error?.message || res?.error || "") });
    if (!silent) {
      await requestAppAlert("Falhou a bloquear o pedido: " + (res.error.message || String(res.error)), {
        title: "Message Requests",
        okText: "OK",
      });
    }
    return { ok: false, error: res.error };
  }
  dmCanMessageCacheByUserId.delete(targetUid);
  void refreshMessageRequestsForSidebar({ rerender: true }).catch(() => {});
  deferRelationshipTraceToReconcile(trace, { delayMs: 180 });
  scheduleRelationshipReconcile(180, trace);
  return { ok: true, error: null };
}

