function scheduleRelationshipRealtimeProfileHydration(userIds = [], renderOptions = {}) {
  const wanted = Array.from(new Set((Array.isArray(userIds) ? userIds : [])
    .map((id) => normId(id))
    .filter(Boolean)));
  if (!wanted.length) return;
  void fetchProfilesByIds(wanted, { includeBio: false, force: false }).then(() => {
    state.friends = hydrateRelationshipRowsFromCache(state.friends);
    state.incoming = hydrateRelationshipRowsFromCache(state.incoming);
    state.outgoing = hydrateRelationshipRowsFromCache(state.outgoing);
    state.messageIncoming = hydrateRelationshipRowsFromCache(state.messageIncoming);
    state.messageOutgoing = hydrateRelationshipRowsFromCache(state.messageOutgoing);
    syncMessageRequestStateAliases();
    state.messageDrafts = hydrateRelationshipRowsFromCache(state.messageDrafts);
    state.dmContacts = hydrateRelationshipRowsFromCache(state.dmContacts);
    renderRelationshipUiNow(renderOptions || {});
  }).catch(() => {});
}

function snapshotDmUserUiState(userId) {
  const uid = normId(userId || "");
  if (!uid) return null;
  const hiddenRecord = getDmHiddenRowRecord(uid);
  return {
    userId: uid,
    hidden: !!hiddenRecord,
    hiddenRecord,
    unreadCount: Number(dmUnreadByUserId.get(uid) || 0),
  };
}

function restoreDmUserUiState(snapshot, { rerenderDmList = false } = {}) {
  const uid = normId(snapshot?.userId || "");
  if (!uid) return;

  if (snapshot?.hidden) {
    dmHiddenRowByUserId.set(uid, normalizeDmHiddenRowRecord(snapshot.hiddenRecord, { hiddenAt: Date.now(), lastKnownActivityKey: "" }));
  } else {
    dmHiddenRowByUserId.delete(uid);
    dmHiddenByUserId.delete(uid);
  }

  const unreadCount = Number(snapshot?.unreadCount || 0);
  if (unreadCount > 0) dmUnreadByUserId.set(uid, unreadCount);
  else dmUnreadByUserId.delete(uid);

  persistDmUnreadUsersToStorage();
  persistDmHiddenToStorage();
  scheduleDmChromeRender({
    decorations: true,
    groupsRail: true,
    widgets: true,
    reorderDmList: !rerenderDmList,
  });

  if (rerenderDmList) {
    queueLightweightDmListRenderFromState();
  }
}

function snapshotRelationshipState({ targetUserId = "", includeBlockedUsers = false } = {}) {
  return {
    friends: [...(state.friends || [])],
    incoming: [...(state.incoming || [])],
    outgoing: [...(state.outgoing || [])],
    messageIncoming: [...(state.messageIncoming || [])],
    messageOutgoing: [...(state.messageOutgoing || [])],
    messageDrafts: [...(state.messageDrafts || [])],
    dmContacts: [...(state.dmContacts || [])],
    blockedUsers: includeBlockedUsers ? [...(state.blockedUsers || [])] : null,
    dmUserUi: snapshotDmUserUiState(targetUserId),
  };
}

function getOptimisticRelationshipProfile({ userId = "", username = "", displayName = "", avatarUrl = "" } = {}) {
  const uid = normId(userId || "");
  const uname = String(username || "").trim();
  const seed = uid
    ? (
      getCachedProfile(uid)
      || getFriendRowByUserId(uid)
      || getMessageContactRowByUserId(uid)
      || getIncomingMessageRequestByUserId(uid)
      || getOutgoingMessageRequestByUserId(uid)
      || getDraftMessageRequestByUserId(uid)
      || getBlockedUserRowById(uid)
      || null
    )
    : (
      getFriendRowByUsername(uname)
      || getMessageContactRowByUsername(uname)
      || getBlockedUserRowByUsername(uname)
      || null
    );
  if (!uid && !uname && !seed) return null;
  return {
    ...(seed || {}),
    id: uid || normId(seed?.id || seed?.other_user_id || seed?.userId || seed?.blocked_user_id || ""),
    username: uname || String(seed?.username || "").trim(),
    display_name: String(displayName || seed?.display_name || seed?.displayName || seed?.username || uname || "User").trim() || "User",
    avatar_url: avatarUrl || seed?.avatar_url || seed?.avatarUrl || null,
  };
}

function refreshAddFriendPreviewFromLocalState({ userId = "", username = "" } = {}) {
  const host = document.getElementById("addFriendPreview");
  if (!host) return;
  const currentQuery = String(document.getElementById("addUsername")?.value || addFriendLookupLastQuery || "").trim();
  if (!currentQuery) return;

  const affectedId = normId(userId || "");
  const affectedUsername = String(username || "").trim().toLowerCase();
  const previewId = normId(addFriendPreviewProfileId || "");
  const previewUsername = String(addFriendPreviewProfileUsername || "").trim().toLowerCase();
  const queryLower = currentQuery.toLowerCase();
  const matches =
    (!!affectedId && previewId === affectedId)
    || (!!affectedUsername && (previewUsername === affectedUsername || queryLower === affectedUsername));
  if (!matches) return;

  const profile = getOptimisticRelationshipProfile({
    userId: affectedId || previewId,
    username: username || currentQuery,
  });
  if (!profile?.id) return;
  renderAddFriendPreview(profile, { query: currentQuery, loading: false });
}

function renderRelationshipUiNow({
  rerenderFriends = false,
  rerenderPending = false,
  rerenderBlockedSettings = false,
  rerenderDmList = false,
  affectedUserId = "",
  affectedUsername = "",
} = {}) {
  const trace = getRelationshipCurrentTrace();
  relationshipTraceMeasureSync(trace, "renderRelationshipUiNow", () => {
    if (rerenderFriends) renderFriends({ skipPresenceRefresh: true, skipGroupsRail: true });
    if (rerenderPending) renderPending({ skipWidgets: true, skipAddFriendLookup: true });
    if (rerenderFriends) renderGroupsRail();
    if (rerenderFriends || rerenderPending || rerenderBlockedSettings) {
      scheduleUiRender("widgets", () => renderWidgets());
    }
  }, {
    rerenderFriends: !!rerenderFriends,
    rerenderPending: !!rerenderPending,
    rerenderBlockedSettings: !!rerenderBlockedSettings,
    rerenderDmList: !!rerenderDmList,
    affectedUserId: normId(affectedUserId || ""),
  });
  if (rerenderBlockedSettings) renderBlockedUsersSettingsRowsFromState();
  if (rerenderDmList) {
    relationshipTraceLog(trace, "loadDmList:queued", { source: "renderRelationshipUiNow" });
    queueLightweightDmListRenderFromState();
  } else {
    relationshipTraceMeasureSync(trace, "reorderDmListByActivity", () => {
      reorderDmListByActivity();
    });
  }
  try {
    const targetUid = normId(affectedUserId || "");
    const targetUsername = String(affectedUsername || "").trim().toLowerCase();
    const currentCardUid = normId(userCardCurrentUserId || "");
    const currentCardUsername = String(userCardCurrentUsername || "").trim().toLowerCase();
    if ((targetUid && currentCardUid === targetUid) || (!targetUid && targetUsername && currentCardUsername === targetUsername)) {
      refreshOpenUserCard();
    }
  } catch (_) {}
  try {
    const peerUid = normId(getActiveDmPeerUserId() || "");
    const targetUid = normId(affectedUserId || "");
    if (dmProfilePanelOpen && (!targetUid || peerUid === targetUid)) refreshDmProfilePanel();
  } catch (_) {}
  try {
    refreshAddFriendPreviewFromLocalState({ userId: affectedUserId, username: affectedUsername });
  } catch (_) {}
}

let lightweightDmListRenderQueued = false;

function queueLightweightDmListRenderFromState() {
  const trace = getRelationshipCurrentTrace();
  relationshipTraceLog(trace, "loadDmList:queued", { source: "queueLightweightDmListRenderFromState" });
  if (lightweightDmListRenderQueued) return;
  lightweightDmListRenderQueued = true;
  scheduleUiRender("dm-sidebar", () => {
    lightweightDmListRenderQueued = false;
    void loadDmList({
      preloadedFriends: state.friends,
      preloadedContacts: state.dmContacts,
      skipProfileHydration: true,
      skipFriendPreferencesSync: true,
      skipGifFavoritesSync: true,
      skipGroupServerCollections: true,
      skipMessageContactsFetch: true,
      skipActivityHydration: true,
    }).catch(() => {
      reorderDmListByActivity();
    });
  });
}

function restoreRelationshipState(snapshot, {
  rerenderFriends = false,
  rerenderPending = false,
  rerenderBlockedSettings = false,
  rerenderDmList = false,
  affectedUserId = "",
  affectedUsername = "",
} = {}) {
  const trace = getRelationshipCurrentTrace();
  if (!snapshot || typeof snapshot !== "object") return;
  relationshipTraceMeasureSync(trace, "restoreRelationshipState:assign", () => {
    state.friends = Array.isArray(snapshot.friends) ? snapshot.friends : [];
    state.incoming = Array.isArray(snapshot.incoming) ? snapshot.incoming : [];
    state.outgoing = Array.isArray(snapshot.outgoing) ? snapshot.outgoing : [];
    setMessageRequestRows({
      incoming: Array.isArray(snapshot.messageIncoming) ? snapshot.messageIncoming : [],
      outgoing: Array.isArray(snapshot.messageOutgoing) ? snapshot.messageOutgoing : [],
    });
    state.messageDrafts = Array.isArray(snapshot.messageDrafts) ? snapshot.messageDrafts : [];
    state.dmContacts = Array.isArray(snapshot.dmContacts) ? snapshot.dmContacts : [];
    if (Array.isArray(snapshot.blockedUsers)) state.blockedUsers = snapshot.blockedUsers;
    if (snapshot.dmUserUi) restoreDmUserUiState(snapshot.dmUserUi, { rerenderDmList: false });
  });
  renderRelationshipUiNow({
    rerenderFriends,
    rerenderPending,
    rerenderBlockedSettings,
    rerenderDmList,
    affectedUserId,
    affectedUsername,
  });
}

function scheduleRelationshipReconcile(delayMs = 140, trace = null) {
  scheduleGlobalFriendRequestRefresh(delayMs, { trace });
}

function optimisticRemoveFriendById(userId) {
  const uid = normId(userId || "");
  if (!uid) return;
  state.friends = (state.friends || []).filter(
    (f) => normId(f?.other_user_id || f?.id || "") !== uid
  );
  state.incoming = (state.incoming || []).filter(
    (r) => normId(r?.from_user_id || "") !== uid
  );
  state.outgoing = (state.outgoing || []).filter(
    (r) => normId(r?.to_user_id || "") !== uid
  );
  state.messageIncoming = (state.messageIncoming || []).filter(
    (r) => getIncomingMessageRequestPeerId(r) !== uid
  );
  state.messageOutgoing = (state.messageOutgoing || []).filter(
    (r) => getOutgoingMessageRequestPeerId(r) !== uid
  );
  syncMessageRequestStateAliases();
  state.messageDrafts = (state.messageDrafts || []).filter(
    (r) => normId(r?.to_user_id || r?.other_user_id || r?.user_id || r?.id || "") !== uid
  );

  // Zap the user's row from the DM sidebar immediately — no network call, pure DOM.
  const dmList = document.getElementById("dmList");
  if (dmList) {
    dmList.querySelectorAll(`.dm-item[data-dm-id]`).forEach((el) => {
      if (normId(el.getAttribute("data-dm-id") || "") === uid) el.remove();
    });
  }
}
// ─────────────────────────────────────────────────────────────────────────────

async function acceptReq(id) {
  const rid = normId(id || "");
  if (!rid) return;
  const trace = beginRelationshipActionTrace("accept_friend_request", { requestId: rid });

  const incomingRow = (state.incoming || []).find(
    (r) => normId(r?.request_id || r?.id || "") === rid
  );
  const targetUid = normId(incomingRow?.from_user_id || "");
  const snapshot = relationshipTraceMeasureSync(trace, "snapshotRelationshipState", () => snapshotRelationshipState());

  relationshipTraceMeasureSync(trace, "optimisticPatch", () => {
    if (incomingRow) {
      optimisticRemoveIncoming(rid);
      const optimisticFriend = {
        other_user_id: targetUid,
        username: incomingRow.username || "",
        display_name: incomingRow.display_name || incomingRow.username || "",
        avatar_url: incomingRow.avatar_url || null,
        since: new Date().toISOString(),
        _optimistic: true,
      };
      state.friends = [optimisticFriend, ...(state.friends || [])];
    }
  });
  renderRelationshipUiNow({
    rerenderFriends: true,
    rerenderPending: true,
    affectedUserId: targetUid,
    affectedUsername: String(incomingRow?.username || "").trim(),
  });
  relationshipTraceSchedulePaint(trace, "optimisticPaint");

  const { error } = await relationshipTraceMeasureAsync(trace, "rpc:accept_friend_request", () => (
    supabase.rpc("accept_friend_request", { request_id: rid })
  ));
  if (error) {
    restoreRelationshipState(snapshot, {
      rerenderFriends: true,
      rerenderPending: true,
      affectedUserId: targetUid,
      affectedUsername: String(incomingRow?.username || "").trim(),
    });
    relationshipTraceSchedulePaint(trace, "rollbackPaint");
    endRelationshipTrace(trace, "rpc_error", { message: String(error?.message || error || "") });
    alert("Erro: " + error.message);
    return;
  }

  deferRelationshipTraceToReconcile(trace, { delayMs: 180 });
  scheduleRelationshipReconcile(180, trace);
}

async function rejectReq(id) {
  const rid = normId(id || "");
  if (!rid) return;
  const trace = beginRelationshipActionTrace("reject_friend_request", { requestId: rid });

  const incomingRow = (state.incoming || []).find(
    (r) => normId(r?.request_id || r?.id || "") === rid
  ) || null;
  const snapshot = relationshipTraceMeasureSync(trace, "snapshotRelationshipState", () => snapshotRelationshipState());
  relationshipTraceMeasureSync(trace, "optimisticPatch", () => {
    optimisticRemoveIncoming(rid);
  });
  renderRelationshipUiNow({
    rerenderPending: true,
    affectedUserId: normId(incomingRow?.from_user_id || ""),
    affectedUsername: String(incomingRow?.username || "").trim(),
  });
  relationshipTraceSchedulePaint(trace, "optimisticPaint");

  const { error } = await relationshipTraceMeasureAsync(trace, "rpc:reject_friend_request", () => (
    supabase.rpc("reject_friend_request", { request_id: rid })
  ));
  if (error) {
    restoreRelationshipState(snapshot, {
      rerenderPending: true,
      affectedUserId: normId(incomingRow?.from_user_id || ""),
      affectedUsername: String(incomingRow?.username || "").trim(),
    });
    relationshipTraceSchedulePaint(trace, "rollbackPaint");
    endRelationshipTrace(trace, "rpc_error", { message: String(error?.message || error || "") });
    alert("Erro: " + error.message);
    return;
  }
  deferRelationshipTraceToReconcile(trace, { delayMs: 180 });
  scheduleRelationshipReconcile(180, trace);
}

async function cancelReq(id) {
  const rid = normId(id || "");
  if (!rid) return;
  const trace = beginRelationshipActionTrace("cancel_friend_request", { requestId: rid });

  const outgoingRow = (state.outgoing || []).find(
    (r) => normId(r?.request_id || r?.id || "") === rid
  ) || null;
  const snapshot = relationshipTraceMeasureSync(trace, "snapshotRelationshipState", () => snapshotRelationshipState());
  relationshipTraceMeasureSync(trace, "optimisticPatch", () => {
    optimisticRemoveOutgoing(rid);
  });
  renderRelationshipUiNow({
    rerenderPending: true,
    affectedUserId: normId(outgoingRow?.to_user_id || ""),
    affectedUsername: String(outgoingRow?.username || "").trim(),
  });
  relationshipTraceSchedulePaint(trace, "optimisticPaint");

  const { error } = await relationshipTraceMeasureAsync(trace, "rpc:cancel_friend_request", () => (
    supabase.rpc("cancel_friend_request", { request_id: rid })
  ));
  if (error) {
    restoreRelationshipState(snapshot, {
      rerenderPending: true,
      affectedUserId: normId(outgoingRow?.to_user_id || ""),
      affectedUsername: String(outgoingRow?.username || "").trim(),
    });
    relationshipTraceSchedulePaint(trace, "rollbackPaint");
    endRelationshipTrace(trace, "rpc_error", { message: String(error?.message || error || "") });
    alert("Erro: " + error.message);
    return;
  }
  deferRelationshipTraceToReconcile(trace, { delayMs: 180 });
  scheduleRelationshipReconcile(180, trace);
}

