function isMissingDmFriendPreferencesTableError(error) {
  const code = String(error?.code || "").trim().toLowerCase();
  const msg = String(error?.message || "").trim().toLowerCase();
  const details = String(error?.details || "").trim().toLowerCase();
  if (!code && !msg && !details) return false;
  if (code === "42p01" || code === "pgrst205") return true;
  return (
    (msg.includes("friend_user_preferences") && (msg.includes("not exist") || msg.includes("schema cache")))
    || (details.includes("friend_user_preferences") && details.includes("not exist"))
  );
}

function normalizeDmFriendPreferenceNickname(value) {
  return String(value || "").trim().slice(0, 48);
}

function getDmFriendPreferencesSyncFingerprint(userId, friendIds = []) {
  const meId = normId(userId || "");
  const ids = Array.isArray(friendIds)
    ? friendIds.map((id) => normId(id)).filter(Boolean).sort()
    : [];
  return `${meId}:${ids.join(",")}`;
}

async function syncDmFriendPreferencesFromCloud(friendsRows = state.friends, { force = false } = {}) {
  ensureDmClientStateLoaded();
  const meId = normId(state?.user?.id || "");
  if (!meId) return false;

  const friendIds = Array.from(
    new Set(
      (Array.isArray(friendsRows) ? friendsRows : [])
        .map((row) => normId(row?.other_user_id || row?.id || ""))
        .filter(Boolean)
    )
  ).sort();

  const syncFp = getDmFriendPreferencesSyncFingerprint(meId, friendIds);
  const nowMs = Date.now();
  const syncFresh = dmFriendPreferencesCloudSyncFingerprint === syncFp
    && (nowMs - Number(dmFriendPreferencesCloudLastSyncAt || 0)) < 12_000;
  if (!force && syncFresh) return false;
  if (!force && dmFriendPreferencesCloudSyncInFlight) return dmFriendPreferencesCloudSyncInFlight;

  const run = (async () => {
    if (!friendIds.length) {
      dmFriendPreferencesCloudSyncFingerprint = syncFp;
      dmFriendPreferencesCloudLastSyncAt = Date.now();
      return false;
    }

    const { data, error } = await supabase
      .from("friend_user_preferences")
      .select("friend_user_id, is_best_friend, nickname")
      .eq("user_id", meId)
      .in("friend_user_id", friendIds);

    if (error) {
      if (isMissingDmFriendPreferencesTableError(error)) {
        dmFriendPreferencesCloudAvailable = false;
        dmFriendPreferencesCloudSyncFingerprint = syncFp;
        dmFriendPreferencesCloudLastSyncAt = Date.now();
        return false;
      }
      console.warn("friend prefs: cloud sync read failed", error);
      return false;
    }

    dmFriendPreferencesCloudAvailable = true;
    const remoteByFriendId = new Map();
    (Array.isArray(data) ? data : []).forEach((row) => {
      const uid = normId(row?.friend_user_id || "");
      if (!uid) return;
      remoteByFriendId.set(uid, {
        isBestFriend: !!row?.is_best_friend,
        nickname: normalizeDmFriendPreferenceNickname(row?.nickname),
      });
    });

    const nextBestFriendIds = new Set();
    const nextNicknames = new Map();
    const rowsToBackfill = [];

    friendIds.forEach((uid) => {
      const remote = remoteByFriendId.get(uid);
      const localBest = dmBestFriendUserIds.has(uid);
      const localNick = normalizeDmFriendPreferenceNickname(dmFriendNicknameByUserId.get(uid));

      if (remote) {
        if (remote.isBestFriend) nextBestFriendIds.add(uid);
        if (remote.nickname) nextNicknames.set(uid, remote.nickname);
        return;
      }

      if (localBest) nextBestFriendIds.add(uid);
      if (localNick) nextNicknames.set(uid, localNick);
      if (localBest || localNick) {
        rowsToBackfill.push({
          user_id: meId,
          friend_user_id: uid,
          is_best_friend: !!localBest,
          nickname: localNick || null,
        });
      }
    });

    dmBestFriendUserIds.clear();
    nextBestFriendIds.forEach((uid) => dmBestFriendUserIds.add(uid));
    dmFriendNicknameByUserId.clear();
    nextNicknames.forEach((nick, uid) => dmFriendNicknameByUserId.set(uid, nick));
    persistDmBestFriendsToStorage();
    persistDmFriendNicknamesToStorage();

    dmFriendPreferencesCloudSyncFingerprint = syncFp;
    dmFriendPreferencesCloudLastSyncAt = Date.now();

    if (rowsToBackfill.length) {
      const { error: backfillErr } = await supabase
        .from("friend_user_preferences")
        .upsert(rowsToBackfill, { onConflict: "user_id,friend_user_id" });
      if (backfillErr) {
        if (isMissingDmFriendPreferencesTableError(backfillErr)) {
          dmFriendPreferencesCloudAvailable = false;
        } else {
          console.warn("friend prefs: cloud backfill failed", backfillErr);
        }
      }
    }

    return true;
  })();

  dmFriendPreferencesCloudSyncInFlight = run;
  try {
    return await run;
  } finally {
    if (dmFriendPreferencesCloudSyncInFlight === run) {
      dmFriendPreferencesCloudSyncInFlight = null;
    }
  }
}

async function writeDmFriendPreferenceToCloud(userId) {
  const meId = normId(state?.user?.id || "");
  const uid = normId(userId || "");
  if (!meId || !uid || uid === meId) return false;
  if (dmFriendPreferencesCloudAvailable === false) return false;

  const isBestFriend = dmBestFriendUserIds.has(uid);
  const nickname = normalizeDmFriendPreferenceNickname(dmFriendNicknameByUserId.get(uid));
  const hasPref = isBestFriend || !!nickname;

  if (hasPref) {
    const { error } = await supabase
      .from("friend_user_preferences")
      .upsert({
        user_id: meId,
        friend_user_id: uid,
        is_best_friend: !!isBestFriend,
        nickname: nickname || null,
      }, { onConflict: "user_id,friend_user_id" });
    if (error) {
      if (isMissingDmFriendPreferencesTableError(error)) {
        dmFriendPreferencesCloudAvailable = false;
        return false;
      }
      if (isAltaraPlusLimitError(error, "best_friends")) {
        dmBestFriendUserIds.delete(uid);
        persistDmBestFriendsToStorage();
        showAltaraPlusBestFriendsLimitReached();
        return false;
      }
      console.warn("friend prefs: cloud upsert failed", error);
      return false;
    }
  } else {
    const { error } = await supabase
      .from("friend_user_preferences")
      .delete()
      .eq("user_id", meId)
      .eq("friend_user_id", uid);
    if (error) {
      if (isMissingDmFriendPreferencesTableError(error)) {
        dmFriendPreferencesCloudAvailable = false;
        return false;
      }
      console.warn("friend prefs: cloud delete failed", error);
      return false;
    }
  }

  dmFriendPreferencesCloudAvailable = true;
  dmFriendPreferencesCloudLastSyncAt = Date.now();
  return true;
}

function queueDmFriendPreferenceCloudWrite(userId) {
  const uid = normId(userId);
  if (!uid) return;
  dmFriendPreferencesCloudWriteQueue = dmFriendPreferencesCloudWriteQueue
    .then(() => writeDmFriendPreferenceToCloud(uid))
    .catch((err) => {
      console.warn("friend prefs: cloud write queue failed", err);
    });
}

