function isDmUserMuted(userId) {
  ensureDmClientStateLoaded();
  const uid = normId(userId);
  if (!uid) return false;
  if (!dmMutedUserIds.has(uid)) return false;
  const until = normalizeMuteUntilValue(dmMutedUserUntilById.get(uid));
  if (until > 0 && until <= Date.now()) {
    dmMutedUserIds.delete(uid);
    dmMutedUserUntilById.delete(uid);
    persistDmMutedUsersToStorage();
    scheduleDmMuteExpiryTimer();
    return false;
  }
  return true;
}

function setDmUserMuted(userId, muted = true, { persist = true, untilMs = 0 } = {}) {
  ensureDmClientStateLoaded();
  const uid = normId(userId);
  if (!uid) return false;
  const next = !!muted;
  const has = dmMutedUserIds.has(uid);
  const nextUntil = normalizeMuteUntilValue(untilMs);
  if (next && !has) {
    dmMutedUserIds.add(uid);
    dmMutedUserUntilById.set(uid, nextUntil);
    if (persist) persistDmMutedUsersToStorage();
    scheduleDmMuteExpiryTimer();
    return true;
  }
  if (next && has) {
    const prevUntil = normalizeMuteUntilValue(dmMutedUserUntilById.get(uid));
    if (prevUntil !== nextUntil) {
      dmMutedUserUntilById.set(uid, nextUntil);
      if (persist) persistDmMutedUsersToStorage();
      scheduleDmMuteExpiryTimer();
      return true;
    }
    scheduleDmMuteExpiryTimer();
    return false;
  }
  if (!next && (has || dmMutedUserUntilById.has(uid))) {
    dmMutedUserIds.delete(uid);
    dmMutedUserUntilById.delete(uid);
    if (persist) persistDmMutedUsersToStorage();
    scheduleDmMuteExpiryTimer();
    return true;
  }
  scheduleDmMuteExpiryTimer();
  return false;
}

function toggleDmUserMuted(userId, {
  forceMuted = null,
  untilMs = 0,
  rerender = true,
} = {}) {
  const uid = normId(userId);
  if (!uid) return false;
  const nextMuted = (forceMuted === null)
    ? !isDmUserMuted(uid)
    : !!forceMuted;
  const changed = setDmUserMuted(uid, nextMuted, { persist: true, untilMs });
  if (changed && rerender) queueLightweightDmListRenderFromState();
  return nextMuted;
}

