function logTypingDebug(action = "", details = {}) {
  try {
    if (!isAltaraLocalhostDebugContext()) return;
    console.info("[typing]", action, details || {});
  } catch (_) {}
}

function logTypingInboxDebug(action = "", details = {}) {
  try {
    if (!isAltaraLocalhostDebugContext()) return;
    console.info("[typing-inbox]", action, details || {});
  } catch (_) {}
}

function getTypingInboxChannelName(userId = "") {
  const uid = normId(userId || "");
  return uid ? `typing:inbox:${uid}` : "";
}

function getDmPeerUserIdFromRow(row = {}) {
  return normId(
    row?.other_user_id
    || row?.otherUserId
    || row?.peer_user_id
    || row?.peerUserId
    || row?.friend_user_id
    || row?.friendUserId
    || row?.user_id
    || row?.userId
    || row?.id
    || ""
  );
}

function getDmConversationIdFromRow(row = {}) {
  return normId(
    row?.conversation_id
    || row?.conversationId
    || row?.dm_conversation_id
    || row?.dmConversationId
    || row?.direct_conversation_id
    || row?.directConversationId
    || ""
  );
}

function rememberDmConversationPeer(conversationId = "", userId = "", source = "unknown") {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  if (!convId) return false;
  const existingMeta = getConversationMeta(convId) || {};
  if (isServerConversationKind(existingMeta?.kind) || normId(existingMeta?.serverId || existingMeta?.server_id || "") || findServerChannelContextByConversationId(convId)) {
    logNotificationDebug("dm_peer_map_skip_server_conversation", { conversationId: convId, senderUserId: uid, context: "server_channel", skippedReason: source });
    return false;
  }
  if (!uid) {
    const previousUid = normId(dmConversationPeerCache.get(convId) || "");
    if (previousUid && normId(dmConversationIdByUserId.get(previousUid) || "") === convId) dmConversationIdByUserId.delete(previousUid);
    dmConversationPeerCache.delete(convId);
    return false;
  }
  const previousConvId = normId(dmConversationIdByUserId.get(uid) || "");
  const previousUid = normId(dmConversationPeerCache.get(convId) || "");
  dmConversationPeerCache.set(convId, uid);
  dmConversationIdByUserId.set(uid, convId);
  try {
    setConversationMeta(convId, {
      kind: "dm",
      isGroup: false,
      otherUserId: uid,
      other_user_id: uid,
    });
  } catch (_) {}
  if (previousConvId !== convId || previousUid !== uid) {
    logTypingDebug("dm_conversation_map_populated", { source, userId: uid, conversationId: convId });
  }
  return true;
}

function populateDmConversationIdMapFromRows(rows = [], source = "rows") {
  let count = 0;
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const uid = getDmPeerUserIdFromRow(row);
    const convId = getDmConversationIdFromRow(row);
    if (uid && convId && rememberDmConversationPeer(convId, uid, source)) count += 1;
  });
  return count;
}

function getKnownDmConversationIdForUser(userId = "") {
  const uid = normId(userId || "");
  if (!uid) return "";
  const cachedConvId = normId(dmConversationIdByUserId.get(uid) || "");
  if (cachedConvId) return cachedConvId;
  const rowSources = [
    ...(Array.isArray(state.dmContacts) ? state.dmContacts : []),
    ...(Array.isArray(state.friends) ? state.friends : []),
    ...(Array.isArray(state.dmSidebarRows) ? state.dmSidebarRows : []),
    ...(Array.isArray(lastDmSidebarFinalRows) ? lastDmSidebarFinalRows : []),
  ];
  for (const row of rowSources) {
    const rowUid = getDmPeerUserIdFromRow(row);
    if (!rowUid || rowUid !== uid) continue;
    const convId = getDmConversationIdFromRow(row);
    if (convId) {
      rememberDmConversationPeer(convId, uid, "known-dm-conversation-lookup");
      return convId;
    }
  }
  for (const [convIdRaw, peerUserIdRaw] of dmConversationPeerCache.entries()) {
    const convId = normId(convIdRaw || "");
    const peerUserId = normId(peerUserIdRaw || "");
    if (convId && peerUserId === uid) {
      dmConversationIdByUserId.set(uid, convId);
      return convId;
    }
  }
  for (const [convIdRaw, metaRaw] of dmConversationMetaById.entries()) {
    const convId = normId(convIdRaw || "");
    const kind = String(metaRaw?.kind || "").trim().toLowerCase();
    if (!convId || (kind && kind !== "dm")) continue;
    const metaPeerUserId = normId(metaRaw?.otherUserId || metaRaw?.other_user_id || "");
    if (metaPeerUserId === uid) {
      rememberDmConversationPeer(convId, uid, "conversation-meta-lookup");
      return convId;
    }
  }
  return "";
}

function hasMissingKnownDmConversationIdsForRows(rows = []) {
  return (Array.isArray(rows) ? rows : []).some((row) => {
    const uid = getDmPeerUserIdFromRow(row);
    return !!uid && !getKnownDmConversationIdForUser(uid);
  });
}
function getTypingContextKeyFromPayload(payload = {}) {

  const contextType = String(payload?.contextType || payload?.context_type || "").trim().toLowerCase();
  const conversationId = normId(payload?.conversationId || payload?.conversation_id || "");
  const serverId = normId(payload?.serverId || payload?.server_id || "");
  const channelId = normId(payload?.channelId || payload?.channel_id || "");
  if (contextType === "server_channel" && serverId && channelId) return `typing:server:${serverId}:channel:${channelId}`;
  if (contextType === "group_dm" && conversationId) return `typing:group:${conversationId}`;
  if (contextType === "dm" && conversationId) return `typing:dm:${conversationId}`;
  if (serverId && channelId) return `typing:server:${serverId}:channel:${channelId}`;
  if (conversationId) return `typing:dm:${conversationId}`;
  return "";
}

function parseTypingContextKey(contextKey = "") {
  const key = String(contextKey || "").trim();
  if (!key) return { key: "", contextType: "", conversationId: "", serverId: "", channelId: "", userId: "" };
  const inboxDmMatch = key.match(/^inbox:dm:([0-9a-f-]{8,})$/i);
  if (inboxDmMatch) return { key, contextType: "inbox_dm", conversationId: "", serverId: "", channelId: "", userId: normId(inboxDmMatch[1] || "") };
  const inboxGroupMatch = key.match(/^inbox:group:([0-9a-f-]{8,}):([0-9a-f-]{8,})$/i);
  if (inboxGroupMatch) return { key, contextType: "inbox_group", conversationId: normId(inboxGroupMatch[1] || ""), serverId: "", channelId: "", userId: normId(inboxGroupMatch[2] || "") };
  const dmMatch = key.match(/^typing:dm:([0-9a-f-]{8,})$/i);
  if (dmMatch) return { key, contextType: "dm", conversationId: normId(dmMatch[1] || ""), serverId: "", channelId: "", userId: "" };
  const groupMatch = key.match(/^typing:group:([0-9a-f-]{8,})$/i);
  if (groupMatch) return { key, contextType: "group_dm", conversationId: normId(groupMatch[1] || ""), serverId: "", channelId: "", userId: "" };
  const serverMatch = key.match(/^typing:server:([0-9a-f-]{8,}):channel:([0-9a-f-]{8,})$/i);
  if (serverMatch) return { key, contextType: "server_channel", conversationId: "", serverId: normId(serverMatch[1] || ""), channelId: normId(serverMatch[2] || ""), userId: "" };
  return { key, contextType: "", conversationId: "", serverId: "", channelId: "", userId: "" };
}

function buildTypingContextForConversation(conversationId = "", contextType = "dm") {
  const convId = normId(conversationId || "");
  const type = String(contextType || "dm").trim().toLowerCase() === "group_dm" || String(contextType || "").trim().toLowerCase() === "group" ? "group_dm" : "dm";
  if (!convId) return null;
  const channelName = type === "group_dm" ? `typing:group:${convId}` : `typing:dm:${convId}`;
  return { key: channelName, channelName, contextType: type, conversationId: convId, serverId: "", channelId: "" };
}

function buildTypingContextForSidebarElement(el = null) {
  if (!el || typeof el.getAttribute !== "function") return null;
  const explicitKey = String(el.getAttribute("data-typing-context-key") || "").trim();
  const parsed = parseTypingContextKey(explicitKey);
  const attrType = String(el.getAttribute("data-typing-context-type") || parsed.contextType || "").trim().toLowerCase();
  const conversationId = normId(
    el.getAttribute("data-typing-conversation-id")
    || el.getAttribute("data-conversation-id")
    || el.getAttribute("data-dm-group-conversation")
    || el.getAttribute("data-dm-conversation")
    || parsed.conversationId
    || ""
  );
  const contextType = attrType === "group" || attrType === "group_dm" ? "group_dm" : (attrType === "dm" ? "dm" : parsed.contextType);
  if (explicitKey && (parsed.contextType === "dm" || parsed.contextType === "group_dm")) {
    return { ...parsed, channelName: explicitKey, conversationId: parsed.conversationId || conversationId };
  }
  return buildTypingContextForConversation(conversationId, contextType || "dm");
}

function collectVisibleTypingSidebarContexts() {
  const contexts = new Map();
  let scanned = 0;
  try {
    document.querySelectorAll("[data-typing-context-key]").forEach((el) => {
      scanned += 1;
      const context = buildTypingContextForSidebarElement(el);
      if (!context?.key || context.contextType === "server_channel") return;
      contexts.set(context.key, context);
      logTypingDebug("sidebar_context_found", {
        contextKey: context.key,
        contextType: context.contextType,
        conversationId: context.conversationId,
        userId: normId(el.getAttribute("data-user-id") || el.getAttribute("data-dm-id") || ""),
      });
    });
    document.querySelectorAll(".dm-item[data-dm-id]:not([data-typing-context-key])").forEach((el) => {
      const userId = normId(el.getAttribute("data-user-id") || el.getAttribute("data-dm-id") || "");
      if (userId) logTypingDebug("missing_conversation_id_for_user", { source: "sidebar-context-scan", userId });
    });
  } catch (_) {}
  logTypingDebug("sidebar_contexts_scan", { scanned, found: contexts.size, contextKeys: Array.from(contexts.keys()) });
  return contexts;
}
function getTypingContext(conversationIdInput = "") {
  const conversationId = normId(conversationIdInput || activeDmId || state.activeDm?.conversationId || "");
  if (!conversationId || !state.user?.id) return null;
  const meta = getConversationMeta(conversationId) || {};
  const activeMeta = normId(activeDmId || state.activeDm?.conversationId || "") === conversationId ? (state.activeDm || {}) : {};
  const kind = String(activeMeta?.kind || meta?.kind || "dm").trim().toLowerCase();
  if (kind === "server") {
    const resolved = resolveServerChannelTimelineContext({ conversationId });
    const serverId = normId(resolved?.serverId || activeMeta?.serverId || meta?.serverId || "");
    const channelId = normId(resolved?.channelId || activeMeta?.channelId || meta?.channelId || meta?.channel_id || "");
    const channelType = normalizeConversationChannelType(resolved?.channelType || activeMeta?.channelType || meta?.channelType || "text");
    if (!serverId || !channelId || channelType !== "text") return null;
    const channelName = `typing:server:${serverId}:channel:${channelId}`;
    return {
      key: channelName,
      channelName,
      contextType: "server_channel",
      conversationId,
      serverId,
      channelId,
    };
  }
  const contextType = kind === "group" || activeMeta?.isGroup || meta?.isGroup ? "group_dm" : "dm";
  const channelName = contextType === "group_dm" ? `typing:group:${conversationId}` : `typing:dm:${conversationId}`;
  return {
    key: channelName,
    channelName,
    contextType,
    conversationId,
    serverId: "",
    channelId: "",
  };
}

function getCurrentTypingUserPayload(context = typingActiveContext, type = "typing_start") {
  const userId = normId(state.user?.id || state.me?.id || "");
  if (!userId || !context?.key) return null;
  const displayName = String(state.me?.display_name || state.me?.username || state.user?.user_metadata?.display_name || state.user?.email || "Someone").trim() || "Someone";
  const avatarUrl = String((typeof getCurrentMeAvatarUrl === "function" ? getCurrentMeAvatarUrl() : "") || state.me?.avatar_url || "").trim();
  return {
    type,
    userId,
    displayName,
    avatarUrl,
    conversationId: context.conversationId || "",
    serverId: context.serverId || "",
    channelId: context.channelId || "",
    contextType: context.contextType || "dm",
    sentAt: new Date().toISOString(),
  };
}

function ensureTypingIndicatorElement() {
  let el = document.getElementById("dmTypingIndicator");
  const dmMain = document.getElementById("dmMain");
  if (!el) {
    el = document.createElement("div");
    el.id = "dmTypingIndicator";
    el.className = "typingIndicator";
    el.setAttribute("role", "status");
    el.setAttribute("aria-live", "polite");
    el.setAttribute("aria-atomic", "true");
    el.hidden = true;
  }
  if (dmMain && el.parentElement !== dmMain) {
    const composer = dmMain.querySelector(".dmComposer,.dm__composer");
    if (composer && composer.parentNode === dmMain) dmMain.insertBefore(el, composer);
    else dmMain.appendChild(el);
  }
  return el;
}

function getTypingUsersForContext(contextKey = typingActiveContextKey) {
  const key = String(contextKey || "");
  if (!key) return [];
  const map = typingUsersByContextKey.get(key);
  if (!map) return [];
  const now = Date.now();
  const currentUserId = normId(state.user?.id || "");
  const showSelf = isSelfTypingStatusDebugEnabled();
  const users = [];
  for (const [userId, entry] of map.entries()) {
    if (!userId || (userId === currentUserId && !showSelf)) continue;
    if (now - Number(entry?.lastSeenAt || 0) > TYPING_STALE_MS) continue;
    users.push(entry);
  }
  users.sort((a, b) => String(a.displayName || "").localeCompare(String(b.displayName || "")));
  return users;
}

function isSelfTypingStatusDebugEnabled() {
  try {
    return String(localStorage.getItem("ALTARA_SHOW_SELF_TYPING") || "").trim() === "1";
  } catch (_) {
    return false;
  }
}

function shouldShowTypingForUser(userId = "") {
  const uid = normId(userId || "");
  if (!uid) return false;
  const selfId = normId(state.user?.id || "");
  if (selfId && uid === selfId && !isSelfTypingStatusDebugEnabled()) return false;
  return true;
}

function getTypingUsersForCurrentContext() {
  return getTypingUsersForContext(typingActiveContextKey).filter((entry) => shouldShowTypingForUser(entry?.userId || ""));
}

function isUserTypingInCurrentContext(userId = "") {
  const uid = normId(userId || "");
  if (!uid || !shouldShowTypingForUser(uid)) return false;
  return getTypingUsersForCurrentContext().some((entry) => normId(entry?.userId || "") === uid);
}

function logTypingStatusDebug(action = "", details = {}) {
  try {
    if (!isAltaraLocalhostDebugContext()) return;
    console.info("[typing-status]", action, details || {});
  } catch (_) {}
}

function cssEscapeAltaraIdentifier(value = "") {
  const raw = String(value || "");
  try {
    if (typeof CSS !== "undefined" && typeof CSS.escape === "function") return CSS.escape(raw);
  } catch (_) {}
  return raw.replace(/[^a-zA-Z0-9_-]/g, (ch) => `\\${ch}`);
}

function buildTypingPresenceBadgeHtml(displayName = "Someone") {
  const safeName = String(displayName || "Someone").trim() || "Someone";
  const label = safeName.toLowerCase() === "several people" ? "Several people are typing" : `${safeName} is typing`;
  return `<span class="typingPresenceBadge" aria-label="${escAttr(label)}" title="${escAttr(label)}"><span class="typingPresenceBadge__dot" aria-hidden="true"></span><span class="typingPresenceBadge__dot" aria-hidden="true"></span><span class="typingPresenceBadge__dot" aria-hidden="true"></span><span class="sr-only">${esc(label)}</span></span>`;
}

function getTypingPresenceBadgeElementsForUser(userId = "") {
  const uid = normId(userId || "");
  if (!uid) return [];
  const escaped = cssEscapeAltaraIdentifier(uid);
  const selectors = [
    `[data-status-dot="${escaped}"]`,
    `[data-user-id="${escaped}"] .statusDot`,
    `[data-user-id="${escaped}"] [data-presence-badge]`,
    `.serverMemberRow[data-server-right-user="${escaped}"] .statusDot`,
    `.dm-item[data-dm-id="${escaped}"] .statusDot`,
    `.dmGroupMemberRow[data-group-member-id="${escaped}"] .statusDot`,
    `.presenceRow[data-presence-user="${escaped}"] .statusDot`,
    `.serverVoiceMember[data-server-voice-member-id="${escaped}"] .statusDot`,
  ];
  const badges = [];
  const seen = new Set();
  selectors.forEach((selector) => {
    try {
      document.querySelectorAll(selector).forEach((el) => {
        if (!el || seen.has(el)) return;
        seen.add(el);
        badges.push(el);
      });
    } catch (_) {}
  });
  const activePeerId = normId(typeof getActiveDmPeerUserId === "function" ? getActiveDmPeerUserId() : "");
  if (activePeerId && activePeerId === uid) {
    const dmProfileDot = document.querySelector("#dmProfileAvatar .statusDot");
    if (dmProfileDot && !seen.has(dmProfileDot)) {
      seen.add(dmProfileDot);
      badges.push(dmProfileDot);
    }
  }
  return badges.filter((badge) => !badge.closest?.("[data-server-right-is-bot='1'],.serverMemberRow--bot,.serverVoiceMember.is-bot"));
}

function getTypingPresenceCardForBadge(badgeEl = null) {
  if (!badgeEl || typeof badgeEl.closest !== "function") return null;
  return badgeEl.closest("[data-user-id],.serverMemberRow,.dm-item,.dmGroupMemberRow,.presenceRow,.serverVoiceMember,.userCardCard,.dmProfilePanel,.dmProfileAvatar,#dmProfileAvatar,#userCardAvatar") || badgeEl.parentElement || null;
}

function applyTypingPresenceBadgeElement(badgeEl, userId = "", displayName = "", { temporary = false } = {}) {
  if (!badgeEl) return false;
  const uid = normId(userId || "");
  if (uid && !shouldShowTypingForUser(uid)) return false;
  if (typeof badgeEl.dataset.altaraTypingOriginalClass === "undefined") badgeEl.dataset.altaraTypingOriginalClass = badgeEl.className || "";
  if (typeof badgeEl.dataset.altaraTypingOriginalHtml === "undefined") badgeEl.dataset.altaraTypingOriginalHtml = badgeEl.innerHTML || "";
  if (typeof badgeEl.dataset.altaraTypingOriginalStatus === "undefined") badgeEl.dataset.altaraTypingOriginalStatus = badgeEl.hasAttribute("data-status") ? String(badgeEl.getAttribute("data-status") || "") : "__missing__";
  if (typeof badgeEl.dataset.altaraTypingOriginalAria === "undefined") badgeEl.dataset.altaraTypingOriginalAria = badgeEl.hasAttribute("aria-label") ? String(badgeEl.getAttribute("aria-label") || "") : "__missing__";
  if (typeof badgeEl.dataset.altaraTypingOriginalTitle === "undefined") badgeEl.dataset.altaraTypingOriginalTitle = badgeEl.hasAttribute("title") ? String(badgeEl.getAttribute("title") || "") : "__missing__";
  badgeEl.innerHTML = buildTypingPresenceBadgeHtml(displayName || "Someone");
  badgeEl.classList.add("is-typing-presence");
  badgeEl.setAttribute("data-altara-typing-presence-badge", "1");
  badgeEl.setAttribute("data-status", "typing");
  const label = String(displayName || "Someone").trim().toLowerCase() === "several people" ? "Several people are typing" : `${String(displayName || "Someone").trim() || "Someone"} is typing`;
  badgeEl.setAttribute("aria-label", label);
  badgeEl.setAttribute("title", label);
  if (temporary) badgeEl.setAttribute("data-altara-typing-temporary-badge", "1");
  const card = getTypingPresenceCardForBadge(badgeEl);
  if (card) {
    card.classList.add("is-typing-presence");
    card.setAttribute("data-altara-typing-card", "1");
    if (uid) card.setAttribute("data-altara-typing-user", uid);
  }
  logTypingStatusDebug("render_badge", {
    userId: uid,
    displayName,
    contextKey: typingActiveContextKey,
    temporary,
    applied: true,
  });
  return true;
}

function ensureTemporaryTypingBadgeForConversationRow(rowEl = null) {
  if (!rowEl || typeof rowEl.querySelector !== "function") return null;
  const avatar = rowEl.querySelector(".avatar,.dmAvatar,.groupDmAvatar,.serverNavItemAvatar");
  if (!avatar) return null;
  let badge = avatar.querySelector(".statusDot[data-altara-typing-conversation-badge='1']");
  if (!badge) {
    badge = document.createElement("span");
    badge.className = "statusDot";
    badge.setAttribute("data-altara-typing-conversation-badge", "1");
    avatar.appendChild(badge);
  }
  return badge;
}

function clearTypingStatusOnUserCards({ reason = "clear" } = {}) {
  let cleared = 0;
  document.querySelectorAll("[data-altara-typing-status]").forEach((el) => {
    const originalHtml = el.dataset.altaraTypingOriginalHtml || "";
    setElementHtmlIfChanged(el, originalHtml);
    el.hidden = el.dataset.altaraTypingOriginalHidden === "1";
    el.style.display = el.dataset.altaraTypingOriginalDisplay || "";
    el.classList.remove("hasTypingDotsStatus", "typingStatusText", "memberTypingStatus");
    el.removeAttribute("data-altara-typing-status");
    delete el.dataset.altaraTypingOriginalHtml;
    delete el.dataset.altaraTypingOriginalText;
    delete el.dataset.altaraTypingOriginalHidden;
    delete el.dataset.altaraTypingOriginalDisplay;
    cleared += 1;
  });
  document.querySelectorAll("[data-altara-typing-presence-badge='1']").forEach((badge) => {
    const removeTemporary = badge.getAttribute("data-altara-typing-temporary-badge") === "1";
    if (removeTemporary) {
      badge.remove();
      cleared += 1;
      return;
    }
    badge.className = badge.dataset.altaraTypingOriginalClass || badge.className.replace(/\bis-typing-presence\b/g, "").trim();
    badge.innerHTML = badge.dataset.altaraTypingOriginalHtml || "";
    const originalStatus = badge.dataset.altaraTypingOriginalStatus;
    if (originalStatus === "__missing__") badge.removeAttribute("data-status");
    else if (typeof originalStatus !== "undefined") badge.setAttribute("data-status", originalStatus);
    const originalAria = badge.dataset.altaraTypingOriginalAria;
    if (originalAria === "__missing__") badge.removeAttribute("aria-label");
    else if (typeof originalAria !== "undefined") badge.setAttribute("aria-label", originalAria);
    const originalTitle = badge.dataset.altaraTypingOriginalTitle;
    if (originalTitle === "__missing__") badge.removeAttribute("title");
    else if (typeof originalTitle !== "undefined") badge.setAttribute("title", originalTitle);
    badge.removeAttribute("data-altara-typing-presence-badge");
    badge.removeAttribute("data-altara-typing-temporary-badge");
    delete badge.dataset.altaraTypingOriginalClass;
    delete badge.dataset.altaraTypingOriginalHtml;
    delete badge.dataset.altaraTypingOriginalStatus;
    delete badge.dataset.altaraTypingOriginalAria;
    delete badge.dataset.altaraTypingOriginalTitle;
    cleared += 1;
  });
  document.querySelectorAll("[data-altara-typing-card='1']").forEach((card) => {
    card.classList.remove("is-typing", "is-typing-presence");
    if (typeof card.dataset.altaraTypingOriginalCardHidden !== "undefined") card.hidden = card.dataset.altaraTypingOriginalCardHidden === "1";
    if (typeof card.dataset.altaraTypingOriginalCardDisplay !== "undefined") card.style.display = card.dataset.altaraTypingOriginalCardDisplay || "";
    card.removeAttribute("data-altara-typing-card");
    card.removeAttribute("data-altara-typing-user");
    delete card.dataset.altaraTypingOriginalCardHidden;
    delete card.dataset.altaraTypingOriginalCardDisplay;
  });
  if (cleared) logTypingStatusDebug("cleared", { reason, cleared });
  return cleared;
}

function applyTypingStatusToProfileSurfaces(userId = "", displayName = "") {
  const uid = normId(userId || "");
  if (!uid) return 0;
  let applied = 0;
  getTypingPresenceBadgeElementsForUser(uid).forEach((badge) => {
    if (applyTypingPresenceBadgeElement(badge, uid, displayName)) applied += 1;
  });
  return applied;
}

function applyTypingPresenceBadgeToConversationRows(contextKey = "", typingUsers = []) {
  const parsed = parseTypingContextKey(contextKey || "");
  if (parsed.contextType !== "group_dm" && parsed.contextType !== "inbox_group") return 0;
  const convId = normId(parsed.conversationId || "");
  if (!convId || !Array.isArray(typingUsers) || !typingUsers.length) return 0;
  const escaped = cssEscapeAltaraIdentifier(convId);
  const rows = [];
  try {
    document.querySelectorAll(`.dm-item[data-typing-context-key="typing:group:${escaped}"],.dm-item[data-dm-group-conversation="${escaped}"],.dm-item[data-dm-conversation="${escaped}"][data-dm-group-conversation]`).forEach((el) => rows.push(el));
  } catch (_) {}
  const speakerLabel = typingUsers.length > 1 ? "Several people" : (typingUsers[0]?.displayName || "Someone");
  let applied = 0;
  rows.forEach((row) => {
    const badge = ensureTemporaryTypingBadgeForConversationRow(row);
    if (applyTypingPresenceBadgeElement(badge, "", speakerLabel, { temporary: true })) {
      applied += 1;
      row.setAttribute("data-altara-typing-conversation", convId);
    }
  });
  if (applied) logTypingStatusDebug("render_group_row_badge", { conversationId: convId, badgeCount: applied, contextKey });
  return applied;
}

function renderTypingStatusOnUserCards({ reason = "render" } = {}) {
  const cleared = clearTypingStatusOnUserCards({ reason: `${reason}:rerender` });
  const contextKeys = Array.from(typingUsersByContextKey.keys());
  if (!contextKeys.length) {
    logTypingStatusDebug("render", { contextKey: typingActiveContextKey, badgeCount: 0, cleared, applied: false });
    return 0;
  }
  let appliedCount = 0;
  const appliedUserIds = [];
  const appliedConversationIds = [];
  contextKeys.forEach((contextKey) => {
    const parsed = parseTypingContextKey(contextKey);
    const typingUsers = getTypingUsersForContext(contextKey);
    if (!typingUsers.length) return;
    const isActiveContext = contextKey === typingActiveContextKey;
    const shouldApplyUserBadges = isActiveContext || parsed.contextType === "dm" || parsed.contextType === "inbox_dm" || parsed.contextType === "inbox_group";
    if (shouldApplyUserBadges) {
      typingUsers.forEach((entry) => {
        const uid = normId(entry?.userId || "");
        if (!uid) return;
        if (!shouldShowTypingForUser(uid)) {
          logTypingStatusDebug("render", { userId: uid, contextKey, skippedSelf: true });
          return;
        }
        const badgeElements = getTypingPresenceBadgeElementsForUser(uid);
        let badgeApplied = 0;
        badgeElements.forEach((badge) => {
          if (applyTypingPresenceBadgeElement(badge, uid, entry?.displayName || "")) {
            badgeApplied += 1;
            appliedCount += 1;
          }
        });
        if (badgeApplied) {
          appliedUserIds.push(uid);
          if (String(contextKey || "").startsWith("inbox:")) logTypingInboxDebug("apply_badge", { contextKey, userId: uid, conversationId: parsed.conversationId || "", contextType: parsed.contextType, badgeCount: badgeApplied });
        }
        logTypingStatusDebug("render", {
          userId: uid,
          displayName: entry?.displayName || "",
          contextKey,
          badgeCount: badgeApplied,
          applied: badgeApplied > 0,
        });
      });
    }
    const conversationRowCount = applyTypingPresenceBadgeToConversationRows(contextKey, typingUsers);
    if (conversationRowCount && parsed.conversationId) appliedConversationIds.push(parsed.conversationId);
    appliedCount += conversationRowCount;
  });
  logTypingStatusDebug("render_complete", {
    reason,
    contextKey: typingActiveContextKey,
    contextCount: contextKeys.length,
    appliedCount,
    appliedUserIds: Array.from(new Set(appliedUserIds)),
    appliedConversationIds: Array.from(new Set(appliedConversationIds)),
  });
  return appliedCount;
}

function getTypingStatusDebugCardSummary() {
  const badges = Array.from(document.querySelectorAll("[data-altara-typing-presence-badge='1']"));
  const cards = Array.from(document.querySelectorAll("[data-altara-typing-card='1']"));
  const userIds = cards.map((node) => normId(node.getAttribute("data-altara-typing-user") || "")).filter(Boolean);
  const conversationIds = cards.map((node) => normId(
    node.getAttribute("data-altara-typing-conversation")
    || node.getAttribute("data-typing-conversation-id")
    || node.getAttribute("data-dm-group-conversation")
    || node.getAttribute("data-dm-conversation")
    || ""
  )).filter(Boolean);
  const ownTypingHidden = Array.from(typingUsersByContextKey.values()).some((map) => Array.from(map.values()).some((entry) => {
    const uid = normId(entry?.userId || "");
    return !!uid && uid === normId(state.user?.id || "") && !isSelfTypingStatusDebugEnabled();
  }));
  return {
    visibleTypingCardCount: cards.length,
    cardUserIdsWithTypingStatus: Array.from(new Set(userIds)),
    typingPresenceBadgeCount: badges.length,
    userIdsWithTypingPresenceBadge: Array.from(new Set(userIds)),
    conversationIdsWithTypingPresenceBadge: Array.from(new Set(conversationIds)),
    bottomIndicatorVisible: !!document.getElementById("dmTypingIndicator")?.classList.contains("is-visible"),
    ownTypingHidden,
  };
}

function renderTypingIndicator(contextKey = typingActiveContextKey) {
  const el = ensureTypingIndicatorElement();
  if (!el) return;
  const key = String(contextKey || "");
  if (!key || key !== typingActiveContextKey) {
    el.hidden = true;
    el.classList.remove("is-visible");
    setElementHtmlIfChanged(el, "");
    renderTypingStatusOnUserCards({ reason: "typing-indicator-context-mismatch" });
    return;
  }
  const users = key === typingActiveContextKey
    ? getTypingUsersForCurrentContext()
    : getTypingUsersForContext(key).filter((entry) => shouldShowTypingForUser(entry?.userId || ""));
  if (!users.length) {
    el.hidden = true;
    el.classList.remove("is-visible");
    setElementHtmlIfChanged(el, "");
    logTypingDebug("render", { contextKey: key, count: 0 });
    renderTypingStatusOnUserCards({ reason: "typing-indicator-empty" });
    return;
  }
  let textHtml = "";
  if (users.length === 1) {
    textHtml = `<span class="typingIndicatorName">${esc(users[0].displayName || "Someone")}</span> is typing`;
  } else if (users.length === 2) {
    textHtml = `<span class="typingIndicatorName">${esc(users[0].displayName || "Someone")}</span> and <span class="typingIndicatorName">${esc(users[1].displayName || "Someone")}</span> are typing`;
  } else {
    textHtml = "Several people are typing";
  }
  setElementHtmlIfChanged(el, `${textHtml}<span class="typingIndicatorDots" aria-hidden="true"><i></i><i></i><i></i></span>`);
  el.hidden = false;
  el.classList.add("is-visible");
  logTypingDebug("render", { contextKey: key, count: users.length });
  renderTypingStatusOnUserCards({ reason: "typing-indicator" });
}

function sweepTypingUsers(reason = "expiry") {
  const now = Date.now();
  let changedActive = false;
  let changedAny = false;
  for (const [contextKey, map] of typingUsersByContextKey.entries()) {
    let changed = false;
    for (const [userId, entry] of map.entries()) {
      if (now - Number(entry?.lastSeenAt || 0) > TYPING_STALE_MS) {
        map.delete(userId);
        changed = true;
        changedAny = true;
        logTypingDebug("expire_user", { contextKey, userId, reason });
        if (String(contextKey || "").startsWith("inbox:")) logTypingInboxDebug("expire", { contextKey, senderUserId: userId, reason });
      }
    }
    if (!map.size) typingUsersByContextKey.delete(contextKey);
    if (changed && contextKey === typingActiveContextKey) changedActive = true;
  }
  if (changedActive) renderTypingIndicator(typingActiveContextKey);
  else if (changedAny) renderTypingStatusOnUserCards({ reason: `typing-expiry:${reason}` });
}

function scheduleTypingExpirySweep() {
  if (typingExpiryTimer) return;
  typingExpiryTimer = setInterval(() => sweepTypingUsers("interval"), 1000);
}

function clearTypingBlurStopTimer() {
  if (!typingBlurStopTimer) return;
  clearTimeout(typingBlurStopTimer);
  typingBlurStopTimer = 0;
}

function getTypingInboxSenderPayload(type = "typing_start", context = typingActiveContext, basePayload = null) {
  const payload = basePayload || getCurrentTypingUserPayload(context, type);
  if (!payload) return null;
  const senderUserId = normId(payload.userId || payload.senderUserId || state.user?.id || "");
  if (!senderUserId) return null;
  return {
    type,
    contextType: context?.contextType || payload.contextType || "dm",
    conversationId: normId(context?.conversationId || payload.conversationId || ""),
    senderUserId,
    senderDisplayName: String(payload.displayName || state.me?.display_name || state.me?.username || "Someone").trim() || "Someone",
    senderAvatarUrl: String(payload.avatarUrl || state.me?.avatar_url || "").trim(),
    sentAt: new Date().toISOString(),
  };
}

function getKnownGroupTypingRecipientIds(context = typingActiveContext) {
  const convId = normId(context?.conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return [];
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  const activeMeta = activeConvId === convId ? (state.activeDm || {}) : {};
  const cachedMeta = getConversationMeta(convId) || {};
  const row = (state.groupDms || []).find((entry) => normId(entry?.conversationId || "") === convId) || null;
  const meId = normId(state.user?.id || "");
  return normalizeUuidArray([
    ...(Array.isArray(activeMeta?.memberIds) ? activeMeta.memberIds : []),
    ...(Array.isArray(cachedMeta?.memberIds) ? cachedMeta.memberIds : []),
    ...(Array.isArray(row?.memberIds) ? row.memberIds : []),
  ]).filter((uid) => uid && uid !== meId);
}

async function resolveTypingInboxRecipientsForContext(context = typingActiveContext) {
  const ctx = context || typingActiveContext;
  const contextType = String(ctx?.contextType || "").trim().toLowerCase();
  const convId = normId(ctx?.conversationId || "");
  const meId = normId(state.user?.id || "");
  if (!meId || !convId) return [];
  if (contextType === "dm") {
    let peerId = "";
    const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
    if (activeConvId === convId) peerId = normId(getActiveDmPeerUserId?.() || state.activeDm?.otherUserId || state.activeDm?.other_user_id || callOtherUserId || "");
    peerId = peerId || normId(dmConversationPeerCache.get(convId) || "");
    const cachedMeta = getConversationMeta(convId) || {};
    peerId = peerId || normId(cachedMeta?.otherUserId || cachedMeta?.other_user_id || "");
    if (!peerId && typeof resolveConversationPeerUserId === "function") {
      try { peerId = normId(await resolveConversationPeerUserId(convId, "", { triggerReason: "typing_inbox_dm_recipient" }) || ""); } catch (_) { peerId = ""; }
    }
    if (!peerId || peerId === meId) return [];
    return [peerId];
  }
  if (contextType === "group_dm") {
    let ids = getKnownGroupTypingRecipientIds(ctx);
    if (!ids.length && typeof getGroupConversationMemberIds === "function") {
      try { ids = await getGroupConversationMemberIds(convId, { includeSelf: false, force: false }); } catch (_) { ids = []; }
    }
    ids = normalizeUuidArray(ids).filter((uid) => uid && uid !== meId);
    if (!ids.length) logTypingInboxDebug("group_participants_missing", { conversationId: convId, contextType });
    return ids;
  }
  return [];
}

function getTypingInboxGroupName(context = typingActiveContext) {
  const convId = normId(context?.conversationId || "");
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  const active = activeConvId === convId ? (state.activeDm || {}) : {};
  const meta = getConversationMeta(convId) || {};
  const row = (state.groupDms || []).find((entry) => normId(entry?.conversationId || "") === convId) || null;
  return String(active?.displayName || active?.name || meta?.displayName || meta?.name || row?.name || "Group DM").trim() || "Group DM";
}

function getOrCreateTypingInboxOutboundChannel(recipientUserId = "") {
  const uid = normId(recipientUserId || "");
  if (!uid) return null;
  const existing = typingInboxOutboundChannelsByRecipientUserId.get(uid);
  if (existing?.channel) return existing;
  const channelName = getTypingInboxChannelName(uid);
  if (!channelName) return null;
  const entry = { channel: null, status: "created", readyPromise: null, readyResolved: false, readyTimer: 0 };
  const channel = supabase.channel(channelName, { config: { broadcast: { self: false } } });
  entry.channel = channel;
  entry.readyPromise = new Promise((resolve) => {
    const finish = () => {
      if (entry.readyResolved) return;
      entry.readyResolved = true;
      if (entry.readyTimer) clearTimeout(entry.readyTimer);
      entry.readyTimer = 0;
      resolve(channel);
    };
    entry.readyTimer = setTimeout(finish, 900);
    channel.subscribe((status) => {
      entry.status = status;
      if (status === "SUBSCRIBED" || status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") finish();
    });
  });
  typingInboxOutboundChannelsByRecipientUserId.set(uid, entry);
  return entry;
}

function unsubscribeTypingInboxOutboundChannels(reason = "outbound_cleanup") {
  typingInboxOutboundChannelsByRecipientUserId.forEach((entry, recipientUserId) => {
    if (entry?.readyTimer) clearTimeout(entry.readyTimer);
    try { if (entry?.channel) supabase.removeChannel(entry.channel); } catch (_) {}
    logTypingInboxDebug("unsubscribe", { reason, recipientUserId, outbound: true });
  });
  typingInboxOutboundChannelsByRecipientUserId.clear();
}

async function sendTypingInboxPayload(recipientUserId = "", payload = {}) {
  const recipientId = normId(recipientUserId || "");
  if (!recipientId || !payload?.senderUserId || recipientId === normId(payload.senderUserId || "")) return false;
  const entry = getOrCreateTypingInboxOutboundChannel(recipientId);
  if (!entry?.channel) return false;
  try {
    await entry.readyPromise;
    await entry.channel.send({ type: "broadcast", event: "typing_inbox", payload: { ...payload, recipientUserId: recipientId } });
    logTypingInboxDebug(payload.type === "typing_stop" ? "send_stop" : "send_start", {
      senderUserId: payload.senderUserId,
      recipientUserId: recipientId,
      conversationId: payload.conversationId || "",
      contextType: payload.contextType || "",
    });
    return true;
  } catch (error) {
    logTypingInboxDebug("send_error", { recipientUserId: recipientId, message: String(error?.message || error || "unknown_error") });
    return false;
  }
}

async function sendTypingInboxBroadcasts(type = "typing_start", context = typingActiveContext, basePayload = null) {
  const ctx = context || typingActiveContext;
  const contextType = String(ctx?.contextType || "").trim().toLowerCase();
  if (contextType !== "dm" && contextType !== "group_dm") return false;
  const payload = getTypingInboxSenderPayload(type, ctx, basePayload);
  if (!payload) return false;
  const recipients = await resolveTypingInboxRecipientsForContext(ctx);
  if (!recipients.length) {
    logTypingInboxDebug("send_skipped_no_recipients", { senderUserId: payload.senderUserId, conversationId: payload.conversationId, contextType });
    return false;
  }
  const groupName = contextType === "group_dm" ? getTypingInboxGroupName(ctx) : "";
  const results = await Promise.allSettled(recipients.map((recipientUserId) => sendTypingInboxPayload(recipientUserId, {
    ...payload,
    groupName,
  })));
  return results.some((result) => result.status === "fulfilled" && result.value === true);
}

function normalizeIncomingTypingInboxPayload(payload = {}) {
  const type = String(payload?.type || "typing_start").trim().toLowerCase() === "typing_stop" ? "typing_stop" : "typing_start";
  const senderUserId = normId(payload?.senderUserId || payload?.sender_user_id || payload?.userId || payload?.user_id || "");
  const recipientUserId = normId(payload?.recipientUserId || payload?.recipient_user_id || "");
  const contextTypeRaw = String(payload?.contextType || payload?.context_type || "dm").trim().toLowerCase();
  const contextType = contextTypeRaw === "group" || contextTypeRaw === "group_dm" ? "group_dm" : "dm";
  const conversationId = normId(payload?.conversationId || payload?.conversation_id || "");
  if (!senderUserId) return null;
  const contextKey = contextType === "group_dm" && conversationId
    ? `inbox:group:${conversationId}:${senderUserId}`
    : `inbox:dm:${senderUserId}`;
  return {
    type,
    contextKey,
    userId: senderUserId,
    displayName: String(payload?.senderDisplayName || payload?.sender_display_name || payload?.displayName || payload?.display_name || payload?.username || "Someone").trim() || "Someone",
    avatarUrl: String(payload?.senderAvatarUrl || payload?.sender_avatar_url || payload?.avatarUrl || payload?.avatar_url || "").trim(),
    recipientUserId,
    conversationId,
    contextType,
    groupName: String(payload?.groupName || payload?.group_name || "").trim(),
    lastSeenAt: Date.now(),
  };
}

function handleIncomingTypingInboxBroadcast(rawPayload = {}) {
  const entry = normalizeIncomingTypingInboxPayload(rawPayload);
  if (!entry) return;
  const selfId = normId(state.user?.id || "");
  if (entry.recipientUserId && selfId && entry.recipientUserId !== selfId) {
    logTypingInboxDebug("receive_skipped_recipient_mismatch", { senderUserId: entry.userId, recipientUserId: entry.recipientUserId, currentUserId: selfId });
    return;
  }
  if (entry.userId === selfId && !isSelfTypingStatusDebugEnabled()) {
    logTypingInboxDebug("receive_skipped_self", { senderUserId: entry.userId, conversationId: entry.conversationId, contextType: entry.contextType });
    return;
  }
  let map = typingUsersByContextKey.get(entry.contextKey);
  if (!map) {
    map = new Map();
    typingUsersByContextKey.set(entry.contextKey, map);
  }
  if (entry.type === "typing_stop") {
    map.delete(entry.userId);
    if (!map.size) typingUsersByContextKey.delete(entry.contextKey);
    logTypingInboxDebug("receive_stop", { senderUserId: entry.userId, recipientUserId: entry.recipientUserId, conversationId: entry.conversationId, contextType: entry.contextType });
  } else {
    map.set(entry.userId, entry);
    logTypingInboxDebug("receive_start", { senderUserId: entry.userId, recipientUserId: entry.recipientUserId, conversationId: entry.conversationId, contextType: entry.contextType });
  }
  scheduleTypingExpirySweep();
  renderTypingStatusOnUserCards({ reason: "typing-inbox" });
}

function scheduleTypingInboxResubscribe(reason = "restart") {
  if (typingInboxRestartTimer || !state.user?.id) return;
  typingInboxRestartTimer = setTimeout(() => {
    typingInboxRestartTimer = 0;
    subscribeTypingInboxForCurrentUser(reason);
  }, 1200);
}

function unsubscribeTypingInboxForCurrentUser({ reason = "unsubscribe", clearState = false, clearOutbound = false } = {}) {
  if (typingInboxRestartTimer) {
    clearTimeout(typingInboxRestartTimer);
    typingInboxRestartTimer = 0;
  }
  const oldChannel = typingInboxChannel;
  const oldKey = typingInboxChannelKey;
  typingInboxChannel = null;
  typingInboxUserId = "";
  typingInboxChannelKey = "";
  if (oldChannel) {
    try { supabase.removeChannel(oldChannel); } catch (_) {}
    logTypingInboxDebug("unsubscribe", { reason, contextKey: oldKey });
  }
  if (clearOutbound) unsubscribeTypingInboxOutboundChannels(reason);
  if (clearState) {
    for (const key of Array.from(typingUsersByContextKey.keys())) {
      if (String(key || "").startsWith("inbox:")) typingUsersByContextKey.delete(key);
    }
    renderTypingStatusOnUserCards({ reason: `typing-inbox-${reason}` });
  }
}

function subscribeTypingInboxForCurrentUser(reason = "subscribe") {
  const userId = normId(state.user?.id || "");
  if (!userId) {
    unsubscribeTypingInboxForCurrentUser({ reason: `${reason}:no-user`, clearState: true, clearOutbound: true });
    return null;
  }
  const channelName = getTypingInboxChannelName(userId);
  if (!channelName) return null;
  if (typingInboxChannel && typingInboxUserId === userId && typingInboxChannelKey === channelName) return typingInboxChannel;
  unsubscribeTypingInboxForCurrentUser({ reason: `${reason}:switch-user`, clearState: true, clearOutbound: true });
  const channel = supabase.channel(channelName, { config: { broadcast: { self: false } } });
  typingInboxChannel = channel;
  typingInboxUserId = userId;
  typingInboxChannelKey = channelName;
  channel
    .on("broadcast", { event: "typing_inbox" }, (payload) => {
      handleIncomingTypingInboxBroadcast(payload?.payload || payload || {});
    })
    .subscribe((status) => {
      logTypingInboxDebug("subscribe", { status, reason, userId, channelName });
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        if (typingInboxUserId === userId) scheduleTypingInboxResubscribe(`restart:${String(status || "")}`);
      }
    });
  exposeAltaraTypingDebugHelper();
  return channel;
}

async function sendTypingBroadcast(type = "typing_start", context = typingActiveContext, channel = typingRealtimeChannel) {
  if (!context?.key) return false;
  const payload = getCurrentTypingUserPayload(context, type);
  if (!payload) return false;
  void sendTypingInboxBroadcasts(type, context, payload).catch((error) => {
    logTypingInboxDebug("send_error", { contextKey: context.key, message: String(error?.message || error || "unknown_error") });
  });
  if (!channel || typeof channel.send !== "function") return false;
  try {
    await channel.send({ type: "broadcast", event: "typing", payload });
    const now = Date.now();
    if (type === "typing_start") typingLastSentStartAtByContextKey.set(context.key, now);
    else typingLastSentStopAtByContextKey.set(context.key, now);
    logTypingDebug(type === "typing_start" ? "send_start" : "send_stop", {
      contextKey: context.key,
      contextType: context.contextType,
      conversationId: context.conversationId,
      serverId: context.serverId,
      channelId: context.channelId,
    });
    return true;
  } catch (error) {
    logTypingDebug("send_error", { contextKey: context.key, type, message: String(error?.message || error || "unknown_error") });
    return false;
  }
}

function sendTypingStart({ force = false, reason = "input" } = {}) {
  const context = getTypingContext();
  if (!context?.key || context.key !== typingActiveContextKey) return;
  const now = Date.now();
  const last = Number(typingLastSentStartAtByContextKey.get(context.key) || 0);
  if (!force && now - last < TYPING_START_THROTTLE_MS) return;
  typingIsLocalTyping = true;
  void sendTypingBroadcast("typing_start", context, typingRealtimeChannel);
  logTypingDebug("start_requested", { reason, contextKey: context.key, throttled: false });
}

function sendTypingStop({ force = false, reason = "stop", context = typingActiveContext, channel = typingRealtimeChannel } = {}) {
  clearTypingBlurStopTimer();
  if (!context?.key) return;
  if (!force && !typingIsLocalTyping) return;
  typingIsLocalTyping = false;
  void sendTypingBroadcast("typing_stop", context, channel);
  logTypingDebug("stop_requested", { reason, contextKey: context.key });
}

function handleTypingComposerInput(value = "") {
  const inputText = String(value || "");
  if (!getTypingContext()) return;
  if (inputText.length) sendTypingStart({ reason: "input" });
  else sendTypingStop({ force: true, reason: "input-empty" });
}

function scheduleTypingBlurStop() {
  clearTypingBlurStopTimer();
  typingBlurStopTimer = setTimeout(() => {
    typingBlurStopTimer = 0;
    sendTypingStop({ force: true, reason: "blur" });
  }, TYPING_BLUR_STOP_DELAY_MS);
}

function normalizeIncomingTypingPayload(payload = {}) {
  const userId = normId(payload?.userId || payload?.user_id || "");
  const type = String(payload?.type || "typing_start").trim().toLowerCase() === "typing_stop" ? "typing_stop" : "typing_start";
  const contextKey = getTypingContextKeyFromPayload(payload);
  if (!userId || !contextKey) return null;
  return {
    type,
    contextKey,
    userId,
    displayName: String(payload?.displayName || payload?.display_name || payload?.username || "Someone").trim() || "Someone",
    avatarUrl: String(payload?.avatarUrl || payload?.avatar_url || "").trim(),
    lastSeenAt: Date.now(),
  };
}

function handleIncomingTypingBroadcast(rawPayload = {}, options = {}) {
  const entry = normalizeIncomingTypingPayload(rawPayload);
  if (!entry) return;
  const selfId = normId(state.user?.id || "");
  if (entry.userId === selfId && !isSelfTypingStatusDebugEnabled()) {
    logTypingDebug("skipped_self", { contextKey: entry.contextKey, userId: entry.userId, source: options?.source || "active" });
    return;
  }
  let map = typingUsersByContextKey.get(entry.contextKey);
  if (!map) {
    map = new Map();
    typingUsersByContextKey.set(entry.contextKey, map);
  }
  if (entry.type === "typing_stop") {
    map.delete(entry.userId);
    if (!map.size) typingUsersByContextKey.delete(entry.contextKey);
    logTypingDebug(options?.source === "sidebar" ? "sidebar_receive_stop" : "receive_stop", { contextKey: entry.contextKey, userId: entry.userId });
  } else {
    map.set(entry.userId, entry);
    logTypingDebug(options?.source === "sidebar" ? "sidebar_receive_start" : "receive_start", { contextKey: entry.contextKey, userId: entry.userId, displayName: entry.displayName });
  }
  if (entry.contextKey === typingActiveContextKey) renderTypingIndicator(entry.contextKey);
  else renderTypingStatusOnUserCards({ reason: options?.source === "sidebar" ? "sidebar-typing-received" : "typing-received-nonactive" });
}

function unsubscribeTypingContext({ sendStop = true, reason = "unsubscribe" } = {}) {
  const oldContext = typingActiveContext;
  const oldChannel = typingRealtimeChannel;
  if (sendStop && oldContext?.key && oldChannel) sendTypingStop({ force: true, reason, context: oldContext, channel: oldChannel });
  clearTypingBlurStopTimer();
  typingIsLocalTyping = false;
  typingActiveContext = null;
  typingActiveContextKey = "";
  typingActiveChannelName = "";
  typingRealtimeChannel = null;
  if (oldChannel) {
    try { supabase.removeChannel(oldChannel); } catch (_) {}
  }
  const el = ensureTypingIndicatorElement();
  if (el) {
    el.hidden = true;
    el.classList.remove("is-visible");
    setElementHtmlIfChanged(el, "");
  }
  clearTypingStatusOnUserCards({ reason });
  setTimeout(() => syncTypingSidebarSubscriptionsFromVisibleRows(`${reason}:active-unsubscribe`), 0);
  if (oldContext?.key || oldChannel) logTypingDebug("unsubscribe", { reason, contextKey: oldContext?.key || "" });
}

function unsubscribeTypingSidebarContext(contextKey = "", reason = "sidebar_unsubscribe") {
  const key = String(contextKey || "").trim();
  if (!key) return;
  const channel = typingSidebarSubscriptionsByContextKey.get(key);
  typingSidebarSubscriptionsByContextKey.delete(key);
  typingSidebarContextMetaByKey.delete(key);
  if (channel) {
    try { supabase.removeChannel(channel); } catch (_) {}
    logTypingDebug("sidebar_unsubscribe", { reason, contextKey: key });
  }
}

function unsubscribeTypingSidebarSubscriptions(reason = "sidebar_unsubscribe_all") {
  Array.from(typingSidebarSubscriptionsByContextKey.keys()).forEach((key) => unsubscribeTypingSidebarContext(key, reason));
}

function subscribeTypingSidebarContext(context, reason = "sidebar_subscribe") {
  if (!context?.key || !context?.channelName || context.key === typingActiveContextKey) return false;
  if (typingSidebarSubscriptionsByContextKey.has(context.key)) {
    typingSidebarContextMetaByKey.set(context.key, context);
    return true;
  }
  const channel = supabase.channel(context.channelName, { config: { broadcast: { self: false } } });
  typingSidebarSubscriptionsByContextKey.set(context.key, channel);
  typingSidebarContextMetaByKey.set(context.key, context);
  channel
    .on("broadcast", { event: "typing" }, (payload) => {
      handleIncomingTypingBroadcast(payload?.payload || payload || {}, { source: "sidebar" });
    })
    .subscribe((status) => {
      logTypingDebug("sidebar_subscription_ready", {
        status,
        reason,
        contextKey: context.key,
        contextType: context.contextType,
        conversationId: context.conversationId,
      });
    });
  logTypingDebug("sidebar_subscribe", {
    reason,
    contextKey: context.key,
    contextType: context.contextType,
    conversationId: context.conversationId,
  });
  return true;
}

function syncTypingSidebarSubscriptionsFromVisibleRows(reason = "sidebar_sync") {
  if (!state.user?.id) return;
  const contexts = collectVisibleTypingSidebarContexts();
  logTypingDebug("sidebar_contexts_scan", {
    reason,
    visibleCount: contexts.size,
    visibleContextKeys: Array.from(contexts.keys()),
    subscribedContextKeys: Array.from(typingSidebarSubscriptionsByContextKey.keys()),
  });
  for (const key of Array.from(typingSidebarSubscriptionsByContextKey.keys())) {
    if (!contexts.has(key) || key === typingActiveContextKey) unsubscribeTypingSidebarContext(key, `${reason}:stale`);
  }
  contexts.forEach((context, key) => {
    if (key === typingActiveContextKey) {
      unsubscribeTypingSidebarContext(key, `${reason}:active-context`);
      return;
    }
    subscribeTypingSidebarContext(context, reason);
  });
  scheduleTypingExpirySweep();
  exposeAltaraTypingDebugHelper();
  renderTypingStatusOnUserCards({ reason });
}

function subscribeTypingForCurrentContext(reason = "subscribe") {
  const context = getTypingContext();
  if (!context?.key) {
    unsubscribeTypingContext({ sendStop: true, reason: `${reason}:no-context` });
    subscribeTypingInboxForCurrentUser(`${reason}:inbox-only`);
    return null;
  }
  if (typingRealtimeChannel && typingActiveContextKey === context.key) {
    typingActiveContext = context;
    subscribeTypingInboxForCurrentUser(`${reason}:active-existing`);
    renderTypingIndicator(context.key);
    syncTypingSidebarSubscriptionsFromVisibleRows(`${reason}:active-existing`);
    return context;
  }
  unsubscribeTypingContext({ sendStop: true, reason: `${reason}:switch` });
  const channel = supabase.channel(context.channelName, { config: { broadcast: { self: false } } });
  typingRealtimeChannel = channel;
  typingActiveContext = context;
  typingActiveContextKey = context.key;
  typingActiveChannelName = context.channelName;
  channel
    .on("broadcast", { event: "typing" }, (payload) => {
      handleIncomingTypingBroadcast(payload?.payload || payload || {});
    })
    .subscribe((status) => {
      logTypingDebug("subscription_ready", { status, reason, contextKey: context.key, channelName: context.channelName });
      if (status === "SUBSCRIBED") {
        const input = document.getElementById("dmInput");
        if (input && String(input.value || "").length) sendTypingStart({ force: true, reason: "resubscribe-input" });
      }
    });
  scheduleTypingExpirySweep();
  subscribeTypingInboxForCurrentUser(`${reason}:active-context`);
  ensureTypingIndicatorElement();
  renderTypingIndicator(context.key);
  syncTypingSidebarSubscriptionsFromVisibleRows(`${reason}:active-context`);
  exposeAltaraTypingDebugHelper();
  logTypingDebug("subscribe", {
    reason,
    contextKey: context.key,
    channelName: context.channelName,
    contextType: context.contextType,
    conversationId: context.conversationId,
    serverId: context.serverId,
    channelId: context.channelId,
  });
  return context;
}

function exposeAltaraTypingDebugHelper() {
  try {
    if (typeof window === "undefined" || !isAltaraLocalhostDebugContext()) return;
    window.__ALTARA_DEBUG_TYPING_STATE__ = () => {
      const input = document.getElementById("dmInput");
      const users = getTypingUsersForCurrentContext().map((entry) => ({
        userId: entry.userId,
        displayName: entry.displayName,
        avatarUrlPresent: !!entry.avatarUrl,
        ageMs: Math.max(0, Date.now() - Number(entry.lastSeenAt || 0)),
      }));
      const allTypingContexts = Array.from(typingUsersByContextKey.entries()).map(([contextKey, map]) => ({
        contextKey,
        ...parseTypingContextKey(contextKey),
        users: Array.from(map.values()).map((entry) => ({
          userId: entry.userId,
          displayName: entry.displayName,
          ageMs: Math.max(0, Date.now() - Number(entry.lastSeenAt || 0)),
        })),
      }));
      const inboxTypingContexts = allTypingContexts.filter((entry) => String(entry.contextKey || "").startsWith("inbox:"));
      const inboxTypingUsers = inboxTypingContexts
        .filter((entry) => entry.contextType === "inbox_dm")
        .flatMap((entry) => (entry.users || []).map((user) => ({ ...user, contextKey: entry.contextKey })));
      const inboxTypingGroups = inboxTypingContexts
        .filter((entry) => entry.contextType === "inbox_group")
        .map((entry) => ({
          contextKey: entry.contextKey,
          conversationId: entry.conversationId,
          senderUserId: entry.userId,
          users: entry.users || [],
        }));
      return {
        activeContextKey: typingActiveContextKey,
        activeChannelName: typingActiveChannelName,
        subscribed: !!typingRealtimeChannel,
        typingInboxSubscribed: !!typingInboxChannel,
        typingInboxChannelKey,
        inboxTypingUsers,
        inboxTypingGroups,
        typingUsers: users,
        activeTypingUsers: users,
        allTypingContexts,
        sidebarSubscribedContextKeys: Array.from(typingSidebarSubscriptionsByContextKey.keys()),
        visibleSidebarTypingContextKeys: Array.from(collectVisibleTypingSidebarContexts().keys()),
        dmConversationIdByUserId: Object.fromEntries(Array.from(dmConversationIdByUserId.entries())),
        currentContextKey: typingActiveContextKey,
        ...getTypingStatusDebugCardSummary(),
        lastSentStartAt: Number(typingLastSentStartAtByContextKey.get(typingActiveContextKey) || 0) || null,
        lastSentStopAt: Number(typingLastSentStopAtByContextKey.get(typingActiveContextKey) || 0) || null,
        currentInputLength: String(input?.value || "").length,
      };
    };
  } catch (_) {}
}
