function getContextMenuNow() {
  return (typeof performance !== "undefined" && typeof performance.now === "function")
    ? performance.now()
    : Date.now();
}

function isContextMenuDebugEnabled() {
  try { return localStorage.getItem("altara.debug.contextMenu") === "1"; } catch (_) { return false; }
}

function logContextMenuDebug(message, detail = {}) {
  if (!isContextMenuDebugEnabled()) return;
  try { console.debug(`[ContextMenu] ${message}`, detail); } catch (_) {}
}

function getContextMenuEventPath(event) {
  try {
    if (typeof event?.composedPath === "function") return event.composedPath();
  } catch (_) {}
  return [];
}

function eventPathContainsElement(event, element) {
  if (!event || !element) return false;
  const path = getContextMenuEventPath(event);
  if (Array.isArray(path) && path.includes(element)) return true;
  const target = eventTargetElement(event);
  return !!(target && (target === element || element.contains?.(target)));
}

function eventPathContainsSelector(event, selector = "") {
  if (!event || !selector) return false;
  const path = getContextMenuEventPath(event);
  if (Array.isArray(path) && path.some((entry) => entry?.matches?.(selector))) return true;
  const target = eventTargetElement(event);
  return !!target?.closest?.(selector);
}

function isDmUserListMenuOpen() {
  const menu = document.getElementById("dmUserListMenu");
  return !!menu?.classList?.contains("is-open");
}

const ALTARA_CONTEXT_MENU_CLOSE_REASONS = new Set([
  "action",
  "outside_click",
  "escape",
  "route_change",
  "target_removed",
  "open_other_menu",
  "manual_close",
]);

const ALTARA_CONTEXT_MENU_SURFACE_SELECTOR = [
  "#botContextMenu",
  "#serverPanelMenu",
  "#serverFolderMenu",
  "#serverChannelItemMenu",
  "#serverVoiceMemberMenu",
  "#dmGroupMemberMenu",
  "#dmGroupListMenu",
  "#dmUserListMenu",
  "#dmMuteDurationMenu",
  "#dmUserRoleMenu",
  "#msgActionMenu",
  "#meStatusMenu",
  ".msgMenu--submenu",
].join(",");

const altaraContextMenuDebugState = {
  currentType: "",
  targetId: "",
  targetKind: "",
  menuId: "",
  openedAt: 0,
  lastCloseReason: "",
  lastOpenReason: "",
  lastOutsideClickWasInsideMenu: false,
  screenX: null,
  screenY: null,
  anchorEl: null,
};

function normalizeAltaraContextMenuCloseReason(reason = "action", fallback = "action") {
  const raw = String(reason || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
  if (ALTARA_CONTEXT_MENU_CLOSE_REASONS.has(raw)) return raw;
  if (raw === "outside" || raw === "outsideclick") return "outside_click";
  if (raw === "esc") return "escape";
  if (raw === "another_menu" || raw === "bot_menu" || raw === "open_other" || raw === "other_menu") return "open_other_menu";
  if (raw === "manual" || raw === "manual_close") return "manual_close";
  if (raw === "sidebar_render" || raw === "scroll" || raw === "resize" || raw === "refresh" || raw === "timer" || raw === "mouseleave") return fallback;
  return ALTARA_CONTEXT_MENU_CLOSE_REASONS.has(fallback) ? fallback : "action";
}

function setAltaraContextMenuOpen({
  type = "",
  targetId = "",
  targetKind = "",
  menuId = "",
  anchorEl = null,
  point = null,
  reason = "contextmenu",
} = {}) {
  altaraContextMenuDebugState.currentType = String(type || "").trim();
  altaraContextMenuDebugState.targetId = String(targetId || "").trim();
  altaraContextMenuDebugState.targetKind = String(targetKind || "").trim();
  altaraContextMenuDebugState.menuId = String(menuId || "").trim();
  altaraContextMenuDebugState.openedAt = getContextMenuNow();
  altaraContextMenuDebugState.lastOpenReason = String(reason || "contextmenu").trim() || "contextmenu";
  altaraContextMenuDebugState.lastOutsideClickWasInsideMenu = false;
  const px = Number(point?.clientX ?? point?.x ?? point?.left ?? NaN);
  const py = Number(point?.clientY ?? point?.y ?? point?.top ?? NaN);
  altaraContextMenuDebugState.screenX = Number.isFinite(px) ? px : null;
  altaraContextMenuDebugState.screenY = Number.isFinite(py) ? py : null;
  altaraContextMenuDebugState.anchorEl = anchorEl || null;
}

function recordAltaraContextMenuClose(type = "", reason = "action") {
  const normalizedReason = normalizeAltaraContextMenuCloseReason(reason, "action");
  altaraContextMenuDebugState.lastCloseReason = normalizedReason;
  const normalizedType = String(type || "").trim();
  if (!normalizedType || !altaraContextMenuDebugState.currentType || altaraContextMenuDebugState.currentType === normalizedType) {
    altaraContextMenuDebugState.currentType = "";
    altaraContextMenuDebugState.targetId = "";
    altaraContextMenuDebugState.targetKind = "";
    altaraContextMenuDebugState.menuId = "";
    altaraContextMenuDebugState.openedAt = 0;
    altaraContextMenuDebugState.screenX = null;
    altaraContextMenuDebugState.screenY = null;
    altaraContextMenuDebugState.anchorEl = null;
  }
  return normalizedReason;
}

function isAltaraContextMenuEventInside(event, menuEl, anchorEl = null) {
  const target = eventTargetElement(event);
  const anchor = anchorEl || altaraContextMenuDebugState.anchorEl || null;
  const inside = !!(
    (menuEl && eventPathContainsElement(event, menuEl))
    || (anchor && eventPathContainsElement(event, anchor))
    || eventPathContainsSelector(event, ALTARA_CONTEXT_MENU_SURFACE_SELECTOR)
    || target?.closest?.("[data-msg-more]")
  );
  altaraContextMenuDebugState.lastOutsideClickWasInsideMenu = inside;
  return inside;
}

function bindStableAltaraContextMenu(menu, {
  type = "context",
  close = null,
  getAnchor = null,
} = {}) {
  if (!menu || menu.dataset.stableContextMenuBound === "1") return;
  menu.dataset.stableContextMenuBound = "1";

  document.addEventListener("pointerdown", (event) => {
    if (!menu.classList.contains("is-open")) return;
    const target = eventTargetElement(event);
    if (!target) return;
    const anchor = typeof getAnchor === "function" ? getAnchor() : null;
    if (isAltaraContextMenuEventInside(event, menu, anchor)) return;
    const pointerType = String(event?.pointerType || "").trim().toLowerCase();
    const isPrimaryOutside = event?.button === 0 || pointerType === "touch" || pointerType === "pen";
    if (!isPrimaryOutside) return;
    if (typeof close === "function") close("outside_click");
  }, true);

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (!menu.classList.contains("is-open")) return;
    if (typeof close === "function") close("escape");
  });

  menu.addEventListener("pointerdown", (event) => {
    event.stopPropagation();
  });
  menu.addEventListener("click", (event) => {
    event.stopPropagation();
  });
  menu.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
  });
}

function isAnyAltaraContextMenuOpen() {
  if (altaraContextMenuDebugState.currentType) return true;
  try {
    return !!document.querySelector(".msgMenu.is-open");
  } catch (_) {
    return false;
  }
}

function findAltaraContextMenuElementByAttr(selector = "", attrNames = [], value = "") {
  const needle = String(value || "").trim();
  if (!selector || !needle) return null;
  try {
    const nodes = document.querySelectorAll(selector);
    for (const node of nodes) {
      if (!(node instanceof HTMLElement)) continue;
      for (const attr of attrNames) {
        if (String(node.getAttribute(attr) || "").trim() === needle) return node;
      }
    }
  } catch (_) {}
  return null;
}

function isServerChannelContextMenuTargetAvailable(serverId = "", channels = null, categories = null) {
  const target = serverChannelItemMenuTarget || null;
  if (!target) return false;
  const sid = normId(serverId || target.serverId || "");
  const targetServerId = normId(target.serverId || "");
  if (sid && targetServerId && sid !== targetServerId) return false;

  const itemType = String(target.itemType || "channel").trim().toLowerCase();
  if (itemType === "category") {
    const categoryId = normId(target.categoryId || altaraContextMenuDebugState.targetId || "");
    if (!categoryId) return false;
    const source = Array.isArray(categories)
      ? categories
      : (serverChannelCategoryListByServerId.get(sid) || []);
    if (Array.isArray(source) && source.some((cat) => normId(cat?.id || cat?.categoryId || "") === categoryId)) return true;
    return !!findAltaraContextMenuElementByAttr(
      "[data-server-category-toggle], [data-server-category-id]",
      ["data-server-category-toggle", "data-server-category-id"],
      categoryId
    );
  }

  const convId = normId(target.conversationId || altaraContextMenuDebugState.targetId || "");
  const channelId = normId(target.channelId || "");
  const source = Array.isArray(channels)
    ? channels
    : (serverChannelListByServerId.get(sid) || []);
  if (Array.isArray(source) && source.some((ch) => {
    const rowConvId = normId(ch?.conversationId || ch?.conversation_id || "");
    const rowChannelId = normId(ch?.id || ch?.channelId || ch?.channel_id || "");
    return (!!convId && rowConvId === convId) || (!!channelId && rowChannelId === channelId);
  })) return true;

  if (convId && findAltaraContextMenuElementByAttr(
    "[data-server-channel-open], [data-server-voice-channel]",
    ["data-server-channel-open", "data-server-voice-channel"],
    convId
  )) return true;
  if (channelId && findAltaraContextMenuElementByAttr(
    "[data-server-channel-id]",
    ["data-server-channel-id"],
    channelId
  )) return true;
  return false;
}

function getAltaraContextMenuTargetStillExists() {
  const type = String(altaraContextMenuDebugState.currentType || "").trim();
  const targetId = String(altaraContextMenuDebugState.targetId || "").trim();
  if (!type) return false;
  if (type === "server_channel") return isServerChannelContextMenuTargetAvailable();
  if (type === "message") return !!findAltaraContextMenuElementByAttr(".msg[data-msg-id]", ["data-msg-id"], targetId);
  if (type === "bot") {
    return !!findAltaraContextMenuElementByAttr(
      "[data-bot-profile-bot-id], [data-bot-profile-public-id]",
      ["data-bot-profile-bot-id", "data-bot-profile-public-id"],
      targetId
    ) || !!document.getElementById(altaraContextMenuDebugState.menuId || "");
  }
  if (type === "user_member" || type === "group_member" || type === "server_voice_member") {
    return !!findAltaraContextMenuElementByAttr(
      "[data-user-list-id], [data-server-voice-member-id], [data-group-member-id]",
      ["data-user-list-id", "data-server-voice-member-id", "data-group-member-id"],
      targetId
    ) || !!document.getElementById(altaraContextMenuDebugState.menuId || "");
  }
  if (type === "server" || type === "server_folder" || type === "group_dm" || type === "me_status") {
    const menu = document.getElementById(altaraContextMenuDebugState.menuId || "");
    return !!menu?.classList?.contains("is-open");
  }
  const menu = document.getElementById(altaraContextMenuDebugState.menuId || "");
  return !!menu?.classList?.contains("is-open");
}

function reconcileServerChannelContextMenuAfterRender(serverId = "", channels = [], categories = []) {
  const menu = document.getElementById("serverChannelItemMenu");
  if (!menu?.classList?.contains("is-open")) return;
  const target = serverChannelItemMenuTarget || null;
  if (!target) {
    closeServerChannelItemMenu("target_removed");
    return;
  }
  const sid = normId(serverId || "");
  const targetServerId = normId(target.serverId || "");
  if (sid && targetServerId && sid !== targetServerId) {
    closeServerChannelItemMenu("route_change");
    return;
  }
  if (!isServerChannelContextMenuTargetAvailable(sid, channels, categories)) {
    closeServerChannelItemMenu("target_removed");
  }
}


function installAltaraContextMenuDebugHelper() {
  try {
    if (typeof window === "undefined") return;
    window.__ALTARA_CONTEXT_MENU_DEBUG__ = () => ({
      currentMenuType: altaraContextMenuDebugState.currentType || (isDmUserListMenuOpen() ? "user_member" : ""),
      targetId: altaraContextMenuDebugState.targetId || dmUserListMenuState?.targetUserId || dmUserListMenuTargetUserId || "",
      targetKind: altaraContextMenuDebugState.targetKind || dmUserListMenuState?.rowType || "",
      menuId: altaraContextMenuDebugState.menuId || "",
      openedAt: altaraContextMenuDebugState.openedAt || dmUserListMenuState?.openedAt || 0,
      lastCloseReason: altaraContextMenuDebugState.lastCloseReason || normalizeAltaraContextMenuCloseReason(dmUserListMenuLastCloseReason || "", "action"),
      lastOpenReason: altaraContextMenuDebugState.lastOpenReason || "",
      screenPosition: (Number.isFinite(altaraContextMenuDebugState.screenX) && Number.isFinite(altaraContextMenuDebugState.screenY))
        ? { x: altaraContextMenuDebugState.screenX, y: altaraContextMenuDebugState.screenY }
        : null,
      lastOutsidePointerWasInsideMenu: !!altaraContextMenuDebugState.lastOutsidePointerWasInsideMenu,
      lastOutsideClickWasInsideMenu: !!altaraContextMenuDebugState.lastOutsideClickWasInsideMenu,
      targetStillExists: getAltaraContextMenuTargetStillExists(),
    });
  } catch (_) {}
}

