function normalizePopoverAnchorId(type = "", anchorId = "") {
  const normalized = String(anchorId || "").trim();
  return normalized || String(type || "popover").trim() || "popover";
}

function bindActivePopoverManagerOnce() {
  if (activePopoverManagerBound) return;
  activePopoverManagerBound = true;
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (closeActivePopover()) event.stopPropagation();
  }, true);
}

function isSameActivePopover(type = "", anchorId = "") {
  if (!activePopover) return false;
  const normalizedType = String(type || "").trim();
  const normalizedAnchorId = normalizePopoverAnchorId(normalizedType, anchorId);
  return activePopover.type === normalizedType && activePopover.anchorId === normalizedAnchorId;
}

function setActivePopover({ type = "", anchorId = "", anchorEl = null, close = null } = {}) {
  const normalizedType = String(type || "").trim();
  if (!normalizedType || typeof close !== "function") return null;
  bindActivePopoverManagerOnce();
  const normalizedAnchorId = normalizePopoverAnchorId(normalizedType, anchorId);
  activePopover = {
    type: normalizedType,
    anchorId: normalizedAnchorId,
    anchorEl: anchorEl instanceof HTMLElement ? anchorEl : null,
    close,
  };
  return activePopover;
}

function clearActivePopover(type = "", anchorId = "") {
  if (!activePopover) return;
  const normalizedType = String(type || "").trim();
  if (normalizedType && activePopover.type !== normalizedType) return;
  const normalizedAnchorId = anchorId ? normalizePopoverAnchorId(normalizedType || activePopover.type, anchorId) : "";
  if (normalizedAnchorId && activePopover.anchorId !== normalizedAnchorId) return;
  activePopover = null;
}

function closeActivePopover({ exceptType = "", exceptAnchorId = "" } = {}) {
  const current = activePopover;
  if (!current) return false;
  const normalizedExceptType = String(exceptType || "").trim();
  const normalizedExceptAnchorId = exceptAnchorId
    ? normalizePopoverAnchorId(normalizedExceptType || current.type, exceptAnchorId)
    : "";
  if (normalizedExceptType && current.type === normalizedExceptType) {
    if (!normalizedExceptAnchorId || current.anchorId === normalizedExceptAnchorId) return false;
  }
  activePopover = null;
  try { current.close?.(); } catch (error) { console.warn("popover close failed", error?.message || error); }
  return true;
}

function togglePopover({ type = "", anchorId = "", anchorEl = null, open = null, close = null } = {}) {
  const normalizedType = String(type || "").trim();
  if (!normalizedType || typeof open !== "function" || typeof close !== "function") return false;
  const normalizedAnchorId = normalizePopoverAnchorId(normalizedType, anchorId);
  if (isSameActivePopover(normalizedType, normalizedAnchorId)) {
    closeActivePopover();
    return false;
  }
  closeActivePopover();
  open();
  setActivePopover({ type: normalizedType, anchorId: normalizedAnchorId, anchorEl, close });
  return true;
}
