function installAltaraServerInviteDebugHelpers() {
  if (typeof window === "undefined") return;
  window.altaraDebugServerInvites = window.altaraDebugServerInvites || {};
  window.altaraDebugServerInvites.inspectStatus = function inspectStatus() {
    const sid = normId(serverInviteServerId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
    return {
      activeServerId: sid,
      currentUserId: normId(state.user?.id || ""),
      canInvite: getServerCapabilityMeta(sid).canInvite,
      inviteLinkCode: serverInviteLinkCode,
      inviteUrl: serverInviteLinkUrl,
      inviteTables: {
        server_invite_links: "used by invite preview/link flow when SQL is applied",
      },
      rpcAvailability: {
        create_server_invite_link: "checked on generate",
        preview_server_invite: "checked by invite card hydration",
        join_server_by_invite_code_safe: "checked on join",
        invite_server_members: "legacy/direct fallback only",
      },
      candidatesCount: getInvitableServerFriends(sid).length,
      pendingInvitesCount: pendingExternalServerInviteCode ? 1 : 0,
      busyUserId: serverInviteBusyUserId,
      lastInvitedUserId: serverInviteLastInvitedUserId,
    };
  };
  window.altaraDebugServerInvites.openInviteModal = function openInviteModal(serverId = "") {
    const sid = normId(serverId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
    return openServerInviteModal({
      serverId: sid,
      name: getServerRowById(sid)?.name || "Server",
      iconUrl: getServerRowById(sid)?.iconUrl || "",
    });
  };
  window.altaraDebugServerInvites.reloadCandidates = function reloadCandidates() {
    return reloadServerInviteCandidates({ force: true });
  };
  window.altaraDebugServerInvites.inspectCandidates = function inspectCandidates(serverId = "") {
    const sid = normId(serverId || serverInviteServerId || getActiveServerIdForSidebar?.() || "");
    return getInvitableServerFriends(sid);
  };
  window.altaraDebugServerInvites.createInviteForUser = function createInviteForUser(userId = "") {
    return sendServerInviteLinkToFriend(userId);
  };
  window.altaraDebugServerInvites.inspectPendingInvites = function inspectPendingInvites() {
    return {
      pendingExternalServerInviteCode,
      inviteCards: Array.from(document.querySelectorAll(".dmServerInviteCard[data-invite-code]")).map((card) => ({
        code: card.getAttribute("data-invite-code") || "",
        state: card.getAttribute("data-invite-state") || "",
        serverId: card.getAttribute("data-invite-server-id") || "",
        text: String(card.textContent || "").replace(/\s+/g, " ").trim(),
      })),
    };
  };
  window.altaraDebugServerInvites.inspectInviteCards = function inspectInviteCards() {
    return Array.from(document.querySelectorAll(".dmServerInviteCard[data-invite-code]")).map((card) => {
      const code = normalizeServerInviteCode(card.getAttribute("data-invite-code") || "");
      const preview = serverInvitePreviewStateByCode.get(code) || {};
      const serverId = card.getAttribute("data-invite-server-id") || preview.serverId || "";
      return {
        code,
        status: card.getAttribute("data-invite-state") || preview.status || "",
        serverId,
        serverName: preview.serverName || card.querySelector(".dmServerInviteName")?.textContent?.trim?.() || "",
        isBanned: preview.isBanned === true || !!serverInviteBannedStateByCode.get(code),
        alreadyMember: preview.alreadyMember === true,
        hasIcon: !!card.querySelector(".msgInviteCard__icon"),
        hasBanner: !!card.querySelector(".dmServerInviteHeroImg"),
        serverBannerUrl: preview.serverBannerUrl || card.querySelector(".dmServerInviteHeroImg")?.getAttribute?.("src") || "",
        previewStale: !!serverInvitePreviewStaleByCode.get(code),
        lastPreviewAt: preview.lastPreviewAt || "",
        lastProfileUpdateAt: preview.lastProfileUpdateAt || serverInvitePreviewProfileTouchedByCode.get(code) || "",
        lastBannerSetAt: preview.lastBannerSetAt || (normId(serverId || "") && lastServerBannerSetByServerId.get(normId(serverId || ""))?.at
          ? new Date(lastServerBannerSetByServerId.get(normId(serverId || "")).at).toISOString()
          : ""),
        lastBannerClearAt: preview.lastBannerClearAt || (normId(serverId || "") && lastServerBannerClearAtByServerId.get(normId(serverId || ""))
          ? new Date(lastServerBannerClearAtByServerId.get(normId(serverId || ""))).toISOString()
          : ""),
        subscribedToProfileUpdates: !!serverProfileBroadcastChannels.has(normId(serverId || "")),
        lastPreviewError: preview.lastPreviewError || "",
        buttonText: card.querySelector(".msgInviteCard__joinBtn")?.textContent?.trim?.() || "",
      };
    });
  };
  window.altaraDebugServerInvites.refreshInvitePreview = async function refreshInvitePreview(code = "") {
    const inviteCode = normalizeServerInviteCode(code || document.querySelector(".dmServerInviteCard[data-invite-code]")?.getAttribute?.("data-invite-code") || "");
    if (!inviteCode) return null;
    const preview = await previewServerInviteCode(inviteCode);
    refreshInviteCardsForCode(inviteCode);
    return preview;
  };
  window.altaraDebugServerInvites.inspectInviteState = function inspectInviteState(code = "") {
    const inviteCode = normalizeServerInviteCode(code || "");
    const preview = serverInvitePreviewStateByCode.get(inviteCode) || null;
    return {
      code: inviteCode,
      status: preview?.status || "",
      serverId: preview?.serverId || "",
      serverName: preview?.serverName || "",
      hasBanner: !!preview?.serverBannerUrl,
      serverBannerUrl: preview?.serverBannerUrl || "",
      previewSource: preview?.source || "",
      previewStale: !!serverInvitePreviewStaleByCode.get(inviteCode),
      lastProfileUpdateAt: preview?.lastProfileUpdateAt || serverInvitePreviewProfileTouchedByCode.get(inviteCode) || "",
      lastBannerSetAt: preview?.lastBannerSetAt || (normId(preview?.serverId || "") && lastServerBannerSetByServerId.get(normId(preview?.serverId || ""))?.at
        ? new Date(lastServerBannerSetByServerId.get(normId(preview?.serverId || "")).at).toISOString()
        : ""),
      lastBannerClearAt: preview?.lastBannerClearAt || (normId(preview?.serverId || "") && lastServerBannerClearAtByServerId.get(normId(preview?.serverId || ""))
        ? new Date(lastServerBannerClearAtByServerId.get(normId(preview?.serverId || ""))).toISOString()
        : ""),
      preview,
      banned: serverInviteBannedStateByCode.get(inviteCode) || null,
      cards: inviteCode ? Array.from(document.querySelectorAll(`.dmServerInviteCard[data-invite-code="${typeof CSS !== "undefined" && CSS.escape ? CSS.escape(inviteCode) : inviteCode.replace(/["\\]/g, "\\$&")}"]`)).map((card) => ({
        state: card.getAttribute("data-invite-state") || "",
        serverId: card.getAttribute("data-invite-server-id") || "",
        hasBanner: !!card.querySelector(".dmServerInviteHeroImg"),
        text: String(card.textContent || "").replace(/\s+/g, " ").trim(),
      })) : [],
    };
  };
  window.altaraDebugServerInvites.refreshVisibleInviteCardsForServer = function debugRefreshVisibleInviteCardsForServer(serverId = "") {
    return refreshVisibleInviteCardsForServer(serverId, "debug");
  };
  window.altaraDebugServerInvites.acceptInvite = function acceptInvite(inviteIdOrCode = "") {
    return joinServerFromInviteCode(inviteIdOrCode, { openConversation: true, showFeedback: true, source: "debug" });
  };
}
installAltaraServerInviteDebugHelpers();

function installAltaraServerProfileDebugHelpers() {
  if (typeof window === "undefined") return;
  window.altaraDebugCropper = window.altaraDebugCropper || {};
  window.altaraDebugCropper.inspect = function inspectCropper() {
    const modal = document.getElementById("bannerEditorModal");
    const settingsModal = document.getElementById("serverSettingsModal");
    const canvas = document.getElementById("bannerEditorCanvas");
    const zoom = document.getElementById("bannerEditorZoom");
    const wrap = canvas?.parentElement || null;
    const rect = canvas?.getBoundingClientRect?.() || null;
    const info = rect ? { cssW: Math.max(1, rect.width), cssH: Math.max(1, rect.height), dpr: window.devicePixelRatio || 1 } : null;
    const crop = info ? getBannerCropMetrics(info) : null;
    const modalStyle = modal ? getComputedStyle(modal) : null;
    const settingsStyle = settingsModal ? getComputedStyle(settingsModal) : null;
    const zIndex = Number.parseInt(modalStyle?.zIndex || "0", 10) || 0;
    const settingsZ = Number.parseInt(settingsStyle?.zIndex || "0", 10) || 0;
    return {
      isOpen: !!(modal && !modal.classList.contains("hidden")),
      target: BE.target || "",
      title: modal?.querySelector?.(".modalTitle")?.textContent?.trim?.() || "",
      aspectRatio: Number(BE.cropRatio || 0),
      modalParent: modal?.parentElement?.tagName || "",
      zIndex,
      topLayer: modal?.classList?.contains("altaraServerBannerEditorTopLayer") || false,
      imageLoaded: !!BE.img,
      naturalWidth: Number(BE.img?.naturalWidth || BE.img?.width || 0),
      naturalHeight: Number(BE.img?.naturalHeight || BE.img?.height || 0),
      cropWidth: Number(crop?.w || 0),
      cropHeight: Number(crop?.h || 0),
      scale: Number(BE.scale || 0),
      minScale: Number(BE.minScale || 0),
      maxScale: Number(BE.maxScale || 0),
      offsetX: Number(BE.ox || 0),
      offsetY: Number(BE.oy || 0),
      sliderValue: String(zoom?.value || ""),
      canDrag: !!BE._dragBound && !!wrap && getComputedStyle(wrap).pointerEvents !== "none",
      canZoom: !!zoom && !zoom.disabled,
      lastPointerEvent: BE.lastPointerEvent || "",
      lastWheelEvent: BE.lastWheelEvent || "",
      processingState: BE.processingState || "idle",
      lastApplyAt: BE.lastApplyAt || 0,
      lastCloseAt: BE.lastCloseAt || 0,
      lastError: BE.lastError || "",
      cropperAboveSettings: zIndex > settingsZ,
    };
  };
  window.altaraDebugCropper.forceClose = function forceCloseCropper() {
    hideBannerEditor();
    return window.altaraDebugCropper.inspect();
  };
  window.altaraDebugCropper.testExport = async function testExportCropper() {
    const exported = await exportOptimizedServerBannerBlob();
    return {
      ok: !!exported?.blob,
      size: Number(exported?.blob?.size || 0),
      width: Number(exported?.width || 0),
      height: Number(exported?.height || 0),
      type: String(exported?.mime || exported?.blob?.type || ""),
      ext: String(exported?.ext || ""),
    };
  };
  window.altaraDebugServerProfile = window.altaraDebugServerProfile || {};
  const resolveDebugServerProfileServerId = (serverId = "") => {
    const direct = normId(serverId || serverSettingsServerId || "");
    if (direct) return direct;
    if (typeof getActiveServerIdForSidebar === "function") {
      const sidebarId = normId(getActiveServerIdForSidebar() || "");
      if (sidebarId) return sidebarId;
    }
    if (typeof getActiveServerContext === "function") {
      const ctxId = normId(getActiveServerContext()?.serverId || "");
      if (ctxId) return ctxId;
    }
    return "";
  };
  window.altaraDebugServerProfile.inspectBanner = async function inspectBanner(serverId = "") {
    const sid = resolveDebugServerProfileServerId(serverId);
    const cached = sid ? getServerRowById(sid) : null;
    const welcome = sid ? await readServerWelcomeChannelFromTable(sid).catch((error) => ({ error })) : null;
    let dbRow = null;
    let dbError = null;
    if (sid) {
      const res = await supabase
        .from("servers")
        .select("id, name, icon_url, banner_url")
        .eq("id", sid)
        .maybeSingle();
      dbRow = res?.data || null;
      dbError = res?.error || null;
    }
    return {
      serverId: sid,
      bannerUrl: normalizeBannerUrl(cached?.bannerUrl || dbRow?.banner_url || ""),
      cachedBannerUrl: normalizeBannerUrl(cached?.bannerUrl || ""),
      dbBannerUrl: normalizeBannerUrl(dbRow?.banner_url || ""),
      hasCachedBanner: !!normalizeBannerUrl(cached?.bannerUrl || ""),
      hasDbBanner: !!normalizeBannerUrl(dbRow?.banner_url || ""),
      pendingBanner: !!serverSettingsBannerFile,
      pendingBannerIsGif: !!serverSettingsBannerIsGif,
      pendingRemove: !!serverSettingsBannerRemoved,
      processingState: BE.processingState || "idle",
      pendingBlobSize: Number(serverSettingsBannerFile?.size || 0),
      pendingMimeType: String(serverSettingsBannerFile?.type || serverSettingsBannerOutputMeta?.outputType || ""),
      previewUrl: serverSettingsBannerPreviewUrl || "",
      uploadPath: serverSettingsBannerFile ? `${normId(state.user?.id || "")}/server-banners/${sid || "draft"}_*.${String(serverSettingsBannerOutputMeta?.outputExt || "").trim() || "webp"}` : "",
      cropperPreset: "server_banner_16_9",
      outputSize: Number(serverSettingsBannerOutputMeta?.outputSize || 0),
      outputWidth: Number(serverSettingsBannerOutputMeta?.outputWidth || 0),
      outputHeight: Number(serverSettingsBannerOutputMeta?.outputHeight || 0),
      outputType: String(serverSettingsBannerOutputMeta?.outputType || ""),
      welcomeChannelRaw: normId(cached?.welcomeConversationId || serverSettingsWelcomeChannelId || ""),
      welcomeChannelResolved: normId(welcome?.welcomeConversationId || ""),
      updateRpcSignature: "update_server_profile_v2(p_server_id,p_name,p_icon_url,p_welcome_channel_id,p_banner_url)",
      dbError: dbError ? { message: dbError.message, code: dbError.code, details: dbError.details } : null,
    };
  };
  window.altaraDebugServerProfile.inspectRealtime = function inspectServerProfileRealtime(serverId = "") {
    const sid = resolveDebugServerProfileServerId(serverId);
    const row = sid ? getServerRowById(sid) : null;
    const inviteCards = sid ? getVisibleInviteCardsForServer(sid) : [];
    const pendingCodes = [];
    for (const [code, stale] of serverInvitePreviewStaleByCode.entries()) {
      const preview = serverInvitePreviewStateByCode.get(code) || null;
      if (normId(preview?.serverId || "") === sid) pendingCodes.push({ code, ...(stale || {}) });
    }
    return {
      serverId: sid,
      subscribed: !!serverProfileBroadcastChannels.has(sid),
      channels: Array.from(serverProfileBroadcastChannels.keys()).map((id) => getServerProfileBroadcastChannelName(id)),
      focusRepreviewBound: !!serverProfileFocusRepreviewBound,
      focusRepreviewTimerActive: !!serverProfileFocusRepreviewTimer,
      subscriptionsReady: !!state.user?.id,
      lastProfileBroadcastReceivedAt: lastServerProfileBroadcastReceivedAt,
      lastProfileBroadcastSentAt: lastServerProfileBroadcastSentAt,
      lastProfileBroadcastPayload: lastServerProfileBroadcastPayload,
      lastBannerSetAt: lastServerBannerSetByServerId.get(sid)?.at
        ? new Date(lastServerBannerSetByServerId.get(sid).at).toISOString()
        : "",
      lastBannerClearAt: lastServerBannerClearAtByServerId.get(sid)
        ? new Date(lastServerBannerClearAtByServerId.get(sid)).toISOString()
        : "",
      bannerWasExplicitlySet: !!lastServerBannerSetByServerId.get(sid)?.url,
      bannerWasExplicitlyCleared: !!lastServerBannerClearAtByServerId.get(sid),
      lastServersPostgresUpdateAt,
      cachedBannerUrl: normalizeBannerUrl(row?.bannerUrl || ""),
      activeServerBannerUrl: normalizeBannerUrl(getActiveServerContext?.()?.bannerUrl || state.activeDm?.bannerUrl || ""),
      settingsBannerUrl: normId(serverSettingsServerId || "") === sid ? normalizeBannerUrl(serverSettingsBannerUrl || "") : "",
      inviteCardsLinked: inviteCards.length,
      pendingRepreviewCount: pendingCodes.length,
      pendingRepreviews: pendingCodes,
    };
  };
  window.altaraDebugServerProfile.broadcastProfileUpdate = function debugBroadcastProfileUpdate(serverId = "") {
    const sid = resolveDebugServerProfileServerId(serverId);
    const row = sid ? getServerRowById(sid) : null;
    if (!sid || !row) return { ok: false, error: "server_not_found" };
    const payload = {
      serverId: sid,
      name: row.name || "Server",
      iconUrl: row.iconUrl || "",
      bannerUrl: row.bannerUrl || "",
      welcomeChannelId: row.welcomeConversationId || "",
      updatedAt: new Date().toISOString(),
      sourceUserId: normId(state.user?.id || ""),
    };
    return broadcastServerProfileUpdate(sid, payload);
  };
  window.altaraDebugServerProfile.inspectBannerEditor = function inspectBannerEditor() {
    const cropper = window.altaraDebugCropper?.inspect?.() || {};
    const modal = document.getElementById("bannerEditorModal");
    const settingsModal = document.getElementById("serverSettingsModal");
    const settingsStyle = settingsModal ? getComputedStyle(settingsModal) : null;
    const settingsModalZIndex = Number.parseInt(settingsStyle?.zIndex || "0", 10) || 0;
    return {
      ...cropper,
      settingsModalZIndex,
      cropperAboveSettings: Number(cropper.zIndex || 0) > settingsModalZIndex,
      pointerEvents: modal
        ? getComputedStyle(modal).pointerEvents
        : "",
      focusTrapPaused: BE.target === "server_banner" && !!(modal && !modal.classList.contains("hidden")),
      selectedFileName: BE.selectedFileName || "",
      selectedFileSize: Number(BE.selectedFileSize || 0),
      serverPendingBanner: !!serverSettingsBannerFile,
      serverPendingRemove: !!serverSettingsBannerRemoved,
      serverPreviewUrl: serverSettingsBannerPreviewUrl || "",
    };
  };
  window.altaraDebugServerProfile.cancelBannerProcessing = function cancelBannerProcessing() {
    BE.processingState = "idle";
    BE.lastError = "";
    hideBannerEditor();
    const input = document.getElementById("serverSettingsBannerFile");
    if (input) input.value = "";
    clearServerSettingsSaveFeedback();
    logServerProfileBannerDebug("processing reset", { target: "server_banner" });
    return { ok: true, processingState: BE.processingState || "idle" };
  };
  window.altaraDebugServerProfile.inspectWelcomeChannel = async function inspectWelcomeChannel(serverId = "") {
    const sid = resolveDebugServerProfileServerId(serverId);
    const row = sid ? getServerRowById(sid) : null;
    const table = sid ? await readServerWelcomeChannelFromTable(sid).catch((error) => ({ error })) : null;
    const channels = sid ? await fetchServerChannelsForSidebar(sid, { force: false }).catch(() => []) : [];
    const raw = normId(table?.welcomeConversationId || row?.welcomeConversationId || serverSettingsWelcomeChannelId || "");
    const matched = (channels || []).find((ch) => normId(ch?.conversationId || "") === raw || normId(ch?.id || "") === raw) || null;
    return {
      serverId: sid,
      welcomeChannelRaw: raw,
      welcomeChannelResolved: normId(matched?.conversationId || raw || ""),
      matchedChannelId: normId(matched?.id || ""),
      matchedConversationId: normId(matched?.conversationId || ""),
      selectValue: normId(document.getElementById("serverSettingsWelcomeChannel")?.value || ""),
      storesCanonicalConversationId: true,
      table,
    };
  };
  window.altaraDebugServerProfile.testBannerCompression = async function testBannerCompression(file = null) {
    if (!file) return { ok: false, error: "Pass a File object from an input/drop event." };
    await openBannerEditor(file, state.user, {
      gifMode: false,
      cropRatio: 16 / 9,
      title: "Test Server Banner Compression",
      applyIdleText: "Test Compression",
      applyBusyText: "Processing...",
      onApply: async () => {
        const exported = await exportOptimizedServerBannerBlob();
        serverSettingsBannerOutputMeta = {
          outputSize: Number(exported?.blob?.size || 0),
          outputWidth: Number(exported?.width || 0),
          outputHeight: Number(exported?.height || 0),
          outputType: String(exported?.mime || exported?.blob?.type || ""),
          outputExt: String(exported?.ext || ""),
        };
        console.info("[server-settings] banner compression test", serverSettingsBannerOutputMeta);
      },
    });
    return { ok: true, message: "Use the banner editor Apply button to run compression." };
  };
  window.altaraDebugServerProfile.setBannerUrl = async function setBannerUrl(serverId = "", url = "") {
    const sid = resolveDebugServerProfileServerId(serverId);
    const row = sid ? getServerRowById(sid) : null;
    if (!sid || !row) return { ok: false, error: "server_not_found" };
    const bannerUrl = normalizeBannerUrl(url || "");
    const res = await updateServerProfileWithWelcomeRpc(sid, {
      name: row.name || "Server",
      iconUrl: row.iconUrl || "",
      welcomeChannelId: row.welcomeConversationId || "",
      bannerUrl,
      bannerTouched: true,
    });
    if (res?.error) return { ok: false, error: res.error };
    row.bannerUrl = bannerUrl;
    const payload = {
      serverId: sid,
      name: row.name || "Server",
      iconUrl: row.iconUrl || "",
      bannerUrl: bannerUrl ? bannerUrl : null,
      serverBannerUrl: bannerUrl ? bannerUrl : null,
      hasBanner: !!bannerUrl,
      bannerRemoved: !bannerUrl,
      welcomeChannelId: row.welcomeConversationId || "",
      updatedAt: new Date().toISOString(),
      sourceUserId: normId(state.user?.id || ""),
    };
    applyServerProfileUpdate(sid, payload, { source: "debug_set_banner", repreview: false });
    void broadcastServerProfileUpdate(sid, payload);
    void refreshVisibleInviteCardsForServer(sid, "debug_set_banner").catch(() => {});
    renderServerSettingsBannerPreview();
    return { ok: true, serverId: sid, bannerUrl, method: res?.method || "rpc" };
  };
  window.altaraDebugServerProfile.clearBanner = function clearBanner(serverId = "") {
    return window.altaraDebugServerProfile.setBannerUrl(serverId, "");
  };
}
installAltaraServerProfileDebugHelpers();

