function isDirectDmE2eeEnabled() {
  return DIRECT_DM_E2EE_ENABLED === true;
}

function isDirectDmE2eeDiagnosticsEnabled() {
  if (DIRECT_DM_E2EE_DIAGNOSTICS_ENABLED === true) return true;
  try {
    if (typeof window !== "undefined" && window.__ALTARA_DM_E2EE_DEBUG__ === true) return true;
  } catch (_) {}
  try {
    if (typeof localStorage === "undefined") return false;
    return String(localStorage.getItem(DIRECT_DM_E2EE_DIAGNOSTICS_STORAGE_KEY) || "").trim() === "1";
  } catch (_) {
    return false;
  }
}

