function getVisibleDmPrivacyConversationId() {
  const activeId = normId(activeDmId || "");
  const stateConvId = normId(state.activeDm?.conversationId || "");
  return activeId || stateConvId;
}

function getDmPrivacyBadgeSourceDebug(conversationId = "") {
  const convId = normId(conversationId || "");
  const cached = convId ? getConversationMeta(convId) : null;
  const activeStateConvId = normId(state.activeDm?.conversationId || "");
  const activeMatches = !!(convId && activeStateConvId === convId);
  const activeMeta = activeMatches ? (state.activeDm || {}) : null;
  const merged = { ...(cached || {}), ...(activeMeta || {}) };
  const meta = hasExplicitDmPrivacyMetaFields(merged) ? buildDmPrivacyMeta(merged, { fallbackKind: String(merged.kind || "dm").trim().toLowerCase() || "dm" }) : buildSafeStandardDmPrivacyMeta("pending_fetch");
  return {
    conversationId: convId,
    activeConversationId: getVisibleDmPrivacyConversationId(),
    state: normalizeDmPrivacyState(meta.dmPrivacyState),
    source: String(meta.dmPrivacySource || ""),
    usedCache: !!(cached && hasExplicitDmPrivacyMetaFields(cached)),
    usedActiveDm: !!(activeMeta && hasExplicitDmPrivacyMetaFields(activeMeta)),
  };
}

