function getRenderStackHint() {
  try {
    const stack = String(new Error().stack || "").split("\n").slice(2, 7)
      .map((line) => line.trim().replace(/^at\s+/, ""))
      .filter(Boolean);
    return stack.join(" <- ").slice(0, 500);
  } catch (_) {
    return "";
  }
}

