function getServerPermissionsRealtimeChannelName(serverId = "") {
  const sid = normId(serverId || "");
  // Batch 0A cache-bust: versioned so any stale, long-lived client connection
  // from before this hardening pass reconnects under a distinct channel name
  // rather than silently sharing state with the new permission-check logic.
  return sid ? `server-permissions-batch0a-v2:${sid}` : "";
}

function getServerIdFromPermissionsRealtimePayload(payload = null) {
  return normId(
    payload?.serverId
    || payload?.payload?.serverId
    || payload?.payload?.server_id
    || payload?.new?.server_id
    || payload?.old?.server_id
    || payload?.new?.id
    || payload?.old?.id
    || ""
  );
}

function teardownActiveServerPermissionsRealtime() {
  if (activeServerPermissionsRealtimeRefreshTimer) {
    clearTimeout(activeServerPermissionsRealtimeRefreshTimer);
    activeServerPermissionsRealtimeRefreshTimer = 0;
  }
  if (activeServerPermissionsRealtimeChannel) {
    try { supabase.removeChannel(activeServerPermissionsRealtimeChannel); } catch (_) {}
  }
  activeServerPermissionsRealtimeChannel = null;
  activeServerPermissionsRealtimeKey = "";
}

function setupActiveServerPermissionsRealtime(serverId = "") {
  const sid = normId(serverId || "");
  const key = getServerPermissionsRealtimeChannelName(sid);
  if (!sid || !state.user?.id || !key) {
    teardownActiveServerPermissionsRealtime();
    return null;
  }
  if (activeServerPermissionsRealtimeChannel && activeServerPermissionsRealtimeKey === key) {
    return activeServerPermissionsRealtimeChannel;
  }
  teardownActiveServerPermissionsRealtime();

  const onChange = (reason) => (payload) => {
    const eventPayload = payload?.payload || payload || {};
    const sourceClientId = String(eventPayload?.sourceClientId || "");
    const eventChannelId = normId(
      eventPayload?.channelId
      || payload?.new?.channel_id
      || payload?.old?.channel_id
      || ""
    );
    const editChannelId = normId(serverChannelCreateEditChannelId || "");
    if (
      sourceClientId
      && sourceClientId === serverChannelAccessClientId
      && Number(eventPayload?.saveNonce || 0) <= serverChannelCreateSaveNonce
    ) {
      return;
    }
    if (
      serverChannelCreateSaving
      && normId(serverChannelCreateServerId || "") === sid
      && ["server_channel_permission_overwrites_change", "permissions_broadcast"].includes(reason)
      && (!eventChannelId || !editChannelId || eventChannelId === editChannelId)
    ) {
      serverChannelCreateDeferredPermissionsRefresh = true;
      return;
    }
    if (reason === "server_members_change") {
      const eventType = String(payload?.eventType || "").toUpperCase();
      const row = payload?.new || payload?.old || {};
      if (eventType === "DELETE") {
        void handleServerMemberRemoved({
          serverId: row.server_id || sid,
          userId: row.user_id || "",
          reason: "member_removed",
          source: "postgres_delete",
        });
      } else if (eventType === "INSERT") {
        lastMemberJoinedPostgresReceivedAt = Date.now();
        serverMembersDebugLog("[server-members] postgres insert received", { serverId: row.server_id || sid, userId: row.user_id || "", payload });
        void handleServerMemberJoined({
          serverId: row.server_id || sid,
          userId: row.user_id || "",
          row,
          reason: "member_joined",
          source: "postgres_insert",
        });
      } else if (eventType === "UPDATE") {
        void handleServerMemberJoined({
          serverId: row.server_id || sid,
          userId: row.user_id || "",
          row,
          reason: "member_updated",
          source: "postgres_update",
        });
      }
    }
    scheduleActivePermissionsRefresh(reason, payload);
  };
  const channel = supabase
    .channel(key, { config: { broadcast: { self: false } } })
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "server_roles",
      filter: `server_id=eq.${sid}`,
    }, onChange("server_roles_change"))
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "server_role_members",
      filter: `server_id=eq.${sid}`,
    }, onChange("server_role_members_change"))
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "server_members",
      filter: `server_id=eq.${sid}`,
    }, onChange("server_members_change"))
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "server_channel_permission_overwrites",
      filter: `server_id=eq.${sid}`,
    }, onChange("server_channel_permission_overwrites_change"))
    .on("broadcast", { event: "server-permissions-changed-batch0a-v2" }, onChange("permissions_broadcast"))
    .subscribe((status, error) => {
      if (!["CHANNEL_ERROR", "TIMED_OUT", "CLOSED"].includes(String(status || ""))) return;
      const warnKey = `${key}:${status}`;
      if (activeServerPermissionsRealtimeWarned.has(warnKey)) return;
      activeServerPermissionsRealtimeWarned.add(warnKey);
      console.warn("[permissions] realtime subscription issue", {
        serverId: sid,
        channel: key,
        status,
        message: error?.message || error || "",
        error,
      });
    });

  activeServerPermissionsRealtimeChannel = channel;
  activeServerPermissionsRealtimeKey = key;
  return channel;
}

function scheduleActivePermissionsRefresh(reason = "permissions_realtime", payload = null) {
  const context = getActiveMessageComposerPermissionContext();
  const payloadServerId = getServerIdFromPermissionsRealtimePayload(payload);
  const sid = normId(payloadServerId || context.serverId || "");
  if (!sid || (context.serverId && sid !== context.serverId)) return;
  const normalizedReason = String(reason || "").toLowerCase();
  const channelAccessMayHaveChanged = normalizedReason.includes("server_channel_permission_overwrites")
    || normalizedReason.includes("private_channel")
    || normalizedReason.includes("channel_access");
  invalidateServerMessageHistoryForServer(sid, `permissions:${reason}`, {
    preserveValidSnapshot: !channelAccessMayHaveChanged,
  });

  if (context.isServerTextChannel && context.serverId === sid) {
    closeMessageMenu("permissions_refresh");
    setActiveMessageComposerPermissionState({
      key: context.key,
      loading: true,
      canSend: false,
      canReact: false,
      canAttach: false,
      reason: "checking",
      trace: null,
    });
    renderMessageComposer(reason);
  }

  if (activeServerPermissionsRealtimeRefreshTimer) clearTimeout(activeServerPermissionsRealtimeRefreshTimer);
  activeServerPermissionsRealtimeRefreshTimer = setTimeout(async () => {
    activeServerPermissionsRealtimeRefreshTimer = 0;
    const latest = getActiveMessageComposerPermissionContext();
    if (latest.serverId && latest.serverId !== sid) return;

    serverRoleListByServerId.delete(sid);
    serverRoleMemberMapByServerId.delete(sid);
    serverRolePermissionCacheFetchedAtByServerId.delete(sid);
    serverMemberListByServerId.delete(sid);
    Array.from(serverVoicePermissionDecisionByChannel.keys()).forEach((key) => {
      if (String(key || "").startsWith(`${sid}:`)) {
        serverVoicePermissionDecisionByChannel.delete(key);
      }
    });

    await fetchServerMembersForSidebar(sid, { force: true }).catch((error) => {
      console.warn("[permissions] failed to refresh members after permissions change", { serverId: sid, reason, message: error?.message || error, error });
      return [];
    });
    await ensureServerRolePermissionCache(sid, { force: true }).catch((error) => {
      console.warn("[permissions] failed to refresh roles after permissions change", { serverId: sid, reason, message: error?.message || error, error });
      return null;
    });
    await loadAllVisibleChannelPermissionOverwritesForServer(sid, { force: true }).catch((error) => {
      console.warn("[channel-permissions] failed to refresh overwrites", { serverId: sid, reason, message: error?.message || error, error });
      return null;
    });
    const { serverCtx } = getActiveServerChannelsRuntimeContext();
    if (serverCtx && normId(serverCtx.serverId || "") === sid) {
      renderServerChannelsPanel(
        serverCtx,
        serverChannelListByServerId.get(sid) || [],
        serverMemberListByServerId.get(sid) || [],
        serverChannelCategoryListByServerId.get(sid) || []
      );
    }
    scheduleServerVoiceOccupancyHydration(sid, `permissions:${reason}`, {
      delayMs: 0,
      ensureSubscription: true,
    });
    await reconcileActiveServerChannelAfterPermissionChange(reason);
    await refreshActiveMessageComposerPermission({ reason });
    await reconcileActiveServerMessageHistory(`permissions:${reason}`).catch((error) => {
      console.warn("[message-history] realtime reconciliation failed", {
        serverId: sid,
        reason,
        message: error?.message || error,
      });
    });
    await refreshAndReconcileCurrentServerVoicePermissions(`permissions:${reason}`, {
      force: true,
    }).catch((error) => {
      console.warn("[server-voice-permissions] active participant reconciliation failed", {
        serverId: sid,
        reason,
        message: error?.message || error,
      });
    });

    const settingsModal = document.getElementById("serverSettingsModal");
    const settingsOpen = !!(settingsModal && !settingsModal.classList.contains("hidden"));
    if (settingsOpen && normId(serverSettingsServerId || "") === sid) {
      await loadServerSettingsRolesForModal(sid, { force: true }).catch(() => {});
      renderServerSettingsMembersPanel();
      if (getServerSettingsActivePanelName() === "channels") {
        await loadServerSettingsChannels(sid, { force: true, reason: `permissions:${reason}` }).catch(() => false);
      }
    }
    if (activeChannelSettingsModalState && normId(activeChannelSettingsModalState.serverId || "") === sid) {
      await loadChannelPermissionOverwrites(sid, activeChannelSettingsModalState.channelId || "", { force: true }).catch(() => {});
      renderChannelSettingsModal();
    }
  }, 160);
}

async function emitServerPermissionsChangedBroadcast(serverId = "", payload = {}) {
  const sid = normId(serverId || "");
  const channelName = getServerPermissionsRealtimeChannelName(sid);
  if (!sid || !channelName || !state.user?.id) return false;
  const message = {
    serverId: sid,
    updatedAt: new Date().toISOString(),
    ...(payload || {}),
  };
  let channel = activeServerPermissionsRealtimeKey === channelName ? activeServerPermissionsRealtimeChannel : null;
  let temporaryChannel = false;
  let readyTimer = 0;
  try {
    if (!channel) {
      temporaryChannel = true;
      channel = supabase.channel(channelName, { config: { broadcast: { self: false } } });
      await new Promise((resolve) => {
        let done = false;
        const finish = () => {
          if (done) return;
          done = true;
          if (readyTimer) clearTimeout(readyTimer);
          resolve();
        };
        readyTimer = setTimeout(finish, 900);
        channel.subscribe((status) => {
          if (["SUBSCRIBED", "CHANNEL_ERROR", "TIMED_OUT", "CLOSED"].includes(String(status || ""))) finish();
        });
      });
    }
    await channel.send({ type: "broadcast", event: "server-permissions-changed-batch0a-v2", payload: message });
    return true;
  } catch (error) {
    console.warn("[permissions] failed to broadcast server permissions change", { serverId: sid, message: error?.message || error, error });
    return false;
  } finally {
    if (readyTimer) clearTimeout(readyTimer);
    if (temporaryChannel && channel) {
      try { supabase.removeChannel(channel); } catch (_) {}
    }
  }
}
function applyDmComposerEditUi(options = {}) {
  const renderReason = normalizeRenderReason(typeof options === "string" ? options : options?.reason || "composer-update");
  const input = document.getElementById("dmInput");
  logChatComposerRenderDiagnostic(renderReason, activeDmId || state.activeDm?.conversationId || "");
  const focusSnapshot = captureDmComposerFocusSnapshot(input);
  const send = document.getElementById("dmSend");
  const isEditing = !!(dmEditTarget?.id);
  const privateTextRequired = activeDmSupportsEncryptedTextOnly();
  const requestPreviewActive = isActiveMessageRequestPreview();
  const requestDraftActive = isActiveMessageRequestDraft();

  if (input) {
    const nextPlaceholder = requestDraftActive
      ? "Write a first message..."
      : (requestPreviewActive
        ? "Accept this request to reply."
        : (isEditing
          ? t("dm.privacy.edit_input", "Edit message...")
          : (privateTextRequired
            ? getDirectDmE2eeComposerPlaceholder()
            : t("dm.privacy.standard_input", "Message..."))));
    if (input.placeholder !== nextPlaceholder) input.placeholder = nextPlaceholder;
  }
  if (send && !send.disabled) {
    setElementTextIfChanged(send, isEditing ? "Save" : "Send");
  }
  applyDmComposerCapabilityUi();
  applyMessageComposerPermissionUi();
  updateDmComposerPreview();
  refreshDmComposerFormatToolbar(input);
  restoreDmComposerFocusSnapshot(focusSnapshot);
}

function createEmptyComposerStyleRangeState() {
  return {
    bold: [],
    italic: [],
    strike: [],
    code: [],
    spoiler: [],
  };
}

function cloneComposerStyleRangeState(inputState = dmComposerStyleRanges) {
  const src = inputState && typeof inputState === "object" ? inputState : {};
  const out = createEmptyComposerStyleRangeState();
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    out[mode] = Array.isArray(src[mode]) ? src[mode].slice() : [];
  }
  return out;
}

function normalizeComposerBooleanRanges(rawRanges, textLenInput) {
  const textLen = Math.max(0, Number(textLenInput) || 0);
  const list = Array.isArray(rawRanges) ? rawRanges : [];
  if (!textLen || !list.length) return [];

  const paint = new Array(textLen).fill(false);
  for (const item of list) {
    if (!item || typeof item !== "object") continue;
    let start = Math.max(0, Math.min(textLen, Number(item.start) || 0));
    let end = Math.max(0, Math.min(textLen, Number(item.end) || 0));
    if (end < start) [start, end] = [end, start];
    if (end <= start) continue;
    for (let i = start; i < end; i += 1) paint[i] = true;
  }

  const out = [];
  let i = 0;
  while (i < textLen) {
    if (!paint[i]) {
      i += 1;
      continue;
    }
    let j = i + 1;
    while (j < textLen && paint[j]) j += 1;
    out.push({ start: i, end: j });
    i = j;
  }
  return out;
}

function buildComposerBooleanPaint(textLenInput, rangesInput = []) {
  const textLen = Math.max(0, Number(textLenInput) || 0);
  const paint = new Array(textLen).fill(false);
  if (!textLen) return paint;
  const ranges = normalizeComposerBooleanRanges(rangesInput, textLen);
  for (const item of ranges) {
    const start = Math.max(0, Math.min(textLen, Number(item?.start) || 0));
    const end = Math.max(0, Math.min(textLen, Number(item?.end) || 0));
    if (end <= start) continue;
    for (let i = start; i < end; i += 1) paint[i] = true;
  }
  return paint;
}

function buildComposerBooleanRangesFromPaint(paintInput = []) {
  const paint = Array.isArray(paintInput) ? paintInput : [];
  if (!paint.length) return [];
  const out = [];
  let i = 0;
  while (i < paint.length) {
    if (!paint[i]) {
      i += 1;
      continue;
    }
    let j = i + 1;
    while (j < paint.length && paint[j]) j += 1;
    out.push({ start: i, end: j });
    i = j;
  }
  return out;
}

function pickComposerInsertionBoolean(prevPaint = [], changeStart = 0, removeEnd = 0) {
  if (!Array.isArray(prevPaint) || !prevPaint.length) return false;
  const len = prevPaint.length;
  const at = Math.max(0, Math.min(len, Number(changeStart) || 0));
  const remEnd = Math.max(at, Math.min(len, Number(removeEnd) || at));
  const rem = Math.max(0, remEnd - at);

  if (rem > 0) {
    let solid = null;
    let mixed = false;
    const end = Math.max(at, Math.min(len, at + rem));
    for (let i = at; i < end; i += 1) {
      const on = !!prevPaint[i];
      if (solid === null) {
        solid = on;
      } else if (solid !== on) {
        mixed = true;
        break;
      }
    }
    if (!mixed && solid !== null) return !!solid;
  }

  const left = at > 0 ? !!prevPaint[at - 1] : false;
  const right = at < len ? !!prevPaint[at] : false;
  if (left === right) return left;
  // Discord-like behavior: when inserting at a style boundary, follow the
  // style on the right side (caret side), so formatting does not "stick"
  // unexpectedly after a wrapped selection.
  return right;
}

function reconcileComposerBooleanRangesByDiff(prevTextInput = "", nextTextInput = "", rangesInput = []) {
  const prevText = String(prevTextInput || "");
  const nextText = String(nextTextInput || "");
  const prevLen = prevText.length;
  const nextLen = nextText.length;
  const normalized = normalizeComposerBooleanRanges(rangesInput, prevLen);
  if (!normalized.length) return [];
  if (prevText === nextText) return normalizeComposerBooleanRanges(normalized, nextLen);

  let prefix = 0;
  while (prefix < prevLen && prefix < nextLen && prevText.charCodeAt(prefix) === nextText.charCodeAt(prefix)) {
    prefix += 1;
  }

  let suffix = 0;
  while (
    suffix < (prevLen - prefix)
    && suffix < (nextLen - prefix)
    && prevText.charCodeAt(prevLen - 1 - suffix) === nextText.charCodeAt(nextLen - 1 - suffix)
  ) {
    suffix += 1;
  }

  const removedLen = Math.max(0, prevLen - prefix - suffix);
  const addedLen = Math.max(0, nextLen - prefix - suffix);
  const prevPaint = buildComposerBooleanPaint(prevLen, normalized);
  const nextPaint = new Array(nextLen).fill(false);
  const insertedState = pickComposerInsertionBoolean(prevPaint, prefix, prefix + removedLen);

  for (let i = 0; i < prefix; i += 1) nextPaint[i] = !!prevPaint[i];
  for (let i = 0; i < addedLen; i += 1) nextPaint[prefix + i] = insertedState;
  for (let i = 0; i < suffix; i += 1) {
    nextPaint[prefix + addedLen + i] = !!prevPaint[prevLen - suffix + i];
  }

  return normalizeComposerBooleanRanges(buildComposerBooleanRangesFromPaint(nextPaint), nextLen);
}

function reconcileDmComposerStyleRanges(nextTextInput = "") {
  const nextText = String(nextTextInput || "");
  if (reconcileDmComposerStyleRangesFromBeforeInput(nextText)) return;
  const prevText = String(dmComposerStyleRangesSnapshotText || "");
  const currentState = cloneComposerStyleRangeState(dmComposerStyleRanges);
  const hasAnyStyle = DM_COMPOSER_STYLE_ORDER.some((mode) => Array.isArray(currentState[mode]) && currentState[mode].length);
  if (!hasAnyStyle) {
    dmComposerStyleRangesSnapshotText = nextText;
    return;
  }
  if (!prevText || prevText === nextText) {
    dmComposerStyleRangesSnapshotText = nextText;
    return;
  }

  const nextState = createEmptyComposerStyleRangeState();
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    nextState[mode] = reconcileComposerBooleanRangesByDiff(prevText, nextText, currentState[mode]);
  }
  dmComposerStyleRanges = nextState;
  dmComposerStyleRangesSnapshotText = nextText;
}

function reconcileDmComposerStyleRangesFromBeforeInput(nextTextInput = "") {
  const ctx = dmComposerBeforeInputEdit;
  if (!ctx) return false;

  const nextText = String(nextTextInput || "");
  const prevText = String(ctx.prevText || "");
  if (prevText !== String(dmComposerStyleRangesSnapshotText || "")) return false;

  const currentState = cloneComposerStyleRangeState(dmComposerStyleRanges);
  const hasAnyStyle = DM_COMPOSER_STYLE_ORDER.some((mode) => Array.isArray(currentState[mode]) && currentState[mode].length);
  if (!hasAnyStyle) return false;

  const prevLen = prevText.length;
  const nextLen = nextText.length;
  const removeStart = Math.max(0, Math.min(prevLen, Number(ctx.removeStart) || 0));
  const removeEnd = Math.max(removeStart, Math.min(prevLen, Number(ctx.removeEnd) || removeStart));
  const removedLen = Math.max(0, removeEnd - removeStart);
  const insertedLen = nextLen - (prevLen - removedLen);
  if (!Number.isFinite(insertedLen) || insertedLen < 0) return false;

  const nextState = createEmptyComposerStyleRangeState();
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    const prevPaint = buildComposerBooleanPaint(prevLen, currentState[mode]);
    const nextPaint = [];
    if (removeStart > 0) nextPaint.push(...prevPaint.slice(0, removeStart));

    const insertedState = pickComposerInsertionBoolean(prevPaint, removeStart, removeEnd);
    for (let i = 0; i < insertedLen; i += 1) nextPaint.push(!!insertedState);

    if (removeEnd < prevLen) nextPaint.push(...prevPaint.slice(removeEnd));
    if (nextPaint.length !== nextLen) return false;

    nextState[mode] = normalizeComposerBooleanRanges(
      buildComposerBooleanRangesFromPaint(nextPaint),
      nextLen,
    );
  }

  dmComposerStyleRanges = nextState;
  dmComposerStyleRangesSnapshotText = nextText;
  return true;
}

function reconcileDmComposerSizeRanges(nextTextInput = "") {
  if (reconcileDmComposerSizeRangesFromBeforeInput(nextTextInput)) return;
  const nextText = String(nextTextInput || "");
  const prevText = String(dmComposerSizeRangesSnapshotText || "");
  if (!dmComposerSizeRanges.length) {
    dmComposerSizeRangesSnapshotText = nextText;
    return;
  }
  if (!prevText || prevText === nextText) {
    dmComposerSizeRangesSnapshotText = nextText;
    return;
  }

  const prevLen = prevText.length;
  const nextLen = nextText.length;
  let prefix = 0;
  while (prefix < prevLen && prefix < nextLen && prevText.charCodeAt(prefix) === nextText.charCodeAt(prefix)) {
    prefix += 1;
  }

  let suffix = 0;
  while (
    suffix < (prevLen - prefix)
    && suffix < (nextLen - prefix)
    && prevText.charCodeAt(prevLen - 1 - suffix) === nextText.charCodeAt(nextLen - 1 - suffix)
  ) {
    suffix += 1;
  }

  const addedLen = Math.max(0, nextLen - prefix - suffix);
  const prevPaint = buildComposerSizePaint(prevLen, dmComposerSizeRanges);
  const nextPaint = new Array(nextLen).fill(0);
  const insertedSize = pickComposerInsertionSize(prevPaint, prefix, prefix + Math.max(0, prevLen - prefix - suffix));

  for (let i = 0; i < prefix; i += 1) nextPaint[i] = Number(prevPaint[i] || 0);
  for (let i = 0; i < addedLen; i += 1) nextPaint[prefix + i] = Number(insertedSize || 0);
  for (let i = 0; i < suffix; i += 1) {
    nextPaint[prefix + addedLen + i] = Number(prevPaint[prevLen - suffix + i] || 0);
  }

  dmComposerSizeRanges = normalizeComposerSizeRanges(
    buildComposerSizeRangesFromPaint(nextPaint),
    nextLen,
  );
  dmComposerSizeRangesSnapshotText = nextText;
}

function reconcileDmComposerSizeRangesFromBeforeInput(nextTextInput = "") {
  const ctx = dmComposerBeforeInputEdit;
  if (!ctx || !dmComposerSizeRanges.length) return false;

  const nextText = String(nextTextInput || "");
  const prevText = String(ctx.prevText || "");
  if (prevText !== String(dmComposerSizeRangesSnapshotText || "")) return false;

  const prevLen = prevText.length;
  const nextLen = nextText.length;
  const removeStart = Math.max(0, Math.min(prevLen, Number(ctx.removeStart) || 0));
  const removeEnd = Math.max(removeStart, Math.min(prevLen, Number(ctx.removeEnd) || removeStart));
  const removedLen = Math.max(0, removeEnd - removeStart);
  const insertedLen = nextLen - (prevLen - removedLen);
  if (!Number.isFinite(insertedLen) || insertedLen < 0) return false;

  const prevPaint = buildComposerSizePaint(prevLen, dmComposerSizeRanges);
  const nextPaint = [];
  if (removeStart > 0) nextPaint.push(...prevPaint.slice(0, removeStart));

  const insertedSize = pickComposerInsertionSize(prevPaint, removeStart, removeEnd);
  for (let i = 0; i < insertedLen; i += 1) nextPaint.push(Number(insertedSize || 0));

  if (removeEnd < prevLen) nextPaint.push(...prevPaint.slice(removeEnd));
  if (nextPaint.length !== nextLen) return false;

  dmComposerSizeRanges = normalizeComposerSizeRanges(
    buildComposerSizeRangesFromPaint(nextPaint),
    nextLen,
  );
  dmComposerSizeRangesSnapshotText = nextText;
  return true;
}

function clearDmComposerColorRanges() {
  dmComposerColorRanges = [];
  dmComposerColorRangesSnapshotText = "";
  dmComposerSizeRanges = [];
  dmComposerSizeRangesSnapshotText = "";
  dmComposerSizeSelection = null;
  dmComposerSizeSliderActive = false;
  dmComposerStyleRanges = createEmptyComposerStyleRangeState();
  dmComposerStyleRangesSnapshotText = "";
  dmComposerBeforeInputEdit = null;
}

function parseComposerTextWithColorRanges(rawInput = "") {
  const src = String(rawInput || "");
  if (!src || src.toLowerCase().indexOf("[color=") < 0) {
    return { text: src, ranges: [] };
  }
  const out = [];
  const ranges = [];
  const re = /\[color=(#[0-9a-f]{3,6})\]([\s\S]*?)\[\/color\]/gi;
  let cursor = 0;
  let m;
  while ((m = re.exec(src))) {
    const fullStart = Number(m.index || 0);
    const fullEnd = Number(re.lastIndex || fullStart);
    if (fullStart > cursor) out.push(src.slice(cursor, fullStart));
    const color = normalizeMessageColorHex(m[1]);
    const inner = String(m[2] || "");
    const start = out.join("").length;
    out.push(inner);
    const end = out.join("").length;
    if (color && end > start) ranges.push({ start, end, color });
    cursor = fullEnd;
  }
  if (cursor < src.length) out.push(src.slice(cursor));
  return {
    text: out.join(""),
    ranges,
  };
}

function parseComposerTextWithTagRanges(rawInput = "", tagDef = null) {
  const src = String(rawInput || "");
  const open = String(tagDef?.open || "").trim();
  const close = String(tagDef?.close || "").trim();
  if (!src || !open || !close) return { text: src, ranges: [] };

  const openEsc = open.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const closeEsc = close.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`${openEsc}([\\s\\S]*?)${closeEsc}`, "gi");
  const out = [];
  const ranges = [];
  let cursor = 0;
  let m;
  while ((m = re.exec(src))) {
    const fullStart = Number(m.index || 0);
    const fullEnd = Number(re.lastIndex || fullStart);
    if (fullStart > cursor) out.push(src.slice(cursor, fullStart));
    const inner = String(m[1] || "");
    const start = out.join("").length;
    out.push(inner);
    const end = out.join("").length;
    if (end > start) ranges.push({ start, end });
    cursor = fullEnd;
  }
  if (cursor < src.length) out.push(src.slice(cursor));
  return {
    text: out.join(""),
    ranges,
  };
}

function normalizeComposerFontSize(valueInput) {
  const num = Number(valueInput);
  if (!Number.isFinite(num)) return DM_COMPOSER_FONT_SIZE_DEFAULT;
  const rounded = Math.round(num / DM_COMPOSER_FONT_SIZE_STEP) * DM_COMPOSER_FONT_SIZE_STEP;
  return Math.max(DM_COMPOSER_FONT_SIZE_MIN, Math.min(DM_COMPOSER_FONT_SIZE_MAX, rounded));
}

function normalizeComposerSizeRanges(rawRanges, textLenInput) {
  const textLen = Math.max(0, Number(textLenInput) || 0);
  const list = Array.isArray(rawRanges) ? rawRanges : [];
  if (!textLen || !list.length) return [];

  const paint = new Array(textLen).fill(0);
  for (const item of list) {
    if (!item || typeof item !== "object") continue;
    const size = normalizeComposerFontSize(item.size);
    if (size === DM_COMPOSER_FONT_SIZE_DEFAULT) continue;
    let start = Math.max(0, Math.min(textLen, Number(item.start) || 0));
    let end = Math.max(0, Math.min(textLen, Number(item.end) || 0));
    if (end < start) [start, end] = [end, start];
    if (end <= start) continue;
    for (let i = start; i < end; i += 1) paint[i] = size;
  }

  const out = [];
  let i = 0;
  while (i < textLen) {
    const size = Number(paint[i] || 0);
    if (!size) {
      i += 1;
      continue;
    }
    let j = i + 1;
    while (j < textLen && Number(paint[j] || 0) === size) j += 1;
    out.push({ start: i, end: j, size });
    i = j;
  }
  return out;
}

function buildComposerSizePaint(textLenInput, rangesInput = dmComposerSizeRanges) {
  const textLen = Math.max(0, Number(textLenInput) || 0);
  const paint = new Array(textLen).fill(0);
  if (!textLen) return paint;
  const ranges = normalizeComposerSizeRanges(rangesInput, textLen);
  for (const item of ranges) {
    const size = normalizeComposerFontSize(item?.size);
    if (!size || size === DM_COMPOSER_FONT_SIZE_DEFAULT) continue;
    const start = Math.max(0, Math.min(textLen, Number(item?.start) || 0));
    const end = Math.max(0, Math.min(textLen, Number(item?.end) || 0));
    if (end <= start) continue;
    for (let i = start; i < end; i += 1) paint[i] = size;
  }
  return paint;
}

function buildComposerSizeRangesFromPaint(paintInput = []) {
  const paint = Array.isArray(paintInput) ? paintInput : [];
  if (!paint.length) return [];
  const out = [];
  let i = 0;
  while (i < paint.length) {
    const size = Number(paint[i] || 0);
    if (!size) {
      i += 1;
      continue;
    }
    let j = i + 1;
    while (j < paint.length && Number(paint[j] || 0) === size) j += 1;
    out.push({ start: i, end: j, size });
    i = j;
  }
  return out;
}

function parseComposerTextWithFormattingRanges(rawInput = "") {
  const src = String(rawInput || "");
  if (!src) {
    return {
      text: "",
      colorRanges: [],
      sizeRanges: [],
      styleRanges: createEmptyComposerStyleRangeState(),
    };
  }

  const outChars = [];
  const colorPaint = [];
  const sizePaint = [];
  const stylePaintByMode = {};
  const styleDepthByMode = {};
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    stylePaintByMode[mode] = [];
    styleDepthByMode[mode] = 0;
  }

  const colorStack = [];
  const sizeStack = [];
  const getActiveColor = () => {
    if (!colorStack.length) return "";
    return normalizeMessageColorHex(colorStack[colorStack.length - 1]) || "";
  };
  const getActiveSize = () => {
    if (!sizeStack.length) return 0;
    const safe = normalizeComposerFontSize(sizeStack[sizeStack.length - 1]);
    return safe === DM_COMPOSER_FONT_SIZE_DEFAULT ? 0 : safe;
  };

  let i = 0;
  while (i < src.length) {
    if (src.charCodeAt(i) === 91) { // '['
      let consumed = 0;

      const colorOpen = src.slice(i).match(/^\[color=(#[0-9a-f]{3,6})\]/i);
      if (colorOpen) {
        const safeColor = normalizeMessageColorHex(colorOpen[1]);
        if (safeColor) colorStack.push(safeColor);
        consumed = colorOpen[0].length;
      } else {
        const colorClose = src.slice(i).match(/^\[\/color\]/i);
        if (colorClose) {
          if (colorStack.length) colorStack.pop();
          consumed = colorClose[0].length;
        }
      }

      if (!consumed) {
        const sizeOpen = src.slice(i).match(/^\[size=(\d{1,2})\]/i);
        if (sizeOpen) {
          const safeSize = normalizeComposerFontSize(sizeOpen[1]);
          sizeStack.push(safeSize);
          consumed = sizeOpen[0].length;
        } else {
          const sizeClose = src.slice(i).match(/^\[\/size\]/i);
          if (sizeClose) {
            if (sizeStack.length) sizeStack.pop();
            consumed = sizeClose[0].length;
          }
        }
      }

      if (!consumed) {
        for (const mode of DM_COMPOSER_STYLE_ORDER) {
          const openTag = String(DM_COMPOSER_STYLE_TAGS[mode]?.open || "");
          const closeTag = String(DM_COMPOSER_STYLE_TAGS[mode]?.close || "");
          if (openTag && src.slice(i, i + openTag.length).toLowerCase() === openTag.toLowerCase()) {
            styleDepthByMode[mode] = Math.max(0, Number(styleDepthByMode[mode] || 0) + 1);
            consumed = openTag.length;
            break;
          }
          if (closeTag && src.slice(i, i + closeTag.length).toLowerCase() === closeTag.toLowerCase()) {
            styleDepthByMode[mode] = Math.max(0, Number(styleDepthByMode[mode] || 0) - 1);
            consumed = closeTag.length;
            break;
          }
        }
      }

      if (consumed > 0) {
        i += consumed;
        continue;
      }
    }

    const ch = src[i];
    outChars.push(ch);
    colorPaint.push(getActiveColor());
    sizePaint.push(getActiveSize());
    for (const mode of DM_COMPOSER_STYLE_ORDER) {
      stylePaintByMode[mode].push(Number(styleDepthByMode[mode] || 0) > 0);
    }
    i += 1;
  }

  const text = outChars.join("");
  const colorRanges = normalizeComposerColorRanges(buildComposerColorRangesFromPaint(colorPaint), text.length);
  const sizeRanges = [];
  const styleRanges = createEmptyComposerStyleRangeState();
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    styleRanges[mode] = normalizeComposerBooleanRanges(
      buildComposerBooleanRangesFromPaint(stylePaintByMode[mode]),
      text.length,
    );
  }

  return { text, colorRanges, sizeRanges, styleRanges };
}

function normalizeComposerColorRanges(rawRanges, textLenInput) {
  const textLen = Math.max(0, Number(textLenInput) || 0);
  const list = Array.isArray(rawRanges) ? rawRanges : [];
  if (!textLen || !list.length) return [];

  const paint = new Array(textLen).fill("");
  for (const item of list) {
    if (!item || typeof item !== "object") continue;
    const color = normalizeMessageColorHex(item.color);
    if (!color) continue;
    let start = Math.max(0, Math.min(textLen, Number(item.start) || 0));
    let end = Math.max(0, Math.min(textLen, Number(item.end) || 0));
    if (end < start) [start, end] = [end, start];
    if (end <= start) continue;
    for (let i = start; i < end; i += 1) paint[i] = color;
  }

  const out = [];
  let i = 0;
  while (i < textLen) {
    const color = paint[i];
    if (!color) {
      i += 1;
      continue;
    }
    let j = i + 1;
    while (j < textLen && paint[j] === color) j += 1;
    out.push({ start: i, end: j, color });
    i = j;
  }
  return out;
}

function serializeComposerTextWithColorRanges(rawTextInput = "", rangesInput = dmComposerColorRanges) {
  const text = String(rawTextInput || "");
  if (!text) return "";
  const ranges = normalizeComposerColorRanges(rangesInput, text.length);
  if (!ranges.length) return text;

  let out = "";
  let cursor = 0;
  for (const r of ranges) {
    const start = Math.max(0, Math.min(text.length, Number(r.start) || 0));
    const end = Math.max(0, Math.min(text.length, Number(r.end) || 0));
    if (end <= start) continue;
    if (start > cursor) out += text.slice(cursor, start);
    out += `[color=${r.color}]${text.slice(start, end)}[/color]`;
    cursor = end;
  }
  if (cursor < text.length) out += text.slice(cursor);
  return out;
}

function serializeComposerTextWithFormattingRanges(
  rawTextInput = "",
  colorRangesInput = dmComposerColorRanges,
  sizeRangesInput = [],
  styleRangesInput = dmComposerStyleRanges,
) {
  const text = String(rawTextInput || "");
  if (!text) return "";
  const colorPaint = buildComposerColorPaint(text.length, colorRangesInput);
  const styleState = styleRangesInput && typeof styleRangesInput === "object"
    ? styleRangesInput
    : createEmptyComposerStyleRangeState();
  const stylePaintByMode = {};
  let hasStyle = false;
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    const paint = buildComposerBooleanPaint(text.length, styleState[mode]);
    stylePaintByMode[mode] = paint;
    if (!hasStyle && paint.some(Boolean)) hasStyle = true;
  }
  const hasColor = colorPaint.some((value) => !!normalizeMessageColorHex(value));
  if (!hasColor && !hasStyle) return text;

  const sameStyleStateAt = (a, b) => {
    for (const mode of DM_COMPOSER_STYLE_ORDER) {
      if (!!stylePaintByMode[mode][a] !== !!stylePaintByMode[mode][b]) return false;
    }
    return true;
  };

  let out = "";
  let i = 0;
  while (i < text.length) {
    const color = normalizeMessageColorHex(colorPaint[i]) || "";
    let j = i + 1;
    while (j < text.length) {
      const nextColor = normalizeMessageColorHex(colorPaint[j]) || "";
      if (nextColor !== color) break;
      if (!sameStyleStateAt(i, j)) break;
      j += 1;
    }

    let segment = text.slice(i, j);
    const activeModes = DM_COMPOSER_STYLE_ORDER.filter((mode) => !!stylePaintByMode[mode][i]);
    if (activeModes.length) {
      const open = activeModes.map((mode) => String(DM_COMPOSER_STYLE_TAGS[mode]?.open || "")).join("");
      const close = activeModes
        .slice()
        .reverse()
        .map((mode) => String(DM_COMPOSER_STYLE_TAGS[mode]?.close || ""))
        .join("");
      segment = `${open}${segment}${close}`;
    }
    if (color) {
      segment = `[color=${color}]${segment}[/color]`;
    }
    out += segment;
    i = j;
  }
  return out;
}

function buildComposerColorPaint(textLenInput, rangesInput = dmComposerColorRanges) {
  const textLen = Math.max(0, Number(textLenInput) || 0);
  const paint = new Array(textLen).fill("");
  if (!textLen) return paint;
  const ranges = normalizeComposerColorRanges(rangesInput, textLen);
  for (const item of ranges) {
    const color = normalizeMessageColorHex(item?.color);
    if (!color) continue;
    const start = Math.max(0, Math.min(textLen, Number(item?.start) || 0));
    const end = Math.max(0, Math.min(textLen, Number(item?.end) || 0));
    if (end <= start) continue;
    for (let i = start; i < end; i += 1) paint[i] = color;
  }
  return paint;
}

function buildComposerColorRangesFromPaint(paintInput = []) {
  const paint = Array.isArray(paintInput) ? paintInput : [];
  if (!paint.length) return [];
  const out = [];
  let i = 0;
  while (i < paint.length) {
    const color = normalizeMessageColorHex(paint[i]);
    if (!color) {
      i += 1;
      continue;
    }
    let j = i + 1;
    while (j < paint.length && normalizeMessageColorHex(paint[j]) === color) j += 1;
    out.push({ start: i, end: j, color });
    i = j;
  }
  return out;
}

function pickComposerInsertionColor(prevPaint = [], changeStart = 0, removeEnd = 0) {
  if (!Array.isArray(prevPaint) || !prevPaint.length) return "";
  const len = prevPaint.length;
  const at = Math.max(0, Math.min(len, Number(changeStart) || 0));
  const remEnd = Math.max(at, Math.min(len, Number(removeEnd) || at));
  const rem = Math.max(0, remEnd - at);

  if (rem > 0) {
    let solid = "";
    let mixed = false;
    const end = Math.max(at, Math.min(len, at + rem));
    for (let i = at; i < end; i += 1) {
      const c = normalizeMessageColorHex(prevPaint[i]);
      if (!solid) {
        solid = c;
      } else if (solid !== c) {
        mixed = true;
        break;
      }
    }
    if (!mixed && solid) return solid;
  }
  return "";
}

function pickComposerInsertionSize(prevPaint = [], changeStart = 0, removeEnd = 0) {
  if (!Array.isArray(prevPaint) || !prevPaint.length) return 0;
  const len = prevPaint.length;
  const at = Math.max(0, Math.min(len, Number(changeStart) || 0));
  const remEnd = Math.max(at, Math.min(len, Number(removeEnd) || at));
  const rem = Math.max(0, remEnd - at);

  if (rem > 0) {
    let solid = 0;
    let mixed = false;
    const end = Math.max(at, Math.min(len, at + rem));
    for (let i = at; i < end; i += 1) {
      const s = Number(prevPaint[i] || 0);
      if (!solid) {
        solid = s;
      } else if (solid !== s) {
        mixed = true;
        break;
      }
    }
    if (!mixed && solid) return solid;
  }

  const left = at > 0 ? Number(prevPaint[at - 1] || 0) : 0;
  const right = at < len ? Number(prevPaint[at] || 0) : 0;
  if (left && right && left === right) return left;
  if (left) return left;
  if (right) return right;
  return 0;
}

function captureDmComposerBeforeInputEdit(inputEl, ev) {
  if (!inputEl) {
    dmComposerBeforeInputEdit = null;
    return;
  }
  const prevText = String(inputEl.value || "");
  let start = Number.isFinite(inputEl.selectionStart) ? inputEl.selectionStart : prevText.length;
  let end = Number.isFinite(inputEl.selectionEnd) ? inputEl.selectionEnd : start;
  start = Math.max(0, Math.min(start, prevText.length));
  end = Math.max(0, Math.min(end, prevText.length));
  if (end < start) [start, end] = [end, start];

  const inputType = String(ev?.inputType || "").trim();
  let removeStart = start;
  let removeEnd = end;
  if (start === end) {
    if (inputType === "deleteContentBackward") {
      removeStart = Math.max(0, start - 1);
      removeEnd = start;
    } else if (inputType === "deleteContentForward") {
      removeStart = start;
      removeEnd = Math.min(prevText.length, start + 1);
    }
  }

  dmComposerBeforeInputEdit = {
    prevText,
    removeStart,
    removeEnd,
    inputType,
  };
}

function reconcileDmComposerColorRangesFromBeforeInput(nextTextInput = "") {
  const ctx = dmComposerBeforeInputEdit;
  if (!ctx || !dmComposerColorRanges.length) return false;

  const nextText = String(nextTextInput || "");
  const prevText = String(ctx.prevText || "");
  if (prevText !== String(dmComposerColorRangesSnapshotText || "")) return false;

  const prevLen = prevText.length;
  const nextLen = nextText.length;
  const removeStart = Math.max(0, Math.min(prevLen, Number(ctx.removeStart) || 0));
  const removeEnd = Math.max(removeStart, Math.min(prevLen, Number(ctx.removeEnd) || removeStart));
  const removedLen = Math.max(0, removeEnd - removeStart);
  const insertedLen = nextLen - (prevLen - removedLen);
  if (!Number.isFinite(insertedLen) || insertedLen < 0) return false;

  const prevPaint = buildComposerColorPaint(prevLen, dmComposerColorRanges);
  const nextPaint = [];
  if (removeStart > 0) nextPaint.push(...prevPaint.slice(0, removeStart));

  const insertedColor = pickComposerInsertionColor(prevPaint, removeStart, removeEnd);
  for (let i = 0; i < insertedLen; i += 1) nextPaint.push(insertedColor);

  if (removeEnd < prevLen) nextPaint.push(...prevPaint.slice(removeEnd));
  if (nextPaint.length !== nextLen) return false;

  dmComposerColorRanges = normalizeComposerColorRanges(
    buildComposerColorRangesFromPaint(nextPaint),
    nextLen
  );
  dmComposerColorRangesSnapshotText = nextText;
  return true;
}

function reconcileDmComposerColorRanges(nextTextInput = "") {
  const nextText = String(nextTextInput || "");
  const prevText = String(dmComposerColorRangesSnapshotText || "");

  if (reconcileDmComposerColorRangesFromBeforeInput(nextText)) return;

  if (!dmComposerColorRanges.length) {
    dmComposerColorRangesSnapshotText = nextText;
    return;
  }
  if (prevText === nextText) {
    dmComposerColorRangesSnapshotText = nextText;
    return;
  }

  const prevLen = prevText.length;
  const nextLen = nextText.length;
  let prefix = 0;
  while (prefix < prevLen && prefix < nextLen && prevText.charCodeAt(prefix) === nextText.charCodeAt(prefix)) {
    prefix += 1;
  }

  let suffix = 0;
  while (
    suffix < (prevLen - prefix)
    && suffix < (nextLen - prefix)
    && prevText.charCodeAt(prevLen - 1 - suffix) === nextText.charCodeAt(nextLen - 1 - suffix)
  ) {
    suffix += 1;
  }

  const removedLen = Math.max(0, prevLen - prefix - suffix);
  const addedLen = Math.max(0, nextLen - prefix - suffix);
  const prevPaint = buildComposerColorPaint(prevLen, dmComposerColorRanges);
  const nextPaint = new Array(nextLen).fill("");

  for (let i = 0; i < prefix; i += 1) nextPaint[i] = prevPaint[i] || "";

  const insertedColor = pickComposerInsertionColor(prevPaint, prefix, prefix + removedLen);
  for (let i = 0; i < addedLen; i += 1) nextPaint[prefix + i] = insertedColor;

  for (let i = 0; i < suffix; i += 1) {
    nextPaint[prefix + addedLen + i] = prevPaint[prevLen - suffix + i] || "";
  }

  dmComposerColorRanges = normalizeComposerColorRanges(
    buildComposerColorRangesFromPaint(nextPaint),
    nextLen
  );
  dmComposerColorRangesSnapshotText = nextText;
}

function hasComposerInlineFormatting(
  rawText = "",
  colorRangesInput = dmComposerColorRanges,
  styleRangesInput = dmComposerStyleRanges,
  sizeRangesInput = [],
) {
  const text = String(rawText || "");
  if (!text) return false;
  if (Array.isArray(colorRangesInput) && colorRangesInput.length) return true;
  if (styleRangesInput && typeof styleRangesInput === "object") {
    for (const mode of DM_COMPOSER_STYLE_ORDER) {
      if (Array.isArray(styleRangesInput[mode]) && styleRangesInput[mode].length) return true;
    }
  }
  if (/`[^`\n]+`/.test(text)) return true;
  if (/\*\*\*([^*\n](?:[\s\S]*?[^*\n])?)\*\*\*/.test(text)) return true;
  if (/\*\*([^*\n](?:[\s\S]*?[^*\n])?)\*\*/.test(text)) return true;
  if (/\*([^*\n](?:[\s\S]*?[^*\n])?)\*/.test(text)) return true;
  if (/__([^_\n](?:[\s\S]*?[^_\n])?)__/.test(text)) return true;
  if (/~~([^~\n](?:[\s\S]*?[^~\n])?)~~/.test(text)) return true;
  if (/\|\|([^|\n](?:[\s\S]*?[^|\n])?)\|\|/.test(text)) return true;
  if (/\[color=#[0-9a-f]{3,6}\][\s\S]*?\[\/color\]/i.test(text)) return true;
  return false;
}

function hasParsedComposerFormatting(parsed = null, rawSource = "") {
  const src = String(rawSource || "");
  const p = parsed && typeof parsed === "object" ? parsed : {};
  if (String(p.text || "") !== src) return true;
  if (Array.isArray(p.colorRanges) && p.colorRanges.length) return true;
  if (p.styleRanges && typeof p.styleRanges === "object") {
    for (const mode of DM_COMPOSER_STYLE_ORDER) {
      if (Array.isArray(p.styleRanges[mode]) && p.styleRanges[mode].length) return true;
    }
  }
  return false;
}

function insertParsedFormattingIntoComposer(inputEl, parsedInput = null) {
  const input = inputEl || document.getElementById("dmInput");
  if (!input) return false;
  const parsed = parsedInput && typeof parsedInput === "object" ? parsedInput : {};
  const insertText = String(parsed.text || "");
  if (!insertText) return false;

  const sel = getDmInputSelectionInfo(input);
  const prevText = String(sel.value || "");
  const prevLen = prevText.length;
  const replaceStart = Math.max(0, Math.min(prevLen, Number(sel.start) || 0));
  const replaceEnd = Math.max(replaceStart, Math.min(prevLen, Number(sel.end) || replaceStart));
  const nextText = `${prevText.slice(0, replaceStart)}${insertText}${prevText.slice(replaceEnd)}`;
  const nextLen = nextText.length;
  const insertLen = insertText.length;

  const prevColorPaint = buildComposerColorPaint(prevLen, dmComposerColorRanges);
  const prevSizePaint = buildComposerSizePaint(prevLen, dmComposerSizeRanges);
  const prevStylePaintByMode = {};
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    prevStylePaintByMode[mode] = buildComposerBooleanPaint(prevLen, dmComposerStyleRanges?.[mode] || []);
  }

  const insertColorRanges = normalizeComposerColorRanges(parsed.colorRanges || [], insertLen);
  const insertSizeRanges = normalizeComposerSizeRanges(parsed.sizeRanges || [], insertLen);
  const insertStyleState = cloneComposerStyleRangeState(parsed.styleRanges);
  const insertColorPaint = buildComposerColorPaint(insertLen, insertColorRanges);
  const insertSizePaint = buildComposerSizePaint(insertLen, insertSizeRanges);
  const insertStylePaintByMode = {};
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    insertStylePaintByMode[mode] = buildComposerBooleanPaint(insertLen, insertStyleState[mode] || []);
  }

  const nextColorPaint = [];
  const nextSizePaint = [];
  if (replaceStart > 0) {
    nextColorPaint.push(...prevColorPaint.slice(0, replaceStart));
    nextSizePaint.push(...prevSizePaint.slice(0, replaceStart));
  }
  if (insertLen > 0) {
    nextColorPaint.push(...insertColorPaint);
    nextSizePaint.push(...insertSizePaint);
  }
  if (replaceEnd < prevLen) {
    nextColorPaint.push(...prevColorPaint.slice(replaceEnd));
    nextSizePaint.push(...prevSizePaint.slice(replaceEnd));
  }

  const nextStyleState = createEmptyComposerStyleRangeState();
  for (const mode of DM_COMPOSER_STYLE_ORDER) {
    const prevPaint = prevStylePaintByMode[mode] || [];
    const insertPaint = insertStylePaintByMode[mode] || [];
    const mergedPaint = [];
    if (replaceStart > 0) mergedPaint.push(...prevPaint.slice(0, replaceStart));
    if (insertLen > 0) mergedPaint.push(...insertPaint);
    if (replaceEnd < prevLen) mergedPaint.push(...prevPaint.slice(replaceEnd));
    nextStyleState[mode] = normalizeComposerBooleanRanges(
      buildComposerBooleanRangesFromPaint(mergedPaint),
      nextLen,
    );
  }

  input.value = nextText;
  dmComposerColorRanges = normalizeComposerColorRanges(buildComposerColorRangesFromPaint(nextColorPaint), nextLen);
  dmComposerColorRangesSnapshotText = nextText;
  dmComposerSizeRanges = normalizeComposerSizeRanges(buildComposerSizeRangesFromPaint(nextSizePaint), nextLen);
  dmComposerSizeRangesSnapshotText = nextText;
  dmComposerStyleRanges = cloneComposerStyleRangeState(nextStyleState);
  dmComposerStyleRangesSnapshotText = nextText;

  const nextCaret = replaceStart + insertLen;
  setDmInputSelectionInfo(input, nextCaret, nextCaret);
  updateDmComposerPreview();
  refreshDmComposerFormatToolbar(input);
  return true;
}

function syncDmInputRichMirrorMetrics(inputEl = null) {
  const input = inputEl || document.getElementById("dmInput");
  const mirror = document.getElementById("dmInputRichMirror");
  if (!input || !mirror) return;
  const style = window.getComputedStyle(input);
  mirror.style.color = "var(--text-main)";
  mirror.style.font = style.font;
  mirror.style.letterSpacing = style.letterSpacing;
  mirror.style.fontSize = style.fontSize;
  mirror.style.lineHeight = style.lineHeight;
  mirror.style.paddingTop = style.paddingTop;
  mirror.style.paddingRight = style.paddingRight;
  mirror.style.paddingBottom = style.paddingBottom;
  mirror.style.paddingLeft = style.paddingLeft;
  mirror.style.textAlign = style.textAlign;
}

function getDmComposerActiveTypingFontSize(inputEl = null) {
  const input = inputEl || document.getElementById("dmInput");
  if (!input) return DM_COMPOSER_FONT_SIZE_DEFAULT;
  const sel = getDmInputSelectionInfo(input);
  const value = String(sel.value || "");
  if (!value.length) return DM_COMPOSER_FONT_SIZE_DEFAULT;
  const paint = buildComposerSizePaint(value.length, dmComposerSizeRanges);

  const distinctEffectiveSizes = new Set();
  for (let i = 0; i < paint.length; i += 1) {
    const effective = normalizeComposerFontSize(Number(paint[i] || 0) || DM_COMPOSER_FONT_SIZE_DEFAULT);
    distinctEffectiveSizes.add(effective);
    if (distinctEffectiveSizes.size > 1) break;
  }
  if (distinctEffectiveSizes.size > 1) {
    // Mixed size runs in one line become unstable if we move the real caret size around.
    // Keep a stable base size and let the rich mirror show the per-segment visual sizes.
    return DM_COMPOSER_FONT_SIZE_DEFAULT;
  }

  if (sel.hasSelection) {
    return getDmInputRangeCurrentFontSize(input, sel);
  }
  const caret = Math.max(0, Math.min(value.length, Number(sel.start) || 0));
  const before = caret > 0 ? Number(paint[caret - 1] || 0) : 0;
  if (before > 0) return normalizeComposerFontSize(before);
  const after = caret < value.length ? Number(paint[caret] || 0) : 0;
  if (after > 0) return normalizeComposerFontSize(after);
  return DM_COMPOSER_FONT_SIZE_DEFAULT;
}

function getDmComposerSelectionDisplayFontSize(inputEl = null, selectionInput = null) {
  const input = inputEl || document.getElementById("dmInput");
  if (!input) return DM_COMPOSER_FONT_SIZE_DEFAULT;
  const sel = selectionInput && typeof selectionInput === "object"
    ? selectionInput
    : getDmInputSelectionInfo(input);
  const value = String(sel?.value || input.value || "");
  if (!value.length) return DM_COMPOSER_FONT_SIZE_DEFAULT;
  if (!sel?.hasSelection) return getDmComposerActiveTypingFontSize(input);

  const start = Math.max(0, Math.min(value.length, Number(sel.start) || 0));
  const end = Math.max(start, Math.min(value.length, Number(sel.end) || start));
  if (end <= start) return DM_COMPOSER_FONT_SIZE_DEFAULT;
  const sizePaint = buildComposerSizePaint(value.length, dmComposerSizeRanges);
  let maxSize = DM_COMPOSER_FONT_SIZE_DEFAULT;
  for (let i = start; i < end; i += 1) {
    const effective = normalizeComposerFontSize(Number(sizePaint[i] || 0) || DM_COMPOSER_FONT_SIZE_DEFAULT);
    if (effective > maxSize) maxSize = effective;
  }
  return maxSize;
}

function updateDmComposerPreview() {
  const input = document.getElementById("dmInput");
  const wrap = document.getElementById("dmInputWrap");
  const mirror = document.getElementById("dmInputRichMirror");
  if (!input || !wrap || !mirror) return;
  wrap.dataset.richReady = "0";
  const raw = String(input.value || "");
  reconcileDmComposerSizeRanges(raw);
  reconcileDmComposerColorRanges(raw);
  reconcileDmComposerStyleRanges(raw);

  // Size feature disabled: keep parser compatibility for old messages, but do
  // not keep active size ranges in composer state.
  if (dmComposerSizeRanges.length) dmComposerSizeRanges = [];
  dmComposerSizeRangesSnapshotText = raw;

  const lineCount = Math.max(1, raw.split(/\r?\n/).length);
  const lineHeightPx = Math.round(DM_COMPOSER_FONT_SIZE_DEFAULT * 1.35);
  const composerHeight = Math.max(46, Math.min(220, (lineCount * lineHeightPx) + 18));
  wrap.style.setProperty("--dmComposerInputHeight", `${composerHeight}px`);

  const resetComposerInputTypography = () => {
    input.style.removeProperty("font-size");
    input.style.removeProperty("line-height");
  };

  if (!raw) {
    mirror.innerHTML = "";
    wrap.classList.remove("has-rich-preview");
    resetComposerInputTypography();
    syncDmInputRichMirrorMetrics(input);
    syncDmInputRichMirrorScroll(input);
    return;
  }

  const renderSource = serializeComposerTextWithFormattingRanges(
    raw,
    dmComposerColorRanges,
    [],
    dmComposerStyleRanges,
  );
  const useRichPreview = hasComposerInlineFormatting(raw, dmComposerColorRanges, dmComposerStyleRanges, []);
  if (!useRichPreview) {
    mirror.innerHTML = "";
    wrap.classList.remove("has-rich-preview");
    resetComposerInputTypography();
    syncDmInputRichMirrorMetrics(input);
    syncDmInputRichMirrorScroll(input);
    return;
  }

  const activeEl = document.activeElement;
  const hasFocus = document.activeElement === input;
  const hasComposerUiFocus = !!(
    hasFocus
    || (activeEl && typeof activeEl.closest === "function" && (
      activeEl.closest("#dmFormatToolbar")
      || activeEl.closest("#appColorPicker")
    ))
  );
  const sel = getDmInputSelectionInfo(input);
  // Keep rich preview while selecting inside the input so styles remain visible.
  // Only force plain rendering when selection exists but focus moved away
  // (e.g. temporarily on the floating toolbar), which avoids overlay artifacts.
  if (sel.hasSelection && !hasComposerUiFocus) {
    mirror.innerHTML = "";
    wrap.classList.remove("has-rich-preview");
    wrap.dataset.richReady = "0";
    resetComposerInputTypography();
    syncDmInputRichMirrorMetrics(input);
    syncDmInputRichMirrorScroll(input);
    return;
  }

  syncDmInputRichMirrorMetrics(input);
  mirror.innerHTML = `<span>${renderComposerPreviewTextHtml(renderSource)}</span>`;
  if (!String(mirror.textContent || "").length) {
    wrap.classList.remove("has-rich-preview");
    wrap.dataset.richReady = "0";
    resetComposerInputTypography();
    return;
  }
  if (!hasFocus) hideDmComposerFormatToolbar();
  wrap.classList.add("has-rich-preview");
  wrap.dataset.richReady = "1";
  syncDmInputRichMirrorScroll(input);
}

function syncDmInputRichMirrorScroll(inputEl = null) {
  const input = inputEl || document.getElementById("dmInput");
  const mirror = document.getElementById("dmInputRichMirror");
  if (!input || !mirror) return;
  mirror.scrollLeft = Number.isFinite(input.scrollLeft) ? Number(input.scrollLeft) : 0;
  mirror.scrollTop = Number.isFinite(input.scrollTop) ? Number(input.scrollTop) : 0;
}

function getDmInputSelectionInfo(inputEl) {
  if (!inputEl) return { value: "", start: 0, end: 0, hasSelection: false };
  const value = String(inputEl.value || "");
  let start = Number.isFinite(inputEl.selectionStart) ? inputEl.selectionStart : value.length;
  let end = Number.isFinite(inputEl.selectionEnd) ? inputEl.selectionEnd : start;
  const pickerOpenForComposer = !!(
    customColorPickerTargetInput instanceof HTMLInputElement
    && customColorPickerTargetInput.id === "dmFormatColorPicker"
    && dmComposerColorSelection
    && Number.isFinite(dmComposerColorSelection.start)
    && Number.isFinite(dmComposerColorSelection.end)
  );
  if (pickerOpenForComposer && end <= start) {
    start = Number(dmComposerColorSelection.start) || 0;
    end = Number(dmComposerColorSelection.end) || start;
  }
  start = Math.max(0, Math.min(start, value.length));
  end = Math.max(0, Math.min(end, value.length));
  if (end < start) [start, end] = [end, start];
  return { value, start, end, hasSelection: end > start };
}

function setDmInputSelectionInfo(inputEl, start, end, options = {}) {
  if (!inputEl) return;
  const shouldFocus = options?.focus !== false;
  if (shouldFocus) {
    try {
      inputEl.focus({ preventScroll: true });
    } catch (_) {
      try { inputEl.focus(); } catch (_) {}
    }
  }
  try {
    inputEl.setSelectionRange(start, end);
  } catch (_) {}
}

function hideDmComposerFormatToolbar() {
  const toolbar = document.getElementById("dmFormatToolbar");
  if (!toolbar) return;
  toolbar.style.display = "none";
  toolbar.setAttribute("aria-hidden", "true");
  if (!dmComposerSizeSliderActive) {
    dmComposerSizeSelection = null;
    dmComposerToolbarLockedPosition = null;
    dmComposerSizeSliderPointerId = null;
  }
}

function lockDmComposerFormatToolbarPosition(toolbarEl = null) {
  const toolbar = toolbarEl || document.getElementById("dmFormatToolbar");
  if (!toolbar) return;
  const leftInline = Number.parseFloat(toolbar.style.left);
  const topInline = Number.parseFloat(toolbar.style.top);
  const rect = toolbar.getBoundingClientRect();
  dmComposerToolbarLockedPosition = {
    left: Number.isFinite(leftInline) ? leftInline : rect.left,
    top: Number.isFinite(topInline) ? topInline : rect.top,
  };
}

function getDmInputSelectionAnchorIndex(inputEl, sel) {
  const valueLen = String(sel?.value || "").length;
  let start = Number.isFinite(sel?.start) ? Number(sel.start) : 0;
  let end = Number.isFinite(sel?.end) ? Number(sel.end) : 0;
  start = Math.max(0, Math.min(start, valueLen));
  end = Math.max(0, Math.min(end, valueLen));
  const direction = String(inputEl?.selectionDirection || "forward").toLowerCase();
  const rawAnchor = (direction === "backward") ? start : end;
  return Math.max(0, Math.min(rawAnchor, valueLen));
}

const dmInputMeasureCanvas = document.createElement("canvas");
const dmInputMeasureCtx = dmInputMeasureCanvas.getContext("2d");

function measureDmInputTextWidth(inputEl, text = "") {
  if (!dmInputMeasureCtx || !inputEl) return 0;
  const style = window.getComputedStyle(inputEl);
  dmInputMeasureCtx.font = style.font || `${style.fontSize} ${style.fontFamily}`;
  const normalized = String(text || "").replace(/\r?\n/g, " ");
  let width = dmInputMeasureCtx.measureText(normalized).width;
  const letterSpacing = Number.parseFloat(style.letterSpacing);
  if (Number.isFinite(letterSpacing) && letterSpacing !== 0 && normalized.length > 1) {
    width += letterSpacing * (normalized.length - 1);
  }
  return width;
}

function refreshDmComposerFormatToolbar(inputEl = null) {
  const input = inputEl || document.getElementById("dmInput");
  const toolbar = document.getElementById("dmFormatToolbar");
  const sizeSlider = document.getElementById("dmFormatSizeSlider");
  if (!toolbar || !input) return;

  const selRaw = getDmInputSelectionInfo(input);
  const valueLen = String(selRaw.value || "").length;
  const hasPinnedSizeRange = !!(
    dmComposerSizeSelection
    && Number.isFinite(dmComposerSizeSelection.start)
    && Number.isFinite(dmComposerSizeSelection.end)
    && dmComposerSizeSelection.end > dmComposerSizeSelection.start
  );
  const sel = (selRaw.hasSelection || !hasPinnedSizeRange)
    ? selRaw
    : {
      value: selRaw.value,
      start: Math.max(0, Math.min(valueLen, Number(dmComposerSizeSelection.start) || 0)),
      end: Math.max(0, Math.min(valueLen, Number(dmComposerSizeSelection.end) || 0)),
      hasSelection: true,
    };
  const activeEl = document.activeElement;
  const toolbarActive = !!(activeEl && typeof activeEl.closest === "function" && activeEl.closest("#dmFormatToolbar"));
  const inputActive = (activeEl === input) || toolbarActive || hasPinnedSizeRange;
  if (!sel.hasSelection || !inputActive) {
    hideDmComposerFormatToolbar();
    return;
  }

  toolbar.style.display = "flex";
  toolbar.setAttribute("aria-hidden", "false");

  const rect = input.getBoundingClientRect();
  const style = window.getComputedStyle(input);
  const width = Math.max(160, toolbar.offsetWidth || 260);
  const height = Math.max(28, toolbar.offsetHeight || 38);
  let left;
  let top;

  if (
    dmComposerSizeSliderActive
    && dmComposerToolbarLockedPosition
    && Number.isFinite(dmComposerToolbarLockedPosition.left)
    && Number.isFinite(dmComposerToolbarLockedPosition.top)
  ) {
    left = dmComposerToolbarLockedPosition.left;
    top = dmComposerToolbarLockedPosition.top;
  } else {
    const paddingLeft = Number.parseFloat(style.paddingLeft) || 12;
    const margin = 8;
    const anchorIndex = getDmInputSelectionAnchorIndex(input, sel);
    const beforeText = sel.value.slice(0, anchorIndex);
    const textWidth = measureDmInputTextWidth(input, beforeText);
    const scrollLeft = Number.isFinite(input.scrollLeft) ? Number(input.scrollLeft) : 0;
    let anchorX = rect.left + paddingLeft + textWidth - scrollLeft;
    anchorX = Math.max(rect.left + 12, Math.min(anchorX, rect.right - 12));

    left = anchorX - (width / 2);
    left = Math.max(10, Math.min(left, window.innerWidth - width - 10));

    top = rect.top - height - margin;
    if (top < 10) top = rect.bottom + margin;
  }

  toolbar.style.left = `${Math.round(left)}px`;
  toolbar.style.top = `${Math.round(top)}px`;

  if (sizeSlider) {
    const currentSize = getDmInputRangeCurrentFontSize(input, sel);
    sizeSlider.value = String(currentSize);
    sizeSlider.title = `Tamanho: ${currentSize}px`;
  }
}

function applyDmInputSelectionWrapper(inputEl, prefix, suffix = prefix) {
  const sel = getDmInputSelectionInfo(inputEl);
  if (!sel.hasSelection) return false;
  const selected = sel.value.slice(sel.start, sel.end);
  const next = `${sel.value.slice(0, sel.start)}${prefix}${selected}${suffix}${sel.value.slice(sel.end)}`;
  inputEl.value = next;
  reconcileDmComposerColorRanges(next);
  dmComposerStyleRanges = createEmptyComposerStyleRangeState();
  dmComposerStyleRangesSnapshotText = next;
  dmComposerBeforeInputEdit = null;
  const nextCaret = sel.start + prefix.length + selected.length + suffix.length;
  setDmInputSelectionInfo(inputEl, nextCaret, nextCaret);
  updateDmComposerPreview();
  refreshDmComposerFormatToolbar(inputEl);
  return true;
}

function applyDmInputSelectionStyle(inputEl, mode = "") {
  const styleMode = String(mode || "").trim().toLowerCase();
  if (!DM_COMPOSER_STYLE_ORDER.includes(styleMode)) return false;
  const marker = DM_COMPOSER_STYLE_MARKERS[styleMode];
  if (!marker?.open || !marker?.close) return false;
  return applyDmInputSelectionWrapper(inputEl, marker.open, marker.close);
}

function applyDmInputSelectionColor(inputEl, colorHex = "") {
  const safeColor = normalizeMessageColorHex(colorHex);
  if (!safeColor) return false;
  const sel = getDmInputSelectionInfo(inputEl);
  if (!sel.hasSelection) return false;

  return applyDmInputColorRange(inputEl, sel.start, sel.end, safeColor);
}

function applyDmInputColorRange(inputEl, startInput, endInput, colorHex = "", { collapseSelection = true, refocus = true } = {}) {
  if (!inputEl) return false;
  const safeColor = normalizeMessageColorHex(colorHex);
  if (!safeColor) return false;
  const value = String(inputEl.value || "");
  const textLen = value.length;
  let start = Math.max(0, Math.min(textLen, Number(startInput) || 0));
  let end = Math.max(0, Math.min(textLen, Number(endInput) || 0));
  if (end < start) [start, end] = [end, start];
  if (end <= start) return false;

  const nextRanges = Array.isArray(dmComposerColorRanges) ? dmComposerColorRanges.slice() : [];
  nextRanges.push({ start, end, color: safeColor });
  dmComposerColorRanges = normalizeComposerColorRanges(nextRanges, textLen);
  dmComposerColorRangesSnapshotText = value;

  const nextCaret = collapseSelection ? end : start;
  const nextEnd = collapseSelection ? end : end;
  setDmInputSelectionInfo(inputEl, nextCaret, nextEnd, { focus: !!refocus });
  updateDmComposerPreview();
  refreshDmComposerFormatToolbar(inputEl);
  return true;
}

function setDmInputRangeFontSize(inputEl, startInput, endInput, sizeInput) {
  if (!inputEl) return false;
  const value = String(inputEl.value || "");
  const len = value.length;
  let start = Math.max(0, Math.min(len, Number(startInput) || 0));
  let end = Math.max(0, Math.min(len, Number(endInput) || 0));
  if (end < start) [start, end] = [end, start];
  if (end <= start) return false;
  const safeSize = normalizeComposerFontSize(sizeInput);
  const applied = safeSize === DM_COMPOSER_FONT_SIZE_DEFAULT ? 0 : safeSize;

  const sizePaint = buildComposerSizePaint(len, dmComposerSizeRanges);
  for (let i = start; i < end; i += 1) sizePaint[i] = applied;

  dmComposerSizeRanges = normalizeComposerSizeRanges(
    buildComposerSizeRangesFromPaint(sizePaint),
    len,
  );
  dmComposerSizeRangesSnapshotText = value;
  return true;
}

function getDmInputFormattingTargetRange(inputEl) {
  const sel = getDmInputSelectionInfo(inputEl);
  const value = String(sel.value || "");
  if (!value) return null;
  if (sel.hasSelection) return { value, start: sel.start, end: sel.end };
  return { value, start: 0, end: value.length };
}

function getDmInputRangeCurrentFontSize(inputEl, rangeInput = null) {
  const range = rangeInput || getDmInputFormattingTargetRange(inputEl);
  if (!range) return DM_COMPOSER_FONT_SIZE_DEFAULT;
  const sizePaint = buildComposerSizePaint(String(range.value || "").length, dmComposerSizeRanges);
  for (let i = range.start; i < range.end; i += 1) {
    const hit = Number(sizePaint[i] || 0);
    if (hit > 0) return normalizeComposerFontSize(hit);
  }
  return DM_COMPOSER_FONT_SIZE_DEFAULT;
}

function applyDmInputSelectionSizeStep(inputEl, directionInput = 1) {
  const sel = getDmInputFormattingTargetRange(inputEl);
  if (!sel) return false;
  const direction = Number(directionInput) >= 0 ? 1 : -1;
  const current = getDmInputRangeCurrentFontSize(inputEl, sel);

  const next = normalizeComposerFontSize(current + (direction * DM_COMPOSER_FONT_SIZE_STEP));
  if (next === current) return false;
  if (!setDmInputRangeFontSize(inputEl, sel.start, sel.end, next)) return false;

  setDmInputSelectionInfo(inputEl, sel.end, sel.end);
  updateDmComposerPreview();
  refreshDmComposerFormatToolbar(inputEl);
  return true;
}

function bindDmComposerFormatToolbarOnce(inputEl) {
  if (dmComposerFormatToolbarBound) return;
  dmComposerFormatToolbarBound = true;

  const input = inputEl || document.getElementById("dmInput");
  const toolbar = document.getElementById("dmFormatToolbar");
  const colorBtn = document.getElementById("btnDmFormatColor");
  const colorPicker = document.getElementById("dmFormatColorPicker");
  const sizeSlider = document.getElementById("dmFormatSizeSlider");
  if (!input || !toolbar) return;
  bindCustomThemeColorPickerOnce();

  let dmComposerColorPickerIgnoreInitialSync = false;

  const syncDmComposerColorButton = (valueInput = "") => {
    const safe = normalizeMessageColorHex(valueInput || colorPicker?.value || "") || "#8ea0ff";
    if (!safe || !colorBtn) return;
    colorBtn.style.color = safe;
  };

  const applyDmComposerPickerColor = (valueInput = "") => {
    const safeColor = normalizeMessageColorHex(valueInput || "");
    if (!safeColor || !input) return;
    syncDmComposerColorButton(safeColor);
    if (dmComposerColorPickerIgnoreInitialSync && safeColor === dmComposerColorPickerOpenValue) {
      dmComposerColorPickerIgnoreInitialSync = false;
      return;
    }
    dmComposerColorPickerIgnoreInitialSync = false;
    const snapshot = dmComposerColorSelection;
    if (!snapshot || !Number.isFinite(snapshot.start) || !Number.isFinite(snapshot.end)) return;
    applyDmInputColorRange(input, snapshot.start, snapshot.end, safeColor, {
      collapseSelection: false,
      refocus: false,
    });
    dmComposerColorPickerOpenValue = safeColor;
  };

  syncDmComposerColorButton();

  const queueRefresh = () => {
    const sel = getDmInputSelectionInfo(input);
    if (!sel.hasSelection && !dmComposerSizeSliderActive) {
      dmComposerSizeSelection = null;
    }
    updateDmComposerPreview();
    syncDmInputRichMirrorScroll(input);
    window.setTimeout(() => refreshDmComposerFormatToolbar(input), 0);
  };

  input.addEventListener("select", queueRefresh);
  input.addEventListener("beforeinput", (e) => {
    captureDmComposerBeforeInputEdit(input, e);
  });
  input.addEventListener("mouseup", queueRefresh);
  input.addEventListener("keyup", queueRefresh);
  input.addEventListener("scroll", queueRefresh);
  input.addEventListener("focus", queueRefresh);
  input.addEventListener("blur", (e) => {
    const nextTarget = eventTargetElement(e) || e?.relatedTarget || document.activeElement;
    const movingIntoToolbar = !!(nextTarget && typeof nextTarget.closest === "function" && nextTarget.closest("#dmFormatToolbar"));
    const movingIntoPicker = !!(nextTarget && typeof nextTarget.closest === "function" && nextTarget.closest("#appColorPicker"));
    dmComposerBeforeInputEdit = null;
    if (!movingIntoToolbar && !movingIntoPicker) {
      dmComposerColorSelection = null;
      dmComposerColorPickerOpenValue = "";
    }
    if (!movingIntoToolbar && !movingIntoPicker && !dmComposerSizeSliderActive) dmComposerSizeSelection = null;
    updateDmComposerPreview();
    window.setTimeout(() => refreshDmComposerFormatToolbar(input), 70);
  });

  window.addEventListener("resize", () => refreshDmComposerFormatToolbar(input));
  window.addEventListener("scroll", () => refreshDmComposerFormatToolbar(input), true);
  window.addEventListener("blur", () => {
    hideDmComposerFormatToolbar();
    dmComposerColorSelection = null;
    dmComposerColorPickerOpenValue = "";
    dmComposerSizeSelection = null;
    dmComposerSizeSliderActive = false;
    dmComposerSizeSliderPointerId = null;
    dmComposerToolbarLockedPosition = null;
    try { input.blur(); } catch (_) {}
    updateDmComposerPreview();
  });
  window.addEventListener("focus", () => {
    updateDmComposerPreview();
    refreshDmComposerFormatToolbar(input);
  });
  document.addEventListener("mousedown", (e) => {
    if (document.activeElement !== input) return;
    const t = eventTargetElement(e) || e?.target;
    if (!t) return;
    if (t.closest?.(".dmComposer")) return;
    if (t.closest?.("#dmFormatToolbar")) return;
    if (t.closest?.("#appColorPicker")) return;
    try { input.blur(); } catch (_) {}
    updateDmComposerPreview();
  }, true);

  toolbar.addEventListener("mousedown", (e) => {
    const target = eventTargetElement(e) || e?.target;
    if (target?.closest?.(".dmFormatToolbar__sizeSlider")) return;
    if (target?.closest?.("input,textarea,select")) return;
    if (target?.closest?.(".dmFormatToolbar__btn")) {
      e.preventDefault();
    }
  });

  toolbar.addEventListener("click", (e) => {
    const btn = e.target?.closest?.("[data-dm-format]");
    if (!btn || !input) return;
    e.preventDefault();
    const mode = String(btn.dataset.dmFormat || "");
    if (!mode) return;

    if (mode === "bold") applyDmInputSelectionStyle(input, "bold");
    else if (mode === "italic") applyDmInputSelectionStyle(input, "italic");
    else if (mode === "strike") applyDmInputSelectionStyle(input, "strike");
    else if (mode === "code") applyDmInputSelectionStyle(input, "code");
    else if (mode === "spoiler") applyDmInputSelectionStyle(input, "spoiler");
    else if (mode === "sizeDown") applyDmInputSelectionSizeStep(input, -1);
    else if (mode === "sizeUp") applyDmInputSelectionSizeStep(input, 1);
  });

  colorBtn?.addEventListener("click", (e) => {
    e.preventDefault();
    const sel = getDmInputSelectionInfo(input);
    if (!sel.hasSelection) return;
    dmComposerColorSelection = { start: sel.start, end: sel.end };
    dmComposerColorPickerOpenValue = normalizeMessageColorHex(colorPicker?.value || "");
    dmComposerColorPickerIgnoreInitialSync = true;
    if (colorPicker instanceof HTMLInputElement) {
      openCustomColorPickerForInput(colorPicker, { anchorEl: colorBtn, freezeAnchorRect: true });
    }
  });

  colorPicker?.addEventListener("input", (e) => {
    applyDmComposerPickerColor(e?.target?.value || "");
  });

  colorPicker?.addEventListener("change", (e) => {
    applyDmComposerPickerColor(e?.target?.value || "");
  });

  colorPicker?.addEventListener("appcolorpickerclose", (e) => {
    const finalColor = normalizeMessageColorHex(e?.detail?.value || "");
    if (finalColor && dmComposerColorSelection && finalColor !== dmComposerColorPickerOpenValue) {
      applyDmComposerPickerColor(finalColor);
    }
    const snapshot = dmComposerColorSelection;
    if (snapshot && Number.isFinite(snapshot.end)) {
      setDmInputSelectionInfo(input, snapshot.end, snapshot.end);
    }
    dmComposerColorSelection = null;
    dmComposerColorPickerOpenValue = "";
    dmComposerColorPickerIgnoreInitialSync = false;
  });

  const captureSizeTargetRange = () => {
    const targetRange = getDmInputFormattingTargetRange(input);
    dmComposerSizeSelection = targetRange
      ? { start: targetRange.start, end: targetRange.end }
      : null;
  };

  const beginSizeSliderDrag = (pointerId = null) => {
    dmComposerSizeSliderActive = true;
    captureSizeTargetRange();
    lockDmComposerFormatToolbarPosition(toolbar);
    dmComposerSizeSliderPointerId = Number.isFinite(pointerId) ? Number(pointerId) : null;
  };

  const endSizeSliderDrag = ({ refresh = true } = {}) => {
    dmComposerSizeSliderActive = false;
    dmComposerSizeSliderPointerId = null;
    dmComposerToolbarLockedPosition = null;
    if (refresh) window.requestAnimationFrame(() => refreshDmComposerFormatToolbar(input));
  };

  const applySizeSliderValue = () => {
    if (!input || !sizeSlider) return;
    const value = normalizeComposerFontSize(sizeSlider.value);
    const fallback = getDmInputFormattingTargetRange(input);
    const target = dmComposerSizeSelection && Number.isFinite(dmComposerSizeSelection.start) && Number.isFinite(dmComposerSizeSelection.end)
      ? dmComposerSizeSelection
      : fallback;
    if (!target || target.end <= target.start) return;
    if (!setDmInputRangeFontSize(input, target.start, target.end, value)) return;
    updateDmComposerPreview();
    refreshDmComposerFormatToolbar(input);
  };

  const applySizeSliderFromClientX = (clientX) => {
    if (!sizeSlider || !Number.isFinite(clientX)) return;
    const rect = sizeSlider.getBoundingClientRect();
    const widthPx = Math.max(1, Number(rect.width) || 1);
    let ratio = (Number(clientX) - Number(rect.left || 0)) / widthPx;
    ratio = Math.max(0, Math.min(1, ratio));
    const min = Number.isFinite(Number(sizeSlider.min)) ? Number(sizeSlider.min) : DM_COMPOSER_FONT_SIZE_MIN;
    const max = Number.isFinite(Number(sizeSlider.max)) ? Number(sizeSlider.max) : DM_COMPOSER_FONT_SIZE_MAX;
    const stepRaw = Number(sizeSlider.step);
    const step = stepRaw > 0 ? stepRaw : 1;
    const raw = min + ((max - min) * ratio);
    const stepped = min + (Math.round((raw - min) / step) * step);
    const safe = normalizeComposerFontSize(Math.max(min, Math.min(max, stepped)));
    if (Number(sizeSlider.value) !== safe) sizeSlider.value = String(safe);
    applySizeSliderValue();
  };

  sizeSlider?.addEventListener("pointerdown", (e) => {
    beginSizeSliderDrag(e?.pointerId);
    try {
      if (Number.isFinite(e?.pointerId) && typeof sizeSlider.setPointerCapture === "function") {
        sizeSlider.setPointerCapture(e.pointerId);
      }
    } catch (_) {}
  });
  sizeSlider?.addEventListener("mousedown", (e) => {
    if ("PointerEvent" in window) return;
    beginSizeSliderDrag();
    applySizeSliderFromClientX(e?.clientX);
  });
  sizeSlider?.addEventListener("input", () => {
    applySizeSliderValue();
  });
  sizeSlider?.addEventListener("change", () => {
    applySizeSliderValue();
    endSizeSliderDrag();
  });
  sizeSlider?.addEventListener("click", () => {
    applySizeSliderValue();
  });
  sizeSlider?.addEventListener("focus", () => {
    if (!dmComposerSizeSelection) captureSizeTargetRange();
    dmComposerSizeSliderActive = true;
  });
  sizeSlider?.addEventListener("wheel", (e) => {
    e.preventDefault();
  }, { passive: false });
  sizeSlider?.addEventListener("pointerup", (e) => {
    if (Number.isFinite(dmComposerSizeSliderPointerId) && Number(e?.pointerId) !== dmComposerSizeSliderPointerId) return;
    endSizeSliderDrag();
  });
  sizeSlider?.addEventListener("blur", () => {
    if (!dmComposerSizeSliderActive) {
      dmComposerSizeSliderPointerId = null;
      dmComposerToolbarLockedPosition = null;
    }
  });
  window.addEventListener("pointermove", (e) => {
    if (!dmComposerSizeSliderActive || !sizeSlider) return;
    if (Number.isFinite(dmComposerSizeSliderPointerId) && Number(e?.pointerId) !== dmComposerSizeSliderPointerId) return;
    if (Number(e?.buttons) === 0) {
      endSizeSliderDrag();
      return;
    }
    applySizeSliderFromClientX(e?.clientX);
  });
  window.addEventListener("pointerup", (e) => {
    if (!dmComposerSizeSliderActive) return;
    if (Number.isFinite(dmComposerSizeSliderPointerId) && Number(e?.pointerId) !== dmComposerSizeSliderPointerId) return;
    endSizeSliderDrag();
  });
  window.addEventListener("pointercancel", (e) => {
    if (!dmComposerSizeSliderActive) return;
    if (Number.isFinite(dmComposerSizeSliderPointerId) && Number(e?.pointerId) !== dmComposerSizeSliderPointerId) return;
    endSizeSliderDrag();
  });
  window.addEventListener("mouseup", () => {
    if (!("PointerEvent" in window)) endSizeSliderDrag();
  });
}

function focusDmComposerSoon({ attempts = 3, delayMs = 42 } = {}) {
  let triesLeft = Math.max(1, Number(attempts) || 1);
  const delay = Math.max(16, Number(delayMs) || 42);

  const tryFocus = () => {
    const input = document.getElementById("dmInput");
    if (!(input instanceof HTMLInputElement || input instanceof HTMLTextAreaElement)) return;
    if (input.disabled || input.readOnly) return;

    try {
      input.focus({ preventScroll: true });
    } catch (_) {
      try { input.focus(); } catch (_) {}
    }

    if (document.activeElement === input) {
      try {
        const end = String(input.value || "").length;
        input.setSelectionRange(end, end);
      } catch (_) {}
      return;
    }

    triesLeft -= 1;
    if (triesLeft <= 0) return;
    setTimeout(() => {
      requestAnimationFrame(tryFocus);
    }, delay);
  };

  requestAnimationFrame(tryFocus);
}

function clearDmEditTarget({ clearInput = false, focusInput = false, render = true } = {}) {
  const hadEditTarget = !!(dmEditTarget?.id);
  dmEditTarget = null;
  const input = document.getElementById("dmInput");
  if (clearInput && input) {
    input.value = "";
    clearDmComposerColorRanges();
  }
  if (focusInput && input) {
    try { input.focus({ preventScroll: true }); } catch (_) {
      try { input.focus(); } catch (_) {}
    }
  }
  if (render) renderDmReplyBar();
  else applyDmComposerEditUi();
  return hadEditTarget;
}

function startDmMessageEdit(messageId, { focusInput = true } = {}) {
  const message = getEditableDmMessageById(messageId);
  if (!message) return false;
  const input = document.getElementById("dmInput");
  if (!input) return false;
  const parsed = safeParseMessageContent(message.content);
  const parsedFormatting = parseComposerTextWithFormattingRanges(String(parsed.text || ""));
  dmReplyTarget = null;
  dmEditTarget = {
    id: String(message.id || "").trim(),
    conversationId: normId(message.conversation_id || activeDmId || ""),
  };
  input.value = parsedFormatting.text;
  dmComposerColorRanges = normalizeComposerColorRanges(parsedFormatting.colorRanges, parsedFormatting.text.length);
  dmComposerColorRangesSnapshotText = parsedFormatting.text;
  dmComposerSizeRanges = normalizeComposerSizeRanges(parsedFormatting.sizeRanges, parsedFormatting.text.length);
  dmComposerSizeRangesSnapshotText = parsedFormatting.text;
  dmComposerStyleRanges = cloneComposerStyleRangeState(parsedFormatting.styleRanges);
  dmComposerStyleRangesSnapshotText = parsedFormatting.text;
  if (focusInput) {
    try { input.focus({ preventScroll: true }); } catch (_) {
      try { input.focus(); } catch (_) {}
    }
    try {
      const end = input.value.length;
      input.setSelectionRange(end, end);
    } catch (_) {}
  }
  renderDmReplyBar();
  return true;
}

function renderDmReplyBar() {
  const bar = document.getElementById("dmReplyBar");
  if (!bar) return;

  const editTargetId = String(dmEditTarget?.id || "").trim();
  if (editTargetId) {
    const target = getEditableDmMessageById(editTargetId);
    if (!target) {
      dmEditTarget = null;
    } else {
      const author = getMessageAuthorName(target);
      const preview = getMessagePreviewText(target);
      bar.style.display = "flex";
      bar.innerHTML = `
        <div class="dmReplyBar__text">
          <span class="dmReplyBar__title">A editar mensagem de ${esc(author)}</span>
          <span class="dmReplyBar__body">${esc(preview)}</span>
        </div>
        <button class="dmReplyBar__close" type="button" id="btnDmReplyCancel" aria-label="Cancelar edicao">×</button>
      `;
      document.getElementById("btnDmReplyCancel")?.addEventListener("click", () => {
        clearDmEditTarget({ clearInput: true, focusInput: true, render: true });
      });
      applyDmComposerEditUi();
      return;
    }
  }

  if (!dmReplyTarget?.id) {
    bar.style.display = "none";
    bar.innerHTML = "";
    applyDmComposerEditUi();
    return;
  }

  const target = getMessageById(dmReplyTarget.id);
  const author = target ? getMessageAuthorName(target) : (dmReplyTarget.author || t("usercard.msg.kind.message", "Message"));
  const preview = target ? getMessagePreviewText(target) : (dmReplyTarget.preview || t("msg.deleted", "Deleted message"));

  bar.style.display = "flex";
  bar.innerHTML = `
    <div class="dmReplyBar__text">
      <span class="dmReplyBar__title">A responder a ${esc(author)}</span>
      <span class="dmReplyBar__body">${esc(preview)}</span>
    </div>
    <button class="dmReplyBar__close" type="button" id="btnDmReplyCancel" aria-label="Cancelar reply">×</button>
  `;

  document.getElementById("btnDmReplyCancel")?.addEventListener("click", () => {
    dmReplyTarget = null;
    renderDmReplyBar();
  });
  applyDmComposerEditUi();
}

function setDmReplyTarget(messageId) {
  if (!dmFeatureCaps.advancedMessages) return;
  if (dmEditTarget?.id) {
    clearDmEditTarget({ clearInput: true, focusInput: false, render: false });
  }
  const m = getMessageById(messageId);
  if (!m) return;
  dmReplyTarget = {
    id: m.id,
    author: getMessageAuthorName(m),
    preview: getMessagePreviewText(m),
  };
  renderDmReplyBar();
  document.getElementById("dmInput")?.focus();
}

function getPinnedMessagesFromCache() {
  return filterRowsForServerMessageHistory(activeDmId || state.activeDm?.conversationId || "", dmMessagesCache)
    .filter((m) => !!m?.is_pinned)
    .sort((a, b) => new Date(b?.pinned_at || b?.created_at || 0) - new Date(a?.pinned_at || a?.created_at || 0));
}

async function getPinnedMessagesCountForActiveDm() {
  const localCount = getPinnedMessagesFromCache().length;
  if (!activeDmId || !dmFeatureCaps.advancedMessages) return localCount;

  const { count, error } = await supabase
    .from("messages")
    .select("id", { count: "exact", head: true })
    .eq("conversation_id", activeDmId)
    .eq("is_pinned", true);

  if (error) return localCount;
  if (!Number.isFinite(Number(count))) return localCount;
  return Math.max(0, Number(count));
}

function getActiveDmPeerUserId() {
  if (state.activeDm?.isGroup || state.activeDm?.kind === "group" || state.activeDm?.kind === "server") return "";
  return normId(state.activeDm?.otherUserId || state.activeDm?.other_user_id || callOtherUserId || "");
}

function normalizeGroupMemberLabel(displayName, username, fallback = t("call.member", "member")) {
  const d = String(displayName || "").trim();
  const u = String(username || "").trim();
  return d || u || fallback;
}

function getGroupConversationMembersCache(conversationId) {
  const convId = normId(conversationId);
  if (!convId) return [];
  return Array.isArray(dmGroupMembersCacheByConversation.get(convId))
    ? dmGroupMembersCacheByConversation.get(convId)
    : [];
}

async function fetchGroupConversationMembers(conversationId, { force = false } = {}) {
  const convId = normId(conversationId);
  if (!convId) return [];
  if (!force) {
    const cached = getGroupConversationMembersCache(convId);
    if (cached.length) return cached;
  }

  const { data, error } = await supabase
    .from("conversation_members")
    .select("user_id")
    .eq("conversation_id", convId);

  if (error || !Array.isArray(data)) {
    if (error) console.warn("group members fetch failed", error);
    return getGroupConversationMembersCache(convId);
  }

  const uniqueMemberIds = Array.from(new Set(
    data
      .map((row) => normId(row?.user_id || ""))
      .filter(Boolean)
  ));
  await fetchProfilesByIds(uniqueMemberIds, { includeBio: false, maxAgeMs: PROFILE_CACHE_TTL_MS }).catch(() => []);

  const members = uniqueMemberIds
    .map((uid) => {
      const profile = getCachedProfile(uid) || {};
      const username = String(profile?.username || "").trim();
      const displayName = normalizeGroupMemberLabel(profile?.display_name, username, uid.slice(0, 8));
      const avatarUrl = String(profile?.avatar_url || "").trim();
      const nameColor = normalizeNameColor(profile?.name_color || "");
      return {
        userId: uid,
        username,
        displayName,
        avatarUrl,
        nameColor,
      };
    })
    .sort((a, b) => {
      const an = String(a?.displayName || a?.username || "").toLowerCase();
      const bn = String(b?.displayName || b?.username || "").toLowerCase();
      return an.localeCompare(bn);
    });

  dmGroupMembersCacheByConversation.set(convId, members);

  const memberIds = members.map((m) => m.userId);
  const memberDisplayNames = members.map((m) => m.displayName);
  const memberUsernames = members.map((m) => m.username);
  const nextMeta = {
    memberCount: members.length,
    memberIds,
    memberDisplayNames,
    memberUsernames,
  };
  setConversationMeta(convId, nextMeta);
  if (normId(state.activeDm?.conversationId || activeDmId || "") === convId) {
    state.activeDm = {
      ...(state.activeDm || {}),
      ...nextMeta,
    };
  }

  return members;
}
async function getGroupConversationMemberIds(conversationId, { includeSelf = false, force = false } = {}) {
  const convId = normId(conversationId);
  if (!convId) return [];
  const activeMeta = getActiveConversationMeta(convId) || {};
  const serverCtx = findServerChannelContextByConversationId(convId);
  const serverId = normId(activeMeta?.serverId || state.activeDm?.serverId || serverCtx?.serverId || "");
  const isServerConversation = String(activeMeta?.kind || "").trim().toLowerCase() === "server" || !!serverId;

  let memberIds = [];

  if (isServerConversation && serverId) {
    let serverMembers = Array.isArray(serverMemberListByServerId.get(serverId))
      ? (serverMemberListByServerId.get(serverId) || [])
      : [];
    if (force || !serverMembers.length) {
      try {
        serverMembers = await fetchServerMembersForSidebar(serverId, { force });
      } catch (e) {
        console.warn("server members resolve failed for call targets", e);
      }
    }

    const normalizedServerMembers = (Array.isArray(serverMembers) ? serverMembers : [])
      .map((row) => {
        const uid = normId(row?.userId || "");
        if (!uid) return null;
        const username = String(row?.username || "").trim();
        const displayName = normalizeGroupMemberLabel(row?.displayName, username, uid.slice(0, 8));
        return {
          userId: uid,
          username,
          displayName,
          avatarUrl: String(row?.avatarUrl || "").trim(),
          nameColor: normalizeNameColor(row?.nameColor || ""),
        };
      })
      .filter(Boolean);

    if (normalizedServerMembers.length) {
      dmGroupMembersCacheByConversation.set(convId, normalizedServerMembers);

      memberIds = normalizedServerMembers.map((m) => m.userId);
      const memberDisplayNames = normalizedServerMembers.map((m) => m.displayName);
      const memberUsernames = normalizedServerMembers.map((m) => m.username);
      const nextMeta = {
        memberCount: normalizedServerMembers.length,
        memberIds,
        memberDisplayNames,
        memberUsernames,
      };
      setConversationMeta(convId, nextMeta);
      if (normId(state.activeDm?.conversationId || activeDmId || "") === convId) {
        state.activeDm = {
          ...(state.activeDm || {}),
          ...nextMeta,
        };
      }
    }
  }

  if (!memberIds.length) {
    memberIds = normalizeUuidArray(activeMeta?.memberIds);
  }
  const canUseConversationMembersFallback = !isServerConversation || !serverId;
  if ((!memberIds.length || force) && canUseConversationMembersFallback) {
    const members = await fetchGroupConversationMembers(convId, { force });
    memberIds = members.map((m) => normId(m?.userId)).filter(Boolean);
  }
  const meId = normId(state.user?.id || "");
  return memberIds.filter((uid) => includeSelf || uid !== meId);
}

function findGroupMemberInfo(conversationId, userId) {
  const uid = normId(userId);
  if (!uid) return null;
  const members = getGroupConversationMembersCache(conversationId);
  return members.find((m) => normId(m?.userId) === uid) || null;
}

function getDmPeerProfileSeed() {
  const uid = getActiveDmPeerUserId();
  if (!uid) return null;
  const cached = getCachedProfile(uid) || {};
  return {
    id: uid,
    username: state.activeDm?.username || cached?.username || "",
    display_name: state.activeDm?.displayName || cached?.display_name || cached?.username || "",
    avatar_url: state.activeDm?.avatarUrl || state.activeDm?.avatar_url || cached?.avatar_url || cached?.avatarUrl || "",
    bio: typeof cached?.bio === "string" ? cached.bio : "",
    name_color: state.activeDm?.name_color || cached?.name_color || "",
    call_tile_color: state.activeDm?.call_tile_color || cached?.call_tile_color || "",
    banner_url: state.activeDm?.banner_url || cached?.banner_url || cached?.theme_settings?.banner_url || "",
  };
}

function dmStatusLabel(status) {
  if (status === "online") return "online";
  if (status === "idle") return "ausente";
  if (status === "dnd") return "ocupado";
  return "offline";
}

function closeGroupMemberMenu(reason = "action") {
  const menu = document.getElementById("dmGroupMemberMenu");
  if (!menu) return;
  const wasOpen = menu.classList.contains("is-open");
  menu.classList.remove("is-open");
  dmGroupMemberMenuTarget = null;
  if (wasOpen) recordAltaraContextMenuClose("group_member", reason);
}

async function ringGroupMember(memberUserId) {
  const uid = normId(memberUserId);
  const meId = normId(state.user?.id || "");
  const convId = normId(activeDmId || callConversationId || state.activeDm?.conversationId || "");
  if (!uid || !convId || !meId || uid === meId) return;

  const activeMeta = getActiveConversationMeta(convId) || {};
  if (!isGroupConversationMeta(activeMeta)) {
    alert("Ring só funciona em Group DM.");
    return;
  }

  const callActive = !!(
    inCall ||
    (callPc && callPc.connectionState !== "closed" && callPc.connectionState !== "failed") ||
    ringTimeout
  );
  const sameConversation = normId(callConversationId || activeDmId || "") === convId;
  if (!callActive || !sameConversation || !groupCallMode) {
    alert("Entra primeiro numa chamada deste grupo.");
    return;
  }

  const memberInfo = findGroupMemberInfo(convId, uid) || {};
  const memberLabel = memberInfo?.displayName || memberInfo?.username || t("call.member", "member");
  await sendCallSignal("ice", {
    signal: "group_ring",
    group_call: true,
    from_label: state.me?.display_name || state.me?.username || t("call.someone", "someone"),
    from_avatar: state.me?.avatar_url || null,
    manual: true,
  }, uid, convId);
  setCallStatus(`?? A chamar ${memberLabel} para a call...`, true);
}

function ensureGroupMemberMenu() {
  let menu = document.getElementById("dmGroupMemberMenu");
  if (!menu) {
    menu = document.createElement("div");
    menu.id = "dmGroupMemberMenu";
    menu.className = "msgMenu";
    document.body.appendChild(menu);
  }

  if (dmGroupMemberMenuBound) return menu;
  dmGroupMemberMenuBound = true;

  bindStableAltaraContextMenu(menu, {
    type: "group_member",
    close: closeGroupMemberMenu,
    getAnchor: () => altaraContextMenuDebugState.currentType === "group_member" ? altaraContextMenuDebugState.anchorEl : null,
  });

  menu.addEventListener("click", async (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    const actionBtn = target.closest("[data-group-member-act]");
    if (!actionBtn) return;
    e.preventDefault();
    const action = String(actionBtn.getAttribute("data-group-member-act") || "").trim().toLowerCase();
    const targetUserId = normId(actionBtn.getAttribute("data-group-member-id") || "");
    closeGroupMemberMenu();
    if (action === "ring" && targetUserId) {
      await ringGroupMember(targetUserId);
    }
  });

  return menu;
}

function openGroupMemberMenuAt(memberUserId, point, { canRing = false } = {}) {
  const uid = normId(memberUserId);
  if (!uid || !point) return;
  closeMessageMenu("open_other_menu");
  closeDmListMenus("open_other_menu");
  const menu = ensureGroupMemberMenu();
  const memberInfo = findGroupMemberInfo(activeDmId, uid) || {};
  const label = memberInfo?.displayName || memberInfo?.username || t("call.member", "member");

  menu.innerHTML = [
    `<button class="msgMenu__item${canRing ? "" : " is-disabled"}" data-group-member-act="ring" data-group-member-id="${escAttr(uid)}" ${canRing ? "" : "disabled"}><span>Ring ${esc(label)}</span><span>&#x1F4DE;</span></button>`,
  ].join("");

  menu.classList.add("is-open");
  dmGroupMemberMenuTarget = uid;
  setAltaraContextMenuOpen({ type: "group_member", targetId: uid, targetKind: "group_member", menuId: "dmGroupMemberMenu", point, reason: "contextmenu" });

  const vw = window.innerWidth || document.documentElement.clientWidth || 0;
  const vh = window.innerHeight || document.documentElement.clientHeight || 0;
  const menuWidth = 220;
  const menuHeight = Math.max(40, menu.offsetHeight || 44);
  let left = Number(point.x || 0);
  let top = Number(point.y || 0);
  if (left + menuWidth > vw - 8) left = Math.max(8, vw - menuWidth - 8);
  if (top + menuHeight > vh - 8) top = Math.max(8, vh - menuHeight - 8);
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
}

