  modal.className = "modal hidden";
  modal.setAttribute("aria-hidden", "true");
  modal.innerHTML = `
    <div class="modal__backdrop" data-close="1"></div>
    <div class="modalCard dmFriendNicknameModalCard" role="dialog" aria-modal="true" aria-labelledby="dmFriendNicknameTitle">
      <div class="modalTop">
        <div class="modalTitle" id="dmFriendNicknameTitle">Change Friend Nickname</div>
        <button class="icon-btn" type="button" id="btnDmFriendNicknameClose" aria-label="Close">×</button>
      </div>
      <div class="modal__body dmFriendNicknameModalBody">
        <label class="dmFriendNicknameFieldLabel" for="dmFriendNicknameInput">Nickname</label>
        <input
          id="dmFriendNicknameInput"
          class="input dmFriendNicknameInput"
          type="text"
          maxlength="48"
          placeholder="Write a nickname..."
          autocomplete="off"
        />
        <div class="hint dmFriendNicknameHint">Leave empty to remove nickname.</div>
      </div>
      <div class="dmFriendNicknameModalActions">
        <button class="btn ghost" type="button" id="btnDmFriendNicknameCancel">Cancel</button>
        <button class="btn" type="button" id="btnDmFriendNicknameSave">Save</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
