function requestServerFolderRename(seedName = "Folder", currentValue = "") {
  const bridge = window?.altaraDesktop;
  const isDesktopApp = !!bridge && bridge.isDesktopApp === true;

  if (!isDesktopApp) {
    try {
      return requestAppPrompt(`Folder name for ${seedName}`, {
        title: "Rename Folder",
        label: "Folder name",
        defaultValue: currentValue || "",
        placeholder: "Write a folder name...",
        hint: "Leave empty to reset the name.",
        okText: "Save",
        cancelText: t("dialog.confirm.cancel", "Cancel"),
        maxLength: 48,
        selectText: true,
        preserveWhitespace: true,
      });
    } catch (_) {
      return Promise.resolve(null);
    }
  }

  const modal = ensureServerFolderRenameModal();
  const titleEl = document.getElementById("serverFolderRenameTitle");
  const inputEl = document.getElementById("serverFolderRenameInput");
  const btnClose = document.getElementById("btnServerFolderRenameClose");
  const btnCancel = document.getElementById("btnServerFolderRenameCancel");
  const btnSave = document.getElementById("btnServerFolderRenameSave");
  if (!modal || !inputEl || !btnClose || !btnCancel || !btnSave) return Promise.resolve(null);

  if (serverFolderRenameModalBound !== true) {
    serverFolderRenameModalBound = true;
    modal.addEventListener("click", (e) => {
      const target = eventTargetElement(e);
      if (!target) return;
      if (target.dataset?.close) {
        closeServerFolderRenameModal(null);
      }
    });
    btnClose.addEventListener("click", () => closeServerFolderRenameModal(null));
    btnCancel.addEventListener("click", () => closeServerFolderRenameModal(null));
    btnSave.addEventListener("click", () => closeServerFolderRenameModal(String(inputEl.value || "")));
    inputEl.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        closeServerFolderRenameModal(null);
        return;
      }
      if (e.key === "Enter") {
        e.preventDefault();
        closeServerFolderRenameModal(String(inputEl.value || ""));
      }
    });
  }

  if (typeof titleEl?.textContent === "string") {
    titleEl.textContent = `Rename Folder - ${seedName}`;
  }
  inputEl.value = String(currentValue || "");
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  requestAnimationFrame(() => {
    try {
      inputEl.focus();
      inputEl.select();
    } catch (_) {}
  });

  return new Promise((resolve) => {
    serverFolderRenamePromptResolver = resolve;
  });
}

function ensureAppConfirmModal() {
  return document.getElementById("appConfirmModal");
}

function getAppConfirmInputControls() {
  return {
    wrap: document.getElementById("appConfirmInputWrap"),
    label: document.getElementById("appConfirmInputLabel"),
    input: document.getElementById("appConfirmInput"),
    passwordInput: document.getElementById("appConfirmPasswordInput"),
    hint: document.getElementById("appConfirmInputHint"),
  };
}

function getActiveAppConfirmInputElement() {
  const { input, passwordInput } = getAppConfirmInputControls();
  const inputType = String(appConfirmPromptOptions?.inputType || "").trim().toLowerCase();
  if (inputType === "password" && passwordInput instanceof HTMLInputElement) return passwordInput;
  return input;
}

function closeAppConfirmModal(result = false) {
  const modal = ensureAppConfirmModal();
  if (!modal) return;
  modal.classList.add("hidden");
  modal.setAttribute("aria-hidden", "true");
  modal.classList.remove(
    "appConfirmModal--alert",
    "appConfirmModal--confirm",
    "appConfirmModal--prompt",
    "appConfirmModal--danger"
  );

  const promptMode = appConfirmPromptMode;
  const { wrap, input, passwordInput, hint } = getAppConfirmInputControls();
  const activeInput = getActiveAppConfirmInputElement();
  const inputRawValue = (activeInput instanceof HTMLTextAreaElement || activeInput instanceof HTMLInputElement) ? String(activeInput.value || "") : "";
  const inputValue = appConfirmPromptOptions?.preserveWhitespace ? inputRawValue : inputRawValue.trim();
  if (wrap instanceof HTMLElement) {
    wrap.hidden = true;
    wrap.style.display = "none";
  }
  if (hint instanceof HTMLElement) hint.textContent = "";
  if (input instanceof HTMLTextAreaElement) {
    input.value = "";
    input.placeholder = "";
    input.disabled = false;
    input.hidden = false;
  }
  if (passwordInput instanceof HTMLInputElement) {
    passwordInput.value = "";
    passwordInput.placeholder = "";
    passwordInput.disabled = false;
    passwordInput.hidden = true;
  }

  const resolver = appConfirmPromptResolver;
  appConfirmPromptResolver = null;
  appConfirmPromptOptions = {};
  if (typeof resolver === "function") {
    try {
      resolver(promptMode === "prompt" ? (result ? inputValue : null) : !!result);
    } catch (_) {}
  }
}

function requestAppConfirm(message = "", options = {}) {
  const requestedMode = String(options?.mode || "confirm").trim().toLowerCase();
  const mode = requestedMode === "alert"
    ? "alert"
    : (requestedMode === "prompt" ? "prompt" : "confirm");
  const modal = ensureAppConfirmModal();
  const titleEl = document.getElementById("appConfirmTitle");
  const messageEl = document.getElementById("appConfirmMessage");
  const btnClose = document.getElementById("btnAppConfirmClose");
  const btnCancel = document.getElementById("btnAppConfirmCancel");
  const btnOk = document.getElementById("btnAppConfirmOk");
  const { wrap: inputWrap, label: inputLabel, input: inputEl, passwordInput: passwordInputEl, hint: inputHint } = getAppConfirmInputControls();

  if (!modal || !titleEl || !messageEl || !btnClose || !btnCancel || !btnOk) {
    try {
      if (mode === "prompt") {
        const nativePrompt = typeof window !== "undefined" && typeof window.prompt === "function"
          ? window.prompt.bind(window)
          : null;
        if (!nativePrompt) return Promise.resolve(null);
        const fallbackValue = nativePrompt(String(message || ""), String(options?.defaultValue || ""));
        if (fallbackValue === null) return Promise.resolve(null);
        const nextValue = String(fallbackValue || "").trim();
        if (options?.requireValue && !nextValue) return Promise.resolve(null);
        return Promise.resolve(nextValue);
      }
      if (mode === "alert") {
        const nativeAlert = appNativeAlertFn
          || (typeof window !== "undefined" && typeof window.alert === "function"
            ? window.alert.bind(window)
            : null);
        if (nativeAlert) nativeAlert(String(message || ""));
        return Promise.resolve(true);
      }
      return Promise.resolve(window.confirm(String(message || "")));
    } catch (_) {
      return Promise.resolve(mode === "prompt" ? null : mode === "alert");
    }
  }

  const showCancel = mode !== "alert";
  const danger = options?.danger === true;
  const titleText = String(options?.title || "").trim()
    || (mode === "alert"
      ? t("dialog.notice.title", "Notice")
      : t("dialog.confirm.title", "Confirm action"));
  const okText = String(options?.okText || options?.confirmText || "").trim()
    || (mode === "alert" ? t("dialog.notice.ok", "OK") : t("dialog.confirm.ok", "Confirm"));
  const cancelText = String(options?.cancelText || "").trim() || t("dialog.confirm.cancel", "Cancel");

  if (appConfirmModalBound !== true) {
    appConfirmModalBound = true;
    modal.addEventListener("click", (e) => {
      const target = eventTargetElement(e);
      if (!target) return;
      if (target.dataset?.appConfirmClose) {
        closeAppConfirmModal(appConfirmPromptMode === "alert");
      }
    });
    btnClose.addEventListener("click", () => closeAppConfirmModal(appConfirmPromptMode === "alert"));
    btnCancel.addEventListener("click", () => closeAppConfirmModal(false));
    btnOk.addEventListener("click", () => {
      const input = getActiveAppConfirmInputElement();
      if (appConfirmPromptMode === "prompt" && appConfirmPromptOptions?.requireValue) {
        const nextValue = (input instanceof HTMLTextAreaElement || input instanceof HTMLInputElement) ? String(input.value || "").trim() : "";
        if (!nextValue) {
          try { input?.focus?.(); } catch (_) {}
          return;
        }
      }
      closeAppConfirmModal(true);
    });
    modal.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        closeAppConfirmModal(appConfirmPromptMode === "alert");
        return;
      }
      if (e.key === "Enter") {
        const { input } = getAppConfirmInputControls();
        if (appConfirmPromptMode === "prompt") {
          const activeInput = getActiveAppConfirmInputElement();
          if (activeInput instanceof HTMLTextAreaElement && !e.ctrlKey && !e.metaKey) return;
          e.preventDefault();
          if (appConfirmPromptOptions?.requireValue) {
            const nextValue = (activeInput instanceof HTMLTextAreaElement || activeInput instanceof HTMLInputElement) ? String(activeInput.value || "").trim() : "";
            if (!nextValue) {
              try { activeInput?.focus?.(); } catch (_) {}
              return;
            }
          }
          closeAppConfirmModal(true);
          return;
        }
        e.preventDefault();
        closeAppConfirmModal(true);
      }
    });
  }

  if (typeof appConfirmPromptResolver === "function") {
    try {
      appConfirmPromptResolver(appConfirmPromptMode === "prompt" ? null : false);
    } catch (_) {}
    appConfirmPromptResolver = null;
  }

  appConfirmPromptMode = mode;
  appConfirmPromptOptions = { ...(options || {}) };
  titleEl.textContent = titleText;
  messageEl.textContent = String(message || "");
  btnOk.textContent = okText;
  btnCancel.textContent = cancelText;
  btnCancel.style.display = showCancel ? "" : "none";
  btnClose.style.display = showCancel ? "" : "none";
  btnOk.classList.toggle("danger", danger);
  btnOk.classList.toggle("primary", !danger);
  modal.classList.toggle("appConfirmModal--alert", mode === "alert");
  modal.classList.toggle("appConfirmModal--confirm", mode === "confirm");
  modal.classList.toggle("appConfirmModal--prompt", mode === "prompt");
  modal.classList.toggle("appConfirmModal--danger", danger);
  if (inputWrap instanceof HTMLElement) {
    const showPromptInput = mode === "prompt";
    inputWrap.hidden = !showPromptInput;
    inputWrap.style.display = showPromptInput ? "" : "none";
  }
  const promptInputType = String(options?.inputType || "").trim().toLowerCase();
  const usePasswordInput = promptInputType === "password";
  if (inputLabel instanceof HTMLElement) {
    inputLabel.textContent = String(options?.label || "").trim() || t("moderation.prompt.label", "Message");
    inputLabel.setAttribute("for", usePasswordInput ? "appConfirmPasswordInput" : "appConfirmInput");
  }
  if (inputHint instanceof HTMLElement) {
    inputHint.textContent = mode === "prompt"
      ? String(options?.hint || "").trim()
      : "";
  }
  if (inputEl instanceof HTMLTextAreaElement) {
    inputEl.hidden = usePasswordInput;
    inputEl.value = mode === "prompt" && !usePasswordInput ? String(options?.defaultValue || "") : "";
    inputEl.placeholder = mode === "prompt" && !usePasswordInput ? String(options?.placeholder || "") : "";
    inputEl.maxLength = Math.max(0, Number(options?.maxLength) || 4000);
    inputEl.disabled = false;
  }
  if (passwordInputEl instanceof HTMLInputElement) {
    passwordInputEl.hidden = !usePasswordInput;
    passwordInputEl.value = mode === "prompt" && usePasswordInput ? String(options?.defaultValue || "") : "";
    passwordInputEl.placeholder = mode === "prompt" && usePasswordInput ? String(options?.placeholder || "") : "";
    passwordInputEl.maxLength = Math.max(0, Number(options?.maxLength) || 4000);
    passwordInputEl.disabled = false;
  }

  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");

  requestAnimationFrame(() => {
    const activePromptInput = getActiveAppConfirmInputElement();
    if (mode === "prompt" && (activePromptInput instanceof HTMLTextAreaElement || activePromptInput instanceof HTMLInputElement)) {
      try {
        activePromptInput.focus();
        if (options?.selectText) activePromptInput.select();
        else activePromptInput.setSelectionRange(activePromptInput.value.length, activePromptInput.value.length);
        return;
      } catch (_) {}
    }
    try { btnOk.focus(); } catch (_) {}
  });

  return new Promise((resolve) => {
    appConfirmPromptResolver = resolve;
  });
}

function requestAppAlert(message = "", options = {}) {
  return requestAppConfirm(message, { ...(options || {}), mode: "alert" });
}

function requestAppPrompt(message = "", options = {}) {
  return requestAppConfirm(message, { ...(options || {}), mode: "prompt" });
}

function installAppAlertShim() {
  if (appAlertShimInstalled) return;
  appAlertShimInstalled = true;
  if (typeof window === "undefined") return;

  try {
    if (typeof window.alert === "function") {
      appNativeAlertFn = window.alert.bind(window);
    }
  } catch (_) {
    appNativeAlertFn = null;
  }

  try {
    window.alert = (message = "") => {
      const text = String(message ?? "");
      if (typeof requestAppAlert === "function") {
        void requestAppAlert(text, {
          okText: t("dialog.notice.ok", "OK"),
        });
        return;
      }
      try { appNativeAlertFn?.(text); } catch (_) {}
    };
  } catch (_) {}
}

installAppAlertShim();

function ensureDmUserListMenu() {
  const clearSubmenuHoverCloseTimer = () => {
    if (dmUserListSubmenuHoverTimer) {
      clearTimeout(dmUserListSubmenuHoverTimer);
      dmUserListSubmenuHoverTimer = null;
    }
  };

  const scheduleSubmenuHoverClose = () => {
    if (dmUserListSubmenuHoverTimer) return;
    dmUserListSubmenuHoverTimer = setTimeout(() => {
      dmUserListSubmenuHoverTimer = null;
      const mainMenu = document.getElementById("dmUserListMenu");
      if (!mainMenu || !mainMenu.classList.contains("is-open")) return;
      closeDmMuteDurationMenu();
      closeDmUserRoleMenu();
      closeDmUserModerationMenu();
    }, 130);
  };

  const getActiveServerMemberSubmenu = () => [
    document.getElementById("dmMuteDurationMenu"),
    document.getElementById("dmUserRoleMenu"),
    document.getElementById("dmUserModerationMenu"),
    document.getElementById("serverVoiceMemberMenu"),
  ].find((submenu) => submenu?.classList.contains("is-open")) || null;

  const closeActiveServerMemberSubmenu = (reason = "submenu_close") => {
    const active = getActiveServerMemberSubmenu();
    if (!active) return false;
    const parentAction = String(active.dataset.parentAction || "");
    if (active.id === "dmMuteDurationMenu") closeDmMuteDurationMenu(reason);
    else if (active.id === "dmUserRoleMenu") closeDmUserRoleMenu(reason);
    else if (active.id === "dmUserModerationMenu") closeDmUserModerationMenu(reason);
    else if (active.id === "serverVoiceMemberMenu") closeServerVoiceMemberMenu({ force: true, reason });
    if (parentAction) {
      try {
        document.querySelector(`#dmUserListMenu [data-user-list-act="${cssEscapeAltaraIdentifier(parentAction)}"]`)?.focus?.({ preventScroll: true });
      } catch (_) {}
    }
    return true;
  };

  const bindServerMemberSubmenuHoverBridge = (submenu) => {
    if (!submenu || submenu.dataset.serverMemberHoverBridgeBound === "1") return;
    submenu.dataset.serverMemberHoverBridgeBound = "1";
    submenu.addEventListener("mouseenter", clearSubmenuHoverCloseTimer);
    submenu.addEventListener("mouseleave", scheduleSubmenuHoverClose);
  };

  const getDmUserListSubmenuSide = (submenuWidth = 232, gap = 2, margin = 8) => {
    const mainMenu = document.getElementById("dmUserListMenu");
    const rect = mainMenu?.getBoundingClientRect?.();
    const viewport = getMenuViewportSize();
    if (!rect) return "right";
    const width = Math.max(180, Number(submenuWidth || 232) || 232);
    const rightFits = rect.right + gap + width <= viewport.width - margin;
    const leftFits = rect.left - gap - width >= margin;
    const side = rightFits || !leftFits ? "right" : "left";
    if (mainMenu) mainMenu.dataset.submenuSide = side;
    return side;
  };

  const getDmUserListSubmenuBootstrapPoint = (actionBtn, {
    submenuWidth = 220,
    gap = 2,
  } = {}) => {
    const rect = actionBtn?.getBoundingClientRect?.();
    if (!rect) return { x: 0, y: 0 };
    const side = getDmUserListSubmenuSide(submenuWidth, gap);
    const x = side === "left"
      ? Math.round(rect.left - Number(submenuWidth || 220) - Number(gap || 2))
      : Math.round(rect.right + Number(gap || 2));
    const y = Math.round(rect.top - 2);
    return { x, y };
  };

  const alignDmUserListSubmenuToAction = (submenuMenu, actionBtn, {
    fallbackWidth = 220,
    minHeight = 72,
    gap = 2,
    submenuName = "",
  } = {}) => {
    if (!submenuMenu || !actionBtn) return;
    const measuredWidth = Math.max(
      180,
      Math.round(
        submenuMenu.offsetWidth
          || submenuMenu.getBoundingClientRect?.().width
          || Number(fallbackWidth || 220)
      )
    );
    positionServerMemberSubmenu(submenuMenu, actionBtn, {
      fallbackWidth: measuredWidth,
      margin: 8,
      gap,
      submenuName,
    });
  };

  const openDmUserMuteSubmenuFromAction = (actionBtn, {
    targetId = "",
  } = {}) => {
    const uid = normId(targetId || "");
    if (!actionBtn || !uid) return;
    closeDmUserRoleMenu();
    closeDmUserModerationMenu();
    closeServerVoiceMemberMenu({ force: true, reason: "sibling_submenu" });
    const point = getDmUserListSubmenuBootstrapPoint(actionBtn, { submenuWidth: 198, gap: 2 });
    openDmMuteDurationMenuAt(point, { targetType: "user", targetId: uid });
    const muteMenu = document.getElementById("dmMuteDurationMenu");
    bindServerMemberSubmenuHoverBridge(muteMenu);
    alignDmUserListSubmenuToAction(muteMenu, actionBtn, {
      fallbackWidth: 198,
      minHeight: 180,
      gap: 2,
      submenuName: "mute",
    });
  };

  const openDmUserRoleSubmenuFromAction = async (actionBtn, {
    serverId = "",
    userId = "",
    username = "",
    displayName = "",
    avatarUrl = "",
  } = {}) => {
    const sid = normId(serverId || "");
    const uid = normId(userId || "");
    if (!actionBtn || !sid || !uid) return false;
    closeDmMuteDurationMenu();
    closeDmUserModerationMenu();
    closeServerVoiceMemberMenu({ force: true, reason: "sibling_submenu" });
    const point = getDmUserListSubmenuBootstrapPoint(actionBtn, { submenuWidth: 232, gap: 2 });
    const opened = await openDmUserRoleMenuAt(point, {
      serverId: sid,
      userId: uid,
      username,
      displayName,
      avatarUrl,
    });
    if (!opened) return false;
    const roleMenu = document.getElementById("dmUserRoleMenu");
    bindServerMemberSubmenuHoverBridge(roleMenu);
    alignDmUserListSubmenuToAction(roleMenu, actionBtn, {
      fallbackWidth: 232,
      minHeight: 120,
      gap: 2,
      submenuName: "roles",
    });
    return true;
  };

  const getDmUserModerationMenuMeta = (serverId = "", targetUserId = "") => {
    const sid = normId(serverId || "");
    const uid = normId(targetUserId || "");
    const permissionResolved = !!(
      serverRolePermissionCacheFetchedAtByServerId.has(sid)
      || getServerCapabilityMeta(sid).isOwner
      || getServerCapabilityMeta(sid).isActualOwner
    );
    const context = getServerMemberManagementContext(sid, uid);
    const nickname = getServerNicknameActionState(sid, uid);
    const hierarchyAllowed = !!(
      sid
      && uid
      && !context.isSelf
      && !context.targetIsOwner
      && (context.actorIsOwner || context.targetBelowActor)
    );
    let hierarchyReason = "";
    if (context.isSelf) hierarchyReason = "You cannot moderate yourself.";
    else if (context.targetIsOwner) hierarchyReason = "The server owner cannot be moderated.";
    else if (!hierarchyAllowed) hierarchyReason = "This member has an equal or higher role.";
    return {
      serverId: sid,
      targetUserId: uid,
      permissionResolved,
      context,
      hierarchyAllowed,
      hierarchyReason,
      canKick: !!(permissionResolved && hierarchyAllowed && context.canKick),
      canBan: !!(permissionResolved && hierarchyAllowed && context.canBan),
      canTimeout: !!(permissionResolved && hierarchyAllowed && context.canTimeout),
      timeoutActive: !!getServerMemberTimeout(sid, uid),
      canChangeNickname: !!(permissionResolved && !context.isSelf && nickname.allowed),
      nicknameReason: nickname.reason,
    };
  };

  const buildDmUserModerationMenuHtml = (context = {}) => {
    const meta = getDmUserModerationMenuMeta(context.serverId, context.targetUserId);
    const displayName = normalizeConversationLabel(context.displayName || context.username || "member", "member");
    const kickHint = !meta.permissionResolved
      ? "Checking permissions..."
      : (!meta.hierarchyAllowed ? meta.hierarchyReason : (!meta.context.canKick ? "Requires Kick Members." : ""));
    const banHint = !meta.permissionResolved
      ? "Checking permissions..."
      : (!meta.hierarchyAllowed ? meta.hierarchyReason : (!meta.context.canBan ? "Requires Ban Members." : ""));
    const timeoutHint = !meta.permissionResolved
      ? "Checking permissions..."
      : (!meta.hierarchyAllowed ? meta.hierarchyReason : (!meta.context.canTimeout ? "Requires Timeout Members." : ""));
    const nicknameHint = !meta.permissionResolved
      ? "Checking permissions..."
      : (meta.canChangeNickname ? "" : (
        meta.nicknameReason === "managed_bot_nickname_locked"
          ? "Managed bot nickname is locked."
          : (meta.nicknameReason === "target_is_owner"
            ? "The server owner is protected."
            : (meta.nicknameReason === "role_hierarchy_blocked"
              ? "This member has an equal or higher role."
              : "Requires Change Own Nickname or Manage Nicknames."))
      ));
    const action = (name, label, enabled, hint, { danger = false } = {}) => `
      <button
        class="msgMenu__item${danger ? " msgMenu__item--danger" : ""}${enabled ? "" : " is-disabled"}"
        type="button"
        data-user-moderation-act="${escAttr(name)}"
        ${enabled ? "" : "disabled"}
      >
        <span class="msgMenu__itemMain"><span>${esc(label)}</span>${hint ? `<span class="msgMenu__itemHint">${esc(hint)}</span>` : ""}</span>
      </button>
    `;
    return [
      `<div class="msgMenu__meta">${esc(displayName)} • Server Moderation</div>`,
      `<div class="msgMenu__divider"></div>`,
      action("nickname", "Change Server Nickname", meta.canChangeNickname, nicknameHint),
      action(meta.timeoutActive ? "remove_timeout" : "timeout", meta.timeoutActive ? "Remove Timeout" : "Timeout Member", meta.canTimeout, timeoutHint),
      action("kick", "Kick from Server", meta.canKick, kickHint, { danger: true }),
      action("ban", "Ban from Server", meta.canBan, banHint, { danger: true }),
    ].join("");
  };

  const ensureDmUserModerationMenu = () => {
    let moderationMenu = document.getElementById("dmUserModerationMenu");
    if (!moderationMenu) {
      moderationMenu = document.createElement("div");
      moderationMenu.id = "dmUserModerationMenu";
      moderationMenu.className = "msgMenu msgMenu--submenu";
      document.body.appendChild(moderationMenu);
    }
    if (dmUserModerationMenuBound) return moderationMenu;
    dmUserModerationMenuBound = true;
    bindStableAltaraContextMenu(moderationMenu, {
      type: "user_moderation_submenu",
      close: closeDmUserModerationMenu,
      getAnchor: () => altaraContextMenuDebugState.anchorEl,
    });
    moderationMenu.addEventListener("click", async (event) => {
      const target = eventTargetElement(event);
      const actionButton = target?.closest?.("[data-user-moderation-act]");
      if (!actionButton || actionButton.disabled || dmUserModerationMenuBusy) return;
      event.preventDefault();
      const action = String(actionButton.getAttribute("data-user-moderation-act") || "").trim().toLowerCase();
      const current = dmUserModerationMenuTarget ? { ...dmUserModerationMenuTarget } : null;
      if (!current?.serverId || !current?.targetUserId || !["nickname", "timeout", "remove_timeout", "kick", "ban"].includes(action)) return;
      const meta = getDmUserModerationMenuMeta(current.serverId, current.targetUserId);
      if (
        (action === "nickname" && !meta.canChangeNickname)
        || ((action === "timeout" || action === "remove_timeout") && !meta.canTimeout)
        || (action === "kick" && !meta.canKick)
        || (action === "ban" && !meta.canBan)
      ) return;
      dmUserModerationMenuBusy = true;
      if (action === "nickname") {
        serverMemberContextMenuReturnFocusEl = dmUserListMenuState?.openTargetEl || null;
      }
      closeDmListMenus("action");
      try {
        if (action === "nickname") {
          await openServerNicknameModal(current.serverId, current.targetUserId, { source: "server-member-context-menu" });
        } else if (action === "timeout") {
          await openServerSettingsTimeoutModal(current.targetUserId, { serverId: current.serverId });
        } else if (action === "remove_timeout") {
          await handleServerSettingsMemberClearTimeout(current.targetUserId, { serverId: current.serverId });
        } else if (action === "kick") {
          await handleServerSettingsMemberKick(current.targetUserId, { serverId: current.serverId });
        } else {
          await handleServerSettingsMemberBan(current.targetUserId, { serverId: current.serverId });
        }
      } finally {
        dmUserModerationMenuBusy = false;
      }
    });
    return moderationMenu;
  };

  const openDmUserModerationSubmenuFromAction = async (actionBtn, {
    serverId = "",
    userId = "",
    username = "",
    displayName = "",
  } = {}) => {
    const sid = normId(serverId || "");
    const uid = normId(userId || "");
    if (!actionBtn || !sid || !uid) return false;
    const rootOpenedAt = Number(dmUserListMenuState?.openedAt || 0);
    closeDmMuteDurationMenu();
    closeDmUserRoleMenu();
    closeServerVoiceMemberMenu({ force: true, reason: "sibling_submenu" });
    await ensureServerRolePermissionCache(sid, { force: false }).catch(() => {});
    if (
      !document.getElementById("dmUserListMenu")?.classList.contains("is-open")
      || Number(dmUserListMenuState?.openedAt || 0) !== rootOpenedAt
      || normId(dmUserListMenuState?.targetUserId || "") !== uid
    ) return false;
    const moderationMenu = ensureDmUserModerationMenu();
    bindServerMemberSubmenuHoverBridge(moderationMenu);
    dmUserModerationMenuTarget = { serverId: sid, targetUserId: uid, username, displayName };
    moderationMenu.innerHTML = buildDmUserModerationMenuHtml(dmUserModerationMenuTarget);
    moderationMenu.classList.add("is-open");
    const point = getDmUserListSubmenuBootstrapPoint(actionBtn, { submenuWidth: 252, gap: 2 });
    positionMenuAtPoint(moderationMenu, point, { width: 252, minHeight: 120, margin: 8 });
    alignDmUserListSubmenuToAction(moderationMenu, actionBtn, {
      fallbackWidth: 252,
      minHeight: 120,
      gap: 2,
      submenuName: "moderation",
    });
    return true;
  };

  const openDmUserVoiceSubmenuFromAction = async (actionBtn) => {
    if (!actionBtn || actionBtn.disabled) return false;
    const uid = normId(actionBtn.getAttribute("data-user-list-id") || "");
    const sid = normId(actionBtn.getAttribute("data-user-list-server-id") || "");
    let conversationId = normId(actionBtn.getAttribute("data-user-list-server-voice-conv") || "");
    if (!uid || !sid) return false;
    const rootOpenedAt = Number(dmUserListMenuState?.openedAt || 0);
    if (!conversationId) conversationId = resolveServerVoiceMenuConversationForMember(sid, uid);
    if (!conversationId) return false;
    await ensureServerRolePermissionCache(sid, { force: false }).catch(() => {});
    if (
      !document.getElementById("dmUserListMenu")?.classList.contains("is-open")
      || Number(dmUserListMenuState?.openedAt || 0) !== rootOpenedAt
      || normId(dmUserListMenuState?.targetUserId || "") !== uid
    ) return false;
    closeDmMuteDurationMenu();
    closeDmUserRoleMenu();
    closeDmUserModerationMenu();
    const rect = actionBtn.getBoundingClientRect?.() || {};
    const opened = tryOpenServerVoiceMemberMenuAt(uid, conversationId, {
      x: Number(rect.right || 0),
      y: Number(rect.top || 0),
    }, {
      displayName: String(actionBtn.getAttribute("data-user-list-display") || "").trim(),
      serverId: sid,
      anchorEl: actionBtn,
      asSubmenu: true,
    });
    if (
      !opened
      || !document.getElementById("dmUserListMenu")?.classList.contains("is-open")
      || Number(dmUserListMenuState?.openedAt || 0) !== rootOpenedAt
      || normId(dmUserListMenuState?.targetUserId || "") !== uid
    ) {
      closeDmUserRoleMenu("stale_submenu");
      return false;
    }
    bindServerMemberSubmenuHoverBridge(document.getElementById("serverVoiceMemberMenu"));
    positionServerMemberSubmenu(document.getElementById("serverVoiceMemberMenu"), actionBtn, {
      fallbackWidth: 286,
      margin: 8,
      gap: 4,
      submenuName: "voice",
    });
    return true;
  };

  function getDmUserRoleMenuMeta(serverId, targetUserId) {
    const sid = normId(serverId || "");
    const uid = normId(targetUserId || "");
    const base = {
      canOpen: false,
      reason: "",
      hasRoles: false,
      isSelf: false,
      canTouchTarget: false,
    };
    if (!sid || !uid) return base;

    const roleList = serverRoleListByServerId.get(sid) || [];
    const hasRoles = Array.isArray(roleList) && roleList.length > 0;
    const meId = normId(state.user?.id || "");
    const isSelf = !!(meId && uid === meId);
    const caps = getServerCapabilityMeta(sid);
    const canManageRoles = currentUserCanManageRoles(sid);
    const moderation = canServerActorModerateTargetWithPermission({
      serverId: sid,
      actorUserId: meId,
      targetUserId: uid,
    });
    const canTouchTarget = !!(isSelf || moderation?.canTouchTarget);
    const canOpen = !!(canManageRoles && hasRoles && canTouchTarget);

    let reason = "";
    if (!canManageRoles) reason = "Sem permissao para gerir roles.";
    else if (!hasRoles) reason = "Sem roles custom neste server.";
    else if (!canTouchTarget) reason = "Nao podes gerir roles deste membro.";

    return { canOpen, reason, hasRoles, isSelf, canTouchTarget };
  }

  function buildDmUserRoleMenuHtml(context = {}) {
    const sid = normId(context.serverId || "");
    const uid = normId(context.targetUserId || "");
    const displayName = normalizeConversationLabel(
      context.displayName || context.username || "member",
      "member"
    );
    const roleList = (serverRoleListByServerId.get(sid) || []).slice();
    const roleMap = serverRoleMemberMapByServerId.get(sid) || new Map();
    const meta = getDmUserRoleMenuMeta(sid, uid);
    const disabledAll = !meta.canOpen || dmUserRoleMenuBusy;

    const rows = roleList.map((role) => {
      const rid = normId(role?.id || "");
      if (!rid) return "";
      const assignedSet = roleMap.get(rid);
      const assigned = !!(assignedSet instanceof Set && assignedSet.has(uid));
      if (isEveryoneServerRole(role)) return "";
  const roleName = normalizeServerRoleName(role?.name || "Role") || "Role";
      const roleColor = normalizeServerRoleColor(role?.color || SERVER_ROLE_DEFAULT_COLOR);
      return `
        <button
          class="msgMenu__item${disabledAll ? " is-disabled" : ""}"
          data-user-role-act="toggle_role"
          data-user-role-server-id="${escAttr(sid)}"
          data-user-role-user-id="${escAttr(uid)}"
          data-user-role-role-id="${escAttr(rid)}"
          ${disabledAll ? "disabled" : ""}
        >
          <span class="msgMenuRoleMain">
            <span class="msgMenuRoleSwatch" style="--role-color:${escAttr(roleColor)}"></span>
            <span>${esc(roleName)}</span>
          </span>
          <span class="msgMenuRoleCheck${assigned ? " is-on" : ""}" aria-hidden="true">${assigned ? "&#10003;" : ""}</span>
        </button>
      `;
    }).filter(Boolean);

    return [
      `<div class="msgMenu__meta">${esc(displayName)} • Roles</div>`,
      `<div class="msgMenu__divider"></div>`,
      rows.length
        ? rows.join("")
        : `<div class="msgMenu__meta">Sem roles custom neste server.</div>`,
      (!meta.canOpen && meta.reason)
        ? `<div class="msgMenu__meta">${esc(meta.reason)}</div>`
        : "",
    ].join("");
  }

  function ensureDmUserRoleMenu() {
    let menu = document.getElementById("dmUserRoleMenu");
    if (!menu) {
      menu = document.createElement("div");
      menu.id = "dmUserRoleMenu";
      menu.className = "msgMenu msgMenu--submenu";
      document.body.appendChild(menu);
    }

    if (dmUserRoleMenuBound) return menu;
    dmUserRoleMenuBound = true;

    bindStableAltaraContextMenu(menu, {
      type: "user_role_submenu",
      close: closeDmUserRoleMenu,
      getAnchor: () => altaraContextMenuDebugState.anchorEl,
    });

    menu.addEventListener("click", async (e) => {
      const target = eventTargetElement(e);
      if (!target) return;
      const actionBtn = target.closest("[data-user-role-act]");
      if (!actionBtn || actionBtn.disabled) return;
      e.preventDefault();

      const action = String(actionBtn.getAttribute("data-user-role-act") || "").trim().toLowerCase();
      if (action !== "toggle_role") return;
      if (dmUserRoleMenuBusy) return;

      const sid = normId(actionBtn.getAttribute("data-user-role-server-id") || "");
      const uid = normId(actionBtn.getAttribute("data-user-role-user-id") || "");
      const rid = normId(actionBtn.getAttribute("data-user-role-role-id") || "");
      if (!sid || !uid || !rid) return;

      const roleMap = serverRoleMemberMapByServerId.get(sid) || new Map();
      const assignedSet = roleMap.get(rid);
      const isAssigned = !!(assignedSet instanceof Set && assignedSet.has(uid));

      dmUserRoleMenuBusy = true;
      const res = await setServerRoleMembershipForServer(sid, {
        roleId: rid,
        userId: uid,
        enabled: !isAssigned,
      });
      dmUserRoleMenuBusy = false;

      if (res?.error) {
        alert(`Erro a atualizar role: ${res.error?.message || res.error}`);
        if (dmUserRoleMenuTarget) {
          menu.innerHTML = buildDmUserRoleMenuHtml(dmUserRoleMenuTarget);
        }
        return;
      }

      applyServerRoleMemberAssignment(sid, rid, uid, !isAssigned);
      if (dmUserRoleMenuTarget) {
        menu.innerHTML = buildDmUserRoleMenuHtml(dmUserRoleMenuTarget);
      }

      const activeCtx = getActiveServerContext();
      if (normId(activeCtx?.serverId || "") === sid) {
        const members = serverMemberListByServerId.get(sid) || [];
        void renderServerMembersRightPanel(activeCtx, members);
      }
      if (normId(serverSettingsServerId || "") === sid) {
        renderServerSettingsRolesUi();
      }
      closeDmListMenus("role_action");
    });

    return menu;
  }

  async function openDmUserRoleMenuAt(point, {
    serverId = "",
    userId = "",
    username = "",
    displayName = "",
    avatarUrl = "",
  } = {}) {
    const sid = normId(serverId || "");
    const uid = normId(userId || "");
    if (!sid || !uid || !point) return false;
    await ensureServerRolePermissionCache(sid, { force: false }).catch(() => {});
    const menu = ensureDmUserRoleMenu();
    dmUserRoleMenuTarget = {
      serverId: sid,
      targetUserId: uid,
      username: String(username || "").trim(),
      displayName: String(displayName || "").trim(),
      avatarUrl: String(avatarUrl || "").trim(),
    };
    menu.innerHTML = buildDmUserRoleMenuHtml(dmUserRoleMenuTarget);
    menu.classList.add("is-open");
    positionMenuAtPoint(menu, point, { width: 232, minHeight: 120 });
    return true;
  }

  let menu = document.getElementById("dmUserListMenu");
  if (!menu) {
    menu = document.createElement("div");
    menu.id = "dmUserListMenu";
    menu.className = "msgMenu";
    document.body.appendChild(menu);
  }

  if (dmUserListMenuBound) return menu;
  dmUserListMenuBound = true;

  document.addEventListener("pointerdown", (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    if (!menu.classList.contains("is-open")) return;
    const now = getContextMenuNow();
    const openedAt = Number(dmUserListMenuState?.openedAt || 0);
    const outsideCloseEnabledAt = Number(dmUserListMenuState?.outsideCloseEnabledAt || 0);
    const eventStamp = Number(e?.timeStamp || 0);
    const isOpeningEvent = !!openedAt && (
      now < outsideCloseEnabledAt
      || (eventStamp && Math.abs(eventStamp - openedAt) < 80)
    );
    if (isOpeningEvent) {
      logContextMenuDebug("ignored opening click", { targetUserId: dmUserListMenuState?.targetUserId || "" });
      return;
    }
    if (eventPathContainsSelector(e, "#dmUserListMenu")) return;
    if (eventPathContainsSelector(e, "#dmMuteDurationMenu")) return;
    if (eventPathContainsSelector(e, "#dmUserRoleMenu")) return;
    if (eventPathContainsSelector(e, "#dmUserModerationMenu")) return;
    if (eventPathContainsSelector(e, "#serverVoiceMemberMenu")) return;
    const opener = dmUserListMenuState?.openTargetEl || null;
    if (opener && eventPathContainsElement(e, opener)) return;
    logContextMenuDebug("outside click close", { targetUserId: dmUserListMenuState?.targetUserId || "" });
    closeDmUserListMenu("outside_click");
  }, true);

  document.addEventListener("mousemove", (e) => {
    if (!menu.classList.contains("is-open")) {
      clearSubmenuHoverCloseTimer();
      return;
    }
    const target = eventTargetElement(e);
    const insideAnyMenu = !!(
      target
      && (
        target.closest("#dmUserListMenu")
        || target.closest("#dmMuteDurationMenu")
        || target.closest("#dmUserRoleMenu")
        || target.closest("#dmUserModerationMenu")
        || target.closest("#serverVoiceMemberMenu")
      )
    );
    if (insideAnyMenu) clearSubmenuHoverCloseTimer();
    else scheduleSubmenuHoverClose();
  });

  window.addEventListener("resize", () => {
    if (!menu.classList.contains("is-open")) return;
    const cursorPoint = dmUserListMenuState?.cursorPoint || null;
    const anchor = dmUserListMenuState?.openTargetEl || null;
    positionServerMemberRootMenu(menu, { point: cursorPoint, anchorEl: anchor, width: 276, margin: 8, offset: 6 });
    closeDmMuteDurationMenu("resize");
    closeDmUserRoleMenu("resize");
    closeDmUserModerationMenu("resize");
    closeServerVoiceMemberMenu({ force: true, reason: "resize" });
    logContextMenuDebug("viewport changed; menu repositioned", { reason: "resize", targetUserId: dmUserListMenuState?.targetUserId || "" });
  });
  window.addEventListener("blur", () => {
    if (menu.classList.contains("is-open")) closeDmListMenus("window_blur");
  });
  window.addEventListener("scroll", (event) => {
    if (!menu.classList.contains("is-open")) return;
    const target = eventTargetElement(event);
    if (target?.closest?.("#dmUserListMenu,#dmMuteDurationMenu,#dmUserRoleMenu,#dmUserModerationMenu,#serverVoiceMemberMenu")) return;
    closeDmListMenus("viewport_scroll");
  }, true);
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      if (closeActiveServerMemberSubmenu("escape_submenu")) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      logContextMenuDebug("escape close", { targetUserId: dmUserListMenuState?.targetUserId || "" });
      closeDmListMenus("escape");
      return;
    }
    if (e.key === "ArrowLeft" && getActiveServerMemberSubmenu()) {
      e.preventDefault();
      e.stopPropagation();
      closeActiveServerMemberSubmenu("keyboard_left");
      return;
    }
    if (e.key === "ArrowRight" && menu.classList.contains("is-open")) {
      const focused = document.activeElement?.closest?.(
        "[data-user-list-act='open_server_roles_menu'],[data-user-list-act='open_server_moderation_menu'],[data-user-list-act='open_server_voice_menu'],[data-user-list-act='mute_open']"
      );
      if (focused && !focused.disabled) {
        e.preventDefault();
        e.stopPropagation();
        focused.click();
        requestAnimationFrame(() => {
          getActiveServerMemberSubmenu()?.querySelector?.(".msgMenu__item:not(:disabled)")?.focus?.({ preventScroll: true });
        });
      }
    }
  });

  menu.addEventListener("click", async (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    const actionBtn = target.closest("[data-user-list-act]");
    if (!actionBtn || actionBtn.disabled) return;
    e.preventDefault();

    const action = String(actionBtn.getAttribute("data-user-list-act") || "").trim().toLowerCase();
    const uid = normId(actionBtn.getAttribute("data-user-list-id") || "");
    const uname = String(actionBtn.getAttribute("data-user-list-username") || "").trim();
    const row = getFriendRowByUserId(uid) || getFriendRowByUsername(uname) || null;
    const resolvedUid = normId(uid || row?.other_user_id || row?.id || "");
    const resolvedUname = String(uname || row?.username || "").trim();
    const display = String(actionBtn.getAttribute("data-user-list-display") || row?.display_name || uname || "User");
    const avatar = String(actionBtn.getAttribute("data-user-list-avatar") || row?.avatar_url || "").trim();
    const serverIdAttr = normId(actionBtn.getAttribute("data-user-list-server-id") || "");
    const dmLockConversationId = normId(actionBtn.getAttribute("data-user-list-dm-id") || "");
    let serverVoiceConvId = normId(actionBtn.getAttribute("data-user-list-server-voice-conv") || "");
    if (!resolvedUid && !resolvedUname) return;

    if (action === "mark_read") {
      closeDmListMenus();
      clearDmUnreadForUser(resolvedUid);
      return;
    }
    if (action === "profile") {
      closeDmListMenus();
      const anchorPoint = { x: e.clientX || 0, y: e.clientY || 0 };
      await openUserCardModal(resolvedUid, {
        username: resolvedUname,
        display_name: display,
        avatar_url: avatar,
      }, {
        point: anchorPoint,
        conversationId: serverVoiceConvId,
        conversationLabel: String(state.activeDm?.displayName || "").trim(),
        serverId: serverIdAttr,
        kind: serverIdAttr ? "server" : "",
        presentation: "overlay",
      });
      return;
    }
    if (action === "message") {
      closeDmListMenus();
      const currentAction = getUserCardMessageActionMeta(resolvedUid, resolvedUname);
      if (currentAction?.action === "open_dm") {
        await startDmWith(resolvedUname, display || resolvedUname, avatar || null, resolvedUid);
        return;
      }
      if (currentAction?.action === "accept_message_request" && currentAction?.requestId) {
        const result = await acceptMessageReq(currentAction.requestId);
        if (result?.ok && result?.conversationId) await showDm(result.conversationId, { autoAnswerIfPending: true });
        return;
      }
      if (currentAction?.action === "pending_message_request" && currentAction?.requestId) {
        openMessageRequestPreview(currentAction.requestId, { direction: "outgoing" });
        return;
      }
      if (currentAction?.action === "send_message_request") {
        await promptAndStartMessageRequest({ id: resolvedUid, username: resolvedUname, display_name: display, avatar_url: avatar }, { source: "sidebar" });
        return;
      }
      if (currentAction?.action === "privacy_blocked" || currentAction?.action === "blocked") {
        await requestAppAlert(currentAction?.reason || "This user isn't accepting messages.", {
          title: "Direct Messages",
          okText: "OK",
        });
      }
      return;
    }
    if (action === "add_friend") {
      closeDmListMenus();
      await sendFriendRequest(resolvedUname, { preserveInput: true });
      refreshOpenUserCard();
      return;
    }
    if (action === "accept_friend_request") {
      closeDmListMenus();
      const requestId = normId(actionBtn.getAttribute("data-user-list-request-id") || "");
      if (requestId) await acceptReq(requestId);
      refreshOpenUserCard();
      return;
    }
    if (action === "accept_message_request") {
      closeDmListMenus();
      const requestId = String(actionBtn.getAttribute("data-user-list-request-id") || "").trim();
      if (!requestId) return;
      const result = await acceptMessageReq(requestId);
      if (result?.ok && result?.conversationId) await showDm(result.conversationId, { autoAnswerIfPending: true });
      return;
    }
    if (action === "ignore_message_request") {
      closeDmListMenus();
      const requestId = String(actionBtn.getAttribute("data-user-list-request-id") || "").trim();
      if (requestId) await rejectMessageReq(requestId);
      return;
    }
    if (action === "block_message_request") {
      closeDmListMenus();
      const requestId = String(actionBtn.getAttribute("data-user-list-request-id") || "").trim();
      if (requestId) await blockMessageReq(requestId);
      return;
    }
    if (action === "start_call") {
      closeDmListMenus();
      const conversationId = await startDmWith(resolvedUname, display, avatar || null, resolvedUid);
      if (conversationId) await startCall(conversationId, resolvedUid, display || resolvedUname || t("call.friend", "friend"));
      return;
    }
    if (action === "toggle_bestfriend") {
      closeDmListMenus();
      toggleDmBestFriend(resolvedUid, { rerender: false });
      renderFriends();
      void loadDmList().catch(() => { reorderDmListByActivity(); });
      return;
    }
    if (action === "edit_nickname") {
      closeDmListMenus();
      if (!resolvedUid) return;
      const currentNickname = getDmFriendNickname(resolvedUid);
      const seedName = display || resolvedUname || "user";
      const nextRaw = await requestDmFriendNickname(seedName, currentNickname || "");
      if (nextRaw === null) return;
      setDmFriendNickname(resolvedUid, nextRaw, { persist: true, syncCloud: true });
      renderFriends();
      void loadDmList().catch(() => { reorderDmListByActivity(); });
      return;
    }
    if (action === "change_server_nickname") {
      if (!resolvedUid || !serverIdAttr) return;
      const nicknameState = getServerNicknameActionState(serverIdAttr, resolvedUid);
      if (!nicknameState.allowed || !nicknameState.isSelf) return;
      serverMemberContextMenuReturnFocusEl = dmUserListMenuState?.openTargetEl || null;
      closeDmListMenus("nickname_action");
      await openServerNicknameModal(serverIdAttr, resolvedUid, { source: "server-member-context-menu-self" });
      return;
    }
    if (action === "close_dm") {
      closeDmListMenus();
      hideDmUser(resolvedUid, { rerender: true });
      return;
    }
    if (action === "lock_dm") {
      closeDmListMenus();
      await createDmLockForUserMenuAction({
        userId: resolvedUid,
        username: resolvedUname,
        displayName: display,
        dmIdHint: dmLockConversationId,
      });
      return;
    }
    if (action === "lock_dm_altara_plus_upsell") {
      closeDmListMenus();
      await requestLockedDmAltaraPlusUpsellModal();
      return;
    }
    if (action === "unlock_dm") {
      closeDmListMenus();
      await unlockDmForUserMenuAction({
        userId: resolvedUid,
        username: resolvedUname,
        dmIdHint: dmLockConversationId,
      });
      return;
    }
    if (action === "lock_dm_again") {
      closeDmListMenus();
      relockDmForSessionFromMenuAction(dmLockConversationId);
      return;
    }
    if (action === "remove_dm_lock") {
      closeDmListMenus();
      await removeDmLockForUserMenuAction({
        userId: resolvedUid,
        username: resolvedUname,
        dmIdHint: dmLockConversationId,
      });
      return;
    }
    if (action === "remove_friend") {
      if (!resolvedUid) return;
      closeDmListMenus();
      const label = display || resolvedUname || "este amigo";
      const ok = await requestAppConfirm(`Remover ${label} dos amigos?`, {
        title: "Friends",
        okText: t("dialog.confirm.ok", "Confirm"),
        cancelText: t("dialog.confirm.cancel", "Cancel"),
        danger: true,
      });
      if (!ok) return;
      const trace = beginRelationshipActionTrace("remove_friend", {
        userId: resolvedUid,
        username: resolvedUname,
      });

      // ── TRUE OPTIMISTIC: patch immediately after confirm, before RPC ──
      const snapshot = relationshipTraceMeasureSync(trace, "snapshotRelationshipState", () => (
        snapshotRelationshipState({ targetUserId: resolvedUid })
      ));
      relationshipTraceMeasureSync(trace, "optimisticPatch", () => {
        optimisticRemoveFriendById(resolvedUid);
        hideDmUser(resolvedUid, { rerender: false });
        clearDmUnreadForUser(resolvedUid);
      });
      renderRelationshipUiNow({
        rerenderFriends: true,
        rerenderPending: true,
        affectedUserId: resolvedUid,
        affectedUsername: resolvedUname,
      });
      relationshipTraceSchedulePaint(trace, "optimisticPaint");
      // ──────────────────────────────────────────────────────────────────

      const { error } = await relationshipTraceMeasureAsync(trace, "rpc:remove_friend", () => (
        removeFriendRpc(resolvedUid)
      ));
      if (error) {
        restoreRelationshipState(snapshot, {
          rerenderFriends: true,
          rerenderPending: true,
          rerenderDmList: true,
          affectedUserId: resolvedUid,
          affectedUsername: resolvedUname,
        });
        relationshipTraceSchedulePaint(trace, "rollbackPaint");
        endRelationshipTrace(trace, "rpc_error", { message: String(error?.message || error || "") });
        if (isMissingRpcError(error)) {
          const proj = getSupabaseProjectRefLabel();
          await requestAppAlert(
            `Falta SQL para remover amigos no Supabase (proj: ${proj}).\n` +
            "Executa o patch SQL: SQL/SUPABASE_PATCH_FRIEND_BLOCK_REMOVE.sql\n" +
            "e depois recarrega a app.",
            { title: "Friends", okText: t("dialog.notice.ok", "OK") }
          );
        } else {
          await requestAppAlert(`Erro ao remover amigo: ${error.message || error}`, {
            title: "Friends",
            okText: t("dialog.notice.ok", "OK"),
          });
        }
        return;
      }
      deferRelationshipTraceToReconcile(trace, { delayMs: 180 });
      scheduleRelationshipReconcile(180, trace);
      return;
    }
    if (action === "block_user") {
      if (!resolvedUid) return;
      closeDmListMenus();
      const label = display || resolvedUname || "este utilizador";
      const ok = await requestAppConfirm(`Bloquear ${label}?\nIsto remove a amizade e pedidos entre voces.`, {
        title: "Block User",
        okText: t("dialog.confirm.ok", "Confirm"),
        cancelText: t("dialog.confirm.cancel", "Cancel"),
        danger: true,
      });
      if (!ok) return;
      const trace = beginRelationshipActionTrace("block_user", {
        userId: resolvedUid,
        username: resolvedUname,
      });

      // ── TRUE OPTIMISTIC: patch immediately after confirm, before RPC ──
      const snapshot = relationshipTraceMeasureSync(trace, "snapshotRelationshipState", () => (
        snapshotRelationshipState({ targetUserId: resolvedUid, includeBlockedUsers: true })
      ));
      relationshipTraceMeasureSync(trace, "optimisticPatch", () => {
        optimisticRemoveFriendById(resolvedUid);
        upsertBlockedUserRow({
          userId: resolvedUid,
          username: resolvedUname,
          displayName: display || resolvedUname || "User",
          avatarUrl: avatar || null,
          createdAt: new Date().toISOString(),
        });
        hideDmUser(resolvedUid, { rerender: false });
        clearDmUnreadForUser(resolvedUid);
      });
      renderRelationshipUiNow({
        rerenderFriends: true,
        rerenderPending: true,
        rerenderBlockedSettings: settingsActiveTab === "blocked-users",
        affectedUserId: resolvedUid,
        affectedUsername: resolvedUname,
      });
      relationshipTraceSchedulePaint(trace, "optimisticPaint");
      // ──────────────────────────────────────────────────────────────────

      const { error } = await relationshipTraceMeasureAsync(trace, "rpc:block_user", () => (
        blockUserRpc(resolvedUid)
      ));
      if (error) {
        restoreRelationshipState(snapshot, {
          rerenderFriends: true,
          rerenderPending: true,
          rerenderBlockedSettings: settingsActiveTab === "blocked-users",
          rerenderDmList: true,
          affectedUserId: resolvedUid,
          affectedUsername: resolvedUname,
        });
        relationshipTraceSchedulePaint(trace, "rollbackPaint");
        endRelationshipTrace(trace, "rpc_error", { message: String(error?.message || error || "") });
        const missingSql = isMissingRpcError(error) || isMissingTableError(error, "user_blocks");
        if (missingSql) {
          const proj = getSupabaseProjectRefLabel();
          await requestAppAlert(
            `Falta SQL para bloqueios no Supabase (proj: ${proj}).\n` +
            "Executa o patch SQL: SQL/SUPABASE_PATCH_FRIEND_BLOCK_REMOVE.sql\n" +
            "e depois recarrega a app.",
            { title: "Block User", okText: t("dialog.notice.ok", "OK") }
          );
        } else {
          await requestAppAlert(`Erro ao bloquear utilizador: ${error.message || error}`, {
            title: "Block User",
            okText: t("dialog.notice.ok", "OK"),
          });
        }
        return;
      }
      deferRelationshipTraceToReconcile(trace, { delayMs: 180 });
      scheduleRelationshipReconcile(180, trace);
      return;
    }
    if (action === "report_user") {
      if (!resolvedUid) return;
      closeDmListMenus();
      openReportUserModal(resolvedUid, resolvedUname, display);
      return;
    }
    if (action === "mute_open") {
      openDmUserMuteSubmenuFromAction(actionBtn, { targetId: resolvedUid });
      return;
    }
    if (action === "open_server_roles_menu") {
      if (!resolvedUid || !serverIdAttr) return;
      await openDmUserRoleSubmenuFromAction(actionBtn, {
        serverId: serverIdAttr,
        userId: resolvedUid,
        username: resolvedUname,
        displayName: display,
        avatarUrl: avatar,
      });
      return;
    }
    if (action === "open_server_moderation_menu") {
      if (!resolvedUid || !serverIdAttr) return;
      await openDmUserModerationSubmenuFromAction(actionBtn, {
        serverId: serverIdAttr,
        userId: resolvedUid,
        username: resolvedUname,
        displayName: display,
      });
      return;
    }
    if (action === "open_server_voice_menu") {
      if (!resolvedUid || !serverIdAttr) return;
      if (!serverVoiceConvId) {
        serverVoiceConvId = resolveServerVoiceMenuConversationForMember(serverIdAttr, resolvedUid);
      }
      if (!serverVoiceConvId) {
        closeDmListMenus();
        alert("Nao encontrei canal de voz neste server para abrir os controlos.");
        return;
      }
      await openDmUserVoiceSubmenuFromAction(actionBtn);
      return;
    }
    if (action === "copy_user_id") {
      closeDmListMenus();
      await copyTextWithPromptFallback(resolvedUid, "User ID");
      return;
    }
    if (action === "copy_channel_id") {
      closeDmListMenus();
      try {
        const convId = await ensureFriendConversationId(resolvedUid, resolvedUname);
        if (convId) await copyTextWithPromptFallback(convId, "Channel ID");
      } catch (err) {
        alert(`Erro a copiar channel id: ${err?.message || err}`);
      }
      return;
    }
  });

  menu.addEventListener("mouseover", (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    clearSubmenuHoverCloseTimer();
    const roleBtn = target.closest("[data-user-list-act='open_server_roles_menu']");
    if (roleBtn && !roleBtn.disabled) {
      const uid = normId(roleBtn.getAttribute("data-user-list-id") || "");
      const sid = normId(roleBtn.getAttribute("data-user-list-server-id") || "");
      const username = String(roleBtn.getAttribute("data-user-list-username") || "").trim();
      const display = String(roleBtn.getAttribute("data-user-list-display") || username).trim();
      const avatar = String(roleBtn.getAttribute("data-user-list-avatar") || "").trim();
      if (uid && sid) {
        void openDmUserRoleSubmenuFromAction(roleBtn, {
          serverId: sid,
          userId: uid,
          username,
          displayName: display,
          avatarUrl: avatar,
        });
      }
      return;
    }
    const moderationBtn = target.closest("[data-user-list-act='open_server_moderation_menu']");
    if (moderationBtn && !moderationBtn.disabled) {
      const uid = normId(moderationBtn.getAttribute("data-user-list-id") || "");
      const sid = normId(moderationBtn.getAttribute("data-user-list-server-id") || "");
      if (uid && sid) {
        void openDmUserModerationSubmenuFromAction(moderationBtn, {
          serverId: sid,
          userId: uid,
          username: String(moderationBtn.getAttribute("data-user-list-username") || "").trim(),
          displayName: String(moderationBtn.getAttribute("data-user-list-display") || "").trim(),
        });
      }
      return;
    }
    const voiceBtn = target.closest("[data-user-list-act='open_server_voice_menu']");
    if (voiceBtn && !voiceBtn.disabled) {
      void openDmUserVoiceSubmenuFromAction(voiceBtn);
      return;
    }
    if (target.closest("[data-user-list-act]")) {
      closeDmUserRoleMenu();
      closeDmUserModerationMenu();
      closeDmMuteDurationMenu();
      closeServerVoiceMemberMenu({ force: true, reason: "sibling_action" });
    }
    const actionBtn = target.closest("[data-user-list-act='mute_open']");
    if (!actionBtn || actionBtn.disabled) return;
    const uid = normId(actionBtn.getAttribute("data-user-list-id") || "");
    if (!uid) return;
    openDmUserMuteSubmenuFromAction(actionBtn, { targetId: uid });
  });

  menu.addEventListener("focusin", (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    clearSubmenuHoverCloseTimer();
    const roleBtn = target.closest("[data-user-list-act='open_server_roles_menu']");
    if (roleBtn && !roleBtn.disabled) {
      const uid = normId(roleBtn.getAttribute("data-user-list-id") || "");
      const sid = normId(roleBtn.getAttribute("data-user-list-server-id") || "");
      const username = String(roleBtn.getAttribute("data-user-list-username") || "").trim();
      const display = String(roleBtn.getAttribute("data-user-list-display") || username).trim();
      const avatar = String(roleBtn.getAttribute("data-user-list-avatar") || "").trim();
      if (uid && sid) {
        void openDmUserRoleSubmenuFromAction(roleBtn, {
          serverId: sid,
          userId: uid,
          username,
          displayName: display,
          avatarUrl: avatar,
        });
      }
      return;
    }
    const moderationBtn = target.closest("[data-user-list-act='open_server_moderation_menu']");
    if (moderationBtn && !moderationBtn.disabled) {
      const uid = normId(moderationBtn.getAttribute("data-user-list-id") || "");
      const sid = normId(moderationBtn.getAttribute("data-user-list-server-id") || "");
      if (uid && sid) {
        void openDmUserModerationSubmenuFromAction(moderationBtn, {
          serverId: sid,
          userId: uid,
          username: String(moderationBtn.getAttribute("data-user-list-username") || "").trim(),
          displayName: String(moderationBtn.getAttribute("data-user-list-display") || "").trim(),
        });
      }
      return;
    }
    const voiceBtn = target.closest("[data-user-list-act='open_server_voice_menu']");
    if (voiceBtn && !voiceBtn.disabled) {
      void openDmUserVoiceSubmenuFromAction(voiceBtn);
      return;
    }
    if (target.closest("[data-user-list-act]")) {
      closeDmUserRoleMenu();
      closeDmUserModerationMenu();
      closeDmMuteDurationMenu();
      closeServerVoiceMemberMenu({ force: true, reason: "sibling_action" });
    }
    const actionBtn = target.closest("[data-user-list-act='mute_open']");
    if (!actionBtn || actionBtn.disabled) return;
    const uid = normId(actionBtn.getAttribute("data-user-list-id") || "");
    if (!uid) return;
    openDmUserMuteSubmenuFromAction(actionBtn, { targetId: uid });
  });

  return menu;
}

function openDmUserListMenuAt({
  userId,
  username = "",
  displayName = "",
  avatarUrl = "",
  point = null,
  anchorEl = null,
  serverVoiceMenu = null,
  requestId = "",
  requestDirection = "",
  rowType = "",
} = {}) {
  const uid = normId(userId);
  if ((!uid && !username) || (!point && !anchorEl)) return;
  markPerfStart("context_menu_open", { rowType: String(rowType || "").trim(), byCursor: !!point });
  closeActivePopover();
  closeMessageMenu();
  if (dmPinsPanelOpen) {
    dmPinsLastValidItems = dmPinsLastValidItems.filter((row) => normId(row?.id || "") !== normId(mid));
    renderDmPinsList(dmPinsLastValidItems.length ? dmPinsLastValidItems : getPinnedMessagesFromCache());
  }
  closeGroupMemberMenu();
  closeGroupDmListMenu();
  closeDmUserListMenu("another menu");
  closeDmMuteDurationMenu();
  closeDmUserRoleMenu();
  const menu = ensureDmUserListMenu();
  const meId = normId(state.user?.id || "");
  const friendRow = getFriendRowByUserId(uid) || getFriendRowByUsername(username) || null;
  const isFriend = !!friendRow;
  const isSelfTarget = !!uid && uid === meId;
  const incomingMessageRequest = getIncomingMessageRequestByUserId(uid) || null;
  const outgoingMessageRequest = getOutgoingMessageRequestByUserId(uid) || null;
  const safeRequestDirection = String(requestDirection || "").trim().toLowerCase();
  const incomingRequestId = String(
    (safeRequestDirection === "incoming" ? requestId : "")
    || incomingMessageRequest?.request_id
    || incomingMessageRequest?.id
    || ""
  ).trim();
  const outgoingRequestId = String(
    (safeRequestDirection === "outgoing" ? requestId : "")
    || outgoingMessageRequest?.request_id
    || outgoingMessageRequest?.id
    || ""
  ).trim();
  const isIncomingMessageRequestMenu = !!incomingRequestId && !isFriend;
  const isOutgoingMessageRequestMenu = !isIncomingMessageRequestMenu && !!outgoingRequestId && !isFriend;
  const requestRow = isIncomingMessageRequestMenu ? incomingMessageRequest : (isOutgoingMessageRequestMenu ? outgoingMessageRequest : null);
  const resolvedUsername = String(username || requestRow?.username || friendRow?.username || "").trim();
  const resolvedDisplayName = String(displayName || requestRow?.display_name || requestRow?.displayName || friendRow?.display_name || friendRow?.displayName || resolvedUsername || "User").trim();
  const resolvedAvatarUrl = String(avatarUrl || requestRow?.avatar_url || requestRow?.avatarUrl || friendRow?.avatar_url || "").trim();
  const muted = isDmUserMuted(uid);
  const bestFriend = isFriend && isDmBestFriend(uid);
  const currentNickname = isFriend ? getDmFriendNickname(uid) : "";
  const muteLabel = `Mute @${resolvedDisplayName || resolvedUsername || "user"}`;
  const bestFriendLabel = bestFriend ? "Remove Best Friend" : "Mark As Best Friend";
  const nickLabel = currentNickname ? `Change Friend Nickname (${currentNickname})` : "Change Friend Nickname";
  const serverVoiceServerId = normId(serverVoiceMenu?.serverId || "");
  const serverVoiceConversationId = normId(serverVoiceMenu?.conversationId || "");
  const canOpenServerVoiceMenu = !!serverVoiceServerId && !!serverVoiceConversationId;
  const submenuSide = "right";
  const submenuChevron = "&#x203A;";
  const canBlockUser = !!uid && !isSelfTarget;
  let blockUserHint = "";
  if (!canBlockUser) {
    if (isSelfTarget) blockUserHint = "Nao podes bloquear a tua propria conta.";
    else blockUserHint = "Nao e possivel bloquear este utilizador agora.";
  }
  const caps = getServerCapabilityMeta(serverVoiceServerId);
  const canManageRoles = serverVoiceServerId ? currentUserCanManageRoles(serverVoiceServerId) : false;
  const roleList = serverVoiceServerId ? (serverRoleListByServerId.get(serverVoiceServerId) || []) : [];
  const roleModeration = canServerActorModerateTargetWithPermission({
    serverId: serverVoiceServerId,
    actorUserId: meId,
    targetUserId: uid,
  });
  const canOpenServerRolesMenu = !!(
    serverVoiceServerId
    && canManageRoles
    && roleList.length
    && (uid === meId || roleModeration?.canTouchTarget)
  );
  let roleMenuHint = "";
  if (serverVoiceServerId && !canOpenServerRolesMenu) {
    if (!canManageRoles) roleMenuHint = "Sem permissao para gerir roles.";
    else if (!roleList.length) roleMenuHint = "Sem roles custom.";
    else roleMenuHint = "Nao podes gerir roles deste membro.";
  }
  const moderationContext = getServerMemberManagementContext(serverVoiceServerId, uid);
  const nicknameAction = getServerNicknameActionState(serverVoiceServerId, uid);
  const moderationPermissionResolved = !!(
    serverRolePermissionCacheFetchedAtByServerId.has(serverVoiceServerId)
    || getServerCapabilityMeta(serverVoiceServerId).isOwner
    || getServerCapabilityMeta(serverVoiceServerId).isActualOwner
  );
  const canOpenServerModerationMenu = !!(
    serverVoiceServerId
    && moderationPermissionResolved
    && !moderationContext.isSelf
    && (
      nicknameAction.allowed
      || (
        !moderationContext.isSelf
        && !moderationContext.targetIsOwner
        && (moderationContext.actorIsOwner || moderationContext.targetBelowActor)
        && (moderationContext.canKick || moderationContext.canBan || moderationContext.canTimeout)
      )
    )
  );
  let moderationMenuHint = "";
  if (serverVoiceServerId && !canOpenServerModerationMenu) {
    if (!moderationPermissionResolved) moderationMenuHint = "Checking permissions...";
    else if (moderationContext.isSelf && !nicknameAction.allowed) moderationMenuHint = "Requires Change Own Nickname.";
    else if (moderationContext.targetIsOwner) moderationMenuHint = "Cannot moderate the server owner.";
    else if (!(moderationContext.actorIsOwner || moderationContext.targetBelowActor)) moderationMenuHint = "No available actions: equal or higher role.";
    else moderationMenuHint = "Requires Manage Nicknames, Kick Members, Ban Members, or Timeout Members.";
  }
  const canShowDmLockControls = isFriend && !serverVoiceServerId;
  const dmLockRecord = canShowDmLockControls
    ? resolveDmLockRecordForMenuTarget({ userId: uid, username: resolvedUsername })
    : null;
  const dmLockConversationId = normId(dmLockRecord?.dmId || "");
  const dmLockUnlockedThisSession = !!dmLockConversationId && isDmUnlockedForSession(dmLockConversationId);
  const dmLockCreateAllowed = canShowDmLockControls && canCreateLockedDmForCurrentUser();
  const dmLockCreateAction = dmLockCreateAllowed ? "lock_dm" : "lock_dm_altara_plus_upsell";
  const dmLockCreateLabelHtml = dmLockCreateAllowed
    ? "Lock DM"
    : 'Lock DM <span aria-hidden="true">&middot;</span> ALTARA+';
  const dmLockControlHtml = !canShowDmLockControls
    ? ""
    : (dmLockConversationId
      ? [
        `<button class="msgMenu__item${dmLockUnlockedThisSession ? " is-disabled" : ""}" data-user-list-act="unlock_dm" data-user-list-id="${escAttr(uid)}" data-user-list-username="${escAttr(resolvedUsername)}" data-user-list-display="${escAttr(resolvedDisplayName)}" data-user-list-avatar="${escAttr(resolvedAvatarUrl)}" data-user-list-dm-id="${escAttr(dmLockConversationId)}" ${dmLockUnlockedThisSession ? "disabled" : ""}><span>Unlock DM</span></button>`,
        `<button class="msgMenu__item${dmLockUnlockedThisSession ? "" : " is-disabled"}" data-user-list-act="lock_dm_again" data-user-list-id="${escAttr(uid)}" data-user-list-username="${escAttr(resolvedUsername)}" data-user-list-display="${escAttr(resolvedDisplayName)}" data-user-list-avatar="${escAttr(resolvedAvatarUrl)}" data-user-list-dm-id="${escAttr(dmLockConversationId)}" ${dmLockUnlockedThisSession ? "" : "disabled"}><span>Lock DM again</span></button>`,
        `<button class="msgMenu__item" data-user-list-act="remove_dm_lock" data-user-list-id="${escAttr(uid)}" data-user-list-username="${escAttr(resolvedUsername)}" data-user-list-display="${escAttr(resolvedDisplayName)}" data-user-list-avatar="${escAttr(resolvedAvatarUrl)}" data-user-list-dm-id="${escAttr(dmLockConversationId)}"><span>Remove DM Lock</span></button>`,
      ].join("")
      : `<button class="msgMenu__item" data-user-list-act="${escAttr(dmLockCreateAction)}" data-user-list-id="${escAttr(uid)}" data-user-list-username="${escAttr(resolvedUsername)}" data-user-list-display="${escAttr(resolvedDisplayName)}" data-user-list-avatar="${escAttr(resolvedAvatarUrl)}"><span>${dmLockCreateLabelHtml}</span></button>`);

  const commonAttrs = `data-user-list-id="${escAttr(uid)}" data-user-list-username="${escAttr(resolvedUsername)}" data-user-list-display="${escAttr(resolvedDisplayName)}" data-user-list-avatar="${escAttr(resolvedAvatarUrl)}"`;
  const item = (action, label, { danger = false, disabled = false, extra = "", right = "", hint = "" } = {}) => {
    const hintHtml = hint ? `<span class="msgMenu__itemHint">${esc(hint)}</span>` : "";
    return `<button class="msgMenu__item${danger ? " msgMenu__item--danger" : ""}${disabled ? " is-disabled" : ""}" data-user-list-act="${escAttr(action)}" ${commonAttrs} ${extra || ""} ${disabled ? "disabled" : ""}><span class="msgMenu__itemMain"><span>${esc(label)}</span>${hintHtml}</span>${right || ""}</button>`;
  };
  const divider = '<div class="msgMenu__divider"></div>';
  const friendAction = getAddFriendPreviewPrimaryAction({
    id: uid,
    username: resolvedUsername,
    display_name: resolvedDisplayName,
    avatar_url: resolvedAvatarUrl,
  });
  const friendActionHtml = (() => {
    if (isSelfTarget || isFriend) return "";
    if (friendAction?.kind === "send") return item("add_friend", t("tab.add", "Add Friend"));
    if (friendAction?.kind === "accept") {
      return item("accept_friend_request", friendAction.label || "Accept Friend", {
        extra: `data-user-list-request-id="${escAttr(friendAction.requestId || "")}"`,
      });
    }
    if (friendAction?.kind === "sent") return item("friend_request_pending", friendAction.label || "Request sent", { disabled: true });
    return "";
  })();
  const serverControlsHtml = [
    serverVoiceServerId && isSelfTarget
      ? item("change_server_nickname", "Change Server Nickname", {
        disabled: !moderationPermissionResolved || !nicknameAction.allowed,
        extra: `data-user-list-server-id="${escAttr(serverVoiceServerId)}"`,
        hint: !moderationPermissionResolved
          ? "Checking permissions..."
          : (nicknameAction.allowed ? "" : "Requires Change Own Nickname."),
      })
      : "",
    serverVoiceServerId
      ? item("open_server_roles_menu", "Roles", {
        disabled: !canOpenServerRolesMenu,
        extra: `data-user-list-server-id="${escAttr(serverVoiceServerId)}"`,
        right: `<span>${submenuChevron}</span>`,
        hint: roleMenuHint,
      })
      : "",
    serverVoiceServerId && !isSelfTarget
      ? item("open_server_moderation_menu", "Server Moderation", {
        disabled: !canOpenServerModerationMenu,
        extra: `data-user-list-server-id="${escAttr(serverVoiceServerId)}"`,
        right: `<span>${submenuChevron}</span>`,
        hint: moderationMenuHint,
      })
      : "",
    serverVoiceServerId
      ? item("open_server_voice_menu", "Server Voice Controls", {
        disabled: !canOpenServerVoiceMenu,
        extra: `data-user-list-server-id="${escAttr(serverVoiceServerId)}" data-user-list-server-voice-conv="${escAttr(serverVoiceConversationId)}"`,
        right: `<span>${submenuChevron}</span>`,
      })
      : "",
  ].filter(Boolean).join("");

  debugProfileActions(uid, {
    source: "context_menu",
    rowType: String(rowType || "").trim(),
    isIncomingMessageRequestMenu,
    isOutgoingMessageRequestMenu,
  });

  if (isIncomingMessageRequestMenu) {
    menu.innerHTML = [
      item("profile", "Profile"),
      divider,
      item("accept_message_request", "Accept", { extra: `data-user-list-request-id="${escAttr(incomingRequestId)}"` }),
      item("ignore_message_request", "Ignore", { extra: `data-user-list-request-id="${escAttr(incomingRequestId)}"` }),
      item("block_message_request", "Block", { danger: true, extra: `data-user-list-request-id="${escAttr(incomingRequestId)}"` }),
      divider,
      item("report_user", "Report", { danger: true, disabled: !canBlockUser }),
      item("copy_user_id", "Copy User ID", { right: '<span class="msgMenu__kbd">ID</span>' }),
    ].join("");
  } else if (isOutgoingMessageRequestMenu) {
    menu.innerHTML = [
      item("profile", "Profile"),
      divider,
      item("pending_message_request", "Message Request Sent", { disabled: true }),
      item("block_user", "Block", { danger: true, disabled: !canBlockUser }),
      divider,
      item("copy_user_id", "Copy User ID", { right: '<span class="msgMenu__kbd">ID</span>' }),
    ].join("");
  } else if (isFriend) {
    const canRemoveFriend = !!uid && !isSelfTarget;
    menu.innerHTML = [
      item("mark_read", "Mark As Read"),
      divider,
      item("profile", "Profile"),
      item("message", "Message"),
      item("start_call", "Start a Call"),
      item("toggle_bestfriend", bestFriendLabel, { right: '<span>&#x1F4CC;</span>' }),
      item("edit_nickname", nickLabel),
      item("close_dm", "Close DM", { extra: `data-user-list-dm-id="${escAttr(dmLockConversationId)}"` }),
      dmLockControlHtml ? divider : "",
      dmLockControlHtml,
      divider,
      item("remove_friend", "Remove Friend", { disabled: !canRemoveFriend }),
      item("report_user", "Report", { danger: true, disabled: !canBlockUser }),
      item("block_user", "Block", { danger: true, disabled: !canBlockUser, hint: blockUserHint }),
      divider,
      item("mute_open", muteLabel, { right: `<span>${submenuChevron}</span>`, hint: muted ? "Mute ativo" : "" }),
      serverControlsHtml ? divider : "",
      serverControlsHtml,
      divider,
      item("copy_user_id", "Copy User ID", { right: '<span class="msgMenu__kbd">ID</span>' }),
      item("copy_channel_id", "Copy Channel ID", { right: '<span class="msgMenu__kbd">ID</span>' }),
    ].filter(Boolean).join("");
  } else {
    menu.innerHTML = [
      item("profile", "Profile"),
      item("message", "Message"),
      friendActionHtml,
      divider,
      item("mute_open", muteLabel, { right: `<span>${submenuChevron}</span>`, hint: muted ? "Mute ativo" : "" }),
      item("report_user", "Report", { danger: true, disabled: !canBlockUser }),
      item("block_user", "Block", { danger: true, disabled: !canBlockUser }),
      serverControlsHtml ? divider : "",
      serverControlsHtml,
      divider,
      item("copy_user_id", "Copy User ID", { right: '<span class="msgMenu__kbd">ID</span>' }),
    ].filter(Boolean).join("");
  }

  menu.classList.add("is-open");
  menu.dataset.submenuSide = submenuSide;
  dmUserListMenuTargetUserId = uid;
  const openedAt = getContextMenuNow();
  dmUserListMenuState = {
    targetUserId: uid,
    rowType: String(rowType || "").trim(),
    openedAt,
    outsideCloseEnabledAt: openedAt + 90,
    openEventStamp: Number(point?.timeStamp || 0) || 0,
    openPointerId: Number.isFinite(Number(point?.pointerId)) ? Number(point.pointerId) : null,
    openTargetEl: anchorEl || null,
    cursorPoint: point ? {
      clientX: Number.isFinite(Number(point.clientX)) ? Number(point.clientX) : Number(point.x),
      clientY: Number.isFinite(Number(point.clientY)) ? Number(point.clientY) : Number(point.y),
    } : null,
  };
  dmUserListMenuLastCloseReason = "";
  setAltaraContextMenuOpen({
    type: "user_member",
    targetId: uid || resolvedUsername || "",
    targetKind: String(rowType || "user").trim() || "user",
    menuId: "dmUserListMenu",
    anchorEl,
    point,
    reason: point ? "contextmenu" : "trigger",
  });
  logContextMenuDebug("open", {
    targetUserId: uid,
    rowType: dmUserListMenuState.rowType,
    x: Number(point?.clientX ?? point?.x ?? 0),
    y: Number(point?.clientY ?? point?.y ?? 0),
  });
  setTimeout(() => {
    if (dmUserListMenuState?.openedAt === openedAt) dmUserListMenuState.outsideCloseEnabledAt = getContextMenuNow();
  }, 0);
  const cursorPoint = point
    ? {
      clientX: Number.isFinite(Number(point.clientX)) ? Number(point.clientX) : Number(point.x),
      clientY: Number.isFinite(Number(point.clientY)) ? Number(point.clientY) : Number(point.y),
    }
    : null;
  const anchorRect = anchorEl?.getBoundingClientRect?.() || null;
  serverMemberContextMenuReturnFocusEl = anchorEl || null;
  serverMemberContextMenuLastCloseReason = "";
  serverMemberContextMenuActiveSubmenu = "";
  serverMemberContextMenuDebugState = {
    open: true,
    targetUserId: uid,
    serverId: serverVoiceServerId,
    pointerCoordinates: {
      x: Number(cursorPoint?.clientX || anchorRect?.left || 0),
      y: Number(cursorPoint?.clientY || anchorRect?.top || 0),
    },
    anchorCoordinates: anchorRect ? {
      left: Number(anchorRect.left || 0),
      top: Number(anchorRect.top || 0),
      right: Number(anchorRect.right || 0),
      bottom: Number(anchorRect.bottom || 0),
    } : {
      left: Number(cursorPoint?.clientX || 0),
      top: Number(cursorPoint?.clientY || 0),
      right: Number(cursorPoint?.clientX || 0),
      bottom: Number(cursorPoint?.clientY || 0),
    },
    menuDimensions: { width: 0, height: 0 },
    viewportDimensions: getMenuViewportSize(),
    finalX: 0,
    finalY: 0,
    verticalDirection: "",
    horizontalDirection: "",
    activeSubmenu: "",
    submenuDirection: "",
    nicknameActionAvailable: !!nicknameAction.allowed,
    nicknameActionIsSelf: !!nicknameAction.isSelf,
    nicknameActionReason: String(nicknameAction.reason || ""),
    kickPermission: !!moderationContext.canKick,
    banPermission: !!moderationContext.canBan,
    hierarchyAllowed: !!(moderationContext.actorIsOwner || moderationContext.targetBelowActor),
    hierarchyReason: moderationContext.isSelf
      ? "self_target"
      : (moderationContext.targetIsOwner
        ? "target_is_owner"
        : ((moderationContext.actorIsOwner || moderationContext.targetBelowActor) ? "allowed" : "role_hierarchy_blocked")),
    permissionResolved: moderationPermissionResolved,
    openedAt: Date.now(),
    lastCloseReason: "",
  };
  positionServerMemberRootMenu(menu, {
    point: cursorPoint,
    anchorEl,
    width: 276,
    margin: 8,
    offset: 6,
  });
  requestAnimationFrame(() => {
    const rect = menu.getBoundingClientRect?.() || {};
    const viewport = getMenuViewportSize();
    const rightSpace = viewport.width - Number(rect.right || 0) - 8;
    const leftSpace = Number(rect.left || 0) - 8;
    const resolvedSubmenuSide = rightSpace >= 252 || rightSpace >= leftSpace ? "right" : "left";
    menu.dataset.submenuSide = resolvedSubmenuSide;
    if (serverMemberContextMenuDebugState?.openedAt) {
      serverMemberContextMenuDebugState.menuDimensions = { width: Number(rect.width || 0), height: Number(rect.height || 0) };
      serverMemberContextMenuDebugState.viewportDimensions = viewport;
      serverMemberContextMenuDebugState.finalX = Number(rect.left || 0);
      serverMemberContextMenuDebugState.finalY = Number(rect.top || 0);
      serverMemberContextMenuDebugState.submenuDirection = resolvedSubmenuSide;
      serverMemberContextMenuDebugState.rootScrollable = menu.scrollHeight > menu.clientHeight;
    }
  });
  markPerfEnd("context_menu_open", { rowType: String(rowType || "").trim(), byCursor: !!point });
}

window.altaraDebugServerMemberContextMenu = {
  inspectState() {
    const menu = document.getElementById("dmUserListMenu");
    const moderationMenu = document.getElementById("dmUserModerationMenu");
    return {
      rootOpen: !!menu?.classList.contains("is-open"),
      open: !!menu?.classList.contains("is-open"),
      moderationSubmenuOpen: !!moderationMenu?.classList.contains("is-open"),
      targetUserId: serverMemberContextMenuDebugState?.targetUserId || "",
      serverId: serverMemberContextMenuDebugState?.serverId || "",
      activeSubmenu: serverMemberContextMenuActiveSubmenu || "",
      lastCloseReason: serverMemberContextMenuLastCloseReason || serverMemberContextMenuDebugState?.lastCloseReason || "",
    };
  },
  inspectPosition() {
    const menu = document.getElementById("dmUserListMenu");
    const rect = menu?.getBoundingClientRect?.() || null;
    return serverMemberContextMenuDebugState ? {
      anchorCoordinates: serverMemberContextMenuDebugState.anchorCoordinates,
      menuDimensions: rect ? { width: Number(rect.width || 0), height: Number(rect.height || 0) } : serverMemberContextMenuDebugState.menuDimensions,
      viewportDimensions: getMenuViewportSize(),
      finalX: rect ? Number(rect.left || 0) : serverMemberContextMenuDebugState.finalX,
      finalY: rect ? Number(rect.top || 0) : serverMemberContextMenuDebugState.finalY,
      verticalDirection: String(menu?.dataset?.verticalDirection || serverMemberContextMenuDebugState.verticalDirection || ""),
      horizontalDirection: String(menu?.dataset?.horizontalDirection || serverMemberContextMenuDebugState.horizontalDirection || ""),
      submenuDirection: String(menu?.dataset?.submenuSide || serverMemberContextMenuDebugState.submenuDirection || ""),
      overflowScroll: menu?.dataset?.viewportScroll === "1" || serverMemberContextMenuDebugState.rootScrollable === true,
    } : null;
  },
  inspectTarget() {
    return serverMemberContextMenuDebugState ? {
      targetUserId: serverMemberContextMenuDebugState.targetUserId,
      serverId: serverMemberContextMenuDebugState.serverId,
    } : null;
  },
  inspectModerationActions() {
    return serverMemberContextMenuDebugState ? {
      kickPermission: serverMemberContextMenuDebugState.kickPermission,
      banPermission: serverMemberContextMenuDebugState.banPermission,
      permissionResolved: serverMemberContextMenuDebugState.permissionResolved,
      hierarchyAllowed: serverMemberContextMenuDebugState.hierarchyAllowed,
      hierarchyReason: serverMemberContextMenuDebugState.hierarchyReason,
      nicknameAvailable: serverMemberContextMenuDebugState.nicknameActionAvailable === true,
      nicknameIsSelf: serverMemberContextMenuDebugState.nicknameActionIsSelf === true,
      nicknameReason: serverMemberContextMenuDebugState.nicknameActionReason || "",
    } : null;
  },
  inspectSubmenuState() {
    const ids = ["dmMuteDurationMenu", "dmUserRoleMenu", "dmUserModerationMenu", "serverVoiceMemberMenu"];
    const active = ids.map((id) => document.getElementById(id)).find((menu) => menu?.classList.contains("is-open")) || null;
    const rect = active?.getBoundingClientRect?.() || null;
    return {
      activeSubmenu: serverMemberContextMenuActiveSubmenu || "",
      elementId: active?.id || "",
      measuredWidth: Number(rect?.width || serverMemberContextMenuDebugState?.submenuDimensions?.width || 0),
      measuredHeight: Number(rect?.height || serverMemberContextMenuDebugState?.submenuDimensions?.height || 0),
      direction: String(active?.dataset?.submenuDirection || serverMemberContextMenuDebugState?.submenuDirection || ""),
      finalX: Number(rect?.left || serverMemberContextMenuDebugState?.submenuFinalX || 0),
      finalY: Number(rect?.top || serverMemberContextMenuDebugState?.submenuFinalY || 0),
      overflowScroll: active?.dataset?.viewportScroll === "1" || serverMemberContextMenuDebugState?.submenuScrollable === true,
      viewportDimensions: getMenuViewportSize(),
    };
  },
  inspectLifecycle() {
    return {
      rootOpen: !!document.getElementById("dmUserListMenu")?.classList.contains("is-open"),
      activeSubmenu: serverMemberContextMenuActiveSubmenu || "",
      rootCount: document.querySelectorAll("#dmUserListMenu").length,
      openSubmenuCount: document.querySelectorAll("#dmMuteDurationMenu.is-open,#dmUserRoleMenu.is-open,#dmUserModerationMenu.is-open,#serverVoiceMemberMenu.is-open").length,
      openedAt: Number(serverMemberContextMenuDebugState?.openedAt || 0),
      closedAt: Number(serverMemberContextMenuDebugState?.closedAt || 0),
      lastCloseReason: serverMemberContextMenuLastCloseReason || serverMemberContextMenuDebugState?.lastCloseReason || "",
      targetStillExists: getAltaraContextMenuTargetStillExists(),
    };
  },
};

function renderDmGroupMembersPanel(members = [], { loading = false } = {}) {
  const panel = document.getElementById("dmProfilePanel");
  const titleEl = document.querySelector("#dmProfilePanel .dmProfilePanel__title");
  const bannerEl = document.getElementById("dmProfileBanner");
  const avatarEl = document.getElementById("dmProfileAvatar");
  const bodyEl = document.querySelector("#dmProfilePanel .dmProfilePanel__body");
  const footerEl = document.querySelector("#dmProfilePanel .dmProfilePanel__footer");
  const identityWrap = document.querySelector("#dmProfilePanel .dmProfileIdentity");
  const nameEl = document.getElementById("dmProfileName");
  const handleEl = document.getElementById("dmProfileHandle");
  const statusWrap = document.querySelector("#dmProfilePanel .dmProfilePresence");
  const bioWrap = document.querySelector("#dmProfilePanel .dmProfileSection");
  const activityPreviewEl = document.getElementById("dmProfileActivityPreview");
  const widgetsPreviewEl = document.getElementById("dmProfileWidgetsPreview");
  const mutualSectionEl = document.getElementById("dmProfileMutualSection");
  const connectionsPreviewEl = document.getElementById("dmProfileConnectionsPreview");
  const btnOpen = document.getElementById("btnDmProfileOpenCard");
  if (!panel || !bodyEl) return;

  let membersBody = document.getElementById("dmGroupMembersBody");
  if (!membersBody) {
    membersBody = document.createElement("div");
    membersBody.id = "dmGroupMembersBody";
    membersBody.className = "dmGroupMembersBody";
    membersBody.style.display = "none";
    bodyEl.appendChild(membersBody);
  }

  const list = Array.isArray(members) ? members : [];
  const count = list.length;
  panel.classList.add("is-group-members");
  if (titleEl) titleEl.textContent = `Members - ${count}`;
  if (bannerEl) bannerEl.style.display = "none";
  if (avatarEl) avatarEl.style.display = "none";
  if (identityWrap) identityWrap.style.display = "none";
  if (nameEl) nameEl.style.display = "none";
  if (handleEl) handleEl.style.display = "none";
  if (statusWrap) statusWrap.style.display = "none";
  if (bioWrap) bioWrap.style.display = "none";
  if (activityPreviewEl) {
    activityPreviewEl.classList.add("hidden");
    activityPreviewEl.setAttribute("aria-hidden", "true");
    activityPreviewEl.innerHTML = "";
  }
  if (widgetsPreviewEl) {
    widgetsPreviewEl.classList.add("hidden");
    widgetsPreviewEl.setAttribute("aria-hidden", "true");
    widgetsPreviewEl.innerHTML = "";
  }
  if (mutualSectionEl) {
    mutualSectionEl.classList.add("hidden");
    mutualSectionEl.setAttribute("aria-hidden", "true");
    mutualSectionEl.innerHTML = "";
  }
  if (footerEl) footerEl.style.display = "none";
  if (btnOpen) btnOpen.style.display = "none";
  membersBody.style.display = "block";

  if (loading) {
    membersBody.innerHTML = `<div class="hint">${t("app.loading", "Loading...")}</div>`;
    return;
  }

  if (!list.length) {
    membersBody.innerHTML = `<div class="hint">${t("dm.no_members", "No members to show.")}</div>`;
    return;
  }

  const meId = normId(state.user?.id || "");
  membersBody.innerHTML = `
    <div class="dmGroupMembersList">
      ${list.map((m) => {
    const uid = normId(m?.userId || "");
    const isMe = uid === meId;
    const status = getPresenceStatusForUser(uid) || "offline";
    const nameColorAttrs = buildUserNameColorAttrs(uid, m?.nameColor || "");
    const avatarHtml = m?.avatarUrl
      ? buildAvatarMediaHtml(m.avatarUrl, { userId: uid, alt: m.displayName || m.username || "avatar", loading: "lazy", deferAnimatedStorage: true })
      : `<span class="groupDmAvatarFallback">${esc(String(m?.displayName || m?.username || "?").trim().charAt(0).toUpperCase() || "?")}</span>`;
    return `
        <button
          class="dmGroupMemberRow${isMe ? " is-me" : ""}"
          type="button"
          data-user-id="${escAttr(uid)}"
          data-group-member-id="${escAttr(uid)}"
          title="${escAttr(isMe ? t("usercard.you", "You") : t("group.right_click_ring", "Right-click to ring"))}"
        >
          <span class="dmGroupMemberRow__avatar">${avatarHtml}<span class="statusDot" data-status="${escAttr(status)}"></span></span>
          <span class="dmGroupMemberRow__text">
            <span class="dmGroupMemberRow__name${nameColorAttrs.cls}"${nameColorAttrs.style}>${esc(m?.displayName || m?.username || t("call.member", "member"))}${isMe ? t("group.you_suffix", " (you)") : ""}</span>
            <span class="dmGroupMemberRow__handle">@${esc(m?.username || "user")}</span>
          </span>
        </button>
      `;
  }).join("")}
    </div>
  `;
  renderTypingStatusOnUserCards({ reason: "group-members-render" });
}

function trimDmProfilePreviewText(value = "", maxLen = 46) {
  const raw = String(value || "").trim().replace(/\s+/g, " ");
  if (!raw) return "";
  return raw.length > maxLen ? `${raw.slice(0, Math.max(1, maxLen - 3))}...` : raw;
}

function buildDmProfileWidgetPreviewMeta(widget = {}, item = null, itemCount = 0) {
  const parts = [];
  if (item) {
    const statusLabel = getProfileWidgetStatusLabel(item?.status || "");
    if (statusLabel) parts.push(statusLabel);
    const note = trimDmProfilePreviewText(item?.note || "", 42);
    if (note) parts.push(note);
    const tag = Array.isArray(item?.tags)
      ? trimDmProfilePreviewText(item.tags.find((entry) => String(entry || "").trim()) || "", 24)
      : "";
    if (tag) parts.push(`#${tag}`);
  }
  if (itemCount > 1) {
    parts.push(t("profile.widgets.preview.more", "{count} items").replace("{count}", String(itemCount)));
  }
  if (!parts.length) {
    parts.push(normalizeProfileWidgetTitle(widget?.title || "") || getProfileWidgetTypeLabel(widget?.widget_type || ""));
  }
  return parts.slice(0, 2).filter(Boolean).join(" - ");
}

function buildDmProfileWidgetsPreviewHtml(widgets = [], {
  loading = false,
  error = "",
} = {}) {
  const safeWidgets = Array.isArray(widgets) ? widgets.filter((widget) => !!widget) : [];
  const previewWidgets = safeWidgets
    .map((widget) => {
      const items = Array.isArray(widget?.items) ? widget.items : [];
      const featured = getProfileWidgetFeaturedItem(widget);
      const item = featured || items.find((entry) => normalizeProfileWidgetTitle(entry?.title || "")) || null;
      return { widget, item, itemCount: items.length };
    })
    .filter((entry) => entry.item || entry.itemCount)
    .slice(0, 3);
  const sectionLabel = t("dm.profile_featured", "Featured");

  if (!previewWidgets.length) {
    const stateHtml = loading
      ? `
        <div class="dmProfileEmptyState dmProfileEmptyState--loading">
          <span class="dmProfileEmptyState__mark" aria-hidden="true"></span>
          <span class="dmProfileEmptyState__body">
            <span class="dmProfileEmptyState__title">${esc(t("dm.profile_featured_loading", "Loading featured widgets..."))}</span>
            <span class="dmProfileEmptyState__text">${esc(t("profile.widgets.loading.text", "Fetching profile interests."))}</span>
          </span>
        </div>
      `
      : `
        <div class="dmProfileEmptyState">
          <span class="dmProfileEmptyState__mark" aria-hidden="true"></span>
          <span class="dmProfileEmptyState__body">
            <span class="dmProfileEmptyState__title">${esc(t("dm.profile_featured_empty_title", "No featured widgets yet."))}</span>
            <span class="dmProfileEmptyState__text">${esc(error || t("dm.profile_featured_empty_body", "Open full profile to see more."))}</span>
          </span>
        </div>
      `;
    return `
      <section class="dmProfileWidgetsPreviewShell" aria-label="${escAttr(sectionLabel)}">
        <div class="dmProfileWidgetsPreviewTitle">${esc(sectionLabel)}</div>
        ${stateHtml}
      </section>
    `;
  }

  return `
    <section class="dmProfileWidgetsPreviewShell" aria-label="${escAttr(sectionLabel)}">
      <div class="dmProfileWidgetsPreviewTitle">${esc(sectionLabel)}</div>
      <div class="dmProfileWidgetPreviewList">
        ${previewWidgets.map(({ widget, item, itemCount }) => {
    const typeLabel = getProfileWidgetTypeLabel(widget?.widget_type || "");
    const title = normalizeProfileWidgetTitle(item?.title || widget?.title || "") || t("profile.widgets.item.untitled", "Untitled");
    const metaText = buildDmProfileWidgetPreviewMeta(widget, item, itemCount);
    const artworkUrl = getProfileWidgetArtworkUrl(item);
    const mediaHtml = artworkUrl
      ? lazyMediaImageHtml(artworkUrl, { alt: title, attrs: 'draggable="false"' })
      : `<span>${esc(String(title).charAt(0).toUpperCase() || "?")}</span>`;
    return `
          <button class="dmProfileWidgetPreviewCard" type="button" data-dm-profile-widget-preview="1">
            <span class="dmProfileWidgetPreviewMedia">${mediaHtml}</span>
            <span class="dmProfileWidgetPreviewBody">
              <span class="dmProfileWidgetPreviewBadge">${esc(typeLabel)}</span>
              <span class="dmProfileWidgetPreviewName">${esc(title)}</span>
              <span class="dmProfileWidgetPreviewMeta">${esc(metaText)}</span>
            </span>
          </button>
        `;
  }).join("")}
      </div>
    </section>
  `;
}

function renderDmProfileWidgetsPreview(userId = "", widgets = [], {
  loading = false,
  error = "",
} = {}) {
  const el = document.getElementById("dmProfileWidgetsPreview");
  if (!el) return;
  const uid = normId(userId || "");
  const safeWidgets = getProfileWidgetsForViewer(uid, widgets);
  const html = buildDmProfileWidgetsPreviewHtml(safeWidgets, { loading, error });
  el.innerHTML = html;
  bindLazyMediaImages(el);
  queueManagedGifPlaybackSync(el);
  el.dataset.userId = uid;
  el.classList.remove("hidden");
  el.setAttribute("aria-hidden", "false");
}

function getDmProfileCandidateServerRows() {
  const seen = new Set();
  const servers = [];
  (Array.isArray(state.servers) ? state.servers : []).forEach((serverRow) => {
    const sid = normId(serverRow?.serverId || serverRow?.server_id || serverRow?.id || "");
    const kind = String(serverRow?.kind || "server").trim().toLowerCase();
    if (!sid || seen.has(sid) || (kind && kind !== "server")) return;
    seen.add(sid);
    servers.push({
      serverId: sid,
      name: normalizeConversationLabel(serverRow?.name || "Server", "Server"),
      iconUrl: String(serverRow?.iconUrl || serverRow?.icon_url || "").trim(),
      memberCount: Number(serverRow?.memberCount || serverRow?.member_count || 0),
    });
  });
  return servers;
}

function getDmProfileMutualServerSnapshot(userId = "") {
  const uid = normId(userId || "");
  if (!uid) {
    return { status: "unavailable", items: [], count: null, missingServerIds: [] };
  }
  const items = [];
  const missingServerIds = [];
  getDmProfileCandidateServerRows().forEach((serverRow) => {
    const sid = normId(serverRow?.serverId || "");
    if (!sid) return;

    if (!serverMemberListByServerId.has(sid)) {
      missingServerIds.push(sid);
      return;
    }
    const members = Array.isArray(serverMemberListByServerId.get(sid))
      ? (serverMemberListByServerId.get(sid) || [])
      : [];
    if (!members.some((member) => normId(member?.userId || member?.user_id || member?.id || "") === uid)) return;
    items.push(serverRow);
  });
  return {
    status: missingServerIds.length ? "loading" : "loaded",
    items,
    count: missingServerIds.length ? null : items.length,
    missingServerIds,
  };
}

function getDmProfileMutualServers(userId = "") {
  return getDmProfileMutualServerSnapshot(userId).items;
}

function ensureDmProfileMutualExpandedState(userId = "") {
  const uid = normId(userId || "");
  if (dmProfileMutualExpandedState.userId !== uid) {
    dmProfileMutualExpandedState = { userId: uid, servers: false, friends: false };
  }
  return dmProfileMutualExpandedState;
}

function normalizeDmProfileMutualFriendEntries(candidate = []) {
  const seen = new Set();
  const friends = [];
  (Array.isArray(candidate) ? candidate : []).forEach((entry) => {
    const id = normId(entry?.id || entry?.user_id || entry?.userId || entry || "");
    if (!id || seen.has(id)) return;
    seen.add(id);
    const cached = getCachedProfile(id) || {};
    const displayName = String(entry?.display_name || entry?.displayName || cached?.display_name || cached?.username || "").trim();
    const username = String(entry?.username || cached?.username || "").trim();
    const avatarUrl = resolveProfileAvatarUrl(entry?.avatar_url || entry?.avatarUrl || cached?.avatar_url || cached?.avatarUrl || "", "");
    friends.push({
      userId: id,
      displayName: displayName || username || "User",
      username,
      avatarUrl,
      status: getPresenceStatusForUser(id) || "offline",
    });
  });
  return friends;
}

function getDmProfileMutualFriendsSnapshot(profile = {}) {
  const source = profile && typeof profile === "object" ? profile : {};
  const listCandidates = [
    source?.mutual_friends,
    source?.mutualFriends,
    source?.shared_friends,
    source?.sharedFriends,
  ];
  for (const candidate of listCandidates) {
    if (!Array.isArray(candidate)) continue;
    const items = normalizeDmProfileMutualFriendEntries(candidate);
    return { status: "loaded", items, count: items.length, hasList: true };
  }
  const countCandidates = [
    source?.mutual_friend_count,
    source?.mutualFriendCount,
    source?.shared_friend_count,
    source?.sharedFriendCount,
  ];
  for (const candidate of countCandidates) {
    if (candidate === null || typeof candidate === "undefined" || String(candidate).trim() === "") continue;
    const count = Number(candidate);
    if (Number.isFinite(count) && count >= 0) {
      return { status: "loaded", items: [], count: Math.floor(count), hasList: false };
    }
  }
  return { status: "unavailable", items: [], count: null, hasList: false };
}

function getDmProfileMutualFriends(profile = {}) {
  return getDmProfileMutualFriendsSnapshot(profile).items;
}

function getDmProfileMutualFriendCount(profile = {}) {
  const snapshot = getDmProfileMutualFriendsSnapshot(profile);
  return Number.isFinite(Number(snapshot.count)) ? Math.max(0, Math.floor(Number(snapshot.count))) : 0;
}

function buildDmProfileMutualServerEntryHtml(entry = {}) {
  const name = String(entry?.name || "Server").trim();
  const iconUrl = String(entry?.iconUrl || "").trim();
  const initial = name.charAt(0).toUpperCase() || "S";
  const memberCount = Number(entry?.memberCount || 0);
  const sub = memberCount > 0
    ? (memberCount === 1
      ? t("dm.group_member_count_one", "1 member")
      : t("dm.group_member_count", "{n} members").replace("{n}", String(memberCount)))
    : "";
  const iconHtml = iconUrl
    ? lazyMediaImageHtml(iconUrl, { alt: name })
    : `<span>${esc(initial)}</span>`;
  return `
    <div class="dmProfileMutualItemRow">
      <span class="dmProfileContextIcon">${iconHtml}</span>
      <span class="dmProfileContextMeta">
        <span class="dmProfileContextName">${esc(name)}</span>
        ${sub ? `<span class="dmProfileContextSub">${esc(sub)}</span>` : ""}
      </span>
    </div>
  `;
}

function buildDmProfileMutualFriendEntryHtml(entry = {}) {
  const uid = normId(entry?.userId || "");
  const name = String(entry?.displayName || entry?.username || "User").trim();
  const username = String(entry?.username || "").trim();
  const avatarUrl = String(entry?.avatarUrl || "").trim();
  const status = String(entry?.status || getPresenceStatusForUser(uid) || "offline").trim();
  const initial = name.charAt(0).toUpperCase() || "?";
  const avatarHtml = avatarUrl
    ? buildAvatarMediaHtml(avatarUrl, { userId: uid, alt: name, loading: "lazy", deferAnimatedStorage: true })
    : `<span class="groupDmAvatarFallback">${esc(initial)}</span>`;
  return `
    <div class="dmProfileMutualItemRow">
      <span class="dmProfileMutualFriendAvatar">${avatarHtml}<span class="statusDot" data-status="${escAttr(status)}"></span></span>
      <span class="dmProfileContextMeta">
        <span class="dmProfileContextName">${esc(name)}</span>
        ${username ? `<span class="dmProfileContextSub">@${esc(username)}</span>` : ""}
      </span>
    </div>
  `;
}

function buildDmProfileMutualExpandedContentHtml({
  kind = "",
  items = [],
  count = 0,
  status = "loaded",
  emptyText = "",
  loadingText = "",
  unavailableText = "",
} = {}) {
  const safeKind = String(kind || "").trim();
  const safeStatus = String(status || "loaded").trim().toLowerCase();
  const list = Array.isArray(items) ? items : [];
  if (safeStatus === "loading" || safeStatus === "unavailable") {
    const text = safeStatus === "loading"
      ? (loadingText || t("app.loading", "Loading..."))
      : (unavailableText || t("usercard.unavailable", "Unavailable"));
    return `
      <div class="dmProfileMutualExpanded" data-dm-profile-mutual-expanded="${escAttr(safeKind)}" data-state="${escAttr(safeStatus)}">
        <div class="dmProfileMutualEmpty">${esc(text)}</div>
      </div>
    `;
  }
  const total = Math.max(0, Math.floor(Number(count) || list.length || 0));
  const shown = list.slice(0, 5);
  if (!total) {
    return `
      <div class="dmProfileMutualExpanded" data-dm-profile-mutual-expanded="${escAttr(safeKind)}">
        <div class="dmProfileMutualEmpty">${esc(emptyText || "Nothing to show yet.")}</div>
      </div>
    `;
  }
  const rows = shown.map((entry) => (
    safeKind === "friends"
      ? buildDmProfileMutualFriendEntryHtml(entry)
      : buildDmProfileMutualServerEntryHtml(entry)
  )).join("");
  const remaining = Math.max(0, total - shown.length);
  const moreHtml = remaining > 0
    ? `<button class="dmProfileMutualMoreRow" type="button" data-dm-profile-mutual-view-all="${escAttr(safeKind)}">+${esc(String(remaining))} more</button>`
    : "";
  return `
    <div class="dmProfileMutualExpanded" data-dm-profile-mutual-expanded="${escAttr(safeKind)}">
      ${rows}
      ${moreHtml}
    </div>
  `;
}

function buildDmProfileMutualActionRowHtml({
  kind = "",
  label = "",
  count = 0,
  countLabel = "",
  badgeLabel = "",
  status = "loaded",
  disabled = false,
  expanded = false,
} = {}) {
  const safeKind = String(kind || "").trim() || "mutual";
  const safeLabel = String(label || "").trim() || "Mutual";
  const safeStatus = String(status || "loaded").trim().toLowerCase();
  const safeCount = Math.max(0, Math.floor(Number(count) || 0));
  const safeCountLabel = String(countLabel || "").trim() || String(safeCount);
  const safeBadgeLabel = String(badgeLabel || "").trim();
  const isDisabled = !!disabled;
  const stateClass = safeStatus && safeStatus !== "loaded" ? ` is-${safeStatus}` : "";
  const disabledClass = isDisabled ? " is-disabled" : "";
  const trailingHtml = safeBadgeLabel
    ? `<span class="dmProfileMutualActionBadge">${esc(safeBadgeLabel)}</span>`
    : `<span class="dmProfileMutualActionChevron" aria-hidden="true">&rsaquo;</span>`;
  const disabledAttr = isDisabled ? ` disabled aria-disabled="true"` : "";
  return `
    <button class="dmProfileMutualActionRow${expanded ? " is-expanded" : ""}${stateClass}${disabledClass}" type="button" data-dm-profile-mutual-row="${escAttr(safeKind)}" aria-expanded="${expanded ? "true" : "false"}" aria-label="${escAttr(`${safeLabel} - ${safeBadgeLabel || safeCountLabel}`)}"${disabledAttr}>
      <span class="dmProfileMutualActionText">
        <span class="dmProfileMutualActionLabel">${esc(safeLabel)}</span>
        ${safeBadgeLabel ? "" : `<span class="dmProfileMutualActionCount">&mdash; ${esc(safeCountLabel)}</span>`}
      </span>
      ${trailingHtml}
    </button>
  `;
}

function buildDmProfileMutualSectionHtml(userId = "", profile = {}) {
  const serverSnapshot = getDmProfileMutualServerSnapshot(userId);
  const friendSnapshot = getDmProfileMutualFriendsSnapshot(profile);
  const expanded = ensureDmProfileMutualExpandedState(userId);
  const sectionLabel = t("usercard.tab.shared", "Connections");
  const serverCount = Number.isFinite(Number(serverSnapshot.count))
    ? Math.max(0, Math.floor(Number(serverSnapshot.count)))
    : 0;
  const friendCount = Number.isFinite(Number(friendSnapshot.count))
    ? Math.max(0, Math.floor(Number(friendSnapshot.count)))
    : 0;
  const loadingLabel = t("app.loading", "Loading...");
  const unavailableLabel = t("usercard.unavailable", "Unavailable");
  const serverCountLabel = serverSnapshot.status === "loading"
    ? loadingLabel
    : (serverSnapshot.status === "unavailable" ? unavailableLabel : String(serverCount));
  const friendCountLabel = friendSnapshot.status === "unavailable"
    ? unavailableLabel
    : String(friendCount);
  const friendsExpanded = !!expanded.friends && friendSnapshot.status !== "unavailable";
  return `
    <section class="dmProfileContextShell" aria-label="${escAttr(sectionLabel)}">
      <div class="dmProfileMutualActionList">
        ${buildDmProfileMutualActionRowHtml({
          kind: "servers",
          label: t("dm.mutual_servers", "Mutual Servers"),
          count: serverCount,
          countLabel: serverCountLabel,
          status: serverSnapshot.status,
          expanded: !!expanded.servers,
        })}
        ${expanded.servers ? buildDmProfileMutualExpandedContentHtml({
          kind: "servers",
          items: serverSnapshot.items,
          count: serverCount,
          status: serverSnapshot.status,
          emptyText: t("dm.mutual_servers_empty", "No mutual servers yet."),
          loadingText: t("dm.mutual_servers_loading", "Loading mutual servers..."),
          unavailableText: t("dm.mutual_servers_unavailable", "Mutual servers unavailable."),
        }) : ""}
        ${buildDmProfileMutualActionRowHtml({
          kind: "friends",
          label: t("dm.mutual_friends", "Mutual Friends"),
          count: friendCount,
          countLabel: friendCountLabel,
          badgeLabel: friendSnapshot.status === "unavailable" ? t("dm.mutual_friends_soon", "Soon") : "",
          status: friendSnapshot.status,
          disabled: friendSnapshot.status === "unavailable",
          expanded: friendsExpanded,
        })}
        ${friendsExpanded ? buildDmProfileMutualExpandedContentHtml({
          kind: "friends",
          items: friendSnapshot.items,
          count: friendCount,
          status: friendSnapshot.status,
          emptyText: t("dm.mutual_friends_empty", "No mutual friends yet."),
          unavailableText: t("dm.mutual_friends_unavailable", "Mutual friends unavailable."),
        }) : ""}
      </div>
    </section>
  `;
}

function ensureDmProfileMutualServersLoaded(userId = "", profile = {}) {
  const uid = normId(userId || "");
  if (!uid) return;
  const snapshot = getDmProfileMutualServerSnapshot(uid);
  const missingServerIds = normalizeUuidArray(snapshot.missingServerIds || []);
  if (!missingServerIds.length) return;
  const loadKey = `${uid}|${missingServerIds.slice().sort().join(",")}`;
  if (dmProfileMutualServersLoadKey === loadKey && dmProfileMutualServersLoadPromise) return;
  const requestId = ++dmProfileMutualServersLoadSeq;
  dmProfileMutualServersLoadKey = loadKey;
  dmProfileMutualServersLoadPromise = Promise.all(
    missingServerIds.map((sid) => fetchServerMembersForSidebar(sid, { force: false }).catch(() => []))
  ).finally(() => {
    if (requestId === dmProfileMutualServersLoadSeq) {
      dmProfileMutualServersLoadKey = "";
      dmProfileMutualServersLoadPromise = null;
    }
    if (!dmProfilePanelOpen || uid !== getActiveDmPeerUserId()) return;
    renderDmProfileMutualSection(uid, dmProfileMutualProfileSnapshot || profile || getCachedProfile(uid) || {});
  });
}

function renderDmProfileMutualSection(userId = "", profile = {}) {
  const el = document.getElementById("dmProfileMutualSection");
  if (!el) return;
  dmProfileMutualProfileSnapshot = profile && typeof profile === "object" ? profile : {};
  const html = buildDmProfileMutualSectionHtml(userId, profile);
  el.innerHTML = html;
  el.classList.remove("hidden");
  el.setAttribute("aria-hidden", "false");
  bindLazyMediaImages(el);
  ensureDmProfileMutualServersLoaded(userId, profile);
}

async function openDmGroupMembersPanel({ force = false } = {}) {
  if (!activeDmId) return;
  const convId = normId(activeDmId);
  if (!convId) return;
  bindDmProfilePanelOnce();

  dmPinsPanelOpen = false;
  dmProfilePanelOpen = true;
  setDmSidePanelMode("profile");
  syncDmPinsPanelState();
  renderDmGroupMembersPanel([], { loading: true });

  const members = await fetchGroupConversationMembers(convId, { force });
  if (!dmProfilePanelOpen || normId(activeDmId) !== convId) return;
  renderDmGroupMembersPanel(members, { loading: false });
}

function renderDmProfileConnectionsPreview(userId = "", profileInput = {}, { loading = false } = {}) {
  const el = document.getElementById("dmProfileConnectionsPreview");
  if (!el) return;
  const uid = normId(userId || profileInput?.id || "");
  const isSelf = uid === normId(state.user?.id || "");
  const html = buildProfileConnectionsCompactSectionHtml(profileInput || {}, { userId: uid, isSelf, loading, title: "Connections" });
  if (!html) {
    el.innerHTML = "";
    el.classList.add("hidden");
    el.setAttribute("aria-hidden", "true");
    return;
  }
  setElementHtmlIfChanged(el, html);
  el.classList.remove("hidden");
  el.setAttribute("aria-hidden", "false");
}

function renderDmProfilePanel(profile = {}, { loading = false } = {}) {
  const uid = String(profile?.id || "").trim();
  const canonicalName = profile?.display_name || profile?.username || "User";
  const username = profile?.username || "user";
  const bio = String(profile?.bio || "").trim();
  const avatarFallback = state.activeDm?.avatarUrl || state.activeDm?.avatar_url || getCachedProfile(uid)?.avatar_url || getCachedProfile(uid)?.avatarUrl || "";
  const avatarUrl = resolveProfileAvatarUrl(profile?.avatar_url || profile?.avatarUrl || "", avatarFallback) || "";
  const status = uid ? getPresenceStatusForUser(uid) : "offline";
  const nameColor = resolveUserNameColor(uid, profile?.name_color);
  const tileColor = resolveCallTileColor(uid, profile?.call_tile_color);
  const bannerUrl = resolveUserBannerUrl(uid, profile?.banner_url || profile?.theme_settings?.banner_url || "");
  const selfId = normId(state.user?.id || "");
  const isSelf = !!(uid && selfId && uid === selfId);
  const friendNickname = isSelf ? "" : getDmFriendNickname(uid);
  const hasFriendNickname = !!friendNickname;
  const name = hasFriendNickname ? friendNickname : canonicalName;
  const initial = String(name || "?").trim().charAt(0).toUpperCase() || "?";

  const bannerEl = document.getElementById("dmProfileBanner");
  const avatarEl = document.getElementById("dmProfileAvatar");
  const nameEl = document.getElementById("dmProfileName");
  const handleEl = document.getElementById("dmProfileHandle");
  const statusDotEl = document.getElementById("dmProfileStatusDot");
  const statusTextEl = document.getElementById("dmProfileStatusText");
  const bioEl = document.getElementById("dmProfileBio");
  const panel = document.getElementById("dmProfilePanel");
  const titleEl = document.querySelector("#dmProfilePanel .dmProfilePanel__title");
  const footerEl = document.querySelector("#dmProfilePanel .dmProfilePanel__footer");
  const membersBody = document.getElementById("dmGroupMembersBody");
  const identityWrap = document.querySelector("#dmProfilePanel .dmProfileIdentity");
  const statusWrap = document.querySelector("#dmProfilePanel .dmProfilePresence");
  const bioWrap = document.querySelector("#dmProfilePanel .dmProfileSection");
  const activityPreviewEl = document.getElementById("dmProfileActivityPreview");
  const widgetsPreviewEl = document.getElementById("dmProfileWidgetsPreview");
  const mutualSectionEl = document.getElementById("dmProfileMutualSection");
  const connectionsPreviewEl = document.getElementById("dmProfileConnectionsPreview");
  const btnOpen = document.getElementById("btnDmProfileOpenCard");

  if (panel) panel.classList.remove("is-group-members");
  if (titleEl) titleEl.textContent = t("dm.profile_preview", "Profile Preview");
  if (bannerEl) bannerEl.style.display = "";
  if (avatarEl) avatarEl.style.display = "";
  if (identityWrap) identityWrap.style.display = "";
  if (nameEl) nameEl.style.display = "";
  if (handleEl) handleEl.style.display = "";
  if (statusWrap) statusWrap.style.display = "none";
  if (bioWrap) bioWrap.style.display = "";
  if (activityPreviewEl) activityPreviewEl.style.display = "";
  if (widgetsPreviewEl) widgetsPreviewEl.style.display = "";
  if (mutualSectionEl) mutualSectionEl.style.display = "";
  if (connectionsPreviewEl) connectionsPreviewEl.style.display = "";
  if (footerEl) footerEl.style.display = "";
  if (btnOpen) btnOpen.style.display = "";
  if (membersBody) {
    membersBody.style.display = "none";
    membersBody.innerHTML = "";
  }

  if (bannerEl) {
    const base = tileColor || "#344976";
    const start = mixHex(base, "#111827", 0.74);
    const end = mixHex(base, "#0b1018", 0.9);
    const glow = rgbaFromHex(base, 0.24);
    applyBannerStyle(bannerEl, bannerUrl, start, end, glow, {
      overlay: "none",
      userId: uid,
      profile,
    });
    bannerEl.classList.toggle("has-image", !!bannerUrl);
  }
  if (avatarEl) {
    const avatarStatusDotHtml = `<span class="statusDot dmProfileAvatarStatusDot" data-status="${escAttr(status || "offline")}"></span>`;
    avatarEl.innerHTML = avatarUrl
      ? `${buildAvatarMediaHtml(avatarUrl, { userId: uid, profile, alt: "avatar", loading: "lazy", controlledGif: true })}${avatarStatusDotHtml}`
      : `<span class="msg__avatarFallback">${esc(initial)}</span>${avatarStatusDotHtml}`;
    queueManagedGifPlaybackSync(avatarEl);
  }
  if (nameEl) {
    nameEl.textContent = name;
    nameEl.classList.toggle("is-nickname", hasFriendNickname);
    nameEl.classList.toggle("userNameCustom", !!nameColor);
    if (nameColor) nameEl.style.setProperty("--user-name-color", nameColor);
    else nameEl.style.removeProperty("--user-name-color");
  }
  if (handleEl) {
    const handleSegments = [];
    if (hasFriendNickname) {
      const canonicalLower = String(canonicalName || "").trim().toLowerCase();
      const usernameLower = String(username || "").trim().toLowerCase();
      const showCanonical = !!(canonicalLower && canonicalLower !== usernameLower);
      if (showCanonical && username) handleSegments.push(canonicalName, `@${username}`);
      else if (showCanonical) handleSegments.push(canonicalName);
      else handleSegments.push(`@${username || "user"}`);
      handleEl.classList.add("is-nickname");
    } else {
      handleSegments.push(`@${username || "user"}`);
      handleEl.classList.remove("is-nickname");
    }
    setElementHtmlIfChanged(handleEl, buildProfileMetaSegmentsHtml(handleSegments));
  }
  if (statusWrap) statusWrap.style.display = "none";
  if (statusDotEl) statusDotEl.setAttribute("data-status", status || "offline");
  if (statusTextEl) statusTextEl.textContent = dmStatusLabel(status);
  if (bioEl) bioEl.textContent = bio || (loading ? t("app.loading", "Loading...") : t("dm.profile_no_bio", "No bio yet."));
  if (activityPreviewEl) {
    const activityHtml = buildGameActivityCardHtml(getPresenceActivityForUser(uid), { className: "dmProfileActivityCard" });
    activityPreviewEl.innerHTML = activityHtml;
    activityPreviewEl.classList.toggle("hidden", !activityHtml);
    activityPreviewEl.setAttribute("aria-hidden", activityHtml ? "false" : "true");
  }
  renderDmProfileConnectionsPreview(uid, profile, { loading });
  renderDmProfileWidgetsPreview(uid, getCachedProfileWidgetsForUser(uid), { loading });
  renderDmProfileMutualSection(uid, profile);
  renderTypingStatusOnUserCards({ reason: "dm-profile-render" });
}

function refreshDmProfilePanel() {
  if (!dmProfilePanelOpen || !activeDmId) return;
  const activeMeta = getActiveConversationMeta(activeDmId) || {};
  const isServerConversation = isServerConversationKind(activeMeta?.kind) || !!normId(activeMeta?.serverId || "");
  if (isServerConversation) {
    dmProfilePanelOpen = false;
    if (!dmPinsPanelOpen) setDmSidePanelMode("none");
    syncDmPinsPanelState();
    return;
  }
  if (isGroupConversationMeta(activeMeta)) {
    const members = getGroupConversationMembersCache(activeDmId);
    renderDmGroupMembersPanel(members, { loading: !members.length });
    return;
  }
  const seed = getDmPeerProfileSeed();
  if (!seed) return;
  renderDmProfilePanel(seed, { loading: false });
}

async function openDmProfilePanel({ force = false } = {}) {
  if (!activeDmId) return;
  const activeMeta = getActiveConversationMeta(activeDmId) || {};
  const isServerConversation = isServerConversationKind(activeMeta?.kind) || !!normId(activeMeta?.serverId || "");
  if (isServerConversation) {
    dmProfilePanelOpen = false;
    if (!dmPinsPanelOpen) setDmSidePanelMode("none");
    syncDmPinsPanelState();
    return;
  }
  if (isGroupConversationMeta(activeMeta)) {
    await openDmGroupMembersPanel({ force });
    return;
  }
  bindDmProfilePanelOnce();

  dmPinsPanelOpen = false;
  dmProfilePanelOpen = true;
  setDmSidePanelMode("profile");
  syncDmPinsPanelState();

  const seed = getDmPeerProfileSeed();
  if (!seed) return;

  renderDmProfilePanel(seed, { loading: true });

  const requestId = ++dmProfilePanelRequestSeq;
  const uid = seed.id;
  const [fetched, widgetsResult] = await Promise.all([
    fetchProfilesByIds([uid], { includeBio: true, force: true }).catch(() => []),
    fetchProfileWidgetsForUser(uid, { force: !!force })
      .then((rows) => ({ rows, error: null }))
      .catch((error) => ({ rows: getCachedProfileWidgetsForUser(uid), error })),
    fetchPublicConnectedAccountsForUser(uid, { force: !!force }).catch(() => getCachedPublicConnectedAccountsForUser(uid)),
  ]);
  if (requestId !== dmProfilePanelRequestSeq) return;
  if (!dmProfilePanelOpen || uid !== getActiveDmPeerUserId()) return;

  const profile = fetched?.[0] || getCachedProfile(uid) || seed;
  renderDmProfilePanel(profile, { loading: false });
  if (widgetsResult?.error) {
    renderDmProfileWidgetsPreview(uid, widgetsResult.rows || [], {
      loading: false,
      error: toProfileWidgetError(widgetsResult.error, t("profile.widgets.error.load", "Could not load widgets.")),
    });
  }
}

function closeDmProfilePanel() {
  closeGroupMemberMenu();
  dmProfilePanelOpen = false;
  if (!dmPinsPanelOpen) setDmSidePanelMode("none");
  syncDmPinsPanelState();
}

function syncDmPinsPanelState() {
  const pinsPanel = document.getElementById("dmPinsPanel");
  const profilePanel = document.getElementById("dmProfilePanel");
  const pinsBtn = document.getElementById("btnDmPins");
  const profileBtn = document.getElementById("btnDmProfilePanel");
  const dmMain = document.getElementById("dmMain");
  const activeMeta = getActiveConversationMeta(activeDmId) || {};
  const isServerConversation = isServerConversationKind(activeMeta?.kind) || !!normId(activeMeta?.serverId || "");
  if (isServerConversation && dmProfilePanelOpen) {
    dmProfilePanelOpen = false;
  }
  const canShowPins = !!(dmFeatureCaps.advancedMessages && activeDmId && dmPinsPanelOpen);
  const canShowProfile = !!(activeDmId && dmProfilePanelOpen && !isServerConversation);

  if (pinsPanel) {
    pinsPanel.classList.toggle("hidden", !canShowPins);
    pinsPanel.setAttribute("aria-hidden", canShowPins ? "false" : "true");
  }
  if (profilePanel) {
    profilePanel.classList.toggle("hidden", !canShowProfile);
    profilePanel.setAttribute("aria-hidden", canShowProfile ? "false" : "true");
  }
  if (pinsBtn) {
    pinsBtn.classList.toggle("is-on", canShowPins);
    pinsBtn.setAttribute("aria-pressed", canShowPins ? "true" : "false");
  }
  if (profileBtn) {
    if (isServerConversation) {
      const membersOpen = !isRightSidebarCollapsed();
      profileBtn.classList.add("is-members-mode");
      profileBtn.classList.toggle("is-on", membersOpen);
      profileBtn.setAttribute("aria-pressed", membersOpen ? "true" : "false");
    } else {
      profileBtn.classList.remove("is-members-mode");
      profileBtn.classList.toggle("is-on", canShowProfile);
      profileBtn.setAttribute("aria-pressed", canShowProfile ? "true" : "false");
    }
  }
  if (dmMain) dmMain.classList.toggle("sidepanel-open", canShowPins || canShowProfile);
}

function closeDmPinsModal() {
  dmPinsPanelOpen = false;
  if (!dmProfilePanelOpen) setDmSidePanelMode("none");
  syncDmPinsPanelState();
}

function getDisplayFileNameFromUrl(rawUrl = "", fallback = "ficheiro") {
  const safeFallback = String(fallback || "ficheiro").trim() || "ficheiro";
  try {
    const parsed = new URL(String(rawUrl || ""), window.location.href);
    const leaf = decodeURIComponent(String(parsed.pathname || "").split("/").filter(Boolean).pop() || "");
    return leaf || safeFallback;
  } catch (_) {
    return safeFallback;
  }
}

function dmPinFilePreviewHtml({
  icon = "",
  displayName = "",
  meta = "",
  badgeHtml = "",
} = {}) {
  return `
    <div class="dmPinPreview dmPinPreview--file">
      <span class="dmPinPreview__icon" aria-hidden="true">${esc(icon || "FILE")}</span>
      <span class="dmPinPreview__fileText">
        <span class="dmPinPreview__fileName">${esc(displayName || "ficheiro")}</span>
        <span class="dmPinPreview__fileMeta">${esc(meta || "Unknown size")}</span>
      </span>
      ${badgeHtml || ""}
    </div>
  `;
}

function dmPinPreviewHtml(m) {
  const parsed = safeParseMessageContent(m?.content);

  if (parsed.type === "gif") {
    const url = String(parsed.url || "").trim();
    if (url) {
      const gifAttachment = sanitizeAttachmentPayload(parsed.attachment);
      const displayName = gifAttachment
        ? formatAttachmentDisplayName(gifAttachment.name || "gif", gifAttachment.kind)
        : formatAttachmentDisplayName(getDisplayFileNameFromUrl(url, "gif"), "image");
      const meta = gifAttachment
        ? (attachmentMetaLabel(gifAttachment) || "GIF - Unknown size")
        : "GIF - Unknown size";
      return dmPinFilePreviewHtml({ icon: "GIF", displayName, meta });
    }
    return `<div class="dmPinPreview dmPinPreview--text">${esc(getMessagePreviewText(m))}</div>`;
  }

  if (parsed.type === "attachment" || parsed.type === "attachments") {
    const attachments = extractParsedAttachments(parsed);
    const att = attachments.length ? attachments[0] : null;
    if (!att) return `<div class="dmPinPreview dmPinPreview--text">${esc(getMessagePreviewText(m))}</div>`;

    const meta = attachmentMetaLabel(att);
    const displayName = formatAttachmentDisplayName(att.name || "ficheiro", att.kind);
    const spoilerCls = att.spoiler ? " dmPinPreview--spoiler" : "";
    const badgeParts = [];
    if (att.spoiler) badgeParts.push("Blur");
    if (attachments.length > 1) badgeParts.push(`+${attachments.length - 1}`);
    const spoilerBadge = badgeParts.length ? `<span class="dmPinPreview__badge">${esc(badgeParts.join(" "))}</span>` : "";

    if (att.kind === "image") {
      return dmPinFilePreviewHtml({
        icon: isGifLikeAttachment(att) ? "GIF" : "IMG",
        displayName,
        meta: meta || `${isGifLikeAttachment(att) ? "GIF" : "Imagem"} - Unknown size`,
        badgeHtml: spoilerBadge,
      });
    }

    if (att.kind === "video") {
      return dmPinFilePreviewHtml({
        icon: "VID",
        displayName,
        meta: meta || "Video - Unknown size",
        badgeHtml: spoilerBadge,
      });
    }

    if (att.kind === "audio") {
      return `
        <div class="dmPinPreview dmPinPreview--file">
          <span class="dmPinPreview__icon" aria-hidden="true">&#x1F3B5;</span>
          <span class="dmPinPreview__fileText">
            <span class="dmPinPreview__fileName">${esc(displayName)}</span>
            <span class="dmPinPreview__fileMeta">${esc(meta)}</span>
          </span>
        </div>
      `;
    }

    return `
      <div class="dmPinPreview dmPinPreview--file">
        <span class="dmPinPreview__icon" aria-hidden="true">&#x1F4CE;</span>
        <span class="dmPinPreview__fileText">
          <span class="dmPinPreview__fileName">${esc(displayName)}</span>
          <span class="dmPinPreview__fileMeta">${esc(meta)}</span>
        </span>
      </div>
    `;
  }

  if (isSystemChipMessage(parsed)) {
    return `<div class="dmPinPreview dmPinPreview--text">${esc(getSystemEventDisplayText(m, parsed))}</div>`;
  }

  return `<div class="dmPinPreview dmPinPreview--text">${esc(getMessagePreviewText(m))}</div>`;
}

function renderDmPinsList(items) {
  const list = document.getElementById("dmPinsList");
  if (!list) return;
  if (!dmPinsPanelOpen) {
    list.innerHTML = "";
    return;
  }

  if (!Array.isArray(items) || !items.length) {
    list.innerHTML = `<div class="hint">${t("dm.no_pins", "No pinned messages.")}</div>`;
    return;
  }

  list.innerHTML = items.map((m) => {
    const mid = String(m?.id || "");
    if (!mid) return "";
    const name = getMessageAuthorName(m);
    const stamp = getMessageStamp(m?.pinned_at || m?.created_at || new Date().toISOString());
    const parsed = safeParseMessageContent(m?.content);
    const parsedAttachments = (parsed.type === "attachment" || parsed.type === "attachments")
      ? extractParsedAttachments(parsed)
      : [];
    const firstAttachment = parsedAttachments.length ? parsedAttachments[0] : null;
    const kind = parsed.type === "gif"
      ? "GIF"
      : ((parsed.type === "attachment" || parsed.type === "attachments")
        ? (parsedAttachments.length > 1
          ? `${parsedAttachments.length} anexos`
          : (firstAttachment?.kind === "image"
            ? "Imagem"
            : (firstAttachment?.kind === "video"
              ? "Video"
              : (firstAttachment?.kind === "audio" ? "Audio" : "Ficheiro"))))
        : (parsed.type === "call_event"
          ? "Chamada"
          : (parsed.type === "system_event" ? "Sistema" : "Texto")));
    const previewHtml = dmPinPreviewHtml(m);
    return `
      <button class="dmPinRow" type="button" data-dm-pin-open="${escAttr(mid)}">
        <div class="dmPinRow__meta">
          <span class="dmPinRow__name">${esc(name)}</span>
          <span>${esc(stamp)}</span>
          <span>- ${esc(kind)}</span>
        </div>
        <div class="dmPinRow__preview">${previewHtml}</div>
      </button>
    `;
  }).join("");
}

async function ensureDmMessageInCache(messageId) {
  const mid = normId(messageId);
  if (!mid || !activeDmId) return null;
  const historyContext = getServerMessageHistoryContext(activeDmId);
  if (historyContext) {
    const prepared = await prepareServerMessageHistoryForConversation(activeDmId, {
      force: false,
      reason: "message-ensure",
    });
    if (!prepared?.ok) return null;
  }

  const existing = getMessageById(mid);
  if (existing) return existing;

  const { data, error } = await supabase
    .from("messages")
    .select(dmMessageSelectColumns())
    .eq("id", mid)
    .eq("conversation_id", activeDmId)
    .single();

  if (error || !data || normId(data.conversation_id) !== normId(activeDmId)) {
    return null;
  }

  const [resolvedRow] = await hydrateDmRowsForDisplay([data], { conversationId: activeDmId });
  const hydratedRow = resolvedRow || data;
  if (!isMessageRowVisibleForServerHistory(activeDmId, hydratedRow)) return null;

  dmMessagesCache.push(hydratedRow);
  dmMessagesCache.sort((a, b) => new Date(a?.created_at || 0) - new Date(b?.created_at || 0));
  if (hydratedRow.id) dmMessageIds.add(normId(hydratedRow.id));
  cacheProfileRow({
    id: hydratedRow?.user_id,
    username: hydratedRow?.profiles?.username,
    display_name: hydratedRow?.profiles?.display_name,
    avatar_url: hydratedRow?.profiles?.avatar_url,
    name_color: hydratedRow?.profiles?.name_color,
  });
  void fetchProfilesByIds([hydratedRow?.user_id], { includeBio: false });
  renderMessagesFromCache({ keepBottom: false, reason: "message-ensure" });
  return hydratedRow;
}

async function refreshDmPinsPanel({ silent = false, reason = "pins-refresh" } = {}) {
  const conversationId = normId(activeDmId || "");
  if (!conversationId || !dmPinsPanelOpen) return [];
  const historyContext = getServerMessageHistoryContext(conversationId);
  const prepared = historyContext
    ? await prepareServerMessageHistoryForConversation(conversationId, {
      force: false,
      reason: `${reason}-history`,
    })
    : { ok: true, generation: 0 };
  if (historyContext && !prepared?.ok) {
    dmPinsLastValidItems = [];
    renderDmPinsList([]);
    return [];
  }
  const historyGeneration = Number(prepared?.generation || 0);
  const seq = ++dmPinsRefreshSeq;
  const list = document.getElementById("dmPinsList");
  if (!list) return;
  if (!silent && !dmPinsLastValidItems.length) {
    list.innerHTML = `<div class="hint">A carregar pins...</div>`;
  }

  let items = [];
  if (dmFeatureCaps.advancedMessages) {
    const { data, error } = await supabase
      .from("messages")
      .select(dmMessageSelectColumns())
      .eq("conversation_id", conversationId)
      .eq("is_pinned", true)
      .order("pinned_at", { ascending: false })
      .order("created_at", { ascending: false })
      .limit(DM_PIN_LIMIT);
    if (
      seq !== dmPinsRefreshSeq
      || normId(activeDmId || "") !== conversationId
      || !dmPinsPanelOpen
      || (historyContext && !isServerMessageHistoryGenerationCurrent(conversationId, historyGeneration))
    ) {
      if (historyContext) serverMessageHistoryDebugState.staleFetchDiscardedCount += 1;
      return dmPinsLastValidItems;
    }
    if (!error && Array.isArray(data)) {
      items = filterRowsForServerMessageHistory(
        conversationId,
        await hydrateDmRowsForDisplay(data, { conversationId })
      );
      if (
        seq !== dmPinsRefreshSeq
        || normId(activeDmId || "") !== conversationId
        || !dmPinsPanelOpen
        || (historyContext && !isServerMessageHistoryGenerationCurrent(conversationId, historyGeneration))
      ) {
        if (historyContext) serverMessageHistoryDebugState.staleFetchDiscardedCount += 1;
        return dmPinsLastValidItems;
      }
      dmPinsLastValidItems = items;
    } else if (error) {
      console.warn("load pinned messages failed", { reason, error });
      items = dmPinsLastValidItems;
    }
  }

  if (!items.length && !dmPinsLastValidItems.length) {
    items = getPinnedMessagesFromCache();
    if (items.length) dmPinsLastValidItems = items;
  }

  renderDmPinsList(items);
  return items;
}

async function openDmPinsModal() {
  if (!activeDmId) return;
  bindDmPinsModalOnce();

  dmProfilePanelOpen = false;
  dmPinsPanelOpen = true;
  dmPinsLastValidItems = [];
  setDmSidePanelMode("pins");
  syncDmPinsPanelState();
  return refreshDmPinsPanel({ silent: false, reason: "pins-panel-open" });
}

function bindDmPinsModalOnce() {
  if (dmPinsBound) return;
  dmPinsBound = true;

  document.getElementById("btnDmPinsClose")?.addEventListener("click", closeDmPinsModal);

  document.getElementById("dmPinsList")?.addEventListener("click", async (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    const btn = target.closest("[data-dm-pin-open]");
    if (!btn) return;
    const mid = btn.getAttribute("data-dm-pin-open");
    if (!mid) return;

    await ensureDmMessageInCache(mid);
    jumpToMessage(mid);
  });

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    const userCardModal = document.getElementById("userCardModal");
    if (userCardModal && !userCardModal.classList.contains("hidden")) return;
    if (!dmPinsPanelOpen) return;
    closeDmPinsModal();
  });
}

function bindDmProfilePanelOnce() {
  if (dmProfilePanelBound) return;
  dmProfilePanelBound = true;

  document.getElementById("btnDmProfileClose")?.addEventListener("click", closeDmProfilePanel);
  const openFullProfileFromDmPanel = async (ev = null) => {
    const uid = getActiveDmPeerUserId();
    if (!uid) return;
    const anchorEl = ev?.currentTarget || ev?.target || document.getElementById("dmProfileAvatar") || null;
    await openUserCardModal(uid, { username: state.activeDm?.username || "" }, {
      anchorEl,
      conversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
      conversationLabel: String(state.activeDm?.displayName || state.activeDm?.username || "").trim(),
      serverId: normId(state.activeDm?.serverId || ""),
      kind: normId(state.activeDm?.serverId || "") ? "server" : String(state.activeDm?.kind || "").trim().toLowerCase(),
      presentation: "overlay",
      initialTab: "widgets",
    });
  };
  const bindProfileOpenTarget = (el) => {
    if (!el) return;
    const isButton = el.tagName === "BUTTON";
    if (!isButton) {
      el.classList.add("is-clickable");
      el.setAttribute("role", "button");
      if (!el.hasAttribute("tabindex")) el.setAttribute("tabindex", "0");
    }
    el.addEventListener("click", openFullProfileFromDmPanel);
    if (!isButton) {
      el.addEventListener("keydown", (e) => {
        if (e.key !== "Enter" && e.key !== " ") return;
        e.preventDefault();
        void openFullProfileFromDmPanel(e);
      });
    }
  };

  bindProfileOpenTarget(document.getElementById("btnDmProfileOpenCard"));
  bindProfileOpenTarget(document.getElementById("dmProfileAvatar"));
  bindProfileOpenTarget(document.getElementById("dmProfileName"));
  bindProfileOpenTarget(document.getElementById("dmProfileHandle"));
  bindProfileOpenTarget(document.getElementById("dmTitle"));

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    const userCardModal = document.getElementById("userCardModal");
    if (userCardModal && !userCardModal.classList.contains("hidden")) return;
    if (!dmProfilePanelOpen) return;
    closeDmProfilePanel();
  });

  const panelBody = document.querySelector("#dmProfilePanel .dmProfilePanel__body");
  panelBody?.addEventListener("click", async (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    const widgetPreview = target.closest("[data-dm-profile-widget-preview]");
    if (widgetPreview) {
      const uid = getActiveDmPeerUserId();
      if (!uid) return;
      await openUserCardModal(uid, { username: state.activeDm?.username || "" }, {
        conversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
        conversationLabel: String(state.activeDm?.displayName || state.activeDm?.username || "").trim(),
        serverId: normId(state.activeDm?.serverId || ""),
        kind: normId(state.activeDm?.serverId || "") ? "server" : String(state.activeDm?.kind || "").trim().toLowerCase(),
        presentation: "overlay",
        initialTab: "widgets",
      });
      return;
    }
    const mutualViewAll = target.closest("[data-dm-profile-mutual-view-all]");
    if (mutualViewAll) {
      const uid = getActiveDmPeerUserId();
      if (!uid) return;
      await openUserCardModal(uid, { username: state.activeDm?.username || "" }, {
        conversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
        conversationLabel: String(state.activeDm?.displayName || state.activeDm?.username || "").trim(),
        serverId: normId(state.activeDm?.serverId || ""),
        kind: normId(state.activeDm?.serverId || "") ? "server" : String(state.activeDm?.kind || "").trim().toLowerCase(),
        presentation: "overlay",
        initialTab: "shared",
        anchorEl: mutualViewAll,
      });
      return;
    }
    const mutualRow = target.closest("[data-dm-profile-mutual-row]");
    if (mutualRow) {
      const uid = getActiveDmPeerUserId();
      if (!uid) return;
      const kind = String(mutualRow.getAttribute("data-dm-profile-mutual-row") || "").trim();
      const expanded = ensureDmProfileMutualExpandedState(uid);
      if (kind === "servers") expanded.servers = !expanded.servers;
      else if (kind === "friends") expanded.friends = !expanded.friends;
      renderDmProfileMutualSection(uid, dmProfileMutualProfileSnapshot || getCachedProfile(uid) || {});
      return;
    }
    const row = target.closest("[data-group-member-id]");
    if (!row) return;
    const uid = normId(row.getAttribute("data-group-member-id") || "");
    if (!uid) return;
    const member = findGroupMemberInfo(activeDmId, uid) || {};
    const anchorEl = row;
    await openUserCardModal(uid, {
      username: member?.username || "",
      display_name: member?.displayName || "",
      avatar_url: member?.avatarUrl || "",
      name_color: member?.nameColor || "",
    }, {
      anchorEl,
      conversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
      conversationLabel: String(state.activeDm?.displayName || "").trim(),
      serverId: normId(state.activeDm?.serverId || ""),
      kind: normId(state.activeDm?.serverId || "") ? "server" : "group",
    });
  });

  panelBody?.addEventListener("contextmenu", (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    const row = target.closest("[data-group-member-id]");
    if (!row) return;
    const uid = normId(row.getAttribute("data-group-member-id") || "");
    if (!uid) return;
    const meId = normId(state.user?.id || "");
    const canRing = uid !== meId;
    e.preventDefault();
    openGroupMemberMenuAt(uid, { x: e.clientX, y: e.clientY }, { canRing });
  });
}

function getUserCardAnchorRect() {
  if (userCardAnchorEl && document.body?.contains(userCardAnchorEl) && typeof userCardAnchorEl.getBoundingClientRect === "function") {
    const rect = userCardAnchorEl.getBoundingClientRect();
    if ((rect.width > 0 && rect.height > 0) || Number.isFinite(rect.left) || Number.isFinite(rect.top)) {
      userCardLastAnchorRect = {
        left: Number(rect.left || 0),
        right: Number(rect.right || 0),
        top: Number(rect.top || 0),
        bottom: Number(rect.bottom || 0),
        width: Number(rect.width || 0),
        height: Number(rect.height || 0),
      };
      return rect;
    }
  }
  if (userCardAnchorPoint && Number.isFinite(Number(userCardAnchorPoint.x)) && Number.isFinite(Number(userCardAnchorPoint.y))) {
    const x = Number(userCardAnchorPoint.x);
    const y = Number(userCardAnchorPoint.y);
    userCardLastAnchorRect = { left: x, right: x, top: y, bottom: y, width: 0, height: 0 };
    return userCardLastAnchorRect;
  }
  if (userCardLastAnchorRect) return userCardLastAnchorRect;
  return null;
}

function positionUserCardModal() {
  const modal = document.getElementById("userCardModal");
  const card = modal?.querySelector(".userCardCard");
  if (!modal || !card || modal.classList.contains("hidden")) return;

  const vw = window.innerWidth || document.documentElement.clientWidth || 0;
  const vh = window.innerHeight || document.documentElement.clientHeight || 0;
  const margin = 8;
  const gap = 10;
  const rect = userCardPresentationMode === "overlay" ? null : getUserCardAnchorRect();

  const cardWidth = Math.min(card.offsetWidth || 780, Math.max(280, vw - margin * 2));
  const cardHeight = Math.min(card.offsetHeight || 560, Math.max(220, vh - margin * 2));

  let left = Math.round((vw - cardWidth) / 2);
  let top = Math.round((vh - cardHeight) / 2);

  if (rect) {
    left = Math.round(rect.right + gap);
    const anchorMidY = Number(rect.top || 0) + (Number(rect.height || 0) / 2);
    top = Math.round(anchorMidY - (cardHeight * 0.34));

    if (left + cardWidth > vw - margin) left = Math.round(rect.left - cardWidth - gap);
    if (left < margin) {
      left = Math.round(Math.min(Math.max(margin, Number(rect.left || 0)), vw - cardWidth - margin));
    }
  }

  left = Math.max(margin, Math.min(left, vw - cardWidth - margin));
  top = Math.max(margin, Math.min(top, vh - cardHeight - margin));

  card.style.left = `${left}px`;
  card.style.top = `${top}px`;
}

function queueUserCardModalPosition() {
  requestAnimationFrame(() => positionUserCardModal());
}

function applyUserCardModalPresentation(modeInput = "anchored") {
  const modal = document.getElementById("userCardModal");
  if (!modal) return;
  const mode = String(modeInput || "").trim().toLowerCase() === "overlay"
    ? "overlay"
    : "anchored";
  userCardPresentationMode = mode;
  modal.classList.toggle("userCardModal--overlay", mode === "overlay");
}

function applyUserCardModalLayout(modeInput = "full") {
  const modal = document.getElementById("userCardModal");
  if (!modal) return;
  const mode = String(modeInput || "").trim().toLowerCase() === "preview"
    ? "preview"
    : "full";
  userCardLayoutMode = mode;
  modal.classList.toggle("userCardModal--preview", mode === "preview");
}

function closeUserCardModal() {
  const modal = document.getElementById("userCardModal");
  if (!modal) return;
  const card = modal.querySelector(".userCardCard");
  if (card) {
    card.style.removeProperty("left");
    card.style.removeProperty("top");
  }
  modal.classList.add("hidden");
  modal.setAttribute("aria-hidden", "true");
  userCardCurrentUserId = null;
  userCardCurrentUsername = "";
  userCardAnchorEl = null;
  userCardAnchorPoint = null;
  userCardLastAnchorRect = null;
  userCardCurrentContext = null;
  userCardCurrentInsights = null;
  userCardInsightsLoading = false;
  userCardWidgetsLoading = false;
  userCardWidgetsError = "";
  userCardPublicConnectionsLoading = false;
  userCardPublicConnectionsError = "";
  userCardWidgetsMutating = false;
  userCardWidgetRefreshToken += 1;
  userCardActiveTab = "widgets";
  applyUserCardModalPresentation("anchored");
  applyUserCardModalLayout("full");
  closeProfileWidgetInlineSearchPopover({ refresh: false });
  closeProfileWidgetModal();
  closeProfileWidgetItemModal();
  if (profileTimerWidgetTicker) {
    clearInterval(profileTimerWidgetTicker);
    profileTimerWidgetTicker = 0;
  }
}

function normalizeUserCardContext(contextInput = {}) {
  const context = (contextInput && typeof contextInput === "object") ? contextInput : {};
  const conversationId = normId(context.conversationId || "");
  const serverId = normId(context.serverId || "");
  const conversationMeta = conversationId ? (getConversationMeta(conversationId) || {}) : {};
  const serverRow = serverId ? (getServerRowById(serverId) || {}) : null;
  const canUseLiveConversationLabel = !!(conversationId || serverId);

  let kind = String(context.kind || conversationMeta?.kind || "").trim().toLowerCase();
  if (!kind && serverId) kind = "server";
  if (kind !== "server" && kind !== "group") kind = "dm";

  const conversationLabel = String(
    context.conversationLabel
    || conversationMeta?.displayName
    || (kind === "server" ? serverRow?.name : "")
    || (canUseLiveConversationLabel ? state.activeDm?.displayName : "")
    || (canUseLiveConversationLabel ? state.activeDm?.username : "")
    || ""
  ).trim();

  return {
    conversationId,
    serverId,
    kind,
    conversationLabel,
    serverName: String(context.serverName || serverRow?.name || "").trim(),
  };
}

function formatUserCardDate(valueInput = "") {
  const raw = String(valueInput || "").trim();
  if (!raw) return "";
  const ms = Date.parse(raw);
  if (!Number.isFinite(ms) || ms <= 0) return "";
  const { locale } = getMessageLocaleContext();
  try {
    return new Date(ms).toLocaleDateString(locale, {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  } catch (_) {
    return raw;
  }
}

function getUserCardRelationMeta(userId) {
  const uid = normId(userId);
  const selfId = normId(state.user?.id || "");
  if (!uid) return { label: "", tone: "" };
  if (uid === selfId) {
    return { label: "", tone: "self", since: "", isSelf: true, kind: "self" };
  }
  if (isUserBlockedLocally(uid)) {
    return { label: t("relationship.blocked", "Blocked"), tone: "pending", since: "", isSelf: false, kind: "blocked" };
  }

  const friend = getFriendRowByUserId(uid) || null;
  if (friend) {
    const bestFriend = isDmBestFriend(uid);
    return {
      label: bestFriend ? t("usercard.best_friend", "Best friend") : t("usercard.friend_rel", "Friend"),
      tone: bestFriend ? "best" : "friend",
      since: String(friend?.since || friend?.created_at || "").trim(),
      isSelf: false,
      kind: "friend",
    };
  }

  const incoming = (state.incoming || []).find((row) => normId(row?.from_user_id || row?.user_id || row?.id || "") === uid) || null;
  if (incoming) {
    return {
      label: "Pedido recebido",
      tone: "pending",
      since: String(incoming?.created_at || "").trim(),
      isSelf: false,
      kind: "friend_request",
    };
  }

  const outgoing = (state.outgoing || []).find((row) => normId(row?.to_user_id || row?.user_id || row?.id || "") === uid) || null;
  if (outgoing) {
    return {
      label: "Pedido enviado",
      tone: "pending",
      since: String(outgoing?.created_at || "").trim(),
      isSelf: false,
      kind: "friend_request",
    };
  }

  const incomingMessage = getIncomingMessageRequestByUserId(uid) || null;
  if (incomingMessage) {
    return {
      label: "Msg recebida",
      tone: "pending",
      since: String(incomingMessage?.created_at || "").trim(),
      isSelf: false,
      kind: "message_request",
    };
  }

  const outgoingMessage = getOutgoingMessageRequestByUserId(uid) || null;
  if (outgoingMessage) {
    return {
      label: "Msg enviada",
      tone: "pending",
      since: String(outgoingMessage?.created_at || "").trim(),
      isSelf: false,
      kind: "message_request",
    };
  }

  return { label: "", tone: "", since: "", isSelf: false, kind: "" };
}

function getUserCardMessageActionMeta(userId, username = "") {
  const uid = normId(userId);
  const uname = String(username || "").trim();
  const selfId = normId(state.user?.id || "");
  if (!uid || uid === selfId) {
    return { label: "", disabled: true, action: "none", requestId: "" };
  }
  if (isUserBlockedLocally(uid)) {
    return { label: t("usercard.message", "Message"), disabled: true, action: "blocked", requestId: "", reason: "You can't message this user." };
  }
  if (getFriendRowByUserId(uid) || getMessageContactRowByUserId(uid)) {
    return { label: t("usercard.message", "Message"), disabled: !uname, action: "open_dm", requestId: "" };
  }
  const incomingMessage = getIncomingMessageRequestByUserId(uid);
  if (incomingMessage) {
    return {
      label: t("inbox.action.accept", "Accept"),
      disabled: false,
      action: "accept_message_request",
      requestId: String(incomingMessage?.request_id || "").trim(),
    };
  }
  const outgoingMessage = getOutgoingMessageRequestByUserId(uid);
  if (outgoingMessage) {
    return {
      label: t("msg.action.request_pending", "Request sent"),
      disabled: true,
      action: "pending_message_request",
      requestId: String(outgoingMessage?.request_id || "").trim(),
    };
  }
  const gate = getCanMessageUserCachedOrLocal(uid);
  if (!gate?.allowed || gate.route === "blocked") {
    return {
      label: t("usercard.message", "Message"),
      disabled: true,
      action: "privacy_blocked",
      requestId: "",
      reason: gate?.reason || "This user isn't accepting messages from people outside their privacy settings.",
    };
  }
  return {
    label: t("usercard.message", "Message"),
    disabled: !uname,
    action: "send_message_request",
    requestId: "",
    route: gate.route || "request",
    reason: gate.route === "request" ? "This will send a message request." : "",
  };
}

function isProfileActionsDebugEnabled() {
  try {
    return typeof localStorage !== "undefined"
      && (
        String(localStorage.getItem("altara.debug.profileActions") || "").trim() === "1"
        || String(localStorage.getItem(MESSAGE_REQUESTS_DEBUG_STORAGE_KEY) || "").trim() === "1"
      );
  } catch (_) {
    return false;
  }
}

function buildProfileActionsDebugState(targetUserId, extra = {}) {
  const uid = normId(targetUserId || "");
  const incomingFriend = (state.incoming || []).find((row) => normId(row?.from_user_id || row?.user_id || row?.id || "") === uid) || null;
  const outgoingFriend = (state.outgoing || []).find((row) => normId(row?.to_user_id || row?.user_id || row?.id || "") === uid) || null;
  return {
    targetUserId: uid,
    isFriend: !!getFriendRowByUserId(uid),
    isBestFriend: isDmBestFriend(uid),
    isContact: !!getMessageContactRowByUserId(uid),
    hasOutgoingFriendRequest: !!outgoingFriend,
    hasIncomingFriendRequest: !!incomingFriend,
    hasIncomingMessageRequest: !!getIncomingMessageRequestByUserId(uid),
    hasOutgoingMessageRequest: !!getOutgoingMessageRequestByUserId(uid),
    ...extra,
  };
}

function debugProfileActions(targetUserId, extra = {}) {
  if (!isProfileActionsDebugEnabled()) return;
  try {
    console.debug("[ProfileActions]", buildProfileActionsDebugState(targetUserId, extra));
  } catch (_) {}
}

function buildUserCardFactHtml(label, value, { mono = false } = {}) {
  const safeLabel = String(label || "").trim();
  const safeValue = String(value || "").trim();
  if (!safeLabel || !safeValue) return "";
  return `
    <div class="userCardFact">
      <div class="userCardFact__label">${esc(safeLabel)}</div>
      <div class="userCardFact__value${mono ? " userCardFact__value--mono" : ""}">${esc(safeValue)}</div>
    </div>
  `;
}

function buildProfileSpotifyProgressHtml(activity = null) {
  const normalized = sanitizeSpotifyActivity(activity || null);
  if (!normalized || normalized.showProgress === false) return "";
  const progress = getSpotifyActivityProgress(normalized);
  if (!progress.durationMs) return "";
  return '<div class="profile-spotify-progress" data-spotify-activity-progress="1" data-spotify-started-at="' + escAttr(normalized.startedAt || 0) + '" data-spotify-progress-ms="' + escAttr(normalized.progressMs || 0) + '" data-spotify-duration-ms="' + escAttr(normalized.durationMs || 0) + '" data-spotify-is-playing="' + escAttr(normalized.isPlaying !== false ? '1' : '0') + '">' +
    '<div class="profile-spotify-progress__time" data-spotify-progress-label="1">' + esc(formatSpotifyTime(progress.progressMs) + ' / ' + formatSpotifyTime(progress.durationMs)) + '</div>' +
    '<div class="spotifyActivityProgress__bar profile-spotify-progress__bar" aria-hidden="true"><span style="--spotify-progress:' + escAttr(progress.percent.toFixed(2)) + '%"></span></div>' +
  '</div>';
}

function buildProfileSpotifyCardHtml(activityInput = null) {
  const activity = sanitizeSpotifyActivity(activityInput || null);
  if (!activity) return "";
  const artistLine = activity.artist || activity.details || "Spotify";
  const albumLine = String(activity.album || "").trim();
  const artworkUrl = normalizeActivityImageUrl(activity.artworkUrl || "");
  const artworkHtml = '<div class="profile-spotify-cover activityArtworkThumb" aria-hidden="true"' + (artworkUrl ? ' data-image-url="' + escAttr(artworkUrl) + '"' : '') + '>' +
    '<span>SP</span>' +
    (artworkUrl ? '<img src="' + escAttr(artworkUrl) + '" alt="" loading="lazy" />' : "") +
  '</div>';
  return '<section class="profile-spotify-card" data-spotify-profile-activity="1">' +
    artworkHtml +
    '<div class="profile-spotify-info">' +
      '<div class="profile-spotify-label">Listening to Spotify</div>' +
      '<div class="profile-spotify-title" title="' + escAttr(activity.name) + '">' + esc(activity.name) + '</div>' +
      '<div class="profile-spotify-artist" title="' + escAttr(artistLine) + '">' + esc(artistLine) + '</div>' +
      (albumLine ? '<div class="profile-spotify-album" title="' + escAttr(albumLine) + '">' + esc(albumLine) + '</div>' : '') +
      buildProfileSpotifyProgressHtml(activity) +
    '</div>' +
  '</section>';
}

function buildUserCardActivityPanelHtml(profile = {}, insights = {}, { loading = false, context = null, hasPublicActivity = false } = {}) {
  void profile;
  void insights;
  void context;

  if (loading && !hasPublicActivity) {
    return `
      <div class="userCardPanelIntro">
        <div class="userCardPanelEyebrow">${esc(t("usercard.activity.eyebrow", "Activity"))}</div>
        <div class="userCardPanelTitle">${esc(t("usercard.activity.loading.title", "Loading activity..."))}</div>
        <div class="userCardPanelText">${esc(t("usercard.activity.loading.text", "Checking public activity status."))}</div>
      </div>
    `;
  }

  const title = hasPublicActivity
    ? t("usercard.activity.latest.title", "Public activity")
    : t("usercard.activity.empty.title", "No public activity right now.");
  const text = hasPublicActivity
    ? t("usercard.activity.subtitle.default", "Safe public activity only.")
    : t("usercard.activity.empty.span", "Only public presence activity appears here.");

  return `
    <div class="userCardPanelIntro">
      <div class="userCardPanelEyebrow">${esc(t("usercard.activity.eyebrow", "Activity"))}</div>
      <div class="userCardPanelTitle">${esc(title)}</div>
      <div class="userCardPanelText">${esc(text)}</div>
    </div>
    ${hasPublicActivity ? "" : `
      <div class="userCardEmptyState">
        <strong>${esc(t("usercard.activity.empty.strong", "Nothing to show yet."))}</strong>
        <span>${esc(t("usercard.activity.empty.span", "Only public presence activity appears here."))}</span>
      </div>
    `}
  `;
}

function buildUserCardMediaPanelHtml(profile = {}, insights = {}, { loading = false } = {}) {
  void profile;
  void insights;
  void loading;
  return `
    <div class="userCardPanelIntro">
      <div class="userCardPanelEyebrow">Media</div>
      <div class="userCardPanelTitle">No public media activity</div>
      <div class="userCardPanelText">Conversation media is private and is not shown on profiles.</div>
    </div>
    <div class="userCardEmptyState">
      <strong>Nothing to show yet.</strong>
      <span>Only safe public activity belongs in profile surfaces.</span>
    </div>
  `;
}

const PROFILE_CONNECTION_PROVIDER_CONFIG = Object.freeze({
  spotify: { label: "Spotify", icon: "spotify" },
  instagram: { label: "Instagram", icon: "instagram" },
  discord: { label: "Discord", icon: "DC" },
  steam: { label: "Steam", icon: "ST" },
  github: { label: "GitHub", icon: "GH" },
  playstation: { label: "PlayStation", icon: "PS" },
  xbox: { label: "Xbox", icon: "XB" },
  youtube: { label: "YouTube", icon: "YT" },
  twitch: { label: "Twitch", icon: "TW" },
  tiktok: { label: "TikTok", icon: "TT" },
  website: { label: "Website", icon: "WEB" },
});

function normalizePublicConnectionProvider(value = "") {
  return String(value || "").trim().toLowerCase().replace(/[^a-z0-9_-]/g, "").slice(0, 40);
}

function getProfileConnectionProviderConfig(providerInput = "") {
  const provider = normalizePublicConnectionProvider(providerInput);
  return PROFILE_CONNECTION_PROVIDER_CONFIG[provider] || {
    label: provider ? provider.charAt(0).toUpperCase() + provider.slice(1) : "Connection",
    icon: provider ? provider.slice(0, 2).toUpperCase() : "ID",
  };
}

function normalizeConnectionProfileUrl(value = "", providerInput = "") {
  const raw = String(value || "").trim();
  const provider = normalizePublicConnectionProvider(providerInput || "");
  if (!raw || /^(javascript|file|blob|data):/i.test(raw)) return "";
  let url;
  try { url = new URL(raw); } catch (_) { return ""; }
  if (url.protocol !== "https:") return "";
  url.hash = "";
  const host = url.hostname.toLowerCase();
  const path = url.pathname.replace(/\/+$/, "");
  if (provider === "spotify" && host === "open.spotify.com" && /^\/user\/[A-Za-z0-9._-]+$/.test(path)) {
    return "https://open.spotify.com" + path;
  }
  if (provider === "instagram" && (host === "instagram.com" || host === "www.instagram.com") && /^\/[A-Za-z0-9._]{1,30}$/.test(path)) {
    return "https://instagram.com" + path;
  }
  if (provider === "youtube" && (host === "youtube.com" || host === "www.youtube.com") && (/^\/@[A-Za-z0-9._-]{3,40}$/.test(path) || /^\/(channel|c|user)\/[A-Za-z0-9._-]{3,80}$/.test(path))) {
    return "https://www.youtube.com" + path;
  }
  if (provider === "steam" && host === "steamcommunity.com" && /^\/(id\/[A-Za-z0-9_-]{2,32}|profiles\/[0-9]{16,20})$/.test(path)) {
    return "https://steamcommunity.com" + path;
  }
  return "";
}

function normalizePublicConnectionAvatarUrl(providerInput = "", valueInput = "") {
  const provider = normalizePublicConnectionProvider(providerInput || "");
  const safeUrl = normalizeActivityImageUrl(valueInput || "");
  if (!safeUrl || !safeUrl.startsWith("https://")) return "";
  try {
    const url = new URL(safeUrl);
    const host = url.hostname.toLowerCase();
    if (provider === STEAM_PROVIDER) {
      return /^(avatars\.(akamai\.|cloudflare\.)?steamstatic\.com|media\.steamstatic\.com)$/.test(host) ? safeUrl : "";
    }
    return safeUrl;
  } catch (_) {
    return "";
  }
}

function normalizePublicConnectedAccount(row = null) {
  if (!row || typeof row !== "object") return null;
  const provider = normalizePublicConnectionProvider(row.provider || "");
  if (!provider) return null;
  const config = getProfileConnectionProviderConfig(provider);
  const providerUsername = String(row.provider_username || row.providerUsername || row.username || "").trim().slice(0, 120);
  const providerDisplayName = String(row.provider_display_name || row.providerDisplayName || row.displayName || row.name || "").trim().slice(0, 120);
  const profileUrl = normalizeConnectionProfileUrl(row.profile_url || row.profileUrl || row.url || "", provider);
  const rawSource = String(row.source || "").trim().toLowerCase();
  const source = rawSource === "manual" ? "manual" : (rawSource === "verified" ? "verified" : "oauth");
  const verified = source === "manual" ? false : (row.verified === true || row.verified === "true" || source === "verified" || provider === SPOTIFY_PROVIDER);
  const updatedAt = String(row.updated_at || row.updatedAt || "").trim();
  let displayName = String(row.displayName || row.display_name || providerDisplayName || providerUsername || config.label || "").trim().slice(0, 120);
  let subtitle = String(row.subtitle || row.description || (verified ? "Verified " + config.label + " account" : config.label) || "").trim().slice(0, 140);
  const avatarUrl = normalizePublicConnectionAvatarUrl(provider, row.avatarUrl || row.avatar_url || row.imageUrl || row.image_url || "");
  if (provider === STEAM_PROVIDER && verified) {
    if (!displayName || isTechnicalConnectionIdentifier(displayName)) displayName = "Steam";
    subtitle = "Verified Steam account";
  }
  if (provider === YOUTUBE_PROVIDER && verified) {
    if (!displayName || isTechnicalConnectionIdentifier(displayName)) displayName = "YouTube";
    subtitle = "Verified YouTube channel";
  }
  return {
    provider,
    label: String(row.label || config.label || provider).trim().slice(0, 80),
    displayName,
    subtitle,
    providerUsername,
    providerDisplayName,
    profileUrl,
    source,
    verified,
    avatarUrl,
    updatedAt,
  };
}

function isTechnicalConnectionIdentifier(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return false;
  const lower = raw.toLowerCase();
  return lower.startsWith("spotify:user:")
    || lower.startsWith("spotify:")
    || lower.startsWith("urn:")
    || lower.includes(":user:")
    || /^[0-9]{12,24}$/.test(lower)
    || /^[0-9]{3,6}\.{3}[0-9]{3,6}$/.test(lower)
    || lower.length > 40;
}

function getHumanReadableConnectionUsername(account = null) {
  const normalized = normalizePublicConnectedAccount(account);
  if (!normalized || isTechnicalConnectionIdentifier(normalized.providerUsername)) return "";
  return normalized.providerUsername;
}

function getProfileConnectionDisplayTitle(account = null) {
  const normalized = normalizePublicConnectedAccount(account);
  if (!normalized) return "Connection";
  const config = getProfileConnectionProviderConfig(normalized.provider);
  const displayName = String(normalized.providerDisplayName || "").trim();
  if (displayName && !isTechnicalConnectionIdentifier(displayName)) return displayName;
  const username = getHumanReadableConnectionUsername(normalized);
  return username || config.label;
}

function buildProfileConnectionIconHtml(providerInput = "") {
  const provider = normalizePublicConnectionProvider(providerInput);
  const config = getProfileConnectionProviderConfig(provider);
  if (provider === "spotify") {
    return '<svg class="profile-connection-iconGlyph" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6.2 8.1c3.9-1.1 8.2-.7 11.7 1.2"/><path d="M7 11.4c3.1-.9 6.8-.5 9.4 1"/><path d="M7.7 14.6c2.3-.6 5-.4 7 .7"/></svg>';
  }
  if (provider === "instagram") {
    return '<svg class="profile-connection-iconGlyph" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="6" y="6" width="12" height="12" rx="4"/><circle cx="12" cy="12" r="3"/><path d="M16.2 7.8h.01"/></svg>';
  }
  if (provider === "youtube") {
    return '<svg class="profile-connection-iconGlyph profile-connection-iconGlyph--fill" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9.5 8.2v7.6L16 12z"/></svg>';
  }
  if (provider === "steam") {
    return '<svg class="profile-connection-iconGlyph" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="15.5" cy="8.5" r="3"/><circle cx="8.2" cy="15.8" r="2.6"/><path d="M10.4 14.4l3-3"/><path d="M5.5 14.5l2.1.9"/></svg>';
  }
  return esc(config.icon);
}

function shortenSteamId64(value = "") {
  const raw = String(value || "").trim();
  if (raw.length <= 10) return raw;
  return raw.slice(0, 4) + "..." + raw.slice(-4);
}

function normalizeSteamProfileConnectionUrl(steamid64Input = "", urlInput = "") {
  const steamid64 = String(steamid64Input || "").trim();
  const explicit = normalizeConnectionProfileUrl(urlInput || "", STEAM_PROVIDER);
  if (explicit && (explicit.startsWith("https://steamcommunity.com/profiles/") || explicit.startsWith("https://steamcommunity.com/id/"))) return explicit;
  if (/^\d{16,20}$/.test(steamid64)) return "https://steamcommunity.com/profiles/" + steamid64;
  return "";
}

function getPublicProfileConnections(profileInput = null) {
  const profile = profileInput && typeof profileInput === "object" ? profileInput : {};
  const connectedAccounts = profile.connected_accounts && typeof profile.connected_accounts === "object" && !Array.isArray(profile.connected_accounts) ? profile.connected_accounts : {};
  const out = [];
  const steam = connectedAccounts.steam && typeof connectedAccounts.steam === "object" && !Array.isArray(connectedAccounts.steam) ? connectedAccounts.steam : null;
  if (steam) {
    const steamid64 = String(steam.steamid64 || steam.steamId64 || "").trim();
    const showOnProfile = steam.showOnProfile === true || steam.show_on_profile === true || steam.show_on_profile === "true" || steam.showOnProfile === "true";
    const verified = steam.verified === true || steam.verified === "true";
    const url = normalizeSteamProfileConnectionUrl(steamid64, steam.profileUrl || steam.profile_url || "");
    if (showOnProfile && verified && /^\d{16,20}$/.test(steamid64) && url) {
      const personaName = String(steam.displayName || steam.personaName || steam.providerDisplayName || "").trim();
      out.push({
        provider: STEAM_PROVIDER,
        label: "Steam",
        displayName: personaName || "Steam",
        subtitle: "Verified Steam account",
        providerUsername: steamid64,
        providerDisplayName: personaName || "",
        profileUrl: url,
        source: "verified",
        verified: true,
        avatarUrl: normalizePublicConnectionAvatarUrl(STEAM_PROVIDER, steam.avatarMedium || steam.avatar || steam.avatarFull || steam.avatarUrl || ""),
        updatedAt: String(steam.lastSyncedAt || steam.linkedAt || "").trim(),
      });
    }
  }
  const spotify = connectedAccounts.spotify && typeof connectedAccounts.spotify === "object" && !Array.isArray(connectedAccounts.spotify) ? connectedAccounts.spotify : null;
  if (spotify) {
    const showOnProfile = spotify.showOnProfile === true || spotify.show_on_profile === true || spotify.show_on_profile === "true" || spotify.showOnProfile === "true";
    const url = normalizeConnectionProfileUrl(spotify.profileUrl || spotify.profile_url || "", SPOTIFY_PROVIDER);
    if (showOnProfile && (spotify.verified === true || spotify.connected === true || spotify.provider === SPOTIFY_PROVIDER)) {
      out.push({
        provider: SPOTIFY_PROVIDER,
        label: "Spotify",
        displayName: String(spotify.displayName || spotify.providerDisplayName || spotify.username || "Spotify").trim() || "Spotify",
        subtitle: "Verified Spotify account",
        providerUsername: String(spotify.providerUsername || spotify.username || "").trim(),
        providerDisplayName: String(spotify.displayName || spotify.providerDisplayName || "").trim(),
        profileUrl: url,
        source: "verified",
        verified: true,
        avatarUrl: normalizePublicConnectionAvatarUrl(SPOTIFY_PROVIDER, spotify.avatarUrl || spotify.avatar_url || ""),
        updatedAt: String(spotify.lastSyncedAt || spotify.updatedAt || "").trim(),
      });
    }
  }
  const youtube = connectedAccounts.youtube && typeof connectedAccounts.youtube === "object" && !Array.isArray(connectedAccounts.youtube) ? connectedAccounts.youtube : null;
  if (youtube) {
    const channelId = String(youtube.channelId || youtube.channel_id || "").trim();
    const showOnProfile = youtube.showOnProfile === true || youtube.show_on_profile === true || youtube.show_on_profile === "true" || youtube.showOnProfile === "true";
    const verified = youtube.verified === true || youtube.verified === "true" || youtube.provider === YOUTUBE_PROVIDER;
    const handle = String(youtube.handle || youtube.customUrl || "").trim();
    const fallbackUrl = handle && /^@[A-Za-z0-9._-]{3,40}$/.test(handle)
      ? "https://www.youtube.com/" + handle
      : (channelId ? "https://www.youtube.com/channel/" + channelId : "");
    const url = normalizeConnectionProfileUrl(youtube.channelUrl || youtube.channel_url || youtube.profileUrl || youtube.profile_url || fallbackUrl, YOUTUBE_PROVIDER);
    if (showOnProfile && verified && channelId && url) {
      out.push({
        provider: YOUTUBE_PROVIDER,
        label: "YouTube",
        displayName: String(youtube.title || youtube.displayName || youtube.providerDisplayName || "YouTube").trim() || "YouTube",
        subtitle: "Verified YouTube channel",
        providerUsername: handle || channelId,
        providerDisplayName: String(youtube.title || youtube.displayName || "").trim(),
        profileUrl: url,
        source: "verified",
        verified: true,
        avatarUrl: normalizePublicConnectionAvatarUrl(YOUTUBE_PROVIDER, youtube.thumbnailUrl || youtube.thumbnail_url || youtube.avatarUrl || youtube.avatar_url || ""),
        updatedAt: String(youtube.lastSyncedAt || youtube.last_synced_at || youtube.linkedAt || "").trim(),
      });
    }
  }
  return normalizePublicConnectedAccounts(out);
}

function getPublicProfileConnectionsForRender(profileInput = null, userIdInput = "") {
  const uid = normId(userIdInput || profileInput?.id || "");
  const cached = uid ? getCachedPublicConnectedAccountsForUser(uid) : [];
  const profileConnections = getPublicProfileConnections(profileInput || {});
  return normalizePublicConnectedAccounts([...cached, ...profileConnections]);
}

function profileHasHiddenPublicConnections(profileInput = null) {
  const profile = profileInput && typeof profileInput === "object" ? profileInput : {};
  const connectedAccounts = profile.connected_accounts && typeof profile.connected_accounts === "object" && !Array.isArray(profile.connected_accounts) ? profile.connected_accounts : {};
  const steam = connectedAccounts.steam && typeof connectedAccounts.steam === "object" && !Array.isArray(connectedAccounts.steam) ? connectedAccounts.steam : null;
  if ((steam?.verified === true || steam?.verified === "true") && /^\d{16,20}$/.test(String(steam.steamid64 || "")) && (steam.showOnProfile === false || steam.showOnProfile === "false" || steam.show_on_profile === false || steam.show_on_profile === "false")) return true;
  const youtube = connectedAccounts.youtube && typeof connectedAccounts.youtube === "object" && !Array.isArray(connectedAccounts.youtube) ? connectedAccounts.youtube : null;
  if ((youtube?.verified === true || youtube?.verified === "true") && String(youtube.channelId || youtube.channel_id || "").trim() && (youtube.showOnProfile === false || youtube.showOnProfile === "false" || youtube.show_on_profile === false || youtube.show_on_profile === "false")) return true;
  const spotifyAccount = getSpotifyConnectedAccount();
  if (normId(profile?.id || "") === normId(state.user?.id || "") && spotifyAccount && spotifyAccount.showOnProfile === false) return true;
  return false;
}

function normalizePublicConnectedAccounts(rows = []) {
  const seen = new Set();
  return (Array.isArray(rows) ? rows : [])
    .map(normalizePublicConnectedAccount)
    .filter(Boolean)
    .filter((account) => {
      const key = [account.provider, account.profileUrl || account.providerUsername || account.displayName || ""].join(":");
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => {
      const labelA = getProfileConnectionProviderConfig(a.provider).label;
      const labelB = getProfileConnectionProviderConfig(b.provider).label;
      return labelA.localeCompare(labelB) || a.provider.localeCompare(b.provider);
    });
}

function getCachedPublicConnectedAccountsForUser(userId = "") {
  const uid = normId(userId || "");
  if (!uid) return [];
  return normalizePublicConnectedAccounts(userCardPublicConnectionsCache.get(uid) || []);
}

async function fetchPublicConnectedAccountsForUser(targetUserId, { force = false, maxAgeMs = 0 } = {}) {
  const uid = normId(targetUserId || "");
  if (!uid) return [];
  const cacheMaxAgeMs = Math.max(0, Number(maxAgeMs || 0) || 0);
  const fetchedAt = Number(userCardPublicConnectionsFetchedAtByUser.get(uid) || 0);
  const cacheFresh = !cacheMaxAgeMs || (!!fetchedAt && (Date.now() - fetchedAt) >= 0 && (Date.now() - fetchedAt) <= cacheMaxAgeMs);
  if (!force && userCardPublicConnectionsCache.has(uid) && cacheFresh) return getCachedPublicConnectedAccountsForUser(uid);
  const collected = [];
  let primaryError = null;
  try {
    const { data, error } = await supabase.rpc("get_public_connected_accounts", { p_user_id: uid });
    if (error) throw error;
    collected.push(...normalizePublicConnectedAccounts(data || []));
  } catch (error) {
    primaryError = error;
  }
  try {
    const { data, error } = await supabase.rpc("get_profile_public_connections", { p_profile_id: uid });
    if (error) throw error;
    collected.push(...normalizePublicConnectedAccounts(Array.isArray(data) ? data : (data ? JSON.parse(JSON.stringify(data)) : [])));
  } catch (error) {
    const msg = String(error?.message || error || "").toLowerCase();
    if (!msg.includes("get_profile_public_connections") && !msg.includes("function") && !msg.includes("schema cache")) {
      try { console.warn("[ProfileConnections] profile public connections RPC failed", error?.message || error); } catch (_) {}
    }
  }
  if (uid === normId(state.user?.id || "")) collected.push(...getPublicProfileConnections(getCurrentMeProfileSnapshot()));
  const rows = normalizePublicConnectedAccounts(collected);
  userCardPublicConnectionsCache.set(uid, rows);
  userCardPublicConnectionsFetchedAtByUser.set(uid, Date.now());
  if (!rows.length && primaryError) throw primaryError;
  return getCachedPublicConnectedAccountsForUser(uid);
}

function getSafeProfileConnectionUsername(value = "", pattern = /^[a-z0-9_.-]{1,80}$/i) {
  const raw = String(value || "").trim().replace(/^@+/, "");
  if (!raw || raw.length > 120 || !pattern.test(raw)) return "";
  return raw;
}

function validatePublicConnectionExternalUrl(providerInput = "", urlInput = "") {
  const provider = normalizePublicConnectionProvider(providerInput || "");
  const safeUrl = normalizeConnectionProfileUrl(urlInput || "", provider);
  if (!safeUrl) return "";
  if (provider === STEAM_PROVIDER) return (safeUrl.startsWith("https://steamcommunity.com/profiles/") || safeUrl.startsWith("https://steamcommunity.com/id/")) ? safeUrl : "";
  if (provider === SPOTIFY_PROVIDER) return safeUrl.startsWith("https://open.spotify.com/") ? safeUrl : "";
  return safeUrl;
}

async function openPublicProfileConnectionExternalUrl(providerInput = "", urlInput = "") {
  const provider = normalizePublicConnectionProvider(providerInput || "");
  const safeUrl = validatePublicConnectionExternalUrl(provider, urlInput);
  if (!safeUrl) return false;
  const bridge = getDesktopBridge();
  if (bridge && typeof bridge.openExternal === "function") {
    try {
      const result = await bridge.openExternal(safeUrl);
      return result !== false;
    } catch (_) {
      return false;
    }
  }
  try {
    const opened = window.open(safeUrl, "_blank", "noopener,noreferrer");
    if (opened) {
      try { opened.opener = null; } catch (_) {}
      return true;
    }
  } catch (_) {}
  return false;
}

function bindProfileConnectionLinkDelegationOnce() {
  if (profileConnectionLinkDelegationBound) return;
  profileConnectionLinkDelegationBound = true;
  document.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    const link = target?.closest?.("[data-profile-connection-url]");
    if (!link) return;
    const provider = link.getAttribute("data-provider") || "";
    const url = link.getAttribute("data-profile-connection-url") || link.getAttribute("href") || "";
    const safeUrl = validatePublicConnectionExternalUrl(provider, url);
    if (!safeUrl) return;
    event.preventDefault();
    event.stopPropagation();
    void openPublicProfileConnectionExternalUrl(provider, safeUrl);
  }, true);
}

function buildProfileConnectionExternalUrl(account = null) {
  if (!account || typeof account !== "object") return "";
  const provider = normalizePublicConnectionProvider(account.provider || "");
  const explicitUrl = validatePublicConnectionExternalUrl(provider, account.profileUrl || account.profile_url || account.url || "");
  if (explicitUrl) return explicitUrl;
  const username = getHumanReadableConnectionUsername(account);
  if (!provider || !username) return "";
  if (provider === "github") {
    const safe = getSafeProfileConnectionUsername(username, /^[a-z0-9](?:[a-z0-9-]{0,37}[a-z0-9])?$/i);
    return safe ? "https://github.com/" + encodeURIComponent(safe) : "";
  }
  if (provider === "twitch") {
    const safe = getSafeProfileConnectionUsername(username, /^[a-z0-9_]{3,25}$/i);
    return safe ? "https://www.twitch.tv/" + encodeURIComponent(safe) : "";
  }
  if (provider === "tiktok") {
    const safe = getSafeProfileConnectionUsername(username, /^[a-z0-9._]{2,24}$/i);
    return safe ? "https://www.tiktok.com/@" + encodeURIComponent(safe) : "";
  }
  if (provider === "steam") {
    const safe = getSafeProfileConnectionUsername(username, /^[a-z0-9_-]{2,32}$/i);
    return /^\d{16,20}$/.test(safe) ? "https://steamcommunity.com/profiles/" + encodeURIComponent(safe) : "";
  }
  if (provider === "youtube") {
    const safe = getSafeProfileConnectionUsername(username, /^[a-z0-9._-]{3,40}$/i);
    return safe ? "https://www.youtube.com/@" + encodeURIComponent(safe) : "";
  }
  if (provider === "spotify") {
    const safe = getSafeProfileConnectionUsername(username, /^[a-z0-9._-]{2,120}$/i);
    return safe ? "https://open.spotify.com/user/" + encodeURIComponent(safe) : "";
  }
  return "";
}

function buildProfileConnectionRowHtml(account = null) {
  const normalized = normalizePublicConnectedAccount(account);
  if (!normalized) return "";
  const config = getProfileConnectionProviderConfig(normalized.provider);
  const title = getProfileConnectionDisplayTitle(normalized);
  const humanUsername = getHumanReadableConnectionUsername(normalized);
  const subtitleParts = [config.label, humanUsername && humanUsername !== title && humanUsername.length <= 32 ? humanUsername : ""].filter(Boolean);
  const subtitle = subtitleParts.join(" - ");
  const externalUrl = buildProfileConnectionExternalUrl(normalized);
  const tag = externalUrl ? "a" : "div";
  const verifiedHtml = normalized.verified ? '<span class="profile-connection-verified" title="Verified" aria-label="Verified">&#10003;</span>' : '';
  const linkAttrs = externalUrl ? ' href="' + escAttr(externalUrl) + '" target="_blank" rel="noopener noreferrer" data-profile-connection-url="' + escAttr(externalUrl) + '" aria-label="Open ' + escAttr(config.label) + ' profile"' : "";
  const avatarHtml = normalized.avatarUrl ? '<img class="profile-connection-avatar" src="' + escAttr(normalized.avatarUrl) + '" alt="" loading="lazy" referrerpolicy="no-referrer" />' : buildProfileConnectionIconHtml(normalized.provider);
  bindProfileConnectionLinkDelegationOnce();
  return '<' + tag + ' class="profile-connection-row' + (externalUrl ? ' is-link' : '') + '" data-provider="' + escAttr(normalized.provider) + '"' + linkAttrs + '>' +
    '<span class="profile-connection-icon" data-provider="' + escAttr(normalized.provider) + '">' + avatarHtml + '</span>' +
    '<span class="profile-connection-body">' +
      '<span class="profile-connection-title" title="' + escAttr(title) + '">' + esc(title) + verifiedHtml + '</span>' +
      '<span class="profile-connection-subtitle">' + esc(normalized.subtitle || subtitle || config.label) + '</span>' +
    '</span>' +
    (externalUrl ? '<span class="profile-connection-link" aria-hidden="true">&#8599;</span>' : '') +
  '</' + tag + '>';
}

function buildUserCardPublicConnectionsSectionHtml(accounts = [], { loading = false, error = "", isSelf = false, profile = null, title = "Connections" } = {}) {
  const normalizedAccounts = normalizePublicConnectedAccounts(accounts || []);
  if (loading && !normalizedAccounts.length) {
    return '<div class="userCardSharedCard profile-connections-card">' +
      '<div class="userCardSharedTitle">' + esc(title || "Connections") + '</div>' +
      '<div class="profile-connections-list" aria-busy="true">' +
        '<div class="profile-connection-row is-loading"><span class="profile-connection-icon"></span><span class="profile-connection-body"><span class="profile-connection-title">Loading connections...</span><span class="profile-connection-subtitle">Checking public accounts</span></span></div>' +
      '</div>' +
    '</div>';
  }
  if (error && !normalizedAccounts.length) return "";
  if (!normalizedAccounts.length) {
    if (isSelf && profileHasHiddenPublicConnections(profile)) {
      return '<div class="userCardSharedCard profile-connections-card profile-connections-card--hint"><div class="userCardSharedTitle">' + esc(title || "Connections") + '</div><div class="userCardSharedText">Connections are hidden from your profile.</div></div>';
    }
    return "";
  }
  return '<div class="userCardSharedCard profile-connections-card">' +
    '<div class="userCardSharedTitle">' + esc(title || "Connections") + '</div>' +
    '<div class="profile-connections-list">' + normalizedAccounts.map(buildProfileConnectionRowHtml).join("") + '</div>' +
  '</div>';
}

function buildProfileConnectionsCompactSectionHtml(profile = {}, { userId = "", isSelf = false, loading = false, title = "Connections" } = {}) {
  const connections = getPublicProfileConnectionsForRender(profile || {}, userId || profile?.id || "");
  if (!connections.length && loading) return "";
  if (!connections.length) {
    return isSelf && profileHasHiddenPublicConnections(profile)
      ? '<section class="profile-connections-compact profile-connections-compact--hint"><div class="profile-connections-compact__title">' + esc(title) + '</div><div class="profile-connections-hint">Connections are hidden from your profile.</div></section>'
      : "";
  }
  return '<section class="profile-connections-compact"><div class="profile-connections-compact__title">' + esc(title) + '</div><div class="profile-connections-list">' + connections.map(buildProfileConnectionRowHtml).join("") + '</div></section>';
}

function renderUserCardOverviewConnections(profile = {}, { isSelf = false, loading = false } = {}) {
  const bioEl = document.getElementById("userCardBio");
  if (!bioEl) return;
  const factsEl = document.getElementById("userCardFacts");
  let section = document.getElementById("userCardProfileConnections");
  const html = buildProfileConnectionsCompactSectionHtml(profile, { userId: profile?.id || userCardCurrentUserId || "", isSelf, loading, title: "Connections" });
  if (!html) {
    section?.remove?.();
    return;
  }
  if (!section) {
    section = document.createElement("div");
    section.id = "userCardProfileConnections";
  }
  const spotifyActivityCard = factsEl?.querySelector?.('[data-spotify-profile-activity="1"]') || null;
  if (spotifyActivityCard) {
    spotifyActivityCard.insertAdjacentElement("afterend", section);
  } else {
    bioEl.insertAdjacentElement("afterend", section);
  }
  setElementHtmlIfChanged(section, html);
}
function buildUserCardSharedPanelHtml(profile = {}, insights = {}, { relation = null, context = null, publicConnections = [], connectionsLoading = false, connectionsError = "" } = {}) {
  const sharedServers = Array.isArray(insights?.sharedServers) ? insights.sharedServers : [];
  const sharedGroups = Array.isArray(insights?.sharedGroups) ? insights.sharedGroups : [];
  const currentServerMembership = insights?.currentServerMembership || null;
  const chipHtml = [];
  if (relation?.label) chipHtml.push(`<span class="userCardChip">${esc(relation.label)}</span>`);
  if (currentServerMembership?.role) chipHtml.push(`<span class="userCardChip">${esc(currentServerMembership.role)}</span>`);
  if (currentServerMembership?.joinedAt) chipHtml.push(`<span class="userCardChip">aqui desde ${esc(formatUserCardDate(new Date(currentServerMembership.joinedAt).toISOString()))}</span>`);

  const cards = [];
  const isSelfProfile = normId(profile?.id || "") === normId(state.user?.id || "");
  const publicConnectionsForPanel = normalizePublicConnectedAccounts([...(publicConnections || []), ...getPublicProfileConnections(profile)]);
  const publicConnectionsHtml = buildUserCardPublicConnectionsSectionHtml(publicConnectionsForPanel, {
    loading: connectionsLoading,
    error: connectionsError,
    isSelf: isSelfProfile,
    profile,
    title: "Connections",
  });

  if (chipHtml.length) {
    cards.push(`
      <div class="userCardSharedCard">
        <div class="userCardSharedTitle">Resumo rapido</div>
        <div class="userCardChipRow">${chipHtml.join("")}</div>
      </div>
    `);
  }

  if (sharedServers.length) {
    cards.push(`
      <div class="userCardSharedCard">
        <div class="userCardSharedTitle">Servers em comum carregados</div>
        <div class="userCardServerList">
          ${sharedServers.map((server) => {
            const name = String(server?.name || "Server").trim();
            const iconUrl = String(server?.iconUrl || "").trim();
            const initial = name.charAt(0).toUpperCase() || "S";
            const sub = [
              server?.isCurrent ? t("usercard.current_server", "current server") : t("usercard.recently_loaded", "recently loaded"),
              server?.memberCount ? (server.memberCount === 1 ? t("dm.group_member_count_one", "1 member") : t("dm.group_member_count", "{n} members").replace("{n}", server.memberCount)) : "",
            ].filter(Boolean).join(" • ");
            return `
              <div class="userCardServerItem">
                <div class="userCardServerOrb">
                  ${iconUrl ? lazyMediaImageHtml(iconUrl, { alt: name }) : `<span>${esc(initial)}</span>`}
                </div>
                <div class="userCardServerMeta">
                  <div class="userCardServerName">${esc(name)}</div>
                  <div class="userCardServerSub">${esc(sub || "server partilhado")}</div>
                </div>
              </div>
            `;
          }).join("")}
        </div>
      </div>
    `);
  }

  if (sharedGroups.length) {
    cards.push(`
      <div class="userCardSharedCard">
        <div class="userCardSharedTitle">Grupos em comum</div>
        <div class="userCardChipRow">
          ${sharedGroups.map((group) => `<span class="userCardChip">${esc(group?.name || "Group DM")}</span>`).join("")}
        </div>
      </div>
    `);
  }

  const publicConnectionCount = publicConnectionsForPanel.length;
  const hasContextCards = cards.length > 0;
  const panelTitle = publicConnectionCount || connectionsLoading || connectionsError
    ? "Connections"
    : (hasContextCards ? "Shared context" : "Profile details");
  const panelText = publicConnectionCount
    ? "External accounts this person chose to show on their profile."
    : (hasContextCards ? "Shared servers, groups, and public context." : "Nothing shared here yet.");

  return `
    <div class="userCardPanelIntro">
      <div class="userCardPanelEyebrow">Ligacoes</div>
      <div class="userCardPanelTitle">${esc(panelTitle)}</div>
      <div class="userCardPanelText">${esc(panelText)}</div>
    </div>
    <div class="userCardSharedStack">${publicConnectionsHtml}${cards.join("")}${(!publicConnectionsHtml && !cards.length && !connectionsLoading) ? '<div class="userCardEmptyState"><strong>Nothing shared here yet.</strong><span>Public connections and shared context can appear here.</span></div>' : ''}</div>
  `;
}

function isProfileWidgetsDebugEnabled() {
  try {
    if (typeof window !== "undefined" && window.__ALTARA_WIDGETS_DEBUG_LOGS__ === true) return true;
    if (typeof localStorage === "undefined") return false;
    return localStorage.getItem("altara.debug.profile_widgets") === "1"
      || localStorage.getItem("altara.debug.widgets") === "1";
  } catch (_) {
    return false;
  }
}

function logProfileWidgetsDebug(event = "", details = {}) {
  if (!isProfileWidgetsDebugEnabled()) return;
  try { console.debug("[Widgets] " + String(event || "event"), details && typeof details === "object" ? details : {}); } catch (_) {}
}

function normalizeProfileWidgetDefKey(value = "") {
  const raw = String(value || "").trim().toLowerCase().replace(/[^a-z0-9_ -]/g, "").replace(/[ -]+/g, "_");
  const aliased = PROFILE_WIDGET_TYPE_ALIASES[raw] || raw;
  return PROFILE_WIDGET_DEFS[aliased] ? aliased : "custom";
}

function getProfileWidgetDef(typeInput = "") {
  return PROFILE_WIDGET_DEFS[normalizeProfileWidgetDefKey(typeInput)] || PROFILE_WIDGET_DEFS.custom;
}

function getProfileWidgetAllowedSizes(typeInput = "") {
  const def = getProfileWidgetDef(typeInput);
  return Array.isArray(def?.allowedSizes) ? def.allowedSizes.slice() : ["medium"];
}

function getProfileWidgetDefaultSize(typeInput = "") {
  const fallback = String(getProfileWidgetDef(typeInput)?.defaultSize || "medium").trim().toLowerCase();
  return PROFILE_WIDGET_SIZES.includes(fallback) ? fallback : "medium";
}

function normalizeProfileWidgetSize(sizeInput = "", typeInput = "") {
  const raw = String(sizeInput || "").trim().toLowerCase();
  const allowed = getProfileWidgetAllowedSizes(typeInput);
  if (PROFILE_WIDGET_SIZES.includes(raw) && allowed.includes(raw)) return raw;
  const defaultSize = getProfileWidgetDefaultSize(typeInput);
  return allowed.includes(defaultSize) ? defaultSize : (allowed[0] || "medium");
}

function normalizeProfileWidgetConfig(input = {}) {
  return input && typeof input === "object" && !Array.isArray(input) ? { ...input } : {};
}

function getProfileWidgetConfigFromRow(row = {}) {
  return normalizeProfileWidgetConfig(row?.config || row?.widget_config || row?.layout_config || {});
}

function getProfileWidgetSizeFromRow(row = {}, widgetTypeInput = "") {
  const config = getProfileWidgetConfigFromRow(row);
  return normalizeProfileWidgetSize(row?.size || row?.widget_size || row?.widgetSize || config.size || "medium", widgetTypeInput || row?.widget_type || row?.type || "custom");
}
function normalizeProfileWidgetType(value = "") {
  const raw = String(value || "").trim().toLowerCase().replace(/[^a-z0-9_ -]/g, "").replace(/[ -]+/g, "_");
  if (!raw) return "custom";
  const aliased = PROFILE_WIDGET_TYPE_ALIASES[raw] || raw;
  if (PROFILE_WIDGET_TYPES.includes(aliased)) return aliased;
  if (PROFILE_WIDGET_DASHBOARD_ONLY_TYPES.includes(aliased)) return "";
  return "custom";
}

function isProfileContentWidgetType(typeInput = "") {
  return PROFILE_WIDGET_TYPES.includes(normalizeProfileWidgetType(typeInput || ""));
}

function isDashboardOnlyProfileWidgetType(typeInput = "") {
  const raw = String(typeInput || "").trim().toLowerCase().replace(/[^a-z0-9_ -]/g, "").replace(/[ -]+/g, "_");
  if (!raw) return false;
  const type = PROFILE_WIDGET_TYPE_ALIASES[raw] || raw;
  return !PROFILE_WIDGET_TYPES.includes(type);
}

function normalizeProfileWidgetCreateType(value = "") {
  const type = normalizeProfileWidgetType(value);
  return PROFILE_WIDGET_CREATE_TYPES.includes(type) ? type : "games";
}

function normalizeProfileWidgetStatus(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  return PROFILE_WIDGET_STATUSES.includes(raw) ? raw : "favorite";
}

function normalizeProfileWidgetVisibility(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  return PROFILE_WIDGET_VISIBILITY.includes(raw) ? raw : "public";
}

function normalizeProfileWidgetNote(value = "") {
  const raw = String(value ?? "");
  return raw.length > PROFILE_WIDGET_LIMITS.noteMax
    ? raw.slice(0, PROFILE_WIDGET_LIMITS.noteMax)
    : raw;
}

function normalizeProfileWidgetTitle(value = "") {
  const raw = String(value || "").trim();
  return raw.slice(0, PROFILE_WIDGET_LIMITS.titleMax);
}

function normalizeProfileWidgetTags(input = []) {
  const arr = Array.isArray(input) ? input : [];
  const out = [];
  arr.forEach((entry) => {
    if (out.length >= PROFILE_WIDGET_LIMITS.tagsMax) return;
    const tag = String(entry || "").trim();
    if (!tag) return;
    if (tag.length > PROFILE_WIDGET_LIMITS.tagLenMax) return;
    out.push(tag);
  });
  return out;
}

function parseProfileWidgetTagsInput(input = "") {
  const raw = String(input || "");
  if (!raw) return [];
  return normalizeProfileWidgetTags(
    raw.split(",").map((part) => String(part || "").trim())
  );
}

function normalizeCatalogType(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  return PROFILE_WIDGET_CATALOG_ALLOWED_TYPES.includes(raw) ? raw : "custom";
}

function catalogTypeFromWidgetType(widgetTypeInput = "") {
  const widgetType = normalizeProfileWidgetType(widgetTypeInput);
  if (widgetType === "spotify" || widgetType === "current_activity") return "music";
  return PROFILE_WIDGET_TO_CATALOG_TYPE[widgetType] || "custom";
}

function normalizeCatalogSource(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  if (!raw) return "local";
  if (["rawg", "tmdb", "tvmaze", "omdb", "deezer", "spotify", "apple_music", "anilist", "local", "mock"].includes(raw)) return raw;
  return "local";
}

function normalizeProfileWidgetItemMetadata(input = {}) {
  const src = input && typeof input === "object" && !Array.isArray(input)
    ? input
    : {};
  const out = {};

  const sourceRaw = String(src.source || src.catalog_source || "").trim().toLowerCase();
  const source = sourceRaw && ["rawg", "tmdb", "tvmaze", "omdb", "deezer", "spotify", "apple_music", "anilist", "local", "mock"].includes(sourceRaw)
    ? sourceRaw
    : "";
  const sourceId = String(src.source_id || src.catalog_source_id || "").trim().slice(0, 80);
  const catalogTypeRaw = String(src.catalog_type || src.type || "").trim().toLowerCase();
  const catalogType = catalogTypeRaw && PROFILE_WIDGET_CATALOG_ALLOWED_TYPES.includes(catalogTypeRaw)
    ? catalogTypeRaw
    : "";

  if (source) out.source = source;
  if (sourceId) out.source_id = sourceId;
  if (catalogType) out.catalog_type = catalogType;

  const platforms = Array.isArray(src.platforms)
    ? src.platforms
      .map((entry) => String(entry || "").trim())
      .filter(Boolean)
      .slice(0, 12)
    : [];
  const genres = Array.isArray(src.genres)
    ? src.genres
      .map((entry) => String(entry || "").trim())
      .filter(Boolean)
      .slice(0, 12)
    : [];
  if (platforms.length) out.platforms = platforms;
  if (genres.length) out.genres = genres;

  const release = String(src.released || "").trim().slice(0, 32);
  if (release) out.released = release;
  const slug = String(src.slug || "").trim().slice(0, 120);
  if (slug) out.slug = slug;

  const releaseYearRaw = Number(src.release_year);
  if (Number.isFinite(releaseYearRaw) && releaseYearRaw >= 1900 && releaseYearRaw <= 2100) {
    out.release_year = Math.round(releaseYearRaw);
  }

  const rating = Number(src.rating);
  if (Number.isFinite(rating)) out.rating = Math.max(0, Math.min(5, Number(rating.toFixed(2))));
  const rawgRating = Number(src.rawg_rating);
  if (Number.isFinite(rawgRating)) out.rawg_rating = Math.max(0, Math.min(5, Number(rawgRating.toFixed(2))));

  const imdbId = String(src.imdb || src.imdb_id || "").trim().slice(0, 32);
  if (imdbId) out.imdb = imdbId;
  const omdbType = String(src.omdb_type || "").trim().toLowerCase();
  if (omdbType === "movie" || omdbType === "series" || omdbType === "episode") out.omdb_type = omdbType;
  const yearText = String(src.year_text || "").trim().slice(0, 24);
  if (yearText) out.year_text = yearText;
  const anilistFormat = String(src.anilist_format || "").trim().slice(0, 32);
  if (anilistFormat) out.anilist_format = anilistFormat;
  const anilistStatus = String(src.anilist_status || "").trim().slice(0, 32);
  if (anilistStatus) out.anilist_status = anilistStatus;
  const averageScore = Number(src.average_score);
  if (Number.isFinite(averageScore)) out.average_score = Math.max(0, Math.min(100, Math.round(averageScore)));
  const trackTitle = String(src.track_title || "").trim().slice(0, 120);
  if (trackTitle) out.track_title = trackTitle;
  const artistName = String(src.artist || src.artist_name || "").trim().slice(0, 120);
  if (artistName) out.artist = artistName;
  const artistId = String(src.artist_id || "").trim().slice(0, 40);
  if (artistId) out.artist_id = artistId;
  const artistUrl = normalizeCatalogExternalUrl(src.artist_url || "");
  if (artistUrl) out.artist_url = artistUrl;
  const albumTitle = String(src.album || src.album_title || "").trim().slice(0, 120);
  if (albumTitle) out.album = albumTitle;
  const albumId = String(src.album_id || "").trim().slice(0, 40);
  if (albumId) out.album_id = albumId;
  const previewUrl = normalizeCatalogExternalUrl(src.preview_url || src.preview || "");
  if (previewUrl) out.preview_url = previewUrl;
  const durationSeconds = Number(src.duration_seconds ?? src.duration);
  if (Number.isFinite(durationSeconds) && durationSeconds > 0) out.duration_seconds = clampInt(durationSeconds, 1, 36000, 1);
  const deezerRank = Number(src.deezer_rank ?? src.rank);
  if (Number.isFinite(deezerRank) && deezerRank > 0) out.deezer_rank = Math.min(Math.round(deezerRank), 1000000000);

  return out;
}

function normalizeCatalogCoverUrl(value = "") {
  const safe = normalizeBannerUrl(value || "");
  if (!safe) return "";
  const lower = safe.toLowerCase();
  if (lower.startsWith("data:")) return "";
  return safe;
}

function getProfileWidgetArtworkUrl(source = null) {
  const raw = source && typeof source === "object" ? source : {};
  const meta = raw.metadata && typeof raw.metadata === "object" && !Array.isArray(raw.metadata)
    ? raw.metadata
    : {};
  const candidates = [
    raw.cover_url,
    raw.coverUrl,
    raw.cover,
    raw.image_url,
    raw.imageUrl,
    raw.image,
    raw.background_image,
    raw.backgroundImage,
    raw.background,
    raw.thumbnail_url,
    raw.thumbnailUrl,
    raw.thumbnail,
    raw.media_url,
    raw.mediaUrl,
    meta.cover_url,
    meta.coverUrl,
    meta.cover,
    meta.image_url,
    meta.imageUrl,
    meta.image,
    meta.background_image,
    meta.backgroundImage,
    meta.background,
    meta.thumbnail_url,
    meta.thumbnailUrl,
    meta.thumbnail,
    meta.media_url,
    meta.mediaUrl,
    meta.album_cover,
    meta.album_cover_url,
  ];
  for (const candidate of candidates) {
    const safe = normalizeCatalogCoverUrl(candidate || "");
    if (safe) return safe;
  }
  return "";
}

function normalizeCatalogExternalUrl(value = "") {
  const safe = normalizeBannerUrl(value || "");
  if (!safe) return "";
  const lower = safe.toLowerCase();
  if (lower.startsWith("data:")) return "";
  return safe;
}

function normalizeCatalogSearchResultRow(row = {}) {
  const title = normalizeProfileWidgetTitle(row?.title || "");
  const sourceId = String(row?.source_id || "").trim();
  if (!title) return null;
  if (!sourceId) return null;
  const releaseYearRaw = Number(row?.release_year);
  const releaseYear = Number.isFinite(releaseYearRaw) && releaseYearRaw >= 1900 && releaseYearRaw <= 2100
    ? Math.round(releaseYearRaw)
    : null;
  return {
    source: normalizeCatalogSource(row?.source || ""),
    source_id: sourceId,
    type: normalizeCatalogType(row?.type || ""),
    title,
    cover_url: normalizeCatalogCoverUrl(row?.cover_url || ""),
    release_year: releaseYear,
    external_url: normalizeCatalogExternalUrl(row?.external_url || ""),
    metadata: normalizeProfileWidgetItemMetadata(row?.metadata || {}),
    result_origin: String(row?.result_origin || "").trim().toLowerCase() === "external" ? "external" : "local",
  };
}

function getCatalogSourceLabel(sourceInput = "") {
  const source = normalizeCatalogSource(sourceInput);
  if (source === "mock") return "MOCK";
  if (source === "rawg") return "RAWG";
  if (source === "tmdb") return "TMDB";
  if (source === "omdb") return "OMDb";
  if (source === "tvmaze") return "TVMaze";
  if (source === "deezer") return "Deezer";
  if (source === "spotify") return "Spotify";
  if (source === "apple_music") return "Apple Music";
  if (source === "anilist") return "AniList";
  return "Local";
}

function normalizeProfileWidgetItemRow(row = {}) {
  const ratingRaw = row?.rating;
  const rating = Number.isFinite(Number(ratingRaw))
    ? clampInt(ratingRaw, 1, 5, 1)
    : null;
  const artworkUrl = getProfileWidgetArtworkUrl(row);
  return {
    id: normId(row?.id || ""),
    widget_id: normId(row?.widget_id || ""),
    user_id: normId(row?.user_id || ""),
    title: normalizeProfileWidgetTitle(row?.title || ""),
    cover_url: artworkUrl,
    coverUrl: artworkUrl,
    imageUrl: normalizeCatalogCoverUrl(row?.image_url || row?.imageUrl || row?.image || "") || artworkUrl,
    backgroundImage: normalizeCatalogCoverUrl(row?.background_image || row?.backgroundImage || row?.background || "") || artworkUrl,
    thumbnailUrl: normalizeCatalogCoverUrl(row?.thumbnail_url || row?.thumbnailUrl || row?.thumbnail || "") || artworkUrl,
    external_url: normalizeCatalogExternalUrl(row?.external_url || row?.externalUrl || ""),
    status: normalizeProfileWidgetStatus(row?.status || ""),
    rating,
    note: normalizeProfileWidgetNote(row?.note || ""),
    tags: normalizeProfileWidgetTags(row?.tags || []),
    mood: String(row?.mood || "").trim(),
    visibility: normalizeProfileWidgetVisibility(row?.visibility || (row?.is_public === false ? "private" : "public")),
    is_public: row?.is_public === false ? false : true,
    hidden: row?.hidden === true || row?.is_hidden === true || row?.is_enabled === false,
    is_featured: !!row?.is_featured,
    position: clampInt(row?.position, 0, 9999, 0),
    metadata: normalizeProfileWidgetItemMetadata(row?.metadata || {}),
    created_at: String(row?.created_at || "").trim(),
    updated_at: String(row?.updated_at || "").trim(),
  };
}

function normalizeProfileWidgetRow(row = {}) {
  const itemsRaw = Array.isArray(row?.items) ? row.items : [];
  const items = itemsRaw
    .map((item) => normalizeProfileWidgetItemRow(item))
    .filter((item) => !!item.id && !!item.title)
    .sort((a, b) => (
      Number(a.position || 0) - Number(b.position || 0)
      || (Date.parse(a.created_at || 0) || 0) - (Date.parse(b.created_at || 0) || 0)
    ));
  const widgetType = normalizeProfileWidgetType(row?.widget_type || row?.type || "");
  const position = clampInt(
    typeof row?.position !== "undefined" ? row.position : row?.widget_position,
    0,
    9999,
    0
  );
  let config = getProfileWidgetConfigFromRow(row);
  if (widgetType === "timer") config = normalizeProfileTimerWidgetConfig(config);
  const size = getProfileWidgetSizeFromRow({ ...row, config }, widgetType);
  const createdAt = String(row?.created_at || row?.createdAt || "").trim();
  const updatedAt = String(row?.updated_at || row?.updatedAt || "").trim();

  return {
    id: normId(row?.id || ""),
    user_id: normId(row?.user_id || row?.userId || ""),
    widget_type: widgetType,
    type: widgetType,
    size,
    order: position,
    position,
    config,
    title: normalizeProfileWidgetTitle(row?.title || ""),
    is_enabled: row?.is_enabled !== false,
    visibility: normalizeProfileWidgetVisibility(row?.visibility || (row?.is_public === false ? "private" : "public")),
    is_public: row?.is_public === false ? false : true,
    hidden: row?.hidden === true || row?.is_hidden === true,
    created_at: createdAt,
    createdAt,
    updated_at: updatedAt,
    updatedAt,
    items,
  };
}

function cloneProfileWidgetsList(list = []) {
  return (Array.isArray(list) ? list : []).map((widget) => {
    const widgetType = normalizeProfileWidgetType(widget?.widget_type || widget?.type || "");
    const position = clampInt(typeof widget?.position !== "undefined" ? widget.position : widget?.order, 0, 9999, 0);
    const size = normalizeProfileWidgetSize(widget?.size || widget?.config?.size || "medium", widgetType);
    return {
    ...widget,
    widget_type: widgetType,
    type: widgetType,
    size,
    order: position,
    position,
    config: widgetType === "timer" ? normalizeProfileTimerWidgetConfig(widget?.config || {}) : normalizeProfileWidgetConfig(widget?.config || {}),
    items: Array.isArray(widget?.items)
      ? widget.items.map((item) => ({
        ...item,
        tags: Array.isArray(item?.tags) ? item.tags.slice() : [],
        metadata: normalizeProfileWidgetItemMetadata(item?.metadata || {}),
        coverUrl: normalizeCatalogCoverUrl(item?.coverUrl || item?.cover_url || ""),
        imageUrl: normalizeCatalogCoverUrl(item?.imageUrl || item?.image_url || item?.image || ""),
        backgroundImage: normalizeCatalogCoverUrl(item?.backgroundImage || item?.background_image || item?.background || ""),
        thumbnailUrl: normalizeCatalogCoverUrl(item?.thumbnailUrl || item?.thumbnail_url || item?.thumbnail || ""),
      }))
      : [],
  };
  });
}

function getCachedProfileWidgetsForUser(userId) {
  const uid = normId(userId || "");
  if (!uid) return [];
  return cloneProfileWidgetsList(userCardWidgetsCache.get(uid) || []);
}

function getProfileWidgetTypeLabel(typeInput = "") {
  const type = normalizeProfileWidgetType(typeInput);
  if (type === "games") return t("profile.widgets.type.games", "Games");
  if (type === "movies") return t("profile.widgets.type.movies", "Movies");
  if (type === "series") return t("profile.widgets.type.series", "Series");
  if (type === "music") return t("profile.widgets.type.music", "Music");
  if (type === "anime") return t("profile.widgets.type.anime", "Anime");
  if (type === "timer") return t("profile.widgets.type.timer", "Timer");
  const def = getProfileWidgetDef(type);
  return def?.label || t("profile.widgets.type.custom", "Custom");
}

function getProfileWidgetCatalogTypeLabel(catalogTypeInput = "") {
  const catalogType = normalizeCatalogType(catalogTypeInput || "custom");
  if (catalogType === "game") return t("profile.widgets.type.games", "Games");
  if (catalogType === "movie") return t("profile.widgets.type.movies", "Movies");
  if (catalogType === "series") return t("profile.widgets.type.series", "Series");
  if (catalogType === "music") return t("profile.widgets.type.music", "Music");
  if (catalogType === "anime") return t("profile.widgets.type.anime", "Anime");
  return t("profile.widgets.type.custom", "Custom");
}

function getProfileWidgetAddItemButtonLabel(widgetTypeInput = "") {
  const widgetType = normalizeProfileWidgetType(widgetTypeInput || "");
  if (widgetType === "games") return t("profile.widgets.add_game", "Add game");
  if (widgetType === "movies") return t("profile.widgets.add_movie", "Add movie");
  if (widgetType === "series") return t("profile.widgets.add_series", "Add series");
  if (widgetType === "music") return t("profile.widgets.add_music", "Add music");
  if (widgetType === "anime") return t("profile.widgets.add_anime", "Add anime");
  if (widgetType === "timer") return t("widget.timer.settings", "Timer settings");
  return t("profile.widgets.add_item", "Add item");
}

function isProfileWidgetItemBackedType(typeInput = "") {
  return !PROFILE_WIDGET_NON_ITEM_TYPES.includes(normalizeProfileWidgetType(typeInput || ""));
}

function getProfileWidgetStatusLabel(statusInput = "") {
  const status = normalizeProfileWidgetStatus(statusInput);
  if (status === "current") return t("profile.widgets.status.current", "Currently");
  if (status === "wishlist") return t("profile.widgets.status.wishlist", "Want to");
  if (status === "completed") return t("profile.widgets.status.completed", "Completed");
  if (status === "dropped") return t("profile.widgets.status.dropped", "Dropped");
  return t("profile.widgets.status.favorite", "Favorite");
}

function getProfileWidgetVisibilityLabel(visibilityInput = "") {
  const visibility = normalizeProfileWidgetVisibility(visibilityInput);
  if (visibility === "friends") return t("profile.widgets.visibility.friends", "Friends");
  if (visibility === "private") return t("profile.widgets.visibility.private", "Private");
  return t("profile.widgets.visibility.public", "Public");
}


function clampProfileTimerMinutes(valueInput, fallback = 20) {
  return clampInt(valueInput, 1, 180, fallback);
}

function normalizeProfileTimerConfig(input = {}) {
  const src = input && typeof input === "object" && !Array.isArray(input) ? input : {};
  const presetRaw = String(src.preset || PROFILE_TIMER_DEFAULT_CONFIG.preset).trim().toLowerCase();
  const preset = Object.prototype.hasOwnProperty.call(PROFILE_TIMER_PRESETS, presetRaw) ? presetRaw : "study_20_5";
  const presetDef = PROFILE_TIMER_PRESETS[preset] || PROFILE_TIMER_PRESETS.study_20_5;
  const modeRaw = String(src.mode || presetDef.mode || PROFILE_TIMER_DEFAULT_CONFIG.mode).trim().toLowerCase();
  const mode = modeRaw === "basic" ? "basic" : "study";
  return {
    mode,
    preset,
    durationMinutes: clampProfileTimerMinutes(src.durationMinutes ?? src.timerMinutes ?? src.minutes, mode === "basic" ? 20 : presetDef.workMinutes),
    workMinutes: clampProfileTimerMinutes(src.workMinutes, preset === "custom" ? PROFILE_TIMER_DEFAULT_CONFIG.workMinutes : presetDef.workMinutes),
    breakMinutes: clampInt(src.breakMinutes, 1, 60, preset === "custom" ? PROFILE_TIMER_DEFAULT_CONFIG.breakMinutes : presetDef.breakMinutes),
    rounds: clampInt(src.rounds, 0, 12, PROFILE_TIMER_DEFAULT_CONFIG.rounds),
    autoStartBreak: src.autoStartBreak === true,
    autoStartNextWork: src.autoStartNextWork === true,
    soundEnabled: src.soundEnabled !== false,
    focusIntegrationEnabled: false,
  };
}

function normalizeProfileTimerWidgetConfig(configInput = {}) {
  const config = normalizeProfileWidgetConfig(configInput || {});
  return {
    ...config,
    timer: normalizeProfileTimerConfig(config.timer || config.profileTimer || {}),
  };
}

function getProfileTimerConfig(widget = {}) {
  const config = normalizeProfileWidgetConfig(widget?.config || {});
  return normalizeProfileTimerConfig(config.timer || {});
}

function getProfileTimerPhaseSeconds(configInput = {}, phaseInput = "work") {
  const config = normalizeProfileTimerConfig(configInput || {});
  const phase = String(phaseInput || "work").trim().toLowerCase() === "break" ? "break" : "work";
  const minutes = config.mode === "basic"
    ? config.durationMinutes
    : (phase === "break" ? config.breakMinutes : config.workMinutes);
  return Math.max(1, Math.round(minutes * 60));
}

function getProfileTimerRuntimeStorageKey(widget = {}) {
  const wid = normId(widget?.id || "");
  const uid = normId(state.user?.id || widget?.user_id || userCardCurrentUserId || "local") || "local";
  return wid ? `altara.timer.${uid}.${wid}` : "";
}

function getDefaultProfileTimerRuntime(configInput = {}, overrides = {}) {
  const config = normalizeProfileTimerConfig(configInput || {});
  const phase = config.mode === "basic" ? "work" : "work";
  return {
    phase,
    isRunning: false,
    startedAt: "",
    durationSeconds: getProfileTimerPhaseSeconds(config, phase),
    pausedElapsedSeconds: 0,
    round: 1,
    completedRounds: 0,
    isComplete: false,
    updatedAt: new Date().toISOString(),
    ...overrides,
  };
}

function normalizeProfileTimerRuntime(input = {}, configInput = {}) {
  const config = normalizeProfileTimerConfig(configInput || {});
  const src = input && typeof input === "object" && !Array.isArray(input) ? input : {};
  const phase = config.mode === "study" && String(src.phase || "").trim().toLowerCase() === "break" ? "break" : "work";
  const fallbackDuration = getProfileTimerPhaseSeconds(config, phase);
  const durationSeconds = clampInt(src.durationSeconds, 1, 86400, fallbackDuration);
  const startedAtRaw = String(src.startedAt || "").trim();
  const startedMs = Date.parse(startedAtRaw);
  const isRunning = src.isRunning === true && Number.isFinite(startedMs) && startedMs > 0;
  return {
    phase,
    isRunning,
    startedAt: isRunning ? startedAtRaw : "",
    durationSeconds,
    pausedElapsedSeconds: clampInt(src.pausedElapsedSeconds, 0, durationSeconds, 0),
    round: clampInt(src.round, 1, 999, 1),
    completedRounds: clampInt(src.completedRounds, 0, 999, 0),
    isComplete: src.isComplete === true,
    updatedAt: String(src.updatedAt || "").trim() || new Date().toISOString(),
  };
}

function readProfileTimerRuntime(widget = {}, configInput = null) {
  const config = configInput || getProfileTimerConfig(widget);
  const key = getProfileTimerRuntimeStorageKey(widget);
  if (!key || typeof localStorage === "undefined") return getDefaultProfileTimerRuntime(config);
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return getDefaultProfileTimerRuntime(config);
    return normalizeProfileTimerRuntime(JSON.parse(raw), config);
  } catch (_) {
    return getDefaultProfileTimerRuntime(config);
  }
}

function writeProfileTimerRuntime(widget = {}, runtimeInput = {}, configInput = null) {
  const config = configInput || getProfileTimerConfig(widget);
  const key = getProfileTimerRuntimeStorageKey(widget);
  const runtime = normalizeProfileTimerRuntime({
    ...runtimeInput,
    updatedAt: new Date().toISOString(),
  }, config);
  if (key && typeof localStorage !== "undefined") {
    try { localStorage.setItem(key, JSON.stringify(runtime)); } catch (_) {}
  }
  return runtime;
}

function getProfileTimerElapsedSeconds(runtime = {}, nowMs = Date.now()) {
  const duration = clampInt(runtime.durationSeconds, 1, 86400, 1);
  let elapsed = clampInt(runtime.pausedElapsedSeconds, 0, duration, 0);
  if (runtime.isRunning && runtime.startedAt) {
    const startedMs = Date.parse(runtime.startedAt);
    if (Number.isFinite(startedMs) && startedMs > 0) {
      elapsed += Math.max(0, Math.floor((nowMs - startedMs) / 1000));
    }
  }
  return Math.min(duration, Math.max(0, elapsed));
}

function formatProfileTimerSeconds(secondsInput = 0) {
  const total = Math.max(0, Math.floor(Number(secondsInput) || 0));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const seconds = total % 60;
  if (hours > 0) return `${hours}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

function getProfileTimerPresetLabel(presetInput = "") {
  const preset = PROFILE_TIMER_PRESETS[String(presetInput || "").trim().toLowerCase()] || PROFILE_TIMER_PRESETS.study_20_5;
  return t(preset.labelKey, preset.fallback);
}

function getProfileTimerRoundLabel(config = {}, runtime = {}) {
  if (config.mode !== "study") return t("widget.timer.ready", "Ready");
  const round = clampInt(runtime.round, 1, 999, 1);
  const rounds = clampInt(config.rounds, 0, 12, PROFILE_TIMER_DEFAULT_CONFIG.rounds);
  if (rounds <= 0) return tf("widget.timer.round_infinite", { round }, `Round ${round}`);
  return tf("widget.timer.round", { round: Math.min(round, rounds), rounds }, `Round ${Math.min(round, rounds)}/${rounds}`);
}

function getProfileTimerNextLabel(config = {}, runtime = {}) {
  if (config.mode !== "study") return "";
  if (runtime.phase === "break") {
    return tf("widget.timer.next_focus", { minutes: config.workMinutes }, `Next: ${config.workMinutes} min focus`);
  }
  return tf("widget.timer.next_break", { minutes: config.breakMinutes }, `Next: ${config.breakMinutes} min break`);
}

function getProfileTimerRenderModel(widget = {}) {
  const config = getProfileTimerConfig(widget);
  const runtime = readProfileTimerRuntime(widget, config);
  const elapsedSeconds = getProfileTimerElapsedSeconds(runtime);
  const remainingSeconds = runtime.isComplete ? 0 : Math.max(0, runtime.durationSeconds - elapsedSeconds);
  const progress = runtime.durationSeconds > 0
    ? Math.max(0, Math.min(100, (elapsedSeconds / runtime.durationSeconds) * 100))
    : 0;
  const isBreak = config.mode === "study" && runtime.phase === "break";
  const phaseLabel = runtime.isComplete
    ? t("widget.timer.completed", "Study cycle complete")
    : (config.mode === "basic"
      ? t("widget.timer.basic", "Basic Timer")
      : (isBreak ? t("widget.timer.break", "Break") : t("widget.timer.focus", "Focus")));
  const title = config.mode === "basic" ? t("widget.timer.basic", "Basic Timer") : t("widget.timer.study", "Study Mode");
  const subline = config.mode === "basic"
    ? tf("widget.timer.line.basic", { minutes: config.durationMinutes }, `${config.durationMinutes} min timer`)
    : tf("widget.timer.line.study", { work: config.workMinutes, break: config.breakMinutes }, `${config.workMinutes} min focus - ${config.breakMinutes} min break`);
  const toggleLabel = runtime.isRunning
    ? t("widget.timer.pause", "Pause")
    : (elapsedSeconds > 0 && !runtime.isComplete ? t("widget.timer.resume", "Resume") : t("widget.timer.start", "Start"));
  return {
    config,
    runtime,
    elapsedSeconds,
    remainingSeconds,
    progress,
    isBreak,
    title,
    phaseLabel,
    subline,
    timeText: formatProfileTimerSeconds(remainingSeconds),
    toggleLabel,
    roundLabel: getProfileTimerRoundLabel(config, runtime),
    nextLabel: getProfileTimerNextLabel(config, runtime),
  };
}

function showProfileTimerToast(message = "", tone = "info") {
  const text = String(message || "").trim();
  if (!text || typeof document === "undefined") return;
  let toast = document.getElementById("profileTimerToast");
  if (!toast) {
    toast = document.createElement("div");
    toast.id = "profileTimerToast";
    toast.className = "profileTimerToast";
    document.body.appendChild(toast);
  }
  toast.textContent = text;
  toast.setAttribute("data-tone", tone === "warn" ? "warn" : "info");
  toast.classList.add("is-visible");
  setTimeout(() => {
    toast.classList.remove("is-visible");
  }, 2600);
}

function playProfileTimerSoftChime(configInput = {}) {
  const config = normalizeProfileTimerConfig(configInput || {});
  if (!config.soundEnabled || typeof window === "undefined") return;
  const AudioCtor = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtor) return;
  try {
    const ctx = new AudioCtor();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.value = 740;
    gain.gain.setValueAtTime(0.0001, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.045, ctx.currentTime + 0.025);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.42);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.45);
    setTimeout(() => { try { ctx.close(); } catch (_) {} }, 700);
  } catch (_) {}
}

function startProfileTimerRuntime(widget = {}) {
  const config = getProfileTimerConfig(widget);
  const runtime = readProfileTimerRuntime(widget, config);
  const elapsed = runtime.isComplete ? 0 : getProfileTimerElapsedSeconds(runtime);
  const phase = runtime.isComplete ? "work" : runtime.phase;
  const next = {
    ...runtime,
    phase,
    isRunning: true,
    isComplete: false,
    startedAt: new Date().toISOString(),
    durationSeconds: runtime.isComplete ? getProfileTimerPhaseSeconds(config, phase) : runtime.durationSeconds,
    pausedElapsedSeconds: runtime.isComplete ? 0 : Math.min(elapsed, Math.max(0, runtime.durationSeconds - 1)),
  };
  writeProfileTimerRuntime(widget, next, config);
}

function pauseProfileTimerRuntime(widget = {}) {
  const config = getProfileTimerConfig(widget);
  const runtime = readProfileTimerRuntime(widget, config);
  writeProfileTimerRuntime(widget, {
    ...runtime,
    isRunning: false,
    startedAt: "",
    pausedElapsedSeconds: getProfileTimerElapsedSeconds(runtime),
  }, config);
}

function resetProfileTimerRuntime(widget = {}) {
  const config = getProfileTimerConfig(widget);
  writeProfileTimerRuntime(widget, getDefaultProfileTimerRuntime(config), config);
}

function completeProfileTimerRuntime(widget = {}) {
  const config = getProfileTimerConfig(widget);
  const runtime = readProfileTimerRuntime(widget, config);
  writeProfileTimerRuntime(widget, {
    ...runtime,
    isRunning: false,
    startedAt: "",
    pausedElapsedSeconds: runtime.durationSeconds,
    isComplete: true,
  }, config);
  playProfileTimerSoftChime(config);
  showProfileTimerToast(t("widget.timer.completed", "Study cycle complete"), "info");
}

function advanceProfileTimerRuntime(widget = {}, { skipped = false } = {}) {
  const config = getProfileTimerConfig(widget);
  const runtime = readProfileTimerRuntime(widget, config);
  const nowIso = new Date().toISOString();
  if (config.mode === "basic") {
    completeProfileTimerRuntime(widget);
    return;
  }
  if (runtime.phase === "work") {
    const shouldRun = skipped ? false : config.autoStartBreak;
    writeProfileTimerRuntime(widget, {
      phase: "break",
      isRunning: shouldRun,
      startedAt: shouldRun ? nowIso : "",
      durationSeconds: getProfileTimerPhaseSeconds(config, "break"),
      pausedElapsedSeconds: 0,
      round: runtime.round,
      completedRounds: runtime.completedRounds,
      isComplete: false,
    }, config);
    if (!skipped) {
      playProfileTimerSoftChime(config);
      showProfileTimerToast(t("widget.timer.break", "Break"), "info");
    }
    return;
  }
  const completedRounds = clampInt(runtime.completedRounds, 0, 999, 0) + 1;
  const rounds = clampInt(config.rounds, 0, 12, PROFILE_TIMER_DEFAULT_CONFIG.rounds);
  if (rounds > 0 && completedRounds >= rounds) {
    writeProfileTimerRuntime(widget, {
      phase: "work",
      isRunning: false,
      startedAt: "",
      durationSeconds: getProfileTimerPhaseSeconds(config, "work"),
      pausedElapsedSeconds: 0,
      round: rounds,
      completedRounds,
      isComplete: true,
    }, config);
    playProfileTimerSoftChime(config);
    showProfileTimerToast(t("widget.timer.completed", "Study cycle complete"), "info");
    return;
  }
  const shouldRun = skipped ? false : config.autoStartNextWork;
  writeProfileTimerRuntime(widget, {
    phase: "work",
    isRunning: shouldRun,
    startedAt: shouldRun ? nowIso : "",
    durationSeconds: getProfileTimerPhaseSeconds(config, "work"),
    pausedElapsedSeconds: 0,
    round: clampInt(runtime.round, 1, 999, 1) + 1,
    completedRounds,
    isComplete: false,
  }, config);
  if (!skipped) {
    playProfileTimerSoftChime(config);
    showProfileTimerToast(t("widget.timer.focus", "Focus"), "info");
  }
}

function buildProfileTimerSettingsButtonHtml(widget = {}) {
  return `<button class="profileTimerBtn profileTimerBtn--settings" type="button" data-profile-widget-act="timer-open-settings" data-widget-id="${escAttr(widget.id || "")}" aria-label="${escAttr(t("widget.timer.settings", "Timer settings"))}">${esc(t("widget.timer.settings", "Settings"))}</button>`;
}

function buildProfileTimerSettingsSheetHtml(widget = {}, { source = "profile" } = {}) {
  const config = getProfileTimerConfig(widget);
  const presetOptions = Object.entries(PROFILE_TIMER_PRESETS).map(([key]) => {
    const selected = key === config.preset ? " selected" : "";
    return `<option value="${escAttr(key)}"${selected}>${esc(getProfileTimerPresetLabel(key))}</option>`;
  }).join("");
  const widgetId = String(widget?.id || "").trim();
  return `
    <div class="profileTimerSettingsBackdrop" data-profile-timer-settings-close aria-hidden="true"></div>
    <section class="profileTimerSettingsSheet" role="dialog" aria-modal="true" aria-labelledby="profileTimerSettingsTitle" data-profile-timer-settings-source="${escAttr(source)}" data-widget-id="${escAttr(widgetId)}">
      <header class="profileTimerSettingsSheetHead">
        <div>
          <p class="profileTimerSettingsEyebrow">${esc(t("widget.timer.study", "Study Mode"))}</p>
          <h2 id="profileTimerSettingsTitle" class="profileTimerSettingsSheetTitle">${esc(t("widget.timer.settings", "Timer Settings"))}</h2>
        </div>
        <button class="profileTimerSettingsIconBtn" type="button" data-profile-timer-settings-close aria-label="${escAttr(t("common.close", "Close"))}">&times;</button>
      </header>
      <div class="profileTimerSettingsBody">
        <label class="profileTimerSettingsRow">
          <span>${esc(t("widget.timer.mode", "Mode"))}</span>
          <select class="profileTimerSelect" data-profile-timer-setting="mode">
            <option value="study"${config.mode === "study" ? " selected" : ""}>${esc(t("widget.timer.study", "Study Mode"))}</option>
            <option value="basic"${config.mode === "basic" ? " selected" : ""}>${esc(t("widget.timer.basic", "Basic Timer"))}</option>
          </select>
        </label>
        <label class="profileTimerSettingsRow">
          <span>${esc(t("widget.timer.preset", "Preset"))}</span>
          <select class="profileTimerSelect" data-profile-timer-setting="preset">${presetOptions}</select>
        </label>
        <div class="profileTimerSettingsGrid">
          <label class="profileTimerSettingsRow">
            <span>${esc(t("widget.timer.focus_minutes", "Focus minutes"))}</span>
            <input class="profileTimerNumberInput" type="number" min="1" max="180" inputmode="numeric" value="${escAttr(config.workMinutes)}" data-profile-timer-setting="workMinutes" />
          </label>
          <label class="profileTimerSettingsRow">
            <span>${esc(t("widget.timer.break_minutes", "Break minutes"))}</span>
            <input class="profileTimerNumberInput" type="number" min="1" max="60" inputmode="numeric" value="${escAttr(config.breakMinutes)}" data-profile-timer-setting="breakMinutes" />
          </label>
          <label class="profileTimerSettingsRow">
            <span>${esc(t("widget.timer.duration_minutes", "Duration"))}</span>
            <input class="profileTimerNumberInput" type="number" min="1" max="180" inputmode="numeric" value="${escAttr(config.durationMinutes)}" data-profile-timer-setting="durationMinutes" />
          </label>
          <label class="profileTimerSettingsRow">
            <span>${esc(t("widget.timer.rounds", "Rounds"))}</span>
            <input class="profileTimerNumberInput" type="number" min="0" max="12" inputmode="numeric" value="${escAttr(config.rounds)}" data-profile-timer-setting="rounds" />
            <em>${esc(t("widget.timer.rounds_hint", "0 = infinite"))}</em>
          </label>
        </div>
        <label class="profileTimerToggleRow">
          <input type="checkbox" data-profile-timer-setting="autoStartBreak"${config.autoStartBreak ? " checked" : ""} />
          <span>${esc(t("widget.timer.auto_start_break", "Auto-start break"))}</span>
        </label>
        <label class="profileTimerToggleRow">
          <input type="checkbox" data-profile-timer-setting="autoStartNextWork"${config.autoStartNextWork ? " checked" : ""} />
          <span>${esc(t("widget.timer.auto_start_focus", "Auto-start focus"))}</span>
        </label>
        <label class="profileTimerToggleRow">
          <input type="checkbox" data-profile-timer-setting="soundEnabled"${config.soundEnabled ? " checked" : ""} />
          <span>${esc(t("widget.timer.sound", "Sound"))}</span>
        </label>
      </div>
      <footer class="profileTimerSettingsSheetActions">
        <button class="profileTimerSettingsReset" type="button" data-profile-timer-settings-reset>${esc(t("widget.timer.reset_study", "Reset to Study 20/5"))}</button>
        <span></span>
        <button class="profileTimerSettingsCancel" type="button" data-profile-timer-settings-close>${esc(t("common.cancel", "Cancel"))}</button>
        <button class="profileTimerSettingsSave" type="button" data-profile-timer-settings-save>${esc(t("common.save", "Save"))}</button>
      </footer>
    </section>
  `;
}

function getProfileTimerSettingsPortal() {
  if (typeof document === "undefined") return null;
  return document.getElementById("profileTimerSettingsPortal");
}

function closeProfileTimerSettingsSheet() {
  const portal = getProfileTimerSettingsPortal();
  if (portal) portal.remove();
  if (typeof document !== "undefined") {
    document.removeEventListener("keydown", handleProfileTimerSettingsKeydown, true);
  }
}

function handleProfileTimerSettingsKeydown(event) {
  if (!event || event.key !== "Escape") return;
  if (!getProfileTimerSettingsPortal()) return;
  event.preventDefault();
  closeProfileTimerSettingsSheet();
}

function openProfileTimerSettingsSheet(widget = {}, { source = "profile" } = {}) {
  if (typeof document === "undefined") return;
  closeProfileTimerSettingsSheet();
  const portal = document.createElement("div");
  portal.id = "profileTimerSettingsPortal";
  portal.className = "profileTimerSettingsPortal";
  portal.innerHTML = buildProfileTimerSettingsSheetHtml(widget, { source });
  bindProfileTimerSettingsPortal(portal);
  document.body.appendChild(portal);
  document.addEventListener("keydown", handleProfileTimerSettingsKeydown, true);
  const firstField = portal.querySelector("[data-profile-timer-setting]");
  if (firstField && typeof firstField.focus === "function") {
    setTimeout(() => { try { firstField.focus({ preventScroll: true }); } catch (_) { try { firstField.focus(); } catch (_) {} } }, 0);
  }
  if (isProfileWidgetsDebugEnabled()) {
    try { console.debug("[Widgets] timer settings open", { source, widgetId: widget?.id || "" }); } catch (_) {}
  }
}

function getProfileTimerSettingsWidgetFromPortal(portal = null) {
  const sheet = portal?.querySelector?.(".profileTimerSettingsSheet") || null;
  const source = String(sheet?.getAttribute?.("data-profile-timer-settings-source") || "profile").trim();
  if (source === "local") return getWidgetTimerProfileAdapter(getWidgetSize("timer"));
  const widgetId = normId(sheet?.getAttribute?.("data-widget-id") || "");
  return widgetId ? findCurrentUserCardWidget(widgetId) : null;
}

function getProfileTimerSettingsSourceFromPortal(portal = null) {
  const sheet = portal?.querySelector?.(".profileTimerSettingsSheet") || null;
  return String(sheet?.getAttribute?.("data-profile-timer-settings-source") || "profile").trim() === "local" ? "local" : "profile";
}

function applyProfileTimerPresetToSettingsRoot(root = null, presetKey = "study_20_5") {
  if (!(root instanceof Element)) return;
  const preset = PROFILE_TIMER_PRESETS[String(presetKey || "").trim().toLowerCase()];
  if (!preset || presetKey === "custom") return;
  const workEl = root.querySelector('[data-profile-timer-setting="workMinutes"]');
  const breakEl = root.querySelector('[data-profile-timer-setting="breakMinutes"]');
  const durationEl = root.querySelector('[data-profile-timer-setting="durationMinutes"]');
  const modeEl = root.querySelector('[data-profile-timer-setting="mode"]');
  if (workEl instanceof HTMLInputElement) workEl.value = String(preset.workMinutes);
  if (breakEl instanceof HTMLInputElement) breakEl.value = String(preset.breakMinutes);
  if (durationEl instanceof HTMLInputElement) durationEl.value = String(preset.workMinutes);
  if (modeEl instanceof HTMLSelectElement) modeEl.value = preset.mode || "study";
}

function readProfileTimerSettingsFromRoot(root = null, widget = {}) {
  const current = getProfileTimerConfig(widget);
  if (!(root instanceof Element)) return current;
  const getField = (name) => root.querySelector(`[data-profile-timer-setting="${name}"]`);
  const modeEl = getField("mode");
  const presetEl = getField("preset");
  const workEl = getField("workMinutes");
  const breakEl = getField("breakMinutes");
  const durationEl = getField("durationMinutes");
  const roundsEl = getField("rounds");
  const autoBreakEl = getField("autoStartBreak");
  const autoWorkEl = getField("autoStartNextWork");
  const soundEl = getField("soundEnabled");
  const workValue = workEl instanceof HTMLInputElement ? workEl.value : current.workMinutes;
  const breakValue = breakEl instanceof HTMLInputElement ? breakEl.value : current.breakMinutes;
  let preset = presetEl instanceof HTMLSelectElement ? presetEl.value : current.preset;
  const presetDef = PROFILE_TIMER_PRESETS[String(preset || "").trim().toLowerCase()];
  if (presetDef && preset !== "custom") {
    const workNum = Number(workValue);
    const breakNum = Number(breakValue);
    if ((Number.isFinite(workNum) && workNum !== presetDef.workMinutes) || (Number.isFinite(breakNum) && breakNum !== presetDef.breakMinutes)) {
      preset = "custom";
    }
  }
  return normalizeProfileTimerConfig({
    mode: modeEl instanceof HTMLSelectElement ? modeEl.value : current.mode,
    preset,
    workMinutes: workValue,
    breakMinutes: breakValue,
    durationMinutes: durationEl instanceof HTMLInputElement ? durationEl.value : current.durationMinutes,
    rounds: roundsEl instanceof HTMLInputElement ? roundsEl.value : current.rounds,
    autoStartBreak: autoBreakEl instanceof HTMLInputElement ? autoBreakEl.checked : current.autoStartBreak,
    autoStartNextWork: autoWorkEl instanceof HTMLInputElement ? autoWorkEl.checked : current.autoStartNextWork,
    soundEnabled: soundEl instanceof HTMLInputElement ? soundEl.checked : current.soundEnabled,
    focusIntegrationEnabled: false,
  });
}

async function saveProfileTimerSettingsFromPortal(portal = null) {
  if (!(portal instanceof Element)) return false;
  const widget = getProfileTimerSettingsWidgetFromPortal(portal);
  if (!widget) return false;
  const source = getProfileTimerSettingsSourceFromPortal(portal);
  const timerConfig = readProfileTimerSettingsFromRoot(portal, widget);
  const saveBtn = portal.querySelector("[data-profile-timer-settings-save]");
  if (saveBtn instanceof HTMLButtonElement) saveBtn.disabled = true;
  try {
    if (source === "local") {
      const savedConfig = saveWidgetTimerConfig(timerConfig);
      writeProfileTimerRuntime(widget, getDefaultProfileTimerRuntime(savedConfig), savedConfig);
      renderWidgets();
      syncWidgetTimerScheduler();
      showProfileTimerToast(t("widget.timer.settings_saved", "Timer settings saved"), "info");
      if (isProfileWidgetsDebugEnabled()) {
        try { console.debug("[Widgets] timer settings save", { source, config: savedConfig }); } catch (_) {}
      }
      closeProfileTimerSettingsSheet();
      return true;
    }
    const ok = await saveProfileTimerWidgetSettingsConfig(widget, timerConfig);
    if (ok) closeProfileTimerSettingsSheet();
    return ok;
  } finally {
    if (saveBtn instanceof HTMLButtonElement) saveBtn.disabled = false;
  }
}

function bindProfileTimerSettingsPortal(portal = null) {
  if (!(portal instanceof Element)) return;
  portal.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    if (target.closest("[data-profile-timer-settings-close]")) {
      event.preventDefault();
      closeProfileTimerSettingsSheet();
      return;
    }
    if (target.closest("[data-profile-timer-settings-reset]")) {
      event.preventDefault();
      const presetEl = portal.querySelector('[data-profile-timer-setting="preset"]');
      if (presetEl instanceof HTMLSelectElement) presetEl.value = "study_20_5";
      const roundsEl = portal.querySelector('[data-profile-timer-setting="rounds"]');
      const autoBreakEl = portal.querySelector('[data-profile-timer-setting="autoStartBreak"]');
      const autoWorkEl = portal.querySelector('[data-profile-timer-setting="autoStartNextWork"]');
      const soundEl = portal.querySelector('[data-profile-timer-setting="soundEnabled"]');
      applyProfileTimerPresetToSettingsRoot(portal, "study_20_5");
      if (roundsEl instanceof HTMLInputElement) roundsEl.value = "4";
      if (autoBreakEl instanceof HTMLInputElement) autoBreakEl.checked = false;
      if (autoWorkEl instanceof HTMLInputElement) autoWorkEl.checked = false;
      if (soundEl instanceof HTMLInputElement) soundEl.checked = true;
      return;
    }
    if (target.closest("[data-profile-timer-settings-save]")) {
      event.preventDefault();
      void saveProfileTimerSettingsFromPortal(portal);
    }
  });
  portal.addEventListener("change", (event) => {
    const target = event.target;
    if (target instanceof HTMLSelectElement && target.getAttribute("data-profile-timer-setting") === "preset") {
      applyProfileTimerPresetToSettingsRoot(portal, target.value);
    }
  });
  portal.addEventListener("input", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) return;
    if (!["workMinutes", "breakMinutes"].includes(target.getAttribute("data-profile-timer-setting") || "")) return;
    const presetEl = portal.querySelector('[data-profile-timer-setting="preset"]');
    if (presetEl instanceof HTMLSelectElement) presetEl.value = "custom";
  });
}
function buildProfileTimerWidgetCardHtml(widget = {}, {
  className = "",
  layoutAttrs = "",
  layoutStyle = "",
  size = "medium",
  isOwnerProfile = false,
  isEditing = false,
  controlsHtml = "",
} = {}) {
  const model = getProfileTimerRenderModel(widget);
  const canControl = !!isOwnerProfile;
  const phaseTone = model.isBreak ? "break" : "focus";
  const toggleAction = model.runtime.isRunning ? "timer-pause" : "timer-start";
  const settingsHtml = canControl && size !== "small" ? buildProfileTimerSettingsButtonHtml(widget, model) : "";
  const skipHtml = canControl && size === "large" && model.config.mode === "study"
    ? `<button class="profileTimerBtn" type="button" data-profile-widget-act="timer-skip" data-widget-id="${escAttr(widget.id || "")}" aria-label="${escAttr(t("widget.timer.skip", "Skip"))}">${esc(t("widget.timer.skip", "Skip"))}</button>`
    : "";
  const resetHtml = canControl && size !== "small"
    ? `<button class="profileTimerBtn" type="button" data-profile-widget-act="timer-reset" data-widget-id="${escAttr(widget.id || "")}" aria-label="${escAttr(t("widget.timer.reset", "Reset"))}">${esc(t("widget.timer.reset", "Reset"))}</button>`
    : "";
  const controls = canControl ? `
    <div class="profileTimerControls">
      <button class="profileTimerBtn profileTimerBtn--primary" type="button" data-profile-widget-act="${escAttr(toggleAction)}" data-widget-id="${escAttr(widget.id || "")}" aria-label="${escAttr(model.toggleLabel)}" data-profile-timer-toggle>${esc(model.toggleLabel)}</button>
      ${skipHtml}
      ${resetHtml}
      ${settingsHtml}
    </div>
  ` : "";
  const sizeClass = `profileTimerWidget--${size}`;
  const nextHtml = size === "large" && model.nextLabel ? `<div class="profileTimerNext" data-profile-timer-next>${esc(model.nextLabel)}</div>` : "";
  const settingsSlot = "";

  return `
    <article class="${escAttr(className)} profileTimerWidget ${escAttr(sizeClass)}" data-profile-widget-id="${escAttr(widget.id || "")}" data-profile-timer-widget-id="${escAttr(widget.id || "")}" data-widget-size="${escAttr(size)}" data-widget-type="timer" data-profile-timer-phase="${escAttr(phaseTone)}" ${layoutAttrs} style="${escAttr(layoutStyle)} --profile-timer-progress:${escAttr(model.progress.toFixed(2))}%;" role="listitem">
      <div class="profileTimerInner">
        <div class="profileTimerHeader">
          <div>
            <div class="profileTimerKicker">${esc(size === "small" ? t("widget.timer", "Timer") : model.title)}</div>
            <div class="profileTimerPhase" data-profile-timer-phase-label>${esc(model.phaseLabel)}</div>
          </div>
          ${size !== "small" ? `<div class="profileTimerRound" data-profile-timer-round>${esc(model.roundLabel)}</div>` : ""}
        </div>
        <div class="profileTimerMain">
          <div class="profileTimerRing" aria-hidden="true"><span></span></div>
          <div class="profileTimerTime" data-profile-timer-time aria-label="${escAttr(model.phaseLabel + " " + model.timeText)}">${esc(model.timeText)}</div>
        </div>
        ${size !== "small" ? `<div class="profileTimerSubline" data-profile-timer-subline>${esc(model.subline)}</div>` : ""}
        ${size !== "small" ? `<div class="profileTimerProgress" aria-hidden="true"><span data-profile-timer-progress></span></div>` : ""}
        ${nextHtml}
        ${controls}
        ${settingsSlot}
      </div>
      ${isEditing ? controlsHtml : ""}
    </article>
  `;
}

function updateProfileTimerWidgetDom(card = null, modelInput = null) {
  if (!(card instanceof Element)) return;
  const widgetId = normId(card.getAttribute("data-profile-timer-widget-id") || "");
  const widget = widgetId ? findCurrentUserCardWidget(widgetId) : null;
  const model = modelInput || (widget ? getProfileTimerRenderModel(widget) : null);
  if (!model) return;
  card.style.setProperty("--profile-timer-progress", `${model.progress.toFixed(2)}%`);
  card.setAttribute("data-profile-timer-phase", model.isBreak ? "break" : "focus");
  const timeEl = card.querySelector("[data-profile-timer-time]");
  if (timeEl) {
    timeEl.textContent = model.timeText;
    timeEl.setAttribute("aria-label", `${model.phaseLabel} ${model.timeText}`);
  }
  const phaseEl = card.querySelector("[data-profile-timer-phase-label]");
  if (phaseEl) phaseEl.textContent = model.phaseLabel;
  const roundEl = card.querySelector("[data-profile-timer-round]");
  if (roundEl) roundEl.textContent = model.roundLabel;
  const nextEl = card.querySelector("[data-profile-timer-next]");
  if (nextEl) nextEl.textContent = model.nextLabel;
}

function syncProfileTimerWidgetScheduler() {
  if (typeof document === "undefined") return;
  const cards = Array.from(document.querySelectorAll("[data-profile-timer-widget-id]"));
  const hasRunning = cards.some((card) => {
    const widgetId = normId(card.getAttribute("data-profile-timer-widget-id") || "");
    const widget = widgetId ? findCurrentUserCardWidget(widgetId) : null;
    if (!widget) return false;
    const model = getProfileTimerRenderModel(widget);
    return model.runtime.isRunning;
  });
  if (hasRunning && !profileTimerWidgetTicker) {
    profileTimerWidgetTicker = setInterval(tickProfileTimerWidgets, 1000);
  } else if (!hasRunning && profileTimerWidgetTicker) {
    clearInterval(profileTimerWidgetTicker);
    profileTimerWidgetTicker = 0;
  }
}

function tickProfileTimerWidgets() {
  if (typeof document === "undefined") return;
  const cards = Array.from(document.querySelectorAll("[data-profile-timer-widget-id]"));
  let shouldKeepTicking = false;
  cards.forEach((card) => {
    const widgetId = normId(card.getAttribute("data-profile-timer-widget-id") || "");
    const widget = widgetId ? findCurrentUserCardWidget(widgetId) : null;
    if (!widget) return;
    const model = getProfileTimerRenderModel(widget);
    if (model.runtime.isRunning && model.remainingSeconds <= 0) {
      advanceProfileTimerRuntime(widget);
      refreshOpenUserCard({ forceWidgetPanelRender: true });
      shouldKeepTicking = true;
      return;
    }
    if (model.runtime.isRunning) shouldKeepTicking = true;
    updateProfileTimerWidgetDom(card, model);
  });
  if (!shouldKeepTicking && profileTimerWidgetTicker) {
    clearInterval(profileTimerWidgetTicker);
    profileTimerWidgetTicker = 0;
  }
}

function readProfileTimerSettingsFromCard(card = null, widget = {}) {
  return readProfileTimerSettingsFromRoot(card, widget);
}
async function saveProfileTimerWidgetSettingsConfig(widget = {}, timerConfigInput = {}) {
  if (!widget?.id || userCardWidgetsMutating) return false;
  const uid = normId(userCardCurrentUserId || "");
  const meId = normId(state.user?.id || "");
  if (!uid || uid !== meId) return false;
  const timerConfig = normalizeProfileTimerConfig(timerConfigInput || getProfileTimerConfig(widget));
  const previousWidgets = getCurrentUserCardWidgets();
  const currentLayout = getProfileWidgetComputedLayout(widget, PROFILE_WIDGET_DESKTOP_COLUMNS);
  const nextConfig = normalizeProfileTimerWidgetConfig({
    ...(widget.config || {}),
    timer: timerConfig,
    size: normalizeProfileWidgetSize(widget.size || "medium", "timer"),
  });
  userCardWidgetsMutating = true;
  try {
    const normalizedWidget = { ...widget, widget_type: "timer", type: "timer", config: nextConfig };
    const payloadConfig = getProfileWidgetConfigWithDesktopLayout(normalizedWidget, currentLayout);
    await updateProfileWidgetRpc(widget.id, {
      size: normalizeProfileWidgetSize(widget.size || "medium", "timer"),
      config: payloadConfig,
    });
    writeProfileTimerRuntime(widget, getDefaultProfileTimerRuntime(timerConfig), timerConfig);
    await refreshUserCardWidgetsData({ force: true, keepLoading: true });
    refreshOpenUserCard({ forceWidgetPanelRender: true });
    setUserCardActiveTab("widgets");
    showProfileTimerToast(t("widget.timer.settings_saved", "Timer settings saved"), "info");
    if (isProfileWidgetsDebugEnabled()) {
      try { console.debug("[Widgets] timer settings save", { source: "profile", widgetId: widget.id, config: timerConfig }); } catch (_) {}
    }
    return true;
  } catch (error) {
    setCachedProfileWidgetsForUser(uid, previousWidgets);
    alert(toProfileWidgetError(error, t("profile.widgets.error.save", "Could not save widget.")));
    return false;
  } finally {
    userCardWidgetsMutating = false;
    syncProfileTimerWidgetScheduler();
  }
}

async function saveProfileTimerWidgetSettings(widget = {}, actionButton = null) {
  const root = actionButton?.closest?.(".profileTimerSettingsSheet") || actionButton?.closest?.(".profileWidgetCard") || null;
  const timerConfig = readProfileTimerSettingsFromRoot(root, widget);
  return saveProfileTimerWidgetSettingsConfig(widget, timerConfig);
}
async function handleProfileTimerWidgetAction(action = "", widget = {}, actionButton = null) {
  const uid = normId(userCardCurrentUserId || "");
  const meId = normId(state.user?.id || "");
  if (!widget?.id || !uid || uid !== meId) return;
  if (action === "timer-open-settings") {
    openProfileTimerSettingsSheet(widget, { source: "profile" });
    return;
  }
  if (action === "timer-save-settings") {
    await saveProfileTimerWidgetSettings(widget, actionButton);
    return;
  }
  const model = getProfileTimerRenderModel(widget);
  if (action === "timer-start") startProfileTimerRuntime(widget);
  else if (action === "timer-pause") pauseProfileTimerRuntime(widget);
  else if (action === "timer-reset") resetProfileTimerRuntime(widget);
  else if (action === "timer-skip") advanceProfileTimerRuntime(widget, { skipped: true });
  else return;
  refreshOpenUserCard({ forceWidgetPanelRender: true });
  syncProfileTimerWidgetScheduler();
  if (isProfileWidgetsDebugEnabled()) {
    try { console.debug("[Widgets] timer", { action, widgetId: widget.id, before: model.runtime, after: readProfileTimerRuntime(widget) }); } catch (_) {}
  }
}

function formatProfileWidgetStars(ratingInput = null) {
  if (!Number.isFinite(Number(ratingInput))) return "";
  const rating = clampInt(ratingInput, 1, 5, 1);
  return `${"?".repeat(rating)}${"?".repeat(5 - rating)}`;
}

function getProfileWidgetFeaturedItem(widget) {
  if (!widget || !Array.isArray(widget.items) || !widget.items.length) return null;
  return widget.items.find((item) => !!item?.is_featured) || widget.items[0] || null;
}

function isProfileWidgetPubliclyVisible(widget = null) {
  if (!widget || typeof widget !== "object") return false;
  if (widget.hidden === true || widget.is_enabled === false || widget.is_public === false) return false;
  const visibility = normalizeProfileWidgetVisibility(widget.visibility || "public");
  return visibility === "public";
}

function isProfileWidgetItemPubliclyVisible(item = null) {
  if (!item || typeof item !== "object") return false;
  if (item.hidden === true || item.is_public === false) return false;
  const visibility = normalizeProfileWidgetVisibility(item.visibility || "public");
  return visibility === "public";
}

function getProfileWidgetsForViewer(userId = "", widgets = []) {
  const uid = normId(userId || "");
  const isOwner = !!(uid && uid === normId(state.user?.id || ""));
  const source = Array.isArray(widgets) ? cloneProfileWidgetsList(widgets) : [];
  const profileWidgets = source.filter((widget) => isProfileContentWidgetType(widget?.widget_type || widget?.type || ""));
  if (isOwner) return profileWidgets;
  return profileWidgets
    .filter(isProfileWidgetPubliclyVisible)
    .map((widget) => ({
      ...widget,
      items: (Array.isArray(widget.items) ? widget.items : []).filter(isProfileWidgetItemPubliclyVisible),
    }))
    .filter((widget) => (Array.isArray(widget.items) ? widget.items.length : 0) > 0);
}

function isProfileWidgetRpcUnavailable(error) {
  const code = String(error?.code || "").trim().toLowerCase();
  const msg = String(error?.message || "").trim().toLowerCase();
  return code === "42883"
    || code === "pgrst202"
    || msg.includes("list_profile_widgets")
    || msg.includes("create_profile_widget")
    || msg.includes("profile_widgets");
}

function toProfileWidgetError(error, fallbackMessage = "") {
  const fallback = String(fallbackMessage || "").trim() || t("profile.widgets.error.generic", "Could not load profile widgets.");
  if (!error) return fallback;
  if (isProfileWidgetRpcUnavailable(error)) {
    return t(
      "profile.widgets.error.sql_missing",
      "Profile Widgets SQL patch is missing. Apply SQL/SUPABASE_PATCH_PROFILE_INTEREST_WIDGETS.sql."
    );
  }
  return String(error?.message || fallback).trim() || fallback;
}

async function fetchProfileWidgetsForUser(targetUserId, { force = false, maxAgeMs = 0 } = {}) {
  const uid = normId(targetUserId || "");
  if (!uid) return [];
  const cacheMaxAgeMs = Math.max(0, Number(maxAgeMs || 0) || 0);
  const fetchedAt = Number(userCardWidgetsFetchedAtByUser.get(uid) || 0);
  const cacheFresh = !cacheMaxAgeMs || (!!fetchedAt && (Date.now() - fetchedAt) >= 0 && (Date.now() - fetchedAt) <= cacheMaxAgeMs);
  if (!force && userCardWidgetsCache.has(uid) && cacheFresh) {
    return getCachedProfileWidgetsForUser(uid);
  }

  const { data, error } = await supabase.rpc("list_profile_widgets", {
    target_user_id: uid,
  });
  if (error) throw error;
  logProfileWidgetsDebug("loaded", { userId: uid, count: Array.isArray(data) ? data.length : 0 });

  const rawRows = Array.isArray(data) ? data : [];
  const widgets = rawRows
    .map((row) => normalizeProfileWidgetRow(row))
    .filter((row) => !!row.id)
    .sort((a, b) => (
      Number(a.position || 0) - Number(b.position || 0)
      || (Date.parse(a.created_at || 0) || 0) - (Date.parse(b.created_at || 0) || 0)
    ));
  const accidentalDashboardWidgets = widgets.filter((widget) => isDashboardOnlyProfileWidgetType(widget?.widget_type || widget?.type || ""));
  if (accidentalDashboardWidgets.length) {
    logProfileWidgetsDebug("dashboard widgets hidden from profile", {
      userId: uid,
      widgets: accidentalDashboardWidgets.map((widget) => ({ id: widget.id, type: widget.widget_type || widget.type })),
    });
  }

  logProfileWidgetsDebug("normalized", {
    userId: uid,
    widgets: widgets.map((widget) => ({
      id: widget.id,
      type: widget.widget_type,
      size: widget.size,
      order: widget.order,
      itemCount: Array.isArray(widget.items) ? widget.items.length : 0,
    })),
  });
  userCardWidgetsCache.set(uid, getProfileWidgetsForViewer(uid, widgets));
  userCardWidgetsFetchedAtByUser.set(uid, Date.now());
  return getCachedProfileWidgetsForUser(uid);
}

async function createProfileWidgetRpc(widgetTypeInput, titleInput) {
  const widgetType = normalizeProfileWidgetCreateType(widgetTypeInput);
  const title = normalizeProfileWidgetTitle(titleInput);
  if (!title) throw new Error(t("profile.widgets.error.title_required", "Title is required."));
  const { data, error } = await supabase.rpc("create_profile_widget", {
    p_widget_type: widgetType,
    p_title: title,
  });
  if (error) throw error;
  return normalizeProfileWidgetRow(data || {});
}

