      firstFastFetchAt: row.firstFastFetchAt ? new Date(row.firstFastFetchAt).toISOString() : null,
      responseRenderedAt: row.renderedAt ? new Date(row.renderedAt).toISOString() : null,
      thinkingClearedAt: row.clearedThinkingAt ? new Date(row.clearedThinkingAt).toISOString() : null,
      resolvedBy,
