      botRowReceivedAt: row.botMessageInsertAt ? new Date(row.botMessageInsertAt).toISOString() : null,
      responseFetchedAt: row.responseFetchedAt ? new Date(row.responseFetchedAt).toISOString() : null,
      appendedAt: row.appendedAt ? new Date(row.appendedAt).toISOString() : null,
      renderedAt: row.renderedAt ? new Date(row.renderedAt).toISOString() : null,
      clearedThinkingAt: row.clearedThinkingAt ? new Date(row.clearedThinkingAt).toISOString() : null,
      usedRealtime: row.botChannelMessagesInsertReceived === true || row.botInteractionRespondedUpdateReceived === true,
