function getUserScopedVoiceStorageKey(baseKey = "") {
  const key = String(baseKey || "").trim();
  const uid = getAltaraCurrentUserId();
  return uid ? `${key}:${uid}` : key;
}

function readUserScopedVoiceStorageRaw(baseKey = "") {
  const key = String(baseKey || "").trim();
  if (!key || typeof localStorage === "undefined") return null;
  const scopedKey = getUserScopedVoiceStorageKey(key);
  try {
    const scoped = localStorage.getItem(scopedKey);
    if (scoped !== null) return scoped;
    return localStorage.getItem(key);
  } catch (_) {
    return null;
  }
}

function writeUserScopedVoiceStorageRaw(baseKey = "", value = "") {
  const key = String(baseKey || "").trim();
  if (!key || typeof localStorage === "undefined") return false;
  try {
    localStorage.setItem(getUserScopedVoiceStorageKey(key), String(value));
    return true;
  } catch (_) {
    return false;
  }
}
