function inferNotificationForSoundCue(kind, name) {
  const cueName = String(name || "").trim().toLowerCase();
  if (kind === "sfx" && (cueName === "ring" || cueName === "incoming")) return { type: "call" };
  if (kind === "ui" && cueName === "group_dm") return { type: "group_dm" };
  if (kind === "ui" && cueName === "msg") return { type: "direct_dm" };
  return { type: "system" };
}

function resolveNotificationForSoundCue(kind, name, notification = null) {
  if (notification && typeof notification === "object") {
    return {
      ...inferNotificationForSoundCue(kind, name),
      ...notification,
    };
  }
  return inferNotificationForSoundCue(kind, name);
}

function shouldSuppressNotificationSoundForStatus(kind, name, notification = null) {
  const cueName = String(name || "").trim().toLowerCase();
  if (!cueName) return false;
  if (!shouldMuteNotificationSoundsNow(resolveNotificationForSoundCue(kind, cueName, notification))) return false;
  if (kind === "sfx") return DND_MUTED_SFX_NAMES.has(cueName);
  if (kind === "ui") return DND_MUTED_UI_CUE_NAMES.has(cueName);
  return false;
}

