function clampRemoteStreamAttenuationStrength(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return REMOTE_STREAM_ATTENUATION_STRENGTH_DEFAULT;
  if (n < 0) return 0;
  if (n > 1) return 1;
  return n;
}

