function applySpatialAudioPreset(preset = "", contextOrRoomId = "") {
  const context = contextOrRoomId && typeof contextOrRoomId === "object"
    ? contextOrRoomId
    : getSpatialAudioServerVoiceContext({ conversationId: contextOrRoomId || getSpatialAudioConversationId() });
  if (!isServerVoiceSpatialAudioContext(context)) return false;
  const tierInfo = getSpatialAudioTierInfo();
  const def = getSpatialAudioPresetDefinition(preset || SPATIAL_AUDIO_DEFAULT_PRESET);
  const allowed = canUseSpatialAudioPreset(def.key, tierInfo);
  logSpatialAudioPlusDebug("feature access", { feature: def.tier === "nova" ? "spatial_audio_advanced_presets" : (def.tier === "core" ? "spatial_audio_personal_presets" : "spatial_audio_basic"), allowed, preset: def.key, tier: tierInfo.tier });
  if (!allowed) return false;
  const current = readSpatialAudioSettings(context);
  const participants = getSpatialAudioRemoteParticipants(context);
  const nextSettings = normalizeSpatialAudioSettings({
    ...current,
    activePreset: def.key,
    blend: def.blend,
    roomSize: def.roomSize,
  });
  const positions = buildSpatialAudioPresetPositions(def.key, participants, nextSettings);
  writeSpatialAudioSettings({
    ...current,
    activePreset: def.key,
    blend: def.blend,
    roomSize: def.roomSize,
    layoutSource: "personal",
    personalPositions: positions,
  }, context, context.localUserId, { debounce: false });
  spatialAudioManager?.entries?.forEach?.((managed) => spatialAudioManager.applyEntryPositionAndGain(managed));
  spatialAudioLastUiSignature = "";
  logSpatialAudioPlusDebug("preset applied", { preset: def.key, positions: getSpatialAudioPositionCount(positions) });
  renderSpatialAudioPrototypeUi(context);
  return true;
}

function getSpatialAudioAutoPosition(userId = "", index = 0, total = 1, settings = null, forcedMode = "") {
  void userId;
  void settings;
  void forcedMode;
  const safeTotal = Math.max(1, Number(total) || 1);
  const safeIndex = Math.max(0, Math.min(safeTotal - 1, Number(index) || 0));
  if (safeTotal === 1) return normalizeSpatialAudioPosition({ x: 0.5, y: 0.35 });
  if (safeTotal === 2) {
    return normalizeSpatialAudioPosition({ x: safeIndex === 0 ? 0.32 : 0.68, y: 0.35 });
  }
  if (safeTotal === 3) {
    const positions = [
      { x: 0.25, y: 0.42 },
      { x: 0.5, y: 0.28 },
      { x: 0.75, y: 0.42 },
    ];
    return normalizeSpatialAudioPosition(positions[safeIndex] || positions[0]);
  }
  if (safeTotal <= 5) {
    const center = (safeTotal - 1) / 2;
    const spread = center > 0 ? (safeIndex - center) / center : 0;
    const edgeLift = Math.abs(spread);
    return normalizeSpatialAudioPosition({
      x: 0.5 + (spread * 0.35),
      y: 0.28 + (edgeLift * 0.16),
    });
  }
  const cols = Math.min(4, Math.max(3, Math.ceil(Math.sqrt(safeTotal))));
  const rows = Math.max(1, Math.ceil(safeTotal / cols));
  const col = safeIndex % cols;
  const row = Math.floor(safeIndex / cols);
  const xMin = 0.16;
  const xMax = 0.84;
  const yMin = 0.16;
  const yMax = Math.min(0.52, 0.28 + (rows * 0.1));
  return normalizeSpatialAudioPosition({
    x: cols <= 1 ? 0.5 : xMin + ((xMax - xMin) * (col / Math.max(1, cols - 1))),
    y: rows <= 1 ? 0.35 : yMin + ((yMax - yMin) * (row / Math.max(1, rows - 1))),
  });
}

function buildSpatialAudioPresetPositions(preset = SPATIAL_AUDIO_DEFAULT_PRESET, participants = [], settings = null) {
  const list = Array.isArray(participants) ? participants : [];
  const safe = normalizeSpatialAudioSettings(settings || getDefaultSpatialAudioSettings());
  const def = getSpatialAudioPresetDefinition(preset || safe.activePreset || SPATIAL_AUDIO_DEFAULT_PRESET);
  const mode = String(def.mode || "arc").trim().toLowerCase();
  const positions = {};
  const total = Math.max(1, list.length);
  list.forEach((participant, index) => {
    const uid = normId(participant?.userId || "");
    if (!uid) return;
    let pos = null;
    if (mode === "front") {
      const spread = total <= 1 ? 0 : (index - ((total - 1) / 2)) / Math.max(1, (total - 1) / 2);
      pos = { x: 0.5 + (spread * 0.24), y: 0.32 + (Math.abs(spread) * 0.08) };
    } else if (mode === "wide") {
      const spread = total <= 1 ? 0 : (index - ((total - 1) / 2)) / Math.max(1, (total - 1) / 2);
      pos = { x: 0.5 + (spread * 0.38), y: 0.34 + (Math.abs(spread) * 0.12) };
    } else if (mode === "close") {
      const spread = total <= 1 ? 0 : (index - ((total - 1) / 2)) / Math.max(1, (total - 1) / 2);
      pos = { x: 0.5 + (spread * 0.2), y: 0.44 + (Math.abs(spread) * 0.05) };
    } else if (mode === "circle" || mode === "table") {
      const start = -Math.PI * 0.78;
      const end = -Math.PI * 0.22;
      const angle = total <= 1 ? -Math.PI / 2 : start + ((end - start) * (index / Math.max(1, total - 1)));
      const radiusX = mode === "table" ? 0.34 : 0.38;
      const radiusY = mode === "table" ? 0.25 : 0.3;
      pos = { x: 0.5 + (Math.cos(angle) * radiusX), y: 0.62 + (Math.sin(angle) * radiusY) };
    } else if (mode === "stage" || mode === "cinema") {
      const spread = total <= 1 ? 0 : (index - ((total - 1) / 2)) / Math.max(1, (total - 1) / 2);
      const row = total > 5 ? Math.floor(index / 5) : 0;
      pos = { x: 0.5 + (spread * (mode === "cinema" ? 0.4 : 0.34)), y: 0.24 + (row * 0.14) + (Math.abs(spread) * 0.04) };
    } else if (mode === "conference") {
      const col = index % 2;
      const row = Math.floor(index / 2);
      const rows = Math.max(1, Math.ceil(total / 2));
      pos = { x: total === 1 ? 0.5 : (col === 0 ? 0.32 : 0.68), y: 0.28 + (Math.min(row, rows - 1) * 0.1) };
    } else {
      pos = getSpatialAudioAutoPosition(uid, index, total, safe);
    }
    positions[uid] = normalizeSpatialAudioPosition(pos);
  });
  return positions;
}

function getDefaultSpatialAudioPosition(userId = "", index = 0, total = 1) {
  return getSpatialAudioAutoPosition(userId, index, total, getSpatialAudioEffectiveSettings(getSpatialAudioServerVoiceContext()));
}

function getSpatialAudioParticipantPosition(userId = "", { roomId = "", localUserId = "", index = 0, total = 1, settings = null, mode = "" } = {}) {
  void mode;
  void localUserId;
  const uid = normId(userId || "");
  if (!uid) return normalizeSpatialAudioPosition(null);
  const context = getSpatialAudioServerVoiceContext({ conversationId: roomId || getSpatialAudioConversationId() });
  const safeSettings = normalizeSpatialAudioSettings(settings || getSpatialAudioEffectiveSettings(context));
  const stored = safeSettings.positions?.[uid] || safeSettings.personalPositions?.[uid] || null;
  if (stored) return normalizeSpatialAudioPosition(stored);
  return getSpatialAudioAutoPosition(uid, index, total, safeSettings);
}

function setSpatialAudioParticipantPosition(userId = "", position = null, { roomId = "", localUserId = "", render = true, debounce = true } = {}) {
  const uid = normId(userId || "");
  if (!uid) return;
  const context = getSpatialAudioServerVoiceContext({ conversationId: roomId || getSpatialAudioConversationId() });
  if (!isServerVoiceSpatialAudioContext(context)) return;
  const actorId = normId(localUserId || context.localUserId || getSpatialAudioLocalUserId());
  if (uid === actorId) return;
  const rid = normId(context.conversationId || "");
  if (!rid) return;
  const current = readSpatialAudioSettings(context, actorId);
  const positions = normalizeSpatialAudioPositions(current.personalPositions);
  positions[uid] = normalizeSpatialAudioPosition(position);
  const saved = writeSpatialAudioSettings({
    ...current,
    layoutSource: "personal",
    personalPositions: positions,
  }, context, actorId, { debounce });
  spatialAudioSelectedParticipantId = uid;
  spatialAudioManager?.setParticipantPosition(uid, saved?.personalPositions?.[uid] || positions[uid], { roomId: rid, localUserId: context.localUserId });
  spatialAudioLastUiSignature = "";
  if (render) renderSpatialAudioPrototypeUi({ conversationId: rid });
}

function getSpatialAudioBlendFactor(settings = null) {
  const safe = normalizeSpatialAudioSettings(settings || getDefaultSpatialAudioSettings());
  return clampSpatialAudioNumber(safe.blend, 0, 100, SPATIAL_AUDIO_DEFAULT_SETTINGS.blend) / 100;
}

function getSpatialAudioRoomScale(settings = null) {
  return getSpatialAudioRoomSizeScale(settings);
}

function getSpatialAudioRoomSizeScale(settings = null) {
  const safe = normalizeSpatialAudioSettings(settings || getDefaultSpatialAudioSettings());
  const roomSize = clampSpatialAudioNumber(safe.roomSize, 1, 10, SPATIAL_AUDIO_DEFAULT_SETTINGS.roomSize);
  return 0.75 + (((roomSize - 1) / 9) * 1.05);
}

function getSpatialAudioMaxReasonableDistance() {
  return 0.82;
}

function isSpatialAudioCornerPosition(position = null) {
  const pos = normalizeSpatialAudioPosition(position);
  return !!((pos.x <= 0.18 || pos.x >= 0.82) && pos.y <= 0.18);
}

function lerpSpatialAudio(a, b, t) {
  return a + ((b - a) * Math.max(0, Math.min(1, Number(t) || 0)));
}

function computeSpatialAudioMetrics(position = null, settings = null, listenerPosition = null) {
  const safe = normalizeSpatialAudioSettings(settings || getSpatialAudioEffectiveSettings(getSpatialAudioServerVoiceContext()));
  const tierInfo = getSpatialAudioTierInfo();
  const hdMode = !!safe.hdEnabled && !!tierInfo.canUseHd;
  const pos = normalizeSpatialAudioPosition(position);
  const listener = normalizeSpatialAudioPosition(listenerPosition || SPATIAL_AUDIO_LISTENER_POSITION);
  const dx = pos.x - listener.x;
  const dy = pos.y - listener.y;
  const distance = Math.sqrt((dx * dx) + (dy * dy));
  const blend = Math.max(0, Math.min(1, getSpatialAudioBlendFactor(safe) * (hdMode ? 1.06 : 1)));
  const roomSizeScale = getSpatialAudioRoomSizeScale(safe) * (hdMode ? 1.03 : 1);
  const normalizedDistance = Math.max(0, Math.min(1, (distance * roomSizeScale) / getSpatialAudioMaxReasonableDistance()));
  const rawPan = Math.max(-1, Math.min(1, dx * 2.2 * roomSizeScale));
  const pan = Math.max(-1, Math.min(1, rawPan * blend));
  const minGain = SPATIAL_AUDIO_MIN_GAIN;
  const gain = Math.max(minGain, Math.min(1, 1 - (normalizedDistance * blend * 0.55 * roomSizeScale)));
  const corner = isSpatialAudioCornerPosition(pos);
  const closeCutoff = hdMode ? 14000 : 12000;
  const farCutoff = corner ? (hdMode ? 3800 : 3600) : (hdMode ? 4700 : 4200);
  const cutoff = Math.max(3200, Math.min(closeCutoff, lerpSpatialAudio(closeCutoff, farCutoff, normalizedDistance * blend)));
  const pannerX = rawPan * 2.35 * blend;
  const pannerZ = -0.55 - (normalizedDistance * 3.1 * blend);
  return {
    position: pos,
    listenerPosition: listener,
    dx,
    dy,
    distance,
    normalizedDistance,
    blend,
    roomSizeScale,
    rawPan,
    pan,
    gain,
    cutoff,
    corner,
    hdMode,
    coords: { x: pannerX, y: 0, z: pannerZ },
  };
}

function getSpatialAudioDistanceGain(position = null, settings = null) {
  return computeSpatialAudioMetrics(position, settings).gain;
}

function getSpatialAudioPan(position = null, settings = null) {
  return computeSpatialAudioMetrics(position, settings).pan;
}

function getSpatialAudioPannerCoords(position = null, settings = null) {
  return computeSpatialAudioMetrics(position, settings).coords;
}

function getSpatialAudioRoomGridPixels(settings = null) {
  const safe = normalizeSpatialAudioSettings(settings || getDefaultSpatialAudioSettings());
  const roomSize = clampSpatialAudioNumber(safe.roomSize, 1, 10, SPATIAL_AUDIO_DEFAULT_SETTINGS.roomSize);
  return Math.round(96 - ((roomSize - 1) * 6.4));
}

function getSpatialAudioQuickActionPosition(action = "", userId = "", participants = []) {
  const uid = normId(userId || "");
  const list = Array.isArray(participants) ? participants : [];
  const index = Math.max(0, list.findIndex((participant) => normId(participant?.userId || "") === uid));
  const normalizedAction = String(action || "").trim().toLowerCase();
  if (normalizedAction === "closer") return normalizeSpatialAudioPosition({ x: 0.5, y: 0.54 });
  if (normalizedAction === "center") return normalizeSpatialAudioPosition({ x: 0.5, y: 0.35 });
  if (normalizedAction === "left") return normalizeSpatialAudioPosition({ x: 0.12, y: 0.35 });
  if (normalizedAction === "right") return normalizeSpatialAudioPosition({ x: 0.88, y: 0.35 });
  if (normalizedAction === "corner") return normalizeSpatialAudioPosition({ x: index % 2 === 0 ? 0.12 : 0.88, y: 0.12 });
  return null;
}

function applySpatialAudioQuickAction(action = "", userId = "") {
  const uid = normId(userId || spatialAudioSelectedParticipantId || "");
  const context = getSpatialAudioServerVoiceContext();
  if (!uid || !isServerVoiceSpatialAudioContext(context)) return;
  if (!canEditSpatialAudioCurrentLayout(context, context.localUserId)) return;
  const participants = getSpatialAudioRemoteParticipants(context);
  const position = getSpatialAudioQuickActionPosition(action, uid, participants);
  if (!position) return;
  setSpatialAudioParticipantPosition(uid, position, {
    roomId: context.conversationId,
    localUserId: context.localUserId,
    render: false,
    debounce: false,
  });
  spatialAudioParticipantMenuOpen = true;
  spatialAudioManager?.entries?.forEach?.((managed) => spatialAudioManager.applyEntryPositionAndGain(managed));
  spatialAudioLastUiSignature = "";
  renderSpatialAudioPrototypeUi(context);
}

function getSpatialAudioParticipantIdentity(userId = "", conversationId = "") {
  const uid = normId(userId || "");
  const convId = normId(conversationId || getSpatialAudioConversationId());
  if (!uid) return { label: t("call.member", "member"), avatar: null };
  const privateIdentity = isPrivateDmLiveKitTransportConversation(convId) ? resolvePrivateCallParticipantIdentity(uid) : null;
  const groupIdentity = getGroupMemberIdentity(convId, uid) || null;
  const serverPresence = getServerVoicePresenceMemberMeta(convId, uid) || null;
  const cached = getCachedProfile(uid) || null;
  const label = String(privateIdentity?.label || groupIdentity?.label || serverPresence?.label || cached?.display_name || cached?.username || t("call.member", "member")).trim() || t("call.member", "member");
  const avatar = String(privateIdentity?.avatar || groupIdentity?.avatar || serverPresence?.avatar || cached?.avatar_url || "").trim() || null;
  return { label, avatar };
}

function getRemoteAudioEntryPlaybackState(entry = null, { anyParticipantSpeaking = isAnyCallParticipantSpeaking(), masterSpeakerVolume = clampVolume01(voiceSpeakerMasterVolume) } = {}) {
  const type = resolveRemoteAudioEntryType(entry);
  const ownerUserId = normId(entry?.ownerUserId || "");
  const source = String(entry?.source || "").trim().toLowerCase();
  const activeConvId = normId(callConversationId || activeDmId || state.activeDm?.conversationId || convId || "");
  const streamPreferenceKey = type === REMOTE_AUDIO_TYPE_SHARE ? (String(entry?.streamPreferenceKey || "").trim() || resolveRemoteAudioEntryStreamPreferenceKey(entry)) : "";
  const userFactor = type === REMOTE_AUDIO_TYPE_SHARE ? 1 : getRemoteUserVoiceVolume(ownerUserId);
  const streamFactor = type === REMOTE_AUDIO_TYPE_SHARE ? getRemoteStreamVolume(streamPreferenceKey) : 1;
  const attenuationEnabled = type === REMOTE_AUDIO_TYPE_SHARE ? getRemoteStreamAttenuationEnabled(streamPreferenceKey) : false;
  const attenuationStrength = type === REMOTE_AUDIO_TYPE_SHARE ? getRemoteStreamAttenuationStrength(streamPreferenceKey) : REMOTE_STREAM_ATTENUATION_STRENGTH_DEFAULT;
  const attenuationFactor = type === REMOTE_AUDIO_TYPE_SHARE && attenuationEnabled && anyParticipantSpeaking ? clampVolume01(1 - attenuationStrength) : 1;
  const baseVolume = type === REMOTE_AUDIO_TYPE_SHARE ? (clampVolume01(remoteShareVolume) * streamFactor * attenuationFactor) : (clampVolume01(remoteVoiceVolume) * userFactor);
  const mixedGain = clampRemoteAudioPlaybackGain(baseVolume * masterSpeakerVolume);
  const typeMuted = type === REMOTE_AUDIO_TYPE_SHARE ? remoteShareMuted : remoteVoiceMuted;
  const userMuted = type === REMOTE_AUDIO_TYPE_SHARE ? false : getRemoteUserVoiceMuted(ownerUserId);
  const streamMuted = type === REMOTE_AUDIO_TYPE_SHARE ? getRemoteStreamMuted(streamPreferenceKey) : false;
  const watchGateMuted = type === REMOTE_AUDIO_TYPE_SHARE && isRemoteShareWatchPromptActive(activeConvId, streamPreferenceKey);
  const isServerVoiceCall = !!(activeConvId && isServerVoiceConversationById(activeConvId));
  const directPeerId = normId(callMediaPeerUserId || callOtherUserId || "");
  const callConnState = String(callPc?.connectionState || "").toLowerCase();
  const callIceState = String(callPc?.iceConnectionState || "").toLowerCase();
  const directPeerConnected = callConnState === "connected" || callIceState === "connected" || callIceState === "completed";
  const duplicateRelayForOwner = !!(isServerVoiceCall && source === "relay" && ownerUserId && ownerUserId === directPeerId && directPeerConnected && hasLiveRemoteAudioTrackFromOwner(ownerUserId, { source: "direct", type }));
  const participantAudioState = activeConvId && ownerUserId ? getCallParticipantAudioState(activeConvId, ownerUserId) : null;
  const transportParticipantState = activeConvId && ownerUserId ? getServerVoiceTransportParticipantState(activeConvId, ownerUserId) : null;
  const remoteParticipantMuted = !!(type === REMOTE_AUDIO_TYPE_VOICE && (participantAudioState?.micMuted === true || transportParticipantState?.audioMuted === true));
  const trackMuted = !!(entry?.track?.muted || String(entry?.track?.readyState || "").toLowerCase() === "ended");
  const outputDeafened = getEffectiveLocalDeafened(activeConvId);
  const muted = !!(outputDeafened || typeMuted || userMuted || streamMuted || watchGateMuted || duplicateRelayForOwner || remoteParticipantMuted || trackMuted);
  return { type, ownerUserId, source, activeConvId, streamPreferenceKey, userFactor, streamFactor, attenuationEnabled, attenuationStrength, attenuationFactor, baseVolume, mixedGain, typeMuted, userMuted, streamMuted, watchGateMuted, duplicateRelayForOwner, remoteParticipantMuted, trackMuted, muted };
}

function isSpatialAudioCallContextActive(conversationId = null) {
  const context = getSpatialAudioServerVoiceContext({ conversationId: conversationId || getSpatialAudioConversationId() });
  return isServerVoiceSpatialAudioContext(context);
}

function isSpatialAudioManagedEntryCandidate(entry = null, playback = null, { ignoreEnabled = false, includeFailed = false } = {}) {
  if (!entry) return false;
  const candidatePlayback = playback || getRemoteAudioEntryPlaybackState(entry);
  const type = candidatePlayback.type || resolveRemoteAudioEntryType(entry);
  const ownerUserId = normId(candidatePlayback.ownerUserId || entry?.ownerUserId || "");
  const meId = getSpatialAudioLocalUserId();
  if (!ownerUserId || (meId && ownerUserId === meId)) return false;
  if (type !== REMOTE_AUDIO_TYPE_VOICE) return false;
  if (String(entry?.source || "").trim().toLowerCase() !== "livekit") return false;
  if (!isLiveAudioTrack(entry?.track || null)) return false;
  if (!includeFailed && entry?.spatialAudioFailed) return false;
  const entryConvId = normId(entry?.conversationId || candidatePlayback.activeConvId || "");
  const context = getSpatialAudioServerVoiceContext({ conversationId: entryConvId });
  if (!isServerVoiceSpatialAudioContext(context)) return false;
  if (entryConvId && entryConvId !== context.conversationId) return false;
  if (!ignoreEnabled) {
    if (!readSpatialAudioDebugEnabled() || !spatialAudioCallEnabled) return false;
  }
  return true;
}

function setSpatialAudioSessionError(message = "") {
  spatialAudioLastError = String(message || "").trim();
  spatialAudioCallEnabled = false;
  spatialAudioRoomOpen = false;
  spatialAudioLastUiSignature = "";
}

function disableSpatialAudioSessionForFailure(message = "Spatial audio failed; using normal audio.") {
  setSpatialAudioSessionError(message);
  disposeSpatialAudioManager({ restoreNative: true, applyVolumes: false });
  setTimeout(() => {
    applyRemoteAudioVolumes();
    renderSpatialAudioPrototypeUi();
  }, 0);
}

function setAudioParamTarget(param = null, value = 0, smoothing = 0.035) {
  if (!param) return;
  const safeValue = Number.isFinite(Number(value)) ? Number(value) : 0;
  try {
    const ctx = param.context || null;
    const at = ctx?.currentTime || spatialAudioManager?.ctx?.currentTime || 0;
    if (typeof param.setTargetAtTime === "function") param.setTargetAtTime(safeValue, at, smoothing);
    else param.value = safeValue;
  } catch (_) {
    try { param.value = safeValue; } catch (_) {}
  }
}

class SpatialAudioManager {
  constructor() {
    this.entries = new Map();
    this.ctx = null;
    this.outputDeviceId = "";
    this.resumeBound = false;
  }

  ensureContext() {
    if (this.ctx) return this.ctx;
    const Ctor = window.AudioContext || window.webkitAudioContext;
    if (!Ctor) return null;
    try {
      this.ctx = new Ctor();
      this.configureListener();
      this.bindResumeOnce();
      void this.setOutputDevice(String(voiceOutputDeviceId || "").trim() || "default");
      void this.resume();
      return this.ctx;
    } catch (error) {
      console.warn("spatial audio context failed", error);
      this.ctx = null;
      return null;
    }
  }

  configureListener() {
    const listener = this.ctx?.listener || null;
    if (!listener) return;
    try {
      if (listener.positionX) {
        listener.positionX.value = 0;
        listener.positionY.value = 0;
        listener.positionZ.value = 0;
      } else if (typeof listener.setPosition === "function") {
        listener.setPosition(0, 0, 0);
      }
      if (listener.forwardX) {
        listener.forwardX.value = 0;
        listener.forwardY.value = 0;
        listener.forwardZ.value = -1;
        listener.upX.value = 0;
        listener.upY.value = 1;
        listener.upZ.value = 0;
      } else if (typeof listener.setOrientation === "function") {
        listener.setOrientation(0, 0, -1, 0, 1, 0);
      }
    } catch (_) {}
  }

  bindResumeOnce() {
    if (this.resumeBound) return;
    this.resumeBound = true;
    const resume = () => { void this.resume(); };
    window.addEventListener("pointerdown", resume, { capture: true, passive: true });
    window.addEventListener("keydown", resume, true);
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "visible") void this.resume();
    });
  }

  async resume() {
    const ctx = this.ensureContext();
    if (!ctx || ctx.state !== "suspended") return;
    try { await ctx.resume(); } catch (_) {}
  }

  async setOutputDevice(deviceId = "default") {
    const ctx = this.ensureContext();
    if (!ctx || typeof ctx.setSinkId !== "function") return false;
    const sinkId = String(deviceId || "").trim() || "default";
    if (this.outputDeviceId === sinkId) return true;
    try {
      await ctx.setSinkId(sinkId);
      this.outputDeviceId = sinkId;
      return true;
    } catch (error) {
      console.warn("spatial audio setSinkId failed", error);
      if (sinkId !== "default") {
        try {
          await ctx.setSinkId("default");
          this.outputDeviceId = "default";
        } catch (_) {}
      }
      return false;
    }
  }

ensureEntry(entry = null, playback = null) {
    if (!entry?.track) return false;
    const key = normId(entry.id || entry.track.id || "");
    if (!key) return false;
    const existing = this.entries.get(key) || null;
    if (existing && existing.track === entry.track) {
      existing.entry = entry;
      this.updateEntryPlayback(entry, playback);
      return true;
    }
    if (existing) this.removeTrack(key, { restoreNative: true });
    const ctx = this.ensureContext();
    if (!ctx || typeof ctx.createMediaStreamSource !== "function") return false;

    let stream = null;
    let sourceNode = null;
    let gainNode = null;
    let filterNode = null;
    let spatialNode = null;
    let panNode = null;
    let spatialMode = "panner";
    try {
      stream = new MediaStream();
      stream.addTrack(entry.track);
      sourceNode = ctx.createMediaStreamSource(stream);
      gainNode = ctx.createGain();
      gainNode.gain.value = 0;
      filterNode = ctx.createBiquadFilter();
      filterNode.type = "lowpass";
      filterNode.frequency.value = 12000;
      filterNode.Q.value = 0.45;
      try {
        spatialNode = ctx.createPanner();
        spatialNode.panningModel = "HRTF";
        spatialNode.distanceModel = "linear";
        spatialNode.refDistance = 1;
        spatialNode.maxDistance = 10;
        spatialNode.rolloffFactor = 0;
        spatialNode.coneInnerAngle = 360;
        spatialNode.coneOuterAngle = 360;
        spatialMode = "panner";
      } catch (_) {
        spatialNode = null;
      }
      if (typeof ctx.createStereoPanner === "function") panNode = ctx.createStereoPanner();
      if (!spatialNode) {
        if (!panNode) throw new Error("StereoPanner unavailable");
        spatialNode = panNode;
        spatialMode = "stereo";
      }
      sourceNode.connect(gainNode);
      gainNode.connect(filterNode);
      filterNode.connect(spatialNode);
      if (spatialMode === "panner" && panNode) {
        spatialNode.connect(panNode);
        panNode.connect(ctx.destination);
      } else {
        spatialNode.connect(ctx.destination);
      }
    } catch (error) {
      try { sourceNode?.disconnect?.(); } catch (_) {}
      try { gainNode?.disconnect?.(); } catch (_) {}
      try { filterNode?.disconnect?.(); } catch (_) {}
      try { spatialNode?.disconnect?.(); } catch (_) {}
      try { panNode?.disconnect?.(); } catch (_) {}
      this.handleEntryFailure(entry, error);
      return false;
    }

    const managed = {
      id: key,
      entry,
      track: entry.track,
      ownerUserId: normId(entry.ownerUserId || ""),
      conversationId: normId(entry.conversationId || callConversationId || activeDmId || ""),
      stream,
      sourceNode,
      gainNode,
      filterNode,
      spatialNode,
      panNode,
      spatialMode,
      playbackGain: 0,
      muted: true,
      lastComputedAudio: null,
      onTrackMute: null,
      onTrackUnmute: null,
      onTrackEnded: null,
    };
    managed.onTrackMute = () => this.updateEntryPlayback(entry, getRemoteAudioEntryPlaybackState(entry));
    managed.onTrackUnmute = () => {
      void this.resume();
      this.updateEntryPlayback(entry, getRemoteAudioEntryPlaybackState(entry));
    };
    managed.onTrackEnded = () => this.removeTrack(key, { restoreNative: false });
    try { entry.track.addEventListener?.("mute", managed.onTrackMute); } catch (_) {}
    try { entry.track.addEventListener?.("unmute", managed.onTrackUnmute); } catch (_) {}
    try { entry.track.addEventListener?.("ended", managed.onTrackEnded, { once: true }); } catch (_) {}

    this.entries.set(key, managed);
    entry.spatialAudioManaged = true;
    entry.spatialAudioFailed = false;
    this.forceNativeElementSilent(entry);
    this.updateEntryPlayback(entry, playback);
    return true;
  }

  forceNativeElementSilent(entry = null) {
    const audioEl = entry?.audioEl || null;
    if (!(audioEl instanceof HTMLMediaElement)) return;
    try { audioEl.dataset.spatialAudioManaged = "1"; } catch (_) {}
    try { audioEl.volume = 0; } catch (_) {}
    try { audioEl.muted = true; } catch (_) {}
  }

  restoreNativeElement(entry = null) {
    const audioEl = entry?.audioEl || null;
    if (!(audioEl instanceof HTMLMediaElement)) return;
    try { delete audioEl.dataset.spatialAudioManaged; } catch (_) {}
  }

  updateEntryPlayback(entry = null, playback = null) {
    if (!entry) return false;
    const key = normId(entry.id || entry.track?.id || "");
    const managed = this.entries.get(key) || null;
    if (!managed) return false;
    const state = playback || getRemoteAudioEntryPlaybackState(entry);
    managed.entry = entry;
    managed.ownerUserId = normId(entry.ownerUserId || managed.ownerUserId || "");
    managed.conversationId = normId(entry.conversationId || managed.conversationId || callConversationId || activeDmId || "");
    managed.playbackGain = clampRemoteAudioPlaybackGain(state.mixedGain);
    managed.muted = !!state.muted;
    this.forceNativeElementSilent(entry);
    this.applyEntryPositionAndGain(managed);
    return true;
  }

applyEntryPositionAndGain(managed = null) {
    if (!managed?.gainNode) return;
    const context = getSpatialAudioServerVoiceContext({ conversationId: managed.conversationId });
    const settings = getSpatialAudioEffectiveSettings(context);
    const participants = getSpatialAudioParticipantsForLayout(context, settings.layoutSource);
    const index = Math.max(0, participants.findIndex((participant) => participant.userId === managed.ownerUserId));
    const position = getSpatialAudioParticipantPosition(managed.ownerUserId, {
      roomId: context.conversationId || managed.conversationId,
      localUserId: context.localUserId || getSpatialAudioLocalUserId(),
      index,
      total: Math.max(1, participants.length),
      settings,
    });
    const listenerPosition = getSpatialAudioListenerPosition(context, settings);
    const metrics = computeSpatialAudioMetrics(position, settings, listenerPosition);
    const targetGain = managed.muted ? 0 : clampRemoteAudioPlaybackGain(managed.playbackGain * metrics.gain);
    setAudioParamTarget(managed.gainNode.gain, targetGain, 0.055);
    if (managed.filterNode?.frequency) setAudioParamTarget(managed.filterNode.frequency, metrics.cutoff, 0.08);
    managed.lastComputedAudio = {
      pan: metrics.pan,
      gain: metrics.gain,
      effectiveGain: targetGain,
      cutoff: metrics.cutoff,
      distance: metrics.distance,
      normalizedDistance: metrics.normalizedDistance,
      position: metrics.position,
      listenerPosition: metrics.listenerPosition,
    };
    this.applyEntryPosition(managed, position, settings, metrics);
  }

applyEntryPosition(managed = null, position = null, settings = null, metrics = null) {
    if (!managed?.spatialNode) return;
    const pos = normalizeSpatialAudioPosition(position);
    const safeSettings = normalizeSpatialAudioSettings(settings || getSpatialAudioEffectiveSettings(getSpatialAudioServerVoiceContext({ conversationId: managed.conversationId })));
    const audioMetrics = metrics || computeSpatialAudioMetrics(pos, safeSettings);
    try {
      if (managed.spatialMode === "panner") {
        const coords = audioMetrics.coords || getSpatialAudioPannerCoords(pos, safeSettings);
        const node = managed.spatialNode;
        if (node.positionX) {
          setAudioParamTarget(node.positionX, coords.x, 0.055);
          setAudioParamTarget(node.positionY, coords.y, 0.055);
          setAudioParamTarget(node.positionZ, coords.z, 0.055);
        } else if (typeof node.setPosition === "function") {
          node.setPosition(coords.x, coords.y, coords.z);
        }
        if (managed.panNode?.pan) setAudioParamTarget(managed.panNode.pan, audioMetrics.pan, 0.055);
        return;
      }
      if (managed.spatialNode.pan) setAudioParamTarget(managed.spatialNode.pan, audioMetrics.pan, 0.055);
    } catch (error) {
      if (managed.spatialMode === "panner" && this.fallbackEntryToStereo(managed)) {
        this.applyEntryPosition(managed, pos, safeSettings, audioMetrics);
        return;
      }
      this.handleEntryFailure(managed.entry, error);
    }
  }

fallbackEntryToStereo(managed = null) {
    const ctx = this.ensureContext();
    if (!managed?.filterNode || !ctx || typeof ctx.createStereoPanner !== "function") return false;
    try {
      const stereoNode = ctx.createStereoPanner();
      try { managed.spatialNode?.disconnect?.(); } catch (_) {}
      try { managed.panNode?.disconnect?.(); } catch (_) {}
      try { managed.filterNode?.disconnect?.(); } catch (_) {}
      managed.filterNode.connect(stereoNode);
      stereoNode.connect(ctx.destination);
      managed.spatialNode = stereoNode;
      managed.panNode = stereoNode;
      managed.spatialMode = "stereo";
      return true;
    } catch (_) {
      return false;
    }
  }

  setParticipantPosition(userId = "", position = null, opts = {}) {
    void position;
    void opts;
    const uid = normId(userId || "");
    if (!uid) return;
    for (const managed of this.entries.values()) {
      if (normId(managed.ownerUserId || "") !== uid) continue;
      this.applyEntryPositionAndGain(managed);
    }
  }

  hasEntry(trackId = "") {
    return this.entries.has(normId(trackId || ""));
  }

removeTrack(trackId = "", { restoreNative = true } = {}) {
    const key = normId(trackId || "");
    if (!key) return;
    const managed = this.entries.get(key) || null;
    if (!managed) return;
    try { managed.sourceNode?.disconnect?.(); } catch (_) {}
    try { managed.gainNode?.disconnect?.(); } catch (_) {}
    try { managed.filterNode?.disconnect?.(); } catch (_) {}
    try { managed.spatialNode?.disconnect?.(); } catch (_) {}
    try {
      if (managed.panNode && managed.panNode !== managed.spatialNode) managed.panNode.disconnect?.();
    } catch (_) {}
    try {
      if (managed.track?.removeEventListener) {
        if (managed.onTrackMute) managed.track.removeEventListener("mute", managed.onTrackMute);
        if (managed.onTrackUnmute) managed.track.removeEventListener("unmute", managed.onTrackUnmute);
        if (managed.onTrackEnded) managed.track.removeEventListener("ended", managed.onTrackEnded);
      }
    } catch (_) {}
    if (managed.entry) {
      managed.entry.spatialAudioManaged = false;
      if (restoreNative) this.restoreNativeElement(managed.entry);
    }
    this.entries.delete(key);
  }

  pruneToTrackIds(trackIds = new Set()) {
    const keep = trackIds instanceof Set ? trackIds : new Set();
    for (const key of Array.from(this.entries.keys())) {
      if (!keep.has(key)) this.removeTrack(key, { restoreNative: true });
    }
  }

  handleEntryFailure(entry = null, error = null) {
    if (entry) {
      const key = normId(entry.id || entry.track?.id || "");
      if (key) this.removeTrack(key, { restoreNative: true });
      entry.spatialAudioManaged = false;
      entry.spatialAudioFailed = true;
      this.restoreNativeElement(entry);
    }
    console.warn("spatial audio fallback to native playback", error);
    disableSpatialAudioSessionForFailure("Spatial audio failed; using normal audio.");
  }

  dispose({ restoreNative = true } = {}) {
    for (const key of Array.from(this.entries.keys())) this.removeTrack(key, { restoreNative });
    if (this.ctx) {
      try { this.ctx.close?.().catch?.(() => {}); } catch (_) {}
      this.ctx = null;
    }
    this.outputDeviceId = "";
  }
}

function ensureSpatialAudioManager(context = null) {
  const spatialContext = getSpatialAudioServerVoiceContext(context || {});
  if (!readSpatialAudioDebugEnabled() || !spatialAudioCallEnabled) return null;
  if (!isServerVoiceSpatialAudioContext(spatialContext)) return null;
  if (!syncSpatialAudioActiveContext(spatialContext)) return null;
  if (!spatialAudioManager) spatialAudioManager = new SpatialAudioManager();
  if (!spatialAudioManager.ensureContext()) {
    disableSpatialAudioSessionForFailure("Web Audio is unavailable; using normal audio.");
    return null;
  }
  return spatialAudioManager;
}

function disposeSpatialAudioManager({ restoreNative = true, applyVolumes = true, clearContext = true } = {}) {
  if (spatialAudioManager) {
    spatialAudioManager.dispose({ restoreNative });
    spatialAudioManager = null;
    if (applyVolumes) applyRemoteAudioVolumes();
  }
  if (clearContext) spatialAudioActiveContextKey = "";
}

function syncSpatialAudioEntryPlayback(entry = null, playback = null) {
  const key = normId(entry?.id || entry?.track?.id || "");
  if (!key) return false;
  const shouldSpatialize = isSpatialAudioManagedEntryCandidate(entry, playback) && isSpatialAudioEntryWithinParticipantLimit(entry, playback);
  if (!shouldSpatialize) {
    spatialAudioManager?.removeTrack(key, { restoreNative: true });
    return false;
  }
  const manager = ensureSpatialAudioManager({ conversationId: playback?.activeConvId || entry?.conversationId || "" });
  if (!manager) return false;
  if (!manager.ensureEntry(entry, playback)) return false;
  manager.updateEntryPlayback(entry, playback);
  return manager.hasEntry(key);
}

function getSpatialAudioEligibleTrackIdSet() {
  const keepIds = new Set();
  const anyParticipantSpeaking = isAnyCallParticipantSpeaking();
  const masterSpeakerVolume = clampVolume01(voiceSpeakerMasterVolume);
  for (const entry of remoteAudioTrackEls.values()) {
    if (!entry) continue;
    const playback = getRemoteAudioEntryPlaybackState(entry, { anyParticipantSpeaking, masterSpeakerVolume });
    const key = normId(entry.id || entry.track?.id || "");
    if (key && isSpatialAudioManagedEntryCandidate(entry, playback) && isSpatialAudioEntryWithinParticipantLimit(entry, playback)) keepIds.add(key);
  }
  return keepIds;
}

function pruneSpatialAudioManagerToEligibleTracks() {
  if (!spatialAudioManager) return;
  spatialAudioManager.pruneToTrackIds(getSpatialAudioEligibleTrackIdSet());
}

function getSpatialAudioRemoteAudioTrackCount(context = null) {
  const spatialContext = context && typeof context === "object" && Object.prototype.hasOwnProperty.call(context, "serverId")
    ? context
    : getSpatialAudioServerVoiceContext(context || {});
  if (!isServerVoiceSpatialAudioContext(spatialContext)) return 0;
  const convId = normId(spatialContext.conversationId || "");
  let count = 0;
  for (const entry of remoteAudioTrackEls.values()) {
    if (!entry || normId(entry?.conversationId || "") !== convId) continue;
    const playback = getRemoteAudioEntryPlaybackState(entry);
    if (isSpatialAudioManagedEntryCandidate(entry, playback, { ignoreEnabled: true, includeFailed: true })) count += 1;
  }
  return count;
}

function getSpatialAudioParticipantLimitState(context = null) {
  const spatialContext = context && typeof context === "object" && Object.prototype.hasOwnProperty.call(context, "serverId")
    ? context
    : getSpatialAudioServerVoiceContext(context || {});
  const tierInfo = getSpatialAudioTierInfo();
  const participants = isServerVoiceSpatialAudioContext(spatialContext) ? getSpatialAudioRemoteParticipants(spatialContext) : [];
  const total = participants.length;
  const limit = tierInfo.participantLimit;
  const spatializedCount = Number.isFinite(limit) ? Math.min(total, Math.max(0, Number(limit) || 0)) : total;
  const allowedUserIds = new Set(participants.slice(0, spatializedCount).map((participant) => normId(participant?.userId || "")).filter(Boolean));
  const limited = Number.isFinite(limit) && total > limit;
  return {
    tier: tierInfo.tier,
    limit,
    total,
    spatializedCount,
    limited,
    allowedUserIds,
    canUnlockMore: tierInfo.tier === "free" || tierInfo.tier === "core",
    label: tierInfo.tier === "nova"
      ? "All speakers spatialized"
      : String(spatializedCount) + " speakers spatialized" + (tierInfo.tier === "free" && limited ? " ? ALTARA+ Core unlocks more" : ""),
  };
}

function isSpatialAudioOwnerWithinParticipantLimit(ownerUserId = "", context = null) {
  const uid = normId(ownerUserId || "");
  if (!uid) return false;
  const state = getSpatialAudioParticipantLimitState(context);
  if (!Number.isFinite(state.limit)) return true;
  if (!state.limited) return true;
  return state.allowedUserIds.has(uid);
}

function isSpatialAudioEntryWithinParticipantLimit(entry = null, playback = null) {
  const ownerUserId = normId(playback?.ownerUserId || entry?.ownerUserId || "");
  const convId = normId(entry?.conversationId || playback?.activeConvId || "");
  const context = getSpatialAudioServerVoiceContext({ conversationId: convId || getSpatialAudioConversationId() });
  return isSpatialAudioOwnerWithinParticipantLimit(ownerUserId, context);
}

function syncSpatialAudioForRemoteAudioEntries() {
  const context = getSpatialAudioServerVoiceContext();
  if (!readSpatialAudioDebugEnabled() || !spatialAudioCallEnabled || !isServerVoiceSpatialAudioContext(context)) {
    disposeSpatialAudioManager({ restoreNative: true, applyVolumes: false });
    return;
  }

  const limitState = getSpatialAudioParticipantLimitState(context);
  if (limitState.limited) {
    logSpatialAudioPlusDebug("participant limit applied", { tier: limitState.tier, limit: limitState.limit, total: limitState.total, spatialized: limitState.spatializedCount });
  }

  const candidates = [];
  const anyParticipantSpeaking = isAnyCallParticipantSpeaking();
  const masterSpeakerVolume = clampVolume01(voiceSpeakerMasterVolume);
  for (const entry of remoteAudioTrackEls.values()) {
    if (!entry) continue;
    const playback = getRemoteAudioEntryPlaybackState(entry, { anyParticipantSpeaking, masterSpeakerVolume });
    const key = normId(entry.id || entry.track?.id || "");
    const withinLimit = isSpatialAudioEntryWithinParticipantLimit(entry, playback);
    if (isSpatialAudioManagedEntryCandidate(entry, playback) && withinLimit) candidates.push({ entry, playback, key });
    else if (key) spatialAudioManager?.removeTrack(key, { restoreNative: true });
  }

  if (!candidates.length) {
    disposeSpatialAudioManager({ restoreNative: true, applyVolumes: false, clearContext: false });
    return;
  }

  const manager = ensureSpatialAudioManager(context);
  if (!manager) return;
  const keepIds = new Set();
  for (const item of candidates) {
    if (manager.ensureEntry(item.entry, item.playback)) {
      manager.updateEntryPlayback(item.entry, item.playback);
      if (item.key) keepIds.add(item.key);
    }
  }
  manager.pruneToTrackIds(keepIds);
}

function getSpatialAudioRemoteParticipants(context = null) {
  const spatialContext = context && typeof context === "object" && Object.prototype.hasOwnProperty.call(context, "serverId")
    ? context
    : getSpatialAudioServerVoiceContext(context || {});
  if (!isServerVoiceSpatialAudioContext(spatialContext)) return [];
  const convId = normId(spatialContext.conversationId || "");
  const meId = getSpatialAudioLocalUserId();
  const participantIds = new Set(getServerVoiceInCallParticipantIds(convId, {
    triggerReason: "spatial_audio_room_participants",
    callerFunction: "getSpatialAudioRemoteParticipants",
  }));
  const hasAuthoritativeIds = participantIds.size > 0;
  const byUser = new Map();
  for (const entry of remoteAudioTrackEls.values()) {
    if (!entry) continue;
    if (normId(entry?.conversationId || "") !== convId) continue;
    const playback = getRemoteAudioEntryPlaybackState(entry);
    if (!isSpatialAudioManagedEntryCandidate(entry, playback, { ignoreEnabled: true, includeFailed: true })) continue;
    const uid = normId(playback.ownerUserId || entry.ownerUserId || "");
    if (!uid || (meId && uid === meId)) continue;
    if (hasAuthoritativeIds && !participantIds.has(uid)) continue;
    let item = byUser.get(uid) || null;
    if (!item) {
      const identity = getSpatialAudioParticipantIdentity(uid, convId);
      item = { userId: uid, label: identity.label, avatar: identity.avatar, trackIds: [], muted: true, speaking: false, failed: false };
      byUser.set(uid, item);
    }
    const trackId = normId(entry.id || entry.track?.id || "");
    if (trackId && !item.trackIds.includes(trackId)) item.trackIds.push(trackId);
    item.muted = item.muted && !!playback.muted;
    item.speaking = item.speaking || isCallSpeakingUiUserActive(uid);
    item.failed = item.failed || !!entry.spatialAudioFailed;
  }
  for (const uidRaw of participantIds) {
    const uid = normId(uidRaw || "");
    if (!uid || (meId && uid === meId) || byUser.has(uid)) continue;
    const identity = getSpatialAudioParticipantIdentity(uid, convId);
    byUser.set(uid, { userId: uid, label: identity.label, avatar: identity.avatar, trackIds: [], muted: true, speaking: false, failed: false });
  }
  return Array.from(byUser.values()).sort((a, b) => a.label.localeCompare(b.label));
}

function getSpatialAudioServerRoomParticipants(context = null) {
  const spatialContext = context && typeof context === "object" && Object.prototype.hasOwnProperty.call(context, "serverId")
    ? context
    : getSpatialAudioServerVoiceContext(context || {});
  if (!isServerVoiceSpatialAudioContext(spatialContext)) return [];
  const convId = normId(spatialContext.conversationId || "");
  const meId = getSpatialAudioLocalUserId();
  const participantIds = new Set(getServerVoiceInCallParticipantIds(convId, {
    triggerReason: "spatial_audio_server_room_participants",
    callerFunction: "getSpatialAudioServerRoomParticipants",
  }));
  if (meId) participantIds.add(meId);
  const byUser = new Map();
  const ensureParticipant = (uidRaw) => {
    const uid = normId(uidRaw || "");
    if (!uid) return null;
    let item = byUser.get(uid) || null;
    if (item) return item;
    const identity = getSpatialAudioParticipantIdentity(uid, convId);
    const isSelf = !!(meId && uid === meId);
    const baseLabel = String(identity.label || t("call.member", "member")).trim() || t("call.member", "member");
    item = {
      userId: uid,
      label: isSelf ? baseLabel + " (You)" : baseLabel,
      avatar: identity.avatar,
      trackIds: [],
      muted: false,
      speaking: isCallSpeakingUiUserActive(uid),
      failed: false,
      isSelf,
    };
    byUser.set(uid, item);
    return item;
  };
  for (const uid of participantIds) ensureParticipant(uid);
  for (const entry of remoteAudioTrackEls.values()) {
    if (!entry) continue;
    if (normId(entry?.conversationId || "") !== convId) continue;
    const playback = getRemoteAudioEntryPlaybackState(entry);
    const type = playback.type || resolveRemoteAudioEntryType(entry);
    if (type !== REMOTE_AUDIO_TYPE_VOICE) continue;
    const uid = normId(playback.ownerUserId || entry.ownerUserId || "");
    if (!uid) continue;
    const item = ensureParticipant(uid);
    if (!item) continue;
    const trackId = normId(entry.id || entry.track?.id || "");
    if (trackId && !item.trackIds.includes(trackId)) item.trackIds.push(trackId);
    item.muted = !!playback.muted;
    item.speaking = item.speaking || isCallSpeakingUiUserActive(uid);
    item.failed = item.failed || !!entry.spatialAudioFailed;
  }
  return Array.from(byUser.values()).sort((a, b) => {
    if (a.isSelf && !b.isSelf) return -1;
    if (!a.isSelf && b.isSelf) return 1;
    return String(a.label || "").localeCompare(String(b.label || ""));
  });
}

function getSpatialAudioParticipantsForLayout(context = null, layoutSource = "") {
  void layoutSource;
  return getSpatialAudioRemoteParticipants(context);
}

function getSpatialAudioListenerPosition(contextOrRoomId = "", settings = null) {
  void contextOrRoomId;
  void settings;
  return normalizeSpatialAudioPosition(SPATIAL_AUDIO_LISTENER_POSITION);
}

function getSpatialAudioChannelLabel(context = null) {
  const ctx = context && typeof context === "object" && Object.prototype.hasOwnProperty.call(context, "conversationId")
    ? context
    : getSpatialAudioServerVoiceContext(context || {});
  const convId = normId(ctx?.conversationId || "");
  const channelCtx = findServerChannelContextByConversationId(convId) || null;
  const meta = getActiveConversationMeta(convId) || getConversationMeta(convId) || {};
  const raw = String(
    channelCtx?.channel?.name
    || channelCtx?.channel?.displayName
    || channelCtx?.channel?.label
    || meta?.displayName
    || meta?.name
    || meta?.title
    || "Voice"
  ).trim().replace(/^#\s*/, "");
  return "# " + (raw || "Voice");
}

function hideSpatialAudioPrototypeUi({ closeRoom = true } = {}) {
  const controlsGroup = document.getElementById("spatialAudioControls");
  const overlay = document.getElementById("spatialAudioRoomOverlay");
  const popover = document.getElementById("spatialAudioPopover");
  const participantMenu = document.getElementById("spatialAudioParticipantMenu");
  const miniBtn = document.getElementById("btnSpatialAudioMenuSmall");
  if (closeRoom) spatialAudioRoomOpen = false;
  spatialAudioPopoverOpen = false;
  closeSpatialAudioParticipantMenu({ render: false });
  spatialAudioDragState = null;
  spatialAudioLastUiSignature = "";
  if (controlsGroup) {
    controlsGroup.hidden = true;
    controlsGroup.style.display = "none";
  }
  if (miniBtn) {
    miniBtn.hidden = true;
    miniBtn.style.display = "none";
    miniBtn.classList.remove("is-on", "is-error");
    miniBtn.setAttribute("aria-expanded", "false");
  }
  if (popover) {
    popover.hidden = true;
    popover.setAttribute("aria-hidden", "true");
  }
  if (participantMenu) {
    participantMenu.hidden = true;
    participantMenu.setAttribute("aria-hidden", "true");
  }
  if (overlay) {
    overlay.hidden = true;
    overlay.setAttribute("aria-hidden", "true");
  }
}

function getSpatialAudioPopoverAnchorElement() {
  const preferred = spatialAudioPopoverAnchorId ? document.getElementById(spatialAudioPopoverAnchorId) : null;
  if (preferred && !preferred.hidden && preferred.getClientRects?.().length) return preferred;
  const fallbackIds = ["btnSpatialAudioMenu", "btnSpatialAudioMenuSmall"];
  for (const id of fallbackIds) {
    const el = document.getElementById(id);
    if (el && !el.hidden && el.getClientRects?.().length) return el;
  }
  return document.getElementById("callBar") || document.querySelector("#callStage .callStageControls") || null;
}

function openSpatialAudioPopover(anchorEl = null, { toggle = false } = {}) {
  const anchorId = String(anchorEl?.id || "").trim();
  const wasOpen = !!spatialAudioPopoverOpen;
  const sameAnchor = !!(anchorId && anchorId === spatialAudioPopoverAnchorId);
  if (anchorId) spatialAudioPopoverAnchorId = anchorId;
  spatialAudioRoomOpen = false;
  spatialAudioPopoverOpen = toggle ? !(wasOpen && sameAnchor) : true;
  spatialAudioLastUiSignature = "";
  renderSpatialAudioPrototypeUi();
}

function getSpatialAudioPopoverBlockedLeftEdge(viewportW = 0) {
  const selectors = [
    ".panel.left",
    ".leftDock",
    ".leftDockGroups",
    ".leftDockDms",
    "#serverChannelsPanel",
    ".serverChannelsPanel",
    ".voiceMiniDockSlot",
    "#callBar.is-docked-in-sidebar",
  ];
  const seen = new Set();
  let blockedRight = 0;
  selectors.forEach((selector) => {
    document.querySelectorAll(selector).forEach((el) => {
      if (!el || seen.has(el)) return;
      seen.add(el);
      const style = window.getComputedStyle?.(el) || null;
      if (style && (style.display === "none" || style.visibility === "hidden")) return;
      const rect = el.getBoundingClientRect?.();
      if (!rect || rect.width < 24 || rect.height < 24) return;
      if (rect.right <= 0 || rect.left >= viewportW) return;
      const isLeftChrome = rect.left <= 120 || el.matches?.(".panel.left, .leftDock, .leftDockGroups, .leftDockDms, #serverChannelsPanel, .serverChannelsPanel, .voiceMiniDockSlot, #callBar.is-docked-in-sidebar");
      if (!isLeftChrome) return;
      if (rect.right > viewportW - 48) return;
      blockedRight = Math.max(blockedRight, Math.min(viewportW, rect.right));
    });
  });
  return Math.max(0, blockedRight);
}

function positionSpatialAudioPopover() {
  const popover = document.getElementById("spatialAudioPopover");
  if (!popover || popover.hidden) return;
  const viewportW = Math.max(320, window.innerWidth || document.documentElement?.clientWidth || 320);
  const viewportH = Math.max(240, window.innerHeight || document.documentElement?.clientHeight || 240);
  const margin = 12;
  const gap = 8;
  const maxHeight = Math.max(220, Math.min(720, viewportH - (margin * 2)));
  popover.style.maxHeight = maxHeight + "px";
  popover.style.overflowY = "auto";
  popover.style.overscrollBehavior = "contain";
  popover.style.right = "auto";
  popover.style.bottom = "auto";
  popover.style.width = "";

  const anchor = getSpatialAudioPopoverAnchorElement();
  const anchorRect = anchor?.getBoundingClientRect?.() || { left: viewportW - 24, right: viewportW - 24, top: viewportH - 76, bottom: viewportH - 44, width: 0, height: 0 };
  const blockedLeftEdge = getSpatialAudioPopoverBlockedLeftEdge(viewportW);
  const blockedMinLeft = blockedLeftEdge > 0 ? blockedLeftEdge + gap : margin;
  const naturalRect = popover.getBoundingClientRect();
  const naturalWidth = Math.min(naturalRect.width || 372, viewportW - (margin * 2));
  const availableRightOfSidebar = viewportW - blockedMinLeft - margin;
  const canFitRightOfSidebar = blockedLeftEdge > 0 && availableRightOfSidebar >= 260;
  const width = Math.max(240, Math.min(naturalWidth, canFitRightOfSidebar ? availableRightOfSidebar : viewportW - (margin * 2)));
  popover.style.width = Math.round(width) + "px";

  const measuredRect = popover.getBoundingClientRect();
  const height = Math.min(measuredRect.height || maxHeight, maxHeight);
  let left = Number(anchorRect.right || 0) - width;
  if (!Number.isFinite(left)) left = viewportW - width - margin;
  if (Number(anchorRect.right || 0) <= blockedMinLeft + 16 && canFitRightOfSidebar) {
    left = blockedMinLeft;
  }
  left = Math.max(margin, Math.min(left, viewportW - width - margin));
  if (canFitRightOfSidebar) left = Math.max(blockedMinLeft, left);
  left = Math.min(left, viewportW - width - margin);

  const spaceAbove = Number(anchorRect.top || 0) - margin;
  const spaceBelow = viewportH - Number(anchorRect.bottom || 0) - margin;
  let top = spaceBelow >= Math.min(height, 360)
    ? Number(anchorRect.bottom || 0) + gap
    : Number(anchorRect.top || 0) - height - gap;
  if (spaceAbove < height && spaceBelow > spaceAbove) top = Number(anchorRect.bottom || 0) + gap;
  top = Math.max(margin, Math.min(top, viewportH - height - margin));
  popover.style.left = Math.round(left) + "px";
  popover.style.top = Math.round(top) + "px";
}

