function resetCallAudioToSafeDefaults({ resetPerUserVolumes = false } = {}) {
  let changed = false;
  if (micMuted) {
    micMuted = false;
    changed = true;
  }
  if (deafened) {
    deafened = false;
    changed = true;
  }
  if (remoteVoiceMuted) {
    remoteVoiceMuted = false;
    try { writeUserScopedVoiceStorageRaw(REMOTE_VOICE_MUTED_KEY, "0"); } catch (_) {}
    changed = true;
  }
  if (remoteShareMuted) {
    remoteShareMuted = false;
    try { writeUserScopedVoiceStorageRaw(REMOTE_SHARE_MUTED_KEY, "0"); } catch (_) {}
    changed = true;
  }
  if (!Number.isFinite(remoteVoiceVolume) || remoteVoiceVolume <= 0.001) {
    remoteVoiceVolume = 1;
    try { writeUserScopedVoiceStorageRaw(REMOTE_VOICE_VOLUME_KEY, "1"); } catch (_) {}
    changed = true;
  }
  if (!Number.isFinite(remoteShareVolume) || remoteShareVolume <= 0.001) {
    remoteShareVolume = 1;
    try { writeUserScopedVoiceStorageRaw(REMOTE_SHARE_VOLUME_KEY, "1"); } catch (_) {}
    changed = true;
  }
  if (!Number.isFinite(voiceSpeakerMasterVolume) || voiceSpeakerMasterVolume <= 0.001) {
    voiceSpeakerMasterVolume = 1;
    saveVoiceVideoPref(VOICE_SPEAKER_MASTER_VOLUME_KEY, "1");
    changed = true;
  }
  if (!Number.isFinite(voiceMicGain) || voiceMicGain <= 0.001) {
    voiceMicGain = VOICE_MIC_GAIN_DEFAULT;
    saveVoiceVideoPref(VOICE_MIC_GAIN_KEY, String(VOICE_MIC_GAIN_DEFAULT));
    changed = true;
  }
  if (resetPerUserVolumes && remoteUserVoiceVolumeByUserId.size) {
    remoteUserVoiceVolumeByUserId.clear();
    persistRemoteUserVoiceVolumePrefs();
    changed = true;
  }
  if (resetPerUserVolumes && remoteUserVoiceMutedByUserId.size) {
    remoteUserVoiceMutedByUserId.clear();
    persistRemoteUserVoiceMutedPrefs();
    changed = true;
  }
  if (resetPerUserVolumes && remoteStreamVolumeById.size) {
    remoteStreamVolumeById.clear();
    persistRemoteStreamVolumePrefs();
    changed = true;
  }
  if (resetPerUserVolumes && remoteStreamMutedById.size) {
    remoteStreamMutedById.clear();
    persistRemoteStreamMutedPrefs();
    changed = true;
  }
  if (resetPerUserVolumes && remoteStreamAttenuationEnabledById.size) {
    remoteStreamAttenuationEnabledById.clear();
    persistRemoteStreamAttenuationEnabledPrefs();
    changed = true;
  }
  if (resetPerUserVolumes && remoteStreamAttenuationStrengthById.size) {
    remoteStreamAttenuationStrengthById.clear();
    persistRemoteStreamAttenuationStrengthPrefs();
    changed = true;
  }
  if (!changed) return false;
  applyVoiceMicGainLive();
  applyMicMute();
  void applyDeafen();
  applyRemoteAudioVolumes();
  syncCallAudioMenuUi();
  return true;
}

function hasLiveRemoteAudioType(type) {
  for (const entry of remoteAudioTrackEls.values()) {
    if (!entry || resolveRemoteAudioEntryType(entry) !== type) continue;
    if (entry.track?.readyState === "live" || entry.audioEl?.srcObject) return true;
  }
  if (type === REMOTE_AUDIO_TYPE_VOICE) {
    const fallback = document.getElementById("callRemoteAudio");
    if (fallback?.srcObject) return true;
  }
  return false;
}

