async function toggleServerVoiceScreenshare(conversationId = null, {
  triggerReason = "manual_toggle",
} = {}) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  if (!convId) return false;
  const layer = getActiveServerVoiceScreenshareLayer(convId);
  if (!layer || typeof layer.toggleShare !== "function") {
    throw new Error("server_voice_screenshare_layer_unavailable");
  }
  const wasLocalShareActive = !!layer.isLocalShareActive?.();
  if (!wasLocalShareActive) {
    await assertCurrentServerVoiceParticipationPermission("stream", {
      conversationId: convId,
      forceCheck: false,
    });
    const prefs = layer.getPreferences?.() || null;
    logServerVoiceDebug("screenshare.share_audio_used_for_capture", {
      conversationId: convId || null,
      triggerReason: String(triggerReason || "").trim() || "manual_toggle",
      callerFunction: "toggleServerVoiceScreenshare",
      source: "toggle_start",
      shareAudioEnabled: !!prefs?.shareAudioEnabled,
      localShareActive: false,
    });
  }
  await layer.toggleShare({
    triggerReason: String(triggerReason || "").trim() || "manual_toggle",
  });
  refreshCallUI();
  return !!layer.isLocalShareActive?.();
}

