async function toggleServerVoiceScreenshareStreamAudio(conversationId = null, {
  triggerReason = "share_audio_toggle",
  callerFunction = "toggleServerVoiceScreenshareStreamAudio",
} = {}) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  const layer = getActiveServerVoiceScreenshareLayer(convId);
  if (!layer || typeof layer.toggleShareAudioEnabled !== "function") {
    throw new Error("server_voice_screenshare_layer_unavailable");
  }
  const previousPrefs = layer.getPreferences?.() || null;
  const localShareActive = !!layer.isLocalShareActive?.();
  const normalizedTriggerReason = String(triggerReason || "").trim() || "share_audio_toggle";
  const normalizedCallerFunction = String(callerFunction || "").trim() || "toggleServerVoiceScreenshareStreamAudio";
  logServerVoiceDebug("screenshare.share_audio_toggle_clicked", {
    conversationId: convId || null,
    triggerReason: normalizedTriggerReason,
    callerFunction: normalizedCallerFunction,
    localShareActive,
    shareAudioEnabledBefore: !!previousPrefs?.shareAudioEnabled,
  });
  const prefs = await layer.toggleShareAudioEnabled({
    triggerReason: normalizedTriggerReason,
    applyLive: false,
  });
  const resolvedPrefs = prefs || layer.getPreferences?.() || null;
  logServerVoiceDebug("screenshare.share_audio_preference_saved", {
    conversationId: convId || null,
    triggerReason: normalizedTriggerReason,
    callerFunction: normalizedCallerFunction,
    localShareActive,
    shareAudioEnabledBefore: !!previousPrefs?.shareAudioEnabled,
    shareAudioEnabledAfter: !!resolvedPrefs?.shareAudioEnabled,
  });
  refreshCallUI();
  return resolvedPrefs;
}

async function selectServerVoiceScreenshareSource(conversationId = null, {
  triggerReason = "source_select",
} = {}) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  const layer = getActiveServerVoiceScreenshareLayer(convId);
  if (!layer || typeof layer.selectSource !== "function") {
    throw new Error("server_voice_screenshare_layer_unavailable");
  }
  const selection = await layer.selectSource({
    triggerReason: String(triggerReason || "").trim() || "source_select",
  });
  refreshCallUI();
  return selection;
}

async function openServerVoiceScreenshareFullPicker(conversationId = null, {
  triggerReason = "manual_toggle",
  callerFunction = "openServerVoiceScreenshareFullPicker",
} = {}) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  if (!convId) return false;
  closeCallShareMenu();
  const layer = getActiveServerVoiceScreenshareLayer(convId);
  if (!layer) {
    throw new Error("server_voice_screenshare_layer_unavailable");
  }
  await assertCurrentServerVoiceParticipationPermission("stream", {
    conversationId: convId,
    forceCheck: false,
  });
  const previousPrefs = getServerVoiceScreensharePreferences(convId, {
    reason: "full_picker_preset_request",
    source: "full_picker",
    logLoaded: true,
    callerFunction: "openServerVoiceScreenshareFullPicker",
  });
  const wasLocalShareActive = !!layer.isLocalShareActive?.();
  logServerVoiceDebug("screenshare.menu_opened", {
    conversationId: convId,
    triggerReason: String(triggerReason || "").trim() || "manual_toggle",
    callerFunction: String(callerFunction || "").trim() || "openServerVoiceScreenshareFullPicker",
    mode: "full_picker",
    localShareActive: wasLocalShareActive,
    streamPreset: String(previousPrefs?.streamPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_STREAM_PRESET).trim().toLowerCase() || SERVER_VOICE_SCREENSHARE_DEFAULT_STREAM_PRESET,
    qualityPreset: String(previousPrefs?.qualityPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_QUALITY_PRESET).trim().toLowerCase() || SERVER_VOICE_SCREENSHARE_DEFAULT_QUALITY_PRESET,
    fpsPreset: String(previousPrefs?.fpsPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_FPS_PRESET).trim() || SERVER_VOICE_SCREENSHARE_DEFAULT_FPS_PRESET,
    shareAudioEnabled: !!previousPrefs?.shareAudioEnabled,
  });
  const picked = await openServerVoiceScreenshareSourcePicker(convId, {
    triggerReason: String(triggerReason || "").trim() || "manual_toggle",
    capturePreferences: {
      streamPreset: String(previousPrefs?.streamPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_STREAM_PRESET).trim().toLowerCase() || SERVER_VOICE_SCREENSHARE_DEFAULT_STREAM_PRESET,
      qualityPreset: String(previousPrefs?.qualityPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_QUALITY_PRESET).trim().toLowerCase() || SERVER_VOICE_SCREENSHARE_DEFAULT_QUALITY_PRESET,
      fpsPreset: String(previousPrefs?.fpsPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_FPS_PRESET).trim() || SERVER_VOICE_SCREENSHARE_DEFAULT_FPS_PRESET,
      withAudio: !!previousPrefs?.shareAudioEnabled,
    },
    sourceOnly: false,
    localShareActive: wasLocalShareActive,
  });
  if (!picked) {
    refreshCallUI();
    return wasLocalShareActive;
  }
  const pickedAction = String(picked?.action || "").trim().toLowerCase();
  const nextAction = pickedAction || (wasLocalShareActive ? "change" : "start");
  const nextShareAudioEnabled = typeof picked?.withAudio === "boolean"
    ? !!picked.withAudio
    : !!previousPrefs?.shareAudioEnabled;
  const nextPresetState = resolveServerVoiceScreensharePresetState({
    streamPreset: picked?.streamPreset || previousPrefs?.streamPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_STREAM_PRESET,
    qualityPreset: picked?.qualityPreset || previousPrefs?.qualityPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_QUALITY_PRESET,
    fpsPreset: picked?.fpsPreset || previousPrefs?.fpsPreset || SERVER_VOICE_SCREENSHARE_DEFAULT_FPS_PRESET,
    shareAudioEnabled: nextShareAudioEnabled,
  }, {
    conversationId: convId,
    source: "full_picker_confirm",
    reason: `${String(triggerReason || "").trim() || "manual_toggle"}_picker_confirmed`,
    logLoaded: false,
    callerFunction: "openServerVoiceScreenshareFullPicker",
  });
  const nextStreamPreset = nextPresetState.streamPreset;
  logServerVoiceDebug("screenshare.preset_used_for_capture", {
    conversationId: convId,
    quality: nextPresetState.qualityPreset,
    fps: nextPresetState.fpsPreset,
    streamPreset: nextPresetState.streamPreset,
    source: "full_picker_confirm",
    reason: `${String(triggerReason || "").trim() || "manual_toggle"}_picker_confirmed`,
    callerFunction: "openServerVoiceScreenshareFullPicker",
    localShareActive: wasLocalShareActive,
    action: nextAction,
  });
  logServerVoiceDebug("screenshare.share_audio_used_for_capture", {
    conversationId: convId || null,
    triggerReason: String(triggerReason || "").trim() || "manual_toggle",
    callerFunction: "openServerVoiceScreenshareFullPicker",
    source: "full_picker",
    action: nextAction,
    localShareActive: wasLocalShareActive,
    shareAudioEnabled: !!nextShareAudioEnabled,
  });
  const previousShareAudioEnabled = !!previousPrefs?.shareAudioEnabled;
  await layer.setStreamPreset?.(nextStreamPreset, {
    triggerReason: `${triggerReason}_picker_stream_preset`,
    applyLive: true,
  });
  await layer.setShareAudioEnabled?.(nextShareAudioEnabled, {
    triggerReason: `${triggerReason}_picker_share_audio`,
    applyLive: false,
  });
  const hasSourceSelection = !!String(picked?.sourceId || "").trim();
  const sourceType = String(picked?.sourceType || "").trim().toLowerCase();
  const allowsDisplayMediaFlow = sourceType === "display_media";
  if (hasSourceSelection) {
    layer.setPreferredSourceSelection?.({
      sourceId: String(picked.sourceId || "").trim(),
      sourceKind: String(picked.sourceKind || "").trim(),
      sourceName: String(picked.sourceName || "").trim(),
      sourceType: String(picked.sourceType || "desktop_source").trim() || "desktop_source",
    }, {
      triggerReason: `${triggerReason}_picker_source_selected`,
    });
  }
  if (nextAction === "stop") {
    if (wasLocalShareActive) {
      await layer.stopShare?.({
        triggerReason: `${triggerReason}_picker_stop`,
      });
    }
    refreshCallUI();
    return false;
  }
  const shouldRestartForAudio = wasLocalShareActive && (nextShareAudioEnabled !== previousShareAudioEnabled);
  const shouldRestartForSource = wasLocalShareActive && hasSourceSelection;
  if (!wasLocalShareActive) {
    if (!hasSourceSelection && !allowsDisplayMediaFlow) {
      setCallStatus("Pick a source before starting stream.", true);
      setTimeout(() => setCallStatus("", false), 2000);
      refreshCallUI();
      return false;
    }
    await layer.startShare?.({
      triggerReason: `${triggerReason}_picker_start`,
    });
    refreshCallUI();
    return !!layer.isLocalShareActive?.();
  }
  if (shouldRestartForSource || shouldRestartForAudio) {
    if (shouldRestartForAudio) {
      logServerVoiceDebug("screenshare.share_audio_restart_required", {
        conversationId: convId || null,
        triggerReason: String(triggerReason || "").trim() || "manual_toggle",
        callerFunction: "openServerVoiceScreenshareFullPicker",
        reason: "full_picker_share_audio_changed",
        previousShareAudioEnabled,
        nextShareAudioEnabled: !!nextShareAudioEnabled,
      });
    }
    await restartServerVoiceScreenshareWithStageCleanup(convId, {
      triggerReason: `${triggerReason}_picker_restart`,
      callerFunction: "openServerVoiceScreenshareFullPicker",
      restoreFocusIfPreviouslyFocused: true,
    });
    if (shouldRestartForAudio) {
      logServerVoiceDebug("screenshare.share_audio_restart_completed", {
        conversationId: convId || null,
        triggerReason: String(triggerReason || "").trim() || "manual_toggle",
        callerFunction: "openServerVoiceScreenshareFullPicker",
        reason: "full_picker_share_audio_changed",
        previousShareAudioEnabled,
        nextShareAudioEnabled: !!nextShareAudioEnabled,
      });
    }
    refreshCallUI();
    return !!layer.isLocalShareActive?.();
  }
  refreshCallUI();
  return !!layer.isLocalShareActive?.();
}

function getServerVoiceTransportParticipantState(conversationId, userId) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  if (!convId || !uid) return null;
  const snapshot = getServerVoiceTransportSnapshot(convId);
  if (!snapshot?.participantsByUser || typeof snapshot.participantsByUser !== "object") return null;
  return snapshot.participantsByUser[uid] || null;
}

function getServerVoiceTransportParticipantIds(conversationId) {
  const convId = normId(conversationId || "");
  if (!convId) return [];
  const snapshot = getServerVoiceTransportSnapshot(convId);
  if (!snapshot?.participantsByUser || typeof snapshot.participantsByUser !== "object") return [];
  const meId = normId(state.user?.id || "");
  return normalizeUuidArray(
    Object.keys(snapshot.participantsByUser || {}).filter((uid) => {
      if (!uid || uid === meId) return false;
      const participantState = snapshot.participantsByUser?.[uid] || null;
      return isServerVoiceTransportParticipantInChannel(convId, uid, participantState);
    })
  );
}

const SERVER_VOICE_PARTICIPANT_RUNTIME_STATE = Object.freeze({
  NOT_IN_CHANNEL: "not_in_channel",
  JOINING: "joining",
  CONNECTED: "connected",
  AUDIO_LIVE: "audio_live",
  FAILED: "failed",
});

function getServerVoiceTransportParticipantFailureReason(conversationId, userId, participantState = null, snapshot = null) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const meId = normId(state.user?.id || "");
  if (!convId || !uid) return null;
  const isLocal = !!(meId && uid === meId);
  const resolvedSnapshot = snapshot || getServerVoiceTransportSnapshot(convId) || {};
  const sourceError = isLocal
    ? (resolvedSnapshot.lastError || resolvedSnapshot.lastDisconnect || participantState?.lastError || null)
    : (participantState?.lastError || null);
  const rawReason = sourceError?.reason
    || sourceError?.errorMessage
    || sourceError?.message
    || sourceError?.stage
    || sourceError?.errorName
    || sourceError?.name
    || null;
  return String(rawReason || "").trim() || null;
}

function getServerVoiceTransportParticipantStateLabel(runtimeState, {
  isLocal = false,
  failureReason = null,
} = {}) {
  switch (runtimeState) {
    case SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.NOT_IN_CHANNEL:
      return "Not in channel";
    case SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.JOINING:
      return isLocal ? "Joining voice" : "Joining";
    case SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED:
      return "Connected";
    case SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.AUDIO_LIVE:
      return "Audio live";
    case SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.FAILED:
      return failureReason ? `Failed: ${failureReason}` : "Failed";
    default:
      return "";
  }
}

function parseServerVoiceTimestampMs(value) {
  if (typeof value === "number" && Number.isFinite(value) && value > 0) return value;
  const raw = String(value || "").trim();
  if (!raw) return 0;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
}

function getServerVoiceTransportParticipantPresenceJoinedAtMs(conversationId, userId) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  if (!convId || !uid) return 0;
  const authoritativeMembers = getAuthoritativeServerVoicePresenceMembers(convId);
  if (Array.isArray(authoritativeMembers) && authoritativeMembers.length) {
    const hit = authoritativeMembers.find((member) => normId(member?.userId || "") === uid) || null;
    const joinedAtMs = parseServerVoiceTimestampMs(hit?.joinedAt);
    if (joinedAtMs > 0) return joinedAtMs;
  }
  const presenceEntry = getServerVoicePresenceEntry(convId, { create: false });
  const seenAtMs = Number(presenceEntry?.seenAtByUser?.get?.(uid) || 0);
  return Number.isFinite(seenAtMs) && seenAtMs > 0 ? seenAtMs : 0;
}

function isServerVoiceTransportParticipantInChannel(conversationId, userId, participantState = null) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const meId = normId(state.user?.id || "");
  if (!convId || !uid) return false;
  if (
    uid === meId
    && (
      isServerVoiceTransportSessionActive(convId)
      || !!String(serverVoiceJoinInFlightByConversation.get(convId) || "").trim()
    )
  ) {
    return true;
  }
  return !!(
    participantState?.presentInRoom
    || participantState?.audioSubscribed
    || participantState?.audioAttached
    || participantState?.audioLive
  );
}

function isServerVoiceTransportParticipantMediaReadyState(participantState = null) {
  return !!(
    participantState?.audioAttached
    || participantState?.audioLive
  );
}

function getServerVoiceTransportParticipantFirstSeenAtMs(conversationId, userId, participantState = null) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  if (!convId || !uid) return 0;
  const times = [
    parseServerVoiceTimestampMs(participantState?.joinedAt),
    parseServerVoiceTimestampMs(participantState?.discoveredAt),
    getServerVoiceTransportParticipantPresenceJoinedAtMs(convId, uid),
    Number(getCallParticipantAudioState(convId, uid)?.seenAt || 0),
  ].filter((value) => Number.isFinite(value) && value > 0);
  if (!times.length) return 0;
  return Math.min(...times);
}

function getServerVoiceTransportLocalConnectingStartedAtMs(conversationId) {
  const convId = normId(conversationId || "");
  if (!convId) return 0;
  const snapshot = getServerVoiceTransportSnapshot(convId);
  if (!snapshot) return 0;
  const connectionState = String(snapshot.connectionState || "").trim().toLowerCase();
  const times = [];
  if (connectionState === "connecting" || connectionState === "reconnecting" || connectionState === "signalreconnecting") {
    times.push(parseServerVoiceTimestampMs(snapshot.connectionStateChangedAt));
  }
  if (snapshot.local?.roomConnected) {
    times.push(parseServerVoiceTimestampMs(snapshot.connectedAt));
  }
  return times.filter((value) => Number.isFinite(value) && value > 0)[0] || 0;
}

function isServerVoiceTransportParticipantConnectingTimedOut(conversationId, userId, participantState = null) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const meId = normId(state.user?.id || "");
  if (!convId || !uid) return false;
  const snapshot = getServerVoiceTransportSnapshot(convId);
  if (!snapshot) return false;
  const effectiveParticipantState = participantState || getServerVoiceTransportParticipantState(convId, uid);
  const runtimeState = getServerVoiceTransportParticipantRuntimeState(convId, uid, effectiveParticipantState, snapshot);
  if (
    runtimeState === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.NOT_IN_CHANNEL
    || runtimeState === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.AUDIO_LIVE
    || runtimeState === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.FAILED
  ) {
    return false;
  }
  if (!isServerVoiceTransportParticipantInChannel(convId, uid, effectiveParticipantState)) return false;
  const startedAt = uid === meId
    ? getServerVoiceTransportLocalConnectingStartedAtMs(convId)
    : getServerVoiceTransportParticipantFirstSeenAtMs(convId, uid, effectiveParticipantState);
  if (!startedAt) return false;
  return (Date.now() - startedAt) >= SERVER_VOICE_MEDIA_READY_TIMEOUT_MS;
}

function getServerVoiceTransportParticipantRuntimeState(conversationId, userId, participantState = null, snapshot = null) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const meId = normId(state.user?.id || "");
  if (!convId || !uid) return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.NOT_IN_CHANNEL;
  const resolvedSnapshot = snapshot || getServerVoiceTransportSnapshot(convId) || {};
  const isLocal = !!(meId && uid === meId);
  const inChannel = isServerVoiceTransportParticipantInChannel(convId, uid, participantState);
  const connectionState = String(participantState?.connectionState || resolvedSnapshot.connectionState || "").trim().toLowerCase();
  const joinPhase = String(resolvedSnapshot.joinPhase || "").trim().toLowerCase();
  const joinInFlight = !!String(serverVoiceJoinInFlightByConversation.get(convId) || "").trim();
  const failureReason = getServerVoiceTransportParticipantFailureReason(convId, uid, participantState, resolvedSnapshot);

  if (failureReason) {
    const localReady = !!(resolvedSnapshot.local?.mediaReady && resolvedSnapshot.local?.audioTrackPublished);
    const remoteReady = !!(participantState?.audioAttached || participantState?.audioLive);
    if ((isLocal && !localReady) || (!isLocal && !remoteReady)) {
      return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.FAILED;
    }
  }

  if (isLocal && resolvedSnapshot.local?.mediaReady && resolvedSnapshot.local?.audioTrackPublished) {
    return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.AUDIO_LIVE;
  }
  if (!isLocal && (participantState?.audioAttached || participantState?.audioLive)) {
    return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.AUDIO_LIVE;
  }

  if (isLocal && (resolvedSnapshot.local?.roomConnected || connectionState === "connected")) {
    return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED;
  }
  if (!isLocal && (participantState?.presentInRoom || participantState?.audioSubscribed)) {
    return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED;
  }

  if (
    inChannel
    || (
      isLocal
      && (
        joinInFlight
        || connectionState === "connecting"
        || connectionState === "reconnecting"
        || connectionState === "signalreconnecting"
        || (joinPhase && joinPhase !== "idle" && joinPhase !== "disconnected" && joinPhase !== "disconnected_unexpected")
      )
    )
  ) {
    return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.JOINING;
  }

  return SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.NOT_IN_CHANNEL;
}

function buildServerVoiceTransportParticipantUiState(conversationId, userId) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const meId = normId(state.user?.id || "");
  if (!convId || !uid) return null;
  const snapshot = getServerVoiceTransportSnapshot(convId) || {};
  const participantState = getServerVoiceTransportParticipantState(convId, uid) || null;
  const localAudioState = getCallParticipantAudioState(convId, uid) || null;
  const isLocal = !!(meId && uid === meId);
  const inChannel = isServerVoiceTransportParticipantInChannel(convId, uid, participantState);
  const runtimeState = getServerVoiceTransportParticipantRuntimeState(convId, uid, participantState, snapshot);
  const failureReason = getServerVoiceTransportParticipantFailureReason(convId, uid, participantState, snapshot);
  const mediaReady = runtimeState === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.AUDIO_LIVE;
  const connectingTimedOut = isServerVoiceTransportParticipantConnectingTimedOut(convId, uid, participantState);
  return {
    userId: uid,
    isLocal,
    state: runtimeState,
    stateLabel: getServerVoiceTransportParticipantStateLabel(runtimeState, {
      isLocal,
      failureReason,
    }),
    failureReason,
    inChannel,
    presentInRoom: isLocal ? !!snapshot?.local?.roomConnected : !!participantState?.presentInRoom,
    connectionState: String(participantState?.connectionState || snapshot.connectionState || "").trim().toLowerCase() || "disconnected",
    participantSidCount: isLocal ? 1 : Number(participantState?.participantSidCount || 0),
    localAudioCreated: isLocal ? !!snapshot?.local?.audioTrackCreated : null,
    localAudioPublished: isLocal ? !!snapshot?.local?.audioTrackPublished : null,
    remoteAudioSubscribed: isLocal ? null : !!participantState?.audioSubscribed,
    remoteAudioAttached: isLocal ? null : !!participantState?.audioAttached,
    remoteAudioSubscriptionCount: isLocal ? null : Number(participantState?.audioSubscriptionCount || 0),
    remoteAudioAttachmentCount: isLocal ? null : Number(participantState?.audioAttachmentCount || 0),
    remoteAudioTrackIds: isLocal ? [] : [ ...(participantState?.audioTrackIds || []) ],
    mediaReady,
    speaking: !!participantState?.speaking,
    muted: isLocal
      ? !!micMuted
      : (localAudioState?.micMuted != null ? !!localAudioState.micMuted : !!participantState?.audioMuted),
    deafened: isLocal
      ? !!deafened
      : (localAudioState?.deafened != null ? !!localAudioState.deafened : null),
    connectingTimedOut,
    participantState,
  };
}

function getServerVoiceTransportUiStates(conversationId) {
  const convId = normId(conversationId || "");
  if (!convId) return [];
  const meId = normId(state.user?.id || "");
  const orderedIds = normalizeUuidArray([
    meId,
    ...getServerVoiceTransportParticipantIds(convId),
  ]);
  return orderedIds
    .map((uid) => buildServerVoiceTransportParticipantUiState(convId, uid))
    .filter(Boolean);
}

function isServerVoiceTransportSessionActive(conversationId = null) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  if (!shouldUseServerVoiceLiveKitTransport(convId)) return false;
  const snapshot = getServerVoiceTransportSnapshot(convId);
  if (!snapshot) return !!getActiveServerVoiceTransportController(convId);
  const state = String(snapshot.connectionState || "").trim().toLowerCase();
  const phase = String(snapshot.joinPhase || "").trim().toLowerCase();
  return !!(
    getActiveServerVoiceTransportController(convId)
    || state === "connecting"
    || state === "connected"
    || state === "reconnecting"
    || state === "signalreconnecting"
    || (phase && phase !== "idle" && phase !== "disconnected" && phase !== "disconnected_unexpected")
  );
}

function isServerVoiceTransportMediaReady(conversationId = null) {
  const snapshot = getServerVoiceTransportSnapshot(conversationId);
  return !!snapshot?.local?.mediaReady;
}

function getServerVoiceTransportParticipantStatusLabel(conversationId, userId, {
  includeSelf = true,
} = {}) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const meId = normId(state.user?.id || "");
  if (!convId || !uid) return "";
  const isSelf = !!(meId && uid === meId);
  if (isSelf && !includeSelf) return "";

  const participantUiState = buildServerVoiceTransportParticipantUiState(convId, uid);
  return participantUiState?.stateLabel || "";
}

function getServerVoiceTransportStageStatusText(conversationId = null) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  if (!shouldUseServerVoiceLiveKitTransport(convId)) return "";
  const snapshot = getServerVoiceTransportSnapshot(convId);
  if (!snapshot) return "Joining channel...";
  const meId = normId(state.user?.id || "");
  const localState = meId ? buildServerVoiceTransportParticipantUiState(convId, meId) : null;

  const connectionState = String(snapshot.connectionState || "").trim().toLowerCase();
  if (localState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.FAILED) {
    return localState.failureReason
      ? `Audio failed � ${localState.failureReason}`
      : "Audio failed";
  }
  if (connectionState === "reconnecting" || connectionState === "signalreconnecting") {
    return "Reconnecting audio...";
  }
  if (localState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.JOINING || snapshot.local?.roomConnected !== true || connectionState === "connecting") {
    return "Joining voice...";
  }
  if (localState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED) {
    if (!snapshot.local?.audioTrackCreated) return "Connected � Preparing microphone...";
    if (!snapshot.local?.audioTrackPublished) return "Connected � Publishing microphone...";
    return "Connected � Waiting for audio...";
  }

  const participantUiStateByUserId = new Map();
  getServerVoiceTransportUiStates(convId).forEach((participantUiState) => {
    const uid = normId(participantUiState?.userId || "");
    if (!uid) return;
    participantUiStateByUserId.set(uid, participantUiState);
  });
  const remoteVisibleIds = getServerVoiceInCallParticipants(convId, {
    triggerReason: "stage_status_text",
    callerFunction: "getServerVoiceTransportStageStatusText",
  })
    .map((participant) => normId(participant?.userId || ""))
    .filter((uid) => uid && uid !== meId);

  let audioLiveCount = 0;
  let waitingCount = 0;
  let failedCount = 0;
  remoteVisibleIds.forEach((uid) => {
    const runtimeState = participantUiStateByUserId.get(uid)?.state || SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED;
    if (runtimeState === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.AUDIO_LIVE) {
      audioLiveCount += 1;
      return;
    }
    if (runtimeState === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.FAILED) {
      failedCount += 1;
      return;
    }
    waitingCount += 1;
  });
  if (audioLiveCount > 0 && waitingCount > 0) {
    return `Connected � ${audioLiveCount} audio live � ${waitingCount} waiting audio`;
  }
  if (audioLiveCount > 0 && failedCount > 0) {
    return `Connected � ${audioLiveCount} audio live � ${failedCount} failed`;
  }
  if (audioLiveCount > 0) {
    return `Connected � ${audioLiveCount} audio live`;
  }
  if (waitingCount > 0) {
    return `Connected � ${waitingCount} joining`;
  }
  if (failedCount > 0) {
    return `Connected � ${failedCount} failed`;
  }
  return "Connected � Waiting for others";
}

function updateActiveServerVoiceTransportLocalControls(conversationId = null) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  const controller = getActiveServerVoiceTransportController(convId);
  if (!controller) return;
  try {
    controller.updateLocalControls({
      micMuted: getEffectiveLocalMicMuted(convId),
      deafened: !!deafened,
      inputDeviceId: String(voiceInputDeviceId || "").trim() || "default",
      outputDeviceId: String(voiceOutputDeviceId || "").trim() || "default",
    });
  } catch (_) {}
}

function markServerVoiceTransportRemoteAudioAttached(conversationId, userId, trackId = null, trackSid = null) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const controller = getActiveServerVoiceTransportController(convId);
  if (!controller || !uid) return;
  try {
    controller.markRemoteTrackAttached(uid, {
      kind: "audio",
      trackId,
      trackSid,
    });
  } catch (_) {}
}

function markServerVoiceTransportRemoteAudioDetached(conversationId, userId, trackId = null, trackSid = null) {
  const convId = normId(conversationId || "");
  const uid = normId(userId || "");
  const controller = getActiveServerVoiceTransportController(convId);
  if (!controller || !uid) return;
  try {
    controller.markRemoteTrackDetached(uid, {
      kind: "audio",
      trackId,
      trackSid,
    });
  } catch (_) {}
}

function clearServerVoiceTransportRemoteAudioTracks(conversationId = null) {
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  if (!convId) return;
  const idsToRemove = [];
  for (const [trackId, entry] of remoteAudioTrackEls.entries()) {
    if (!entry) continue;
    const source = String(entry?.source || "").trim().toLowerCase();
    if (source !== "livekit") continue;
    idsToRemove.push(trackId);
  }
  idsToRemove.forEach((trackId) => removeRemoteAudioTrackEl(trackId, { reason: "livekit_transport_clear" }));
}

async function reconnectServerVoiceV2Microphone(conversationId = null, {
  reason = "manual_reconnect",
} = {}) {
  if (serverVoiceReconnectAudioPromise) return serverVoiceReconnectAudioPromise;
  const convId = normId(conversationId || currentServerVoiceV2Session?.conversationId || callConversationId || "");
  const session = currentServerVoiceV2Session || null;
  const sid = normId(session?.serverId || "");
  const channelId = normId(session?.voiceChannelId || "");
  if (!convId || !sid || !channelId || !serverVoiceTransportController) return false;

  const controller = serverVoiceTransportController;
  const request = (async () => {
    setCallStatus("Refreshing voice permissions...", true);
    refreshCallUI();
    const decision = await refreshServerVoicePermissionDecision({
      serverId: sid,
      channelId,
      conversationId: convId,
      force: true,
      reason: `reconnect_audio:${reason}`,
    });
    const localResult = await applyCurrentServerVoiceParticipationDecision(decision, {
      reason: `reconnect_audio:${reason}`,
      notify: true,
    });
    if (localResult?.disconnected || serverVoiceTransportController !== controller) return false;

    const reconciliation = await invokeServerVoicePermissionReconciliation({
      serverId: sid,
      channelId,
      scope: "self",
      reason: `reconnect_audio:${reason}`,
      forceAfterInFlight: true,
    });
    if (serverVoiceTransportController !== controller) return false;

    if (decision?.speak !== true) {
      const message = "You joined as a listener because microphone publishing is not permitted.";
      notifyServerVoicePermissionDenied("speak", { message });
      setCallStatus("Connected to voice.", true);
      refreshCallUI();
      return false;
    }

    const permissionWait = await controller.waitForLocalParticipantPermission?.({
      source: "microphone",
      timeoutMs: 3500,
    });
    const localPermission = recordLocalServerVoiceParticipantPermission("reconnect_audio_after_reconcile");
    if (!permissionWait?.ok || localPermission?.microphoneAllowed !== true) {
      const mismatch = Object.assign(
        new Error("failed to publish track, insufficient permissions"),
        { code: "livekit_microphone_grant_not_applied" },
      );
      await settleServerVoiceAsListenerAfterMicrophoneFailure(mismatch, {
        decision,
        reason: "reconnect_audio_grant_mismatch",
        notify: true,
      });
      return false;
    }

    setCallStatus("Reconnecting microphone...", true);
    refreshCallUI();
    try {
      const stream = await getLocalAudioStream();
      const micTrack = getBestLocalMicTrack() || stream?.getAudioTracks?.()[0] || null;
      if (!micTrack) throw new Error("Microphone unavailable.");
      localMicTrack = micTrack;
      try { localMicTrack.contentHint = "speech"; } catch (_) {}
      registerCallSpeakingMeter(localMicTrack, normId(state.user?.id || ""), { local: true });
      localMicTrack.enabled = !getEffectiveLocalMicMuted(convId);
      applyMicMute();
      await controller.publishMicrophone(localMicTrack, {
        micMuted: getEffectiveLocalMicMuted(convId),
        deafened: !!deafened,
        inputDeviceId: String(voiceInputDeviceId || "").trim() || "default",
        outputDeviceId: String(voiceOutputDeviceId || "").trim() || "default",
      });
      recordLocalServerVoiceParticipantPermission("reconnect_audio_microphone_published");
      lastServerVoiceMicrophonePublishFailure = null;
      setServerVoiceTransportSnapshot(convId, controller.getSnapshot());
      updateActiveServerVoiceTransportLocalControls(convId);
      setCallStatus("Connected to voice.", true);
      refreshCallUI();
      return {
        ok: true,
        reconciliation: {
          edgeFunctionName: "server-voice-v2-reconcile-permissions",
          deploymentMarker: String(reconciliation?.deploymentMarker || reconciliation?.functionVersion || ""),
        },
      };
    } catch (error) {
      await settleServerVoiceAsListenerAfterMicrophoneFailure(error, {
        decision,
        reason: "reconnect_audio_microphone_failed",
        notify: true,
      });
      setCallStatus("Connected to voice.", true);
      refreshCallUI();
      return false;
    }
  })().catch((error) => {
    const message = "Could not refresh microphone permissions. You remain connected as a listener.";
    if (typeof notifyServerVoiceModerationUi === "function") {
      notifyServerVoiceModerationUi(message, { error: true });
    }
    lastServerVoiceMicrophonePublishFailure = {
      reason: "reconnect_audio_permission_refresh_failed",
      errorCode: String(error?.code || ""),
      errorName: String(error?.name || ""),
      errorMessage: String(error?.message || error || "voice_permission_refresh_failed"),
      message,
      at: Date.now(),
    };
    setCallStatus("Connected to voice.", true);
    refreshCallUI();
    return false;
  }).finally(() => {
    if (serverVoiceReconnectAudioPromise === request) {
      serverVoiceReconnectAudioPromise = null;
    }
  });
  serverVoiceReconnectAudioPromise = request;
  return request;
}

async function reconnectServerVoiceAudio(conversationId = null, {
  reason = "manual_reconnect",
} = {}) {
  const convId = normId(conversationId || callConversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId || !shouldUseServerVoiceLiveKitTransport(convId)) return;
  if (
    isServerVoiceV2Enabled()
    && currentServerVoiceV2Session
    && serverVoiceTransportController
    && normId(currentServerVoiceV2Session.conversationId || "") === convId
  ) {
    return reconnectServerVoiceV2Microphone(convId, { reason });
  }
  const isGroupDmLiveKitReconnect = isGroupDmLiveKitTransportConversation(convId);
  logServerVoiceDebug("room.reconnect_requested", {
    conversationId: convId,
    reason: String(reason || "").trim() || "manual_reconnect",
    ...getServerVoiceLocalMediaDebugState(convId),
  });
  setCallStatus("Reconnecting audio...", true);
  clearServerVoiceTransportRemoteAudioTracks(convId);
  await disconnectActiveServerVoiceTransport({
    conversationId: convId,
    reason: String(reason || "").trim() || "manual_reconnect",
    reasonCode: `cleanup.transport_disconnect.${String(reason || "").trim() || "manual_reconnect"}`,
    triggeredBy: "reconnectServerVoiceAudio",
  });
  if (isGroupDmLiveKitReconnect || shouldRouteGroupDmCallViaLiveKit(convId)) {
    await startGroupDmLiveKitCall(convId, {
      joinExistingOnly: true,
      triggerReason: String(reason || "").trim() || "manual_reconnect",
    });
    return;
  }
  await startServerVoiceLiveKitCall(convId, { joinExistingOnly: true, source: "reconnect" });
}

function formatServerVoiceDebugValue(value, {
  na = false,
  status = false,
} = {}) {
  const text = na ? "--" : String(value || "no");
  const classes = ["serverVoiceDebugOverlay__value"];
  if (na) classes.push("is-na");
  else if (status) classes.push("is-status");
  else if (String(text).trim().toLowerCase() === "yes") classes.push("is-yes");
  else if (String(text).trim().toLowerCase() === "no") classes.push("is-no");
  return `<span class="${classes.join(" ")}">${esc(text)}</span>`;
}

function formatServerVoiceDebugTime(value) {
  const ms = parseServerVoiceTimestampMs(value);
  if (!ms) return "--";
  try {
    return new Date(ms).toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
  } catch (_) {}
  return "--";
}

function getServerVoiceDebugReasonText(details = null) {
  if (!details || typeof details !== "object") return "--";
  return String(
    details.reason
    || details.errorMessage
    || details.kind
    || details.errorCode
    || details.message
    || details.stage
    || details.errorName
    || details.name
    || "",
  ).trim() || "--";
}

function buildServerVoiceCallDiagnostics(conversationId = null) {
  const convId = getInspectableServerVoiceConversationId(conversationId);
  if (!convId) return null;
  const snapshot = getServerVoiceTransportSnapshot(convId) || {};
  const activeController = getActiveServerVoiceTransportController(convId);
  const participantStates = getServerVoiceTransportUiStates(convId);
  const lastJoinFailure = getServerVoiceJoinFailureSummary(convId);
  return {
    generatedAt: new Date().toISOString(),
    conversationId: convId,
    transport: snapshot.transport || SERVER_VOICE_TRANSPORT_KIND || "livekit",
    roomState: {
      roomName: snapshot.roomName || null,
      roomUrl: snapshot.roomUrl || null,
      connectionState: snapshot.connectionState || "disconnected",
      joinPhase: snapshot.joinPhase || "idle",
      connected: !!snapshot.connected,
      reconnecting: !!snapshot.reconnecting,
      disconnectRequested: !!snapshot.disconnectRequested,
      joinAttemptId: snapshot.joinAttemptId || String(serverVoiceActiveJoinAttemptIdByConversation.get(convId) || "").trim() || null,
      joinAttemptInFlight: String(serverVoiceJoinInFlightByConversation.get(convId) || "").trim() || null,
      controllerId: snapshot.controllerId || String(activeController?.controllerId || "").trim() || null,
      local: snapshot.local || null,
      lastError: snapshot.lastError || null,
      lastErrorReason: getServerVoiceDebugReasonText(snapshot.lastError),
      lastDisconnect: snapshot.lastDisconnect || null,
      lastDisconnectReason: getServerVoiceDebugReasonText(snapshot.lastDisconnect),
      lastJoinFailure: lastJoinFailure || null,
      lastJoinFailureKind: String(lastJoinFailure?.kind || "").trim() || null,
      lastJoinFailureReason: getServerVoiceDebugReasonText(lastJoinFailure),
    },
    participants: participantStates.map((participantUiState) => ({
      userId: participantUiState.userId,
      state: participantUiState.state,
      stateLabel: participantUiState.stateLabel,
      inChannel: !!participantUiState.inChannel,
      presentInRoom: !!participantUiState.presentInRoom,
      participantSidCount: participantUiState.participantSidCount ?? null,
      connectionState: participantUiState.connectionState || "disconnected",
      localAudioCreated: participantUiState.localAudioCreated,
      localAudioPublished: participantUiState.localAudioPublished,
      remoteAudioSubscribed: participantUiState.remoteAudioSubscribed,
      remoteAudioAttached: participantUiState.remoteAudioAttached,
      remoteAudioSubscriptionCount: participantUiState.remoteAudioSubscriptionCount ?? null,
      remoteAudioAttachmentCount: participantUiState.remoteAudioAttachmentCount ?? null,
      remoteAudioTrackIds: participantUiState.remoteAudioTrackIds || [],
      mediaReady: !!participantUiState.mediaReady,
      speaking: !!participantUiState.speaking,
      muted: participantUiState.muted,
      deafened: participantUiState.deafened,
      failureReason: participantUiState.failureReason || null,
    })),
  };
}

async function copyServerVoiceCallDiagnostics(conversationId = null) {
  const diagnostics = buildServerVoiceCallDiagnostics(conversationId);
  if (!diagnostics) return false;
  const copied = await copyTextWithPromptFallback(
    JSON.stringify(diagnostics, null, 2),
    "call diagnostics",
  );
  if (!copied) return false;
  logServerVoiceDebug("diagnostics.copied", {
    conversationId: diagnostics.conversationId,
    joinAttemptId: diagnostics.roomState?.joinAttemptId || null,
    controllerId: diagnostics.roomState?.controllerId || null,
  });
  setCallStatus("Call diagnostics copied.", true);
  setTimeout(() => {
    const activeConvId = normId(callConversationId || activeDmId || state.activeDm?.conversationId || "");
    if (activeConvId === diagnostics.conversationId && isServerVoiceTransportSessionActive(activeConvId)) {
      setCallStatus("", false);
    }
  }, 1400);
  return true;
}

function logServerVoiceTransportConnectingTimeouts(conversationId = null) {
  if (!isServerVoiceDebugLoggingEnabled()) return;
  const convId = normId(conversationId || "");
  if (!convId || !shouldUseServerVoiceLiveKitTransport(convId)) return;
  const snapshot = getServerVoiceTransportSnapshot(convId) || {};
  getServerVoiceTransportUiStates(convId)
    .filter((participantUiState) => participantUiState?.connectingTimedOut)
    .forEach((participantUiState) => {
      logServerVoiceDiagnosticWarning("transport.media_timeout", {
        conversationId: convId,
        peerUserId: participantUiState.userId || null,
        local: !!participantUiState.isLocal,
        inChannel: !!participantUiState.inChannel,
        presentInRoom: !!participantUiState.presentInRoom,
        connectionState: participantUiState.connectionState || null,
        localAudioCreated: participantUiState.localAudioCreated,
        localAudioPublished: participantUiState.localAudioPublished,
        remoteAudioSubscribed: participantUiState.remoteAudioSubscribed,
        remoteAudioAttached: participantUiState.remoteAudioAttached,
        mediaReady: !!participantUiState.mediaReady,
        state: participantUiState.state || null,
        failureReason: participantUiState.failureReason || null,
        speaking: !!participantUiState.speaking,
        muted: participantUiState.muted,
        deafened: participantUiState.deafened,
        reconnecting: !!snapshot.reconnecting,
      });
    });
}

function renderServerVoiceDebugOverlay(conversationId = null, {
  callUiVisible = false,
  isServerVoiceCallUi = false,
} = {}) {
  const {
    stage,
    serverVoiceDebugOverlay,
    serverVoiceDebugOverlayBody,
    btnServerVoiceCopyDiagnostics,
  } = getCallEls();
  if (!serverVoiceDebugOverlay || !serverVoiceDebugOverlayBody) return;
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  const shouldShow = !!(
    convId
    && isServerVoiceCallUi
    && callUiVisible
    && shouldUseServerVoiceLiveKitTransport(convId)
    && readServerVoiceDebugLoggingFlag()
  );
  if (!shouldShow) {
    serverVoiceDebugOverlay.hidden = true;
    serverVoiceDebugOverlay.setAttribute("aria-hidden", "true");
    serverVoiceDebugOverlayBody.innerHTML = "";
    if (btnServerVoiceCopyDiagnostics) {
      btnServerVoiceCopyDiagnostics.hidden = true;
      btnServerVoiceCopyDiagnostics.disabled = true;
    }
    stage?.classList.remove("has-server-voice-debug");
    return;
  }

  const snapshot = getServerVoiceTransportSnapshot(convId) || {};
  const participantStates = getServerVoiceTransportUiStates(convId);
  const lastJoinFailure = getServerVoiceJoinFailureSummary(convId) || null;
  const roomParticipantCount = participantStates.filter((participantUiState) => participantUiState?.presentInRoom).length;
  const mediaReadyCount = participantStates.filter((participantUiState) => participantUiState?.mediaReady).length;
  const rowHead = `
    <div class="serverVoiceDebugOverlay__row serverVoiceDebugOverlay__row--head">
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Participant</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">State</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Channel</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Room</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Conn</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Local published</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Remote sub</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Remote attach</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Audio live</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Speaking</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Muted</div>
      <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--head">Error</div>
    </div>
  `;
  const rowHtml = participantStates.map((participantUiState) => {
    const identity = getGroupMemberIdentity(convId, participantUiState.userId) || {};
    const label = identity?.label || (participantUiState.isLocal ? (state.me?.display_name || state.me?.username || "You") : "member");
    const statusLabel = participantUiState.stateLabel || "Idle";
    return `
      <div class="serverVoiceDebugOverlay__row">
        <div class="serverVoiceDebugOverlay__cell serverVoiceDebugOverlay__cell--participant">
          ${esc(label)}${participantUiState.isLocal ? " (You)" : ""}
          <span class="serverVoiceDebugOverlay__participantMeta">${esc(statusLabel)}</span>
        </div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.state || "--", { status: true, na: !participantUiState.state })}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.inChannel ? "yes" : "no")}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.presentInRoom ? "yes" : "no")}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.connectionState || "--", { status: true, na: !participantUiState.connectionState })}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.localAudioPublished ? "yes" : "no", { na: participantUiState.localAudioPublished == null })}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.remoteAudioSubscribed ? "yes" : "no", { na: participantUiState.remoteAudioSubscribed == null })}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.remoteAudioAttached ? "yes" : "no", { na: participantUiState.remoteAudioAttached == null })}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.mediaReady ? "yes" : "no")}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.speaking ? "yes" : "no")}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.muted ? "yes" : "no", { na: participantUiState.muted == null })}</div>
        <div class="serverVoiceDebugOverlay__cell">${formatServerVoiceDebugValue(participantUiState.failureReason || "--", { status: true, na: !participantUiState.failureReason })}</div>
      </div>
    `;
  }).join("");

  serverVoiceDebugOverlayBody.innerHTML = `
    <div class="serverVoiceDebugOverlay__summary">
      <div class="serverVoiceDebugOverlay__summaryLine">
        in_channel: <code>${participantStates.filter((participantUiState) => participantUiState?.inChannel).length}</code>
        � in_room: <code>${roomParticipantCount}</code>
        � media_ready: <code>${mediaReadyCount}</code>
      </div>
      <div class="serverVoiceDebugOverlay__summaryLine">
        room_state: <code>${esc(String(snapshot.connectionState || "disconnected"))}</code>
        � reconnecting: <code>${snapshot.reconnecting ? "yes" : "no"}</code>
        � reconnected_at: <code>${esc(formatServerVoiceDebugTime(snapshot.reconnectedAt))}</code>
      </div>
      <div class="serverVoiceDebugOverlay__summaryLine">
        last_failure: <code>${esc(String(lastJoinFailure?.kind || "--"))}</code>
        � reason: <code>${esc(getServerVoiceDebugReasonText(lastJoinFailure))}</code>
        � edge: <code>${esc(String(lastJoinFailure?.edgeFunctionName || "--"))}</code>
        � status: <code>${esc(lastJoinFailure?.httpStatus == null ? "--" : String(lastJoinFailure.httpStatus))}</code>
      </div>
    </div>
    <div class="serverVoiceDebugOverlay__table">
      ${rowHead}
      ${rowHtml || `<div class="serverVoiceDebugOverlay__empty">No participants tracked yet.</div>`}
    </div>
  `;
  serverVoiceDebugOverlay.hidden = false;
  serverVoiceDebugOverlay.setAttribute("aria-hidden", "false");
  if (btnServerVoiceCopyDiagnostics) {
    btnServerVoiceCopyDiagnostics.hidden = false;
    btnServerVoiceCopyDiagnostics.disabled = false;
  }
  stage?.classList.add("has-server-voice-debug");
}

function renderServerVoiceAudioFallback(conversationId = null, {
  callUiVisible = false,
  isServerVoiceCallUi = false,
} = {}) {
  const {
    serverVoiceAudioFallback,
    serverVoiceAudioFallbackText,
    btnServerVoiceReconnect,
    btnServerVoiceReconnectSmall,
  } = getCallEls();
  if (!serverVoiceAudioFallback || !serverVoiceAudioFallbackText) return;
  const convId = normId(conversationId || callConversationId || activeDmId || "");
  const localUserId = normId(state.user?.id || "");
  const hideFallbackPanel = () => {
    serverVoiceAudioFallback.hidden = true;
    serverVoiceAudioFallback.setAttribute("aria-hidden", "true");
    serverVoiceAudioFallbackText.textContent = "";
    if (btnServerVoiceReconnect) {
      btnServerVoiceReconnect.hidden = true;
      btnServerVoiceReconnect.style.display = "none";
      btnServerVoiceReconnect.disabled = true;
    }
    if (btnServerVoiceReconnectSmall) {
      btnServerVoiceReconnectSmall.hidden = true;
      btnServerVoiceReconnectSmall.style.display = "none";
      btnServerVoiceReconnectSmall.disabled = true;
    }
  };
  const transportActive = !!(convId && shouldUseServerVoiceLiveKitTransport(convId));
  const shouldEvaluate = !!(transportActive && isServerVoiceCallUi && callUiVisible);
  if (!shouldEvaluate) {
    hideFallbackPanel();
    logServerVoiceDebug("audio_reconnect_panel.render_blocked", {
      conversationId: convId || null,
      localUserId: localUserId || null,
      participantId: localUserId || null,
      inChannel: false,
      inRoom: false,
      mediaReady: false,
      localAudioReady: false,
      reason: "panel_not_evaluated",
    });
    return;
  }

  const snapshot = getServerVoiceTransportSnapshot(convId) || {};
  const participantStates = getServerVoiceTransportUiStates(convId);
  const localState = participantStates.find((participantUiState) => participantUiState?.isLocal) || null;
  const remoteTimedOut = participantStates.filter((participantUiState) => (
    !participantUiState?.isLocal
    && (
      participantUiState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.JOINING
      || participantUiState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED
    )
    && participantUiState?.connectingTimedOut
  ));
  const remoteFailed = participantStates.filter((participantUiState) => (
    !participantUiState?.isLocal
    && participantUiState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.FAILED
  ));
  const localTimedOut = !!(
    localState?.connectingTimedOut
    && (
      localState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.JOINING
      || localState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.CONNECTED
    )
  );
  const localFailed = !!(localState?.state === SERVER_VOICE_PARTICIPANT_RUNTIME_STATE.FAILED);
  const reconnecting = !!snapshot.reconnecting;
  const connecting = String(snapshot.connectionState || "").trim().toLowerCase() === "connecting";
  const localParticipantId = normId(localState?.userId || localUserId || "");
  const localInChannel = !!localState?.inChannel;
  const localInRoom = !!localState?.presentInRoom;
  const localMediaReady = !!localState?.mediaReady;
  const localAudioReady = !!(
    snapshot?.local?.mediaReady
    && snapshot?.local?.audioTrackPublished
    && snapshot?.local?.roomConnected
  );
  const logAudioReconnectPanelEvent = (event, reason = "", extra = {}) => {
    logServerVoiceDebug(event, {
      conversationId: convId || null,
      localUserId: localUserId || null,
      participantId: localParticipantId || null,
      inChannel: localInChannel,
      inRoom: localInRoom,
      mediaReady: localMediaReady,
      localAudioReady,
      reason: String(reason || "").trim() || null,
      ...(extra && typeof extra === "object" && !Array.isArray(extra) ? extra : {}),
    });
  };
  const remoteTimedOutCount = remoteTimedOut.length;
  const remoteFailedCount = remoteFailed.length;
  logAudioReconnectPanelEvent("audio_reconnect_panel.state_source", "state_evaluated", {
    reconnecting,
    connecting,
    localTimedOut,
    localFailed,
    remoteTimedOutCount,
    remoteFailedCount,
    connectionState: String(snapshot.connectionState || "").trim().toLowerCase() || "disconnected",
  });

  const showFallback = !!(reconnecting || localTimedOut || localFailed);
  if (!showFallback) {
    const blockedReason = (remoteTimedOutCount > 0 || remoteFailedCount > 0)
      ? "blocked_remote_only_media_not_ready"
      : "blocked_no_local_audio_failure";
    logAudioReconnectPanelEvent("audio_reconnect_panel.render_blocked", blockedReason, {
      reconnecting,
      connecting,
      localTimedOut,
      localFailed,
      remoteTimedOutCount,
      remoteFailedCount,
    });
    hideFallbackPanel();
    return;
  }

  let fallbackText = "Connecting audio...";
  let fallbackReason = "local_audio_reconnecting";
  if (localFailed) {
    fallbackText = localState?.failureReason
      ? `Audio failed... ${localState.failureReason}. Use Reconnect audio.`
      : "Audio failed... Use Reconnect audio.";
    fallbackReason = "local_audio_failed";
  } else if (reconnecting) {
    fallbackText = "Connecting audio... ALTARA is reconnecting to the voice room.";
    fallbackReason = "local_audio_reconnecting";
  } else if (localTimedOut) {
    fallbackText = "Connecting audio... Your microphone or room media is still not ready.";
    fallbackReason = "local_audio_timeout";
  }

  logServerVoiceTransportConnectingTimeouts(convId);
  logAudioReconnectPanelEvent("audio_reconnect_panel.render_requested", fallbackReason, {
    reconnecting,
    connecting,
    localTimedOut,
    localFailed,
    remoteTimedOutCount,
    remoteFailedCount,
    fallbackText,
  });
  serverVoiceAudioFallbackText.textContent = fallbackText;
  serverVoiceAudioFallback.hidden = false;
  serverVoiceAudioFallback.setAttribute("aria-hidden", "false");
  const showReconnect = !!(localTimedOut || localFailed || reconnecting);
  if (btnServerVoiceReconnect) {
    btnServerVoiceReconnect.hidden = !showReconnect;
    btnServerVoiceReconnect.style.display = showReconnect ? "" : "none";
    btnServerVoiceReconnect.disabled = !showReconnect;
  }
  if (btnServerVoiceReconnectSmall) {
    btnServerVoiceReconnectSmall.hidden = !showReconnect;
    btnServerVoiceReconnectSmall.style.display = showReconnect ? "" : "none";
    btnServerVoiceReconnectSmall.disabled = !showReconnect;
  }
}

