let dmPrivacyAuthStateSubscription = null;
const dmPrivacyFollowupRefetchTimersByConversation = new Map();
const dmPrivacyEventRetryTimersByConversation = new Map();
const dmPrivacyPendingEventsByConversation = new Map();
const dmPrivacyRequestGraceByConversation = new Map();
const dmPrivacyRequestConfirmTimersByConversation = new Map();
const processedDmPrivacyEventIds = new Set();
const dmPrivacyPollLoggedDuplicateEventIds = new Set();
let lastDmPrivacyEventCreatedAt = "";
const DM_PRIVACY_EVENT_RETRY_DELAYS_MS = Object.freeze([500, 1500]);
const DM_PRIVACY_EVENT_POLL_VISIBLE_MS = 1000;
const DM_PRIVACY_EVENT_POLL_HIDDEN_MS = 3000;
const DM_PRIVACY_EVENT_STALE_TOAST_SUPPRESS_MS = 10 * 60 * 1000;
const DM_PRIVACY_REQUEST_CONFIRM_DELAYS_MS = Object.freeze([250, 750, 1500]);
