const DM_PRIVACY_ACTIVE_POLL_RECONCILE_MS = 1000;
const DM_PRIVACY_ACTIVE_POLL_STABLE_MS = 15000;
let globalServerChannelRestartTimer = null;
let globalBotChannelMessageRestartTimer = null;
let globalServerRoleTablesRestartTimer = null;
let globalProfileRestartTimer = null;
let globalFriendRequestRestartTimer = null;
let globalMessageRequestRestartTimer = null;
let globalGroupDmCallRestartTimer = null;
let globalModerationActionRestartTimer = null;
let globalFriendRequestRefreshTimer = null;
let globalFriendRequestRefreshInFlight = false;
