let friendRequestsSyncFallbackTimer = null;
let friendRequestsSyncFallbackInFlight = false;
let friendRequestsSyncFingerprint = "";
let lastFriendsListSignature = "";
let lastIncomingFriendRequestsSignature = "";
let lastOutgoingFriendRequestsSignature = "";
let profileSyncFallbackTimer = null;
let profileSyncFallbackInFlight = false;
let profileFallbackLastForceSyncAt = 0;
let dmCollectionsSyncFallbackTimer = null;
let dmCollectionsSyncFallbackInFlight = false;
let dmCollectionsSyncFingerprint = "";
