let serverActiveChannelSyncFallbackInFlight = false;
let serverActiveChannelSyncServerId = "";
let serverActiveChannelSyncFingerprint = "";
const serverRoleRealtimeRefreshTimersByServerId = new Map();
const serverBotInstallRealtimeRefreshTimersByServerId = new Map();
let activeServerBotRefreshListenersBound = false;
let activeServerBotInstallChannel = null;
let activeServerBotInstallRealtimeServerId = "";
let activeServerBotInstallRealtimeRestartTimer = null;
const profileRealtimeFingerprints = new Map();
function startGlobalCallListener() {
  if (globalCallChannel) {
    try {
      supabase.removeChannel(globalCallChannel);
    } catch (_) {}
    globalCallChannel = null;
  }
  callRealtimeMembershipDescriptorsByConversation = new Map();
  callRealtimeMembershipDescriptorsLoadedAt = 0;
  callRealtimeMembershipDescriptorsInFlight = null;
  scheduleCallRealtimeSubscriptionSync(0);
}

async function resolveGroupDmConversationIdByCallId(callId) {
  const cid = normId(callId || "");
  if (!cid) return "";
  const fromCache = normId(groupDmCallConversationByCallId.get(cid) || "");
  if (fromCache) return fromCache;
  if (!(await ensureGroupDmCallBackendAvailability())) return "";
  const { data, error } = await supabase
    .from("group_dm_call_sessions")
    .select("conversation_id")
    .eq("id", cid)
    .maybeSingle();
  if (error) {
    console.warn("resolve call conversation id failed", error);
    return "";
  }
  const convId = normId(data?.conversation_id || "");
  if (convId) groupDmCallConversationByCallId.set(cid, convId);
  return convId;
}

function onGlobalGroupDmCallSessionChanged(row, eventType = "update") {
  const convId = normId(row?.conversation_id || "");
  if (!convId) return;
  const status = String(row?.status || "").trim().toLowerCase();
  if (eventType === "insert" && status === "active") {
    try {
      window.dispatchEvent(new CustomEvent("call_started", {
        detail: {
          callId: normId(row?.id || ""),
          groupId: convId,
          group_call: true,
        },
      }));
    } catch (_) {}
  } else if (status === "ended" || eventType === "delete") {
    try {
      window.dispatchEvent(new CustomEvent("call_ended", {
        detail: {
          callId: normId(row?.id || ""),
          groupId: convId,
          group_call: true,
        },
      }));
    } catch (_) {}
  }
  scheduleGroupDmCallStateRefresh(convId, 80);
}

function onGlobalGroupDmCallParticipantChanged(row) {
  const callId = normId(row?.call_id || "");
  if (!callId) return;
  void (async () => {
    const convId = await resolveGroupDmConversationIdByCallId(callId);
    if (!convId) return;
    try {
      window.dispatchEvent(new CustomEvent("participants_update", {
        detail: {
          callId,
          groupId: convId,
          userId: normId(row?.user_id || ""),
          state: normalizeGroupDmJoinState(row?.join_state),
          group_call: true,
        },
      }));
    } catch (_) {}
    scheduleGroupDmCallStateRefresh(convId, 80);
  })();
}

function startGlobalGroupDmCallStateListener() {
  if (!state.user?.id) return;
  if (globalGroupDmCallRestartTimer) {
    clearTimeout(globalGroupDmCallRestartTimer);
    globalGroupDmCallRestartTimer = null;
  }
  if (globalGroupDmCallSessionChannel) {
    supabase.removeChannel(globalGroupDmCallSessionChannel);
    globalGroupDmCallSessionChannel = null;
  }
  if (globalGroupDmCallParticipantChannel) {
    supabase.removeChannel(globalGroupDmCallParticipantChannel);
    globalGroupDmCallParticipantChannel = null;
  }

  void ensureGroupDmCallBackendAvailability().then((enabled) => {
    if (!enabled) return;

    globalGroupDmCallSessionChannel = supabase
      .channel("global-group-dm-call-sessions:" + state.user.id)
      .on("postgres_changes", {
        event: "INSERT",
        schema: "public",
        table: "group_dm_call_sessions",
      }, (payload) => {
        onGlobalGroupDmCallSessionChanged(payload?.new || null, "insert");
      })
      .on("postgres_changes", {
        event: "UPDATE",
        schema: "public",
        table: "group_dm_call_sessions",
      }, (payload) => {
        onGlobalGroupDmCallSessionChanged(payload?.new || payload?.old || null, "update");
      })
      .on("postgres_changes", {
        event: "DELETE",
        schema: "public",
        table: "group_dm_call_sessions",
      }, (payload) => {
        onGlobalGroupDmCallSessionChanged(payload?.old || null, "delete");
      })
      .subscribe((status) => {
        if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
          if (globalGroupDmCallRestartTimer || !state.user?.id) return;
          globalGroupDmCallRestartTimer = setTimeout(() => {
            globalGroupDmCallRestartTimer = null;
            startGlobalGroupDmCallStateListener();
          }, 1200);
        }
      });

    globalGroupDmCallParticipantChannel = supabase
      .channel("global-group-dm-call-participants:" + state.user.id)
      .on("postgres_changes", {
        event: "INSERT",
        schema: "public",
        table: "group_dm_call_participants",
      }, (payload) => {
        onGlobalGroupDmCallParticipantChanged(payload?.new || null);
      })
      .on("postgres_changes", {
        event: "UPDATE",
        schema: "public",
        table: "group_dm_call_participants",
      }, (payload) => {
        onGlobalGroupDmCallParticipantChanged(payload?.new || payload?.old || null);
      })
      .on("postgres_changes", {
        event: "DELETE",
        schema: "public",
        table: "group_dm_call_participants",
      }, (payload) => {
        onGlobalGroupDmCallParticipantChanged(payload?.old || null);
      })
      .subscribe((status) => {
        if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
          if (globalGroupDmCallRestartTimer || !state.user?.id) return;
          globalGroupDmCallRestartTimer = setTimeout(() => {
            globalGroupDmCallRestartTimer = null;
            startGlobalGroupDmCallStateListener();
          }, 1200);
        }
      });
  });
}

let globalFriendRequestRefreshPending = false;
let globalFriendRequestRefreshPendingTrace = null;

function scheduleGlobalFriendRequestRefresh(delayMs = 150, { trace = null } = {}) {
  if (!state.user?.id) return;
  logFriendsRealtimeDebug("state refresh scheduled", {
    userId: normId(state.user.id || ""),
    delayMs: Math.max(0, Number(delayMs) || 0),
  });
  if (trace && !trace.ended) {
    globalFriendRequestRefreshPendingTrace = trace;
    relationshipTraceLog(trace, "globalFriendRequestRefresh:scheduled", { delayMs: Math.max(0, Number(delayMs) || 0) });
  }
  // If a refresh is already running, mark that another is needed and let the
  // finally-block re-schedule it, rather than silently dropping the event.
  if (globalFriendRequestRefreshInFlight) {
    globalFriendRequestRefreshPending = true;
    return;
  }
  if (globalFriendRequestRefreshTimer) clearTimeout(globalFriendRequestRefreshTimer);
  globalFriendRequestRefreshTimer = setTimeout(async () => {
    const refreshTrace = globalFriendRequestRefreshPendingTrace && !globalFriendRequestRefreshPendingTrace.ended
      ? globalFriendRequestRefreshPendingTrace
      : (trace && !trace.ended ? trace : null);
    globalFriendRequestRefreshPendingTrace = null;
    globalFriendRequestRefreshTimer = null;
    if (!state.user?.id) return;
    if (globalFriendRequestRefreshInFlight) {
      globalFriendRequestRefreshPending = true;
      if (refreshTrace && !refreshTrace.ended) globalFriendRequestRefreshPendingTrace = refreshTrace;
      return;
    }
    globalFriendRequestRefreshInFlight = true;
    globalFriendRequestRefreshPending = false;
    const prevReconcileTrace = relationshipReconcileTrace;
    if (refreshTrace && !refreshTrace.ended) {
      relationshipReconcileTrace = refreshTrace;
      relationshipTraceLog(refreshTrace, "reconcile:start");
    }
    try {
      await refresh({ lightweight: true });
    } catch (e) {
      console.warn("friend requests realtime refresh failed", e);
      if (refreshTrace && !refreshTrace.ended) {
        endRelationshipTrace(refreshTrace, "reconcile_error", {
          message: String(e?.message || e || "unknown reconcile error"),
        });
      }
    } finally {
      if (refreshTrace && !refreshTrace.ended) {
        endRelationshipTrace(refreshTrace, "reconciled");
      } else if (relationshipReconcileTrace === refreshTrace) {
        relationshipReconcileTrace = prevReconcileTrace || null;
      }
      globalFriendRequestRefreshInFlight = false;
      // If another event arrived while we were refreshing, do one more pass.
      if (globalFriendRequestRefreshPending && state.user?.id) {
        globalFriendRequestRefreshPending = false;
        scheduleGlobalFriendRequestRefresh(200);
      }
    }
  }, Math.max(0, Number(delayMs) || 0));
}

function onGlobalFriendRequestChanged(row, eventType = "UPDATE") {
  if (!state.user?.id) return;
  if (!row || typeof row !== "object") {
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }
  const me = normId(state.user.id);
  const fromId = normId(row?.from_user_id || "");
  const toId = normId(row?.to_user_id || "");
  const requestId = normId(row?.request_id || row?.id || "");
  if (!fromId && !toId) {
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }
  if (fromId !== me && toId !== me) return;
  const otherUserId = fromId === me ? toId : fromId;
  const optimisticProfile = getOptimisticRelationshipProfile({ userId: otherUserId });
  const affectedUsername = String(optimisticProfile?.username || row?.username || "").trim();
  const safeEventType = String(eventType || "UPDATE").trim().toUpperCase();
  const status = String(row?.status || (safeEventType === "DELETE" ? "" : "pending")).trim().toLowerCase();

  if (safeEventType === "DELETE" && status === "accepted") {
    if (requestId) {
      optimisticRemoveIncoming(requestId);
      optimisticRemoveOutgoing(requestId);
    }
    if (otherUserId) {
      optimisticRemoveFriendById(otherUserId);
    }
    renderRelationshipUiNow({
      rerenderFriends: true,
      rerenderPending: true,
      rerenderDmList: true,
      affectedUserId: otherUserId,
      affectedUsername,
    });
    if (otherUserId) {
      scheduleRelationshipRealtimeProfileHydration([otherUserId], {
        rerenderPending: true,
        affectedUserId: otherUserId,
        affectedUsername,
      });
    }
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }

  if (requestId && (safeEventType === "DELETE" || status === "rejected" || status === "cancelled" || status === "canceled")) {
    optimisticRemoveIncoming(requestId);
    optimisticRemoveOutgoing(requestId);
    renderRelationshipUiNow({
      rerenderPending: true,
      affectedUserId: otherUserId,
      affectedUsername,
    });
    if (otherUserId) {
      scheduleRelationshipRealtimeProfileHydration([otherUserId], {
        rerenderPending: true,
        affectedUserId: otherUserId,
        affectedUsername,
      });
    }
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }

  if (status === "accepted") {
    if (requestId) {
      optimisticRemoveIncoming(requestId);
      optimisticRemoveOutgoing(requestId);
    }
    if (otherUserId) {
      upsertFriendRow({
        other_user_id: otherUserId,
        username: String(optimisticProfile?.username || row?.username || "").trim(),
        display_name: String(optimisticProfile?.display_name || row?.display_name || optimisticProfile?.username || row?.username || "User").trim() || "User",
        avatar_url: optimisticProfile?.avatar_url || row?.avatar_url || null,
        since: String(row?.updated_at || row?.created_at || new Date().toISOString()).trim(),
      });
    }
    renderRelationshipUiNow({
      rerenderFriends: true,
      rerenderPending: true,
      affectedUserId: otherUserId,
      affectedUsername,
    });
    queueLightweightDmListRenderFromState();
    if (otherUserId) {
      scheduleRelationshipRealtimeProfileHydration([otherUserId], {
        rerenderFriends: true,
        rerenderPending: true,
        affectedUserId: otherUserId,
        affectedUsername,
      });
    }
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }

  if (toId === me) {
    const nextIncoming = upsertIncomingFriendRequestRow(row);
    const activeTab = document.querySelector("[data-tab].active")?.getAttribute("data-tab") || "";
    const toastRequestId = requestId || normId(nextIncoming?.request_id || nextIncoming?.id || "");
    if (safeEventType === "INSERT" && toastRequestId && activeTab !== "pending" && !shownIncomingFriendRequestToastIds.has(toastRequestId)) {
      shownIncomingFriendRequestToastIds.add(toastRequestId);
      const label = String(nextIncoming?.display_name || nextIncoming?.username || affectedUsername || "Someone").trim();
      showFriendRequestToast(label + " sent you a friend request");
    }
  } else if (fromId === me) {
    upsertOutgoingFriendRequestRow(row);
  }
  renderRelationshipUiNow({
    rerenderPending: true,
    affectedUserId: otherUserId,
    affectedUsername,
  });
  if (otherUserId) {
    scheduleRelationshipRealtimeProfileHydration([otherUserId], {
      rerenderPending: true,
      affectedUserId: otherUserId,
      affectedUsername,
    });
  }
  scheduleGlobalFriendRequestRefresh(100);
}

function onGlobalMessageRequestChanged(row, eventType = "UPDATE") {
  if (!state.user?.id) return;
  if (!row || typeof row !== "object") {
    logMessageRequestsDebug("realtime event", { eventType: String(eventType || "UPDATE"), row: null });
    void refreshMessageRequestsAndSidebar("message_requests_realtime", { force: true, source: "realtime-empty" }).catch(() => {});
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }
  const me = normId(state.user.id);
  const fromId = getIncomingMessageRequestPeerId(row);
  const toId = getOutgoingMessageRequestPeerId(row);
  const requestId = normId(row?.request_id || row?.id || "");
  if (!fromId && !toId) {
    logMessageRequestsDebug("realtime event", { eventType: String(eventType || "UPDATE"), requestId, reason: "missing-participants" });
    void refreshMessageRequestsAndSidebar("message_requests_realtime", { force: true, source: "realtime-missing-participants" }).catch(() => {});
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }
  if (fromId !== me && toId !== me) return;
  const otherUserId = fromId === me ? toId : fromId;
  const optimisticProfile = getOptimisticRelationshipProfile({ userId: otherUserId });
  const affectedUsername = String(optimisticProfile?.username || row?.username || "").trim();
  const safeEventType = String(eventType || "UPDATE").trim().toUpperCase();
  const status = String(row?.status || (safeEventType === "DELETE" ? "" : "pending")).trim().toLowerCase();
  logMessageRequestsDebug("realtime event", {
    eventType: safeEventType,
    requestId,
    fromId,
    toId,
    status,
  });

  if (requestId && (safeEventType === "DELETE" || status === "rejected" || status === "ignored" || status === "blocked" || status === "expired" || status === "cancelled" || status === "canceled")) {
    optimisticRemoveMessageIncoming(requestId);
    optimisticRemoveMessageOutgoing(requestId);
    if (activeMessageRequestPreviewId === requestId) {
      activeMessageRequestPreviewId = "";
      hideDmRequestBanner();
      leaveActiveDmView({ captureHistory: true });
    }
    renderRelationshipUiNow({
      rerenderPending: true,
      rerenderDmList: true,
      affectedUserId: otherUserId,
      affectedUsername,
    });
    if (otherUserId) {
      scheduleRelationshipRealtimeProfileHydration([otherUserId], {
        rerenderPending: true,
        affectedUserId: otherUserId,
        affectedUsername,
      });
    }
    void refreshMessageRequestsAndSidebar("message_requests_realtime", { force: true, source: "realtime-resolved" }).catch(() => {});
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }

  if (status === "accepted") {
    const acceptedConversationId = normId(row?.conversation_id || "");
    const shouldOpenAcceptedConversation = !!requestId
      && activeMessageRequestPreviewId === requestId
      && !!acceptedConversationId;
    if (requestId) {
      optimisticRemoveMessageIncoming(requestId);
      optimisticRemoveMessageOutgoing(requestId);
      if (activeMessageRequestPreviewId === requestId) {
        activeMessageRequestPreviewId = "";
        hideDmRequestBanner();
      }
    }
    if (otherUserId) {
      upsertDmContactRow({
        other_user_id: otherUserId,
        username: String(optimisticProfile?.username || row?.username || "").trim(),
        display_name: String(optimisticProfile?.display_name || row?.display_name || optimisticProfile?.username || row?.username || "User").trim() || "User",
        avatar_url: optimisticProfile?.avatar_url || row?.avatar_url || null,
        conversation_id: acceptedConversationId,
        _optimistic: false,
      });
    }
    renderRelationshipUiNow({
      rerenderPending: true,
      rerenderDmList: true,
      affectedUserId: otherUserId,
      affectedUsername,
    });
    if (shouldOpenAcceptedConversation) {
      void showDm(acceptedConversationId, { autoAnswerIfPending: true }).catch(() => {});
    }
    queueLightweightDmListRenderFromState();
    if (otherUserId) {
      scheduleRelationshipRealtimeProfileHydration([otherUserId], {
        rerenderPending: true,
        affectedUserId: otherUserId,
        affectedUsername,
      });
    }
    void refreshMessageRequestsAndSidebar("message_requests_realtime", { force: true, source: "realtime-accepted" }).catch(() => {});
    scheduleGlobalFriendRequestRefresh(100);
    return;
  }

  if (toId === me) {
    upsertIncomingMessageRequestRow(row);
  } else if (fromId === me) {
    upsertOutgoingMessageRequestRow(row);
  }
  renderRelationshipUiNow({
    rerenderPending: true,
    rerenderDmList: true,
    affectedUserId: otherUserId,
    affectedUsername,
  });
  if (otherUserId) {
    scheduleRelationshipRealtimeProfileHydration([otherUserId], {
      rerenderPending: true,
      affectedUserId: otherUserId,
      affectedUsername,
    });
  }
  void refreshMessageRequestsAndSidebar("message_requests_realtime", { force: true, source: "realtime-pending" }).catch(() => {});
  scheduleGlobalFriendRequestRefresh(100);
}

function stopGlobalFriendRequestListener({ stopPoll = false, reason = "stopped" } = {}) {
  if (globalFriendRequestRestartTimer) {
    clearTimeout(globalFriendRequestRestartTimer);
    globalFriendRequestRestartTimer = null;
  }
  if (globalFriendRequestChannel) {
    try { supabase.removeChannel(globalFriendRequestChannel); } catch (_) {}
    globalFriendRequestChannel = null;
  }
  globalFriendRequestUserId = "";
  globalFriendRequestAuthToken = "";
  if (stopPoll && friendRequestsSyncFallbackTimer) {
    clearTimeout(friendRequestsSyncFallbackTimer);
    friendRequestsSyncFallbackTimer = null;
  }
  if (stopPoll) friendRequestsSyncFallbackInFlight = false;
  logFriendsRealtimeDebug("status", { status: "STOPPED", reason: String(reason || "stopped") });
}

async function startGlobalFriendRequestListener({ force = false, reason = "start" } = {}) {
  const stateUserId = normId(state.user?.id || "");
  if (!stateUserId) return;
  if (globalFriendRequestRestartTimer) {
    clearTimeout(globalFriendRequestRestartTimer);
    globalFriendRequestRestartTimer = null;
  }

  let session = null;
  try {
    const { data } = await supabase.auth.getSession();
    session = data?.session || null;
  } catch (_) {}
  const currentUserId = normId(session?.user?.id || stateUserId);
  const accessToken = String(session?.access_token || getAuthTokenForKeepAlive() || "").trim();
  if (!currentUserId) return;
  logFriendsRealtimeDebug("session ready", { userId: currentUserId });
  if (accessToken && supabase?.realtime && typeof supabase.realtime.setAuth === "function") {
    try { await Promise.resolve(supabase.realtime.setAuth(accessToken)); } catch (error) {
      logFriendsRealtimeDebug("status", { status: "SET_AUTH_ERROR", error: String(error?.message || error || "unknown") });
    }
  }

  if (!force && globalFriendRequestChannel && globalFriendRequestUserId === currentUserId && globalFriendRequestAuthToken === accessToken) {
    return;
  }
  stopGlobalFriendRequestListener({ stopPoll: false, reason: "resubscribe:" + String(reason || "start") });

  const channelName = "global-friend-requests:" + currentUserId;
  logFriendsRealtimeDebug("subscribing", {
    mode: "unfiltered-rls",
    userId: currentUserId,
    channelName,
  });

  const handleFR = (eventType) => (payload) => {
    const row = payload?.new || payload?.old || null;
    const fromUserId = normId(row?.from_user_id || "");
    const toUserId = normId(row?.to_user_id || "");
    const requestId = normId(row?.request_id || row?.id || "");
    const status = String(row?.status || "").trim().toLowerCase();
    const hasParticipantIds = !!(fromUserId || toUserId);
    const currentUserMatches = !!currentUserId && (fromUserId === currentUserId || toUserId === currentUserId);
    logFriendsRealtimeDebug("change received", {
      eventType: String(eventType || payload?.eventType || "").trim().toUpperCase(),
      requestId,
      fromUserId,
      toUserId,
      status,
      currentUserMatches,
    });
    if (hasParticipantIds && !currentUserMatches) {
      logFriendsRealtimeDebug("ignored unrelated request", { requestId, fromUserId, toUserId });
      return;
    }
    onGlobalFriendRequestChanged(row, eventType);
  };

  globalFriendRequestUserId = currentUserId;
  globalFriendRequestAuthToken = accessToken;
  globalFriendRequestChannel = supabase
    .channel(channelName)
    .on("postgres_changes", { event: "INSERT", schema: "public", table: "friend_requests" }, handleFR("INSERT"))
    .on("postgres_changes", { event: "UPDATE", schema: "public", table: "friend_requests" }, handleFR("UPDATE"))
    .on("postgres_changes", { event: "DELETE", schema: "public", table: "friend_requests" }, handleFR("DELETE"))
    .subscribe((status, error) => {
      logFriendsRealtimeDebug("status", {
        status: String(status || ""),
        error: String(error?.message || error || ""),
        channelName,
        userId: currentUserId,
      });
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        if (globalFriendRequestRestartTimer || !state.user?.id) return;
        globalFriendRequestRestartTimer = setTimeout(() => {
          globalFriendRequestRestartTimer = null;
          void startGlobalFriendRequestListener({ force: true, reason: "restart:" + String(status || "") });
        }, 1200);
      }
    });
}

function startFriendRequestsAuthStateListener() {
  if (friendRequestsAuthStateSubscription) return;
  if (!supabase?.auth || typeof supabase.auth.onAuthStateChange !== "function") return;
  try {
    const { data } = supabase.auth.onAuthStateChange((event, session) => {
      const userId = normId(session?.user?.id || state.user?.id || "");
      setAuthAccessToken(session?.access_token || getAuthTokenForKeepAlive() || "");
      if (!session?.access_token || !userId) {
        stopGlobalFriendRequestListener({ stopPoll: true, reason: "auth:" + String(event || "signed_out") });
        unsubscribeTypingInboxForCurrentUser({ reason: "auth:" + String(event || "signed_out"), clearState: true, clearOutbound: true });
        return;
      }
      logFriendsRealtimeDebug("session ready", { userId });
      subscribeTypingInboxForCurrentUser("auth:" + String(event || "session"));
      void startGlobalFriendRequestListener({ force: true, reason: "auth:" + String(event || "session") });
      try { startGlobalMessageRequestListener(); } catch (_) {}
      void refreshMessageRequestsAndSidebar("auth_ready", { force: true }).catch(() => {});
      startFriendRequestsSyncFallback();
    });
    friendRequestsAuthStateSubscription = data?.subscription || data || null;
  } catch (_) {}
}

function startGlobalMessageRequestListener() {
  if (!state.user?.id) return;
  if (globalMessageRequestRestartTimer) {
    clearTimeout(globalMessageRequestRestartTimer);
    globalMessageRequestRestartTimer = null;
  }
  if (globalMessageRequestChannel) {
    supabase.removeChannel(globalMessageRequestChannel);
    globalMessageRequestChannel = null;
  }

  const mrUserId = state.user.id;
  messageRequestsRealtimeStatus = "subscribing";
  const handleMR = (eventType) => (payload) => {
    const row = payload?.new || payload?.old || null;
    logMessageRequestsDebug("realtime event", {
      eventType: String(eventType || payload?.eventType || "").trim().toUpperCase(),
      requestId: normId(row?.request_id || row?.id || ""),
      fromUserId: getIncomingMessageRequestPeerId(row || {}),
      toUserId: getOutgoingMessageRequestPeerId(row || {}),
      status: String(row?.status || "").trim().toLowerCase(),
    });
    onGlobalMessageRequestChanged(row, eventType);
  };
  globalMessageRequestChannel = supabase
    .channel("global-message-requests:" + mrUserId)
    .on("postgres_changes", { event: "INSERT", schema: "public", table: "message_requests" }, handleMR("INSERT"))
    .on("postgres_changes", { event: "UPDATE", schema: "public", table: "message_requests" }, handleMR("UPDATE"))
    .on("postgres_changes", { event: "DELETE", schema: "public", table: "message_requests" }, handleMR("DELETE"))
    .subscribe((status) => {
      messageRequestsRealtimeStatus = String(status || "");
      logMessageRequestsDebug("realtime status", { status: messageRequestsRealtimeStatus, userId: mrUserId });
      if (status === "SUBSCRIBED") {
        void refreshMessageRequestsAndSidebar("message_requests_realtime_subscribed", { force: true }).catch(() => {});
        return;
      }
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        if (globalMessageRequestRestartTimer || !state.user?.id) return;
        globalMessageRequestRestartTimer = setTimeout(() => {
          globalMessageRequestRestartTimer = null;
          startGlobalMessageRequestListener();
        }, 1200);
      }
    });
}

// ─── USER BLOCKS REALTIME ────────────────────────────────────────────────────
// Blocks are the only relationship table with no realtime subscription.
// Without this, blocking/unblocking only takes effect after a full restart.
//
// What we handle:
//  INSERT → A just blocked someone: remove them from A's friends/DM lists live
//  DELETE → A just unblocked someone: re-render so they can appear again

function onGlobalModerationActionChanged(row, eventType = "UPDATE") {
  if (!state.user?.id) return;
  const actionId = normId(row?.id || "");
  if (eventType === "DELETE") {
    if (!actionId) return;
    moderationInboxReplyPendingActionIds.delete(actionId);
    removeModerationInboxAction(actionId, { render: true });
    scheduleModerationInboxRefresh(120, { render: true });
    return;
  }

  const action = normalizeOwnerModerationActionRow(row);
  if (!action?.id || action.targetUserId !== normId(state.user.id)) return;
  upsertModerationInboxAction(action, { render: true });
  if (!shouldModerationActionRequireResponse(action)) {
    moderationInboxReplyPendingActionIds.delete(action.id);
  }
  scheduleModerationInboxRefresh(120, { render: true });
  if (action.actionType === "ban") {
    void refreshMyModerationState({ enforceBan: true });
  } else if (action.actionType === "unban") {
    void refreshMyModerationState({ enforceBan: false });
  }
}

function startGlobalModerationActionListener() {
  if (!state.user?.id) return;
  if (globalModerationActionRestartTimer) {
    clearTimeout(globalModerationActionRestartTimer);
    globalModerationActionRestartTimer = null;
  }
  if (globalModerationActionChannel) {
    supabase.removeChannel(globalModerationActionChannel);
    globalModerationActionChannel = null;
  }

  const moderationUserId = state.user.id;
  const handleModeration = (eventType) => (payload) => {
    const row = payload?.new || payload?.old || null;
    onGlobalModerationActionChanged(row, eventType);
  };
  globalModerationActionChannel = supabase
    .channel("global-moderation-actions:" + moderationUserId)
    .on("postgres_changes", { event: "INSERT", schema: "public", table: "moderation_actions", filter: `target_user_id=eq.${moderationUserId}` }, handleModeration("INSERT"))
    .on("postgres_changes", { event: "UPDATE", schema: "public", table: "moderation_actions", filter: `target_user_id=eq.${moderationUserId}` }, handleModeration("UPDATE"))
    .on("postgres_changes", { event: "DELETE", schema: "public", table: "moderation_actions", filter: `target_user_id=eq.${moderationUserId}` }, handleModeration("DELETE"))
    .subscribe((status) => {
      if (status === "SUBSCRIBED") {
        scheduleModerationInboxRefresh(0, { render: true });
        return;
      }
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        if (globalModerationActionRestartTimer || !state.user?.id) return;
        globalModerationActionRestartTimer = setTimeout(() => {
          globalModerationActionRestartTimer = null;
          startGlobalModerationActionListener();
        }, 1200);
      }
    });
}

function onGlobalUserBlockChanged(row, eventType) {
  if (!state.user?.id || !row || typeof row !== "object") return;
  const me = normId(state.user.id);
  const blocker = normId(row?.blocker_user_id || "");
  const blocked = normId(row?.blocked_user_id || "");

  // Only handle rows where WE are the blocker (RLS guarantees this anyway).
  if (blocker !== me) return;

  if (eventType === "INSERT" && blocked) {
    const optimisticProfile = getOptimisticRelationshipProfile({ userId: blocked });
    // Optimistically remove the blocked user from in-memory friend/DM state
    // so the UI feels instant. The full refresh settles any edge cases.
    state.friends = (state.friends || []).filter((f) => {
      const fid = normId(f?.other_user_id || f?.id || "");
      return fid !== blocked;
    });
    state.incoming = (state.incoming || []).filter((r) => normId(r?.from_user_id || "") !== blocked);
    state.outgoing = (state.outgoing || []).filter((r) => normId(r?.to_user_id || "") !== blocked);
    state.messageIncoming = (state.messageIncoming || []).filter((r) => getIncomingMessageRequestPeerId(r) !== blocked);
    state.messageOutgoing = (state.messageOutgoing || []).filter((r) => getOutgoingMessageRequestPeerId(r) !== blocked);
    syncMessageRequestStateAliases();
    upsertBlockedUserRow({
      userId: blocked,
      username: String(optimisticProfile?.username || "").trim(),
      displayName: String(optimisticProfile?.display_name || optimisticProfile?.username || "User").trim() || "User",
      avatarUrl: String(optimisticProfile?.avatar_url || "").trim(),
      createdAt: String(row?.created_at || new Date().toISOString()).trim(),
    });
    renderFriends({ skipPresenceRefresh: true });
    renderPending();
    if (settingsActiveTab === "blocked-users") renderBlockedUsersSettingsRowsFromState();
  } else if (eventType === "DELETE" && blocked) {
    removeBlockedUserRowById(blocked);
    if (settingsActiveTab === "blocked-users") renderBlockedUsersSettingsRowsFromState();
  }

  // Always schedule a reconcile pass to settle any server-side edge cases.
  scheduleGlobalFriendRequestRefresh(200);
}

function startGlobalUserBlocksListener() {
  if (!state.user?.id) return;
  if (globalUserBlocksRestartTimer) {
    clearTimeout(globalUserBlocksRestartTimer);
    globalUserBlocksRestartTimer = null;
  }
  if (globalUserBlocksChannel) {
    supabase.removeChannel(globalUserBlocksChannel);
    globalUserBlocksChannel = null;
  }

  const ubUserId = state.user.id;
  globalUserBlocksChannel = supabase
    .channel("global-user-blocks:" + ubUserId)
    // Only listen for rows where I am the blocker (matches the RLS policy exactly).
    .on("postgres_changes", { event: "INSERT", schema: "public", table: "user_blocks", filter: `blocker_user_id=eq.${ubUserId}` }, (payload) => {
      onGlobalUserBlockChanged(payload?.new || null, "INSERT");
    })
    .on("postgres_changes", { event: "DELETE", schema: "public", table: "user_blocks", filter: `blocker_user_id=eq.${ubUserId}` }, (payload) => {
      onGlobalUserBlockChanged(payload?.old || null, "DELETE");
    })
    .subscribe((status) => {
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        if (globalUserBlocksRestartTimer || !state.user?.id) return;
        globalUserBlocksRestartTimer = setTimeout(() => {
          globalUserBlocksRestartTimer = null;
          startGlobalUserBlocksListener();
        }, 1200);
      }
    });
}
// ─────────────────────────────────────────────────────────────────────────────

async function runFriendRequestsSyncFallback() {
  if (friendRequestsSyncFallbackInFlight || !state.user?.id) return;
  if (typeof navigator !== "undefined" && navigator.onLine === false) return;
  friendRequestsSyncFallbackInFlight = true;
  try {
    const previousMessageRequestsFingerprint = buildFriendCollectionsFingerprint([], [], [], getIncomingMessageRequestRows(), getOutgoingMessageRequestRows());
    const [friends, incoming, outgoing, messageIncoming, messageOutgoing] = await Promise.all([
      supabase.rpc("list_my_friends"),
      supabase.rpc("incoming_friend_requests"),
      supabase.rpc("outgoing_friend_requests"),
      supabase.rpc("incoming_message_requests"),
      supabase.rpc("outgoing_message_requests"),
    ]);
    const missingIncomingMessageRpc = isMissingRpcError(messageIncoming?.error);
    const missingOutgoingMessageRpc = isMissingRpcError(messageOutgoing?.error);
    if (friends.error || incoming.error || outgoing.error) return;
    if (messageIncoming.error && !missingIncomingMessageRpc) return;
    if (messageOutgoing.error && !missingOutgoingMessageRpc) return;

    const safeMessageIncoming = missingIncomingMessageRpc ? [] : (messageIncoming.data || []);
    const safeMessageOutgoing = missingOutgoingMessageRpc ? [] : (messageOutgoing.data || []);
    logFriendsPollDebug("fetched", {
      incomingCount: Array.isArray(incoming.data) ? incoming.data.length : 0,
      outgoingCount: Array.isArray(outgoing.data) ? outgoing.data.length : 0,
      friendsCount: Array.isArray(friends.data) ? friends.data.length : 0,
    });

    const nextFp = buildFriendCollectionsFingerprint(
      friends.data || [],
      incoming.data || [],
      outgoing.data || [],
      safeMessageIncoming,
      safeMessageOutgoing,
    );
    if (!nextFp || nextFp === friendRequestsSyncFingerprint) {
      logFriendsPollDebug("skipped unchanged", {
        incomingCount: Array.isArray(incoming.data) ? incoming.data.length : 0,
        outgoingCount: Array.isArray(outgoing.data) ? outgoing.data.length : 0,
        friendsCount: Array.isArray(friends.data) ? friends.data.length : 0,
      });
      return;
    }

    const contactsRes = await listMyMessageContactsRpc().catch(() => ({ data: [], error: null }));

    logFriendsPollDebug("applied changes", {
      incomingCount: Array.isArray(incoming.data) ? incoming.data.length : 0,
      outgoingCount: Array.isArray(outgoing.data) ? outgoing.data.length : 0,
      friendsCount: Array.isArray(friends.data) ? friends.data.length : 0,
    });
    await applyFriendCollectionsData({
      friendsRows: friends.data || [],
      incomingRows: incoming.data || [],
      outgoingRows: outgoing.data || [],
      messageIncomingRows: safeMessageIncoming,
      messageOutgoingRows: safeMessageOutgoing,
      messageContactsRows: !contactsRes?.error && Array.isArray(contactsRes?.data) ? contactsRes.data : null,
      sourceFingerprint: nextFp,
      hydrateProfiles: false,
      syncFriendPreferences: false,
      syncGifFavorites: false,
      reloadDmList: true,
      skipGroupServerCollections: true,
      skipMessageContactsFetch: !contactsRes?.error,
      preserveDmActivityHydration: true,
    });
    const nextMessageRequestsFingerprint = buildFriendCollectionsFingerprint([], [], [], safeMessageIncoming, safeMessageOutgoing);
    if (nextMessageRequestsFingerprint !== previousMessageRequestsFingerprint) {
      logMessageRequestsDebug("notification event refresh", { reason: "friend_requests_poll_changed" });
      void refreshMessageRequestsAndSidebar("notification_event", { force: true }).catch(() => {});
    }
  } catch (_) {
    // best-effort fallback
  } finally {
    friendRequestsSyncFallbackInFlight = false;
  }
}

function isFallbackSyncVisible() {
  if (typeof document === "undefined") return true;
  return document.visibilityState !== "hidden";
}

function getFallbackSyncIntervalMs(kind) {
  const key = String(kind || "").trim();
  const map = isFallbackSyncVisible()
    ? FALLBACK_SYNC_VISIBLE_INTERVAL_MS
    : FALLBACK_SYNC_HIDDEN_INTERVAL_MS;
  const raw = Number(map?.[key]);
  if (!Number.isFinite(raw) || raw < 1000) return 15000;
  return raw;
}

function startFriendRequestsSyncFallback() {
  if (friendRequestsSyncFallbackTimer) clearTimeout(friendRequestsSyncFallbackTimer);
  logFriendsPollDebug("started", {
    userId: normId(state.user?.id || ""),
    intervalMs: getFallbackSyncIntervalMs("friendRequests"),
  });
  const tick = async () => {
    await runFriendRequestsSyncFallback();
    friendRequestsSyncFallbackTimer = setTimeout(() => {
      void tick();
    }, getFallbackSyncIntervalMs("friendRequests"));
  };
  friendRequestsSyncFallbackTimer = setTimeout(() => {
    void tick();
  }, getFallbackSyncIntervalMs("friendRequests"));
  void runFriendRequestsSyncFallback();
}

async function onGlobalConversationMembershipInserted(row) {
  if (!row || !state.user?.id) return;
  const convId = normId(row.conversation_id);
  if (!convId) return;
  clearDmMessageConversationAccessCache(convId);
  serverConversationMemberIdsByConversationId.delete(convId);

  const activeServerCtx = getActiveServerContext();
  const activeServerId = normId(activeServerCtx?.serverId || "");
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (activeServerId && activeConvId && activeConvId === convId) {
    const activeMembers = serverMemberListByServerId.get(activeServerId) || [];
    await renderServerMembersRightPanel(activeServerCtx, activeMembers, {
      forceChannelMembers: true,
    }).catch(() => {});
  }

  const myId = normId(state.user.id);
  if (normId(row.user_id) !== myId) return;

  const serverMembershipCtx = await resolveServerConversationMembershipContext(convId, { allowLookup: true });
  if (serverMembershipCtx?.serverId) {
    const sid = normId(serverMembershipCtx.serverId || "");
    if (sid) {
      serverChannelListByServerId.delete(sid);
      serverChannelCategoryListByServerId.delete(sid);
      const activeServerId = normId(getActiveServerContext()?.serverId || "");
      if (activeServerId && activeServerId === sid) {
        await refreshServerConversationUi({ force: true, reason: "server-channel-change", refreshChannels: true, refreshMembers: true }).catch(() => {});
      }
    }
    return;
  }

  const prevGroupIds = new Set(
    (state.groupDms || [])
      .map((g) => normId(g?.conversationId))
      .filter(Boolean)
  );

  invalidateGroupAndServerCollectionsCache();
  await loadDmList();

  const nextGroupIds = new Set(
    (state.groupDms || [])
      .map((g) => normId(g?.conversationId))
      .filter(Boolean)
  );

  const becameVisibleNow = nextGroupIds.has(convId) && !prevGroupIds.has(convId);
  if (becameVisibleNow && !isDmConversationActivelyViewed(convId) && shouldNotifyInFocus({ type: "group_dm" })) {
    playUiCue("group_dm");
  }
}

async function onGlobalConversationMembershipDeleted(row) {
  if (!row || !state.user?.id) return;
  const convId = normId(row.conversation_id);
  if (!convId) return;
  clearDmMessageConversationAccessCache(convId);
  serverConversationMemberIdsByConversationId.delete(convId);

  const activeServerCtx = getActiveServerContext();
  const activeServerId = normId(activeServerCtx?.serverId || "");
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (activeServerId && activeConvId && activeConvId === convId) {
    const activeMembers = serverMemberListByServerId.get(activeServerId) || [];
    await renderServerMembersRightPanel(activeServerCtx, activeMembers, {
      forceChannelMembers: true,
    }).catch(() => {});
  }

  const myId = normId(state.user.id);
  if (normId(row.user_id) !== myId) return;

  const serverMembershipCtx = await resolveServerConversationMembershipContext(convId, { allowLookup: false });
  if (serverMembershipCtx?.serverId) {
    const sid = normId(serverMembershipCtx.serverId || "");
    const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
    const wasActiveDeletedChannel = activeConvId === convId;
    const activeServerVoiceTransport = !!(
      shouldUseServerVoiceLiveKitTransport(convId)
      && (
        normId(callConversationId || "") === convId
        || isServerVoiceTransportSessionActive(convId)
      )
    );
    const accessLossConfirmation = activeServerVoiceTransport
      ? await confirmServerConversationAccessLoss(convId, { force: true })
      : null;
    const shouldPreserveActiveServerVoiceContext = !!(
      activeServerVoiceTransport
      && accessLossConfirmation
      && !accessLossConfirmation.confirmedLost
    );
    dmUnreadByConversationId.delete(convId);
    persistDmUnreadConversationsToStorage();
    applyDmNotificationDecorations();

    if (normId(callConversationId || "") === convId && inCall) {
      if (shouldPreserveActiveServerVoiceContext) {
        logServerVoiceCleanupTrigger("cleanup.access_lost.skipped", {
          conversationId: convId,
          reasonCode: `cleanup.access_lost.${String(accessLossConfirmation?.reason || "not_confirmed").trim() || "not_confirmed"}`,
          triggeredBy: "onGlobalConversationMembershipDeleted",
          serverId: sid || null,
          channelId: normId(serverMembershipCtx?.channelId || "") || null,
          ...accessLossConfirmation,
          level: "warn",
        });
      } else {
        if (activeServerVoiceTransport) {
          logServerVoiceCleanupTrigger("cleanup.access_lost.confirmed", {
            conversationId: convId,
            reasonCode: `cleanup.access_lost.${String(accessLossConfirmation?.reason || "conversation_members_deleted").trim() || "conversation_members_deleted"}`,
            triggeredBy: "onGlobalConversationMembershipDeleted",
            serverId: sid || null,
            channelId: normId(serverMembershipCtx?.channelId || "") || null,
            ...accessLossConfirmation,
            level: "error",
          });
        }
        await hangupCurrentCallByUser("?? You no longer have access to this channel.");
      }
    }

    if (sid) {
      serverChannelListByServerId.delete(sid);
      serverChannelCategoryListByServerId.delete(sid);
      await refreshServerConversationUi({ force: true, reason: "server-channel-change", refreshChannels: true, refreshMembers: true }).catch(() => {});
    }

    if (shouldPreserveActiveServerVoiceContext) return;
    if (!wasActiveDeletedChannel) return;

    const channels = sid
      ? await fetchServerChannelsForSidebar(sid, { force: true }).catch(() => [])
      : [];
    const nextChannel = (channels || []).find((ch) => normalizeConversationChannelType(ch?.channelType || "") !== "voice")
      || (channels || [])[0]
      || null;
    const serverRow = getServerRowById(sid);
    const serverName = normalizeConversationLabel(serverRow?.name || state.activeDm?.serverName || "Server", "Server");
    const serverIcon = String(serverRow?.iconUrl || "").trim();

    if (nextChannel?.conversationId) {
      const nextType = normalizeConversationChannelType(nextChannel?.channelType || "text");
      await openConversationById(nextChannel.conversationId, {
        kind: "server",
        isGroup: true,
        displayName: normalizeConversationLabel(
          nextChannel.name || (nextType === "voice" ? "voice-lounge" : "general"),
          nextType === "voice" ? "voice-lounge" : "general"
        ),
        serverId: sid,
        serverName,
        avatarUrl: serverIcon,
        channelType: nextType,
      });
      return;
    }

    activeDmId = null;
    state.activeDm = null;
    setMidMode("friends");
    syncDmActiveListHighlight();
    renderGroupsRail();
    setRightSidebarToServerMembers({ active: false });
    return;
  }

  dmUnreadByConversationId.delete(convId);
  persistDmUnreadConversationsToStorage();
  applyDmNotificationDecorations();

  if (normId(activeDmId || state.activeDm?.conversationId || "") === convId) {
    const backBtn = document.getElementById("btnBackToFriends");
    if (backBtn) {
      try { backBtn.click(); } catch (_) {}
    } else {
      activeDmId = null;
      state.activeDm = null;
      setMidMode("friends");
    }
  }

  invalidateGroupAndServerCollectionsCache();
  await loadDmList();
}

function startGlobalDmMembershipListener() {
  if (!state.user?.id) return;
  if (globalDmMembershipRestartTimer) {
    clearTimeout(globalDmMembershipRestartTimer);
    globalDmMembershipRestartTimer = null;
  }
  if (globalDmMembershipChannel) {
    supabase.removeChannel(globalDmMembershipChannel);
    globalDmMembershipChannel = null;
  }

  globalDmMembershipChannel = supabase
    .channel("global-dm-memberships:" + state.user.id)
    .on("postgres_changes", {
      event: "INSERT",
      schema: "public",
      table: "conversation_members",
    }, async (payload) => {
      try {
        await onGlobalConversationMembershipInserted(payload?.new || null);
      } catch (e) {
        console.warn("dm membership realtime insert failed", e);
      }
    })
    .on("postgres_changes", {
      event: "DELETE",
      schema: "public",
      table: "conversation_members",
    }, async (payload) => {
      try {
        await onGlobalConversationMembershipDeleted(payload?.old || null);
      } catch (e) {
        console.warn("dm membership realtime delete failed", e);
      }
    })
    .subscribe((status) => {
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        if (globalDmMembershipRestartTimer || !state.user?.id) return;
        globalDmMembershipRestartTimer = setTimeout(() => {
          globalDmMembershipRestartTimer = null;
          startGlobalDmMembershipListener();
        }, 1200);
      }
    });
}

function buildDmCollectionsFingerprint() {
  const groupKeys = (state.groupDms || [])
    .map((g) => {
      const convId = normId(g?.conversationId);
      if (!convId) return "";
      const members = Number(g?.memberCount || 0);
      const ts = Number(g?.lastMessageAt || 0);
      const name = normalizeConversationLabel(g?.name || "Group DM", "Group DM");
      const avatar = String(g?.avatarUrl || "").trim();
      return `${convId}|${members}|${ts}|${name}|${avatar}`;
    })
    .filter(Boolean)
    .sort();

  const serverKeys = (state.servers || [])
    .map((s) => {
      const convId = normId(s?.defaultConversationId);
      if (!convId) return "";
      const sid = normId(s?.serverId || "");
      const members = Number(s?.memberCount || 0);
      const name = normalizeConversationLabel(s?.name || "Server", "Server");
      const icon = String(s?.iconUrl || "").trim();
      return `${sid}|${convId}|${members}|${name}|${icon}`;
    })
    .filter(Boolean)
    .sort();

  return `${groupKeys.join(",")}::${serverKeys.join(",")}`;
}

function buildActiveServerChannelSyncFingerprint(serverId, channels = [], categories = [], {
  activeConversationId = "",
  visibleMemberIds = [],
} = {}) {
  const sid = normId(serverId || "");
  if (!sid) return "";
  const channelKeys = (Array.isArray(channels) ? channels : [])
    .map((ch) => {
      const conversationId = normId(ch?.conversationId || "");
      if (!conversationId) return "";
      const channelId = normId(ch?.id || "");
      const categoryId = normId(ch?.categoryId || "");
      const channelType = normalizeConversationChannelType(ch?.channelType || "text");
      const name = normalizeConversationLabel(
        ch?.name || (channelType === "voice" ? "voice-lounge" : "general"),
        channelType === "voice" ? "voice-lounge" : "general"
      );
      return [
        channelId,
        conversationId,
        channelType,
        categoryId,
        Number(ch?.position || 0),
        Number(ch?.createdAt || 0),
        name,
        ch?.isPrivate ? "1" : "0",
      ].join("|");
    })
    .filter(Boolean)
    .sort();

  const categoryKeys = (Array.isArray(categories) ? categories : [])
    .map((cat) => {
      const categoryId = normId(cat?.id || "");
      if (!categoryId) return "";
      return [
        categoryId,
        Number(cat?.position || 0),
        Number(cat?.createdAt || 0),
        normalizeServerCategoryName(cat?.name || "Category"),
      ].join("|");
    })
    .filter(Boolean)
    .sort();

  const activeConvId = normId(activeConversationId || "");
  const memberKeys = normalizeUuidArray(visibleMemberIds || []).sort();
  return `${sid}::${activeConvId}::${memberKeys.join(",")}::${channelKeys.join(",")}::${categoryKeys.join(",")}`;
}

async function moveAwayFromUnavailableActiveServerChannel(serverId, channels = []) {
  const sid = normId(serverId || getActiveServerContext()?.serverId || "");
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (!sid || !activeConvId) return false;

  const visibleChannels = Array.isArray(channels) ? channels : [];
  const stillVisible = visibleChannels.some((ch) => normId(ch?.conversationId || "") === activeConvId);
  if (stillVisible) return false;

  dmUnreadByConversationId.delete(activeConvId);
  persistDmUnreadConversationsToStorage();
  applyDmNotificationDecorations();

  const activeServerVoiceTransport = !!(
    shouldUseServerVoiceLiveKitTransport(activeConvId)
    && (
      normId(callConversationId || "") === activeConvId
      || isServerVoiceTransportSessionActive(activeConvId)
    )
  );
  const accessLossConfirmation = activeServerVoiceTransport
    ? await confirmServerConversationAccessLoss(activeConvId, { force: true })
    : null;
  if (activeServerVoiceTransport && !accessLossConfirmation?.confirmedLost) {
    logServerVoiceCleanupTrigger("cleanup.access_lost.skipped", {
      conversationId: activeConvId,
      reasonCode: `cleanup.access_lost.${String(accessLossConfirmation?.reason || "visibility_not_confirmed").trim() || "visibility_not_confirmed"}`,
      triggeredBy: "moveAwayFromUnavailableActiveServerChannel",
      serverId: sid || null,
      visibleChannelCount: visibleChannels.length,
      ...accessLossConfirmation,
      level: "warn",
    });
    return false;
  }

  if (normId(callConversationId || "") === activeConvId && inCall) {
    if (activeServerVoiceTransport) {
      logServerVoiceCleanupTrigger("cleanup.access_lost.confirmed", {
        conversationId: activeConvId,
        reasonCode: `cleanup.access_lost.${String(accessLossConfirmation?.reason || "visibility_confirmed").trim() || "visibility_confirmed"}`,
        triggeredBy: "moveAwayFromUnavailableActiveServerChannel",
        serverId: sid || null,
        visibleChannelCount: visibleChannels.length,
        ...accessLossConfirmation,
        level: "error",
      });
    }
    await hangupCurrentCallByUser("?? You no longer have access to this channel.");
  }

  const nextChannel = visibleChannels.find((ch) => normalizeConversationChannelType(ch?.channelType || "") !== "voice")
    || visibleChannels[0]
    || null;
  const serverRow = getServerRowById(sid);
  const serverName = normalizeConversationLabel(serverRow?.name || state.activeDm?.serverName || "Server", "Server");
  const serverIcon = String(serverRow?.iconUrl || "").trim();

  if (nextChannel?.conversationId) {
    const nextType = normalizeConversationChannelType(nextChannel?.channelType || "text");
    await openConversationById(nextChannel.conversationId, {
      kind: "server",
      isGroup: true,
      displayName: normalizeConversationLabel(
        nextChannel.name || (nextType === "voice" ? "voice-lounge" : "general"),
        nextType === "voice" ? "voice-lounge" : "general"
      ),
      serverId: sid,
      serverName,
      avatarUrl: serverIcon,
      channelType: nextType,
    });
    return true;
  }

  activeDmId = null;
  state.activeDm = null;
  setMidMode("friends");
  syncDmActiveListHighlight();
  renderGroupsRail();
  setRightSidebarToServerMembers({ active: false });
  return true;
}

function syncActiveConversationHeaderFromMeta() {
  const convId = normId(activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return;
  const cachedMeta = getConversationMeta(convId) || {};
  const activeKind = String(state.activeDm?.kind || cachedMeta?.kind || "").trim().toLowerCase();
  if (activeKind !== "group" && activeKind !== "server") return;

  const fallback = activeKind === "server" ? "Server" : "Group DM";
  const nextTitle = normalizeConversationLabel(
    cachedMeta?.displayName || state.activeDm?.displayName || fallback,
    fallback
  );

  state.activeDm = {
    ...(state.activeDm || {}),
    displayName: nextTitle,
    avatarUrl: String(cachedMeta?.avatarUrl || state.activeDm?.avatarUrl || "").trim(),
    kind: activeKind,
    isGroup: true,
  };
  setConversationMeta(convId, {
    displayName: nextTitle,
    avatarUrl: state.activeDm?.avatarUrl || "",
    kind: activeKind,
    isGroup: true,
  });

  const titleEl = document.getElementById("dmTitle");
  if (titleEl && titleEl.textContent !== nextTitle) {
    titleEl.textContent = nextTitle;
    applyDmTitleNameStyle();
  }
  updateDmHeaderAvatar();
}

async function runDmCollectionsSyncFallback() {
  if (dmCollectionsSyncFallbackInFlight || !state.user?.id) return;
  if (typeof navigator !== "undefined" && navigator.onLine === false) return;
  dmCollectionsSyncFallbackInFlight = true;
  try {
    const prevFp = dmCollectionsSyncFingerprint || buildDmCollectionsFingerprint();
    await loadGroupAndServerCollections({ force: false, hydrateGroupMetadata: false });
    const nextFp = buildDmCollectionsFingerprint();
    dmCollectionsSyncFingerprint = nextFp;
    if (nextFp === prevFp) return;
    await loadDmList();
    syncActiveConversationHeaderFromMeta();
  } catch (_) {
    // best-effort fallback
  } finally {
    dmCollectionsSyncFallbackInFlight = false;
  }
}

async function runActiveServerChannelSyncFallback() {
  if (serverActiveChannelSyncFallbackInFlight || !state.user?.id) return;
  if (typeof navigator !== "undefined" && navigator.onLine === false) return;

  const serverCtx = getActiveServerContext();
  const sid = normId(serverCtx?.serverId || "");
  if (!sid) {
    serverActiveChannelSyncServerId = "";
    serverActiveChannelSyncFingerprint = "";
    return;
  }

  serverActiveChannelSyncFallbackInFlight = true;
  try {
    const [channels, categories] = await Promise.all([
      fetchServerChannelsForSidebar(sid, { force: true }).catch(() => []),
      fetchServerChannelCategoriesForSidebar(sid, { force: true }).catch(() => []),
    ]);
    const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
    const visibleMemberIds = activeConvId
      ? await fetchServerConversationMemberIds(activeConvId, { force: false }).catch(() => [])
      : [];
    const nextFingerprint = buildActiveServerChannelSyncFingerprint(sid, channels, categories, {
      activeConversationId: activeConvId,
      visibleMemberIds,
    });
    const prevServerId = serverActiveChannelSyncServerId;
    const prevFingerprint = serverActiveChannelSyncFingerprint;
    serverActiveChannelSyncServerId = sid;
    serverActiveChannelSyncFingerprint = nextFingerprint;

    const activeStillVisible = !activeConvId
      || (channels || []).some((ch) => normId(ch?.conversationId || "") === activeConvId);

    if (prevServerId === sid && prevFingerprint === nextFingerprint && activeStillVisible) return;

    await refreshServerConversationUi({ force: true, reason: "server-channel-change", refreshChannels: true, refreshMembers: true }).catch(() => {});
    if (!activeStillVisible) {
      await moveAwayFromUnavailableActiveServerChannel(sid, channels);
    }
  } finally {
    serverActiveChannelSyncFallbackInFlight = false;
  }
}

function startDmCollectionsSyncFallback() {
  if (dmCollectionsSyncFallbackTimer) clearTimeout(dmCollectionsSyncFallbackTimer);
  const tick = async () => {
    await runDmCollectionsSyncFallback();
    dmCollectionsSyncFallbackTimer = setTimeout(() => {
      void tick();
    }, getFallbackSyncIntervalMs("dmCollections"));
  };
  dmCollectionsSyncFallbackTimer = setTimeout(() => {
    void tick();
  }, getFallbackSyncIntervalMs("dmCollections"));
  void runDmCollectionsSyncFallback();
}

function startActiveServerChannelSyncFallback() {
  if (serverActiveChannelSyncFallbackTimer) clearTimeout(serverActiveChannelSyncFallbackTimer);
  const tick = async () => {
    await runActiveServerChannelSyncFallback();
    serverActiveChannelSyncFallbackTimer = setTimeout(() => {
      void tick();
    }, getFallbackSyncIntervalMs("activeServerChannels"));
  };
  serverActiveChannelSyncFallbackTimer = setTimeout(() => {
    void tick();
  }, getFallbackSyncIntervalMs("activeServerChannels"));
  void runActiveServerChannelSyncFallback();
}

function clearDmPrivacyFollowupRefetch(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId) return;
  const timers = dmPrivacyFollowupRefetchTimersByConversation.get(convId) || [];
  timers.forEach((timer) => clearTimeout(timer));
  dmPrivacyFollowupRefetchTimersByConversation.delete(convId);
}

function scheduleDmPrivacyFollowupRefetch(conversationId = "") {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return;
  clearDmPrivacyFollowupRefetch(convId);
  const timers = [500, 1500].map((delay) => setTimeout(() => {
    const currentActive = normId(activeDmId || state.activeDm?.conversationId || "");
    if (currentActive !== convId) return;
    void refreshDmPrivacyMetaFromServer(convId, { rerender: true, source: "refetch" }).catch((error) => {
      logDmPrivacyDebug("refetch failed", {
        ...getDmPrivacyDebugContext(convId),
        source: "followup",
        error: String(error?.message || error || "unknown"),
      });
    });
  }, delay));
  dmPrivacyFollowupRefetchTimersByConversation.set(convId, timers);
}

function clearDmPrivacyEventRetries(conversationId = "") {
  const convId = normId(conversationId || "");
  if (!convId) return;
  const timers = dmPrivacyEventRetryTimersByConversation.get(convId) || [];
  timers.forEach((timer) => clearTimeout(timer));
  dmPrivacyEventRetryTimersByConversation.delete(convId);
}

function normalizeNullableDmPrivacyEpoch(value) {
  if (value === null || typeof value === "undefined" || String(value).trim() === "") return null;
  const epoch = Number(value);
  if (!Number.isFinite(epoch)) return null;
  return Math.max(0, Math.round(epoch));
}

function normalizeDmPrivacyEventPayload(input = {}) {
  const row = input?.new && typeof input.new === "object" ? input.new : input;
  if (!row || typeof row !== "object") return null;
  const eventType = String(row.event_type || row.eventType || "").trim().toLowerCase();
  const allowedTypes = new Set([
    "encryption_requested",
    "encryption_request_cancelled",
    "encryption_request_declined",
    "encryption_activated",
    "encryption_reset",
    "vault_switched_to_sync",
  ]);
  if (!allowedTypes.has(eventType)) return null;
  const conversationId = normId(row.conversation_id || row.conversationId || "");
  const actorUserId = normId(row.actor_user_id || row.actorUserId || "");
  const targetUserId = normId(row.target_user_id || row.targetUserId || "");
  if (!conversationId || !targetUserId) return null;
  return {
    id: normId(row.id || ""),
    conversationId,
    actorUserId,
    targetUserId,
    eventType,
    privacyState: normalizeDmPrivacyState(row.privacy_state || row.privacyState || "standard"),
    privacyEpoch: normalizeNullableDmPrivacyEpoch(row.privacy_epoch ?? row.privacyEpoch),
    createdAt: String(row.created_at || row.createdAt || "").trim(),
  };
}

function buildDmPrivacyPatchFromEvent(event = {}) {
  const privacyState = normalizeDmPrivacyState(event.privacyState || "standard");
  const patch = {
    kind: "dm",
    dm_privacy_state: privacyState,
    dm_privacy_epoch: event.privacyEpoch,
    dm_privacy_source: event.eventType === "encryption_reset" ? "friendship_removed" : "user",
  };

  if (event.eventType === "encryption_reset" || event.eventType === "vault_switched_to_sync") {
    patch.dm_privacy_request_nonce = null;
    patch.dm_privacy_requested_by = null;
    patch.dm_privacy_requested_at = null;
    patch.dm_privacy_activated_at = null;
    patch.dm_privacy_state = "standard";
    return patch;
  }

  if (event.eventType === "encryption_requested") {
    patch.dm_privacy_requested_by = normId(event.actorUserId || "") || null;
    patch.dm_privacy_requested_at = event.createdAt || null;
    patch.dm_privacy_activated_at = null;
    return patch;
  }

  if (event.eventType === "encryption_activated") {
    patch.dm_privacy_request_nonce = null;
    patch.dm_privacy_requested_by = null;
    patch.dm_privacy_requested_at = null;
    patch.dm_privacy_activated_at = event.createdAt || null;
    return patch;
  }

  if (event.eventType === "encryption_request_declined" || event.eventType === "encryption_request_cancelled") {
    patch.dm_privacy_request_nonce = null;
    patch.dm_privacy_requested_by = null;
    patch.dm_privacy_requested_at = null;
    patch.dm_privacy_activated_at = null;
    return patch;
  }

  return patch;
}

function shouldApplyDmPrivacyEventOptimisticPatch(event = {}) {
  const convId = normId(event.conversationId || "");
  if (!convId) return false;
  const localMeta = getConversationDmPrivacyMeta(convId);
  const localState = normalizeDmPrivacyState(localMeta?.dmPrivacyState || "standard");
  const localEpoch = normalizeDmPrivacyEpoch(localMeta?.dmPrivacyEpoch, 0);
  if (event.privacyEpoch !== null && localState === "private_active" && localEpoch > event.privacyEpoch) {
    return false;
  }
  return true;
}

function applyDmPrivacyEventOptimisticPatch(event = {}) {
  const convId = normId(event.conversationId || "");
  if (!convId || !shouldApplyDmPrivacyEventOptimisticPatch(event)) {
    logDmPrivacyDebug("event patch skipped", {
      ...getDmPrivacyDebugContext(convId),
      eventType: String(event.eventType || ""),
      privacyEpoch: event.privacyEpoch,
    });
    return null;
  }
  const activeMatches = getVisibleDmPrivacyConversationId() === convId;
  return patchConversationPrivacyState(convId, buildDmPrivacyPatchFromEvent(event), {
    rerender: activeMatches,
    refreshKeys: true,
    renderList: true,
    source: "dm-privacy-event:" + String(event.eventType || "unknown"),
  });
}

function getDmPrivacyEventActorLabel(event = {}) {
  const actorId = normId(event.actorUserId || "");
  if (!actorId) return t("dm.privacy.peer_fallback", "your friend");
  const friend = getFriendRowByUserId(actorId) || null;
  const cached = getCachedProfile(actorId) || null;
  return normalizeConversationLabel(
    friend?.display_name
    || friend?.username
    || cached?.display_name
    || cached?.username
    || t("dm.privacy.peer_fallback", "your friend"),
    t("dm.privacy.peer_fallback", "your friend")
  );
}

function maybeShowDmPrivacyEventToast(event = {}, { activeMatches = false, fetchFailed = false } = {}) {
  if (fetchFailed) {
    if (activeMatches) {
      showDmPrivacyToast(t("dm.privacy.toast_state_will_update", "Vault request state will update shortly."));
    }
    return;
  }
  if (!event) return;
  if (event.eventType === "encryption_reset") {
    showDmPrivacyToast(t(
      "dm.privacy.toast_reset_friendship_removed",
      "Vault was reset because you are no longer friends."
    ));
    return;
  }
  if (event.eventType === "vault_switched_to_sync") {
    if (normId(event.actorUserId || "") !== normId(state.user?.id || "")) {
      showDmPrivacyToast(t("dm.privacy.toast_switched_to_sync", "This DM switched back to Sync."));
    }
    return;
  }
  if (event.eventType !== "encryption_requested" || activeMatches) return;
  const actorLabel = getDmPrivacyEventActorLabel(event);
  showDmPrivacyToast(tf(
    "dm.privacy.toast_request_received",
    { name: actorLabel },
    "{name} wants to switch this DM to Vault."
  ));
}

function scheduleDmPrivacyEventFetchRetry(event = {}, attempt = 0) {
  const convId = normId(event.conversationId || "");
  if (!convId) return;
  const delay = DM_PRIVACY_EVENT_RETRY_DELAYS_MS[attempt];
  if (!Number.isFinite(delay)) {
    const activeMatches = normId(activeDmId || state.activeDm?.conversationId || "") === convId;
    maybeShowDmPrivacyEventToast(event, { activeMatches, fetchFailed: true });
    return;
  }
  const timer = setTimeout(() => {
    const timers = (dmPrivacyEventRetryTimersByConversation.get(convId) || []).filter((entry) => entry !== timer);
    if (timers.length) dmPrivacyEventRetryTimersByConversation.set(convId, timers);
    else dmPrivacyEventRetryTimersByConversation.delete(convId);
    void fetchAndPatchDmPrivacyEventState(event, attempt + 1);
  }, delay);
  const timers = dmPrivacyEventRetryTimersByConversation.get(convId) || [];
  timers.push(timer);
  dmPrivacyEventRetryTimersByConversation.set(convId, timers);
}

async function fetchAndPatchDmPrivacyEventState(event = {}, attempt = 0) {
  const convId = normId(event.conversationId || "");
  if (!convId) return null;
  const activeMatches = normId(activeDmId || state.activeDm?.conversationId || "") === convId;
  try {
    const meta = await fetchConversationPrivacyState(convId, {
      rerender: activeMatches,
      source: "dm-privacy-event-fetch:" + String(event.eventType || "unknown"),
    });
    clearDmPrivacyEventRetries(convId);
    return meta;
  } catch (error) {
    logDmPrivacyDebug("event fetch failed", {
      ...getDmPrivacyDebugContext(convId),
      eventType: String(event.eventType || ""),
      attempt,
      error: String(error?.message || error || "unknown"),
    });
    scheduleDmPrivacyEventFetchRetry(event, attempt);
    return null;
  }
}

function handleDmPrivacyEvent(input = {}, options = {}) {
  const opts = options && typeof options === "object" ? options : {};
  const event = normalizeDmPrivacyEventPayload(input);
  const currentUserId = normId(state.user?.id || globalDmPrivacyEventUserId || "");
  const convId = normId(event?.conversationId || "");
  if (event) {
    logDmPrivacyEventsDebug("handle start", {
      conversationId: convId,
      eventType: String(event.eventType || ""),
      source: String(opts.source || "realtime"),
    });
  }
  const targetMatches = !!event && !!currentUserId && normId(event.targetUserId || "") === currentUserId;
  logDmPrivacyDebug("event received", {
    ...getDmPrivacyDebugContext(convId),
    eventType: String(event?.eventType || ""),
    conversationId: convId,
    actorUserId: normId(event?.actorUserId || ""),
    targetUserIdMatchesCurrentUser: targetMatches,
  });
  if (!event || !targetMatches) return;

  clearDmPrivacyEventRetries(convId);
  dmPrivacyPendingEventsByConversation.set(convId, { ...event, receivedAt: Date.now() });
  const activeMatches = normId(activeDmId || state.activeDm?.conversationId || "") === convId;
  applyDmPrivacyEventOptimisticPatch(event);
  if (!opts.suppressToast) maybeShowDmPrivacyEventToast(event, { activeMatches, fetchFailed: false });
  void fetchAndPatchDmPrivacyEventState(event, 0);
}

function getDmPrivacyEventId(event = {}) {
  return normId(event?.id || event?.event_id || event?.eventId || "");
}

function dispatchDmPrivacyEvent(eventInput = {}, { source = "realtime", suppressToast = false } = {}) {
  const event = normalizeDmPrivacyEventPayload(eventInput);
  const eventId = getDmPrivacyEventId(event);
  const sourceLabel = String(source || "realtime");
  if (!event) return false;
  if (eventId && processedDmPrivacyEventIds.has(eventId)) {
    if (sourceLabel === "poll") {
      if (!dmPrivacyPollLoggedDuplicateEventIds.has(eventId)) {
        dmPrivacyPollLoggedDuplicateEventIds.add(eventId);
        logDmPrivacyEventsPollDebug("ignored duplicate", { eventId });
      }
    } else {
      logDmPrivacyEventsDebug("insert ignored duplicate", {
        eventId,
        conversationId: normId(event.conversationId || ""),
        eventType: String(event.eventType || ""),
      });
    }
    return false;
  }
  if (eventId) processedDmPrivacyEventIds.add(eventId);
  handleDmPrivacyEvent(event, { source: sourceLabel, suppressToast });
  if (sourceLabel === "poll") {
    logDmPrivacyEventsPollDebug("handle dispatched", { eventId });
  }
  return true;
}

function getDmPrivacyEventAgeMs(event = {}) {
  const createdAt = String(event?.createdAt || event?.created_at || "").trim();
  if (!createdAt) return 0;
  const ts = Date.parse(createdAt);
  if (!Number.isFinite(ts)) return 0;
  return Math.max(0, Date.now() - ts);
}

function getDmPrivacyEventPollIntervalMs() {
  try {
    if (typeof document !== "undefined" && document.visibilityState === "hidden") return DM_PRIVACY_EVENT_POLL_HIDDEN_MS;
  } catch (_) {}
  return DM_PRIVACY_EVENT_POLL_VISIBLE_MS;
}

function clearGlobalDmPrivacyEventSessionRetry() {
  if (!globalDmPrivacyEventSessionRetryTimer) return;
  clearTimeout(globalDmPrivacyEventSessionRetryTimer);
  globalDmPrivacyEventSessionRetryTimer = null;
}

function scheduleGlobalDmPrivacyEventSessionRetry(reason = "session-missing") {
  if (globalDmPrivacyEventSessionRetryTimer || !isDirectDmE2eeEnabled()) return;
  globalDmPrivacyEventSessionRetryTimer = setTimeout(() => {
    globalDmPrivacyEventSessionRetryTimer = null;
    void startGlobalDmPrivacyEventListener({ force: true, reason });
  }, 800);
}

function scheduleGlobalDmPrivacyEventPoll(delayMs = getDmPrivacyEventPollIntervalMs()) {
  const userId = normId(globalDmPrivacyEventPollUserId || state.user?.id || globalDmPrivacyEventUserId || "");
  if (!userId) return;
  if (globalDmPrivacyEventPollTimer) clearTimeout(globalDmPrivacyEventPollTimer);
  globalDmPrivacyEventPollTimer = setTimeout(() => {
    globalDmPrivacyEventPollTimer = null;
    void runGlobalDmPrivacyEventPoll();
  }, Math.max(0, Number(delayMs) || 0));
}

function stopGlobalDmPrivacyEventPolling({ resetProcessed = false } = {}) {
  if (globalDmPrivacyEventPollTimer) {
    clearTimeout(globalDmPrivacyEventPollTimer);
    globalDmPrivacyEventPollTimer = null;
  }
  const hadPoller = !!globalDmPrivacyEventPollUserId || globalDmPrivacyEventPollInFlight;
  globalDmPrivacyEventPollUserId = "";
  globalDmPrivacyEventPollInFlight = false;
  if (resetProcessed) {
    processedDmPrivacyEventIds.clear();
    dmPrivacyPollLoggedDuplicateEventIds.clear();
    lastDmPrivacyEventCreatedAt = "";
  }
  if (hadPoller) logDmPrivacyEventsPollDebug("stopped", {});
}

function bindGlobalDmPrivacyEventPollVisibilityOnce() {
  if (globalDmPrivacyEventPollVisibilityBound) return;
  globalDmPrivacyEventPollVisibilityBound = true;
  try {
    document.addEventListener("visibilitychange", () => {
      const userId = normId(globalDmPrivacyEventPollUserId || "");
      if (!userId) return;
      scheduleGlobalDmPrivacyEventPoll(getDmPrivacyEventPollIntervalMs());
      logDmPrivacyEventsPollDebug("started", {
        userId,
        intervalMs: getDmPrivacyEventPollIntervalMs(),
      });
    });
  } catch (_) {}
}

function startGlobalDmPrivacyEventPolling(userIdInput = "") {
  const userId = normId(userIdInput || state.user?.id || globalDmPrivacyEventUserId || "");
  if (!userId || !isDirectDmE2eeEnabled()) {
    stopGlobalDmPrivacyEventPolling({ resetProcessed: true });
    return;
  }
  bindGlobalDmPrivacyEventPollVisibilityOnce();
  if (globalDmPrivacyEventPollUserId && globalDmPrivacyEventPollUserId !== userId) {
    stopGlobalDmPrivacyEventPolling({ resetProcessed: true });
  }
  globalDmPrivacyEventPollUserId = userId;
  const intervalMs = getDmPrivacyEventPollIntervalMs();
  logDmPrivacyEventsPollDebug("started", { userId, intervalMs });
  scheduleGlobalDmPrivacyEventPoll(0);
}

function processPolledDmPrivacyEvent(row = {}, currentUserId = "") {
  const event = normalizeDmPrivacyEventPayload(row);
  const eventId = getDmPrivacyEventId(event || row);
  if (!event) return;
  if (event.createdAt) {
    const previous = Date.parse(lastDmPrivacyEventCreatedAt || "");
    const next = Date.parse(event.createdAt);
    if (Number.isFinite(next) && (!Number.isFinite(previous) || next > previous)) {
      lastDmPrivacyEventCreatedAt = event.createdAt;
    }
  }
  if (eventId && processedDmPrivacyEventIds.has(eventId)) {
    if (!dmPrivacyPollLoggedDuplicateEventIds.has(eventId)) {
      dmPrivacyPollLoggedDuplicateEventIds.add(eventId);
      logDmPrivacyEventsPollDebug("ignored duplicate", { eventId });
    }
    return;
  }
  if (normId(event.targetUserId || "") !== normId(currentUserId || "")) return;
  logDmPrivacyEventsPollDebug("new event", {
    eventId,
    eventType: String(event.eventType || ""),
    conversationId: normId(event.conversationId || ""),
  });
  dispatchDmPrivacyEvent(event, {
    source: "poll",
    suppressToast: getDmPrivacyEventAgeMs(event) > DM_PRIVACY_EVENT_STALE_TOAST_SUPPRESS_MS,
  });
}

async function runGlobalDmPrivacyEventPoll() {
  const userId = normId(globalDmPrivacyEventPollUserId || state.user?.id || globalDmPrivacyEventUserId || "");
  if (!isDirectDmE2eeEnabled()) {
    stopGlobalDmPrivacyEventPolling({ resetProcessed: true });
    return;
  }
  if (!userId) {
    stopGlobalDmPrivacyEventPolling({ resetProcessed: true });
    return;
  }
  if (globalDmPrivacyEventPollInFlight) {
    scheduleGlobalDmPrivacyEventPoll(getDmPrivacyEventPollIntervalMs());
    return;
  }
  globalDmPrivacyEventPollInFlight = true;
  try {
    const { data, error } = await supabase
      .from("dm_privacy_events")
      .select("id, conversation_id, actor_user_id, target_user_id, event_type, privacy_state, privacy_epoch, created_at")
      .eq("target_user_id", userId)
      .order("created_at", { ascending: false })
      .limit(20);
    if (error) {
      logDmPrivacyEventsPollDebug("fetched", {
        count: 0,
        userId,
        error: String(error?.message || error || "unknown"),
      });
      return;
    }
    const rows = Array.isArray(data) ? data : [];
    logDmPrivacyEventsPollDebug("fetched", { count: rows.length, userId });
    rows.slice().reverse().forEach((row) => processPolledDmPrivacyEvent(row, userId));
  } catch (error) {
    logDmPrivacyEventsPollDebug("fetched", {
      count: 0,
      userId,
      error: String(error?.message || error || "unknown"),
    });
  } finally {
    globalDmPrivacyEventPollInFlight = false;
    if (normId(globalDmPrivacyEventPollUserId || "") === userId) {
      scheduleGlobalDmPrivacyEventPoll(getDmPrivacyEventPollIntervalMs());
    }
  }
}

function stopGlobalDmPrivacyEventListener() {
  if (globalDmPrivacyEventRestartTimer) {
    clearTimeout(globalDmPrivacyEventRestartTimer);
    globalDmPrivacyEventRestartTimer = null;
  }
  if (globalDmPrivacyEventChannel) {
    try { supabase.removeChannel(globalDmPrivacyEventChannel); } catch (_) {}
    globalDmPrivacyEventChannel = null;
  }
  globalDmPrivacyEventUserId = "";
  globalDmPrivacyEventStatus = "";
  globalDmPrivacyEventAuthToken = "";
}

async function resolveDmPrivacyEventSession(sessionInput = null, reason = "session") {
  if (sessionInput?.user?.id && sessionInput?.access_token) return sessionInput;
  try {
    const { data, error } = await supabase.auth.getSession();
    if (error) {
      logDmPrivacyEventsDebug("status", { status: "SESSION_ERROR", error: String(error?.message || error || "unknown") });
      return null;
    }
    return data?.session || null;
  } catch (error) {
    logDmPrivacyEventsDebug("status", { status: "SESSION_ERROR", error: String(error?.message || error || "unknown"), reason: String(reason || "session") });
    return null;
  }
}

async function startGlobalDmPrivacyEventListener(options = {}) {
  const opts = options && typeof options === "object" ? options : {};
  const reason = String(opts.reason || "manual");
  if (!isDirectDmE2eeEnabled()) {
    stopGlobalDmPrivacyEventListener();
    stopGlobalDmPrivacyEventPolling({ resetProcessed: true });
    return;
  }

  const session = await resolveDmPrivacyEventSession(opts.session || null, reason);
  const sessionUserId = normId(session?.user?.id || "");
  const currentUserId = sessionUserId || normId(state.user?.id || "");
  const accessToken = String(session?.access_token || "").trim();
  if (!currentUserId || !accessToken) {
    logDmPrivacyEventsDebug("status", {
      status: "WAITING_FOR_SESSION",
      error: "",
      reason,
      stateUserId: normId(state.user?.id || ""),
      sessionUserId,
    });
    stopGlobalDmPrivacyEventListener();
    stopGlobalDmPrivacyEventPolling({ resetProcessed: true });
    scheduleGlobalDmPrivacyEventSessionRetry(reason);
    return;
  }

  clearGlobalDmPrivacyEventSessionRetry();
  logDmPrivacyEventsDebug("session ready", { userId: currentUserId });
  startGlobalDmPrivacyEventPolling(currentUserId);

  try {
    if (supabase?.realtime && typeof supabase.realtime.setAuth === "function") {
      await Promise.resolve(supabase.realtime.setAuth(accessToken));
    }
  } catch (error) {
    logDmPrivacyEventsDebug("status", { status: "REALTIME_AUTH_ERROR", error: String(error?.message || error || "unknown") });
  }

  const canReuseChannel = !!(
    !opts.force
    && globalDmPrivacyEventChannel
    && globalDmPrivacyEventUserId === currentUserId
    && globalDmPrivacyEventAuthToken === accessToken
    && (globalDmPrivacyEventStatus === "SUBSCRIBED" || globalDmPrivacyEventStatus === "JOINING")
  );
  if (canReuseChannel) return;
  if (globalDmPrivacyEventChannel) stopGlobalDmPrivacyEventListener();

  const channelName = "global-dm-privacy-events:" + currentUserId;
  const subscriptionMode = "unfiltered-rls";
  logDmPrivacyDebug("event subscription started", {
    ...getDmPrivacyDebugContext(),
    mode: subscriptionMode,
    userId: currentUserId,
    channelName,
    reason,
  });
  logDmPrivacyEventsDebug("subscribing", {
    mode: subscriptionMode,
    userId: currentUserId,
    channelName,
  });

  const channel = supabase.channel(channelName);
  globalDmPrivacyEventChannel = channel;
  globalDmPrivacyEventUserId = currentUserId;
  globalDmPrivacyEventAuthToken = accessToken;
  globalDmPrivacyEventStatus = "JOINING";
  channel
    .on("postgres_changes", {
      event: "INSERT",
      schema: "public",
      table: "dm_privacy_events",
    }, (payload) => {
      const row = payload?.new || payload;
      if (!row) return;
      const event = normalizeDmPrivacyEventPayload(row);
      const callbackCurrentUserId = normId(state.user?.id || currentUserId);
      const targetUserId = normId(event?.targetUserId || row?.target_user_id || row?.targetUserId || "");
      const targetMatchesCurrentUser = !!event && !!callbackCurrentUserId && targetUserId === callbackCurrentUserId;
      logDmPrivacyEventsDebug("insert received", {
        eventId: normId(event?.id || row?.id || ""),
        conversationId: normId(event?.conversationId || row?.conversation_id || row?.conversationId || ""),
        eventType: String(event?.eventType || row?.event_type || row?.eventType || ""),
        actorUserId: normId(event?.actorUserId || row?.actor_user_id || row?.actorUserId || ""),
        targetUserId,
        currentUserId: callbackCurrentUserId,
        targetMatchesCurrentUser,
      });
      if (!event) return;
      if (!targetMatchesCurrentUser) {
        logDmPrivacyEventsDebug("insert ignored target mismatch", {
          eventId: normId(event.id || row?.id || ""),
          conversationId: normId(event.conversationId || row?.conversation_id || row?.conversationId || ""),
          targetUserId,
          currentUserId: callbackCurrentUserId,
        });
        return;
      }
      try {
        dispatchDmPrivacyEvent(event, { source: "realtime" });
      } catch (error) {
        logDmPrivacyDebug("event handler failed", {
          ...getDmPrivacyDebugContext(),
          error: String(error?.message || error || "unknown"),
        });
        logDmPrivacyEventsDebug("status", { status: "HANDLER_ERROR", error: String(error?.message || error || "unknown") });
      }
    })
    .subscribe((status, error) => {
      globalDmPrivacyEventStatus = String(status || "");
      const errorText = String(error?.message || error || "");
      logDmPrivacyDebug("event subscription status", {
        ...getDmPrivacyDebugContext(),
        mode: subscriptionMode,
        status: globalDmPrivacyEventStatus,
        error: errorText,
        channelName,
        userId: currentUserId,
        table: "public.dm_privacy_events",
        publicationTablePresent: "verified",
      });
      logDmPrivacyEventsDebug("status", {
        status: globalDmPrivacyEventStatus,
        error: errorText,
        mode: subscriptionMode,
        channelName,
        userId: currentUserId,
        table: "public.dm_privacy_events",
        publicationTablePresent: "verified",
      });
      if (status !== "CHANNEL_ERROR" && status !== "TIMED_OUT" && status !== "CLOSED") return;
      if (globalDmPrivacyEventChannel !== channel || globalDmPrivacyEventUserId !== currentUserId) return;
      if (globalDmPrivacyEventRestartTimer || !currentUserId) return;
      const restartStatus = globalDmPrivacyEventStatus;
      globalDmPrivacyEventRestartTimer = setTimeout(() => {
        globalDmPrivacyEventRestartTimer = null;
        if (globalDmPrivacyEventChannel === channel) {
          try { supabase.removeChannel(channel); } catch (_) {}
          globalDmPrivacyEventChannel = null;
          globalDmPrivacyEventUserId = "";
          globalDmPrivacyEventStatus = "";
          globalDmPrivacyEventAuthToken = "";
        }
        void startGlobalDmPrivacyEventListener({ force: true, reason: "restart:" + restartStatus });
      }, 1200);
    });
}

function shouldPollActiveDmPrivacy(conversationId = "") {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!state.user?.id || !convId || !isDirectDmE2eeEnabled() || !dmFeatureCaps.dmPrivacyState) return false;
  if (normId(activeDmId || state.activeDm?.conversationId || "") !== convId) return false;
  if (!isDirectDmConversationKind(state.activeDm?.kind || "")) return false;
  return true;
}

function getActiveDmPrivacyPollIntervalMs(conversationId = "") {
  const convId = normId(conversationId || activeDmPrivacyPollConversationId || activeDmId || state.activeDm?.conversationId || "");
  const privacyState = normalizeDmPrivacyState(getConversationDmPrivacyMeta(convId).dmPrivacyState);
  if (privacyState === "standard" || privacyState === "private_requested") return DM_PRIVACY_ACTIVE_POLL_RECONCILE_MS;
  return DM_PRIVACY_ACTIVE_POLL_STABLE_MS;
}

function stopActiveDmPrivacyPolling(reason = "stopped") {
  const stoppedConversationId = normId(activeDmPrivacyPollConversationId || "");
  const hadPoller = !!activeDmPrivacyPollTimer || !!activeDmPrivacyPollConversationId || activeDmPrivacyPollInFlight;
  if (activeDmPrivacyPollTimer) {
    clearTimeout(activeDmPrivacyPollTimer);
    activeDmPrivacyPollTimer = null;
  }
  activeDmPrivacyPollConversationId = "";
  activeDmPrivacyPollInFlight = false;
  if (hadPoller) {
    logDmPrivacyActivePollDebug("stopped", {
      conversationId: stoppedConversationId,
      reason: String(reason || "stopped"),
    });
  }
}

function startActiveDmPrivacyPolling(conversationId = "", { immediate = false } = {}) {
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!shouldPollActiveDmPrivacy(convId)) {
    if (activeDmPrivacyPollConversationId === convId) stopActiveDmPrivacyPolling("not-active-direct-dm");
    return;
  }
  if (activeDmPrivacyPollTimer && activeDmPrivacyPollConversationId === convId && !immediate) return;
  const alreadyPollingConversation = activeDmPrivacyPollConversationId === convId;
  if (activeDmPrivacyPollTimer) clearTimeout(activeDmPrivacyPollTimer);
  activeDmPrivacyPollConversationId = convId;
  const delayMs = immediate ? 0 : getActiveDmPrivacyPollIntervalMs(convId);
  if (!alreadyPollingConversation || immediate) {
    logDmPrivacyActivePollDebug("started", {
      conversationId: convId,
      userId: normId(state.user?.id || ""),
      intervalMs: delayMs,
    });
  }
  activeDmPrivacyPollTimer = setTimeout(() => {
    activeDmPrivacyPollTimer = null;
    void runActiveDmPrivacyPoll(convId);
  }, delayMs);
}

async function reconcileActiveDmPrivacyStateFromServer(conversationId = "", { source = "active-poll" } = {}) {
  const convId = normId(conversationId || activeDmPrivacyPollConversationId || activeDmId || state.activeDm?.conversationId || "");
  if (!convId) return null;
  const localMeta = summarizeDmPrivacyMetaForDebug(getConversationDmPrivacyMeta(convId));
  const { row, error } = await fetchConversationPrivacyRowDirect(convId, { reason: source });
  if (!row) {
    logDmPrivacyActivePollDebug("fetched", {
      conversationId: convId,
      dbState: "unavailable",
      localState: localMeta.state,
      requestedBy: "",
      epoch: localMeta.epoch,
      error: String(error?.message || error || "no_row"),
    });
    throw error || new Error("conversation_privacy_state_unavailable");
  }

  const dbState = normalizeDmPrivacyState(row?.dm_privacy_state || row?.dmPrivacyState || "standard");
  const dbRequestedBy = normId(row?.dm_privacy_requested_by || row?.dmPrivacyRequestedBy || "");
  const dbEpoch = normalizeDmPrivacyEpoch(row?.dm_privacy_epoch ?? row?.dmPrivacyEpoch, 0);
  logDmPrivacyActivePollDebug("fetched", {
    conversationId: convId,
    dbState,
    localState: localMeta.state,
    requestedBy: dbRequestedBy,
    epoch: dbEpoch,
  });

  if (shouldIgnoreDmRequestGraceDowngrade(convId, dbState, localMeta.state)) {
    logDmRequestDebug("confirm mismatch ignored", {
      dbState: "standard",
      rpcState: "private_requested",
      source: String(source || "active-poll"),
    });
    logDmRequestDebug("false-failure prevented", {
      reason: "rpc_requested_confirm_stale",
      source: String(source || "active-poll"),
    });
    return getConversationDmPrivacyMeta(convId);
  }

  const latestLocalMeta = getConversationDmPrivacyMeta(convId);
  const localSignature = getDmPrivacySignature(latestLocalMeta);
  const dbSignature = getDmPrivacySignature({
    ...row,
    kind: String(row?.kind || "dm").trim().toLowerCase() || "dm",
  });
  if (localSignature === dbSignature) {
    logDmPrivacyActivePollDebug("unchanged skip", {
      conversationId: convId,
      state: dbState,
      signature: dbSignature,
    });
    return latestLocalMeta;
  }

  const activeMatchesForPoll = getVisibleDmPrivacyConversationId() === convId;
  const meta = patchConversationPrivacyState(convId, {
    ...row,
    kind: String(row?.kind || "dm").trim().toLowerCase() || "dm",
  }, { rerender: activeMatchesForPoll, refreshKeys: true, source });

  const newState = normalizeDmPrivacyState(meta?.dmPrivacyState || dbState);
  if (localMeta.state !== newState) {
    logDmPrivacyActivePollDebug("state mismatch patched", {
      oldState: localMeta.state,
      newState,
    });
  }
  if (newState === "private_active") {
    void ensureDmE2eeBootstrapStarted();
  }
  return meta;
}

async function runActiveDmPrivacyPoll(conversationId = "") {
  const convId = normId(conversationId || activeDmPrivacyPollConversationId || "");
  if (!shouldPollActiveDmPrivacy(convId)) {
    if (activeDmPrivacyPollConversationId === convId) stopActiveDmPrivacyPolling("no-active-direct-dm");
    return;
  }
  if (activeDmPrivacyPollInFlight) {
    startActiveDmPrivacyPolling(convId);
    return;
  }
  activeDmPrivacyPollInFlight = true;
  try {
    logDmPrivacyDebug("poll", { ...getDmPrivacyDebugContext(convId) });
    await reconcileActiveDmPrivacyStateFromServer(convId, { source: "active-poll" });
  } catch (error) {
    logDmPrivacyDebug("poll failed", {
      ...getDmPrivacyDebugContext(convId),
      error: String(error?.message || error || "unknown"),
    });
  } finally {
    activeDmPrivacyPollInFlight = false;
  }
  if (shouldPollActiveDmPrivacy(convId)) startActiveDmPrivacyPolling(convId);
  else stopActiveDmPrivacyPolling("no-active-direct-dm");
}

function stopActiveDmPrivacyListener() {
  if (activeDmPrivacyRestartTimer) {
    clearTimeout(activeDmPrivacyRestartTimer);
    activeDmPrivacyRestartTimer = null;
  }
  if (activeDmPrivacyChannel) {
    supabase.removeChannel(activeDmPrivacyChannel);
    activeDmPrivacyChannel = null;
  }
  activeDmPrivacyConversationId = "";
  stopActiveDmPrivacyPolling();
}

function startDmPrivacyAuthStateListener() {
  if (dmPrivacyAuthStateSubscription) return;
  if (!supabase?.auth || typeof supabase.auth.onAuthStateChange !== "function") return;
  try {
    const { data } = supabase.auth.onAuthStateChange((event, session) => {
      const convId = normId(activeDmId || state.activeDm?.conversationId || "");
      logDmPrivacyDebug("auth state changed", {
        ...getDmPrivacyDebugContext(convId),
        event: String(event || ""),
        sessionUserId: normId(session?.user?.id || ""),
      });
      if (normId(session?.user?.id || "")) void startGlobalDmPrivacyEventListener({ session, force: true, reason: "auth:" + String(event || "") });
      else {
        stopGlobalDmPrivacyEventListener();
        stopGlobalDmPrivacyEventPolling({ resetProcessed: true });
        stopActiveDmPrivacyListener();
        scheduleGlobalDmPrivacyEventSessionRetry("auth:" + String(event || ""));
      }
      if (!convId || !isDirectDmE2eeEnabled() || !isDirectDmConversationKind(state.activeDm?.kind || "")) return;
      void ensureDmPrivacyFeatureCapsForSync(convId, "auth_state")
        .then(() => refreshDmPrivacyMetaFromServer(convId, { rerender: true, source: "auth-state" }))
        .then(() => {
          if (normId(activeDmId || state.activeDm?.conversationId || "") === convId) {
            startActiveDmPrivacyListener(convId);
          }
        })
        .catch((error) => {
          logDmPrivacyDebug("auth state refresh failed", {
            ...getDmPrivacyDebugContext(convId),
            error: String(error?.message || error || "unknown"),
          });
        });
    });
    dmPrivacyAuthStateSubscription = data?.subscription || true;
  } catch (error) {
    logDmPrivacyDebug("auth listener failed", {
      ...getDmPrivacyDebugContext(),
      error: String(error?.message || error || "unknown"),
    });
  }
}

function startActiveDmPrivacyListener(conversationId) {
  startDmPrivacyAuthStateListener();
  const convId = normId(conversationId || activeDmId || state.activeDm?.conversationId || "");
  const activeMatches = normId(activeDmId || state.activeDm?.conversationId || "") === convId;
  if (!state.user?.id || !convId || !isDirectDmE2eeEnabled()) {
    logDmPrivacyDebug("subscription status", {
      ...getDmPrivacyDebugContext(convId),
      status: "SKIPPED",
      reason: !state.user?.id ? "auth_missing" : (!convId ? "conversation_missing" : "runtime_disabled"),
    });
    stopActiveDmPrivacyListener();
    return;
  }

  if (!dmFeatureCaps.dmPrivacyState) {
    if (activeDmPrivacyChannel && activeDmPrivacyConversationId !== convId) stopActiveDmPrivacyListener();
    logDmPrivacyDebug("subscription status", {
      ...getDmPrivacyDebugContext(convId),
      status: "WAITING_FOR_FEATURE_CAPS",
      conversationId: convId,
      activeConversationMatches: activeMatches,
    });
    void ensureDmPrivacyFeatureCapsForSync(convId, "subscribe")
      .then((ready) => {
        if (!ready) {
          logDmPrivacyDebug("subscription status", {
            ...getDmPrivacyDebugContext(convId),
            status: "FEATURE_CAPS_UNAVAILABLE",
            conversationId: convId,
          });
          return;
        }
        if (normId(activeDmId || state.activeDm?.conversationId || "") !== convId) return;
        void refreshDmPrivacyMetaFromServer(convId, { rerender: true, source: "feature-caps-ready" }).catch(() => {});
        startActiveDmPrivacyListener(convId);
      });
    return;
  }

  if (activeDmPrivacyChannel && activeDmPrivacyConversationId === convId) {
    startActiveDmPrivacyPolling(convId, { immediate: true });
    return;
  }
  stopActiveDmPrivacyListener();
  activeDmPrivacyConversationId = convId;

  const channelName = "dm-privacy:" + state.user.id + ":" + convId;
  const filter = "id=eq." + convId;
  logDmPrivacyDebug("subscribing", {
    ...getDmPrivacyDebugContext(convId),
    channelName,
    filter,
  });
  const channel = supabase.channel(channelName);
  activeDmPrivacyChannel = channel;
  channel
    .on("postgres_changes", {
      event: "UPDATE",
      schema: "public",
      table: "conversations",
      filter,
    }, (payload) => {
      const row = payload?.new || null;
      const payloadConversationId = normId(row?.id || row?.conversation_id || "");
      const currentlyActive = normId(activeDmId || state.activeDm?.conversationId || "");
      const currentMeta = getConversationDmPrivacyMeta(convId);
      logDmPrivacyDebug("realtime update received", {
        ...getDmPrivacyDebugContext(convId),
        payloadConversationId,
        oldState: normalizeDmPrivacyState(currentMeta.dmPrivacyState),
        newState: normalizeDmPrivacyState(row?.dm_privacy_state || row?.dmPrivacyState || "standard"),
        requestedBy: normId(row?.dm_privacy_requested_by || row?.dmPrivacyRequestedBy || ""),
        epoch: normalizeDmPrivacyEpoch(row?.dm_privacy_epoch ?? row?.dmPrivacyEpoch, 0),
        activeConversationMatches: currentlyActive === convId,
      });
      if (!row || payloadConversationId !== convId) return;
      setConversationPrivacyState(convId, row, { rerender: true, refreshKeys: true, source: "realtime" });
    })
    .subscribe((status) => {
      logDmPrivacyDebug("subscription status", {
        ...getDmPrivacyDebugContext(convId),
        status: String(status || ""),
        conversationId: convId,
        channelName,
        filter,
      });
      if (status === "SUBSCRIBED") {
        startActiveDmPrivacyPolling(convId, { immediate: true });
        return;
      }
      if (status !== "CHANNEL_ERROR" && status !== "TIMED_OUT" && status !== "CLOSED") return;
      if (activeDmPrivacyChannel !== channel || activeDmPrivacyConversationId !== convId) return;
      if (activeDmPrivacyRestartTimer || normId(activeDmId || state.activeDm?.conversationId || "") !== convId) return;
      activeDmPrivacyRestartTimer = setTimeout(() => {
        activeDmPrivacyRestartTimer = null;
        if (activeDmPrivacyChannel === channel && activeDmPrivacyConversationId === convId && normId(activeDmId || state.activeDm?.conversationId || "") === convId) {
          activeDmPrivacyChannel = null;
          activeDmPrivacyConversationId = "";
          startActiveDmPrivacyListener(convId);
        }
      }, 1200);
    });
  startActiveDmPrivacyPolling(convId, { immediate: true });
}

async function onGlobalConversationUpdated(row) {
  if (!row || !state.user?.id) return;
  const convId = normId(row?.id || row?.conversation_id || "");
  if (!convId) return;

  const cachedMeta = getConversationMeta(convId) || {};
  const activeConvId = normId(activeDmId || state.activeDm?.conversationId || "");
  const activeMeta = activeConvId === convId ? (state.activeDm || {}) : {};
  const kind = String(
    row?.kind
    || activeMeta?.kind
    || cachedMeta?.kind
    || ""
  ).trim().toLowerCase();
  const looksLikeDirectDmUpdate = kind === "dm" || (
    dmFeatureCaps.dmPrivacyState
    && (
      Object.prototype.hasOwnProperty.call(row, "dm_privacy_state")
      || Object.prototype.hasOwnProperty.call(row, "dm_privacy_request_nonce")
      || Object.prototype.hasOwnProperty.call(row, "dm_privacy_disable_request_nonce")
    )
    && (isDirectDmConversationKind(activeMeta?.kind || "") || isDirectDmConversationKind(cachedMeta?.kind || ""))
  );

  if (looksLikeDirectDmUpdate && isDirectDmE2eeEnabled()) {
    if (dmFeatureCaps.dmPrivacyState) {
      let privacyMeta = applyConversationDmPrivacyMeta(convId, {
        ...cachedMeta,
        ...activeMeta,
        ...(row && typeof row === "object" ? row : {}),
        kind: "dm",
      });
      const isActiveDirectDm = (
        activeConvId === convId
        && isDirectDmConversationKind(state.activeDm?.kind || "")
      );
      if (isActiveDirectDm) {
        privacyMeta = setConversationPrivacyState(convId, row, { rerender: true, refreshKeys: true, renderList: false, source: "global-realtime" }) || privacyMeta;
      }
    }
    return;
  }
  if (kind && kind !== "group") return;

  const isTrackedConversation = (state.groupDms || []).some((g) => normId(g?.conversationId) === convId)
    || (state.servers || []).some((s) => normId(s?.defaultConversationId) === convId)
    || normId(activeDmId || state.activeDm?.conversationId || "") === convId;
  if (!isTrackedConversation) return;

  await runDmCollectionsSyncFallback();
  syncActiveConversationHeaderFromMeta();
}

function startGlobalConversationListener() {
  if (!state.user?.id) return;
  if (globalConversationRestartTimer) {
    clearTimeout(globalConversationRestartTimer);
    globalConversationRestartTimer = null;
  }
  if (globalConversationChannel) {
    supabase.removeChannel(globalConversationChannel);
    globalConversationChannel = null;
  }

  globalConversationChannel = supabase
    .channel("global-conversations:" + state.user.id)
    .on("postgres_changes", {
      event: "UPDATE",
      schema: "public",
      table: "conversations",
    }, async (payload) => {
      try {
        await onGlobalConversationUpdated(payload?.new || null);
      } catch (e) {
        console.warn("conversations realtime update failed", e);
      }
    })
    .subscribe((status) => {
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
        if (globalConversationRestartTimer || !state.user?.id) return;
        globalConversationRestartTimer = setTimeout(() => {
          globalConversationRestartTimer = null;
          startGlobalConversationListener();
        }, 1200);
      }
    });
}

function getServerChannelsRealtimeChannelName(serverId = "") {
  const sid = normId(serverId || "");
  return sid ? `server-channels:${sid}` : "";
}

function getServerIdFromChannelsRealtimePayload(payload = null) {
  return normId(
    payload?.serverId
    || payload?.payload?.serverId
    || payload?.payload?.server_id
    || payload?.new?.server_id
    || payload?.old?.server_id
    || ""
  );
}

function teardownActiveServerChannelsRealtime() {
  if (activeServerChannelsRefreshTimer) {
    clearTimeout(activeServerChannelsRefreshTimer);
    activeServerChannelsRefreshTimer = 0;
  }
  if (activeServerChannelsRealtimeChannel) {
    try { supabase.removeChannel(activeServerChannelsRealtimeChannel); } catch (_) {}
  }
  activeServerChannelsRealtimeChannel = null;
  activeServerChannelsRealtimeKey = "";
}

function setupActiveServerChannelsRealtime(serverId = "") {
  const sid = normId(serverId || "");
  const key = getServerChannelsRealtimeChannelName(sid);
  if (!sid || !state.user?.id || !key) {
    teardownActiveServerChannelsRealtime();
    return null;
  }
  if (activeServerChannelsRealtimeChannel && activeServerChannelsRealtimeKey === key) {
    return activeServerChannelsRealtimeChannel;
  }
  teardownActiveServerChannelsRealtime();

  const onChange = (reason) => (payload) => scheduleActiveChannelsRefresh(reason, payload);
  const channel = supabase
    .channel(key, { config: { broadcast: { self: false } } })
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "server_channels",
      filter: `server_id=eq.${sid}`,
    }, onChange("server_channels_change"))
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "server_channel_categories",
      filter: `server_id=eq.${sid}`,
    }, onChange("server_channel_categories_change"))
    .on("broadcast", { event: "server-channels-changed" }, onChange("channels_broadcast"))
    .subscribe((status, error) => {
      if (status === "SUBSCRIBED") {
        scheduleServerVoiceOccupancyHydration(sid, "channels_realtime_subscribed", {
          delayMs: 0,
          ensureSubscription: true,
        });
        return;
      }
      if (!["CHANNEL_ERROR", "TIMED_OUT", "CLOSED"].includes(String(status || ""))) return;
      const warnKey = `${key}:${status}`;
      if (activeServerChannelsRealtimeWarned.has(warnKey)) return;
      activeServerChannelsRealtimeWarned.add(warnKey);
      console.warn("[channels-realtime] subscription issue", {
        serverId: sid,
        channel: key,
        status,
        message: error?.message || error || "",
        error,
      });
    });

  activeServerChannelsRealtimeChannel = channel;
  activeServerChannelsRealtimeKey = key;
  return channel;
}

function getActiveServerChannelsRuntimeContext() {
  const activeCtx = getActiveServerContext?.() || null;
  const sid = normId(activeCtx?.serverId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
  if (!sid) return { serverId: "", serverCtx: null };
  if (shouldSkipRemovedServerRender(sid, "getActiveServerChannelsRuntimeContext")) return { serverId: "", serverCtx: null };
  const serverRow = getServerRowById(sid) || null;
  const serverCtx = activeCtx || {
    serverId: sid,
    name: normalizeConversationLabel(serverRow?.name || state.activeDm?.serverName || state.activeDm?.displayName || "Server", "Server"),
    iconUrl: String(serverRow?.iconUrl || state.activeDm?.avatarUrl || "").trim(),
    ownerUserId: normId(serverRow?.ownerUserId || state.activeDm?.ownerUserId || ""),
    defaultConversationId: normId(serverRow?.defaultConversationId || state.activeDm?.conversationId || activeDmId || ""),
    memberCount: Number(serverRow?.memberCount || state.activeDm?.memberCount || 0),
  };
  return { serverId: sid, serverCtx: { ...serverCtx, serverId: sid } };
}

function getServerChannelsSidebarBodyElement() {
  return document.querySelector("#serverChannelsPanel .serverChannelsPanel__body") || document.getElementById("serverChannelsPanel");
}

function captureServerChannelSidebarVisualState(serverId = "", { reason = "capture" } = {}) {
  const body = getServerChannelsSidebarBodyElement();
  const panel = document.getElementById("serverChannelsPanel");
  const sid = normId(serverId || panel?.getAttribute?.("data-server-panel-server-id") || getActiveServerIdForSidebar?.() || "");
  const activeEl = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const focusChannelId = normId(activeEl?.closest?.("[data-server-channel-id]")?.getAttribute?.("data-server-channel-id") || "");
  const bodyRect = body?.getBoundingClientRect?.() || null;
  const anchorEl = body && bodyRect
    ? Array.from(body.querySelectorAll("[data-server-channel-id], [data-server-category-section]"))
      .find((el) => {
        const rect = el.getBoundingClientRect();
        return rect.bottom > bodyRect.top + 1 && rect.top < bodyRect.bottom - 1;
      }) || null
    : null;
  const anchorChannelId = normId(anchorEl?.getAttribute?.("data-server-channel-id") || "");
  const anchorCategoryId = normId(
    anchorEl?.getAttribute?.("data-server-category-section")
    || anchorEl?.getAttribute?.("data-server-category-id")
    || ""
  );
  const snapshot = {
    serverId: sid,
    scrollTop: Number(body?.scrollTop || 0) || 0,
    anchorRowId: anchorChannelId ? `channel:${anchorChannelId}` : (anchorCategoryId ? `category:${anchorCategoryId}` : ""),
    anchorOffset: anchorEl && bodyRect ? anchorEl.getBoundingClientRect().top - bodyRect.top : 0,
    focusChannelId,
    activeConversationId: normId(activeDmId || state.activeDm?.conversationId || ""),
    scrollHeight: Number(body?.scrollHeight || 0),
    clientHeight: Number(body?.clientHeight || 0),
    reason: String(reason || "capture"),
  };
  if (sid) {
    serverChannelSidebarScrollTopByServerId.set(sid, snapshot.scrollTop);
    if (snapshot.anchorRowId) serverChannelSidebarAnchorByServerId.set(sid, {
      rowId: snapshot.anchorRowId,
      offset: snapshot.anchorOffset,
    });
  }
  lastServerChannelSidebarScrollDebug = {
    ...(lastServerChannelSidebarScrollDebug || {}),
    activeServerId: sid,
    currentScrollTop: snapshot.scrollTop,
    savedScrollTop: sid ? serverChannelSidebarScrollTopByServerId.get(sid) || 0 : 0,
    anchorRowId: snapshot.anchorRowId,
    anchorOffset: snapshot.anchorOffset,
    scrollHeight: snapshot.scrollHeight,
    clientHeight: snapshot.clientHeight,
    renderReason: snapshot.reason,
    restoreApplied: false,
  };
  return snapshot;
}

function restoreServerChannelSidebarVisualState(snapshot = {}, { reason = "restore", afterLayout = true } = {}) {
  const body = getServerChannelsSidebarBodyElement();
  const panel = document.getElementById("serverChannelsPanel");
  const sid = normId(snapshot.serverId || panel?.getAttribute?.("data-server-panel-server-id") || "");
  if (!body || !sid) return false;
  const savedTop = Number.isFinite(Number(snapshot.scrollTop))
    ? Number(snapshot.scrollTop || 0)
    : Number(serverChannelSidebarScrollTopByServerId.get(sid) || 0);
  const savedAnchor = snapshot.anchorRowId
    ? { rowId: snapshot.anchorRowId, offset: Number(snapshot.anchorOffset || 0) }
    : serverChannelSidebarAnchorByServerId.get(sid) || null;
  const applyRestore = () => {
    const currentBody = getServerChannelsSidebarBodyElement();
    const currentPanelSid = normId(document.getElementById("serverChannelsPanel")?.getAttribute?.("data-server-panel-server-id") || "");
    if (!currentBody || currentPanelSid !== sid) return false;
    let restoredByAnchor = false;
    if (savedAnchor?.rowId) {
      const [kind, id] = String(savedAnchor.rowId).split(":");
      const selector = kind === "channel"
        ? `[data-server-channel-id="${cssEscapeAltaraIdentifier(id)}"]`
        : `[data-server-category-section="${cssEscapeAltaraIdentifier(id)}"]`;
      const anchorEl = currentBody.querySelector(selector);
      if (anchorEl) {
        const bodyRect = currentBody.getBoundingClientRect();
        const delta = anchorEl.getBoundingClientRect().top - bodyRect.top - Number(savedAnchor.offset || 0);
        currentBody.scrollTop = Math.max(0, currentBody.scrollTop + delta);
        restoredByAnchor = true;
      }
    }
    if (!restoredByAnchor) {
      const maxTop = Math.max(0, Number(currentBody.scrollHeight || 0) - Number(currentBody.clientHeight || 0));
      currentBody.scrollTop = Math.max(0, Math.min(savedTop, maxTop));
    }
    serverChannelSidebarScrollTopByServerId.set(sid, Number(currentBody.scrollTop || 0));
    lastServerChannelSidebarScrollDebug = {
      ...(lastServerChannelSidebarScrollDebug || {}),
      activeServerId: sid,
      currentScrollTop: Number(currentBody.scrollTop || 0),
      savedScrollTop: savedTop,
      anchorRowId: savedAnchor?.rowId || "",
      anchorOffset: Number(savedAnchor?.offset || 0),
      scrollHeight: Number(currentBody.scrollHeight || 0),
      clientHeight: Number(currentBody.clientHeight || 0),
      renderReason: String(reason || "restore"),
      restoredByAnchor,
      restoreApplied: true,
    };
    return true;
  };
  const applied = applyRestore();
  if (afterLayout && typeof requestAnimationFrame === "function") requestAnimationFrame(applyRestore);
  const focusId = normId(snapshot.focusChannelId || "");
  if (focusId) {
    const focusTarget = document.querySelector(`[data-server-channel-id="${cssEscapeAltaraIdentifier(focusId)}"]`);
    try { focusTarget?.focus?.({ preventScroll: true }); } catch (_) {}
  }
  return applied;
}

function bindServerChannelSidebarScrollPersistence(serverId = "") {
  const sid = normId(serverId || "");
  const body = getServerChannelsSidebarBodyElement();
  if (!sid || !body || body.dataset.altaraScrollPersistenceServerId === sid) return;
  body.dataset.altaraScrollPersistenceServerId = sid;
  body.addEventListener("scroll", () => {
    if (normId(document.getElementById("serverChannelsPanel")?.getAttribute?.("data-server-panel-server-id") || "") !== sid) return;
    captureServerChannelSidebarVisualState(sid, { reason: "user_scroll" });
  }, { passive: true });
}

function installAltaraServerChannelScrollDebugHelpers() {
  if (typeof window === "undefined") return;
  const inspect = () => {
    const panel = document.getElementById("serverChannelsPanel");
    const body = getServerChannelsSidebarBodyElement();
    const sid = normId(panel?.getAttribute?.("data-server-panel-server-id") || getActiveServerIdForSidebar?.() || "");
    const anchor = serverChannelSidebarAnchorByServerId.get(sid) || null;
    return {
      ...(lastServerChannelSidebarScrollDebug || {}),
      activeServerId: sid,
      currentScrollTop: Number(body?.scrollTop || 0),
      savedScrollTop: Number(serverChannelSidebarScrollTopByServerId.get(sid) || 0),
      anchorRowId: anchor?.rowId || lastServerChannelSidebarScrollDebug?.anchorRowId || "",
      anchorOffset: Number(anchor?.offset || lastServerChannelSidebarScrollDebug?.anchorOffset || 0),
      scrollHeight: Number(body?.scrollHeight || 0),
      clientHeight: Number(body?.clientHeight || 0),
    };
  };
  window.altaraDebugServerChannelScroll = {
    inspect,
    capture() {
      const sid = inspect().activeServerId;
      return captureServerChannelSidebarVisualState(sid, { reason: "debug_capture" });
    },
    restore() {
      const sid = inspect().activeServerId;
      return restoreServerChannelSidebarVisualState({
        serverId: sid,
        scrollTop: serverChannelSidebarScrollTopByServerId.get(sid) || 0,
        anchorRowId: serverChannelSidebarAnchorByServerId.get(sid)?.rowId || "",
        anchorOffset: serverChannelSidebarAnchorByServerId.get(sid)?.offset || 0,
      }, { reason: "debug_restore", afterLayout: true });
    },
    simulateSilentRefresh() {
      const { serverId: sid, serverCtx } = getActiveServerChannelsRuntimeContext();
      if (!sid || !serverCtx) return { ok: false, error: "no_active_server" };
      const before = inspect();
      renderServerChannelsPanel(
        serverCtx,
        serverChannelListByServerId.get(sid) || [],
        serverMemberListByServerId.get(sid) || [],
        serverChannelCategoryListByServerId.get(sid) || []
      );
      return { ok: true, before, after: inspect() };
    },
  };
}
installAltaraServerChannelScrollDebugHelpers();

function captureServerChannelItemRects() {
  const rects = new Map();
  document.querySelectorAll("#serverChannelsPanel [data-server-channel-id], #serverChannelsPanel [data-server-category-id]").forEach((el) => {
    if (!(el instanceof HTMLElement)) return;
    const channelId = normId(el.getAttribute("data-server-channel-id") || "");
    const categoryId = normId(el.getAttribute("data-server-category-id") || el.getAttribute("data-server-category-toggle") || "");
    const key = channelId ? `channel:${channelId}` : (categoryId ? `category:${categoryId}` : "");
    if (!key || rects.has(key)) return;
    rects.set(key, el.getBoundingClientRect());
  });
  return rects;
}

function animateServerChannelListReorder(previousRects = new Map()) {
  if (!(previousRects instanceof Map) || !previousRects.size) return;
  requestAnimationFrame(() => {
    document.querySelectorAll("#serverChannelsPanel [data-server-channel-id], #serverChannelsPanel [data-server-category-id]").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      const channelId = normId(el.getAttribute("data-server-channel-id") || "");
      const categoryId = normId(el.getAttribute("data-server-category-id") || el.getAttribute("data-server-category-toggle") || "");
      const key = channelId ? `channel:${channelId}` : (categoryId ? `category:${categoryId}` : "");
      const previous = key ? previousRects.get(key) : null;
      if (!previous) return;
      const next = el.getBoundingClientRect();
      const dy = Math.round(previous.top - next.top);
      if (!dy) return;
      el.style.transition = "transform 0s";
      el.style.transform = `translateY(${dy}px)`;
      requestAnimationFrame(() => {
        el.style.transition = "transform 140ms ease";
        el.style.transform = "";
        window.setTimeout(() => {
          if (el.style.transition === "transform 140ms ease") el.style.transition = "";
        }, 180);
      });
    });
  });
}

function getServerChannelComparableKey(row = {}) {
  return [
    normId(row?.id || ""),
    normId(row?.conversationId || row?.conversation_id || ""),
    String(row?.name || ""),
    normalizeConversationChannelType(row?.channelType || row?.channel_type || "text"),
    normId(row?.categoryId || row?.category_id || ""),
    String(Number(row?.position || 0) || 0),
    String(!!row?.isPrivate),
    String(clampServerVoiceUserLimit(row?.userLimit ?? row?.user_limit ?? 0, 0)),
    normalizeServerVoiceMediaMode(row?.mediaMode || row?.media_mode || "audio_only", "audio_only"),
  ].join("|");
}

function getServerCategoryComparableKey(row = {}) {
  return [
    normId(row?.id || ""),
    String(row?.name || ""),
    String(Number(row?.position || 0) || 0),
  ].join("|");
}

function areServerChannelSnapshotsEqual(current = [], next = [], categoryCurrent = [], categoryNext = []) {
  const currentKeys = (Array.isArray(current) ? current : []).map(getServerChannelComparableKey).join("\n");
  const nextKeys = (Array.isArray(next) ? next : []).map(getServerChannelComparableKey).join("\n");
  if (currentKeys !== nextKeys) return false;
  const currentCategoryKeys = (Array.isArray(categoryCurrent) ? categoryCurrent : []).map(getServerCategoryComparableKey).join("\n");
  const nextCategoryKeys = (Array.isArray(categoryNext) ? categoryNext : []).map(getServerCategoryComparableKey).join("\n");
  return currentCategoryKeys === nextCategoryKeys;
}

function mergeStableServerChannelRows(current = [], next = []) {
  const currentById = new Map((Array.isArray(current) ? current : []).map((row) => [normId(row?.id || ""), row]).filter(([id]) => !!id));
  return (Array.isArray(next) ? next : []).map((row) => {
    const id = normId(row?.id || "");
    const previous = id ? currentById.get(id) : null;
    return previous && getServerChannelComparableKey(previous) === getServerChannelComparableKey(row) ? previous : row;
  });
}

function mergeStableServerCategoryRows(current = [], next = []) {
  const currentById = new Map((Array.isArray(current) ? current : []).map((row) => [normId(row?.id || ""), row]).filter(([id]) => !!id));
  return (Array.isArray(next) ? next : []).map((row) => {
    const id = normId(row?.id || "");
    const previous = id ? currentById.get(id) : null;
    return previous && getServerCategoryComparableKey(previous) === getServerCategoryComparableKey(row) ? previous : row;
  });
}

async function fetchServerChannelCategoriesSnapshotForRealtime(serverId = "") {
  const sid = normId(serverId || "");
  if (!sid) return { ok: false, categories: [], error: { message: "server_id missing" } };
  try {
    const { data, error } = await supabase
      .from("server_channel_categories")
      .select("id, server_id, name, position, created_at")
      .eq("server_id", sid)
      .order("position", { ascending: true })
      .order("created_at", { ascending: true });
    if (error) return { ok: false, categories: serverChannelCategoryListByServerId.get(sid) || [], error };
    const categories = (Array.isArray(data) ? data : []).map((row) => {
      const id = normId(row?.id || "");
      if (!id) return null;
      return {
        id,
        serverId: sid,
        name: normalizeServerCategoryName(row?.name || "Category"),
        position: Number(row?.position || 0),
        createdAt: Date.parse(String(row?.created_at || "")) || 0,
      };
    }).filter(Boolean).sort((a, b) => (
      Number(a.position || 0) - Number(b.position || 0)
      || Number(a.createdAt || 0) - Number(b.createdAt || 0)
      || String(a.name || "").localeCompare(String(b.name || ""))
    ));
    return { ok: true, categories, error: null };
  } catch (error) {
    return { ok: false, categories: serverChannelCategoryListByServerId.get(sid) || [], error };
  }
}

function renderServerChannelsSnapshotSilently(serverId, channels = [], categories = [], options = {}) {
  const sid = normId(serverId || "");
  if (shouldSkipRemovedServerRender(sid, "renderServerChannelsSnapshotSilently")) return false;
  const { serverCtx } = getActiveServerChannelsRuntimeContext();
  if (!sid || !serverCtx || normId(serverCtx.serverId || "") !== sid) return false;
  const visualState = captureServerChannelSidebarVisualState();
  const previousRects = captureServerChannelItemRects();
  const body = getServerChannelsSidebarBodyElement();
  body?.classList?.add("is-realtime-refreshing");
  try {
    renderServerChannelsPanel(serverCtx, channels, serverMemberListByServerId.get(sid) || [], categories || []);
    document.querySelectorAll("#serverChannelsPanel [data-server-channel-id], #serverChannelsPanel .serverChannelsCategory[data-server-category-section]").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      const channelId = normId(el.getAttribute("data-server-channel-id") || "");
      const categoryId = normId(el.getAttribute("data-server-category-section") || el.getAttribute("data-server-category-id") || "");
      const key = channelId ? `channel:${channelId}` : (categoryId ? `category:${categoryId}` : "");
      if (!key || previousRects.has(key)) return;
      el.classList.add("is-realtime-new");
      window.setTimeout(() => el.classList.remove("is-realtime-new"), 180);
    });
    restoreServerChannelSidebarVisualState(visualState);
    animateServerChannelListReorder(previousRects);
    if (options.reason) activeServerChannelsRealtimeState.lastAppliedPayloadReason = String(options.reason || "");
    return true;
  } finally {
    requestAnimationFrame(() => body?.classList?.remove("is-realtime-refreshing"));
  }
}

function applyServerChannelsSnapshot(serverId, nextChannels = [], nextCategories = [], options = {}) {
  const sid = normId(serverId || "");
  if (!sid) return { changed: false, rendered: false };
  const currentChannels = serverChannelListByServerId.get(sid) || [];
  const currentCategories = serverChannelCategoryListByServerId.get(sid) || [];
  const sortedChannels = (Array.isArray(nextChannels) ? nextChannels : []).slice().sort((a, b) => (
    Number(a.position || 0) - Number(b.position || 0)
    || Number(a.createdAt || 0) - Number(b.createdAt || 0)
    || String(a.name || "").localeCompare(String(b.name || ""))
  ));
  const sortedCategories = (Array.isArray(nextCategories) ? nextCategories : []).slice().sort((a, b) => (
    Number(a.position || 0) - Number(b.position || 0)
    || Number(a.createdAt || 0) - Number(b.createdAt || 0)
    || String(a.name || "").localeCompare(String(b.name || ""))
  ));

  if (areServerChannelSnapshotsEqual(currentChannels, sortedChannels, currentCategories, sortedCategories)) {
    return { changed: false, rendered: false };
  }

  const stableChannels = mergeStableServerChannelRows(currentChannels, sortedChannels);
  const stableCategories = mergeStableServerCategoryRows(currentCategories, sortedCategories);
  serverChannelListByServerId.set(sid, stableChannels);
  serverChannelCategoryListByServerId.set(sid, stableCategories);
  serverChannelLoadErrorByServerId.delete(sid);
  setServerChannelLoadState(sid, "ready", { reason: options.reason || "channels-realtime-snapshot" });
  scheduleCallRealtimeSubscriptionSync(0);

  const rendered = renderServerChannelsSnapshotSilently(sid, stableChannels, stableCategories, { reason: options.reason || "channels-realtime-snapshot" });
  reprojectServerVoiceOccupancy(sid, `channel_snapshot:${options.reason || "channels-realtime-snapshot"}`);
  if (normId(serverSettingsServerId || "") === sid) {
    const previousSettingsState = getServerSettingsChannelsState(sid);
    serverSettingsChannelsStateByServerId.set(sid, {
      ...previousSettingsState,
      loaded: true,
      loading: false,
      error: null,
      snapshot: getServerSettingsChannelsSnapshot(sid).fingerprint,
      lastLoadedAt: Date.now(),
      lastReason: options.reason || "channels-realtime-snapshot",
    });
    renderServerSettingsChannelsPanel({ reason: options.reason || "channels-realtime-snapshot" });
  }
  return { changed: true, rendered };
}

function applyServerChannelRealtimePayloadLocally(serverId = "", payload = null, reason = "channels_realtime") {
  const sid = normId(serverId || getServerIdFromChannelsRealtimePayload(payload) || "");
  if (!sid) return false;
  const eventType = String(payload?.eventType || payload?.event || "").trim().toUpperCase();
  const data = payload?.payload && typeof payload.payload === "object" ? payload.payload : payload;
  const payloadReason = String(data?.reason || reason || "").trim();
  const currentChannels = (serverChannelListByServerId.get(sid) || []).slice();
  const currentCategories = (serverChannelCategoryListByServerId.get(sid) || []).slice();
  let nextChannels = currentChannels;
  let nextCategories = currentCategories;
  let changed = false;

  const upsertChannel = (row) => {
    const normalized = normalizeServerChannelSidebarRow(row, sid, {
      hasPositionColumn: true,
      hasCreatedAtColumn: true,
      hasChannelTypeColumn: true,
      hasCategoryIdColumn: true,
      hasIsPrivateColumn: true,
      hasUserLimitColumn: true,
      hasMediaModeColumn: true,
    });
    if (!normalized) return;
    const idx = nextChannels.findIndex((ch) => normId(ch?.id || "") === normalized.id);
    nextChannels = nextChannels.slice();
    if (idx >= 0) nextChannels[idx] = { ...nextChannels[idx], ...normalized };
    else nextChannels.push(normalized);
    changed = true;
  };
  const removeChannel = (id) => {
    const rid = normId(id || "");
    if (!rid) return;
    const filtered = nextChannels.filter((ch) => normId(ch?.id || "") !== rid);
    if (filtered.length !== nextChannels.length) {
      nextChannels = filtered;
      changed = true;
    }
  };
  const upsertCategory = (row) => {
    const id = normId(row?.id || row?.categoryId || "");
    if (!id) return;
    const normalized = {
      id,
      serverId: sid,
      name: normalizeServerCategoryName(row?.name || row?.categoryName || "Category"),
      position: Number(row?.position || 0),
      createdAt: Date.parse(String(row?.created_at || row?.createdAt || "")) || Number(row?.createdAt || 0) || 0,
    };
    const idx = nextCategories.findIndex((cat) => normId(cat?.id || "") === id);
    nextCategories = nextCategories.slice();
    if (idx >= 0) nextCategories[idx] = { ...nextCategories[idx], ...normalized };
    else nextCategories.push(normalized);
    changed = true;
  };
  const removeCategory = (id) => {
    const cid = normId(id || "");
    if (!cid) return;
    const filtered = nextCategories.filter((cat) => normId(cat?.id || "") !== cid);
    if (filtered.length !== nextCategories.length) {
      nextCategories = filtered;
      changed = true;
    }
  };

  if (eventType === "DELETE" && payload?.old) {
    if (payload?.old?.conversation_id || payload?.old?.channel_type || payload?.old?.category_id) removeChannel(payload.old.id);
    else removeCategory(payload.old.id);
  } else if ((eventType === "INSERT" || eventType === "UPDATE") && payload?.new) {
    if (payload?.new?.deleted_at) removeChannel(payload.new.id);
    else if (payload?.new?.conversation_id || payload?.new?.channel_type || payload?.new?.category_id) upsertChannel(payload.new);
    else upsertCategory(payload.new);
  } else if (data?.channel && typeof data.channel === "object") {
    upsertChannel(data.channel);
  } else if (Array.isArray(data?.channels)) {
    data.channels.forEach((row) => upsertChannel(row));
  } else if (data?.category && typeof data.category === "object") {
    upsertCategory(data.category);
  } else if (Array.isArray(data?.categories)) {
    data.categories.forEach((row) => upsertCategory(row));
  } else if (payloadReason === "channel_deleted") {
    removeChannel(data?.channelId || data?.changedChannelIds?.[0]);
  } else if (payloadReason === "category_deleted") {
    const deletedCategoryId = normId(data?.categoryId || data?.changedCategoryIds?.[0] || "");
    removeCategory(deletedCategoryId);
    if (deletedCategoryId) {
      nextChannels = nextChannels.map((channel) => (
        normId(channel?.categoryId || "") === deletedCategoryId
          ? { ...channel, categoryId: "" }
          : channel
      ));
      changed = true;
    }
  } else if (payloadReason === "channel_updated" && data?.channelId && data?.patch) {
    const idx = nextChannels.findIndex((ch) => normId(ch?.id || "") === normId(data.channelId));
    if (idx >= 0) {
      nextChannels = nextChannels.slice();
      nextChannels[idx] = {
        ...nextChannels[idx],
        name: data.patch.name ? normalizeConversationLabel(data.patch.name, nextChannels[idx].name || "general") : nextChannels[idx].name,
        channelType: data.patch.channel_type || data.patch.channelType || nextChannels[idx].channelType,
        categoryId: Object.prototype.hasOwnProperty.call(data.patch, "category_id") ? normId(data.patch.category_id || "") : nextChannels[idx].categoryId,
        position: Object.prototype.hasOwnProperty.call(data.patch, "position") ? Number(data.patch.position || 0) : nextChannels[idx].position,
      };
      changed = true;
    }
  } else if (payloadReason === "category_updated" && data?.categoryId && data?.patch) {
    const idx = nextCategories.findIndex((cat) => normId(cat?.id || "") === normId(data.categoryId));
    if (idx >= 0) {
      nextCategories = nextCategories.slice();
      nextCategories[idx] = {
        ...nextCategories[idx],
        name: data.patch.name ? normalizeServerCategoryName(data.patch.name) : nextCategories[idx].name,
        position: Object.prototype.hasOwnProperty.call(data.patch, "position") ? Number(data.patch.position || 0) : nextCategories[idx].position,
      };
      changed = true;
    }
  } else if (payloadReason === "channel_reordered" && Array.isArray(data?.orderedChannelIds)) {
    const order = new Map(data.orderedChannelIds.map((id, index) => [normId(id), index]));
    nextChannels = nextChannels.map((ch) => order.has(normId(ch?.id || "")) ? { ...ch, position: order.get(normId(ch?.id || "")) } : ch);
    changed = true;
  } else if (payloadReason === "category_reordered" && Array.isArray(data?.orderedCategoryIds)) {
    const order = new Map(data.orderedCategoryIds.map((id, index) => [normId(id), index]));
    nextCategories = nextCategories.map((cat) => order.has(normId(cat?.id || "")) ? { ...cat, position: order.get(normId(cat?.id || "")) } : cat);
    changed = true;
  }

  if (!changed) return false;
  activeServerChannelsRealtimeState.lastAppliedPayloadReason = payloadReason || reason;
  applyServerChannelsSnapshot(sid, nextChannels, nextCategories, { reason: payloadReason || reason });
  return true;
}

function scheduleActiveChannelsRefresh(reason = "channels_realtime", payload = null) {
  const activeCtx = getActiveServerContext?.() || null;
  const activeServerId = normId(activeCtx?.serverId || getActiveServerIdForSidebar?.() || state.activeDm?.serverId || "");
  const payloadServerId = getServerIdFromChannelsRealtimePayload(payload);
  const sid = normId(payloadServerId || activeServerId || "");
  if (!sid || (activeServerId && sid !== activeServerId)) return;
  const normalizedReason = String(reason || "").toLowerCase();
  const canAffectChannelAccess = !normalizedReason.includes("categor")
    && (
      normalizedReason.includes("channel")
      || !!payload?.new?.conversation_id
      || !!payload?.old?.conversation_id
      || !!payload?.data?.channelId
    );
  if (canAffectChannelAccess) {
    invalidateServerMessageHistoryForServer(sid, `channels:${reason}`, {
      preserveValidSnapshot: false,
    });
  }

  const appliedLocal = applyServerChannelRealtimePayloadLocally(sid, payload, reason);
  activeServerChannelsRealtimeState.pendingRefresh = true;
  activeServerChannelsRealtimeState.lastReason = String(reason || "channels_realtime");
  activeServerChannelsRealtimeState.silentMode = true;

  if (activeServerChannelsRefreshTimer) clearTimeout(activeServerChannelsRefreshTimer);
  activeServerChannelsRefreshTimer = setTimeout(() => {
    activeServerChannelsRefreshTimer = 0;
    void refreshActiveServerChannelsFromRealtime(reason, payload, {
      silent: true,
      preserveExisting: true,
      localApplied: appliedLocal,
      historyAccessChanged: canAffectChannelAccess,
    });
  }, appliedLocal ? 320 : 140);
}

async function refreshActiveServerChannelsFromRealtime(reason = "channels_realtime", payload = null, options = {}) {
  const { serverId: sid, serverCtx } = getActiveServerChannelsRuntimeContext();
  if (!sid || !state.user?.id) return false;
  const payloadServerId = getServerIdFromChannelsRealtimePayload(payload);
  if (payloadServerId && payloadServerId !== sid) return false;

  const silent = options?.silent !== false;
  const canAffectChannelAccess = options?.historyAccessChanged === true;
  const previousActiveConversationId = normId(activeDmId || state.activeDm?.conversationId || "");
  activeServerChannelsRealtimeState = {
    ...activeServerChannelsRealtimeState,
    isRefreshing: true,
    pendingRefresh: false,
    silentMode: silent,
    lastReason: String(reason || "channels_realtime"),
  };
  try { console.info("[channels-realtime] refresh", { serverId: sid, reason, silent, payload }); } catch (_) {}

  const previousChannels = serverChannelListByServerId.get(sid) || [];
  const previousCategories = serverChannelCategoryListByServerId.get(sid) || [];
  try {
    const [channelResult, categoryResult] = await Promise.all([
      fetchServerChannelsForSidebarResult(sid, { force: true }),
      fetchServerChannelCategoriesSnapshotForRealtime(sid),
    ]);
    if (channelResult?.ok === false && !channelResult.channels?.length) {
      throw channelResult.error || new Error("channels_realtime_refresh_failed");
    }
    if (categoryResult?.ok === false) {
      console.warn("[channels-realtime] categories silent refresh failed", { serverId: sid, message: categoryResult.error?.message || categoryResult.error, error: categoryResult.error });
    }
    const nextChannels = Array.isArray(channelResult?.channels) && channelResult.channels.length
      ? channelResult.channels
      : previousChannels;
    const nextCategories = categoryResult?.ok === true ? categoryResult.categories : previousCategories;
    serverChannelListByServerId.set(sid, previousChannels);
    serverChannelCategoryListByServerId.set(sid, previousCategories);
    const applyResult = applyServerChannelsSnapshot(sid, nextChannels, nextCategories, { reason: String(reason || "channels_realtime") });
    reprojectServerVoiceOccupancy(sid, `channels:${reason}:cached`);
    scheduleServerVoiceOccupancyHydration(sid, `channels:${reason}`, {
      delayMs: 0,
      ensureSubscription: true,
    });

    const channelsAfterApply = serverChannelListByServerId.get(sid) || nextChannels;
    const hasChannelLoadError = !!serverChannelLoadErrorByServerId.get(sid);
    if (previousActiveConversationId && !hasChannelLoadError) {
      const stillExists = channelsAfterApply.some((ch) => normId(ch?.conversationId || "") === previousActiveConversationId);
      if (!stillExists && normId(state.activeDm?.serverId || serverCtx?.serverId || "") === sid) {
        const nextChannel = channelsAfterApply.find((ch) => normalizeConversationChannelType(ch?.channelType || "") !== "voice")
          || channelsAfterApply[0]
          || null;
        if (nextChannel?.conversationId) {
          const serverRow = getServerRowById(sid) || null;
          const nextType = normalizeConversationChannelType(nextChannel?.channelType || "text");
          await openConversationById(nextChannel.conversationId, {
            kind: "server",
            isGroup: true,
            displayName: normalizeConversationLabel(
              nextChannel.name || (nextType === "voice" ? "voice-lounge" : "general"),
              nextType === "voice" ? "voice-lounge" : "general"
            ),
            serverId: sid,
            serverName: normalizeConversationLabel(serverRow?.name || serverCtx?.name || state.activeDm?.serverName || "Server", "Server"),
            avatarUrl: String(serverRow?.iconUrl || serverCtx?.iconUrl || state.activeDm?.avatarUrl || "").trim(),
            channelType: nextType,
            userLimit: nextType === "voice" ? clampServerVoiceUserLimit(nextChannel?.userLimit ?? 0, 0) : 0,
            mediaMode: nextType === "voice" ? normalizeServerVoiceMediaMode(nextChannel?.mediaMode || "audio_only", "audio_only") : "audio_only",
          });
        } else {
          activeDmId = null;
          state.activeDm = null;
          setMidMode("friends");
          syncDmActiveListHighlight();
          renderGroupsRail();
          setRightSidebarToServerMembers({ active: false });
        }
      }
    }

    activeServerChannelsRealtimeState = {
      ...activeServerChannelsRealtimeState,
      isRefreshing: false,
      lastRefreshAt: Date.now(),
      silentMode: silent,
    };
    if (canAffectChannelAccess) {
      await reconcileActiveServerMessageHistory(`channels:${reason}`).catch((error) => {
        console.warn("[message-history] channel reconciliation failed", {
          serverId: sid,
          reason,
          message: error?.message || error,
        });
      });
    }
    return applyResult.changed;
  } catch (error) {
    if (silent) {
      serverChannelListByServerId.set(sid, previousChannels);
      serverChannelCategoryListByServerId.set(sid, previousCategories);
      console.warn("[channels-realtime] silent refresh failed", { serverId: sid, reason, message: error?.message || error, error });
    } else {
      console.warn("[channels-realtime] refresh failed", { serverId: sid, reason, message: error?.message || error, error });
    }
    activeServerChannelsRealtimeState = {
      ...activeServerChannelsRealtimeState,
      isRefreshing: false,
      lastRefreshAt: Date.now(),
      silentMode: silent,
    };
    return false;
  }
}
async function emitServerChannelsChangedBroadcast(serverId = "", payload = {}) {
  const sid = normId(serverId || "");
  const channelName = getServerChannelsRealtimeChannelName(sid);
  if (!sid || !channelName || !state.user?.id) return false;
  const message = {
    serverId: sid,
    updatedAt: new Date().toISOString(),
    ...(payload || {}),
  };
  let channel = activeServerChannelsRealtimeKey === channelName ? activeServerChannelsRealtimeChannel : null;
  let temporaryChannel = false;
  let readyTimer = 0;
  try {
    if (!channel) {
      temporaryChannel = true;
      channel = supabase.channel(channelName, { config: { broadcast: { self: false } } });
      await new Promise((resolve) => {
        let done = false;
        const finish = () => {
          if (done) return;
          done = true;
          if (readyTimer) clearTimeout(readyTimer);
          resolve();
        };
        readyTimer = setTimeout(finish, 900);
        channel.subscribe((status) => {
          if (["SUBSCRIBED", "CHANNEL_ERROR", "TIMED_OUT", "CLOSED"].includes(String(status || ""))) finish();
        });
      });
    }
    await channel.send({ type: "broadcast", event: "server-channels-changed", payload: message });
    return true;
  } catch (error) {
    console.warn("[channels-realtime] broadcast failed", { serverId: sid, message: error?.message || error, error });
    return false;
  } finally {
    if (readyTimer) clearTimeout(readyTimer);
    if (temporaryChannel && channel) {
      try { supabase.removeChannel(channel); } catch (_) {}
    }
  }
}

