let presence = null;
let presenceOwnerUserId = "";
let presenceStopInFlight = null;
let presenceStartInFlight = null;
let presenceList = [];
let meStatusMenuBound = false;
let meStatusPersistQueue = Promise.resolve();
let currentUserPresenceStatusSyncTimer = null;
let currentUserPresenceStatusSyncInFlight = false;
let lastManualPresenceStatusChangeAt = 0;
const PRESENCE_STATUS_LOCAL_CHANGE_GRACE_MS = 10000;
const PRESENCE_SESSION_ID = (() => {
  try {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") return crypto.randomUUID();
    if (typeof crypto !== "undefined" && typeof crypto.getRandomValues === "function") {
      const bytes = new Uint8Array(16);
      crypto.getRandomValues(bytes);
      return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
    }
  } catch (_) {}
  return String(Date.now()) + "-" + String(Math.random()).slice(2);
})();
const PRESENCE_ONLINE_AT_ISO = new Date().toISOString();
const presenceEffectiveStatusSignatureByUser = new Map();
let lastPresenceActiveNowSignature = "";

function isPresenceDebugEnabled() {
  try { return localStorage.getItem("altara.debug.presence") === "1"; } catch (_) { return false; }
}

function logPresenceDebug(event = "", details = {}) {
  if (!isPresenceDebugEnabled()) return;
  if (typeof console === "undefined" || typeof console.info !== "function") return;
  console.info("[Presence] " + String(event || "event"), details && typeof details === "object" ? details : {});
}

function logPresenceLiveDebug(event = "", details = {}) {
  if (!isPresenceDebugEnabled()) return;
  if (typeof console === "undefined" || typeof console.info !== "function") return;
  console.info("[Presence] " + String(event || "event"), details && typeof details === "object" ? details : {});
}

function getPresenceDeviceType() {
  try {
    const bridge = typeof getDesktopBridge === "function" ? getDesktopBridge() : null;
    if (bridge) return "electron";
  } catch (_) {}
  try {
    const ua = String(navigator?.userAgent || "").toLowerCase();
    if (ua.includes("electron")) return "electron";
    if (/android|iphone|ipad|mobile/.test(ua)) return "web";
  } catch (_) {}
  return "browser";
}


function closeMeStatusMenu(reason = "action") {
  const menu = document.getElementById("meStatusMenu");
  if (!menu) return;
  const wasOpen = menu.classList.contains("is-open");
  menu.classList.remove("is-open");
  clearActivePopover("me-status-menu");
  if (wasOpen) recordAltaraContextMenuClose("me_status", reason);
}

function ensureMeStatusMenu() {
  let menu = document.getElementById("meStatusMenu");
  if (!menu) {
    menu = document.createElement("div");
    menu.id = "meStatusMenu";
    menu.className = "msgMenu msgMenu--submenu meStatusMenu";
    document.body.appendChild(menu);
  }
  menu.classList.add("meStatusMenu");
  if (meStatusMenuBound) return menu;
  meStatusMenuBound = true;

  bindStableAltaraContextMenu(menu, {
    type: "me_status",
    close: closeMeStatusMenu,
    getAnchor: () => altaraContextMenuDebugState.currentType === "me_status" ? altaraContextMenuDebugState.anchorEl : null,
  });

  menu.addEventListener("click", (e) => {
    const target = eventTargetElement(e);
    if (!target) return;
    const btn = target.closest("[data-me-status]");
    if (!btn || btn.disabled) return;
    e.preventDefault();
    const nextStatus = String(btn.getAttribute("data-me-status") || "").trim().toLowerCase();
    closeMeStatusMenu();
    void setMyPresenceStatusEverywhere(nextStatus, { persistAccount: true });
  });

  return menu;
}

