async function runSteamConnectAttempt() {
  connectedAccountsState.error = "";
  clearSteamConnectionNotice({ source: "new_attempt" });
  setConnectionsStatus("", "");
  setConnectionsAction("steam-connect");
  const bridge = getDesktopBridge();
  if (bridge?.isDesktopApp === true && typeof bridge.startSteamConnect === "function") {
    try {
      const result = await bridge.startSteamConnect();
      if (result?.ok) {
        try {
          if (localStorage.getItem("altara_debug_connections") === "1") {
            console.log("[SteamConnect] desktop flow opened", {
              method: String(result?.method || "desktop-local-callback"),
              fallback: result?.fallback === true,
            });
          }
        } catch (_) {}
        setConnectionsStatus(result.fallback ? "Steam login opened with the configured fallback callback." : "Steam login opened in your browser. Return to ALTARA after signing in.", "info");
        return;
      }
      const reason = String(result?.reason || "").trim();
      console.error("[SteamConnect] failed", { reason: reason || "desktop_start_failed" });
      if (reason === "steam_callback_server_failed_no_fallback") {
        showSteamConnectManualUrlFallback("", "Could not start Steam callback server and no fallback callback URL is configured.");
      } else if (reason === "steam_external_open_failed") {
        showSteamConnectManualUrlFallback(result?.authorizationUrl || "", "Could not open Steam login in your browser.");
      } else {
        showSteamConnectManualUrlFallback("", "Could not start Steam connection. Check console for details.");
      }
      return;
    } catch (error) {
      console.error("[SteamConnect] failed", {
        reason: String(error?.message || "desktop_start_failed").slice(0, 120),
      });
      showSteamConnectManualUrlFallback("", "Could not start Steam connection. Check console for details.");
      return;
    } finally {
      setConnectionsAction("");
      renderConnectionsSettingsUi();
    }
  }

  steamConnectFlowDebugState.lastConnectClick.windowOpenAttempted = true;
  const pendingPopup = openPendingSpotifyAuthorizationWindow("Steam", {
    windowName: "altara-steam-connect",
    features: buildSteamConnectPopupFeatures(),
  });
  steamConnectFlowDebugState.lastConnectClick.popupCreated = !!pendingPopup;
  if (!pendingPopup) {
    steamConnectFlowDebugState.lastStartError = "popup_blocked";
    steamConnectFlowDebugState.lastConnectClick.error = "popup_blocked";
    resetSteamConnectFlowState({
      closePopup: false,
      preserveMessage: true,
      terminalReason: "popup_blocked",
    });
    setSteamConnectionNotice({
      kind: "error",
      code: "popup_blocked",
      title: "Popup blocked",
      message: "Allow popups for ALTARA and try again.",
    }, { source: "popup_blocked" });
    setConnectionsStatus("", "");
    return;
  }
  const trustedReturnTo = buildConnectionReturnToUrl(STEAM_PROVIDER);
  const trustedCompletionOrigin = new URL(trustedReturnTo).origin;
  pendingSteamWebConnect = {
    state: "",
    callbackOrigin: trustedCompletionOrigin,
    popup: pendingPopup,
    startedAt: Date.now(),
  };
  beginSteamConnectLifecycleTimers();
  setSteamConnectionNotice({
    kind: "info",
    code: "popup_open",
    title: "Steam sign-in open",
    message: "Complete the sign-in in the Steam window.",
  }, { source: "popup_open" });
  try {
    const edgeFunctionName = STEAM_CONNECT_START_FUNCTION_NAME;
    const authReady = await ensureSupabaseFunctionInvokeAuthReady({
      edgeFunctionName,
      functionPath: "/functions/v1/" + edgeFunctionName,
      requireUser: true,
      logPrefix: "[connections auth]",
      logEvent: "steam_connect_start.auth_state",
      logChannel: "connections",
      failEvent: "steam_connect_start.auth_missing",
    });
    if (!authReady.ok) {
      steamConnectFlowDebugState.lastStartError = "auth_missing";
      resetSteamConnectFlowState({ closePopup: true, preserveMessage: true, terminalReason: "start_auth_missing" });
      setSteamConnectionNotice({
        kind: "error",
        code: "start_auth_missing",
        title: "Sign in required",
        message: "Sign in to ALTARA again, then retry Steam Connect.",
      }, { source: "start_auth_missing" });
      setConnectionsStatus("", "");
      return;
    }

    steamConnectFlowDebugState.lastConnectClick.startRequestAttempted = true;
    const { data, error } = await supabase.functions.invoke(edgeFunctionName, {
      body: { return_to: trustedReturnTo },
    });
    const errorPayload = error ? await readSupabaseFunctionErrorPayload(error) : null;
    const response = data && typeof data === "object" ? data : (errorPayload || {});
    const authorizationUrl = extractSpotifyAuthorizationUrl(response);
    if (error || response?.ok === false || !authorizationUrl) {
      const reason = response?.error || response?.reason || error?.message || "steam_connect_start_failed";
      steamConnectFlowDebugState.lastStartError = String(reason).slice(0, 120);
      resetSteamConnectFlowState({ closePopup: true, preserveMessage: true, terminalReason: "start_failed" });
      setSteamConnectionNotice(buildSteamNoticeForReason(reason), { source: "start_failed" });
      setConnectionsStatus("", "");
      return;
    }

    const authorization = new URL(authorizationUrl);
    const callbackUrl = new URL(String(authorization.searchParams.get("openid.return_to") || ""));
    const expectedState = String(response?.state || callbackUrl.searchParams.get("state") || "").trim();
    if (
      authorization.origin !== "https://steamcommunity.com"
      || authorization.pathname !== "/openid/login"
      || !expectedState
      || !/^https?:$/.test(callbackUrl.protocol)
    ) {
      steamConnectFlowDebugState.lastStartError = "invalid_start_response";
      resetSteamConnectFlowState({ closePopup: true, preserveMessage: true, terminalReason: "invalid_start_response" });
      setSteamConnectionNotice({
        kind: "error",
        code: "invalid_start_response",
        title: "Steam sign-in unavailable",
        message: "Could not start secure Steam login. Try again.",
      }, { source: "invalid_start_response" });
      setConnectionsStatus("", "");
      return;
    }

    if (!pendingSteamWebConnect || pendingSteamWebConnect.popup !== pendingPopup) return;
    pendingSteamWebConnect.state = expectedState;
    await openSteamAuthorizationUrl(authorizationUrl, pendingPopup);
    setSteamConnectionNotice({
      kind: "info",
      code: "popup_open",
      title: "Steam sign-in open",
      message: "Complete the sign-in in the Steam window.",
    }, { source: "authorization_opened" });
    setConnectionsStatus("", "");
    startSpotifyConnectionCompletionPolling({ reason: "steam_connect_button", immediate: true, provider: STEAM_PROVIDER });
  } catch (error) {
    steamConnectFlowDebugState.lastStartError = String(error?.message || "steam_connect_start_failed").slice(0, 120);
    steamConnectFlowDebugState.lastConnectClick.error = steamConnectFlowDebugState.lastStartError;
    resetSteamConnectFlowState({ closePopup: true, preserveMessage: true, terminalReason: "start_exception" });
    setSteamConnectionNotice(buildSteamNoticeForReason(error?.message || "steam_connect_start_failed"), { source: "start_exception" });
    setConnectionsStatus("", "");
  } finally {
    if (connectedAccountsState.action === "steam-connect") setConnectionsAction("");
    renderConnectionsSettingsUi();
  }
}

function startSteamConnect() {
  steamConnectFlowDebugState.lastConnectClickAt = Date.now();
  steamConnectFlowDebugState.lastEarlyReturnReason = "";
  steamConnectFlowDebugState.lastStartError = "";

  if (pendingSteamWebConnect) {
    if (focusPendingSteamPopup()) {
      steamConnectFlowDebugState.lastEarlyReturnReason = "popup_already_open";
      steamConnectFlowDebugState.lastConnectClick.earlyReturnReason = "popup_already_open";
      setSteamConnectionNotice({
        kind: "info",
        code: "popup_open",
        title: "Steam sign-in open",
        message: "Complete the sign-in in the Steam window.",
      }, { source: "popup_focused" });
      setConnectionsStatus("", "");
      return steamConnectInFlight || Promise.resolve({ focusedExistingPopup: true });
    }
    resetSteamConnectFlowState({
      closePopup: false,
      preserveMessage: true,
      terminalReason: "stale_popup_before_retry",
    });
  }
  if (steamConnectInFlight) {
    resetSteamConnectFlowState({
      closePopup: true,
      preserveMessage: true,
      terminalReason: "stale_in_flight_before_retry",
    });
  }
  if (connectedAccountsState.action) {
    resetSteamConnectFlowState({
      closePopup: true,
      preserveMessage: true,
      terminalReason: "stale_action_before_retry",
    });
  }

  const attempt = runSteamConnectAttempt();
  steamConnectInFlight = attempt;
  void attempt
    .finally(() => {
      if (steamConnectInFlight === attempt) steamConnectInFlight = null;
    })
    .catch(() => null);
  return attempt;
}

async function openSteamConnectFlow() {
  return startSteamConnect();
}

