async function disconnectSteamConnection() {
  if (!getSteamConnectedAccount() || connectedAccountsState.action) return;
  setConnectionsAction("steam-disconnect");
  setConnectionsStatus("Disconnecting Steam...", "info");
  try {
    const { data, error } = await supabase.rpc("disconnect_my_steam_account_v1");
    if (error) throw error;
    if (data?.ok !== true) throw new Error("steam_disconnect_failed");
    const uid = normId(state.user?.id || state.me?.id || "");
    if (uid) await refetchCurrentProfileAfterSteamConnectionChange(uid).catch(() => null);
    await refreshConnectedAccounts({ force: true, silent: true }).catch(() => []);
    connectedAccountsState.accounts = (connectedAccountsState.accounts || []).filter((account) => account.provider !== STEAM_PROVIDER);
    if (state.user?.id) userCardPublicConnectionsCache.delete(normId(state.user.id));
    setConnectionsStatus("Steam disconnected.", "info");
  } catch (error) {
    console.error("[SteamConnect] Steam disconnect save failed", error);
    setConnectionsStatus(getSteamConnectionErrorMessage(error?.message || "steam_disconnect_failed", "disconnect"), "warn");
  } finally {
    setConnectionsAction("");
    renderConnectionsSettingsUi();
  }
}

function mergeSteamProfileRefreshIntoCurrentProfile(steamInput = null) {
  const steam = steamInput && typeof steamInput === "object" && !Array.isArray(steamInput) ? steamInput : null;
  if (!steam) return null;
  const steamid64 = String(steam.steamid64 || steam.steamId64 || "").trim();
  if (!/^\d{16,20}$/.test(steamid64)) return null;
  state.me = state.me || {};
  state.me.id = state.me.id || state.user?.id || "";
  const currentAccounts = getProfileConnectedAccountsObject(state.me.connected_accounts);
  const currentSteam = getSteamProfileAccountObject(currentAccounts.steam);
  const nextSteam = { ...currentSteam, ...steam, provider: STEAM_PROVIDER, steamid64 };
  state.me.connected_accounts = { ...currentAccounts, steam: nextSteam };
  cacheProfileRow({ ...(state.me || {}), id: state.me.id || state.user?.id || "" });
  return nextSteam;
}

async function applySteamProfileRefreshPayload(payloadInput = null) {
  const payload = payloadInput && typeof payloadInput === "object" ? payloadInput : {};
  const refreshedSteam = mergeSteamProfileRefreshIntoCurrentProfile(payload.steam || payload.profileSteam || null);
  const steamForAccount = refreshedSteam || payload.steam || null;
  if (payload.account) upsertConnectedAccountInState(payload.account);
  else if (steamForAccount) {
    upsertConnectedAccountInState(buildSteamConnectedAccountFromSteamId(steamForAccount.steamid64 || "", {
      personaName: steamForAccount.personaName || steamForAccount.displayName || "Steam account",
      profileUrl: steamForAccount.profileUrl || "",
      linkedAt: steamForAccount.linkedAt || steamForAccount.linked_at || "",
      lastSyncedAt: steamForAccount.lastSyncedAt || steamForAccount.last_synced_at || "",
      showOnProfile: steamForAccount.showOnProfile !== false && steamForAccount.show_on_profile !== false,
      metadata: steamForAccount,
    }));
  }
  const uid = normId(state.user?.id || state.me?.id || "");
  if (uid) userCardPublicConnectionsCache.delete(uid);
  if (uid) {
    await refetchCurrentProfileAfterSteamConnectionChange(uid).catch((error) => {
      try { console.warn("[SteamConnect] profile refetch after Steam refresh failed", error?.message || error); } catch (_) {}
    });
  }
  await refreshConnectedAccounts({ force: true, silent: true }).catch((error) => {
    try { console.warn("[SteamConnect] connected accounts refresh after Steam profile refresh failed", error?.message || error); } catch (_) {}
    return [];
  });
  try { refreshOpenUserCard(); } catch (_) {}
  try { rerenderOpenProfileMiniPopoutForActivity(); } catch (_) {}
}

function isSteamRefreshFunctionNotFound(error = null, payload = null) {
  const context = error?.context || error?.response;
  const status = Number(context?.status || error?.status || error?.statusCode || payload?.status || 0) || 0;
  const text = String(
    payload?.error
    || payload?.reason
    || error?.message
    || error?.name
    || ""
  ).toLowerCase();
  return status === 404 || text.includes("404") || text.includes("not found") || text.includes("function_not_found");
}

function sanitizeSteamRefreshLogPayload(value = null) {
  if (!value || typeof value !== "object") return value || null;
  const out = {};
  Object.keys(value).slice(0, 30).forEach((key) => {
    if (/token|secret|authorization|auth|code|state|key/i.test(key)) {
      out[key] = "[redacted]";
      return;
    }
    const item = value[key];
    if (item && typeof item === "object") out[key] = "[object]";
    else out[key] = item;
  });
  return out;
}

async function invokeSteamRefreshFunctionByName(edgeFunctionName = "", { source = "manual" } = {}) {
  const name = String(edgeFunctionName || "").trim();
  if (!name) throw new Error("steam_profile_refresh_function_missing");
  console.log("[SteamRefresh] invoking " + name, { source });
  const { data, error } = await supabase.functions.invoke(name, { body: {} });
  const errorPayload = error ? await readSupabaseFunctionErrorPayload(error) : null;
  const payload = data && typeof data === "object" ? data : (errorPayload || {});
  console.log("[SteamRefresh] response data", { functionName: name, data: sanitizeSteamRefreshLogPayload(data || payload || null) });
  console.log("[SteamRefresh] response error", { functionName: name, error: error ? String(error?.message || error || "").slice(0, 240) : null, status: Number(error?.context?.status || error?.response?.status || error?.status || 0) || null });
  return { functionName: name, data, error, errorPayload, payload };
}

async function invokeSteamProfileRefresh({ source = "manual" } = {}) {
  const edgeFunctionName = STEAM_REFRESH_PROFILE_FUNCTION_NAME;
  const authReady = await ensureSupabaseFunctionInvokeAuthReady({
    edgeFunctionName,
    functionPath: "/functions/v1/" + edgeFunctionName,
    requireUser: true,
    logPrefix: "[connections auth]",
    logEvent: "steam_refresh_profile.auth_state",
    logChannel: "connections",
    failEvent: "steam_refresh_profile.auth_missing",
  });
  if (!authReady.ok) throw authReady.error || new Error("steam_refresh_auth_missing");

  let response = await invokeSteamRefreshFunctionByName(edgeFunctionName, { source });
  if (response.error && isSteamRefreshFunctionNotFound(response.error, response.payload)) {
    console.warn("[SteamRefresh] refresh-steam-profile not found, trying compatibility fallback", { source });
    response = await invokeSteamRefreshFunctionByName(STEAM_REFRESH_PROFILE_FALLBACK_FUNCTION_NAME, { source: source + ":fallback" });
  }

  const { error, payload } = response;
  if (error || payload.ok === false) {
    const reason = payload.error || payload.reason || error?.message || "steam_profile_refresh_failed";
    console.error("[SteamRefresh] failed", { source, functionName: response.functionName, reason, payload: sanitizeSteamRefreshLogPayload(payload), error });
    await refreshConnectedAccounts({ force: true, silent: true }).catch(() => []);
    return { ok: false, reason, payload, error, functionName: response.functionName };
  }
  await applySteamProfileRefreshPayload(payload);
  return { ok: true, payload, steam: payload.steam || null, functionName: response.functionName };
}
async function refreshSteamProfileConnection() {
  if (!getSteamConnectedAccount() || connectedAccountsState.action) return;
  setConnectionsAction("steam-refresh");
  setConnectionsStatus("Refreshing Steam profile...", "info");
  try {
    const result = await invokeSteamProfileRefresh({ source: "manual" });
    if (!result.ok) {
      setConnectionsStatus(getSteamConnectionErrorMessage(result.reason, "refresh"), normalizeSteamConnectionErrorCode(result.reason) === "steam_profile_refresh_key_missing" ? "info" : "warn");
      return;
    }
    if (result.payload?.metadataUnavailable === true) {
      setConnectionsStatus(
        getSteamConnectionErrorMessage(result.payload.metadataUnavailableReason || "steam_profile_refresh_not_configured", "refresh"),
        "info",
      );
      return;
    }
    setConnectionsStatus("Steam profile refreshed.", "info");
  } catch (error) {
    console.error("[SteamConnect] Steam profile refresh failed", error);
    setConnectionsStatus(getSteamConnectionErrorMessage(error?.message || "steam_profile_refresh_failed", "refresh"), "warn");
  } finally {
    setConnectionsAction("");
    renderConnectionsSettingsUi();
  }
}

