    icon: metadata.icon || activity.icon,
    cover: metadata.cover || activity.cover,
    background: metadata.background || activity.background || metadata.cover || activity.cover,
    description: metadata.description || activity.description,
    released: metadata.released || activity.released,
    genres: metadata.genres || activity.genres,
    provider: metadata.provider || activity.provider,
    providerId: metadata.providerId || activity.providerId,
    slug: metadata.slug || activity.slug,
    confidence: metadata.confidence || activity.confidence || 1,
