function getGameActivitySignature(activity = null) {
  const normalized = sanitizeGameActivity(activity);
  if (!normalized) return "";
  return [
    normalized.type,
    normalized.gameId,
    normalized.name,
    String(normalized.startedAt || 0),
    normalized.icon || "",
    normalized.cover || "",
    normalized.background || "",
    normalized.provider || "",
    normalized.kind || "",
    normalized.activityVerb || "",
  ].join("|");
}

function isGameActivityHidden(gameId = "") {
  const gid = normalizeGameActivityId(gameId);
  if (!gid) return false;
  if ((gameActivitySettings.hiddenGameIds || []).includes(gid)) return true;
  const local = customActivityGames.find((game) => (
    normalizeGameActivityId(game?.id || "") === gid
    || normalizeGameActivityId(game?.gameId || "") === gid
  ));
  if (local?.hidden === true) return true;
  const desktop = (Array.isArray(desktopActivityState.registeredGames) ? desktopActivityState.registeredGames : []).find((game) => (
    normalizeGameActivityId(game?.id || "") === gid
    || normalizeGameActivityId(game?.gameId || "") === gid
  ));
  return desktop?.hidden === true;
}

function shouldShareGameActivity(activity = null) {
  const normalized = sanitizeGameActivity(activity);
  if (!normalized) return false;
  if (!gameActivitySettings.displayGameActivity) return false;
  if (isGameActivityHidden(normalized.gameId)) return false;
  if (normalized.privateOnly || normalized.confirmed === false) return false;
  if (!normId(state.user?.id || "")) return false;
  const myStatus = normalizeManualPresenceStatus(resolveMyPresenceStatus(state.me));
  if (myStatus === "offline" || myStatus === "invisible") return false;
  return true;
}

function getPublicGameActivity(activity = null) {
  const normalized = sanitizeGameActivity(activity);
  if (!normalized || !shouldShareGameActivity(normalized)) return null;
  return {
    type: "playing",
    name: normalized.name,
    gameId: normalized.gameId,
    startedAt: normalized.startedAt,
    ...(normalized.icon ? { icon: normalized.icon } : {}),
    ...(normalized.cover ? { cover: normalized.cover } : {}),
    ...(normalized.background ? { background: normalized.background } : {}),
    ...(normalized.provider ? { provider: normalized.provider } : {}),
    ...(normalized.providerId ? { providerId: normalized.providerId } : {}),
    ...(normalized.slug ? { slug: normalized.slug } : {}),
    kind: normalized.kind || "game",
    activityVerb: normalized.activityVerb || (normalized.kind === "app" ? "using" : "playing"),
  };
}

function getCurrentPublicGameActivity() {
  return sanitizeGameActivity(effectiveGameActivity);
}

function getPresenceActivityForUser(userId = "") {
  const uid = normId(userId || "");
  if (!uid) return null;
  if (uid === normId(state.user?.id || "")) {
    const resolved = resolveEffectivePresence(uid);
    const activity = resolved.isVisibleOnline ? getCurrentPublicPresenceActivity() : null;
    if (activity?.type === "listening" && activity.provider === SPOTIFY_PROVIDER && activity.showOnProfile === false) return getCurrentPublicGameActivity();
    return activity;
  }
  const hit = getPresenceEntryForUser(uid);
  const resolved = resolveEffectivePresence(uid, { presenceEntry: hit });
  if (!resolved.isVisibleOnline) return null;
  const activity = sanitizePresenceActivity(resolved.activity || hit?.activity || hit?.spotify_activity || hit?.spotifyActivity);
  if (activity?.type === "listening" && activity.provider === SPOTIFY_PROVIDER && activity.showOnProfile === false) return null;
  return activity;
}

function formatGameActivityDurationText(startedAtInput = 0) {
  const startedAt = Number(startedAtInput || 0);
  if (!Number.isFinite(startedAt) || startedAt <= 0) return "Active now";
  const totalMinutes = Math.max(0, Math.floor((Date.now() - startedAt) / 60000));
  if (totalMinutes < 1) return "for less than a minute";
  if (totalMinutes < 60) return `for ${totalMinutes} minute${totalMinutes === 1 ? "" : "s"}`;
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (!minutes) return `for ${hours} hour${hours === 1 ? "" : "s"}`;
  return `for ${hours}h ${minutes}m`;
}

function buildActivityArtworkThumbHtml(source = null, fallbackName = "Game", className = "") {
  const src = source && typeof source === "object" ? source : {};
  const meta = src.metadata && typeof src.metadata === "object" ? src.metadata : {};
  const name = String(src.name || meta.name || fallbackName || "Game").trim() || "Game";
  const initial = name.charAt(0).toUpperCase() || "G";
  const image = normalizeActivityImageUrl(
    src.icon || src.cover || src.artworkUrl || src.artwork_url || src.background
    || meta.icon || meta.cover || meta.artworkUrl || meta.artwork_url || meta.background
    || ""
  );
  const classes = Array.from(new Set([
    ...String(className || "").split(/\s+/).filter(Boolean),
    "activityArtworkThumb",
  ])).join(" ");
  return `
    <div class="${escAttr(classes)}" aria-hidden="true"${image ? ` data-image-url="${escAttr(image)}"` : ""}>
      <span>${esc(initial)}</span>
      ${image ? `<img src="${escAttr(image)}" alt="" loading="lazy" onerror="this.hidden=true;this.closest('.activityArtworkThumb')?.setAttribute('data-image-failed','true')" />` : ""}
    </div>
  `;
}

function buildGameActivityCardHtml(activityInput = null, { className = "" } = {}) {
  const activity = sanitizePresenceActivity(activityInput);
  if (!activity) return "";
  const baseClass = "gameActivityCard" + (activity.type === "listening" && activity.provider === SPOTIFY_PROVIDER ? " gameActivityCard--spotify" : "") + (className ? " " + escAttr(className) : "");
  if (activity.type === "listening" && activity.provider === SPOTIFY_PROVIDER) {
    const artistLine = activity.artist || activity.details || "Spotify";
    return '<section class="' + baseClass + '" data-spotify-activity-card="1">'
      + buildActivityArtworkThumbHtml({ name: activity.name, artworkUrl: activity.artworkUrl, icon: activity.artworkUrl }, activity.name, "gameActivityCard__icon")
      + '<div class="gameActivityCard__body">'
      + '<div class="gameActivityCard__eyebrow">Listening to Spotify</div>'
      + '<div class="gameActivityCard__name">' + esc(activity.name) + '</div>'
      + '<div class="gameActivityCard__meta">' + esc(artistLine) + '</div>'
      + buildSpotifyProgressHtml(activity)
      + '</div></section>';
  }
  return `
    <section class="${baseClass}" data-game-activity-card="${escAttr(activity.gameId)}">
      ${buildActivityArtworkThumbHtml(activity, activity.name, "gameActivityCard__icon")}
      <div class="gameActivityCard__body">
        <div class="gameActivityCard__eyebrow">${esc(getActivityVerbLabel(activity))}</div>
        <div class="gameActivityCard__name">${esc(activity.name)}</div>
        <div class="gameActivityCard__meta" data-game-activity-elapsed="${escAttr(activity.startedAt)}">${esc(formatGameActivityDurationText(activity.startedAt))}</div>
      </div>
    </section>
  `;
}

function updateGameActivityElapsedLabels() {
  document.querySelectorAll("[data-game-activity-elapsed]").forEach((el) => {
    const startedAt = Number(el.getAttribute("data-game-activity-elapsed") || 0);
    el.textContent = formatGameActivityDurationText(startedAt);
  });
  updateSpotifyProgressLabels();
}

function syncGameActivityElapsedTimer() {
  const hasActivity = !!(effectiveGameActivity || detectedGameActivity || getCurrentSpotifyPresenceActivity() || document.querySelector("[data-game-activity-elapsed], [data-spotify-activity-progress]"));
  if (hasActivity && !gameActivityElapsedTimer) {
    gameActivityElapsedTimer = window.setInterval(updateGameActivityElapsedLabels, GAME_ACTIVITY_ELAPSED_TICK_MS);
  } else if (!hasActivity && gameActivityElapsedTimer) {
    clearInterval(gameActivityElapsedTimer);
    gameActivityElapsedTimer = null;
  }
}

function rerenderOpenProfileMiniPopoutForActivity() {
  const popout = document.getElementById("meProfilePopout");
  if (!popout || !popout.classList.contains("is-open")) return;
  const uid = getMeProfilePopoutTargetId();
  if (!uid) return;
  const isSelf = isMeProfilePopoutSelf(uid);
  const seedProfile = isSelf
    ? getMeUserCardSeed()
    : (getCachedProfile(uid) || buildMiniProfileSeedForUser(uid, meProfilePopoutTargetSeed || {}) || { id: uid });
  const activity = getPresenceActivityForUser(uid);
  const signature = JSON.stringify({
    uid,
    isSelf,
    displayName: String(seedProfile?.display_name || seedProfile?.displayName || seedProfile?.username || ""),
    avatar: String(seedProfile?.avatar_url || seedProfile?.avatarUrl || ""),
    banner: String(seedProfile?.banner_url || seedProfile?.bannerUrl || seedProfile?.theme_settings?.banner_url || ""),
    status: getPresenceStatusForUser(uid),
    activity: getPresenceActivityRenderSignature(activity),
  });
  if (popout.dataset.profileActivitySignature === signature) {
    updateGameActivityElapsedLabels();
    logRenderDebug("profile skipped unchanged", { userId: uid, surface: "mini-popout" });
    return;
  }
  popout.dataset.profileActivitySignature = signature;
  setElementHtmlIfChanged(popout, buildMeProfilePopoutHtml(seedProfile, { loading: false }));
  queueManagedGifPlaybackSync(popout);
  applyMeProfilePopoutBannerStyle(seedProfile);
  renderMeProfilePopoutWidgetsPreview({ loading: false });
  positionMeProfilePopout();
}

const gameActivityStatusFlowWarningKeys = new Set();

function warnGameActivityStatusFlowSkipped(step = "", error = null) {
  const errorName = String(error?.name || "Error").slice(0, 80);
  const errorMessage = String(error?.message || error || "unknown_error").slice(0, 180);
  const key = [String(step || "activity"), errorName, errorMessage].join("|");
  const shouldLog = !gameActivityStatusFlowWarningKeys.has(key) || isPresenceDebugEnabled();
  gameActivityStatusFlowWarningKeys.add(key);
  if (!shouldLog || typeof console === "undefined" || typeof console.warn !== "function") return;
  console.warn("[Presence] game activity skipped", {
    step: String(step || "activity").slice(0, 80),
    errorName,
    errorMessage,
  });
}

function runGameActivityStatusFlowStep(step = "", fn = null) {
  try {
    return typeof fn === "function" ? fn() : undefined;
  } catch (error) {
    warnGameActivityStatusFlowSkipped(step, error);
    return undefined;
  }
}

function refreshGameActivityDisplays() {
  runGameActivityStatusFlowStep("apply-me-status-dot", () => applyMeStatusDot(resolveMyPresenceStatus(state.me)));
  runGameActivityStatusFlowStep("render-activity-settings", () => renderActivitySettingsUi());
  runGameActivityStatusFlowStep("render-connections-settings", () => renderConnectionsSettingsUi());
  runGameActivityStatusFlowStep("update-activity-elapsed-labels", () => updateGameActivityElapsedLabels());
  runGameActivityStatusFlowStep("rerender-profile-popout", () => rerenderOpenProfileMiniPopoutForActivity());
  runGameActivityStatusFlowStep("refresh-open-user-card", () => refreshOpenUserCard());
  runGameActivityStatusFlowStep("refresh-server-members-activity", () => {
    const serverCtx = getActiveServerContext?.();
    if (serverCtx?.serverId) {
      const members = serverMemberListByServerId.get(normId(serverCtx.serverId || "")) || [];
      if (members.length) void renderServerMembersRightPanel(serverCtx, members, { forceChannelMembers: false });
    }
  });
  runGameActivityStatusFlowStep("sync-activity-elapsed-timer", () => syncGameActivityElapsedTimer());
}

function updateEffectiveGameActivity({ publishPresence = true, render = true } = {}) {
  const previousSignature = getPresenceActivitySignature(getCurrentPublicPresenceActivity());
  let next = null;
  try {
    next = getPublicGameActivity(detectedGameActivity);
  } catch (error) {
    warnGameActivityStatusFlowSkipped("resolve-public-game-activity", error);
    next = null;
  }
  effectiveGameActivity = next;
  const publicActivity = getCurrentPublicPresenceActivity();
  const nextSignature = getPresenceActivitySignature(publicActivity);
  if (state.me) state.me.activity = publicActivity || null;
  if (state.user?.id) cacheProfileRow({ id: state.user.id, activity: publicActivity || null });
  if (render || previousSignature !== nextSignature) refreshGameActivityDisplays();
  if (publishPresence && previousSignature !== nextSignature) {
    try { void presence?.refresh?.(); } catch (_) {}
  }
  return next;
}

function normalizeDesktopActivityPayload(payload = null) {
  const raw = payload && typeof payload === "object" ? payload : {};
  const registeredGames = Array.isArray(raw.registeredGames)
    ? raw.registeredGames.map((game) => {
        const id = normalizeGameActivityId(game?.id || game?.name || "");
        const name = String(game?.name || "").trim().slice(0, 96);
        if (!id || !name) return null;
        return {
          id,
          name,
          executables: Array.isArray(game?.executables)
            ? game.executables.map((exe) => normalizeActivityExecutableName(exe)).filter(Boolean).slice(0, 12)
            : [],
          aliases: Array.isArray(game?.aliases) ? game.aliases.map((item) => String(item || "").trim()).filter(Boolean).slice(0, 12) : [],
          metadata: sanitizeGameMetadata(game?.metadata || null, name),
          rawgSlug: String(game?.rawgSlug || game?.rawg_slug || "").trim(),
          rawgId: Number.isFinite(Number(game?.rawgId ?? game?.rawg_id)) ? Number(game.rawgId ?? game.rawg_id) : null,
          steamAppId: Number.isFinite(Number(game?.steamAppId ?? game?.steam_app_id)) ? Number(game.steamAppId ?? game.steam_app_id) : null,
          steamGridDbId: Number.isFinite(Number(game?.steamGridDbId ?? game?.steamgriddb_id)) ? Number(game.steamGridDbId ?? game.steamgriddb_id) : null,
          source: String(game?.source || (game?.custom ? "manual" : "detected")).trim().toLowerCase() === "manual" ? "manual" : "detected",
          kind: String(game?.kind || "").trim().toLowerCase() === "app" ? "app" : "game",
          activityVerb: String(game?.activityVerb || game?.activity_verb || "").trim().toLowerCase() === "using" ? "using" : "playing",
          gameId: normalizeGameActivityId(game?.gameId || game?.game_id || id),
          firstDetectedAt: String(game?.firstDetectedAt || game?.first_detected_at || "").trim(),
          lastDetectedAt: String(game?.lastDetectedAt || game?.last_detected_at || "").trim(),
          createdAt: String(game?.createdAt || "").trim(),
          updatedAt: String(game?.updatedAt || "").trim(),
          custom: game?.custom === true,
          removable: game?.removable === true,
          hidden: game?.hidden === true,
          privateOnly: game?.privateOnly === true,
          confirmed: game?.confirmed !== false,
          running: game?.running === true,
          icon: normalizeActivityImageUrl(game?.icon || ""),
          cover: normalizeActivityImageUrl(game?.cover || ""),
        };
      }).filter(Boolean)
    : [];
  return {
    supported: raw.supported === true,
    enabled: raw.enabled === true,
    platform: String(raw.platform || "web").trim() || "web",
    pollMs: Number(raw.pollMs || 20000) || 20000,
    activity: sanitizeGameActivity(raw.activity),
    registeredGames,
  };
}

function handleDesktopActivityPayload(payload = null, { resolveMetadata = true, upsertDetected = true } = {}) {
  desktopActivityState = normalizeDesktopActivityPayload(payload);
  const nextDetectedActivity = sanitizeGameActivity(desktopActivityState.activity);
  if (isRemovedManualActivitySuppressed(nextDetectedActivity) || isGameActivityHidden(nextDetectedActivity?.gameId || "")) {
    desktopActivityState = { ...desktopActivityState, activity: null };
    detectedGameActivity = null;
  } else {
    detectedGameActivity = nextDetectedActivity;
  }
  if (upsertDetected && detectedGameActivity && upsertDetectedActivityRegisteredGame(detectedGameActivity)) {
    queueDesktopActivityUserGamesSync();
  }
  mergeLocalRegisteredActivityGamesIntoDesktopState(detectedGameActivity);
  updateEffectiveGameActivity({ publishPresence: true, render: true });
  notifyFocusAutomationSignalChanged("activity_changed", { source: "desktop_payload", currentDetectedApp: getCurrentFocusDetectedApp() });
  scheduleFocusOpenAppsRefresh("desktop_activity_payload", { render: settingsActiveTab === "notifications" });
  if (resolveMetadata && detectedGameActivity) {
    void resolveDetectedGameActivityMetadata(detectedGameActivity).catch((error) => {
      console.warn("desktop activity metadata resolve failed", error?.message || error);
    });
  }
  if (settingsActiveTab === "notifications") {
    renderFocusAdvancedSettingsUi(getFocusNotificationSettings());
  }
  if (settingsActiveTab === "activity") {
    scheduleRegisteredGamesMetadataEnrichment({ force: false, reason: "desktop_payload" });
  }
}
async function syncDesktopActivityDetectionEnabled() {
  const activityBridge = getDesktopActivityBridge();
  const platform = getDesktopActivityBridgePlatform();
  if (!activityBridge || typeof activityBridge.setDetectionEnabled !== "function") {
    desktopActivityState = {
      ...desktopActivityState,
      supported: false,
      enabled: false,
      platform,
    };
    detectedGameActivity = null;
    updateEffectiveGameActivity({ publishPresence: true, render: true });
    notifyFocusAutomationSignalChanged("activity_changed", { source: "desktop_activity_unavailable", currentDetectedApp: null });
    if (settingsActiveTab === "notifications") renderFocusAdvancedSettingsUi(getFocusNotificationSettings());
    return desktopActivityState;
  }
  try {
    const payload = await activityBridge.setDetectionEnabled(!!gameActivitySettings.detectGamesAutomatically);
    handleDesktopActivityPayload(payload);
  } catch (error) {
    console.warn("desktop activity detection sync failed", error?.message || error);
  }
  return desktopActivityState;
}

function getActivityMetadataProviderStatusText() {
  return "Metadata provider: RAWG";
}

async function refreshActivityMetadataProviderStatus({ render = false } = {}) {
  activityMetadataProviderStatus = { provider: "rawg", cacheVersion: "v4" };
  if (render && settingsActiveTab === "activity") renderActivitySettingsUi();
  return activityMetadataProviderStatus;
}
async function initDesktopGameActivityBridge() {
  if (desktopActivityBridgeInitialized) return;
  desktopActivityBridgeInitialized = true;
  const activityBridge = getDesktopActivityBridge();
  if (!activityBridge) {
    desktopActivityState = normalizeDesktopActivityPayload({ supported: false, platform: "web" });
    renderActivitySettingsUi();
    return;
  }
  if (typeof activityBridge.onDetectedActivityChanged === "function") {
    desktopActivityBridgeUnsubscribe = activityBridge.onDetectedActivityChanged((payload) => {
      handleDesktopActivityPayload(payload);
    });
  }
  await syncDesktopActivityUserGames();
  try {
    if (typeof activityBridge.getState === "function") {
      handleDesktopActivityPayload(await activityBridge.getState());
    }
  } catch (error) {
    console.warn("desktop activity state load failed", error?.message || error);
  }
  await syncDesktopActivityDetectionEnabled();
}

function getActivityRunningAppModalEls() {
  return {
    modal: document.getElementById("activityRunningAppModal"),
    status: document.getElementById("activityRunningAppStatus"),
    search: document.getElementById("activityRunningAppSearch"),
    list: document.getElementById("activityRunningAppList"),
    resolver: document.getElementById("activityRunningAppResolver"),
    showSystem: document.getElementById("activityRunningShowSystemApps"),
    addSelected: document.getElementById("btnActivityRunningAppAddSelected"),
  };
}
function sanitizeRunningAppRow(row = null) {
  if (!row || typeof row !== "object") return null;
  const executable = normalizeActivityExecutableName(row.executable || "");
  if (!executable) return null;
  const knownGameName = String(row.knownGameName || "").trim().slice(0, 96);
  const registered = getRegisteredActivityGameByExecutable(executable);
  return {
    executable,
    displayName: getFriendlyRunningAppName(executable, knownGameName),
    knownGameId: normalizeGameActivityId(row.knownGameId || ""),
    knownGameName,
    matchedKnownGame: row.matchedKnownGame === true,
    alreadyRegistered: !!registered,
    registeredId: registered?.id || "",
  };
}
function getActivityGameExecutableKeys(game = null) {
  const executables = Array.isArray(game?.executables) ? game.executables : [game?.executable || game?.executableName || ""];
  return Array.from(new Set(executables
    .map((item) => normalizeActivityExecutableName(item || "").toLowerCase())
    .filter(Boolean)));
}

function isRemovedManualActivityExecutableSuppressed(executableInput = "") {
  const executable = normalizeActivityExecutableName(executableInput || "");
  const normalized = executable.toLowerCase();
  if (!normalized) return false;
  if (removedManualActivityExecutables.has(normalized)) return true;
  const stored = readRemovedManualActivityApps();
  const hit = Object.keys(stored.executables || {}).some((entryExecutable) => normalizeActivityExecutableName(entryExecutable).toLowerCase() === normalized);
  if (hit) removedManualActivityExecutables.add(normalized);
  return hit;
}

function isRemovedManualActivityGameSuppressed(game = null) {
  if (!game || typeof game !== "object") return false;
  return getActivityGameExecutableKeys(game).some((exe) => isRemovedManualActivityExecutableSuppressed(exe));
}

function persistRemovedManualActivityGame(game = null) {
  if (!game || typeof game !== "object") return;
  const stored = readRemovedManualActivityApps();
  const removedAt = new Date().toISOString();
  const name = String(game.name || game.metadata?.name || "").trim().slice(0, 96);
  const executables = Array.from(new Set((Array.isArray(game.executables) ? game.executables : [game.executable || game.executableName || ""])
    .map((item) => normalizeActivityExecutableName(item || ""))
    .filter(Boolean)));
  executables.forEach((executable) => {
    removedManualActivityExecutables.add(executable.toLowerCase());
    stored.executables[executable] = { removedAt, name };
  });
  writeRemovedManualActivityApps(stored);
}

function clearRemovedManualActivitySuppressionForGame(game = null) {
  const gid = normalizeGameActivityId(game?.id || game?.gameId || "");
  if (gid) removedManualActivityGameIds.delete(gid);
  const executableKeys = new Set(getActivityGameExecutableKeys(game));
  executableKeys.forEach((exe) => removedManualActivityExecutables.delete(exe));
  if (!executableKeys.size) return;
  const stored = readRemovedManualActivityApps();
  Object.keys(stored.executables || {}).forEach((entryExecutable) => {
    if (executableKeys.has(normalizeActivityExecutableName(entryExecutable).toLowerCase())) {
      delete stored.executables[entryExecutable];
    }
  });
  writeRemovedManualActivityApps(stored);
}

function markRemovedManualActivityGame(game = null) {
  const gid = normalizeGameActivityId(game?.id || game?.gameId || "");
  if (gid) removedManualActivityGameIds.add(gid);
  getActivityGameExecutableKeys(game).forEach((exe) => removedManualActivityExecutables.add(exe));
  persistRemovedManualActivityGame(game);
}

function isRemovedManualActivitySuppressed(activityInput = null) {
  const activity = sanitizeGameActivity(activityInput || null);
  if (!activity) return false;
  const gid = normalizeGameActivityId(activity.gameId || activity.id || "");
  const executable = normalizeActivityExecutableName(activity.executable || "").toLowerCase();
  return !!((gid && removedManualActivityGameIds.has(gid)) || (executable && isRemovedManualActivityExecutableSuppressed(executable)));
}

function removeRegisteredActivityApp(gameInput = null) {
  const game = gameInput && typeof gameInput === "object" ? gameInput : null;
  const gid = normalizeGameActivityId(game?.id || game?.gameId || "");
  if (!gid) return false;
  const existing = customActivityGames.find((item) => normalizeGameActivityId(item?.id || item?.gameId || "") === gid);
  if (!existing || existing.source !== "manual") return false;

  markRemovedManualActivityGame(existing);
  debugSettingsLog("[Activity] Removing registered activity app", { gameId: gid, executables: getActivityGameExecutableKeys(existing) });
  const removedExecutables = new Set(getActivityGameExecutableKeys(existing));
  writeCustomActivityGames(customActivityGames.filter((item) => normalizeGameActivityId(item?.id || item?.gameId || "") !== gid));
  activityMetadataStatusByGameId.delete(gid);

  if ((gameActivitySettings.hiddenGameIds || []).includes(gid)) {
    writeGameActivitySettings({
      ...gameActivitySettings,
      hiddenGameIds: (gameActivitySettings.hiddenGameIds || []).filter((item) => normalizeGameActivityId(item) !== gid),
    });
  }

  const currentExecutable = normalizeActivityExecutableName(detectedGameActivity?.executable || "").toLowerCase();
  const removedCurrentActivity = !!(
    normalizeGameActivityId(detectedGameActivity?.gameId || "") === gid
    || (currentExecutable && removedExecutables.has(currentExecutable))
  );
  if (removedCurrentActivity) detectedGameActivity = null;

  mergeLocalRegisteredActivityGamesIntoDesktopState(detectedGameActivity);
  requestActivitySettingsListForceRender();
  updateEffectiveGameActivity({ publishPresence: true, render: true });
  renderActivitySettingsUi({ forceList: true });

  void syncDesktopActivityUserGames().then(() => {
    if (removedCurrentActivity && isRemovedManualActivitySuppressed(detectedGameActivity)) {
      detectedGameActivity = null;
      requestActivitySettingsListForceRender();
      updateEffectiveGameActivity({ publishPresence: true, render: true });
    }
    requestActivitySettingsListForceRender();
    renderActivitySettingsUi({ forceList: true });
  });
  return true;
}

function ensureActivityRemoveConfirmModal() {
  let modal = document.getElementById("activityRemoveConfirmModal");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "activityRemoveConfirmModal";
    modal.className = "modal hidden activityRemoveConfirmModal";
    modal.setAttribute("aria-hidden", "true");
    modal.innerHTML = [
      '<div class="modal__backdrop" data-action="activity-remove-cancel"></div>',
      '<div class="modalCard activityRemoveConfirmCard" role="dialog" aria-modal="true" aria-labelledby="activityRemoveConfirmTitle" aria-describedby="activityRemoveConfirmBody">',
      '  <div class="modalTop">',
      '    <div id="activityRemoveConfirmTitle" class="modalTitle">Remove activity app?</div>',
      '    <button id="btnActivityRemoveConfirmClose" class="icon-btn" type="button" data-action="activity-remove-cancel" aria-label="Close">&times;</button>',
      '  </div>',
      '  <div class="modal__body activityRemoveConfirmBody">',
      '    <div id="activityRemoveConfirmBody" class="appConfirmModalMessage">This app will stop being shown as activity. You can add it again later.</div>',
      '    <div id="activityRemoveConfirmError" class="settingsHint activityRemoveConfirmError" hidden></div>',
      '  </div>',
      '  <div class="appConfirmModalActions activityRemoveConfirmActions">',
      '    <button id="btnActivityRemoveCancel" class="btn ghost" type="button" data-action="activity-remove-cancel">Cancel</button>',
      '    <button id="btnActivityRemoveConfirm" class="btn danger" type="button" data-action="activity-remove-confirm">Remove</button>',
      '  </div>',
      '</div>',
    ].join("");
    document.body.appendChild(modal);
  }
  if (activityRemoveConfirmModalBound !== true) {
    activityRemoveConfirmModalBound = true;
    modal.addEventListener("pointerdown", (event) => {
      event.stopPropagation();
    }, true);
    modal.addEventListener("click", (event) => {
      const target = eventTargetElement(event);
      if (!target) return;
      const confirmButton = target.closest?.('[data-action="activity-remove-confirm"]');
      if (confirmButton instanceof HTMLElement) {
        event.preventDefault();
        event.stopPropagation();
        void confirmActivityRemoveFromModal();
        return;
      }
      const cancelButton = target.closest?.('[data-action="activity-remove-cancel"]');
      if (cancelButton instanceof HTMLElement) {
        event.preventDefault();
        event.stopPropagation();
        debugSettingsLog("[Activity remove] cancelled");
        closeActivityRemoveConfirmModal();
      }
    }, true);
    modal.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        debugSettingsLog("[Activity remove] cancelled");
        closeActivityRemoveConfirmModal();
        return;
      }
      if (event.key === "Enter") {
        event.preventDefault();
        event.stopPropagation();
        void confirmActivityRemoveFromModal();
      }
    }, true);
  }
  return modal;
}

function setActivityRemoveConfirmBusy(isBusy = false) {
  activityRemoveConfirmInFlight = !!isBusy;
  const confirmButton = document.getElementById("btnActivityRemoveConfirm");
  const cancelButton = document.getElementById("btnActivityRemoveCancel");
  const closeButton = document.getElementById("btnActivityRemoveConfirmClose");
  if (confirmButton instanceof HTMLButtonElement) {
    confirmButton.disabled = activityRemoveConfirmInFlight;
    confirmButton.textContent = activityRemoveConfirmInFlight ? "Removing..." : "Remove";
  }
  if (cancelButton instanceof HTMLButtonElement) cancelButton.disabled = activityRemoveConfirmInFlight;
  if (closeButton instanceof HTMLButtonElement) closeButton.disabled = activityRemoveConfirmInFlight;
}

function openActivityRemoveConfirmModal(gameId = "") {
  const gid = normalizeGameActivityId(gameId);
  if (!gid) return false;
  const game = customActivityGames.find((item) => normalizeGameActivityId(item?.id || item?.gameId || "") === gid);
  if (!game) return false;
  const modal = ensureActivityRemoveConfirmModal();
  const errorEl = document.getElementById("activityRemoveConfirmError");
  if (!modal) return false;
  activityRemoveConfirmGameId = gid;
  setActivityRemoveConfirmBusy(false);
  if (errorEl instanceof HTMLElement) {
    errorEl.hidden = true;
    errorEl.textContent = "";
  }
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  debugSettingsLog("[Activity remove] confirmation opened", { gameId: gid });
  requestAnimationFrame(() => {
    try { document.getElementById("btnActivityRemoveConfirm")?.focus?.(); } catch (_) {}
  });
  return true;
}

function closeActivityRemoveConfirmModal() {
  if (activityRemoveConfirmInFlight) return;
  const modal = document.getElementById("activityRemoveConfirmModal");
  if (modal) {
    modal.classList.add("hidden");
    modal.setAttribute("aria-hidden", "true");
  }
  activityRemoveConfirmGameId = "";
}

async function confirmActivityRemoveFromModal() {
  if (activityRemoveConfirmInFlight) return false;
  const gid = normalizeGameActivityId(activityRemoveConfirmGameId || "");
  if (!gid) {
    closeActivityRemoveConfirmModal();
    return false;
  }
  debugSettingsLog("[Activity remove] confirm clicked", { gameId: gid });
  setActivityRemoveConfirmBusy(true);
  const errorEl = document.getElementById("activityRemoveConfirmError");
  try {
    const removed = removeRegisteredActivityApp({ id: gid });
    if (!removed) throw new Error("Activity app was already removed.");
    debugSettingsLog("[Activity remove] removed id", gid);
    activityRemoveConfirmInFlight = false;
    closeActivityRemoveConfirmModal();
    return true;
  } catch (error) {
    if (errorEl instanceof HTMLElement) {
      errorEl.hidden = false;
      errorEl.textContent = "Could not remove this activity app.";
    }
    setActivityRemoveConfirmBusy(false);
    return false;
  }
}

function removeCustomActivityGame(gameId = "") {
  return openActivityRemoveConfirmModal(gameId);
}

function setRegisteredActivityGameHidden(gameId = "", hiddenInput = true) {
  const gid = normalizeGameActivityId(gameId || "");
  if (!gid) return false;
  const hidden = hiddenInput === true;
  const hiddenIds = new Set((gameActivitySettings.hiddenGameIds || []).map(normalizeGameActivityId).filter(Boolean));
  if (hidden) hiddenIds.add(gid);
  else hiddenIds.delete(gid);
  writeGameActivitySettings({
    ...gameActivitySettings,
    hiddenGameIds: Array.from(hiddenIds),
  });

  let changed = false;
  const now = new Date().toISOString();
  const nextGames = customActivityGames.map((game) => {
    const matches = normalizeGameActivityId(game?.id || "") === gid || normalizeGameActivityId(game?.gameId || "") === gid;
    if (!matches) return game;
    if (game.hidden === hidden) return game;
    changed = true;
    return sanitizeCustomActivityGame({ ...game, hidden, updatedAt: now }) || { ...game, hidden, updatedAt: now };
  });
  if (changed) writeCustomActivityGames(nextGames);

  const game = getRegisteredActivityGameById(gid);
  const executableKeys = new Set(getActivityGameExecutableKeys(game));
  const currentExecutable = normalizeActivityExecutableName(detectedGameActivity?.executable || "").toLowerCase();
  const affectsCurrent = !!(
    normalizeGameActivityId(detectedGameActivity?.gameId || "") === gid
    || (currentExecutable && executableKeys.has(currentExecutable))
  );
  if (hidden && affectsCurrent) detectedGameActivity = null;

  mergeLocalRegisteredActivityGamesIntoDesktopState(detectedGameActivity);
  requestActivitySettingsListForceRender();
  updateEffectiveGameActivity({ publishPresence: true, render: true });
  renderActivitySettingsUi({ forceList: true });

  void syncDesktopActivityUserGames().then(async () => {
    const bridge = getDesktopActivityBridge();
    if (!hidden && bridge && typeof bridge.pollNow === "function" && gameActivitySettings.detectGamesAutomatically) {
      try { handleDesktopActivityPayload(await bridge.pollNow()); } catch (_) {}
    }
    requestActivitySettingsListForceRender();
    renderActivitySettingsUi({ forceList: true });
  });
  return true;
}

function updateCustomActivityGameMetadata(gameId = "", metadataInput = null, patch = {}) {
  const gid = normalizeGameActivityId(gameId);
  const metadata = sanitizeGameMetadata(metadataInput || null);
  if (!gid || !metadata) return false;
  const next = customActivityGames.map((game) => {
    if (normalizeGameActivityId(game?.id || "") !== gid) return game;
    return sanitizeCustomActivityGame({
      ...game,
      name: metadata.name || game.name,
      aliases: Array.from(new Set([metadata.name || "", ...(game.aliases || [])].filter(Boolean))).slice(0, 12),
      metadata,
      privateOnly: typeof patch.privateOnly === "boolean" ? patch.privateOnly : game.privateOnly === true,
      confirmed: typeof patch.confirmed === "boolean" ? patch.confirmed : game.confirmed !== false,
      updatedAt: new Date().toISOString(),
    }) || game;
  });
  writeCustomActivityGames(next);
  return true;
}

async function refreshRegisteredGameMetadata(gameId = "", { button = null } = {}) {
  const game = getRegisteredActivityGameById(gameId);
  if (!game) return null;
  const originalText = button instanceof HTMLButtonElement ? button.textContent : "";
  if (button instanceof HTMLButtonElement) {
    button.disabled = true;
    button.textContent = "Finding...";
  }
  try {
    const executable = Array.isArray(game.executables) ? game.executables[0] : "";
    const result = await resolveGameMetadata({
      gameId: game.id,
      executable,
      name: game.name,
      registryGame: game,
    }, { force: true, allowProvider: true });
    const candidates = Array.isArray(result?.candidates) ? result.candidates.map((item) => sanitizeGameMetadata(item || null)).filter(Boolean) : [];
    if (result?.source === "candidates" && candidates.length > 1) {
      openActivityMetadataCandidateModal(game, candidates);
      return null;
    }
    const metadata = candidates.length
      ? candidates[0]
      : ((result?.metadata && result.source !== "fallback") ? result.metadata : null);
    if (metadata) {
      await applyMetadataCandidateToRegisteredGame(game.id, metadata);
    } else {
      setActivityMetadataStatus(game.id, result?.source === "fallback" ? "No game info found" : "Provider unavailable", "No artwork metadata was returned.");
    }
  } catch (error) {
    console.warn("activity metadata refresh failed", error?.message || error);
  } finally {
    if (button instanceof HTMLButtonElement) {
      button.disabled = false;
      button.textContent = originalText || "Find info";
    }
    renderActivitySettingsUi();
  }
  return getBestMetadataForRegisteredGame(game);
}

async function applyMetadataCandidateToRegisteredGame(gameId = "", metadataInput = null) {
  const game = getRegisteredActivityGameById(gameId);
  const metadata = sanitizeGameMetadata(metadataInput || null, game?.name || "");
  if (!game || !metadata) return false;
  const executable = Array.isArray(game.executables) ? game.executables[0] : "";
  writeCachedGameMetadata(getGameMetadataCacheKeys({
    gameId: game.id,
    executable,
    query: metadata.name || game.name,
    provider: metadata.provider,
    providerId: metadata.providerId,
  }), metadata);
  if (customActivityGames.some((item) => normalizeGameActivityId(item?.id || "") === normalizeGameActivityId(game.id || ""))) {
    updateCustomActivityGameMetadata(game.id, metadata, { privateOnly: false, confirmed: true });
    mergeLocalRegisteredActivityGamesIntoDesktopState(detectedGameActivity);
    await syncDesktopActivityUserGames();
  }
  if (detectedGameActivity?.gameId === game.id) {
    detectedGameActivity = applyGameMetadataToActivity(detectedGameActivity, metadata, {
      confirmed: game.confirmed !== false,
      privateOnly: game.privateOnly === true,
    });
    updateEffectiveGameActivity({ publishPresence: true, render: true });
  }
  renderActivitySettingsUi();
  return true;
}

function openActivityMetadataCandidateModal(game = null, candidates = []) {
  const safeGame = game && typeof game === "object" ? game : null;
  const safeCandidates = (Array.isArray(candidates) ? candidates : []).map((item) => sanitizeGameMetadata(item || null)).filter(Boolean).slice(0, 6);
  if (!safeGame?.id || !safeCandidates.length) return;
  bindActivityRunningAppModalOnce();
  exposeSettingsDebugHelpers();
  const { modal } = getActivityRunningAppModalEls();
  if (!modal) return;
  activityMetadataPickGameId = safeGame.id;
  activityRunningApps = [];
  activityRunningSelectedExecutable = Array.isArray(safeGame.executables) ? (safeGame.executables[0] || "") : "";
  activityRunningResolverState = {
    loading: false,
    executable: activityRunningSelectedExecutable,
    query: safeGame.name || "",
    metadata: null,
    candidates: safeCandidates,
    error: "",
    privateFallback: false,
  };
  const titleEl = document.getElementById("activityRunningAppModalTitle");
  if (titleEl) titleEl.textContent = "Choose game match";
  modal.classList.add("is-metadata-pick");
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  renderActivityRunningAppModal(`Choose the match for ${safeGame.name || "this game"}.`);
}
function addOrUpdateCustomActivityGameForExecutable(executableInput = "", metadataInput = null, { privateOnly = false, confirmed = true, kind = "", activityVerb = "" } = {}) {
  const executable = normalizeActivityExecutableName(executableInput || "");
  if (!executable) return null;
  const fallbackName = getFriendlyRunningAppName(executable) || executable.replace(/\.exe$/i, "");
  const metadata = sanitizeGameMetadata(metadataInput || null, fallbackName) || sanitizeGameMetadata({
    provider: "custom",
    name: fallbackName,
    confidence: 0.35,
  }, fallbackName);
  if (!metadata) return null;
  const provider = normalizeGameMetadataProvider(metadata.provider || "");
  const resolvedKind = String(kind || "").trim().toLowerCase() === "game"
    || ((provider === "rawg" || provider === "catalog") && Number(metadata.confidence || 0) >= 0.7)
      ? "game"
      : "app";
  const resolvedVerb = String(activityVerb || "").trim().toLowerCase() === "playing" || resolvedKind === "game" ? "playing" : "using";
  const existingIdx = customActivityGames.findIndex((game) => (
    Array.isArray(game?.executables)
    && game.executables.some((item) => normalizeActivityExecutableName(item).toLowerCase() === executable.toLowerCase())
  ));
  const now = new Date().toISOString();
  const existing = existingIdx >= 0 ? customActivityGames[existingIdx] : null;
  const row = sanitizeCustomActivityGame({
    ...(existing || {}),
    id: existing?.id || `custom-${normalizeGameActivityId(metadata.name || fallbackName)}-${normalizeGameActivityId(executable)}`,
    source: existing?.source || "manual",
    kind: resolvedKind,
    activityVerb: resolvedVerb,
    name: metadata.name || fallbackName,
    executables: [executable],
    aliases: Array.from(new Set([metadata.name || "", fallbackName].filter(Boolean))).slice(0, 12),
    metadata: {
      ...metadata,
      provider: metadata.provider || (resolvedKind === "game" ? "rawg" : "custom"),
      confidence: resolvedKind === "game" ? Math.max(metadata.confidence || 0.85, 0.85) : Math.max(metadata.confidence || 0.35, 0.35),
    },
    hidden: false,
    privateOnly,
    confirmed,
    custom: true,
    removable: true,
    firstDetectedAt: existing?.firstDetectedAt || now,
    lastDetectedAt: now,
    createdAt: existing?.createdAt || now,
    updatedAt: now,
  });
  if (!row) return null;
  clearRemovedManualActivitySuppressionForGame(row);
  writeGameActivitySettings({
    ...gameActivitySettings,
    hiddenGameIds: (gameActivitySettings.hiddenGameIds || []).filter((item) => normalizeGameActivityId(item) !== normalizeGameActivityId(row.id || row.gameId || "")),
  });
  const next = [...customActivityGames];
  if (existingIdx >= 0) next[existingIdx] = row;
  else next.unshift(row);
  writeCustomActivityGames(next);
  writeCachedGameMetadata(getGameMetadataCacheKeys({
    gameId: row.id,
    executable,
    query: row.name,
    provider: row.metadata?.provider,
    providerId: row.metadata?.providerId,
  }), row.metadata);
  return row;
}
async function addRunningAppFromResolvedMetadata(metadataInput = null, { privateFallback = false } = {}) {
  const executable = normalizeActivityExecutableName(activityRunningSelectedExecutable || activityRunningResolverState.executable || "");
  if (!executable) return;
  const existing = getRegisteredActivityGameByExecutable(executable);
  if (existing && !existing.custom) {
    await refreshRegisteredGameMetadata(existing.id);
    closeActivityRunningAppModal();
    return;
  }
  const fallbackName = getFriendlyRunningAppName(executable) || executable.replace(/\.exe$/i, "");
  const metadata = sanitizeGameMetadata(metadataInput || null, fallbackName) || sanitizeGameMetadata({
    provider: "custom",
    name: fallbackName,
    confidence: 0.35,
  }, fallbackName);
  const provider = normalizeGameMetadataProvider(metadata?.provider || "");
  const isGame = !privateFallback && (provider === "rawg" || provider === "catalog") && Number(metadata?.confidence || 0) >= 0.7;
  const row = addOrUpdateCustomActivityGameForExecutable(executable, metadata, {
    privateOnly: false,
    confirmed: true,
    kind: isGame ? "game" : "app",
    activityVerb: isGame ? "playing" : "using",
  });
  if (!row) return;
  const startedAt = detectedGameActivity?.gameId === row.id && Number.isFinite(Number(detectedGameActivity.startedAt))
    ? Number(detectedGameActivity.startedAt)
    : Date.now();
  detectedGameActivity = sanitizeGameActivity({
    type: "playing",
    source: "manual-running-app",
    gameId: row.id,
    name: row.name,
    kind: row.kind || "app",
    activityVerb: row.activityVerb || (row.kind === "app" ? "using" : "playing"),
    startedAt,
    detectedAt: Date.now(),
    icon: row.metadata?.icon || row.icon || "",
    cover: row.metadata?.cover || row.cover || "",
    background: row.metadata?.background || row.metadata?.cover || row.cover || "",
    description: row.metadata?.description || "",
    provider: row.metadata?.provider || (row.kind === "app" ? "custom" : "rawg"),
    providerId: row.metadata?.providerId || "",
    slug: row.metadata?.slug || "",
    confidence: row.metadata?.confidence || (row.kind === "app" ? 0.35 : 0.85),
    confirmed: true,
    privateOnly: false,
    executable,
  }) || detectedGameActivity;
  requestActivitySettingsListForceRender();
  updateEffectiveGameActivity({ publishPresence: true, render: true });
  await syncDesktopActivityUserGames();
  const bridge = getDesktopActivityBridge();
  if (bridge && typeof bridge.pollNow === "function" && gameActivitySettings.detectGamesAutomatically) {
    try { handleDesktopActivityPayload(await bridge.pollNow()); } catch (_) {}
  }
  renderActivitySettingsUi({ forceList: true });
  closeActivityRunningAppModal();
}

function closeActivityRunningAppModal() {
  const { modal } = getActivityRunningAppModalEls();
  if (!modal) return;
  modal.classList.add("hidden");
  modal.classList.remove("is-metadata-pick");
  modal.setAttribute("aria-hidden", "true");
  const titleEl = document.getElementById("activityRunningAppModalTitle");
  if (titleEl) titleEl.textContent = "Add running app";
  activityRunningApps = [];
  activityRunningSelectedExecutable = "";
  activityRunningSearchQuery = "";
  activityRunningUnavailableMessage = "";
  activityRunningShowSystemApps = false;
  activityMetadataPickGameId = "";
  activityRunningResolverState = { loading: false, executable: "", query: "", metadata: null, candidates: [], error: "", privateFallback: false };
}

async function openActivityRunningAppModal() {
  bindActivityRunningAppModalOnce();
  exposeSettingsDebugHelpers();
  const { modal } = getActivityRunningAppModalEls();
  debugSettingsLog("[Activity] opening modal", { modal: !!modal });
  if (!modal) return;
  activityRunningApps = [];
  activityRunningSelectedExecutable = "";
  activityRunningSearchQuery = "";
  activityRunningUnavailableMessage = "";
  activityRunningShowSystemApps = false;
  activityMetadataPickGameId = "";
  activityRunningResolverState = { loading: false, executable: "", query: "", metadata: null, candidates: [], error: "", privateFallback: false };
  const titleEl = document.getElementById("activityRunningAppModalTitle");
  if (titleEl) titleEl.textContent = "Add running app";
  modal.classList.remove("is-metadata-pick");
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  debugSettingsLog("[Activity] modal rendered", { open: !modal.classList.contains("hidden") });
  renderActivityRunningAppModal();
  await loadActivityRunningApps();
}

async function openAddRunningAppModal() {
  return openActivityRunningAppModal();
}
async function loadActivityRunningApps() {
  const bridge = getDesktopActivityBridge();
  debugSettingsLog("[Activity] bridge available", !!(bridge && typeof bridge.listRunningApps === "function"));
  activityRunningResolverState = { loading: false, executable: "", query: "", metadata: null, candidates: [], error: "", privateFallback: false };
  activityRunningUnavailableMessage = "";
  if (!bridge || typeof bridge.listRunningApps !== "function") {
    activityRunningApps = [];
    activityRunningUnavailableMessage = "Running app detection is available in the desktop app.";
    renderActivityRunningAppModal(activityRunningUnavailableMessage);
    return;
  }
  renderActivityRunningAppModal("Loading running apps...");
  try {
    const result = await bridge.listRunningApps({ includeSystem: activityRunningShowSystemApps });
    const apps = Array.isArray(result?.apps) ? result.apps.map(sanitizeRunningAppRow).filter(Boolean) : [];
    activityRunningApps = apps.sort((a, b) => {
      if (a.matchedKnownGame !== b.matchedKnownGame) return a.matchedKnownGame ? -1 : 1;
      return a.executable.localeCompare(b.executable);
    });
    activityRunningUnavailableMessage = result?.supported === false ? "Running app selection is currently available on Windows desktop." : "";
    debugSettingsLog("[Activity] apps loaded", activityRunningApps.length);
    renderActivityRunningAppModal(activityRunningUnavailableMessage || "Choose an app running on this device. Process names stay local unless you add one.");
  } catch (error) {
    activityRunningApps = [];
    activityRunningUnavailableMessage = "Could not load running apps.";
    renderActivityRunningAppModal(activityRunningUnavailableMessage);
  }
}

function renderActivityRunningAppModal(statusText = "") {
  const { modal, status, search, showSystem, list, resolver, addSelected } = getActivityRunningAppModalEls();
  if (!modal || modal.classList.contains("hidden")) return;
  if (status) status.textContent = statusText || "Choose an app running on this device. Process names stay local unless you add one.";
  if (search instanceof HTMLInputElement) {
    search.value = activityRunningSearchQuery;
    search.hidden = !!activityMetadataPickGameId;
  }
  if (showSystem instanceof HTMLInputElement) {
    showSystem.checked = !!activityRunningShowSystemApps;
    const toggleWrap = showSystem.closest(".activityRunningAppOptions");
    if (toggleWrap instanceof HTMLElement) toggleWrap.hidden = !!activityMetadataPickGameId;
  }
  if (addSelected instanceof HTMLButtonElement) {
    addSelected.disabled = !activityRunningSelectedExecutable || activityRunningResolverState.loading === true || !!activityMetadataPickGameId;
    addSelected.textContent = activityRunningResolverState.metadata ? "Add selected" : "Add as app";
  }
  if (list) {
    if (activityMetadataPickGameId) {
      const game = getRegisteredActivityGameById(activityMetadataPickGameId);
      list.innerHTML = `
        <div class="activityRunningAppEmpty">
          <b>${esc(game?.name || "Registered game")}</b>
          <span>${esc((game?.executables || []).slice(0, 2).join(", ") || "Choose the best metadata match.")}</span>
        </div>
      `;
    } else {
      const searchNeedle = normalizeGameMetadataComparableName(activityRunningSearchQuery);
      const filteredApps = activityRunningApps.filter((app) => {
        if (!searchNeedle) return true;
        return normalizeGameMetadataComparableName(`${app.displayName || ""} ${app.executable || ""}`).includes(searchNeedle);
      });
      list.innerHTML = filteredApps.length
        ? filteredApps.map((app) => {
          const selected = normalizeActivityExecutableName(app.executable).toLowerCase() === normalizeActivityExecutableName(activityRunningSelectedExecutable).toLowerCase();
          const label = app.displayName || app.knownGameName || getFriendlyRunningAppName(app.executable) || app.executable;
          return `
            <button class="activityRunningAppItem${selected ? " is-selected" : ""}" type="button" data-running-executable="${escAttr(app.executable)}">
              <span>
                <b>${esc(label)}</b>
                <small>${esc(app.executable)}</small>
              </span>
              ${app.alreadyRegistered ? `<span class="settingsActivityGameProvider">REGISTERED</span>` : (app.matchedKnownGame ? `<span class="settingsActivityGameProvider">GAME</span>` : `<span class="settingsActivityGameProvider">APP</span>`)}
            </button>
          `;
        }).join("")
        : `<div class="activityRunningAppEmpty">${esc(activityRunningUnavailableMessage || "No running apps found.")}</div>`;
    }
  }
  if (!resolver) return;

  const state = activityRunningResolverState || {};
  if (!activityRunningSelectedExecutable) {
    resolver.innerHTML = `<div class="activityRunningAppEmpty">Select a running app to add it or search game metadata.</div>`;
    return;
  }
  if (state.loading) {
    resolver.innerHTML = `
      <div class="activityRunningAppEmpty">
        <b>Finding game info...</b>
        <span>${esc(state.query || activityRunningSelectedExecutable)}</span>
      </div>
    `;
    return;
  }

  const existing = getRegisteredActivityGameByExecutable(activityRunningSelectedExecutable);
  if (state.metadata) {
    const provider = normalizeGameMetadataProvider(state.metadata.provider || "") || "local";
    resolver.innerHTML = `
      <div class="activityRunningPreview">
        ${buildActivityArtworkThumbHtml(state.metadata, state.metadata.name, "activityRunningAppThumb")}
        <div class="activityRunningPreview__body">
          <span class="settingsActivityGameProvider">${esc(provider.toUpperCase())}</span>
          <b>${esc(state.metadata.name)}</b>
          <small>${existing ? "Already registered. You can refresh its info." : "Matched automatically. Add it without typing a name or photo."}</small>
          ${state.metadata.description ? `<p>${esc(state.metadata.description)}</p>` : ""}
        </div>
      </div>
      <button class="btn" type="button" data-activity-running-add-auto>${existing ? "Refresh info" : "Add"}</button>
    `;
    return;
  }

  if (Array.isArray(state.candidates) && state.candidates.length) {
    resolver.innerHTML = `
      <div class="activityRunningResolverHead">
        <b>Choose game match</b>
        <small>ALTARA found a few possible matches for ${esc(state.query || activityRunningSelectedExecutable)}.</small>
      </div>
      <div class="activityRunningCandidates">
        ${state.candidates.map((candidate, index) => `
          <button class="activityRunningCandidate" type="button" data-activity-running-candidate="${escAttr(index)}">
            ${buildActivityArtworkThumbHtml(candidate, candidate.name, "activityRunningAppThumb")}
            <span>
              <b>${esc(candidate.name)}</b>
              <small>${esc((candidate.provider || "rawg").toUpperCase())}${candidate.released ? ` - ${esc(candidate.released)}` : ""}</small>
            </span>
          </button>
        `).join("")}
      </div>
      <button class="btn ghost" type="button" data-activity-running-use-app-name>Use app name instead</button>
    `;
    return;
  }

  const fallbackName = getFriendlyRunningAppName(activityRunningSelectedExecutable) || "Running app";
  resolver.innerHTML = `
    <div class="activityRunningAppEmpty">
      <b>${esc(state.error || "No game info found.")}</b>
      <span>ALTARA can still add ${esc(fallbackName)} as an app. It will only be shown after you add it.</span>
    </div>
    <button class="btn ghost" type="button" data-activity-running-private>Add as app</button>
  `;
}
async function selectActivityRunningExecutable(executableInput = "") {
  const executable = normalizeActivityExecutableName(executableInput || "");
  if (!executable) return;
  activityRunningSelectedExecutable = executable;
  const appRow = activityRunningApps.find((app) => normalizeActivityExecutableName(app.executable).toLowerCase() === executable.toLowerCase()) || null;
  const query = getFriendlyRunningAppName(executable, appRow?.knownGameName || "") || executable.replace(/\.exe$/i, "");
  const seq = ++activityRunningResolveSeq;
  if (!shouldSearchGameMetadataForRunningApp(appRow || { executable })) {
    activityRunningResolverState = {
      loading: false,
      executable,
      query,
      metadata: null,
      candidates: [],
      error: "No game metadata lookup needed.",
      privateFallback: true,
    };
    renderActivityRunningAppModal();
    return;
  }
  activityRunningResolverState = { loading: true, executable, query, metadata: null, candidates: [], error: "", privateFallback: false };
  renderActivityRunningAppModal();
  try {
    const registered = getRegisteredActivityGameByExecutable(executable);
    const result = await resolveGameMetadata({
      executable,
      query,
      gameId: registered?.id || appRow?.knownGameId || "",
      name: registered?.name || appRow?.knownGameName || query,
      registryGame: registered,
    }, { force: true, allowProvider: true });
    if (seq !== activityRunningResolveSeq) return;
    const candidates = Array.isArray(result?.candidates) ? result.candidates.map((item) => sanitizeGameMetadata(item || null)).filter(Boolean) : [];
    const metadata = sanitizeGameMetadata(result?.metadata || null, query);
    const provider = normalizeGameMetadataProvider(metadata?.provider || "");
    const highConfidence = metadata && result?.source !== "fallback" && result?.source !== "candidates" && (
      registered
      || appRow?.matchedKnownGame
      || (metadata.confidence >= 0.85 && ["cache", "local", "rawg", "catalog"].includes(String(result?.source || provider || "")))
    );
    activityRunningResolverState = {
      loading: false,
      executable,
      query,
      metadata: highConfidence ? metadata : null,
      candidates: highConfidence ? [] : candidates,
      error: highConfidence || candidates.length ? "" : "No game info found.",
      privateFallback: !highConfidence && !candidates.length,
    };
    renderActivityRunningAppModal();
  } catch (error) {
    if (seq !== activityRunningResolveSeq) return;
    activityRunningResolverState = { loading: false, executable, query, metadata: null, candidates: [], error: "No game info found.", privateFallback: true };
    renderActivityRunningAppModal();
  }
}
function bindActivityRunningAppModalOnce() {
  if (activityRunningAppModalBound) return;
  activityRunningAppModalBound = true;
  const { modal, search, showSystem, list, resolver, addSelected } = getActivityRunningAppModalEls();
  document.getElementById("btnActivityRunningAppClose")?.addEventListener("click", closeActivityRunningAppModal);
  document.getElementById("btnActivityRunningAppCancel")?.addEventListener("click", closeActivityRunningAppModal);
  search?.addEventListener("input", (event) => {
    activityRunningSearchQuery = event?.target instanceof HTMLInputElement ? event.target.value : "";
    renderActivityRunningAppModal();
  });
  showSystem?.addEventListener("change", (event) => {
    activityRunningShowSystemApps = event?.target instanceof HTMLInputElement ? event.target.checked : false;
    void loadActivityRunningApps();
  });
  addSelected?.addEventListener("click", () => {
    if (!activityRunningSelectedExecutable || activityRunningResolverState.loading) return;
    if (activityRunningResolverState.metadata) {
      void addRunningAppFromResolvedMetadata(activityRunningResolverState.metadata, { privateFallback: false });
      return;
    }
    const fallbackName = getFriendlyRunningAppName(activityRunningSelectedExecutable) || "Running app";
    void addRunningAppFromResolvedMetadata({ provider: "custom", name: fallbackName, confidence: 0.35 }, { privateFallback: true });
  });
  modal?.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    if (target?.dataset?.close) closeActivityRunningAppModal();
  });
  list?.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    const button = target?.closest?.("[data-running-executable]");
    if (!(button instanceof HTMLButtonElement)) return;
    void selectActivityRunningExecutable(button.getAttribute("data-running-executable") || "");
  });
  resolver?.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    const autoBtn = target.closest?.("[data-activity-running-add-auto]");
    if (autoBtn instanceof HTMLButtonElement) {
      void addRunningAppFromResolvedMetadata(activityRunningResolverState.metadata, { privateFallback: false });
      return;
    }
    const candidateBtn = target.closest?.("[data-activity-running-candidate]");
    if (candidateBtn instanceof HTMLButtonElement) {
      const index = clampInt(candidateBtn.getAttribute("data-activity-running-candidate"), 0, 99, 0);
      const metadata = activityRunningResolverState.candidates?.[index] || null;
      if (metadata && activityMetadataPickGameId) {
        void applyMetadataCandidateToRegisteredGame(activityMetadataPickGameId, metadata).then(() => closeActivityRunningAppModal());
      } else if (metadata) {
        void addRunningAppFromResolvedMetadata(metadata, { privateFallback: false });
      }
      return;
    }
    const useAppNameBtn = target.closest?.("[data-activity-running-use-app-name]");
    if (useAppNameBtn instanceof HTMLButtonElement) {
      const fallbackName = getFriendlyRunningAppName(activityRunningSelectedExecutable) || "Running app";
      void addRunningAppFromResolvedMetadata({ provider: "custom", name: fallbackName, confidence: 0.35 }, { privateFallback: true });
      return;
    }
    const privateBtn = target.closest?.("[data-activity-running-private]");
    if (privateBtn instanceof HTMLButtonElement) {
      const fallbackName = getFriendlyRunningAppName(activityRunningSelectedExecutable) || "Running app";
      void addRunningAppFromResolvedMetadata({ provider: "custom", name: fallbackName, confidence: 0.35 }, { privateFallback: true });
    }
  });
}

function exposeSettingsDebugHelpers() {
  try {
    const host = String(window.location?.hostname || "").trim().toLowerCase();
    const localDev = host === "localhost" || host === "127.0.0.1" || host === "::1";
    if (window?.altaraElectron?.isDev === true || localDev || isSettingsDebugEnabled()) {
      window.__altaraOpenAddRunningAppModal = openAddRunningAppModal;
    }
  } catch (_) {}
}
function requestActivitySettingsListForceRender() {
  activitySettingsForceNextListRender = true;
}

function isActivityRegisteredListInteracting(listEl = null) {
  if (!(listEl instanceof HTMLElement)) return false;
  try {
    if (listEl.matches(":hover")) return true;
  } catch (_) {}
  const active = document.activeElement;
  return !!(active instanceof HTMLElement && listEl.contains(active));
}

function applyPendingActivityRegisteredListRender(listEl = null) {
  if (!(listEl instanceof HTMLElement)) return false;
  const pendingSignature = activitySettingsRegisteredListPendingSignature;
  if (!pendingSignature) return false;
  if (isActivityRegisteredListInteracting(listEl)) return false;
  const pendingHtml = activitySettingsRegisteredListPendingHtml;
  activitySettingsRegisteredListPendingHtml = "";
  activitySettingsRegisteredListPendingSignature = "";
  listEl.innerHTML = pendingHtml;
  listEl.dataset.activityListSignature = pendingSignature;
  activitySettingsRegisteredListSignature = pendingSignature;
  return true;
}

function bindActivityRegisteredListStabilityOnce(listEl = null) {
  if (!(listEl instanceof HTMLElement)) return;
  if (activitySettingsRegisteredListBoundEl === listEl) return;
  activitySettingsRegisteredListBoundEl = listEl;
  activitySettingsRegisteredListPendingHtml = "";
  activitySettingsRegisteredListPendingSignature = "";
  const flushPending = () => {
    const run = () => applyPendingActivityRegisteredListRender(listEl);
    try { window.setTimeout(run, 40); } catch (_) { run(); }
  };
  listEl.addEventListener("pointerleave", flushPending);
  listEl.addEventListener("mouseleave", flushPending);
  listEl.addEventListener("focusout", flushPending);
  listEl.addEventListener("blur", flushPending, true);
}

function setActivityRegisteredListHtml(listEl = null, html = "", signature = "", { force = false } = {}) {
  if (!(listEl instanceof HTMLElement)) return false;
  bindActivityRegisteredListStabilityOnce(listEl);
  const safeHtml = String(html || "");
  const safeSignature = String(signature || safeHtml || "empty");
  const currentSignature = String(listEl.dataset.activityListSignature || "");
  if (currentSignature === safeSignature) {
    if (activitySettingsRegisteredListPendingSignature === safeSignature) {
      activitySettingsRegisteredListPendingHtml = "";
      activitySettingsRegisteredListPendingSignature = "";
    }
    activitySettingsRegisteredListSignature = safeSignature;
    return false;
  }
  if (!force && isActivityRegisteredListInteracting(listEl)) {
    activitySettingsRegisteredListPendingHtml = safeHtml;
    activitySettingsRegisteredListPendingSignature = safeSignature;
    return false;
  }
  activitySettingsRegisteredListPendingHtml = "";
  activitySettingsRegisteredListPendingSignature = "";
  listEl.innerHTML = safeHtml;
  listEl.dataset.activityListSignature = safeSignature;
  activitySettingsRegisteredListSignature = safeSignature;
  return true;
}

function buildActivitySettingsRegisteredListHtml({ supported = false, hasBridge = false } = {}) {
  const games = getLocalRegisteredActivityGamesForState(desktopActivityState.registeredGames, detectedGameActivity);
  if (!games.length) {
    const emptyText = supported
      ? "No registered apps yet. Open a game or app and add it from this device."
      : (hasBridge ? "Running app detection is currently available on Windows desktop." : "Running app detection is available in the desktop app.");
    return {
      html: '<div class="settingsActivityEmpty">' + esc(emptyText) + '</div>',
      signature: JSON.stringify(["empty", supported === true, hasBridge === true, emptyText]),
    };
  }

  const signatureRows = [];
  const html = games.map((game) => {
    const metadata = getBestMetadataForRegisteredGame(game) || getLocalMetadataForRegisteredGame(game) || { name: game.name };
    const hidden = isGameActivityHidden(game.id);
    const displayName = metadata?.name || game.name;
    const exeText = (game.executables || []).slice(0, 3).join(", ");
    const provider = normalizeGameMetadataProvider(metadata?.provider || "") || (game.custom ? "custom" : "local");
    const providerLabel = game.kind === "app"
      ? "APP"
      : (provider === "rawg" ? "RAWG" : (provider === "catalog" ? "CATALOG" : (game.custom ? "CUSTOM" : (provider ? provider.toUpperCase() : "LOCAL"))));
    const hasArtwork = !!(metadata?.icon || metadata?.cover || metadata?.background);
    const privacyText = hidden
      ? "Hidden"
      : (game.privateOnly || game.confirmed === false ? "Private fallback" : "Shareable when enabled");
    const metadataStatus = getActivityMetadataStatus(game.id);
    const metadataStatusText = hidden
      ? "Not shared while hidden"
      : (metadataStatus?.status
        ? (metadataStatus.status + (metadataStatus.detail ? " - " + metadataStatus.detail : ""))
        : (hasArtwork ? "Artwork loaded" : "Missing artwork"));
    const gameId = normalizeGameActivityId(game.id || game.gameId || "");
    const escapedId = escAttr(game.id);
    const canRemove = game.source === "manual" && game.removable === true;
    signatureRows.push({
      id: gameId,
      name: displayName,
      exe: exeText,
      provider: providerLabel,
      privacy: privacyText,
      status: metadataStatusText,
      running: game.running === true,
      hidden,
      removable: canRemove,
      artwork: metadata?.icon || metadata?.cover || metadata?.background || "",
    });
    return [
      '<div class="settingsActivityGameRow" data-activity-game-row="' + escapedId + '">',
      buildActivityArtworkThumbHtml(metadata, displayName, "settingsActivityGameThumb"),
      '<div class="settingsActivityGameRow__main">',
      '<b>' + esc(displayName) + '</b>',
      '<small>' + esc(exeText || "Known executable") + '</small>',
      '<span class="settingsActivityGameMetaLine">',
      '<span class="settingsActivityGameProvider">' + esc(providerLabel) + '</span>',
      '<span>' + esc(privacyText) + '</span>',
      '</span>',
      '<small class="settingsActivityGameInfoStatus">' + esc(metadataStatusText) + '</small>',
      '</div>',
      '<span class="settingsActivityGameState' + (game.running ? " is-running" : "") + '">' + (game.running ? "Running" : "Not running") + '</span>',
      '<div class="settingsActivityGameActions">',
      '<button class="btn ghost settingsActivityGameVisibility settingsActivityActionBtn" type="button" data-action="' + (hidden ? "activity-show" : "activity-hide") + '" data-activity-id="' + escapedId + '" data-activity-game-visibility="' + escapedId + '">' + (hidden ? "Show" : "Hide") + '</button>',
      canRemove ? '<button class="btn ghost danger settingsActivityActionBtn" type="button" data-action="activity-remove-registered-app" data-activity-id="' + escapedId + '">Remove</button>' : "",
      '</div>',
      '</div>',
    ].join("");
  }).join("");

  return { html, signature: JSON.stringify(signatureRows) };
}

function renderActivitySettingsUi({ forceList = false } = {}) {
  const panel = document.querySelector('[data-settings-panel="activity"]');
  if (!panel) return;
  const displayToggle = document.getElementById("settingsActivityDisplayGame");
  const detectToggle = document.getElementById("settingsActivityDetectGames");
  const noteEl = document.getElementById("settingsActivityDesktopNote");
  const providerEl = document.getElementById("settingsActivityMetadataProvider");
  const currentEl = document.getElementById("settingsActivityCurrent");
  const listEl = document.getElementById("settingsActivityGamesList");
  const refreshBtn = document.getElementById("btnSettingsActivityPollNow");
  const addRunningBtn = document.getElementById("btnSettingsActivityAddRunningApp");
  const hasBridge = !!getDesktopActivityBridge();
  const supported = hasBridge && desktopActivityState.supported === true;

  if (displayToggle instanceof HTMLInputElement) displayToggle.checked = !!gameActivitySettings.displayGameActivity;
  if (detectToggle instanceof HTMLInputElement) {
    detectToggle.checked = !!gameActivitySettings.detectGamesAutomatically;
    detectToggle.disabled = !supported;
  }
  if (refreshBtn instanceof HTMLButtonElement) refreshBtn.disabled = !supported || !gameActivitySettings.detectGamesAutomatically;
  if (addRunningBtn instanceof HTMLButtonElement) addRunningBtn.disabled = false;
  if (noteEl) {
    noteEl.textContent = supported
      ? "Activity detection runs locally in the desktop app. Only apps you register can be shared."
      : (hasBridge ? "Running app detection is currently available on Windows desktop." : "Running app detection is available in the desktop app.");
  }
  if (providerEl) providerEl.textContent = getActivityMetadataProviderStatusText();

  const detected = sanitizeGameActivity(detectedGameActivity);
  const shared = getCurrentPublicGameActivity();
  if (currentEl) {
    if (detected) {
      const hidden = isGameActivityHidden(detected.gameId);
      const shareText = shared
        ? `Visible on your profile ${formatGameActivityDurationText(shared.startedAt)}`
        : (hidden
          ? "Hidden locally. This activity will not be shown."
          : (detected.privateOnly || detected.confirmed === false
            ? "Private fallback. Add or confirm this app before sharing."
            : (gameActivitySettings.displayGameActivity ? "Not shared while unavailable or invisible." : "Detected locally. Activity sharing is off.")));
      currentEl.innerHTML = `
        ${buildActivityArtworkThumbHtml(detected, detected.name, "settingsActivityCurrent__icon")}
        <div>
          <b>${esc(getActivityVerbLabel(detected))} ${esc(detected.name)}</b>
          <small>${esc(shareText)}</small>
        </div>
      `;
    } else {
      currentEl.innerHTML = `
        <div class="settingsActivityCurrent__icon activityArtworkThumb" aria-hidden="true"><span>ALT</span></div>
        <div>
          <b>No activity detected</b>
          <small>${esc(gameActivitySettings.detectGamesAutomatically ? "Registered games and apps will appear here when running." : "Enable detection to look for registered games and apps on this device.")}</small>
        </div>
      `;
    }
  }

  if (listEl) {
    const { html, signature } = buildActivitySettingsRegisteredListHtml({ supported, hasBridge });
    const shouldForceList = activitySettingsForceNextListRender === true || forceList === true;
    activitySettingsForceNextListRender = false;
    setActivityRegisteredListHtml(listEl, html, signature, { force: shouldForceList });
  }
}

function bindActivitySettingsUiOnce() {
  if (activitySettingsUiBound) return;
  activitySettingsUiBound = true;

  bindActivityRunningAppModalOnce();
  exposeSettingsDebugHelpers();

  document.getElementById("settingsActivityDisplayGame")?.addEventListener("change", (event) => {
    const checked = event?.target instanceof HTMLInputElement ? event.target.checked : false;
    const next = {
      ...gameActivitySettings,
      displayGameActivity: !!checked,
      detectGamesAutomatically: checked ? true : gameActivitySettings.detectGamesAutomatically,
    };
    writeGameActivitySettings(next);
    updateEffectiveGameActivity({ publishPresence: true, render: true });
    void syncDesktopActivityUserGames().finally(() => syncDesktopActivityDetectionEnabled());
  });

  document.getElementById("settingsActivityDetectGames")?.addEventListener("change", (event) => {
    const checked = event?.target instanceof HTMLInputElement ? event.target.checked : false;
    writeGameActivitySettings({
      ...gameActivitySettings,
      detectGamesAutomatically: !!checked,
    });
    if (!checked) {
      detectedGameActivity = null;
      updateEffectiveGameActivity({ publishPresence: true, render: true });
    }
    void syncDesktopActivityUserGames().finally(() => syncDesktopActivityDetectionEnabled());
  });

  document.getElementById("btnSettingsActivityPollNow")?.addEventListener("click", async (event) => {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    requestActivitySettingsListForceRender();
    const bridge = getDesktopActivityBridge();
    if (!bridge || typeof bridge.pollNow !== "function") return;
    try {
      await syncDesktopActivityUserGames();
      handleDesktopActivityPayload(await bridge.pollNow());
          scheduleRegisteredGamesMetadataEnrichment({ force: true, reason: "manual_refresh" });
    } catch (error) {
      console.warn("desktop activity manual poll failed", error?.message || error);
    }
  });

  document.getElementById("settingsActivityGamesList")?.addEventListener("click", (event) => {
    const target = eventTargetElement(event);
    if (!target) return;
    const removeButton = target.closest?.('[data-action="activity-remove-registered-app"], [data-action="activity-remove"]');
    if (removeButton instanceof HTMLElement) {
      event.preventDefault();
      event.stopPropagation();
      const gameId = normalizeGameActivityId(removeButton.getAttribute("data-activity-id") || "");
      debugSettingsLog("[Activity remove] row remove clicked", { gameId });
      if (gameId) void removeCustomActivityGame(gameId);
      return;
    }

    const visibilityButton = target.closest?.('[data-action="activity-hide"], [data-action="activity-show"], [data-activity-game-visibility]');
    if (visibilityButton instanceof HTMLButtonElement) {
      event.preventDefault();
      event.stopPropagation();
      const gameId = normalizeGameActivityId(visibilityButton.getAttribute("data-activity-game-visibility") || visibilityButton.getAttribute("data-activity-id") || "");
      if (!gameId) return;
      const action = String(visibilityButton.getAttribute("data-action") || "").trim();
      const shouldHide = action === "activity-hide" ? true : (action === "activity-show" ? false : !isGameActivityHidden(gameId));
      setRegisteredActivityGameHidden(gameId, shouldHide);
    }
  });

}

function getServerMemberActivityMeta(userId = "", fallbackStatusLabel = "Offline") {
  const activity = getPresenceActivityForUser(userId);
  if (!activity) return fallbackStatusLabel;
  if (activity.type === "listening" && activity.provider === SPOTIFY_PROVIDER) return "Listening to Spotify";
  return `${getActivityVerbLabel(activity)} ${activity.name}`;
}
async function setMyPresenceStatusEverywhere(statusInput, { persistAccount = true } = {}) {
  const status = normalizeManualPresenceStatus(statusInput);
  const previousStatus = normalizeManualPresenceStatus(resolveMyPresenceStatus(state.me));
  lastManualPresenceStatusChangeAt = Date.now();
  logPresenceDebug("set manual status start", {
    userId: normId(state.user?.id || ""),
    previousStatus,
    status,
    persistAccount: persistAccount !== false,
  });
  if (status === "focus") {
    logPresenceDebug("set manual status focus", {
      userId: normId(state.user?.id || ""),
    });
  }

  state.me = state.me || {};
  state.me.status = setMyStatus(status);
  if (!focusPlusAutomationRuntime.changingStatus && focusPlusAutomationRuntime.activeKey && status !== "focus") {
    scheduleFocusAutomationEvaluation("manual_status_changed", 0);
  }
  if (state.user?.id) cacheProfileRow({ id: state.user.id, status });
  applyMeStatusDot(status);
  updateEffectiveGameActivity({ publishPresence: false, render: true });

  const statusSelect = document.getElementById("presenceStatus");
  if (statusSelect && statusSelect.value !== status) statusSelect.value = status;

  updatePresenceRender();
  let persisted = persistAccount === false;
  if (persistAccount) {
    try {
      persisted = await queueMyPresenceStatusPersist(status);
      logPresenceDebug("manual status persisted", {
        userId: normId(state.user?.id || ""),
        status,
        ok: persisted === true,
      });
      logPresenceLiveDebug("manual status persisted", {
        manualStatus: status,
        ok: persisted === true,
      });
    } catch (error) {
      persisted = false;
      logPresenceDebug("manual status persist failed", {
        userId: normId(state.user?.id || ""),
        status,
        error: String(error?.message || error || "unknown"),
      });
    }
  }

  if (persistAccount && persisted !== true) {
    state.me.status = setMyStatus(previousStatus);
    if (state.user?.id) cacheProfileRow({ id: state.user.id, status: previousStatus });
    applyMeStatusDot(previousStatus);
    updatePresenceRender();
    void refreshCurrentUserPresenceStatusFromAccount({ reason: "manual-status-persist-failed" });
    return previousStatus;
  }

  try {
    logPresenceLiveDebug("re-track called", {
      userId: normId(state.user?.id || ""),
      sessionId: PRESENCE_SESSION_ID,
      manualStatus: status,
    });
    await presence?.setStatus?.(status);
    logPresenceLiveDebug("re-track success", {
      userId: normId(state.user?.id || ""),
      sessionId: PRESENCE_SESSION_ID,
      manualStatus: status,
    });
    logPresenceDebug("presence tracked", {
      userId: normId(state.user?.id || ""),
      status,
      persisted: persisted === true,
    });
  } catch (error) {
    logPresenceDebug("presence track failed", {
      userId: normId(state.user?.id || ""),
      status,
      error: String(error?.message || error || "unknown"),
    });
    logPresenceLiveDebug("re-track fail", {
      userId: normId(state.user?.id || ""),
      sessionId: PRESENCE_SESSION_ID,
      manualStatus: status,
      error: String(error?.message || error || "unknown"),
    });
  }
  return status;
}

function getMePresencePayload() {
  const manualStatus = normalizeManualPresenceStatus(resolveMyPresenceStatus(state.me));
  const activity = getCurrentPublicPresenceActivity();
  const spotifyActivity = getCurrentSpotifyPresenceActivity();
  return {
    id: state.user?.id,
    user_id: state.user?.id,
    session_id: PRESENCE_SESSION_ID,
    username: state.me?.username || "user",
    display_name: state.me?.display_name || state.me?.username || "User",
    avatar_url: getCurrentMeAvatarUrl() || null,
    name_color: normalizeNameColor(state.me?.name_color),
    call_tile_color: normalizeCallTileColor(state.me?.call_tile_color),
    manual_status: manualStatus,
    status: manualStatus,
    has_live_session: true,
    online_at: PRESENCE_ONLINE_AT_ISO,
    last_seen_at: new Date().toISOString(),
    device_type: getPresenceDeviceType(),
    activity,
    spotify_activity: spotifyActivity,
  };
}

function ensureMeStatusDot() {
  const meAvatar = document.getElementById("meAvatar");
  if (!meAvatar) return;

  if (!meAvatar.querySelector(".statusDot")) {
    meAvatar.insertAdjacentHTML("beforeend", `<span class="statusDot statusDot--me" data-status-dot-me="1" data-status="online"></span>`);
  }
}

function applyMeStatusDot(status) {
  const resolved = normalizePresenceStatus(status || getMyStatus());
  const dot = document.querySelector('[data-status-dot-me="1"]');
  if (dot) dot.setAttribute("data-status", resolved);

  document.querySelectorAll("[data-status-mini]").forEach((mini) => {
    mini.setAttribute("data-status-mini", resolved);
  });

  document.querySelectorAll("[data-me-popout-status-label]").forEach((el) => {
    el.textContent = getMeProfilePopoutStatusLabel(resolved);
  });

  document.querySelectorAll(".meProfilePopout__statusText[data-me-popout-act='status']").forEach((el) => {
    el.setAttribute("aria-label", `${t("settings.section.status", "Status")}: ${getMeProfilePopoutStatusLabel(resolved)}`);
  });

  const label = document.getElementById("meStatusLabel");
  if (label) {
    if (resolved === "dnd") label.textContent = "ocupado";
    else if (resolved === "focus") label.textContent = t("status.focus", "focus");
    else if (resolved === "idle") label.textContent = "ausente";
    else if (resolved === "invisible") label.textContent = "invisivel";
    else if (resolved === "offline") label.textContent = "offline";
    else label.textContent = "online";
    const activity = getCurrentPublicPresenceActivity();
    if (activity) label.textContent = `${getActivityVerbLabel(activity)} ${activity.name}`;
  }

  const dockStatusBtn = document.getElementById("meStatusBtn");
  if (dockStatusBtn) {
    dockStatusBtn.setAttribute(
      "aria-label",
      `${t("settings.section.status", "Status")}: ${getMeProfilePopoutStatusLabel(resolved)}`
    );
  }
}

function applySelfManualStatusFromPresenceList(list = []) {
  const meId = normId(state.user?.id || "");
  if (!meId) return;
  const hit = (list || []).find((u) => normId(u?.id || u?.user_id || "") === meId);
  const remoteStatus = readPresenceStatusValue(hit?.manual_status) || readPresenceStatusValue(hit?.manualStatus);
  if (!remoteStatus) return;
  const nextStatus = normalizeManualPresenceStatus(remoteStatus);
  const localStatus = normalizeManualPresenceStatus(resolveMyPresenceStatus(state.me));
  if (nextStatus === localStatus) return;
  const inLocalGrace = Date.now() - Number(lastManualPresenceStatusChangeAt || 0) < PRESENCE_STATUS_LOCAL_CHANGE_GRACE_MS;
  if (inLocalGrace) {
    logPresenceDebug("presence sync ignored during local grace", {
      userId: meId,
      localStatus,
      remoteStatus: nextStatus,
    });
    return;
  }
  state.me = state.me || {};
  state.me.status = setMyStatus(nextStatus);
  cacheProfileRow({ id: meId, status: nextStatus });
  applyMeStatusDot(nextStatus);
  logPresenceDebug("remote status update received", {
    userId: meId,
    previousStatus: localStatus,
    status: nextStatus,
    source: "presence",
  });
  try { void presence?.setStatus?.(nextStatus); } catch (_) {}
}

function syncProfilesFromPresenceList(list = []) {
  const rows = (list || [])
    .map((u) => {
      const id = String(u?.id || "").trim();
      if (!id) return null;
      return {
        id,
        username: u?.username || null,
        display_name: u?.display_name || null,
        avatar_url: u?.avatar_url || null,
        name_color: normalizeNameColor(u?.name_color),
        call_tile_color: normalizeCallTileColor(u?.call_tile_color),
        status: readPresenceStatusValue(u?.manual_status) || readPresenceStatusValue(u?.manualStatus) || null,
        activity: sanitizePresenceActivity(u?.activity || u?.spotify_activity || u?.spotifyActivity),
      };
    })
    .filter(Boolean);

  if (!rows.length) return;
  cacheProfileRows(rows);

  const otherId = String(callOtherUserId || "").trim();
  if (!otherId) return;
  const hit = rows.find((x) => x.id === otherId);
  if (!hit) return;

  if (hit.display_name || hit.username) {
    callOtherLabel = hit.display_name || hit.username || callOtherLabel;
  }
  if (hit.avatar_url) callOtherAvatar = hit.avatar_url;

  state.activeDm = {
    ...(state.activeDm || {}),
    otherUserId: otherId,
    ...(hit.username ? { username: hit.username } : {}),
    ...(hit.display_name ? { displayName: hit.display_name } : {}),
    ...(hit.avatar_url ? { avatarUrl: hit.avatar_url } : {}),
    name_color: normalizeNameColor(hit.name_color),
    call_tile_color: normalizeCallTileColor(hit.call_tile_color),
  };
  applyDmTitleNameStyle();
}

function injectStatusSelectorIntoProfileOverlay() {
  const wrapId = "presenceStatusWrap";
  const slot = document.getElementById("settingsStatusSlot");
  if (!slot) return;
  if (document.getElementById(wrapId)) {
    const selExisting = document.getElementById("presenceStatus");
    if (selExisting) selExisting.value = resolveMyPresenceStatus(state.me);
    applyLanguageToStaticUi();
    return;
  }

  const html = `
    <div id="${wrapId}" class="settingsField">
      <label class="label" for="presenceStatus">${esc(t("settings.section.status", "Status"))}</label>
      <select id="presenceStatus" class="input">
        <option value="online">${esc(t("status.option.online", "Online"))}</option>
        <option value="idle">${esc(t("status.option.idle", "Away"))}</option>
        <option value="focus">${esc(t("status.option.focus", "Focus"))}</option>
        <option value="dnd">${esc(t("status.option.dnd", "Do Not Disturb"))}</option>
        <option value="invisible">${esc(t("status.option.invisible", "Invisible"))}</option>
      </select>
      <div class="settingsHint">${esc(t("settings.status.hint", "This status is saved in real time to your account."))}</div>
    </div>
  `;
  slot.insertAdjacentHTML("beforeend", html);

  const sel = document.getElementById("presenceStatus");
  if (sel) sel.value = resolveMyPresenceStatus(state.me);

  sel?.addEventListener("change", (e) => {
    const v = normalizePresenceStatus(e?.target?.value);
    void setMyPresenceStatusEverywhere(v, { persistAccount: true });
  });
  applyLanguageToStaticUi();
}

function setStatusDotsForUser(userId, status) {
  const raw = String(userId || "");
  if (!raw) return;

  let dots = [];
  try {
    const escaped = (typeof CSS !== "undefined" && typeof CSS.escape === "function")
      ? CSS.escape(raw)
      : raw.replace(/["\\]/g, "\\$&");
    dots = Array.from(document.querySelectorAll(`[data-status-dot="${escaped}"]`));
  } catch (_) {
    dots = Array.from(document.querySelectorAll("[data-status-dot]"))
      .filter((dot) => dot.getAttribute("data-status-dot") === raw);
  }

  const resolved = normalizePresenceStatus(status || "offline");
  dots.forEach((dot) => dot.setAttribute("data-status", resolved));
}

function applyPresenceStatusDots(snapshot = []) {
  Array.from(document.querySelectorAll("[data-status-dot]")).forEach((dot) => {
    dot.setAttribute("data-status", "offline");
  });

  (Array.isArray(snapshot) ? snapshot : []).forEach((entry) => {
    const uid = normId(entry?.id || entry?.user_id || "");
    if (!uid) return;
    setStatusDotsForUser(uid, getPresenceStatusForUser(uid) || normalizePresenceStatus(entry?.status || "offline"));
  });
}

function pushFriendIdCandidate(list, source, value) {
  const id = normId(value || "");
  if (!id) return;
  list.push({ source, id });
}

function getFriendIdCandidates(friend = {}) {
  const profile = friend?.profile && typeof friend.profile === "object" ? friend.profile : {};
  const profiles = friend?.profiles && typeof friend.profiles === "object" ? friend.profiles : {};
  const friendProfile = friend?.friend && typeof friend.friend === "object" ? friend.friend : {};
  const candidates = [];
  pushFriendIdCandidate(candidates, "other_user_id", friend?.other_user_id);
  pushFriendIdCandidate(candidates, "friend_user_id", friend?.friend_user_id);
  pushFriendIdCandidate(candidates, "friendUserId", friend?.friendUserId);
  pushFriendIdCandidate(candidates, "friend_id", friend?.friend_id);
  pushFriendIdCandidate(candidates, "friendId", friend?.friendId);
  pushFriendIdCandidate(candidates, "peer_user_id", friend?.peer_user_id);
  pushFriendIdCandidate(candidates, "peerUserId", friend?.peerUserId);
  pushFriendIdCandidate(candidates, "target_user_id", friend?.target_user_id);
  pushFriendIdCandidate(candidates, "targetUserId", friend?.targetUserId);
  pushFriendIdCandidate(candidates, "profile.id", profile?.id);
  pushFriendIdCandidate(candidates, "profiles.id", profiles?.id);
  pushFriendIdCandidate(candidates, "friend.id", friendProfile?.id);
  pushFriendIdCandidate(candidates, "profile_id", friend?.profile_id);
  pushFriendIdCandidate(candidates, "profileId", friend?.profileId);
  pushFriendIdCandidate(candidates, "user_id", friend?.user_id);
  pushFriendIdCandidate(candidates, "userId", friend?.userId);
  pushFriendIdCandidate(candidates, "id", friend?.id);
  return candidates;
}

function getFriendRawIds(friend = {}) {
  return getFriendIdCandidates(friend).reduce((acc, item) => {
    if (!acc[item.source]) acc[item.source] = item.id;
    return acc;
  }, {});
}

function getFriendUserId(friend = {}, currentUserId = "") {
  const selfId = normId(currentUserId || state.user?.id || "");
  const candidates = getFriendIdCandidates(friend);
  const nonSelf = selfId ? candidates.find((item) => item.id && item.id !== selfId) : null;
  if (nonSelf) return nonSelf.id;
  return candidates[0]?.id || "";
}

function getPresenceFriendUserId(friend = {}) {
  return getFriendUserId(friend, state.user?.id || "");
}

function getPresenceKnownFriendIds() {
  return Array.from(new Set((state.friends || []).map((f) => getFriendUserId(f)).filter(Boolean)));
}

function getPresenceFriendDebugRows() {
  return (state.friends || []).map((f) => {
    const extractedFriendUserId = getFriendUserId(f);
    const entry = extractedFriendUserId ? getPresenceEntryForUser(extractedFriendUserId) : null;
    const resolved = extractedFriendUserId ? resolveEffectivePresence(extractedFriendUserId, { presenceEntry: entry }) : null;
    const profile = f?.profile && typeof f.profile === "object" ? f.profile : {};
    const profiles = f?.profiles && typeof f.profiles === "object" ? f.profiles : {};
    const friendProfile = f?.friend && typeof f.friend === "object" ? f.friend : {};
    const displayName = String(getFriendDisplayName?.(f) || f?.display_name || f?.displayName || f?.username || profile.display_name || profiles.display_name || friendProfile.display_name || "");
    const rawFriendIds = getFriendRawIds(f);
    if (!extractedFriendUserId) {
      logPresenceLiveDebug("friend id mismatch", { displayName, rawFriendIds });
    }
    const manualStatus = readPresenceStatusValue(entry?.manual_status)
      || readPresenceStatusValue(entry?.manualStatus)
      || readPresenceStatusValue(f?.status)
      || readPresenceStatusValue(f?.presence_status)
      || readPresenceStatusValue(f?.theme_settings?.presence_status)
      || readPresenceStatusValue(profile?.status)
      || readPresenceStatusValue(profile?.theme_settings?.presence_status)
      || readPresenceStatusValue(profiles?.status)
      || readPresenceStatusValue(profiles?.theme_settings?.presence_status)
      || readPresenceStatusValue(friendProfile?.status)
      || readPresenceStatusValue(friendProfile?.theme_settings?.presence_status)
      || "";
    return {
      displayName,
      extractedFriendUserId,
      friendUserId: extractedFriendUserId,
      userId: extractedFriendUserId,
      username: String(f?.username || ""),
      rawFriendIds,
      hasLiveSession: !!resolved?.hasLiveSession,
      manualStatus,
      effectiveStatus: resolved?.effectiveStatus || "offline",
      sessionCount: Number(entry?.live_session_count || 0),
      sessionsFound: Array.isArray(entry?.live_sessions) ? entry.live_sessions : [],
      profileStatus: readPresenceStatusValue(f?.status) || readPresenceStatusValue(f?.presence_status) || readPresenceStatusValue(f?.theme_settings?.presence_status) || "",
      presenceManualStatus: readPresenceStatusValue(entry?.manual_status) || "",
      visibleToOthers: !!resolved?.visibleToOthers,
      includedInActiveNow: resolved?.effectiveStatus === "online" || resolved?.effectiveStatus === "idle" || resolved?.effectiveStatus === "focus" || resolved?.effectiveStatus === "dnd",
    };
  });
}

function getPresenceActiveNowDebugUsers() {
  return getPresenceFriendDebugRows().filter((row) => (
    row.effectiveStatus === "online"
    || row.effectiveStatus === "idle"
    || row.effectiveStatus === "focus"
    || row.effectiveStatus === "dnd"
  ));
}

function compactPresenceDebugPayload(payload = {}) {
  const p = payload && typeof payload === "object" ? payload : {};
  return {
    user_id: normId(p.user_id || p.userId || p.id || ""),
    session_id: String(p.session_id || p.sessionId || "").trim(),
    manual_status: normalizeManualPresenceStatus(p.manual_status || p.manualStatus || p.status || "online"),
    device_type: String(p.device_type || p.deviceType || getPresenceDeviceType()).trim(),
    online_at: String(p.online_at || p.onlineAt || "").trim(),
    last_seen_at: String(p.last_seen_at || p.lastSeenAt || p.last_seen || p.lastSeen || "").trim(),
  };
}

function bindPresenceDebugGlobals() {
  if (typeof window === "undefined") return;
  window.__ALTARA_PRESENCE_DEBUG__ = function () {
    const runtime = presence && typeof presence.getDebugSnapshot === "function"
      ? presence.getDebugSnapshot()
      : {};
    const manualStatus = normalizeManualPresenceStatus(resolveMyPresenceStatus(state.me));
    const friends = getPresenceFriendDebugRows();
    const channelState = runtime.channelState || runtime.presenceChannelState || "not-started";
    return {
      currentUserId: normId(state.user?.id || ""),
      currentUserName: String(state.me?.display_name || state.me?.username || state.user?.email || "").trim(),
      manualStatus,
      supabaseUrl: String(SUPABASE_URL || ""),
      presenceChannelName: runtime.presenceChannelName || "altara-presence-global",
      channelName: runtime.presenceChannelName || "altara-presence-global",
      channelTopic: runtime.channelTopic || "",
      channelState,
      presenceChannelState: channelState,
      socketConnected: runtime.socketConnected === true,
      ownSessionId: runtime.ownSessionId || PRESENCE_SESSION_ID,
      ownTrackPayload: runtime.ownTrackPayload || compactPresenceDebugPayload(getMePresencePayload()),
      rawPresenceState: runtime.rawPresenceState || {},
      rawPresenceStateKeys: Array.isArray(runtime.rawPresenceStateKeys) ? runtime.rawPresenceStateKeys : Object.keys(runtime.rawPresenceState || {}),
      rawPresencePayloadsCompact: Array.isArray(runtime.rawPresencePayloadsCompact) ? runtime.rawPresencePayloadsCompact : [],
      liveSessionsByUserId: runtime.liveSessionsByUserId || {},
      effectivePresenceByUserId: runtime.effectivePresenceByUserId || {},
      rawLiveSessionsByUserId: runtime.rawLiveSessionsByUserId || {},
      lastSeenLiveAtByUserId: runtime.lastSeenLiveAtByUserId || {},
      presenceList: Array.isArray(presenceList) ? presenceList : [],
      knownFriendIds: getPresenceKnownFriendIds(),
      friends,
      resolvedFriendPresenceRows: friends,
      friendPresenceSummary: friends,
      activeNowUsers: getPresenceActiveNowDebugUsers(),
      connectionState: window.__ALTARA_CONNECTION_STATE__ || null,
      lastPresenceSyncAt: runtime.lastPresenceSyncAt || 0,
      lastPresenceTrackAt: runtime.lastPresenceTrackAt || 0,
      lastTrackResult: runtime.lastTrackResult || "",
      lastPresenceError: runtime.lastPresenceError || "",
    };
  };
  window.__ALTARA_PRESENCE_RETRACK__ = async function () {
    if (!presence) await startPresence().catch(() => null);
    await presence?.refresh?.();
    renderFriends({ skipPresenceRefresh: true });
    updatePresenceRender();
    return window.__ALTARA_PRESENCE_DEBUG__();
  };
  window.__ALTARA_PRESENCE_FORCE_RESYNC__ = async function () {
    logPresenceLiveDebug("force resync requested", { currentUserId: normId(state.user?.id || "") });
    if (!presence) await startPresence().catch(() => null);
    await presence?.refresh?.();
    await loadDmList({ lightweight: true }).catch(() => null);
    await refresh({ lightweight: true }).catch(() => null);
    renderFriends({ skipPresenceRefresh: true });
    updatePresenceRender();
    logPresenceLiveDebug("force resync complete", { currentUserId: normId(state.user?.id || "") });
    return window.__ALTARA_PRESENCE_DEBUG__();
  };
  window.__ALTARA_PRESENCE_DUMP_FRIENDS__ = function () {
    const rows = getPresenceFriendDebugRows();
    try { console.table(rows); } catch (_) { try { console.log("[Presence] friends", rows); } catch (_) {} }
    return rows;
  };
}

function schedulePresenceRender(reason = "presence") {
  scheduleUiRender("presence", () => {
    markPerfStart("presence_render", { reason: String(reason || "presence") });
    updatePresenceRender();
    markPerfEnd("presence_render", { reason: String(reason || "presence") });
  });
}

function updatePresenceRender() {
  const trace = getRelationshipCurrentTrace();
  const traceLabel = relationshipTracePhaseStart(trace, "updatePresenceRender");
  try {
  if (serverSettingsServerId && getServerSettingsActivePanelName?.() === "members") {
    renderServerSettingsMembersPanel();
  }
  const dmListEl = document.getElementById("dmList");
  const offlineListEl = document.getElementById("offlineList");
  const activeNowEl = document.getElementById("activeNow");
  const onlineCountEl = document.getElementById("onlineCount");
  const searchInputEl = document.getElementById("searchInput");
  const dmMain = document.getElementById("dmMain");
  const dmVisible = !!dmMain && dmMain.style.display !== "none";
  const activeConversationId = normId(activeDmId || state.activeDm?.conversationId || "");
  const activeCallConversationId = normId(callConversationId || "");
  const callPcActive = !!(
    callPc
    && callPc.connectionState !== "closed"
    && callPc.connectionState !== "failed"
  );
  const activeServerVoiceTransport = !!(
    activeConversationId
    && isServerVoiceTransportSessionActive(activeConversationId)
  );
  const shouldHideActiveNowInCall = !!(
    activeConversationId
    && (
      activeServerVoiceTransport
      || (
        activeCallConversationId === activeConversationId
        && (
          inCall
          || groupCallMode
          || groupDmCallLiveKitJoinInFlight
          || callPcActive
        )
      )
    )
  );
  const serverCtx = dmVisible
    ? (getActiveServerContext() || getActiveServerSidebarContext?.() || null)
    : null;
  const shouldPreserveServerMembersPanel = !!(
    dmVisible
    && (
      serverCtx
      || isServerConversationUiOpen()
      || normId(state.activeDm?.serverId || "")
    )
  );

  if (serverCtx) {
    const serverName = normalizeConversationLabel(serverCtx?.name || "Server", "Server");
    setRightSidebarToServerMembers({
      active: true,
      title: `${serverName} Members`,
      count: Number(serverCtx?.memberCount || 0),
    });
    applyPresenceStatusDots(presenceList);

    ensureMeStatusDot();
    applyMeStatusDot(getMePresencePayload().status || "online");
    applyDmTitleNameStyle();
    refreshOpenUserCard();
    refreshDmProfilePanel();
    ensureServerSidebarForCurrentContext("presence-render-server-context");
    void refreshServerConversationUi({ reason: "sidebar-members", refreshChannels: false, refreshMembers: true }).catch(() => {});
    return;
  }

  if (shouldPreserveServerMembersPanel) {
    sanitizeRightSidebarForContext("server_members");
    applyPresenceStatusDots(presenceList);
    ensureMeStatusDot();
    applyMeStatusDot(getMePresencePayload().status || "online");
    return;
  }

  setRightSidebarToServerMembers({ active: false });

  // Hide Offline section from the right panel (keep only Active Now).
  const offlineLabelEl = offlineListEl?.previousElementSibling || null;
  if (offlineLabelEl && (offlineLabelEl.classList?.contains("rightSectionLabel") || offlineLabelEl.classList?.contains("sectionTitle"))) {
    offlineLabelEl.style.display = "none";
  }
  if (offlineListEl) {
    offlineListEl.innerHTML = "";
    offlineListEl.style.display = "none";
  }

  if (!activeNowEl && !offlineListEl && !dmListEl) return;

  if (activeNowEl) {
    if (shouldHideActiveNowInCall) {
      activeNowEl.innerHTML = "";
      activeNowEl.style.display = "none";
      if (onlineCountEl) onlineCountEl.textContent = "0";
    } else {
      activeNowEl.style.display = "";
    }
  }

  renderPresenceUI({
    list: presenceList,
    me: getMePresencePayload(),
    friends: state.friends || [],
    dmListEl,
    offlineListEl: null,
    activeNowEl: shouldHideActiveNowInCall ? null : activeNowEl,
    onlineCountEl,
    source: "updatePresenceRender",
    searchValue: searchInputEl?.value || "",
    onUserClick: async (u) => {
      if (u?.username) await openDm(u.username);
    },
    onStatusDot: (userId, status) => {
      setStatusDotsForUser(userId, status);
    }
  });

  const usersInActiveCall = new Set();
  if (activeConversationId) {
    if (isServerVoiceConversationById(activeConversationId)) {
      getServerVoiceChannelOccupantIds(activeConversationId, {
        triggerReason: "presence_active_now_filter",
        callerFunction: "updatePresenceRender",
      }).forEach((uid) => {
        const normalized = normId(uid || "");
        if (normalized) usersInActiveCall.add(normalized);
      });
    } else if (normId(callConversationId || "") === activeConversationId) {
      getEffectiveGroupCallActiveUserIds(activeConversationId).forEach((uid) => {
        const normalized = normId(uid || "");
        if (normalized) usersInActiveCall.add(normalized);
      });
    }
  }

  // Enforce: Active Now only shows online/idle/focus/dnd entries.
  if (activeNowEl && !shouldHideActiveNowInCall) {
    const rows = Array.from(activeNowEl.querySelectorAll(".presenceRow"));
    rows.forEach((row) => {
      const rowUserId = normId(row.getAttribute("data-presence-user") || "");
      const inActiveCall = !!(rowUserId && usersInActiveCall.has(rowUserId));
      const stateText = String(row.querySelector(".presenceState")?.textContent || "").trim().toLowerCase();
      const dotStatus = String(row.querySelector(".statusDot")?.getAttribute("data-status") || "").trim().toLowerCase();
      const isActive = dotStatus === "online" || dotStatus === "idle" || dotStatus === "focus" || dotStatus === "dnd";
      if (inActiveCall || !isActive || stateText === "offline" || stateText === "invisible") {
        row.remove();
      }
    });

    const activeRows = activeNowEl.querySelectorAll(".presenceRow").length;
    const activeNowSignature = Array.from(activeNowEl.querySelectorAll(".presenceRow")).map((row) => {
      const uid = normId(row.getAttribute("data-presence-user") || "");
      const dot = String(row.querySelector(".statusDot")?.getAttribute("data-status") || "");
      const activity = String(row.querySelector(".presenceActivityTitle")?.textContent || "").trim();
      return [uid, dot, activity].join(":");
    }).join("|");
    if (activeNowSignature !== lastPresenceActiveNowSignature) {
      lastPresenceActiveNowSignature = activeNowSignature;
      logPresenceDebug("active now updated", {
        count: activeRows,
      });
    }
    if (!activeRows) activeNowEl.innerHTML = `<div class="hint">No one online right now.</div>`;
    if (onlineCountEl) onlineCountEl.textContent = String(activeRows);
  }

  ensureMeStatusDot();
  applyMeStatusDot(getMePresencePayload().status || "online");
  applyDmTitleNameStyle();
  refreshOpenUserCard();
  refreshDmProfilePanel();
  renderTypingStatusOnUserCards({ reason: "presence-render" });
  } finally {
    relationshipTracePhaseEnd(trace, traceLabel);
  }
}

async function startPresence() {
  if (presenceStartInFlight) return presenceStartInFlight;
  const startTask = startPresenceOnce();
  presenceStartInFlight = startTask;
  try {
    return await startTask;
  } finally {
    if (presenceStartInFlight === startTask) presenceStartInFlight = null;
  }
}

async function startPresenceOnce() {
  if (!state.user || !state.me) return;

  ensureMeStatusDot();
  bindPresenceDebugGlobals();

  const nextPresenceOwnerUserId = normId(state.user?.id || "");
  if (presenceStopInFlight) {
    try { await presenceStopInFlight; } catch (_) {}
  }
  if (presence && presenceOwnerUserId === nextPresenceOwnerUserId) {
    logPresenceLiveDebug("restart existing presence system", { userId: nextPresenceOwnerUserId });
    try { await presence.start?.(); } catch (error) {
      logPresenceLiveDebug("restart existing presence system failed", {
        userId: nextPresenceOwnerUserId,
        error: getSafeAuthErrorCode(error, "presence_restart"),
      });
      throw error;
    }
    try { await presence.refresh?.(); } catch (_) {}
    return;
  }
  if (presence && presenceOwnerUserId && presenceOwnerUserId !== nextPresenceOwnerUserId && typeof presence.stop === "function") {
    try { await presence.stop(); } catch (_) {}
    presence = null;
    presenceList = [];
    presenceOwnerUserId = "";
  }

  try {
    const { data } = await supabase.auth.getSession();
    const token = String(data?.session?.access_token || "").trim();
    logPresenceLiveDebug("auth ready", {
      userId: normId(data?.session?.user?.id || state.user?.id || ""),
    });
    if (token && supabase?.realtime && typeof supabase.realtime.setAuth === "function") {
      await Promise.resolve(supabase.realtime.setAuth(token));
    }
  } catch (error) {
    logPresenceDebug("realtime auth failed", {
      userId: normId(state.user?.id || ""),
      error: String(error?.message || error || "unknown"),
    });
  }

  const bootStatusSource = readPresenceStatusValue(state.me?.status)
    ? "profiles.status"
    : (readPresenceStatusValue(state.me?.theme_settings?.presence_status) ? "profiles.theme_settings" : "local-cache");
  const persisted = resolveMyPresenceStatus(state.me);
  state.me.status = persisted;
  setMyStatus(persisted);
  logPresenceDebug("boot profile status", {
    userId: normId(state.user?.id || ""),
    status: persisted,
    source: bootStatusSource,
  });

  presenceOwnerUserId = nextPresenceOwnerUserId;
  presence = createPresenceSystem({
    supabase,
    getMe: () => getMePresencePayload(),
    manageReconnectExternally: true,
    onStatus: (status, meta = {}) => recordAltaraRealtimeStatus(status, { source: meta?.source || "presence", error: meta?.error || null }),
    onPresenceList: (list) => {
      presenceList = list || [];
      logPresenceDebug("presence sync received", {
        userId: normId(state.user?.id || ""),
        count: presenceList.length,
      });
      logPresenceLiveDebug("presence sync received", {
        userIds: presenceList.map((u) => normId(u?.id || u?.user_id || "")).filter(Boolean),
        sessionCount: presenceList.reduce((sum, u) => sum + Number(u?.live_session_count || 0), 0),
      });
      getPresenceFriendDebugRows().forEach((row) => {
        logPresenceLiveDebug("friend match", {
          currentUserId: normId(state.user?.id || ""),
          friendName: String(row.displayName || row.username || "").slice(0, 120),
          friendUserId: row.extractedFriendUserId || row.friendUserId || row.userId || "",
          hasLiveSession: row.hasLiveSession === true,
          manualStatusFromPresence: row.presenceManualStatus || "",
          effectiveStatus: row.effectiveStatus || "offline",
          includedInActiveNow: row.includedInActiveNow === true,
        });
      });
      logPresenceLiveDebug("friend sessions", {
        friends: getPresenceFriendDebugRows().map((row) => ({
          friendUserId: row.extractedFriendUserId || row.friendUserId || row.userId || "",
          sessionCount: Number(row.sessionCount || 0),
          manualStatus: row.manualStatus || "",
          effectiveStatus: row.effectiveStatus || "offline",
        })),
      });
      logPresenceLiveDebug("activeNowUsers", {
        count: getPresenceActiveNowDebugUsers().length,
        userIds: getPresenceActiveNowDebugUsers().map((row) => row.extractedFriendUserId || row.friendUserId || row.userId || "").filter(Boolean),
      });
      applySelfManualStatusFromPresenceList(presenceList);
      syncProfilesFromPresenceList(presenceList);
      schedulePresenceRender("presence_list");
      const hasActiveCallUi = !!(
        inCall
        || groupCallMode
        || normId(callConversationId || "")
        || (
          callPc
          && callPc.connectionState !== "closed"
          && callPc.connectionState !== "failed"
        )
      );
      if (hasActiveCallUi) refreshCallUI();
    },
    onError: (e) => console.warn("presence error", e),
  });

  await presence.start();

  const searchInputEl = document.getElementById("searchInput");
  searchInputEl?.addEventListener("input", updatePresenceRender);

  document.addEventListener("visibilitychange", () => {
    if (!presence || document.visibilityState !== "visible") return;
    const nextStatus = resolveMyPresenceStatus(state.me);
    state.me.status = nextStatus;
    setMyStatus(nextStatus);
    void presence.setStatus(nextStatus);
    void runProfileSyncFallback();
    void refreshCurrentUserPresenceStatusFromAccount({ reason: "visibility" });
  });

  await presence.setStatus(persisted);
}

/* ========================= INIT ========================= */
(async function init() {
  try { window.__ALTARA_NORMAL_BOOT_STARTED__ = true; window.__ALTARA_NORMAL_BOOT_DONE__ = false; window.__ALTARA_NORMAL_BOOT_ERROR__ = null; } catch (_) {}
  recordAltaraBootEvent("normal_boot_start", { shellFirst: true });
  try { window.__ALTARA_RENDER_IMMEDIATE_APP_SHELL__?.("normal_boot_start"); } catch (error) { recordAltaraBootEvent("required_task_error", { task: "immediate_shell", message: error?.message || error || "unknown" }); }
  markPerfStart("auth_ready");
  if (window.__ALTARA_SAFE_BOOT_ENABLED__ === true) {
    recordAltaraBootEvent("safe_boot_enabled", { shellRendered: window.__ALTARA_SHELL_RENDERED__ === true, source: window.__ALTARA_SAFE_BOOT_SOURCE__ || "unknown" });
    try { window.__ALTARA_RENDER_IMMEDIATE_APP_SHELL__?.("safe_boot"); } catch (_) {}
    try { setDesktopBootOverlayVisible(false); } catch (_) {}
    setAltaraBootCompleted?.();
    return;
  }
  recordAltaraBootEvent("safe_boot_mode_disabled_normal_boot_continues", { source: window.__ALTARA_SAFE_BOOT_SOURCE__ || "none" });
  scheduleFallbackOnlyHydrationRetry("normal_boot");
  setDesktopBootOverlayVisible(!!getDesktopBridge());
  void hydrateAltaraDesktopRuntimeMeta().then(() => exposeAltaraBootDebugHelper?.());
  initAltaraConnectionManager();
  initGlobalMotionMode();
  bindMediaEgressDebugObserverOnce();
  scheduleAltaraHardBootDeadlines("init-start");
  recordAltaraBootEvent("auth_start", { source: "init" });
  const bootSession = await getCachedAltaraAuthSessionForBoot();
  if (bootSession?.user && !state.user) state.user = bootSession.user;
  if (state.user?.id) restoreAltaraOfflineNavigationSnapshot(state.user.id);
  forceRenderBootSafeShell("cached-session-ready");
  const bootConnectionOk = await waitForAltaraConnectionBeforeProtectedBoot({ hasCachedSession: !!bootSession });
  if (!bootConnectionOk && !bootSession) {
    setDesktopBootOverlayVisible(false);
    window.location.replace("./login.html?offline=1");
    return;
  }
  let bootAuthFallbackCategory = "";
  let bootAuthFallbackSafeCode = "";
  state.user = await awaitWithTimeout(requireAuth(buildBotAuthorizeLoginRedirectUrl("./login.html"), { cachedSession: bootSession }), 3500, "requireAuth").catch((error) => {
    recordAltaraBootEvent("auth_error", { source: "init", message: error?.message || error || "unknown" });
    recordAltaraBootEvent("required_task_error", { task: "requireAuth", message: error?.message || error || "unknown" });
    const category = String(
      error?.authStateCategory
      || classifyAuthFailure(error, {
        navigatorOnline: getNavigatorOnlineSignal(),
        authOperation: true,
      })
      || ALTARA_AUTH_STATE.UNEXPECTED_BOOT_ERROR
    );
    bootAuthFallbackCategory = category;
    bootAuthFallbackSafeCode = String(error?.code || getSafeAuthErrorCode(error, category));
    setAltaraConnectionPatch({
      authState: category,
      lastSafeErrorCode: bootAuthFallbackSafeCode || "auth_boot_unexpected",
    }, "boot-auth-recoverable-error");
    return bootSession?.user || null;
  });
  const bootAuthResolution = getLastAuthResolution();
  setAltaraConnectionPatch({
    authState: bootAuthFallbackCategory || bootAuthResolution.category,
    lastSafeErrorCode: bootAuthFallbackSafeCode || bootAuthResolution.safeErrorCode || altaraConnectionState.lastSafeErrorCode,
  }, "boot-auth-classified");
  recordAltaraBootEvent(state.user?.id ? "auth_done" : "auth_error", { source: "init", hasUser: !!state.user?.id });
  if (!state.user) {
    markPerfEnd("auth_ready", { ok: false });
    setDesktopBootOverlayVisible(false);
    return;
  }
  markPerfEnd("auth_ready", { ok: true });
  forceRenderBootSafeShell("auth-ready");
  if (typeof consumeInitialDesktopDeepLinkIfPresent === "function" && await consumeInitialDesktopDeepLinkIfPresent()) {
    setDesktopBootOverlayVisible(false);
    return;
  }
  const bootUserId = normId(state.user?.id || "");
  if (!bootUserId) {
    setAltaraConnectionPatch({
      authState: ALTARA_AUTH_STATE.UNEXPECTED_BOOT_ERROR,
      lastSafeErrorCode: "auth_cached_identity_missing",
    }, "boot-auth-identity-missing");
    recordAltaraBootEvent("required_task_error", {
      task: "requireAuth",
      code: "auth_cached_identity_missing",
    });
    setDesktopBootOverlayVisible(false);
    return;
  }
  setAppLanguage(readStoredAppLanguage(), { persist: false, rerender: false, syncForm: false });
  bindAltaraPlusDesktopBillingEventsOnce();
  bindSpotifyConnectionCallbackEventsOnce();
  const shouldHandleAltaraPlusReturnSignals = shouldRefreshAltaraPlusFromWindowLocation();
  const initialAltaraPlusRefreshPromise = Promise.resolve()
    .then(() => refreshCurrentUserAltaraPlusStatus({
      reason: shouldHandleAltaraPlusReturnSignals ? "billing_return" : "session_load",
    }))
    .catch((error) => {
      console.warn("initial altara+ refresh failed", error?.message || error);
      return createFreeAltaraPlusStatus();
    });

  let initialModerationState = state.moderationState || normalizeUserModerationStateRow({ user_id: state.user.id });
  try {
    initialModerationState = await awaitWithTimeout(
      refreshMyModerationState({ timeoutMs: PROFILE_BOOT_TIMEOUT_MS }),
      PROFILE_BOOT_TIMEOUT_MS + 1000,
      "initial moderation state"
    );
  } catch (error) {
    console.warn("initial moderation state failed", error?.message || error);
  }
  try {
    if (await enforceModerationAccessGate(initialModerationState)) {
      setDesktopBootOverlayVisible(false);
      return;
    }
  } catch (error) {
    console.warn("initial moderation gate failed", error?.message || error);
  }
  consumeDmE2eeLoginSyncNotice();
  void initRtcConfigFromDesktop().catch((error) => recordAltaraBootEvent("optional_task_error", { task: "rtc_config", message: error?.message || error || "unknown" }));
  void refreshRtcTurnCredentials({ force: false });
  bindUiZoomWheelShortcutOnce();
  const meAvatarEl = $("meAvatar");
  try {
    bindMeProfilePopoutDockOnce();
  } catch (error) {
    console.error("me profile dock binding failed", error);
  }
  meAvatarEl?.addEventListener("contextmenu", (e) => {
    e.preventDefault();
    openMeStatusMenuAt({ x: e.clientX, y: e.clientY });
  });
  meAvatarEl?.addEventListener("keydown", (e) => {
    if (e.key === "ContextMenu" || (e.shiftKey && e.key === "F10")) {
      e.preventDefault();
      const rect = meAvatarEl.getBoundingClientRect();
      openMeStatusMenuAt({
        x: Math.round(rect.left + Math.min(rect.width, 140) * 0.74),
        y: Math.round(rect.top + Math.max(rect.height, 56) * 0.82),
      });
      return;
    }
    if (e.key !== "Enter" && e.key !== " ") return;
    e.preventDefault();
    openMeProfilePopout();
  });

  $("btnHeaderSettings")?.addEventListener("click", openProfileOverlay);
  $("btnSendRequest")?.addEventListener("click", sendFriendRequest);
  $("addUsername")?.addEventListener("input", () => {
    scheduleAddFriendProfileLookup({ immediate: false, force: false });
  });
  $("addUsername")?.addEventListener("keydown", (e) => {
    if (e.isComposing) return;
    if (e.key !== "Enter") return;
    e.preventDefault();
    void sendFriendRequest();
  });

  altaraBootDebugState.initialRefreshStarted = true;
  altaraBootDebugState.activeBlockingTask = "initial_refresh";
  recordAltaraBootEvent("boot_start", { blockingTask: "initial_refresh" });
  recordAltaraBootEvent("initial_refresh_start");
  scheduleAltaraBootLoadingWatchdog("initial-refresh");
  const initialRefreshPromise = Promise.resolve()
    .then(() => awaitWithTimeout(
      refresh(),
      RPC_SOFT_TIMEOUT_MS + 4000,
      "initial refresh"
    ))
    .then(() => {
      altaraBootDebugState.initialRefreshDone = true;
      altaraBootDebugState.activeBlockingTask = "";
      recordAltaraBootEvent("initial_refresh_done");
    })
    .catch((err) => {
      altaraBootDebugState.initialRefreshDone = true;
      altaraBootDebugState.activeBlockingTask = "";
      recordAltaraBootEvent("initial_refresh_error", { message: err?.message || err || "unknown" });
      console.warn("initial refresh failed", err?.message || err);
    });

  try {
    recordAltaraBootEvent("required_task_start", { task: "profile_fast_hydration" });
    state.me = await awaitWithTimeout(
      getMyProfile(state.user.id),
      1200,
      "getMyProfile fast boot"
    );
    state.me.name_color = normalizeNameColor(state.me.name_color);
    state.me.call_tile_color = normalizeCallTileColor(state.me.call_tile_color);
    state.me.status = resolveMyPresenceStatus(state.me);
    setMyStatus(state.me.status);
    cacheProfileRow(state.me);
    persistAltaraOfflineNavigationSnapshot();
    if (isProfileOverlayOpen()) {
      settingsProfileLoading = false;
      settingsProfileLoadError = "";
      syncOpenSettingsAccountFromProfile(state.me, { force: false, reason: "profile_arrived" });
      renderSettingsAccountLoadStatus();
    }
    const theme = applyAppearanceSettings(loadAppearanceSettings({ force: true }));
    applyDesktopBehaviorSettingsToUi(desktopBehaviorSettingsCache);
    setAppLanguage(theme.app_language, { persist: true, rerender: false, syncForm: false });
    $("meName").textContent = state.me.display_name || state.me.username;
    applyMeHeaderNameStyle();
    $("meTag").textContent = "@" + state.me.username;
    setAvatar($("meAvatar"), getCurrentMeAvatarUrl(), state.user?.id || "");
    applyMeHeaderBannerStyle();
    applyMeStatusDot(state.me.status);
    recordAltaraBootEvent("required_task_done", { task: "profile_fast_hydration" });
  } catch (e) {
    console.warn(e);
    recordAltaraBootEvent("required_task_error", { task: "profile_fast_hydration", message: e?.message || e || "unknown" });
    const fallbackStatus = resolveMyPresenceStatus(state.me);
    state.me = {
      ...(state.me || {}),
      status: fallbackStatus,
    };
    setMyStatus(fallbackStatus);
    applyAppearanceSettings(loadAppearanceSettings());
    setAppLanguage(readStoredAppLanguage(), { persist: true, rerender: false, syncForm: false });
    const cachedDisplayName = String(state.me?.display_name || state.me?.username || state.user?.user_metadata?.display_name || state.user?.user_metadata?.username || "").trim();
    if (cachedDisplayName && $("meName")) $("meName").textContent = cachedDisplayName;
    else renderBootUserDockFallback("profile-offline-fallback");
    applyMeHeaderNameStyle();
    const cachedUsername = String(state.me?.username || state.user?.user_metadata?.username || "").trim();
    if ($("meTag")) $("meTag").textContent = cachedUsername ? `@${cachedUsername}` : (bootUserId.slice(0, 8) || "uid");
    applyMeHeaderBannerStyle();
    applyMeStatusDot(fallbackStatus);
    if (isProfileOverlayOpen()) {
      settingsProfileLoading = false;
      settingsProfileLoadError = String(e?.message || e || "Profile unavailable.").slice(0, 180);
      renderSettingsAccountLoadStatus();
    }
  }

  void initialAltaraPlusRefreshPromise.catch(() => createFreeAltaraPlusStatus());
  if (shouldHandleAltaraPlusReturnSignals) {
    void handleAltaraPlusCheckoutReturnFromLocation().catch(() => false);
    void handleAltaraPlusPortalReturnFromLocation().catch(() => false);
  }
  void handleSteamOpenIdCallbackFromLocation().catch((error) => {
    console.warn("[SteamConnect] callback handling failed", error?.message || error);
    recordAltaraBootEvent("optional_task_error", { task: "steam_callback", message: error?.message || error || "unknown" });
    return false;
  });
  void handleSpotifyConnectionReturnFromLocation().catch(() => false);
  void refreshConnectedAccounts({ force: true, silent: true }).catch(() => []);

  void ensureDmFeatureCaps()
    .then((caps) => {
      if (
        isDirectDmE2eeEnabled()
        && caps?.e2eeMessages
        && String(state.activeDm?.kind || "").trim().toLowerCase() === "dm"
        && activeDmRequiresEncryptedText()
      ) return ensureDmE2eeBootstrapStarted();
      return null;
    })
    .catch((error) => {
      console.warn("dm e2ee boot preflight failed", error?.message || error);
    });

  recordAltaraBootEvent("render_home_start", { source: "init" });
  markPerfStart("first_main_ui_render");
  setupTabs();
  bindMainNavigationControlsOnce();
  bindPartyPickerOnce();
  bindServerCreateModalOnce();
  bindServerChannelCreateModalOnce();
  bindServerInviteModalOnce();
  bindServerInviteDeepLinksOnce();
  bindServerSettingsModalOnce();
  if (isAltaraDeveloperPlatformRoutesEnabled()) {
    try {
      bindBotRouteOverlayOnce();
    } catch (error) {
      rememberAltaraBootError("lastBotError", error);
    }
  }
  bindDmGroupCreateModalOnce();
  bindDmGroupEditModalOnce();
  bindLeftSidebarResizerOnce();
  bindRightSidebarResizerOnce();
  bindRightSidebarOverlayOnce();
  bindAppPanelShortcutsOnce();
  wireDmComposer();
  bindGifPickerOnce();
  bindUserCardModalOnce();
  bindEmojiPickerOnce();
  setDesktopBootOverlayVisible(false);
  if (isAltaraDefinitivelyOffline() && altaraOfflineCachedActiveConversation?.conversationId) {
    await showCachedConversationOffline(
      altaraOfflineCachedActiveConversation.conversationId,
      altaraOfflineCachedActiveConversation,
    ).catch(() => false);
  }
  recordAltaraBootEvent("render_home_done", { source: "init" });
  markPerfEnd("first_main_ui_render");
  markPerfEnd("app_boot");

  void initialRefreshPromise.finally(() => {
    scheduleBootActiveConversationMessageRestore("boot-restore-after-refresh");
  });
  void refreshMyModerationInboxEntries({ render: true }).catch(() => null);
  void refreshMyModerationState({ enforceBan: true }).catch(() => null);
  startModerationPolling();
  appBootCompleted = true;
  scheduleBootActiveConversationMessageRestore("boot-restore");
  if (isAltaraDeveloperPlatformRoutesEnabled() && shouldHandleAltaraBotRouteAtStartup()) {
    void handleBotRouteFromLocation({ source: "init" }).catch((error) => {
      rememberAltaraBootError("lastRouteError", error);
      return false;
    });
  }
  void consumeServerInviteFromUrlIfPresent({ showFeedback: true }).catch(() => false);
  void consumePendingExternalServerInviteCodeIfPresent({ showFeedback: true }).catch(() => false);

  startDmPrivacyAuthStateListener();
  startFriendRequestsAuthStateListener();
  if (!isAltaraDefinitivelyOffline()) {
    startGlobalCallListener();
    startGlobalGroupDmCallStateListener();
    subscribeTypingInboxForCurrentUser("app-boot");
    startGlobalDmMessageListener();
    startGlobalBotChannelMessageListener();
    startGlobalDmMembershipListener();
    startGlobalConversationListener();
    void startGlobalDmPrivacyEventListener({ force: true, reason: "init" });
    startGlobalServerChannelTableListener();
    startGlobalServerRoleTablesListener();
    startGlobalProfileListener();
    void startGlobalFriendRequestListener({ force: true, reason: "init" });
    startGlobalMessageRequestListener();
  }
  bindMessageRequestLiveRefreshFallbacksOnce();
  bindConversationMessageCacheRefreshFallbacksOnce();
  if (!isAltaraDefinitivelyOffline()) {
    void refreshMessageRequestsAndSidebar("app_boot", { force: true }).catch(() => {});
    scheduleConversationMessagePrefetch("app_boot");
    startGlobalModerationActionListener();
    startGlobalUserBlocksListener();
  }
  startFriendRequestsSyncFallback();
  startProfileSyncFallback();
  startCurrentUserPresenceStatusSyncFallback();
  bindPresenceDebugGlobals();
  startDmCollectionsSyncFallback();
  startActiveServerChannelSyncFallback();
  bindCallUIButtons();
  bindDesktopSharePickerOnce();
  bindDesktopUpdateUiOnce();
  bindDesktopCallThumbarOnce();
  refreshCallUI();

  const { oDecline } = getCallEls();
  if (oDecline) {
    oDecline.onclick = async () => {
      const ringInfo = pendingGroupRingInfo ? { ...pendingGroupRingInfo } : null;
      showOverlay(false);
      pendingOffer = null;
      pendingCallInfo = null;
      pendingGroupRingInfo = null;
      pendingGroupRingAutoJoin = null;
      clearTimers();
      stopSfx("incoming");
      if (ringInfo?.fromUserId && ringInfo?.conversationId) {
        await declineGroupDmCallSession(ringInfo.conversationId, "declined");
        await sendCallSignal("ice", {
          signal: "group_ring_decline",
          group_call: true,
          reason: "declined",
        }, ringInfo.fromUserId, ringInfo.conversationId);
      }
    };
  }

  void initDesktopGameActivityBridge().catch((error) => {
    console.warn("[activity] optional desktop activity initialization failed", error?.message || error);
    recordAltaraBootEvent("optional_task_error", {
      task: "desktop_game_activity_bridge",
      message: error?.message || error || "unknown",
    });
  });
  if (!isAltaraDefinitivelyOffline()) {
    void startPresence().catch((error) => console.warn("presence start failed", error?.message || error));
  }
  window.setTimeout(() => {
    if (!isAltaraDefinitivelyOffline()) void syncWidgetTodoFromCloud({ force: false }).catch(() => false);
    try { startWidgetReminderMonitor(); } catch (_) {}
  }, 900);
  void maybeShowDesktopInstallWelcome();

  window.openDm = openDm;
  window.showDm = showDm;
  window.startDmWith = startDmWith;
  window.setTenorApiKey = setTenorApiKey;
  window.getTenorApiKey = getTenorApiKey;
  recordAltaraBootEvent("boot_done", { forcedEarlier: altaraBootDebugState.stuckLoadingRecovered || altaraBootDebugState.bootCompleted });
  recordAltaraBootEvent("normal_boot_done", { shellRendered: window.__ALTARA_SHELL_RENDERED__ === true, realHydratedContentPresent: window.__ALTARA_IS_REAL_HYDRATED_CONTENT_PRESENT__?.("any") === true });
  try { window.__ALTARA_NORMAL_BOOT_DONE__ = true; } catch (_) {}
  setAltaraBootCompleted();
})().catch((err) => {
  try { window.__ALTARA_RECORD_RUNTIME_ERROR__?.("normal_hydration_error", err); } catch (_) {}
  rememberAltaraBootError("lastStartupError", err);
  recordAltaraBootEvent("normal_hydration_error", { message: err?.message || err || "unknown" });
  recordAltaraBootEvent("fatal", { message: err?.message || err || "unknown" });
  recordAltaraBootEvent("normal_boot_error", { message: err?.message || err || "unknown" });
  try { window.__ALTARA_NORMAL_BOOT_ERROR__ = getSafeAltaraBootError(err); } catch (_) {}
  console.error("app init failed", err);
  try { window.__ALTARA_RENDER_PREBOOT_SAFE_SHELL__?.("fatal_boot_error"); } catch (_) {}
  setDesktopBootOverlayVisible(false);
  showAltaraBootFailurePanelIfNeeded();
});




